class PSSessionParser:
    DECODE_ENCODINGS = ("utf-16", "utf-8-sig", "utf-8", "latin-1")

    def __init__(self):
        self.session = None
        self.source_path = None

    @classmethod
    def _decode_bytes(cls, data: bytes) -> str:
        last_error = None
        for enc in cls.DECODE_ENCODINGS:
            try:
                return data.decode(enc).strip().strip("\ufeff").strip()
            except Exception as exc:
                last_error = exc
        raise RuntimeError(f"Could not decode file bytes: {last_error}")

    @classmethod
    def _read_text(cls, path: str) -> str:
        return cls._decode_bytes(Path(path).read_bytes())

    def load(self, path: str):
        self.session = json.loads(self._read_text(path))
        self.source_path = path
        return self.session

    def load_from_bytes(self, data: bytes, source_path: str):
        self.session = json.loads(self._decode_bytes(data))
        self.source_path = source_path
        return self.session

    @staticmethod
    def _parse_method_text(method_text: str) -> dict:
        if not isinstance(method_text, str):
            return {}
        out = {}
        for line in method_text.splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, v = line.split("=", 1)
            out[k.strip()] = v.strip()
        return out

    @staticmethod
    def _unit_to_text(unit_obj):
        if isinstance(unit_obj, dict):
            return unit_obj.get("S") or unit_obj.get("Q") or unit_obj.get("A") or unit_obj.get("Type")
        return unit_obj

    @staticmethod
    def _is_data_array_dict(obj) -> bool:
        return isinstance(obj, dict) and "DataValues" in obj and "Description" in obj

    @staticmethod
    def _extract_value(item):
        if isinstance(item, dict) and "V" in item:
            return item.get("V")
        return item

    @classmethod
    def _extract_values(cls, data_array: dict):
        return [cls._extract_value(v) for v in data_array.get("DataValues", [])]

    @staticmethod
    def _to_number_if_possible(value):
        if value is None:
            return None
        if isinstance(value, (int, float)):
            return value
        text = str(value).strip()
        if not text:
            return value
        try:
            number = float(text)
            return int(number) if number.is_integer() else number
        except Exception:
            return value

    @staticmethod
    def _sanitize_filename(text: str) -> str:
        text = str(text or "untitled")
        text = re.sub(r"[^A-Za-z0-9._-]+", "_", text)
        text = re.sub(r"_+", "_", text).strip("_.")
        return text or "untitled"

    def summarize(self) -> dict:
        if self.session is None:
            raise RuntimeError("No session loaded.")
        measurements = self.session.get("Measurements", [])
        title_counts = Counter(m.get("Title", "Untitled") for m in measurements)
        technique_counts = Counter()
        rows = []
        for idx, m in enumerate(measurements):
            method = self._parse_method_text(m.get("Method", ""))
            method_id = method.get("METHOD_ID") or method.get("TECHNIQUE") or "unknown"
            technique_counts[method_id] += 1
            rows.append({
                "index": idx,
                "title": m.get("Title"),
                "method_id": method.get("METHOD_ID"),
                "technique": method.get("TECHNIQUE"),
                "n_curves": len(m.get("Curves", [])),
                "n_eis_blocks": len(m.get("EISDataList", [])),
                "curve_titles": [c.get("Title") for c in m.get("Curves", [])[:12]],
            })
        return {
            "source_file": str(self.source_path) if self.source_path is not None else "",
            "session_type": self.session.get("Type"),
            "core_version": self.session.get("CoreVersion"),
            "n_measurements": len(measurements),
            "measurement_title_counts": dict(title_counts),
            "technique_counts": dict(technique_counts),
            "measurement_rows": rows,
        }

    def build_compact_summary(self) -> dict:
        if self.session is None:
            raise RuntimeError("No session loaded.")
        measurements = self.session.get("Measurements", [])
        technique_counts = Counter()
        measurement_rows = []
        for idx, m in enumerate(measurements):
            method = self._parse_method_text(m.get("Method", ""))
            method_id = method.get("METHOD_ID") or method.get("TECHNIQUE") or "unknown"
            technique_counts[method_id] += 1
            measurement_rows.append({
                "index": idx,
                "title": m.get("Title"),
                "method_id": method.get("METHOD_ID"),
                "technique": method.get("TECHNIQUE"),
                "scan_rate": self._to_number_if_possible(method.get("SCAN_RATE")),
                "n_scans": self._to_number_if_possible(method.get("N_SCANS")),
                "e_begin": self._to_number_if_possible(method.get("E_BEGIN")),
                "e_end": self._to_number_if_possible(method.get("E_END")),
                "n_curves": len(m.get("Curves", [])),
                "n_eis_blocks": len(m.get("EISDataList", [])),
            })
        return {
            "source_file": self.source_path,
            "session_type": self.session.get("Type"),
            "core_version": self.session.get("CoreVersion"),
            "n_measurements": len(measurements),
            "technique_counts": dict(technique_counts),
            "measurement_rows": measurement_rows,
        }

    def session_minified_json(self) -> str:
        if self.session is None:
            raise RuntimeError("No session loaded.")
        return json.dumps(self.session, ensure_ascii=False, separators=(",", ":"))

    def iter_primary_curve_exports(self):
        """Yield primary current-bearing x/y curves suitable for generic curve fitting.
        This intentionally skips auxiliary curves such as Cell potential and Measured WE potential.
        """
        if self.session is None:
            raise RuntimeError("No session loaded.")

        for m_idx, measurement in enumerate(self.session.get("Measurements", []), start=1):
            method = self._parse_method_text(measurement.get("Method", ""))
            measurement_title = measurement.get("Title", f"Measurement_{m_idx}")
            for c_idx, curve in enumerate(measurement.get("Curves", []), start=1):
                x_arr = curve.get("XAxisDataArray") or {}
                y_arr = curve.get("YAxisDataArray") or {}
                if not (self._is_data_array_dict(x_arr) and self._is_data_array_dict(y_arr)):
                    continue

                title = str(curve.get("Title") or "")
                y_desc = str(y_arr.get("Description") or "")
                title_lower = title.lower()
                y_desc_lower = y_desc.lower()

                is_primary = (
                    "i vs" in title_lower
                    or "current" in y_desc_lower
                    or y_desc_lower.startswith("scan")
                    or y_desc_lower == "current"
                )

                if not is_primary:
                    continue

                x_values = self._extract_values(x_arr)
                y_values = self._extract_values(y_arr)
                n = min(len(x_values), len(y_values))
                if n == 0:
                    continue

                yield {
                    "measurement_index": m_idx,
                    "curve_index": c_idx,
                    "measurement_title": measurement_title,
                    "curve_title": title or f"Curve_{c_idx}",
                    "method_id": method.get("METHOD_ID"),
                    "technique": method.get("TECHNIQUE"),
                    "scan_rate": self._to_number_if_possible(method.get("SCAN_RATE")),
                    "x_label": x_arr.get("Description"),
                    "x_unit": self._unit_to_text(x_arr.get("Unit")),
                    "y_label": y_arr.get("Description"),
                    "y_unit": self._unit_to_text(y_arr.get("Unit")),
                    "rows": list(zip(x_values[:n], y_values[:n])),
                }

    def primary_numeric_payload(self) -> dict:
        if self.session is None:
            raise RuntimeError("No session loaded.")
        payload = {
            'format': 'pssession-primary-curves-v1',
            'source_file': self.source_path,
            'session_type': self.session.get('Type'),
            'core_version': self.session.get('CoreVersion'),
            'curves': {},
        }
        for idx, curve in enumerate(self.iter_primary_curve_exports(), start=1):
            key = f"curve_{idx:03d}"
            rows = curve.get('rows') or []
            arr = np.asarray(rows, dtype=float) if rows else np.empty((0, 2), dtype=float)
            payload['curves'][key] = {
                'measurement_index': curve.get('measurement_index'),
                'curve_index': curve.get('curve_index'),
                'measurement_title': curve.get('measurement_title'),
                'curve_title': curve.get('curve_title'),
                'method_id': curve.get('method_id'),
                'technique': curve.get('technique'),
                'scan_rate': curve.get('scan_rate'),
                'x_label': curve.get('x_label'),
                'x_unit': curve.get('x_unit'),
                'y_label': curve.get('y_label'),
                'y_unit': curve.get('y_unit'),
                'array': arr,
            }
        return payload




class VersaStudioParser:
    """Robust native reader for VersaStudio .par + .par.psbd pairs.

    Supports CV, LSV, CA, CP, OCP, and best-effort raw EIS detection.
    The 48-byte big-endian record layout is used for DC/time-series data;
    the 92-byte big-endian layout is used for raw EIS blocks when present.
    """
    CV_RECORD_BYTES = 48
    EIS_RECORD_BYTES = 92

    CV_OFF_ELAPSED_US = 16
    CV_OFF_PT_IDX = 20
    CV_OFF_SEG_ID = 24
    CV_OFF_I_RANGE_CODE = 28
    CV_OFF_I_ADC = 40
    CV_OFF_E_ADC = 32
    CV_OFF_E_VOLTS = 44

    EIS_OFF_ZIMAG_OHM = 0
    EIS_OFF_FREQ_HZ = 24
    EIS_OFF_AC_AMP_V = 40
    EIS_OFF_ZREAL_OHM = 88

    CURRENT_RANGE = {
        0: 200e-3,
        1: 20e-3,
        2: 2e-3,
        3: 200e-6,
        4: 20e-6,
        5: 2e-6,
        6: 200e-9,
        7: 20e-9,
        8: 2e-9,
        9: 200e-12,
    }
    I_ADC_FULLSCALE = 32768.0
    E_ADC_SCALE = -3255.0

    def __init__(self):
        self.metadata = None
        self.decoded = None
        self.source_path = None
        self.psbd_path = None

    @staticmethod
    def _be_i32(buf: bytes, off: int) -> int:
        import struct
        return struct.unpack_from('>i', buf, off)[0]

    @staticmethod
    def _be_f32(buf: bytes, off: int) -> float:
        import struct
        return struct.unpack_from('>f', buf, off)[0]

    @classmethod
    def decode_range_code(cls, raw_i32: int) -> int:
        if 1 <= raw_i32 <= 8:
            return raw_i32
        low = raw_i32 & 0xFF
        if low in cls.CURRENT_RANGE:
            return low
        return -1

    @classmethod
    def compute_current(cls, adc_count: int, range_code: int) -> float:
        fs = cls.CURRENT_RANGE.get(range_code)
        if fs is None:
            return float('nan')
        return adc_count / cls.I_ADC_FULLSCALE * fs

    @staticmethod
    def _unwrap_elapsed_seconds(raw_i32: np.ndarray) -> np.ndarray:
        vals = raw_i32.view(np.uint32).astype(np.float64)
        rolls = np.where(np.diff(vals) < -(1 << 31))[0]
        for idx in rolls:
            vals[idx + 1:] += float(1 << 32)
        return vals * 1e-6

    @staticmethod
    def _technique_from_action_name(name: str) -> str:
        n = (name or '').strip().lower()
        if 'potentiostatic eis' in n or 'galvanostatic eis' in n or re.search(r'\beis\b', n) or 'impedance' in n:
            return 'EIS'
        if 'cyclic voltammetry' in n:
            return 'CV'
        if 'linear scan voltammetry' in n:
            return 'LSV'
        if 'chronoamperometry' in n:
            return 'CA'
        if 'chronopotentiometry' in n:
            return 'CP'
        if 'open circuit' in n:
            return 'OCP'
        if n == 'condition':
            return 'COND'
        if n == 'zra' or 'zero resistance' in n:
            return 'ZRA'
        if n == 'common' or n.startswith('loop'):
            return 'Auxiliary'
        return 'Unknown'

    def _parse_par_metadata(self, path: str) -> dict:
        text = Path(path).read_text(encoding='utf-8', errors='replace').replace('\r\n', '\n').replace('\r', '\n')

        def extract_section(tag: str) -> dict:
            m = re.search(rf'<{tag}>(.*?)</{tag}>', text, re.S)
            if not m:
                return {}
            out = {}
            for line in m.group(1).strip().splitlines():
                if '=' in line:
                    k, _, v = line.partition('=')
                    out[k.strip()] = v.strip()
            return out

        actions = []
        for i in range(64):
            s = extract_section(f'Action{i}')
            if s:
                s['action_id'] = i
                s['technique'] = self._technique_from_action_name(s.get('Name', ''))
                actions.append(s)

        meta = {
            'application': extract_section('Application'),
            'instrument': extract_section('Instrument'),
            'experiment': extract_section('Experiment'),
            'actions': actions,
            'sample_name': Path(path).stem,
        }
        ocp_text = actions[0].get('Measured Open Circuit', '0 mV') if actions else '0 mV'
        m_ocp = re.search(r'([-\d.]+)\s*mV', ocp_text)
        meta['ocp_measured_V'] = float(m_ocp.group(1)) / 1000.0 if m_ocp else 0.0
        meta['application_version'] = meta['application'].get('Version')
        meta['instrument_type'] = meta['instrument'].get('Type')
        meta['instrument_sn'] = meta['instrument'].get('SN')
        meta['date_acquired'] = meta['experiment'].get('DateAcquired')
        meta['time_acquired'] = meta['experiment'].get('TimeAcquired')
        meta['data_format'] = meta['experiment'].get('DataFormat')

        parsed_actions = []
        for action in actions:
            pa = {
                'action_id': action['action_id'],
                'name': action.get('Name', ''),
                'technique': action.get('technique', 'Unknown'),
                'total_points': PSSessionParser._to_number_if_possible(action.get('Total Points')),
                'duration_s': PSSessionParser._to_number_if_possible(action.get('Duration (s)')),
                'scan_rate_V_s': PSSessionParser._to_number_if_possible(action.get('Scan Rate (V/s)')),
                'cycles': PSSessionParser._to_number_if_possible(action.get('Cycles')),
                'pts_per_cycle': PSSessionParser._to_number_if_possible(action.get('Points Per Cycle')),
                'vertex1_V': PSSessionParser._to_number_if_possible(action.get('Vertex 1 Potential (V),Value')),
                'vertex2_V': PSSessionParser._to_number_if_possible(action.get('Vertex 2 Potential (V),Value')),
                'initial_V': PSSessionParser._to_number_if_possible(action.get('Initial Potential (V),Value')),
                'final_V': PSSessionParser._to_number_if_possible(action.get('Final Potential (V),Value')),
                'hold_V': PSSessionParser._to_number_if_possible(action.get('Potential (V),Value')),
                'set_current_uA': PSSessionParser._to_number_if_possible(action.get('Current (uA)')),
                'current_range': action.get('Current Range'),
                'time_per_point_s': PSSessionParser._to_number_if_possible(action.get('Time Per Point (s)')),
                'start_freq_Hz': PSSessionParser._to_number_if_possible(action.get('Start Frequency (Hz)')),
                'end_freq_Hz': PSSessionParser._to_number_if_possible(action.get('End Frequency (Hz)')),
                'freq_Hz': PSSessionParser._to_number_if_possible(action.get('Frequency (Hz)')),
                'pts_per_decade': PSSessionParser._to_number_if_possible(action.get('Points Per Decade')),
                'ac_amplitude_mV': PSSessionParser._to_number_if_possible(action.get('Amplitude (mV RMS)') or action.get('AC Amplitude (mV),Value')),
            }
            if pa.get('technique') in {'CA', 'CP', 'OCP', 'COND', 'ZRA'} and not pa.get('total_points'):
                dur = pa.get('duration_s')
                tpp = pa.get('time_per_point_s')
                if isinstance(dur, (int, float)) and isinstance(tpp, (int, float)) and tpp and dur:
                    pa['total_points'] = int(dur / tpp) + 2
            parsed_actions.append(pa)
        meta['parsed_actions'] = parsed_actions
        meta['technique_counts'] = dict(Counter(a['technique'] for a in parsed_actions))
        return meta

    def _choose_header_skip(self, data: bytes) -> int:
        candidates = [0, 8]
        best = 0
        best_score = -1
        for skip in candidates:
            if len(data) < skip + self.CV_RECORD_BYTES:
                continue
            n = min(12, max(1, (len(data) - skip) // self.CV_RECORD_BYTES))
            score = 0
            for i in range(n):
                off = skip + i * self.CV_RECORD_BYTES
                try:
                    e = self._be_f32(data, off + self.CV_OFF_E_VOLTS)
                    t = self._be_i32(data, off + self.CV_OFF_ELAPSED_US)
                    pt = self._be_i32(data, off + self.CV_OFF_PT_IDX)
                    if np.isfinite(e) and -10 <= e <= 10:
                        score += 2
                    if 0 <= t < 10**12:
                        score += 1
                    if 0 <= pt < 10**8:
                        score += 1
                except Exception:
                    pass
            if score > best_score:
                best = skip
                best_score = score
        return best

    def _decode_dc_records(self, data: bytes):
        skip = self._choose_header_skip(data)
        n_records = max(0, (len(data) - skip) // self.CV_RECORD_BYTES)
        arr = np.empty((n_records, 7), dtype=np.float64)
        t_raw = np.empty(n_records, dtype=np.int32)
        for i in range(n_records):
            off = skip + i * self.CV_RECORD_BYTES
            e_applied_v = self._be_f32(data, off + self.CV_OFF_E_VOLTS)
            e_adc = self._be_i32(data, off + self.CV_OFF_E_ADC) / self.E_ADC_SCALE
            t_raw[i] = self._be_i32(data, off + self.CV_OFF_ELAPSED_US)
            pt_idx = self._be_i32(data, off + self.CV_OFF_PT_IDX)
            seg_id = self._be_i32(data, off + self.CV_OFF_SEG_ID)
            raw_range = self._be_i32(data, off + self.CV_OFF_I_RANGE_CODE)
            range_code = self.decode_range_code(raw_range)
            i_adc = self._be_i32(data, off + self.CV_OFF_I_ADC)
            i_a = self.compute_current(i_adc, range_code)
            arr[i] = [e_applied_v, e_adc, i_a, 0.0, float(range_code), float(pt_idx), float(seg_id)]
        arr[:, 3] = self._unwrap_elapsed_seconds(t_raw)
        nan_mask = ~np.isfinite(arr[:, 2])
        if nan_mask.any() and (~nan_mask).any():
            idx = np.arange(len(arr))
            valid = ~nan_mask
            arr[nan_mask, 2] = np.interp(idx[nan_mask], idx[valid], arr[valid, 2])
        return arr, skip

    def _is_likely_dc_record(self, data: bytes, rec_index: int) -> bool:
        off = rec_index * self.CV_RECORD_BYTES
        if off + self.CV_RECORD_BYTES > len(data):
            return False
        try:
            e = self._be_f32(data, off + self.CV_OFF_E_VOLTS)
            t = self._be_i32(data, off + self.CV_OFF_ELAPSED_US)
            pt = self._be_i32(data, off + self.CV_OFF_PT_IDX)
        except Exception:
            return False
        return bool(np.isfinite(e) and -2.5 <= e <= 2.5 and 0 <= t < 10**10 and 0 <= pt < 10**8)

    def _detect_cv_end(self, data: bytes, start_rec: int, max_recs: int) -> int:
        total_recs = len(data) // self.CV_RECORD_BYTES
        max_recs = min(max_recs, max(0, total_recs - start_rec))
        bad_run = 0
        last_good = 0
        for k in range(max_recs):
            if self._is_likely_dc_record(data, start_rec + k):
                last_good = k + 1
                bad_run = 0
            else:
                bad_run += 1
                if k > 100 and bad_run >= 6:
                    break
        return last_good

    def _sanitize_dc_segment(self, seg: np.ndarray, tech: str, action: dict | None = None):
        if not isinstance(seg, np.ndarray) or seg.size == 0:
            return seg, None
        seg = np.asarray(seg, dtype=np.float64)
        row_valid = (
            np.all(np.isfinite(seg[:, :4]), axis=1)
            & (np.abs(seg[:, 0]) <= 10.0)
            & (np.abs(seg[:, 1]) <= 10.0)
            & (np.abs(seg[:, 2]) <= 1.0)
            & (seg[:, 3] >= -1e-9)
        )
        if len(seg) > 1:
            dt = np.diff(seg[:, 3])
            bad_time = np.r_[False, dt < -1e-6]
            row_valid &= ~bad_time
        if row_valid.all():
            return seg, None
        min_prefix = min(200, max(20, len(seg)//20))
        bad_run = 0
        cut = len(seg)
        for i, ok in enumerate(row_valid):
            if ok:
                bad_run = 0
            else:
                bad_run += 1
                if i >= min_prefix and bad_run >= 24:
                    cut = i - bad_run + 1
                    break
        if cut == len(seg):
            valid_idx = np.flatnonzero(row_valid)
            if valid_idx.size:
                cut = int(valid_idx[-1]) + 1
        cut = max(0, min(cut, len(seg)))
        trimmed = seg[:cut].copy() if cut < len(seg) else seg
        note = None
        if cut < len(seg):
            note = f"Trimmed corrupted tail from {tech} segment: kept {cut} of {len(seg)} points."
        return trimmed, note

    def _sanitize_eis_array(self, arr: np.ndarray):
        if not isinstance(arr, np.ndarray) or arr.size == 0:
            return None, None
        arr = np.asarray(arr, dtype=np.float64)
        if arr.ndim != 2 or arr.shape[1] < 5:
            return None, 'Discarded malformed EIS block.'
        finite = np.all(np.isfinite(arr[:, :5]), axis=1)
        phys = (
            (arr[:, 0] > 0)
            & (np.abs(arr[:, 1]) < 1e9)
            & (np.abs(arr[:, 2]) < 1e9)
            & ((np.abs(arr[:, 1]) + np.abs(arr[:, 2])) > 0)
        )
        keep = finite & phys
        cleaned = arr[keep]
        if len(cleaned) < 5:
            return None, f"Discarded nominal EIS block as empty/corrupted: only {len(cleaned)} physically valid rows remained."
        if len(cleaned) < max(10, int(0.1 * len(arr))):
            return None, f"Discarded nominal EIS block: only {len(cleaned)} of {len(arr)} rows were physically valid."
        cleaned = cleaned[np.argsort(cleaned[:, 0])[::-1]]
        note = None
        if len(cleaned) != len(arr):
            note = f"Filtered EIS block from {len(arr)} to {len(cleaned)} physically valid rows before export."
        return cleaned, note

    def _decode_eis_rows(self, data: bytes, start: int, max_rows: int | None = None) -> np.ndarray:
        total = len(data)
        rows = []
        off = start
        n = 0
        while off + self.EIS_RECORD_BYTES <= total:
            freq = self._be_f32(data, off + self.EIS_OFF_FREQ_HZ)
            zre = self._be_f32(data, off + self.EIS_OFF_ZREAL_OHM)
            zim = self._be_f32(data, off + self.EIS_OFF_ZIMAG_OHM)
            amp = self._be_f32(data, off + self.EIS_OFF_AC_AMP_V)
            if not (np.isfinite(freq) and 1e-3 <= freq <= 1.1e7 and np.isfinite(zre) and np.isfinite(zim)
                    and abs(zre) < 1e9 and abs(zim) < 1e9 and np.isfinite(amp) and 0 <= abs(amp) <= 10):
                break
            zabs = float(np.hypot(zre, zim))
            phase = float(np.degrees(np.arctan2(zim, zre)))
            rows.append([freq, zre, zim, zabs, phase, amp])
            off += self.EIS_RECORD_BYTES
            n += 1
            if max_rows is not None and n >= max_rows:
                break
        return np.asarray(rows, dtype=np.float64) if rows else np.empty((0, 6), dtype=np.float64)

    def _split_eis_sweeps(self, arr: np.ndarray) -> list:
        if not isinstance(arr, np.ndarray) or arr.size == 0:
            return []
        freq = arr[:, 0]
        starts = [0]
        for i in range(len(freq) - 1):
            if freq[i+1] > freq[i] * 1.2:
                starts.append(i + 1)
        starts = sorted(set(starts))
        sweeps = []
        for s, e in zip(starts, starts[1:] + [len(arr)]):
            chunk = arr[s:e]
            if len(chunk) >= 5:
                sweeps.append(chunk)
        return sweeps

    def _score_eis_candidate(self, data: bytes, start: int, expected_sweeps: int = 0) -> tuple:
        arr = self._decode_eis_rows(data, start, max_rows=max(64, expected_sweeps * 320 if expected_sweeps else 512))
        if len(arr) < 20:
            return (-1e9, [])
        sweeps = self._split_eis_sweeps(arr)
        if not sweeps:
            return (-1e9, [])
        score = 0.0
        for sw in sweeps[: max(1, expected_sweeps or len(sweeps))]:
            f = sw[:, 0]
            desc_ratio = float(np.mean(np.diff(f) <= 0)) if len(f) > 1 else 1.0
            score += desc_ratio * 20.0
            score += min(len(sw), 400) / 10.0
        if expected_sweeps:
            score -= abs(len(sweeps) - expected_sweeps) * 8.0
        score += float(np.log10(max(1e-3, arr[0, 0])))
        return score, sweeps

    def _find_eis_sweeps(self, data: bytes, start_hint: int = 0, expected_sweeps: int = 0):
        total = len(data)
        min_tail = self.EIS_RECORD_BYTES * 6
        if total < min_tail:
            return (None, [])
        max_start = max(0, total - min_tail)
        start_hint = max(0, min(start_hint, max_start))
        candidate_starts = []
        # Search narrowly near the expected DC->EIS boundary; this avoids false
        # positives at byte 0 and keeps load times reasonable for large collections.
        windows = [
            (max(0, start_hint - 256), min(total, start_hint + 1024)),
            (max(0, start_hint - 2048), min(total, start_hint + 8192)),
        ]
        seen = set()
        for base_start, base_end in windows:
            end_for_scan = max(base_start, base_end - self.EIS_RECORD_BYTES * 6)
            for start in range(base_start, end_for_scan, 4):
                if start not in seen:
                    candidate_starts.append(start)
                    seen.add(start)
        if not candidate_starts:
            return (None, [])
        best_score = -1e18
        best = (None, [])
        for start in candidate_starts:
            score, sweeps = self._score_eis_candidate(data, start, expected_sweeps=expected_sweeps)
            if score > best_score:
                best_score = score
                best = (start, sweeps)
        if best_score < -1e6:
            return (None, [])
        return best

    def _eis_action_metadata(self) -> list:
        metas = []
        ocp = self.metadata.get('ocp_measured_V')
        eis_actions = [a for a in self.metadata.get('parsed_actions', []) if a.get('technique') == 'EIS']
        for i, action in enumerate(eis_actions, start=1):
            dc = action.get('hold_V')
            if i == 1 and isinstance(ocp, (int, float)):
                label = f"OCP ({ocp:+.3f} V)"
            elif isinstance(dc, (int, float)):
                label = f"{dc:+.3f} V"
            else:
                label = f"Sweep {i}"
            metas.append({
                'action_id': action.get('action_id'),
                'title': action.get('name') or 'Potentiostatic EIS',
                'technique': 'EIS',
                'dc_potential_V': dc,
                'label': label,
                'start_freq_Hz': action.get('start_freq_Hz'),
                'end_freq_Hz': action.get('end_freq_Hz'),
                'pts_per_decade': action.get('pts_per_decade'),
                'ac_amplitude_mV': action.get('ac_amplitude_mV'),
            })
        return metas

    def _paired_eis_sweeps(self):
        sweeps = list(self.decoded.get('eis_sweeps') or [])
        metas = self.decoded.get('eis_sweep_metadata') or self._eis_action_metadata()
        paired = []
        n = max(len(metas), len(sweeps))
        for i in range(n):
            meta = metas[i].copy() if i < len(metas) else {'action_id': None, 'title': 'Potentiostatic EIS', 'technique': 'EIS', 'label': f'Sweep {i+1}', 'dc_potential_V': None}
            arr = sweeps[i] if i < len(sweeps) else None
            meta['recovered'] = arr is not None
            meta['n_points'] = int(len(arr)) if isinstance(arr, np.ndarray) else 0
            paired.append((meta, arr))
        return paired


    def _parse_psbd(self, path: str) -> dict:
        data = Path(path).read_bytes()
        actions_dc = [a for a in self.metadata.get('parsed_actions', []) if a.get('technique') in {'CV', 'LSV', 'CA', 'CP', 'OCP', 'ZRA'}]
        actions_eis = [a for a in self.metadata.get('parsed_actions', []) if a.get('technique') == 'EIS']

        header_skip = self._choose_header_skip(data)
        notes = []
        dc_segments = []

        expected_dc_points = sum(int(a.get('total_points')) for a in actions_dc if isinstance(a.get('total_points'), (int, float)) and a.get('total_points'))
        use_expected_layout = bool(expected_dc_points and header_skip + expected_dc_points * self.CV_RECORD_BYTES <= len(data))

        rec_cursor = 0
        byte_cursor = header_skip
        eis_start = None
        eis_list = []

        if use_expected_layout:
            # Standard case: use metadata-guided DC length and locate EIS near the expected cursor.
            expected_dc_end = header_skip + expected_dc_points * self.CV_RECORD_BYTES
            eis_start, eis_sweeps = (None, [])
            if actions_eis and expected_dc_end < len(data):
                eis_start, eis_sweeps = self._find_eis_sweeps(data, start_hint=expected_dc_end, expected_sweeps=len(actions_eis))
            dc_data = data[:eis_start] if eis_start is not None else data[:min(len(data), expected_dc_end)]
            full_arr, _ = self._decode_dc_records(dc_data)
            notes.append(f'Decoded {len(full_arr)} raw 48-byte records from .psbd (header skip {header_skip} bytes).')
            notes.append(f'Action metadata declared {expected_dc_points} DC points before EIS.')
            pos = 0
            for idx, action in enumerate(actions_dc, start=1):
                tech = (action.get('technique') or 'DC').upper()
                title = action.get('name') or tech
                want = action.get('total_points')
                want = int(want) if isinstance(want, (int, float)) and want and want > 0 else None
                arr = full_arr[pos: pos + want] if want is not None else full_arr[pos:]
                pos += len(arr)
                if tech in {'OCP', 'ZRA'} and isinstance(arr, np.ndarray) and arr.size:
                    arr = arr.copy()
                    arr[:, 0] = arr[:, 1]
                arr, seg_note = self._sanitize_dc_segment(arr, tech, action)
                if seg_note:
                    notes.append(seg_note)
                if want is not None and len(arr) != want:
                    notes.append(f'{title}: decoded {len(arr)} of expected {want} points.')
                if not isinstance(arr, np.ndarray) or len(arr) == 0:
                    continue
                cycles_data = []
                n_curves = 1
                pts_per_cycle = action.get('pts_per_cycle')
                if tech == 'CV' and isinstance(pts_per_cycle, (int, float)) and pts_per_cycle and len(arr) > 0:
                    ppc = int(pts_per_cycle)
                    for c in range(0, len(arr), ppc):
                        chunk = arr[c:c+ppc]
                        if len(chunk):
                            chunk, chunk_note = self._sanitize_dc_segment(chunk, tech, action)
                            if chunk_note:
                                notes.append(chunk_note)
                            if len(chunk):
                                cycles_data.append(chunk)
                    n_curves = len(cycles_data) if cycles_data else 1
                else:
                    cycles_data = [arr]
                dc_segments.append({
                    'segment_index': idx,
                    'title': title,
                    'technique': tech,
                    'n_points': int(len(arr)),
                    'n_curves': int(n_curves),
                    'scan_rate_V_s': action.get('scan_rate_V_s'),
                    'scan_rate_mV_s': float(action.get('scan_rate_V_s') * 1000.0) if isinstance(action.get('scan_rate_V_s'), (int, float)) else None,
                    'pts_per_cycle': int(action.get('pts_per_cycle')) if isinstance(action.get('pts_per_cycle'), (int, float)) and action.get('pts_per_cycle') else None,
                    'cycles': int(action.get('cycles')) if isinstance(action.get('cycles'), (int, float)) and action.get('cycles') else None,
                    'vertex1_V': action.get('vertex1_V'),
                    'vertex2_V': action.get('vertex2_V'),
                    'initial_V': action.get('initial_V'),
                    'final_V': action.get('final_V'),
                    'hold_V': action.get('hold_V'),
                    'duration_s': action.get('duration_s'),
                    'set_current_uA': action.get('set_current_uA'),
                    'data': arr,
                    'curves': cycles_data,
                })
            byte_cursor = pos * self.CV_RECORD_BYTES + header_skip
            if eis_start is not None:
                notes.append(f'Located EIS region at byte offset {eis_start}.')
                for sw in eis_sweeps:
                    clean, note = self._sanitize_eis_array(sw[:, :5])
                    if note:
                        notes.append(note)
                    if clean is not None and len(clean):
                        eis_list.append(clean)
        else:
            # Fallback case: file is shorter than the declared DC portion.
            # Decode DC actions sequentially until record validity fails; this recovers
            # truncated multi-rate files without falsely declaring EIS at byte 0.
            for idx, action in enumerate(actions_dc, start=1):
                tech = (action.get('technique') or 'DC').upper()
                title = action.get('name') or tech
                want = action.get('total_points')
                want = int(want) if isinstance(want, (int, float)) and want and want > 0 else None
                max_recs = max(0, (len(data) - byte_cursor) // self.CV_RECORD_BYTES)
                actual = self._detect_cv_end(data[byte_cursor:], 0, min(max_recs, (want + 40) if want else max_recs))
                if want is not None:
                    actual = min(actual, want)
                if actual <= 0:
                    notes.append(f'{title}: decoded 0 of expected {want} points.' if want else f'{title}: decoded 0 points.')
                    continue
                arr, _ = self._decode_dc_records(data[byte_cursor: byte_cursor + actual * self.CV_RECORD_BYTES])
                byte_cursor += actual * self.CV_RECORD_BYTES
                rec_cursor += actual
                if tech in {'OCP', 'ZRA'} and isinstance(arr, np.ndarray) and arr.size:
                    arr = arr.copy()
                    arr[:, 0] = arr[:, 1]
                arr, seg_note = self._sanitize_dc_segment(arr, tech, action)
                if seg_note:
                    notes.append(seg_note)
                if want is not None and len(arr) != want:
                    notes.append(f'{title}: decoded {len(arr)} of expected {want} points.')
                if not isinstance(arr, np.ndarray) or len(arr) == 0:
                    continue
                cycles_data = []
                n_curves = 1
                pts_per_cycle = action.get('pts_per_cycle')
                if tech == 'CV' and isinstance(pts_per_cycle, (int, float)) and pts_per_cycle and len(arr) > 0:
                    ppc = int(pts_per_cycle)
                    for c in range(0, len(arr), ppc):
                        chunk = arr[c:c+ppc]
                        if len(chunk):
                            chunk, chunk_note = self._sanitize_dc_segment(chunk, tech, action)
                            if chunk_note:
                                notes.append(chunk_note)
                            if len(chunk):
                                cycles_data.append(chunk)
                    n_curves = len(cycles_data) if cycles_data else 1
                else:
                    cycles_data = [arr]
                dc_segments.append({
                    'segment_index': idx,
                    'title': title,
                    'technique': tech,
                    'n_points': int(len(arr)),
                    'n_curves': int(n_curves),
                    'scan_rate_V_s': action.get('scan_rate_V_s'),
                    'scan_rate_mV_s': float(action.get('scan_rate_V_s') * 1000.0) if isinstance(action.get('scan_rate_V_s'), (int, float)) else None,
                    'pts_per_cycle': int(action.get('pts_per_cycle')) if isinstance(action.get('pts_per_cycle'), (int, float)) and action.get('pts_per_cycle') else None,
                    'cycles': int(action.get('cycles')) if isinstance(action.get('cycles'), (int, float)) and action.get('cycles') else None,
                    'vertex1_V': action.get('vertex1_V'),
                    'vertex2_V': action.get('vertex2_V'),
                    'initial_V': action.get('initial_V'),
                    'final_V': action.get('final_V'),
                    'hold_V': action.get('hold_V'),
                    'duration_s': action.get('duration_s'),
                    'set_current_uA': action.get('set_current_uA'),
                    'data': arr,
                    'curves': cycles_data,
                })
            notes.insert(0, f'Decoded {rec_cursor} raw 48-byte records from .psbd (header skip {header_skip} bytes).')
            if expected_dc_points:
                notes.insert(1, f'Action metadata declared {expected_dc_points} DC points before EIS.')
            # Only search for EIS if enough bytes remain after the recovered DC prefix.
            if actions_eis and byte_cursor + self.EIS_RECORD_BYTES * 5 <= len(data):
                eis_start, eis_sweeps = self._find_eis_sweeps(data, start_hint=byte_cursor, expected_sweeps=len(actions_eis))
                if eis_start is not None:
                    notes.append(f'Located EIS region at byte offset {eis_start}.')
                    for sw in eis_sweeps:
                        clean, note = self._sanitize_eis_array(sw[:, :5])
                        if note:
                            notes.append(note)
                        if clean is not None and len(clean):
                            eis_list.append(clean)
                else:
                    notes.append('No valid EIS region could be located after the decoded DC prefix.')
            elif actions_eis:
                notes.append('No byte room remained after decoded DC segments for a valid EIS block.')

        eis_meta = self._eis_action_metadata()
        if actions_eis and len(eis_list) != len(eis_meta):
            notes.append(f'Recovered {len(eis_list)} EIS sweep(s) for {len(eis_meta)} EIS actions declared in .par.')
        if eis_list:
            for i, sw in enumerate(eis_list, start=1):
                notes.append(f'  EIS sweep {i}: {len(sw)} points, {sw[:,0].max():.6g} to {sw[:,0].min():.6g} Hz.')

        eis_arr = np.vstack(eis_list) if eis_list else None
        return {
            'dc_segments': dc_segments,
            'cv_segments': [s for s in dc_segments if s.get('technique') == 'CV'],
            'eis': eis_arr,
            'eis_sweeps': eis_list,
            'eis_sweep_metadata': eis_meta,
            'eis_n_points': int(sum(len(sw) for sw in eis_list)) if eis_list else 0,
            'eis_start_byte': eis_start if eis_list else None,
            'layout': {'dc_record_bytes': self.CV_RECORD_BYTES, 'eis_record_bytes': self.EIS_RECORD_BYTES},
            'header_skip_bytes': header_skip,
            'notes': notes,
        }

    @staticmethod
    def _resolve_psbd_path(par_path: Path) -> Path:
        """Return the VersaStudio binary companion for a .par method file.

        VersaStudio exports are encountered in both common forms::

            experiment.par + experiment.psbd
            experiment.par + experiment.par.psbd

        The earlier FaradaIQ resolver only checked the second form, which made a
        valid standard ``.par``/``.psbd`` pair fail during Load + inspect.  The
        lookup below accepts both forms and performs a case-insensitive fallback
        so copied Windows datasets also load in case-sensitive environments.
        """
        par_path = Path(par_path)
        candidates = [
            par_path.with_suffix('.psbd'),
            Path(str(par_path) + '.psbd'),
        ]
        seen = set()
        ordered = []
        for candidate in candidates:
            key = str(candidate)
            if key not in seen:
                seen.add(key)
                ordered.append(candidate)
                if candidate.is_file():
                    return candidate

        try:
            siblings = {
                child.name.casefold(): child
                for child in par_path.parent.iterdir()
                if child.is_file()
            }
            for candidate in ordered:
                match = siblings.get(candidate.name.casefold())
                if match is not None:
                    return match
        except Exception:
            pass

        checked = ', '.join(candidate.name for candidate in ordered)
        nearby = []
        try:
            nearby = sorted(child.name for child in par_path.parent.iterdir()
                            if child.is_file() and child.suffix.lower() == '.psbd')
        except Exception:
            pass
        detail = f' Checked: {checked}.'
        if nearby:
            detail += ' Nearby .psbd files: ' + ', '.join(nearby[:12]) + '.'
        raise RuntimeError(
            f'Matching VersaStudio binary data file not found for {par_path.name}.{detail}'
        )

    def load(self, path: str):
        par_path = Path(path)
        if par_path.suffix.lower() != '.par':
            raise RuntimeError('VersaStudioParser expects a .par file.')
        psbd_path = self._resolve_psbd_path(par_path)
        self.metadata = self._parse_par_metadata(str(par_path))
        self.source_path = str(par_path)
        self.psbd_path = str(psbd_path)
        self.decoded = self._parse_psbd(str(psbd_path))
        return {'metadata': self.metadata, 'decoded': self.decoded}

    def summarize(self) -> dict:
        if self.metadata is None:
            raise RuntimeError('No VersaStudio file loaded.')
        rows = [{'index': 0, 'title': 'Common', 'method_id': 'Common', 'technique': 'Common', 'n_curves': 0, 'n_eis_blocks': 0, 'curve_titles': []}]
        for idx, seg in enumerate(self.decoded.get('dc_segments', []), start=1):
            title = seg.get('title') or seg.get('technique')
            rows.append({
                'index': idx,
                'title': title,
                'method_id': title,
                'technique': seg.get('technique'),
                'n_curves': int(seg.get('n_curves') or 1),
                'n_eis_blocks': 0,
                'curve_titles': [f"{seg.get('technique')} curve {i+1}" for i in range(int(seg.get('n_curves') or 1))],
            })
        for meta, arr in self._paired_eis_sweeps():
            rows.append({
                'index': len(rows),
                'title': meta.get('title') or 'Potentiostatic EIS',
                'method_id': meta.get('label') or 'Potentiostatic EIS',
                'technique': 'EIS',
                'n_curves': 0,
                'n_eis_blocks': 1 if arr is not None else 0,
                'curve_titles': [meta.get('label')] if arr is not None else [],
            })
        technique_counts = Counter(r['technique'] for r in rows if r.get('technique'))
        return {
            'source_file': self.source_path,
            'binary_data_file': self.psbd_path,
            'session_type': 'VersaStudio',
            'core_version': self.metadata.get('application_version'),
            'n_measurements': len(rows),
            'technique_counts': dict(technique_counts),
            'measurement_rows': rows,
            'notes': self.decoded.get('notes', []),
        }

    def build_compact_summary(self) -> dict:
        summary = self.summarize()
        action_rows = []
        for seg in self.decoded.get('dc_segments', []):
            row = {
                'title': seg.get('title'),
                'technique': seg.get('technique'),
                'scan_rate': seg.get('scan_rate_V_s'),
                'n_scans': seg.get('n_curves'),
                'n_points': seg.get('n_points'),
                'duration_s': seg.get('duration_s'),
                'hold_V': seg.get('hold_V'),
                'set_current_uA': seg.get('set_current_uA'),
            }
            if seg.get('technique') in {'CV', 'LSV'}:
                row.update({'e_begin': seg.get('initial_V') or seg.get('vertex2_V'), 'e_end': seg.get('final_V') or seg.get('vertex1_V')})
            action_rows.append(row)
        for meta, arr in self._paired_eis_sweeps():
            action_rows.append({
                'title': meta.get('title') or 'Potentiostatic EIS',
                'technique': 'EIS',
                'n_scans': 1,
                'n_points': int(len(arr)) if isinstance(arr, np.ndarray) else 0,
                'freq_min_Hz': float(np.min(arr[:, 0])) if isinstance(arr, np.ndarray) and len(arr) else None,
                'freq_max_Hz': float(np.max(arr[:, 0])) if isinstance(arr, np.ndarray) and len(arr) else None,
                'dc_potential_V': meta.get('dc_potential_V'),
                'label': meta.get('label'),
                'recovered': bool(meta.get('recovered')),
            })
        return {
            'source_file': self.source_path,
            'binary_data_file': self.psbd_path,
            'session_type': 'VersaStudio',
            'core_version': self.metadata.get('application_version'),
            'n_measurements': summary.get('n_measurements'),
            'technique_counts': summary.get('technique_counts'),
            'measurement_rows': action_rows or summary.get('measurement_rows', []),
            'decoded_counts': {
                'n_dc_segments': len(self.decoded.get('dc_segments', [])),
                'n_eis_points': int(sum(len(sw) for sw in (self.decoded.get('eis_sweeps') or []))),
            },
            'notes': self.decoded.get('notes', []),
        }

    def session_minified_json(self) -> str:
        payload = {
            'format': 'versastudio-native-v4',
            'source_file': self.source_path,
            'binary_data_file': self.psbd_path,
            'metadata': self.metadata,
            'decoded_summary': {
                'n_dc_segments': len(self.decoded.get('dc_segments', [])),
                'n_eis_points': int(sum(len(sw) for sw in (self.decoded.get('eis_sweeps') or []))),
                'notes': self.decoded.get('notes', []),
            },
        }
        return json.dumps(payload, ensure_ascii=False, separators=(',', ':'))

    def iter_primary_curve_exports(self):
        if self.metadata is None:
            raise RuntimeError('No VersaStudio file loaded.')
        m_idx = 1
        for seg in self.decoded.get('dc_segments', []):
            tech = seg.get('technique')
            curves = seg.get('curves') or ([seg.get('data')] if isinstance(seg.get('data'), np.ndarray) else [])
            for cidx, arr in enumerate(curves, start=1):
                if not isinstance(arr, np.ndarray) or arr.size == 0:
                    continue
                if tech in {'CV', 'LSV'}:
                    x_label, x_unit, y_label, y_unit = 'Applied potential', 'V', 'Current', 'A'
                    rows = [(float(r[0]), float(r[2])) for r in arr]
                elif tech == 'CA':
                    x_label, x_unit, y_label, y_unit = 'Elapsed time', 's', 'Current', 'A'
                    rows = [(float(r[3]), float(r[2])) for r in arr]
                elif tech == 'CP':
                    x_label, x_unit, y_label, y_unit = 'Elapsed time', 's', 'Potential', 'V'
                    rows = [(float(r[3]), float(r[0])) for r in arr]
                elif tech == 'OCP':
                    x_label, x_unit, y_label, y_unit = 'Elapsed time', 's', 'Open-circuit potential', 'V'
                    rows = [(float(r[3]), float(r[0])) for r in arr]
                else:
                    x_label, x_unit, y_label, y_unit = 'Elapsed time', 's', 'Signal', 'arb'
                    rows = [(float(r[3]), float(r[0])) for r in arr]
                yield {
                    'measurement_index': m_idx,
                    'curve_index': cidx,
                    'measurement_title': seg.get('title') or tech,
                    'curve_title': f"{tech}_{cidx}",
                    'method_id': f'versastudio_{tech.lower()}',
                    'technique': tech,
                    'scan_rate': seg.get('scan_rate_V_s'),
                    'x_label': x_label,
                    'x_unit': x_unit,
                    'y_label': y_label,
                    'y_unit': y_unit,
                    'rows': rows,
                }
            m_idx += 1
        for meta, eis_arr in self._paired_eis_sweeps():
            if not isinstance(eis_arr, np.ndarray) or len(eis_arr) == 0:
                m_idx += 1
                continue
            label = meta.get('label') or 'EIS'
            title = meta.get('title') or 'Potentiostatic EIS'
            yield {
                'measurement_index': m_idx,
                'curve_index': 1,
                'measurement_title': title,
                'curve_title': f'{label}_Nyquist',
                'method_id': 'versastudio_eis',
                'technique': 'EIS',
                'scan_rate': None,
                'x_label': 'Zreal',
                'x_unit': 'ohm',
                'y_label': '-Zimag',
                'y_unit': 'ohm',
                'rows': [(float(r[1]), float(-r[2])) for r in eis_arr],
            }
            yield {
                'measurement_index': m_idx,
                'curve_index': 2,
                'measurement_title': title,
                'curve_title': f'{label}_Bode_mag',
                'method_id': 'versastudio_eis',
                'technique': 'EIS',
                'scan_rate': None,
                'x_label': 'Frequency',
                'x_unit': 'Hz',
                'y_label': '|Z|',
                'y_unit': 'ohm',
                'rows': [(float(r[0]), float(r[3])) for r in eis_arr],
            }
            yield {
                'measurement_index': m_idx,
                'curve_index': 3,
                'measurement_title': title,
                'curve_title': f'{label}_Bode_phase',
                'method_id': 'versastudio_eis',
                'technique': 'EIS',
                'scan_rate': None,
                'x_label': 'Frequency',
                'x_unit': 'Hz',
                'y_label': 'Phase',
                'y_unit': 'deg',
                'rows': [(float(r[0]), float(r[4])) for r in eis_arr],
            }
            m_idx += 1

    def native_numeric_payload(self) -> dict:
        payload = {
            'format': 'versastudio-native-v4',
            'source_file': self.source_path,
            'binary_data_file': self.psbd_path,
            'metadata': self.metadata,
            'segments': {},
        }
        for idx, seg in enumerate(self.decoded.get('dc_segments', []), start=1):
            key = f"segment_{idx:03d}_{(seg.get('technique') or 'dc').lower()}"
            payload['segments'][key] = {
                'title': seg.get('title'),
                'technique': seg.get('technique'),
                'scan_rate_mV_s': seg.get('scan_rate_mV_s'),
                'scan_rate_V_s': seg.get('scan_rate_V_s'),
                'n_points': seg.get('n_points'),
                'n_curves': seg.get('n_curves'),
                'duration_s': seg.get('duration_s'),
                'hold_V': seg.get('hold_V'),
                'set_current_uA': seg.get('set_current_uA'),
                'array': seg.get('data'),
            }
        eis_sweeps = self.decoded.get('eis_sweeps') or []
        eis_meta = self.decoded.get('eis_sweep_metadata') or []
        if eis_sweeps:
            payload['eis_sweeps'] = eis_sweeps
            payload['eis_sweep_metadata'] = eis_meta
            payload['eis'] = np.vstack(eis_sweeps)
        elif eis_meta:
            payload['eis_sweep_metadata'] = eis_meta
        return payload


class SolartronParser:
    """Reader for Solartron CorrWare/ZPlot ASCII files (.cor, .z)."""

    DECODE_ENCODINGS = ("utf-8-sig", "utf-8", "latin-1")
    COLS_COR = ["E_V", "I_A_cm2", "time_s"]
    COLS_EIS = ["freq_Hz", "Zreal_ohm", "Zimag_ohm", "Zabs_ohm", "phase_deg",
                "ampl_V", "bias_V", "time_s", "err", "range_code"]

    def __init__(self):
        self.text = None
        self.source_path = None
        self.kind = None
        self.metadata = {}
        self.data = None
        self.session = None

    @classmethod
    def _decode_bytes(cls, data: bytes) -> str:
        last_error = None
        for enc in cls.DECODE_ENCODINGS:
            try:
                return data.decode(enc).replace("\r\n", "\n").replace("\r", "\n")
            except Exception as exc:
                last_error = exc
        raise RuntimeError(f"Could not decode Solartron file bytes: {last_error}")

    @staticmethod
    def _sanitize_filename(text: str) -> str:
        return PSSessionParser._sanitize_filename(text)

    @staticmethod
    def _to_number_if_possible(value):
        return PSSessionParser._to_number_if_possible(value)

    @staticmethod
    def _floatish(s):
        if s is None:
            return None
        try:
            return float(str(s).split()[0])
        except Exception:
            return None

    @staticmethod
    def _intish(s):
        if s is None:
            return None
        try:
            return int(float(str(s).split()[0]))
        except Exception:
            return None

    @staticmethod
    def _kv(lines, key):
        key_l = key.lower()
        for line in lines:
            l = line.strip()
            if key_l in l.lower() and ':' in l:
                _, _, v = l.partition(':')
                return v.strip()
        return None

    @classmethod
    def _find_data_start(cls, lines):
        for i, line in enumerate(lines):
            if line.strip() == 'End Comments':
                col_header = lines[i - 1].strip() if i > 0 else ''
                return i + 1, col_header
        return None, None

    @staticmethod
    def _split_numeric_line(line: str):
        return [p for p in re.split(r'[\t, ]+', line.strip()) if p != '']

    @staticmethod
    def _infer_technique(kind: str, title: str, source_name: str, meta: dict) -> str:
        blob = f"{title} {source_name} {meta.get('experiment_type','')} {meta.get('experiment_description','')}".lower()
        if kind == 'z' or 'zplot' in blob or 'impedance' in blob or re.search(r'\beis\b', blob):
            return 'EIS'
        if 'conduct' in blob or re.search(r'\bcond\b', blob):
            return 'COND'
        if 'zero resistance' in blob or re.search(r'\bzra\b', blob):
            return 'ZRA'
        if 'open circuit' in blob or re.search(r'\bocp\b', blob):
            return 'OCP'
        if 'cyclic' in blob or 'voltamm' in blob or re.search(r'(^|[_\- ])cv([_\- ]|$)', blob):
            return 'CV'
        if 'linear sweep' in blob or 'linear polarization' in blob or re.search(r'(^|[_\- ])lsv([_\- ]|$)', blob):
            return 'LSV'
        if 'potentiostatic' in blob or 'chronoamper' in blob or 'constv' in blob or 'const v' in blob:
            return 'CA'
        if 'galvanostatic' in blob or 'chronopot' in blob or 'consti' in blob or 'const i' in blob:
            return 'CP'
        return 'Unknown'

    @classmethod
    def _split_cycles_cv(cls, arr: np.ndarray, n_cycles: int):
        if n_cycles is None or n_cycles <= 1 or len(arr) < 3:
            return [arr]
        E = arr[:, 0]
        dE = np.diff(E)
        signs = np.sign(dE)
        turns = []
        prev = None
        for i, s in enumerate(signs):
            if s == 0:
                continue
            if prev is None:
                prev = s
                continue
            if s != prev:
                turns.append(i)
                prev = s
        bounds = [0]
        if len(turns) >= 2:
            for i in range(1, len(turns), 2):
                bounds.append(turns[i] + 1)
        bounds.append(len(arr))
        cycles = []
        for i in range(min(n_cycles, len(bounds) - 1)):
            s, e = bounds[i], bounds[i + 1]
            if s < e:
                cycles.append(arr[s:e])
        if len(cycles) != n_cycles:
            chunk = max(1, len(arr) // n_cycles)
            cycles = [arr[i * chunk:(i + 1) * chunk if i < n_cycles - 1 else len(arr)] for i in range(n_cycles)]
        return cycles

    def _parse_cor_header(self, lines):
        meta = {}
        if len(lines) > 2:
            parts = lines[2].strip().split('\t')
            meta['experiment_description'] = parts[0].strip() if parts else ''
        meta['software'] = 'CorrWare for Windows'
        meta['date'] = self._kv(lines, 'Date') or ''
        meta['time'] = self._kv(lines, 'Time') or ''
        meta['ocp_V'] = self._floatish(self._kv(lines, 'Open Circuit Potential (V)'))
        meta['surface_area_cm2'] = self._floatish(self._kv(lines, 'Surface Area'))
        meta['scan_rate_mV_s'] = self._floatish(self._kv(lines, 'Scan Rate'))
        meta['n_cycles'] = self._intish(self._kv(lines, 'Scan Number'))
        meta['n_points_declared'] = self._intish(self._kv(lines, 'Data Points'))
        meta['potential_V'] = self._floatish(self._kv(lines, 'Potential:'))
        p2 = self._floatish(self._kv(lines, 'Potential #2:'))
        p3 = self._floatish(self._kv(lines, 'Potential #3:'))
        if p2 is not None:
            meta['vertex_start_V'] = p2
        if p3 is not None:
            meta['vertex_end_V'] = p3
        return meta

    def _parse_eis_header(self, lines):
        meta = {}
        meta['software'] = 'ZPlot'
        meta['experiment_type'] = self._kv(lines, 'Experiment Type') or ''
        meta['date'] = self._kv(lines, 'Date') or ''
        meta['time'] = self._kv(lines, 'Time') or ''
        meta['ocp_V'] = self._floatish(self._kv(lines, 'Open Circuit Potential (V)'))
        meta['dc_potential_V'] = self._floatish(self._kv(lines, 'Potential-DC:'))
        meta['ac_amplitude_V'] = self._floatish(self._kv(lines, 'Potential-AC:'))
        meta['freq_initial_Hz'] = self._floatish(self._kv(lines, 'vs Freq-Initial'))
        meta['freq_final_Hz'] = self._floatish(self._kv(lines, 'vs Freq-Final'))
        meta['n_points_declared'] = self._intish(self._kv(lines, 'Data Points'))
        return meta

    def _parse_text(self, text: str, source_path: str):
        self.text = text
        self.source_path = source_path
        suffix = Path(source_path.split('::')[-1]).suffix.lower()
        self.kind = 'z' if suffix == '.z' else 'cor'
        lines = text.splitlines()
        data_start, col_header = self._find_data_start(lines)
        if data_start is None:
            raise RuntimeError(f"No 'End Comments' marker found in {source_path}")
        header_lines = lines[:data_start]
        if self.kind == 'cor':
            meta = self._parse_cor_header(header_lines)
            rows = []
            for line in lines[data_start:]:
                s = line.strip()
                if not s:
                    continue
                try:
                    vals = [float(x) for x in self._split_numeric_line(s)]
                    if len(vals) >= 3:
                        rows.append(vals[:3])
                except Exception:
                    continue
            if not rows:
                raise RuntimeError(f"No numeric CorrWare data found in {source_path}")
            arr = np.asarray(rows, dtype=np.float64)
            title = meta.get('experiment_description', '')
            tech = self._infer_technique('cor', title, source_path, meta)
            meta.update({
                'format': 'CorrWare ASCII',
                'title_line': title,
                'technique': tech,
                'source_file': source_path,
                'filename': Path(source_path.split('::')[-1]).name,
                'stem': Path(source_path.split('::')[-1]).stem,
            })
            self.data = {'columns': list(self.COLS_COR), 'array': arr}
        else:
            meta = self._parse_eis_header(header_lines)
            rows = []
            for line in lines[data_start:]:
                s = line.strip()
                if not s:
                    continue
                try:
                    vals = [float(x) for x in self._split_numeric_line(s)]
                    if len(vals) >= 6:
                        rows.append(vals)
                except Exception:
                    continue
            if not rows:
                raise RuntimeError(f"No numeric ZPlot data found in {source_path}")
            raw = np.asarray(rows, dtype=np.float64)
            freq = raw[:, 0]
            ampl = raw[:, 1] if raw.shape[1] > 1 else np.zeros(len(raw))
            bias = raw[:, 2] if raw.shape[1] > 2 else np.zeros(len(raw))
            tsec = raw[:, 3] if raw.shape[1] > 3 else np.arange(len(raw), dtype=float)
            zre = raw[:, 4] if raw.shape[1] > 4 else np.zeros(len(raw))
            zim = raw[:, 5] if raw.shape[1] > 5 else np.zeros(len(raw))
            zabs = np.sqrt(zre ** 2 + zim ** 2)
            phase = np.degrees(np.arctan2(zim, zre))
            err = raw[:, 7] if raw.shape[1] > 7 else np.zeros(len(raw))
            rng = raw[:, 8] if raw.shape[1] > 8 else np.zeros(len(raw))
            arr = np.column_stack([freq, zre, zim, zabs, phase, ampl, bias, tsec, err, rng])
            arr = arr[np.argsort(arr[:, 0])]
            title = meta.get('experiment_type', '')
            tech = self._infer_technique('z', title, source_path, meta)
            meta.update({
                'format': 'ZPlot ASCII',
                'title_line': title,
                'technique': tech,
                'source_file': source_path,
                'filename': Path(source_path.split('::')[-1]).name,
                'stem': Path(source_path.split('::')[-1]).stem,
                'col_header_raw': col_header,
            })
            self.data = {'columns': list(self.COLS_EIS), 'array': arr}
        self.metadata = meta
        self.session = {'source_file': self.source_path, 'metadata': self.metadata, 'columns': self.data['columns']}

    def load(self, path: str):
        self._parse_text(Path(path).read_text(encoding='latin-1', errors='replace').replace('\r\n', '\n').replace('\r', '\n'), path)
        return self

    def load_from_bytes(self, data: bytes, source_path: str):
        self._parse_text(self._decode_bytes(data), source_path)
        return self

    def summarize(self) -> dict:
        if self.data is None:
            raise RuntimeError('No Solartron file loaded.')
        tech = self.metadata.get('technique', 'Unknown')
        arr = self.data['array']
        rows = [{
            'index': 0,
            'title': Path(self.source_path.split('::')[-1]).name,
            'method_id': tech,
            'technique': tech,
            'n_curves': 1 if tech != 'EIS' else 0,
            'n_eis_blocks': 1 if tech == 'EIS' else 0,
            'n_points': int(len(arr)),
            'columns': self.data['columns'],
        }]
        return {
            'source_file': self.source_path,
            'session_type': self.metadata.get('format'),
            'core_version': None,
            'n_measurements': 1,
            'measurement_title_counts': {tech: 1},
            'technique_counts': {tech: 1},
            'measurement_rows': rows,
        }

    def build_compact_summary(self) -> dict:
        if self.data is None:
            raise RuntimeError('No Solartron file loaded.')
        tech = self.metadata.get('technique', 'Unknown')
        arr = self.data['array']
        cols = self.data['columns']
        return {
            'source_file': self.source_path,
            'session_type': self.metadata.get('format'),
            'core_version': None,
            'n_measurements': 1,
            'technique_counts': {tech: 1},
            'measurement_rows': [{
                'index': 0,
                'title': Path(self.source_path.split('::')[-1]).name,
                'method_id': tech,
                'technique': tech,
                'n_curves': 1 if tech != 'EIS' else 0,
                'n_eis_blocks': 1 if tech == 'EIS' else 0,
                'n_points': int(len(arr)),
                'columns': cols,
                'scan_rate_mV_s': self._to_number_if_possible(self.metadata.get('scan_rate_mV_s')),
                'n_cycles_declared': self._to_number_if_possible(self.metadata.get('n_cycles')),
                'ocp_V': self._to_number_if_possible(self.metadata.get('ocp_V')),
                'data_points_declared': self._to_number_if_possible(self.metadata.get('n_points_declared')),
            }],
        }

    def session_minified_json(self) -> str:
        return json.dumps(self.session, ensure_ascii=False, separators=(',', ':'))

    def iter_primary_curve_exports(self):
        if self.data is None:
            raise RuntimeError('No Solartron file loaded.')
        arr = self.data['array']
        tech = self.metadata.get('technique', 'Unknown')
        cols = self.data['columns']
        exports = []

        if tech in {'CV', 'LSV', 'COND', 'Unknown'}:
            ix, iy = 0, 1
            title = tech if tech != 'Unknown' else 'Curve'
            n_cycles = self.metadata.get('n_cycles') if tech == 'CV' else None
            if tech == 'CV' and n_cycles and n_cycles > 1:
                cycles = self._split_cycles_cv(arr[:, :3], int(n_cycles))
                for ci, cyc in enumerate(cycles, start=1):
                    exports.append({
                        'measurement_index': 1,
                        'curve_index': ci,
                        'measurement_title': 'CV',
                        'curve_title': f'Cycle {ci}',
                        'method_id': 'CV',
                        'technique': 'CV',
                        'scan_rate': self.metadata.get('scan_rate_mV_s'),
                        'x_label': cols[ix],
                        'x_unit': 'V',
                        'y_label': cols[iy],
                        'y_unit': 'A/cm2',
                        'rows': list(zip(cyc[:, ix].tolist(), cyc[:, iy].tolist())),
                    })
            else:
                exports.append({
                    'measurement_index': 1,
                    'curve_index': 1,
                    'measurement_title': title,
                    'curve_title': title,
                    'method_id': tech,
                    'technique': tech,
                    'scan_rate': self.metadata.get('scan_rate_mV_s'),
                    'x_label': cols[ix],
                    'x_unit': 'V',
                    'y_label': cols[iy],
                    'y_unit': 'A/cm2',
                    'rows': list(zip(arr[:, ix].tolist(), arr[:, iy].tolist())),
                })
        elif tech in {'CA', 'CP', 'OCP', 'ZRA'}:
            ix = 2
            iy = 1 if tech == 'CA' else 0
            y_unit = 'A/cm2' if tech == 'CA' else 'V'
            exports.append({
                'measurement_index': 1,
                'curve_index': 1,
                'measurement_title': tech,
                'curve_title': tech,
                'method_id': tech,
                'technique': tech,
                'scan_rate': None,
                'x_label': cols[ix],
                'x_unit': 's',
                'y_label': cols[iy],
                'y_unit': y_unit,
                'rows': list(zip(arr[:, ix].tolist(), arr[:, iy].tolist())),
            })
        elif tech == 'EIS':
            freq, zre, zim, zabs, phase = 0, 1, 2, 3, 4
            exports.extend([
                {
                    'measurement_index': 1,
                    'curve_index': 1,
                    'measurement_title': 'EIS',
                    'curve_title': 'Nyquist',
                    'method_id': 'EIS',
                    'technique': 'EIS',
                    'scan_rate': None,
                    'x_label': cols[zre],
                    'x_unit': 'ohm',
                    'y_label': '-Zimag_ohm',
                    'y_unit': 'ohm',
                    'rows': list(zip(arr[:, zre].tolist(), (-arr[:, zim]).tolist())),
                },
                {
                    'measurement_index': 1,
                    'curve_index': 2,
                    'measurement_title': 'EIS',
                    'curve_title': 'Bode |Z|',
                    'method_id': 'EIS',
                    'technique': 'EIS',
                    'scan_rate': None,
                    'x_label': cols[freq],
                    'x_unit': 'Hz',
                    'y_label': cols[zabs],
                    'y_unit': 'ohm',
                    'rows': list(zip(arr[:, freq].tolist(), arr[:, zabs].tolist())),
                },
                {
                    'measurement_index': 1,
                    'curve_index': 3,
                    'measurement_title': 'EIS',
                    'curve_title': 'Bode phase',
                    'method_id': 'EIS',
                    'technique': 'EIS',
                    'scan_rate': None,
                    'x_label': cols[freq],
                    'x_unit': 'Hz',
                    'y_label': cols[phase],
                    'y_unit': 'deg',
                    'rows': list(zip(arr[:, freq].tolist(), arr[:, phase].tolist())),
                },
            ])
        return exports

    def primary_numeric_payload(self) -> dict:
        if self.data is None:
            raise RuntimeError('No Solartron file loaded.')
        arr = self.data['array']
        tech = self.metadata.get('technique', 'Unknown')
        payload = {
            'format': 'solartron-ascii-v2',
            'source_file': self.source_path,
            'kind': self.kind,
            'technique': tech,
            'metadata': self.metadata,
            'columns': self.data['columns'],
            'array': arr,
        }
        if tech == 'CV' and self.metadata.get('n_cycles') and self.metadata.get('n_cycles') > 1:
            payload['cycles'] = self._split_cycles_cv(arr[:, :3], int(self.metadata['n_cycles']))
        if tech == 'EIS' and arr.shape[1] >= 5:
            payload['eis'] = {
                'frequency_Hz': arr[:, 0],
                'z_real_ohm': arr[:, 1],
                'z_imag_ohm': arr[:, 2],
                'z_abs_ohm': arr[:, 3],
                'phase_deg': arr[:, 4],
            }
        return payload




class BioLogicParser:
    """Reader for BioLogic EC-Lab files (.mpr/.mps/.mgr).

    Uses embedded .mpr parsing adapted from galvani for native numeric extraction,
    while also reading .mps settings text and .mgr XML companions when present.
    """
    DECODE_ENCODINGS = ("utf-8-sig", "utf-8", "latin-1")
    TECHNIQUE_MAP = {
        'potentio electrochemical impedance spectroscopy': 'EIS',
        'galvano electrochemical impedance spectroscopy': 'GEIS',
        'cyclic voltammetry': 'CV',
        'linear sweep voltammetry': 'LSV',
        'constant voltage': 'CA',
        'chronoamperometry': 'CA',
        'constant current': 'CP',
        'chronopotentiometry': 'CP',
        'open circuit voltage': 'OCP',
        'zra': 'ZRA',
    }

    def __init__(self):
        self.source_path = None
        self.primary_path = None
        self.mpr_path = None
        self.mps_path = None
        self.mgr_path = None
        self.mpr_bytes = None
        self.mps_text = None
        self.mgr_text = None
        self.metadata = {}
        self.techniques = []
        self.session = None
        self.mpr_numeric = None

    @classmethod
    def _decode_bytes(cls, data: bytes) -> str:
        last_error = None
        for enc in cls.DECODE_ENCODINGS:
            try:
                return data.decode(enc, errors='replace').replace("\r\n", "\n").replace("\r", "\n")
            except Exception as exc:
                last_error = exc
        raise RuntimeError(f'Could not decode BioLogic text bytes: {last_error}')

    @staticmethod
    def _normalize_mps_name(name: str) -> str:
        base = Path(name).stem
        base = re.sub(r'^VMP\d+\s*-\s*[\d\.]+_', '', base, flags=re.I)
        return base

    @staticmethod
    def _norm_key(name: str) -> str:
        p = Path(name)
        stem = p.stem
        if p.suffix.lower() == '.mps':
            stem = BioLogicParser._normalize_mps_name(p.name)
        return stem.lower()

    @classmethod
    def _pair_from_directory(cls, path: str):
        p = Path(path)
        folder = p.parent
        key = cls._norm_key(p.name)
        matches = {'mpr': None, 'mps': None, 'mgr': None}
        for q in folder.iterdir():
            if not q.is_file():
                continue
            suf = q.suffix.lower()
            if suf not in {'.mpr', '.mps', '.mgr'}:
                continue
            if cls._norm_key(q.name) != key:
                continue
            matches[suf[1:]] = q
        return matches

    @classmethod
    def _pair_from_zip(cls, zf, raw_name: str):
        base_dir = str(PurePosixPath(raw_name).parent)
        key = cls._norm_key(PurePosixPath(raw_name).name)
        matches = {'mpr': None, 'mps': None, 'mgr': None}
        for n in zf.namelist():
            pp = PurePosixPath(n)
            if str(pp.parent) != base_dir:
                continue
            suf = pp.suffix.lower()
            if suf not in {'.mpr', '.mps', '.mgr'}:
                continue
            if cls._norm_key(pp.name) != key:
                continue
            matches[suf[1:]] = n
        return matches

    @classmethod
    def _canonical_technique(cls, name: str) -> str:
        low = (name or '').strip().lower()
        for k, v in cls.TECHNIQUE_MAP.items():
            if k in low:
                return v
        if 'impedance' in low:
            return 'EIS'
        if 'voltammetry' in low and 'cyclic' in low:
            return 'CV'
        return (name or 'Unknown').strip() or 'Unknown'

    def _parse_mps(self, text: str):
        self.mps_text = text
        meta = {}
        techniques = []
        lines = text.split('\n')
        i = 0
        current = None
        while i < len(lines):
            stripped = lines[i].strip().lstrip('\ufeff')
            if not stripped:
                i += 1
                continue
            if ':' in stripped and not stripped.startswith('Technique :'):
                k, v = stripped.split(':', 1)
                if k.strip() in {
                    'Number of linked techniques', 'Filename', 'Device', 'Electrode connection',
                    'Electrolyte', 'Comments', 'Electrode surface area', 'Cycle Definition'
                }:
                    meta[k.strip()] = v.strip()
            if stripped.startswith('Technique :'):
                if current:
                    techniques.append(current)
                seq = stripped.split(':', 1)[1].strip()
                title = lines[i + 1].strip() if i + 1 < len(lines) else 'Unknown'
                current = {
                    'sequence_index': int(float(seq)) if seq.replace('.', '', 1).isdigit() else len(techniques) + 1,
                    'method_id': title,
                    'title': title,
                    'technique': self._canonical_technique(title),
                    'params': {},
                    'curves': 0,
                }
                i += 2
                continue
            if current is not None:
                parts = re.split(r'\s{2,}|\t+', stripped)
                if len(parts) >= 2:
                    key = parts[0].strip()
                    val = ' '.join(parts[1:]).strip()
                    if key:
                        current['params'][key] = val
            i += 1
        if current:
            techniques.append(current)
        meta['n_linked_techniques'] = len(techniques)
        self.metadata.update(meta)
        self.techniques = techniques

    def _parse_mgr(self, text: str):
        self.mgr_text = text

    @staticmethod
    def _first_col(names, *cands):
        for c in cands:
            if c in names:
                return c
        return None

    @staticmethod
    def _technique_from_name(name: str) -> str:
        low = (name or '').lower()
        if 'peis' in low or 'geis' in low or 'eis' in low:
            return 'EIS'
        if 'cv' in low:
            return 'CV'
        if 'lsv' in low:
            return 'LSV'
        if 'cstv' in low or 'ca' in low:
            return 'CA'
        if 'cstc' in low or 'cp' in low:
            return 'CP'
        if 'ocv' in low:
            return 'OCP'
        if 'zra' in low:
            return 'ZRA'
        return 'Unknown'

    def _parse_mpr_numeric(self, data: bytes, basename: str):
        self.mpr_bytes = data
        self.metadata['mpr_size_bytes'] = len(data)
        self.metadata['has_mpr'] = True
        self.metadata['mpr_header'] = data[:64].decode('latin-1', errors='replace').strip('\\x00')
        strings = re.findall(rb'[ -~]{4,}', data[:8192])
        modules = []
        for s in strings:
            txt = s.decode('latin-1', errors='replace')
            if txt.startswith('MODULE'):
                modules.append(txt.strip())
        if modules:
            self.metadata['modules'] = modules[:20]
        try:
            mpr = MPRfile(BytesIO(data), error_on_unknown_column=False)
        except Exception as exc:
            self.metadata['mpr_parse_error'] = str(exc)
            self.mpr_numeric = None
            return
        arr = mpr.data
        names = list(arr.dtype.names or [])
        self.metadata['mpr_columns'] = names
        self.metadata['mpr_npts'] = int(len(arr))
        self.metadata['mpr_version'] = int(getattr(mpr, 'version', -1))
        inferred = self._technique_from_name(basename)
        if 'freq/Hz' in names and self._first_col(names, 'Re(Z)/Ohm', 'Re(Z)/Ohm.cm2'):
            inferred = 'EIS'
        elif inferred == 'Unknown' and self._first_col(names, 'cycle number'):
            inferred = 'CV'
        elif inferred == 'Unknown' and self._first_col(names, 'control/V') and self._first_col(names, '<I>/mA', 'I/mA'):
            inferred = 'CA'
        elif inferred == 'Unknown' and self._first_col(names, 'control/mA', 'control/I') and self._first_col(names, 'Ewe/V', '<Ewe>/V'):
            inferred = 'CP'
        elif inferred == 'Unknown' and self._first_col(names, 'time/s') and self._first_col(names, 'Ewe/V', '<Ewe>/V'):
            inferred = 'OCP'

        numeric = {'format': 'biologic-native-v1', 'technique': inferred, 'columns': names}
        rows = []
        if inferred == 'EIS':
            fcol = self._first_col(names, 'freq/Hz')
            zrcol = self._first_col(names, 'Re(Z)/Ohm', 'Re(Z)/Ohm.cm2')
            zicol = self._first_col(names, '-Im(Z)/Ohm', '-Im(Z)/Ohm.cm2', 'Im(Z)/Ohm', 'Im(Z)/Ohm.cm2')
            zabscol = self._first_col(names, '|Z|/Ohm', '|Z|/Ohm.cm2')
            phcol = self._first_col(names, 'Phase(Z)/deg')
            if fcol and zrcol and zicol:
                freq = np.asarray(arr[fcol], dtype=float)
                zreal = np.asarray(arr[zrcol], dtype=float)
                zimag_raw = np.asarray(arr[zicol], dtype=float)
                zimag = -zimag_raw if zicol.startswith('-Im(') else zimag_raw
                eis = {'freq_Hz': freq, 'Zreal_ohm': zreal, 'Zimag_ohm': zimag}
                if zabscol:
                    eis['Zabs_ohm'] = np.asarray(arr[zabscol], dtype=float)
                if phcol:
                    eis['phase_deg'] = np.asarray(arr[phcol], dtype=float)
                numeric['eis'] = eis
                rows.append({'sequence_index': 1, 'method_id': 'EIS', 'title': 'BioLogic EIS', 'technique': 'EIS', 'params': {}, 'curves': 3 if phcol or zabscol else 1})
        else:
            tcol = self._first_col(names, 'time/s')
            ecol = self._first_col(names, 'Ewe/V', '<Ewe>/V')
            icol = self._first_col(names, '<I>/mA', 'I/mA', '/mA', 'I/A')
            cyc = self._first_col(names, 'cycle number')
            segments = {}
            if ecol and icol:
                e = np.asarray(arr[ecol], dtype=float)
                iA = np.asarray(arr[icol], dtype=float)
                if '/mA' in icol or icol.endswith('mA'):
                    iA = iA * 1e-3
                time_s = np.asarray(arr[tcol], dtype=float) if tcol else np.arange(len(arr), dtype=float)
                if inferred in ('CV', 'LSV'):
                    if cyc:
                        cyc_arr = np.asarray(arr[cyc]).astype(float)
                        finite = cyc_arr[np.isfinite(cyc_arr)]
                        uniq = sorted({int(round(v)) for v in finite}) or [1]
                        for c in uniq:
                            mask = np.isfinite(cyc_arr) & (np.round(cyc_arr).astype(int) == c)
                            if not np.any(mask):
                                continue
                            seg = np.column_stack([e[mask], iA[mask], time_s[mask]])
                            segments[f'cycle_{c:03d}'] = {'technique': inferred, 'array': seg, 'columns': ['E_V', 'I_A', 'time_s']}
                    else:
                        seg = np.column_stack([e, iA, time_s])
                        segments['curve_001'] = {'technique': inferred, 'array': seg, 'columns': ['E_V', 'I_A', 'time_s']}
                elif inferred in ('CA', 'CP', 'OCP', 'ZRA'):
                    y = iA if inferred in ('CA', 'ZRA') else e
                    x = time_s
                    ylab = 'I_A' if inferred in ('CA', 'ZRA') else 'E_V'
                    seg = np.column_stack([x, y])
                    segments['curve_001'] = {'technique': inferred, 'array': seg, 'columns': ['time_s', ylab]}
                else:
                    seg = np.column_stack([e, iA, time_s])
                    segments['curve_001'] = {'technique': 'Unknown', 'array': seg, 'columns': ['E_V', 'I_A', 'time_s']}
            elif tcol and ecol:
                time_s = np.asarray(arr[tcol], dtype=float)
                e = np.asarray(arr[ecol], dtype=float)
                seg = np.column_stack([time_s, e])
                segments['curve_001'] = {'technique': inferred if inferred != 'Unknown' else 'OCP', 'array': seg, 'columns': ['time_s', 'E_V']}
            numeric['segments'] = segments
            rows.append({'sequence_index': 1, 'method_id': inferred, 'title': inferred, 'technique': inferred, 'params': {}, 'curves': len(segments)})
        self.mpr_numeric = numeric
        self.metadata['mpr_inferred_technique'] = inferred
        self.metadata['mpr_native_data_present'] = bool(numeric.get('segments') or numeric.get('eis'))
        if rows:
            if not self.techniques:
                self.techniques = rows
            else:
                techmap = {(t.get('technique'), t.get('method_id')) for t in self.techniques}
                for r in rows:
                    key = (r.get('technique'), r.get('method_id'))
                    if key not in techmap:
                        self.techniques.append(r)

    def load(self, path: str):
        self.source_path = path
        pairs = self._pair_from_directory(path)
        self.primary_path = path
        if pairs['mpr']:
            self.mpr_path = str(pairs['mpr'])
            self._parse_mpr_numeric(Path(self.mpr_path).read_bytes(), Path(self.mpr_path).name)
        if pairs['mps']:
            self.mps_path = str(pairs['mps'])
            self._parse_mps(self._decode_bytes(Path(self.mps_path).read_bytes()))
        if pairs['mgr']:
            self.mgr_path = str(pairs['mgr'])
            self._parse_mgr(self._decode_bytes(Path(self.mgr_path).read_bytes()))
        if not any([self.mpr_path, self.mps_path, self.mgr_path]):
            raise RuntimeError(f'Could not locate BioLogic companion files for {path}')
        self._finalize_session()
        return self.session

    def load_from_zip(self, zf, raw_name: str, zip_path: str):
        self.source_path = f'{zip_path}::{raw_name}'
        pairs = self._pair_from_zip(zf, raw_name)
        self.primary_path = self.source_path
        if pairs['mpr']:
            self.mpr_path = f'{zip_path}::{pairs["mpr"]}'
            self._parse_mpr_numeric(zf.read(pairs['mpr']), PurePosixPath(pairs['mpr']).name)
        if pairs['mps']:
            self.mps_path = f'{zip_path}::{pairs["mps"]}'
            self._parse_mps(self._decode_bytes(zf.read(pairs['mps'])))
        if pairs['mgr']:
            self.mgr_path = f'{zip_path}::{pairs["mgr"]}'
            self._parse_mgr(self._decode_bytes(zf.read(pairs['mgr'])))
        if not any([self.mpr_path, self.mps_path, self.mgr_path]):
            raise RuntimeError(f'Could not locate BioLogic companion files for {raw_name}')
        self._finalize_session()
        return self.session

    def _finalize_session(self):
        basename = Path(self.primary_path.split('::')[-1]).name
        if not self.techniques and self.mpr_path:
            inferred = self.metadata.get('mpr_inferred_technique') or self._technique_from_name(basename)
            curves = 0
            if self.mpr_numeric:
                curves = len(self.mpr_numeric.get('segments', {})) or (1 if self.mpr_numeric.get('eis') else 0)
            self.techniques = [{'sequence_index': 1, 'method_id': inferred, 'title': inferred, 'technique': inferred, 'params': {}, 'curves': curves}]
        self.session = {
            'source_file': self.source_path,
            'format': 'biologic-ec-lab-v2',
            'metadata': self.metadata,
            'techniques': self.techniques,
            'companions': {'mpr': self.mpr_path, 'mps': self.mps_path, 'mgr': self.mgr_path},
        }

    def summarize(self) -> dict:
        technique_counts = Counter(t.get('technique') or 'Unknown' for t in self.techniques)
        rows = [
            {
                'measurement_index': int(t.get('sequence_index', i + 1)),
                'title': t.get('title'),
                'method_id': t.get('method_id'),
                'technique': t.get('technique'),
                'curves': int(t.get('curves', 0)),
                'params': t.get('params', {}),
            }
            for i, t in enumerate(self.techniques)
        ]
        return {
            'source_file': self.source_path,
            'file_type': 'biologic',
            'instrument': self.metadata.get('Device', 'BioLogic EC-Lab'),
            'n_measurements': len(rows),
            'technique_counts': dict(technique_counts),
            'measurement_rows': rows,
            'has_mpr': bool(self.mpr_path),
            'has_mps': bool(self.mps_path),
            'has_mgr': bool(self.mgr_path),
            'mpr_native_data_present': bool(self.mpr_numeric and (self.mpr_numeric.get('segments') or self.mpr_numeric.get('eis'))),
        }

    def build_compact_summary(self) -> dict:
        s = self.summarize()
        return {
            'source_file': s['source_file'],
            'file_type': s['file_type'],
            'instrument': s['instrument'],
            'n_measurements': s['n_measurements'],
            'technique_counts': s['technique_counts'],
            'measurement_rows': s['measurement_rows'],
            'has_mpr': s['has_mpr'],
            'has_mps': s['has_mps'],
            'has_mgr': s['has_mgr'],
            'mpr_native_data_present': s['mpr_native_data_present'],
        }

    def session_minified_json(self) -> str:
        return json.dumps(self.session, ensure_ascii=False, separators=(',', ':'))

    def iter_primary_curve_exports(self):
        if not self.mpr_numeric:
            return []
        out = []
        tech = self.mpr_numeric.get('technique', 'Unknown')
        if self.mpr_numeric.get('segments'):
            for idx, (key, seg) in enumerate(self.mpr_numeric['segments'].items(), start=1):
                arr = np.asarray(seg['array'])
                cols = seg.get('columns', [])
                if arr.ndim != 2 or arr.shape[1] < 2:
                    continue
                if cols[:2] == ['E_V', 'I_A']:
                    rows = [(float(x), float(y)) for x, y in arr[:, :2]]
                    xlab, xunit, ylab, yunit = 'Potential', 'V', 'Current', 'A'
                elif cols[:2] == ['time_s', 'I_A']:
                    rows = [(float(x), float(y)) for x, y in arr[:, :2]]
                    xlab, xunit, ylab, yunit = 'Time', 's', 'Current', 'A'
                else:
                    rows = [(float(x), float(y)) for x, y in arr[:, :2]]
                    xlab, xunit, ylab, yunit = 'Time', 's', 'Potential', 'V'
                out.append({
                    'measurement_index': 1,
                    'curve_index': idx,
                    'measurement_title': tech,
                    'curve_title': key,
                    'method_id': tech,
                    'technique': tech,
                    'scan_rate': None,
                    'x_label': xlab,
                    'x_unit': xunit,
                    'y_label': ylab,
                    'y_unit': yunit,
                    'rows': rows,
                })
        eis = self.mpr_numeric.get('eis')
        if eis:
            zreal = np.asarray(eis['Zreal_ohm'])
            zimag = np.asarray(eis['Zimag_ohm'])
            out.append({'measurement_index': 1, 'curve_index': 1, 'measurement_title': 'EIS', 'curve_title': 'Nyquist', 'method_id': 'EIS', 'technique': 'EIS', 'scan_rate': None, 'x_label': 'Zreal', 'x_unit': 'Ohm', 'y_label': '-Zimag', 'y_unit': 'Ohm', 'rows': [(float(x), float(-y)) for x, y in zip(zreal, zimag)]})
            if 'Zabs_ohm' in eis:
                out.append({'measurement_index': 1, 'curve_index': 2, 'measurement_title': 'EIS', 'curve_title': 'Bode |Z|', 'method_id': 'EIS', 'technique': 'EIS', 'scan_rate': None, 'x_label': 'Frequency', 'x_unit': 'Hz', 'y_label': '|Z|', 'y_unit': 'Ohm', 'rows': [(float(x), float(y)) for x, y in zip(eis['freq_Hz'], eis['Zabs_ohm'])]})
            if 'phase_deg' in eis:
                out.append({'measurement_index': 1, 'curve_index': 3, 'measurement_title': 'EIS', 'curve_title': 'Bode phase', 'method_id': 'EIS', 'technique': 'EIS', 'scan_rate': None, 'x_label': 'Frequency', 'x_unit': 'Hz', 'y_label': 'Phase', 'y_unit': 'deg', 'rows': [(float(x), float(y)) for x, y in zip(eis['freq_Hz'], eis['phase_deg'])]})
        return out

    def primary_numeric_payload(self) -> dict:
        payload = {
            'format': 'biologic-native-bundle-v3',
            'source_file': self.source_path,
            'binary_data_file': self.mpr_path,
            'settings_file': self.mps_path,
            'graph_file': self.mgr_path,
            'metadata': self.metadata,
            'techniques': self.techniques,
            'source_artifacts': {},
        }
        if self.mpr_numeric is not None:
            payload['native_data'] = self.mpr_numeric
        if self.mpr_bytes is not None:
            payload['source_artifacts']['mpr_bytes'] = self.mpr_bytes
        if self.mps_text is not None:
            payload['source_artifacts']['mps_text'] = self.mps_text
        if self.mgr_text is not None:
            payload['source_artifacts']['mgr_xml_text'] = self.mgr_text
        return payload

# ---- HEKA POTMASTER / PATCHMASTER DAT2 parser and splitter ----
import bisect as _heka_bisect
import struct as _heka_struct
from dataclasses import dataclass as _heka_dataclass, field as _heka_field
from typing import Optional as _HekaOptional, Sequence as _HekaSequence, Dict as _HekaDict, List as _HekaList, Iterable as _HekaIterable, Tuple as _HekaTuple

HEKA_HEADER_SIZE = 256
HEKA_TABLE_OFFSET = 64
HEKA_TABLE_ENTRIES = 10
HEKA_COPY_BUFFER_SIZE = 64 * 1024 * 1024
HEKA_MAX_U32 = 0xFFFFFFFF
HEKA_DEFAULT_BYTES_PER_POINT = 4
HEKA_TRACE_LABEL_OFFSET = 12
HEKA_TRACE_KIND_OFFSET = 44
HEKA_TRACE_DATA_OFFSET = 48
HEKA_TRACE_NPOINTS_OFFSET = 52

HEKA_BUNDLE_INDEX_BY_EXT = {
    ".dat": 0,
    ".pul": 1,
    ".pgf": 2,
    ".amp": 3,
    ".mrk": 7,
    ".mth": 8,
    ".onl": 9,
}
HEKA_PHYSICAL_WRITE_ORDER = [".dat", ".pul", ".pgf", ".amp", ".onl", ".mrk", ".mth"]
HEKA_SUPPORT_EXTS = set(HEKA_BUNDLE_INDEX_BY_EXT)
HEKA_DEFAULT_EIS_SEQUENCE = [
    "Imon-2", "Emon-2", "Real(Y)_1", "Imag(Y)_1", "Admit(Y)_1",
    "Phase_1", "Real(Z)_1", "Imag(Z)_1", "Imp|Z|_1",
]
HEKA_EIS_LABEL_RE = re.compile(r"(Real\(Z\)|Imag\(Z\)|Imp\|Z\||\|Z\||Phase|Real\(Y\)|Imag\(Y\)|Admit\(Y\)|\|Y\|)", re.I)
HEKA_CURRENT_LABEL_RE = re.compile(r"(^I|Imon|Current)", re.I)
HEKA_POTENTIAL_LABEL_RE = re.compile(r"(^E|Emon|Volt|Potential)", re.I)
HEKA_KNOWN_TRACE_LABELS = sorted(set(HEKA_DEFAULT_EIS_SEQUENCE + [
    "Imon-1", "Emon-1", "Imon-2", "Emon-2", "Imon-3", "Emon-3", "Imon-4", "Emon-4",
    "Real(Z)_1", "Imag(Z)_1", "Imp|Z|_1", "Phase_1", "Real(Y)_1", "Imag(Y)_1", "Admit(Y)_1",
    "Real(Z)_2", "Imag(Z)_2", "Imp|Z|_2", "Phase_2", "Real(Y)_2", "Imag(Y)_2", "Admit(Y)_2",
    "Vm", "Im", "E", "I", "Current", "Potential", "Voltage"
]))


@_heka_dataclass
class HekaSection:
    ext: str
    offset: int
    length: int
    @property
    def end(self) -> int:
        return self.offset + self.length


@_heka_dataclass
class HekaTraceRec:
    tree_index: int
    rec_offset: int
    label: str
    kind: int
    old_offset: int
    n_points: int
    nbytes: int
    data_offset_mode: str = "unknown"   # bundle_absolute, dat_relative, raw_absolute, unknown
    eis_group_index: _HekaOptional[int] = None
    block_index0: _HekaOptional[int] = None
    @property
    def old_end(self) -> int:
        return self.old_offset + self.nbytes


@_heka_dataclass
class HekaEISGroup:
    group_index: int
    start_tree_index: int
    trace_indices: _HekaList[int]
    block_index0: _HekaOptional[int] = None


@_heka_dataclass
class HekaBlock:
    block_index0: int
    prelude_trace_indices: _HekaList[int]
    eis_group_indices: _HekaList[int]
    trace_indices: _HekaList[int] = _heka_field(default_factory=list)
    status: str = ""


def _heka_u32_at(buf: bytes | bytearray, offset: int) -> int:
    return _heka_struct.unpack_from("<I", buf, offset)[0]


def _heka_put_u32(buf: bytearray, offset: int, value: int) -> None:
    if value < 0 or value > HEKA_MAX_U32:
        raise ValueError(f"Value out of uint32 range: {value}")
    _heka_struct.pack_into("<I", buf, offset, value)


def _heka_human_bytes(n: int) -> str:
    units = ["B", "KiB", "MiB", "GiB", "TiB"]
    x = float(n)
    for u in units:
        if abs(x) < 1024.0 or u == units[-1]:
            return f"{x:.2f} {u}" if u != "B" else f"{int(x)} B"
        x /= 1024.0
    return f"{n} B"


def _heka_parse_numeric_with_unit(text: str) -> float | None:
    """Parse HEKA method values such as 24.000kHz, 10.000mV, or 1.5V."""
    if text is None:
        return None
    m = re.search(r"([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)(?:\s*)([A-Za-zµμ/Ω%]*)", str(text).strip())
    if not m:
        return None
    try:
        value = float(m.group(1))
    except Exception:
        return None
    unit = (m.group(2) or "").replace("μ", "µ")
    unit_l = unit.lower()
    if unit_l.startswith("khz"):
        value *= 1e3
    elif unit_l.startswith("mhz"):
        value *= 1e6
    elif unit_l.startswith("ghz"):
        value *= 1e9
    elif unit_l.startswith("mv"):
        value *= 1e-3
    elif unit_l.startswith("uv") or unit_l.startswith("µv"):
        value *= 1e-6
    elif unit_l.startswith("ma"):
        value *= 1e-3
    elif unit_l.startswith("ua") or unit_l.startswith("µa"):
        value *= 1e-6
    elif unit_l.startswith("na"):
        value *= 1e-9
    elif unit_l.startswith("pa"):
        value *= 1e-12
    return value


def _heka_format_range(lo, hi, unit: str = "", digits: int = 4) -> str:
    if lo in (None, "") or hi in (None, ""):
        return ""
    try:
        lo_f = float(lo); hi_f = float(hi)
    except Exception:
        return ""
    if not (np.isfinite(lo_f) and np.isfinite(hi_f)):
        return ""
    if lo_f == hi_f:
        return f"{lo_f:.{digits}g}{unit}"
    return f"{lo_f:.{digits}g} to {hi_f:.{digits}g}{unit}"


def _heka_format_scalar(value, unit: str = "", digits: int = 4) -> str:
    if value in (None, ""):
        return ""
    try:
        v = float(value)
    except Exception:
        return str(value)
    if not np.isfinite(v):
        return ""
    return f"{v:.{digits}g}{unit}"


def _heka_printable_runs(data: bytes, min_len: int = 8) -> _HekaList[str]:
    """Return printable ASCII-ish strings from binary HEKA support sections."""
    runs = []
    cur = bytearray()
    for b in data:
        if b in (9, 10, 13) or 32 <= b <= 126:
            cur.append(b)
        else:
            if len(cur) >= min_len:
                runs.append(cur.decode("latin-1", errors="ignore"))
            cur = bytearray()
    if len(cur) >= min_len:
        runs.append(cur.decode("latin-1", errors="ignore"))
    return runs


def _heka_cstring_at(buf: bytes | bytearray, offset: int, max_len: int = 64) -> str:
    raw = bytes(buf[offset:offset + max_len]).split(b"\x00", 1)[0]
    return raw.decode("latin-1", errors="ignore")


def _heka_is_printable_label(label: str) -> bool:
    if not label:
        return False
    if len(label) > 48:
        return False
    # Keep common HEKA labels including symbols, but reject path-like/text paragraphs.
    printable = sum(1 for ch in label if ch.isprintable() and ch not in "\r\n\t")
    if printable != len(label):
        return False
    if label.count(" ") > 4:
        return False
    if any(ord(ch) < 32 for ch in label):
        return False
    return True


def _heka_find_bundle_sections_from_header(header: bytes) -> _HekaDict[str, HekaSection]:
    if len(header) < HEKA_HEADER_SIZE or header[:4] != b"DAT2":
        raise ValueError("Not a bundled HEKA DAT2 file.")
    sections: _HekaDict[str, HekaSection] = {}
    for i in range(HEKA_TABLE_ENTRIES):
        entry_off = HEKA_TABLE_OFFSET + i * 16
        offset, length, ext_raw = _heka_struct.unpack_from("<II8s", header, entry_off)
        ext = ext_raw.split(b"\x00", 1)[0].decode("ascii", errors="ignore")
        if ext and length:
            sections[ext] = HekaSection(ext, int(offset), int(length))
    return sections


def _heka_parse_bundle_header(path: Path) -> tuple[bytes, _HekaDict[str, HekaSection]]:
    with Path(path).open("rb") as f:
        header = f.read(HEKA_HEADER_SIZE)
    sections = _heka_find_bundle_sections_from_header(header)
    if ".dat" not in sections:
        raise ValueError("HEKA DAT2 bundle is missing the required .dat section.")
    return header, sections


def _heka_read_section(path: Path, section: HekaSection) -> bytes:
    with Path(path).open("rb") as f:
        f.seek(section.offset)
        data = f.read(section.length)
    if len(data) != section.length:
        raise IOError(f"Could not read complete {section.ext} section from {path}")
    return data


def _heka_write_csv(path: Path, rows: _HekaList[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not rows:
        path.write_text("", encoding="utf-8")
        return
    fieldnames = list(rows[0].keys())
    extra = sorted(set().union(*(r.keys() for r in rows)) - set(fieldnames))
    fieldnames.extend(extra)
    with path.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fieldnames)
        w.writeheader()
        w.writerows(rows)


def _heka_merge_intervals(intervals: _HekaIterable[_HekaTuple[int, int]]) -> _HekaList[_HekaTuple[int, int]]:
    sorted_intervals = sorted((int(a), int(b)) for a, b in intervals if b > a)
    merged: _HekaList[_HekaList[int]] = []
    for a, b in sorted_intervals:
        if not merged or a > merged[-1][1]:
            merged.append([a, b])
        elif b > merged[-1][1]:
            merged[-1][1] = b
    return [(a, b) for a, b in merged]


def _heka_total_interval_bytes(intervals: _HekaIterable[_HekaTuple[int, int]]) -> int:
    return sum(b - a for a, b in intervals)


def _heka_build_header(original_header: bytes, sections: _HekaDict[str, _HekaTuple[int, int]]) -> bytes:
    header = bytearray(HEKA_HEADER_SIZE)
    header[:4] = b"DAT2"
    if original_header and len(original_header) >= HEKA_HEADER_SIZE:
        header[4:64] = original_header[4:64]
    _heka_struct.pack_into("<I", header, 48, HEKA_TABLE_ENTRIES)
    if _heka_u32_at(header, 56) == 0:
        _heka_struct.pack_into("<I", header, 56, 1000)
    for ext, (offset, length) in sections.items():
        idx = HEKA_BUNDLE_INDEX_BY_EXT.get(ext)
        if idx is None:
            continue
        entry_off = HEKA_TABLE_OFFSET + idx * 16
        _heka_struct.pack_into("<II8s", header, entry_off, int(offset), int(length), ext.encode("ascii")[:8].ljust(8, b"\x00"))
    return bytes(header)


def _heka_copy_range(src_path: Path, dst_handle, start: int, nbytes: int) -> None:
    with Path(src_path).open("rb") as src:
        src.seek(start)
        remaining = nbytes
        while remaining:
            chunk = src.read(min(HEKA_COPY_BUFFER_SIZE, remaining))
            if not chunk:
                raise IOError(f"Unexpected EOF while copying from offset {start}")
            dst_handle.write(chunk)
            remaining -= len(chunk)


def _heka_copy_section(src_path: Path, dst_handle, section: HekaSection) -> None:
    _heka_copy_range(src_path, dst_handle, section.offset, section.length)


class HEKAPotmasterParser:
    """Native HEKA POTMASTER/PATCHMASTER DAT2 reader and size-limited splitter.

    The parser is deliberately sequence-flexible: it first extracts every plausible
    trace record from the .pul tree, then detects known EIS online impedance
    channel groups, CV-like current/potential pairs, and line-scan/measurement
    blocks from repeated prelude + sweep patterns.  It works with either a normal
    bundled HEKA DAT2 .dat file or loose support files (.dat + .pul + .pgf/.amp/etc.).
    """

    def __init__(self):
        self.source_path: _HekaOptional[str] = None
        self.bundle_path: _HekaOptional[Path] = None
        self.loose_base: _HekaOptional[Path] = None
        self.mode: str = "unknown"  # bundle, loose, bytes_bundle
        self.header: bytes = b""
        self.sections: _HekaDict[str, HekaSection] = {}
        self.section_bytes: _HekaDict[str, bytes] = {}
        self.support_paths: _HekaDict[str, Path] = {}
        self.pul: bytes = b""
        self.dat_payload_path: _HekaOptional[Path] = None
        self.dat_payload_offset: int = 0
        self.dat_payload_length: int = 0
        self.bytes_per_point: int = HEKA_DEFAULT_BYTES_PER_POINT
        self.traces: _HekaList[HekaTraceRec] = []
        self.eis_groups: _HekaList[HekaEISGroup] = []
        self.blocks: _HekaList[HekaBlock] = []
        self.cv_pairs: _HekaList[dict] = []
        self.method_entries: _HekaList[dict] = []
        self.detail_summary: dict = {}
        self.metadata: dict = {}
        self.notes: _HekaList[str] = []
        self.session: dict = {}

    @staticmethod
    def can_open_path(path: str | Path) -> bool:
        p = Path(path)
        suf = p.suffix.lower()
        if suf not in HEKA_SUPPORT_EXTS:
            return False
        if suf == ".dat":
            try:
                with p.open("rb") as f:
                    head = f.read(4)
                if head == b"DAT2":
                    return True
            except Exception:
                return False
            return (p.with_suffix(".pul").exists() or p.with_suffix(".pgf").exists() or p.with_suffix(".amp").exists())
        return True

    @staticmethod
    def _siblings_for(path: Path) -> _HekaDict[str, Path]:
        base = path.with_suffix("")
        out = {}
        for ext in HEKA_SUPPORT_EXTS:
            q = base.with_suffix(ext)
            if q.exists() and q.is_file():
                out[ext] = q
        return out

    @staticmethod
    def _is_bundle_bytes(data: bytes) -> bool:
        return len(data) >= HEKA_HEADER_SIZE and data[:4] == b"DAT2"

    def load(self, path: str):
        self.__init__()
        self.source_path = path
        p = Path(path)
        if p.suffix.lower() == ".dat":
            with p.open("rb") as f:
                head = f.read(4)
            if head == b"DAT2":
                self._load_bundle_path(p)
            else:
                self._load_loose_set(p)
        elif p.suffix.lower() in HEKA_SUPPORT_EXTS:
            self._load_loose_set(p)
        else:
            raise ValueError(f"Unsupported HEKA input extension: {p.suffix}")
        self._analyze()
        return self

    def load_from_bytes(self, data: bytes, source_path: str):
        self.__init__()
        self.source_path = source_path
        if not self._is_bundle_bytes(data):
            raise ValueError("ZIP HEKA loading currently requires a bundled DAT2 .dat entry; loose support-file ZIP groups should be extracted first.")
        self.mode = "bytes_bundle"
        self.header = data[:HEKA_HEADER_SIZE]
        self.sections = _heka_find_bundle_sections_from_header(self.header)
        self.section_bytes = {}
        for ext, sec in self.sections.items():
            self.section_bytes[ext] = data[sec.offset:sec.end]
        self.pul = self.section_bytes.get(".pul", b"")
        dat_sec = self.sections.get(".dat")
        if dat_sec:
            self.dat_payload_offset = dat_sec.offset
            self.dat_payload_length = dat_sec.length
        self.metadata["source_file"] = source_path
        self.metadata["mode"] = self.mode
        self._analyze()
        return self

    def _load_bundle_path(self, p: Path):
        self.mode = "bundle"
        self.bundle_path = p
        self.header, self.sections = _heka_parse_bundle_header(p)
        if ".pul" not in self.sections:
            raise ValueError("Bundled HEKA file has no .pul section; cannot locate trace metadata.")
        self.pul = _heka_read_section(p, self.sections[".pul"])
        dat_sec = self.sections[".dat"]
        self.dat_payload_path = p
        self.dat_payload_offset = dat_sec.offset
        self.dat_payload_length = dat_sec.length
        self.metadata["source_file"] = str(p)
        self.metadata["mode"] = self.mode
        self.metadata["bundle_file_size_bytes"] = p.stat().st_size
        self.metadata["sections"] = {ext: {"offset": s.offset, "length": s.length, "end": s.end} for ext, s in self.sections.items()}

    def _load_loose_set(self, p: Path):
        self.mode = "loose"
        siblings = self._siblings_for(p)
        if ".pul" not in siblings:
            raise ValueError("Loose HEKA support-file loading requires a matching .pul file with the same base name.")
        self.support_paths = siblings
        self.loose_base = p.with_suffix("")
        self.pul = siblings[".pul"].read_bytes()
        self.dat_payload_path = siblings.get(".dat")
        self.dat_payload_offset = 0
        self.dat_payload_length = siblings[".dat"].stat().st_size if ".dat" in siblings else 0
        if ".dat" not in siblings:
            self.notes.append("Loaded .pul/support metadata without a matching raw .dat payload; trace arrays and plots cannot be exported until the .dat payload is available.")
        self.metadata["source_file"] = str(p)
        self.metadata["mode"] = self.mode
        self.metadata["support_files"] = {ext: str(q) for ext, q in sorted(siblings.items())}
        self.metadata["raw_dat_size_bytes"] = self.dat_payload_length

    def _find_trace_records_generic(self) -> _HekaList[HekaTraceRec]:
        pul = self.pul
        pul_len = len(pul)

        def add_candidate(by_rec, label_pos: int, label: str):
            rec_off = label_pos - HEKA_TRACE_LABEL_OFFSET
            if rec_off < 0 or rec_off + HEKA_TRACE_NPOINTS_OFFSET + 4 > pul_len:
                return
            try:
                kind = _heka_u32_at(pul, rec_off + HEKA_TRACE_KIND_OFFSET)
                old_offset = _heka_u32_at(pul, rec_off + HEKA_TRACE_DATA_OFFSET)
                n_points = _heka_u32_at(pul, rec_off + HEKA_TRACE_NPOINTS_OFFSET)
            except Exception:
                return
            if not (0 < kind < 100):
                return
            if not (0 < n_points < 200_000_000):
                return
            actual = _heka_cstring_at(pul, rec_off + HEKA_TRACE_LABEL_OFFSET, 64)
            if actual != label:
                return
            nbytes = n_points * self.bytes_per_point
            if nbytes <= 0:
                return
            if self.dat_payload_length and nbytes > max(self.dat_payload_length, 16):
                return
            mode = self._classify_trace_offset(old_offset, nbytes)
            if mode == "unknown" and self.dat_payload_length:
                return
            by_rec[rec_off] = HekaTraceRec(-1, rec_off, actual, kind, old_offset, n_points, nbytes, mode)

        # First pass: exact known HEKA channel labels.  This avoids false positives in binary .pul payloads.
        by_rec: _HekaDict[int, HekaTraceRec] = {}
        for label in HEKA_KNOWN_TRACE_LABELS:
            lb = label.encode("latin-1", errors="ignore")
            start = 0
            while True:
                label_pos = pul.find(lb, start)
                if label_pos < 0:
                    break
                add_candidate(by_rec, label_pos, label)
                start = label_pos + 1
        if by_rec:
            traces = sorted(by_rec.values(), key=lambda t: t.rec_offset)
            for i, tr in enumerate(traces):
                tr.tree_index = i
            return traces

        # Fallback pass: scan NUL-terminated printable channel labels, but keep only electrochemically plausible labels.
        by_rec = {}
        plausible = re.compile(r"(Imon|Emon|Current|Potential|Voltage|Real\(Z\)|Imag\(Z\)|Imp\|Z\||Phase|Real\(Y\)|Imag\(Y\)|Admit\(Y\)|^I[0-9_ -]*$|^E[0-9_ -]*$|^V[0-9_ -]*$)", re.I)
        for label_pos in range(HEKA_TRACE_LABEL_OFFSET, max(HEKA_TRACE_LABEL_OFFSET, pul_len - 8)):
            b0 = pul[label_pos]
            if b0 < 33 or b0 > 126:
                continue
            nul = pul.find(b"\x00", label_pos, min(label_pos + 49, pul_len))
            if nul < 0 or nul == label_pos:
                continue
            label = pul[label_pos:nul].decode("latin-1", errors="ignore")
            if not _heka_is_printable_label(label):
                continue
            if not any(ch.isalpha() for ch in label):
                continue
            if not plausible.search(label):
                continue
            add_candidate(by_rec, label_pos, label)
        traces = sorted(by_rec.values(), key=lambda t: t.rec_offset)
        for i, tr in enumerate(traces):
            tr.tree_index = i
        return traces

    def _classify_trace_offset(self, old_offset: int, nbytes: int) -> str:
        if nbytes <= 0:
            return "unknown"
        if self.mode in {"bundle", "bytes_bundle"} and ".dat" in self.sections:
            dat_sec = self.sections[".dat"]
            if old_offset >= dat_sec.offset and old_offset + nbytes <= dat_sec.end:
                return "bundle_absolute"
            if old_offset >= 0 and old_offset + nbytes <= dat_sec.length:
                return "dat_relative"
            try:
                if self.bundle_path and old_offset + nbytes <= self.bundle_path.stat().st_size:
                    return "raw_absolute"
            except Exception:
                pass
        else:
            if old_offset >= 0 and old_offset + nbytes <= self.dat_payload_length:
                return "dat_relative"
        return "unknown"

    def _analyze(self):
        if not self.pul:
            raise ValueError("No .pul metadata was loaded; cannot analyze HEKA data.")
        self.traces = self._find_trace_records_generic()
        if not self.traces:
            raise RuntimeError("No HEKA trace records found in the .pul tree. This may be a newer/unsupported tree layout or a mismatched .pul file.")
        self._detect_eis_groups()
        self._infer_blocks()
        self._detect_cv_pairs()
        self._extract_method_entries()
        self._build_detail_summary()
        self._build_metadata()

    def _detect_eis_groups(self):
        labels = [t.label for t in self.traces]
        groups: _HekaList[HekaEISGroup] = []
        covered: set[int] = set()
        seq = HEKA_DEFAULT_EIS_SEQUENCE
        L = len(seq)
        i = 0
        while i <= len(labels) - L:
            if labels[i:i + L] == seq:
                gidx = len(groups)
                idxs = list(range(i, i + L))
                for ti in idxs:
                    self.traces[ti].eis_group_index = gidx
                    covered.add(ti)
                groups.append(HekaEISGroup(gidx, i, idxs))
                i += L
            else:
                i += 1
        # More generic fallback: group consecutive windows containing Z-real/Z-imag/phase-like labels.
        if not groups:
            current = []
            for idx, tr in enumerate(self.traces):
                if HEKA_EIS_LABEL_RE.search(tr.label) or tr.label in {"Imon-2", "Emon-2"}:
                    current.append(idx)
                else:
                    if any(HEKA_EIS_LABEL_RE.search(self.traces[j].label) for j in current) and len(current) >= 2:
                        gidx = len(groups)
                        for ti in current:
                            self.traces[ti].eis_group_index = gidx
                            covered.add(ti)
                        groups.append(HekaEISGroup(gidx, current[0], list(current)))
                    current = []
            if any(HEKA_EIS_LABEL_RE.search(self.traces[j].label) for j in current) and len(current) >= 2:
                gidx = len(groups)
                for ti in current:
                    self.traces[ti].eis_group_index = gidx
                    covered.add(ti)
                groups.append(HekaEISGroup(gidx, current[0], list(current)))
        self.eis_groups = groups
        self._eis_covered = covered

    @staticmethod
    def _cluster_consecutive(indices: _HekaSequence[int]) -> _HekaList[_HekaList[int]]:
        clusters: _HekaList[_HekaList[int]] = []
        cur: _HekaList[int] = []
        for idx in sorted(indices):
            if not cur or idx == cur[-1] + 1:
                cur.append(idx)
            else:
                clusters.append(cur)
                cur = [idx]
        if cur:
            clusters.append(cur)
        return clusters

    def _infer_blocks(self):
        if not self.eis_groups:
            # Generic non-EIS file: treat repeated current/potential pairs or every 100 traces as blocks.
            all_idx = list(range(len(self.traces)))
            self.blocks = [HekaBlock(0, [], [], all_idx, "FULL")]
            for ti in all_idx:
                self.traces[ti].block_index0 = 0
            return
        unmatched = [i for i in range(len(self.traces)) if i not in self._eis_covered]
        clusters = self._cluster_consecutive(unmatched)
        group_starts = [g.start_tree_index for g in self.eis_groups]
        if not clusters:
            trace_indices = sorted(set().union(*(set(g.trace_indices) for g in self.eis_groups)))
            self.blocks = [HekaBlock(0, [], list(range(len(self.eis_groups))), trace_indices, "FULL")]
        else:
            blocks: _HekaList[HekaBlock] = []
            for bi, cluster in enumerate(clusters):
                first_tree = cluster[0]
                g_start = _heka_bisect.bisect_left(group_starts, first_tree)
                if bi + 1 < len(clusters):
                    g_end = _heka_bisect.bisect_left(group_starts, clusters[bi + 1][0])
                else:
                    g_end = len(self.eis_groups)
                gis = list(range(g_start, g_end))
                trace_indices = list(cluster)
                for gi in gis:
                    trace_indices.extend(self.eis_groups[gi].trace_indices)
                blocks.append(HekaBlock(bi, list(cluster), gis, sorted(set(trace_indices))))
            counts = [len(b.eis_group_indices) for b in blocks if len(b.eis_group_indices) > 0]
            full_count = Counter(counts).most_common(1)[0][0] if counts else 0
            for b in blocks:
                n = len(b.eis_group_indices)
                b.status = "EMPTY" if n == 0 else ("FULL" if n == full_count else "PARTIAL")
            self.blocks = blocks
        for b in self.blocks:
            for ti in b.trace_indices:
                if 0 <= ti < len(self.traces):
                    self.traces[ti].block_index0 = b.block_index0
            for gi in b.eis_group_indices:
                if 0 <= gi < len(self.eis_groups):
                    self.eis_groups[gi].block_index0 = b.block_index0

    def _detect_cv_pairs(self):
        pairs = []
        used = set()
        for i, tr in enumerate(self.traces[:-1]):
            if i in used:
                continue
            a = tr
            b = self.traces[i + 1]
            labels = (a.label, b.label)
            is_pair = False
            current_idx = potential_idx = None
            if HEKA_CURRENT_LABEL_RE.search(labels[0]) and HEKA_POTENTIAL_LABEL_RE.search(labels[1]):
                current_idx, potential_idx = i, i + 1
                is_pair = True
            elif HEKA_POTENTIAL_LABEL_RE.search(labels[0]) and HEKA_CURRENT_LABEL_RE.search(labels[1]):
                # v297: a short Ecorr/prelude potential trace can immediately
                # precede the real Tafel current trace.  If the following trace
                # is also potential and matches the current length more closely,
                # defer pairing so current + following potential are selected.
                if i + 2 < len(self.traces):
                    c = self.traces[i + 2]
                    if HEKA_POTENTIAL_LABEL_RE.search(c.label):
                        d_prev = abs(int(a.n_points) - int(b.n_points))
                        d_next = abs(int(c.n_points) - int(b.n_points))
                        if d_next < d_prev:
                            continue
                current_idx, potential_idx = i + 1, i
                is_pair = True
            if not is_pair:
                continue
            if min(a.n_points, b.n_points) < 50:
                continue
            if abs(a.n_points - b.n_points) > max(2, int(0.02 * max(a.n_points, b.n_points))):
                continue
            # Avoid counting online EIS monitor channels as CV pairs.
            if a.eis_group_index is not None or b.eis_group_index is not None:
                continue
            pairs.append({
                "pair_index": len(pairs) + 1,
                "current_trace_index": current_idx,
                "potential_trace_index": potential_idx,
                "current_label": self.traces[current_idx].label,
                "potential_label": self.traces[potential_idx].label,
                "n_points": min(self.traces[current_idx].n_points, self.traces[potential_idx].n_points),
                "block_index0": a.block_index0 if a.block_index0 is not None else b.block_index0,
            })
            used.add(i); used.add(i + 1)
        self.cv_pairs = pairs

    def _read_support_section_for_text(self, ext: str, limit_bytes: int = 24 * 1024 * 1024) -> bytes:
        """Read a small/medium HEKA support section for printable method strings."""
        try:
            if self.mode == "bytes_bundle" and ext in self.section_bytes:
                return self.section_bytes[ext][:limit_bytes]
            if self.mode == "bundle" and self.bundle_path and ext in self.sections:
                sec = self.sections[ext]
                with self.bundle_path.open("rb") as f:
                    f.seek(sec.offset)
                    return f.read(min(sec.length, limit_bytes))
            if self.mode == "loose" and ext in self.support_paths:
                with self.support_paths[ext].open("rb") as f:
                    return f.read(limit_bytes)
        except Exception:
            return b""
        return b""

    @staticmethod
    def _parse_heka_method_line(line: str, source_ext: str, entry_index: int) -> dict | None:
        text = " ".join(str(line).strip().split())
        if not text:
            return None
        method_tokens = (
            "EIS", "CV", "Cyclic", "Voltam", "Ramp", "Sweep", "Scan", "Step", "Pulse",
            "Chrono", "OCP", "Open Circuit", "StartFreq", "EndFreq", "Sine", "FreqPerDec",
            "Cycles", "Potential", "Voltage", "Current", "Amplitude", "Duration", "Sample", "Takedata",
        )
        if not any(tok.lower() in text.lower() for tok in method_tokens):
            return None
        entry = {"method_entry": entry_index, "source_section": source_ext, "raw_text": text[:500]}
        head = text.split("(", 1)[0].strip(" :")
        if head and len(head) <= 64:
            entry["technique_text"] = head
        for key, value in re.findall(r"([A-Za-z][A-Za-z0-9_ /()-]{0,32})\s*=\s*([^,;]+)", text):
            clean_key = re.sub(r"[^A-Za-z0-9]+", "_", key.strip()).strip("_").lower()
            clean_val = value.strip()
            entry[clean_key] = clean_val
            num = _heka_parse_numeric_with_unit(clean_val)
            if num is None:
                continue
            if clean_key in {"startfreq", "start_frequency", "start_freq"}:
                entry["start_freq_Hz"] = num
            elif clean_key in {"endfreq", "end_frequency", "end_freq"}:
                entry["end_freq_Hz"] = num
            elif clean_key in {"sine", "amplitude", "ac_amplitude", "amp"}:
                entry["ac_amplitude_V"] = num
                entry["ac_amplitude_mV"] = num * 1e3
            elif clean_key in {"freqperdec", "freq_per_dec", "points_per_decade", "ptsperdec"}:
                entry["freq_per_decade"] = num
            elif clean_key in {"cycles", "cycle"}:
                entry["cycles"] = num
            elif clean_key == "skip":
                entry["skip"] = num
            elif clean_key in {"scanrate", "scan_rate", "sweeprate", "sweep_rate"}:
                entry["scan_rate_V_s"] = num
            elif "potential" in clean_key or clean_key in {"e_begin", "e_end", "e_start", "e_stop"}:
                entry[clean_key + "_V"] = num
        m = re.search(r"scan\s*rate\s*[:=]?\s*([-+\d.eE]+)\s*(mV/s|V/s)", text, re.I)
        if m:
            val = float(m.group(1)) * (1e-3 if m.group(2).lower().startswith("mv") else 1.0)
            entry["scan_rate_V_s"] = val
        return entry

    def _extract_method_entries(self):
        entries = []
        seen = set()
        for ext in [".mth", ".pgf", ".onl", ".pul"]:
            data = self._read_support_section_for_text(ext)
            if not data:
                continue
            for run in _heka_printable_runs(data, min_len=10):
                for line in re.split(r"[\r\n]+", run):
                    parsed = self._parse_heka_method_line(line, ext, len(entries) + 1)
                    if not parsed:
                        continue
                    key = (parsed.get("source_section"), parsed.get("raw_text"))
                    if key in seen:
                        continue
                    seen.add(key)
                    parsed["method_entry"] = len(entries) + 1
                    entries.append(parsed)
                    if len(entries) >= 500:
                        break
                if len(entries) >= 500:
                    break
        self.method_entries = entries

    def _method_value(self, key: str):
        for e in self.method_entries:
            if key in e and e[key] not in (None, ""):
                return e[key]
        return None

    def _collect_trace_stats_by_label(self, label_patterns: _HekaList[str], max_traces: int = 200, max_points: int = 250000, abs_limit: float | None = None) -> dict:
        cre = re.compile("|".join(label_patterns), re.I)
        vals = []
        n_traces = 0
        n_points = 0
        for ti, tr in enumerate(self.traces):
            if not cre.search(tr.label):
                continue
            if n_traces >= max_traces:
                break
            try:
                arr = self.read_trace_array(ti, max_points=min(max_points, tr.n_points))
            except Exception:
                continue
            arr = np.asarray(arr, dtype=float)
            arr = arr[np.isfinite(arr)]
            if arr.size == 0:
                continue
            if abs_limit is not None:
                arr = arr[np.abs(arr) <= float(abs_limit)]
            else:
                arr = arr[np.abs(arr) < 1e12]
            if arr.size == 0:
                continue
            vals.append(arr)
            n_traces += 1
            n_points += int(arr.size)
        if not vals:
            return {}
        cat = np.concatenate(vals)
        return {"min": float(np.nanmin(cat)), "max": float(np.nanmax(cat)), "median": float(np.nanmedian(cat)), "n_traces_sampled": int(n_traces), "n_points_sampled": int(n_points)}

    def _eis_rows_limited(self, max_groups: int | None = None) -> _HekaList[dict]:
        rows = []
        groups = self.eis_groups if max_groups is None else self.eis_groups[:max_groups]
        for g in groups:
            def first_matching(pattern: str):
                cre = re.compile(pattern, re.I)
                for ti in g.trace_indices:
                    if cre.search(self.traces[ti].label):
                        return ti
                return None
            zre_i = first_matching(r"Real\(Z\)")
            zim_i = first_matching(r"Imag\(Z\)")
            zabs_i = first_matching(r"Imp\|Z\||\|Z\|")
            phase_i = first_matching(r"Phase")
            emon_i = first_matching(r"(^E|Emon|Volt|Potential)")
            imon_i = first_matching(r"(^I|Imon|Current)")
            vals = {}
            for key, ti in [("Zreal_ohm", zre_i), ("Zimag_ohm", zim_i), ("Zabs_ohm", zabs_i), ("phase_deg", phase_i), ("bias_potential_V", emon_i), ("monitor_current_A", imon_i)]:
                if ti is None:
                    vals[key] = ""
                else:
                    try:
                        arr = self.read_trace_array(ti, max_points=64)
                        finite_arr = np.asarray(arr, dtype=float)
                        finite_arr = finite_arr[np.isfinite(finite_arr)]
                        v = float(np.median(finite_arr)) if len(finite_arr) else float("nan")
                        valid = np.isfinite(v)
                        if key == "Zabs_ohm":
                            valid = valid and (0 < abs(v) <= 1e9)
                        elif key in {"Zreal_ohm", "Zimag_ohm"}:
                            valid = valid and (abs(v) <= 1e9)
                        elif key == "phase_deg":
                            valid = valid and (abs(v) <= 180)
                        elif key == "bias_potential_V":
                            valid = valid and (abs(v) <= 10)
                        elif key == "monitor_current_A":
                            valid = valid and (abs(v) <= 1)
                        vals[key] = v if valid else ""
                    except Exception:
                        vals[key] = ""
            rows.append({"eis_group": g.group_index + 1, "position_or_block": "" if g.block_index0 is None else g.block_index0 + 1, "trace_indices": ";".join(str(ti + 1) for ti in g.trace_indices), "labels": ";".join(self.traces[ti].label for ti in g.trace_indices), **vals})
        return rows

    def _collect_eis_impedance_ranges(self, max_groups: int = 500) -> dict:
        if not self.eis_groups:
            return {}
        rows = self._eis_rows_limited(max_groups=max_groups)
        out = {}
        for key, label in [("Zreal_ohm", "zreal"), ("Zimag_ohm", "zimag"), ("Zabs_ohm", "zabs"), ("phase_deg", "phase")]:
            vals = [float(r.get(key)) for r in rows if isinstance(r.get(key), (int, float)) and np.isfinite(float(r.get(key)))]
            if vals:
                out[f"{label}_min"] = float(np.nanmin(vals)); out[f"{label}_max"] = float(np.nanmax(vals)); out[f"{label}_median"] = float(np.nanmedian(vals))
        out["n_groups_sampled"] = len(rows)
        return out

    def _cv_pair_detail(self, p: dict, max_points: int = 500000) -> dict:
        out = {}
        try:
            n = min(int(p["n_points"]), max_points)
            e = self.read_trace_array(p["potential_trace_index"], max_points=n)
            i = self.read_trace_array(p["current_trace_index"], max_points=n)
            e = np.asarray(e, dtype=float); i = np.asarray(i, dtype=float)
            e = e[np.isfinite(e) & (np.abs(e) < 1e6)]
            i = i[np.isfinite(i) & (np.abs(i) < 1e6)]
            if e.size:
                out["potential_min_V"] = float(np.nanmin(e)); out["potential_max_V"] = float(np.nanmax(e)); out["potential_median_V"] = float(np.nanmedian(e))
            if i.size:
                out["current_min_A"] = float(np.nanmin(i)); out["current_max_A"] = float(np.nanmax(i)); out["current_median_A"] = float(np.nanmedian(i))
            out["n_points_sampled"] = int(min(len(e), len(i)))
        except Exception as exc:
            out["detail_note"] = f"range read failed: {exc}"
        return out

    def _infer_repeats_and_freq_points(self) -> dict:
        if not self.blocks or not self.eis_groups:
            return {}
        counts = [len(b.eis_group_indices) for b in self.blocks if len(b.eis_group_indices) > 0]
        if not counts:
            return {}
        full = Counter(counts).most_common(1)[0][0]
        out = {"eis_groups_per_full_block": int(full)}
        if full % 2 == 0:
            out["possible_repeats"] = 2
            out["possible_frequency_points_per_repeat"] = int(full // 2)
        return out

    def _build_detail_summary(self):
        freq_start = self._method_value("start_freq_Hz")
        freq_end = self._method_value("end_freq_Hz")
        freq_min = freq_max = None
        if freq_start not in (None, "") and freq_end not in (None, ""):
            try:
                freq_min = min(float(freq_start), float(freq_end)); freq_max = max(float(freq_start), float(freq_end))
            except Exception:
                pass
        scan_rate = self._method_value("scan_rate_V_s")
        ac_amp_mV = self._method_value("ac_amplitude_mV")
        freq_per_dec = self._method_value("freq_per_decade")
        cycles = self._method_value("cycles")
        skip = self._method_value("skip")
        cv_details = [self._cv_pair_detail(p) for p in self.cv_pairs[:50]]
        cv_pmins = [d.get("potential_min_V") for d in cv_details if d.get("potential_min_V") is not None]
        cv_pmaxs = [d.get("potential_max_V") for d in cv_details if d.get("potential_max_V") is not None]
        cv_imins = [d.get("current_min_A") for d in cv_details if d.get("current_min_A") is not None]
        cv_imaxs = [d.get("current_max_A") for d in cv_details if d.get("current_max_A") is not None]
        eis_ranges = self._collect_eis_impedance_ranges(max_groups=500) if self.eis_groups else {}
        emon_stats = self._collect_trace_stats_by_label([r"(^E|Emon|Volt|Potential)"], max_traces=100, abs_limit=10.0) if self.traces else {}
        imon_stats = self._collect_trace_stats_by_label([r"(^I|Imon|Current)"], max_traces=100, abs_limit=1.0) if self.traces else {}
        position_counts = [len(b.eis_group_indices) for b in self.blocks]
        full_count = Counter([c for c in position_counts if c > 0]).most_common(1)[0][0] if any(c > 0 for c in position_counts) else 0
        partial_blocks = [i + 1 for i, c in enumerate(position_counts) if full_count and 0 < c != full_count]
        self.detail_summary = {
            "frequency_min_Hz": freq_min, "frequency_max_Hz": freq_max, "frequency_range_text": _heka_format_range(freq_min, freq_max, " Hz"),
            "scan_rate_V_s": scan_rate, "scan_rate_text": _heka_format_scalar(scan_rate, " V/s"),
            "ac_amplitude_mV": ac_amp_mV, "ac_amplitude_text": _heka_format_scalar(ac_amp_mV, " mV"),
            "freq_per_decade": freq_per_dec, "cycles": cycles, "skip": skip,
            "cv_potential_min_V": min(cv_pmins) if cv_pmins else None, "cv_potential_max_V": max(cv_pmaxs) if cv_pmaxs else None,
            "cv_current_min_A": min(cv_imins) if cv_imins else None, "cv_current_max_A": max(cv_imaxs) if cv_imaxs else None,
            "cv_potential_range_text": _heka_format_range(min(cv_pmins) if cv_pmins else None, max(cv_pmaxs) if cv_pmaxs else None, " V"),
            "cv_current_range_text": _heka_format_range(min(cv_imins) if cv_imins else None, max(cv_imaxs) if cv_imaxs else None, " A"),
            "emon_min_V": emon_stats.get("min"), "emon_max_V": emon_stats.get("max"), "emon_range_text": _heka_format_range(emon_stats.get("min"), emon_stats.get("max"), " V"),
            "imon_min_A": imon_stats.get("min"), "imon_max_A": imon_stats.get("max"), "imon_range_text": _heka_format_range(imon_stats.get("min"), imon_stats.get("max"), " A"),
            "zreal_range_text": _heka_format_range(eis_ranges.get("zreal_min"), eis_ranges.get("zreal_max"), " Ω"),
            "zimag_range_text": _heka_format_range(eis_ranges.get("zimag_min"), eis_ranges.get("zimag_max"), " Ω"),
            "zabs_range_text": _heka_format_range(eis_ranges.get("zabs_min"), eis_ranges.get("zabs_max"), " Ω"),
            "phase_range_text": _heka_format_range(eis_ranges.get("phase_min"), eis_ranges.get("phase_max"), "°"),
            "eis_groups_per_full_block": full_count,
            "partial_blocks": partial_blocks,
            "repeat_inference": self._infer_repeats_and_freq_points(),
            "method_entries_preview": self.method_entries[:12],
            "n_method_entries": len(self.method_entries),
        }

    def _build_metadata(self):
        label_counts = Counter(t.label for t in self.traces)
        offset_modes = Counter(t.data_offset_mode for t in self.traces)
        tech_counts = Counter()
        if self.eis_groups:
            tech_counts["EIS"] = len(self.eis_groups)
        if self.cv_pairs:
            tech_counts["CV"] = len(self.cv_pairs)
        if not tech_counts:
            tech_counts["HEKA traces"] = len(self.traces)
        block_counts = Counter(len(b.eis_group_indices) for b in self.blocks)
        self.metadata.update({
            "format": "heka-potmaster-patchmaster-dat2-v1",
            "n_traces": len(self.traces),
            "n_eis_groups": len(self.eis_groups),
            "n_blocks": len(self.blocks),
            "n_cv_pairs": len(self.cv_pairs),
            "label_counts": dict(label_counts),
            "offset_modes": dict(offset_modes),
            "eis_groups_per_block_distribution": dict(block_counts),
            "technique_counts": dict(tech_counts),
            "detail_summary": self.detail_summary,
            "method_entries": self.method_entries[:200],
        })
        self.session = {
            "format": "heka-potmaster-summary-v1",
            "source_file": self.source_path,
            "metadata": self.metadata,
            "notes": self.notes,
        }

    def _trace_abs_file_offset(self, tr: HekaTraceRec) -> int:
        if self.mode == "bundle":
            if tr.data_offset_mode == "bundle_absolute" or tr.data_offset_mode == "raw_absolute":
                return tr.old_offset
            if tr.data_offset_mode == "dat_relative":
                return self.dat_payload_offset + tr.old_offset
        elif self.mode == "loose":
            return tr.old_offset
        raise ValueError("Cannot read trace data for in-memory bundle or unknown offset mode.")

    def read_trace_array(self, trace_index: int, max_points: _HekaOptional[int] = None) -> np.ndarray:
        tr = self.traces[trace_index]
        n = tr.n_points if max_points is None else min(tr.n_points, int(max_points))
        if self.mode == "bytes_bundle":
            if ".dat" not in self.section_bytes:
                raise ValueError("No .dat section bytes are available.")
            if tr.data_offset_mode == "bundle_absolute":
                start = tr.old_offset - self.dat_payload_offset
            else:
                start = tr.old_offset
            raw = self.section_bytes[".dat"][start:start + n * self.bytes_per_point]
            return np.frombuffer(raw, dtype="<f4", count=len(raw) // 4).astype(float)
        if self.dat_payload_path is None:
            raise ValueError("No data payload path available.")
        start = self._trace_abs_file_offset(tr)
        with self.dat_payload_path.open("rb") as f:
            f.seek(start)
            raw = f.read(n * self.bytes_per_point)
        return np.frombuffer(raw, dtype="<f4", count=len(raw) // 4).astype(float)

    def _trace_rows(self) -> _HekaList[dict]:
        rows = []
        for tr in self.traces:
            rows.append({
                "trace_index": tr.tree_index,
                "record_offset_in_pul": tr.rec_offset,
                "label": tr.label,
                "kind": tr.kind,
                "data_offset": tr.old_offset,
                "data_offset_mode": tr.data_offset_mode,
                "n_points": tr.n_points,
                "nbytes_float32": tr.nbytes,
                "eis_group_index": "" if tr.eis_group_index is None else tr.eis_group_index + 1,
                "block_position": "" if tr.block_index0 is None else tr.block_index0 + 1,
            })
        return rows

    def _bundle_section_rows(self) -> _HekaList[dict]:
        if self.sections:
            return [{"section": ext, "offset": sec.offset, "length": sec.length, "end": sec.end} for ext, sec in sorted(self.sections.items(), key=lambda kv: kv[1].offset)]
        return [{"section": ext, "path": str(path), "length": path.stat().st_size} for ext, path in sorted(self.support_paths.items())]

    def _position_rows(self) -> _HekaList[dict]:
        rows = []
        ds = self.detail_summary or {}
        full_count = ds.get("eis_groups_per_full_block") or 0
        for b in self.blocks:
            intervals = _heka_merge_intervals((self.traces[i].old_offset, self.traces[i].old_end) for i in b.trace_indices)
            union_bytes = _heka_total_interval_bytes(intervals)
            tech = "EIS" if b.eis_group_indices else ("CV" if any((p.get("block_index0") == b.block_index0) for p in self.cv_pairs) else "HEKA")
            rows.append({
                "position_or_block": b.block_index0 + 1,
                "technique": tech,
                "status": b.status,
                "prelude_trace_count": len(b.prelude_trace_indices),
                "eis_group_count": len(b.eis_group_indices),
                "eis_groups_expected_full_block": full_count,
                "trace_count": len(b.trace_indices),
                "method_frequency_range": ds.get("frequency_range_text", ""),
                "scan_rate": ds.get("scan_rate_text", ""),
                "eis_ac_amplitude": ds.get("ac_amplitude_text", ""),
                "freq_per_decade": ds.get("freq_per_decade", ""),
                "cycles": ds.get("cycles", ""),
                "monitor_potential_range": ds.get("emon_range_text", ""),
                "monitor_current_range": ds.get("imon_range_text", ""),
                "cv_potential_range": ds.get("cv_potential_range_text", ""),
                "cv_current_range": ds.get("cv_current_range_text", ""),
                "Zreal_range_sample": ds.get("zreal_range_text", ""),
                "Zimag_range_sample": ds.get("zimag_range_text", ""),
                "Zabs_range_sample": ds.get("zabs_range_text", ""),
                "phase_range_sample": ds.get("phase_range_text", ""),
                "data_union_bytes": union_bytes,
                "data_union_MiB": round(union_bytes / 1024 / 1024, 6),
                "first_trace_index": min(b.trace_indices) + 1 if b.trace_indices else "",
                "last_trace_index": max(b.trace_indices) + 1 if b.trace_indices else "",
            })
        return rows

    def _eis_rows(self) -> _HekaList[dict]:
        rows = self._eis_rows_limited(max_groups=None)
        ds = self.detail_summary or {}
        for r in rows:
            r["method_frequency_range"] = ds.get("frequency_range_text", "")
            r["freq_per_decade"] = ds.get("freq_per_decade", "")
            r["ac_amplitude_mV"] = ds.get("ac_amplitude_mV", "")
            r["cycles"] = ds.get("cycles", "")
        return rows

    def _cv_summary_rows(self) -> _HekaList[dict]:
        rows = []
        for p in self.cv_pairs:
            detail = self._cv_pair_detail(p, max_points=300000)
            rows.append({
                "cv_pair": p["pair_index"],
                "position_or_block": "" if p.get("block_index0") is None else p["block_index0"] + 1,
                "potential_trace_index": p["potential_trace_index"] + 1,
                "current_trace_index": p["current_trace_index"] + 1,
                "potential_label": p["potential_label"],
                "current_label": p["current_label"],
                "n_points": p["n_points"],
                "scan_rate": (self.detail_summary or {}).get("scan_rate_text", ""),
                "potential_min_V": detail.get("potential_min_V", ""),
                "potential_max_V": detail.get("potential_max_V", ""),
                "current_min_A": detail.get("current_min_A", ""),
                "current_max_A": detail.get("current_max_A", ""),
                "potential_range": _heka_format_range(detail.get("potential_min_V"), detail.get("potential_max_V"), " V"),
                "current_range": _heka_format_range(detail.get("current_min_A"), detail.get("current_max_A"), " A"),
            })
        return rows

    def summarize(self) -> dict:
        rows = []
        ds = self.detail_summary or {}
        for b in self.blocks[:200]:
            tech = "EIS" if b.eis_group_indices else ("CV" if any((p.get("block_index0") == b.block_index0) for p in self.cv_pairs) else "HEKA")
            extras = []
            if tech == "EIS":
                if ds.get("frequency_range_text"):
                    extras.append(f"freq={ds.get('frequency_range_text')}")
                if ds.get("ac_amplitude_text"):
                    extras.append(f"AC={ds.get('ac_amplitude_text')}")
                if ds.get("freq_per_decade") not in (None, ""):
                    extras.append(f"pts/dec={ds.get('freq_per_decade')}")
                if ds.get("zabs_range_text"):
                    extras.append(f"|Z|={ds.get('zabs_range_text')}")
                if ds.get("emon_range_text"):
                    extras.append(f"E={ds.get('emon_range_text')}")
            if tech == "CV":
                if ds.get("cv_potential_range_text"):
                    extras.append(f"E={ds.get('cv_potential_range_text')}")
                if ds.get("cv_current_range_text"):
                    extras.append(f"I={ds.get('cv_current_range_text')}")
                if ds.get("scan_rate_text"):
                    extras.append(f"scan={ds.get('scan_rate_text')}")
            rows.append({
                "index": b.block_index0 + 1,
                "title": f"HEKA block/position {b.block_index0 + 1}",
                "method_id": tech,
                "technique": tech,
                "n_curves": len(b.trace_indices),
                "n_eis_blocks": len(b.eis_group_indices),
                "status": b.status,
                "frequency_range": ds.get("frequency_range_text", ""),
                "scan_rate": ds.get("scan_rate_text", ""),
                "ac_amplitude": ds.get("ac_amplitude_text", ""),
                "freq_per_decade": ds.get("freq_per_decade", ""),
                "cycles": ds.get("cycles", ""),
                "potential_range": ds.get("cv_potential_range_text") or ds.get("emon_range_text", ""),
                "current_range": ds.get("cv_current_range_text") or ds.get("imon_range_text", ""),
                "z_range": ds.get("zabs_range_text", ""),
                "details_text": "; ".join(extras),
            })
        return {
            "source_file": self.source_path,
            "vendor": "HEKA/POTMASTER/PATCHMASTER",
            "mode": self.mode,
            "n_measurements": len(self.blocks) if self.blocks else len(self.traces),
            "technique_counts": self.metadata.get("technique_counts", {}),
            "measurement_rows": rows,
            "notes": self.notes,
            "heka_metadata": self.metadata,
            "heka_detail_summary": self.detail_summary,
            "heka_method_entries": self.method_entries[:50],
        }

    def build_compact_summary(self) -> dict:
        return self.summarize()

    def session_minified_json(self) -> str:
        return json.dumps(self.session, ensure_ascii=False, separators=(",", ":"))

    def native_numeric_payload(self) -> dict:
        # Do not preload giant HEKA arrays into the general .npy bundle.  CSV/HDF5-style exports are written by export_analysis_ready_outputs().
        return {
            "format": "heka-potmaster-native-index-v1",
            "source_file": self.source_path,
            "mode": self.mode,
            "metadata": self.metadata,
            "trace_index": self._trace_rows(),
            "position_report": self._position_rows(),
            "cv_pairs": self._cv_summary_rows(),
        }

    def primary_numeric_payload(self) -> dict:
        return self.native_numeric_payload()

    def iter_primary_curve_exports(self):
        # Yield CV-like current/potential pairs as simple x/y curves, but skip huge traces.
        for p in self.cv_pairs:
            n = int(p["n_points"])
            if n <= 0 or n > 2_000_000:
                continue
            try:
                e = self.read_trace_array(p["potential_trace_index"], max_points=n)
                i = self.read_trace_array(p["current_trace_index"], max_points=n)
            except Exception:
                continue
            m = min(len(e), len(i))
            if m == 0:
                continue
            yield {
                "measurement_index": p["pair_index"],
                "curve_index": 1,
                "measurement_title": f"HEKA CV pair {p['pair_index']}",
                "curve_title": "current_vs_potential",
                "method_id": "HEKA-CV",
                "technique": "CV",
                "scan_rate": None,
                "x_label": p["potential_label"],
                "x_unit": "V",
                "y_label": p["current_label"],
                "y_unit": "A",
                "rows": list(zip(e[:m].tolist(), i[:m].tolist())),
            }

    def export_analysis_ready_outputs(self, output_dir: Path, base_name: str) -> dict:
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        safe = PSSessionParser._sanitize_filename(base_name)
        csv_entries = []
        skipped = []
        files = []
        def write_named_csv(suffix: str, rows: _HekaList[dict], description: str):
            path = output_dir / f"{safe}_{suffix}.csv"
            _heka_write_csv(path, rows)
            files.append(str(path))
            csv_entries.append({
                "relative_csv_path": path.name,
                "technique": "HEKA",
                "curve_title": description,
                "n_points": len(rows),
                "x_label": "",
                "x_unit": "",
                "y_label": "",
                "y_unit": "",
                "method_id": "HEKA",
            })
            return path
        write_named_csv("heka_bundle_sections", self._bundle_section_rows(), "HEKA bundle/support section table")
        write_named_csv("heka_trace_index", self._trace_rows(), "HEKA .pul trace index")
        write_named_csv("heka_position_report", self._position_rows(), "HEKA inferred block/position report")
        if self.method_entries:
            write_named_csv("heka_method_entries", self.method_entries, "HEKA extracted method/program text and parsed parameters")
        if self.eis_groups:
            write_named_csv("heka_eis_online_impedance_summary", self._eis_rows(), "HEKA online EIS impedance summary")
        if self.cv_pairs:
            write_named_csv("heka_cv_pair_summary", self._cv_summary_rows(), "HEKA CV current/potential pair summary")
            # A compact combined CV CSV with one row per point and pair id.
            cv_path = output_dir / f"{safe}_heka_cv_combined.csv"
            with cv_path.open("w", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow(["cv_pair", "point", "potential_V", "current_A"])
                for p in self.cv_pairs:
                    n = min(int(p["n_points"]), 2_000_000)
                    try:
                        e = self.read_trace_array(p["potential_trace_index"], max_points=n)
                        i = self.read_trace_array(p["current_trace_index"], max_points=n)
                    except Exception as exc:
                        skipped.append({"reason": f"Could not export CV pair {p['pair_index']}: {exc}"})
                        continue
                    m = min(len(e), len(i))
                    for k in range(m):
                        w.writerow([p["pair_index"], k, float(e[k]), float(i[k])])
            files.append(str(cv_path))
            csv_entries.append({"relative_csv_path": cv_path.name, "technique": "CV", "curve_title": "HEKA combined CV current-potential table", "n_points": "", "x_label": "potential", "x_unit": "V", "y_label": "current", "y_unit": "A", "method_id": "HEKA-CV"})
        # Optional lightweight plots if matplotlib exists.
        try:
            import matplotlib
            matplotlib.use("Agg")
            import matplotlib.pyplot as plt
            if self.eis_groups:
                rows = self._eis_rows()
                zre = np.array([r.get("Zreal_ohm") for r in rows if isinstance(r.get("Zreal_ohm"), (int, float))], dtype=float)
                zim = np.array([r.get("Zimag_ohm") for r in rows if isinstance(r.get("Zimag_ohm"), (int, float))], dtype=float)
                if len(zre) and len(zim) and len(zre) == len(zim):
                    fig = plt.figure(figsize=(6, 5), dpi=160)
                    plt.plot(zre, -zim, ".", markersize=2)
                    plt.xlabel("Zreal / Ω")
                    plt.ylabel("-Zimag / Ω")
                    plt.title("HEKA online EIS Nyquist summary")
                    plt.tight_layout()
                    pth = output_dir / f"{safe}_heka_eis_nyquist_summary.png"
                    fig.savefig(pth)
                    plt.close(fig)
                    files.append(str(pth))
            if self.cv_pairs:
                fig = plt.figure(figsize=(6, 5), dpi=160)
                for p in self.cv_pairs[:50]:
                    n = min(int(p["n_points"]), 200000)
                    try:
                        e = self.read_trace_array(p["potential_trace_index"], max_points=n)
                        i = self.read_trace_array(p["current_trace_index"], max_points=n)
                    except Exception:
                        continue
                    m = min(len(e), len(i))
                    if m:
                        plt.plot(e[:m], i[:m], linewidth=0.8, alpha=0.7)
                plt.xlabel("Potential / V")
                plt.ylabel("Current / A")
                plt.title("HEKA CV overlay")
                plt.tight_layout()
                pth = output_dir / f"{safe}_heka_cv_overlay.png"
                fig.savefig(pth)
                plt.close(fig)
                files.append(str(pth))
        except Exception as exc:
            skipped.append({"reason": f"Plot export skipped: {exc}"})
        return {"files": files, "csv_entries": csv_entries, "skipped_entries": skipped, "n_csv_files": sum(1 for f in files if str(f).lower().endswith('.csv'))}

    def _trace_intervals_for_indices(self, indices: _HekaIterable[int]) -> _HekaList[_HekaTuple[int, int]]:
        return [(self.traces[i].old_offset, self.traces[i].old_end) for i in indices]

    def _selected_indices_for_unit_indices(self, unit_kind: str, unit_indices: _HekaList[int]) -> set[int]:
        selected: set[int] = set()
        if unit_kind == "blocks":
            for ui in unit_indices:
                selected.update(self.blocks[ui].trace_indices)
        elif unit_kind == "groups":
            for ui in unit_indices:
                selected.update(self.eis_groups[ui].trace_indices)
        else:
            selected.update(unit_indices)
        return selected

    def _split_units(self):
        if len(self.blocks) > 1:
            return "blocks", list(range(len(self.blocks)))
        if len(self.eis_groups) > 1:
            return "groups", list(range(len(self.eis_groups)))
        return "traces", list(range(len(self.traces)))

    def _estimate_part_size(self, selected: set[int], non_dat_bytes: int, dummy_nbytes: int) -> int:
        intervals = _heka_merge_intervals(self._trace_intervals_for_indices(selected))
        return HEKA_HEADER_SIZE + dummy_nbytes + _heka_total_interval_bytes(intervals) + non_dat_bytes

    def plan_size_limited_split(self, max_output_bytes: int) -> dict:
        if self.mode != "bundle" or not self.bundle_path:
            raise ValueError("Size-limited HEKA splitting requires a bundled DAT2 file path.")
        unit_kind, units = self._split_units()
        if not units:
            raise ValueError("No HEKA trace units are available for splitting.")
        non_dat_bytes = sum(sec.length for ext, sec in self.sections.items() if ext != ".dat")
        dummy_nbytes = HEKA_DEFAULT_BYTES_PER_POINT
        parts = []
        cur_units = []
        for u in units:
            test_units = cur_units + [u]
            selected = self._selected_indices_for_unit_indices(unit_kind, test_units)
            est = self._estimate_part_size(selected, non_dat_bytes, dummy_nbytes)
            if cur_units and est > max_output_bytes:
                selected_cur = self._selected_indices_for_unit_indices(unit_kind, cur_units)
                parts.append({"unit_kind": unit_kind, "units": cur_units, "selected_traces": selected_cur, "estimated_size_bytes": self._estimate_part_size(selected_cur, non_dat_bytes, dummy_nbytes)})
                cur_units = [u]
            else:
                cur_units = test_units
        if cur_units:
            selected_cur = self._selected_indices_for_unit_indices(unit_kind, cur_units)
            parts.append({"unit_kind": unit_kind, "units": cur_units, "selected_traces": selected_cur, "estimated_size_bytes": self._estimate_part_size(selected_cur, non_dat_bytes, dummy_nbytes)})
        return {"unit_kind": unit_kind, "max_output_bytes": max_output_bytes, "parts": parts}

    def _validate_split_offsets(self, intervals: _HekaList[_HekaTuple[int, int]]) -> int:
        if not intervals:
            return 0
        dat_sec = self.sections[".dat"]
        min_a = min(a for a, _ in intervals)
        max_b = max(b for _, b in intervals)
        if min_a >= dat_sec.offset and max_b <= dat_sec.end:
            return 0
        if min_a >= 0 and max_b <= dat_sec.length:
            return dat_sec.offset
        raise ValueError(
            "Selected HEKA trace offsets do not fit inside the bundle .dat section. "
            "This usually means the .pul support tree does not match the bundled .dat data payload."
        )

    def _map_trace_offsets_to_new(self, selected: set[int], intervals: _HekaList[_HekaTuple[int, int]], new_copied_data_start: int) -> _HekaDict[int, int]:
        starts = [a for a, _ in intervals]
        prefix = []
        running = 0
        for a, b in intervals:
            prefix.append(running)
            running += b - a
        mapping = {}
        for ti in sorted(selected):
            tr = self.traces[ti]
            j = _heka_bisect.bisect_right(starts, tr.old_offset) - 1
            if j < 0:
                raise RuntimeError(f"Trace {ti + 1} offset {tr.old_offset} was not in any copied interval")
            a, b = intervals[j]
            if tr.old_end > b:
                raise RuntimeError(f"Trace {ti + 1} spans outside copied interval")
            mapping[ti] = new_copied_data_start + prefix[j] + (tr.old_offset - a)
        return mapping

    def _write_split_bundle(self, out_path: Path, selected: set[int], force: bool = False, dummy_n_points: int = 1) -> dict:
        if self.mode != "bundle" or not self.bundle_path:
            raise ValueError("Writing HEKA split bundles requires an input bundled DAT2 file path.")
        if out_path.exists() and not force:
            raise FileExistsError(f"Output exists: {out_path}. Use overwrite/force to replace it.")
        dummy_nbytes = dummy_n_points * self.bytes_per_point
        intervals = _heka_merge_intervals(self._trace_intervals_for_indices(selected))
        src_origin_shift = self._validate_split_offsets(intervals)
        selected_union_bytes = _heka_total_interval_bytes(intervals)
        new_dat_length = dummy_nbytes + selected_union_bytes
        section_offsets = {}
        off = HEKA_HEADER_SIZE
        section_offsets[".dat"] = (off, new_dat_length); off += new_dat_length
        section_offsets[".pul"] = (off, len(self.pul)); off += len(self.pul)
        for ext in HEKA_PHYSICAL_WRITE_ORDER:
            if ext in {".dat", ".pul"}:
                continue
            sec = self.sections.get(ext)
            if sec is not None:
                section_offsets[ext] = (off, sec.length); off += sec.length
        if off > HEKA_MAX_U32:
            raise ValueError(f"Split output would exceed HEKA uint32 bundle limit: {off:,} bytes")
        patched_pul = bytearray(self.pul)
        new_dat_start = section_offsets[".dat"][0]
        dummy_abs_offset = new_dat_start
        new_copied_start = new_dat_start + dummy_nbytes
        for tr in self.traces:
            _heka_put_u32(patched_pul, tr.rec_offset + HEKA_TRACE_DATA_OFFSET, dummy_abs_offset)
            _heka_put_u32(patched_pul, tr.rec_offset + HEKA_TRACE_NPOINTS_OFFSET, dummy_n_points)
        mapping = self._map_trace_offsets_to_new(selected, intervals, new_copied_start)
        for ti, new_abs in mapping.items():
            tr = self.traces[ti]
            _heka_put_u32(patched_pul, tr.rec_offset + HEKA_TRACE_DATA_OFFSET, new_abs)
            _heka_put_u32(patched_pul, tr.rec_offset + HEKA_TRACE_NPOINTS_OFFSET, tr.n_points)
        header = _heka_build_header(self.header, section_offsets)
        tmp = out_path.with_name(out_path.name + ".tmp")
        if tmp.exists():
            tmp.unlink()
        with tmp.open("wb") as out:
            out.write(header)
            out.write(b"\x00" * dummy_nbytes)
            for a, b in intervals:
                _heka_copy_range(self.bundle_path, out, a + src_origin_shift, b - a)
            out.write(patched_pul)
            for ext in HEKA_PHYSICAL_WRITE_ORDER:
                if ext in {".dat", ".pul"}:
                    continue
                sec = self.sections.get(ext)
                if sec is not None:
                    _heka_copy_section(self.bundle_path, out, sec)
        if out_path.exists() and force:
            out_path.unlink()
        tmp.replace(out_path)
        return {
            "output": str(out_path),
            "output_size_bytes": out_path.stat().st_size,
            "output_size_MiB": round(out_path.stat().st_size / 1024 / 1024, 6),
            "selected_traces": len(selected),
            "copied_data_intervals": len(intervals),
            "copied_data_union_bytes": selected_union_bytes,
            "copied_data_union_MiB": round(selected_union_bytes / 1024 / 1024, 6),
        }

    def split_into_size_limited_bundles(self, output_dir: Path, max_output_gb: float = 1.95, force: bool = False) -> dict:
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        max_bytes = int(float(max_output_gb) * 1024 ** 3)
        plan = self.plan_size_limited_split(max_bytes)
        # Validate every planned part before writing any output, so a mismatched or
        # previously split bundle cannot leave a partial output set on disk.
        for part in plan["parts"]:
            intervals = _heka_merge_intervals(self._trace_intervals_for_indices(set(part["selected_traces"])))
            self._validate_split_offsets(intervals)
        stem = PSSessionParser._sanitize_filename(Path(self.source_path or "heka_bundle").stem)
        rows = []
        for idx, part in enumerate(plan["parts"], start=1):
            units = part["units"]
            kind = part["unit_kind"]
            if units:
                unit_label = f"{kind}{min(units)+1:03d}-{max(units)+1:03d}"
            else:
                unit_label = f"{kind}NONE"
            out_path = output_dir / f"{stem}_part{idx:03d}_{unit_label}.dat"
            info = self._write_split_bundle(out_path, set(part["selected_traces"]), force=force)
            info.update({
                "part": idx,
                "unit_kind": kind,
                "units_1based": ",".join(str(u + 1) for u in units),
                "estimated_size_bytes": part["estimated_size_bytes"],
                "estimated_size_MiB": round(part["estimated_size_bytes"] / 1024 / 1024, 6),
            })
            rows.append(info)
        report = output_dir / f"{stem}_heka_split_report.csv"
        _heka_write_csv(report, rows)
        return {"plan": plan, "report": str(report), "rows": rows}


# ---- HEKA v13 enhancements: scan/point inference + photo sequence support ----
HEKA_IMAGE_EXTS = {".jpg", ".jpeg", ".png", ".tif", ".tiff", ".bmp", ".webp"}
HEKA_PHOTO_MAX_ORIGINAL_BYTES_IN_NPY = 300 * 1024 * 1024
HEKA_PHOTO_THUMB_MAX_DIM = 256


def _heka_v13_nat_key(path: Path):
    parts = re.split(r"(\d+)", Path(path).name.lower())
    return [int(p) if p.isdigit() else p for p in parts]


def _heka_v13_last_int(text: str):
    nums = re.findall(r"(?<!\d)(\d+)(?!\d)", str(text))
    return int(nums[-1]) if nums else None


def _heka_v13_xy_from_name(name: str):
    s = Path(str(name)).stem.lower()
    patterns = [
        r"x[-_ ]*(\d+).*?y[-_ ]*(\d+)",
        r"y[-_ ]*(\d+).*?x[-_ ]*(\d+)",
        r"row[-_ ]*(\d+).*?col[-_ ]*(\d+)",
        r"r[-_ ]*(\d+).*?c[-_ ]*(\d+)",
    ]
    for pat in patterns:
        m = re.search(pat, s)
        if not m:
            continue
        a, b = int(m.group(1)), int(m.group(2))
        if pat.startswith("y"):
            return {"x_index": b, "y_index": a}
        if "row" in pat or pat.startswith("r"):
            return {"x_index": b, "y_index": a}
        return {"x_index": a, "y_index": b}
    return None


def _heka_v13_init(self, *args, **kwargs):
    _HEKA_V13_ORIGINAL_INIT(self, *args, **kwargs)
    self.image_files = []
    self.image_manifest = []
    self.photo_summary = {}
    self.scan_inference = {}


def _heka_v13_photo_base_dir(self):
    try:
        if self.mode == "loose" and self.loose_base is not None:
            return self.loose_base.parent
        if self.mode == "bundle" and self.bundle_path is not None:
            return self.bundle_path.parent
        if self.source_path:
            p = Path(str(self.source_path))
            if p.exists():
                return p.parent if p.is_file() else p
    except Exception:
        return None
    return None


def _heka_v13_discover_photo_sequence(self):
    base_dir = _heka_v13_photo_base_dir(self)
    self.image_files = []
    self.image_manifest = []
    self.photo_summary = {"n_images": 0, "base_dir": str(base_dir) if base_dir else "", "image_order_method": "none"}
    if not base_dir or not Path(base_dir).exists():
        return
    try:
        direct = [p for p in Path(base_dir).iterdir() if p.is_file() and p.suffix.lower() in HEKA_IMAGE_EXTS]
        # Prefer same-folder images.  If no same-folder images exist, look one level down.
        if direct:
            candidates = direct
            scope = "same_folder"
        else:
            candidates = []
            for child in Path(base_dir).iterdir():
                if child.is_dir():
                    candidates.extend([p for p in child.iterdir() if p.is_file() and p.suffix.lower() in HEKA_IMAGE_EXTS])
            scope = "one_level_subfolders"
        candidates = sorted(set(candidates), key=_heka_v13_nat_key)
        if not candidates:
            return
        numbered = [_heka_v13_last_int(p.stem) for p in candidates]
        if sum(n is not None for n in numbered) >= max(1, int(0.7 * len(candidates))):
            candidates = sorted(candidates, key=lambda p: (_heka_v13_last_int(p.stem) is None, _heka_v13_last_int(p.stem) or 10**18, _heka_v13_nat_key(p)))
            order_method = "numeric filename order"
        else:
            candidates = sorted(candidates, key=lambda p: (p.stat().st_mtime, _heka_v13_nat_key(p)))
            order_method = "file modified-time order"
        rows = []
        for idx, p in enumerate(candidates, start=1):
            st = p.stat()
            row = {
                "photo_index": idx,
                "filename": p.name,
                "path": str(p),
                "relative_path": str(p.relative_to(base_dir)).replace("\\", "/") if str(p).startswith(str(base_dir)) else p.name,
                "size_bytes": int(st.st_size),
                "modified_time": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
                "numeric_index_from_filename": _heka_v13_last_int(p.stem) if _heka_v13_last_int(p.stem) is not None else "",
            }
            xy = _heka_v13_xy_from_name(p.name)
            if xy:
                row.update(xy)
            try:
                from PIL import Image
                with Image.open(p) as im:
                    row["width_px"] = int(im.width)
                    row["height_px"] = int(im.height)
                    row["image_mode"] = str(im.mode)
            except Exception as exc:
                row["image_read_note"] = f"PIL header read failed: {exc}"
            rows.append(row)
        xvals = {r.get("x_index") for r in rows if r.get("x_index") not in (None, "")}
        yvals = {r.get("y_index") for r in rows if r.get("y_index") not in (None, "")}
        self.image_files = candidates
        self.image_manifest = rows
        self.photo_summary = {
            "n_images": len(rows),
            "base_dir": str(base_dir),
            "search_scope": scope,
            "image_order_method": order_method,
            "first_image": rows[0].get("filename") if rows else "",
            "last_image": rows[-1].get("filename") if rows else "",
            "total_image_bytes": int(sum(r.get("size_bytes", 0) for r in rows)),
            "has_xy_indices_in_names": bool(xvals and yvals),
            "unique_x_indices": len(xvals),
            "unique_y_indices": len(yvals),
        }
    except Exception as exc:
        self.photo_summary = {"n_images": 0, "base_dir": str(base_dir), "photo_discovery_error": str(exc)}
        self.notes.append(f"Photo sequence discovery skipped: {exc}")


def _heka_v13_measurement_point_count(self):
    n_blocks = len(getattr(self, "blocks", []) or [])
    n_cv = len(getattr(self, "cv_pairs", []) or [])
    n_eis_groups = len(getattr(self, "eis_groups", []) or [])
    n_images = len(getattr(self, "image_manifest", []) or [])
    # For EIS line scans, repeated HEKA blocks are the true positions.
    # For mixed CV+EIS files where EIS appears in a single block but CV pairs repeat,
    # the CV pair count is a better point count than the one-block tree wrapper.
    if n_eis_groups and n_blocks > 1:
        base = n_blocks
    elif n_cv:
        base = max(n_cv, n_blocks)
    else:
        base = n_blocks if n_blocks else len(getattr(self, "traces", []) or [])
    return max(base, n_images)


def _heka_v13_infer_scan_geometry(self):
    n_blocks = len(getattr(self, "blocks", []) or [])
    n_cv = len(getattr(self, "cv_pairs", []) or [])
    n_eis_groups = len(getattr(self, "eis_groups", []) or [])
    n_images = len(getattr(self, "image_manifest", []) or [])
    n_points = _heka_v13_measurement_point_count(self)
    total_trace_points = int(sum(int(t.n_points) for t in getattr(self, "traces", []) or []))
    total_trace_bytes = int(sum(int(t.nbytes) for t in getattr(self, "traces", []) or []))
    evidence = []
    confidence = "medium"
    img_rows = getattr(self, "image_manifest", []) or []
    xvals = sorted({r.get("x_index") for r in img_rows if r.get("x_index") not in (None, "")})
    yvals = sorted({r.get("y_index") for r in img_rows if r.get("y_index") not in (None, "")})
    numeric_ids = [r.get("numeric_index_from_filename") for r in img_rows if r.get("numeric_index_from_filename") not in (None, "")]
    method_text = "\n".join(str(e.get("raw_text", "")) for e in getattr(self, "method_entries", []) or [])
    text_lower = method_text.lower()
    if n_images:
        evidence.append(f"found {n_images} same-folder microscope/photo images")
    if n_eis_groups:
        evidence.append(f"found {n_eis_groups} EIS groups across {n_blocks} inferred HEKA blocks/positions")
    if n_cv:
        evidence.append(f"found {n_cv} CV current-potential pairs")
    if xvals and yvals and len(xvals) > 1 and len(yvals) > 1:
        scan_type = "XY scan/grid"
        confidence = "high"
        evidence.append(f"image filenames contain X/Y or row/column indices: {len(xvals)} × {len(yvals)} grid candidates")
    elif "xy" in text_lower or ("x" in text_lower and "y" in text_lower and ("stage" in text_lower or "scan" in text_lower)):
        scan_type = "possible XY scan/grid"
        confidence = "medium"
        evidence.append("method text contains X/Y scan-like terms")
    elif n_points <= 1:
        scan_type = "single point / single experiment"
        confidence = "high"
    elif n_images and numeric_ids and len(set(numeric_ids)) >= max(2, int(0.7 * n_images)):
        scan_type = "line scan / ordered point scan"
        confidence = "high"
        evidence.append("photo filenames contain a one-dimensional numeric sequence")
    elif n_eis_groups and n_blocks > 1:
        scan_type = "line scan / ordered block sequence"
        confidence = "medium"
        evidence.append("multiple repeated HEKA blocks/positions but no X/Y coordinate metadata was decoded")
    elif n_cv > 1:
        scan_type = "line scan / ordered CV point sequence"
        confidence = "medium"
        evidence.append("multiple CV pairs but no X/Y coordinate metadata was decoded")
    else:
        scan_type = "multi-point scan, geometry unclear"
        confidence = "low"
    if n_images and n_points:
        if n_images == n_points:
            evidence.append("photo count matches inferred measurement-point count")
        else:
            evidence.append(f"photo count ({n_images}) does not exactly match inferred measurement-point count ({n_points})")
    return {
        "scan_type": scan_type,
        "scan_confidence": confidence,
        "evidence": evidence,
        "n_inferred_measurement_points": int(n_points),
        "n_heka_blocks_or_positions": int(n_blocks),
        "n_cv_pairs": int(n_cv),
        "n_eis_groups": int(n_eis_groups),
        "n_photos": int(n_images),
        "total_trace_data_points": total_trace_points,
        "total_trace_data_bytes": total_trace_bytes,
        "total_trace_data_MiB": round(total_trace_bytes / 1024 / 1024, 6),
    }


def _heka_v13_analyze(self):
    _HEKA_V13_ORIGINAL_ANALYZE(self)
    _heka_v13_discover_photo_sequence(self)
    self.scan_inference = _heka_v13_infer_scan_geometry(self)
    # Rebuild detail/metadata so the GUI and exported summaries include the v13 fields.
    _HEKA_V13_ORIGINAL_BUILD_DETAIL_SUMMARY(self)
    self.scan_inference = _heka_v13_infer_scan_geometry(self)
    self.detail_summary["scan_inference"] = self.scan_inference
    self.detail_summary["photo_summary"] = self.photo_summary
    self.detail_summary["n_inferred_measurement_points"] = self.scan_inference.get("n_inferred_measurement_points")
    self.detail_summary["total_trace_data_points"] = self.scan_inference.get("total_trace_data_points")
    self.detail_summary["total_trace_data_MiB"] = self.scan_inference.get("total_trace_data_MiB")
    self.detail_summary["scan_type"] = self.scan_inference.get("scan_type")
    self.detail_summary["scan_confidence"] = self.scan_inference.get("scan_confidence")
    _HEKA_V13_ORIGINAL_BUILD_METADATA(self)
    self.metadata["scan_inference"] = self.scan_inference
    self.metadata["photo_summary"] = self.photo_summary
    self.metadata["n_photos"] = len(getattr(self, "image_manifest", []) or [])
    self.session["metadata"] = self.metadata


def _heka_v13_position_rows(self):
    rows = _HEKA_V13_ORIGINAL_POSITION_ROWS(self)
    for row in rows:
        try:
            bi = int(row.get("position_or_block", 0)) - 1
            if 0 <= bi < len(self.blocks):
                pts = int(sum(int(self.traces[i].n_points) for i in self.blocks[bi].trace_indices))
                row["total_trace_points_in_block"] = pts
                row["total_trace_points_in_block_Mpoints"] = round(pts / 1_000_000, 6)
                if len(getattr(self, "image_manifest", []) or []) == len(rows):
                    im = self.image_manifest[bi]
                    row["matched_photo"] = im.get("filename", "")
                    row["matched_photo_index"] = im.get("photo_index", "")
        except Exception:
            pass
        row["scan_type"] = (getattr(self, "scan_inference", {}) or {}).get("scan_type", "")
    return rows


def _heka_v13_cv_summary_rows(self):
    rows = _HEKA_V13_ORIGINAL_CV_SUMMARY_ROWS(self)
    imgs = getattr(self, "image_manifest", []) or []
    if imgs and len(imgs) == len(rows):
        for row, im in zip(rows, imgs):
            row["matched_photo"] = im.get("filename", "")
            row["matched_photo_index"] = im.get("photo_index", "")
    for row in rows:
        row["scan_type"] = (getattr(self, "scan_inference", {}) or {}).get("scan_type", "")
    return rows


def _heka_v13_summarize(self):
    s = _HEKA_V13_ORIGINAL_SUMMARIZE(self)
    ds = s.get("heka_detail_summary") or {}
    scan = getattr(self, "scan_inference", {}) or ds.get("scan_inference") or {}
    photos = getattr(self, "photo_summary", {}) or ds.get("photo_summary") or {}
    s["heka_scan_inference"] = scan
    s["heka_photo_summary"] = photos
    s["n_measurements"] = int(scan.get("n_inferred_measurement_points") or s.get("n_measurements") or 0)
    # For CV-only point/line scans, display one row per CV pair rather than one giant generic block.
    if getattr(self, "cv_pairs", None) and not getattr(self, "eis_groups", None) and len(self.cv_pairs) > 1:
        rows = []
        for r in self._cv_summary_rows():
            extras = []
            if r.get("scan_rate"):
                extras.append(f"scan={r.get('scan_rate')}")
            if r.get("potential_range"):
                extras.append(f"E={r.get('potential_range')}")
            if r.get("current_range"):
                extras.append(f"I={r.get('current_range')}")
            if r.get("matched_photo"):
                extras.append(f"photo={r.get('matched_photo')}")
            rows.append({
                "index": r.get("cv_pair"),
                "title": f"HEKA CV point/pair {r.get('cv_pair')}",
                "method_id": "CV",
                "technique": "CV",
                "n_curves": 2,
                "n_eis_blocks": 0,
                "n_points": r.get("n_points"),
                "status": "FULL",
                "scan_type": scan.get("scan_type", ""),
                "frequency_range": "",
                "scan_rate": r.get("scan_rate", ""),
                "ac_amplitude": "",
                "potential_range": r.get("potential_range", ""),
                "current_range": r.get("current_range", ""),
                "z_range": "",
                "matched_photo": r.get("matched_photo", ""),
                "details_text": "; ".join(extras),
            })
        s["measurement_rows"] = rows
    else:
        # Add point totals and scan type to existing block rows.
        rows = s.get("measurement_rows", [])
        for row in rows:
            row["scan_type"] = scan.get("scan_type", "")
            try:
                bi = int(row.get("index", 0)) - 1
                if 0 <= bi < len(self.blocks):
                    row["n_points"] = int(sum(int(self.traces[i].n_points) for i in self.blocks[bi].trace_indices))
            except Exception:
                pass
        s["measurement_rows"] = rows
    return s


def _heka_v13_photo_payload(self):
    manifest = list(getattr(self, "image_manifest", []) or [])
    files = list(getattr(self, "image_files", []) or [])
    payload = {
        "format": "heka-photo-sequence-v1",
        "summary": getattr(self, "photo_summary", {}) or {},
        "manifest": manifest,
        "images": [],
        "note": "Original compressed image bytes are included when total image size is below the safety limit; thumbnails are included when PIL can read the image.",
    }
    if not files:
        return payload
    total = int(sum(p.stat().st_size for p in files if p.exists()))
    include_original = total <= HEKA_PHOTO_MAX_ORIGINAL_BYTES_IN_NPY
    if not include_original:
        payload["original_bytes_note"] = f"Skipped original image bytes because total photo size {total:,} bytes exceeds limit {HEKA_PHOTO_MAX_ORIGINAL_BYTES_IN_NPY:,} bytes. Filenames/metadata and thumbnails are still included."
    for row, p in zip(manifest, files):
        item = {"photo_index": row.get("photo_index"), "filename": row.get("filename"), "relative_path": row.get("relative_path"), "size_bytes": row.get("size_bytes")}
        if include_original:
            try:
                item["original_file_bytes_uint8"] = np.frombuffer(p.read_bytes(), dtype=np.uint8).copy()
            except Exception as exc:
                item["original_bytes_error"] = str(exc)
        try:
            from PIL import Image
            with Image.open(p) as im:
                im = im.convert("RGB")
                im.thumbnail((HEKA_PHOTO_THUMB_MAX_DIM, HEKA_PHOTO_THUMB_MAX_DIM))
                item["thumbnail_rgb_uint8"] = np.asarray(im, dtype=np.uint8)
                item["thumbnail_shape"] = tuple(item["thumbnail_rgb_uint8"].shape)
        except Exception as exc:
            item["thumbnail_error"] = str(exc)
        payload["images"].append(item)
    return payload


def _heka_v13_native_numeric_payload(self):
    payload = _HEKA_V13_ORIGINAL_NATIVE_PAYLOAD(self)
    payload["scan_inference"] = getattr(self, "scan_inference", {}) or {}
    payload["photo_sequence"] = _heka_v13_photo_payload(self)
    return payload


def _heka_v13_export_photo_sequence(self, output_dir: Path, safe: str) -> dict:
    output_dir = Path(output_dir)
    files = []
    skipped = []
    csv_entries = []
    if not getattr(self, "image_manifest", None):
        return {"files": files, "skipped_entries": skipped, "csv_entries": csv_entries}
    manifest_path = output_dir / f"{safe}_heka_photo_manifest.csv"
    try:
        _heka_write_csv(manifest_path, self.image_manifest)
        files.append(str(manifest_path))
        csv_entries.append({
            "relative_csv_path": manifest_path.name,
            "technique": "HEKA-photo",
            "curve_title": "HEKA associated photo sequence manifest",
            "n_points": len(self.image_manifest),
            "x_label": "photo_index",
            "x_unit": "",
            "y_label": "image file",
            "y_unit": "",
            "method_id": "HEKA-photo",
        })
    except Exception as exc:
        skipped.append({"reason": f"Photo manifest export failed: {exc}"})
    try:
        from PIL import Image, ImageDraw
        frames = []
        max_dim = 960
        for row, p in zip(self.image_manifest, self.image_files):
            try:
                with Image.open(p) as im:
                    im = im.convert("RGB")
                    im.thumbnail((max_dim, max_dim))
                    canvas = Image.new("RGB", (max_dim, max_dim), (0, 0, 0))
                    x = (max_dim - im.width) // 2
                    y = (max_dim - im.height) // 2
                    canvas.paste(im, (x, y))
                    draw = ImageDraw.Draw(canvas)
                    label = f"{row.get('photo_index')}: {row.get('filename')}"
                    draw.rectangle((0, 0, max_dim, 28), fill=(0, 0, 0))
                    draw.text((8, 8), label[:120], fill=(255, 255, 255))
                    frames.append(canvas)
            except Exception as exc:
                skipped.append({"reason": f"Photo frame skipped for {p.name}: {exc}"})
        if frames:
            gif_path = output_dir / f"{safe}_heka_photo_sequence.gif"
            frames[0].save(gif_path, save_all=True, append_images=frames[1:], duration=250, loop=0, optimize=True)
            files.append(str(gif_path))
    except Exception as exc:
        skipped.append({"reason": f"Photo GIF export skipped: {exc}"})
    return {"files": files, "skipped_entries": skipped, "csv_entries": csv_entries}


def _heka_v13_export_analysis_ready_outputs(self, output_dir: Path, base_name: str) -> dict:
    info = _HEKA_V13_ORIGINAL_EXPORT_ANALYSIS(self, output_dir, base_name)
    safe = PSSessionParser._sanitize_filename(base_name)
    photo_info = _heka_v13_export_photo_sequence(self, Path(output_dir), safe)
    info.setdefault("files", []).extend(photo_info.get("files", []))
    info.setdefault("skipped_entries", []).extend(photo_info.get("skipped_entries", []))
    info.setdefault("csv_entries", []).extend(photo_info.get("csv_entries", []))
    info["n_csv_files"] = int(info.get("n_csv_files", 0)) + sum(1 for f in photo_info.get("files", []) if str(f).lower().endswith(".csv"))
    return info


