_HEKA_V13_ORIGINAL_SUMMARIZE = HEKAPotmasterParser.summarize
_HEKA_V13_ORIGINAL_NATIVE_PAYLOAD = HEKAPotmasterParser.native_numeric_payload
_HEKA_V13_ORIGINAL_EXPORT_ANALYSIS = HEKAPotmasterParser.export_analysis_ready_outputs
HEKAPotmasterParser.__init__ = _heka_v13_init
