# ---- End HEKA POTMASTER / PATCHMASTER DAT2 parser and splitter ----


class PSSessionCollection:
    def __init__(self):
        self.mode = None
        self.source_path = None
        self.entries = []

    @staticmethod
    def _normalize_entry_name(entry_name: str) -> str:
        return str(PurePosixPath(str(entry_name).replace("\\", "/")))

    @classmethod
    def _drop_common_root(cls, names):
        parts_list = [PurePosixPath(cls._normalize_entry_name(n)).parts for n in names]
        if not parts_list:
            return names
        first = parts_list[0][0] if parts_list[0] else None
        if not first:
            return names
        if all(parts and parts[0] == first for parts in parts_list):
            return [str(PurePosixPath(*parts[1:])) for parts in parts_list]
        return names

    @classmethod
    def _build_path_metadata(cls, entry_name: str, virtual_source: str, mode: str, root_source_path: str) -> dict:
        normalized_entry_name = cls._normalize_entry_name(entry_name)
        parts = [p for p in PurePosixPath(normalized_entry_name).parts if p not in ("", ".")]
        if mode == "single":
            source_file = Path(virtual_source)
            basename = source_file.name
            relative_path = basename
            folder_parts = []
        else:
            basename = parts[-1] if parts else Path(normalized_entry_name).name
            relative_path = normalized_entry_name
            folder_parts = parts[:-1]
        immediate_parent_folder = folder_parts[-1] if folder_parts else ""
        return {
            "collection_mode": mode,
            "root_source_path": root_source_path,
            "virtual_source": virtual_source,
            "entry_name": entry_name,
            "relative_path": relative_path,
            "basename": basename,
            "folder_parts": folder_parts,
            "folder_hierarchy": "/".join(folder_parts),
            "subfolder_names": folder_parts,
            "immediate_parent_folder": immediate_parent_folder,
        }

    def load(self, path: str):
        self.entries = []
        self.source_path = path
        source = Path(path)
        if source.is_dir():
            self.mode = "directory"
            self._load_directory(path)
        elif source.suffix.lower() == ".zip":
            self.mode = "zip"
            self._load_zip(path)
        else:
            self.mode = "single"
            if source.suffix.lower() in HEKA_SUPPORT_EXTS and HEKAPotmasterParser.can_open_path(source):
                parser = HEKAPotmasterParser()
            elif source.suffix.lower() == '.par':
                parser = VersaStudioParser()
            elif source.suffix.lower() in {'.cor', '.z'}:
                parser = SolartronParser()
            elif source.suffix.lower() in {'.mpr', '.mps', '.mgr'}:
                parser = BioLogicParser()
            else:
                parser = PSSessionParser()
            parser.load(path)
            self.entries.append({
                "entry_name": source.name,
                "virtual_source": path,
                "parser": parser,
            })
        for entry in self.entries:
            entry["path_metadata"] = self._build_path_metadata(
                entry["entry_name"], entry["virtual_source"], self.mode, self.source_path
            )
        return self

    def _load_zip(self, zip_path: str):
        with zipfile.ZipFile(zip_path, "r") as zf:
            names = sorted([n for n in zf.namelist() if n.lower().endswith((".pssession", ".dat", ".cor", ".z", ".mpr", ".mps", ".mgr"))])
            if not names:
                raise RuntimeError("ZIP loading supports PalmSens .pssession, bundled HEKA DAT2 .dat, Solartron .cor/.z, and BioLogic .mpr/.mps/.mgr entries. For VersaStudio or loose HEKA support files, load a folder directly.")
            # Collapse BioLogic companion triplets into one logical entry
            selected = []
            seen_bio = set()
            for n in names:
                low = n.lower()
                if low.endswith(('.mpr', '.mps', '.mgr')):
                    key = (str(PurePosixPath(n).parent), BioLogicParser._norm_key(PurePosixPath(n).name))
                    if key in seen_bio:
                        continue
                    seen_bio.add(key)
                    # prefer .mpr, else .mps, else .mgr
                    group = BioLogicParser._pair_from_zip(zf, n)
                    chosen = group.get('mpr') or group.get('mps') or group.get('mgr')
                    if chosen:
                        selected.append(chosen)
                else:
                    selected.append(n)
            display_names = self._drop_common_root(selected)
            for raw_name, disp_name in zip(selected, display_names):
                low = raw_name.lower()
                if low.endswith('.dat'):
                    data = zf.read(raw_name)
                    if data[:4] == b'DAT2':
                        parser = HEKAPotmasterParser()
                        parser.load_from_bytes(data, f"{zip_path}::{raw_name}")
                    else:
                        continue
                elif low.endswith('.pssession'):
                    parser = PSSessionParser()
                    parser.load_from_bytes(zf.read(raw_name), f"{zip_path}::{raw_name}")
                elif low.endswith(('.cor', '.z')):
                    parser = SolartronParser()
                    parser.load_from_bytes(zf.read(raw_name), f"{zip_path}::{raw_name}")
                else:
                    parser = BioLogicParser()
                    parser.load_from_zip(zf, raw_name, zip_path)
                self.entries.append({
                    "entry_name": disp_name,
                    "virtual_source": f"{zip_path}::{raw_name}",
                    "parser": parser,
                })

    def _load_directory(self, dir_path: str):
        root = Path(dir_path)
        paths = sorted([p for p in root.rglob("*") if p.is_file() and p.suffix.lower() in {".pssession", ".dat", ".pul", ".pgf", ".amp", ".mrk", ".mth", ".onl", ".par", ".cor", ".z", ".mpr", ".mps", ".mgr"}])
        if not paths:
            raise RuntimeError("No .pssession, HEKA .dat/.pul support files, VersaStudio .par, Solartron .cor/.z, or BioLogic .mpr/.mps/.mgr files found inside the selected folder.")
        selected = []
        seen_heka = set()
        seen_bio = set()
        for p in paths:
            suf = p.suffix.lower()
            if suf in HEKA_SUPPORT_EXTS and HEKAPotmasterParser.can_open_path(p):
                key = (str(p.parent), p.with_suffix('').name)
                if key in seen_heka:
                    continue
                seen_heka.add(key)
                group = HEKAPotmasterParser._siblings_for(p)
                chosen = group.get('.dat') or group.get('.pul') or p
                selected.append(chosen)
            elif suf in {'.mpr', '.mps', '.mgr'}:
                key = (str(p.parent), BioLogicParser._norm_key(p.name))
                if key in seen_bio:
                    continue
                seen_bio.add(key)
                group = BioLogicParser._pair_from_directory(str(p))
                chosen = group.get('mpr') or group.get('mps') or group.get('mgr')
                if chosen is not None:
                    selected.append(chosen)
            else:
                selected.append(p)
        for p in selected:
            if p.suffix.lower() in HEKA_SUPPORT_EXTS and HEKAPotmasterParser.can_open_path(p):
                parser = HEKAPotmasterParser()
            elif p.suffix.lower() == '.par':
                parser = VersaStudioParser()
            elif p.suffix.lower() in {'.cor', '.z'}:
                parser = SolartronParser()
            elif p.suffix.lower() in {'.mpr', '.mps', '.mgr'}:
                parser = BioLogicParser()
            else:
                parser = PSSessionParser()
            parser.load(str(p))
            rel_name = str(p.relative_to(root)).replace("\\", "/")
            self.entries.append({
                "entry_name": rel_name,
                "virtual_source": str(p),
                "parser": parser,
            })

    def _build_path_index(self) -> dict:
        out = {}
        for idx, entry in enumerate(self.entries, start=1):
            path_id = f"p{idx:04d}"
            entry["path_id"] = path_id
            meta = entry["path_metadata"]
            out[path_id] = {
                "relative_path": meta.get("relative_path"),
                "basename": meta.get("basename"),
                "immediate_parent_folder": meta.get("immediate_parent_folder"),
                "folder_hierarchy": meta.get("folder_hierarchy"),
                "subfolder_names": meta.get("subfolder_names", []),
                "collection_mode": meta.get("collection_mode"),
            }
        return out

    def unique_subfolders(self):
        seen = set()
        out = []
        for entry in self.entries:
            for part in entry.get("path_metadata", {}).get("subfolder_names", []):
                part = str(part).strip()
                if part and part not in seen:
                    seen.add(part)
                    out.append(part)
        return out

    def summarize(self) -> dict:
        if not self.entries:
            raise RuntimeError("No session loaded.")
        if self.mode == "single":
            return self.entries[0]["parser"].summarize()
        entry_summaries = []
        aggregate = Counter()
        total_measurements = 0
        for idx, entry in enumerate(self.entries, start=1):
            s = entry["parser"].summarize()
            total_measurements += s.get("n_measurements", 0)
            aggregate.update(s.get("technique_counts", {}))
            entry_summaries.append({
                "index": idx,
                "entry_name": entry["entry_name"],
                "path_metadata": entry["path_metadata"],
                "n_measurements": s.get("n_measurements"),
                "technique_counts": s.get("technique_counts", {}),
            })
        return {
            "source_file": self.source_path,
            "mode": self.mode,
            "n_entries": len(self.entries),
            "n_total_measurements": total_measurements,
            "aggregate_technique_counts": dict(aggregate),
            "entry_summaries": entry_summaries,
        }

    def build_parsed_npy_bundle(self, experimental_description: str) -> dict:
        if not self.entries:
            raise RuntimeError("No session loaded.")
        description = experimental_description.strip()
        path_index = self._build_path_index()
        aggregate = Counter()
        total_measurements = 0
        entries_out = []
        for idx, entry in enumerate(self.entries, start=1):
            parser = entry['parser']
            compact = parser.build_compact_summary()
            total_measurements += compact.get('n_measurements', 0)
            aggregate.update(compact.get('technique_counts', {}))
            meta = path_index[entry['path_id']]
            if hasattr(parser, 'native_numeric_payload'):
                numeric_payload = parser.native_numeric_payload()
            else:
                numeric_payload = parser.primary_numeric_payload()
            entries_out.append({
                'entry_id': f"e{idx:04d}",
                'path_id': entry['path_id'],
                'relative_path': meta.get('relative_path'),
                'basename': meta.get('basename'),
                'immediate_parent_folder': meta.get('immediate_parent_folder'),
                'folder_hierarchy': meta.get('folder_hierarchy'),
                'subfolder_names': meta.get('subfolder_names', []),
                'summary': compact,
                'numeric_payload': numeric_payload,
            })
        return {
            'format': 'electrochemistry-parsed-bundle-v2',
            'created': datetime.now().isoformat(timespec='seconds'),
            'source_file': self.source_path,
            'mode': self.mode,
            'experimental_description': description,
            'path_index': path_index,
            'collection_summary': {
                'source_file': self.source_path,
                'mode': self.mode,
                'n_entries': len(self.entries),
                'n_total_measurements': total_measurements,
                'aggregate_technique_counts': dict(aggregate),
            },
            'entries': entries_out,
        }

    def build_npy_record_list(self, experimental_description: str) -> list:
        if not self.entries:
            raise RuntimeError("No session loaded.")
        description = experimental_description.strip()
        path_index = self._build_path_index()
        aggregate = Counter()
        total_measurements = 0
        records = []
        for idx, entry in enumerate(self.entries, start=1):
            compact = entry["parser"].build_compact_summary()
            total_measurements += compact.get("n_measurements", 0)
            aggregate.update(compact.get("technique_counts", {}))
            meta = path_index[entry["path_id"]]
            records.append({
                "record_type": "entry",
                "entry_id": f"e{idx:04d}",
                "path_id": entry["path_id"],
                "relative_path": meta.get("relative_path"),
                "basename": meta.get("basename"),
                "immediate_parent_folder": meta.get("immediate_parent_folder"),
                "folder_hierarchy": meta.get("folder_hierarchy"),
                "subfolder_names": meta.get("subfolder_names", []),
                "summary": compact,
                "session_json": entry["parser"].session_minified_json(),
            })
        header = {
            "record_type": "header",
            "npy_format": "gzip-utf8-jsonl-v1",
            "created": datetime.now().isoformat(timespec="seconds"),
            "source_file": self.source_path,
            "mode": self.mode,
            "experimental_description": description,
            "path_index": path_index,
            "collection_summary": {
                "source_file": self.source_path,
                "mode": self.mode,
                "n_entries": len(self.entries),
                "n_total_measurements": total_measurements,
                "aggregate_technique_counts": dict(aggregate),
            },
        }
        return [header] + records

    def build_summary_json(self, experimental_description: str) -> dict:
        if not self.entries:
            raise RuntimeError("No session loaded.")
        description = experimental_description.strip()
        path_index = self._build_path_index()
        aggregate = Counter()
        total_measurements = 0
        entries = []
        for idx, entry in enumerate(self.entries, start=1):
            compact = entry["parser"].build_compact_summary()
            total_measurements += compact.get("n_measurements", 0)
            aggregate.update(compact.get("technique_counts", {}))
            entries.append({
                "entry_id": f"e{idx:04d}",
                "path_id": entry["path_id"],
                "summary": compact,
            })
        return {
            "created": datetime.now().isoformat(timespec="seconds"),
            "source_file": self.source_path,
            "mode": self.mode,
            "experimental_description": description,
            "subfolder_list": self.unique_subfolders(),
            "path_index": path_index,
            "collection_summary": {
                "source_file": self.source_path,
                "mode": self.mode,
                "n_entries": len(self.entries),
                "n_total_measurements": total_measurements,
                "aggregate_technique_counts": dict(aggregate),
            },
            "entries": entries,
        }

    def export_analysis_ready_csv(self, output_dir: Path, base_name: str) -> dict:
        analysis_root = output_dir / f"{base_name}_analysis_ready_csv"
        analysis_root.mkdir(parents=True, exist_ok=True)
        manifest_path = output_dir / f"{base_name}_analysis_ready_manifest.json"

        csv_entries = []
        skipped_entries = []
        total_csv = 0

        for entry_idx, entry in enumerate(self.entries, start=1):
            meta = entry["path_metadata"]
            rel_dir = Path(*meta.get("subfolder_names", [])) if meta.get("subfolder_names") else Path()
            target_dir = analysis_root / rel_dir
            target_dir.mkdir(parents=True, exist_ok=True)

            stem = Path(meta.get("basename", f"entry_{entry_idx}")).stem
            parser = entry["parser"]
            exported_here = 0
            if hasattr(parser, "export_analysis_ready_outputs"):
                custom_info = parser.export_analysis_ready_outputs(target_dir, stem)
                for ce in custom_info.get("csv_entries", []):
                    ce = dict(ce)
                    ce.setdefault("entry_id", f"e{entry_idx:04d}")
                    ce.setdefault("relative_source_path", meta.get("relative_path"))
                    ce["relative_csv_path"] = str((target_dir / ce.get("relative_csv_path", "")).relative_to(analysis_root)).replace("\\", "/") if ce.get("relative_csv_path") else ""
                    ce.setdefault("subfolder_names", meta.get("subfolder_names", []))
                    ce.setdefault("immediate_parent_folder", meta.get("immediate_parent_folder"))
                    ce.setdefault("measurement_index", "")
                    ce.setdefault("curve_index", "")
                    ce.setdefault("measurement_title", "")
                    ce.setdefault("scan_rate", "")
                    csv_entries.append(ce)
                for se in custom_info.get("skipped_entries", []):
                    skipped_entries.append({"entry_id": f"e{entry_idx:04d}", "relative_source_path": meta.get("relative_path"), **dict(se)})
                total_csv += int(custom_info.get("n_csv_files", 0))
                exported_here += int(custom_info.get("n_csv_files", 0))
            for curve in parser.iter_primary_curve_exports():
                fname = (
                    f"{PSSessionParser._sanitize_filename(stem)}"
                    f"__m{curve['measurement_index']:03d}"
                    f"__c{curve['curve_index']:03d}"
                    f"__{PSSessionParser._sanitize_filename(curve['curve_title'])}.csv"
                )
                out_path = target_dir / fname
                with open(out_path, "w", encoding="utf-8", newline="") as f:
                    writer = csv.writer(f)
                    for x, y in curve["rows"]:
                        writer.writerow([x, y])
                csv_entries.append({
                    "entry_id": f"e{entry_idx:04d}",
                    "relative_source_path": meta.get("relative_path"),
                    "relative_csv_path": str(out_path.relative_to(analysis_root)).replace("\\", "/"),
                    "subfolder_names": meta.get("subfolder_names", []),
                    "immediate_parent_folder": meta.get("immediate_parent_folder"),
                    "measurement_index": curve["measurement_index"],
                    "curve_index": curve["curve_index"],
                    "measurement_title": curve["measurement_title"],
                    "curve_title": curve["curve_title"],
                    "method_id": curve["method_id"],
                    "technique": curve["technique"],
                    "scan_rate": curve["scan_rate"],
                    "x_label": curve["x_label"],
                    "x_unit": curve["x_unit"],
                    "y_label": curve["y_label"],
                    "y_unit": curve["y_unit"],
                    "n_points": len(curve["rows"]),
                })
                exported_here += 1
                total_csv += 1
            if exported_here == 0:
                skipped_entries.append({
                    "entry_id": f"e{entry_idx:04d}",
                    "relative_source_path": meta.get("relative_path"),
                    "reason": "No primary x/y current-bearing curves found for CSV export.",
                })

        manifest = {
            "created": datetime.now().isoformat(timespec="seconds"),
            "source_file": str(self.source_path) if self.source_path is not None else "",
            "mode": self.mode,
            "analysis_ready_root": str(analysis_root),
            "n_csv_files": total_csv,
            "subfolder_list": self.unique_subfolders(),
            "csv_entries": csv_entries,
            "skipped_entries": skipped_entries,
        }
        with open(manifest_path, "w", encoding="utf-8") as f:
            json.dump(manifest, f, ensure_ascii=False, separators=(",", ":"))

        return {
            "analysis_ready_root": analysis_root,
            "manifest_path": manifest_path,
            "n_csv_files": total_csv,
        }


class SessionReaderGUI(tk.Tk):
    def __init__(self):
        super().__init__()
        # v227 startup paint guard: keep the native root unmapped until the full
        # main layout has been built and High Contrast has been applied.  Several
        # legacy wrappers call update_idletasks during construction, so withdrawing
        # immediately is required to prevent a default-Tk/Dark flash.
        try:
            self.withdraw()
            self.configure(background="#000000")
        except Exception:
            pass
        self._faradaiq_startup_hidden = True
        self._faradaiq_theme_mode = "high contrast"
        self.theme_mode_var = tk.StringVar(master=self, value="High Contrast")
        try:
            _v36_apply_theme(self, "High Contrast")
        except Exception:
            pass
        self.title(APP_TITLE)
        self.geometry("1460x920")
        self.minsize(1120, 760)

        self.collection = PSSessionCollection()
        self.current_summary = None

        self.file_var = tk.StringVar()
        self.output_dir_var = tk.StringVar(value=str(Path.cwd()))
        self.include_raw_json_var = tk.BooleanVar(value=False)

        self._build_ui()

    def _build_ui(self):
        top = ttk.Frame(self, padding=10)
        top.pack(fill="x")

        ttk.Label(top, text="Input file/folder: HEKA DAT2, PalmSens, VersaStudio, Solartron, BioLogic, ZIP, or folder").grid(row=0, column=0, sticky="w", padx=(0, 10), pady=4)
        ttk.Entry(top, textvariable=self.file_var, width=100).grid(row=0, column=1, sticky="ew", pady=4)

        file_btns = ttk.Frame(top)
        file_btns.grid(row=0, column=2, sticky="e", padx=(10, 0), pady=4)
        ttk.Button(file_btns, text="Browse file", command=self.browse_file).pack(side="left", padx=(0, 6))
        ttk.Button(file_btns, text="Browse folder", command=self.browse_input_folder).pack(side="left", padx=(0, 6))
        ttk.Button(file_btns, text="Load and inspect", command=self.load_and_inspect).pack(side="left")

        ttk.Label(top, text="Output folder").grid(row=1, column=0, sticky="w", padx=(0, 10), pady=4)
        ttk.Entry(top, textvariable=self.output_dir_var, width=100).grid(row=1, column=1, sticky="ew", pady=4)

        output_btns = ttk.Frame(top)
        output_btns.grid(row=1, column=2, sticky="e", padx=(10, 0), pady=4)
        ttk.Button(output_btns, text="Choose folder", command=self.browse_output_dir).pack(side="left", padx=(0, 6))
        ttk.Button(output_btns, text="Export archive + analysis-ready CSV", command=self.export_outputs).pack(side="left", padx=(0, 6))
        ttk.Button(output_btns, text="Split HEKA <2GB", command=self.split_heka_bundle_outputs).pack(side="left", padx=(0, 6))
        ttk.Button(output_btns, text="Open Help Guide", command=self.open_help_guide).pack(side="left", padx=(0, 6))
        ttk.Button(output_btns, text="About / credits", command=self.show_about_credits).pack(side="left")

        # v20: keep pySECCM/DRT launchers visible in the main toolbar rather than
        # adding them below the large paned window where they can be off-screen.
        seccm_btns = ttk.LabelFrame(top, text="pySECCM / DRT runners", padding=(6, 4))
        seccm_btns.grid(row=2, column=0, columnspan=3, sticky="ew", pady=(6, 4))
