        ttk.Button(seccm_btns, text="EIS", command=lambda: self.open_pyseccm_tool("eis")).pack(side="left", padx=(0, 6))
        ttk.Button(seccm_btns, text="IV / Tafel", command=lambda: self.open_pyseccm_tool("iv")).pack(side="left", padx=(0, 6))
        ttk.Button(seccm_btns, text="OCP", command=lambda: self.open_pyseccm_tool("ocp")).pack(side="left", padx=(0, 6))
        ttk.Button(seccm_btns, text="pyDRT", command=lambda: self.open_pyseccm_tool("drt")).pack(side="left", padx=(0, 10))
        ttk.Button(seccm_btns, text="Launcher window", command=self.open_pyseccm_launcher).pack(side="left", padx=(0, 8))
        ttk.Button(seccm_btns, text="Check/install deps", command=self.check_install_pyseccm_dependencies).pack(side="left", padx=(0, 12))
        ttk.Label(seccm_btns, text="Export first, then run the generated data folder. Runs open in separate command windows.").pack(side="left", fill="x", expand=True)

        ttk.Checkbutton(top, text="Also save full raw JSON copy (can be very large)", variable=self.include_raw_json_var).grid(row=3, column=1, sticky="w", pady=(4, 4))
        top.columnconfigure(1, weight=1)

        middle = ttk.Panedwindow(self, orient="horizontal")
        middle.pack(fill="both", expand=True, padx=10, pady=(0, 10))

        left_frame = ttk.Frame(middle, padding=6)
        right_frame = ttk.Frame(middle, padding=6)
        middle.add(left_frame, weight=1)
        middle.add(right_frame, weight=2)

        ttk.Label(left_frame, text="Experimental description").pack(anchor="w")
        self.desc_text = ScrolledText(left_frame, wrap="word", height=14)
        self.desc_text.pack(fill="x", expand=False, pady=(4, 10))

        prompt_frame = ttk.Frame(left_frame)
        prompt_frame.pack(fill="x", pady=(0, 10))
        ttk.Button(prompt_frame, text="Append AI Analysis Prompt", command=self.append_ai_prompt).grid(row=0, column=0, sticky="w")
        ttk.Label(prompt_frame, text="Generates a clear electrochemistry-focused prompt and appends it to the experimental description box.").grid(row=0, column=1, sticky="w", padx=(8, 0))
        prompt_frame.columnconfigure(1, weight=1)

        ttk.Label(left_frame, text="Session summary").pack(anchor="w")
        self.summary_text = ScrolledText(left_frame, wrap="word", height=28)
        self.summary_text.pack(fill="both", expand=True)

        ttk.Label(right_frame, text="Data structure preview").pack(anchor="w")
