def _session_reader_gui_v14_display_summary(self, summary: dict):
    _SESSION_READER_GUI_V14_ORIGINAL_DISPLAY_SUMMARY(self, summary)
    extra_lines = []
    def add_from(s, prefix=""):
        ds = s.get("heka_detail_summary") or {}
        exp = s.get("heka_seccm_software_exports") or ds.get("seccm_software_exports") or {}
        if exp and exp.get("n_files"):
            if prefix:
                extra_lines.append(prefix)
            extra_lines.append(f"  Companion software-exported data files found: {exp.get('n_files')}")
            extra_lines.append(f"  Companion file types: {exp.get('counts_by_kind')}")
            if exp.get("data_folders"):
                extra_lines.append(f"  Data subfolder(s): {', '.join(Path(x).name for x in exp.get('data_folders', []))}")
            extra_lines.append("  Export creates a pySECCM-compatible folder named *_for_plotting_analysis.")
    if summary.get("mode") in {"zip", "directory"}:
        for entry in getattr(self.collection, "entries", [])[:20]:
            add_from(entry.get("parser").summarize(), prefix=f"SECCM plotting compatibility for {entry.get('entry_name')}:")
    else:
        add_from(summary)
    if extra_lines:
        cur = self.summary_text.get("1.0", "end").rstrip()
        self.summary_text.delete("1.0", "end")
        self.summary_text.insert("1.0", cur + "\n\n" + "\n".join(extra_lines))


