# ---- HEKA v14.1 fix: stabilize EIS frequency table across point/line scans ----

def _heka_v177_eis_blocks_and_frequency_table(self):
    blocks = []
    if getattr(self, "blocks", None):
        for b in self.blocks:
            if getattr(b, "eis_group_indices", None):
                groups = [self.eis_groups[gi] for gi in b.eis_group_indices]
                if groups:
                    blocks.append((b.block_index0, groups))
    if not blocks and getattr(self, "eis_groups", None):
        blocks = [(0, list(self.eis_groups))]
    # Pick the most common complete frequency-count and use the first such block as the canonical table.
    counts = Counter(len(gs) for _, gs in blocks if gs)
    if counts:
        full_count = counts.most_common(1)[0][0]
        ref_groups = next((gs for _, gs in blocks if len(gs) == full_count), blocks[0][1])
    else:
        ref_groups = []
    freq_table = [_heka_v14_eis_group_frequency_Hz(self, g) for g in ref_groups]
    return blocks, freq_table


def _heka_v177_eis_row_from_group(self, group, freq_override=None):
    row = _heka_v14_eis_row_from_group(self, group)
    if freq_override is not None and np.isfinite(freq_override) and freq_override > 0:
        row[1] = float(freq_override)
        row[2] = float(np.log10(float(freq_override)))
    return row


def _heka_v177_write_eis_file_from_heka(self, out_path: Path):
    blocks, freq_table = _heka_v177_eis_blocks_and_frequency_table(self)
    rows = []
    for _bi, groups in blocks:
        for j, g in enumerate(groups):
            f_override = freq_table[j] if j < len(freq_table) else None
            rows.append(_heka_v177_eis_row_from_group(self, g, f_override))
    header = ["Sweep #", "f2[Hz]", "log(f)", "AdmitY[S]", "log(AdmitY)", "RealY[S]", "ImagY[S]", "Phase[deg]", "RealZ[Ohm]", "ImagZ[Ohm]", "ImpZ[Ohm]", "log(ImpZ)"]
    _heka_v14_write_repeated_header_table(out_path, header, rows)
    return {"path": str(out_path), "n_rows": len(rows), "n_unique_frequency_points": len(freq_table)}


def _heka_v177_write_drt_input_csvs(self, drt_dir: Path):
    drt_dir.mkdir(parents=True, exist_ok=True)
    files = []
    blocks, freq_table = _heka_v177_eis_blocks_and_frequency_table(self)
    for bi, groups in blocks:
        rows = []
        for j, g in enumerate(groups):
            f_override = freq_table[j] if j < len(freq_table) else None
            r = _heka_v177_eis_row_from_group(self, g, f_override)
            freq, zre, zim = r[1], r[8], r[9]
            if np.isfinite(freq) and np.isfinite(zre) and np.isfinite(zim):
                rows.append([freq, zre, zim])
        if rows:
            path = drt_dir / f"position_{bi+1:03d}_freq_zreal_zimag.csv"
            with open(path, "w", encoding="utf-8", newline="") as f:
                w = csv.writer(f)
                w.writerow(["frequency_Hz", "Zreal_ohm", "Zimag_ohm"])
                w.writerows(rows)
            files.append(str(path))
    return files

# Rebind the names used by the exporter.
_heka_v14_write_eis_file_from_heka = _heka_v177_write_eis_file_from_heka
_heka_v14_write_drt_input_csvs = _heka_v177_write_drt_input_csvs

# ---- End HEKA v14.1 fix ----


# ---- HEKA v14.2 fix: synthesize unique EIS table when HEKA online trace durations clip at low frequency ----

def _heka_v177_eis_blocks_and_frequency_table(self):
    blocks = []
    if getattr(self, "blocks", None):
        for b in self.blocks:
            if getattr(b, "eis_group_indices", None):
                groups = [self.eis_groups[gi] for gi in b.eis_group_indices]
                if groups:
                    blocks.append((b.block_index0, groups))
    if not blocks and getattr(self, "eis_groups", None):
        blocks = [(0, list(self.eis_groups))]
    counts = Counter(len(gs) for _, gs in blocks if gs)
    if counts:
        full_count = counts.most_common(1)[0][0]
        ref_groups = next((gs for _, gs in blocks if len(gs) == full_count), blocks[0][1])
    else:
        full_count = 0
        ref_groups = []
    freq_table = [_heka_v14_eis_group_frequency_Hz(self, g) for g in ref_groups]
    valid_unique = len({round(float(x), 12) for x in freq_table if np.isfinite(x) and x > 0})
    if freq_table and valid_unique < len(freq_table):
        # POTMASTER can store low-frequency online traces with the same minimum acquisition window.
        # In that case trace length is no longer a usable frequency identifier, so make a unique
        # monotonic table from the method range. This keeps pySECCM tools grouping correct.
        ds = getattr(self, "detail_summary", {}) or {}
        f_hi = ds.get("frequency_max_Hz") or ds.get("start_freq_Hz")
        f_lo = ds.get("frequency_min_Hz") or ds.get("end_freq_Hz")
        try:
            f_hi = float(f_hi); f_lo = float(f_lo)
        except Exception:
            f_hi = f_lo = None
        if f_hi and f_lo and f_hi > f_lo > 0 and len(freq_table) > 1:
            freq_table = list(np.geomspace(f_hi, f_lo, len(freq_table)))
    return blocks, freq_table

_heka_v177_eis_blocks_and_frequency_table = _heka_v177_eis_blocks_and_frequency_table

# ---- End HEKA v14.2 fix ----


# ---- HEKA v15 enhancements: generate pySECCM files directly from HEKA DAT/PUL only ----
# The v14 exporter could copy a vendor-exported data/ subfolder when present.  v15 deliberately
# treats that subfolder as a reference only and always creates the pySECCM-compatible files from
# the HEKA binary bundle/support data.

HEKA_V15_MAX_TRACE_POINTS_FOR_EXPORT = 5_000_000


def _heka_v15_is_current_trace(label: str) -> bool:
    return bool(re.search(r"(^I($|[-_ ])|Imon|Current)", str(label), re.I))


def _heka_v15_is_potential_trace(label: str) -> bool:
    return bool(re.search(r"(^E($|[-_ ])|Emon|Volt|Potential)", str(label), re.I))


def _heka_v15_d64(pul: bytes, off: int, default=float("nan")) -> float:
    try:
        if off < 0 or off + 8 > len(pul):
            return default
        v = _heka_struct.unpack_from("<d", pul, off)[0]
        return float(v) if np.isfinite(v) else default
    except Exception:
        return default


def _heka_v15_trace_sample_interval_s(self, ti: int) -> float:
    try:
        tr = self.traces[int(ti)]
        # In all tested POTMASTER files, rec_offset+112 stores the trace sample interval in seconds.
        dt = _heka_v15_d64(self.pul, tr.rec_offset + 112)
        if np.isfinite(dt) and 0 < dt < 1e6:
            return float(dt)
    except Exception:
        pass
    return float("nan")


def _heka_v15_trace_duration_s(self, ti: int) -> float:
    try:
        tr = self.traces[int(ti)]
        dt = _heka_v15_trace_sample_interval_s(self, ti)
        if np.isfinite(dt) and dt > 0:
            return float(tr.n_points) * dt
    except Exception:
        pass
    return 0.0


def _heka_v15_block_duration_s(self, block) -> float:
    # We estimate elapsed acquisition time from trace sample intervals in the .pul metadata.
    # This does not include any unrecorded stage-settling or user wait time, but it is DAT/PUL-derived.
    try:
        return float(sum(_heka_v15_trace_duration_s(self, ti) for ti in sorted(set(block.trace_indices))))
    except Exception:
        return 0.0


def _heka_v15_block_start_time_estimates(self) -> list[float]:
    starts = []
    t = 0.0
    for b in getattr(self, "blocks", []) or []:
        starts.append(float(t))
        t += max(0.0, _heka_v15_block_duration_s(self, b))
    return starts


def _heka_v15_find_takedata_pair_for_block(self, block):
    """Return (current_trace_index, potential_trace_index) for the point/takedata step.

    POTMASTER stores the stage coordinates immediately before the short Emon trace record in
    the .pul tree.  The short two-point Imon/Emon pair is typically the Takedata step.
    """
    prelude = list(getattr(block, "prelude_trace_indices", []) or [])
    # Prefer a short consecutive Imon/Emon pair in the prelude.
    for a, b in zip(prelude, prelude[1:]):
        ta = self.traces[int(a)]
        tb = self.traces[int(b)]
        if max(int(ta.n_points), int(tb.n_points)) > 10:
            continue
        if _heka_v15_is_current_trace(ta.label) and _heka_v15_is_potential_trace(tb.label):
            return int(a), int(b)
        if _heka_v15_is_potential_trace(ta.label) and _heka_v15_is_current_trace(tb.label):
            return int(b), int(a)
    # Fallback: first current/potential short traces anywhere in prelude.
    cur = pot = None
    for ti in prelude:
        tr = self.traces[int(ti)]
        if int(tr.n_points) > 10:
            continue
        if cur is None and _heka_v15_is_current_trace(tr.label):
            cur = int(ti)
        if pot is None and _heka_v15_is_potential_trace(tr.label):
            pot = int(ti)
        if cur is not None and pot is not None:
            return cur, pot
    return None, None


def _heka_v15_takedata_row_from_block(self, block, point_index0: int, start_time_s: float = 0.0):
    ci, ei = _heka_v15_find_takedata_pair_for_block(self, block)
    if ci is None or ei is None:
        return None
    ctrace = self.traces[ci]
    etrace = self.traces[ei]
    er = int(etrace.rec_offset)
    cr = int(ctrace.rec_offset)
    x = _heka_v15_d64(self.pul, er - 124)
    y = _heka_v15_d64(self.pul, er - 116)
    z = _heka_v15_d64(self.pul, er - 108)
    # The tested POTMASTER Takedata files match these fields:
    #   current: current trace record +136 as a double
    #   Emon: mean of two potential values at potential trace record +232 and +240
    imon = _heka_v15_d64(self.pul, cr + 136)
    e1 = _heka_v15_d64(self.pul, er + 232)
    e2 = _heka_v15_d64(self.pul, er + 240)
    ev = float("nan")
    if np.isfinite(e1) and np.isfinite(e2) and abs(e1) < 20 and abs(e2) < 20:
        ev = 0.5 * (e1 + e2)
    elif np.isfinite(e1) and abs(e1) < 20:
        ev = e1
    elif np.isfinite(e2) and abs(e2) < 20:
        ev = e2
    if not np.isfinite(imon) or abs(imon) > 10:
        try:
            arr = self.read_trace_array(ci, max_points=min(int(ctrace.n_points), 64))
            arr = np.asarray(arr, dtype=float)
            arr = arr[np.isfinite(arr)]
            if arr.size:
                imon = float(np.nanmedian(arr))
        except Exception:
            pass
    if not np.isfinite(ev) or abs(ev) > 20:
        try:
            arr = self.read_trace_array(ei, max_points=min(int(etrace.n_points), 64))
            arr = np.asarray(arr, dtype=float)
            arr = arr[np.isfinite(arr)]
            if arr.size:
                ev = float(np.nanmedian(arr))
        except Exception:
            pass
    # If stage coordinates cannot be decoded, keep NaN rather than inventing X/Y/Z.
    return [
        1,
        imon if np.isfinite(imon) else float("nan"),
        ev if np.isfinite(ev) else float("nan"),
        x if np.isfinite(x) else float("nan"),
        y if np.isfinite(y) else float("nan"),
        z if np.isfinite(z) else float("nan"),
        float(start_time_s) if np.isfinite(start_time_s) else float(point_index0),
    ]


def _heka_v15_position_rows_from_dat(self):
    starts = _heka_v15_block_start_time_estimates(self)
    rows = []
    for idx, b in enumerate(getattr(self, "blocks", []) or []):
        row = _heka_v15_takedata_row_from_block(self, b, idx, starts[idx] if idx < len(starts) else float(idx))
        if row is not None:
            rows.append(row)
    if rows:
        finite_xyz = sum(1 for r in rows if np.isfinite(r[3]) and np.isfinite(r[4]) and np.isfinite(r[5]))
        src = "decoded_from_HEKA_pul_takedata_records"
        if finite_xyz < len(rows):
            src += "_with_missing_stage_coordinates"
        return rows, src
    # Last-resort only: no take-data records were found. This path leaves coordinates blank.
    n_points = int((getattr(self, "scan_inference", {}) or {}).get("n_inferred_measurement_points") or len(getattr(self, "blocks", []) or []) or 1)
    rows = [[1, float("nan"), float("nan"), float("nan"), float("nan"), float("nan"), float(i)] for i in range(n_points)]
    return rows, "no_HEKA_takedata_records_found_blank_coordinates_not_synthetic_stage"


# Override the v14 position-file function so the main pySECCM file is always from DAT/PUL, never from data/*.txt.
def _heka_v14_estimated_position_rows(self):
    return _heka_v15_position_rows_from_dat(self)


def _heka_v15_eis_entries(self):
    entries = []
    for e in getattr(self, "method_entries", []) or []:
        raw = str(e.get("raw_text", ""))
        tech = str(e.get("technique_text", ""))
        if "eis" in tech.lower() or "startfreq" in raw.lower() or "impedance" in raw.lower():
            entries.append(e)
    return entries


def _heka_v15_method_float(entry: dict, *keys, default=float("nan")):
    for k in keys:
        if k in entry and entry.get(k) not in (None, ""):
            try:
                return float(entry.get(k))
            except Exception:
                try:
                    v = _heka_parse_numeric_with_unit(str(entry.get(k)))
                    if v is not None:
                        return float(v)
                except Exception:
                    pass
    return default


def _heka_v15_generate_log_frequency_list(entry: dict, n_points: int) -> list[float]:
    """Method-derived EIS frequency fallback.

    HEKA/POTMASTER stores the requested StartFreq/EndFreq/FreqPerDec in method text.  Some
    POTMASTER online impedance exports use an internal frequency table that is not explicitly
    stored as one simple float vector in the DAT2 tree.  This fallback is therefore DAT-method-
    derived and monotonic, which is sufficient for pySECCM/DRT input when the vendor text export
    is unavailable.
    """
    n_points = int(max(1, n_points))
    f0 = _heka_v15_method_float(entry, "start_freq_Hz", "startfreq", default=float("nan"))
    f1 = _heka_v15_method_float(entry, "end_freq_Hz", "endfreq", default=float("nan"))
    if not (np.isfinite(f0) and np.isfinite(f1) and f0 > 0 and f1 > 0):
        return [float(i + 1) for i in range(n_points)][::-1]
    # Use high-to-low ordering, matching HEKA exported fullEIS files.
    hi = max(f0, f1)
    lo = min(f0, f1)
    if n_points == 1:
        return [hi]
    freqs = np.logspace(np.log10(hi), np.log10(lo), n_points)
    return [float(x) for x in freqs]


def _heka_v15_frequency_vector_for_segment(self, segment_groups, entry: dict | None = None):
    n = len(segment_groups)
    if n <= 0:
        return []
    entry = entry or (_heka_v15_eis_entries(self)[0] if _heka_v15_eis_entries(self) else {})
    return _heka_v15_generate_log_frequency_list(entry, n)


def _heka_v15_eis_segments_by_block(self):
    by_block = {}
    for g in getattr(self, "eis_groups", []) or []:
        bi = g.block_index0 if g.block_index0 is not None else 0
        by_block.setdefault(int(bi), []).append(g)
    for bi in by_block:
        by_block[bi] = sorted(by_block[bi], key=lambda g: int(g.group_index))
    entries = _heka_v15_eis_entries(self)
    n_methods = max(1, len(entries))
    # If several EIS methods exist and each block divides evenly, produce separate method segments.
    result = {mi: {} for mi in range(n_methods)}
    for bi, groups in sorted(by_block.items()):
        if n_methods > 1 and len(groups) >= n_methods and len(groups) % n_methods == 0:
            seg_len = len(groups) // n_methods
            for mi in range(n_methods):
                result[mi][bi] = groups[mi * seg_len:(mi + 1) * seg_len]
        else:
            result[0][bi] = groups
            for mi in range(1, n_methods):
                result[mi][bi] = []
    # Drop empty segments.
    return {mi: blocks for mi, blocks in result.items() if any(blocks.values())}


def _heka_v15_eis_row_from_group_with_freq(self, group, freq: float):
    row = _heka_v14_eis_row_from_group(self, group)
    row[1] = float(freq) if np.isfinite(freq) and freq > 0 else float("nan")
    row[2] = np.log10(row[1]) if np.isfinite(row[1]) and row[1] > 0 else np.nan
    return row


def _heka_v15_write_eis_file_for_segment(self, out_path: Path, segment_index: int = 0, entry: dict | None = None):
    segments = _heka_v15_eis_segments_by_block(self)
    blocks = segments.get(segment_index, {})
    rows = []
    for bi in sorted(blocks):
        groups = blocks[bi]
        freqs = _heka_v15_frequency_vector_for_segment(self, groups, entry=entry)
        for g, f in zip(groups, freqs):
            rows.append(_heka_v15_eis_row_from_group_with_freq(self, g, f))
    header = ["Sweep #", "f2[Hz]", "log(f)", "AdmitY[S]", "log(AdmitY)", "RealY[S]", "ImagY[S]", "Phase[deg]", "RealZ[Ohm]", "ImagZ[Ohm]", "ImpZ[Ohm]", "log(ImpZ)"]
    _heka_v14_write_repeated_header_table(out_path, header, rows)
    return {"path": str(out_path), "n_rows": len(rows), "segment_index": segment_index + 1, "frequency_source": "method_logspace_from_HEKA_DAT_PUL_method_text"}


# Replace v14 fullEIS writer.  It now uses method-derived frequency values, not trace n_points.
def _heka_v14_write_eis_file_from_heka(self, out_path: Path):
    entries = _heka_v15_eis_entries(self)
    entry = entries[0] if entries else None
    return _heka_v15_write_eis_file_for_segment(self, out_path, 0, entry=entry)


def _heka_v15_generate_eis_files(self, data_dir: Path, safe: str):
    out = []
    segments = _heka_v15_eis_segments_by_block(self)
    entries = _heka_v15_eis_entries(self)
    if not segments:
        return out
    for mi in sorted(segments):
        # Preserve legacy name for first EIS so pySECCM auto-detection works.
        if mi == 0:
            name = f"{safe}_fullEIS_6.txt"
        else:
            name = f"{safe}_fullEIS_method{mi+1}.txt"
        entry = entries[mi] if mi < len(entries) else (entries[0] if entries else None)
        info = _heka_v15_write_eis_file_for_segment(self, data_dir / name, mi, entry=entry)
        info.update({"kind": "EIS", "filename": name, "method_entry": mi + 1})
        out.append(info)
    return out


def _heka_v15_current_potential_pairs_by_block(self):
    return _heka_v14_cv_pairs_by_block(self)


def _heka_v15_allocated_cv_pair_ids(self) -> set[int]:
    used = set()
    entries = _heka_v14_cv_entries(self)
    by = _heka_v15_current_potential_pairs_by_block(self)
    if not entries or not by:
        return used
    offset = 0
    pairs_per_block = min(len(v) for v in by.values()) if by else 0
    for entry in entries:
        cycles = _heka_v14_parse_cycles_from_entry(entry)
        if offset + cycles > pairs_per_block:
            break
        for block_pairs in by.values():
            for cyc in range(cycles):
                if offset + cyc < len(block_pairs):
                    used.add(int(block_pairs[offset + cyc].get("pair_index", -1)))
        offset += cycles
    return used


def _heka_v15_write_generic_pair_file(self, out_path: Path, pairs_by_block: dict, pairs_to_use: list[dict], kind: str = "IV"):
    out_path.parent.mkdir(parents=True, exist_ok=True)
    total = 0
    groups = 0
    with open(out_path, "w", encoding="windows-1252", newline="") as f:
        for bi in sorted(pairs_by_block):
            for p in pairs_by_block[bi]:
                if int(p.get("pair_index", -1)) not in {int(q.get("pair_index", -2)) for q in pairs_to_use}:
                    continue
                n = min(int(p.get("n_points") or 0), HEKA_V15_MAX_TRACE_POINTS_FOR_EXPORT)
                if n <= 0:
                    continue
                try:
                    e = np.asarray(self.read_trace_array(p["potential_trace_index"], max_points=n), dtype=float)
                    cur = np.asarray(self.read_trace_array(p["current_trace_index"], max_points=n), dtype=float)
                except Exception:
                    continue
                m = min(len(e), len(cur))
                if m <= 0:
                    continue
                dt = _heka_v15_trace_sample_interval_s(self, p["potential_trace_index"])
                if not (np.isfinite(dt) and dt > 0):
                    dt = 1.0
                f.write(f"Series_{kind}_{bi+1}\n")
                f.write(f"Sweep_{kind}_{bi+1}_1,  0.000000000E+00, 00:00:00.000, 1970/01/01 00:00:00.000, \"Generated from HEKA DAT/PUL\"\n")
                f.write('"Index", "Time[s]"       , "Imon-2[A]"     , "Time[s]"       , "Emon-2[V]"     \n')
                for k in range(m):
                    t = k * dt
                    f.write(f"{k:7d}, {t:16.9E}, {float(cur[k]):16.9E}, {t:16.9E}, {float(e[k]):16.9E}\n")
                f.write("\n")
                total += m
                groups += 1
    return {"path": str(out_path), "n_groups": groups, "total_rows": total}


def _heka_v15_generate_iv_tafel_ocp_files(self, data_dir: Path, safe: str):
    """Best-effort creation of IV/Tafel/OCP files from DAT traces when these steps exist.

    CV pairs are allocated first from CV method entries.  Remaining current/potential pairs are
    mapped to IV/Tafel if the method text suggests ramp/Tafel/IV, or to OCP if it suggests OCP.
    This avoids creating fake files when the experiment only contains CV+EIS.
    """
    files = []
    by = _heka_v15_current_potential_pairs_by_block(self)
    if not by:
        return files
    used_cv = _heka_v15_allocated_cv_pair_ids(self)
    remaining = []
    for pairs in by.values():
        for p in pairs:
            if int(p.get("pair_index", -1)) not in used_cv:
                remaining.append(p)
    if not remaining:
        return files
    raw_methods = "\n".join(str(e.get("raw_text", "")) for e in getattr(self, "method_entries", []) or [])
    has_iv = bool(re.search(r"\b(Tafel|IV|I[- ]?V|Ramp|LSV|Linear)\b", raw_methods, re.I))
    has_ocp = bool(re.search(r"\b(OCP|Open\s*Circuit)\b", raw_methods, re.I))
    if has_iv:
        iv_name = f"{safe}_IV_Tafel_from_HEKA_7.asc"
        corr_name = f"{safe}_Ecorr_Icorr_from_HEKA_7.txt"
        info = _heka_v15_write_generic_pair_file(self, data_dir / iv_name, by, remaining, kind="IV")
        info.update({"kind": "TAFEL-IV", "filename": iv_name, "source": "remaining_current_potential_pairs_after_CV_allocation"})
        files.append(info)
        # Make a simple Ecorr/Icorr table from point/takedata rows so parse_IV has a companion file.
        pos_rows, _ = _heka_v15_position_rows_from_dat(self)
        corr_rows = []
        for r in pos_rows:
            corr_rows.append([1, r[2], r[1], r[5] if len(r) > 5 else np.nan, np.nan])
        _heka_v14_write_repeated_header_table(data_dir / corr_name, ["Sweep #", "E_corr[V]", "I_corr[A]", "Z-pos[m]", "Rp"], corr_rows)
        files.append({"kind": "TAFEL-corr", "filename": corr_name, "path": str(data_dir / corr_name), "n_rows": len(corr_rows), "source": "HEKA_takedata_summary"})
    if has_ocp:
        ocp_name = f"{safe}_OCP_from_HEKA_8.asc"
        avg_name = f"{safe}_avgOCP_from_HEKA_8.txt"
        info = _heka_v15_write_generic_pair_file(self, data_dir / ocp_name, by, remaining, kind="OCP")
        info.update({"kind": "OCP", "filename": ocp_name, "source": "remaining_current_potential_pairs_after_CV_allocation"})
        files.append(info)
        pos_rows, _ = _heka_v15_position_rows_from_dat(self)
        avg_rows = [[1, r[2]] for r in pos_rows]
        _heka_v14_write_repeated_header_table(data_dir / avg_name, ["Sweep #", "OCP-value[V]"], avg_rows)
        files.append({"kind": "OCP-average", "filename": avg_name, "path": str(data_dir / avg_name), "n_rows": len(avg_rows), "source": "HEKA_takedata_summary"})
    return files


# Make NPY payload include the DAT-generated pySECCM manifest, not copied software exports.
def _heka_v15_generated_export_payload(self):
    payload = {
        "format": "seccm-heka-generated-from-dat-v2",
        "note": "pySECCM-compatible files are generated directly from HEKA DAT/PUL trace metadata and arrays. Existing data/ software-export folders are ignored except as user reference files.",
        "takedata_preview": [],
    }
    try:
        rows, src = _heka_v15_position_rows_from_dat(self)
        payload["takedata_source"] = src
        payload["takedata_preview"] = rows[:20]
        payload["n_takedata_rows"] = len(rows)
    except Exception as exc:
        payload["takedata_error"] = str(exc)
    return payload


def _heka_v14_companion_export_payload(self):
    return _heka_v15_generated_export_payload(self)


# Do not copy software exports into the data folder in v15.
def _heka_v14_copy_existing_software_files(self, data_dir: Path):
    return []


def _heka_v14_export_seccm_plotting_analysis_outputs(self, output_dir: Path, base_name: str) -> dict:
    output_dir = Path(output_dir)
    safe = PSSessionParser._sanitize_filename(base_name)
    root = output_dir / f"{safe}_for_plotting_analysis"
    root.mkdir(parents=True, exist_ok=True)
    generated_data = root / "data_generated_from_HEKA"
    main_data = root / "data"
    drt_dir = root / "DRT_input_csv"
    photos_dir = root / "photos"
    reference_dir = root / "software_data_reference_ignored"
    for d in (generated_data, main_data, drt_dir, photos_dir, reference_dir):
        d.mkdir(parents=True, exist_ok=True)

    manifest = {
        "created": datetime.now().isoformat(timespec="seconds"),
        "format": "heka-seccm-plotting-analysis-folder-v2-generated-from-DAT",
        "source_file": self.source_path,
        "plotting_root": str(root),
        "data_folder_for_pySECCM tools": str(main_data),
        "notes": [
            "v15: pySECCM-compatible takedata/fullEIS/CV/IV/OCP files are generated from HEKA DAT/PUL only.",
            "Existing HEKA software-exported data/ files are not used to populate the main data folder."
        ],
        "generated_from_heka": [],
        "software_reference_ignored": getattr(self, "seccm_software_exports", {}),
        "drt_input_csv_files": [],
        "photos": [],
        "script_bundle_copy": "",
        "main_data_source": str(generated_data),
    }

    try:
        pos_info = _heka_v14_write_position_file(self, generated_data, safe)
        manifest["generated_from_heka"].append(pos_info)
    except Exception as exc:
        manifest["notes"].append(f"Could not generate DAT-derived take-data/position file: {exc}")

    try:
        for info in _heka_v15_generate_eis_files(self, generated_data, safe):
            manifest["generated_from_heka"].append(info)
    except Exception as exc:
        manifest["notes"].append(f"Could not generate DAT-derived fullEIS file(s): {exc}")

    try:
        for info in _heka_v14_generate_cv_files(self, generated_data, safe):
            info["source"] = "HEKA_DAT_PUL_current_potential_pairs"
            manifest["generated_from_heka"].append(info)
    except Exception as exc:
        manifest["notes"].append(f"Could not generate DAT-derived CV files: {exc}")

    try:
        for info in _heka_v15_generate_iv_tafel_ocp_files(self, generated_data, safe):
            manifest["generated_from_heka"].append(info)
    except Exception as exc:
        manifest["notes"].append(f"Could not generate DAT-derived IV/Tafel/OCP files: {exc}")

    try:
        manifest["drt_input_csv_files"] = _heka_v14_write_drt_input_csvs(self, drt_dir)
    except Exception as exc:
        manifest["notes"].append(f"Could not generate DRT input CSV files: {exc}")

    try:
        manifest["photos"] = _heka_v14_copy_photos_to_plotting_folder(self, photos_dir)
    except Exception as exc:
        manifest["notes"].append(f"Could not copy photos: {exc}")

    try:
        for p in main_data.iterdir():
            if p.is_file():
                p.unlink()
            elif p.is_dir():
                _v14_shutil.rmtree(p)
        for p in sorted(generated_data.iterdir(), key=_heka_v14_nat_key_path):
            if p.is_file():
                _v14_shutil.copy2(p, main_data / p.name)
        _heka_v14_make_minimal_mplstyle(main_data)
    except Exception as exc:
        manifest["notes"].append(f"Could not populate main data folder from generated HEKA files: {exc}")

    manifest["script_bundle_copy"] = _heka_v14_copy_script_bundle_to_output(root)

    manifest_path = root / "plotting_analysis_manifest.json"
    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2, ensure_ascii=False)
    return {
        "root": str(root),
        "main_data": str(main_data),
        "manifest": str(manifest_path),
        "n_software_files": 0,
        "n_generated_files": len(manifest.get("generated_from_heka", [])),
        "n_drt_files": len(manifest.get("drt_input_csv_files", [])),
        "files": [str(manifest_path), str(root), str(main_data)],
    }


# Improve DRT frequency values too: use method-derived segment frequencies.
def _heka_v14_write_drt_input_csvs(self, drt_dir: Path):
    drt_dir.mkdir(parents=True, exist_ok=True)
    files = []
    segments = _heka_v15_eis_segments_by_block(self)
    entries = _heka_v15_eis_entries(self)
    for mi, blocks in sorted(segments.items()):
        entry = entries[mi] if mi < len(entries) else (entries[0] if entries else {})
        for bi, groups in sorted(blocks.items()):
            freqs = _heka_v15_frequency_vector_for_segment(self, groups, entry=entry)
            rows = []
            for g, f in zip(groups, freqs):
                r = _heka_v15_eis_row_from_group_with_freq(self, g, f)
                freq, zre, zim = r[1], r[8], r[9]
                if np.isfinite(freq) and np.isfinite(zre) and np.isfinite(zim):
                    rows.append([freq, zre, zim])
            if rows:
                suffix = f"method{mi+1}_" if len(segments) > 1 else ""
                path = drt_dir / f"position_{bi+1:03d}_{suffix}freq_zreal_zimag.csv"
                with open(path, "w", encoding="utf-8", newline="") as f:
                    w = csv.writer(f)
                    w.writerow(["frequency_Hz", "Zreal_ohm", "Zimag_ohm"])
                    w.writerows(rows)
                files.append(str(path))
    return files


# Session summary additions for v15.
_HEKA_V15_ORIGINAL_SUMMARIZE = HEKAPotmasterParser.summarize

def _heka_v15_summarize(self):
    s = _HEKA_V15_ORIGINAL_SUMMARIZE(self)
    try:
        rows, src = _heka_v15_position_rows_from_dat(self)
        ds = s.setdefault("heka_detail_summary", {})
        ds["pyseccm_generation_mode"] = "generated_from_HEKA_DAT_PUL_only"
        ds["takedata_source"] = src
        ds["n_DAT_decoded_takedata_rows"] = len(rows)
        finite_xyz = sum(1 for r in rows if np.isfinite(r[3]) and np.isfinite(r[4]) and np.isfinite(r[5]))
        ds["n_DAT_decoded_stage_coordinate_rows"] = finite_xyz
        s["notes"] = list(s.get("notes", []) or [])
        s["notes"].append("v15: pySECCM-compatible data files are generated from HEKA DAT/PUL; software-exported data/ folders are ignored for main output.")
    except Exception as exc:
        s.setdefault("notes", []).append(f"v15 takedata decode summary failed: {exc}")
    return s

HEKAPotmasterParser.summarize = _heka_v15_summarize
HEKAPotmasterParser.build_compact_summary = _heka_v15_summarize


def _heka_v15_native_numeric_payload(self):
    payload = _HEKA_V14_ORIGINAL_NATIVE_PAYLOAD(self) if '_HEKA_V14_ORIGINAL_NATIVE_PAYLOAD' in globals() else self.native_numeric_payload()
    payload["seccm_generated_from_dat"] = _heka_v15_generated_export_payload(self)
    return payload

HEKAPotmasterParser.native_numeric_payload = _heka_v15_native_numeric_payload
HEKAPotmasterParser.primary_numeric_payload = _heka_v15_native_numeric_payload



# ---- HEKA v16 enhancements: generalized point -> method sequence model ----
# v16 makes the HEKA output adaptable to different POTMASTER/PATCHMASTER sequences.
# It builds an explicit sequence model from the trace tree instead of assuming one fixed
# experiment order.  The pySECCM-compatible legacy files are still generated, but a richer
# manifest is also written so downstream code can discover CV/EIS/OCP/Tafel/other steps.

APP_TITLE = "FaradaIQ Studio v273"
HEKA_V16_SEQUENCE_FORMAT = "heka-point-method-sequence-v1"
HEKA_V16_MAX_TRACE_POINTS_FOR_CANONICAL_CSV = 1_000_000


def _heka_v16_float_or_none(x):
    try:
        v = float(x)
        return v if np.isfinite(v) else None
    except Exception:
        return None


def _heka_v16_unique_sorted(vals, tol=1e-12):
    out = []
    for v in sorted([float(x) for x in vals if x is not None and np.isfinite(float(x))]):
        if not out or abs(v - out[-1]) > tol:
            out.append(v)
    return out


def _heka_v16_scan_geometry_from_takedata(rows):
    """Infer single point / line scan / XY scan / point sequence from decoded stage rows."""
    n = len(rows or [])
    geom = {
        "scan_type": "single point" if n <= 1 else "ordered point sequence",
        "n_points": int(n),
        "axis_summary": {},
        "evidence": [],
    }
    if not rows:
        geom["scan_type"] = "unknown/no take-data rows"
        return geom
    xs = [_heka_v16_float_or_none(r[3]) for r in rows if len(r) > 3]
    ys = [_heka_v16_float_or_none(r[4]) for r in rows if len(r) > 4]
    zs = [_heka_v16_float_or_none(r[5]) for r in rows if len(r) > 5]
    ux = _heka_v16_unique_sorted(xs)
    uy = _heka_v16_unique_sorted(ys)
    uz = _heka_v16_unique_sorted(zs)
    geom["axis_summary"] = {
        "unique_x": len(ux), "unique_y": len(uy), "unique_z": len(uz),
        "x_min_m": min(ux) if ux else None, "x_max_m": max(ux) if ux else None,
        "y_min_m": min(uy) if uy else None, "y_max_m": max(uy) if uy else None,
        "z_min_m": min(uz) if uz else None, "z_max_m": max(uz) if uz else None,
    }
    varying = [axis for axis, u in (("X", ux), ("Y", uy), ("Z", uz)) if len(u) > 1]
    if len(varying) >= 2 and len(ux) * max(1, len(uy)) >= max(4, int(0.75 * n)):
        geom["scan_type"] = "XY/2D grid or raster scan"
        geom["evidence"].append(f"multiple varying axes: {', '.join(varying)}")
    elif len(varying) == 1:
        geom["scan_type"] = f"line scan along {varying[0]}"
        geom["evidence"].append(f"only {varying[0]} has multiple decoded stage positions")
    elif n > 1:
        geom["scan_type"] = "ordered point sequence / repeated single location"
        geom["evidence"].append("multiple points but decoded stage coordinates are constant or unavailable")
    else:
        geom["scan_type"] = "single point"
    return geom


def _heka_v16_method_signature(method_type, name="", **kwargs):
    pieces = [str(method_type or "UNKNOWN")]
    for key in ("scan_rate_V_s", "bias_V", "freq_min_Hz", "freq_max_Hz", "n_cycles", "n_rows"):
        val = kwargs.get(key)
        if val is not None and val != "":
            try:
                if isinstance(val, float):
                    pieces.append(f"{key}={val:.6g}")
                else:
                    pieces.append(f"{key}={val}")
            except Exception:
                pieces.append(f"{key}={val}")
    if name:
        pieces.append(PSSessionParser._sanitize_filename(str(name))[:48])
    return "|".join(pieces)


def _heka_v297_pair_has_log_i(self, pair):
    """Strongly identify a Tafel/IV pair when HEKA stored the companion log(i) trace.

    Legacy SECCM files can contain current + potential + log(i) as one
    polarization series even when the method text only says "Current vs. Potential".
    The companion log(i) channel is direct acquisition evidence and is more
    specific than treating the pair as generic CV.
    """
    try:
        ci = int(pair.get("current_trace_index", -1)); ei = int(pair.get("potential_trace_index", -1))
        n = int(pair.get("n_points") or 0)
        hi = max(ci, ei)
        for idx in range(max(0, hi - 1), min(len(self.traces), hi + 4)):
            if idx in {ci, ei}:
                continue
            tr = self.traces[idx]
            label = re.sub(r"\s+", "", str(getattr(tr, "label", "") or "").lower())
            if label in {"log(i)", "logi", "log(|i|)", "logabs(i)"} or "log(i)" in label:
                tn = int(getattr(tr, "n_points", 0) or 0)
                if n <= 0 or tn == n:
                    return True
    except Exception:
        pass
    return False


def _heka_v16_get_cv_allocations(self):
    """Return point/block-aware CV allocations based on CV method entries and current/potential pairs."""
    allocations = []
    try:
        entries = _heka_v14_cv_entries(self)
        by = _heka_v15_current_potential_pairs_by_block(self)
    except Exception:
        entries, by = [], {}
    if not by:
        return allocations
    pairs_per_block = min((len(v) for v in by.values()), default=0)
    offset = 0
    file_method_index = 2
    if entries:
        for entry_i, entry in enumerate(entries, start=1):
            cycles = _heka_v14_parse_cycles_from_entry(entry)
            rate_v_s = _heka_v14_parse_rate_from_entry(entry)
            rate_label = _heka_v14_rate_label(rate_v_s, entry)
            if offset + cycles > pairs_per_block:
                break
            for bi in sorted(by):
                block_pairs = by[bi]
                for cyc in range(cycles):
                    idx = offset + cyc
                    if idx >= len(block_pairs):
                        continue
                    p = dict(block_pairs[idx])
                    allocations.append({
                        "block_index0": int(bi),
                        "point_index": int(bi) + 1,
                        "method_type": "CV",
                        "method_entry": entry_i,
                        "method_order_hint": file_method_index,
                        "cycle_index": cyc + 1,
                        "n_cycles": cycles,
                        "scan_rate_V_s": _heka_v16_float_or_none(rate_v_s),
                        "scan_rate_mV_s": (float(rate_v_s) * 1000.0 if np.isfinite(rate_v_s) else None),
                        "rate_label": rate_label,
                        "pair_index": int(p.get("pair_index", -1)),
                        "current_trace_index": int(p.get("current_trace_index", -1)),
                        "potential_trace_index": int(p.get("potential_trace_index", -1)),
                        "n_points": int(p.get("n_points") or 0),
                        "raw_method_text": str(entry.get("raw_text", ""))[:500],
                    })
            offset += cycles
            file_method_index += 1
    else:
        # No CV method text, but current/potential pairs exist. Preserve them as generic curves.
        for bi in sorted(by):
            for local_i, p in enumerate(by[bi], start=1):
                pair_type = "TAFEL_IV" if _heka_v297_pair_has_log_i(self, p) else "CURRENT_POTENTIAL_PAIR"
                allocations.append({
                    "block_index0": int(bi),
                    "point_index": int(bi) + 1,
                    "method_type": pair_type,
                    "method_entry": None,
                    "method_order_hint": local_i,
                    "cycle_index": 1,
                    "n_cycles": 1,
                    "scan_rate_V_s": None,
                    "scan_rate_mV_s": None,
                    "rate_label": "unknownRate",
                    "pair_index": int(p.get("pair_index", -1)),
                    "current_trace_index": int(p.get("current_trace_index", -1)),
                    "potential_trace_index": int(p.get("potential_trace_index", -1)),
                    "n_points": int(p.get("n_points") or 0),
                    "raw_method_text": "companion log(i) trace identifies IV/Tafel" if pair_type == "TAFEL_IV" else "",
                })
    return allocations


def _heka_v16_get_eis_allocations(self):
    allocations = []
    try:
        segments = _heka_v15_eis_segments_by_block(self)
        entries = _heka_v15_eis_entries(self)
    except Exception:
        segments, entries = {}, []
    for mi in sorted(segments):
        entry = entries[mi] if mi < len(entries) else (entries[0] if entries else {})
        f_start = _heka_v15_method_float(entry, "start_freq_Hz", "startfreq", default=float("nan"))
        f_end = _heka_v15_method_float(entry, "end_freq_Hz", "endfreq", default=float("nan"))
        f_hi = max(f_start, f_end) if np.isfinite(f_start) and np.isfinite(f_end) else None
        f_lo = min(f_start, f_end) if np.isfinite(f_start) and np.isfinite(f_end) else None
        ac_mV = _heka_v15_method_float(entry, "ac_amplitude_mV", "sine", default=float("nan"))
        for bi, groups in sorted((segments.get(mi) or {}).items()):
            n_freq = len(groups or [])
            allocations.append({
                "block_index0": int(bi),
                "point_index": int(bi) + 1,
                "method_type": "EIS",
                "method_entry": mi + 1,
                "method_order_hint": 100 + mi,
                "eis_segment_index": mi + 1,
                "n_frequency_rows": int(n_freq),
                "freq_max_Hz": f_hi,
                "freq_min_Hz": f_lo,
                "ac_amplitude_mV": _heka_v16_float_or_none(ac_mV),
                "group_indices": [int(g.group_index) for g in groups],
                "raw_method_text": str(entry.get("raw_text", ""))[:500],
            })
    return allocations


def _heka_v16_get_remaining_pair_allocations(self, cv_allocations):
    allocations = []
    try:
        by = _heka_v15_current_potential_pairs_by_block(self)
    except Exception:
        by = {}
    used = {int(a.get("pair_index", -1)) for a in cv_allocations}
    raw_methods = "\n".join(str(e.get("raw_text", "")) for e in getattr(self, "method_entries", []) or [])
    has_iv = bool(re.search(r"\b(Tafel|IV|I[- ]?V|Ramp|LSV|Linear)\b", raw_methods, re.I))
    has_ocp = bool(re.search(r"\b(OCP|Open\s*Circuit)\b", raw_methods, re.I))
    for bi in sorted(by):
        order = 200
        for p in by[bi]:
            pair_idx = int(p.get("pair_index", -1))
            if pair_idx in used:
                continue
            method_type = "TAFEL_IV" if has_iv else ("OCP" if has_ocp else "UNCATEGORIZED_CURRENT_POTENTIAL")
            allocations.append({
                "block_index0": int(bi),
                "point_index": int(bi) + 1,
                "method_type": method_type,
                "method_entry": None,
                "method_order_hint": order,
                "pair_index": pair_idx,
                "current_trace_index": int(p.get("current_trace_index", -1)),
                "potential_trace_index": int(p.get("potential_trace_index", -1)),
                "n_points": int(p.get("n_points") or 0),
                "raw_method_text": "remaining current/potential pair after CV allocation",
            })
            order += 1
    return allocations


def _heka_v16_build_sequence_model(self):
    try:
        takedata_rows, takedata_source = _heka_v15_position_rows_from_dat(self)
    except Exception as exc:
        takedata_rows, takedata_source = [], f"takedata_decode_failed: {exc}"
    blocks = list(getattr(self, "blocks", []) or [])
    if not blocks and getattr(self, "traces", None):
        # fallback pseudo-block for unusual non-EIS files
        blocks = [HekaBlock(0, [], [], list(range(len(self.traces))), "FULL")]
    cv_alloc = _heka_v16_get_cv_allocations(self)
    eis_alloc = _heka_v16_get_eis_allocations(self)
    other_alloc = _heka_v16_get_remaining_pair_allocations(self, cv_alloc)
    by_block = {}
    for item in cv_alloc + eis_alloc + other_alloc:
        by_block.setdefault(int(item.get("block_index0", 0)), []).append(dict(item))
    geom = _heka_v16_scan_geometry_from_takedata(takedata_rows)
    points = []
    n_points = max(len(blocks), len(takedata_rows), max(by_block.keys(), default=-1) + 1)
    for bi in range(n_points):
        b = blocks[bi] if bi < len(blocks) else None
        row = takedata_rows[bi] if bi < len(takedata_rows) else None
        point = {
            "point_index": bi + 1,
            "block_index0": bi,
            "status": getattr(b, "status", "") if b else "NO_BLOCK",
            "trace_count": len(getattr(b, "trace_indices", []) or []) if b else 0,
            "eis_group_count": len(getattr(b, "eis_group_indices", []) or []) if b else 0,
            "takedata": None,
            "methods": [],
        }
        if row is not None:
            point["takedata"] = {
                "sweep": int(row[0]) if len(row) > 0 and np.isfinite(row[0]) else None,
                "Imon_A": _heka_v16_float_or_none(row[1] if len(row) > 1 else None),
                "Emon_V": _heka_v16_float_or_none(row[2] if len(row) > 2 else None),
                "x_m": _heka_v16_float_or_none(row[3] if len(row) > 3 else None),
                "y_m": _heka_v16_float_or_none(row[4] if len(row) > 4 else None),
                "z_m": _heka_v16_float_or_none(row[5] if len(row) > 5 else None),
                "time_s": _heka_v16_float_or_none(row[6] if len(row) > 6 else None),
                "source": takedata_source,
            }
        methods = sorted(by_block.get(bi, []), key=lambda x: (int(x.get("method_order_hint") or 0), int(x.get("cycle_index") or 0), int(x.get("pair_index") or -1)))
        # Add explicit take-data method at the start for downstream sequence awareness.
        if point["takedata"] is not None:
            point["methods"].append({
                "sequence_order": 1,
                "method_type": "TAKEDATA",
                "method_name": "Takedata / stage-position record",
                "n_rows": 1,
                "source": takedata_source,
            })
        for m_i, m in enumerate(methods, start=2 if point["takedata"] is not None else 1):
            mt = m.get("method_type", "UNKNOWN")
            name = mt
            if mt == "CV":
                sr = m.get("scan_rate_mV_s")
                name = f"CV {sr:g} mV/s" if sr is not None else "CV"
                m["legacy_pyseccm_filename_hint"] = f"CV{m.get('rate_label', 'unknownRate')}_{m.get('n_cycles', 1)}cycles"
            elif mt == "EIS":
                fmin = m.get("freq_min_Hz"); fmax = m.get("freq_max_Hz")
                name = f"EIS {fmax:g}→{fmin:g} Hz" if fmin and fmax else "EIS"
                m["legacy_pyseccm_filename_hint"] = "fullEIS" if int(m.get("eis_segment_index", 1)) == 1 else f"fullEIS_method{m.get('eis_segment_index')}"
            elif mt == "TAFEL_IV":
                name = "IV/Tafel"
            elif mt == "OCP":
                name = "OCP"
            m = dict(m)
            m["sequence_order"] = m_i
            m["method_name"] = name
            m["method_signature"] = _heka_v16_method_signature(
                mt,
                name,
                scan_rate_V_s=m.get("scan_rate_V_s"),
                freq_min_Hz=m.get("freq_min_Hz"),
                freq_max_Hz=m.get("freq_max_Hz"),
                n_cycles=m.get("n_cycles"),
                n_rows=m.get("n_frequency_rows") or m.get("n_points"),
            )
            point["methods"].append(m)
        points.append(point)
    signatures = Counter()
    for p in points:
        sig = " > ".join(m.get("method_signature") or m.get("method_type", "UNKNOWN") for m in p.get("methods", []))
        signatures[sig] += 1
    model = {
        "format": HEKA_V16_SEQUENCE_FORMAT,
        "source_file": self.source_path,
        "point_count": len(points),
        "scan_geometry": geom,
        "takedata_source": takedata_source,
        "method_counts_total": dict(Counter(m.get("method_type", "UNKNOWN") for p in points for m in p.get("methods", []))),
        "sequence_template_counts": dict(signatures),
        "points": points,
        "notes": [
            "Built from HEKA DAT/PUL trace order, trace labels, online EIS groups, and parsed method text.",
            "Legacy pySECCM files are generated for compatibility, but this JSON/CSV manifest is the preferred robust interface for arbitrary experiment sequences."
        ],
    }
    return model


def _heka_v16_sequence_table_rows(model):
    rows = []
    for p in model.get("points", []):
        td = p.get("takedata") or {}
        for m in p.get("methods", []):
            rows.append({
                "point_index": p.get("point_index"),
                "block_index0": p.get("block_index0"),
                "point_status": p.get("status"),
                "x_m": td.get("x_m"),
                "y_m": td.get("y_m"),
                "z_m": td.get("z_m"),
                "time_s": td.get("time_s"),
                "sequence_order": m.get("sequence_order"),
                "method_type": m.get("method_type"),
                "method_name": m.get("method_name"),
                "method_entry": m.get("method_entry"),
                "cycle_index": m.get("cycle_index"),
                "n_cycles": m.get("n_cycles"),
                "n_points": m.get("n_points"),
                "n_frequency_rows": m.get("n_frequency_rows"),
                "scan_rate_V_s": m.get("scan_rate_V_s"),
                "scan_rate_mV_s": m.get("scan_rate_mV_s"),
                "freq_min_Hz": m.get("freq_min_Hz"),
                "freq_max_Hz": m.get("freq_max_Hz"),
                "ac_amplitude_mV": m.get("ac_amplitude_mV"),
                "pair_index": m.get("pair_index"),
                "current_trace_index": m.get("current_trace_index"),
                "potential_trace_index": m.get("potential_trace_index"),
                "eis_segment_index": m.get("eis_segment_index"),
                "group_indices": ";".join(map(str, m.get("group_indices", []) or [])),
                "legacy_pyseccm_filename_hint": m.get("legacy_pyseccm_filename_hint"),
                "method_signature": m.get("method_signature"),
            })
    return rows


def _heka_v16_export_sequence_files(self, output_dir: Path, safe: str):
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    model = _heka_v16_build_sequence_model(self)
    json_path = output_dir / f"{safe}_heka_sequence_manifest.json"
    csv_path = output_dir / f"{safe}_heka_sequence_table.csv"
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(model, f, indent=2, ensure_ascii=False)
    _heka_write_csv(csv_path, _heka_v16_sequence_table_rows(model))
    return model, [str(json_path), str(csv_path)]


def _heka_v16_write_canonical_per_point_csvs(self, root_dir: Path, safe: str, model: dict):
    """Write optional analysis-friendly per-point CSV files independent of legacy pySECCM naming."""
    base = Path(root_dir) / "data_by_point_sequence"
    base.mkdir(parents=True, exist_ok=True)
    written = []
    for p in model.get("points", []):
        point_dir = base / f"point_{int(p.get('point_index', 0)):03d}"
        point_dir.mkdir(parents=True, exist_ok=True)
        # Small point manifest
        with open(point_dir / "point_manifest.json", "w", encoding="utf-8") as f:
            json.dump(p, f, indent=2, ensure_ascii=False)
        written.append(str(point_dir / "point_manifest.json"))
        for m in p.get("methods", []):
            mt = m.get("method_type")
            if mt in {"CV", "CURRENT_POTENTIAL_PAIR", "TAFEL_IV", "OCP", "UNCATEGORIZED_CURRENT_POTENTIAL"}:
                ci = m.get("current_trace_index"); ei = m.get("potential_trace_index")
                if ci is None or ei is None:
                    continue
                try:
                    n = min(int(m.get("n_points") or 0), HEKA_V16_MAX_TRACE_POINTS_FOR_CANONICAL_CSV)
                    if n <= 0: continue
                    cur = np.asarray(self.read_trace_array(int(ci), max_points=n), dtype=float)
                    pot = np.asarray(self.read_trace_array(int(ei), max_points=n), dtype=float)
                    k = min(len(cur), len(pot))
                    if k <= 0: continue
                    dt = _heka_v15_trace_sample_interval_s(self, int(ei))
                    if not (np.isfinite(dt) and dt > 0): dt = 1.0
                    fn = f"seq{int(m.get('sequence_order', 0)):02d}_{PSSessionParser._sanitize_filename(mt)}.csv"
                    with open(point_dir / fn, "w", newline="", encoding="utf-8") as f:
                        w = csv.writer(f)
                        w.writerow(["index", "time_s", "potential_V", "current_A", "method_type", "scan_rate_V_s"])
                        for i in range(k):
                            w.writerow([i, i * dt, float(pot[i]), float(cur[i]), mt, m.get("scan_rate_V_s")])
                    written.append(str(point_dir / fn))
                except Exception:
                    pass
            elif mt == "EIS":
                groups = []
                for gi in m.get("group_indices", []) or []:
                    try:
                        groups.append(self.eis_groups[int(gi)])
                    except Exception:
                        pass
                if not groups:
                    continue
                try:
                    entry = None
                    entries = _heka_v15_eis_entries(self)
                    seg = int(m.get("eis_segment_index") or 1) - 1
                    if 0 <= seg < len(entries): entry = entries[seg]
                    freqs = _heka_v15_frequency_vector_for_segment(self, groups, entry=entry)
                    fn = f"seq{int(m.get('sequence_order', 0)):02d}_EIS.csv"
                    with open(point_dir / fn, "w", newline="", encoding="utf-8") as f:
                        w = csv.writer(f)
                        w.writerow(["frequency_Hz", "Zreal_ohm", "Zimag_ohm", "Zabs_ohm", "phase_deg", "Yreal_S", "Yimag_S", "Yabs_S"])
                        for g, fr in zip(groups, freqs):
                            row = _heka_v15_eis_row_from_group_with_freq(self, g, fr)
                            # row = [sweep, f, logf, Yabs, logY, Yreal, Yimag, phase, Zreal, Zimag, Zabs, logZ]
                            w.writerow([row[1], row[8], row[9], row[10], row[7], row[5], row[6], row[3]])
                    written.append(str(point_dir / fn))
                except Exception:
                    pass
    return written


# Export hook: call the v15 pySECCM generator, then add sequence manifest + canonical per-point files.
_HEKA_V16_ORIGINAL_SECCM_EXPORT = _heka_v14_export_seccm_plotting_analysis_outputs

def _heka_v16_export_seccm_plotting_analysis_outputs(self, output_dir: Path, base_name: str) -> dict:
    info = _HEKA_V16_ORIGINAL_SECCM_EXPORT(self, output_dir, base_name)
    safe = PSSessionParser._sanitize_filename(base_name)
    root = Path(info.get("root") or Path(output_dir) / f"{safe}_for_plotting_analysis")
    try:
        model, seq_files = _heka_v16_export_sequence_files(self, root, safe)
        canonical = _heka_v16_write_canonical_per_point_csvs(self, root, safe, model)
        info.setdefault("files", []).extend(seq_files)
        info.setdefault("files", []).extend(canonical[:20])
        info["sequence_manifest"] = seq_files[0]
        info["sequence_table"] = seq_files[1]
        info["data_by_point_sequence_folder"] = str(root / "data_by_point_sequence")
        info["n_sequence_points"] = int(model.get("point_count", 0))
        info["method_counts_total"] = model.get("method_counts_total", {})
        info["scan_type"] = (model.get("scan_geometry") or {}).get("scan_type")
        # Patch existing manifest if available.
        man_path = Path(info.get("manifest", ""))
        if man_path.exists():
            with open(man_path, "r", encoding="utf-8") as f:
                man = json.load(f)
            man["format"] = "heka-seccm-plotting-analysis-folder-v3-sequence-aware"
            man["sequence_manifest"] = seq_files[0]
            man["sequence_table"] = seq_files[1]
            man["data_by_point_sequence_folder"] = str(root / "data_by_point_sequence")
            man["scan_type"] = info.get("scan_type")
            man["method_counts_total"] = info.get("method_counts_total")
            man.setdefault("notes", []).append("v16: added generalized point→method sequence manifest and per-point canonical CSV folder.")
            with open(man_path, "w", encoding="utf-8") as f:
                json.dump(man, f, indent=2, ensure_ascii=False)
    except Exception as exc:
        info.setdefault("notes", []).append(f"v16 sequence-aware export failed: {exc}")
    return info

_heka_v14_export_seccm_plotting_analysis_outputs = _heka_v16_export_seccm_plotting_analysis_outputs


# Native payload hook.
_HEKA_V16_ORIGINAL_NATIVE_PAYLOAD = HEKAPotmasterParser.native_numeric_payload

def _heka_v16_native_numeric_payload(self):
    payload = _HEKA_V16_ORIGINAL_NATIVE_PAYLOAD(self)
    try:
        payload["heka_sequence_model"] = _heka_v16_build_sequence_model(self)
    except Exception as exc:
        payload["heka_sequence_model_error"] = str(exc)
    return payload

HEKAPotmasterParser.native_numeric_payload = _heka_v16_native_numeric_payload
HEKAPotmasterParser.primary_numeric_payload = _heka_v16_native_numeric_payload


# Summary hook for the main window.
_HEKA_V16_ORIGINAL_SUMMARIZE = HEKAPotmasterParser.summarize

def _heka_v16_summarize(self):
    s = _HEKA_V16_ORIGINAL_SUMMARIZE(self)
    try:
        model = _heka_v16_build_sequence_model(self)
        ds = s.setdefault("heka_detail_summary", {})
        ds["sequence_model_format"] = HEKA_V16_SEQUENCE_FORMAT
        ds["sequence_point_count"] = model.get("point_count")
        ds["scan_type_sequence_aware"] = (model.get("scan_geometry") or {}).get("scan_type")
        ds["method_counts_sequence_aware"] = model.get("method_counts_total", {})
        ds["sequence_template_counts"] = model.get("sequence_template_counts", {})
        s.setdefault("notes", []).append("v16: generalized point→method sequence model enabled; output includes sequence_manifest.json, sequence_table.csv, and data_by_point_sequence/.")
        # Replace/augment measurement_rows with sequence-aware point rows when HEKA has blocks.
        rows = []
        for p in model.get("points", [])[:500]:
            td = p.get("takedata") or {}
            method_labels = [m.get("method_name") or m.get("method_type") for m in p.get("methods", [])]
            rows.append({
                "index": p.get("point_index"),
                "title": f"Point {p.get('point_index')}",
                "method_id": "HEKA sequence point",
                "technique": "+".join(sorted(set(m.get("method_type", "") for m in p.get("methods", []))) or ["unknown"]),
                "n_curves": sum(1 for m in p.get("methods", []) if m.get("method_type") in {"CV", "CURRENT_POTENTIAL_PAIR", "TAFEL_IV", "OCP", "UNCATEGORIZED_CURRENT_POTENTIAL"}),
                "n_eis_blocks": sum(int(m.get("n_frequency_rows") or 0) for m in p.get("methods", []) if m.get("method_type") == "EIS"),
                "n_points": p.get("trace_count"),
                "status": p.get("status"),
                "x_m": td.get("x_m"), "y_m": td.get("y_m"), "z_m": td.get("z_m"), "time_s": td.get("time_s"),
                "details_text": "; ".join(method_labels),
            })
        if rows:
            s["measurement_rows"] = rows
    except Exception as exc:
        s.setdefault("notes", []).append(f"v16 sequence summary failed: {exc}")
    return s

HEKAPotmasterParser.summarize = _heka_v16_summarize
HEKAPotmasterParser.build_compact_summary = _heka_v16_summarize


# Display extra sequence information in the Session summary textbox.
_SESSION_READER_GUI_V16_ORIGINAL_DISPLAY_SUMMARY = SessionReaderGUI._display_summary

def _session_reader_gui_v16_display_summary(self, summary: dict):
    _SESSION_READER_GUI_V16_ORIGINAL_DISPLAY_SUMMARY(self, summary)
    extra = []
    def add(s, label=""):
        ds = s.get("heka_detail_summary") or {}
        if not ds.get("sequence_model_format"):
            return
        if label:
            extra.append(label)
        extra.append(f"  Sequence model: {ds.get('sequence_model_format')}")
        extra.append(f"  Scan type: {ds.get('scan_type_sequence_aware')}")
        extra.append(f"  Sequence points: {ds.get('sequence_point_count')}")
        extra.append(f"  Method counts: {ds.get('method_counts_sequence_aware')}")
        tmpl = ds.get("sequence_template_counts") or {}
        if tmpl:
            first = list(tmpl.items())[:3]
            extra.append("  Common point sequence(s): " + " | ".join(f"{v}× {k[:160]}" for k, v in first))
    try:
        if summary.get("mode") in {"zip", "directory"}:
            for entry in getattr(self.collection, "entries", [])[:20]:
                add(entry.get("parser").summarize(), f"HEKA sequence for {entry.get('entry_name')}:")
        else:
            add(summary)
    except Exception:
        pass
    if extra:
        cur = self.summary_text.get("1.0", "end").rstrip()
        self.summary_text.delete("1.0", "end")
        self.summary_text.insert("1.0", cur + "\n\n" + "\n".join(extra))

SessionReaderGUI._display_summary = _session_reader_gui_v16_display_summary


# ---- End HEKA v16 enhancements ----


# ---- HEKA v16.1 refinement: group CV cycles under each scan-rate method and improve geometry inference ----

def _heka_v16_unique_sorted_tol(vals, tol):
    vals = [float(x) for x in vals if x is not None and np.isfinite(float(x))]
    if not vals:
        return []
    vals.sort()
    out = [vals[0]]
    for v in vals[1:]:
        if abs(v - out[-1]) > tol:
            out.append(v)
    return out


def _heka_v16_scan_geometry_from_takedata(rows):
    n = len(rows or [])
    geom = {"scan_type": "single point" if n <= 1 else "ordered point sequence", "n_points": int(n), "axis_summary": {}, "evidence": []}
    if not rows:
        geom["scan_type"] = "unknown/no take-data rows"
        return geom
    xs = [_heka_v16_float_or_none(r[3]) for r in rows if len(r) > 3]
    ys = [_heka_v16_float_or_none(r[4]) for r in rows if len(r) > 4]
    zs = [_heka_v16_float_or_none(r[5]) for r in rows if len(r) > 5]
    spans = {}
    for name, vals in (("X", xs), ("Y", ys), ("Z", zs)):
        finite = [float(v) for v in vals if v is not None and np.isfinite(float(v))]
        spans[name] = (max(finite) - min(finite)) if finite else 0.0
    max_span = max(spans.values()) if spans else 0.0
    # Treat micron/sub-micron drift as non-scanned unless it is a meaningful fraction of the largest axis.
    axis_tol = max(1e-6, 0.005 * max_span)
    ux = _heka_v16_unique_sorted_tol(xs, axis_tol)
    uy = _heka_v16_unique_sorted_tol(ys, axis_tol)
    uz = _heka_v16_unique_sorted_tol(zs, axis_tol)
    geom["axis_summary"] = {
        "unique_x": len(ux), "unique_y": len(uy), "unique_z": len(uz),
        "x_span_m": spans.get("X"), "y_span_m": spans.get("Y"), "z_span_m": spans.get("Z"),
        "axis_tolerance_m": axis_tol,
        "x_min_m": min([v for v in xs if v is not None], default=None), "x_max_m": max([v for v in xs if v is not None], default=None),
        "y_min_m": min([v for v in ys if v is not None], default=None), "y_max_m": max([v for v in ys if v is not None], default=None),
        "z_min_m": min([v for v in zs if v is not None], default=None), "z_max_m": max([v for v in zs if v is not None], default=None),
    }
    varying = [axis for axis in ("X", "Y", "Z") if spans.get(axis, 0.0) > axis_tol]
    lateral = [axis for axis in ("X", "Y") if spans.get(axis, 0.0) > axis_tol]
    if len(lateral) >= 2 and len(ux) * max(1, len(uy)) >= max(4, int(0.75 * n)):
        geom["scan_type"] = "XY/2D grid or raster scan"
        geom["evidence"].append(f"X and Y both vary above tolerance {axis_tol:.3g} m")
    elif len(lateral) == 1:
        z_note = " with Z adjustment" if spans.get("Z", 0.0) > axis_tol else ""
        geom["scan_type"] = f"line scan along {lateral[0]}{z_note}"
        geom["evidence"].append(f"only lateral axis {lateral[0]} varies above tolerance {axis_tol:.3g} m; Z variation is treated as height/feedback, not XY rastering")
    elif spans.get("Z", 0.0) > axis_tol:
        geom["scan_type"] = "Z approach/depth scan"
        geom["evidence"].append(f"Z varies above tolerance {axis_tol:.3g} m while X/Y are constant")
    elif n > 1:
        geom["scan_type"] = "ordered point sequence / repeated single location"
        geom["evidence"].append("multiple points but no decoded stage axis varies above tolerance")
    else:
        geom["scan_type"] = "single point"
    return geom


def _heka_v177_group_cv_allocations(cv_alloc):
    grouped = {}
    for a in cv_alloc or []:
        if a.get("method_type") != "CV":
            grouped.setdefault((a.get("block_index0"), a.get("pair_index"), "single"), dict(a))
            continue
        key = (int(a.get("block_index0", 0)), a.get("method_entry"), a.get("scan_rate_V_s"), a.get("method_order_hint"))
        g = grouped.get(key)
        if g is None:
            g = dict(a)
            g["cycle_pairs"] = []
            grouped[key] = g
        g["cycle_pairs"].append({
            "cycle_index": a.get("cycle_index"),
            "pair_index": a.get("pair_index"),
            "current_trace_index": a.get("current_trace_index"),
            "potential_trace_index": a.get("potential_trace_index"),
            "n_points": a.get("n_points"),
        })
        g["n_cycles"] = max(int(g.get("n_cycles") or 1), len(g["cycle_pairs"]))
        g["n_points"] = sum(int(cp.get("n_points") or 0) for cp in g["cycle_pairs"])
    return list(grouped.values())


def _heka_v16_build_sequence_model(self):
    try:
        takedata_rows, takedata_source = _heka_v15_position_rows_from_dat(self)
    except Exception as exc:
        takedata_rows, takedata_source = [], f"takedata_decode_failed: {exc}"
    blocks = list(getattr(self, "blocks", []) or [])
    if not blocks and getattr(self, "traces", None):
        blocks = [HekaBlock(0, [], [], list(range(len(self.traces))), "FULL")]
    cv_alloc_raw = _heka_v16_get_cv_allocations(self)
    cv_alloc = _heka_v177_group_cv_allocations(cv_alloc_raw)
    eis_alloc = _heka_v16_get_eis_allocations(self)
    other_alloc = _heka_v16_get_remaining_pair_allocations(self, cv_alloc_raw)

    # v297: some legacy SECCM line/raster DAT2 files contain one HEKA block for
    # the whole acquisition even though the current/potential motif repeats once
    # per spatial point.  When the point count is independently available from
    # Takedata/fallback position rows, distribute the sequential pair allocations
    # across those points instead of attaching every Tafel curve to Point 001.
    cadence_redistributed = False
    ntd = len(takedata_rows)
    if len(blocks) == 1 and ntd > 1:
        pair_alloc = [a for a in (cv_alloc + other_alloc) if int(a.get("block_index0", 0)) == 0 and int(a.get("pair_index", -1)) >= 0]
        pair_alloc.sort(key=lambda a: int(a.get("pair_index", -1)))
        if len(pair_alloc) in {ntd, max(0, ntd - 1)}:
            for pi, item in enumerate(pair_alloc):
                item["block_index0"] = pi
                item["point_index"] = pi + 1
                item["allocation_basis"] = "v297 single-block repeated pair cadence matched to Takedata point count"
            cadence_redistributed = True
        if len(eis_alloc) == ntd and all(int(a.get("block_index0", 0)) == 0 for a in eis_alloc):
            for pi, item in enumerate(sorted(eis_alloc, key=lambda a: int(a.get("method_entry") or 0))):
                item["block_index0"] = pi
                item["point_index"] = pi + 1
                item["allocation_basis"] = "v297 single-block EIS cadence matched to Takedata point count"
            cadence_redistributed = True
    by_block = {}
    for item in cv_alloc + eis_alloc + other_alloc:
        by_block.setdefault(int(item.get("block_index0", 0)), []).append(dict(item))
    geom = _heka_v16_scan_geometry_from_takedata(takedata_rows)
    points = []
    n_points = max(len(blocks), len(takedata_rows), max(by_block.keys(), default=-1) + 1)
    for bi in range(n_points):
        b = blocks[bi] if bi < len(blocks) else None
        row = takedata_rows[bi] if bi < len(takedata_rows) else None
        point = {"point_index": bi + 1, "block_index0": bi, "status": getattr(b, "status", "") if b else "NO_BLOCK", "trace_count": len(getattr(b, "trace_indices", []) or []) if b else 0, "eis_group_count": len(getattr(b, "eis_group_indices", []) or []) if b else 0, "takedata": None, "methods": []}
        if row is not None:
            point["takedata"] = {"sweep": int(row[0]) if len(row) > 0 and np.isfinite(row[0]) else None, "Imon_A": _heka_v16_float_or_none(row[1] if len(row) > 1 else None), "Emon_V": _heka_v16_float_or_none(row[2] if len(row) > 2 else None), "x_m": _heka_v16_float_or_none(row[3] if len(row) > 3 else None), "y_m": _heka_v16_float_or_none(row[4] if len(row) > 4 else None), "z_m": _heka_v16_float_or_none(row[5] if len(row) > 5 else None), "time_s": _heka_v16_float_or_none(row[6] if len(row) > 6 else None), "source": takedata_source}
        methods = sorted(by_block.get(bi, []), key=lambda x: (int(x.get("method_order_hint") or 0), int(x.get("method_entry") or 0), int(x.get("cycle_index") or 0), int(x.get("pair_index") or -1)))
        if cadence_redistributed and b is None and methods:
            point["status"] = "INFERRED_FROM_METHOD_CADENCE"
            point["trace_count"] = sum(2 for m in methods if m.get("current_trace_index") is not None and m.get("potential_trace_index") is not None)
        if point["takedata"] is not None:
            point["methods"].append({"sequence_order": 1, "method_type": "TAKEDATA", "method_name": "Takedata / stage-position record", "n_rows": 1, "source": takedata_source})
        for m_i, m in enumerate(methods, start=2 if point["takedata"] is not None else 1):
            mt = m.get("method_type", "UNKNOWN")
            name = mt
            if mt == "CV":
                sr = m.get("scan_rate_mV_s")
                name = f"CV {sr:g} mV/s" if sr is not None else "CV"
                m["legacy_pyseccm_filename_hint"] = f"CV{m.get('rate_label', 'unknownRate')}_{m.get('n_cycles', 1)}cycles"
            elif mt == "EIS":
                fmin = m.get("freq_min_Hz"); fmax = m.get("freq_max_Hz")
                name = f"EIS {fmax:g}→{fmin:g} Hz" if fmin and fmax else "EIS"
                m["legacy_pyseccm_filename_hint"] = "fullEIS" if int(m.get("eis_segment_index", 1)) == 1 else f"fullEIS_method{m.get('eis_segment_index')}"
            elif mt == "TAFEL_IV":
                name = "IV/Tafel"
            elif mt == "OCP":
                name = "OCP"
            m = dict(m)
            m["sequence_order"] = m_i
            m["method_name"] = name
            m["method_signature"] = _heka_v16_method_signature(mt, name, scan_rate_V_s=m.get("scan_rate_V_s"), freq_min_Hz=m.get("freq_min_Hz"), freq_max_Hz=m.get("freq_max_Hz"), n_cycles=m.get("n_cycles"), n_rows=m.get("n_frequency_rows") or m.get("n_points"))
            point["methods"].append(m)
        points.append(point)
    signatures = Counter()
    for p in points:
        sig = " > ".join(m.get("method_signature") or m.get("method_type", "UNKNOWN") for m in p.get("methods", []))
        signatures[sig] += 1
    return {"format": HEKA_V16_SEQUENCE_FORMAT, "source_file": self.source_path, "point_count": len(points), "scan_geometry": geom, "takedata_source": takedata_source, "method_counts_total": dict(Counter(m.get("method_type", "UNKNOWN") for p in points for m in p.get("methods", []))), "sequence_template_counts": dict(signatures), "points": points, "notes": ["Built from HEKA DAT/PUL trace order, trace labels, online EIS groups, and parsed method text.", "CV cycles are grouped under each scan-rate method; individual cycle trace pairs are stored in cycle_pairs.", "v297 redistributes repeated single-block current/potential cadence across independently inferred spatial points when counts agree.", "A companion log(i) channel is treated as direct evidence that a current/potential pair is IV/Tafel rather than generic CV.", "Legacy pySECCM files are generated for compatibility, but this JSON/CSV manifest is the preferred robust interface for arbitrary experiment sequences."]}


def _heka_v16_sequence_table_rows(model):
    rows = []
    for p in model.get("points", []):
        td = p.get("takedata") or {}
        for m in p.get("methods", []):
            cps = m.get("cycle_pairs") or []
            rows.append({
                "point_index": p.get("point_index"), "block_index0": p.get("block_index0"), "point_status": p.get("status"),
                "x_m": td.get("x_m"), "y_m": td.get("y_m"), "z_m": td.get("z_m"), "time_s": td.get("time_s"),
                "sequence_order": m.get("sequence_order"), "method_type": m.get("method_type"), "method_name": m.get("method_name"), "method_entry": m.get("method_entry"),
                "cycle_index": m.get("cycle_index"), "n_cycles": m.get("n_cycles"), "n_points": m.get("n_points"), "n_frequency_rows": m.get("n_frequency_rows"),
                "scan_rate_V_s": m.get("scan_rate_V_s"), "scan_rate_mV_s": m.get("scan_rate_mV_s"), "freq_min_Hz": m.get("freq_min_Hz"), "freq_max_Hz": m.get("freq_max_Hz"), "ac_amplitude_mV": m.get("ac_amplitude_mV"),
                "pair_index": m.get("pair_index"), "cycle_pair_indices": ";".join(str(cp.get("pair_index")) for cp in cps),
                "current_trace_index": m.get("current_trace_index"), "potential_trace_index": m.get("potential_trace_index"), "eis_segment_index": m.get("eis_segment_index"), "group_indices": ";".join(map(str, m.get("group_indices", []) or [])),
                "legacy_pyseccm_filename_hint": m.get("legacy_pyseccm_filename_hint"), "method_signature": m.get("method_signature"),
            })
    return rows


def _heka_v16_write_canonical_per_point_csvs(self, root_dir: Path, safe: str, model: dict):
    base = Path(root_dir) / "data_by_point_sequence"
    base.mkdir(parents=True, exist_ok=True)
    written = []
    for p in model.get("points", []):
        point_dir = base / f"point_{int(p.get('point_index', 0)):03d}"
        point_dir.mkdir(parents=True, exist_ok=True)
        with open(point_dir / "point_manifest.json", "w", encoding="utf-8") as f:
            json.dump(p, f, indent=2, ensure_ascii=False)
        written.append(str(point_dir / "point_manifest.json"))
        for m in p.get("methods", []):
            mt = m.get("method_type")
            cycle_pairs = m.get("cycle_pairs") or []
            pair_sources = cycle_pairs if cycle_pairs else ([m] if mt in {"CV", "CURRENT_POTENTIAL_PAIR", "TAFEL_IV", "OCP", "UNCATEGORIZED_CURRENT_POTENTIAL"} else [])
            if pair_sources:
                try:
                    fn = f"seq{int(m.get('sequence_order', 0)):02d}_{PSSessionParser._sanitize_filename(mt)}.csv"
                    with open(point_dir / fn, "w", newline="", encoding="utf-8") as f:
                        w = csv.writer(f)
                        w.writerow(["cycle_index", "index", "time_s", "potential_V", "current_A", "method_type", "scan_rate_V_s"])
                        for src in pair_sources:
                            ci = src.get("current_trace_index"); ei = src.get("potential_trace_index")
                            if ci is None or ei is None: continue
                            n = min(int(src.get("n_points") or 0), HEKA_V16_MAX_TRACE_POINTS_FOR_CANONICAL_CSV)
                            if n <= 0: continue
                            cur = np.asarray(self.read_trace_array(int(ci), max_points=n), dtype=float)
                            pot = np.asarray(self.read_trace_array(int(ei), max_points=n), dtype=float)
                            k = min(len(cur), len(pot))
                            dt = _heka_v15_trace_sample_interval_s(self, int(ei))
                            if not (np.isfinite(dt) and dt > 0): dt = 1.0
                            cyc = src.get("cycle_index") or m.get("cycle_index") or 1
                            for i in range(k):
                                w.writerow([cyc, i, i * dt, float(pot[i]), float(cur[i]), mt, m.get("scan_rate_V_s")])
                    written.append(str(point_dir / fn))
                except Exception:
                    pass
            elif mt == "EIS":
                groups = []
                for gi in m.get("group_indices", []) or []:
                    try: groups.append(self.eis_groups[int(gi)])
                    except Exception: pass
                if not groups: continue
                try:
                    entries = _heka_v15_eis_entries(self)
                    seg = int(m.get("eis_segment_index") or 1) - 1
                    entry = entries[seg] if 0 <= seg < len(entries) else None
                    freqs = _heka_v15_frequency_vector_for_segment(self, groups, entry=entry)
                    fn = f"seq{int(m.get('sequence_order', 0)):02d}_EIS.csv"
                    with open(point_dir / fn, "w", newline="", encoding="utf-8") as f:
                        w = csv.writer(f); w.writerow(["frequency_Hz", "Zreal_ohm", "Zimag_ohm", "Zabs_ohm", "phase_deg", "Yreal_S", "Yimag_S", "Yabs_S"])
                        for g, fr in zip(groups, freqs):
                            row = _heka_v15_eis_row_from_group_with_freq(self, g, fr)
                            w.writerow([row[1], row[8], row[9], row[10], row[7], row[5], row[6], row[3]])
                    written.append(str(point_dir / fn))
                except Exception:
                    pass
    return written

# ---- End HEKA v16.1 refinement ----



# ---- HEKA v17 enhancement: synthetic fallback coordinates + pySECCM validation helper ----
# v17 keeps real HEKA/PUL stage coordinates whenever they are present.  If HEKA did not store
# X/Y/Z stage coordinates, or if only some rows contain usable X/Y/Z, the pySECCM-compatible
# take-data file is still generated with deterministic fallback coordinates and the filename is
# marked with SYNTHETIC_XYZ so the user can immediately see that those coordinates are not real.
APP_TITLE = "FaradaIQ Studio v273"
HEKA_V17_FORMAT_NOTE = "heka-v17-synthetic-coordinate-fallback"
HEKA_V17_SYNTHETIC_SPACING_M = 1.0e-6


def _heka_v17_is_finite_xyz(row):
    try:
        return bool(len(row) >= 6 and np.isfinite(float(row[3])) and np.isfinite(float(row[4])) and np.isfinite(float(row[5])))
    except Exception:
        return False


def _heka_v17_make_synthetic_xyz(n_points: int, spacing_m: float = HEKA_V17_SYNTHETIC_SPACING_M):
    """Return deterministic fallback coordinates as a simple ordered line scan.

    These coordinates are only used when HEKA did not store recoverable stage coordinates.
    They keep pySECCM/plotting scripts runnable but are explicitly identified as synthetic.
    """
    n = max(1, int(n_points or 1))
    return [(float(i) * float(spacing_m), 0.0, 0.0) for i in range(n)]


def _heka_v17_fill_missing_stage_coordinates(rows):
    """Fill missing X/Y/Z and return (rows, coordinate_mode, note)."""
    rows = [list(r) for r in (rows or [])]
    n = len(rows)
    if n <= 0:
        return rows, "none", "No take-data rows were available."

    finite_idx = [i for i, r in enumerate(rows) if _heka_v17_is_finite_xyz(r)]
    if len(finite_idx) == n:
        return rows, "real_HEKA_XYZ", "All X/Y/Z coordinates were decoded from HEKA/PUL records."

    # If some real coordinates exist, interpolate/extrapolate each axis over point order.
    # This preserves real coordinates and fills only missing rows; filename is still marked synthetic.
    if len(finite_idx) >= 2:
        x = np.arange(n, dtype=float)
        for col in (3, 4, 5):
            xp = np.array(finite_idx, dtype=float)
            yp = np.array([float(rows[i][col]) for i in finite_idx], dtype=float)
            filled = np.interp(x, xp, yp)
            for i in range(n):
                if len(rows[i]) < 7:
                    rows[i] = (rows[i] + [float("nan")] * 7)[:7]
                if not np.isfinite(float(rows[i][col])):
                    rows[i][col] = float(filled[i])
        return rows, "mixed_real_and_interpolated_SYNTHETIC_XYZ", f"Filled {n - len(finite_idx)} missing X/Y/Z rows by interpolation/extrapolation from {len(finite_idx)} real HEKA stage rows."

    # If only one real coordinate exists, keep it as a base point and create an ordered line in X.
    if len(finite_idx) == 1:
        base = rows[finite_idx[0]]
        bx, by, bz = float(base[3]), float(base[4]), float(base[5])
        for i in range(n):
            if len(rows[i]) < 7:
                rows[i] = (rows[i] + [float("nan")] * 7)[:7]
            if not _heka_v17_is_finite_xyz(rows[i]):
                rows[i][3] = bx + (i - finite_idx[0]) * HEKA_V17_SYNTHETIC_SPACING_M
                rows[i][4] = by
                rows[i][5] = bz
        return rows, "mixed_real_and_line_fallback_SYNTHETIC_XYZ", "Only one real HEKA stage coordinate was found; missing coordinates were filled as an ordered 1 µm-spaced X line from that point."

    # No real coordinates were decoded: create a simple ordered line scan.
    xyz = _heka_v17_make_synthetic_xyz(n)
    for i, (sx, sy, sz) in enumerate(xyz):
        if len(rows[i]) < 7:
            rows[i] = (rows[i] + [float("nan")] * 7)[:7]
        rows[i][3] = sx
        rows[i][4] = sy
        rows[i][5] = sz
    return rows, "fully_synthetic_ordered_X_line_SYNTHETIC_XYZ", f"No real HEKA X/Y/Z stage coordinates were decoded; generated {n} ordered fallback points at {HEKA_V17_SYNTHETIC_SPACING_M:g} m spacing along X."


_HEKA_V17_ORIGINAL_POSITION_ROWS_FROM_DAT = _heka_v15_position_rows_from_dat

def _heka_v17_position_rows_from_dat(self):
    rows, source = _HEKA_V17_ORIGINAL_POSITION_ROWS_FROM_DAT(self)
    rows, coord_mode, note = _heka_v17_fill_missing_stage_coordinates(rows)
    # Store lightweight diagnostics on the parser for export/summary use.
    try:
        self.heka_v17_coordinate_mode = coord_mode
        self.heka_v17_coordinate_note = note
        self.heka_v17_coordinate_is_synthetic = bool("SYNTHETIC" in coord_mode.upper())
    except Exception:
        pass
    if coord_mode == "real_HEKA_XYZ":
        return rows, source
    return rows, f"{source}__{coord_mode}"

# Replace the DAT/PUL take-data row source globally used by v15/v16/v17 export paths.
_heka_v15_position_rows_from_dat = _heka_v17_position_rows_from_dat
_heka_v14_estimated_position_rows = _heka_v17_position_rows_from_dat


def _heka_v17_position_filename(safe: str, source: str) -> str:
    src = str(source or "")
    if "SYNTHETIC" in src.upper():
        return f"{safe}_takedata_1_SYNTHETIC_XYZ.txt"
    return f"{safe}_takedata_1.txt"


def _heka_v14_write_position_file(self, data_dir: Path, safe: str):
    """v17 override: write real HEKA coordinates if present; otherwise write marked fallback coordinates."""
    rows, source = _heka_v15_position_rows_from_dat(self)
    data_dir = Path(data_dir)
    data_dir.mkdir(parents=True, exist_ok=True)
    fname = _heka_v17_position_filename(safe, source)
    path = data_dir / fname
    header = ["Sweep #", "Imon-2[A]", "Emon-2[V]", "X-pos[m]", "Y-pos[m]", "Z-pos[m]", "Time[s]"]
    _heka_v14_write_repeated_header_table(path, header, rows)
    info = {"path": str(path), "filename": path.name, "kind": "position/takedata", "n_rows": len(rows), "source": source}
    try:
        info["coordinate_mode"] = getattr(self, "heka_v17_coordinate_mode", "")
        info["synthetic_coordinates"] = bool("SYNTHETIC" in str(source).upper())
        info["coordinate_note"] = getattr(self, "heka_v17_coordinate_note", "")
    except Exception:
        pass
    return info


def _heka_v17_find_position_file_in_manifest(generated_entries):
    for row in generated_entries or []:
        if str(row.get("kind", "")).lower() == "position/takedata":
            p = Path(str(row.get("path", "")))
            if p.exists():
                return p
    return None


_HEKA_V17_ORIGINAL_SECCM_EXPORT = _heka_v16_export_seccm_plotting_analysis_outputs

def _heka_v17_export_seccm_plotting_analysis_outputs(self, output_dir: Path, base_name: str) -> dict:
    info = _HEKA_V17_ORIGINAL_SECCM_EXPORT(self, output_dir, base_name)
    safe = PSSessionParser._sanitize_filename(base_name)
    root = Path(info.get("root") or Path(output_dir) / f"{safe}_for_plotting_analysis")
    main_data = Path(info.get("main_data") or root / "data")
    man_path = Path(info.get("manifest", root / "plotting_analysis_manifest.json"))

    try:
        # Main data folder should contain exactly the file name that makes clear whether XYZ are real or fallback.
        rows, source = _heka_v15_position_rows_from_dat(self)
        expected_name = _heka_v17_position_filename(safe, source)
        expected_path = main_data / expected_name
        if not expected_path.exists():
            for p in main_data.glob(f"{safe}_takedata_1*.txt"):
                try:
                    p.unlink()
                except Exception:
                    pass
            _heka_v14_write_repeated_header_table(expected_path, ["Sweep #", "Imon-2[A]", "Emon-2[V]", "X-pos[m]", "Y-pos[m]", "Z-pos[m]", "Time[s]"], rows)

        info["position_file_for_pySECCM tools"] = str(expected_path)
        info["takedata_source"] = source
        info["synthetic_coordinates"] = bool("SYNTHETIC" in str(source).upper())
        info["coordinate_note"] = getattr(self, "heka_v17_coordinate_note", "")

        if man_path.exists():
            with open(man_path, "r", encoding="utf-8") as f:
                man = json.load(f)
            man["format"] = "heka-seccm-plotting-analysis-folder-v4-sequence-aware-synthetic-coordinate-aware"
            man["position_file_for_pySECCM tools"] = str(expected_path)
            man["takedata_source"] = source
            man["synthetic_coordinates"] = bool("SYNTHETIC" in str(source).upper())
            man["coordinate_note"] = getattr(self, "heka_v17_coordinate_note", "")
            man.setdefault("notes", []).append("v17: if HEKA/PUL X/Y/Z stage coordinates are missing, the take-data file is generated with deterministic fallback coordinates and the filename contains SYNTHETIC_XYZ.")
            with open(man_path, "w", encoding="utf-8") as f:
                json.dump(man, f, indent=2, ensure_ascii=False)
    except Exception as exc:
        info.setdefault("notes", []).append(f"v17 synthetic-coordinate take-data finalization failed: {exc}")
    return info

_heka_v14_export_seccm_plotting_analysis_outputs = _heka_v17_export_seccm_plotting_analysis_outputs


_HEKA_V17_ORIGINAL_NATIVE_PAYLOAD = HEKAPotmasterParser.native_numeric_payload

def _heka_v17_native_numeric_payload(self):
    payload = _HEKA_V17_ORIGINAL_NATIVE_PAYLOAD(self)
    try:
        rows, src = _heka_v15_position_rows_from_dat(self)
        payload["heka_v17_coordinate_policy"] = {
            "format": HEKA_V17_FORMAT_NOTE,
            "takedata_source": src,
            "synthetic_coordinates": bool("SYNTHETIC" in str(src).upper()),
            "coordinate_mode": getattr(self, "heka_v17_coordinate_mode", ""),
            "coordinate_note": getattr(self, "heka_v17_coordinate_note", ""),
            "fallback_spacing_m": HEKA_V17_SYNTHETIC_SPACING_M,
            "takedata_preview": rows[:20],
        }
    except Exception as exc:
        payload["heka_v17_coordinate_policy_error"] = str(exc)
    return payload

HEKAPotmasterParser.native_numeric_payload = _heka_v17_native_numeric_payload
HEKAPotmasterParser.primary_numeric_payload = _heka_v17_native_numeric_payload


_HEKA_V17_ORIGINAL_SUMMARIZE = HEKAPotmasterParser.summarize

def _heka_v17_summarize(self):
    s = _HEKA_V17_ORIGINAL_SUMMARIZE(self)
    try:
        rows, src = _heka_v15_position_rows_from_dat(self)
        ds = s.setdefault("heka_detail_summary", {})
        ds["v17_takedata_source"] = src
        ds["v17_synthetic_coordinates"] = bool("SYNTHETIC" in str(src).upper())
        ds["v17_coordinate_mode"] = getattr(self, "heka_v17_coordinate_mode", "")
        ds["v17_coordinate_note"] = getattr(self, "heka_v17_coordinate_note", "")
        ds["v17_fallback_spacing_m"] = HEKA_V17_SYNTHETIC_SPACING_M
        s.setdefault("notes", []).append("v17: missing HEKA X/Y/Z stage coordinates are filled with deterministic fallback coordinates and the take-data filename is marked SYNTHETIC_XYZ.")
    except Exception as exc:
        s.setdefault("notes", []).append(f"v17 coordinate policy summary failed: {exc}")
    return s

HEKAPotmasterParser.summarize = _heka_v17_summarize
HEKAPotmasterParser.build_compact_summary = _heka_v17_summarize


# Optional command-line smoke test helper for development and advanced users.
def heka_v17_smoke_test(input_dat: str, output_dir: str, pyseccm_dir: str | None = None) -> dict:
    """Load a HEKA DAT/support file, export analysis outputs, and optionally run pySECCM parsers.

    This is intentionally not called by the GUI automatically, but it makes it easy to validate a
    dataset from PowerShell/Python without opening the GUI.
    """
    p = HEKAPotmasterParser().load(input_dat)
    base = Path(input_dat).stem
    out = Path(output_dir)
    info = p.export_analysis_ready_outputs(out, base)
    result = {"export_info": info, "pyseccm_checks": []}
    try:
        seccm = info.get("seccm_plotting_analysis", {}) or info
        data_dir = Path(seccm.get("main_data") or "")
        pos_file = Path(seccm.get("position_file_for_pySECCM tools") or "")
        if not pos_file.exists() and data_dir.exists():
            candidates = sorted(data_dir.glob("*takedata*.txt"), key=lambda q: q.name)
            pos_file = candidates[0] if candidates else pos_file
        if pyseccm_dir:
            pyroot = Path(pyseccm_dir)
            import subprocess, sys
            if pos_file.exists() and data_dir.exists():
                eis_candidates = sorted(data_dir.glob("*fullEIS*.txt"), key=lambda q: q.name)
                cv_candidates = sorted(data_dir.glob("*CV*.asc"), key=lambda q: q.name)
                if eis_candidates and (pyroot / "parse_EIS.py").exists():
                    # pySECCM tools builds output paths relative to the passed filenames,
                    # so run inside the data folder and pass only filenames, matching the GUI runner.
                    cmd = [sys.executable, str(pyroot / "parse_EIS.py"), pos_file.name, eis_candidates[0].name]
                    cp = subprocess.run(cmd, cwd=str(data_dir), capture_output=True, text=True, timeout=120)
                    result["pyseccm_checks"].append({"script": "parse_EIS.py", "returncode": cp.returncode, "stdout_tail": cp.stdout[-1000:], "stderr_tail": cp.stderr[-2000:]})
                if cv_candidates and (pyroot / "parse_CV.py").exists():
                    cmd = [sys.executable, str(pyroot / "parse_CV.py"), cv_candidates[0].name]
                    cp = subprocess.run(cmd, cwd=str(data_dir), capture_output=True, text=True, timeout=120)
                    result["pyseccm_checks"].append({"script": "parse_CV.py", "returncode": cp.returncode, "stdout_tail": cp.stdout[-1000:], "stderr_tail": cp.stderr[-2000:]})
    except Exception as exc:
        result["pyseccm_check_error"] = str(exc)
    return result

# ---- End HEKA v17 enhancement ----



# ---- HEKA v19 enhancement: GUI launchers for each pySECCM tools command ----
# Adds dedicated CV/EIS/IV-OCP/DRT windows with file selectors and CLI option controls.
import sys as _v19_sys
import shlex as _v19_shlex
import threading as _v19_threading
import subprocess as _v19_subprocess

APP_TITLE = "FaradaIQ Studio v273"


def _v19_path_name(p):
    try:
        return Path(p).name
    except Exception:
        return str(p)


def _v19_quote_cmd(args):
    parts = []
    for a in args:
        s = str(a)
        if " " in s or "\t" in s or "(" in s or ")" in s:
            parts.append('"' + s.replace('"', '\\"') + '"')
        else:
            parts.append(s)
    return " ".join(parts)


def _v19_find_pyseccm_script_root(start_dirs=None):
    start_dirs = [Path(p) for p in (start_dirs or []) if p]
    here = Path(__file__).resolve().parent
    candidates = [
        here / "pyseccm_tools",
        here,
        Path.cwd() / "pyseccm_tools",
        Path.cwd(),
    ]
    for s in start_dirs:
        candidates.extend([
            s / "pyseccm_tools",
            s,
            s.parent / "pyseccm_tools",
            s.parent,
        ])
    seen = set()
    for p in candidates:
        try:
            rp = p.resolve()
        except Exception:
            rp = p
        if str(rp) in seen:
            continue
        seen.add(str(rp))
        if (p / "parse_CV.py").exists() and (p / "parse_EIS.py").exists():
            return str(p)
    return ""


def _v19_default_plotting_data_dir_for_gui(gui):
    # Prefer the generated pySECCM-compatible data folder for the currently loaded HEKA dataset.
    try:
        if getattr(gui, "collection", None) and getattr(gui.collection, "source_path", None):
            source_path = Path(gui.collection.source_path)
            base_name = source_path.stem if source_path.is_file() else source_path.name
            safe_base = PSSessionParser._sanitize_filename(base_name)
            out = Path(gui.output_dir_var.get().strip() or ".")
            candidates = [
                out / f"{safe_base}_analysis_ready_csv" / f"{safe_base}_for_plotting_analysis" / "data",
                out / f"{safe_base}_for_plotting_analysis" / "data",
                out / f"{safe_base}_analysis_ready_csv" / f"{safe_base}_for_plotting_analysis" / "data_generated_from_HEKA",
                out / f"{safe_base}_for_plotting_analysis" / "data_generated_from_HEKA",
            ]
            for c in candidates:
                if c.exists() and c.is_dir():
                    return str(c)
    except Exception:
        pass
    try:
        old = _session_reader_gui_v14_default_plotting_data_dir(gui)
        if old:
            return old
    except Exception:
        pass
    return str(Path(getattr(gui, "output_dir_var", tk.StringVar(value=".")).get() or ".").resolve())


def _v19_default_script_dir_for_gui(gui):
    starts = []
    try:
        starts.append(Path(gui.output_dir_var.get().strip() or "."))
    except Exception:
        pass
    try:
        if getattr(gui, "collection", None) and getattr(gui.collection, "source_path", None):
            starts.append(Path(gui.collection.source_path).parent)
    except Exception:
        pass
    found = _v19_find_pyseccm_script_root(starts)
    if found:
        return found
    try:
        return _session_reader_gui_v14_default_script_dir(gui)
    except Exception:
        return ""


def _v19_classify_file(path: Path):
    try:
        return _heka_v14_classify_companion_file(path)
    except Exception:
        low = path.name.lower()
        if "takedata" in low:
            return "position/takedata"
        if "fulleis" in low or "eis" in low:
            return "EIS"
        if "cv" in low and path.suffix.lower() in {".asc", ".txt", ".csv"}:
            return "CV"
        if "avg" in low and "ocp" in low:
            return "OCP-average"
        if "ocp" in low:
            return "OCP"
        if "corr" in low or "ecorr" in low or "icorr" in low:
            return "TAFEL-corr"
        if "tafel" in low or "iv" in low:
            return "TAFEL-IV"
        return "unknown"




def _v22_find_drt_input_dirs(data_dir: Path):
    """Return DRT input directories, including sample-scoped parse_EIS outputs.

    v22 pySECCM plotting writes into Figures/<sample_name>/Nyquist instead of
    Figures/Nyquist, so multiple datasets can coexist without overwriting.
    """
    d = Path(data_dir)
    candidates = [
        d.parent / "DRT_input_csv",
        d / "DRT_input_csv",
        d / "Figures" / "Nyquist",          # legacy
        d.parent / "Figures" / "Nyquist",   # legacy
    ]
    for fig_root in [d / "Figures", d.parent / "Figures"]:
        if fig_root.exists() and fig_root.is_dir():
            try:
                for sub in sorted(fig_root.iterdir(), key=lambda p: p.name.lower()):
                    ny = sub / "Nyquist"
                    if sub.is_dir() and ny.exists() and ny.is_dir():
                        candidates.append(ny)
            except Exception:
                pass
    out = []
    seen = set()
    for c in candidates:
        try:
            key = str(c.resolve())
        except Exception:
            key = str(c)
        if c.exists() and c.is_dir() and key not in seen:
            out.append(c)
            seen.add(key)
    return out

def _v19_detect_pyseccm_files(data_dir: Path):
    d = Path(data_dir)
    out = {"cv": [], "eis": [], "pos": [], "iv": [], "corr": [], "ocp": [], "avg_ocp": [], "drt_dir": []}
    if not d.exists() or not d.is_dir():
        return out
    try:
        files = sorted([p for p in d.iterdir() if p.is_file()], key=_heka_v14_nat_key_path)
    except Exception:
        files = sorted([p for p in d.iterdir() if p.is_file()], key=lambda p: p.name.lower())
    for p in files:
        kind = _v19_classify_file(p)
        if kind == "position/takedata":
            out["pos"].append(p)
        elif kind == "EIS":
            out["eis"].append(p)
        elif kind == "CV":
            out["cv"].append(p)
        elif kind == "TAFEL-corr":
            out["corr"].append(p)
        elif kind == "TAFEL-IV":
            out["iv"].append(p)
        elif kind == "OCP-average":
            out["avg_ocp"].append(p)
        elif kind == "OCP":
            out["ocp"].append(p)
    # Prefer DRT_input_csv generated by the HEKA exporter; if parse_EIS --plot has run, Figures/Nyquist is also valid.
    for c in _v22_find_drt_input_dirs(d):
        out["drt_dir"].append(c)
    return out


def _v19_first(paths):
    return str(paths[0]) if paths else ""


class PySECCMRunWindow(tk.Toplevel):
    """Tool-specific pySECCM tools runner.

    The controls mirror the command-line forms in README-CV, README-EIS,
    README-TAFEL, README-OCP, and headless_pyDRTtools/README.
    """
    TOOL_TITLES = {
        "cv": "pySECCM CV parser: parse_CV.py cv_file [--plot]",
        "eis": "pySECCM EIS parser: parse_EIS.py pos_file eis_file [--plot] [--n_grid]",
        "iv": "pySECCM IV/Tafel parser: parse_IV.py pos_file corr_file iv_file [--plot] [--n_grid]",
        "ocp": "pySECCM OCP parser: parse_OCP.py pos_file avg_ocp_file ocp_file [--plot] [--n_grid]",
        "drt": "headless pyDRTtools: headless_pyDRTtools.py input_dir [options]",
    }

    def __init__(self, master=None, tool="eis", default_data_dir="", default_script_dir=""):
        super().__init__(master)
        self.tool = tool.lower().strip()
        self.title(self.TOOL_TITLES.get(self.tool, "pySECCM Runner"))
        self.geometry("1060x760")
        self.minsize(900, 620)
        self.data_dir_var = tk.StringVar(value=str(default_data_dir or Path.cwd()))
        self.script_dir_var = tk.StringVar(value=str(default_script_dir or _v19_find_pyseccm_script_root([default_data_dir])))
        self.python_var = tk.StringVar(value=_v19_sys.executable)
        self.plot_var = tk.BooleanVar(value=True)
        self.run_all_cv_var = tk.BooleanVar(value=True)
        self.n_grid_var = tk.StringVar(value="100")
        self.cv_file_var = tk.StringVar()
        self.pos_file_var = tk.StringVar()
        self.eis_file_var = tk.StringVar()
        self.corr_file_var = tk.StringVar()
        self.iv_file_var = tk.StringVar()
        self.avg_ocp_file_var = tk.StringVar()
        self.ocp_file_var = tk.StringVar()
        self.drt_input_dir_var = tk.StringVar()
        self.rbf_type_var = tk.StringVar(value="gaussian")
        self.data_used_var = tk.StringVar(value="combined")
        self.derivative_var = tk.StringVar(value="1")
        self.inductance_var = tk.StringVar(value="without")
        self.regularization_var = tk.StringVar(value="1.0E-3")
        self.shape_control_var = tk.StringVar(value="fwhm")
        self.coefficient_var = tk.StringVar(value="0.5")
        self.sample_number_var = tk.StringVar(value="2000")
        self.drt_run_id_var = tk.StringVar(value="")  # blank = automatic timestamp/UUID folder
        self.run_type_vars = {k: tk.BooleanVar(value=(k == "simple")) for k in ["simple", "bayesian", "bht"]}
        self.plot_type_vars = {k: tk.BooleanVar(value=(k in {"eis", "drt"})) for k in ["eis", "magnitude", "phase", "re", "im", "re_residual", "im_residual", "drt", "score"]}
        self.export_type_vars = {k: tk.BooleanVar(value=(k == "drt")) for k in ["drt", "eis"]}
        self.detected = {}
        self._build_ui()
        self.auto_detect()

    def _build_ui(self):
        outer = ttk.Frame(self, padding=10)
        outer.pack(fill="both", expand=True)
        common = ttk.LabelFrame(outer, text="Common settings", padding=8)
        common.pack(fill="x")
        ttk.Label(common, text="Parsed data folder").grid(row=0, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(common, textvariable=self.data_dir_var, width=95).grid(row=0, column=1, sticky="ew", pady=3)
        ttk.Button(common, text="Browse", command=self.browse_data_dir).grid(row=0, column=2, padx=(8, 0), pady=3)
        ttk.Label(common, text="pySECCM tools folder").grid(row=1, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(common, textvariable=self.script_dir_var, width=95).grid(row=1, column=1, sticky="ew", pady=3)
        ttk.Button(common, text="Browse", command=self.browse_script_dir).grid(row=1, column=2, padx=(8, 0), pady=3)
        ttk.Label(common, text="Python executable").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(common, textvariable=self.python_var, width=95).grid(row=2, column=1, sticky="ew", pady=3)
        ttk.Button(common, text="Browse", command=self.browse_python).grid(row=2, column=2, padx=(8, 0), pady=3)
        common.columnconfigure(1, weight=1)

        specific = ttk.LabelFrame(outer, text=self.TOOL_TITLES.get(self.tool, "Tool options"), padding=8)
        specific.pack(fill="x", pady=(10, 0))
        self._specific_frame = specific
        if self.tool == "cv":
            self._build_cv_options(specific)
        elif self.tool == "eis":
            self._build_eis_options(specific)
        elif self.tool == "iv":
            self._build_iv_options(specific)
        elif self.tool == "ocp":
            self._build_ocp_options(specific)
        elif self.tool == "drt":
            self._build_drt_options(specific)

        btns = ttk.Frame(outer)
        btns.pack(fill="x", pady=(10, 8))
        ttk.Button(btns, text="Auto-detect files", command=self.auto_detect).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Show command", command=self.show_command).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Run", command=self.run).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Open data folder", command=self.open_data_folder).pack(side="left", padx=(12, 6))
        ttk.Button(btns, text="Open script folder", command=self.open_script_folder).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=self.destroy).pack(side="right")

        self.log_text = ScrolledText(outer, wrap="word")
        self.log_text.pack(fill="both", expand=True)

    def _file_row(self, parent, row, label, var, filetypes=None):
        ttk.Label(parent, text=label).grid(row=row, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(parent, textvariable=var, width=100).grid(row=row, column=1, sticky="ew", pady=3)
        ttk.Button(parent, text="Browse", command=lambda: self.browse_file_var(var, filetypes=filetypes)).grid(row=row, column=2, padx=(8, 0), pady=3)
        parent.columnconfigure(1, weight=1)

    def _dir_row(self, parent, row, label, var):
        ttk.Label(parent, text=label).grid(row=row, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(parent, textvariable=var, width=100).grid(row=row, column=1, sticky="ew", pady=3)
        ttk.Button(parent, text="Browse", command=lambda: self.browse_dir_var(var)).grid(row=row, column=2, padx=(8, 0), pady=3)
        parent.columnconfigure(1, weight=1)

    def _build_cv_options(self, f):
        self._file_row(f, 0, "CV file", self.cv_file_var, [("CV files", "*.asc *.txt *.csv"), ("All files", "*.*")])
        ttk.Checkbutton(f, text="Run all detected CV files in parsed data folder", variable=self.run_all_cv_var).grid(row=1, column=1, sticky="w", pady=3)
        ttk.Checkbutton(f, text="--plot", variable=self.plot_var).grid(row=2, column=1, sticky="w", pady=3)
        ttk.Label(f, text="README command: python parse_CV.py cv_file --plot").grid(row=3, column=1, sticky="w", pady=3)

    def _build_eis_options(self, f):
        self._file_row(f, 0, "Position/takedata file", self.pos_file_var, [("Takedata", "*.txt *.csv"), ("All files", "*.*")])
        self._file_row(f, 1, "Full EIS file", self.eis_file_var, [("EIS", "*.txt *.csv"), ("All files", "*.*")])
        ttk.Checkbutton(f, text="--plot", variable=self.plot_var).grid(row=2, column=1, sticky="w", pady=3)
        ttk.Label(f, text="--n_grid").grid(row=3, column=0, sticky="w", padx=(0, 8), pady=3)
