        self._file_row(f, 1, "Averaged OCP file", self.avg_ocp_file_var, [("OCP avg", "*.txt *.asc *.csv"), ("All files", "*.*")])
        self._file_row(f, 2, "Full OCP file", self.ocp_file_var, [("OCP full", "*.txt *.asc *.csv"), ("All files", "*.*")])
