# ---- HEKA v22 enhancement: dependency checking/install + command-window runners ----
import importlib.util as _v22_importlib_util
import tempfile as _v22_tempfile
import os as _v22_os

APP_TITLE = "FaradaIQ Studio v273"

_V22_BASE_MODULES = {
    "numpy": "numpy",
    "pandas": "pandas",
    "scipy": "scipy",
    "matplotlib": "matplotlib",
}
_V22_DRT_MODULES = {
    "cvxpy": "cvxpy",
    "PyQt5": "PyQt5",
}
_V22_IMAGE_MODULES = {
    "PIL": "pillow",
}


def _v22_required_modules(kind="all"):
    kind = (kind or "all").lower()
    mods = dict(_V22_BASE_MODULES)
    if kind in {"all", "drt"}:
        mods.update(_V22_DRT_MODULES)
    if kind in {"all", "image", "gui"}:
        mods.update(_V22_IMAGE_MODULES)
    return mods


def _v22_missing_modules_in_current_python(kind="all"):
    missing = []
    for mod, pip_name in _v22_required_modules(kind).items():
        if _v22_importlib_util.find_spec(mod) is None:
            missing.append((mod, pip_name))
    return missing


def _v22_missing_modules_for_python(python_exe, kind="all"):
    """Return [(module, pip_package), ...] for the selected Python executable."""
    python_exe = str(python_exe or _v19_sys.executable)
    mods = _v22_required_modules(kind)
    code = (
        "import importlib.util, json; "
        "mods=%r; "
        "print(json.dumps([m for m in mods if importlib.util.find_spec(m) is None]))"
    ) % list(mods.keys())
    try:
        cp = _v19_subprocess.run([python_exe, "-c", code], capture_output=True, text=True, timeout=30)
        if cp.returncode != 0:
            # If this Python itself cannot run the check, report all as unresolved rather than silently passing.
            return [(m, p) for m, p in mods.items()]
        import json as _json
        missing_mods = _json.loads((cp.stdout or "[]").strip().splitlines()[-1])
        return [(m, mods[m]) for m in missing_mods if m in mods]
    except Exception:
        return [(m, p) for m, p in mods.items()]


def _v22_pip_install_batch_text(python_exe, pip_packages, title="Install pySECCM dependencies"):
    python_exe = str(python_exe or _v19_sys.executable)
    packages = []
    for p in pip_packages:
        if p and p not in packages:
            packages.append(str(p))
    pkg_cmd = " ".join(_v19_quote_cmd([p]) for p in packages)
    py = _v19_quote_cmd([python_exe])
    return f"""@echo off
chcp 65001 >nul
title {title}
echo ============================================================
echo {title}
echo Python: {python_exe}
echo Packages: {', '.join(packages)}
echo ============================================================
echo.
{py} -m pip --version
IF ERRORLEVEL 1 (
  echo pip is not available. Trying ensurepip...
  {py} -m ensurepip --upgrade
)
echo.
echo Upgrading pip/setuptools/wheel first...
{py} -m pip install --upgrade pip setuptools wheel
echo.
echo Installing missing dependencies...
{py} -m pip install --upgrade {pkg_cmd}
echo.
echo Dependency installation finished with exit code %ERRORLEVEL%.
echo Close this window, then rerun the parser/DRT command from the GUI.
echo.
pause
"""


def _v22_write_bat_and_launch(batch_text, cwd=None, prefix="electrochem_bridge"):
    cwd = Path(cwd or Path.cwd())
    fd, bat_path = _v22_tempfile.mkstemp(prefix=prefix + "_", suffix=".bat", text=True)
    with _v22_os.fdopen(fd, "w", encoding="utf-8", newline="\r\n") as f:
        f.write(batch_text)
    if _v19_sys.platform.startswith("win"):
        flags = getattr(_v19_subprocess, "CREATE_NEW_CONSOLE", 0)
        _v19_subprocess.Popen(["cmd.exe", "/k", bat_path], cwd=str(cwd), creationflags=flags)
    else:
        # Non-Windows fallback: run in background and let caller inspect logs if launched from a terminal.
        _v19_subprocess.Popen(["sh", bat_path], cwd=str(cwd))
    return bat_path


def _v22_command_batch_text(commands, title="pySECCM run"):
    lines = [
        "@echo off",
        "chcp 65001 >nul",
        f"title {title}",
        "echo ============================================================",
        f"echo {title}",
        "echo ============================================================",
        "echo.",
    ]
    for i, (args, cwd) in enumerate(commands, start=1):
        cwd = Path(cwd)
        cmdline = _v19_subprocess.list2cmdline([str(a) for a in args])
        lines += [
            f"echo [{i}/{len(commands)}] Working folder:",
            f"echo {cwd}",
            f"cd /d {_v19_subprocess.list2cmdline([str(cwd)])}",
            "echo.",
            "echo Command:",
            f"echo {cmdline}",
            "echo ------------------------------------------------------------",
            cmdline,
            "set LAST_EXIT=%ERRORLEVEL%",
            "echo ------------------------------------------------------------",
            "echo Exit code: %LAST_EXIT%",
            "echo.",
        ]
    lines += [
        "echo All requested commands finished.",
        "echo This window is intentionally left open so you can inspect errors/output.",
        "echo.",
        "pause",
    ]
    return "\n".join(lines) + "\n"


def _v22_install_dependencies_for_python(python_exe=None, kind="all", parent=None, force=False):
    python_exe = str(python_exe or _v19_sys.executable)
    missing = _v22_missing_modules_for_python(python_exe, kind=kind)
    if not missing and not force:
        try:
            messagebox.showinfo("Dependencies OK", f"Required {kind} dependencies are already available for:\n{python_exe}")
        except Exception:
            pass
        return []
    packages = [pip_name for _, pip_name in (missing or _v22_required_modules(kind).items())]
    if missing:
        msg = "Missing Python dependencies for:\n" + python_exe + "\n\n" + "\n".join(f"  {m}  (pip: {p})" for m, p in missing) + "\n\nOpen a command window and install them now?"
    else:
        msg = "Reinstall/upgrade required dependencies for:\n" + python_exe + "\n\nOpen a command window now?"
    try:
        ok = messagebox.askyesno("Install pySECCM/DRT dependencies", msg, parent=parent)
    except Exception:
        ok = True
    if not ok:
        return missing
    batch = _v22_pip_install_batch_text(python_exe, packages, title=f"Install ElectroChem Bridge {kind} dependencies")
    bat = _v22_write_bat_and_launch(batch, cwd=Path(__file__).resolve().parent, prefix="install_pyseccm_deps")
    try:
        if parent is not None and hasattr(parent, "log"):
            parent.log(f"Opened dependency installer command window: {bat}")
    except Exception:
        pass
    return missing


def _session_reader_gui_v22_check_install_pyseccm_dependencies(self):
    _v22_install_dependencies_for_python(_v19_sys.executable, kind="all", parent=self)


# Patch runner window: add dependency buttons and run commands in separate command windows.
