def _pyseccm_run_window_v22_dependency_kind(self):
    return "drt" if getattr(self, "tool", "").lower() == "drt" else "base"


def _pyseccm_run_window_v22_check_install_dependencies(self, force=False):
    return _v22_install_dependencies_for_python(self.python_var.get().strip() or _v19_sys.executable, kind=_pyseccm_run_window_v22_dependency_kind(self), parent=self, force=force)


def _pyseccm_run_window_v22_run(self):
    try:
        commands = self.build_commands()
    except Exception as exc:
        messagebox.showerror("Run error", str(exc), parent=self)
        self.log(f"Run error: {exc}")
        return
    kind = _pyseccm_run_window_v22_dependency_kind(self)
    missing = _v22_missing_modules_for_python(self.python_var.get().strip() or _v19_sys.executable, kind=kind)
    if missing:
        msg = "Missing dependencies were found for this selected Python:\n\n" + "\n".join(f"  {m} (pip: {p})" for m, p in missing) + "\n\nInstall now? After installation, click Run again."
        if messagebox.askyesno("Missing dependencies", msg, parent=self):
            _v22_install_dependencies_for_python(self.python_var.get().strip() or _v19_sys.executable, kind=kind, parent=self)
        else:
            self.log("Run cancelled because dependencies are missing.")
        return
    try:
        for args, cwd in commands:
            if "--plot" in args:
                self._maybe_style(Path(cwd))
        batch = _v22_command_batch_text(commands, title=self.title())
        bat = _v22_write_bat_and_launch(batch, cwd=commands[0][1], prefix="run_pyseccm")
        self.log("Opened separate Command Prompt window for run.")
        self.log(f"Batch file: {bat}")
        self.show_command()
    except Exception as exc:
        messagebox.showerror("Run error", str(exc), parent=self)
        self.log(f"FAILED to launch command window: {exc}")

PySECCMRunWindow._build_ui = _pyseccm_run_window_v22_build_ui
PySECCMRunWindow.check_install_dependencies = _pyseccm_run_window_v22_check_install_dependencies
