# ---- HEKA v26 enhancement: isolated venv dependency environment for pySECCM/DRT ----
APP_TITLE = "FaradaIQ Studio v273"

_V26_BASE_REQUIREMENTS = [
    "numpy==1.26.4",
    "pandas==2.2.2",
    "scipy==1.13.1",
    "matplotlib==3.8.4",
    "contourpy==1.2.0",
    "pillow==10.3.0",
]
_V26_DRT_REQUIREMENTS = [
    "cvxpy==1.6.7",
    "PyQt5==5.15.10",
]


def _v26_requirement_specs(kind="all"):
    kind = (kind or "all").lower()
    reqs = list(_V26_BASE_REQUIREMENTS)
    if kind in {"all", "drt"}:
        reqs.extend(_V26_DRT_REQUIREMENTS)
    out = []
    seen = set()
    for req in reqs:
        key = req.lower()
        if key not in seen:
            seen.add(key)
            out.append(req)
    return out


def _v26_import_check_code(kind="all"):
    kind = (kind or "all").lower()
    modules = ["numpy", "pandas", "scipy", "matplotlib", "PIL"]
    if kind in {"all", "drt"}:
        modules.extend(["cvxpy", "PyQt5"])
    return (
        "import importlib, sys, traceback\n"
        f"mods={modules!r}\n"
        "broken=[]\n"
        "try:\n"
        "    import numpy as np\n"
        "    print('numpy', np.__version__)\n"
        "    if int(str(np.__version__).split('.')[0]) >= 2:\n"
        "        broken.append(('numpy', 'NumPy 2.x detected; use numpy==1.26.4 for this Anaconda-compatible stack'))\n"
        "except Exception as exc:\n"
        "    broken.append(('numpy', repr(exc)))\n"
        "for m in mods:\n"
        "    if m == 'numpy':\n"
        "        continue\n"
        "    try:\n"
        "        mod = importlib.import_module(m)\n"
        "        print(m, getattr(mod, '__version__', 'OK'))\n"
        "    except Exception:\n"
        "        broken.append((m, traceback.format_exc()))\n"
        "if broken:\n"
        "    print('BROKEN_IMPORTS_BEGIN')\n"
        "    for m, err in broken:\n"
        "        print('---', m, '---')\n"
        "        print(err)\n"
        "    print('BROKEN_IMPORTS_END')\n"
        "    sys.exit(4)\n"
        "print('IMPORT_CHECK_OK')\n"
    )


def _v22_missing_modules_for_python(python_exe, kind="all"):
    """v26 override: import modules, catching binary incompatibility, not just find_spec."""
    python_exe = str(python_exe or _v19_sys.executable)
    code = _v26_import_check_code(kind)
    try:
        cp = _v19_subprocess.run([python_exe, "-c", code], capture_output=True, text=True, timeout=90)
        if cp.returncode == 0 and "IMPORT_CHECK_OK" in (cp.stdout or ""):
            return []
        return [("scientific_stack_repair", " ".join(_v26_requirement_specs(kind)))]
    except Exception:
        return [("scientific_stack_repair", " ".join(_v26_requirement_specs(kind)))]


def _v22_pip_install_batch_text(python_exe, pip_packages=None, title="Repair ElectroChem Bridge dependencies"):
    """v26 override: install a pinned NumPy-1.26-compatible stack and do not upgrade NumPy to 2.x."""
    python_exe = str(python_exe or _v19_sys.executable)
    title_lower = str(title).lower()
    kind = "base" if (("base" in title_lower or "cv" in title_lower or "eis" in title_lower or "iv" in title_lower or "ocp" in title_lower) and "drt" not in title_lower) else "all"
    reqs = _v26_requirement_specs(kind)
    req_cmd = " ".join(_v19_quote_cmd([p]) for p in reqs)
    py = _v19_quote_cmd([python_exe])
    import_check = _v26_import_check_code("all" if kind == "all" else "base").replace('"', '\"').replace('%', '%%')
    return f"""@echo off
chcp 65001 >nul
title {title}
echo ============================================================
echo {title}
echo Python: {python_exe}
echo ============================================================
echo.
{py} -m pip --version
IF ERRORLEVEL 1 (
  echo pip is not available. Trying ensurepip...
  {py} -m ensurepip --upgrade
)
echo.
echo Installing pinned NumPy-1.26-compatible dependency set.
echo This intentionally prevents NumPy 2.x from breaking pandas/scipy/matplotlib binary wheels.
echo.
{py} -m pip install --no-cache-dir --force-reinstall {req_cmd}
echo.
echo Running import sanity check...
{py} -c "{import_check}"
echo.
echo Dependency repair finished with exit code %%ERRORLEVEL%%.
echo Close this window, then rerun the parser/DRT command from the GUI.
echo.
pause
"""


def _v22_install_dependencies_for_python(python_exe=None, kind="all", parent=None, force=False):
    """v26 override: repair with pinned versions whenever missing/broken imports are detected."""
    python_exe = str(python_exe or _v19_sys.executable)
    missing = _v22_missing_modules_for_python(python_exe, kind=kind)
    if not missing and not force:
        try:
            messagebox.showinfo("Dependencies OK", f"Required {kind} dependencies import cleanly for:\n{python_exe}")
        except Exception:
            pass
        return []
    reqs = _v26_requirement_specs(kind)
    msg = (
        "Dependencies are missing or binary-incompatible for:\n" + python_exe +
        "\n\nThis often happens when pip upgraded NumPy to 2.x inside Anaconda, while "
        "pandas/scipy/matplotlib were compiled against NumPy 1.x.\n\n"
        "Repair now with the pinned NumPy-1.26-compatible set?\n\n" +
        "\n".join("  " + r for r in reqs)
    )
    try:
        ok = messagebox.askyesno("Repair pySECCM/DRT dependencies", msg, parent=parent)
    except Exception:
        ok = True
    if not ok:
        return missing
    batch = _v22_pip_install_batch_text(python_exe, reqs, title=f"Repair ElectroChem Bridge {kind} dependencies")
    bat = _v22_write_bat_and_launch(batch, cwd=Path(__file__).resolve().parent, prefix="repair_pyseccm_deps")
    try:
        if parent is not None and hasattr(parent, "log"):
            parent.log(f"Opened dependency repair command window: {bat}")
    except Exception:
        pass
    return missing

# ---- End HEKA v26 dependency repair enhancement ----


# ---- HEKA v27 enhancement: optional auto-run all pySECCM/DRT parsers after export ----
# Adds a main-GUI checkbox.  When selected, Export archive + analysis-ready CSV will also
# launch the default pySECCM/DRT pipeline for every generated *_for_plotting_analysis/data folder.
# CV/EIS/IV/OCP run with --plot; EIS/IV/OCP use --n_grid 100; DRT runs simple DRT if DRT input CSVs exist.
APP_TITLE = "FaradaIQ Studio v273"


def _v27_find_widget_by_text(root, widget_cls_name, text_value):
    """Find a Tk/ttk widget recursively by its configured text label."""
    try:
        if root.winfo_class() == widget_cls_name and str(root.cget("text")) == str(text_value):
            return root
    except Exception:
        pass
    try:
        for child in root.winfo_children():
            found = _v27_find_widget_by_text(child, widget_cls_name, text_value)
            if found is not None:
                return found
    except Exception:
        pass
    return None


def _v27_current_base_name(gui):
    try:
        source_path = Path(gui.collection.source_path)
        return source_path.stem if source_path.is_file() else source_path.name
    except Exception:
        return "electrochem_session"


def _v27_candidate_plotting_data_dirs(gui, base_name=None):
    """Return generated pySECCM-compatible data folders for the current export."""
    base_name = base_name or _v27_current_base_name(gui)
    out = Path(gui.output_dir_var.get().strip() or ".").resolve()
    safe_base = PSSessionParser._sanitize_filename(base_name)
    roots = [
        out / f"{base_name}_analysis_ready_csv",
        out / f"{safe_base}_analysis_ready_csv",
        out,
    ]
    dirs = []
    seen = set()
    patterns = ["*_for_plotting_analysis/data", "*_for_plotting_analysis\\data"]
    for root in roots:
        if not root.exists() or not root.is_dir():
            continue
        try:
            candidates = []
            # pathlib glob is platform-sensitive; this covers normal paths and any nested folder export.
            candidates.extend([p for p in root.rglob("data") if p.is_dir() and p.parent.name.endswith("_for_plotting_analysis")])
            # Also support older/generated folder names if present.
            candidates.extend([p for p in root.rglob("data_generated_from_HEKA") if p.is_dir()])
            for c in candidates:
                key = str(c.resolve())
                if key not in seen:
                    seen.add(key)
                    dirs.append(c)
        except Exception:
            pass
    # Prefer folders with actual pySECCM data files.
    good = []
    for d in dirs:
        try:
            detected = _v19_detect_pyseccm_files(d)
            if any(detected.get(k) for k in ["cv", "eis", "iv", "corr", "ocp", "avg_ocp", "pos", "drt_dir"]):
                good.append(d)
        except Exception:
            good.append(d)
    return good or dirs


def _v27_pair_by_order_or_first(primary, secondary):
    """Pair lists for IV/OCP defaults: zip when both have many, otherwise reuse the first secondary."""
    primary = list(primary or [])
    secondary = list(secondary or [])
    if not primary or not secondary:
        return []
    if len(primary) == len(secondary):
        return list(zip(primary, secondary))
    return [(p, secondary[0]) for p in primary]


def _v27_build_auto_pyseccm_commands_for_data_dir(data_dir, script_root=None, python_exe=None, include_drt=True):
    """Build default pySECCM/DRT command list for one generated data folder."""
    data_dir = Path(data_dir)
    script_root = Path(script_root or _v19_find_pyseccm_script_root([data_dir, data_dir.parent, Path(__file__).resolve().parent]) or (Path(__file__).resolve().parent / "pyseccm_tools"))
    python_exe = str(python_exe or _v19_sys.executable)
    detected = _v19_detect_pyseccm_files(data_dir)
    commands = []
    notes = []

    def script(name):
        p = script_root / name
        if not p.exists():
            notes.append(f"Missing script: {p}")
            return None
        return p

    pos_files = detected.get("pos", []) or []
    pos = pos_files[0] if pos_files else None

    # CV: run every generated CV file.
    cv_script = script("parse_CV.py")
    if cv_script:
        for cv in detected.get("cv", []) or []:
            cwd = cv.parent
            args = [python_exe, str(cv_script), cv.name, "--plot"]
            commands.append((args, cwd))

    # EIS: run every fullEIS file when a position file is present.
    eis_script = script("parse_EIS.py")
    if eis_script and pos:
        for eis in detected.get("eis", []) or []:
            cwd = pos.parent if pos.parent == eis.parent else data_dir
            args = [python_exe, str(eis_script), pos.name if pos.parent == cwd else str(pos), eis.name if eis.parent == cwd else str(eis), "--plot", "--n_grid", "100"]
            commands.append((args, cwd))
    elif detected.get("eis"):
        notes.append(f"Skipped EIS in {data_dir}: no takedata/position file was found.")

    # IV/Tafel: requires position + corr + IV file.
    iv_script = script("parse_IV.py")
    if iv_script and pos:
        for iv, corr in _v27_pair_by_order_or_first(detected.get("iv", []), detected.get("corr", [])):
            cwd = data_dir if not (pos.parent == corr.parent == iv.parent) else pos.parent
            args = [python_exe, str(iv_script), pos.name if pos.parent == cwd else str(pos), corr.name if corr.parent == cwd else str(corr), iv.name if iv.parent == cwd else str(iv), "--plot", "--n_grid", "100"]
            commands.append((args, cwd))
    elif detected.get("iv") or detected.get("corr"):
        notes.append(f"Skipped IV/Tafel in {data_dir}: requires takedata + corr + IV/Tafel files.")

    # OCP: requires position + average OCP + full OCP.
    ocp_script = script("parse_OCP.py")
    if ocp_script and pos:
        for ocp, avg in _v27_pair_by_order_or_first(detected.get("ocp", []), detected.get("avg_ocp", [])):
            cwd = data_dir if not (pos.parent == avg.parent == ocp.parent) else pos.parent
            args = [python_exe, str(ocp_script), pos.name if pos.parent == cwd else str(pos), avg.name if avg.parent == cwd else str(avg), ocp.name if ocp.parent == cwd else str(ocp), "--plot", "--n_grid", "100"]
            commands.append((args, cwd))
    elif detected.get("ocp") or detected.get("avg_ocp"):
        notes.append(f"Skipped OCP in {data_dir}: requires takedata + averaged OCP + full OCP files.")

    # DRT: run simple DRT when exporter-generated DRT_input_csv exists.  DRT is placed after EIS/plots.
    if include_drt:
        drt_candidates = []
        for d in detected.get("drt_dir", []) or []:
            # Prefer exporter-generated DRT_input_csv; avoid sample Figures/Nyquist duplicates unless no DRT_input_csv exists.
            if d.name.lower() == "drt_input_csv" or "drt_input" in str(d).lower():
                drt_candidates.append(d)
        if not drt_candidates:
            drt_candidates = list(detected.get("drt_dir", []) or [])
        drt_script = None
        for p in [
            script_root / "headless_pyDRTtools" / "pyDRTtools" / "headless_pyDRTtools.py",
            script_root / "pyDRTtools" / "headless_pyDRTtools.py",
            script_root / "headless_pyDRTtools.py",
        ]:
            if p.exists():
                drt_script = p
                break
        if drt_script:
            for drt_dir in drt_candidates:
                args = [python_exe, str(drt_script), str(drt_dir), "--run_types", "simple", "--plot_types", "eis", "drt", "--export_types", "drt"]
                commands.append((args, drt_script.parent))
        elif drt_candidates:
            notes.append(f"Skipped DRT in {data_dir}: headless_pyDRTtools.py was not found under {script_root}.")

    return commands, notes, detected


def _v27_auto_pyseccm_batch_text(commands, notes=None, title="Auto pySECCM/DRT after export"):
    """Command-window batch for the automatic post-export pipeline."""
    header = _v22_command_batch_text(commands, title=title) if commands else "@echo off\nchcp 65001 >nul\n"
    if not notes:
        return header
    # Insert notes near the top after title lines.
    lines = header.splitlines()
    insert_at = min(6, len(lines))
    note_lines = ["echo.", "echo Auto-run notes:"]
    for n in notes:
        safe = str(n).replace("%", "%%")
        note_lines.append(f"echo   {safe}")
    note_lines.append("echo.")
    lines[insert_at:insert_at] = note_lines
    return "\n".join(lines) + "\n"


def _v27_launch_auto_pyseccm_after_export(gui, base_name=None):
    """Launch default parsers for every generated data folder.  Returns a status dict."""
    base_name = base_name or _v27_current_base_name(gui)
    data_dirs = _v27_candidate_plotting_data_dirs(gui, base_name=base_name)
    if not data_dirs:
        raise FileNotFoundError("No generated *_for_plotting_analysis/data folder was found after export.")
    script_root = _v19_default_script_dir_for_gui(gui) or _v19_find_pyseccm_script_root([Path(__file__).resolve().parent])
    if not script_root:
        script_root = str(Path(__file__).resolve().parent / "pyseccm_tools")
    python_exe = _v19_sys.executable

    missing = _v22_missing_modules_for_python(python_exe, kind="all")
    if missing:
        msg = "The auto-run pipeline needs pySECCM/DRT dependencies in the private Python environment.\n\nRepair/install them now?"
        if messagebox.askyesno("Auto-run dependencies", msg, parent=gui):
            _v22_install_dependencies_for_python(python_exe, kind="all", parent=gui)
        raise RuntimeError("Dependencies are missing or being repaired. Run Export again after the dependency window finishes.")

    all_commands = []
    all_notes = []
    folder_reports = []
    for d in data_dirs:
        try:
            cmds, notes, detected = _v27_build_auto_pyseccm_commands_for_data_dir(d, script_root=script_root, python_exe=python_exe, include_drt=True)
            all_commands.extend(cmds)
            all_notes.extend(notes)
            folder_reports.append({
                "data_dir": str(d),
                "n_cv": len(detected.get("cv", [])),
                "n_eis": len(detected.get("eis", [])),
                "n_iv": len(detected.get("iv", [])),
                "n_corr": len(detected.get("corr", [])),
                "n_ocp": len(detected.get("ocp", [])),
                "n_avg_ocp": len(detected.get("avg_ocp", [])),
                "n_drt_dir": len(detected.get("drt_dir", [])),
                "n_commands": len(cmds),
            })
            # Make Matplotlib styles before commands run.
            try:
                _heka_v14_make_minimal_mplstyle(Path(d))
            except Exception:
                pass
        except Exception as exc:
            all_notes.append(f"Failed to prepare {d}: {exc}")
    if not all_commands:
        detail = "\n".join(all_notes) if all_notes else "No CV/EIS/IV/OCP/DRT files were detected."
        raise RuntimeError("No auto-run commands could be built.\n" + detail)
    title = "Auto pySECCM/DRT after ElectroChem export"
    batch = _v27_auto_pyseccm_batch_text(all_commands, notes=all_notes, title=title)
    bat = _v22_write_bat_and_launch(batch, cwd=Path(data_dirs[0]), prefix="auto_pyseccm_after_export")
    return {"batch": str(bat), "n_commands": len(all_commands), "folders": folder_reports, "script_root": str(script_root), "python_exe": str(python_exe)}


