# ---- v29 enhancement: generic EIS-to-DRT export for all parsers + modern UI/icon ----
APP_TITLE = "FaradaIQ Studio v273"


def _v29_safe_label(text, default="EIS"):
    try:
        s = PSSessionParser._sanitize_filename(str(text or default))
    except Exception:
        s = str(text or default)
        s = re.sub(r"[^A-Za-z0-9._-]+", "_", s).strip("_.") or default
    return s[:120] or default


def _v29_triplet_array(freq, zre, zim):
    try:
        f = np.asarray(freq, dtype=float).ravel()
        r = np.asarray(zre, dtype=float).ravel()
        im = np.asarray(zim, dtype=float).ravel()
        n = min(len(f), len(r), len(im))
        if n < 3:
            return None
        arr = np.column_stack([f[:n], r[:n], im[:n]])
        mask = np.all(np.isfinite(arr), axis=1) & (arr[:,0] > 0)
        arr = arr[mask]
        if len(arr) < 3:
            return None
        # DRT tools expect sensible frequency ordering; keep descending if possible.
        try:
            arr = arr[np.argsort(arr[:,0])[::-1]]
        except Exception:
            pass
        return arr
    except Exception:
        return None


def _v29_write_drt_csv(path, arr):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow(["frequency_Hz", "Zreal_ohm", "Zimag_ohm"])
        for row in np.asarray(arr, dtype=float):
            w.writerow([f"{row[0]:.12G}", f"{row[1]:.12G}", f"{row[2]:.12G}"])
    return str(path)


def _v29_data_array_values(obj):
    if isinstance(obj, dict) and "DataValues" in obj:
        vals = []
        for v in obj.get("DataValues", []) or []:
            if isinstance(v, dict) and "V" in v:
                vals.append(v.get("V"))
            else:
                vals.append(v)
        return vals
    return None


def _v29_collect_pssession_arrays(obj, out=None, path=""):
    """Find numeric DataArray-like leaves in PalmSens .pssession JSON."""
    out = [] if out is None else out
    if isinstance(obj, dict):
        vals = _v29_data_array_values(obj)
        if vals is not None:
            name = " ".join(str(x or "") for x in [obj.get("Description"), obj.get("Title"), obj.get("Name"), path]).strip()
            unit = obj.get("Unit")
            try:
                arr = np.asarray([PSSessionParser._to_number_if_possible(v) for v in vals], dtype=float)
                if len(arr) >= 3 and np.isfinite(arr).any():
                    out.append((name, unit, arr))
            except Exception:
                pass
        for k, v in obj.items():
            if k == "DataValues":
                continue
            _v29_collect_pssession_arrays(v, out, f"{path}/{k}" if path else str(k))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            _v29_collect_pssession_arrays(v, out, f"{path}[{i}]")
    return out


def _v29_pick_named_array(arrays, patterns):
    for pat in patterns:
        rx = re.compile(pat, re.I)
        for name, unit, arr in arrays:
            blob = f"{name} {unit}"
            if rx.search(blob):
                return arr, name
    return None, ""


def _v29_extract_pssession_eis(parser):
    records = []
    try:
        measurements = parser.session.get("Measurements", []) if parser.session else []
    except Exception:
        measurements = []
    for mi, m in enumerate(measurements, start=1):
        blocks = []
        if isinstance(m, dict):
            if m.get("EISDataList"):
                blocks.extend(m.get("EISDataList") or [])
            # Some PalmSens versions store impedance as regular curves rather than EISDataList.
            if not blocks:
                method = PSSessionParser._parse_method_text(m.get("Method", ""))
                blob = " ".join(str(x or "") for x in [m.get("Title"), method.get("METHOD_ID"), method.get("TECHNIQUE")])
                if re.search(r"EIS|impedance", blob, re.I):
                    blocks.append(m)
        for bi, b in enumerate(blocks, start=1):
            arrays = _v29_collect_pssession_arrays(b)
            freq, fn = _v29_pick_named_array(arrays, [r"\bfreq(uency)?\b", r"/Hz\b", r"Hz"])
            zre, rn = _v29_pick_named_array(arrays, [r"Re\s*\(?Z\)?", r"Z.?real", r"Real.*Ohm", r"Z'", r"Zprime"])
            zim, iname = _v29_pick_named_array(arrays, [r"-?Im\s*\(?Z\)?", r"Z.?imag", r"Imag.*Ohm", r"Z''", r"Zdouble"])
            arr = _v29_triplet_array(freq, zre, zim) if freq is not None and zre is not None and zim is not None else None
            if arr is not None:
                title = m.get("Title") or f"PalmSens_EIS_{mi}_{bi}"
                records.append({"label": f"{title}_block{bi}", "array": arr, "source": "PalmSens EISDataList/curves"})
    return records


def _v29_extract_generic_eis_records(parser):
    """Return [{'label': str, 'array': Nx3 freq,zreal,zimag, 'source': str}, ...]."""
    records = []
    try:
        if isinstance(parser, HEKAPotmasterParser):
            segments = _heka_v15_eis_segments_by_block(parser)
            entries = _heka_v15_eis_entries(parser)
            for mi, blocks in sorted(segments.items()):
                entry = entries[mi] if mi < len(entries) else (entries[0] if entries else {})
                for bi, groups in sorted(blocks.items()):
                    freqs = _heka_v15_frequency_vector_for_segment(parser, groups, entry=entry)
                    rows = []
                    for g, f in zip(groups, freqs):
                        r = _heka_v15_eis_row_from_group_with_freq(parser, g, f)
                        rows.append([r[1], r[8], r[9]])
                    arr = _v29_triplet_array([r[0] for r in rows], [r[1] for r in rows], [r[2] for r in rows])
                    if arr is not None:
                        label = f"HEKA_method{mi+1}_position{bi+1:03d}"
                        records.append({"label": label, "array": arr, "source": "HEKA DAT/PUL online impedance"})
            return records
    except Exception:
        pass
    try:
        if isinstance(parser, VersaStudioParser):
            for idx, (meta, arr0) in enumerate(parser._paired_eis_sweeps(), start=1):
                if isinstance(arr0, np.ndarray) and arr0.ndim == 2 and arr0.shape[1] >= 3:
                    arr = _v29_triplet_array(arr0[:,0], arr0[:,1], arr0[:,2])
                    if arr is not None:
                        label = meta.get("label") or meta.get("title") or f"VersaStudio_EIS_{idx}"
                        records.append({"label": label, "array": arr, "source": "VersaStudio decoded EIS sweep"})
            return records
    except Exception:
        pass
    try:
        if isinstance(parser, SolartronParser):
            if parser.metadata.get("technique") == "EIS" and parser.data and isinstance(parser.data.get("array"), np.ndarray):
                arr0 = parser.data["array"]
                if arr0.ndim == 2 and arr0.shape[1] >= 3:
                    arr = _v29_triplet_array(arr0[:,0], arr0[:,1], arr0[:,2])
                    if arr is not None:
                        label = parser.metadata.get("stem") or Path(str(parser.source_path)).stem or "Solartron_EIS"
                        records.append({"label": label, "array": arr, "source": "Solartron .z EIS"})
            return records
    except Exception:
        pass
    try:
        if isinstance(parser, BioLogicParser):
            eis = (parser.mpr_numeric or {}).get("eis") if getattr(parser, "mpr_numeric", None) else None
            if eis:
                # Support several possible key casings.
                freq = eis.get("freq_Hz") or eis.get("frequency_Hz") or eis.get("freq/Hz")
                zre = eis.get("Zreal_ohm") or eis.get("Re(Z)/Ohm") or eis.get("ReZ_ohm")
                zim = eis.get("Zimag_ohm") or eis.get("-Im(Z)/Ohm") or eis.get("ImZ_ohm")
                arr = _v29_triplet_array(freq, zre, zim)
                if arr is not None:
                    label = Path(str(parser.source_path or "BioLogic_EIS")).stem
                    records.append({"label": label, "array": arr, "source": "BioLogic MPR EIS"})
            return records
    except Exception:
        pass
    try:
        if isinstance(parser, PSSessionParser):
            return _v29_extract_pssession_eis(parser)
    except Exception:
        pass
    return records


def _v29_export_generic_drt_for_collection(collection, analysis_root: Path, base_name: str):
    """Create DRT_input_csv folders for any EIS spectra decoded from any supported vendor."""
    analysis_root = Path(analysis_root)
    safe_base = _v29_safe_label(base_name, "electrochem_session")
    all_dir = analysis_root / "DRT_input_csv_all"
    all_dir.mkdir(parents=True, exist_ok=True)
    manifest = {
        "created": datetime.now().isoformat(timespec="seconds"),
        "format": "generic-eis-drt-input-v1",
        "note": "DRT-compatible CSV files generated directly from decoded EIS spectra for all supported vendors. Each CSV has frequency_Hz, Zreal_ohm, Zimag_ohm.",
        "analysis_ready_root": str(analysis_root),
        "all_drt_input_dir": str(all_dir),
        "entries": [],
        "n_files": 0,
    }
    files = []
    for entry_idx, entry in enumerate(getattr(collection, "entries", []) or [], start=1):
        parser = entry.get("parser")
        meta = entry.get("path_metadata", {}) or {}
        stem = Path(meta.get("basename", f"entry_{entry_idx}")).stem
        rel_dir = Path(*meta.get("subfolder_names", [])) if meta.get("subfolder_names") else Path()
        target_root = analysis_root / rel_dir / f"{_v29_safe_label(stem)}_for_plotting_analysis"
        data_dir = target_root / "data"
        drt_dir = target_root / "DRT_input_csv"
        for d in (data_dir, drt_dir):
            d.mkdir(parents=True, exist_ok=True)
        records = _v29_extract_generic_eis_records(parser)
        entry_manifest = {
            "entry_id": f"e{entry_idx:04d}",
            "source_file": meta.get("relative_path") or getattr(parser, "source_path", ""),
            "stem": stem,
            "vendor_parser": parser.__class__.__name__ if parser else "unknown",
            "plotting_root": str(target_root),
            "data_folder": str(data_dir),
            "drt_input_csv_dir": str(drt_dir),
            "n_eis_spectra": len(records),
            "files": [],
        }
        # Add a lightweight README into data so the DRT folder is discoverable from the data folder.
        try:
            (data_dir / "README_DRT_input_csv.txt").write_text(
                "DRT-compatible EIS CSV files are in ../DRT_input_csv.\n"
                "Each CSV has columns: frequency_Hz, Zreal_ohm, Zimag_ohm.\n"
                "These files can be used with headless_pyDRTtools.py.\n",
                encoding="utf-8",
            )
        except Exception:
            pass
        for ri, rec in enumerate(records, start=1):
            label = _v29_safe_label(rec.get("label"), f"EIS_{ri:03d}")
            fname = f"{_v29_safe_label(stem)}__{label}__freq_zreal_zimag.csv"
            arr = np.asarray(rec.get("array"), dtype=float)
            p1 = drt_dir / fname
            p2 = all_dir / f"e{entry_idx:04d}__{fname}"
            _v29_write_drt_csv(p1, arr)
            _v29_write_drt_csv(p2, arr)
            row = {
                "label": rec.get("label"),
                "source": rec.get("source"),
                "n_rows": int(len(arr)),
                "freq_min_Hz": float(np.nanmin(arr[:,0])) if len(arr) else None,
                "freq_max_Hz": float(np.nanmax(arr[:,0])) if len(arr) else None,
                "relative_drt_path": str(p1.relative_to(analysis_root)).replace("\\", "/"),
                "relative_all_drt_path": str(p2.relative_to(analysis_root)).replace("\\", "/"),
            }
            entry_manifest["files"].append(row)
            files.append(str(p1))
        if records:
            # Put a manifest beside the per-entry DRT folder for direct use.
            try:
                with open(target_root / "generic_DRT_input_manifest.json", "w", encoding="utf-8") as f:
                    json.dump(entry_manifest, f, indent=2, ensure_ascii=False)
            except Exception:
                pass
        manifest["entries"].append(entry_manifest)
    manifest["n_files"] = len(files)
    manifest_path = analysis_root / "generic_DRT_input_manifest.json"
    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2, ensure_ascii=False)
    return {"manifest_path": str(manifest_path), "all_drt_input_dir": str(all_dir), "n_files": len(files), "files": files}


# Patch collection export so every vendor gets DRT-compatible EIS CSVs when EIS data exists.
_PSS_COLLECTION_V29_PREV_EXPORT_ANALYSIS_READY_CSV = PSSessionCollection.export_analysis_ready_csv

def _pss_collection_v29_export_analysis_ready_csv(self, output_dir: Path, base_name: str) -> dict:
    info = _PSS_COLLECTION_V29_PREV_EXPORT_ANALYSIS_READY_CSV(self, output_dir, base_name)
    try:
        drt_info = _v29_export_generic_drt_for_collection(self, Path(info["analysis_ready_root"]), base_name)
        info["generic_drt_input"] = drt_info
        # Update the main manifest created by the previous exporter.
        try:
            mp = Path(info.get("manifest_path", ""))
            if mp.exists():
                data = json.loads(mp.read_text(encoding="utf-8"))
                data["generic_drt_input"] = drt_info
                mp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass
    except Exception as exc:
        info["generic_drt_input_error"] = str(exc)
    return info

PSSessionCollection.export_analysis_ready_csv = _pss_collection_v29_export_analysis_ready_csv


# Make DRT folder discovery include generic DRT_input_csv folders from any vendor export.
_V29_PREV_FIND_DRT_INPUT_DIRS = _v22_find_drt_input_dirs

def _v22_find_drt_input_dirs(data_dir: Path):
    d = Path(data_dir)
    out = list(_V29_PREV_FIND_DRT_INPUT_DIRS(d))
    extra = [
        d / "DRT_input_csv",
        d.parent / "DRT_input_csv",
        d.parent / "DRT_input_csv_all",
        d.parent.parent / "DRT_input_csv_all",
    ]
    try:
        for p in d.parents:
            # Limit search depth to keep the GUI responsive.
            if p == p.parent:
                break
            if len(str(p)) < 3:
                break
            c = p / "DRT_input_csv_all"
            if c.exists():
                extra.append(c)
            # Stop once we reach the analysis_ready_csv root.
            if p.name.endswith("_analysis_ready_csv"):
                break
    except Exception:
        pass
    seen = {str(Path(x).resolve()) for x in out if Path(x).exists()}
    for c in extra:
        try:
            key = str(c.resolve())
        except Exception:
            key = str(c)
        if c.exists() and c.is_dir() and key not in seen:
            out.append(c)
            seen.add(key)
    return out


# Modern, calmer GUI styling and application icon.
def _v29_icon_paths():
    root = Path(__file__).resolve().parent
    return root / "electrochem_bridge_icon.ico", root / "electrochem_bridge_icon.png"


def _v29_set_icon(win):
    ico, png = _v29_icon_paths()
    try:
        if ico.exists():
            win.iconbitmap(str(ico))
            return
    except Exception:
        pass
    try:
        if png.exists():
            img = tk.PhotoImage(file=str(png))
            win._v29_icon_img = img
            win.iconphoto(True, img)
    except Exception:
        pass


def _v29_apply_modern_style(root):
    try:
        style = ttk.Style(root)
        # Use a native theme when available, then layer calm colors/padding over it.
        available = set(style.theme_names())
        for theme in ("vista", "xpnative", "clam", "alt"):
            if theme in available:
                style.theme_use(theme)
                break
        bg = "#f5f7fb"
        panel = "#ffffff"
        ink = "#172033"
        muted = "#475569"
        accent = "#0f766e"
        accent2 = "#155e75"
        try:
            root.configure(bg=bg)
        except Exception:
            pass
        style.configure("TFrame", background=bg)
        style.configure("TLabelframe", background=bg, borderwidth=1, relief="solid")
        style.configure("TLabelframe.Label", background=bg, foreground=accent2, font=("Segoe UI", 10, "bold"))
        style.configure("TLabel", background=bg, foreground=ink, font=("Segoe UI", 9))
        style.configure("TButton", font=("Segoe UI", 9), padding=(10, 5))
        style.configure("Accent.TButton", font=("Segoe UI", 9, "bold"), padding=(12, 6), foreground="#ffffff", background=accent)
        style.map("Accent.TButton", background=[("active", "#0d9488"), ("pressed", "#115e59")])
        style.configure("TEntry", padding=(4, 3))
        style.configure("TCheckbutton", background=bg, foreground=ink, font=("Segoe UI", 9))
        style.configure("Hero.TFrame", background="#0f172a")
        style.configure("HeroTitle.TLabel", background="#0f172a", foreground="#e0f2fe", font=("Segoe UI Semibold", 16))
        style.configure("HeroSub.TLabel", background="#0f172a", foreground="#bae6fd", font=("Segoe UI", 9))
        style.configure("Status.TLabel", background=bg, foreground=muted, font=("Segoe UI", 9))
    except Exception:
        pass



