def _v31_apply_dark_responsive_style(root):
    try:
        style = ttk.Style(root)
        available = set(style.theme_names())
        if "clam" in available:
            style.theme_use("clam")
        elif "vista" in available:
            style.theme_use("vista")

        bg = "#07111f"
        surface = "#0f1b2d"
        surface2 = "#12243a"
        field = "#f8fafc"
        ink = "#e5eefb"
        muted = "#a8bed6"
        accent = "#14b8a6"
        accent_hover = "#2dd4bf"
        amber = "#facc15"
        blue = "#38bdf8"

        try:
            root.configure(bg=bg)
        except Exception:
            pass

        style.configure(".", font=("Segoe UI", 9))
        style.configure("TFrame", background=bg)
        style.configure("App.TFrame", background=bg)
        style.configure("Card.TFrame", background=surface, relief="flat")
        style.configure("Toolbar.TFrame", background=surface)
        style.configure("Hero.TFrame", background="#081827")
        style.configure("TLabel", background=bg, foreground=ink, font=("Segoe UI", 9))
        style.configure("Card.TLabel", background=surface, foreground=ink, font=("Segoe UI", 9))
        style.configure("Muted.TLabel", background=surface, foreground=muted, font=("Segoe UI", 8))
        style.configure("HeroTitle.TLabel", background="#081827", foreground="#e0f2fe", font=("Segoe UI Semibold", 20))
        style.configure("HeroSub.TLabel", background="#081827", foreground="#bae6fd", font=("Segoe UI", 9))
        style.configure("HeroCredit.TLabel", background="#081827", foreground="#7dd3fc", font=("Segoe UI", 8))
        style.configure("Section.TLabel", background=bg, foreground="#dbeafe", font=("Segoe UI Semibold", 11))
        style.configure("TLabelframe", background=surface, foreground=ink, borderwidth=1, relief="solid")
        style.configure("TLabelframe.Label", background=surface, foreground="#7dd3fc", font=("Segoe UI Semibold", 10))
        style.configure("TEntry", padding=(5, 5), fieldbackground=field, foreground="#0f172a", insertcolor="#0f172a")
        style.configure("TButton", font=("Segoe UI", 9), padding=(10, 6), background="#e5e7eb", foreground="#0f172a")
        style.map("TButton",
                  background=[("active", "#ffffff"), ("pressed", "#cbd5e1")],
                  foreground=[("active", "#0f172a")])
        style.configure("Accent.TButton", font=("Segoe UI Semibold", 9), padding=(12, 7), background=accent, foreground="#062a2a")
        style.map("Accent.TButton",
                  background=[("active", accent_hover), ("pressed", "#0f766e")],
                  foreground=[("active", "#042f2e"), ("pressed", "#ffffff")])
        style.configure("Danger.TButton", font=("Segoe UI", 9), padding=(10, 6), background="#334155", foreground="#e2e8f0")
        style.configure("TCheckbutton", background=surface, foreground=ink, font=("Segoe UI", 9))
        style.map("TCheckbutton",
                  background=[("active", surface2)],
                  foreground=[("active", "#ffffff")])
        style.configure("Status.TLabel", background=bg, foreground=muted, font=("Segoe UI", 9))
        style.configure("Horizontal.TPanedwindow", background=bg)
        style.configure("Vertical.TPanedwindow", background=bg)
        return {"bg": bg, "surface": surface, "surface2": surface2, "ink": ink, "muted": muted}
    except Exception:
        return {"bg": "#07111f", "surface": "#0f1b2d", "surface2": "#12243a", "ink": "#e5eefb", "muted": "#a8bed6"}


def _v31_config_text_widget(widget, *, small=False):
    try:
        widget.configure(
            background="#020617",
            foreground="#e5eefb",
            insertbackground="#f8fafc",
            selectbackground="#0f766e",
            selectforeground="#ffffff",
            relief="flat",
            borderwidth=0,
            highlightthickness=1,
            highlightbackground="#1e3a5f",
            highlightcolor="#14b8a6",
            font=("Consolas", 8 if small else 9),
        )
    except Exception:
        pass


def _v31_pack_button_grid(parent, specs, columns=5):
    """Compact button grid that wraps on small screens instead of overflowing off-screen."""
    for i, (label, command, style_name) in enumerate(specs):
        kwargs = {"text": label, "command": command}
        if style_name:
            kwargs["style"] = style_name
        btn = ttk.Button(parent, **kwargs)
        btn.grid(row=i // columns, column=i % columns, sticky="ew", padx=3, pady=3)
    for col in range(columns):
        parent.columnconfigure(col, weight=1)


