def _session_reader_gui_v31_build_ui(self):
    colors = _v31_apply_dark_responsive_style(self)
    try:
        _v29_set_icon(self)
    except Exception:
        pass
    try:
        self.title(APP_TITLE)
    except Exception:
        pass

    # Responsive default geometry. Keeps large screens spacious but prevents tiny laptop clipping.
    try:
        sw = int(self.winfo_screenwidth())
        sh = int(self.winfo_screenheight())
        if sw <= 1366:
            w = min(sw - 40, 1280)
            h = min(sh - 80, 760)
            self.geometry(f"{w}x{h}+10+10")
            self.minsize(980, 660)
            compact = True
        elif sw <= 1600:
            w = min(sw - 60, 1420)
            h = min(sh - 90, 850)
            self.geometry(f"{w}x{h}+20+20")
            self.minsize(1080, 700)
            compact = False
        else:
            self.geometry("1550x940")
            self.minsize(1120, 740)
            compact = False
    except Exception:
        compact = False

    root = ttk.Frame(self, style="App.TFrame", padding=(10 if compact else 14, 8 if compact else 12))
    root.pack(fill="both", expand=True)

    # Header
    hero = ttk.Frame(root, style="Hero.TFrame", padding=(12 if compact else 16, 9 if compact else 12))
    hero.pack(fill="x", pady=(0, 8))
    hero.columnconfigure(1, weight=1)

    try:
        icon_path = Path(__file__).with_name("electrochem_bridge_icon.png")
        if icon_path.exists():
            self._v31_icon_img = tk.PhotoImage(file=str(icon_path))
            ttk.Label(hero, image=self._v31_icon_img, style="HeroSub.TLabel").grid(row=0, column=0, rowspan=3, sticky="nw", padx=(0, 12))
    except Exception:
        pass

    header_text = ttk.Frame(hero, style="Hero.TFrame")
    header_text.grid(row=0, column=1, sticky="ew")
    ttk.Label(header_text, text="FaradaIQ Studio", style="HeroTitle.TLabel").pack(anchor="w")
    ttk.Label(header_text, text="Designed by Venky Prabhakaran and powered by LLM • 2026", style="HeroSub.TLabel").pack(anchor="w", pady=(1, 0))
    ttk.Label(
        header_text,
        text="Supported: HEKA/POTMASTER/PATCHMASTER DAT2 (.dat/.pul/.pgf/.amp/.mrk/.mth/.onl) • PalmSens (.pssession) • VersaStudio (.par/.psbd) • Solartron (.cor/.z) • BioLogic (.mpr/.mps/.mgr) • ZIP/folders",
        style="HeroSub.TLabel",
        wraplength=max(720, min(1280, int(self.winfo_screenwidth()) - 260)),
    ).pack(anchor="w", pady=(2, 0))
    ttk.Label(
        header_text,
        text="Includes electrochemical data parsing, pySECCM plotting, DRT automation, and AI-analysis handoff. pyDRTtools module credit: Ciucci Lab, https://github.com/ciuccislab/pyDRTtools",
        style="HeroCredit.TLabel",
        wraplength=max(720, min(1280, int(self.winfo_screenwidth()) - 260)),
    ).pack(anchor="w", pady=(2, 0))

    ttk.Button(hero, text="About / credits", command=self.show_about_credits).grid(row=0, column=2, sticky="ne", padx=(10, 0))

    # Controls card
    controls = ttk.Frame(root, style="Card.TFrame", padding=(10, 8))
    controls.pack(fill="x", pady=(0, 8))
    for c in range(4):
        controls.columnconfigure(c, weight=1 if c == 1 else 0)

    ttk.Label(controls, text="Input", style="Card.TLabel").grid(row=0, column=0, sticky="w", padx=(0, 8), pady=(0, 4))
    ttk.Entry(controls, textvariable=self.file_var).grid(row=0, column=1, columnspan=3, sticky="ew", pady=(0, 4))

    file_buttons = ttk.Frame(controls, style="Card.TFrame")
    file_buttons.grid(row=1, column=1, columnspan=3, sticky="ew", pady=(0, 5))
    _v31_pack_button_grid(file_buttons, [
        ("Browse file", self.browse_file, None),
        ("Browse folder", self.browse_input_folder, None),
        ("Load and inspect", self.load_and_inspect, "Accent.TButton"),
    ], columns=3)

    ttk.Label(controls, text="Output", style="Card.TLabel").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=(4, 4))
    ttk.Entry(controls, textvariable=self.output_dir_var).grid(row=2, column=1, columnspan=3, sticky="ew", pady=(4, 4))

    output_buttons = ttk.Frame(controls, style="Card.TFrame")
    output_buttons.grid(row=3, column=1, columnspan=3, sticky="ew", pady=(0, 2))
    _v31_pack_button_grid(output_buttons, [
        ("Choose folder", self.browse_output_dir, None),
        ("Export archive + CSV", self.export_outputs, "Accent.TButton"),
        ("Split HEKA <2GB", self.split_heka_bundle_outputs, None),
        ("Open Help Guide", self.open_help_guide, None),
    ], columns=4)

    # pySECCM / DRT panel with the auto-run checkbox in its own visible row.
    tools = ttk.LabelFrame(root, text="pySECCM / DRT runners", padding=(10, 8))
    tools.pack(fill="x", pady=(0, 8))
    tool_buttons = ttk.Frame(tools, style="Card.TFrame")
    tool_buttons.pack(fill="x", anchor="w")
    _v31_pack_button_grid(tool_buttons, [
        ("CV", lambda: self.open_pyseccm_tool("cv"), None),
        ("EIS", lambda: self.open_pyseccm_tool("eis"), None),
        ("IV / Tafel", lambda: self.open_pyseccm_tool("iv"), None),
        ("OCP", lambda: self.open_pyseccm_tool("ocp"), None),
        ("pyDRT", lambda: self.open_pyseccm_tool("drt"), None),
        ("Launcher window", self.open_pyseccm_launcher, None),
        ("Check/install deps", self.check_install_pyseccm_dependencies, None),
    ], columns=7 if not compact else 4)

    if not hasattr(self, "auto_run_pyseccm_after_export_var"):
        self.auto_run_pyseccm_after_export_var = tk.BooleanVar(value=False)
    auto_row = ttk.Frame(tools, style="Card.TFrame")
    auto_row.pack(fill="x", pady=(6, 0))
    ttk.Checkbutton(
        auto_row,
        text="After export: auto-run available CV/EIS/IV/OCP + DRT using default options",
        variable=self.auto_run_pyseccm_after_export_var,
    ).pack(side="left", padx=(0, 12))
    ttk.Label(
        auto_row,
        text="Runs open in separate command windows after files are generated.",
        style="Muted.TLabel",
    ).pack(side="left", fill="x", expand=True)

    raw_row = ttk.Frame(root, style="App.TFrame")
    raw_row.pack(fill="x", pady=(0, 8))
    ttk.Checkbutton(raw_row, text="Also save full raw JSON copy (can be very large)", variable=self.include_raw_json_var).pack(anchor="w")

    # Body panes. Use vertical stacking on small screens; horizontal on larger screens.
    orient = "vertical" if compact else "horizontal"
    body = ttk.Panedwindow(root, orient=orient)
    body.pack(fill="both", expand=True)

    left_frame = ttk.Frame(body, style="App.TFrame", padding=(0, 0, 6 if not compact else 0, 0))
    right_frame = ttk.Frame(body, style="App.TFrame", padding=(6 if not compact else 0, 0, 0, 0))
    body.add(left_frame, weight=1)
    body.add(right_frame, weight=2)

    # Left side uses a paned window so description/summary resize naturally.
    left_pane = ttk.Panedwindow(left_frame, orient="vertical")
    left_pane.pack(fill="both", expand=True)

    desc_card = ttk.Frame(left_pane, style="Card.TFrame", padding=(8, 8))
    summary_card = ttk.Frame(left_pane, style="Card.TFrame", padding=(8, 8))
    left_pane.add(desc_card, weight=1)
    left_pane.add(summary_card, weight=2)

    ttk.Label(desc_card, text="Experimental description", style="Card.TLabel", font=("Segoe UI Semibold", 10)).pack(anchor="w")
    self.desc_text = ScrolledText(desc_card, wrap="word", height=6 if compact else 8)
    self.desc_text.pack(fill="both", expand=True, pady=(4, 6))
    _v31_config_text_widget(self.desc_text, small=compact)

    prompt_frame = ttk.Frame(desc_card, style="Card.TFrame")
    prompt_frame.pack(fill="x")
    ttk.Button(prompt_frame, text="Append AI Analysis Prompt", command=self.append_ai_prompt).pack(side="left")
    ttk.Label(prompt_frame, text="Adds an electrochemical analysis prompt.", style="Muted.TLabel").pack(side="left", padx=(8, 0))

    ttk.Label(summary_card, text="Session summary", style="Card.TLabel", font=("Segoe UI Semibold", 10)).pack(anchor="w")
    self.summary_text = ScrolledText(summary_card, wrap="word", height=12 if compact else 18)
    self.summary_text.pack(fill="both", expand=True, pady=(4, 0))
    _v31_config_text_widget(self.summary_text, small=compact)

    preview_card = ttk.Frame(right_frame, style="Card.TFrame", padding=(8, 8))
    preview_card.pack(fill="both", expand=True)
    ttk.Label(preview_card, text="Data structure preview", style="Card.TLabel", font=("Segoe UI Semibold", 10)).pack(anchor="w")
    self.structure_text = ScrolledText(preview_card, wrap="none", height=18 if compact else 24)
    self.structure_text.pack(fill="both", expand=True, pady=(4, 0))
    _v31_config_text_widget(self.structure_text, small=compact)

    status_frame = ttk.Frame(root, style="App.TFrame", padding=(0, 8, 0, 0))
    status_frame.pack(fill="x")
    self.status_var = tk.StringVar(value="Ready")
    ttk.Label(status_frame, textvariable=self.status_var, style="Status.TLabel").pack(anchor="w")


