# ---- v32 enhancement: neutral environment naming and single DRT input file set ----
APP_TITLE = "FaradaIQ Studio v273"

# Keep one DRT-compatible file set per DRT_input_csv folder. Older versions wrote both
# short legacy position_### files and generic per-method files; this cleanup removes
# duplicates so DRT folders stay unambiguous for reruns and GitHub release packages.
def _v32_cleanup_duplicate_drt_inputs(analysis_root: Path):
    removed = []
    try:
        root = Path(analysis_root)
        for drt_dir in root.rglob("DRT_input_csv"):
            if not drt_dir.is_dir():
                continue
            # A generic/method-aware file has the sample/method in the filename.
            method_files = list(drt_dir.glob("*__*freq_zreal_zimag.csv")) + list(drt_dir.glob("*method*_position*freq_zreal_zimag.csv"))
            if method_files:
                for p in list(drt_dir.glob("position_[0-9][0-9][0-9]_freq_zreal_zimag.csv")) + list(drt_dir.glob("*HEKA_method*freq_zreal_zimag.csv")):
                    try:
                        if p.exists():
                            p.unlink()
                            removed.append(str(p))
                    except Exception:
                        pass
        # Also clean old branded method names from the all-vendor aggregate folder if user reuses an output folder.
        for all_dir in root.rglob("DRT_input_csv_all"):
            if not all_dir.is_dir():
                continue
            for p in all_dir.glob("*HEKA_method*freq_zreal_zimag.csv"):
                try:
                    p.unlink()
                    removed.append(str(p))
                except Exception:
                    pass
    except Exception:
        pass
    return removed

try:
    _V32_PREV_GENERIC_EIS_EXTRACTOR = _v29_extract_generic_eis_records
except Exception:
    _V32_PREV_GENERIC_EIS_EXTRACTOR = None

def _v29_extract_generic_eis_records(parser):
    """v32 override: same generic DRT extraction, but no vendor/product name in DRT filenames."""
    records = []
    try:
        if isinstance(parser, HEKAPotmasterParser):
            segments = _heka_v15_eis_segments_by_block(parser)
            entries = _heka_v15_eis_entries(parser)
            for mi, blocks in sorted(segments.items()):
                entry = entries[mi] if mi < len(entries) else (entries[0] if entries else {})
                for bi, groups in sorted(blocks.items()):
                    freqs = _heka_v15_frequency_vector_for_segment(parser, groups, entry=entry)
                    rows = []
                    for g, f in zip(groups, freqs):
                        r = _heka_v15_eis_row_from_group_with_freq(parser, g, f)
                        rows.append([r[1], r[8], r[9]])
                    arr = _v29_triplet_array([r[0] for r in rows], [r[1] for r in rows], [r[2] for r in rows])
                    if arr is not None:
                        label = f"method{mi+1:02d}_position{bi+1:03d}"
                        records.append({"label": label, "array": arr, "source": "DAT/PUL online impedance"})
            return records
    except Exception:
        pass
    if _V32_PREV_GENERIC_EIS_EXTRACTOR is not None:
        return _V32_PREV_GENERIC_EIS_EXTRACTOR(parser)
    return records

try:
    _PSS_COLLECTION_V32_PREV_EXPORT_ANALYSIS_READY_CSV = PSSessionCollection.export_analysis_ready_csv
    def _pss_collection_v32_export_analysis_ready_csv(self, output_dir: Path, base_name: str) -> dict:
        info = _PSS_COLLECTION_V32_PREV_EXPORT_ANALYSIS_READY_CSV(self, output_dir, base_name)
        try:
            removed = _v32_cleanup_duplicate_drt_inputs(Path(info.get("analysis_ready_root", output_dir)))
            if removed:
                info["drt_duplicate_cleanup"] = {"removed_files": removed, "n_removed": len(removed)}
        except Exception:
            pass
        return info
    PSSessionCollection.export_analysis_ready_csv = _pss_collection_v32_export_analysis_ready_csv
except Exception:
    pass

