# ---- v35 enhancement: AI-analysis bundle with parsed/analyzed outputs ----
APP_TITLE = "FaradaIQ Studio v273"

def _v35_safe_name(text, default="analysis"):
    try:
        return PSSessionParser._sanitize_filename(str(text or default)) or default
    except Exception:
        return re.sub(r"[^A-Za-z0-9._-]+", "_", str(text or default)).strip("_.") or default


def _v35_count_lines(path, max_bytes_for_full_count=100_000_000):
    try:
        path = Path(path)
        if path.stat().st_size > max_bytes_for_full_count:
            return None
        n = 0
        with open(path, "rb") as f:
            for _ in f:
                n += 1
        return n
    except Exception:
        return None


def _v35_text_preview(path, max_chars=20000):
    try:
        data = Path(path).read_bytes()
        truncated = len(data) > max_chars * 4
        sample = data[:max_chars * 4]
        for enc in ("utf-8-sig", "utf-8", "latin-1"):
            try:
                text = sample.decode(enc, errors="replace")
                break
            except Exception:
                text = ""
        if len(text) > max_chars:
            text = text[:max_chars]
            truncated = True
        return {"preview": text, "preview_truncated": bool(truncated)}
    except Exception as exc:
        return {"preview": "", "preview_error": str(exc), "preview_truncated": True}


def _v35_detect_table_metadata(path):
    """Lightweight table metadata for AI handoff without forcing large files into memory."""
    path = Path(path)
    info = {"line_count": _v35_count_lines(path)}
    try:
        prev = _v35_text_preview(path, max_chars=5000).get("preview", "")
        lines = [ln for ln in prev.splitlines() if ln.strip()]
        if not lines:
            return info
        # Find likely header row.
        header = lines[0]
        for ln in lines[:8]:
            if ("," in ln or "\t" in ln or ";" in ln) and any(ch.isalpha() for ch in ln):
                header = ln
                break
        delim = "," if header.count(",") >= max(header.count("\t"), header.count(";")) else ("\t" if header.count("\t") >= header.count(";") else ";")
        if delim in header:
            cols = [c.strip().strip('"') for c in header.split(delim)]
        else:
            cols = re.split(r"\s+", header.strip())
        cols = [c for c in cols if c]
        info["detected_columns"] = cols[:80]
        info["n_detected_columns"] = len(cols)
    except Exception as exc:
        info["table_metadata_error"] = str(exc)
    return info


def _v35_collect_analysis_files(analysis_root):
    analysis_root = Path(analysis_root).resolve()
    include_exts = {
        ".csv", ".txt", ".asc", ".json", ".npy", ".npz",
        ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".svg", ".pdf", ".html",
        ".h5", ".hdf5", ".xlsx"
    }
    skip_dir_names = {
        "__pycache__", ".git", ".faradaiq_venv", ".deareis_venv", ".echem_bridge_venv",
        ".bridge_heka_venv", "AI_analysis_with_parsed_outputs", "with_analysis"
    }
    files = []
    if not analysis_root.exists():
        return files
    for p in analysis_root.rglob("*"):
        try:
            if not p.is_file():
                continue
            if any(part in skip_dir_names or part.endswith("_with_analysis") for part in p.relative_to(analysis_root).parts):
                continue
            if p.suffix.lower() not in include_exts:
                continue
            files.append(p)
        except Exception:
            continue
    return sorted(files, key=lambda x: str(x.relative_to(analysis_root)).lower())


def make_ai_analysis_bundle(analysis_root, base_name=None, label="with_analysis", copy_files=True):
    import shutil
    """Create a separate AI-ready npy/json bundle containing parsed + analyzed output files.

    This is intentionally generic: it works after raw export, and it can be run again after
    pySECCM/DRT parsers produce Figures/ and DRT/ output folders.
    """
    analysis_root = Path(analysis_root).resolve()
    if base_name is None:
        name = analysis_root.name
        base_name = name[:-len("_analysis_ready_csv")] if name.endswith("_analysis_ready_csv") else name
    safe = _v35_safe_name(base_name)
    bundle_dir = analysis_root / f"{safe}_AI_analysis_with_parsed_outputs"
    snapshot_dir = bundle_dir / "files_snapshot"
    bundle_dir.mkdir(parents=True, exist_ok=True)
    if copy_files:
        snapshot_dir.mkdir(parents=True, exist_ok=True)

    files = _v35_collect_analysis_files(analysis_root)
    manifest_files = []
    text_previews = []
    table_summaries = []
    copied_count = 0
    skipped_copy_count = 0
    max_copy_bytes = 250_000_000

    for p in files:
        try:
            rel = p.relative_to(analysis_root).as_posix()
        except Exception:
            rel = p.name
        try:
            st = p.stat()
            size = int(st.st_size)
            item = {
                "relative_path": rel,
                "name": p.name,
                "suffix": p.suffix.lower(),
                "size_bytes": size,
                "modified_time": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
            }
            if p.suffix.lower() in {".csv", ".txt", ".asc", ".json"}:
                preview = _v35_text_preview(p)
                item.update({"preview_truncated": preview.get("preview_truncated", True)})
                text_previews.append({
                    "relative_path": rel,
                    "preview": preview.get("preview", ""),
                    "preview_truncated": preview.get("preview_truncated", True),
                })
                if p.suffix.lower() in {".csv", ".txt", ".asc"}:
                    meta = _v35_detect_table_metadata(p)
                    item.update(meta)
                    table_summaries.append({"relative_path": rel, **meta})
            if copy_files:
                if size <= max_copy_bytes:
                    dest = snapshot_dir / rel
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    try:
                        shutil.copy2(p, dest)
                        item["snapshot_relative_path"] = str(Path("files_snapshot") / rel).replace("\\", "/")
                        copied_count += 1
                    except Exception as exc:
                        item["copy_error"] = str(exc)
                        skipped_copy_count += 1
                else:
                    item["copy_skipped"] = f"file larger than {max_copy_bytes} bytes"
                    skipped_copy_count += 1
            manifest_files.append(item)
        except Exception as exc:
            manifest_files.append({"relative_path": str(p), "error": str(exc)})

    # Helpful SECCM-focused categorization.
    categories = {
        "takedata_or_position": [],
        "cv": [],
        "eis_drt_input": [],
        "drt_outputs": [],
        "figures": [],
        "json_metadata": [],
        "npy_payloads": [],
        "other": [],
    }
    for item in manifest_files:
        rel = item.get("relative_path", "")
        low = rel.lower()
        if "drt_input_csv" in low or "freq_zreal_zimag" in low or "fulleis" in low or "eis" in low:
            categories["eis_drt_input"].append(rel)
        elif "/drt/" in low or "\\drt\\" in low or "drt_" in low:
            categories["drt_outputs"].append(rel)
        elif "takedata" in low or ("position" in low and "freq_zreal_zimag" not in low):
            categories["takedata_or_position"].append(rel)
        elif "cv" in low or low.endswith(".asc"):
            categories["cv"].append(rel)
        elif item.get("suffix") in {".png", ".jpg", ".jpeg", ".svg", ".pdf"} or "figures" in low:
            categories["figures"].append(rel)
        elif item.get("suffix") == ".json":
            categories["json_metadata"].append(rel)
        elif item.get("suffix") in {".npy", ".npz"}:
            categories["npy_payloads"].append(rel)
        else:
            categories["other"].append(rel)

    summary = {
        "schema": "faradaiq-ai-analysis-bundle-v1",
        "app": "FaradaIQ Studio",
        "version": "v273",
        "created": datetime.now().isoformat(timespec="seconds"),
        "base_name": base_name,
        "label": label,
        "analysis_root": str(analysis_root),
        "bundle_dir": str(bundle_dir),
        "snapshot_dir": str(snapshot_dir) if copy_files else None,
        "n_files_indexed": len(manifest_files),
        "n_files_copied": copied_count,
        "n_files_copy_skipped": skipped_copy_count,
        "categories": {k: {"count": len(v), "files": v[:500]} for k, v in categories.items()},
        "notes": [
            "This folder is intended for AI analysis handoff.",
            "It indexes and snapshots parsed/exported data, SECCM-compatible files, DRT inputs, parser outputs, figures, and metadata when present.",
            "JSON contains metadata and previews; NPY contains the same manifest plus text previews/table summaries as a Python object bundle.",
        ],
    }
    manifest = {
        "schema": "faradaiq-ai-analysis-manifest-v1",
        "summary": summary,
        "files": manifest_files,
    }
    payload = {
        "schema": "faradaiq-ai-analysis-payload-v1",
        "summary": summary,
        "manifest_files": manifest_files,
        "text_previews": text_previews,
        "table_summaries": table_summaries,
    }

    manifest_path = bundle_dir / f"{safe}_AI_analysis_manifest.json"
    summary_path = bundle_dir / f"{safe}_AI_analysis_summary.json"
    npy_path = bundle_dir / f"{safe}_AI_analysis_payload.npy"
    readme_path = bundle_dir / "README_AI_ANALYSIS.txt"

    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    with open(summary_path, "w", encoding="utf-8") as f:
        json.dump(summary, f, ensure_ascii=False, indent=2)
    np.save(npy_path, np.array(payload, dtype=object), allow_pickle=True)
    readme_path.write_text(
        "FaradaIQ Studio AI analysis bundle\n"
        "============================\n\n"
        f"Created: {summary['created']}\n"
        f"Base name: {base_name}\n"
        f"Analysis root: {analysis_root}\n\n"
        "Use these files for AI handoff:\n"
        f"- {npy_path.name}\n"
        f"- {summary_path.name}\n"
        f"- {manifest_path.name}\n\n"
        "The files_snapshot folder contains copies of parsed/analyzed output files when they are not too large.\n",
        encoding="utf-8",
    )
    return {
        "bundle_dir": str(bundle_dir),
        "manifest_path": str(manifest_path),
        "summary_path": str(summary_path),
        "npy_path": str(npy_path),
        "n_files_indexed": len(manifest_files),
        "n_files_copied": copied_count,
    }


def _v35_analysis_root_for_export(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    out = Path(gui.output_dir_var.get().strip() or ".").resolve()
    safe_base = _v35_safe_name(base_name)
    for p in [out / f"{base_name}_analysis_ready_csv", out / f"{safe_base}_analysis_ready_csv"]:
        if p.exists() and p.is_dir():
            return p
    return out


def _v35_analysis_root_from_data_dir(data_dir):
    p = Path(data_dir).resolve()
    try:
        if p.name.lower() in {"data", "data_generated_from_heka"} and p.parent.name.endswith("_for_plotting_analysis"):
            return p.parent.parent
        if p.name.lower() == "drt_input_csv":
            return p.parent.parent if p.parent.name.endswith("_for_plotting_analysis") else p.parent
    except Exception:
        pass
    return p.parent


# Create/update the AI analysis bundle after every normal export.
_SESSION_READER_GUI_V35_PREV_EXPORT_OUTPUTS = SessionReaderGUI.export_outputs

def _session_reader_gui_v35_export_outputs(self):
    base_name = _v27_current_base_name(self)
    _SESSION_READER_GUI_V35_PREV_EXPORT_OUTPUTS(self)
    try:
        analysis_root = _v35_analysis_root_for_export(self, base_name=base_name)
        if analysis_root.exists():
            self.set_status("Creating AI analysis bundle...")
            info = make_ai_analysis_bundle(analysis_root, base_name=base_name, label="after_export", copy_files=True)
            self.set_status("Export complete. AI analysis bundle created.")
            try:
                messagebox.showinfo(
                    "AI analysis bundle created",
                    "Created a separate AI-analysis folder:\n\n"
                    f"{info.get('bundle_dir')}\n\n"
                    f"Files indexed: {info.get('n_files_indexed')}\n"
                    f"Files copied: {info.get('n_files_copied')}\n\n"
                    "If auto-run is enabled, the command window will refresh this bundle again after CV/EIS/DRT parsing finishes.",
                    parent=self,
                )
            except Exception:
                pass
    except Exception as exc:
        try:
            self.set_status("Export complete, but AI analysis bundle creation failed.")
            messagebox.showwarning("AI bundle skipped", f"Export completed, but the AI analysis bundle could not be created:\n\n{exc}", parent=self)
        except Exception:
            pass

SessionReaderGUI.export_outputs = _session_reader_gui_v35_export_outputs


# Override auto-run launcher so it regenerates the AI analysis bundle after all parser commands finish.
def _v27_launch_auto_pyseccm_after_export(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    data_dirs = _v27_candidate_plotting_data_dirs(gui, base_name=base_name)
    if not data_dirs:
        raise FileNotFoundError("No generated *_for_plotting_analysis/data folder was found after export.")
    script_root = _v19_default_script_dir_for_gui(gui) or _v19_find_pyseccm_script_root([Path(__file__).resolve().parent])
    if not script_root:
        script_root = str(Path(__file__).resolve().parent / "pyseccm_tools")
    python_exe = _v19_sys.executable

    missing = _v22_missing_modules_for_python(python_exe, kind="all")
    if missing:
        msg = "The auto-run pipeline needs pySECCM/DRT dependencies in the private Python environment.\n\nRepair/install them now?"
        if messagebox.askyesno("Auto-run dependencies", msg, parent=gui):
            _v22_install_dependencies_for_python(python_exe, kind="all", parent=gui)
        raise RuntimeError("Dependencies are missing or being repaired. Run Export again after the dependency window finishes.")

    all_commands = []
    all_notes = []
    folder_reports = []
    analysis_roots = []
    for d in data_dirs:
        try:
            cmds, notes, detected = _v27_build_auto_pyseccm_commands_for_data_dir(d, script_root=script_root, python_exe=python_exe, include_drt=True)
            all_commands.extend(cmds)
            all_notes.extend(notes)
            folder_reports.append({
                "data_dir": str(d),
                "n_cv": len(detected.get("cv", [])),
                "n_eis": len(detected.get("eis", [])),
                "n_iv": len(detected.get("iv", [])),
                "n_corr": len(detected.get("corr", [])),
                "n_ocp": len(detected.get("ocp", [])),
                "n_avg_ocp": len(detected.get("avg_ocp", [])),
                "n_drt_dir": len(detected.get("drt_dir", [])),
                "n_commands": len(cmds),
            })
            root = _v35_analysis_root_from_data_dir(d)
            if root not in analysis_roots:
                analysis_roots.append(root)
            try:
                _heka_v14_make_minimal_mplstyle(Path(d))
            except Exception:
                pass
        except Exception as exc:
            all_notes.append(f"Failed to prepare {d}: {exc}")

    # Rebuild AI bundles after all parsers/plotters finish, so they include Figures, DRT runs, and parsed output tables.
    for root in analysis_roots:
        try:
            all_commands.append((
                [python_exe, str(Path(__file__).resolve()), "--make-ai-analysis-bundle", str(root), "--base-name", str(base_name), "--label", "after_auto_parse"],
                root
            ))
            all_notes.append(f"AI analysis bundle will be refreshed after auto-parse: {root}")
        except Exception:
            pass

    if not all_commands:
        detail = "\n".join(all_notes) if all_notes else "No CV/EIS/IV/OCP/DRT files were detected."
        raise RuntimeError("No auto-run commands could be built.\n" + detail)
    title = "Auto pySECCM/DRT + AI bundle after FaradaIQ Studio export"
    batch = _v27_auto_pyseccm_batch_text(all_commands, notes=all_notes, title=title)
    bat = _v22_write_bat_and_launch(batch, cwd=Path(data_dirs[0]), prefix="auto_pyseccm_after_export")
    return {"batch": str(bat), "n_commands": len(all_commands), "folders": folder_reports, "script_root": str(script_root), "python_exe": str(python_exe)}


def _v35_cli_make_ai_bundle(argv):
    import argparse
    parser = argparse.ArgumentParser(description="Create a FaradaIQ Studio AI-analysis bundle from an analysis-ready output folder.")
    parser.add_argument("--make-ai-analysis-bundle", dest="analysis_root", required=True)
    parser.add_argument("--base-name", dest="base_name", default=None)
    parser.add_argument("--label", dest="label", default="cli")
    parser.add_argument("--no-copy-files", action="store_true")
    ns = parser.parse_args(argv)
    info = make_ai_analysis_bundle(ns.analysis_root, base_name=ns.base_name, label=ns.label, copy_files=not ns.no_copy_files)
    print("FaradaIQ Studio AI analysis bundle created")
    for k, v in info.items():
        print(f"{k}: {v}")
    return 0


def _v35_main():
    import sys as _v35_sys
    try:
        if len(_v35_sys.argv) > 1 and _v35_sys.argv[1] == "--make-ai-analysis-bundle":
            raise SystemExit(_v35_cli_make_ai_bundle(_v35_sys.argv[1:]))
    except SystemExit:
        raise
    except Exception as exc:
        print(f"AI bundle CLI failed: {exc}", file=_v35_sys.stderr)
        raise SystemExit(1)
    app = SessionReaderGUI()
    app.mainloop()

# ---- End v35 enhancement ----



