        style.configure("TCheckbutton", background=p["surface"], foreground=p["ink"], font=("Segoe UI",9)); style.map("TCheckbutton", background=[("active",p["surface2"])], foreground=[("active",p["ink"])]); style.configure("Status.TLabel", background=p["bg"], foreground=p["muted"], font=("Segoe UI",8))
