def _v36_toggle_theme(self):
    _v36_apply_theme(self, "light" if getattr(self,"_faradaiq_theme_mode","dark")=="dark" else "dark")


def _v36_cleanup_notes_widget(widget):
    if widget is None: return
    try: txt=widget.get("1.0","end")
    except Exception: return
    out=[]; skip=False; removed=False
    bad=("v15:","v16:","v17:","v18:","v19:","v20:","software-exported","fallback coordinates")
    for line in txt.splitlines():
        s=line.strip(); low=s.lower()
        if low.startswith("notes:") and any(b in low for b in bad):
            removed=True; skip=True; continue
        if skip:
            if (s.startswith("-") and any(b in low for b in bad)) or not s:
                removed=True; continue
            skip=False
        if s.startswith("-") and any(b in low for b in bad):
            removed=True; continue
        out.append(line)
    if removed:
        if out and out[-1].strip(): out.append("")
        out.append("Processing metadata: detailed generation notes are saved in the exported manifest JSON files.")
    try:
        widget.delete("1.0","end"); widget.insert("1.0", "\n".join(out).strip()+"\n")
    except Exception: pass

