# ---- v40 enhancement: Windows-env LLM provider selection, ping, and LiteLLM proxy helper ----
APP_TITLE = "FaradaIQ Studio v273"
_FARADAIQ_SELECTED_LLM_PROVIDER = None


def _v40_import_winreg():
    try:
        import winreg
        return winreg
    except Exception:
        return None


def _v40_env_value(name):
    """Read environment variables from process first, then Windows User/Machine env when available."""
    try:
        v = os.environ.get(name)
        if v not in (None, ""):
            return v, "Process"
    except Exception:
        pass
    winreg = _v40_import_winreg()
    if winreg is not None:
        probes = [
            (winreg.HKEY_CURRENT_USER, r"Environment", "User"),
            (winreg.HKEY_LOCAL_MACHINE, r"SYSTEM\CurrentControlSet\Control\Session Manager\Environment", "Machine"),
        ]
        for hive, subkey, label in probes:
            try:
                with winreg.OpenKey(hive, subkey) as key:
                    val, _typ = winreg.QueryValueEx(key, name)
                    if val not in (None, ""):
                        return str(val), label
            except Exception:
                pass
    return "", ""


def _v40_env_first(names, default=""):
    for n in names:
        v, _src = _v40_env_value(n)
        if v not in (None, ""):
            return v
    return default


# Override older env reader so LLM/Edison settings see Windows User/Machine variables too.
_v37_env_first = _v40_env_first


def _v40_env_status_rows():
    groups = [
        ("AI Incubator / API Key Depot", [
            ("AI_INCUBATOR_BASE_URL", "Base URL"),
            ("AI_INCUBATOR_MODEL", "Model"),
            ("AI_INCUBATOR_API_KEY", "API key"),
            ("GOOGLE_API_KEY", "Alt API key"),
            ("LLM_API_KEY", "Alt API key"),
        ]),
        ("Ollama", [
            ("OLLAMA_HOST", "Host"),
            ("OLLAMA_BASE_URL", "Alt host"),
            ("OLLAMA_MODEL", "Model"),
            ("OLLAMA_API_KEY", "Optional API key"),
        ]),
        ("AWS / LiteLLM proxy", [
            ("LITELLM_BASE_URL", "OpenAI-compatible proxy URL"),
            ("LITELLM_KEY", "Proxy key"),
            ("LITELLM_MODEL", "Proxy model alias"),
            ("AWS_PROFILE", "AWS profile"),
            ("AWS_REGION", "AWS region"),
            ("AWS_DEFAULT_REGION", "AWS default region"),
            ("AWS_BEDROCK_MODEL_ID", "Bedrock model ID"),
            ("BEDROCK_MODEL_ID", "Alt Bedrock model ID"),
        ]),
        ("Edison Scientific", [
            ("EDISON_BASE_URL", "Portal URL"),
            ("EDISON_UPLOAD_URL", "Upload URL"),
            ("EDISON_API_KEY", "Upload/API key"),
        ]),
    ]
    rows = []
    for group, items in groups:
        for key, desc in items:
            value, scope = _v40_env_value(key)
            rows.append({
                "group": group,
                "key": key,
                "description": desc,
                "present": bool(value),
                "scope": scope or "",
                "masked": _v37_mask_key(value) if ("KEY" in key or "TOKEN" in key or "SECRET" in key) else (value if value else ""),
            })
    return rows


def _v40_detect_ollama_model():
    host = _v40_env_first(["OLLAMA_HOST", "OLLAMA_BASE_URL"], "http://127.0.0.1:11434").rstrip("/")
    api_host = host[:-3] if host.endswith("/v1") else host
    env_model = _v40_env_first(["OLLAMA_MODEL", "FARADAIQ_OLLAMA_MODEL"], "")
    if env_model:
        return host, env_model, "env"
    try:
        tags = _v37_read_json_url(api_host + "/api/tags", timeout=2)
        models = tags.get("models", []) or []
        if models:
            model = models[0].get("name") or models[0].get("model") or ""
            if model:
                return host, model, "ollama /api/tags"
    except Exception:
        pass
    return host, "", ""


def _v40_provider_candidates(include_unavailable=True):
    """Return all selectable LLM providers, even when missing keys/proxy, so GUI can show what to fix."""
    candidates = []

    ai_key = _v40_env_first(["AI_INCUBATOR_API_KEY", "GOOGLE_API_KEY", "LLM_API_KEY", "FARADAIQ_LLM_API_KEY"], "")
    ai_key_name = ""
    for k in ["AI_INCUBATOR_API_KEY", "GOOGLE_API_KEY", "LLM_API_KEY", "FARADAIQ_LLM_API_KEY"]:
        if _v40_env_value(k)[0]:
            ai_key_name = k
            break
    ai_base = _v40_env_first(["AI_INCUBATOR_BASE_URL"], "https://ai-incubator-api.pnnl.gov").rstrip("/")
    ai_model = _v40_env_first(["AI_INCUBATOR_MODEL", "FARADAIQ_AI_INCUBATOR_MODEL"], "claude-sonnet-4-6-birthright")
    candidates.append({
        "name": "AI Incubator",
        "kind": "openai",
        "base_url": ai_base,
        "api_key": ai_key,
        "model": ai_model,
        "available": bool(ai_key),
        "missing": [] if ai_key else ["AI_INCUBATOR_API_KEY or GOOGLE_API_KEY or LLM_API_KEY"],
        "source": f"env:{ai_key_name}" if ai_key_name else "missing API key",
    })

    ollama_host, ollama_model, ollama_source = _v40_detect_ollama_model()
    ollama_base = ollama_host if ollama_host.endswith("/v1") else ollama_host.rstrip("/") + "/v1"
    candidates.append({
        "name": "Ollama",
        "kind": "openai",
        "base_url": ollama_base,
        "api_key": _v40_env_first(["OLLAMA_API_KEY"], "ollama"),
        "model": ollama_model or _v40_env_first(["OLLAMA_MODEL"], ""),
        "available": bool(ollama_model),
        "missing": [] if ollama_model else ["OLLAMA_MODEL or a running Ollama model from /api/tags"],
        "source": ollama_source or "not running / no model detected",
    })

    litellm_base = _v40_env_first(["LITELLM_BASE_URL", "AWS_LITELLM_BASE_URL"], "http://127.0.0.1:4000/v1").rstrip("/")
    litellm_key = _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY", "AWS_LITELLM_KEY"], "sk-local")
    litellm_model = _v40_env_first(["LITELLM_MODEL", "AWS_LITELLM_MODEL", "BEDROCK_LITELLM_MODEL"], "faradaiq-bedrock")
    candidates.append({
        "name": "AWS Bedrock via LiteLLM",
        "kind": "openai",
        "base_url": litellm_base,
        "api_key": litellm_key,
        "model": litellm_model,
        "available": True,
        "missing": [],
        "source": "local LiteLLM proxy; use Start AWS LiteLLM proxy if ping fails",
    })

    bedrock_model = _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "")
    aws_region = _v40_env_first(["AWS_REGION", "AWS_REGION_NAME", "AWS_DEFAULT_REGION"], "")
    aws_auth = _v40_env_first(["AWS_PROFILE", "AWS_ACCESS_KEY_ID"], "")
    candidates.append({
        "name": "AWS Bedrock direct",
        "kind": "bedrock",
        "model": bedrock_model,
        "available": bool(bedrock_model and aws_region and aws_auth),
        "missing": [m for m, ok in [
            ("AWS_BEDROCK_MODEL_ID or BEDROCK_MODEL_ID", bool(bedrock_model)),
            ("AWS_REGION / AWS_DEFAULT_REGION", bool(aws_region)),
            ("AWS_PROFILE or AWS_ACCESS_KEY_ID", bool(aws_auth)),
        ] if not ok],
        "source": "boto3 direct Bedrock",
    })

    return candidates if include_unavailable else [c for c in candidates if c.get("available")]


def _v37_llm_connections():
    """v40 override: selectable/provider-aware connections from Process/User/Machine Windows env."""
    selected = _FARADAIQ_SELECTED_LLM_PROVIDER or _v40_env_first(["FARADAIQ_LLM_PROVIDER"], "Auto")
    candidates = _v40_provider_candidates(include_unavailable=False)
    if selected and selected.lower() not in ("auto", "best", "default"):
        filtered = [c for c in candidates if c.get("name") == selected]
        return filtered or candidates
    return candidates


def _v40_ping_provider(candidate, max_tokens=20):
    """Return (ok, message). Does a real small LLM call, not just env detection."""
    try:
        if candidate.get("kind") == "openai":
            base = candidate.get("base_url", "").rstrip("/")
            if not base.endswith("/v1"):
                base = base + "/v1"
            model = candidate.get("model") or ""
            if not model:
                return False, "No model selected/detected."
            out = _v37_openai_chat(
                base,
                candidate.get("api_key") or "none",
                model,
                [
                    {"role": "system", "content": "You are a connection test. Reply with exactly PONG."},
                    {"role": "user", "content": "Ping."},
                ],
                max_tokens=max_tokens,
                temperature=0.0,
            )
            return True, (out or "").strip()[:300]
        if candidate.get("kind") == "bedrock":
            if candidate.get("missing"):
                return False, "Missing: " + ", ".join(candidate.get("missing"))
            out = _v37_aws_bedrock_chat(
                candidate.get("model"),
                [
                    {"role": "system", "content": "You are a connection test. Reply with exactly PONG."},
                    {"role": "user", "content": "Ping."},
                ],
                max_tokens=max_tokens,
                temperature=0.0,
            )
            return True, (out or "").strip()[:300]
        return False, "Unsupported provider kind."
    except Exception as exc:
        return False, str(exc)[:800]


def _v37_call_best_llm(messages, max_tokens=2600, temperature=0.2):
    """v40 override: use selected provider if chosen; otherwise try candidates in order."""
    selected = _FARADAIQ_SELECTED_LLM_PROVIDER or _v40_env_first(["FARADAIQ_LLM_PROVIDER"], "Auto")
    candidates = _v40_provider_candidates(include_unavailable=False)
    if selected and selected.lower() not in ("auto", "best", "default"):
        candidates = [c for c in candidates if c.get("name") == selected] or candidates
    errors = []
    for c in candidates:
        try:
            if c.get("kind") == "openai":
                base = c.get("base_url", "").rstrip("/")
                if not base.endswith("/v1"):
                    base += "/v1"
                return _v37_openai_chat(base, c.get("api_key") or "none", c.get("model"), messages, max_tokens=max_tokens, temperature=temperature), c
            if c.get("kind") == "bedrock":
                return _v37_aws_bedrock_chat(c.get("model"), messages, max_tokens=max_tokens, temperature=temperature), c
        except Exception as exc:
            errors.append(f"{c.get('name')}: {exc}")
    raise RuntimeError("No selected/available LLM backend succeeded.\n" + "\n".join(errors))


def _v40_litellm_proxy_paths():
    root = Path(__file__).resolve().parent / "litellm_proxy"
    return {
        "root": root,
        "venv": root / ".faradaiq_litellm_venv",
        "config": root / "litellm_bedrock.yaml",
        "requirements": root / "requirements_litellm_proxy.txt",
        "bat": root / "start_faradaiq_litellm_proxy.bat",
        "test_json": root / "proxy_test.json",
    }


def _v40_write_litellm_proxy_files():
    paths = _v40_litellm_proxy_paths()
    root = paths["root"]
    root.mkdir(parents=True, exist_ok=True)

    alias = _v40_env_first(["LITELLM_MODEL", "AWS_LITELLM_MODEL", "BEDROCK_LITELLM_MODEL"], "faradaiq-bedrock")
    bedrock_model = _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "anthropic.claude-3-haiku-20240307-v1:0")
    region = _v40_env_first(["AWS_REGION", "AWS_REGION_NAME", "AWS_DEFAULT_REGION"], "us-west-2")
    profile = _v40_env_first(["AWS_PROFILE"], "")
    key = _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY", "AWS_LITELLM_KEY"], "sk-local")
    port = _v40_env_first(["LITELLM_PORT"], "4000")

    profile_line = f'      aws_profile_name: "{profile}"\n' if profile else ""
    config = (
        "model_list:\n"
        f"  - model_name: {alias}\n"
        "    litellm_params:\n"
        f"      model: bedrock/{bedrock_model}\n"
        f'      aws_region_name: "{region}"\n'
        f"{profile_line}"
        "litellm_settings:\n"
        "  drop_params: true\n"
        "general_settings:\n"
        f"  master_key: {key}\n"
    )
    paths["config"].write_text(config, encoding="utf-8")
    paths["requirements"].write_text("litellm[proxy]\nboto3\n", encoding="utf-8")
    paths["test_json"].write_text(json.dumps({
        "model": alias,
        "messages": [{"role": "user", "content": "Say exactly: FaradaIQ LiteLLM proxy is working."}],
        "max_tokens": 50,
    }, indent=2), encoding="utf-8")

    seed_python = sys.executable
    bat = f"""@echo off
setlocal EnableExtensions
title FaradaIQ AWS Bedrock LiteLLM proxy
cd /d "%~dp0"

echo ============================================================
echo FaradaIQ AWS Bedrock LiteLLM proxy
echo ============================================================
echo This creates/uses a separate proxy environment in:
echo   %CD%\\.faradaiq_litellm_venv
echo.
echo It does not modify your main FaradaIQ environment or Anaconda.
echo.

set "VENV=.faradaiq_litellm_venv"
set "PYTHON_SEED={seed_python}"
set "LITELLM_PORT={port}"
set "LITELLM_KEY={key}"
set "LITELLM_BASE_URL=http://127.0.0.1:%LITELLM_PORT%/v1"
set "AWS_REGION={region}"
set "AWS_DEFAULT_REGION={region}"
"""
    if profile:
        bat += f'set "AWS_PROFILE={profile}"\n'
    bat += f"""
if not exist "%VENV%\\Scripts\\python.exe" (
  echo Creating LiteLLM proxy environment...
  "%PYTHON_SEED%" -m venv "%VENV%"
  if errorlevel 1 goto fail
)

echo Upgrading pip and installing LiteLLM proxy dependencies...
"%VENV%\\Scripts\\python.exe" -m pip install --upgrade pip setuptools wheel
if errorlevel 1 goto fail
"%VENV%\\Scripts\\python.exe" -m pip install -r "requirements_litellm_proxy.txt"
if errorlevel 1 goto fail

echo.
echo Starting LiteLLM proxy:
echo   URL:   %LITELLM_BASE_URL%
echo   Model: {alias}
echo   Key:   %LITELLM_KEY%
echo.
echo Keep this window open while using AWS/LiteLLM in FaradaIQ.
echo.

if exist "%VENV%\\Scripts\\litellm.exe" (
  "%VENV%\\Scripts\\litellm.exe" --config "litellm_bedrock.yaml" --host 127.0.0.1 --port %LITELLM_PORT%
) else (
  "%VENV%\\Scripts\\python.exe" -m litellm --config "litellm_bedrock.yaml" --host 127.0.0.1 --port %LITELLM_PORT%
)

goto end

:fail
echo.
echo [ERROR] LiteLLM proxy setup failed.
echo Check AWS_PROFILE/AWS_REGION/AWS credentials and internet access.
echo.

:end
pause
"""
    paths["bat"].write_text(bat, encoding="utf-8")
    return paths


def _v40_start_litellm_proxy(parent=None):
    try:
        paths = _v40_write_litellm_proxy_files()
        os.startfile(str(paths["bat"]))
        msg = (
            "Started/opened the AWS Bedrock LiteLLM proxy setup window.\n\n"
            f"Folder:\n{paths['root']}\n\n"
            "Keep that command window open, then return here and click Ping selected or Ping all."
        )
        try:
            messagebox.showinfo("LiteLLM proxy", msg, parent=parent)
        except Exception:
            pass
        return paths
    except Exception as exc:
        try:
            messagebox.showerror("LiteLLM proxy error", str(exc), parent=parent)
        except Exception:
            pass
        raise


def _v40_provider_report_text(ping_results=None):
    ping_results = ping_results or {}
    lines = [
        "FaradaIQ LLM / Edison settings",
        "",
        "Keys are read from Process, Windows User, and Windows Machine environment variables.",
        "Secret values are masked and never printed.",
        "",
        "Selectable LLM providers:",
    ]
    for c in _v40_provider_candidates(include_unavailable=True):
        status = "configured" if c.get("available") else "needs setup"
        ping = ping_results.get(c.get("name"))
        ping_txt = f" | ping: {'OK' if ping and ping[0] else 'FAILED'} - {ping[1] if ping else ''}" if ping else ""
        miss = (" | missing: " + ", ".join(c.get("missing", []))) if c.get("missing") else ""
        lines.append(f"  - {c.get('name')}: {status} | model={c.get('model','')} | {c.get('source','')}{miss}{ping_txt}")
    lines += ["", "Environment variables:"]
    for row in _v40_env_status_rows():
        present = "OK" if row["present"] else "MISSING"
        value = row["masked"] if row["present"] else ""
        src = f" ({row['scope']})" if row["scope"] else ""
        lines.append(f"  [{present}] {row['key']:<28} {row['description']:<34} {value}{src}")
    lines += [
        "",
        "AWS/LiteLLM notes:",
        "  - Click Start AWS LiteLLM proxy to create litellm_proxy/ in the launch folder.",
        "  - The proxy uses a separate .faradaiq_litellm_venv environment.",
        "  - It writes litellm_bedrock.yaml and start_faradaiq_litellm_proxy.bat in that folder.",
    ]
    return "\n".join(lines)


def _v37_show_llm_settings(self):
    """v40 override: provider choice, real ping tests, and AWS LiteLLM proxy starter."""
    global _FARADAIQ_SELECTED_LLM_PROVIDER
    try:
        win = tk.Toplevel(self)
        win.title("FaradaIQ LLM / Edison settings")
        win.geometry("960x700")
        try:
            p = _v36_theme_palette(getattr(self, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass

        outer = ttk.Frame(win, style="Card.TFrame", padding=(12, 12))
        outer.pack(fill="both", expand=True, padx=10, pady=10)

        ttk.Label(outer, text="LLM provider, key check, and ping test", style="Section.TLabel").pack(anchor="w")
        ttk.Label(
            outer,
            text="Choose an LLM backend. FaradaIQ reads keys from Windows environment variables and can ping the selected model before using it.",
            style="Muted.TLabel",
        ).pack(anchor="w", pady=(2, 8))

        selected = tk.StringVar(value=_FARADAIQ_SELECTED_LLM_PROVIDER or _v40_env_first(["FARADAIQ_LLM_PROVIDER"], "Auto"))
        provider_frame = ttk.LabelFrame(outer, text="Provider to use for AI prompt generation", padding=(8, 6))
        provider_frame.pack(fill="x", pady=(0, 8))
        names = ["Auto"] + [c.get("name") for c in _v40_provider_candidates(include_unavailable=True)]
        for n in names:
            ttk.Radiobutton(provider_frame, text=n, value=n, variable=selected).pack(side="left", padx=(0, 12))

        box = ScrolledText(outer, wrap="word", height=26)
        box.pack(fill="both", expand=True, pady=(4, 8))
        try:
            box.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc")
        except Exception:
            pass

        ping_results = {}

        def refresh():
            box.configure(state="normal")
            box.delete("1.0", "end")
            box.insert("1.0", _v40_provider_report_text(ping_results))
            box.configure(state="disabled")

        def apply_choice():
            global _FARADAIQ_SELECTED_LLM_PROVIDER
            _FARADAIQ_SELECTED_LLM_PROVIDER = selected.get()
            try:
                self.set_status(f"Selected LLM provider: {_FARADAIQ_SELECTED_LLM_PROVIDER}")
            except Exception:
                pass
            refresh()

        def ping_selected():
            apply_choice()
            target = selected.get()
            candidates = _v40_provider_candidates(include_unavailable=True)
            if target and target != "Auto":
                candidates = [c for c in candidates if c.get("name") == target]
            else:
                candidates = [c for c in candidates if c.get("available")]
            if not candidates:
                ping_results[target or "Auto"] = (False, "No configured provider to ping.")
                refresh()
                return
            for c in candidates[:1]:
                ok, msg = _v40_ping_provider(c)
                ping_results[c.get("name")] = (ok, msg)
            refresh()

        def ping_all():
            apply_choice()
            for c in _v40_provider_candidates(include_unavailable=True):
                if c.get("available"):
                    ok, msg = _v40_ping_provider(c)
                else:
                    ok, msg = False, "Missing: " + ", ".join(c.get("missing", []))
                ping_results[c.get("name")] = (ok, msg)
                refresh()
            refresh()

        refresh()

        btns = ttk.Frame(outer, style="Card.TFrame")
        btns.pack(fill="x")
        ttk.Button(btns, text="Apply provider", command=apply_choice).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Ping selected", command=ping_selected).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Ping all", command=ping_all).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Refresh env", command=refresh).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Start AWS LiteLLM proxy", command=lambda: _v40_start_litellm_proxy(self)).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Open Edison Scientific", command=lambda: webbrowser.open(_v40_env_first(["EDISON_BASE_URL", "EDISON_SCIENTIFIC_BASE_URL"], "https://platform.edisonscientific.com/"))).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=win.destroy).pack(side="right")
    except Exception:
        messagebox.showinfo("LLM / Edison settings", _v40_provider_report_text(), parent=self)


def _v40_show_llm_quick_status_at_start(self):
    try:
        candidates = _v40_provider_candidates(include_unavailable=True)
        configured = [c.get("name") for c in candidates if c.get("available")]
        missing = []
        for c in candidates:
            if not c.get("available") and c.get("missing"):
                missing.extend(c.get("missing"))
        msg = "LLM backends configured: " + (", ".join(configured) if configured else "none")
        if missing:
            msg += " | Open LLM settings for missing keys."
        self.set_status(msg)
    except Exception:
        pass


