def _v41_file_category(path, rel=""):
    low = (str(rel or path)).lower().replace("\\", "/")
    suffix = Path(path).suffix.lower()
    if "takedata" in low or "position" in low or "stage" in low:
        return "seccm_position_or_takedata"
    if "cv" in low or suffix == ".asc":
        return "cv"
    if "eis" in low or "fulleis" in low or "freq_zreal_zimag" in low or "drt_input_csv" in low:
        return "eis_or_drt_input"
    if "/drt/" in low or "\\drt\\" in low or "drt_" in low:
        return "drt_outputs"
    if "figure" in low or suffix in {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".svg", ".pdf"}:
        return "figures"
    if suffix == ".json":
        return "json_metadata"
    if suffix in {".npy", ".npz"}:
        return "npy_payloads"
    if suffix in {".csv", ".txt"}:
        return "tables_or_text"
    return "other"


def _v41_collect_ai_files(analysis_root, base_name=None):
    """Collect analysis-folder outputs plus raw export siblings such as *_parsed.npy and *_summary.json."""
    analysis_root = Path(analysis_root).resolve()
    files = []
    seen = set()

    def add(p):
        try:
            p = Path(p).resolve()
            if p.exists() and p.is_file():
                key = str(p)
                if key not in seen:
                    seen.add(key)
                    files.append(p)
        except Exception:
            pass

    for p in _v35_collect_analysis_files(analysis_root):
        # Avoid recursively ingesting previous AI bundles or Edison handoff ZIPs.
        try:
            parts_lower = [str(part).lower() for part in p.relative_to(analysis_root).parts]
            if any("ai_analysis_with_parsed_outputs" in part for part in parts_lower):
                continue
            if any("edisonscientific_handoff" in part or "edison_handoff" in part for part in parts_lower):
                continue
        except Exception:
            pass
        add(p)

    # Include raw/export siblings outside the analysis_ready_csv folder.
    parent = analysis_root.parent
    safe = _v35_safe_name(base_name or analysis_root.name.replace("_analysis_ready_csv", ""))
    base_candidates = [base_name, safe, analysis_root.name.replace("_analysis_ready_csv", "")]
    for b in [x for x in base_candidates if x]:
        for suffix in ["_parsed.npy", "_summary.json", "_raw_session.json", "_analysis_ready_manifest.json"]:
            add(parent / f"{b}{suffix}")
        for p in parent.glob(f"{b}*.npy"):
            add(p)
        for p in parent.glob(f"{b}*.json"):
            add(p)

    return sorted(files, key=lambda x: str(x).lower())


def _v41_relative_label(path, analysis_root, base_name=None):
    p = Path(path).resolve()
    analysis_root = Path(analysis_root).resolve()
    try:
        return p.relative_to(analysis_root).as_posix()
    except Exception:
        pass
    try:
        return ("raw_export_siblings/" + p.relative_to(analysis_root.parent).as_posix())
    except Exception:
        return p.name


def _v41_read_table_payload(path, max_full_bytes=250_000_000):
    """Read parsed tables as actual data for AI payload, not just previews."""
    path = Path(path)
    out = {"loader": "none"}
    size = path.stat().st_size
    if size > max_full_bytes:
        out["skipped_full_load"] = f"file larger than {max_full_bytes} bytes"
        return out
    try:
        # Try pandas with flexible delimiter first.
        import pandas as _pd
        try:
            df = _pd.read_csv(path, sep=None, engine="python", comment=None)
        except Exception:
            # HEKA-style files sometimes have repeated headers; still preserve rows.
            df = _pd.read_csv(path, sep=None, engine="python", header=None, comment=None)
        out.update({
            "loader": "pandas",
            "columns": [str(c) for c in df.columns],
            "shape": [int(df.shape[0]), int(df.shape[1])],
            "data": df.to_dict(orient="list"),
        })
        # Numeric view for model/math use.
        try:
            num = df.apply(_pd.to_numeric, errors="coerce")
            numeric_cols = [str(c) for c in num.columns if num[c].notna().any()]
            if numeric_cols:
                out["numeric_columns"] = numeric_cols
                out["numeric_matrix"] = num[numeric_cols].to_numpy(dtype=float)
        except Exception:
            pass
        return out
    except Exception as exc:
        out["pandas_error"] = str(exc)
    try:
        raw = path.read_text(encoding="utf-8-sig", errors="replace")
        out["loader"] = "raw_text"
        out["raw_text"] = raw
        return out
    except Exception as exc:
        out["raw_text_error"] = str(exc)
    return out


def _v41_load_file_payload(path, rel, max_full_bytes=250_000_000):
    """organized payload content for AI NPY. Includes raw and parsed data where practical."""
    path = Path(path)
    suffix = path.suffix.lower()
    size = path.stat().st_size
    category = _v41_file_category(path, rel)
    payload = {
        "relative_path": rel,
        "name": path.name,
        "suffix": suffix,
        "category": category,
        "size_bytes": int(size),
        "content_loaded": False,
    }
    try:
        if suffix in {".csv", ".txt", ".asc"}:
            preview = _v35_text_preview(path, max_chars=50000)
            payload["text_preview"] = preview.get("preview", "")
            payload["preview_truncated"] = preview.get("preview_truncated", True)
            payload["table"] = _v41_read_table_payload(path, max_full_bytes=max_full_bytes)
            payload["content_loaded"] = payload["table"].get("loader") != "none"
        elif suffix == ".json":
            if size <= max_full_bytes:
                payload["json"] = json.loads(path.read_text(encoding="utf-8", errors="replace"))
                payload["content_loaded"] = True
            else:
                payload["skipped_full_load"] = f"JSON larger than {max_full_bytes} bytes"
        elif suffix in {".npy", ".npz"}:
            if size <= max_full_bytes:
                if suffix == ".npy":
                    payload["npy_object"] = np.load(path, allow_pickle=True)
                else:
                    z = np.load(path, allow_pickle=True)
                    payload["npz_keys"] = list(z.keys())
                    payload["npz_arrays"] = {k: z[k] for k in z.keys()}
                payload["content_loaded"] = True
            else:
                payload["skipped_full_load"] = f"NumPy file larger than {max_full_bytes} bytes"
        elif suffix in {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".svg", ".pdf"}:
            # Include bytes for small figures so Edison/AI tools can inspect them from one payload.
            if size <= 25_000_000:
                payload["binary_bytes"] = path.read_bytes()
                payload["content_loaded"] = True
            else:
                payload["skipped_full_load"] = "figure/binary larger than 25 MB"
        else:
            if size <= 5_000_000:
                payload["raw_bytes"] = path.read_bytes()
                payload["content_loaded"] = True
    except Exception as exc:
        payload["load_error"] = str(exc)
    return payload


def make_ai_analysis_bundle(analysis_root, base_name=None, label="with_analysis", copy_files=True, progress_callback=None):
    """v41 override: include raw exports + parsed/structured post-parser data in NPY and JSON."""
    analysis_root = Path(analysis_root).resolve()
    if base_name is None:
        name = analysis_root.name
        base_name = name[:-len("_analysis_ready_csv")] if name.endswith("_analysis_ready_csv") else name
    safe = _v35_safe_name(base_name)
    bundle_dir = analysis_root / f"{safe}_AI_analysis_with_parsed_outputs"
    snapshot_dir = bundle_dir / "files_snapshot"
    bundle_dir.mkdir(parents=True, exist_ok=True)
    if copy_files:
        snapshot_dir.mkdir(parents=True, exist_ok=True)

    def progress(msg):
        _v41_progress(msg)
        if progress_callback:
            try:
                progress_callback(msg)
            except Exception:
                pass

    progress(f"[AI bundle] Scanning parsed/raw outputs under: {analysis_root}")
    files = _v41_collect_ai_files(analysis_root, base_name=base_name)
    progress(f"[AI bundle] Files discovered: {len(files)}")

    manifest_files = []
    organized_payloads = {}
    text_previews = []
    table_summaries = []
    copied_count = 0
    skipped_copy_count = 0
    max_copy_bytes = 500_000_000
    max_full_load_bytes = 250_000_000

    for idx, p in enumerate(files, start=1):
        rel = _v41_relative_label(p, analysis_root, base_name=base_name)
        category = _v41_file_category(p, rel)
        progress(f"[AI bundle] {idx}/{len(files)} {category}: {rel}")
        try:
            st = p.stat()
            item = {
                "relative_path": rel,
                "name": p.name,
                "suffix": p.suffix.lower(),
                "category": category,
                "size_bytes": int(st.st_size),
                "modified_time": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
            }
            if p.suffix.lower() in {".csv", ".txt", ".asc"}:
                meta = _v35_detect_table_metadata(p)
                item.update(meta)
                table_summaries.append({"relative_path": rel, "category": category, **meta})
                preview = _v35_text_preview(p, max_chars=20000)
                text_previews.append({"relative_path": rel, "category": category, **preview})
            if copy_files:
                if st.st_size <= max_copy_bytes:
                    dest = snapshot_dir / rel
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(p, dest)
                    item["snapshot_relative_path"] = str(Path("files_snapshot") / rel).replace("\\", "/")
                    copied_count += 1
                else:
                    item["copy_skipped"] = f"file larger than {max_copy_bytes} bytes"
                    skipped_copy_count += 1
            manifest_files.append(item)

            payload = _v41_load_file_payload(p, rel, max_full_bytes=max_full_load_bytes)
            organized_payloads.setdefault(category, []).append(payload)
        except Exception as exc:
            manifest_files.append({"relative_path": rel, "category": category, "error": str(exc)})
            organized_payloads.setdefault("errors", []).append({"relative_path": rel, "error": str(exc)})

    categories = {}
    for item in manifest_files:
        cat = item.get("category", "other")
        categories.setdefault(cat, []).append(item.get("relative_path", ""))

    prompt_path = analysis_root / "AI_prompt_current.txt"
    current_prompt = ""
    if prompt_path.exists():
        try:
            current_prompt = prompt_path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            pass

    summary = {
        "schema": "faradaiq-ai-analysis-bundle-v2",
        "app": "FaradaIQ Studio",
        "version": "v273",
        "created": datetime.now().isoformat(timespec="seconds"),
        "base_name": base_name,
        "label": label,
        "analysis_root": str(analysis_root),
        "bundle_dir": str(bundle_dir),
        "snapshot_dir": str(snapshot_dir) if copy_files else None,
        "n_files_indexed": len(manifest_files),
        "n_files_copied": copied_count,
        "n_files_copy_skipped": skipped_copy_count,
        "payload_policy": {
            "max_full_load_bytes_per_table_or_npy": max_full_load_bytes,
            "max_copy_bytes_per_file": max_copy_bytes,
            "figures_binary_loaded_up_to_bytes": 25_000_000,
            "note": "Large files are indexed and copied when allowed; full in-memory NPY payload loading is size-limited to avoid unusable multi-GB bundles.",
        },
        "categories": {k: {"count": len(v), "files": v[:1000]} for k, v in categories.items()},
        "notes": [
            "This folder is intended for AI analysis handoff after parsing.",
            "The NPY payload includes raw export siblings, parsed SECCM files, CV/EIS tables, DRT inputs/outputs, JSON metadata, NPY payloads, figures, and organized analysis-ready content where practical.",
            "The files_snapshot folder contains copied source files for independent review.",
        ],
    }

    manifest = {"schema": "faradaiq-ai-analysis-manifest-v2", "summary": summary, "files": manifest_files}
    payload = {
        "schema": "faradaiq-ai-analysis-payload-v2",
        "summary": summary,
        "current_prompt": current_prompt,
        "manifest_files": manifest_files,
        "organized_payloads": organized_payloads,
        "text_previews": text_previews,
        "table_summaries": table_summaries,
    }

    manifest_path = bundle_dir / f"{safe}_AI_analysis_manifest.json"
    summary_path = bundle_dir / f"{safe}_AI_analysis_summary.json"
    npy_path = bundle_dir / f"{safe}_AI_analysis_payload.npy"
    readme_path = bundle_dir / "README_AI_ANALYSIS.txt"

    progress("[AI bundle] Writing manifest JSON...")
    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    progress("[AI bundle] Writing summary JSON...")
    with open(summary_path, "w", encoding="utf-8") as f:
        json.dump(summary, f, ensure_ascii=False, indent=2)
    progress("[AI bundle] Writing NPY payload with organized analysis-ready data...")
    np.save(npy_path, np.array(payload, dtype=object), allow_pickle=True)
    readme_path.write_text(
        "FaradaIQ Studio AI analysis bundle\n"
        "==================================\n\n"
        f"Created: {summary['created']}\n"
        f"Base name: {base_name}\n"
        f"Analysis root: {analysis_root}\n\n"
        "Use these files for AI handoff:\n"
        f"- {npy_path.name}\n"
        f"- {summary_path.name}\n"
        f"- {manifest_path.name}\n\n"
        "The NPY payload includes organized analysis-ready data grouped by category.\n"
        "The files_snapshot folder contains copies of parsed/analyzed output files when size limits allow.\n",
        encoding="utf-8",
    )
    progress(f"[AI bundle] Complete: {bundle_dir}")
    return {
        "bundle_dir": str(bundle_dir),
        "manifest_path": str(manifest_path),
        "summary_path": str(summary_path),
        "npy_path": str(npy_path),
        "n_files_indexed": len(manifest_files),
        "n_files_copied": copied_count,
    }


def _v41_send_ai_bundle_to_edison_cli(path, base_name=None):
    root = Path(path).resolve()
    if root.name.endswith("_AI_analysis_with_parsed_outputs"):
        bundle_dir = root
        analysis_root = root.parent
        if base_name is None:
            base_name = root.name.replace("_AI_analysis_with_parsed_outputs", "")
    else:
        analysis_root = root
        if base_name is None:
            name = analysis_root.name
            base_name = name[:-len("_analysis_ready_csv")] if name.endswith("_analysis_ready_csv") else name
        info = make_ai_analysis_bundle(analysis_root, base_name=base_name, label="edison_after_parse", copy_files=True)
        bundle_dir = Path(info["bundle_dir"])

    safe = _v35_safe_name(base_name or bundle_dir.name)
    run_id = datetime.now().strftime("%Y%m%d_%H%M%S")
    handoff_dir = analysis_root / f"{safe}_EdisonScientific_handoff" / f"edison_{run_id}"
    handoff_dir.mkdir(parents=True, exist_ok=True)

    prompt_text = ""
    for p in [analysis_root / "AI_prompt_current.txt", bundle_dir / "AI_prompt_current.txt"]:
        if p.exists():
            try:
                prompt_text = p.read_text(encoding="utf-8", errors="replace")
                break
            except Exception:
                pass
    (handoff_dir / "AI_prompt_for_Edison.txt").write_text(prompt_text, encoding="utf-8")

    metadata = {
        "created": datetime.now().isoformat(timespec="seconds"),
        "app": "FaradaIQ Studio",
        "version": "v273",
        "base_name": base_name,
        "analysis_root": str(analysis_root),
        "ai_bundle_dir": str(bundle_dir),
        "edison_base_url": _v40_env_first(["EDISON_BASE_URL", "EDISON_SCIENTIFIC_BASE_URL"], "https://platform.edisonscientific.com/"),
        "edison_upload_url": _v40_env_first(["EDISON_UPLOAD_URL", "EDISON_SCIENTIFIC_UPLOAD_URL"], ""),
        "note": "This zip contains the FaradaIQ AI analysis bundle, parsed outputs snapshot, structured NPY payload, JSON manifests, and current AI prompt text.",
    }
    (handoff_dir / "edison_handoff_metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    zip_path = handoff_dir / f"{safe}_EdisonScientific_AI_bundle_{run_id}.zip"

    _v41_progress(f"[Edison] Creating upload ZIP: {zip_path}")
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for p in bundle_dir.rglob("*"):
            if p.is_file():
                z.write(p, Path("AI_analysis_bundle") / p.relative_to(bundle_dir))
        z.write(handoff_dir / "AI_prompt_for_Edison.txt", "AI_prompt_for_Edison.txt")
        z.write(handoff_dir / "edison_handoff_metadata.json", "edison_handoff_metadata.json")

    upload_url = _v40_env_first(["EDISON_UPLOAD_URL", "EDISON_SCIENTIFIC_UPLOAD_URL"], "")
    api_key = _v40_env_first(["EDISON_API_KEY", "EDISON_SCIENTIFIC_API_KEY"], "")
    if upload_url and api_key:
        _v41_progress("[Edison] Uploading to Edison Scientific...")
        result = _v37_multipart_upload(
            upload_url,
            api_key,
            fields={"app": "FaradaIQ Studio", "version": "v273", "metadata": json.dumps(metadata)},
            files={"file": zip_path},
            timeout=900,
        )
        response_path = handoff_dir / "edison_upload_response.json"
        response_path.write_text(json.dumps(result, indent=2), encoding="utf-8")
        _v41_progress(f"[Edison] Upload complete. Response: {response_path}")
        return {"zip_path": str(zip_path), "handoff_dir": str(handoff_dir), "uploaded": True, "response_path": str(response_path)}
    else:
        _v41_progress("[Edison] EDISON_UPLOAD_URL or EDISON_API_KEY missing. Local handoff ZIP created only.")
        _v41_progress(f"[Edison] Local ZIP: {zip_path}")
        return {"zip_path": str(zip_path), "handoff_dir": str(handoff_dir), "uploaded": False}


# Final export override: use normal export, create AI bundle with live GUI progress, launch parsers, optionally send to Edison after parsing.
_SESSION_READER_GUI_V41_BASE_EXPORT_OUTPUTS = globals().get("_SESSION_READER_GUI_V27_PREV_EXPORT_OUTPUTS", SessionReaderGUI.export_outputs)

def _session_reader_gui_v41_export_outputs(self):
    global _FARADAIQ_AI_PROGRESS_CALLBACK
    base_name = _v27_current_base_name(self)
    progress_win, progress_log = _v41_analysis_progress_window(self, "FaradaIQ live export / AI bundle progress")
    _FARADAIQ_AI_PROGRESS_CALLBACK = progress_log
    try:
        progress_log("[Export] Starting normal export and analysis-ready CSV generation...")
        _SESSION_READER_GUI_V41_BASE_EXPORT_OUTPUTS(self)

        analysis_root = _v35_analysis_root_for_export(self, base_name=base_name)
        if analysis_root.exists():
            try:
                prompt_text = self.desc_text.get("1.0", "end").strip()
                (analysis_root / "AI_prompt_current.txt").write_text(prompt_text, encoding="utf-8")
            except Exception:
                pass
            progress_log("[Export] Creating AI-analysis bundle with raw + parsed + organized data...")
            info = make_ai_analysis_bundle(analysis_root, base_name=base_name, label="after_export", copy_files=True, progress_callback=progress_log)
            progress_log(f"[Export] AI-analysis bundle ready: {info.get('bundle_dir')}")

        enabled = bool(getattr(self, "auto_run_pyseccm_after_export_var", tk.BooleanVar(value=False)).get())
        send_after = bool(getattr(self, "send_ai_bundle_to_edison_after_parse_var", tk.BooleanVar(value=False)).get())
        if enabled:
            progress_log("[Auto-run] Launching available CV/EIS/IV/OCP/DRT parsers in a separate command window...")
            result = _v27_launch_auto_pyseccm_after_export(self, base_name=base_name)
            progress_log(f"[Auto-run] Command window launched: {result.get('batch')}")
            progress_log(f"[Auto-run] Commands queued: {result.get('n_commands')}")
            if send_after:
                progress_log("[Auto-run] Edison send is queued after parser completion in the command window.")
        elif send_after and analysis_root.exists():
            progress_log("[Edison] Auto-run is not enabled; sending current AI bundle to Edison/local handoff now...")
            result = _v41_send_ai_bundle_to_edison_cli(analysis_root, base_name=base_name)
            progress_log(f"[Edison] Handoff complete: {result.get('zip_path')}")
        self.set_status("Export / AI bundle setup complete.")
    except Exception as exc:
        self.set_status("Export / AI bundle action failed.")
        progress_log(f"[ERROR] {exc}")
        messagebox.showerror("FaradaIQ export / AI bundle error", f"{exc}\n\n{traceback.format_exc()}", parent=self)
    finally:
        _FARADAIQ_AI_PROGRESS_CALLBACK = None

SessionReaderGUI.export_outputs = _session_reader_gui_v41_export_outputs


