# Override auto-run launcher to add final AI-bundle refresh and optional Edison send command into the live command window.
def _v27_launch_auto_pyseccm_after_export(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    data_dirs = _v27_candidate_plotting_data_dirs(gui, base_name=base_name)
    if not data_dirs:
        raise FileNotFoundError("No generated *_for_plotting_analysis/data folder was found after export.")
    script_root = _v19_default_script_dir_for_gui(gui) or _v19_find_pyseccm_script_root([Path(__file__).resolve().parent])
    if not script_root:
        script_root = str(Path(__file__).resolve().parent / "pyseccm_tools")
    python_exe = _v19_sys.executable

    missing = _v22_missing_modules_for_python(python_exe, kind="all")
    if missing:
        msg = "The auto-run pipeline needs pySECCM/DRT dependencies in the private Python environment.\n\nRepair/install them now?"
        if messagebox.askyesno("Auto-run dependencies", msg, parent=gui):
            _v22_install_dependencies_for_python(python_exe, kind="all", parent=gui)
        raise RuntimeError("Dependencies are missing or being repaired. Run Export again after the dependency window finishes.")

    send_after = bool(getattr(gui, "send_ai_bundle_to_edison_after_parse_var", tk.BooleanVar(value=False)).get())
    all_commands = []
    all_notes = []
    folder_reports = []
    analysis_roots = []

    for d in data_dirs:
        try:
            cmds, notes, detected = _v27_build_auto_pyseccm_commands_for_data_dir(d, script_root=script_root, python_exe=python_exe, include_drt=True)
            all_commands.extend(cmds)
            all_notes.extend(notes)
            folder_reports.append({
                "data_dir": str(d),
                "n_cv": len(detected.get("cv", [])),
                "n_eis": len(detected.get("eis", [])),
                "n_iv": len(detected.get("iv", [])),
                "n_corr": len(detected.get("corr", [])),
                "n_ocp": len(detected.get("ocp", [])),
                "n_avg_ocp": len(detected.get("avg_ocp", [])),
                "n_drt_dir": len(detected.get("drt_dir", [])),
                "n_commands": len(cmds),
            })
            root = _v35_analysis_root_from_data_dir(d)
            if root not in analysis_roots:
                analysis_roots.append(root)
            try:
                _heka_v14_make_minimal_mplstyle(Path(d))
            except Exception:
                pass
        except Exception as exc:
            all_notes.append(f"Failed to prepare {d}: {exc}")

    # Add post-parser AI bundle refresh and optional Edison handoff.
    for root in analysis_roots:
        try:
            try:
                prompt_text = gui.desc_text.get("1.0", "end").strip()
                (Path(root) / "AI_prompt_current.txt").write_text(prompt_text, encoding="utf-8")
            except Exception:
                pass
            all_commands.append((
                [python_exe, str(Path(__file__).resolve()), "--make-ai-analysis-bundle", str(root), "--base-name", str(base_name), "--label", "after_auto_parse"],
                root,
            ))
            all_notes.append(f"AI analysis bundle will be refreshed after parser completion: {root}")
            if send_after:
                all_commands.append((
                    [python_exe, str(Path(__file__).resolve()), "--send-ai-bundle-to-edison", str(root), "--base-name", str(base_name)],
                    root,
                ))
                all_notes.append(f"Edison/local handoff will run after AI bundle refresh: {root}")
        except Exception as exc:
            all_notes.append(f"Failed to queue AI/Edison post-processing for {root}: {exc}")

    if not all_commands:
        detail = "\n".join(all_notes) if all_notes else "No CV/EIS/IV/OCP/DRT files were detected."
        raise RuntimeError("No auto-run commands could be built.\n" + detail)

    title = "Auto parsers + AI bundle + optional Edison handoff"
    batch = _v27_auto_pyseccm_batch_text(all_commands, notes=all_notes, title=title)
    bat = _v22_write_bat_and_launch(batch, cwd=Path(data_dirs[0]), prefix="auto_pyseccm_after_export")
    return {"batch": str(bat), "n_commands": len(all_commands), "folders": folder_reports, "script_root": str(script_root), "python_exe": str(python_exe)}


def _v41_cli(argv):
    import argparse
    if argv and argv[0] == "--make-ai-analysis-bundle":
        parser = argparse.ArgumentParser(description="Create a FaradaIQ AI-analysis bundle from an analysis-ready output folder.")
        parser.add_argument("--make-ai-analysis-bundle", dest="analysis_root", required=True)
        parser.add_argument("--base-name", dest="base_name", default=None)
        parser.add_argument("--label", dest="label", default="cli")
        parser.add_argument("--no-copy-files", action="store_true")
        ns = parser.parse_args(argv)
        info = make_ai_analysis_bundle(ns.analysis_root, base_name=ns.base_name, label=ns.label, copy_files=not ns.no_copy_files)
        print("FaradaIQ Studio AI analysis bundle created")
        for k, v in info.items():
            print(f"{k}: {v}")
        return 0
    if argv and argv[0] == "--send-ai-bundle-to-edison":
        parser = argparse.ArgumentParser(description="Create/upload Edison Scientific handoff from a FaradaIQ AI bundle or analysis-ready folder.")
        parser.add_argument("--send-ai-bundle-to-edison", dest="path", required=True)
        parser.add_argument("--base-name", dest="base_name", default=None)
        ns = parser.parse_args(argv)
        info = _v41_send_ai_bundle_to_edison_cli(ns.path, base_name=ns.base_name)
        print("FaradaIQ Edison handoff finished")
        for k, v in info.items():
            print(f"{k}: {v}")
        return 0
    return None


def _v41_main():
    try:
        cli_result = _v41_cli(sys.argv[1:])
        if cli_result is not None:
            raise SystemExit(cli_result)
    except SystemExit:
        raise
    except Exception as exc:
        print(f"FaradaIQ CLI failed: {exc}", file=sys.stderr)
        raise SystemExit(1)
    app = SessionReaderGUI()
    app.mainloop()

