def _v42_mask_for_display(value):
    try:
        return _v37_mask_key(value)
    except Exception:
        if not value:
            return ""
        return str(value)[:4] + "..." + str(value)[-4:]


def _v42_provider_defaults(provider):
    provider = str(provider or "Auto")
    if provider == "AI Incubator":
        key = _v40_env_first(["AI_INCUBATOR_API_KEY", "GOOGLE_API_KEY", "LLM_API_KEY", "FARADAIQ_LLM_API_KEY"], "")
        return {
            "base_url": _v40_env_first(["AI_INCUBATOR_BASE_URL"], "https://ai-incubator-api.pnnl.gov"),
            "model": _v40_env_first(["AI_INCUBATOR_MODEL", "FARADAIQ_AI_INCUBATOR_MODEL"], "claude-sonnet-4-6-birthright"),
            "api_key": key,
            "aws_profile": _v40_env_first(["AWS_PROFILE"], ""),
            "aws_region": _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2"),
            "bedrock_model": _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], ""),
        }
    if provider == "Ollama":
        host, model, _src = _v40_detect_ollama_model()
        return {
            "base_url": host if str(host).endswith('/v1') else str(host).rstrip('/') + '/v1',
            "model": model or _v40_env_first(["OLLAMA_MODEL", "FARADAIQ_OLLAMA_MODEL"], "llama3.1"),
            "api_key": _v40_env_first(["OLLAMA_API_KEY"], "ollama"),
            "aws_profile": _v40_env_first(["AWS_PROFILE"], ""),
            "aws_region": _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2"),
            "bedrock_model": _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], ""),
        }
    if provider == "AWS Bedrock via LiteLLM":
        return {
            "base_url": _v40_env_first(["LITELLM_BASE_URL", "AWS_LITELLM_BASE_URL"], "http://127.0.0.1:4000/v1"),
            "model": _v40_env_first(["LITELLM_MODEL", "AWS_LITELLM_MODEL", "BEDROCK_LITELLM_MODEL"], "faradaiq-bedrock"),
            "api_key": _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY", "AWS_LITELLM_KEY"], "sk-local"),
            "aws_profile": _v40_env_first(["AWS_PROFILE"], ""),
            "aws_region": _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2"),
            "bedrock_model": _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "anthropic.claude-3-haiku-20240307-v1:0"),
        }
    if provider == "AWS Bedrock direct":
        return {
            "base_url": "",
            "model": _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "anthropic.claude-3-haiku-20240307-v1:0"),
            "api_key": "",
            "aws_profile": _v40_env_first(["AWS_PROFILE"], ""),
            "aws_region": _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2"),
            "bedrock_model": _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "anthropic.claude-3-haiku-20240307-v1:0"),
        }
    # Auto: fill with first configured provider, else AI Incubator defaults.
    for cand in _v40_provider_candidates(include_unavailable=False):
        if cand.get("name") in {"AI Incubator", "Ollama", "AWS Bedrock via LiteLLM", "AWS Bedrock direct"}:
            return _v42_provider_defaults(cand.get("name"))
    return _v42_provider_defaults("AI Incubator")


def _v42_candidate_from_fields(provider, base_url, model, api_key, aws_profile='', aws_region='', bedrock_model=''):
    provider = str(provider or "Auto")
    if provider == "Auto":
        # Let normal auto-selection use current environment after apply.
        cands = _v40_provider_candidates(include_unavailable=False)
        return cands[0] if cands else {"name":"Auto", "available":False, "missing":["No configured provider"]}
    if provider in {"AI Incubator", "Ollama", "AWS Bedrock via LiteLLM"}:
        return {
            "name": provider,
            "kind": "openai",
            "base_url": str(base_url or "").rstrip("/"),
            "model": model,
            "api_key": api_key or ("ollama" if provider == "Ollama" else ""),
            "available": bool(model and (provider == "Ollama" or api_key or provider == "AWS Bedrock via LiteLLM")),
            "missing": [m for m, ok in [("model", bool(model)), ("api key", bool(api_key or provider in {"Ollama", "AWS Bedrock via LiteLLM"}))] if not ok],
            "source": "manual GUI fields",
        }
    if provider == "AWS Bedrock direct":
        return {
            "name": provider,
            "kind": "bedrock",
            "model": bedrock_model or model,
            "available": bool((bedrock_model or model) and aws_region and (aws_profile or _v40_env_first(["AWS_ACCESS_KEY_ID"], ""))),
            "missing": [m for m, ok in [
                ("AWS_BEDROCK_MODEL_ID", bool(bedrock_model or model)),
                ("AWS_REGION", bool(aws_region)),
                ("AWS_PROFILE or AWS_ACCESS_KEY_ID", bool(aws_profile or _v40_env_first(["AWS_ACCESS_KEY_ID"], ""))),
            ] if not ok],
            "source": "manual GUI fields / boto3 direct",
        }
    return {"name": provider, "available": False, "missing": ["unknown provider"]}


def _v42_apply_llm_fields_to_env(provider, base_url, model, api_key, aws_profile='', aws_region='', bedrock_model=''):
    global _FARADAIQ_SELECTED_LLM_PROVIDER
    provider = str(provider or "Auto")
    _FARADAIQ_SELECTED_LLM_PROVIDER = provider
    os.environ["FARADAIQ_LLM_PROVIDER"] = provider
    if provider == "AI Incubator":
        os.environ["AI_INCUBATOR_BASE_URL"] = str(base_url or "").rstrip("/")
        os.environ["AI_INCUBATOR_MODEL"] = str(model or "")
        if api_key:
            os.environ["AI_INCUBATOR_API_KEY"] = str(api_key)
    elif provider == "Ollama":
        b = str(base_url or "http://127.0.0.1:11434/v1").rstrip("/")
        host = b[:-3] if b.endswith("/v1") else b
        os.environ["OLLAMA_HOST"] = host
        os.environ["OLLAMA_BASE_URL"] = b if b.endswith("/v1") else b + "/v1"
        os.environ["OLLAMA_MODEL"] = str(model or "")
        if api_key:
            os.environ["OLLAMA_API_KEY"] = str(api_key)
    elif provider == "AWS Bedrock via LiteLLM":
        os.environ["LITELLM_BASE_URL"] = str(base_url or "http://127.0.0.1:4000/v1").rstrip("/")
        os.environ["LITELLM_MODEL"] = str(model or "faradaiq-bedrock")
        os.environ["LITELLM_KEY"] = str(api_key or "sk-local")
        if bedrock_model:
            os.environ["AWS_BEDROCK_MODEL_ID"] = str(bedrock_model)
        if aws_region:
            os.environ["AWS_REGION"] = str(aws_region)
            os.environ["AWS_DEFAULT_REGION"] = str(aws_region)
        if aws_profile:
            os.environ["AWS_PROFILE"] = str(aws_profile)
    elif provider == "AWS Bedrock direct":
        if bedrock_model or model:
            os.environ["AWS_BEDROCK_MODEL_ID"] = str(bedrock_model or model)
        if aws_region:
            os.environ["AWS_REGION"] = str(aws_region)
            os.environ["AWS_DEFAULT_REGION"] = str(aws_region)
        if aws_profile:
            os.environ["AWS_PROFILE"] = str(aws_profile)
    return _FARADAIQ_SELECTED_LLM_PROVIDER


def _v42_write_setx_helper(provider, base_url, model, api_key, aws_profile='', aws_region='', bedrock_model=''):
    folder = Path(__file__).resolve().parent / "llm_env_helpers"
    folder.mkdir(parents=True, exist_ok=True)
    bat = folder / "set_faradaiq_llm_env_user.bat"
    lines = ["@echo off", "echo Setting FaradaIQ LLM variables in Windows USER environment...", "echo Secret values will be written to your Windows User env.", "echo."]
    def add(k, v):
        if v not in (None, ""):
            vv = str(v).replace('"', '\\"')
            lines.append(f'setx {k} "{vv}"')
    if provider == "AI Incubator":
        add("AI_INCUBATOR_BASE_URL", base_url)
        add("AI_INCUBATOR_MODEL", model)
        add("AI_INCUBATOR_API_KEY", api_key)
    elif provider == "Ollama":
        b = str(base_url or "").rstrip("/")
        host = b[:-3] if b.endswith("/v1") else b
        add("OLLAMA_HOST", host)
        add("OLLAMA_MODEL", model)
        add("OLLAMA_API_KEY", api_key)
    elif provider == "AWS Bedrock via LiteLLM":
        add("LITELLM_BASE_URL", base_url)
        add("LITELLM_MODEL", model)
        add("LITELLM_KEY", api_key)
        add("AWS_PROFILE", aws_profile)
        add("AWS_REGION", aws_region)
        add("AWS_DEFAULT_REGION", aws_region)
        add("AWS_BEDROCK_MODEL_ID", bedrock_model)
    elif provider == "AWS Bedrock direct":
        add("AWS_PROFILE", aws_profile)
        add("AWS_REGION", aws_region)
        add("AWS_DEFAULT_REGION", aws_region)
        add("AWS_BEDROCK_MODEL_ID", bedrock_model or model)
    lines += ["echo.", "echo Done. Close and reopen PowerShell / FaradaIQ before relying on persistent env values.", "pause"]
    bat.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return bat


def _v42_fill_fields_from_env(provider_var, base_var, model_var, key_var, profile_var, region_var, bedrock_var, log=None):
    provider = provider_var.get() or "Auto"
    vals = _v42_provider_defaults(provider)
    base_var.set(vals.get("base_url", ""))
    model_var.set(vals.get("model", ""))
    key_var.set(vals.get("api_key", ""))
    profile_var.set(vals.get("aws_profile", ""))
    region_var.set(vals.get("aws_region", ""))
    bedrock_var.set(vals.get("bedrock_model", ""))
    if log:
        log(f"Loaded {provider} fields from Process/User/Machine environment. API key shown in the field only for editing; it is not printed in logs.")


def _v37_show_llm_settings(self):
    """v42 override: LLM backend editable provider settings with base URL, model, key, ping, and LiteLLM proxy."""
    try:
        win = tk.Toplevel(self)
        win.title("FaradaIQ LLM settings")
        win.geometry("1040x760")
        try:
            p = _v36_theme_palette(getattr(self, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass
        outer = ttk.Frame(win, style="Card.TFrame", padding=(12, 12))
        outer.pack(fill="both", expand=True, padx=10, pady=10)

        ttk.Label(outer, text="LLM settings", style="Section.TLabel").pack(anchor="w")
        ttk.Label(outer, text="Choose AWS, AI Incubator, or Ollama; fill/edit base URL, model name, and API key; then ping before generating AI prompts.", style="Muted.TLabel").pack(anchor="w", pady=(2, 8))

        provider_var = tk.StringVar(value=_FARADAIQ_SELECTED_LLM_PROVIDER or _v40_env_first(["FARADAIQ_LLM_PROVIDER"], "Auto"))
        base_var = tk.StringVar()
        model_var = tk.StringVar()
        key_var = tk.StringVar()
        profile_var = tk.StringVar()
        region_var = tk.StringVar()
        bedrock_var = tk.StringVar()

        form = ttk.LabelFrame(outer, text="Provider configuration", padding=(10, 8))
        form.pack(fill="x", pady=(0, 8))
        for c in [1, 3]:
            form.columnconfigure(c, weight=1)

        providers = ["Auto", "AI Incubator", "Ollama", "AWS Bedrock via LiteLLM", "AWS Bedrock direct"]
        ttk.Label(form, text="Provider", style="Card.TLabel").grid(row=0, column=0, sticky="w", padx=(0, 8), pady=3)
        provider_box = ttk.Combobox(form, textvariable=provider_var, values=providers, state="readonly", width=28)
        provider_box.grid(row=0, column=1, sticky="ew", pady=3)
        ttk.Label(form, text="Model name / alias", style="Card.TLabel").grid(row=0, column=2, sticky="w", padx=(12, 8), pady=3)
        ttk.Entry(form, textvariable=model_var).grid(row=0, column=3, sticky="ew", pady=3)

        ttk.Label(form, text="Base URL", style="Card.TLabel").grid(row=1, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=base_var).grid(row=1, column=1, columnspan=3, sticky="ew", pady=3)

        ttk.Label(form, text="API key", style="Card.TLabel").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=3)
        key_entry = ttk.Entry(form, textvariable=key_var, show="*")
        key_entry.grid(row=2, column=1, sticky="ew", pady=3)
        show_key_var = tk.BooleanVar(value=False)
        def toggle_key():
            key_entry.configure(show="" if show_key_var.get() else "*")
        ttk.Checkbutton(form, text="show", variable=show_key_var, command=toggle_key).grid(row=2, column=2, sticky="w", padx=(12, 8), pady=3)
        ttk.Label(form, text="For Ollama, key can be 'ollama'. For LiteLLM local proxy, default is sk-local.", style="Muted.TLabel").grid(row=2, column=3, sticky="w", pady=3)

        ttk.Label(form, text="AWS profile", style="Card.TLabel").grid(row=3, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=profile_var).grid(row=3, column=1, sticky="ew", pady=3)
        ttk.Label(form, text="AWS region", style="Card.TLabel").grid(row=3, column=2, sticky="w", padx=(12, 8), pady=3)
        ttk.Entry(form, textvariable=region_var).grid(row=3, column=3, sticky="ew", pady=3)

        ttk.Label(form, text="Bedrock model ID", style="Card.TLabel").grid(row=4, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=bedrock_var).grid(row=4, column=1, columnspan=3, sticky="ew", pady=3)

        logbox = ScrolledText(outer, wrap="word", height=22)
        logbox.pack(fill="both", expand=True, pady=(4, 8))
        try:
            logbox.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc")
        except Exception:
            pass
        def log(msg):
            try:
                logbox.configure(state="normal")
                logbox.insert("end", str(msg) + "\n")
                logbox.see("end")
                logbox.configure(state="disabled")
                win.update_idletasks()
            except Exception:
                pass
        def refresh_env_report():
            logbox.configure(state="normal")
            logbox.delete("1.0", "end")
            logbox.insert("1.0", _v40_provider_report_text())
            logbox.configure(state="disabled")
        def load_env():
            _v42_fill_fields_from_env(provider_var, base_var, model_var, key_var, profile_var, region_var, bedrock_var, log=log)
        def apply_session():
            selected = _v42_apply_llm_fields_to_env(provider_var.get(), base_var.get(), model_var.get(), key_var.get(), profile_var.get(), region_var.get(), bedrock_var.get())
            log(f"Applied provider for this FaradaIQ session: {selected}")
            log(f"Base URL: {base_var.get()}")
            log(f"Model: {model_var.get()}")
            log(f"API key: {_v42_mask_for_display(key_var.get()) if key_var.get() else '(empty)'}")
            try:
                self.set_status(f"Selected LLM provider: {selected}")
            except Exception:
                pass
        def ping_selected():
            apply_session()
            cand = _v42_candidate_from_fields(provider_var.get(), base_var.get(), model_var.get(), key_var.get(), profile_var.get(), region_var.get(), bedrock_var.get())
            log(f"Pinging {cand.get('name')}...")
            ok, msg = _v40_ping_provider(cand)
            log(("PING OK: " if ok else "PING FAILED: ") + str(msg))
        def ping_all():
            apply_session()
            for cand in _v40_provider_candidates(include_unavailable=True):
                if cand.get("available"):
                    log(f"Pinging {cand.get('name')}...")
                    ok, msg = _v40_ping_provider(cand)
                else:
                    ok, msg = False, "Missing: " + ", ".join(cand.get("missing", []))
                log(f"{cand.get('name')}: {'OK' if ok else 'FAILED'} - {msg}")
        def save_setx():
            bat = _v42_write_setx_helper(provider_var.get(), base_var.get(), model_var.get(), key_var.get(), profile_var.get(), region_var.get(), bedrock_var.get())
            log(f"Wrote Windows User env helper BAT: {bat}")
            try:
                os.startfile(str(bat.parent))
            except Exception:
                pass
        def start_proxy():
            apply_session()
            paths = _v40_start_litellm_proxy(self)
            log(f"LiteLLM proxy helper written/launched from: {paths['root']}")
        def provider_changed(_event=None):
            load_env()
        provider_box.bind("<<ComboboxSelected>>", provider_changed)
        load_env()
        refresh_env_report()

        btns = ttk.Frame(outer, style="Card.TFrame")
        btns.pack(fill="x")
        ttk.Button(btns, text="Load/fill from Windows env", command=load_env).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Apply for this session", command=apply_session).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Check / ping selected", command=ping_selected).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Ping all available", command=ping_all).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Start AWS LiteLLM proxy", command=start_proxy).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Save setx helper", command=save_setx).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Refresh env report", command=refresh_env_report).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=win.destroy).pack(side="right")
    except Exception as exc:
        messagebox.showerror("LLM settings error", f"{exc}\n\n{traceback.format_exc()}", parent=self)


