# ---- v43 enhancement: proactive LiteLLM proxy install/start checks for AWS provider ----
APP_TITLE = "FaradaIQ Studio v273"

def _v43_is_litellm_proxy_candidate(candidate):
    try:
        return str(candidate.get("name", "")).strip().lower() == "aws bedrock via litellm"
    except Exception:
        return False


def _v43_litellm_proxy_status(candidate=None):
    """Return installed/running status for the local AWS LiteLLM proxy."""
    paths = _v40_litellm_proxy_paths()
    base = None
    key = None
    model = None
    if candidate:
        base = candidate.get("base_url")
        key = candidate.get("api_key")
        model = candidate.get("model")
    base = (base or _v40_env_first(["LITELLM_BASE_URL", "AWS_LITELLM_BASE_URL"], "http://127.0.0.1:4000/v1")).rstrip("/")
    if not base.endswith("/v1"):
        base = base + "/v1"
    key = key or _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY", "AWS_LITELLM_KEY"], "sk-local")
    model = model or _v40_env_first(["LITELLM_MODEL", "AWS_LITELLM_MODEL", "BEDROCK_LITELLM_MODEL"], "faradaiq-bedrock")

    venv_python = paths["venv"] / "Scripts" / "python.exe"
    litellm_exe = paths["venv"] / "Scripts" / "litellm.exe"
    installed = bool(venv_python.exists() and (litellm_exe.exists() or (paths["venv"] / "Lib" / "site-packages").exists()))
    files_written = bool(paths["bat"].exists() and paths["config"].exists() and paths["requirements"].exists())

    running = False
    running_message = ""
    try:
        # A cheap OpenAI-compatible /models request. Some LiteLLM configs may reject it,
        # so a failed request does not always mean install is bad, but connection errors do.
        import urllib.request as _u_req
        req = _u_req.Request(base + "/models", headers={"Authorization": "Bearer " + str(key)})
        with _u_req.urlopen(req, timeout=2) as resp:
            _ = resp.read(4096)
            running = 200 <= getattr(resp, "status", 200) < 500
            running_message = f"/models responded with HTTP {getattr(resp, 'status', 'OK')}"
    except Exception as exc:
        running_message = str(exc)

    return {
        "paths": paths,
        "base_url": base,
        "model": model,
        "key_masked": _v42_mask_for_display(key),
        "installed": installed,
        "files_written": files_written,
        "running": running,
        "running_message": running_message,
        "venv_python": str(venv_python),
        "litellm_exe": str(litellm_exe),
    }


def _v43_ensure_litellm_proxy(parent=None, log=None, candidate=None, start_if_needed=True):
    """Check whether LiteLLM proxy files/env exist and whether the proxy is reachable.

    If missing or not running, write proxy files and open the proxy launcher.
    The launcher installs LiteLLM if needed and starts the proxy.
    """
    def _log(msg):
        try:
            if log:
                log(msg)
            else:
                print(msg, flush=True)
        except Exception:
            pass

    status = _v43_litellm_proxy_status(candidate)
    _log("[LiteLLM] Checking AWS LiteLLM proxy.")
    _log(f"[LiteLLM] URL: {status['base_url']}")
    _log(f"[LiteLLM] Model alias: {status['model']}")
    _log(f"[LiteLLM] Proxy files written: {'yes' if status['files_written'] else 'no'}")
    _log(f"[LiteLLM] LiteLLM environment appears installed: {'yes' if status['installed'] else 'no'}")
    _log(f"[LiteLLM] Proxy reachable: {'yes' if status['running'] else 'no'} ({status['running_message']})")

    if status["running"]:
        return True, "LiteLLM proxy is already running.", status

    if not start_if_needed:
        return False, "LiteLLM proxy is not running.", status

    paths = _v40_write_litellm_proxy_files()
    _log("[LiteLLM] Proxy not reachable or not installed. Starting LiteLLM proxy launcher.")
    _log(f"[LiteLLM] Launch folder: {paths['root']}")
    _log("[LiteLLM] The proxy launcher will install LiteLLM/boto3 if needed, then start the proxy.")
    try:
        os.startfile(str(paths["bat"]))
        msg = (
            "LiteLLM proxy was not reachable, so FaradaIQ opened the proxy installer/start window.\n\n"
            f"Folder:\n{paths['root']}\n\n"
            "Leave that command window open. If this is the first run, it may take a few minutes to install LiteLLM.\n"
            "After the proxy says it is running, click Ping selected again."
        )
        try:
            messagebox.showinfo("AWS LiteLLM proxy started", msg, parent=parent)
        except Exception:
            pass
        return False, "Proxy launcher opened. Wait for installation/startup, then ping again.", status
    except Exception as exc:
        return False, f"Failed to start proxy launcher: {exc}", status


# Override Start AWS LiteLLM proxy to be explicit about install/start checking.
def _v40_start_litellm_proxy(parent=None):
    ok, msg, status = _v43_ensure_litellm_proxy(parent=parent, log=None, candidate=None, start_if_needed=True)
    if ok:
        try:
            messagebox.showinfo("LiteLLM proxy", "AWS LiteLLM proxy is already running.\n\n" + _v43_proxy_status_short(status), parent=parent)
        except Exception:
            pass
    return status.get("paths", _v40_litellm_proxy_paths())


def _v43_proxy_status_short(status):
    return (
        f"URL: {status.get('base_url')}\n"
        f"Model alias: {status.get('model')}\n"
        f"Installed: {'yes' if status.get('installed') else 'no'}\n"
        f"Running: {'yes' if status.get('running') else 'no'}\n"
        f"Details: {status.get('running_message')}"
    )


# Override ping so AWS/LiteLLM automatically checks install/running and opens the proxy launcher if needed.
_V43_PREV_PING_PROVIDER = _v40_ping_provider

def _v40_ping_provider(candidate, max_tokens=20):
    if _v43_is_litellm_proxy_candidate(candidate):
        ok, msg, status = _v43_ensure_litellm_proxy(parent=None, log=None, candidate=candidate, start_if_needed=True)
        if not ok:
            return False, msg + "\n" + _v43_proxy_status_short(status)
        # Proxy is reachable; now do the real LLM ping.
    return _V43_PREV_PING_PROVIDER(candidate, max_tokens=max_tokens)


# Add richer proxy status to the settings report.
_V43_PREV_PROVIDER_REPORT_TEXT = _v40_provider_report_text

def _v40_provider_report_text(ping_results=None):
    txt = _V43_PREV_PROVIDER_REPORT_TEXT(ping_results)
    try:
        status = _v43_litellm_proxy_status()
        txt += (
            "\n\nAWS LiteLLM proxy status:\n"
            f"  URL: {status['base_url']}\n"
            f"  Model alias: {status['model']}\n"
            f"  Config files created: {'yes' if status['files_written'] else 'no'}\n"
            f"  LiteLLM installed: {'yes' if status['installed'] else 'no'}\n"
            f"  Proxy running/reachable: {'yes' if status['running'] else 'no'}\n"
            f"  Detail: {status['running_message']}\n"
            "  If not running, click Start AWS LiteLLM proxy. First install may take a few minutes.\n"
        )
    except Exception:
        pass
    return txt


# Override LLM settings with proxy-check button and clearer AWS behavior while keeping v42 form.
_V43_PREV_SHOW_LLM_SETTINGS = _v37_show_llm_settings

def _v37_show_llm_settings(self):
    """v43: same LLM backend form plus explicit LiteLLM install/running check."""
