# ---- v44 enhancement: Custom Provider LLM provider + model listing on ping ----
APP_TITLE = "FaradaIQ Studio v273"
_CUSTOM_PROVIDER_NAME = "Custom Provider"


def _v44_is_hex_hash_like(text):
    s = str(text or "").strip()
    return bool(re.fullmatch(r"[0-9a-fA-F]{48,}", s))


def _v44_print_and_log(log, msg):
    try:
        print(str(msg), flush=True)
    except Exception:
        pass
    try:
        if log:
            log(str(msg))
    except Exception:
        pass


def _v44_normalize_openai_base(base_url):
    base = str(base_url or "").strip().rstrip("/")
    if not base:
        return ""
    if not base.endswith("/v1"):
        base += "/v1"
    return base


def _v44_list_openai_models(base_url, api_key="", timeout=8):
    """List OpenAI-compatible models from /v1/models. Returns (models, message)."""
    base = _v44_normalize_openai_base(base_url)
    if not base:
        return [], "No base URL provided."
    try:
        import urllib.request as _u_req
        url = base + "/models"
        headers = {}
        if api_key:
            headers["Authorization"] = "Bearer " + str(api_key)
        req = _u_req.Request(url, headers=headers, method="GET")
        with _u_req.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
        try:
            data = json.loads(raw)
        except Exception:
            return [], "Models endpoint returned non-JSON response: " + raw[:800]
        models = []
        if isinstance(data, dict):
            items = data.get("data", [])
            if isinstance(items, list):
                for item in items:
                    if isinstance(item, dict):
                        mid = item.get("id") or item.get("name") or item.get("model")
                        if mid:
                            models.append(str(mid))
                    elif item:
                        models.append(str(item))
            elif isinstance(data.get("models"), list):
                for item in data.get("models"):
                    if isinstance(item, dict):
                        mid = item.get("name") or item.get("model") or item.get("id")
                        if mid:
                            models.append(str(mid))
                    elif item:
                        models.append(str(item))
        models = sorted(set(models))
        return models, f"GET {url} returned {len(models)} model(s)."
    except Exception as exc:
        return [], f"Could not list OpenAI-compatible models from {base}/models: {exc}"


def _v44_list_ollama_models(base_url, timeout=8):
    """Try native Ollama /api/tags as a backup."""
    base = str(base_url or "http://127.0.0.1:11434").strip().rstrip("/")
    host = base[:-3] if base.endswith("/v1") else base
    try:
        data = _v37_read_json_url(host + "/api/tags", timeout=timeout)
        models = []
        for item in data.get("models", []) or []:
            if isinstance(item, dict):
                m = item.get("name") or item.get("model") or item.get("id")
                if m:
                    models.append(str(m))
            elif item:
                models.append(str(item))
        models = sorted(set(models))
        return models, f"GET {host}/api/tags returned {len(models)} model(s)."
    except Exception as exc:
        return [], f"Could not list Ollama models from {host}/api/tags: {exc}"


def _v44_list_models_for_candidate(candidate):
    """Return (models, message) for display/copying."""
    provider = str(candidate.get("name", ""))
    if candidate.get("kind") == "openai":
        models, msg = _v44_list_openai_models(candidate.get("base_url", ""), candidate.get("api_key", ""))
        if models or provider != "Ollama":
            return models, msg
        omodels, omsg = _v44_list_ollama_models(candidate.get("base_url", ""))
        return omodels, msg + "\n" + omsg
    if candidate.get("kind") == "bedrock":
        # Direct Bedrock model listing is intentionally conservative. A real invocation ping follows.
        return [], "AWS Bedrock direct does not use /v1/models. Ping selected performs a real Bedrock invocation."
    return [], "Provider does not support model listing."


_V44_PREV_PROVIDER_DEFAULTS = _v42_provider_defaults

def _v42_provider_defaults(provider):
    provider = str(provider or "Auto")
    if provider == _CUSTOM_PROVIDER_NAME:
        return {
            "base_url": _v40_env_first(["CUSTOM_LLM_BASE_URL", "FARADAIQ_CUSTOM_BASE_URL", "OPENAI_BASE_URL"], "http://127.0.0.1:8000/v1"),
            "model": _v40_env_first(["CUSTOM_LLM_MODEL", "FARADAIQ_CUSTOM_MODEL", "OPENAI_MODEL"], ""),
            "api_key": _v40_env_first(["CUSTOM_LLM_API_KEY", "FARADAIQ_CUSTOM_API_KEY", "OPENAI_API_KEY"], ""),
            "aws_profile": _v40_env_first(["AWS_PROFILE"], ""),
            "aws_region": _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2"),
            "bedrock_model": _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], ""),
        }
    return _V44_PREV_PROVIDER_DEFAULTS(provider)


_V44_PREV_CANDIDATE_FROM_FIELDS = _v42_candidate_from_fields

def _v42_candidate_from_fields(provider, base_url, model, api_key, aws_profile='', aws_region='', bedrock_model=''):
    provider = str(provider or "Auto")
    if provider == _CUSTOM_PROVIDER_NAME:
        return {
            "name": _CUSTOM_PROVIDER_NAME,
            "kind": "openai",
            "base_url": _v44_normalize_openai_base(base_url),
            "model": model,
            "api_key": api_key or "",
            "available": bool(base_url and model),
            "missing": [m for m, ok in [("base URL", bool(base_url)), ("model", bool(model))] if not ok],
            "source": "manual custom provider GUI fields",
        }
    return _V44_PREV_CANDIDATE_FROM_FIELDS(provider, base_url, model, api_key, aws_profile, aws_region, bedrock_model)


_V44_PREV_APPLY_LLM_FIELDS = _v42_apply_llm_fields_to_env

def _v42_apply_llm_fields_to_env(provider, base_url, model, api_key, aws_profile='', aws_region='', bedrock_model=''):
    provider = str(provider or "Auto")
    if provider == _CUSTOM_PROVIDER_NAME:
        global _FARADAIQ_SELECTED_LLM_PROVIDER
        _FARADAIQ_SELECTED_LLM_PROVIDER = provider
        os.environ["FARADAIQ_LLM_PROVIDER"] = provider
        os.environ["CUSTOM_LLM_BASE_URL"] = _v44_normalize_openai_base(base_url)
        os.environ["CUSTOM_LLM_MODEL"] = str(model or "")
        if api_key:
            os.environ["CUSTOM_LLM_API_KEY"] = str(api_key)
        return _FARADAIQ_SELECTED_LLM_PROVIDER
    return _V44_PREV_APPLY_LLM_FIELDS(provider, base_url, model, api_key, aws_profile, aws_region, bedrock_model)


_V44_PREV_WRITE_SETX_HELPER = _v42_write_setx_helper

def _v42_write_setx_helper(provider, base_url, model, api_key, aws_profile='', aws_region='', bedrock_model=''):
    provider = str(provider or "Auto")
    if provider != _CUSTOM_PROVIDER_NAME:
        return _V44_PREV_WRITE_SETX_HELPER(provider, base_url, model, api_key, aws_profile, aws_region, bedrock_model)
    folder = Path(__file__).resolve().parent / "llm_env_helpers"
    folder.mkdir(parents=True, exist_ok=True)
    bat = folder / "set_faradaiq_custom_llm_env_user.bat"
    lines = [
        "@echo off",
        "echo Setting FaradaIQ CUSTOM Provider LLM variables in Windows USER environment...",
        "echo Secret values will be written to your Windows User env.",
        "echo.",
        f'setx CUSTOM_LLM_BASE_URL "{_v44_normalize_openai_base(base_url)}"',
        f'setx CUSTOM_LLM_MODEL "{str(model or "").replace(chr(34), "")}"',
    ]
    if api_key:
        lines.append(f'setx CUSTOM_LLM_API_KEY "{str(api_key).replace(chr(34), "")}"')
    lines += ["echo.", "echo Done. Close and reopen PowerShell / FaradaIQ before relying on persistent env values.", "pause"]
    bat.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return bat


_V44_PREV_PROVIDER_CANDIDATES = _v40_provider_candidates

def _v40_provider_candidates(include_unavailable=True):
    candidates = _V44_PREV_PROVIDER_CANDIDATES(include_unavailable=True)
    base = _v40_env_first(["CUSTOM_LLM_BASE_URL", "FARADAIQ_CUSTOM_BASE_URL", "OPENAI_BASE_URL"], "")
    model = _v40_env_first(["CUSTOM_LLM_MODEL", "FARADAIQ_CUSTOM_MODEL", "OPENAI_MODEL"], "")
    key = _v40_env_first(["CUSTOM_LLM_API_KEY", "FARADAIQ_CUSTOM_API_KEY", "OPENAI_API_KEY"], "")
    custom = {
        "name": _CUSTOM_PROVIDER_NAME,
        "kind": "openai",
        "base_url": _v44_normalize_openai_base(base),
        "api_key": key,
        "model": model,
        "available": bool(base and model),
        "missing": [m for m, ok in [("CUSTOM_LLM_BASE_URL", bool(base)), ("CUSTOM_LLM_MODEL", bool(model))] if not ok],
        "source": "custom provider environment variables",
    }
    candidates.append(custom)
    return candidates if include_unavailable else [c for c in candidates if c.get("available")]


def _v44_bedrock_model_warning_text(bedrock_model):
    if _v44_is_hex_hash_like(bedrock_model):
        return (
            "WARNING: The Bedrock model ID looks like a long hex/hash value. "
            "For AWS Bedrock it should usually look like a provider/model ID, e.g. "
            "anthropic.claude-3-haiku-20240307-v1:0 or an inference-profile ID. "
            "If this is actually an API key or token, move it out of AWS_BEDROCK_MODEL_ID."
        )
    return ""


def _v44_log_models_then_ping(log, candidate):
    _v44_print_and_log(log, f"Provider: {candidate.get('name')}")
    _v44_print_and_log(log, f"Base URL: {candidate.get('base_url', '')}")
    _v44_print_and_log(log, f"Model selected: {candidate.get('model', '')}")

    warn = _v44_bedrock_model_warning_text(candidate.get("model", ""))
    if warn:
        _v44_print_and_log(log, warn)

    if _v43_is_litellm_proxy_candidate(candidate):
        _v44_print_and_log(log, "AWS/LiteLLM note: /models checks the local proxy only; the chat ping below triggers a real AWS Bedrock model invocation through the proxy.")

    models, msg = _v44_list_models_for_candidate(candidate)
    _v44_print_and_log(log, "Model-list check:")
    _v44_print_and_log(log, msg)
    if models:
        _v44_print_and_log(log, "Available models:")
        for m in models:
            _v44_print_and_log(log, f"  - {m}")
    else:
        _v44_print_and_log(log, "No model list was returned. This can be normal for some AWS/direct providers, but the ping will still test invocation.")

    _v44_print_and_log(log, "Running real ping/invocation test...")
    ok, ping_msg = _v40_ping_provider(candidate)
    _v44_print_and_log(log, ("PING OK: " if ok else "PING FAILED: ") + str(ping_msg))
    return ok, ping_msg, models


# Replace v42 settings window so the provider menu includes Custom and ping lists models in the copyable terminal.
def _v37_show_llm_settings(self):
    """v44: LLM backend editable provider settings + Custom Provider provider + model listing."""
    try:
        win = tk.Toplevel(self)
        win.title("FaradaIQ LLM settings")
        win.geometry("1080x790")
        try:
            p = _v36_theme_palette(getattr(self, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass
        outer = ttk.Frame(win, style="Card.TFrame", padding=(12, 12))
        outer.pack(fill="both", expand=True, padx=10, pady=10)

        ttk.Label(outer, text="LLM settings", style="Section.TLabel").pack(anchor="w")
        ttk.Label(
            outer,
            text="Choose AWS, AI Incubator, Ollama, or a Custom Provider endpoint; fill/edit base URL, model name, and API key; then ping.",
            style="Muted.TLabel",
        ).pack(anchor="w", pady=(2, 8))

        provider_var = tk.StringVar(value=_FARADAIQ_SELECTED_LLM_PROVIDER or _v40_env_first(["FARADAIQ_LLM_PROVIDER"], "Auto"))
        if provider_var.get() not in ["Auto", "AI Incubator", "Ollama", "AWS Bedrock via LiteLLM", "AWS Bedrock direct", _CUSTOM_PROVIDER_NAME]:
            provider_var.set("Auto")
        base_var = tk.StringVar()
        model_var = tk.StringVar()
        key_var = tk.StringVar()
        profile_var = tk.StringVar()
        region_var = tk.StringVar()
        bedrock_var = tk.StringVar()

        form = ttk.LabelFrame(outer, text="Provider configuration", padding=(10, 8))
        form.pack(fill="x", pady=(0, 8))
        for c in [1, 3]:
            form.columnconfigure(c, weight=1)

        providers = ["Auto", "AI Incubator", "Ollama", "AWS Bedrock via LiteLLM", "AWS Bedrock direct", _CUSTOM_PROVIDER_NAME]
        ttk.Label(form, text="Provider", style="Card.TLabel").grid(row=0, column=0, sticky="w", padx=(0, 8), pady=3)
        provider_box = ttk.Combobox(form, textvariable=provider_var, values=providers, state="readonly", width=32)
        provider_box.grid(row=0, column=1, sticky="ew", pady=3)
        ttk.Label(form, text="Model name / alias", style="Card.TLabel").grid(row=0, column=2, sticky="w", padx=(12, 8), pady=3)
        ttk.Entry(form, textvariable=model_var).grid(row=0, column=3, sticky="ew", pady=3)

        ttk.Label(form, text="Base URL", style="Card.TLabel").grid(row=1, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=base_var).grid(row=1, column=1, columnspan=3, sticky="ew", pady=3)

        ttk.Label(form, text="API key", style="Card.TLabel").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=3)
        key_entry = ttk.Entry(form, textvariable=key_var, show="*")
        key_entry.grid(row=2, column=1, sticky="ew", pady=3)
        show_key_var = tk.BooleanVar(value=False)
        def toggle_key():
            key_entry.configure(show="" if show_key_var.get() else "*")
        ttk.Checkbutton(form, text="show", variable=show_key_var, command=toggle_key).grid(row=2, column=2, sticky="w", padx=(12, 8), pady=3)
        ttk.Label(form, text="Custom uses OpenAI-compatible /v1/chat/completions and /v1/models.", style="Muted.TLabel").grid(row=2, column=3, sticky="w", pady=3)

        ttk.Label(form, text="AWS profile", style="Card.TLabel").grid(row=3, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=profile_var).grid(row=3, column=1, sticky="ew", pady=3)
        ttk.Label(form, text="AWS region", style="Card.TLabel").grid(row=3, column=2, sticky="w", padx=(12, 8), pady=3)
        ttk.Entry(form, textvariable=region_var).grid(row=3, column=3, sticky="ew", pady=3)

        ttk.Label(form, text="Bedrock model ID", style="Card.TLabel").grid(row=4, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=bedrock_var).grid(row=4, column=1, columnspan=3, sticky="ew", pady=3)

        logbox = ScrolledText(outer, wrap="word", height=24)
        logbox.pack(fill="both", expand=True, pady=(4, 8))
        try:
            logbox.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc")
        except Exception:
            pass

        def log(msg):
            try:
                logbox.configure(state="normal")
                logbox.insert("end", str(msg) + "\n")
                logbox.see("end")
                logbox.configure(state="disabled")
                win.update_idletasks()
            except Exception:
                pass
            try:
                print(str(msg), flush=True)
            except Exception:
                pass

        def refresh_env_report():
            logbox.configure(state="normal")
            logbox.delete("1.0", "end")
            logbox.insert("1.0", _v40_provider_report_text())
            logbox.configure(state="disabled")

        def load_env():
            _v42_fill_fields_from_env(provider_var, base_var, model_var, key_var, profile_var, region_var, bedrock_var, log=log)
            warn = _v44_bedrock_model_warning_text(bedrock_var.get() or model_var.get())
            if warn and provider_var.get() in {"AWS Bedrock via LiteLLM", "AWS Bedrock direct"}:
                log(warn)

        def apply_session():
            selected = _v42_apply_llm_fields_to_env(provider_var.get(), base_var.get(), model_var.get(), key_var.get(), profile_var.get(), region_var.get(), bedrock_var.get())
            log(f"Applied provider for this FaradaIQ session: {selected}")
            log(f"Base URL: {base_var.get()}")
            log(f"Model: {model_var.get()}")
            log(f"API key: {_v42_mask_for_display(key_var.get()) if key_var.get() else '(empty)'}")
            try:
                self.set_status(f"Selected LLM provider: {selected}")
            except Exception:
                pass

        def current_candidate():
            return _v42_candidate_from_fields(provider_var.get(), base_var.get(), model_var.get(), key_var.get(), profile_var.get(), region_var.get(), bedrock_var.get())

        def list_models_only():
            apply_session()
            cand = current_candidate()
            models, msg = _v44_list_models_for_candidate(cand)
            log("Model-list check:")
            log(msg)
            if models:
                log("Available models:")
                for m in models:
                    log(f"  - {m}")
            else:
                log("No models listed.")

        def ping_selected():
            apply_session()
            cand = current_candidate()
            _v44_log_models_then_ping(log, cand)

        def ping_all():
            apply_session()
            for cand in _v40_provider_candidates(include_unavailable=True):
                if cand.get("available"):
                    log("=" * 72)
                    _v44_log_models_then_ping(log, cand)
                else:
                    log("=" * 72)
                    log(f"{cand.get('name')}: not configured. Missing: {', '.join(cand.get('missing', []))}")

        def save_setx():
            bat = _v42_write_setx_helper(provider_var.get(), base_var.get(), model_var.get(), key_var.get(), profile_var.get(), region_var.get(), bedrock_var.get())
            log(f"Wrote Windows User env helper BAT: {bat}")
            try:
                os.startfile(str(bat.parent))
            except Exception:
                pass

        def start_proxy():
            apply_session()
            cand = current_candidate()
            ok, msg, status = _v43_ensure_litellm_proxy(parent=self, log=log, candidate=cand, start_if_needed=True)
            log(("LiteLLM proxy OK: " if ok else "LiteLLM proxy not ready: ") + msg)
            log(_v43_proxy_status_short(status))

        def provider_changed(_event=None):
            load_env()

        provider_box.bind("<<ComboboxSelected>>", provider_changed)
        load_env()
        refresh_env_report()

        btns = ttk.Frame(outer, style="Card.TFrame")
        btns.pack(fill="x")
        ttk.Button(btns, text="Load/fill from Windows env", command=load_env).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Apply", command=apply_session).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="List models", command=list_models_only).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Ping selected", command=ping_selected).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Ping all", command=ping_all).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Start/check AWS LiteLLM proxy", command=start_proxy).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Save setx helper", command=save_setx).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Refresh env report", command=refresh_env_report).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=win.destroy).pack(side="right")
    except Exception as exc:
        messagebox.showerror("LLM settings error", f"{exc}\n\n{traceback.format_exc()}", parent=self)


def _v44_main():
    _v43_main()

# ---- End v44 enhancement ----



# ---- v45 enhancement: declutter AI toolbar, LLM-generated prompt button, large icon About dialog ----
APP_TITLE = "FaradaIQ Studio v273"


def _v45_widget_text(widget):
    try:
        return str(widget.cget("text"))
    except Exception:
        return ""


def _v45_destroy_matching_widgets(root, exact=None, contains=None):
    exact = set(exact or [])
    contains = list(contains or [])
    try:
        children = list(root.winfo_children())
    except Exception:
        return
    for child in children:
        _v45_destroy_matching_widgets(child, exact=exact, contains=contains)
        txt = _v45_widget_text(child)
        try:
            if txt in exact or any(s in txt for s in contains):
                child.destroy()
        except Exception:
            pass


def _v45_file_tree_for_prompt(gui, max_lines=240):
    lines = []
    roots = []
    try:
        base_name = _v27_current_base_name(gui)
        out = Path(gui.output_dir_var.get().strip() or ".").resolve()
        safe = _v35_safe_name(base_name)
        for p in [out / f"{base_name}_analysis_ready_csv", out / f"{safe}_analysis_ready_csv", out]:
            if p.exists() and p not in roots:
                roots.append(p)
    except Exception:
        pass
    try:
        src = Path(gui.collection.source_path)
        if src.exists() and src not in roots:
            roots.append(src if src.is_dir() else src.parent)
    except Exception:
        pass

    shown = 0
    for root in roots:
        if shown >= max_lines:
            break
        try:
            lines.append(f"[ROOT] {root}")
            shown += 1
            if root.is_file():
                continue
            for p in sorted(root.rglob("*"), key=lambda x: str(x).lower()):
                if shown >= max_lines:
                    lines.append("... file tree truncated ...")
                    return "\n".join(lines)
                try:
                    rel = p.relative_to(root)
                    if any(part in {".git", "__pycache__", ".faradaiq_venv", ".deareis_venv", ".faradaiq_litellm_venv"} for part in rel.parts):
                        continue
                    if p.is_file():
                        size = p.stat().st_size
                        lines.append(f"  FILE {rel.as_posix()}  ({size} bytes)")
                        shown += 1
                    elif len(rel.parts) <= 4:
                        lines.append(f"  DIR  {rel.as_posix()}/")
                        shown += 1
                except Exception:
                    pass
        except Exception:
            pass
    return "\n".join(lines[:max_lines]) if lines else "(No file tree available yet. Export first for full AI bundle file structure.)"


def _v45_current_gui_text(widget, max_chars=50000):
    try:
        text = widget.get("1.0", "end").strip()
        return text[:max_chars] + ("\n...[truncated]..." if len(text) > max_chars else "")
    except Exception:
        return ""


def _v45_generate_ai_prompt_with_llm(gui):
    """Use selected/available LLM to create a scientific prompt and append to Experimental description."""
    win, log = _v41_analysis_progress_window(gui, "Generate AI prompt with LLM")
    try:
        if not getattr(gui, "collection", None) or not getattr(gui.collection, "entries", []):
            messagebox.showwarning("No session loaded", "Load and inspect data first, then generate the LLM scientific prompt.", parent=gui)
            return
        log("[LLM prompt] Gathering session summary, experimental description, and file structure...")
        experiment = _v45_current_gui_text(gui.desc_text)
        summary = _v45_current_gui_text(gui.summary_text)
        structure = _v45_current_gui_text(gui.structure_text)
        tree = _v45_file_tree_for_prompt(gui)

        messages = [
            {
                "role": "system",
                "content": (
                    "You are an expert electrochemist and scientific data-analysis strategist. "
                    "Your task is to write a rigorous AI-analysis prompt, not to analyze the data yet. "
                    "The prompt must guide a downstream LLM or scientific analyst to interrogate CV, EIS, DRT, SECCM, "
                    "and instrument-parsed files with strong scientific discipline, clear uncertainty handling, and no invented conclusions."
                ),
            },
            {
                "role": "user",
                "content": (
                    "Create a publication-quality scientific analysis prompt for the dataset below. "
                    "The prompt should be appended to an experimental description box and later sent with the AI bundle. "
                    "Make it specific to the available session summary, data structure, and file tree.\n\n"
                    "Required sections in the generated prompt:\n"
                    "1. LLM-generated scientific analysis prompt\n"
                    "2. Scientific questions to answer\n"
                    "3. Data integrity and parsing checks\n"
                    "4. CV/EIS/DRT/SECCM analysis tasks as applicable\n"
                    "5. Expected quantitative outputs, figures, and tables\n"
                    "6. Interpretation constraints: separate observation from inference; flag missing metadata; do not fabricate results.\n\n"
                    "Return only the prompt text to append. Do not include JSON.\n\n"
                    "EXPERIMENTAL DESCRIPTION CURRENT TEXT:\n"
                    f"{experiment}\n\n"
                    "SESSION SUMMARY:\n"
                    f"{summary}\n\n"
                    "DATA STRUCTURE PREVIEW:\n"
                    f"{structure}\n\n"
                    "FILE STRUCTURE / EXPORTED OUTPUT TREE:\n"
                    f"{tree}\n"
                ),
            },
        ]
        log("[LLM prompt] Calling selected/available LLM backend...")
        response, provider = _v37_call_best_llm(messages, max_tokens=2800, temperature=0.15)
        provider_name = provider.get("name", "LLM") if isinstance(provider, dict) else "LLM"
        log(f"[LLM prompt] Response received from: {provider_name}")
        response = str(response or "").strip()
        if not response:
            raise RuntimeError("LLM returned an empty response.")
        timestamp = datetime.now().isoformat(timespec="seconds")
        block = (
            "\n\n"
            "==================== LLM-GENERATED AI ANALYSIS PROMPT ====================\n"
            f"Generated: {timestamp}\n"
            f"Provider: {provider_name}\n\n"
            f"{response}\n"
            "================== END LLM-GENERATED AI ANALYSIS PROMPT ==================\n"
        )
        gui.desc_text.insert("end", block)
        gui.desc_text.see("end")
        try:
            base_name = _v27_current_base_name(gui)
            analysis_root = _v35_analysis_root_for_export(gui, base_name=base_name)
            if analysis_root.exists():
                (analysis_root / "AI_prompt_current.txt").write_text(gui.desc_text.get("1.0", "end").strip(), encoding="utf-8")
                log(f"[LLM prompt] Saved prompt copy to: {analysis_root / 'AI_prompt_current.txt'}")
        except Exception:
            pass
        gui.set_status("LLM-generated scientific prompt appended to Experimental description.")
        log("[LLM prompt] Done. Prompt appended to Experimental description.")
    except Exception as exc:
        log(f"[LLM prompt] FAILED: {exc}")
        messagebox.showerror("LLM prompt generation failed", f"{exc}\n\nOpen LLM settings, select a provider, and use Ping selected before trying again.", parent=gui)


