APP_TITLE = "FaradaIQ Studio v273"
_FARADAIQ_DEFAULT_AWS_PROFILE = "BirthrightUser-143924590130"


def _v49_log(log, msg):
    msg = str(msg)
    try:
        print(msg, flush=True)
    except Exception:
        pass
    try:
        if log:
            log(msg)
    except Exception:
        pass


def _v49_wait_openai_models(base_url, api_key, timeout_seconds=60, log=None):
    import time as _time
    base = _v44_normalize_openai_base(base_url)
    api_key = api_key or "sk-local"
    last = ""
    for i in range(int(timeout_seconds)):
        models, msg = _v44_list_openai_models(base, api_key, timeout=3)
        if models or "returned 0 model" in msg:
            return True, models, msg
        last = msg
        if i in {0, 4, 9, 19, 39}:
            _v49_log(log, f"[LiteLLM] waiting for /models... {i+1}/{timeout_seconds} ({last})")
        _time.sleep(1)
    return False, [], last or "Timed out waiting for /models."


def _v49_select_litellm_model(candidate, models, log=None):
    requested = str(candidate.get("model") or "").strip()
    if requested and requested in models:
        return requested
    preferred = []
    if requested:
        preferred.append(requested)
    preferred += ["faradaiq-bedrock", _v40_env_first(["LITELLM_MODEL"], ""), "faradaiq-bedrock-haiku", "bedrock"]
    for p in preferred:
        if p and p in models:
            if requested and requested != p:
                _v49_log(log, f"[LiteLLM] Requested model alias '{requested}' is not in /models. Using available LiteLLM alias '{p}'.")
            return p
    if models:
        chosen = models[0]
        if requested != chosen:
            _v49_log(log, f"[LiteLLM] Requested model alias '{requested}' is not in /models. Using first available alias '{chosen}'.")
        return chosen
    return requested


def _v49_write_aws_refresh_retry_bat(candidate=None):
    """Write a LLM backend AWS SSO refresh + proxy restart + real chat-test BAT."""
    candidate = candidate or {}
    paths = _v40_write_litellm_proxy_files()
    root = paths["root"]
    refresh_bat = root / "run_aws_sso_refresh_restart_and_test.bat"

    base = _v44_normalize_openai_base(candidate.get("base_url") or _v40_env_first(["LITELLM_BASE_URL"], "http://127.0.0.1:4000/v1"))
    key = candidate.get("api_key") or _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY"], "sk-local")
    model = candidate.get("model") or _v40_env_first(["LITELLM_MODEL"], "faradaiq-bedrock")
    profile = _v40_env_first(["AWS_PROFILE"], _FARADAIQ_DEFAULT_AWS_PROFILE)
    region = _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2")
    bedrock_model = _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "anthropic.claude-3-haiku-20240307-v1:0")
    port = "4000"
    try:
        m = re.search(r":(\d+)/v1$", base)
        if m:
            port = m.group(1)
    except Exception:
        pass

    bat = f"""@echo off
setlocal EnableExtensions EnableDelayedExpansion
cd /d "%~dp0"

title FaradaIQ AWS SSO refresh + LiteLLM restart + test

set "AWS_PROFILE={profile}"
set "AWS_REGION={region}"
set "AWS_DEFAULT_REGION={region}"
set "AWS_BEDROCK_MODEL_ID={bedrock_model}"
set "LITELLM_BASE_URL={base}"
set "LITELLM_KEY={key}"
set "LITELLM_MODEL={model}"
set "LITELLM_PORT={port}"

echo ============================================================
echo FaradaIQ AWS SSO refresh + LiteLLM restart + selected-model test
echo ============================================================
echo AWS profile:            %AWS_PROFILE%
echo AWS region:             %AWS_REGION%
echo Bedrock model/profile:  %AWS_BEDROCK_MODEL_ID%
echo LiteLLM URL:            %LITELLM_BASE_URL%
echo LiteLLM model alias:    %LITELLM_MODEL%
echo.
echo This is the real AWS check. The LiteLLM server can start even when
echo AWS SSO is expired or the Bedrock model is inaccessible. The chat
echo completion test below confirms the AWS invocation.
echo.

where aws >nul 2>nul
if errorlevel 1 (
  echo [ERROR] AWS CLI not found. Install AWS CLI and rerun.
  pause
  exit /b 1
)

echo Checking AWS identity...
aws sts get-caller-identity --profile "%AWS_PROFILE%"
if errorlevel 1 (
  echo.
  echo [WARN] AWS identity check failed. Running AWS SSO login now.
  aws sso login --profile "%AWS_PROFILE%"
  if errorlevel 1 (
    echo [ERROR] AWS SSO login failed.
    pause
    exit /b 1
  )
) else (
  echo [OK] AWS identity check succeeded.
  choice /C YN /M "Run aws sso login anyway to refresh token"
  if not errorlevel 2 aws sso login --profile "%AWS_PROFILE%"
)

echo.
echo Stopping any existing LiteLLM process on port %LITELLM_PORT%...
powershell -NoProfile -ExecutionPolicy Bypass -Command "$pids=Get-NetTCPConnection -LocalPort $env:LITELLM_PORT -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess -Unique; foreach($pid in $pids){{try{{Stop-Process -Id $pid -Force -ErrorAction SilentlyContinue; Write-Host ('Stopped PID ' + $pid)}}catch{{}}}}"
timeout /t 2 /nobreak >nul

echo Starting LiteLLM proxy in a separate window...
start "FaradaIQ LiteLLM Proxy" "%CD%\\start_faradaiq_litellm_proxy.bat"

echo Waiting for LiteLLM /models...
powershell -NoProfile -ExecutionPolicy Bypass -Command "$u=$env:LITELLM_BASE_URL.TrimEnd('/') + '/models'; $h=@{{Authorization='Bearer '+$env:LITELLM_KEY}}; for($i=0;$i -lt 75;$i++){{try{{$r=Invoke-RestMethod -Uri $u -Headers $h -TimeoutSec 2; Write-Host '[OK] /models responded'; if($r.data){{$r.data | ForEach-Object {{Write-Host ('  - ' + $_.id)}}}}; exit 0}}catch{{Start-Sleep -Seconds 1}}}}; Write-Host '[ERROR] timed out waiting for LiteLLM /models'; exit 1"
if errorlevel 1 (
  echo [ERROR] LiteLLM proxy did not become ready.
  pause
  exit /b 1
)

echo.
echo Running real selected-model chat completion test...
powershell -NoProfile -ExecutionPolicy Bypass -Command "$body=@{{model=$env:LITELLM_MODEL; messages=@(@{{role='user'; content='Say exactly: FaradaIQ AWS Bedrock ping OK.'}}); max_tokens=80}} | ConvertTo-Json -Depth 8; try{{$r=Invoke-RestMethod -Uri ($env:LITELLM_BASE_URL.TrimEnd('/') + '/chat/completions') -Method Post -Headers @{{Authorization=('Bearer '+$env:LITELLM_KEY)}} -ContentType 'application/json' -Body $body -TimeoutSec 120; Write-Host '[OK] Chat completion succeeded:'; Write-Host $r.choices[0].message.content; exit 0}}catch{{Write-Host '[ERROR] Chat completion failed.'; Write-Host $_.Exception.Message; if($_.ErrorDetails.Message){{Write-Host $_.ErrorDetails.Message}}; exit 1}}"
if errorlevel 1 (
  echo.
  echo [ERROR] Real AWS Bedrock invocation still failed.
  echo Check: Bedrock model access, inference profile ID, SCP restrictions, and region.
) else (
  echo.
  echo [OK] FaradaIQ AWS/LiteLLM real ping succeeded.
)
pause
"""
    refresh_bat.write_text(bat, encoding="utf-8")
    return refresh_bat


def _v49_ping_aws_litellm(candidate, log=None, auto_open_refresh=True):
    """Real AWS/LiteLLM check: /models then /chat/completions, with SSO refresh helper on failure."""
    base = _v44_normalize_openai_base(candidate.get("base_url") or _v40_env_first(["LITELLM_BASE_URL"], "http://127.0.0.1:4000/v1"))
    key = candidate.get("api_key") or _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY"], "sk-local")
    requested_model = candidate.get("model") or _v40_env_first(["LITELLM_MODEL"], "faradaiq-bedrock")
    candidate["base_url"] = base
    candidate["api_key"] = key
    candidate["model"] = requested_model

    _v49_log(log, "[LiteLLM/AWS] Checking local LiteLLM proxy /models...")
    ok_models, models, msg = _v49_wait_openai_models(base, key, timeout_seconds=15, log=log)
    if not ok_models:
        _v49_log(log, "[LiteLLM/AWS] Proxy not reachable. Starting proxy launcher...")
        _v43_ensure_litellm_proxy(parent=None, log=log, candidate=candidate, start_if_needed=True)
        ok_models, models, msg = _v49_wait_openai_models(base, key, timeout_seconds=75, log=log)

    _v49_log(log, "[LiteLLM/AWS] Model-list check:")
    _v49_log(log, msg)
    if models:
        _v49_log(log, "[LiteLLM/AWS] Models exposed by local LiteLLM proxy:")
        for m in models:
            _v49_log(log, f"  - {m}")
    else:
        _v49_log(log, "[LiteLLM/AWS] No models returned from /models.")

    if not ok_models:
        return False, "LiteLLM proxy is not reachable after waiting. Start the proxy BAT and retry."

    selected_model = _v49_select_litellm_model(candidate, models, log=log)
    candidate["model"] = selected_model
    os.environ["LITELLM_BASE_URL"] = base
    os.environ["LITELLM_KEY"] = key
    os.environ["LITELLM_MODEL"] = selected_model

    _v49_log(log, f"[LiteLLM/AWS] Running real chat-completion ping through proxy with model alias: {selected_model}")
    try:
        out = _v37_openai_chat(
            base,
            key,
            selected_model,
            [
                {"role": "system", "content": "You are a connection test. Reply with exactly FARADAIQ_AWS_PING_OK."},
                {"role": "user", "content": "Ping AWS Bedrock through LiteLLM."},
            ],
            max_tokens=40,
            temperature=0.0,
        )
        out = (out or "").strip()
        _v49_log(log, "[LiteLLM/AWS] REAL AWS CHAT PING OK: " + out)
        return True, out
    except Exception as exc:
        err = str(exc)
        _v49_log(log, "[LiteLLM/AWS] REAL AWS CHAT PING FAILED:")
        _v49_log(log, err)
        if auto_open_refresh:
            try:
                refresh_bat = _v49_write_aws_refresh_retry_bat(candidate)
                _v49_log(log, f"[LiteLLM/AWS] Opening AWS SSO refresh + proxy restart + retry BAT:\n{refresh_bat}")
                os.startfile(str(refresh_bat))
                return False, "Chat ping failed. Opened AWS SSO refresh + LiteLLM restart + retry BAT. Complete that window, then ping again."
            except Exception as exc2:
                return False, f"Chat ping failed and refresh BAT could not be opened: {exc2}\nOriginal error: {err}"
        return False, err


_V49_PREV_PING_PROVIDER = _v40_ping_provider

def _v40_ping_provider(candidate, max_tokens=20):
    if _v43_is_litellm_proxy_candidate(candidate):
        return _v49_ping_aws_litellm(candidate, log=None, auto_open_refresh=True)
    return _V49_PREV_PING_PROVIDER(candidate, max_tokens=max_tokens)


_V49_PREV_LOG_MODELS_THEN_PING = _v44_log_models_then_ping

def _v44_log_models_then_ping(log, candidate):
    if _v43_is_litellm_proxy_candidate(candidate):
        _v49_log(log, "=" * 72)
        _v49_log(log, "AWS Bedrock via LiteLLM selected.")
        _v49_log(log, "This will test BOTH the local proxy and the real AWS Bedrock chat invocation.")
        ok, msg = _v49_ping_aws_litellm(candidate, log=log, auto_open_refresh=True)
        _v49_log(log, ("PING OK: " if ok else "PING FAILED: ") + str(msg))
        return ok, msg, []
    return _V49_PREV_LOG_MODELS_THEN_PING(log, candidate)


def _v47_llm_setup_wizard_path():
    root = Path(__file__).resolve().parent
    for name in ["run_faradaiq_llm_setup_wizard.bat"]:
        p = root / name
        if p.exists():
            return p
    return root / "run_faradaiq_llm_setup_wizard.bat"


