# ---- v50 enhancement: update Data structure preview with parsed-output tree after parser runs ----
APP_TITLE = "FaradaIQ Studio v273"
_V50_PARSED_BLOCK_BEGIN = "==================== FARADAIQ PARSED OUTPUT STRUCTURE BEGIN ===================="
_V50_PARSED_BLOCK_END = "===================== FARADAIQ PARSED OUTPUT STRUCTURE END ====================="


def _v50_format_bytes(n):
    try:
        n = float(n)
        for unit in ["B", "KB", "MB", "GB", "TB"]:
            if n < 1024 or unit == "TB":
                return f"{n:.0f} {unit}" if unit == "B" else f"{n:.2f} {unit}"
            n /= 1024.0
    except Exception:
        return ""


def _v50_should_skip_tree_part(part):
    p = str(part).lower()
    return p in {
        "__pycache__", ".git", ".svn", ".hg",
        ".faradaiq_venv", ".deareis_venv", ".echem_bridge_venv", ".bridge_heka_venv",
        ".faradaiq_litellm_venv", ".venv", "site-packages",
    }


def _v50_analysis_roots_for_gui(gui, base_name=None):
    roots = []
    try:
        base_name = base_name or _v27_current_base_name(gui)
    except Exception:
        base_name = base_name or "session"
    try:
        analysis_root = _v35_analysis_root_for_export(gui, base_name=base_name)
        if analysis_root.exists() and analysis_root.is_dir():
            roots.append(Path(analysis_root).resolve())
    except Exception:
        analysis_root = None
    try:
        out = Path(gui.output_dir_var.get().strip() or ".").resolve()
        safe = _v35_safe_name(base_name)
        candidates = [
            out / f"{base_name}_analysis_ready_csv",
            out / f"{safe}_analysis_ready_csv",
            out / f"{base_name}_for_plotting_analysis",
            out / f"{safe}_for_plotting_analysis",
            out / "DRT_input_csv",
            out / "DRT_input_csv_all",
        ]
        for p in candidates:
            if p.exists() and p.is_dir():
                rp = p.resolve()
                if rp not in roots:
                    roots.append(rp)
    except Exception:
        pass
    return roots


def _v50_collect_parsed_output_tree(gui, base_name=None, max_lines=2500):
    """Build a file/folder tree of exported/parsed outputs for the Data structure preview."""
    try:
        base_name = base_name or _v27_current_base_name(gui)
    except Exception:
        base_name = base_name or "session"
    safe = _v35_safe_name(base_name)
    roots = _v50_analysis_roots_for_gui(gui, base_name=base_name)
    out_dir = Path(gui.output_dir_var.get().strip() or ".").resolve()
    timestamp = datetime.now().isoformat(timespec="seconds")

    lines = [
        _V50_PARSED_BLOCK_BEGIN,
        f"Updated: {timestamp}",
        f"Base/session: {base_name}",
        "Purpose: live file/folder map of data generated after export and parser runs.",
        "",
    ]
    manifest = {
        "schema": "faradaiq-parsed-output-structure-v1",
        "created": timestamp,
        "base_name": base_name,
        "output_dir": str(out_dir),
        "roots": [],
        "sibling_files": [],
    }

    if not roots:
        lines += [
            "No analysis-ready output folder found yet.",
            "Export first, or run parsers after export, then refresh/monitor again.",
            _V50_PARSED_BLOCK_END,
        ]
        return "\n".join(lines), manifest

    total_files = 0
    total_dirs = 0
    shown_lines = 0
    truncated = False

    for root in roots:
        lines.append(f"[ROOT] {root}")
        root_entry = {"root": str(root), "files": [], "dirs": []}
        try:
            items = sorted(root.rglob("*"), key=lambda p: (p.is_file(), str(p).lower()))
        except Exception:
            items = []
        for p in items:
            if shown_lines >= max_lines:
                truncated = True
                break
            try:
                rel = p.relative_to(root)
                if any(_v50_should_skip_tree_part(part) for part in rel.parts):
                    continue
                depth = len(rel.parts) - 1
                indent = "  " + ("  " * min(depth, 10))
                if p.is_dir():
                    total_dirs += 1
                    line = f"{indent}DIR  {rel.as_posix()}/"
                    root_entry["dirs"].append(rel.as_posix() + "/")
                elif p.is_file():
                    total_files += 1
                    st = p.stat()
                    mtime = datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds")
                    line = f"{indent}FILE {rel.as_posix()}  ({_v50_format_bytes(st.st_size)}, modified {mtime})"
                    root_entry["files"].append({
                        "relative_path": rel.as_posix(),
                        "size_bytes": int(st.st_size),
                        "modified_time": mtime,
                    })
                else:
                    continue
                lines.append(line)
                shown_lines += 1
            except Exception:
                pass
        manifest["roots"].append(root_entry)
        lines.append("")
        if truncated:
            break

    # Include raw/export sibling files next to analysis_ready_csv.
    try:
        lines.append("[RAW/EXPORT SIBLINGS]")
        sibling_patterns = [
            f"{base_name}*.npy", f"{safe}*.npy",
            f"{base_name}*.json", f"{safe}*.json",
            f"{base_name}*.zip", f"{safe}*.zip",
            f"{base_name}*.h5", f"{safe}*.h5",
            f"{base_name}*.hdf5", f"{safe}*.hdf5",
        ]
        sibling_seen = set()
        for pat in sibling_patterns:
            for p in sorted(out_dir.glob(pat), key=lambda x: str(x).lower()):
                if shown_lines >= max_lines:
                    truncated = True
                    break
                try:
                    if not p.is_file():
                        continue
                    if p.resolve() in sibling_seen:
                        continue
                    sibling_seen.add(p.resolve())
                    st = p.stat()
                    mtime = datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds")
                    lines.append(f"  FILE {p.name}  ({_v50_format_bytes(st.st_size)}, modified {mtime})")
                    manifest["sibling_files"].append({
                        "path": str(p),
                        "name": p.name,
                        "size_bytes": int(st.st_size),
                        "modified_time": mtime,
                    })
                    shown_lines += 1
                except Exception:
                    pass
    except Exception:
        pass

    lines += [
        "",
        f"Summary: {total_dirs} folders and {total_files} files found under parsed-output roots.",
    ]
    if truncated:
        lines.append(f"Preview truncated after {max_lines} lines. Full tree is saved to disk when an analysis-ready folder is available.")
        manifest["truncated"] = True
        manifest["max_lines"] = max_lines
    else:
        manifest["truncated"] = False
    lines.append(_V50_PARSED_BLOCK_END)

    # Save full-ish structure report beside AI bundle for reproducibility.
    try:
        primary = roots[0]
        report_path = primary / f"{safe}_parsed_output_structure_tree.txt"
        json_path = primary / f"{safe}_parsed_output_structure_tree.json"
        report_path.write_text("\n".join(lines), encoding="utf-8")
        json_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
        manifest["report_path"] = str(report_path)
        manifest["json_path"] = str(json_path)
    except Exception:
        pass

    return "\n".join(lines), manifest


def _v50_update_structure_preview_with_parsed_outputs(gui, base_name=None, force=False):
    """Append/refresh parsed-output file tree in the Data structure preview pane."""
    try:
        var = getattr(gui, "append_parsed_structure_after_parser_var", None)
        if not force and var is not None and not bool(var.get()):
            return False
        report, manifest = _v50_collect_parsed_output_tree(gui, base_name=base_name)
        current = gui.structure_text.get("1.0", "end").rstrip()
        # Remove previous parsed-output block to avoid repeated appends.
        pattern = re.compile(
            re.escape(_V50_PARSED_BLOCK_BEGIN) + r".*?" + re.escape(_V50_PARSED_BLOCK_END),
            flags=re.DOTALL,
        )
        cleaned = pattern.sub("", current).rstrip()
        new_text = (cleaned + "\n\n" + report).strip() + "\n"
        gui.structure_text.delete("1.0", "end")
        gui.structure_text.insert("1.0", new_text)
        try:
            gui.set_status("Parsed output structure refreshed in Data structure preview.")
        except Exception:
            pass
        return True
    except Exception as exc:
        try:
            gui.set_status(f"Could not refresh parsed output structure: {exc}")
        except Exception:
            pass
        return False


def _v50_start_parsed_structure_monitor(gui, base_name=None, duration_ms=15*60*1000, interval_ms=5000):
    """Poll output folders so the preview updates while parser command windows are creating files."""
    try:
        var = getattr(gui, "append_parsed_structure_after_parser_var", None)
        if var is not None and not bool(var.get()):
            return
        token = f"{datetime.now().timestamp()}_{id(gui)}"
        gui._v50_parsed_structure_monitor_token = token
        start_ms = int(datetime.now().timestamp() * 1000)
        base_name = base_name or _v27_current_base_name(gui)

        def tick():
            try:
                if getattr(gui, "_v50_parsed_structure_monitor_token", None) != token:
                    return
                v = getattr(gui, "append_parsed_structure_after_parser_var", None)
                if v is not None and not bool(v.get()):
                    return
                _v50_update_structure_preview_with_parsed_outputs(gui, base_name=base_name)
                now_ms = int(datetime.now().timestamp() * 1000)
                if now_ms - start_ms < duration_ms:
                    gui.after(interval_ms, tick)
                else:
                    try:
                        gui.set_status("Parsed-output structure monitor finished.")
                    except Exception:
                        pass
            except Exception:
                pass

        # Start shortly after launch/export so files can appear first, but update immediately too.
        _v50_update_structure_preview_with_parsed_outputs(gui, base_name=base_name)
        gui.after(max(1000, interval_ms), tick)
        try:
            gui.set_status("Monitoring parser output folders to update Data structure preview.")
        except Exception:
            pass
    except Exception:
        pass


