def _v50_add_parsed_structure_checkbox(gui):
    """Add compact checkbox to AI workflow toolbar."""
    try:
        if not hasattr(gui, "append_parsed_structure_after_parser_var"):
            gui.append_parsed_structure_after_parser_var = tk.BooleanVar(value=True)

        lf = _v27_find_widget_by_text(gui, "TLabelframe", "pySECCM / DRT runners") or _v27_find_widget_by_text(gui, "Labelframe", "pySECCM / DRT runners")
        if lf is None:
            return
        target_row = None
        for child in lf.winfo_children():
            try:
                if getattr(child, "_faradaiq_v45_ai_toolbar", False):
                    target_row = child
                    break
            except Exception:
                pass
        if target_row is None:
            target_row = lf

        for child in target_row.winfo_children():
            try:
                if getattr(child, "_faradaiq_v50_parsed_structure_widget", False):
                    return
            except Exception:
                pass

        chk = ttk.Checkbutton(
            target_row,
            text="Append parsed structure",
            variable=gui.append_parsed_structure_after_parser_var,
        )
        chk._faradaiq_v50_parsed_structure_widget = True
        chk.pack(side="left", padx=(10, 0))

        btn = ttk.Button(
            target_row,
            text="Refresh structure",
            command=lambda: _v50_update_structure_preview_with_parsed_outputs(gui, force=True),
        )
        btn._faradaiq_v50_parsed_structure_widget = True
        btn.pack(side="left", padx=(6, 0))
    except Exception:
        pass


