_FARADAIQ_V53_REFRESH_RETRY_TEMPLATE = '@echo off\nsetlocal EnableExtensions EnableDelayedExpansion\ncd /d "%~dp0"\n\ntitle FaradaIQ AWS SSO refresh + LiteLLM restart + test\n\nset "AWS_PROFILE=__PROFILE__"\nset "AWS_REGION=__REGION__"\nset "AWS_DEFAULT_REGION=__REGION__"\nset "AWS_BEDROCK_MODEL_ID=__BEDROCK_MODEL__"\nset "LITELLM_BASE_URL=__BASE__"\nset "LITELLM_KEY=__KEY__"\nset "LITELLM_MODEL=__MODEL__"\nset "LITELLM_PORT=__PORT__"\n\necho ============================================================\necho FaradaIQ AWS SSO refresh + LiteLLM restart + selected-model test\necho ============================================================\necho.\necho Current/default AWS profile:\necho   %AWS_PROFILE%\nset /p "AWS_PROFILE_IN=Enter AWS SSO profile name to use [%AWS_PROFILE%]: "\nif not "%AWS_PROFILE_IN%"=="" set "AWS_PROFILE=%AWS_PROFILE_IN%"\necho Using AWS profile:\necho   %AWS_PROFILE%\necho.\necho Current/default AWS region:\necho   %AWS_REGION%\nset /p "AWS_REGION_IN=Enter AWS region [%AWS_REGION%]: "\nif not "%AWS_REGION_IN%"=="" set "AWS_REGION=%AWS_REGION_IN%"\nset "AWS_DEFAULT_REGION=%AWS_REGION%"\necho Using AWS region:\necho   %AWS_REGION%\necho.\necho Bedrock model/profile:  %AWS_BEDROCK_MODEL_ID%\necho LiteLLM URL:            %LITELLM_BASE_URL%\necho LiteLLM model alias:    %LITELLM_MODEL%\necho.\necho This is the real AWS check. The LiteLLM server can start even when\necho AWS SSO is expired or the Bedrock model is inaccessible. The chat\necho completion test below confirms the AWS invocation.\necho.\n\nwhere aws >nul 2>nul\nif errorlevel 1 (\n  echo [ERROR] AWS CLI not found. Install AWS CLI and rerun.\n  pause\n  exit /b 1\n)\n\necho Checking AWS identity...\naws sts get-caller-identity --profile "%AWS_PROFILE%"\nif errorlevel 1 (\n  echo.\n  echo [WARN] AWS identity check failed. Running AWS SSO login now.\n  aws sso login --profile "%AWS_PROFILE%"\n  if errorlevel 1 (\n    echo [ERROR] AWS SSO login failed.\n    pause\n    exit /b 1\n  )\n)\n\necho Rechecking AWS identity...\naws sts get-caller-identity --profile "%AWS_PROFILE%"\nif errorlevel 1 (\n  echo [ERROR] AWS identity still fails after SSO login.\n  pause\n  exit /b 1\n)\n\necho.\necho Stopping any existing LiteLLM process on port %LITELLM_PORT%...\npowershell -NoProfile -ExecutionPolicy Bypass -Command "$pids=Get-NetTCPConnection -LocalPort $env:LITELLM_PORT -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess -Unique; foreach($pid in $pids){try{Stop-Process -Id $pid -Force -ErrorAction SilentlyContinue; Write-Host (\'Stopped PID \' + $pid)}catch{}}"\ntimeout /t 2 /nobreak >nul\n\necho Starting LiteLLM proxy in a separate window...\nstart "FaradaIQ LiteLLM Proxy" "%CD%\\start_faradaiq_litellm_proxy.bat"\n\necho Waiting for LiteLLM /models...\npowershell -NoProfile -ExecutionPolicy Bypass -Command "$u=$env:LITELLM_BASE_URL.TrimEnd(\'/\') + \'/models\'; $h=@{Authorization=\'Bearer \'+$env:LITELLM_KEY}; for($i=0;$i -lt 75;$i++){try{$r=Invoke-RestMethod -Uri $u -Headers $h -TimeoutSec 2; Write-Host \'[OK] /models responded\'; if($r.data){$r.data | ForEach-Object {Write-Host (\'  - \' + $_.id)}}; exit 0}catch{Start-Sleep -Seconds 1}}; Write-Host \'[ERROR] timed out waiting for LiteLLM /models\'; exit 1"\nif errorlevel 1 (\n  echo [ERROR] LiteLLM proxy did not become ready.\n  pause\n  exit /b 1\n)\n\necho.\necho Running real selected-model chat completion test...\npowershell -NoProfile -ExecutionPolicy Bypass -Command "$body=@{model=$env:LITELLM_MODEL; messages=@(@{role=\'user\'; content=\'Say exactly: FaradaIQ AWS Bedrock ping OK.\'}); max_tokens=80} | ConvertTo-Json -Depth 8; try{$r=Invoke-RestMethod -Uri ($env:LITELLM_BASE_URL.TrimEnd(\'/\') + \'/chat/completions\') -Method Post -Headers @{Authorization=(\'Bearer \'+$env:LITELLM_KEY)} -ContentType \'application/json\' -Body $body -TimeoutSec 120; Write-Host \'[OK] Chat completion succeeded:\'; Write-Host $r.choices[0].message.content; exit 0}catch{Write-Host \'[ERROR] Chat completion failed.\'; Write-Host $_.Exception.Message; if($_.ErrorDetails.Message){Write-Host $_.ErrorDetails.Message}; exit 1}"\nif errorlevel 1 (\n  echo.\n  echo [ERROR] Real AWS Bedrock invocation still failed.\n  echo Check: Bedrock model access, inference profile ID, SCP restrictions, and region.\n) else (\n  echo.\n  echo [OK] FaradaIQ AWS/LiteLLM real ping succeeded.\n)\npause\n'


def _v47_llm_setup_wizard_path():
    root = Path(__file__).resolve().parent
    for name in [
        "run_faradaiq_llm_setup_wizard_v53.bat",
        "run_faradaiq_llm_setup_wizard_v52.bat",
        "run_faradaiq_llm_setup_wizard_v51.bat",
    ]:
        p = root / name
        if p.exists():
            return p
    return root / "run_faradaiq_llm_setup_wizard_v53.bat"


def _v47_start_llm_setup_wizard(parent=None):
    """Open the FaradaIQ LLM backend setup wizard from inside LLM settings."""
    path = _v47_llm_setup_wizard_path()
    if not path.exists():
        try:
            messagebox.showerror(
                "LLM backend setup wizard missing",
                f"Could not find:\n{path}\n\nUse the full FaradaIQ v273 package so the wizard BAT is included.",
                parent=parent,
            )
        except Exception:
            pass
        return
    try:
        os.startfile(str(path))
        try:
            messagebox.showinfo(
                "LLM backend setup wizard started",
                "Opened the FaradaIQ LLM backend setup wizard in a Command Prompt window.\n\n"
                "Use it to configure/check AWS LiteLLM, Ollama, AI Incubator, or a custom provider endpoint.\n"
                "After it finishes, return to LLM settings and click Load/fill from Windows env or Ping selected.",
                parent=parent,
            )
        except Exception:
            pass
    except Exception as exc:
        try:
            messagebox.showerror("Could not start LLM backend setup wizard", str(exc), parent=parent)
        except Exception:
            pass


# Override the settings banner to use neutral naming and avoid any project-specific wording.
_V53_PREV_SHOW_LLM_SETTINGS = _v37_show_llm_settings

def _v37_show_llm_settings(self):
    _V53_PREV_SHOW_LLM_SETTINGS(self)
    try:
        tops = [w for w in self.winfo_children() if isinstance(w, tk.Toplevel)]
        if not tops:
            return
        win = tops[-1]
        # Rename any older button/label text if earlier hooks created them.
        def rename_widgets(root):
            try:
                children = list(root.winfo_children())
            except Exception:
                return
            for child in children:
                try:
                    txt = str(child.cget("text"))
                    if "backend setup wizard" in txt and "LLM backend" not in txt:
                        child.configure(text="LLM backend setup wizard")
                    if "project-specific" in txt.lower() or "prior working setup-style" in txt:
                        child.configure(text="Run AWS/LiteLLM, Ollama, AI Incubator, or custom backend setup here instead of at app startup.")
                    if "Run AWS/LiteLLM, Ollama, AI Incubator, or custom backend setup here instead of at app startup." in txt:
                        child.configure(text="Run AWS/LiteLLM, Ollama, AI Incubator, or custom backend setup here instead of at app startup.")
                except Exception:
                    pass
                rename_widgets(child)
        rename_widgets(win)
    except Exception:
        pass


_V53_PREV_WRITE_LITELLM_PROXY_FILES = _v40_write_litellm_proxy_files

def _v40_write_litellm_proxy_files():
    """v53 override: proxy BAT asks user to confirm AWS profile before any AWS identity check."""
    paths = _V53_PREV_WRITE_LITELLM_PROXY_FILES()
    try:
        profile = _v40_env_first(["AWS_PROFILE"], "BirthrightUser-143924590130")
        paths["requirements"].write_text("litellm[proxy]\nboto3\n", encoding="utf-8")
        paths["bat"].write_text(_FARADAIQ_V53_LITELLM_PROXY_BAT_TEMPLATE.replace("BirthrightUser-143924590130", profile), encoding="utf-8")
        root_shortcut = paths["root"].parent / "start_faradaiq_litellm_proxy.bat"
        root_shortcut.write_text(_FARADAIQ_V53_ROOT_PROXY_SHORTCUT, encoding="utf-8")
    except Exception as exc:
        try:
            print(f"[WARN] Could not write v53 robust LiteLLM proxy BAT: {exc}", flush=True)
        except Exception:
            pass
    return paths


def _v49_write_aws_refresh_retry_bat(candidate=None):
    """Write AWS SSO refresh BAT; prompt for profile before running get-caller-identity."""
    candidate = candidate or {}
    paths = _v40_write_litellm_proxy_files()
    root = paths["root"]
    refresh_bat = root / "run_aws_sso_refresh_restart_and_test.bat"

    base = _v44_normalize_openai_base(candidate.get("base_url") or _v40_env_first(["LITELLM_BASE_URL"], "http://127.0.0.1:4000/v1"))
    key = candidate.get("api_key") or _v40_env_first(["LITELLM_KEY", "LITELLM_MASTER_KEY"], "sk-local")
    model = candidate.get("model") or _v40_env_first(["LITELLM_MODEL"], "faradaiq-bedrock")
    profile = _v40_env_first(["AWS_PROFILE"], "BirthrightUser-143924590130")
    region = _v40_env_first(["AWS_REGION", "AWS_DEFAULT_REGION"], "us-west-2")
    bedrock_model = _v40_env_first(["AWS_BEDROCK_MODEL_ID", "BEDROCK_MODEL_ID"], "anthropic.claude-3-haiku-20240307-v1:0")
    port = "4000"
    try:
        m = re.search(r":(\d+)/v1$", base)
        if m:
            port = m.group(1)
    except Exception:
        pass

    bat = (_FARADAIQ_V53_REFRESH_RETRY_TEMPLATE
           .replace("__PROFILE__", profile)
           .replace("__REGION__", region)
           .replace("__BEDROCK_MODEL__", bedrock_model)
           .replace("__BASE__", base)
           .replace("__KEY__", key)
           .replace("__MODEL__", model)
           .replace("__PORT__", port))
    refresh_bat.write_text(bat, encoding="utf-8")
    return refresh_bat


