APP_TITLE = "FaradaIQ Studio v273"


def _v54_remove_legacy_bottom_plot_toolbar(gui):
    """Remove the old bottom row added by an early wrapper so the main panes get more space."""
    try:
        for child in list(gui.winfo_children()):
            try:
                texts = []
                for sub in child.winfo_children():
                    try:
                        texts.append(str(sub.cget("text")))
                    except Exception:
                        pass
                if "Open pySECCM Plot/DRT Tools" in texts:
                    child.destroy()
            except Exception:
                pass
    except Exception:
        pass


def _v54_compact_button_row(parent, specs, columns):
    for i, (label, command, style_name) in enumerate(specs):
        kw = {"text": label, "command": command}
        if style_name:
            kw["style"] = style_name
        b = ttk.Button(parent, **kw)
        b.grid(row=i // columns, column=i % columns, sticky="ew", padx=2, pady=2)
    for c in range(columns):
        parent.columnconfigure(c, weight=1)


