def _v55_find_existing_analysis_root(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    out = Path(gui.output_dir_var.get().strip() or ".").resolve()
    safe = _v35_safe_name(base_name)
    candidates = [
        out / f"{base_name}_analysis_ready_csv",
        out / f"{safe}_analysis_ready_csv",
    ]
    for p in candidates:
        try:
            if p.exists() and p.is_dir():
                return p.resolve()
        except Exception:
            pass
    return None


def _v55_text_from_widget(widget, max_chars=100_000):
    try:
        txt = widget.get("1.0", "end").strip()
        if len(txt) > max_chars:
            return txt[:max_chars] + "\n...[truncated for prompt]..."
        return txt
    except Exception:
        return ""


def _v55_file_tree_text(analysis_root, max_lines=500):
    analysis_root = Path(analysis_root).resolve()
    lines = [f"[ANALYSIS ROOT] {analysis_root}"]
    n = 0
    try:
        for p in sorted(analysis_root.rglob("*"), key=lambda x: str(x).lower()):
            if n >= max_lines:
                lines.append("...file tree truncated...")
                break
            try:
                rel = p.relative_to(analysis_root).as_posix()
                low_parts = [part.lower() for part in Path(rel).parts]
                if any("ai_analysis_with_parsed_outputs" in part for part in low_parts):
                    continue
                if p.is_dir():
                    if len(Path(rel).parts) <= 5:
                        lines.append(f"DIR  {rel}/")
                        n += 1
                elif p.is_file():
                    size = p.stat().st_size
                    lines.append(f"FILE {rel} ({size} bytes)")
                    n += 1
            except Exception:
                pass
    except Exception as exc:
        lines.append(f"[file tree error: {exc}]")
    return "\n".join(lines)


def _v55_create_new_ai_prompt(gui, analysis_root, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    user_description = _v55_text_from_widget(gui.desc_text)
    session_summary = _v55_text_from_widget(gui.summary_text)
    data_structure = _v55_text_from_widget(gui.structure_text)
    file_tree = _v55_file_tree_text(analysis_root)

    created = datetime.now().isoformat(timespec="seconds")
    prompt = f"""FaradaIQ AI-analysis prompt for electrochemical parsed-output bundle
Generated: {created}
Session/base name: {base_name}

ROLE
You are an electrochemistry-trained scientific data analyst. Analyze the attached FaradaIQ AI bundle rigorously using the parsed raw/export files, SECCM-compatible files, CV/EIS/DRT outputs, figures, metadata, JSON summaries, and NPY payloads. Work at the level of a strong journal manuscript Results/Discussion section.

PRIMARY OBJECTIVES
1. Verify the parsing and data integrity before drawing conclusions.
2. Use the structured NPY/JSON payloads to identify the available techniques, measurement positions, sweeps, spectra, and derived outputs.
3. For SECCM or spatial datasets, connect position/takedata/stage-coordinate files to CV/EIS/DRT outputs and summarize spatial trends.
4. For CV data, report scan rates, potential/current ranges, peak positions/currents when present, hysteresis, background/capacitive behavior, and redox/current trends.
5. For EIS data, report frequency range, Nyquist/Bode features, charge-transfer/diffusion signatures, Warburg behavior if present, and any changes across positions or conditions.
6. For DRT outputs, identify robust relaxation features, avoid over-interpreting poorly constrained peaks, and connect features to likely electrochemical processes only when supported by the data.
7. Flag missing metadata, incomplete parser outputs, truncated files, inconsistent units, or questionable parser classifications.
8. Separate direct observations from interpretation. Do not fabricate values, peaks, fitted parameters, or mechanisms that are not supported by the data.

EXPECTED OUTPUTS
- A concise data-inventory table listing raw, parsed, structured, figure, DRT, JSON, and NPY files used.
- A data-quality / parsing-check section.
- A technique-by-technique analysis section for CV, EIS, DRT, SECCM/spatial data, and figures when present.
- A quantitative-results table with only values that can be read or computed from the included data.
- A short mechanistic interpretation with uncertainty and alternative explanations.
- A figure/table recommendation list for manuscript use.
- A clear list of follow-up calculations or re-parsing steps needed.

CURRENT USER/EXPERIMENTAL DESCRIPTION
{user_description}

SESSION SUMMARY FROM FARADAIQ
{session_summary}

DATA STRUCTURE PREVIEW FROM FARADAIQ
{data_structure}

PARSED/ANALYZED FILE STRUCTURE AVAILABLE FOR THE AI BUNDLE
{file_tree}
"""
    return prompt


def _v55_update_bundle_prompt_payload(info, prompt_text):
    try:
        bundle_dir = Path(info.get("bundle_dir", ""))
        manifest_path = Path(info.get("manifest_path", ""))
        summary_path = Path(info.get("summary_path", ""))
        npy_path = Path(info.get("npy_path", ""))
        prompt_path = bundle_dir / "AI_analysis_prompt_for_current_bundle.txt"
        prompt_path.write_text(prompt_text, encoding="utf-8")

        if summary_path.exists():
            data = json.loads(summary_path.read_text(encoding="utf-8", errors="replace"))
            data["current_prompt"] = prompt_text
            data["analysis_prompt_file"] = prompt_path.name
            data["bundle_build_action"] = "Build AI bundle for analysis"
            data["version"] = "v55"
            summary_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

        if manifest_path.exists():
            data = json.loads(manifest_path.read_text(encoding="utf-8", errors="replace"))
            data["current_prompt"] = prompt_text
            data["analysis_prompt_file"] = prompt_path.name
            data.setdefault("summary", {})["analysis_prompt_file"] = prompt_path.name
            data.setdefault("summary", {})["version"] = "v55"
            manifest_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

        if npy_path.exists():
            arr = np.load(npy_path, allow_pickle=True)
            try:
                payload = arr.item()
            except Exception:
                payload = arr.tolist()
            if isinstance(payload, dict):
                payload["current_prompt"] = prompt_text
                payload["new_ai_prompt"] = prompt_text
                payload["analysis_prompt_file"] = str(prompt_path)
                np.save(npy_path, np.array(payload, dtype=object), allow_pickle=True)
    except Exception:
        pass


def _v55_build_ai_bundle_for_analysis(gui):
    global _FARADAIQ_AI_PROGRESS_CALLBACK
    win, log = _v41_analysis_progress_window(gui, "Build AI bundle for analysis")
    _FARADAIQ_AI_PROGRESS_CALLBACK = log
    try:
        if not getattr(gui, "collection", None) or not getattr(gui.collection, "entries", []):
            messagebox.showwarning("No data loaded", "Load and inspect a dataset first, then build the AI bundle.", parent=gui)
            return

        base_name = _v27_current_base_name(gui)
        analysis_root = _v55_find_existing_analysis_root(gui, base_name=base_name)
        if analysis_root is None:
            messagebox.showwarning(
                "Export first",
                "No analysis-ready output folder was found yet.\n\n"
                "Click Export archive + CSV first, then run parsers if needed, then build the AI bundle.",
                parent=gui,
            )
            return

        log(f"[AI bundle] Analysis root: {analysis_root}")
        log("[AI bundle] Refreshing parsed-output structure preview...")
        try:
            _v50_update_structure_preview_with_parsed_outputs(gui, base_name=base_name, force=True)
        except Exception:
            pass

        log("[AI bundle] Creating new analysis prompt from experimental description, session summary, data structure, and file tree...")
        prompt_text = _v55_create_new_ai_prompt(gui, analysis_root, base_name=base_name)
        (analysis_root / "AI_prompt_current.txt").write_text(prompt_text, encoding="utf-8")

        log("[AI bundle] Building structured NPY/JSON bundle with raw exports + parsed/analyzed outputs...")
        info = make_ai_analysis_bundle(
            analysis_root,
            base_name=base_name,
            label="build_for_analysis_v55",
            copy_files=True,
            progress_callback=log,
        )
        _v55_update_bundle_prompt_payload(info, prompt_text)

        try:
            _v50_update_structure_preview_with_parsed_outputs(gui, base_name=base_name, force=True)
        except Exception:
            pass

        msg = (
            "AI analysis bundle built successfully.\n\n"
            f"Folder:\n{info.get('bundle_dir')}\n\n"
            f"NPY:\n{info.get('npy_path')}\n\n"
            f"JSON:\n{info.get('summary_path')}\n{info.get('manifest_path')}\n\n"
            f"Files indexed: {info.get('n_files_indexed')}\n"
            f"Files copied: {info.get('n_files_copied')}"
        )
        log("[AI bundle] Complete.")
        log(msg)
        gui.set_status("AI analysis bundle built with raw + parsed/analyzed data and new prompt.")
        try:
            os.startfile(str(Path(info.get("bundle_dir"))))
        except Exception:
            pass
        try:
            messagebox.showinfo("AI bundle built for analysis", msg, parent=gui)
        except Exception:
            pass
    except Exception as exc:
        log(f"[ERROR] {exc}")
        gui.set_status("AI bundle build failed.")
        messagebox.showerror("AI bundle build failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)
    finally:
        _FARADAIQ_AI_PROGRESS_CALLBACK = None


def _v55_patch_ai_toolbar(gui):
    """Replace Edison-send/run-Edison controls with one analysis-bundle builder."""
    try:
        build_button_seen = False
        ai_parent = None

        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass

        for w in list(walk(gui)):
            try:
                txt = str(w.cget("text"))
            except Exception:
                continue

            if txt in {"Send AI bundle to Edison", "Auto-send after parser run"}:
                try:
                    w.destroy()
                except Exception:
                    pass
                continue

            if txt in {"Run parsers + Edison", "Run parsers + AI bundle + Edison"}:
                try:
                    w.configure(
                        text="Build AI bundle for analysis",
                        command=lambda g=gui: _v55_build_ai_bundle_for_analysis(g),
                        style="Accent.TButton",
                    )
                    ai_parent = w.master
                    build_button_seen = True
                except Exception:
                    pass

            if txt == "AI workflow":
                try:
                    ai_parent = w.master
                except Exception:
                    pass

        if ai_parent is not None and not build_button_seen:
            ttk.Button(
                ai_parent,
                text="Build AI bundle for analysis",
                command=lambda g=gui: _v55_build_ai_bundle_for_analysis(g),
                style="Accent.TButton",
            ).pack(side="left", padx=(0, 6))

        # Make labels a little shorter after removing Edison-specific workflow.
        for w in list(walk(gui)):
            try:
                txt = str(w.cget("text"))
            except Exception:
                continue
            if txt == "Generate AI prompt":
                try:
                    w.configure(text="Generate prompt")
                except Exception:
                    pass
    except Exception:
        pass


