def _v58_mask_secret(value):
    value = str(value or "")
    if not value:
        return "missing"
    if len(value) <= 8:
        return "found"
    return value[:4] + "..." + value[-4:]


def _v58_edison_env_values():
    return {
        "api_key": _v40_env_first(["EDISON_PLATFORM_API_KEY", "EDISON_API_KEY", "EDISON_SCIENTIFIC_API_KEY"], ""),
        "base_url": _v40_env_first(["EDISON_BASE_URL", "EDISON_SCIENTIFIC_BASE_URL"], "https://platform.edisonscientific.com/"),
        "upload_url": _v40_env_first(["EDISON_UPLOAD_URL", "EDISON_SCIENTIFIC_UPLOAD_URL"], ""),
        "job_name": _v40_env_first(["EDISON_JOB_NAME", "EDISON_ANALYSIS_JOB"], "analysis"),
        "language": _v40_env_first(["EDISON_ANALYSIS_LANGUAGE"], "PYTHON"),
        "max_steps": _v40_env_first(["EDISON_MAX_STEPS"], "30"),
        "mode": _v40_env_first(["EDISON_SEND_MODE"], "official_client"),
        "install_client": _v40_env_first(["EDISON_INSTALL_CLIENT_IF_MISSING"], "1"),
    }


def _v58_edison_settings_report():
    e = _v58_edison_env_values()
    return (
        "Edison Scientific settings\n"
        "==========================\n\n"
        "Official Edison Platform API notes implemented in FaradaIQ:\n"
        "- Edison client authenticates with an Edison platform API key. FaradaIQ checks EDISON_PLATFORM_API_KEY first, then EDISON_API_KEY.\n"
        "- Official data-analysis workflow: upload bundle to Edison data storage, create an ANALYSIS task with data_storage_uris, poll until completion, then retrieve answer/output metadata.\n"
        "- Legacy/custom multipart upload is still available if EDISON_UPLOAD_URL is provided.\n\n"
        f"EDISON_PLATFORM_API_KEY / EDISON_API_KEY: {_v58_mask_secret(e['api_key'])}\n"
        f"EDISON_BASE_URL: {e['base_url']}\n"
        f"EDISON_UPLOAD_URL: {'found' if e['upload_url'] else 'missing'}\n"
        f"EDISON_SEND_MODE: {e['mode']}\n"
        f"EDISON_JOB_NAME: {e['job_name']}\n"
        f"EDISON_ANALYSIS_LANGUAGE: {e['language']}\n"
        f"EDISON_MAX_STEPS: {e['max_steps']}\n"
        f"EDISON_INSTALL_CLIENT_IF_MISSING: {e['install_client']}\n"
    )


def _v58_show_edison_settings(gui):
    try:
        win = tk.Toplevel(gui)
        win.title("FaradaIQ Edison Scientific settings")
        win.geometry("960x720")
        try:
            p = _v36_theme_palette(getattr(gui, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass
        outer = ttk.Frame(win, style="Card.TFrame", padding=(12, 12))
        outer.pack(fill="both", expand=True, padx=10, pady=10)
        ttk.Label(outer, text="Edison Scientific settings", style="Section.TLabel").pack(anchor="w")
        ttk.Label(
            outer,
            text="Reads keys from Windows Process/User/Machine environment, lets you edit for this session, and configures how FaradaIQ sends/retrieves Edison analysis results.",
            style="Muted.TLabel",
            wraplength=900,
        ).pack(anchor="w", pady=(2, 8))

        vals = _v58_edison_env_values()
        api_var = tk.StringVar(value=vals["api_key"])
        base_var = tk.StringVar(value=vals["base_url"])
        upload_var = tk.StringVar(value=vals["upload_url"])
        mode_var = tk.StringVar(value=vals["mode"])
        job_var = tk.StringVar(value=vals["job_name"])
        lang_var = tk.StringVar(value=vals["language"])
        max_steps_var = tk.StringVar(value=vals["max_steps"])
        install_var = tk.BooleanVar(value=str(vals["install_client"]).lower() not in {"0", "false", "no"})

        form = ttk.LabelFrame(outer, text="Editable session settings", padding=(10, 8))
        form.pack(fill="x", pady=(0, 8))
        form.columnconfigure(1, weight=1)
        form.columnconfigure(3, weight=1)

        def row(r, label, widget, col=1, span=1):
            ttk.Label(form, text=label, style="Card.TLabel").grid(row=r, column=0 if col == 1 else 2, sticky="w", padx=(0, 8), pady=3)
            widget.grid(row=r, column=col, columnspan=span, sticky="ew", pady=3)

        key_entry = ttk.Entry(form, textvariable=api_var, show="*")
        row(0, "API key", key_entry, 1, 3)
        show_key_var = tk.BooleanVar(value=False)
        def toggle_key():
            key_entry.configure(show="" if show_key_var.get() else "*")
        ttk.Checkbutton(form, text="show", variable=show_key_var, command=toggle_key).grid(row=0, column=4, sticky="w", padx=(8, 0))

        row(1, "Edison base URL", ttk.Entry(form, textvariable=base_var), 1, 3)
        row(2, "Custom upload URL", ttk.Entry(form, textvariable=upload_var), 1, 3)
        mode_box = ttk.Combobox(form, textvariable=mode_var, values=["official_client", "custom_upload_url"], state="readonly", width=24)
        row(3, "Send mode", mode_box, 1, 1)
        row(3, "Job name", ttk.Entry(form, textvariable=job_var), 3, 1)
        row(4, "Language", ttk.Entry(form, textvariable=lang_var), 1, 1)
        row(4, "Max steps", ttk.Entry(form, textvariable=max_steps_var), 3, 1)
        ttk.Checkbutton(form, text="Install edison-client into FaradaIQ private env if missing", variable=install_var).grid(row=5, column=1, columnspan=3, sticky="w", pady=3)

        docs = ScrolledText(outer, wrap="word", height=18)
        docs.pack(fill="both", expand=True, pady=(4, 8))
        try:
            docs.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc")
        except Exception:
            pass
        docs.insert("1.0", _v58_edison_settings_report())
        docs.configure(state="disabled")

        def apply_session():
            os.environ["EDISON_PLATFORM_API_KEY"] = api_var.get().strip()
            os.environ["EDISON_API_KEY"] = api_var.get().strip()
            os.environ["EDISON_BASE_URL"] = base_var.get().strip()
            os.environ["EDISON_UPLOAD_URL"] = upload_var.get().strip()
            os.environ["EDISON_SEND_MODE"] = mode_var.get().strip()
            os.environ["EDISON_JOB_NAME"] = job_var.get().strip()
            os.environ["EDISON_ANALYSIS_LANGUAGE"] = lang_var.get().strip()
            os.environ["EDISON_MAX_STEPS"] = max_steps_var.get().strip()
            os.environ["EDISON_INSTALL_CLIENT_IF_MISSING"] = "1" if install_var.get() else "0"
            docs.configure(state="normal")
            docs.delete("1.0", "end")
            docs.insert("1.0", _v58_edison_settings_report() + "\n\nApplied these values for this FaradaIQ session.")
            docs.configure(state="disabled")
            try:
                gui.set_status("Edison Scientific settings applied for this session.")
            except Exception:
                pass

        def load_env():
            vals = _v58_edison_env_values()
            api_var.set(vals["api_key"])
            base_var.set(vals["base_url"])
            upload_var.set(vals["upload_url"])
            mode_var.set(vals["mode"])
            job_var.set(vals["job_name"])
            lang_var.set(vals["language"])
            max_steps_var.set(vals["max_steps"])
            install_var.set(str(vals["install_client"]).lower() not in {"0", "false", "no"})
            docs.configure(state="normal")
            docs.delete("1.0", "end")
            docs.insert("1.0", _v58_edison_settings_report())
            docs.configure(state="disabled")

        def save_setx_helper():
            folder = Path(__file__).resolve().parent / "edison_env_helpers"
            folder.mkdir(parents=True, exist_ok=True)
            bat = folder / "set_faradaiq_edison_env_user.bat"
            lines = [
                "@echo off",
                "echo Setting FaradaIQ Edison Scientific Windows USER environment variables...",
                "echo Secret values will be written to Windows User env.",
                f'setx EDISON_PLATFORM_API_KEY "{api_var.get().replace(chr(34), "")}"',
                f'setx EDISON_API_KEY "{api_var.get().replace(chr(34), "")}"',
                f'setx EDISON_BASE_URL "{base_var.get().replace(chr(34), "")}"',
                f'setx EDISON_UPLOAD_URL "{upload_var.get().replace(chr(34), "")}"',
                f'setx EDISON_SEND_MODE "{mode_var.get().replace(chr(34), "")}"',
                f'setx EDISON_JOB_NAME "{job_var.get().replace(chr(34), "")}"',
                f'setx EDISON_ANALYSIS_LANGUAGE "{lang_var.get().replace(chr(34), "")}"',
                f'setx EDISON_MAX_STEPS "{max_steps_var.get().replace(chr(34), "")}"',
                "echo.",
                "echo Done. Open a new terminal/FaradaIQ session before relying on persistent env values.",
                "pause",
            ]
            bat.write_text("\n".join(lines) + "\n", encoding="utf-8")
            try:
                os.startfile(str(folder))
            except Exception:
                pass
            messagebox.showinfo("Edison setx helper written", f"Wrote:\n{bat}", parent=win)

        btns = ttk.Frame(outer, style="Card.TFrame")
        btns.pack(fill="x")
        ttk.Button(btns, text="Load from Windows env", command=load_env).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Apply for this session", command=apply_session).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Save setx helper", command=save_setx_helper).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Open Edison docs", command=lambda: webbrowser.open("https://docs.edisonscientific.com/edison-client")).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Open Edison platform profile", command=lambda: webbrowser.open("https://platform.edisonscientific.com/profile")).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=win.destroy).pack(side="right")
    except Exception as exc:
        messagebox.showerror("Edison settings error", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


def _v58_to_jsonable(obj, depth=0):
    if depth > 8:
        return str(obj)
    if obj is None or isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, Path):
        return str(obj)
    if isinstance(obj, dict):
        return {str(k): _v58_to_jsonable(v, depth+1) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_v58_to_jsonable(v, depth+1) for v in obj]
    try:
        if hasattr(obj, "model_dump"):
            return _v58_to_jsonable(obj.model_dump(), depth+1)
    except Exception:
        pass
    try:
        if hasattr(obj, "dict"):
            return _v58_to_jsonable(obj.dict(), depth+1)
    except Exception:
        pass
    try:
        return _v58_to_jsonable(vars(obj), depth+1)
    except Exception:
        return str(obj)


def _v58_edison_prompt_from_bundle(bundle_dir, max_chars=120000):
    bundle_dir = Path(bundle_dir)
    parts = []
    for name in ["AI_analysis_prompt_for_current_bundle.txt", "AI_prompt_current.txt"]:
        p = bundle_dir / name
        if p.exists():
            try:
                parts.append(p.read_text(encoding="utf-8", errors="replace"))
                break
            except Exception:
                pass
    for p in sorted(bundle_dir.glob("*_AI_analysis_summary.json"))[:1]:
        try:
            parts.append("\n\nAI bundle summary JSON:\n" + p.read_text(encoding="utf-8", errors="replace")[:25000])
        except Exception:
            pass
    txt = "\n\n".join(parts).strip()
    if not txt:
        txt = "Analyze the attached FaradaIQ AI-analysis bundle. Use the included NPY/JSON/CSV/figure files and avoid unsupported conclusions."
    if len(txt) > max_chars:
        txt = txt[:max_chars] + "\n...[truncated by FaradaIQ before Edison submission]..."
    return txt


def _v58_install_edison_client_if_needed():
    try:
        import edison_client  # noqa: F401
        return {"installed": True, "action": "already_available"}
    except Exception as first_exc:
        install_flag = _v40_env_first(["EDISON_INSTALL_CLIENT_IF_MISSING"], "1")
        if str(install_flag).lower() in {"0", "false", "no"}:
            raise RuntimeError("edison-client is not installed and EDISON_INSTALL_CLIENT_IF_MISSING is disabled.") from first_exc
        print("edison-client not found. Installing into this FaradaIQ private Python environment...", flush=True)
        subprocess.check_call([sys.executable, "-m", "pip", "install", "edison-client>=0.15.0,<0.16"])
        import edison_client  # noqa: F401
        return {"installed": True, "action": "installed_with_pip"}


def _v58_extract_edison_answer(job_result_json):
    candidates = []
    if isinstance(job_result_json, dict):
        for key in ["formatted_answer", "answer", "output", "result"]:
            if job_result_json.get(key):
                candidates.append(job_result_json.get(key))
        try:
            candidates.append(job_result_json["environment_frame"]["state"]["state"]["answer"])
        except Exception:
            pass
        try:
            candidates.append(job_result_json["environment_frame"]["state"]["info"]["output_data"])
        except Exception:
            pass
    for c in candidates:
        if c:
            if isinstance(c, str):
                return c
            return json.dumps(c, ensure_ascii=False, indent=2)
    return ""


def _v58_run_official_edison_analysis(zip_path, bundle_dir, metadata, api_key):
    _v58_install_edison_client_if_needed()
    import asyncio
    import time
    from edison_client import EdisonClient
    try:
        # Edison docs show RuntimeConfig and TaskRequest under edison_client.models.app.
        from edison_client.models.app import RuntimeConfig, TaskRequest
    except Exception:
        from edison_client.models import RuntimeConfig, TaskRequest
    try:
        # Edison docs show JobNames available from edison_client; keep fallbacks for older clients.
        from edison_client import JobNames
    except Exception:
        try:
            from edison_client.models.app import JobNames
        except Exception:
            from edison_client.models import JobNames

    async def _upload_and_run():
        client = EdisonClient(api_key=api_key)
        print("Uploading AI bundle ZIP to Edison data storage...", flush=True)
        upload_response = await client.astore_file_content(
            name=f"FaradaIQ AI bundle: {metadata.get('base_name', 'session')}",
            file_path=str(zip_path),
            description="FaradaIQ AI-analysis bundle containing raw exports, parsed/analyzed electrochemistry outputs, NPY/JSON payloads, and prompt.",
        )
        upload_json = _v58_to_jsonable(upload_response)
        try:
            data_storage_id = upload_response.data_storage.id
        except Exception:
            try:
                data_storage_id = upload_json["data_storage"]["id"]
            except Exception:
                data_storage_id = upload_json.get("id") or upload_json.get("data_storage_id")
        if not data_storage_id:
            raise RuntimeError("Could not determine Edison data_storage id from upload response: " + json.dumps(upload_json, indent=2)[:2000])
        print(f"Uploaded. Edison data storage id: {data_storage_id}", flush=True)

        query = _v58_edison_prompt_from_bundle(bundle_dir)
        max_steps = int(_v40_env_first(["EDISON_MAX_STEPS"], "30") or "30")
        language = _v40_env_first(["EDISON_ANALYSIS_LANGUAGE"], "PYTHON") or "PYTHON"
        prompting_config = {
            "system_prompt_additional_guidelines": (
                "You are analyzing a FaradaIQ electrochemistry AI bundle. Use only the uploaded files and prompt. "
                "Separate observations from interpretations; do not invent data, figures, or parameter values."
            )
        }
        runtime_config = RuntimeConfig(
            max_steps=max_steps,
            environment_config={
                "language": language,
                "prompting_config": prompting_config,
                "data_storage_uris": [f"data_entry:{data_storage_id}"],
            },
        )
        job_name_text = str(_v40_env_first(["EDISON_JOB_NAME", "EDISON_ANALYSIS_JOB"], "analysis") or "analysis").lower()
        try:
            job_name = JobNames.ANALYSIS
        except Exception:
            job_name = "analysis"
        if job_name_text not in {"analysis", "finch", "jobnames.analysis"}:
            try:
                job_name = JobNames.from_string(job_name_text)
            except Exception:
                job_name = job_name_text
        task_data = TaskRequest(name=job_name, query=query, runtime_config=runtime_config)
        print("Creating Edison Analysis task...", flush=True)
        trajectory_id = client.create_task(task_data)
        print(f"Task created: {trajectory_id}", flush=True)
        print(f"Live platform URL: https://platform.edisonscientific.com/trajectories/{trajectory_id}", flush=True)

        status = "in progress"
        started = time.time()
        timeout_sec = int(_v40_env_first(["EDISON_TASK_TIMEOUT_SECONDS"], "3600") or "3600")
        poll_sec = int(_v40_env_first(["EDISON_TASK_POLL_SECONDS"], "15") or "15")
        task_status_json = None
        while str(status).lower() in {"in progress", "queued", "running", "pending"}:
            if time.time() - started > timeout_sec:
                raise TimeoutError(f"Edison task did not finish within {timeout_sec} seconds. Task id: {trajectory_id}")
            task_status = client.get_task(trajectory_id)
            task_status_json = _v58_to_jsonable(task_status)
            status = task_status_json.get("status", getattr(task_status, "status", "unknown"))
            print(f"[{datetime.now().isoformat(timespec='seconds')}] Edison task status: {status}", flush=True)
            if str(status).lower() in {"success", "succeeded", "completed", "done", "failed", "error"}:
                break
            time.sleep(poll_sec)
        if str(status).lower() in {"failed", "error"}:
            raise RuntimeError("Edison task failed: " + json.dumps(task_status_json, indent=2)[:4000])
        print("Retrieving Edison task result with verbose=True...", flush=True)
        job_result = client.get_task(trajectory_id, verbose=True)
        job_result_json = _v58_to_jsonable(job_result)
        answer = _v58_extract_edison_answer(job_result_json)
        return {
            "mode": "official_edison_client",
            "trajectory_id": str(trajectory_id),
            "live_url": f"https://platform.edisonscientific.com/trajectories/{trajectory_id}",
            "upload_response": upload_json,
            "data_storage_id": str(data_storage_id),
            "final_status": str(status),
            "answer": answer,
            "task_status": task_status_json,
            "task_result": job_result_json,
        }

    return asyncio.run(_upload_and_run())


_V58_PREV_SEND_BUILT_CLI = _v56_send_built_ai_bundle_to_edison_cli

def _v56_send_built_ai_bundle_to_edison_cli(path, base_name=None):
    """v58: send already-built bundle using official edison-client when configured, else legacy upload URL."""
    root = Path(path).resolve()
    if root.name.endswith("_AI_analysis_with_parsed_outputs"):
        bundle_dir = root
        analysis_root = root.parent
        if base_name is None:
            base_name = root.name.replace("_AI_analysis_with_parsed_outputs", "")
    else:
        analysis_root = root
        if base_name is None:
            nm = analysis_root.name
            base_name = nm[:-len("_analysis_ready_csv")] if nm.endswith("_analysis_ready_csv") else nm
        bundle_dir = _v56_latest_built_ai_bundle(analysis_root, base_name=base_name)
    if bundle_dir is None or not Path(bundle_dir).exists():
        raise FileNotFoundError("No built AI bundle found. Build AI bundle for analysis first.")

    safe = _v35_safe_name(base_name or Path(bundle_dir).name.replace("_AI_analysis_with_parsed_outputs", ""))
    run_id = datetime.now().strftime("%Y%m%d_%H%M%S")
    forced_response_dir = _v40_env_first(["FARADAIQ_EDISON_RESPONSE_DIR"], "")
    if forced_response_dir:
        handoff_dir = Path(forced_response_dir).resolve()
    else:
        handoff_dir = analysis_root / f"{safe}_EdisonScientific_handoff" / f"edison_send_built_{run_id}"
    handoff_dir.mkdir(parents=True, exist_ok=True)
    metadata = {
        "created": datetime.now().isoformat(timespec="seconds"),
        "app": "FaradaIQ Studio",
        "version": "v273",
        "operation": "send_existing_built_ai_bundle_to_edison",
        "base_name": base_name,
        "analysis_root": str(analysis_root),
        "ai_bundle_dir": str(bundle_dir),
        "edison_docs_basis": "edison-client: store file content, create ANALYSIS task, poll get_task, retrieve answer/environment_frame",
    }
    metadata_path = handoff_dir / "edison_send_metadata.json"
    metadata_path.write_text(json.dumps(metadata, ensure_ascii=False, indent=2), encoding="utf-8")
    zip_path = handoff_dir / f"{safe}_BUILT_AI_bundle_for_Edison_{run_id}.zip"
    print("=" * 72, flush=True)
    print("FaradaIQ → Edison Scientific", flush=True)
    print("Sending already-built AI analysis bundle", flush=True)
    print("=" * 72, flush=True)
    print(f"AI bundle folder: {bundle_dir}", flush=True)
    print(f"Handoff folder:   {handoff_dir}", flush=True)
    print(f"Upload ZIP:       {zip_path}", flush=True)
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for p in Path(bundle_dir).rglob("*"):
            if p.is_file():
                z.write(p, Path("AI_analysis_bundle") / p.relative_to(bundle_dir))
        z.write(metadata_path, "edison_send_metadata.json")
    print(f"ZIP created: {zip_path.stat().st_size} bytes", flush=True)

    api_key = _v40_env_first(["EDISON_PLATFORM_API_KEY", "EDISON_API_KEY", "EDISON_SCIENTIFIC_API_KEY"], "")
    upload_url = _v40_env_first(["EDISON_UPLOAD_URL", "EDISON_SCIENTIFIC_UPLOAD_URL"], "")
    mode = str(_v40_env_first(["EDISON_SEND_MODE"], "official_client") or "official_client").lower()
    result = {
        "uploaded": False,
        "mode_requested": mode,
        "zip_path": str(zip_path),
        "handoff_dir": str(handoff_dir),
        "bundle_dir": str(bundle_dir),
        "edison_api_key_present": bool(api_key),
        "edison_upload_url_present": bool(upload_url),
    }
    print("Windows environment check:", flush=True)
    print(f"  EDISON_PLATFORM_API_KEY / EDISON_API_KEY: {_v58_mask_secret(api_key)}", flush=True)
    print(f"  EDISON_UPLOAD_URL: {'found' if upload_url else 'missing'}", flush=True)
    print(f"  EDISON_SEND_MODE: {mode}", flush=True)

    try:
        if mode != "custom_upload_url" and api_key:
            official = _v58_run_official_edison_analysis(zip_path, Path(bundle_dir), metadata, api_key)
            result.update(official)
            result["uploaded"] = True
            result["status"] = "completed_official_edison_client"
        elif upload_url and api_key:
            print("Using custom multipart upload URL fallback...", flush=True)
            legacy = _v37_multipart_upload(
                upload_url,
                api_key,
                fields={"app": "FaradaIQ Studio", "version": "v273", "metadata": json.dumps(metadata)},
                files={"file": zip_path},
                timeout=1200,
            )
            result.update({"uploaded": True, "status": "uploaded_custom_url", "edison_response": legacy})
        else:
            result["status"] = "local_handoff_only_missing_edison_credentials"
            result["message"] = "Missing Edison API key and/or upload URL. Created local handoff ZIP only."
            print("[WARN] Missing Edison credentials. Local handoff only.", flush=True)
    except Exception as exc:
        result.update({"uploaded": False, "status": "send_failed", "error_type": type(exc).__name__, "error": str(exc)})
        print("=" * 72, flush=True)
        print("Edison send failed", flush=True)
        print("=" * 72, flush=True)
        print(str(exc), flush=True)

    response_json = handoff_dir / "edison_send_response.json"
    response_txt = handoff_dir / "edison_send_response_pretty.txt"
    response_json.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    pretty = "FaradaIQ Edison response\n========================\n\n" + _v56_neat_json_text(result) + "\n"
    response_txt.write_text(pretty, encoding="utf-8")
    print("=" * 72, flush=True)
    print("Formatted Edison response", flush=True)
    print("=" * 72, flush=True)
    print(pretty, flush=True)
    print("Saved:", flush=True)
    print(f"  {response_json}", flush=True)
    print(f"  {response_txt}", flush=True)
    return result


def _v58_reformat_edison_response_with_llm(gui, text_widget, response_dir=None):
    try:
        original = text_widget.get("1.0", "end").strip()
        if not original:
            return
        messages = [
            {"role": "system", "content": (
                "You are a formatting assistant. Reformat the provided Edison Scientific response for readability only. "
                "Do not add, delete, infer, summarize away, change numbers, change filenames, change status values, or invent content. "
                "Preserve all factual content. Use clear headings, indentation, and bullet formatting only. If content is ambiguous, keep it unchanged."
            )},
            {"role": "user", "content": original},
        ]
        formatted, provider = _v37_call_best_llm(messages, max_tokens=5000, temperature=0.0)
        formatted = str(formatted or "").strip()
        if formatted:
            text_widget.delete("1.0", "end")
            text_widget.insert("1.0", formatted)
            if response_dir:
                p = Path(response_dir) / "edison_send_response_llm_reformatted.txt"
                p.write_text(formatted, encoding="utf-8")
            try:
                gui.set_status("Edison response reformatted using selected LLM.")
            except Exception:
                pass
    except Exception as exc:
        messagebox.showerror("LLM reformat failed", f"{exc}\n\nUse LLM settings to select/ping a backend first.", parent=gui)


def _v58_show_edison_response_window(gui, response_path):
    try:
        response_path = Path(response_path)
        if not response_path.exists():
            return
        response_dir = response_path.parent
        win = tk.Toplevel(gui)
        win.title("FaradaIQ Edison Scientific response")
        win.geometry("980x720")
        try:
            p = _v36_theme_palette(getattr(gui, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass
        frame = ttk.Frame(win, style="Card.TFrame", padding=(12, 12))
        frame.pack(fill="both", expand=True, padx=10, pady=10)
        ttk.Label(frame, text="Edison Scientific response", style="Section.TLabel").pack(anchor="w")
        ttk.Label(frame, text=f"Editable response file: {response_path}", style="Muted.TLabel", wraplength=900).pack(anchor="w", pady=(2, 6))
        box = ScrolledText(frame, wrap="word", height=28)
        box.pack(fill="both", expand=True)
        try:
            box.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc")
        except Exception:
            pass
        box.insert("1.0", response_path.read_text(encoding="utf-8", errors="replace"))
        btns = ttk.Frame(frame, style="Card.TFrame")
        btns.pack(fill="x", pady=(8, 0))
        def save_current():
            response_path.write_text(box.get("1.0", "end").strip() + "\n", encoding="utf-8")
            try:
                gui.set_status("Edited Edison response saved locally.")
            except Exception:
                pass
        ttk.Button(btns, text="Save edited response", command=save_current).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Reformat using selected LLM", command=lambda: _v58_reformat_edison_response_with_llm(gui, box, response_dir=response_dir)).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Open response folder", command=lambda: os.startfile(str(response_dir)) if hasattr(os, 'startfile') else None).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=win.destroy).pack(side="right")
    except Exception as exc:
        messagebox.showerror("Could not open Edison response", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


def _v58_monitor_edison_response(gui, response_dir, started=None, timeout_ms=2*60*60*1000):
    try:
        response_dir = Path(response_dir)
        started = started or datetime.now()
        target = response_dir / "edison_send_response_pretty.txt"
        if target.exists() and target.stat().st_size > 0:
            gui.set_status("Edison response retrieved and saved locally.")
            _v58_show_edison_response_window(gui, target)
            return
        elapsed = (datetime.now() - started).total_seconds() * 1000
        if elapsed < timeout_ms:
            gui.after(5000, lambda: _v58_monitor_edison_response(gui, response_dir, started=started, timeout_ms=timeout_ms))
        else:
            gui.set_status("Stopped monitoring Edison response window; command may still be running.")
    except Exception:
        pass


_V58_PREV_WRITE_SEND_BAT = _v56_write_send_to_edison_bat

def _v56_write_send_to_edison_bat(gui, analysis_root, base_name=None):
    script = Path(__file__).resolve()
    python_exe = Path(sys.executable).resolve()
    analysis_root = Path(analysis_root).resolve()
    base_name = base_name or _v27_current_base_name(gui)
    safe = _v35_safe_name(base_name)
    run_id = datetime.now().strftime("%Y%m%d_%H%M%S")
    response_dir = analysis_root / f"{safe}_EdisonScientific_handoff" / f"edison_send_built_{run_id}"
    response_dir.mkdir(parents=True, exist_ok=True)
    bat_dir = analysis_root / "_faradaiq_command_windows"
    bat_dir.mkdir(parents=True, exist_ok=True)
    bat_path = bat_dir / f"send_built_ai_bundle_to_edison_{run_id}.bat"
    bat = f"""@echo off
setlocal EnableExtensions
title FaradaIQ Send Built AI Bundle to Edison
cd /d "{analysis_root}"
echo ============================================================
echo FaradaIQ: Send built AI bundle to Edison Scientific
echo ============================================================
echo This command window shows upload progress and the Edison response.
echo It sends the existing built AI-analysis bundle only.
echo It does not rebuild the bundle.
echo.
set "FARADAIQ_EDISON_RESPONSE_DIR={response_dir}"
echo Response folder:
echo   {response_dir}
echo.
"{python_exe}" "{script}" --send-built-ai-bundle-to-edison "{analysis_root}" --base-name "{base_name}"
set "EXITCODE=%ERRORLEVEL%"
echo.
echo FaradaIQ Edison send exited with code %EXITCODE%.
echo Response JSON/TXT were saved under:
echo   {response_dir}
echo.
pause
exit /b %EXITCODE%
"""
    bat_path.write_text(bat, encoding="utf-8")
    return bat_path, response_dir


def _v56_send_built_ai_bundle_to_edison_gui(gui):
    try:
        if not getattr(gui, "collection", None) or not getattr(gui.collection, "entries", []):
            messagebox.showwarning("No data loaded", "Load and inspect a dataset first.", parent=gui)
            return
        base_name = _v27_current_base_name(gui)
        analysis_root = _v55_find_existing_analysis_root(gui, base_name=base_name)
        if analysis_root is None:
            messagebox.showwarning("No analysis folder", "No analysis-ready folder was found. Export first, then build the AI bundle.", parent=gui)
            return
        bundle_dir = _v56_latest_built_ai_bundle(analysis_root, base_name=base_name)
        if bundle_dir is None:
            messagebox.showwarning("Build AI bundle first", "No built AI-analysis bundle was found.\n\nClick 'Build AI bundle for analysis' first, then click 'Send AI bundle to Edison'.", parent=gui)
            return
        bat, response_dir = _v56_write_send_to_edison_bat(gui, analysis_root, base_name=base_name)
        gui.set_status("Opening Edison send command window and monitoring response...")
        try:
            os.startfile(str(bat))
        except Exception:
            subprocess.Popen(["cmd", "/c", "start", "FaradaIQ Edison send", str(bat)], shell=False)
        _v58_monitor_edison_response(gui, response_dir)
    except Exception as exc:
        gui.set_status("Could not start Edison send.")
        messagebox.showerror("Edison send launch failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


