def _v60_walk_widgets(root):
    yield root
    try:
        for child in root.winfo_children():
            yield from _v60_walk_widgets(child)
    except Exception:
        return


def _v60_cleanup_parser_toolbar(gui):
    """Remove redundant Launcher button and rename parser/DRT controls."""
    try:
        for w in list(_v60_walk_widgets(gui)):
            try:
                txt = str(w.cget("text"))
            except Exception:
                continue
            try:
                if txt in {"Launcher", "Launcher window"}:
                    w.destroy()
                elif txt == "Plot/DRT tools":
                    w.configure(text="All parser/DRT tools")
                elif txt in {"Deps", "Check/install deps"}:
                    w.configure(text="Dependencies check")
            except Exception:
                pass
    except Exception:
        pass


