_V59_PREV_EXPORT_OUTPUTS = SessionReaderGUI.export_outputs

def _session_reader_gui_v60_export_outputs(self):
    """When auto-run is enabled, suppress blocking showinfo dialogs so parser commands start immediately."""
    try:
        enabled = bool(getattr(self, "auto_run_pyseccm_after_export_var", tk.BooleanVar(value=False)).get())
    except Exception:
        enabled = False
    if not enabled:
        return _V59_PREV_EXPORT_OUTPUTS(self)

    orig_showinfo = messagebox.showinfo

    def no_wait_info(title, message, *args, **kwargs):
        try:
            self.set_status(str(title) + " — continuing automatically.")
        except Exception:
            pass
        try:
            # Keep detailed information in stdout/command window without waiting for a GUI OK click.
            print("\n" + "=" * 72, flush=True)
            print(str(title), flush=True)
            print("=" * 72, flush=True)
            print(str(message), flush=True)
        except Exception:
            pass
        return "ok"

    messagebox.showinfo = no_wait_info
    try:
        return _V59_PREV_EXPORT_OUTPUTS(self)
    finally:
        messagebox.showinfo = orig_showinfo

SessionReaderGUI.export_outputs = _session_reader_gui_v60_export_outputs



