_V62_PREV_REFORMAT_EDISON_RESPONSE_WITH_LLM = _v58_reformat_edison_response_with_llm

def _v58_reformat_edison_response_with_llm(gui, text_widget, response_dir=None):
    """v62: stricter no-hallucination reformat prompt before using selected LLM."""
    try:
        original = text_widget.get("1.0", "end").strip()
        if not original:
            return
        messages = [
            {"role": "system", "content": (
                "You are a formatting-only assistant. You must preserve the Edison Scientific response exactly in meaning and content. "
                "Do not add, remove, infer, summarize, correct, normalize, translate, or change any content. "
                "Do not change numbers, file paths, ids, task status values, dates, units, URLs, filenames, JSON keys, or JSON values. "
                "Only improve visual formatting with headings, indentation, line breaks, and bullets. If unsure, copy the content unchanged."
            )},
            {"role": "user", "content": "Reformat the following Edison Scientific response for readability only. Preserve all content exactly:\n\n" + original},
        ]
        formatted, provider = _v37_call_best_llm(messages, max_tokens=7000, temperature=0.0)
        formatted = str(formatted or "").strip()
        if formatted:
            text_widget.delete("1.0", "end")
            text_widget.insert("1.0", formatted)
            if response_dir:
                p = Path(response_dir) / "edison_send_response_llm_reformatted.txt"
                p.write_text(formatted, encoding="utf-8")
                meta = Path(response_dir) / "edison_reformat_llm_metadata.json"
                try:
                    meta.write_text(json.dumps({
                        "created": datetime.now().isoformat(timespec="seconds"),
                        "provider": provider,
                        "instruction": "formatting only; no additions/deletions/changes",
                    }, ensure_ascii=False, indent=2), encoding="utf-8")
                except Exception:
                    pass
            try:
                gui.set_status("Edison response reformatted using selected LLM without content changes.")
            except Exception:
                pass
    except Exception as exc:
        messagebox.showerror("LLM reformat failed", f"{exc}\n\nUse LLM settings to select/ping a backend first.", parent=gui)



# ---- v63 enhancement: live export progress window redraw + no blocking export-complete OK ----
APP_TITLE = "FaradaIQ Studio v273"


def _v63_force_redraw(gui=None, win=None, loops=2, process_events=True):
    """Force Tk to paint the progress window before entering long export/file-write stages."""
    for _ in range(max(1, int(loops))):
        try:
            if win is not None and win.winfo_exists():
                win.update_idletasks()
                if process_events:
                    win.update()
        except Exception:
            pass
        try:
            if gui is not None and gui.winfo_exists():
                gui.update_idletasks()
        except Exception:
            pass


def _v63_analysis_progress_window(gui, title="FaradaIQ progress"):
    """Progress window that paints immediately and stays readable during export stages."""
    try:
        win = tk.Toplevel(gui)
        win.title(title)
        win.geometry("860x500")
        win.transient(gui)
        try:
            p = _v36_theme_palette(getattr(gui, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass

        frame = ttk.Frame(win, style="Card.TFrame", padding=(10, 10))
        frame.pack(fill="both", expand=True, padx=10, pady=10)
        ttk.Label(frame, text=title, style="Section.TLabel").pack(anchor="w")

        note = ttk.Label(
            frame,
            text="Live status appears below. During very large file-write steps, the GUI may pause briefly, but the latest started step remains visible.",
            style="Muted.TLabel",
            wraplength=780,
        )
        note.pack(anchor="w", pady=(4, 4))

        txt = ScrolledText(frame, wrap="word", height=20)
        txt.pack(fill="both", expand=True, pady=(4, 8))
        try:
            txt.configure(
                background="#020617",
                foreground="#e5eefb",
                insertbackground="#f8fafc",
                font=("Consolas", 9),
            )
        except Exception:
            pass

        button_row = ttk.Frame(frame, style="Card.TFrame")
        button_row.pack(fill="x")
        ttk.Button(button_row, text="Close", command=win.destroy).pack(side="right")

        def log(msg):
            try:
                timestamp = datetime.now().strftime("%H:%M:%S")
                txt.configure(state="normal")
                txt.insert("end", f"[{timestamp}] {str(msg)}\n")
                txt.see("end")
                txt.configure(state="disabled")
                try:
                    if hasattr(gui, "status_var"):
                        gui.status_var.set(str(msg)[:180])
                except Exception:
                    pass
                # A browser refresh can log while its tree is being rebuilt.
                # Paint the progress window without running other GUI callbacks.
                _v63_force_redraw(gui, win, loops=1, process_events=False)
            except Exception:
                pass

        try:
            win.lift()
            win.focus_force()
        except Exception:
            pass

        # Paint a first line immediately so the window never appears blank while export starts.
        log("[Window] Progress window is ready. Export messages will stream here.")
        _v63_force_redraw(gui, win, loops=3, process_events=False)
        return win, log
    except Exception:
        return None, lambda msg: None


# Use the improved progress window everywhere previous build/export helpers call this function.
_v41_analysis_progress_window = _v63_analysis_progress_window


def _v63_nonblocking_info_capture(title, message, progress_log=None):
    """Replacement for messagebox.showinfo during export so parser auto-run does not wait for OK."""
    try:
        if progress_log:
            lines = str(message).splitlines()
            progress_log(f"[Info suppressed] {title}")
            for line in lines[:20]:
                progress_log(f"  {line}")
            if len(lines) > 20:
                progress_log("  ...message truncated in progress window...")
    except Exception:
        pass
    return "ok"


def _session_reader_gui_v63_export_outputs(self):
    """Export with real-time status mirroring into the progress window and no blocking OK dialog."""
    global _FARADAIQ_AI_PROGRESS_CALLBACK
    base_name = _v27_current_base_name(self)
    progress_win, progress_log = _v63_analysis_progress_window(self, "FaradaIQ live export / AI bundle progress")
    _FARADAIQ_AI_PROGRESS_CALLBACK = progress_log

    original_set_status = getattr(self, "set_status", None)
    original_showinfo = messagebox.showinfo
    in_status = {"busy": False}

    def patched_set_status(message):
        # Mirror status changes from the export engine into the progress window.
        if not in_status["busy"]:
            try:
                in_status["busy"] = True
                progress_log(f"[Export status] {message}")
            finally:
                in_status["busy"] = False
        try:
            if original_set_status:
                original_set_status(message)
            else:
                self.status_var.set(str(message))
                self.update_idletasks()
        except Exception:
            pass
        try:
            _v63_force_redraw(self, progress_win, loops=1)
        except Exception:
            pass

    def patched_showinfo(title, message, *args, **kwargs):
        return _v63_nonblocking_info_capture(title, message, progress_log=progress_log)

    try:
        self.set_status = patched_set_status
        messagebox.showinfo = patched_showinfo

        progress_log("[Export] Starting archive/NPY/JSON/CSV export.")
        progress_log("[Export] The next visible status should be: Building archive bundle.")
        _v63_force_redraw(self, progress_win, loops=4)

        _SESSION_READER_GUI_V41_BASE_EXPORT_OUTPUTS(self)

        analysis_root = _v35_analysis_root_for_export(self, base_name=base_name)
        if analysis_root.exists():
            try:
                prompt_text = self.desc_text.get("1.0", "end").strip()
                (analysis_root / "AI_prompt_current.txt").write_text(prompt_text, encoding="utf-8")
                progress_log("[AI prompt] Current experimental description saved to AI_prompt_current.txt.")
            except Exception as exc:
                progress_log(f"[AI prompt] Could not save current prompt text: {exc}")

            progress_log("[AI bundle] Creating AI-analysis bundle with raw + parsed + organized data...")
            _v63_force_redraw(self, progress_win, loops=2)
            info = make_ai_analysis_bundle(
                analysis_root,
                base_name=base_name,
                label="after_export_v63",
                copy_files=True,
                progress_callback=progress_log,
            )
            progress_log(f"[AI bundle] Ready: {info.get('bundle_dir')}")

        enabled = bool(getattr(self, "auto_run_pyseccm_after_export_var", tk.BooleanVar(value=False)).get())
        send_after = bool(getattr(self, "send_ai_bundle_to_edison_after_parse_var", tk.BooleanVar(value=False)).get())

        if enabled:
            progress_log("[Auto-run] Auto-run is checked; launching CV/EIS/IV/OCP/DRT parsers now.")
            _v63_force_redraw(self, progress_win, loops=2)
            result = _v27_launch_auto_pyseccm_after_export(self, base_name=base_name)
            progress_log(f"[Auto-run] Parser command window launched: {result.get('batch')}")
            progress_log(f"[Auto-run] Commands queued: {result.get('n_commands')}")
            progress_log("[Auto-run] Parser progress/errors are shown in the black command window.")
            if send_after:
                progress_log("[Auto-run] Edison send is queued after parser completion in the command window.")
        elif send_after and analysis_root.exists():
            progress_log("[Edison] Auto-run is not enabled; sending current AI bundle to Edison/local handoff now...")
            result = _v41_send_ai_bundle_to_edison_cli(analysis_root, base_name=base_name)
            progress_log(f"[Edison] Handoff complete: {result.get('zip_path')}")

        progress_log("[Complete] Export / AI bundle / optional parser launch setup complete.")
        try:
            if original_set_status:
                original_set_status("Export / AI bundle setup complete.")
        except Exception:
            pass
    except Exception as exc:
        try:
            if original_set_status:
                original_set_status("Export / AI bundle action failed.")
        except Exception:
            pass
        progress_log(f"[ERROR] {exc}")
        messagebox.showerror("FaradaIQ export / AI bundle error", f"{exc}\n\n{traceback.format_exc()}", parent=self)
    finally:
        _FARADAIQ_AI_PROGRESS_CALLBACK = None
        try:
            self.set_status = original_set_status
        except Exception:
            pass
        try:
            messagebox.showinfo = original_showinfo
        except Exception:
            pass


