# ---- v64 enhancement: Electrochemical data browser + visualization workstation ----
APP_TITLE = "FaradaIQ Studio v273"


def _v64_safe_float_array(values):
    try:
        arr = np.asarray(values, dtype=float)
        if arr.ndim != 1:
            arr = arr.reshape(-1)
        mask = np.isfinite(arr)
        return arr[mask], mask
    except Exception:
        return np.array([], dtype=float), np.array([], dtype=bool)


def _v64_analysis_root_for_browser(gui):
    try:
        base_name = _v27_current_base_name(gui)
    except Exception:
        base_name = "electrochem_session"
    try:
        root = _v55_find_existing_analysis_root(gui, base_name=base_name)
        if root and Path(root).exists():
            return Path(root).resolve(), base_name
    except Exception:
        pass
    try:
        root = _v35_analysis_root_for_export(gui, base_name=base_name)
        if root and Path(root).exists():
            return Path(root).resolve(), base_name
    except Exception:
        pass
    try:
        out = Path(gui.output_dir_var.get().strip() or ".").resolve()
    except Exception:
        out = Path.cwd()
    return out, base_name


def _v64_detect_file_kind(path):
    p = Path(path)
    low = p.as_posix().lower()
    name = p.name.lower()
    suffix = p.suffix.lower()
    if suffix in {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".svg", ".pdf"}:
        return "Figure"
    if suffix in {".npy", ".npz"}:
        return "NumPy payload"
    if suffix in {".json"}:
        return "Metadata JSON"
    if "drt" in low:
        return "DRT"
    if "freq_zreal_zimag" in name or "nyquist" in low or "fulleis" in low or "eis" in low:
        return "EIS"
    if "ocp" in low or "open" in low and "circuit" in low:
        return "OCP"
    if "tafel" in low or " iv" in low or "_iv" in low:
        return "IV / Tafel"
    if "cv" in low or suffix == ".asc" or "lsv" in low:
        return "CV / LSV"
    if "takedata" in low or "position" in low or "stage" in low:
        return "SECCM position / takedata"
    if suffix in {".csv", ".txt", ".tsv"}:
        return "Tables / text"
    return "Other"


def _v64_read_table_file(path, max_rows=None):
    path = Path(path)
    suffix = path.suffix.lower()
    try:
        import pandas as _pd
    except Exception as exc:
        raise RuntimeError("pandas is required to read table files in the data browser.") from exc
    if suffix in {".xlsx", ".xls"}:
        df = _pd.read_excel(path)
    else:
        try:
            df = _pd.read_csv(path, sep=None, engine="python", comment=None)
        except Exception:
            try:
                df = _pd.read_csv(path, sep="\t", engine="python", comment=None)
            except Exception:
                df = _pd.read_csv(path, header=None, sep=None, engine="python", comment=None)
    if max_rows:
        df = df.head(int(max_rows))
    # Drop fully empty columns/rows while preserving source where possible.
    try:
        df = df.dropna(axis=0, how="all").dropna(axis=1, how="all")
    except Exception:
        pass
    return df


def _v64_numeric_columns(df):
    cols = []
    try:
        import pandas as _pd
        for c in df.columns:
            s = _pd.to_numeric(df[c], errors="coerce")
            if s.notna().sum() >= max(2, int(0.1 * len(df))):
                cols.append(c)
    except Exception:
        pass
    return cols


def _v64_choose_xy(df, kind="Auto"):
    """Pick x/y columns from a DataFrame based on echem semantics."""
    try:
        import pandas as _pd
        cols = list(df.columns)
        numeric = _v64_numeric_columns(df)
        low = {c: str(c).lower() for c in cols}
        def find_any(words, pool=None):
            pool = pool or numeric
            for c in pool:
                lc = low.get(c, str(c).lower())
                if any(w in lc for w in words):
                    return c
            return None

        k = str(kind or "Auto").lower()
        if "nyquist" in k or "eis" in k:
            x = find_any(["zreal", "z_real", "z'", "real"])
            y = find_any(["zimag", "z_imag", "z''", "imag"])
            if x is not None and y is not None:
                return x, y, "EIS Nyquist"
        if "bode" in k:
            x = find_any(["freq", "hz", "frequency"])
            y = find_any(["mag", "|z|", "zmod", "modulus", "abs"])
            if x is not None and y is not None:
                return x, y, "Bode magnitude"
        if "cv" in k or "auto" in k or "lsv" in k:
            x = find_any(["potential", "voltage", "ewe", "e/v", "e_v", "v"])
            y = find_any(["current", "i/", "i_", "amp", "ma", "ua", "na"])
            if x is not None and y is not None:
                return x, y, "Current vs potential"
        if "ocp" in k:
            x = find_any(["time", "s"])
            y = find_any(["potential", "voltage", "ocp", "ewe"])
            if x is not None and y is not None:
                return x, y, "OCP"
        if "drt" in k:
            x = find_any(["tau", "time", "freq", "frequency"])
            y = find_any(["gamma", "drt", "resistance", "g("])
            if x is not None and y is not None:
                return x, y, "DRT"
        if len(numeric) >= 2:
            return numeric[0], numeric[1], "Numeric columns"
        return None, None, "No numeric pair detected"
    except Exception:
        return None, None, "Column detection failed"


def _v64_curve_label(path, xcol=None, ycol=None):
    try:
        p = Path(path)
        stem = p.stem
        if len(stem) > 80:
            stem = stem[:77] + "..."
        if xcol is not None and ycol is not None:
            return f"{stem} [{ycol} vs {xcol}]"
        return stem
    except Exception:
        return str(path)


def _v64_integrate_area(x, y):
    try:
        if len(x) >= 2 and len(y) == len(x):
            return float(np.trapz(y, x))
    except Exception:
        pass
    return float("nan")


def _v64_simple_peak_find(x, y, mode="auto", min_prominence_fraction=0.05):
    """Small dependency-light local peak finder for CV/LSV/DRT curves."""
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    mask = np.isfinite(x) & np.isfinite(y)
    x = x[mask]
    y = y[mask]
    if len(y) < 5:
        return []
    peaks = []
    yrange = float(np.nanmax(y) - np.nanmin(y)) if len(y) else 0.0
    threshold = max(abs(yrange) * float(min_prominence_fraction), 1e-30)
    for sign, name in [(1.0, "positive"), (-1.0, "negative")]:
        yy = sign * y
        for i in range(1, len(yy) - 1):
            if yy[i] >= yy[i-1] and yy[i] >= yy[i+1]:
                left = max(0, i - 5)
                right = min(len(yy), i + 6)
                local_base = min(float(np.nanmin(yy[left:i+1])), float(np.nanmin(yy[i:right])))
                height = float(yy[i] - local_base)
                if height >= threshold:
                    peaks.append({
                        "type": name,
                        "index": int(i),
                        "x": float(x[i]),
                        "y": float(y[i]),
                        "height_estimate": float(height),
                    })
    # Keep strongest peaks first, but not too many.
    peaks = sorted(peaks, key=lambda r: abs(r.get("height_estimate", 0.0)), reverse=True)
    return peaks[:50]


