        self.analysis_root = Path(analysis_root).resolve() if analysis_root else _v64_analysis_root_for_browser(gui)[0]
        self.base_name = base_name or _v64_analysis_root_for_browser(gui)[1]
        self.title("FaradaIQ data browser + analysis")
        self.geometry("1500x920")
        self.minsize(1120, 720)
        self.curves = []
        self.manual_points = []
        self.last_plot_paths = []
        self.suggestions = []
