class _FaradaIQTooltip:
    """Small Tk tooltip for buttons, checkboxes, labels, entries, and comboboxes."""
    def __init__(self, widget, text, delay=550, wraplength=460):
        self.widget = widget
        self.text = str(text or "")
        self.delay = int(delay)
        self.wraplength = int(wraplength)
        self._after = None
        self._tip = None
        if not self.text:
            return
        try:
            widget.bind("<Enter>", self._schedule, add="+")
            widget.bind("<Leave>", self._hide, add="+")
            widget.bind("<ButtonPress>", self._hide, add="+")
        except Exception:
            pass

    def _schedule(self, _event=None):
        self._cancel()
        try:
            self._after = self.widget.after(self.delay, self._show)
        except Exception:
            pass

    def _cancel(self):
        if self._after:
            try:
                self.widget.after_cancel(self._after)
            except Exception:
                pass
        self._after = None

    def _show(self):
        if self._tip is not None:
            return
        try:
            x = self.widget.winfo_rootx() + 18
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 10
            self._tip = tk.Toplevel(self.widget)
            self._tip.wm_overrideredirect(True)
            self._tip.wm_geometry(f"+{x}+{y}")
            frame = tk.Frame(self._tip, background="#111827", borderwidth=1, relief="solid")
            frame.pack(fill="both", expand=True)
            label = tk.Label(
                frame,
                text=self.text,
                justify="left",
                background="#111827",
                foreground="#f8fafc",
                padx=9,
                pady=7,
                wraplength=self.wraplength,
                font=("Segoe UI", 9),
            )
            label.pack()
        except Exception:
            self._tip = None

    def _hide(self, _event=None):
        self._cancel()
        if self._tip is not None:
            try:
                self._tip.destroy()
            except Exception:
                pass
            self._tip = None


def _v66_add_tooltip(widget, text):
    try:
        if widget is not None and not getattr(widget, "_faradaiq_tooltip_added", False):
            widget._faradaiq_tooltip_added = True
            widget._faradaiq_tooltip = _FaradaIQTooltip(widget, text)
    except Exception:
        pass


