def _v66_apply_tooltips(root):
    try:
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass
        for w in walk(root):
            try:
                txt = str(w.cget("text"))
            except Exception:
                txt = ""
            if txt in _V66_TOOLTIP_TEXT:
                _v66_add_tooltip(w, _V66_TOOLTIP_TEXT[txt])
            else:
                try:
                    cls = w.winfo_class()
                    if cls in {"Entry", "TEntry"}:
                        _v66_add_tooltip(w, "Editable field. Values may come from Windows environment, current session settings, or selected FaradaIQ output paths.")
                    elif cls in {"TCombobox"}:
                        _v66_add_tooltip(w, "Choose an option from the list. Changing it affects only the current FaradaIQ session unless saved to Windows environment.")
                except Exception:
                    pass
    except Exception:
        pass


def _v66_selected_llm_label_text():
    provider = globals().get("_FARADAIQ_SELECTED_LLM_PROVIDER", None) or _v40_env_first(["FARADAIQ_LLM_PROVIDER"], "Auto")
    cands = _v40_provider_candidates(include_unavailable=True)
    if provider and str(provider).lower() not in {"auto", "best", "default"}:
        cands = [c for c in cands if c.get("name") == provider] or cands
    else:
        # For Auto, show first configured provider if one exists.
        configured = [c for c in cands if c.get("available")]
        cands = configured or cands
    cand = cands[0] if cands else {}
    model = cand.get("model") or _v40_env_first(["AI_INCUBATOR_MODEL", "OLLAMA_MODEL", "LITELLM_MODEL", "AWS_BEDROCK_MODEL_ID"], "")
    ptxt = str(provider or "Auto")
    if ptxt == "Auto" and cand.get("name"):
        ptxt = f"Auto → {cand.get('name')}"
    return ptxt, model, cand


def _v66_update_llm_status_widget(gui):
    try:
        var = getattr(gui, "_faradaiq_llm_status_var", None)
        label = getattr(gui, "_faradaiq_llm_status_label", None)
        if var is None or label is None:
            return
        provider, model, _cand = _v66_selected_llm_label_text()
        last = _FARADAIQ_LLM_LAST_PING
        ok = last.get("ok")
        if ok is True:
            ping_txt = f"PING OK {last.get('time') or ''}".strip()
            color = "#15803d"
        elif ok is False:
            ping_txt = "PING FAILED"
            color = "#b91c1c"
        else:
            ping_txt = "ping not tested"
            color = "#92400e"
        model_txt = f" | model: {model}" if model else ""
        var.set(f"LLM: {provider}{model_txt} | {ping_txt}")
        try:
            label.configure(foreground=color)
        except Exception:
            try:
                label.configure(fg=color)
            except Exception:
                pass
    except Exception:
        pass


def _v66_update_all_llm_status_widgets():
    for gui in list(_FARADAIQ_MAIN_WINDOWS):
        try:
            if gui.winfo_exists():
                _v66_update_llm_status_widget(gui)
        except Exception:
            pass


def _v66_set_llm_ping_status(provider, model, ok, message):
    _FARADAIQ_LLM_LAST_PING.update({
        "provider": provider,
        "model": model,
        "ok": bool(ok),
        "message": str(message or "")[:500],
        "time": datetime.now().strftime("%H:%M:%S"),
    })
    _v66_update_all_llm_status_widgets()


