def _v66_add_llm_status_bar(gui):
    try:
        if gui not in _FARADAIQ_MAIN_WINDOWS:
            _FARADAIQ_MAIN_WINDOWS.append(gui)
    except Exception:
        pass
    try:
        if getattr(gui, "_faradaiq_llm_status_bar_added", False):
            _v66_update_llm_status_widget(gui)
            return
        lf = _v27_find_widget_by_text(gui, "TLabelframe", "pySECCM / DRT runners") or _v27_find_widget_by_text(gui, "Labelframe", "pySECCM / DRT runners")
        parent = lf if lf is not None else gui
        row = ttk.Frame(parent, style="Card.TFrame")
        row.pack(fill="x", pady=(3, 0))
        gui._faradaiq_llm_status_var = tk.StringVar(value="LLM: Auto | ping not tested")
        ttk.Label(row, text="LLM status", style="Muted.TLabel").pack(side="left", padx=(0, 8))
        lbl = ttk.Label(row, textvariable=gui._faradaiq_llm_status_var, style="Card.TLabel")
        lbl.pack(side="left", fill="x", expand=True)
        gui._faradaiq_llm_status_label = lbl
        gui._faradaiq_llm_status_bar_added = True
        _v66_add_tooltip(lbl, "Shows the LLM provider/model FaradaIQ will use for AI prompts. Green means the selected model recently passed a real ping/invocation test.")
        _v66_update_llm_status_widget(gui)
    except Exception:
        pass


def _v66_safe_window_log(gui, log, msg):
    try:
        gui.after(0, lambda: log(msg))
    except Exception:
        try:
            log(msg)
        except Exception:
            pass


def _v66_generate_ai_prompt_with_llm(gui):
    """Nonblocking LLM prompt generation so the progress window paints immediately and stays responsive."""
    win, log = _v63_analysis_progress_window(gui, "Generate AI prompt with LLM")
    try:
        if not getattr(gui, "collection", None) or not getattr(gui.collection, "entries", []):
            messagebox.showwarning("No session loaded", "Load and inspect data first, then generate the LLM scientific prompt.", parent=gui)
            return
        log("[LLM prompt] Progress window is ready.")
        log("[LLM prompt] Gathering session summary, experimental description, and file structure...")
        try:
            _v63_force_redraw(gui, win, loops=3)
        except Exception:
            pass
        experiment = _v45_current_gui_text(gui.desc_text)
        summary = _v45_current_gui_text(gui.summary_text)
        structure = _v45_current_gui_text(gui.structure_text)
        tree = _v45_file_tree_for_prompt(gui)

        messages = [
            {
                "role": "system",
                "content": (
                    "You are an expert electrochemist and scientific data-analysis strategist. "
                    "Your task is to write a rigorous AI-analysis prompt, not to analyze the data yet. "
                    "The prompt must guide a downstream LLM or scientific analyst to interrogate CV, EIS, DRT, SECCM, "
                    "and instrument-parsed files with strong scientific discipline, clear uncertainty handling, and no invented conclusions."
                ),
            },
            {
                "role": "user",
                "content": (
                    "Create a publication-quality scientific analysis prompt for the dataset below. "
                    "The prompt should be appended to an experimental description box and later sent with the AI bundle. "
                    "Make it specific to the available session summary, data structure, and file tree.\n\n"
                    "Required sections in the generated prompt:\n"
                    "1. LLM-generated scientific analysis prompt\n"
                    "2. Scientific questions to answer\n"
                    "3. Data integrity and parsing checks\n"
                    "4. CV/EIS/DRT/SECCM analysis tasks as applicable\n"
                    "5. Expected quantitative outputs, figures, and tables\n"
                    "6. Interpretation constraints: separate observation from inference; flag missing metadata; do not fabricate results.\n\n"
                    "Return only the prompt text to append. Do not include JSON.\n\n"
                    "EXPERIMENTAL DESCRIPTION CURRENT TEXT:\n"
                    f"{experiment}\n\n"
                    "SESSION SUMMARY:\n"
                    f"{summary}\n\n"
                    "DATA STRUCTURE PREVIEW:\n"
                    f"{structure}\n\n"
                    "FILE STRUCTURE / EXPORTED OUTPUT TREE:\n"
                    f"{tree}\n"
                ),
            },
        ]

        def worker():
            try:
                _v66_safe_window_log(gui, log, "[LLM prompt] Calling selected/available LLM backend in background...")
                response, provider = _v37_call_best_llm(messages, max_tokens=2800, temperature=0.15)
                provider_name = provider.get("name", "LLM") if isinstance(provider, dict) else "LLM"
                model_name = provider.get("model", "") if isinstance(provider, dict) else ""
                response = str(response or "").strip()
                if not response:
                    raise RuntimeError("LLM returned an empty response.")
                timestamp = datetime.now().isoformat(timespec="seconds")
                block = (
                    "\n\n"
                    "==================== LLM-GENERATED AI ANALYSIS PROMPT ====================\n"
                    f"Generated: {timestamp}\n"
                    f"Provider: {provider_name}\n"
                    f"Model: {model_name}\n\n"
                    f"{response}\n"
                    "================== END LLM-GENERATED AI ANALYSIS PROMPT ==================\n"
                )
                def finish():
                    try:
                        existing = gui.desc_text.get("1.0", "end").rstrip()
                        gui.desc_text.delete("1.0", "end")
                        gui.desc_text.insert("1.0", existing + block if existing else block.lstrip())
                        root = _v37_analysis_root_for_gui(gui)
                        if root:
                            Path(root).mkdir(parents=True, exist_ok=True)
                            (Path(root) / "AI_prompt_current.txt").write_text(gui.desc_text.get("1.0", "end").strip(), encoding="utf-8")
                        log(f"[LLM prompt] Response received from: {provider_name}")
                        log("[LLM prompt] Prompt appended to Experimental description.")
                        try:
                            gui.set_status(f"LLM prompt generated using {provider_name}.")
                        except Exception:
                            pass
                        _v66_update_all_llm_status_widgets()
                    except Exception as exc:
                        messagebox.showerror("Could not append LLM prompt", str(exc), parent=gui)
                gui.after(0, finish)
            except Exception as exc:
                def fail():
                    log(f"[ERROR] LLM prompt generation failed: {exc}")
                    messagebox.showerror("LLM prompt generation failed", f"{exc}\n\nOpen LLM settings, select a provider, and run Ping selected.", parent=gui)
                try:
                    gui.after(0, fail)
                except Exception:
                    pass

        threading.Thread(target=worker, daemon=True).start()
    except Exception as exc:
        log(f"[ERROR] {exc}")
        messagebox.showerror("LLM prompt generation failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


# Replace older generate-prompt action.
_v45_generate_ai_prompt_with_llm = _v66_generate_ai_prompt_with_llm


def _v66_data_structure_summary_for_bundle(gui, analysis_root, max_files=500):
    lines = [
        f"Base name: {_v27_current_base_name(gui)}",
        f"Analysis root: {analysis_root}",
        "Available FaradaIQ output files by type:",
    ]
    grouped = {}
    try:
        for p in sorted(Path(analysis_root).rglob("*"), key=lambda x: str(x).lower()):
            if not p.is_file():
                continue
            rel = p.relative_to(analysis_root).as_posix()
            if "AI_analysis_with_parsed_outputs" in rel or "EdisonScientific_handoff" in rel:
                continue
            try:
                kind = _v64_detect_file_kind(p)
            except Exception:
                kind = "Other"
            grouped.setdefault(kind, []).append(rel)
    except Exception as exc:
        lines.append(f"[file scan error] {exc}")
    for kind, files in grouped.items():
        lines.append(f"\n{kind} ({len(files)} files)")
        for f in files[:max_files]:
            lines.append(f"  - {f}")
        if len(files) > max_files:
            lines.append("  ...truncated...")
    return "\n".join(lines)


def _v66_llm_guided_bundle(gui):
    """Ask the selected LLM for useful bundle/comparison guidance, save it, then build the bundle."""
    global _FARADAIQ_AI_PROGRESS_CALLBACK
    win, log = _v63_analysis_progress_window(gui, "LLM-guided AI bundle")
    _FARADAIQ_AI_PROGRESS_CALLBACK = log
    try:
        if not getattr(gui, "collection", None) or not getattr(gui.collection, "entries", []):
            messagebox.showwarning("No data loaded", "Load and inspect a dataset first.", parent=gui)
            return
        base_name = _v27_current_base_name(gui)
        analysis_root = _v55_find_existing_analysis_root(gui, base_name=base_name)
        if analysis_root is None:
            messagebox.showwarning("Export first", "Export archive + CSV first, then run the LLM-guided bundle.", parent=gui)
            return
        analysis_root = Path(analysis_root)
        log("[LLM-guided bundle] Preparing data-structure summary for LLM...")
        structure = _v66_data_structure_summary_for_bundle(gui, analysis_root)
        try:
            _v63_force_redraw(gui, win, loops=3)
        except Exception:
            pass

        messages = [
            {"role": "system", "content": (
                "You are an electrochemistry data-curation planner. "
                "Given a FaradaIQ output file tree, recommend what should be emphasized in an AI analysis bundle. "
                "Do not invent results or values. Do not ask for files that are not listed. "
                "Return a practical plan with sections: priority file groups, useful overlays/comparisons, peak/EIS/DRT checks, and any files to deprioritize."
            )},
            {"role": "user", "content": structure},
        ]

        log("[LLM-guided bundle] Calling selected/available LLM for bundling guidance...")
        response, provider = _v37_call_best_llm(messages, max_tokens=2500, temperature=0.1)
        provider_name = provider.get("name", "LLM") if isinstance(provider, dict) else "LLM"
        response = str(response or "").strip()
        if not response:
            raise RuntimeError("LLM returned empty bundle guidance.")

        guidance_dir = analysis_root / f"{_v35_safe_name(base_name)}_FaradaIQ_analyzed_data" / "comparison_tables"
        guidance_dir.mkdir(parents=True, exist_ok=True)
        guidance_txt = guidance_dir / "llm_guided_bundle_plan.txt"
        guidance_json = guidance_dir / "llm_guided_bundle_plan.json"
        guidance_txt.write_text(response, encoding="utf-8")
        guidance_json.write_text(json.dumps({
            "created": datetime.now().isoformat(timespec="seconds"),
            "provider": provider_name,
            "model": provider.get("model", "") if isinstance(provider, dict) else "",
            "analysis_root": str(analysis_root),
            "base_name": base_name,
            "guidance": response,
        }, ensure_ascii=False, indent=2), encoding="utf-8")

        prompt_text = _v55_create_new_ai_prompt(gui, analysis_root, base_name=base_name)
        prompt_text += (
            "\n\n==================== LLM-GUIDED BUNDLE PLAN ====================\n"
            f"Provider: {provider_name}\n\n"
            f"{response}\n"
            "================== END LLM-GUIDED BUNDLE PLAN ==================\n"
        )
        (analysis_root / "AI_prompt_current.txt").write_text(prompt_text, encoding="utf-8")

        log("[LLM-guided bundle] Building AI bundle with saved LLM guidance included...")
        info = make_ai_analysis_bundle(
            analysis_root,
            base_name=base_name,
            label="llm_guided_bundle_v66",
            copy_files=True,
            progress_callback=log,
        )
        _v55_update_bundle_prompt_payload(info, prompt_text)

        log(f"[LLM-guided bundle] Guidance saved: {guidance_txt}")
        log(f"[LLM-guided bundle] Bundle ready: {info.get('bundle_dir')}")
        try:
            os.startfile(str(info.get("bundle_dir")))
        except Exception:
            pass
        messagebox.showinfo(
            "LLM-guided bundle built",
            f"Bundle folder:\n{info.get('bundle_dir')}\n\nGuidance:\n{guidance_txt}",
            parent=gui,
        )
    except Exception as exc:
        log(f"[ERROR] {exc}")
        messagebox.showerror("LLM-guided bundle failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)
    finally:
        _FARADAIQ_AI_PROGRESS_CALLBACK = None


def _v66_deduplicate_and_relabel_ai_toolbar(gui):
    """Fix duplicate Build buttons and add a separate LLM-guided bundle action."""
    try:
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass

        build_buttons = []
        ai_parent = None
        has_guided = False
        for w in list(walk(gui)):
            try:
                txt = str(w.cget("text"))
            except Exception:
                continue
            if txt == "AI workflow":
                ai_parent = w.master
            if txt in {"Build AI bundle for analysis", "Build AI bundle"}:
                build_buttons.append(w)
                try:
                    ai_parent = w.master
                except Exception:
                    pass
            if txt == "LLM-guided bundle":
                has_guided = True
        # Keep only first build button; make label short and clear.
        for i, b in enumerate(build_buttons):
            if i == 0:
                try:
                    b.configure(text="Build AI bundle", command=lambda g=gui: _v55_build_ai_bundle_for_analysis(g))
                    _v66_add_tooltip(b, _V66_TOOLTIP_TEXT["Build AI bundle"])
                except Exception:
                    pass
            else:
                try:
                    b.destroy()
                except Exception:
                    pass
        if ai_parent is not None and not has_guided:
            btn = ttk.Button(
                ai_parent,
                text="LLM-guided bundle",
                command=lambda g=gui: _v66_llm_guided_bundle(g),
            )
            btn.pack(side="left", padx=(6, 6))
            _v66_add_tooltip(btn, _V66_TOOLTIP_TEXT["LLM-guided bundle"])
    except Exception:
        pass


