# ---- v67 enhancement: popout text boxes, branding/credits, rigorous LLM prompt, pySECCM status bar ----
APP_TITLE = "FaradaIQ Studio v273"


def _v67_get_text_font_size(widget, default=9):
    try:
        import tkinter.font as tkfont
        f = tkfont.Font(font=widget.cget("font"))
        return int(f.cget("size") or default)
    except Exception:
        return int(getattr(widget, "_faradaiq_font_size", default))


def _v67_set_text_font_size(widget, size):
    try:
        size = max(6, min(28, int(size)))
        widget._faradaiq_font_size = size
        widget.configure(font=("Consolas", size))
    except Exception:
        pass


def _v67_adjust_text_font(widget, delta):
    _v67_set_text_font_size(widget, _v67_get_text_font_size(widget) + int(delta))


def _v67_textbox_content(widget):
    try:
        return widget.get("1.0", "end").rstrip()
    except Exception:
        return ""


def _v67_set_textbox_content(widget, text):
    try:
        widget.delete("1.0", "end")
        widget.insert("1.0", text)
    except Exception:
        pass


def _v67_open_popout_textbox(gui, title, source_widget, wrap="word"):
    try:
        win = tk.Toplevel(gui)
        win.title(f"{title} — popout")
        win.geometry("1000x720")
        try:
            p = _v36_theme_palette(getattr(gui, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass
        outer = ttk.Frame(win, style="Card.TFrame", padding=(10, 10))
        outer.pack(fill="both", expand=True, padx=10, pady=10)

        top = ttk.Frame(outer, style="Card.TFrame")
        top.pack(fill="x", pady=(0, 6))
        ttk.Label(top, text=title, style="Section.TLabel").pack(side="left", padx=(0, 10))

        txt = ScrolledText(outer, wrap=wrap)
        txt.pack(fill="both", expand=True, pady=(0, 8))
        try:
            txt.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc", font=("Consolas", _v67_get_text_font_size(source_widget)))
        except Exception:
            pass
        txt.insert("1.0", _v67_textbox_content(source_widget))

        def sync_from_main():
            _v67_set_textbox_content(txt, _v67_textbox_content(source_widget))

        def sync_to_main():
            _v67_set_textbox_content(source_widget, _v67_textbox_content(txt))
            try:
                gui.set_status(f"{title} synced back from popout.")
            except Exception:
                pass

        def save_as():
            path = filedialog.asksaveasfilename(title=f"Save {title}", initialfile=_v35_safe_name(title) + ".txt", defaultextension=".txt", filetypes=[("Text", "*.txt"), ("Markdown", "*.md"), ("All files", "*.*")])
            if path:
                Path(path).write_text(_v67_textbox_content(txt), encoding="utf-8")
                try:
                    gui.set_status(f"Saved {title}: {path}")
                except Exception:
                    pass

        for label, cmd, tip in [
            ("Close", win.destroy, "Close this popout window."),
            ("Save as", save_as, "Save the current popout text to a text or markdown file."),
            ("Sync back", sync_to_main, "Copy the edited popout text back into the main FaradaIQ text box."),
            ("Sync from main", sync_from_main, "Reload this popout from the main FaradaIQ text box."),
            ("A+", lambda: _v67_adjust_text_font(txt, +1), "Increase the font size in this popout window."),
            ("A−", lambda: _v67_adjust_text_font(txt, -1), "Decrease the font size in this popout window."),
        ]:
            b = ttk.Button(top, text=label, command=cmd)
            b.pack(side="right", padx=(4, 0))
            try:
                _v66_add_tooltip(b, tip)
            except Exception:
                pass
        win.lift()
    except Exception as exc:
        messagebox.showerror("Popout failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


def _v67_add_textbox_toolbar(gui, widget_attr, title, wrap="word"):
    try:
        widget = getattr(gui, widget_attr, None)
        if widget is None or getattr(widget, "_faradaiq_popout_toolbar_added", False):
            return
        parent = widget.master
        bar = ttk.Frame(parent, style="Card.TFrame")
        try:
            bar.pack(fill="x", before=widget, pady=(0, 2))
        except Exception:
            bar.pack(fill="x", pady=(0, 2))

        ttk.Label(bar, text="").pack(side="left", fill="x", expand=True)
        b_pop = ttk.Button(bar, text="↗", width=3, command=lambda: _v67_open_popout_textbox(gui, title, widget, wrap=wrap))
        b_minus = ttk.Button(bar, text="A−", width=4, command=lambda: _v67_adjust_text_font(widget, -1))
        b_plus = ttk.Button(bar, text="A+", width=4, command=lambda: _v67_adjust_text_font(widget, +1))
        b_plus.pack(side="right", padx=(2, 0))
        b_minus.pack(side="right", padx=(2, 0))
        b_pop.pack(side="right", padx=(2, 0))
        _v66_add_tooltip(b_pop, f"Open {title} in a separate editable popout window.")
        _v66_add_tooltip(b_minus, f"Decrease font size in the {title} box.")
        _v66_add_tooltip(b_plus, f"Increase font size in the {title} box.")
        widget._faradaiq_popout_toolbar_added = True
    except Exception:
        pass


