def _v67_patch_branding_widgets(root):
    try:
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass
        for w in walk(root):
            try:
                txt = str(w.cget("text"))
            except Exception:
                continue
            new = txt.replace("Created by Venky Prabhakaran", "Designed by Venky Prabhakaran and powered by LLM")
            if "pyDRTtools module credit: Ciucci Lab" in new:
                new = "pySECCM parser/plot tools credit: Benjamin A Helfrecht • pyDRTtools module credit: Ciucci Lab, https://github.com/ciuccislab/pyDRTtools"
            if new != txt:
                w.configure(text=new)
    except Exception:
        pass


