def _v67_generate_ai_prompt_messages(gui):
    experiment = _v45_current_gui_text(gui.desc_text)
    summary = _v45_current_gui_text(gui.summary_text)
    structure = _v45_current_gui_text(gui.structure_text)
    tree = _v45_file_tree_for_prompt(gui)
    system = (
        "You are an expert electrochemist, scientific-data analyst, and manuscript-planning assistant. "
        "Your task is to write a rigorous AI-analysis prompt for a downstream analyst/LLM. "
        "You must not analyze the data now. You must not invent results. "
        "The prompt you write must enforce scientific rigor, reproducibility, and clear separation between observation, calculation, inference, and speculation."
    )
    user = (
        "Create a publication-quality AI analysis prompt for the electrochemical dataset below.\n\n"
        "The generated prompt must clearly include these sections:\n"
        "1. Experimental workflow reconstruction: infer and list the likely experimental steps from the available metadata and files, while flagging anything uncertain.\n"
        "2. Data-analysis plan: exact steps for CV, EIS, DRT, SECCM/spatial/takedata, OCP, IV/Tafel, and any figures/metadata that exist.\n"
        "3. Scientific-rigor checklist: data integrity checks, parser/output consistency checks, unit checks, replicate/position checks, outlier/artifact checks, and uncertainty handling.\n"
        "4. Quantitative outputs to compute: peak potentials/currents, peak heights, peak areas/charge, scan-rate trends, Nyquist/Bode metrics, DRT peak positions/intensities, and spatial trends when supported.\n"
        "5. Figure/table plan: overlay plots, comparison plots, peak tables, EIS/DRT tables, spatial maps, and manuscript-ready captions.\n"
        "6. Literature comparison plan: instruct the downstream analyst to compare results with relevant peer-reviewed literature and include only DOI-verified references. The prompt must explicitly say not to fabricate citations or DOI links; if a DOI cannot be verified, the reference should be labeled as needing verification and excluded from final claims.\n"
        "7. Interpretation constraints: separate direct observation from inference, identify alternative explanations, avoid overclaiming, and state what additional experiments are needed.\n\n"
        "Return only the prompt text to append; do not return JSON and do not add preamble.\n\n"
        "EXPERIMENTAL DESCRIPTION CURRENT TEXT:\n"
        f"{experiment}\n\nSESSION SUMMARY:\n{summary}\n\nDATA STRUCTURE PREVIEW:\n{structure}\n\nFILE STRUCTURE / EXPORTED OUTPUT TREE:\n{tree}\n"
    )
    return [{"role": "system", "content": system}, {"role": "user", "content": user}]


def _v67_generate_ai_prompt_with_llm(gui):
    win, log = _v63_analysis_progress_window(gui, "Generate AI prompt with LLM")
    try:
        if not getattr(gui, "collection", None) or not getattr(gui.collection, "entries", []):
            messagebox.showwarning("No session loaded", "Load and inspect data first, then generate the LLM scientific prompt.", parent=gui)
            return
        log("[LLM prompt] Progress window is ready.")
        log("[LLM prompt] Preparing rigorous experiment/data-analysis/literature-comparison prompt request...")
        messages = _v67_generate_ai_prompt_messages(gui)
        try:
            _v63_force_redraw(gui, win, loops=3)
        except Exception:
            pass
        def worker():
            try:
                _v66_safe_window_log(gui, log, "[LLM prompt] Calling selected/available LLM backend in background...")
                response, provider = _v37_call_best_llm(messages, max_tokens=3800, temperature=0.12)
                provider_name = provider.get("name", "LLM") if isinstance(provider, dict) else "LLM"
                model_name = provider.get("model", "") if isinstance(provider, dict) else ""
                response = str(response or "").strip()
                if not response:
                    raise RuntimeError("LLM returned an empty response.")
                timestamp = datetime.now().isoformat(timespec="seconds")
                block = (
                    "\n\n==================== LLM-GENERATED AI ANALYSIS PROMPT ====================\n"
                    f"Generated: {timestamp}\nProvider: {provider_name}\nModel: {model_name}\n\n{response}\n"
                    "================== END LLM-GENERATED AI ANALYSIS PROMPT ==================\n"
                )
                def finish():
                    existing = gui.desc_text.get("1.0", "end").rstrip()
                    gui.desc_text.delete("1.0", "end")
                    gui.desc_text.insert("1.0", existing + block if existing else block.lstrip())
                    root = _v37_analysis_root_for_gui(gui)
                    if root:
                        Path(root).mkdir(parents=True, exist_ok=True)
                        (Path(root) / "AI_prompt_current.txt").write_text(gui.desc_text.get("1.0", "end").strip(), encoding="utf-8")
                    log(f"[LLM prompt] Response received from: {provider_name}")
                    log("[LLM prompt] Prompt appended to Experimental description.")
                    try:
                        gui.set_status(f"LLM prompt generated using {provider_name}.")
                    except Exception:
                        pass
                    _v66_update_all_llm_status_widgets()
                gui.after(0, finish)
            except Exception as exc:
                def fail():
                    log(f"[ERROR] LLM prompt generation failed: {exc}")
                    messagebox.showerror("LLM prompt generation failed", f"{exc}\n\nOpen LLM settings, select a provider, and run Ping selected.", parent=gui)
                gui.after(0, fail)
        threading.Thread(target=worker, daemon=True).start()
    except Exception as exc:
        log(f"[ERROR] {exc}")
        messagebox.showerror("LLM prompt generation failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


_v45_generate_ai_prompt_with_llm = _v67_generate_ai_prompt_with_llm
