def _v67_command_batch_with_progress(commands, progress_file, notes=None, title="Auto pySECCM/DRT after export"):
    total = len(commands)
    pf = str(Path(progress_file))
    lines = ["@echo off", "chcp 65001 >nul", f"title {title}", "echo ============================================================", f"echo {title}", "echo ============================================================", "echo.", f'> "{pf}" echo 0 of {total} STARTING Preparing parser commands']
    if notes:
        lines += ["echo.", "echo Auto-run notes:"]
        for n in notes:
            lines.append(f"echo   {str(n).replace('%','%%')}")
        lines.append("echo.")
    for i, (args, cwd) in enumerate(commands, start=1):
        cwd = Path(cwd)
        cmdline = _v19_subprocess.list2cmdline([str(a) for a in args])
        script_label = Path(str(args[1])).name if len(args) > 1 else Path(str(args[0])).name
        safe_label = str(script_label).replace("&", "and").replace("|", "-").replace(">", "-").replace("<", "-").replace("%", "%%")
        lines += [
            f"> \"{pf}\" echo {i} of {total} RUNNING {safe_label}",
            f"echo [{i}/{total}] Working folder:", f"echo {cwd}", f"cd /d {_v19_subprocess.list2cmdline([str(cwd)])}", "echo.", "echo Command:", f"echo {cmdline}", "echo ------------------------------------------------------------", cmdline, "set LAST_EXIT=%ERRORLEVEL%", "echo ------------------------------------------------------------", "echo Exit code: %LAST_EXIT%", f"> \"{pf}\" echo {i} of {total} DONE rc=%LAST_EXIT% {safe_label}", "echo."]
    lines += [f"> \"{pf}\" echo {total} of {total} FINISHED All parser commands finished", "echo All requested commands finished.", "echo This window is intentionally left open so you can inspect errors/output.", "echo.", "pause"]
    return "\n".join(lines) + "\n"


def _v67_start_pyseccm_monitor(gui, progress_file, total):
    try:
        progress_file = Path(progress_file)
        _v67_add_pyseccm_status_bar(gui)
        if hasattr(gui, "_faradaiq_pyseccm_progress"):
            gui._faradaiq_pyseccm_progress.configure(maximum=max(1, int(total)), value=0)
        if hasattr(gui, "_faradaiq_pyseccm_status_var"):
            gui._faradaiq_pyseccm_status_var.set(f"pySECCM parser: launched 0/{total}")
        state = {"last": "", "stable_finished": 0}
        def poll():
            try:
                txt = progress_file.read_text(encoding="utf-8", errors="replace").strip()
            except Exception:
                txt = state["last"]
            if txt:
                state["last"] = txt
                m = re.match(r"(\d+)\s+of\s+(\d+)\s+(\S+)\s*(.*)", txt)
                if m:
                    cur = int(m.group(1)); tot = max(1, int(m.group(2))); phase = m.group(3); detail = m.group(4).strip()
                    if hasattr(gui, "_faradaiq_pyseccm_progress"):
                        gui._faradaiq_pyseccm_progress.configure(maximum=tot, value=min(cur, tot))
                    if hasattr(gui, "_faradaiq_pyseccm_status_var"):
                        gui._faradaiq_pyseccm_status_var.set(f"pySECCM parser: {phase} {cur}/{tot} {detail}")
                    try:
                        gui.set_status(f"pySECCM parser: {phase} {cur}/{tot} {detail}")
                    except Exception:
                        pass
                    if phase.upper() == "FINISHED":
                        state["stable_finished"] += 1
                        if state["stable_finished"] >= 3:
                            return
            gui.after(1500, poll)
        gui.after(600, poll)
    except Exception:
        pass


def _v27_launch_auto_pyseccm_after_export(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    data_dirs = _v27_candidate_plotting_data_dirs(gui, base_name=base_name)
    if not data_dirs:
        raise FileNotFoundError("No generated *_for_plotting_analysis/data folder was found after export.")
    script_root = _v19_default_script_dir_for_gui(gui) or _v19_find_pyseccm_script_root([Path(__file__).resolve().parent]) or str(Path(__file__).resolve().parent / "pyseccm_tools")
    python_exe = _v19_sys.executable
    missing = _v22_missing_modules_for_python(python_exe, kind="all")
    if missing:
        msg = "The auto-run pipeline needs pySECCM/DRT dependencies in the private Python environment.\n\nRepair/install them now?"
        if messagebox.askyesno("Auto-run dependencies", msg, parent=gui):
            _v22_install_dependencies_for_python(python_exe, kind="all", parent=gui)
        raise RuntimeError("Dependencies are missing or being repaired. Run Export again after the dependency window finishes.")
    all_commands, all_notes, folder_reports = [], [], []
    for d in data_dirs:
        try:
            cmds, notes, detected = _v27_build_auto_pyseccm_commands_for_data_dir(d, script_root=script_root, python_exe=python_exe, include_drt=True)
            all_commands.extend(cmds); all_notes.extend(notes)
            folder_reports.append({"data_dir": str(d), "n_commands": len(cmds), "n_cv": len(detected.get("cv", [])), "n_eis": len(detected.get("eis", [])), "n_iv": len(detected.get("iv", [])), "n_ocp": len(detected.get("ocp", [])), "n_drt_dir": len(detected.get("drt_dir", []))})
            try:
                _heka_v14_make_minimal_mplstyle(Path(d))
            except Exception:
                pass
        except Exception as exc:
            all_notes.append(f"Failed to prepare {d}: {exc}")
    if not all_commands:
        detail = "\n".join(all_notes) if all_notes else "No CV/EIS/IV/OCP/DRT files were detected."
        raise RuntimeError("No auto-run commands could be built.\n" + detail)
    try:
        analysis_root = Path(data_dirs[0]).parents[1]
    except Exception:
        analysis_root = Path(data_dirs[0]).parent
    progress_file = analysis_root / "_faradaiq_pyseccm_parser_progress.txt"
    progress_file.write_text(f"0 of {len(all_commands)} QUEUED Parser commands queued\n", encoding="utf-8")
    batch = _v67_command_batch_with_progress(all_commands, progress_file, notes=all_notes, title="Auto parsers + AI bundle + optional Edison handoff")
    bat = _v22_write_bat_and_launch(batch, cwd=Path(data_dirs[0]), prefix="auto_pyseccm_after_export")
    _v67_start_pyseccm_monitor(gui, progress_file, len(all_commands))
    return {"batch": str(bat), "n_commands": len(all_commands), "folders": folder_reports, "script_root": str(script_root), "python_exe": str(python_exe), "progress_file": str(progress_file)}


