# ---- v69 enhancement: nonblocking parser tools, HEKA file repair, richer browser controls ----
APP_TITLE = "FaradaIQ Studio v273"


# ---------- All parser/DRT tools: Run all available should never freeze the GUI ----------

def _v69_write_and_launch_batch(batch_text, cwd, prefix="faradaiq_batch"):
    try:
        folder = Path(tempfile.gettempdir())
    except Exception:
        folder = Path.cwd()
    path = folder / f"{prefix}_{_dt.datetime.now().strftime('%Y%m%d_%H%M%S_%f')}.bat"
    path.write_text(batch_text, encoding="utf-8")
    try:
        os.startfile(str(path))
    except Exception:
        subprocess.Popen(["cmd", "/c", "start", "FaradaIQ parser batch", str(path)], cwd=str(cwd), shell=False)
    return path


def _v69_make_tools_batch(commands, progress_file, notes=None, title="FaradaIQ parser/DRT tools"):
    total = len(commands)
    pf = str(Path(progress_file))
    lines = [
        "@echo off",
        "chcp 65001 >nul",
        f"title {title}",
        "echo ============================================================",
        f"echo {title}",
        "echo ============================================================",
        "echo This command window shows parser progress and errors.",
        "echo The FaradaIQ tools window remains usable.",
        "echo ============================================================",
        "echo.",
        f'> "{pf}" echo 0 of {total} STARTING Preparing parser commands',
    ]
    if notes:
        lines += ["echo.", "echo Notes:"]
        for note in notes:
            lines.append(f"echo   {str(note).replace('%','%%')}")
        lines.append("echo.")
    for i, (args, cwd, label) in enumerate(commands, start=1):
        cwd = Path(cwd)
        cmdline = _v19_subprocess.list2cmdline([str(a) for a in args])
        safe_label = str(label or Path(str(args[1])).name).replace("&", "and").replace("|", "-").replace(">", "-").replace("<", "-").replace("%", "%%")
        lines += [
            f"> \"{pf}\" echo {i} of {total} RUNNING {safe_label}",
            f"echo [{i}/{total}] {safe_label}",
            "echo Working folder:",
            f"echo {cwd}",
            f"cd /d {_v19_subprocess.list2cmdline([str(cwd)])}",
            "echo Command:",
            f"echo {cmdline}",
            "echo ------------------------------------------------------------",
            cmdline,
            "set LAST_EXIT=%ERRORLEVEL%",
            "echo ------------------------------------------------------------",
            "echo Exit code: %LAST_EXIT%",
            f"> \"{pf}\" echo {i} of {total} DONE rc=%LAST_EXIT% {safe_label}",
            "echo.",
        ]
    lines += [
        f"> \"{pf}\" echo {total} of {total} FINISHED All parser/DRT commands finished",
        "echo All requested parser/DRT commands finished.",
        "echo This window is left open so output and errors can be inspected.",
        "pause",
    ]
    return "\n".join(lines) + "\n"


def _v69_collect_tools_commands(win):
    win.detect_files()
    win._ensure_style()
    commands = []
    notes = []
    data_dir = win._data_dir()
    script_root = win._script_dir()
    py = sys.executable

    try:
        cv_script = win._script("parse_CV.py")
        for p in win.files.get("cv", []):
            commands.append(([py, cv_script, p.name, "--plot"], data_dir, f"CV: {p.name}"))
    except Exception as exc:
        notes.append(f"CV skipped: {exc}")

    try:
        eis_script = win._script("parse_EIS.py")
        if win.files.get("pos") and win.files.get("eis"):
            commands.append(([py, eis_script, win.files["pos"].name, win.files["eis"].name, "--plot"], data_dir, "EIS: parse_EIS.py"))
        else:
            notes.append("EIS skipped: position/takedata or EIS file not detected.")
    except Exception as exc:
        notes.append(f"EIS skipped: {exc}")

    try:
        iv_script = win._script("parse_IV.py")
        if win.files.get("pos") and win.files.get("corr") and win.files.get("iv"):
            commands.append(([py, iv_script, win.files["pos"].name, win.files["corr"].name, win.files["iv"].name, "--plot"], data_dir, "IV/Tafel: parse_IV.py"))
        else:
            notes.append("IV/Tafel skipped: position/corr/IV file not detected.")
    except Exception as exc:
        notes.append(f"IV/Tafel skipped: {exc}")

    try:
        ocp_script = win._script("parse_OCP.py")
        if win.files.get("pos") and win.files.get("avg_ocp") and win.files.get("ocp"):
            commands.append(([py, ocp_script, win.files["pos"].name, win.files["avg_ocp"].name, win.files["ocp"].name, "--plot"], data_dir, "OCP: parse_OCP.py"))
        else:
            notes.append("OCP skipped: position/average/full OCP file not detected.")
    except Exception as exc:
        notes.append(f"OCP skipped: {exc}")

    try:
        candidates = [
            script_root / "headless_pyDRTtools" / "pyDRTtools" / "headless_pyDRTtools.py",
            script_root / "pyDRTtools" / "headless_pyDRTtools.py",
            script_root / "headless_pyDRTtools.py",
        ]
        drt_script = next((p for p in candidates if p.exists()), None)
        if drt_script is None:
            notes.append("DRT skipped: headless_pyDRTtools.py was not found.")
        else:
            drt_dir = win.files.get("drt_dir")
            if drt_dir is None:
                for candidate in [data_dir / "Figures" / "Nyquist", data_dir.parent / "DRT_input_csv"]:
                    if candidate.exists():
                        drt_dir = candidate
                        break
            if drt_dir is None:
                notes.append("DRT skipped: no DRT input folder found. Run EIS first or export DRT_input_csv.")
            else:
                commands.append(([py, drt_script, str(drt_dir), "--run_types", "simple", "--plot_types", "eis", "drt", "--export_types", "drt", "--rbf_type", "gaussian"], drt_script.parent, "DRT: headless_pyDRTtools.py"))
    except Exception as exc:
        notes.append(f"DRT skipped: {exc}")
    return commands, notes


def _v69_tools_start_monitor(win, progress_file, total):
    try:
        if not hasattr(win, "_v69_status_var"):
            bar = ttk.Frame(win, padding=(10, 0, 10, 6))
            bar.pack(fill="x")
            win._v69_progress = ttk.Progressbar(bar, mode="determinate", maximum=max(1, total), length=240)
            win._v69_progress.pack(side="left", padx=(0, 8))
            win._v69_status_var = tk.StringVar(value="Parser/DRT tools: idle")
            ttk.Label(bar, textvariable=win._v69_status_var).pack(side="left", fill="x", expand=True)
        win._v69_progress.configure(maximum=max(1, total), value=0)
        win._v69_status_var.set(f"Parser/DRT tools: launched 0/{total}")
        state = {"last": "", "done_count": 0}
        progress_file = Path(progress_file)
        def poll():
            try:
                txt = progress_file.read_text(encoding="utf-8", errors="replace").strip()
            except Exception:
                txt = state["last"]
            if txt:
                state["last"] = txt
                m = re.match(r"(\d+)\s+of\s+(\d+)\s+(\S+)\s*(.*)", txt)
                if m:
                    cur = int(m.group(1)); tot = max(1, int(m.group(2))); phase = m.group(3); detail = m.group(4).strip()
                    try:
                        win._v69_progress.configure(maximum=tot, value=min(cur, tot))
                    except Exception:
                        pass
                    try:
                        win._v69_status_var.set(f"Parser/DRT tools: {phase} {cur}/{tot} {detail}")
                    except Exception:
                        pass
                    try:
                        win.log(f"[status] {phase} {cur}/{tot} {detail}")
                    except Exception:
                        pass
                    if phase.upper() == "FINISHED":
                        state["done_count"] += 1
                        if state["done_count"] >= 3:
                            return
            try:
                win.after(1500, poll)
            except Exception:
                pass
        win.after(700, poll)
    except Exception:
        pass


def _v69_run_all_available_nonblocking(self):
    try:
        commands, notes = _v69_collect_tools_commands(self)
        if not commands:
            self.log("No parser/DRT commands were available.")
            for n in notes:
                self.log("  " + str(n))
            messagebox.showinfo("No parser/DRT commands", "No compatible CV/EIS/IV/OCP/DRT files were detected.\n\nSee the tool log for details.", parent=self)
            return
        progress_file = self._data_dir() / "_faradaiq_all_parser_drt_tools_progress.txt"
        progress_file.write_text(f"0 of {len(commands)} QUEUED Parser/DRT commands queued\n", encoding="utf-8")
        batch = _v69_make_tools_batch(commands, progress_file, notes=notes, title="FaradaIQ All parser/DRT tools")
        bat = _v69_write_and_launch_batch(batch, self._data_dir(), prefix="faradaiq_all_parser_drt_tools")
        self.log(f"Launched {len(commands)} parser/DRT commands in a separate command window.")
        self.log(f"Batch file: {bat}")
        self.log(f"Progress marker: {progress_file}")
        if notes:
            self.log("Notes/skipped items:")
            for n in notes:
                self.log("  " + str(n))
        _v69_tools_start_monitor(self, progress_file, len(commands))
    except Exception as exc:
        self.log(f"Run all available failed: {exc}")
        messagebox.showerror("Run all available failed", f"{exc}\n\n{traceback.format_exc()}", parent=self)

try:
    SECCMPlotRunnerGUI.run_all_available = _v69_run_all_available_nonblocking
except Exception:
    pass


# ---------- HEKA file repair window ----------

def _v69_natural_sort_key(p):
    s = Path(p).name
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", s)]


def _v69_detect_heka_parts(folder):
    folder = Path(folder)
    files = [p for p in folder.iterdir() if p.is_file()]
    # Split outputs and common chunk names.
    candidates = []
    for p in files:
        low = p.name.lower()
        if low.endswith((".dat", ".pul", ".pgf", ".amp", ".mrk", ".mth", ".onl", ".bin", ".part", ".001", ".002", ".003")) or "part" in low or "split" in low:
            candidates.append(p)
    return sorted(candidates, key=_v69_natural_sort_key)


class FaradaIQHEKARepairWindow(tk.Toplevel):
    def __init__(self, gui):
        super().__init__(gui)
        self.gui = gui
        self.title("HEKA file repair / split-file joiner")
        self.geometry("980x700")
        self.folder_var = tk.StringVar(value=str(Path(gui.output_dir_var.get().strip() or ".").resolve()))
        self.output_var = tk.StringVar(value=str(Path(gui.output_dir_var.get().strip() or ".").resolve()))
        self.basename_var = tk.StringVar(value="repaired_HEKA_bundle.dat")
        self.parts = []
        self._build_ui()
        self.scan()

    def _build_ui(self):
        outer = ttk.Frame(self, padding=(12, 12))
        outer.pack(fill="both", expand=True)
        ttk.Label(outer, text="HEKA file repair", style="Section.TLabel").pack(anchor="w")
        ttk.Label(
            outer,
            text=(
                "Use this when a HEKA/POTMASTER/PATCHMASTER bundle was split into multiple chunk files, or when you need to inspect and rejoin split parts. "
                "Select the folder containing the split files, review the detected order, choose an output folder/name, then click Repair/join selected parts. "
                "The original files are not modified."
            ),
            style="Muted.TLabel",
            wraplength=900,
        ).pack(anchor="w", pady=(2, 8))

        form = ttk.Frame(outer)
        form.pack(fill="x", pady=(0, 8))
        form.columnconfigure(1, weight=1)
        ttk.Label(form, text="Folder with split files").grid(row=0, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=self.folder_var).grid(row=0, column=1, sticky="ew", pady=3)
        ttk.Button(form, text="Browse", command=self.browse_folder).grid(row=0, column=2, padx=(8, 0), pady=3)
        ttk.Label(form, text="Output folder").grid(row=1, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=self.output_var).grid(row=1, column=1, sticky="ew", pady=3)
        ttk.Button(form, text="Browse", command=self.browse_output).grid(row=1, column=2, padx=(8, 0), pady=3)
        ttk.Label(form, text="Output repaired .dat name").grid(row=2, column=0, sticky="w", padx=(0, 8), pady=3)
        ttk.Entry(form, textvariable=self.basename_var).grid(row=2, column=1, sticky="ew", pady=3)

        btns = ttk.Frame(outer)
        btns.pack(fill="x", pady=(0, 8))
        ttk.Button(btns, text="Scan folder", command=self.scan).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Repair/join selected parts", command=self.repair_join).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Open output folder", command=lambda: os.startfile(self.output_var.get())).pack(side="left", padx=(0, 6))
        ttk.Button(btns, text="Close", command=self.destroy).pack(side="right")

        self.tree = ttk.Treeview(outer, columns=("use", "size", "path"), show="headings", selectmode="extended", height=14)
        for col, title, width in [("use", "Order", 80), ("size", "Size", 120), ("path", "Detected split file path"),]:
            self.tree.heading(col, text=title)
        self.tree.column("use", width=80, stretch=False)
        self.tree.column("size", width=120, stretch=False)
        self.tree.column("path", width=720, stretch=True)
        self.tree.pack(fill="both", expand=True, pady=(0, 8))

        self.log_text = ScrolledText(outer, wrap="word", height=10)
        self.log_text.pack(fill="x")
        try:
            self.log_text.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc", font=("Consolas", 9))
        except Exception:
            pass

    def log(self, msg):
        self.log_text.insert("end", str(msg).rstrip() + "\n")
        self.log_text.see("end")
        self.update_idletasks()

    def browse_folder(self):
        p = filedialog.askdirectory(title="Choose folder containing HEKA split files", initialdir=self.folder_var.get())
        if p:
            self.folder_var.set(p)
            self.scan()

    def browse_output(self):
        p = filedialog.askdirectory(title="Choose output folder for repaired HEKA bundle", initialdir=self.output_var.get())
        if p:
            self.output_var.set(p)

    @staticmethod
    def _size_text(n):
        n = float(n)
        for u in ["B", "KiB", "MiB", "GiB"]:
            if n < 1024:
                return f"{n:.0f} {u}" if u == "B" else f"{n:.2f} {u}"
            n /= 1024
        return f"{n:.2f} TiB"

    def scan(self):
        self.tree.delete(*self.tree.get_children())
        self.parts = _v69_detect_heka_parts(self.folder_var.get())
        self.log(f"Scanned: {self.folder_var.get()}")
        self.log(f"Detected {len(self.parts)} possible split/HEKA part files.")
        for i, p in enumerate(self.parts, start=1):
            try:
                self.tree.insert("", "end", iid=str(i-1), values=(i, self._size_text(p.stat().st_size), str(p)))
            except Exception:
                pass
        if self.parts:
            for iid in self.tree.get_children():
                self.tree.selection_add(iid)

    def repair_join(self):
        selected = self.tree.selection()
        if not selected:
            messagebox.showwarning("No parts selected", "Select one or more split parts to join.", parent=self)
            return
        parts = [self.parts[int(iid)] for iid in selected]
        parts = sorted(parts, key=_v69_natural_sort_key)
        outdir = Path(self.output_var.get()).resolve()
        outdir.mkdir(parents=True, exist_ok=True)
        outname = self.basename_var.get().strip() or "repaired_HEKA_bundle.dat"
        if not outname.lower().endswith(".dat"):
            outname += ".dat"
        out = outdir / outname
        if out.exists() and not messagebox.askyesno("Overwrite?", f"Output exists:\n{out}\n\nOverwrite it?", parent=self):
            return
        manifest = outdir / (Path(outname).stem + "_repair_manifest.json")
        self.log("Starting repair/join operation.")
        self.log(f"Output: {out}")
        try:
            total = 0
            with open(out, "wb") as dst:
                for i, p in enumerate(parts, start=1):
                    self.log(f"[{i}/{len(parts)}] Appending: {p.name}")
                    with open(p, "rb") as src:
                        shutil.copyfileobj(src, dst, length=1024 * 1024 * 16)
                    total += p.stat().st_size
                    self.update_idletasks()
            data = {
                "created": datetime.now().isoformat(timespec="seconds"),
                "operation": "HEKA file repair / split-file join",
                "input_folder": self.folder_var.get(),
                "output_file": str(out),
                "output_size_bytes": out.stat().st_size,
                "parts": [{"order": i, "path": str(p), "size_bytes": p.stat().st_size} for i, p in enumerate(parts, start=1)],
                "note": "Original files were not modified. This operation concatenates selected parts in natural filename order.",
            }
            manifest.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
            self.log("Repair/join complete.")
            self.log(f"Manifest: {manifest}")
            try:
                self.gui.set_status(f"HEKA repair complete: {out}")
            except Exception:
                pass
            messagebox.showinfo("HEKA repair complete", f"Created:\n{out}\n\nManifest:\n{manifest}", parent=self)
        except Exception as exc:
            self.log(f"[ERROR] {exc}")
            messagebox.showerror("HEKA repair failed", f"{exc}\n\n{traceback.format_exc()}", parent=self)


def _v69_open_heka_file_repair(gui):
    win = FaradaIQHEKARepairWindow(gui)
    win.lift()


def _v69_patch_heka_repair_button(gui):
    try:
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass
        for w in walk(gui):
            try:
                txt = str(w.cget("text"))
            except Exception:
                continue
            if "Split HEKA" in txt:
                w.configure(text="HEKA file repair", command=lambda g=gui: _v69_open_heka_file_repair(g))
                _v66_add_tooltip(w, "Open HEKA file repair tools. Use this to inspect and rejoin HEKA/POTMASTER split-part files without modifying originals.")
    except Exception:
        pass

SessionReaderGUI.split_heka_bundle_outputs = lambda self: _v69_open_heka_file_repair(self)


# ---------- Data browser: reset, view list, axis controls, technique-aware plotting ----------

def _v69_extract_xy(df, mode, x_choice=None, y_choice=None):
    import pandas as _pd
    cols = list(df.columns)
    numeric = _v64_numeric_columns(df)
    def num(c):
        return _pd.to_numeric(df[c], errors="coerce").to_numpy(dtype=float)
    if x_choice and y_choice and x_choice in cols and y_choice in cols:
        x = num(x_choice); y = num(y_choice)
        return x, y, str(x_choice), str(y_choice), "Custom axis"
    low = {c: str(c).lower() for c in cols}
    def find(words):
        for c in numeric:
            lc = low.get(c, str(c).lower())
            if any(w in lc for w in words):
                return c
        return None
    mode_l = str(mode or "").lower()
    if "eis" in mode_l or "nyquist" in mode_l or "bode" in mode_l:
        freq = find(["freq", "frequency", "hz"])
        zr = find(["zreal", "z_real", "z'", "real"])
        zi = find(["zimag", "z_imag", "z''", "imag"])
        mag = find(["mag", "|z|", "zmod", "modulus", "abs"])
        phase = find(["phase", "angle"])
        if "bode phase" in mode_l:
            xcol = freq or (numeric[0] if numeric else None)
            if phase:
                return num(xcol), num(phase), str(xcol), str(phase), "Bode phase"
            if zr and zi:
                x = num(xcol); y = np.degrees(np.arctan2(num(zi), num(zr)))
                return x, y, str(xcol), "phase_deg(arctan2(Zimag,Zreal))", "Bode phase calculated"
        if "bode" in mode_l:
            xcol = freq or (numeric[0] if numeric else None)
            if mag:
                return num(xcol), num(mag), str(xcol), str(mag), "Bode magnitude"
            if zr and zi:
                x = num(xcol); y = np.sqrt(num(zr)**2 + num(zi)**2)
                return x, y, str(xcol), "|Z|_calculated", "Bode magnitude calculated"
        if zr and zi:
            x = num(zr); y = num(zi)
            yname = str(zi)
            if "raw" not in mode_l:
                y = -y
                yname = "-" + yname
            return x, y, str(zr), yname, "EIS Nyquist"
    if "ocp" in mode_l:
        x = find(["time", "s"]) or (numeric[0] if numeric else None)
        y = find(["potential", "voltage", "ocp", "ewe"]) or (numeric[1] if len(numeric)>1 else None)
        if x and y:
            return num(x), num(y), str(x), str(y), "OCP"
    if "tafel" in mode_l or "iv" in mode_l:
        x = find(["potential", "voltage", "ewe", "e/v", "v"]) or (numeric[0] if numeric else None)
        y = find(["log", "current", "i/", "amp", "ma", "ua", "na"]) or (numeric[1] if len(numeric)>1 else None)
        if x and y:
            return num(x), num(y), str(x), str(y), "IV/Tafel"
    # CV/LSV/general
    x = find(["potential", "voltage", "ewe", "e/v", "v"]) or (numeric[0] if numeric else None)
    y = find(["current", "i/", "i_", "amp", "ma", "ua", "na"]) or (numeric[1] if len(numeric)>1 else None)
    if x and y:
        return num(x), num(y), str(x), str(y), "CV/LSV or numeric"
    return np.array([]), np.array([]), "", "", "No numeric axis pair"


def _v69_browser_reset(self):
    try:
        self.clear_plot()
    except Exception:
        pass
    try:
        self.comp_list.delete(0, "end")
        self.suggestions = []
    except Exception:
        pass
    try:
        if hasattr(self, "plot_view_list"):
            self.plot_view_list.delete(0, "end")
        self._v69_plot_views = []
    except Exception:
        pass
    try:
        self.results_tree.delete(*self.results_tree.get_children())
    except Exception:
        pass
    try:
        self.x_axis_var.set("")
        self.y_axis_var.set("")
        self.plot_mode_var.set("Auto")
        self.normalize_var.set("None")
        self.invert_y_var.set(False); self.logx_var.set(False); self.logy_var.set(False)
    except Exception:
        pass
    self.log("Reset plots, plot views, AI comparison suggestions, and peak/result table.")


def _v69_update_axis_choices(self):
    try:
        paths = self.selected_paths(plottable_only=True)
        if not paths:
            return
        df = _v64_read_table_file(paths[0], max_rows=1000)
        cols = [str(c) for c in df.columns]
        if hasattr(self, "x_axis_box"):
            self.x_axis_box.configure(values=[""] + cols)
        if hasattr(self, "y_axis_box"):
            self.y_axis_box.configure(values=[""] + cols)
    except Exception:
        pass


_V69_PREV_PREVIEW_SELECTED = FaradaIQDataBrowser.preview_selected

def _v69_preview_selected(self):
    _V69_PREV_PREVIEW_SELECTED(self)
    _v69_update_axis_choices(self)


def _v69_plot_file(self, path, clear=False):
    if self.ax is None:
        return
    df = _v64_read_table_file(path)
    mode = self.plot_mode_var.get()
    x_choice = getattr(self, "x_axis_var", tk.StringVar(value="")).get() if hasattr(self, "x_axis_var") else ""
    y_choice = getattr(self, "y_axis_var", tk.StringVar(value="")).get() if hasattr(self, "y_axis_var") else ""
    x, y, xcol, ycol, detected = _v69_extract_xy(df, mode, x_choice=x_choice, y_choice=y_choice)
    mask = np.isfinite(x) & np.isfinite(y)
    x = np.asarray(x, dtype=float)[mask]
    y = np.asarray(y, dtype=float)[mask]
    if len(x) < 2:
        self.log(f"Not enough numeric data in {Path(path).name}")
        return
    y = self._apply_normalization(y, x)
    if clear:
        self.clear_plot()
    label = _v64_curve_label(path, xcol=xcol, ycol=ycol)
    self.ax.plot(x, y, marker="o" if len(x) <= 200 else None, linewidth=1.6, markersize=3, label=label)
    self.ax.set_xlabel(str(xcol))
    self.ax.set_ylabel(str(ycol))
    self.ax.set_title(mode + " overlay")
    self.last_plot_paths.append(Path(path))
    self.curves.append({"path": Path(path), "x": x, "y": y, "xcol": xcol, "ycol": ycol, "label": label})
    self._finish_plot_axes()
    self.log(f"Plotted {Path(path).name}: {detected}")


def _v69_store_current_view(self, name=None):
    try:
        if not getattr(self, "curves", None):
            return
        if not hasattr(self, "_v69_plot_views"):
            self._v69_plot_views = []
        view = {
            "name": name or f"{len(self._v69_plot_views)+1:02d} {self.plot_mode_var.get()} ({len(self.curves)} curves)",
            "mode": self.plot_mode_var.get(),
            "curves": [
                {k: (np.array(v).copy() if k in {"x","y"} else v) for k, v in c.items()}
                for c in self.curves
            ],
        }
        self._v69_plot_views.append(view)
        if hasattr(self, "plot_view_list"):
            self.plot_view_list.insert("end", view["name"])
    except Exception:
        pass


def _v69_load_plot_view(self, _event=None):
    try:
        if not hasattr(self, "plot_view_list") or not getattr(self, "_v69_plot_views", None):
            return
        sel = self.plot_view_list.curselection()
        if not sel:
            return
        view = self._v69_plot_views[sel[0]]
        self.clear_plot()
        self.plot_mode_var.set(view.get("mode", "Auto"))
        for c in view.get("curves", []):
            self.ax.plot(c["x"], c["y"], linewidth=1.6, label=c.get("label", "curve"))
            self.curves.append(c)
        self.ax.set_title(view.get("name", "Saved plot view"))
        self._finish_plot_axes()
        self.log(f"Loaded saved plot/view: {view.get('name')}")
    except Exception as exc:
        self.log(f"Could not load plot view: {exc}")


_V69_PREV_PLOT_SELECTED = FaradaIQDataBrowser.plot_selected

def _v69_plot_selected(self, clear=True):
    _V69_PREV_PLOT_SELECTED(self, clear=clear)
    _v69_store_current_view(self)


def _v69_auto_replot(self, *args):
    try:
        if getattr(self, "_v69_in_replot", False):
            return
        paths = getattr(self, "last_plot_paths", []) or self.selected_paths(plottable_only=True)
        if not paths:
            return
        self._v69_in_replot = True
        self.clear_plot()
        for p in paths:
            try:
                self._plot_file(p, clear=False)
            except Exception as exc:
                self.log(f"Auto-update plot failed for {Path(p).name}: {exc}")
        self._finish_plot_axes()
    finally:
        try:
            self._v69_in_replot = False
        except Exception:
            pass


def _v69_ai_suggest_comparisons(self):
    # Use the old LLM call, then rank/fill the plot view list-like comparison box.
    try:
        structure = self._data_structure_for_llm()
        messages = [
            {"role": "system", "content": (
                "You are an electrochemistry data-analysis planner. "
                "Rank all useful comparisons and plots from most important to least important. "
                "Use only the available FaradaIQ file structure. Do not invent results. "
                "Return 12 to 25 concise one-line suggestions. Prefix each line with a rank number and an importance label: Critical, High, Medium, or Exploratory."
            )},
            {"role": "user", "content": structure},
        ]
        self.log("Sending data structure to selected LLM for ranked comparison suggestions...")
        content, provider = _v37_call_best_llm(messages, max_tokens=2400, temperature=0.1)
        raw_lines = [ln.strip(" -•\t") for ln in str(content).splitlines() if ln.strip()]
        suggestions = []
        for ln in raw_lines:
            ln = re.sub(r"^\d+[\).\s-]+", "", ln).strip()
            if len(ln) > 8:
                suggestions.append(ln)
        self.suggestions = suggestions[:30]
        self.comp_list.delete(0, "end")
        for s in self.suggestions:
            self.comp_list.insert("end", s)
        self.log(f"AI filled {len(self.suggestions)} ranked comparison suggestions.")
        out = self.analyzed_root / "comparison_tables" / "ai_ranked_suggested_comparisons.txt"
        out.write_text("\n".join(self.suggestions), encoding="utf-8")
    except Exception as exc:
        self.log(f"AI suggestion failed: {exc}")
        messagebox.showerror("AI-suggested comparisons failed", f"{exc}\n\nOpen LLM settings and ping/select a backend first.", parent=self)


_V69_PREV_BROWSER_BUILD_UI = FaradaIQDataBrowser._build_ui

def _v69_browser_build_ui(self):
    _V69_PREV_BROWSER_BUILD_UI(self)

    # Add reset button and popout controls to top if possible.
    try:
        top = self.winfo_children()[0]
        b = ttk.Button(top, text="Reset browser", command=lambda: _v69_browser_reset(self))
        b.pack(side="left", padx=(10, 5))
        _v66_add_tooltip(b, "Reset plots, saved plot views, AI comparison suggestions, and peak/result tables for this browser session.")
    except Exception:
        pass

    # Add plot/view list near data tree and comparison list.
    try:
        left = self.comp_list.master.master
        ttk.Label(left, text="Plot/view list", style="Section.TLabel").pack(anchor="w", pady=(8, 2))
        pv_frame = ttk.Frame(left, style="Card.TFrame")
        pv_frame.pack(fill="x", pady=(0, 6))
        self.plot_view_list = tk.Listbox(pv_frame, height=6, exportselection=False)
        self.plot_view_list.pack(side="left", fill="both", expand=True)
        pvs = ttk.Scrollbar(pv_frame, orient="vertical", command=self.plot_view_list.yview)
        self.plot_view_list.configure(yscrollcommand=pvs.set)
        pvs.pack(side="right", fill="y")
        self.plot_view_list.bind("<<ListboxSelect>>", lambda e: _v69_load_plot_view(self, e))
        self._v69_plot_views = []
        _v66_add_tooltip(self.plot_view_list, "Each time you plot/overlay, FaradaIQ saves a view here. Click a saved view to restore it without selecting files again.")
    except Exception:
        pass

    # Add technique-aware axis controls.
    try:
        right = self.results_tree.master.master
        ctrl = ttk.LabelFrame(right, text="Axis / technique controls", padding=(6, 5))
        try:
            ctrl.pack(fill="x", before=self.results_tree.master, pady=(0, 8))
        except Exception:
            ctrl.pack(fill="x", pady=(0, 8))
        self.x_axis_var = tk.StringVar(value="")
        self.y_axis_var = tk.StringVar(value="")
        ttk.Label(ctrl, text="X axis").grid(row=0, column=0, sticky="w", padx=(0, 5), pady=2)
        self.x_axis_box = ttk.Combobox(ctrl, textvariable=self.x_axis_var, values=[""], state="readonly", width=24)
        self.x_axis_box.grid(row=0, column=1, sticky="ew", pady=2)
        ttk.Label(ctrl, text="Y axis").grid(row=1, column=0, sticky="w", padx=(0, 5), pady=2)
        self.y_axis_box = ttk.Combobox(ctrl, textvariable=self.y_axis_var, values=[""], state="readonly", width=24)
        self.y_axis_box.grid(row=1, column=1, sticky="ew", pady=2)
        ctrl.columnconfigure(1, weight=1)
        modes = ["Auto", "CV / LSV", "EIS Nyquist (-Zimag)", "EIS Nyquist raw Zimag", "Bode magnitude", "Bode phase", "OCP", "IV / Tafel", "DRT", "Numeric"]
        try:
            self.plot_mode.configure(values=modes)
        except Exception:
            pass
        for var in [self.x_axis_var, self.y_axis_var, self.plot_mode_var, self.normalize_var, self.invert_y_var, self.logx_var, self.logy_var]:
            try:
                var.trace_add("write", lambda *_: _v69_auto_replot(self))
            except Exception:
                pass
        _v66_add_tooltip(ctrl, "Change plot mode and axis choices. Changes apply immediately to the current plot without an Apply button.")
    except Exception:
        pass

    # Popout button for boxes in browser.
    try:
        # Main log popout
        b = ttk.Button(self.log_text.master, text="↗ Browser log popout", command=lambda: _v67_open_popout_textbox(self, "Browser log", self.log_text, wrap="word"))
        b.pack(anchor="e", pady=(2, 0))
    except Exception:
        pass

    try:
        _v66_apply_tooltips(self)
    except Exception:
        pass


FaradaIQDataBrowser._build_ui = _v69_browser_build_ui
FaradaIQDataBrowser._plot_file = _v69_plot_file
FaradaIQDataBrowser.plot_selected = _v69_plot_selected
FaradaIQDataBrowser.preview_selected = _v69_preview_selected
