# ---- v70 enhancement: QA-driven browser/media/EIS fixes and richer comparison fallback ----
APP_TITLE = "FaradaIQ Studio v273"

_V70_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".gif", ".webp"}
_V70_VIDEO_EXTS = {".mp4", ".avi", ".mov", ".mkv", ".wmv", ".mpeg", ".mpg", ".m4v"}
_V70_TABLE_EXTS = {".csv", ".txt", ".asc", ".tsv", ".xlsx", ".xls"}


# ---------- Media and browser tree organization ----------

_V70_PREV_DETECT_FILE_KIND = _v64_detect_file_kind

def _v64_detect_file_kind(path):
    p = Path(path)
    suf = p.suffix.lower()
    if suf in _V70_IMAGE_EXTS:
        return "Photos / images"
    if suf in _V70_VIDEO_EXTS:
        return "Movies / video"
    return _V70_PREV_DETECT_FILE_KIND(path)


def _v70_media_paths(paths):
    return [Path(p) for p in paths if Path(p).suffix.lower() in (_V70_IMAGE_EXTS | _V70_VIDEO_EXTS)]


def _v70_table_paths(paths):
    return [Path(p) for p in paths if Path(p).suffix.lower() in _V70_TABLE_EXTS]


def _v70_browser_refresh_tree(self):
    try:
        self.tree.delete(*self.tree.get_children())
    except Exception:
        pass
    self._path_by_iid = {}
    self._group_iids = {}
    groups = [
        "CV / LSV", "EIS", "DRT", "OCP", "IV / Tafel", "SECCM position / takedata",
        "Photos / images", "Movies / video", "Figures", "Tables / text", "Metadata JSON", "NumPy payload", "Other"
    ]
    for g in groups:
        iid = self.tree.insert("", "end", text=g, values=(g, ""), open=(g in {"CV / LSV", "EIS", "DRT", "Photos / images"}))
        self._group_iids[g] = iid
    if not self.analysis_root.exists():
        self.log(f"Analysis root does not exist: {self.analysis_root}")
        return
    include_exts = _V70_TABLE_EXTS | _V70_IMAGE_EXTS | _V70_VIDEO_EXTS | {".json", ".npy", ".npz", ".svg", ".pdf", ".h5", ".hdf5"}
    count = 0
    for p in sorted(self.analysis_root.rglob("*"), key=lambda x: str(x).lower()):
        try:
            if not p.is_file() or p.suffix.lower() not in include_exts:
                continue
            rel = p.relative_to(self.analysis_root).as_posix()
            if f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" in rel:
                continue
            kind = _v64_detect_file_kind(p)
            group = kind if kind in self._group_iids else "Other"
            size = p.stat().st_size
            label = rel
            if len(label) > 105:
                label = "..." + label[-102:]
            iid = self.tree.insert(self._group_iids[group], "end", text=label, values=(kind, self._format_size(size)))
            self._path_by_iid[iid] = p
            count += 1
        except Exception:
            pass
    self.log(f"Indexed {count} analysis/media files.")


def _v70_browser_selected_paths(self, plottable_only=True):
    out = []
    for iid in self.tree.selection():
        p = self._path_by_iid.get(iid)
        if p is None:
            continue
        if plottable_only and p.suffix.lower() not in (_V70_TABLE_EXTS | _V70_IMAGE_EXTS | _V70_VIDEO_EXTS):
            continue
        out.append(p)
    return out


# ---------- EIS/technique-aware axis extraction ----------

def _v70_extract_xy(df, mode, x_choice=None, y_choice=None):
    import pandas as _pd
    cols = list(df.columns)
    numeric = _v64_numeric_columns(df)
    def num(c):
        return _pd.to_numeric(df[c], errors="coerce").to_numpy(dtype=float)
    low = {c: str(c).lower() for c in cols}
    def find(words):
        for c in numeric:
            lc = low.get(c, str(c).lower())
            if any(w in lc for w in words):
                return c
        return None
    mode_l = str(mode or "").lower()

    # Manual axes are honored in Numeric or Auto mode. Technique modes use technique-specific formulas.
    if x_choice and y_choice and x_choice in cols and y_choice in cols and (mode_l in {"numeric", "auto", "custom", "manual"}):
        return num(x_choice), num(y_choice), str(x_choice), str(y_choice), "Manual axes"

    freq = find(["freq", "frequency", "hz"])
    zr = find(["zreal", "z_real", "z'", "zre", "real"])
    zi = find(["zimag", "z_imag", "z''", "zim", "imag"])
    mag = find(["|z|", "zmod", "modulus", "magnitude", "mag"])
    phase = find(["phase", "angle"])

    if "bode phase" in mode_l:
        xcol = freq or (numeric[0] if numeric else None)
        if xcol is None:
            return np.array([]), np.array([]), "", "", "Bode phase needs frequency column"
        if phase:
            return num(xcol), num(phase), str(xcol), str(phase), "Bode phase"
        if zr and zi:
            return num(xcol), np.degrees(np.arctan2(num(zi), num(zr))), str(xcol), "phase_deg = atan2(Zimag, Zreal)", "Bode phase calculated"
        return np.array([]), np.array([]), "", "", "Bode phase needs phase or Zreal/Zimag"

    if "bode magnitude" in mode_l or ("bode" in mode_l and "phase" not in mode_l):
        xcol = freq or (numeric[0] if numeric else None)
        if xcol is None:
            return np.array([]), np.array([]), "", "", "Bode magnitude needs frequency column"
        if zr and zi:
            return num(xcol), np.sqrt(num(zr)**2 + num(zi)**2), str(xcol), "|Z| = sqrt(Zreal^2 + Zimag^2)", "Bode magnitude calculated from Zreal/Zimag"
        if mag:
            return num(xcol), np.abs(num(mag)), str(xcol), f"|{mag}|", "Bode magnitude column"
        if zi:
            return num(xcol), np.abs(num(zi)), str(xcol), f"|{zi}| (Zreal missing)", "Approximate magnitude from Zimag only; Zreal column missing"
        return np.array([]), np.array([]), "", "", "Bode magnitude needs Zreal/Zimag or |Z|"

    if "nyquist" in mode_l or "eis" in mode_l:
        if zr and zi:
            y = num(zi)
            yname = str(zi)
            if "raw" not in mode_l:
                y = -y
                yname = "-" + yname
            return num(zr), y, str(zr), yname, "EIS Nyquist"
        return np.array([]), np.array([]), "", "", "Nyquist needs Zreal/Zimag columns"

    if "ocp" in mode_l:
        x = find(["time", "time_s", "seconds", "s"]) or (numeric[0] if numeric else None)
        y = find(["potential", "voltage", "ocp", "ewe"]) or (numeric[1] if len(numeric)>1 else None)
        if x and y:
            return num(x), num(y), str(x), str(y), "OCP"

    if "tafel" in mode_l or "iv" in mode_l:
        x = find(["potential", "voltage", "ewe", "e/v", "v"]) or (numeric[0] if numeric else None)
        y = find(["log", "current", "i/", "amp", "ma", "ua", "na"]) or (numeric[1] if len(numeric)>1 else None)
        if x and y:
            return num(x), num(y), str(x), str(y), "IV/Tafel"

    if "drt" in mode_l:
        x = find(["tau", "time", "freq", "frequency"])
        y = find(["gamma", "drt", "resistance", "g("])
        if x and y:
            return num(x), num(y), str(x), str(y), "DRT"

    # Auto selection: choose technique-specific by filename columns if possible.
    if zr and zi and freq:
        return num(zr), -num(zi), str(zr), f"-{zi}", "Auto EIS Nyquist"
    x = find(["potential", "voltage", "ewe", "e/v", "v"]) or find(["time", "time_s", "seconds"]) or freq or (numeric[0] if numeric else None)
    y = find(["current", "i/", "i_", "amp", "ma", "ua", "na"]) or find(["potential", "voltage", "ocp"]) or (numeric[1] if len(numeric)>1 else None)
    if x and y:
        return num(x), num(y), str(x), str(y), "Auto numeric"
    return np.array([]), np.array([]), "", "", "No numeric axis pair"


def _v70_browser_plot_file(self, path, clear=False):
    if self.ax is None:
        return
    df = _v64_read_table_file(path)
    mode = self.plot_mode_var.get()
    x_choice = getattr(self, "x_axis_var", tk.StringVar(value="")).get() if hasattr(self, "x_axis_var") else ""
    y_choice = getattr(self, "y_axis_var", tk.StringVar(value="")).get() if hasattr(self, "y_axis_var") else ""
    x, y, xcol, ycol, detected = _v70_extract_xy(df, mode, x_choice=x_choice, y_choice=y_choice)
    mask = np.isfinite(x) & np.isfinite(y)
    x = np.asarray(x, dtype=float)[mask]
    y = np.asarray(y, dtype=float)[mask]
    if len(x) < 2:
        self.log(f"Could not plot {Path(path).name}: {detected}")
        return
    y = self._apply_normalization(y, x)
    if clear:
        self.clear_plot()
    label = _v64_curve_label(path, xcol=xcol, ycol=ycol)
    self.ax.plot(x, y, marker="o" if len(x) <= 200 else None, linewidth=1.6, markersize=3, label=label)
    self.ax.set_xlabel(str(xcol))
    self.ax.set_ylabel(str(ycol))
    self.ax.set_title(str(mode) + " overlay")
    # Bode convention: log frequency x-axis, if values are positive.
    try:
        if "bode" in str(mode).lower() and np.nanmin(x) > 0:
            self.ax.set_xscale("log")
            if "magnitude" in str(mode).lower() and np.nanmin(y) > 0:
                self.ax.set_yscale("log")
    except Exception:
        pass
    self.last_plot_paths.append(Path(path))
    self.curves.append({"path": Path(path), "x": x, "y": y, "xcol": xcol, "ycol": ycol, "label": label})
    self._finish_plot_axes()
    self.log(f"Plotted {Path(path).name}: {detected}")


# ---------- Photo/movie display ----------

def _v70_load_media_frame(path):
    p = Path(path)
    suf = p.suffix.lower()
    if suf in _V70_IMAGE_EXTS:
        from PIL import Image, ImageSequence
        im = Image.open(p)
        try:
            if getattr(im, "is_animated", False):
                im = next(ImageSequence.Iterator(im))
        except Exception:
            pass
        return np.asarray(im.convert("RGB")), "image"
    if suf in _V70_VIDEO_EXTS:
        # Try optional libraries if present. Otherwise return None; external opening remains available.
        try:
            import imageio.v3 as iio
            frame = iio.imread(str(p), index=0)
            return frame, "video first frame"
        except Exception:
            try:
                import cv2
                cap = cv2.VideoCapture(str(p))
                ok, frame = cap.read()
                cap.release()
                if ok:
                    frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                    return frame, "video first frame"
            except Exception:
                pass
    return None, "unsupported media"


def _v70_display_media_paths(self, paths, index=0):
    if self.ax is None or not paths:
        return
    self._v70_media_paths = [Path(p) for p in paths]
    self._v70_media_index = max(0, min(int(index), len(paths)-1))
    path = self._v70_media_paths[self._v70_media_index]
    self.clear_plot()
    arr, kind = _v70_load_media_frame(path)
    if arr is not None:
        self.ax.imshow(arr)
        self.ax.axis("off")
        self.ax.set_title(f"{kind}: {path.name}  ({self._v70_media_index+1}/{len(paths)})")
        self.canvas.draw_idle()
        self.log(f"Displayed {kind}: {path}")
    else:
        self.ax.axis("off")
        self.ax.text(0.5, 0.55, f"Movie/media selected:\n{path.name}", ha="center", va="center", fontsize=12)
        self.ax.text(0.5, 0.42, "Preview frame unavailable in this Python environment.\nUse 'Open media externally'.", ha="center", va="center", fontsize=10)
        self.ax.set_title(f"Media: {path.name}  ({self._v70_media_index+1}/{len(paths)})")
        self.canvas.draw_idle()
        self.log(f"Media selected; internal preview unavailable: {path}")
    try:
        _v69_store_current_view(self, name=f"Media {self._v70_media_index+1}/{len(paths)}: {path.name}")
    except Exception:
        pass


def _v70_media_prev(self):
    paths = getattr(self, "_v70_media_paths", [])
    if paths:
        idx = (getattr(self, "_v70_media_index", 0) - 1) % len(paths)
        _v70_display_media_paths(self, paths, idx)


def _v70_media_next(self):
    paths = getattr(self, "_v70_media_paths", [])
    if paths:
        idx = (getattr(self, "_v70_media_index", 0) + 1) % len(paths)
        _v70_display_media_paths(self, paths, idx)


def _v70_media_open_external(self):
    paths = getattr(self, "_v70_media_paths", []) or _v70_media_paths(self.selected_paths(plottable_only=True))
    if not paths:
        return
    path = paths[getattr(self, "_v70_media_index", 0) % len(paths)]
    try:
        os.startfile(str(path))
    except Exception:
        try:
            webbrowser.open(Path(path).resolve().as_uri())
        except Exception:
            pass


# ---------- Browser popouts and fallback AI suggestions ----------

def _v70_open_text_snapshot(self, title, lines):
    try:
        win = tk.Toplevel(self)
        win.title(f"{title} — popout")
        win.geometry("850x650")
        outer = ttk.Frame(win, style="Card.TFrame", padding=(10, 10))
        outer.pack(fill="both", expand=True)
        ttk.Label(outer, text=title, style="Section.TLabel").pack(anchor="w")
        txt = ScrolledText(outer, wrap="none")
        txt.pack(fill="both", expand=True, pady=(6, 6))
        try:
            txt.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc", font=("Consolas", 9))
        except Exception:
            pass
        txt.insert("1.0", "\n".join(str(x) for x in lines))
        ttk.Button(outer, text="Close", command=win.destroy).pack(anchor="e")
    except Exception as exc:
        self.log(f"Popout failed: {exc}")


def _v70_browser_popout_data_tree(self):
    lines = []
    try:
        for parent in self.tree.get_children():
            lines.append(str(self.tree.item(parent, "text")))
            for child in self.tree.get_children(parent):
                lines.append("  " + str(self.tree.item(child, "text")))
    except Exception:
        pass
    _v70_open_text_snapshot(self, "Data tree", lines)


def _v70_browser_popout_comparisons(self):
    lines = [self.comp_list.get(i) for i in range(self.comp_list.size())]
    _v70_open_text_snapshot(self, "AI-suggested comparisons", lines)


def _v70_browser_popout_plot_views(self):
    if hasattr(self, "plot_view_list"):
        lines = [self.plot_view_list.get(i) for i in range(self.plot_view_list.size())]
    else:
        lines = []
    _v70_open_text_snapshot(self, "Plot/view list", lines)


def _v70_browser_popout_results(self):
    lines = ["source,type,x,y,height,area"]
    try:
        for iid in self.results_tree.get_children():
            lines.append(",".join(str(x) for x in self.results_tree.item(iid, "values")))
    except Exception:
        pass
    _v70_open_text_snapshot(self, "Peak / measurement results", lines)


def _v70_builtin_comparison_suggestions(self):
    groups = {}
    try:
        for parent in self.tree.get_children():
            g = self.tree.item(parent, "text")
            groups[g] = len(self.tree.get_children(parent))
    except Exception:
        pass
    suggestions = []
    if groups.get("CV / LSV", 0):
        suggestions += [
            "Critical — Overlay CV/LSV curves by position or replicate to compare peak current, onset potential, hysteresis, and background current.",
            "High — Compare anodic/cathodic peak positions and peak-to-peak separation across selected positions/files.",
            "High — Compute baseline-corrected peak height and integrated charge for selected CV peaks.",
        ]
    if groups.get("EIS", 0):
        suggestions += [
            "Critical — Overlay EIS Nyquist (-Zimag vs Zreal) by position to compare semicircle size and diffusion tails.",
            "Critical — Plot Bode magnitude |Z| and Bode phase versus log frequency for all EIS positions.",
            "High — Compare low-frequency impedance, high-frequency intercept, and phase-minimum trends across positions.",
        ]
    if groups.get("DRT", 0):
        suggestions += [
            "High — Overlay DRT spectra and compare relaxation peak position, width, and intensity across positions.",
            "Medium — Compare DRT-derived features with EIS Nyquist/Bode features for consistency.",
        ]
    if groups.get("OCP", 0):
        suggestions.append("Medium — Compare OCP drift versus time across positions/repeats to identify stabilization or transient behavior.")
    if groups.get("IV / Tafel", 0):
        suggestions.append("High — Compare IV/Tafel slopes, exchange-current-like trends, and current asymmetry across positions/files.")
    if groups.get("SECCM position / takedata", 0):
        suggestions += [
            "Critical — Map key CV/EIS metrics versus SECCM position/takedata coordinates.",
            "High — Compare spatially adjacent points to identify local electrochemical heterogeneity.",
        ]
    if groups.get("Photos / images", 0) or groups.get("Movies / video", 0):
        suggestions.append("Medium — Compare optical photos/videos with electrochemical spatial trends and flag visible artifacts or sample changes.")
    suggestions.append("Exploratory — Export selected overlays to Excel/HDF5 for OriginLab and manuscript plotting.")
    return suggestions


def _v70_ai_suggest_comparisons(self):
    # Fill deterministic suggestions immediately; then try LLM for refined ranking.
    builtin = _v70_builtin_comparison_suggestions(self)
    self.suggestions = builtin[:]
    self.comp_list.delete(0, "end")
    for s in self.suggestions:
        self.comp_list.insert("end", s)
    self.log(f"Filled {len(self.suggestions)} built-in ranked comparison suggestions.")
    try:
        structure = self._data_structure_for_llm()
        messages = [
            {"role": "system", "content": (
                "You are an electrochemistry data-analysis planner. "
                "Improve and rank the useful comparisons/plots from most important to least important. "
                "Use only the available FaradaIQ file structure. Do not invent results. "
                "Return 12 to 25 concise one-line suggestions. Prefix each line with an importance label: Critical, High, Medium, or Exploratory."
            )},
            {"role": "user", "content": structure},
        ]
        self.log("Sending data structure to selected LLM for refined ranked comparison suggestions...")
        content, provider = _v37_call_best_llm(messages, max_tokens=2600, temperature=0.1)
        raw_lines = [ln.strip(" -•\t") for ln in str(content).splitlines() if ln.strip()]
        llm_suggestions = []
        for ln in raw_lines:
            ln = re.sub(r"^\d+[\).\s-]+", "", ln).strip()
            if len(ln) > 8:
                llm_suggestions.append(ln)
        combined = []
        for s in llm_suggestions + builtin:
            if s not in combined:
                combined.append(s)
        self.suggestions = combined[:35]
        self.comp_list.delete(0, "end")
        for s in self.suggestions:
            self.comp_list.insert("end", s)
        self.log(f"AI/refined list now contains {len(self.suggestions)} ranked suggestions.")
        out = self.analyzed_root / "comparison_tables" / "ai_ranked_suggested_comparisons.txt"
        out.write_text("\n".join(self.suggestions), encoding="utf-8")
    except Exception as exc:
        self.log(f"LLM refinement unavailable; kept built-in suggestions. Reason: {exc}")


# ---------- Browser method wiring ----------

def _v70_browser_plot_selected(self, clear=True):
    paths = self.selected_paths(plottable_only=True)
    if not paths:
        messagebox.showinfo("No files selected", "Select one or more table, photo, or movie files in the data tree.", parent=self)
        return
    media = _v70_media_paths(paths)
    tables = _v70_table_paths(paths)
    if clear:
        self.clear_plot()
    if tables:
        for p in tables:
            try:
                self._plot_file(p, clear=False)
            except Exception as exc:
                self.log(f"Plot failed for {p.name}: {exc}")
        self._finish_plot_axes()
        try:
            _v69_store_current_view(self)
        except Exception:
            pass
    if media:
        _v70_display_media_paths(self, media, 0)


_V70_PREV_BROWSER_BUILD_UI = FaradaIQDataBrowser._build_ui

def _v70_browser_build_ui(self):
    _V70_PREV_BROWSER_BUILD_UI(self)

    # Add media navigation to the plot toolbar/top region.
    try:
        # Find first frame inside center-like container that has buttons by scanning children.
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass
        target = None
        for w in walk(self):
            try:
                child_texts = [str(c.cget("text")) for c in w.winfo_children() if hasattr(c, "cget")]
            except Exception:
                child_texts = []
            if "Plot selected" in child_texts and "Overlay selected" in child_texts:
                target = w
                break
        if target is not None and not getattr(self, "_v70_media_buttons_added", False):
            ttk.Button(target, text="◀ media", command=lambda: _v70_media_prev(self)).pack(side="left", padx=(10, 4))
            ttk.Button(target, text="media ▶", command=lambda: _v70_media_next(self)).pack(side="left", padx=(0, 4))
            ttk.Button(target, text="Open media externally", command=lambda: _v70_media_open_external(self)).pack(side="left", padx=(0, 4))
            self._v70_media_buttons_added = True
    except Exception:
        pass

    # Popout controls for browser boxes.
    try:
        if not getattr(self, "_v70_browser_popouts_added", False):
            # Put small popout buttons under left panel lists and results/log.
            if hasattr(self, "comp_list"):
                row = ttk.Frame(self.comp_list.master.master, style="Card.TFrame")
                row.pack(fill="x", pady=(2, 6))
                ttk.Button(row, text="↗ Data tree", command=lambda: _v70_browser_popout_data_tree(self)).pack(side="left", padx=(0, 4))
                ttk.Button(row, text="↗ Comparisons", command=lambda: _v70_browser_popout_comparisons(self)).pack(side="left", padx=(0, 4))
                if hasattr(self, "plot_view_list"):
                    ttk.Button(row, text="↗ Plot views", command=lambda: _v70_browser_popout_plot_views(self)).pack(side="left", padx=(0, 4))
            if hasattr(self, "results_tree"):
                ttk.Button(self.results_tree.master.master, text="↗ Results table", command=lambda: _v70_browser_popout_results(self)).pack(fill="x", pady=(3, 0))
            self._v70_browser_popouts_added = True
    except Exception:
        pass

    try:
        _v66_apply_tooltips(self)
    except Exception:
        pass


FaradaIQDataBrowser._build_ui = _v70_browser_build_ui
FaradaIQDataBrowser.refresh_tree = _v70_browser_refresh_tree
FaradaIQDataBrowser.selected_paths = _v70_browser_selected_paths
FaradaIQDataBrowser._plot_file = _v70_browser_plot_file
FaradaIQDataBrowser.plot_selected = _v70_browser_plot_selected
FaradaIQDataBrowser.ai_suggest_comparisons = _v70_ai_suggest_comparisons


