from dataclasses import dataclass, asdict
import importlib.util
import threading


@dataclass
class ElectrochemicalResource:
    name: str
    category: str
    purpose: str
    integration_type: str
    requires_internet: bool
    requires_api_key: bool
    package_name: str
    import_check: str
    documentation_url: str
    supported_data_types: list
    status: str = "planned"
    install_hint: str = ""
    notes: str = ""


@dataclass
class FaradaIQAnalysisEngine:
    name: str
    category: str
    supported_data_types: list
    package_name: str
    import_check: str
    purpose: str
    status: str = "available"
    assumptions: str = ""
    install_hint: str = ""


def _v71_module_available(import_name):
    if not import_name:
        return True, "no Python import required"
    try:
        return (importlib.util.find_spec(import_name) is not None), import_name
    except Exception as exc:
        return False, str(exc)


def _v71_pip_hint(package_name):
    if not package_name:
        return "No pip package is required for this informational/external resource."
    return f'.faradaiq_venv\\Scripts\\python.exe -m pip install {package_name}'


