def _v71_engines():
    return [
        FaradaIQAnalysisEngine("CV analysis", "Core analysis", ["CV"], "", "", "CV plotting, baseline correction guidance, peak detection, ΔEp, ipa/ipc ratio, scan-rate trends.", "available", "Randles–Ševčík estimates require electrode area, concentration, diffusion coefficient, temperature, electron count, and reversible/semireversible assumptions."),
        FaradaIQAnalysisEngine("EIS fitting", "Core analysis", ["EIS"], "impedance", "impedance", "Nyquist/Bode plotting, Rs/Rct estimates, optional equivalent-circuit fitting via impedance.py.", "optional", "Equivalent-circuit parameters are model-dependent and must be reported with circuit topology and units.", _v71_pip_hint("impedance")),
        FaradaIQAnalysisEngine("DRT", "Core analysis", ["EIS", "DRT"], "", "", "Distribution of relaxation times from valid EIS data using bundled/optional DRT tools.", "bundled helper / optional dependency", "DRT requires regularization, relaxation-time grid, residual checks, and careful interpretation."),
        FaradaIQAnalysisEngine("SECCM parsing", "Vendor/SECCM", ["SECCM"], "", "", "pySECCM parser/plot workflow with progress/status integration.", "available", "pySECCM parser/plot tools credit: Benjamin A Helfrecht."),
        FaradaIQAnalysisEngine("HEKA parsing", "Vendor parser", ["HEKA"], "", "", "FaradaIQ HEKA/PotMaster/PatchMaster bundle structure extraction: groups, series, sweeps, channels, traces, and metadata.", "available", "External HEKA readers are optional checks only."),
        FaradaIQAnalysisEngine("BioLogic parsing", "Vendor parser", ["BioLogic"], "eclabfiles", "eclabfiles", "Optional EC-Lab/MPR conversion and metadata extraction.", "optional", "Preserve raw vendor files; save processed data separately.", _v71_pip_hint("eclabfiles")),
        FaradaIQAnalysisEngine("Battery modeling", "Battery", ["Battery"], "pybamm", "pybamm", "Optional battery modeling and battery EIS simulation using PyBaMM.", "optional battery engine", "Only enable for battery workflows; not general CV/EIS interpretation.", _v71_pip_hint("pybamm")),
        FaradaIQAnalysisEngine("Literature comparison", "Reference", ["CV", "EIS", "DRT", "Literature/DOI"], "", "", "LLM prompt builder for DOI-verified literature comparison with missing metadata warnings.", "available", "Never fabricate references or DOI links."),
    ]


def _v71_status_for_resource(res):
    ok, msg = _v71_module_available(res.import_check)
    if res.import_check:
        return ("installed" if ok else "missing"), msg
    if res.status in {"available"}:
        return "available", "built-in FaradaIQ helper"
    return res.status, "external/info resource"


def _v71_write_session_json(path, payload):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


class FaradaIQKnowledgeResourceWindow(tk.Toplevel):
    def __init__(self, browser_or_gui):
        super().__init__(browser_or_gui)
        self.owner = browser_or_gui
        self.analysis_root = getattr(browser_or_gui, "analysis_root", None)
        if self.analysis_root is None:
            try:
                self.analysis_root, _ = _v64_analysis_root_for_browser(browser_or_gui)
            except Exception:
                self.analysis_root = Path.cwd()
        self.analysis_root = Path(self.analysis_root)
        self.base_name = getattr(browser_or_gui, "base_name", self.analysis_root.name.replace("_analysis_ready_csv", ""))
        self.resources = _v71_resources()
        self.context_resources = []
        self.title("Electrochemical Knowledge & Data Sources")
        self.geometry("1220x820")
        self.minsize(980, 640)
        self._build_ui()
        self.refresh()

    def _build_ui(self):
        outer = ttk.Frame(self, style="Card.TFrame", padding=(10, 10))
        outer.pack(fill="both", expand=True, padx=8, pady=8)
        ttk.Label(outer, text="Electrochemical Knowledge & Data Sources", style="Section.TLabel").pack(anchor="w")
        ttk.Label(
            outer,
            text="Curated resources are grouped as Reference Data, Local Analysis Engines, Vendor File Parsers, Battery Materials, and Advanced Instrument APIs. Missing resources never block local FaradaIQ analysis.",
            style="Muted.TLabel",
            wraplength=1120,
        ).pack(anchor="w", pady=(2, 8))

        filter_frame = ttk.LabelFrame(outer, text="Search and filters", padding=(8, 6))
        filter_frame.pack(fill="x", pady=(0, 8))
        self.search_var = tk.StringVar()
        ttk.Label(filter_frame, text="Search").pack(side="left", padx=(0, 6))
        ent = ttk.Entry(filter_frame, textvariable=self.search_var, width=36)
        ent.pack(side="left", padx=(0, 10))
        self.search_var.trace_add("write", lambda *_: self.refresh())
        self.filter_vars = {}
        filters = ["CV", "EIS", "DRT", "SECCM", "Battery", "Vendor parser", "Literature/DOI", "Instrument control"]
        for f in filters:
            v = tk.BooleanVar(value=False)
            self.filter_vars[f] = v
            cb = ttk.Checkbutton(filter_frame, text=f, variable=v, command=self.refresh)
            cb.pack(side="left", padx=(0, 6))

        main = ttk.Panedwindow(outer, orient="horizontal")
        main.pack(fill="both", expand=True)

        left = ttk.Frame(main, style="Card.TFrame", padding=(4, 4))
        right = ttk.Frame(main, style="Card.TFrame", padding=(8, 4))
        main.add(left, weight=3)
        main.add(right, weight=2)

        cols = ("category", "type", "status", "api", "useful")
        self.tree = ttk.Treeview(left, columns=cols, show="tree headings", selectmode="browse")
        self.tree.heading("#0", text="Resource")
        for c, t, w in [
            ("category", "Category", 150),
            ("type", "Type", 150),
            ("status", "Status", 125),
            ("api", "API key", 70),
            ("useful", "Useful for", 220),
        ]:
            self.tree.heading(c, text=t)
            self.tree.column(c, width=w, stretch=True)
        self.tree.column("#0", width=260, stretch=True)
        y = ttk.Scrollbar(left, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=y.set)
        self.tree.pack(side="left", fill="both", expand=True)
        y.pack(side="right", fill="y")
        self.tree.bind("<<TreeviewSelect>>", lambda e: self.show_selected())

        ttk.Label(right, text="Selected resource details", style="Section.TLabel").pack(anchor="w")
        self.detail = ScrolledText(right, wrap="word", height=22)
        self.detail.pack(fill="both", expand=True, pady=(4, 8))
        try:
            self.detail.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc", font=("Consolas", 9))
        except Exception:
            pass

        btns = ttk.Frame(right, style="Card.TFrame")
        btns.pack(fill="x", pady=(0, 8))
        for label, cmd, tip in [
            ("Check installed analysis libraries", self.check_installed, "Test imports for optional local analysis libraries inside the current FaradaIQ Python environment."),
            ("Open selected resource", self.open_selected, "Open the selected resource documentation/source page in the browser."),
            ("Add to analysis context", self.add_selected_context, "Save the selected resource as context for FaradaIQ prompts and reports."),
            ("Compare current experiment with this resource", self.compare_selected, "Generate a resource-specific comparison prompt for the current session."),
            ("Generate DOI-verified comparison prompt", self.generate_doi_prompt, "Create a prompt that asks for literature comparison with DOI verification and no fabricated references."),
        ]:
            b = ttk.Button(btns, text=label, command=cmd)
            b.pack(fill="x", pady=2)
            try:
                _v66_add_tooltip(b, tip)
            except Exception:
                pass

        self.status_var = tk.StringVar(value="Ready")
        ttk.Label(outer, textvariable=self.status_var, style="Status.TLabel").pack(anchor="w", pady=(8, 0))

    def filtered_resources(self):
        q = self.search_var.get().lower().strip()
        active = [k for k, v in self.filter_vars.items() if v.get()]
        out = []
        for r in self.resources:
            hay = " ".join([r.name, r.category, r.purpose, r.integration_type, " ".join(r.supported_data_types)]).lower()
            if q and q not in hay:
                continue
            if active and not any(a in r.supported_data_types or a.lower() in r.category.lower() for a in active):
                continue
            out.append(r)
        return out

    def refresh(self):
        self.tree.delete(*self.tree.get_children())
        self._resource_by_iid = {}
        group_iids = {}
        for r in self.filtered_resources():
            if r.category not in group_iids:
                group_iids[r.category] = self.tree.insert("", "end", text=r.category, values=("", "", "", "", ""), open=True)
            status, _msg = _v71_status_for_resource(r)
            iid = self.tree.insert(group_iids[r.category], "end", text=r.name, values=(r.category, r.integration_type, status, "yes" if r.requires_api_key else "no", ", ".join(r.supported_data_types)))
            self._resource_by_iid[iid] = r
        self.status_var.set(f"Showing {len(self.filtered_resources())} curated resources.")

    def selected(self):
        sel = self.tree.selection()
        if not sel:
            return None
        return self._resource_by_iid.get(sel[0])

    def show_selected(self):
        r = self.selected()
        if not r:
            return
        status, msg = _v71_status_for_resource(r)
        data = asdict(r)
        data["current_integration_status"] = status
        data["import_check_message"] = msg
        self.detail.configure(state="normal")
        self.detail.delete("1.0", "end")
        self.detail.insert("1.0", json.dumps(data, ensure_ascii=False, indent=2))
        self.detail.configure(state="disabled")
        self.status_var.set(f"{r.name}: {status}")

    def check_installed(self):
        self.status_var.set("Checking optional local analysis libraries...")
        def worker():
            results = []
            for r in self.resources:
                status, msg = _v71_status_for_resource(r)
                if r.import_check:
                    results.append({"name": r.name, "import": r.import_check, "status": status, "message": msg, "install_hint": r.install_hint})
            out = self.analysis_root / f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" / "logs" / "electrochemical_resource_import_check.json"
            _v71_write_session_json(out, results)
            def finish():
                self.status_var.set(f"Library checks complete. Saved: {out}")
                self.refresh()
                self.detail.configure(state="normal")
                self.detail.delete("1.0", "end")
                self.detail.insert("1.0", json.dumps(results, ensure_ascii=False, indent=2))
                self.detail.configure(state="disabled")
            try:
                self.after(0, finish)
            except Exception:
                pass
        threading.Thread(target=worker, daemon=True).start()

    def open_selected(self):
        r = self.selected()
        if not r:
            return
        try:
            webbrowser.open(r.documentation_url)
            self.status_var.set(f"Opened: {r.documentation_url}")
        except Exception as exc:
            self.status_var.set(f"Could not open link: {exc}")

    def add_selected_context(self):
        r = self.selected()
        if not r:
            return
        context_dir = self.analysis_root / f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" / "comparison_tables"
        context_dir.mkdir(parents=True, exist_ok=True)
        path = context_dir / "selected_electrochemical_resources.json"
        current = []
        if path.exists():
            try:
                current = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                current = []
        item = asdict(r)
        item["added"] = datetime.now().isoformat(timespec="seconds")
        if not any(x.get("name") == r.name for x in current):
            current.append(item)
        _v71_write_session_json(path, current)
        self.context_resources = current
        self.status_var.set(f"Added to analysis context: {r.name}")

    def _prompt_text(self, r=None):
        summary = ""
        structure = ""
        try:
            summary = _v45_current_gui_text(getattr(self.owner.gui if hasattr(self.owner, "gui") else self.owner, "summary_text", None))
        except Exception:
            pass
        try:
            structure = _v45_current_gui_text(getattr(self.owner.gui if hasattr(self.owner, "gui") else self.owner, "structure_text", None))
        except Exception:
            pass
        res = json.dumps(asdict(r), ensure_ascii=False, indent=2) if r else "Use all selected resources from context if available."
        return (
            "Generate a rigorous electrochemical literature/resource comparison plan for the current FaradaIQ session.\n\n"
            "Rules:\n"
            "- Use DOI-verified references only.\n"
            "- Do not fabricate references, DOI links, numerical values, mechanisms, or metadata.\n"
            "- Clearly list missing metadata and state how missing metadata limits interpretation.\n"
            "- Separate direct data observation from interpretation.\n"
            "- Include proposed comparison figures/tables and next experiments.\n\n"
            f"SELECTED RESOURCE CONTEXT:\n{res}\n\nSESSION SUMMARY:\n{summary}\n\nDATA STRUCTURE:\n{structure}\n"
        )

    def compare_selected(self):
        r = self.selected()
        if not r:
            return
        prompt = self._prompt_text(r)
        out = self.analysis_root / f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" / "comparison_tables" / f"comparison_prompt_{_v35_safe_name(r.name)}.txt"
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(prompt, encoding="utf-8")
        self.status_var.set(f"Comparison prompt saved: {out}")
        _v70_open_text_snapshot(self, f"Comparison prompt — {r.name}", prompt.splitlines())

    def generate_doi_prompt(self):
        prompt = self._prompt_text(self.selected())
        prompt += "\nOUTPUT FORMAT:\n1. Dataset/resource relevance table\n2. DOI-verified literature comparison plan\n3. Missing metadata table\n4. Figure/table plan\n5. Next experiments\n"
        out = self.analysis_root / f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" / "comparison_tables" / "doi_verified_literature_comparison_prompt.txt"
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(prompt, encoding="utf-8")
        self.status_var.set(f"DOI-verified comparison prompt saved: {out}")
        _v70_open_text_snapshot(self, "DOI-verified comparison prompt", prompt.splitlines())


def _v71_find_table_files(root):
    root = Path(root)
    files = []
    for p in root.rglob("*"):
        try:
            if p.is_file() and p.suffix.lower() in _V70_TABLE_EXTS and "AI_analysis_with_parsed_outputs" not in p.as_posix():
                files.append(p)
        except Exception:
            pass
    return sorted(files, key=lambda p: str(p).lower())


def _v71_guess_table_type(path):
    p = Path(path)
    kind = _v64_detect_file_kind(p)
    if kind in {"EIS", "CV / LSV", "OCP", "IV / Tafel", "DRT"}:
        return kind
    low = p.as_posix().lower()
    if "eis" in low or "zreal" in low or "zimag" in low:
        return "EIS"
    if "cv" in low:
        return "CV / LSV"
    return "Tables / text"


def _v71_eis_quantities(path):
    df = _v64_read_table_file(path)
    x, y, xcol, ycol, detected = _v70_extract_xy(df, "EIS Nyquist (-Zimag)")
    freq, mag, _, _, _ = _v70_extract_xy(df, "Bode magnitude")
    phase_x, phase_y, _, _, _ = _v70_extract_xy(df, "Bode phase")
    result = {"file": str(path), "type": "EIS", "assumptions": [], "warnings": []}
    if len(x) < 2:
        result["warnings"].append("Could not detect both Zreal and Zimag columns.")
        return result
    zreal = np.asarray(x, dtype=float)
    minus_zimag = np.asarray(y, dtype=float)
    result["Rs_ohm_estimate"] = float(np.nanmin(zreal))
    result["Rct_ohm_span_estimate"] = float(np.nanmax(zreal) - np.nanmin(zreal))
    result["minus_Zimag_max_ohm"] = float(np.nanmax(minus_zimag))
    if len(freq) and len(mag):
        result["frequency_min_Hz"] = float(np.nanmin(freq))
        result["frequency_max_Hz"] = float(np.nanmax(freq))
        result["Zmag_min_ohm"] = float(np.nanmin(mag))
        result["Zmag_max_ohm"] = float(np.nanmax(mag))
    if len(phase_y):
        result["phase_min_deg"] = float(np.nanmin(phase_y))
        result["phase_max_deg"] = float(np.nanmax(phase_y))
    try:
        imax = int(np.nanargmax(minus_zimag))
        if len(freq) == len(minus_zimag) and np.isfinite(freq[imax]) and freq[imax] > 0:
            result["tau_peak_s_estimate"] = float(1.0 / (2.0 * np.pi * freq[imax]))
            result["characteristic_frequency_Hz_estimate"] = float(freq[imax])
    except Exception:
        pass
    result["assumptions"].append("Rs and Rct-like span are rough geometry-free estimates from Zreal extrema, not a fitted equivalent circuit.")
    result["assumptions"].append("True Rct/Cdl/CPE/Warburg parameters require equivalent-circuit model selection and fitting.")
    return result


def _v71_cv_quantities(path):
    df = _v64_read_table_file(path)
    x, y, xcol, ycol, detected = _v70_extract_xy(df, "CV / LSV")
    result = {"file": str(path), "type": "CV", "assumptions": [], "warnings": []}
    if len(x) < 3:
        result["warnings"].append("Could not detect potential/current columns.")
        return result
    peaks = _v64_simple_peak_find(x, y)
    pos = [p for p in peaks if p.get("type") == "positive"]
    neg = [p for p in peaks if p.get("type") == "negative"]
    result["n_peak_candidates"] = len(peaks)
    result["peaks"] = peaks[:20]
    if pos:
        result["oxidation_peak_potential_V_estimate"] = pos[0].get("x")
        result["oxidation_peak_current_A_estimate"] = pos[0].get("y")
    if neg:
        result["reduction_peak_potential_V_estimate"] = neg[0].get("x")
        result["reduction_peak_current_A_estimate"] = neg[0].get("y")
    if pos and neg:
        result["delta_Ep_V_estimate"] = abs(float(pos[0].get("x")) - float(neg[0].get("x")))
        ipc = abs(float(neg[0].get("y"))) if neg[0].get("y") is not None else np.nan
        ipa = abs(float(pos[0].get("y"))) if pos[0].get("y") is not None else np.nan
        if ipc and np.isfinite(ipc):
            result["ipa_ipc_ratio_estimate"] = float(ipa / ipc)
    result["warnings"].append("Electrode area, analyte concentration, diffusion coefficient, temperature, and electron count are not assumed.")
    result["assumptions"].append("Randles–Ševčík-style estimates are disabled unless required metadata are provided by the user.")
    return result


class FaradaIQAnalysisEnginesWindow(tk.Toplevel):
    def __init__(self, browser_or_gui):
        super().__init__(browser_or_gui)
        self.owner = browser_or_gui
        self.analysis_root = getattr(browser_or_gui, "analysis_root", None)
        if self.analysis_root is None:
            try:
                self.analysis_root, _ = _v64_analysis_root_for_browser(browser_or_gui)
            except Exception:
                self.analysis_root = Path.cwd()
        self.analysis_root = Path(self.analysis_root)
        self.base_name = getattr(browser_or_gui, "base_name", self.analysis_root.name.replace("_analysis_ready_csv", ""))
        self.engines = _v71_engines()
        self.results = []
        self.title("Analysis Engines & Reference Comparison")
        self.geometry("1260x820")
        self.minsize(980, 640)
        self._build_ui()
        self.detect_session_data()

    def _build_ui(self):
        outer = ttk.Frame(self, style="Card.TFrame", padding=(10, 10))
        outer.pack(fill="both", expand=True, padx=8, pady=8)
        ttk.Label(outer, text="Analysis Engines & Reference Comparison", style="Section.TLabel").pack(anchor="w")
        ttk.Label(
            outer,
            text="Connect the current FaradaIQ session to appropriate local engines and curated reference context. Optional packages are checked safely and never block offline analysis.",
            style="Muted.TLabel",
            wraplength=1120,
        ).pack(anchor="w", pady=(2, 8))

        main = ttk.Panedwindow(outer, orient="horizontal")
        main.pack(fill="both", expand=True)

        left = ttk.Frame(main, style="Card.TFrame", padding=(6, 6))
        right = ttk.Frame(main, style="Card.TFrame", padding=(8, 6))
        main.add(left, weight=2)
        main.add(right, weight=3)

        ttk.Label(left, text="Detected session files", style="Section.TLabel").pack(anchor="w")
        self.file_tree = ttk.Treeview(left, columns=("type", "size"), show="tree headings", selectmode="extended", height=14)
        self.file_tree.heading("#0", text="File")
        self.file_tree.heading("type", text="Detected type")
        self.file_tree.heading("size", text="Size")
        self.file_tree.column("#0", width=360)
        self.file_tree.column("type", width=120)
        self.file_tree.column("size", width=90)
        self.file_tree.pack(fill="both", expand=True, pady=(4, 8))

        ttk.Label(left, text="Available engines", style="Section.TLabel").pack(anchor="w")
        self.engine_tree = ttk.Treeview(left, columns=("category", "status", "types"), show="tree headings", selectmode="browse", height=10)
        self.engine_tree.heading("#0", text="Engine")
        for c, t, w in [("category", "Category", 130), ("status", "Status", 90), ("types", "Data types", 180)]:
            self.engine_tree.heading(c, text=t)
            self.engine_tree.column(c, width=w)
        self.engine_tree.pack(fill="both", expand=True, pady=(4, 8))

        btns = ttk.Frame(left, style="Card.TFrame")
        btns.pack(fill="x")
        for label, cmd in [
            ("Detect session data", self.detect_session_data),
            ("Check engine packages", self.check_engines),
            ("Run selected/compatible analysis", self.run_analysis),
            ("Generate scientific interpretation prompt", self.generate_interpretation_prompt),
            ("Generate AI Prompt with Current Analysis Context", self.generate_context_prompt_with_llm),
            ("Export results", self.export_results),
        ]:
            ttk.Button(btns, text=label, command=cmd).pack(fill="x", pady=2)

        ttk.Label(right, text="Results, assumptions, and warnings", style="Section.TLabel").pack(anchor="w")
        self.results_text = ScrolledText(right, wrap="word")
        self.results_text.pack(fill="both", expand=True, pady=(4, 8))
        try:
            self.results_text.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc", font=("Consolas", 9))
        except Exception:
            pass
        bottom = ttk.Frame(right, style="Card.TFrame")
        bottom.pack(fill="x")
        ttk.Button(bottom, text="↗ Results popout", command=lambda: _v70_open_text_snapshot(self, "Analysis engine results", self.results_text.get("1.0", "end").splitlines())).pack(side="left")
        ttk.Button(bottom, text="Open analyzed-data folder", command=self.open_folder).pack(side="left", padx=(6, 0))
        self.status_var = tk.StringVar(value="Ready")
        ttk.Label(outer, textvariable=self.status_var, style="Status.TLabel").pack(anchor="w", pady=(8, 0))

    def log(self, msg):
        self.results_text.insert("end", str(msg).rstrip() + "\n")
        self.results_text.see("end")
        self.status_var.set(str(msg)[:180])
        self.update_idletasks()

    @staticmethod
    def _size(n):
        n = float(n)
        for unit in ["B", "KiB", "MiB", "GiB"]:
            if n < 1024:
                return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
            n /= 1024
        return f"{n:.1f} TiB"

    def detect_session_data(self):
        self.file_tree.delete(*self.file_tree.get_children())
        self._file_by_iid = {}
        files = _v71_find_table_files(self.analysis_root)
        for p in files[:1000]:
            try:
                kind = _v71_guess_table_type(p)
                rel = p.relative_to(self.analysis_root).as_posix()
                iid = self.file_tree.insert("", "end", text=rel, values=(kind, self._size(p.stat().st_size)))
                self._file_by_iid[iid] = p
            except Exception:
                pass
        self.engine_tree.delete(*self.engine_tree.get_children())
        self._engine_by_iid = {}
        for e in self.engines:
            ok, _ = _v71_module_available(e.import_check)
            status = "available" if (ok or not e.import_check) else "missing"
            iid = self.engine_tree.insert("", "end", text=e.name, values=(e.category, status, ", ".join(e.supported_data_types)))
            self._engine_by_iid[iid] = e
        self.log(f"Detected {len(files)} table files under {self.analysis_root}.")

    def selected_files(self):
        sel = self.file_tree.selection()
        if not sel:
            return list(getattr(self, "_file_by_iid", {}).values())
        return [self._file_by_iid[i] for i in sel if i in self._file_by_iid]

    def check_engines(self):
        results = []
        for e in self.engines:
            ok, msg = _v71_module_available(e.import_check)
            results.append({**asdict(e), "installed": bool(ok or not e.import_check), "import_message": msg})
        out = self._outdir() / "analysis_engine_package_check.json"
        _v71_write_session_json(out, results)
        self.results_text.delete("1.0", "end")
        self.log(json.dumps(results, ensure_ascii=False, indent=2))
        self.log(f"Engine package check saved: {out}")

    def _outdir(self):
        out = self.analysis_root / f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" / "analysis_engine_results"
        out.mkdir(parents=True, exist_ok=True)
        return out

    def run_analysis(self):
        files = self.selected_files()
        self.results = []
        self.results_text.delete("1.0", "end")
        self.log("Running compatible lightweight analysis. Optional fitting engines are checked but not required.")
        for p in files:
            kind = _v71_guess_table_type(p)
            try:
                if kind == "EIS":
                    self.results.append(_v71_eis_quantities(p))
                elif kind == "CV / LSV":
                    self.results.append(_v71_cv_quantities(p))
            except Exception as exc:
                self.results.append({"file": str(p), "type": kind, "error": str(exc)})
        out = self._outdir() / f"{_v35_safe_name(self.base_name)}_analysis_engine_results.json"
        _v71_write_session_json(out, self.results)
        self.log(json.dumps(self.results, ensure_ascii=False, indent=2))
        self.log(f"Saved analysis results: {out}")

    def generate_interpretation_prompt(self):
        if not self.results:
            self.run_analysis()
        prompt = self._context_prompt(send_to_llm=False)
        out = self._outdir() / "scientific_interpretation_prompt.txt"
        out.write_text(prompt, encoding="utf-8")
        self.log(f"Scientific interpretation prompt saved: {out}")
        _v70_open_text_snapshot(self, "Scientific interpretation prompt", prompt.splitlines())

    def _context_prompt(self, send_to_llm=False):
        provider, model, _cand = _v66_selected_llm_label_text()
        ping = globals().get("_FARADAIQ_LLM_LAST_PING", {})
        selected_resources = []
        res_path = self.analysis_root / f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" / "comparison_tables" / "selected_electrochemical_resources.json"
        if res_path.exists():
            try:
                selected_resources = json.loads(res_path.read_text(encoding="utf-8"))
            except Exception:
                selected_resources = []
        missing = []
        for r in self.results:
            missing.extend(r.get("warnings", []))
        return (
            "Generate an electrochemical data-analysis and reporting plan from the current FaradaIQ analysis context.\n\n"
            "Include: experimental workflow reconstruction, detected data type(s), data-quality checks, missing metadata warnings, "
            "CV/EIS/DRT/SECCM-specific analysis steps, mechanistic interpretation constraints, figure/table plan, possible artifacts/controls, "
            "recommended next experiments, and literature comparison using DOI-verified references only. Do not fabricate references or DOI links.\n\n"
            f"Selected LLM: {provider}\nModel: {model}\nLLM ping status: {ping}\n\n"
            f"Analysis root: {self.analysis_root}\n\n"
            f"Selected external resource/database context:\n{json.dumps(selected_resources, ensure_ascii=False, indent=2)}\n\n"
            f"Analysis results / estimates / assumptions:\n{json.dumps(self.results, ensure_ascii=False, indent=2)}\n\n"
            f"Missing metadata warnings:\n{json.dumps(sorted(set(missing)), ensure_ascii=False, indent=2)}\n"
        )

    def generate_context_prompt_with_llm(self):
        if not self.results:
            self.run_analysis()
        prompt = self._context_prompt(send_to_llm=True)
        out = self._outdir() / "ai_prompt_with_current_analysis_context.txt"
        out.write_text(prompt, encoding="utf-8")
        self.log(f"AI prompt with current analysis context saved: {out}")
        # Do not auto-call the LLM here unless user has selected/pinged it; open editable prompt for review.
        _v70_open_text_snapshot(self, "AI Prompt with Current Analysis Context", prompt.splitlines())

    def export_results(self):
        if not self.results:
            self.run_analysis()
        out_json = self._outdir() / f"{_v35_safe_name(self.base_name)}_analysis_engine_results.json"
        _v71_write_session_json(out_json, self.results)
        try:
            import pandas as _pd
            rows = []
            for r in self.results:
                row = {k: v for k, v in r.items() if not isinstance(v, (list, dict))}
                row["warnings"] = "; ".join(r.get("warnings", []))
                row["assumptions"] = "; ".join(r.get("assumptions", []))
                rows.append(row)
            df = _pd.DataFrame(rows)
            out_xlsx = self._outdir() / f"{_v35_safe_name(self.base_name)}_analysis_engine_results.xlsx"
            df.to_excel(out_xlsx, index=False)
            self.log(f"Exported results: {out_json} and {out_xlsx}")
        except Exception:
            self.log(f"Exported JSON results: {out_json}")

    def open_folder(self):
        try:
            os.startfile(str(self._outdir()))
        except Exception:
            webbrowser.open(self._outdir().resolve().as_uri())


