def _v71_patch_main_ai_context_button(gui):
    try:
        if getattr(gui, "_v71_context_prompt_button_added", False):
            return
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass
        ai_parent = None
        for w in walk(gui):
            try:
                if str(w.cget("text")) == "AI workflow":
                    ai_parent = w.master
                    break
            except Exception:
                pass
        if ai_parent is not None:
            btn = ttk.Button(ai_parent, text="AI prompt with context", command=lambda g=gui: _v71_generate_ai_prompt_current_analysis_context(g))
            btn.pack(side="left", padx=(6, 6))
            _v66_add_tooltip(btn, "Generate an AI prompt using current experiment metadata, detected data type, analysis results, selected resource/database context, missing metadata warnings, and selected LLM status.")
            gui._v71_context_prompt_button_added = True
    except Exception:
        pass


