# ---- v72 UI refinement: compact heading-row popout/font controls ----
APP_TITLE = "FaradaIQ Studio v273"


def _v72_forget_existing_text_heading(parent, title):
    """Hide the original standalone heading label so the compact heading/control row replaces it."""
    try:
        for child in list(parent.winfo_children()):
            if child is None:
                continue
            if str(child) == "":
                continue
            try:
                txt = str(child.cget("text")).strip()
                cls = child.winfo_class()
            except Exception:
                continue
            if txt == title and ("Label" in cls or cls in {"TLabel", "Label"}):
                try:
                    child.pack_forget()
                except Exception:
                    try:
                        child.grid_remove()
                    except Exception:
                        pass
    except Exception:
        pass


def _v67_add_textbox_toolbar(gui, widget_attr, title, wrap="word"):
    """v72 override: put ↗, A−, A+ immediately beside the box heading, not right-aligned with a large blank spacer."""
    try:
        widget = getattr(gui, widget_attr, None)
        if widget is None:
            return
        if getattr(widget, "_faradaiq_popout_toolbar_added", False):
            return

        parent = widget.master
        _v72_forget_existing_text_heading(parent, title)

        # Compact heading row directly above the text box.
        row = ttk.Frame(parent, style="Card.TFrame")
        try:
            row.pack(fill="x", before=widget, pady=(0, 2), anchor="w")
        except Exception:
            row.pack(fill="x", pady=(0, 2), anchor="w")

        try:
            title_label = ttk.Label(row, text=title, style="Section.TLabel")
        except Exception:
            title_label = ttk.Label(row, text=title)
        title_label.pack(side="left", padx=(0, 8))

        b_pop = ttk.Button(row, text="↗", width=3, command=lambda: _v67_open_popout_textbox(gui, title, widget, wrap=wrap))
        b_minus = ttk.Button(row, text="A−", width=4, command=lambda: _v67_adjust_text_font(widget, -1))
        b_plus = ttk.Button(row, text="A+", width=4, command=lambda: _v67_adjust_text_font(widget, +1))

        # Buttons are left-aligned next to the heading. No expanding blank spacer is inserted.
        b_pop.pack(side="left", padx=(0, 3))
        b_minus.pack(side="left", padx=(0, 3))
        b_plus.pack(side="left", padx=(0, 3))

        _v66_add_tooltip(title_label, f"{title} text area.")
        _v66_add_tooltip(b_pop, f"Open {title} in a separate editable popout window.")
        _v66_add_tooltip(b_minus, f"Decrease font size in the {title} box.")
        _v66_add_tooltip(b_plus, f"Increase font size in the {title} box.")

        widget._faradaiq_popout_toolbar_added = True
        widget._faradaiq_popout_toolbar_row = row
    except Exception:
        pass



# ---- v73 UI refinement: one global preview toolbar, no per-box button rows ----
APP_TITLE = "FaradaIQ Studio v273"


def _v67_add_textbox_toolbar(gui, widget_attr, title, wrap="word"):
    """v73 override: do not add per-box buttons. One global preview toolbar handles all preview boxes."""
    try:
        widget = getattr(gui, widget_attr, None)
        if widget is not None:
            widget._faradaiq_popout_toolbar_added = True
    except Exception:
        pass


def _v73_preview_widgets(gui):
    items = []
    for attr, title, wrap in [
        ("desc_text", "Experimental description", "word"),
        ("summary_text", "Session summary", "word"),
        ("structure_text", "Data structure preview", "none"),
    ]:
        w = getattr(gui, attr, None)
        if w is not None:
            items.append((w, title, wrap))
    return items


def _v73_adjust_all_preview_fonts(gui, delta):
    try:
        for w, _title, _wrap in _v73_preview_widgets(gui):
            _v67_adjust_text_font(w, int(delta))
        try:
            gui.set_status(f"Preview font size {'increased' if int(delta) > 0 else 'decreased'} for all preview boxes.")
        except Exception:
            pass
    except Exception:
        pass


def _v73_open_all_previews_popout(gui):
    try:
        win = tk.Toplevel(gui)
        win.title("FaradaIQ preview boxes — popout")
        win.geometry("1180x780")
        try:
            p = _v36_theme_palette(getattr(gui, "_faradaiq_theme_mode", "dark"))
            win.configure(bg=p["bg"])
        except Exception:
            pass

        outer = ttk.Frame(win, style="Card.TFrame", padding=(10, 10))
        outer.pack(fill="both", expand=True, padx=10, pady=10)

        top = ttk.Frame(outer, style="Card.TFrame")
        top.pack(fill="x", pady=(0, 8))
        ttk.Label(top, text="FaradaIQ preview boxes", style="Section.TLabel").pack(side="left", padx=(0, 12))

        tabs = ttk.Notebook(outer)
        tabs.pack(fill="both", expand=True)

        popout_texts = {}

        for src, title, wrap in _v73_preview_widgets(gui):
            frame = ttk.Frame(tabs, style="Card.TFrame", padding=(6, 6))
            tabs.add(frame, text=title)
            txt = ScrolledText(frame, wrap=wrap)
            txt.pack(fill="both", expand=True)
            try:
                txt.configure(
                    background="#020617",
                    foreground="#e5eefb",
                    insertbackground="#f8fafc",
                    font=("Consolas", _v67_get_text_font_size(src)),
                )
            except Exception:
                pass
            txt.insert("1.0", _v67_textbox_content(src))
            popout_texts[title] = (txt, src)

        def sync_all_from_main():
            for title, (txt, src) in popout_texts.items():
                _v67_set_textbox_content(txt, _v67_textbox_content(src))

        def sync_all_back():
            for title, (txt, src) in popout_texts.items():
                _v67_set_textbox_content(src, _v67_textbox_content(txt))
            try:
                gui.set_status("All preview popout contents synced back to main window.")
            except Exception:
                pass

        def plus_all():
            for txt, _src in popout_texts.values():
                _v67_adjust_text_font(txt, +1)

        def minus_all():
            for txt, _src in popout_texts.values():
                _v67_adjust_text_font(txt, -1)

        def save_all():
            folder = filedialog.askdirectory(title="Choose folder to save all preview texts")
            if not folder:
                return
            folder = Path(folder)
            folder.mkdir(parents=True, exist_ok=True)
            for title, (txt, _src) in popout_texts.items():
                (folder / f"{_v35_safe_name(title)}.txt").write_text(_v67_textbox_content(txt), encoding="utf-8")
            try:
                gui.set_status(f"Saved all preview popout texts to: {folder}")
            except Exception:
                pass

        for label, cmd, tip in [
            ("A−", minus_all, "Decrease font size in all popout tabs."),
            ("A+", plus_all, "Increase font size in all popout tabs."),
            ("Sync from main", sync_all_from_main, "Reload all tabs from the main FaradaIQ preview boxes."),
            ("Sync back", sync_all_back, "Copy all edited tabs back into the main preview boxes."),
            ("Save all", save_all, "Save all preview tabs as text files."),
            ("Close", win.destroy, "Close this popout window."),
        ]:
            b = ttk.Button(top, text=label, command=cmd)
            b.pack(side="right", padx=(4, 0))
            try:
                _v66_add_tooltip(b, tip)
            except Exception:
                pass

        win.lift()
    except Exception as exc:
        messagebox.showerror("Preview popout failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)


def _v73_toggle_preview_collapse(gui):
    try:
        widgets = _v73_preview_widgets(gui)
        collapsed = bool(getattr(gui, "_faradaiq_previews_collapsed", False))
        if not collapsed:
            gui._faradaiq_preview_pack_info = {}
            for w, _title, _wrap in widgets:
                try:
                    gui._faradaiq_preview_pack_info[str(w)] = (w, w.pack_info())
                    w.pack_forget()
                except Exception:
                    try:
                        gui._faradaiq_preview_pack_info[str(w)] = (w, None)
                        w.configure(height=2)
                    except Exception:
                        pass
            gui._faradaiq_previews_collapsed = True
            try:
                gui._faradaiq_preview_collapse_var.set("Expand previews")
            except Exception:
                pass
            try:
                gui.set_status("Preview boxes collapsed.")
            except Exception:
                pass
        else:
            info = getattr(gui, "_faradaiq_preview_pack_info", {})
            # Restore in a stable order.
            for w, _title, _wrap in widgets:
                restored = False
                for _key, (saved_w, pack_info) in list(info.items()):
                    if saved_w is w:
                        try:
                            if pack_info:
                                w.pack(**pack_info)
                            else:
                                w.configure(height=10)
                            restored = True
                        except Exception:
                            pass
                if not restored:
                    try:
                        w.pack(fill="both", expand=True)
                    except Exception:
                        pass
            gui._faradaiq_previews_collapsed = False
            try:
                gui._faradaiq_preview_collapse_var.set("Collapse previews")
            except Exception:
                pass
            try:
                gui.set_status("Preview boxes expanded.")
            except Exception:
                pass
    except Exception:
        pass


def _v73_remove_legacy_per_box_toolbar_rows(gui):
    """Clean up v72-style per-box rows if a user runs v73 over an already-created UI."""
    try:
        for w, title, _wrap in _v73_preview_widgets(gui):
            row = getattr(w, "_faradaiq_popout_toolbar_row", None)
            if row is not None:
                try:
                    row.destroy()
                except Exception:
                    try:
                        row.pack_forget()
                    except Exception:
                        pass
                try:
                    w._faradaiq_popout_toolbar_row = None
                except Exception:
                    pass
    except Exception:
        pass


def _v73_add_global_preview_controls(gui):
    try:
        if getattr(gui, "_faradaiq_global_preview_controls_added", False):
            return

        lf = _v27_find_widget_by_text(gui, "TLabelframe", "pySECCM / DRT runners") or _v27_find_widget_by_text(gui, "Labelframe", "pySECCM / DRT runners")
        parent = lf if lf is not None else gui

        row = ttk.Frame(parent, style="Card.TFrame")
        row.pack(fill="x", pady=(3, 0))

        ttk.Label(row, text="Preview controls", style="Muted.TLabel").pack(side="left", padx=(0, 8))

        b_pop = ttk.Button(row, text="↗ Popout all", command=lambda g=gui: _v73_open_all_previews_popout(g))
        b_minus = ttk.Button(row, text="A−", width=4, command=lambda g=gui: _v73_adjust_all_preview_fonts(g, -1))
        b_plus = ttk.Button(row, text="A+", width=4, command=lambda g=gui: _v73_adjust_all_preview_fonts(g, +1))
        gui._faradaiq_preview_collapse_var = tk.StringVar(value="Collapse previews")
        b_collapse = ttk.Button(row, textvariable=gui._faradaiq_preview_collapse_var, command=lambda g=gui: _v73_toggle_preview_collapse(g))

        b_pop.pack(side="left", padx=(0, 5))
        b_minus.pack(side="left", padx=(0, 5))
        b_plus.pack(side="left", padx=(0, 5))
        b_collapse.pack(side="left", padx=(0, 5))

        try:
            ttk.Label(row, text="Applies to Experimental description, Session summary, and Data structure preview.", style="Muted.TLabel").pack(side="left", padx=(8, 0))
        except Exception:
            pass

        _v66_add_tooltip(b_pop, "Open all three major preview boxes in one tabbed popout window.")
        _v66_add_tooltip(b_minus, "Decrease font size in all three main preview boxes.")
        _v66_add_tooltip(b_plus, "Increase font size in all three main preview boxes.")
        _v66_add_tooltip(b_collapse, "Collapse or expand all three main preview text boxes together.")

        gui._faradaiq_global_preview_controls_added = True
        gui._faradaiq_global_preview_controls_row = row
    except Exception:
        pass


_V73_PREV_BUILD_UI = SessionReaderGUI._build_ui

def _session_reader_gui_v73_build_ui(self):
    _V73_PREV_BUILD_UI(self)
    try:
        self.title(APP_TITLE)
        _v73_remove_legacy_per_box_toolbar_rows(self)
        _v73_add_global_preview_controls(self)
        _v66_apply_tooltips(self)
        self.after(900, lambda: (_v73_remove_legacy_per_box_toolbar_rows(self), _v73_add_global_preview_controls(self), _v66_apply_tooltips(self)))
    except Exception:
        pass

SessionReaderGUI._build_ui = _session_reader_gui_v73_build_ui



# ---- v75 browser/analysis workspace redesign: cleaner workflow, smart schemas, compact layout ----
APP_TITLE = "FaradaIQ Studio v273"


def _v75_kind_from_paths(paths):
    kinds = []
    for p in paths or []:
        try:
            k = _v64_detect_file_kind(Path(p))
        except Exception:
            k = ""
        kinds.append(str(k))
    joined = " ".join(kinds).lower() + " " + " ".join(str(p).lower() for p in (paths or []))
    if "eis" in joined or "zreal" in joined or "zimag" in joined:
        return "EIS"
    if "drt" in joined:
        return "DRT"
    if "ocp" in joined:
        return "OCP"
    if "tafel" in joined or " iv" in joined or "_iv" in joined or "current-voltage" in joined:
        return "IV / Tafel"
    if "cv" in joined or "lsv" in joined or "current" in joined and "potential" in joined:
        return "CV / LSV"
    if "image" in joined or "photo" in joined or "movie" in joined or "video" in joined:
        return "Media"
    return "General"


def _v75_clone_tree_items(src_tree, dst_tree, parent_src="", parent_dst=""):
    try:
        for iid in src_tree.get_children(parent_src):
            text = src_tree.item(iid, "text")
            vals = src_tree.item(iid, "values")
            open_state = src_tree.item(iid, "open")
            new_iid = dst_tree.insert(parent_dst, "end", text=text, values=vals, open=open_state)
            _v75_clone_tree_items(src_tree, dst_tree, iid, new_iid)
    except Exception:
        pass


def _v75_popup_tree(owner, title, source_tree):
    win = tk.Toplevel(owner)
    win.title(title)
    win.geometry("920x640")
    outer = ttk.Frame(win, style="Card.TFrame", padding=(8, 8))
    outer.pack(fill="both", expand=True)
    ttk.Label(outer, text=title, style="Section.TLabel").pack(anchor="w", pady=(0, 6))
    cols = source_tree["columns"]
    tree = ttk.Treeview(outer, columns=cols, show=source_tree["show"], selectmode="extended")
    tree.pack(side="left", fill="both", expand=True)
    y = ttk.Scrollbar(outer, orient="vertical", command=tree.yview)
    tree.configure(yscrollcommand=y.set)
    y.pack(side="right", fill="y")
    try:
        tree.heading("#0", text=source_tree.heading("#0").get("text", "Item"))
        tree.column("#0", width=max(240, int(source_tree.column("#0").get("width", 300))), stretch=True)
        for c in cols:
            tree.heading(c, text=source_tree.heading(c).get("text", str(c)))
            tree.column(c, width=max(80, int(source_tree.column(c).get("width", 100))), stretch=True)
    except Exception:
        pass
    _v75_clone_tree_items(source_tree, tree)
    return win


def _v75_popup_listbox(owner, title, source_listbox):
    win = tk.Toplevel(owner)
    win.title(title)
    win.geometry("820x520")
    outer = ttk.Frame(win, style="Card.TFrame", padding=(8, 8))
    outer.pack(fill="both", expand=True)
    ttk.Label(outer, text=title, style="Section.TLabel").pack(anchor="w", pady=(0, 6))
    lb = tk.Listbox(outer, exportselection=False)
    lb.pack(side="left", fill="both", expand=True)
    y = ttk.Scrollbar(outer, orient="vertical", command=lb.yview)
    lb.configure(yscrollcommand=y.set)
    y.pack(side="right", fill="y")
    try:
        for i in range(source_listbox.size()):
            lb.insert("end", source_listbox.get(i))
    except Exception:
        pass
    return win


def _v75_popup_log(owner, title, text_widget):
    win = tk.Toplevel(owner)
    win.title(title)
    win.geometry("900x520")
    outer = ttk.Frame(win, style="Card.TFrame", padding=(8, 8))
    outer.pack(fill="both", expand=True)
    ttk.Label(outer, text=title, style="Section.TLabel").pack(anchor="w", pady=(0, 6))
    txt = ScrolledText(outer, wrap="word")
    txt.pack(fill="both", expand=True)
    try:
        txt.configure(font=text_widget.cget("font"), background=text_widget.cget("background"), foreground=text_widget.cget("foreground"), insertbackground=text_widget.cget("insertbackground"))
    except Exception:
        pass
    try:
        txt.insert("1.0", text_widget.get("1.0", "end"))
    except Exception:
        pass
    return win


def _v75_analysis_result(parent, label, value):
    row = ttk.Frame(parent, style="Card.TFrame")
    row.pack(fill="x", pady=1)
    ttk.Label(row, text=label, style="Muted.TLabel", width=24).pack(side="left")
    ttk.Label(row, text=str(value), style="Card.TLabel").pack(side="left", fill="x", expand=True)


def _v75_clear_frame(frame):
    try:
        for c in frame.winfo_children():
            c.destroy()
    except Exception:
        pass


def _v75_get_selected_view_paths(browser):
    paths = []
    try:
        if hasattr(browser, "plot_view_list") and getattr(browser, "_v69_plot_views", None):
            sel = browser.plot_view_list.curselection()
            if sel:
                view = browser._v69_plot_views[sel[0]]
                for c in view.get("curves", []):
                    p = c.get("path")
                    if p:
                        paths.append(Path(p))
    except Exception:
        pass
    if not paths:
        paths = browser.selected_paths(plottable_only=True)
    if not paths:
        paths = list(getattr(browser, "last_plot_paths", []) or [])
    return paths


def _v75_browser_log_status(browser, msg):
    try:
        browser.status_var.set(str(msg)[:220])
    except Exception:
        pass
    try:
        browser.log(msg)
    except Exception:
        pass


