    ttk.Button(pv_btns, text="Analyze view", command=lambda: _v75_run_analysis_for_current_view(self)).pack(side="left", fill="x", expand=True, padx=(3, 0))

    self.schema_frame = ttk.LabelFrame(right, text="Smart measurement analysis", padding=(6, 6))
