    ttk.Button(result_btns, text="Save results", command=self.save_results_table).pack(side="left", fill="x", expand=True, padx=(0, 3))
    ttk.Button(result_btns, text="Export all", command=self.export_all_current).pack(side="left", fill="x", expand=True, padx=(3, 0))

    bottom = ttk.Frame(outer, style="Card.TFrame")
