def _v75_choose_source_folder(browser):
    path = filedialog.askdirectory(title="Choose folder to read data", initialdir=str(browser.analysis_root))
    if path:
        browser.source_folder_var.set(path)
        browser.analysis_root = Path(path).resolve()
        browser.base_name = browser.analysis_root.name.replace("_analysis_ready_csv", "")
        browser.analyzed_root = browser.analysis_root / f"{_v35_safe_name(browser.base_name)}_FaradaIQ_analyzed_data"
        browser._ensure_analyzed_dirs()
        _v75_refresh_from_source_controls(browser)


def _v75_refresh_from_source_controls(browser):
    try:
        browser.analysis_root = Path(browser.source_folder_var.get()).expanduser().resolve()
        browser.base_name = browser.analysis_root.name.replace("_analysis_ready_csv", "")
        browser.analyzed_root = browser.analysis_root / f"{_v35_safe_name(browser.base_name)}_FaradaIQ_analyzed_data"
        browser._ensure_analyzed_dirs()
        browser.refresh_tree()
    except Exception as exc:
        _v75_browser_log_status(browser, f"Refresh failed: {exc}")


def _v75_refresh_tree(self):
    try:
        self.tree.delete(*self.tree.get_children())
    except Exception:
        pass
    self._path_by_iid = {}
    self._group_iids = {}
    groups = [
        "CV / LSV", "EIS", "DRT", "OCP", "IV / Tafel", "SECCM position / takedata",
        "Photos / images", "Movies / video", "Figures", "Tables / text", "Metadata JSON", "NumPy payload", "Other"
    ]
    for g in groups:
        iid = self.tree.insert("", "end", text=g, values=(g, ""), open=(g in {"CV / LSV", "EIS", "DRT"}))
        self._group_iids[g] = iid
    if not self.analysis_root.exists():
        self.log(f"Analysis root does not exist: {self.analysis_root}")
        return

    if self.ai_npy_only_var.get():
        include_exts = {".npy", ".npz"}
    else:
        include_exts = _V70_TABLE_EXTS | _V70_IMAGE_EXTS | _V70_VIDEO_EXTS | {".json", ".npy", ".npz", ".svg", ".pdf", ".h5", ".hdf5"}

    count = 0
    for p in sorted(self.analysis_root.rglob("*"), key=lambda x: str(x).lower()):
        try:
            if not p.is_file() or p.suffix.lower() not in include_exts:
                continue
            rel = p.relative_to(self.analysis_root).as_posix()
            if self.ai_npy_only_var.get():
                low = rel.lower()
                if not (("ai_analysis" in low or "ai_bundle" in low or "parsed_outputs" in low or "payload" in low) and p.suffix.lower() in {".npy", ".npz"}):
                    continue
            elif f"{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data" in rel:
                continue
            kind = _v64_detect_file_kind(p)
            group = kind if kind in self._group_iids else "Other"
            size = p.stat().st_size
            label = rel
            if len(label) > 88:
                label = "..." + label[-85:]
            iid = self.tree.insert(self._group_iids[group], "end", text=label, values=(kind, self._format_size(size)))
            self._path_by_iid[iid] = p
            count += 1
        except Exception:
            pass
    msg = f"Indexed {count} files from {self.analysis_root}"
    if self.ai_npy_only_var.get():
        msg += " (AI-bundle NPY filter on)"
    self.log(msg)
    try:
        self.status_var.set(msg)
    except Exception:
        pass


def _v75_selected_paths(self, plottable_only=True):
    out = []
    for iid in self.tree.selection():
        p = self._path_by_iid.get(iid)
        if p is None:
            continue
        if plottable_only and p.suffix.lower() not in (_V70_TABLE_EXTS | _V70_IMAGE_EXTS | _V70_VIDEO_EXTS):
            continue
        out.append(p)
    return out


def _v75_update_axis_choices(browser):
    try:
        paths = browser.selected_paths(plottable_only=True)
        tables = _v70_table_paths(paths)
        if not tables:
            return
        df = _v64_read_table_file(tables[0], max_rows=1000)
        cols = [str(c) for c in df.columns]
        browser.x_axis_box.configure(values=[""] + cols)
        browser.y_axis_box.configure(values=[""] + cols)
    except Exception:
        pass


def _v75_on_browser_selection(browser):
    paths = browser.selected_paths(plottable_only=True)
    _v75_update_axis_choices(browser)
    kind = _v75_kind_from_paths(paths)
    browser.current_technique_var.set(f"Detected: {kind} | selected files: {len(paths)}")
    _v75_update_analysis_schema(browser, kind)
    try:
        browser.preview_selected()
    except Exception:
        pass


def _v75_update_analysis_schema(browser, kind=None):
    kind = kind or _v75_kind_from_paths(_v75_get_selected_view_paths(browser))
    _v75_clear_frame(browser.schema_body)
    browser.analysis_progress.configure(value=0)
    browser.analysis_progress_var.set(f"Ready for {kind} analysis")
    title = str(kind)
    if title == "CV / LSV":
        ttk.Label(browser.schema_body, text="CV / LSV tools", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="Find oxidation/reduction peaks", command=browser.find_peaks).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="Baseline / area from 2 clicks", command=browser.enable_baseline_mode).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="CV analysis summary + warnings", command=lambda: _v75_run_analysis_for_current_view(browser, force_kind="CV / LSV")).pack(fill="x", pady=2)
        ttk.Label(browser.schema_body, text="Randles–Ševčík estimates remain disabled unless area, concentration, diffusion coefficient, temperature, n, and assumptions are supplied.", style="Muted.TLabel", wraplength=300).pack(anchor="w", pady=(4,0))
    elif title == "EIS":
        ttk.Label(browser.schema_body, text="EIS tools", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="Nyquist plot", command=lambda: _v75_set_mode_and_replot(browser, "EIS Nyquist (-Zimag)")).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="Bode magnitude", command=lambda: _v75_set_mode_and_replot(browser, "Bode magnitude")).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="Bode phase", command=lambda: _v75_set_mode_and_replot(browser, "Bode phase")).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="EIS quantities / fitting-ready summary", command=lambda: _v75_run_analysis_for_current_view(browser, force_kind="EIS")).pack(fill="x", pady=2)
        ttk.Label(browser.schema_body, text="Equivalent-circuit fitting appears only if impedance.py is installed. AutoEIS is optional. DRT requires valid EIS and DRT tools.", style="Muted.TLabel", wraplength=300).pack(anchor="w", pady=(4,0))
    elif title == "DRT":
        ttk.Label(browser.schema_body, text="DRT tools", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="DRT peak table", command=lambda: _v75_run_analysis_for_current_view(browser, force_kind="DRT")).pack(fill="x", pady=2)
        ttk.Label(browser.schema_body, text="DRT requires valid EIS, relaxation-time grid, regularization choice, residual checks, and visible assumptions.", style="Muted.TLabel", wraplength=300).pack(anchor="w", pady=(4,0))
    elif title == "OCP":
        ttk.Label(browser.schema_body, text="OCP tools", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="OCP drift summary", command=lambda: _v75_run_analysis_for_current_view(browser, force_kind="OCP")).pack(fill="x", pady=2)
        ttk.Label(browser.schema_body, text="OCP interpretation depends on reference electrode, stabilization time, and perturbation history.", style="Muted.TLabel", wraplength=300).pack(anchor="w", pady=(4,0))
    elif title == "IV / Tafel":
        ttk.Label(browser.schema_body, text="IV / Tafel tools", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="Tafel/IV summary", command=lambda: _v75_run_analysis_for_current_view(browser, force_kind="IV / Tafel")).pack(fill="x", pady=2)
        ttk.Label(browser.schema_body, text="Tafel slopes require valid kinetic region selection and reference/electrode metadata.", style="Muted.TLabel", wraplength=300).pack(anchor="w", pady=(4,0))
    elif title == "Media":
        ttk.Label(browser.schema_body, text="Media browser", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="Previous media", command=lambda: _v70_media_prev(browser)).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="Next media", command=lambda: _v70_media_next(browser)).pack(fill="x", pady=2)
        ttk.Button(browser.schema_body, text="Open media externally", command=lambda: _v70_media_open_external(browser)).pack(fill="x", pady=2)
    else:
        ttk.Label(browser.schema_body, text="General tools", style="Section.TLabel").pack(anchor="w")
        ttk.Button(browser.schema_body, text="Run compatible analysis on selected view/data", command=lambda: _v75_run_analysis_for_current_view(browser)).pack(fill="x", pady=2)
        ttk.Label(browser.schema_body, text="Select CV/EIS/DRT/OCP/Tafel data to reveal technique-specific tools.", style="Muted.TLabel", wraplength=300).pack(anchor="w", pady=(4,0))


def _v75_set_mode_and_replot(browser, mode):
    browser.plot_mode_var.set(mode)
    _v75_plot_or_overlay_selected(browser)


def _v75_auto_replot(browser):
    try:
        if getattr(browser, "_v75_replot_after_control_change", False):
            return
        paths = getattr(browser, "last_plot_paths", []) or []
        if not paths:
            return
        browser._v75_replot_after_control_change = True
        browser.clear_plot()
        for p in paths:
            if Path(p).suffix.lower() in _V70_TABLE_EXTS:
                browser._plot_file(Path(p), clear=False)
        browser._finish_plot_axes()
        browser._v75_replot_after_control_change = False
    except Exception:
        try:
            browser._v75_replot_after_control_change = False
        except Exception:
            pass


def _v75_hide_show_media_buttons(browser, show):
    try:
        buttons = [browser.media_prev_btn, browser.media_next_btn, browser.media_open_btn]
        for b in buttons:
            if show:
                if not getattr(b, "_v75_packed", False):
                    b.pack(side="left", padx=(0, 4))
                    b._v75_packed = True
            else:
                if getattr(b, "_v75_packed", False):
                    b.pack_forget()
                    b._v75_packed = False
    except Exception:
        pass


def _v75_plot_or_overlay_selected(browser):
    paths = browser.selected_paths(plottable_only=True)
    if not paths:
        messagebox.showinfo("No files selected", "Select one or more CV/EIS/DRT/OCP/Tafel tables, photos, or movies in the data tree.", parent=browser)
        return
    media = _v70_media_paths(paths)
    tables = _v70_table_paths(paths)
    browser.clear_plot()
    browser.last_plot_paths = []
    if tables:
        for p in tables:
            try:
                browser._plot_file(p, clear=False)
            except Exception as exc:
                browser.log(f"Plot failed for {p.name}: {exc}")
        browser._finish_plot_axes()
        _v75_hide_show_media_buttons(browser, False)
    if media:
        _v70_display_media_paths(browser, media, 0)
        _v75_hide_show_media_buttons(browser, len(media) > 1)
    kind = _v75_kind_from_paths(paths)
    browser.current_technique_var.set(f"Detected: {kind} | plotted files: {len(paths)}")
    _v75_update_analysis_schema(browser, kind)
    _v75_store_current_view(browser, paths, kind)


def _v75_store_current_view(browser, paths=None, kind=None, name=None):
    try:
        if not hasattr(browser, "_v69_plot_views"):
            browser._v69_plot_views = []
        paths = paths or list(getattr(browser, "last_plot_paths", []) or [])
        kind = kind or _v75_kind_from_paths(paths)
        curves = []
        for c in getattr(browser, "curves", []):
            curves.append({k: (np.array(v).copy() if k in {"x", "y"} else v) for k, v in c.items()})
        view = {
            "name": name or f"{len(browser._v69_plot_views)+1:02d} {kind} ({len(paths)} file{'s' if len(paths)!=1 else ''})",
            "kind": kind,
            "paths": [str(Path(p)) for p in paths],
            "mode": browser.plot_mode_var.get(),
            "curves": curves,
        }
        browser._v69_plot_views.append(view)
        browser.plot_view_list.insert("end", view["name"])
        try:
            browser.plot_view_list.selection_clear(0, "end")
            browser.plot_view_list.selection_set("end")
            browser.plot_view_list.see("end")
        except Exception:
            pass
        browser.log(f"Added plot/view: {view['name']}")
    except Exception as exc:
        browser.log(f"Could not store plot/view: {exc}")


def _v75_load_plot_view(browser):
    try:
        sel = browser.plot_view_list.curselection()
        if not sel:
            return
        view = browser._v69_plot_views[sel[0]]
        browser.clear_plot()
        browser.plot_mode_var.set(view.get("mode", "Auto"))
        browser.last_plot_paths = [Path(p) for p in view.get("paths", [])]
        media = _v70_media_paths(browser.last_plot_paths)
        if media and not view.get("curves"):
            _v70_display_media_paths(browser, media, 0)
            _v75_hide_show_media_buttons(browser, len(media) > 1)
        else:
            for c in view.get("curves", []):
                browser.ax.plot(c["x"], c["y"], linewidth=1.6, label=c.get("label", "curve"))
                browser.curves.append(c)
            browser.ax.set_title(view.get("name", "Saved plot view"))
            browser._finish_plot_axes()
            _v75_hide_show_media_buttons(browser, False)
        kind = view.get("kind", _v75_kind_from_paths(browser.last_plot_paths))
        browser.current_technique_var.set(f"Detected: {kind} | view: {view.get('name')}")
        _v75_update_analysis_schema(browser, kind)
    except Exception as exc:
        browser.log(f"Could not load plot view: {exc}")


def _v75_rename_current_view(browser):
    try:
        sel = browser.plot_view_list.curselection()
        if not sel:
            messagebox.showinfo("No plot/view selected", "Select a plot/view first.", parent=browser)
            return
        idx = sel[0]
        old = browser._v69_plot_views[idx].get("name", "")
        new = simpledialog.askstring("Rename plot/view", "New plot/view name:", initialvalue=old, parent=browser)
        if not new:
            return
        browser._v69_plot_views[idx]["name"] = new
        browser.plot_view_list.delete(idx)
        browser.plot_view_list.insert(idx, new)
        browser.plot_view_list.selection_set(idx)
        browser.log(f"Renamed plot/view: {new}")
    except Exception as exc:
        browser.log(f"Rename failed: {exc}")


def _v75_browser_reset(browser):
    try:
        browser.clear_plot()
    except Exception:
        pass
    try:
        browser.comp_list.delete(0, "end")
        browser.suggestions = []
    except Exception:
        pass
    try:
        browser.plot_view_list.delete(0, "end")
        browser._v69_plot_views = []
    except Exception:
        pass
    try:
        browser.results_tree.delete(*browser.results_tree.get_children())
    except Exception:
        pass
    _v75_hide_show_media_buttons(browser, False)
    browser.current_technique_var.set("No data selected")
    browser.analysis_progress.configure(value=0)
    browser.analysis_progress_var.set("Analysis idle")
    _v75_update_analysis_schema(browser, "General")
    browser.log("Reset browser session: plots, plot/view list, AI suggestions, results, and analysis status cleared.")


def _v75_run_analysis_for_current_view(browser, force_kind=None):
    paths = _v75_get_selected_view_paths(browser)
    kind = force_kind or _v75_kind_from_paths(paths)
    browser.analysis_progress.configure(value=10)
    browser.analysis_progress_var.set(f"Running {kind} analysis...")
    browser.update_idletasks()
    results = []
    try:
        for idx, p in enumerate(paths):
            if Path(p).suffix.lower() not in _V70_TABLE_EXTS:
                continue
            if kind == "EIS":
                results.append(_v71_eis_quantities(p))
            elif kind == "CV / LSV":
                results.append(_v71_cv_quantities(p))
            else:
                results.append(_v75_generic_table_summary(p, kind))
            browser.analysis_progress.configure(value=min(95, 10 + int(80 * (idx + 1) / max(1, len(paths)))))
            browser.update_idletasks()
        outdir = browser.analyzed_root / "analysis_engine_results"
        outdir.mkdir(parents=True, exist_ok=True)
        out = outdir / f"{_v35_safe_name(browser.base_name)}_{_v35_safe_name(kind)}_browser_analysis.json"
        out.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
        _v75_insert_results_to_tree(browser, results)
        browser.analysis_progress.configure(value=100)
        browser.analysis_progress_var.set(f"{kind} analysis complete. Saved: {out.name}")
        browser.log(f"{kind} analysis complete: {out}")
    except Exception as exc:
        browser.analysis_progress.configure(value=0)
        browser.analysis_progress_var.set(f"Analysis failed: {exc}")
        browser.log(f"Analysis failed: {exc}")


def _v75_generic_table_summary(path, kind):
    df = _v64_read_table_file(path)
    return {
        "file": str(path),
        "type": kind,
        "rows": int(len(df)),
        "columns": [str(c) for c in df.columns],
        "warnings": ["Technique-specific quantitative analysis requires recognized CV/EIS/DRT/OCP/Tafel columns and metadata."],
        "assumptions": ["Raw data are preserved; summary is non-destructive."],
    }


def _v75_insert_results_to_tree(browser, results):
    try:
        browser.results_tree.delete(*browser.results_tree.get_children())
        for r in results:
            src = Path(r.get("file", "")).name
            if r.get("type") == "CV":
                for p in r.get("peaks", [])[:12]:
                    browser.results_tree.insert("", "end", values=(src, p.get("type", "peak"), f"{p.get('x','')}", f"{p.get('y','')}", f"{p.get('height_estimate','')}", ""))
                if "delta_Ep_V_estimate" in r:
                    browser.results_tree.insert("", "end", values=(src, "ΔEp", f"{r.get('delta_Ep_V_estimate'):.6g}", "V", "", ""))
            elif r.get("type") == "EIS":
                for key in ["Rs_ohm_estimate", "Rct_ohm_span_estimate", "minus_Zimag_max_ohm", "tau_peak_s_estimate"]:
                    if key in r:
                        browser.results_tree.insert("", "end", values=(src, key, "", f"{r.get(key):.6g}", "", ""))
            else:
                browser.results_tree.insert("", "end", values=(src, r.get("type", "summary"), "rows", r.get("rows", ""), "", ""))
    except Exception as exc:
        browser.log(f"Could not populate results tree: {exc}")


