def _v752_numeric_column_helpers(df):
    import pandas as _pd
    cols = list(df.columns)
    numeric = _v64_numeric_columns(df)
    low = {c: str(c).lower() for c in cols}

    def num(c):
        return _pd.to_numeric(df[c], errors="coerce").to_numpy(dtype=float)

    def find(words):
        for c in numeric:
            lc = low.get(c, str(c).lower())
            if any(w in lc for w in words):
                return c
        return None

    return numeric, num, find


def _v752_extract_xy(df, mode, x_choice=None, y_choice=None):
    """v75.2: explicit EIS Bode real, imag, and magnitude modes."""
    mode_l = str(mode or "").lower()
    try:
        numeric, num, find = _v752_numeric_column_helpers(df)
        freq = find(["freq", "frequency", "hz"])
        zr = find(["zreal", "z_real", "z'", "zre", "real"])
        zi = find(["zimag", "z_imag", "z''", "zim", "imag"])
        mag = find(["|z|", "zmod", "modulus", "magnitude", "mag", "z_abs", "zabs"])
        xcol = freq or (numeric[0] if numeric else None)

        if "bode real" in mode_l or "zreal" in mode_l and "bode" in mode_l:
            if xcol is None:
                return np.array([]), np.array([]), "", "", "Bode real needs frequency column"
            if zr:
                return num(xcol), num(zr), str(xcol), str(zr), "Bode real: Zreal vs frequency"
            return np.array([]), np.array([]), "", "", "Bode real needs Zreal column"

        if "bode imag" in mode_l or ("bode" in mode_l and ("zimag" in mode_l or "imag" in mode_l)):
            if xcol is None:
                return np.array([]), np.array([]), "", "", "Bode imag needs frequency column"
            if zi:
                return num(xcol), num(zi), str(xcol), str(zi), "Bode imag: Zimag vs frequency"
            return np.array([]), np.array([]), "", "", "Bode imag needs Zimag column"

        if "bode mag" in mode_l or "bode magnitude" in mode_l or ("bode" in mode_l and "phase" not in mode_l and "real" not in mode_l and "imag" not in mode_l):
            if xcol is None:
                return np.array([]), np.array([]), "", "", "Bode magnitude needs frequency column"
            if zr and zi:
                return num(xcol), np.sqrt(num(zr)**2 + num(zi)**2), str(xcol), "|Z| = sqrt(Zreal^2 + Zimag^2)", "Bode magnitude calculated from Zreal/Zimag"
            if mag:
                return num(xcol), np.abs(num(mag)), str(xcol), f"|{mag}|", "Bode magnitude column"
            if zi:
                return num(xcol), np.abs(num(zi)), str(xcol), f"|{zi}| (Zreal missing)", "Approximate magnitude from Zimag only; Zreal column missing"
            return np.array([]), np.array([]), "", "", "Bode magnitude needs Zreal/Zimag or |Z|"
    except Exception:
        pass
    if _V752_PREV_EXTRACT_XY is not None:
        return _V752_PREV_EXTRACT_XY(df, mode, x_choice=x_choice, y_choice=y_choice)
    return np.array([]), np.array([]), "", "", "No numeric axis pair"


try:
    _v70_extract_xy = _v752_extract_xy
except Exception:
    pass


def _v752_reset_plot_geometry(browser):
    """Reset figure layout after dashboard/multi-panel plots so the next single plot does not look squeezed."""
    try:
        fig = getattr(browser, "figure", None)
        if fig is not None:
            try:
                fig.set_tight_layout(False)
            except Exception:
                pass
            try:
                # Explicit single-axis margins; clears residual tight_layout/subplot params from dashboards.
                fig.subplots_adjust(left=0.105, right=0.965, bottom=0.12, top=0.90, wspace=0.25, hspace=0.25)
            except Exception:
                pass
        canvas = getattr(browser, "canvas", None)
        if canvas is not None:
            try:
                w = canvas.get_tk_widget()
                w.pack_configure(fill="both", expand=True)
                # This is only a minimum request to Tk; it prevents tiny canvas collapse on some Windows themes.
                w.configure(height=max(460, int(getattr(browser, "_v752_plot_min_height", 460))))
            except Exception:
                pass
    except Exception:
        pass


