def _v752_plot_xy(ax, x, y, label, logx=False, logy=False, marker_size_cutoff=220):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    mask = np.isfinite(x) & np.isfinite(y)
    x = x[mask]
    y = y[mask]
    if len(x) < 2:
        return False
    ax.plot(x, y, marker="o" if len(x) <= marker_size_cutoff else None, linewidth=1.25, markersize=2.4, label=label)
    if logx and np.nanmin(x) > 0:
        ax.set_xscale("log")
    if logy and np.nanmin(y) > 0:
        ax.set_yscale("log")
    return True


def _v752_eis_dashboard(browser):
    paths = _v75x_get_selected_view_paths(browser)
    tables = _v70_table_paths(paths)
    if not tables:
        try:
            messagebox.showinfo("No EIS tables", "Select or load an EIS plot/view first.", parent=browser)
        except Exception:
            pass
        return
    try:
        browser.figure.clear()
        axes = browser.figure.subplots(3, 2)
        ax_n, ax_re, ax_im, ax_mag, ax_phase, ax_txt = axes.ravel()
        summary_lines = ["EIS dashboard v75.2", "Bode panels: Zreal, Zimag, |Z|, phase", ""]
        plotted_any = False
        for p in tables:
            try:
                df = _v64_read_table_file(p)
                label = Path(p).stem[:45]
                x_n, y_n, xcol_n, ycol_n, det_n = _v70_extract_xy(df, "EIS Nyquist (-Zimag)")
                x_re, y_re, _, ycol_re, _ = _v70_extract_xy(df, "Bode real (Zreal)")
                x_im, y_im, _, ycol_im, _ = _v70_extract_xy(df, "Bode imag (Zimag)")
                x_mag, y_mag, _, ycol_mag, _ = _v70_extract_xy(df, "Bode mag |Z|")
                x_ph, y_ph, _, ycol_ph, _ = _v70_extract_xy(df, "Bode phase")
                plotted_any = _v752_plot_xy(ax_n, x_n, y_n, label, logx=False, logy=False) or plotted_any
                _v752_plot_xy(ax_re, x_re, y_re, label, logx=True, logy=False)
                _v752_plot_xy(ax_im, x_im, y_im, label, logx=True, logy=False)
                _v752_plot_xy(ax_mag, x_mag, y_mag, label, logx=True, logy=True)
                _v752_plot_xy(ax_phase, x_ph, y_ph, label, logx=True, logy=False)
                try:
                    r = _v71_eis_quantities(p)
                    line = f"{Path(p).name}: Rs≈{r.get('Rs_ohm_estimate','?')} Ω; |Z|max≈{r.get('Zmag_max_ohm','?')} Ω; f={r.get('frequency_min_Hz','?')}–{r.get('frequency_max_Hz','?')} Hz"
                    summary_lines.append(line[:170])
                except Exception:
                    summary_lines.append(f"{Path(p).name}: plotted")
            except Exception as exc:
                summary_lines.append(f"{Path(p).name}: failed ({exc})")
        ax_n.set_title("Nyquist")
        ax_n.set_xlabel("Zreal / Ω")
        ax_n.set_ylabel("-Zimag / Ω")
        ax_re.set_title("Bode real")
        ax_re.set_xlabel("Frequency / Hz")
        ax_re.set_ylabel("Zreal / Ω")
        ax_im.set_title("Bode img")
        ax_im.set_xlabel("Frequency / Hz")
        ax_im.set_ylabel("Zimag / Ω")
        ax_mag.set_title("Bode mag")
        ax_mag.set_xlabel("Frequency / Hz")
        ax_mag.set_ylabel("|Z| / Ω")
        ax_phase.set_title("Bode phase")
        ax_phase.set_xlabel("Frequency / Hz")
        ax_phase.set_ylabel("Phase / degree")
        for ax in [ax_n, ax_re, ax_im, ax_mag, ax_phase]:
            ax.grid(True, alpha=0.25)
            try:
                if len(tables) <= 10:
                    ax.legend(fontsize=6, loc="best")
            except Exception:
                pass
        ax_txt.axis("off")
        ax_txt.set_title("Summary / warnings")
        ax_txt.text(0.02, 0.98, "\n".join(summary_lines[:22]), va="top", ha="left", fontsize=7.5)
        try:
            browser.figure.tight_layout(rect=[0.01, 0.01, 0.99, 0.96])
        except Exception:
            pass
        browser.canvas.draw_idle()
        browser.ax = ax_n
        browser.current_technique_var.set(f"Detected: EIS | v75.2 dashboard files: {len(tables)}")
        if plotted_any:
            _v75x_store_current_view(browser, tables, "EIS", name=f"{len(getattr(browser,'_v69_plot_views',[]))+1:02d} EIS Bode real/img/mag dashboard ({len(tables)} files)")
    except Exception as exc:
        try:
            browser.log(f"EIS v75.2 dashboard failed: {exc}")
        except Exception:
            pass
        if _V752_PREV_EIS_DASHBOARD is not None:
            try:
                return _V752_PREV_EIS_DASHBOARD(browser)
            except Exception:
                pass

