def _v752_eis_quantities(path):
    result = _V752_PREV_EIS_QUANTITIES(path) if _V752_PREV_EIS_QUANTITIES is not None else {"file": str(path), "type": "EIS", "warnings": [], "assumptions": []}
    try:
        df = _v64_read_table_file(path)
        f_re, zre, _, _, _ = _v70_extract_xy(df, "Bode real (Zreal)")
        f_im, zim, _, _, _ = _v70_extract_xy(df, "Bode imag (Zimag)")
        f_mag, zmag, _, _, _ = _v70_extract_xy(df, "Bode mag |Z|")
        if len(zre):
            result["Zreal_min_ohm"] = float(np.nanmin(zre))
            result["Zreal_max_ohm"] = float(np.nanmax(zre))
        if len(zim):
            result["Zimag_min_ohm"] = float(np.nanmin(zim))
            result["Zimag_max_ohm"] = float(np.nanmax(zim))
        if len(zmag):
            result["Zmag_min_ohm"] = float(np.nanmin(zmag))
            result["Zmag_max_ohm"] = float(np.nanmax(zmag))
        result.setdefault("assumptions", []).append("v75.2 Bode outputs include Zreal(f), Zimag(f), and |Z|(f); phase remains available but is not a substitute for real/imag impedance trends.")
    except Exception as exc:
        result.setdefault("warnings", []).append(f"v75.2 Bode real/img/mag summary failed: {exc}")
    return result

