# ---------- Analysis Engines window: source from browser Plot/view list only ----------

def _v752_browser_plot_views(owner):
    views = []
    try:
        raw = list(getattr(owner, "_v69_plot_views", []) or [])
        for i, v in enumerate(raw):
            if not isinstance(v, dict):
                continue
            paths = [Path(p) for p in v.get("paths", []) if str(p)]
            if not paths and v.get("curves"):
                for c in v.get("curves", []):
                    if isinstance(c, dict) and c.get("path"):
                        paths.append(Path(c.get("path")))
            views.append({
                "index": i,
                "name": v.get("name") or f"Plot/view {i+1}",
                "kind": v.get("kind") or _v75_kind_from_paths(paths),
                "paths": paths,
                "mode": v.get("mode", "Auto"),
            })
    except Exception:
        pass
    return views


