def _v752_engine_detect_session_data(self):
    try:
        self.file_tree.delete(*self.file_tree.get_children())
    except Exception:
        pass
    self._file_by_iid = {}
    self._view_by_iid = {}
    views = _v752_browser_plot_views(getattr(self, "owner", None))
    if views:
        for view in views:
            iid = self.file_tree.insert("", "end", text=view["name"], values=(view["kind"], str(len(view["paths"]))))
            self._view_by_iid[iid] = view
            self._file_by_iid[iid] = view["paths"]
            for p in view["paths"][:50]:
                try:
                    child = self.file_tree.insert(iid, "end", text=Path(p).name, values=(_v71_guess_table_type(p), ""))
                    self._file_by_iid[child] = [Path(p)]
                except Exception:
                    pass
        self.file_tree.selection_set(self.file_tree.get_children()[0])
        try:
            self.file_tree.item(self.file_tree.get_children()[0], open=True)
        except Exception:
            pass
        source_msg = f"Loaded {len(views)} browser plot/view item(s). Select one or more views to analyze."
    else:
        iid = self.file_tree.insert("", "end", text="No browser plot/view items yet", values=("", ""))
        self._file_by_iid[iid] = []
        source_msg = "No browser plot/view items found. Go back to Data Browser, select files, click Plot / overlay selected, then reopen or refresh this window."

    try:
        self.engine_tree.delete(*self.engine_tree.get_children())
    except Exception:
        pass
    self._engine_by_iid = {}
    for e in self.engines:
        ok, _ = _v71_module_available(e.import_check)
        status = "available" if (ok or not e.import_check) else "missing"
        iid = self.engine_tree.insert("", "end", text=e.name, values=(e.category, status, ", ".join(e.supported_data_types)))
        self._engine_by_iid[iid] = e
    try:
        self.log(source_msg)
    except Exception:
        try:
            self.status_var.set(source_msg)
        except Exception:
            pass

