# ---- v75.3 launch-session isolation and tracking ----
# User-requested behavior:
# * The main BAT creates a unique launch/session folder before the GUI starts.
# * Every FaradaIQ window launched from that BAT receives a distinct session ID.
# * The session ID and folder are visible in the main GUI and data-browser window.
# * The launch folder is tracking-only: logs, session ID, activity tracker,
#   dependency checks, and process context.
# * Browser sessions, audit JSON, report bundles, engine outputs, figures,
#   exports, and AI bundles stay with the chosen data/output root, not here.

APP_TITLE = "FaradaIQ Studio v273"


def _v753_launch_context():
    import os as _os
    import uuid as _uuid
    from pathlib import Path as _Path
    from datetime import datetime as _datetime

    sid = (_os.environ.get("FARADAIQ_SESSION_ID") or "").strip()
    launch_root = (_os.environ.get("FARADAIQ_LAUNCH_ROOT") or "").strip()
    session_dir = (_os.environ.get("FARADAIQ_SESSION_DIR") or "").strip()

    if not sid:
        sid = "FQ_" + _datetime.now().strftime("%Y%m%d_%H%M%S_%f")[:-3] + "_" + _uuid.uuid4().hex[:6].upper()
        _os.environ["FARADAIQ_SESSION_ID"] = sid
    if not launch_root:
        launch_root = str(_Path(__file__).resolve().parent / "FaradaIQ_launch_sessions")
        _os.environ["FARADAIQ_LAUNCH_ROOT"] = launch_root
    if not session_dir:
        session_dir = str(_Path(launch_root) / sid)
        _os.environ["FARADAIQ_SESSION_DIR"] = session_dir

    sdir = _Path(session_dir).resolve()
    # Tracking-only folder: do not create analysis/output/report subfolders here.
    # Real scientific outputs are saved under the selected data/output root.
    subfolders = ["logs", "activity"]
    for sub in subfolders:
        try:
            (sdir / sub).mkdir(parents=True, exist_ok=True)
        except Exception:
            pass

    ctx = {
        "session_id": sid,
        "launch_root": str(_Path(launch_root).resolve()),
        "session_dir": str(sdir),
        "logs_dir": str(sdir / "logs"),
        "tracking_dir": str(sdir),
        "created_or_seen": _datetime.now().isoformat(timespec="seconds"),
        "pid": _os.getpid(),
        "script": str(_Path(__file__).resolve()),
    }
    try:
        info_path = sdir / "session_context.json"
        if not info_path.exists():
            info_path.write_text(json.dumps(_v75_json_safe(ctx), ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    return ctx


def _v753_session_dir_path(*parts):
    from pathlib import Path as _Path
    ctx = _v753_launch_context()
    p = _Path(ctx["session_dir"])
    for part in parts:
        if part:
            p = p / str(part)
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return p


def _v753_track_event(event, payload=None):
    from datetime import datetime as _datetime
    import os as _os
    try:
        ctx = _v753_launch_context()
        rec = {
            "time": _datetime.now().isoformat(timespec="seconds"),
            "session_id": ctx.get("session_id"),
            "pid": _os.getpid(),
            "event": str(event),
            "payload": _v75_json_safe(payload or {}),
        }
        p = _v753_session_dir_path("logs", "faradaiq_session_tracker.jsonl")
        with open(p, "a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    except Exception:
        pass


def _v753_short_session_label(ctx=None):
    ctx = ctx or _v753_launch_context()
    return str(ctx.get("session_id", "FaradaIQ session"))


def _v753_open_session_folder(ctx=None):
    import os as _os
    import webbrowser as _webbrowser
    from pathlib import Path as _Path
    try:
        ctx = ctx or _v753_launch_context()
        p = _Path(ctx.get("session_dir", ".")).resolve()
        try:
            _os.startfile(str(p))
        except Exception:
            _webbrowser.open(p.as_uri())
        _v753_track_event("open_session_folder", {"session_dir": str(p)})
    except Exception:
        pass


def _v753_copy_session_id(widget=None, ctx=None):
    try:
        ctx = ctx or _v753_launch_context()
        root = widget.winfo_toplevel() if widget is not None else None
        if root is not None:
            root.clipboard_clear()
            root.clipboard_append(str(ctx.get("session_id", "")))
        _v753_track_event("copy_session_id", {"session_id": ctx.get("session_id")})
    except Exception:
        pass


def _v753_add_session_banner(window, title="Launch session"):
    """Add a visible session ID/folder row near the top of a Tk/Toplevel window."""
    try:
        if getattr(window, "_v753_session_banner_added", False):
            return
        ctx = _v753_launch_context()
        children = list(window.winfo_children())
        first_child = children[0] if children else None
        try:
            frame = ttk.Frame(window, style="Card.TFrame", padding=(8, 4))
        except Exception:
            frame = ttk.Frame(window, padding=(8, 4))
        if first_child is not None:
            try:
                frame.pack(fill="x", padx=6, pady=(4, 2), before=first_child)
            except Exception:
                frame.pack(fill="x", padx=6, pady=(4, 2))
        else:
            frame.pack(fill="x", padx=6, pady=(4, 2))

        msg = f"{title}: {ctx.get('session_id')}"
        try:
            ttk.Label(frame, text=msg, style="Section.TLabel").pack(side="left", padx=(0, 10))
        except Exception:
            ttk.Label(frame, text=msg).pack(side="left", padx=(0, 10))
        folder_text = f"Tracking folder only: {ctx.get('session_dir')}"
        try:
            ttk.Label(frame, text=folder_text, style="Muted.TLabel").pack(side="left", fill="x", expand=True)
        except Exception:
            ttk.Label(frame, text=folder_text).pack(side="left", fill="x", expand=True)
        ttk.Button(frame, text="Copy ID", command=lambda w=window, c=ctx: _v753_copy_session_id(w, c)).pack(side="right", padx=(5, 0))
        ttk.Button(frame, text="Open tracking folder", command=lambda c=ctx: _v753_open_session_folder(c)).pack(side="right", padx=(5, 0))
        window._v753_session_banner_added = True
    except Exception:
        pass


def _v753_apply_title(window, base="FaradaIQ Studio v273"):
    try:
        ctx = _v753_launch_context()
        window.title(f"{base} — session {ctx.get('session_id')}")
    except Exception:
        pass


