def _v753_session_reader_gui_init(self, *args, **kwargs):
    ctx = _v753_launch_context()
    if _V753_PREV_ROOT_INIT is not None:
        _V753_PREV_ROOT_INIT(self, *args, **kwargs)
    else:
        super(SessionReaderGUI, self).__init__(*args, **kwargs)
    try:
        self._faradaiq_launch_context = ctx
        _v753_apply_title(self, "FaradaIQ Studio v273")
        _v753_add_session_banner(self, "FaradaIQ launch session")
        try:
            # v75.5: launch session folder is tracking-only. Keep the normal
            # output folder at the BAT/app root unless the user changes it.
            if hasattr(self, "output_dir_var"):
                current = str(self.output_dir_var.get() or "").strip()
                if (not current) or (str(ctx.get("session_dir", "")) in current):
                    self.output_dir_var.set(str(Path.cwd()))
        except Exception:
            pass
        try:
            self.after(700, lambda w=self: (_v753_apply_title(w, "FaradaIQ Studio v273"), _v753_add_session_banner(w, "FaradaIQ launch session")))
        except Exception:
            pass
        _v753_track_event("main_window_open", {"title": "FaradaIQ Studio v273", "session_dir": ctx.get("session_dir")})
    except Exception:
        pass


