def _v754_browser_plot_views(owner):
    candidates = []
    if owner is not None:
        candidates.append(owner)
    # If called from the main window, use the most recently opened browser with plot/views.
    for b in list(_FARADAIQ_BROWSER_WINDOWS_V754)[::-1]:
        if b not in candidates:
            candidates.append(b)
    views = []
    for src in candidates:
        try:
            raw = list(getattr(src, "_v69_plot_views", []) or [])
            names_from_list = []
            try:
                if hasattr(src, "plot_view_list"):
                    names_from_list = [src.plot_view_list.get(i) for i in range(src.plot_view_list.size())]
            except Exception:
                names_from_list = []
            for i, v in enumerate(raw):
                if not isinstance(v, dict):
                    continue
                paths = []
                for p in v.get("paths", []) or []:
                    if p:
                        paths.append(Path(p))
                for c in v.get("curves", []) or []:
                    if isinstance(c, dict) and c.get("path"):
                        paths.append(Path(c.get("path")))
                # de-duplicate while preserving order
                dedup = []
                seen = set()
                for p in paths:
                    key = str(p)
                    if key not in seen:
                        dedup.append(p)
                        seen.add(key)
                name = v.get("name") or (names_from_list[i] if i < len(names_from_list) else f"Plot/view {i+1}")
                views.append({
                    "index": i,
                    "name": str(name),
                    "kind": v.get("kind") or _v75_kind_from_paths(dedup),
                    "mode": v.get("mode", "Auto"),
                    "paths": dedup,
                    "source_browser": src,
                })
            if views:
                break
        except Exception:
            continue
    return views


def _v754_engine_build_ui(self):
    outer = ttk.Frame(self, style="Card.TFrame", padding=(10, 10))
    outer.pack(fill="both", expand=True, padx=8, pady=8)
    ttk.Label(outer, text="Analysis Engines & Reference Comparison", style="Section.TLabel").pack(anchor="w")
    ttk.Label(
        outer,
        text="v75.4 source mode: this window analyzes only Plot/view items created in the Data Browser. It will not scan or list all session/raw files.",
        style="Muted.TLabel",
        wraplength=1120,
    ).pack(anchor="w", pady=(2, 8))

    action = ttk.LabelFrame(outer, text="Actions — always visible", padding=(8, 6))
    action.pack(fill="x", pady=(0, 8))
    for label, cmd in [
        ("Refresh Plot/view source", self.detect_session_data),
        ("Check engine packages", self.check_engines),
        ("Run selected Plot/view analysis", self.run_analysis),
        ("Scientific interpretation prompt", self.generate_interpretation_prompt),
        ("AI prompt with current analysis context", self.generate_context_prompt_with_llm),
        ("Export results", self.export_results),
        ("Open analyzed-data folder", self.open_folder),
    ]:
        ttk.Button(action, text=label, command=cmd).pack(side="left", padx=(0, 6), pady=1)

    main = ttk.Panedwindow(outer, orient="horizontal")
    main.pack(fill="both", expand=True)
    left = ttk.Frame(main, style="Card.TFrame", padding=(6, 6))
    right = ttk.Frame(main, style="Card.TFrame", padding=(8, 6))
    main.add(left, weight=2)
    main.add(right, weight=3)

    ttk.Label(left, text="Browser Plot/view list only", style="Section.TLabel").pack(anchor="w")
    src_note = tk.StringVar(value="Create Plot/view items in the Data Browser, then refresh here.")
    self._v754_source_note_var = src_note
    ttk.Label(left, textvariable=src_note, style="Muted.TLabel", wraplength=470).pack(anchor="w", pady=(1, 4))

    fframe = ttk.Frame(left, style="Card.TFrame")
    fframe.pack(fill="both", expand=True, pady=(0, 8))
    self.file_tree = ttk.Treeview(fframe, columns=("technique", "mode", "files"), show="tree headings", selectmode="extended", height=16)
    self.file_tree.heading("#0", text="Plot/view item")
    self.file_tree.heading("technique", text="Technique")
    self.file_tree.heading("mode", text="Mode")
    self.file_tree.heading("files", text="Files")
    self.file_tree.column("#0", width=360, stretch=True)
    self.file_tree.column("technique", width=105, stretch=False)
    self.file_tree.column("mode", width=145, stretch=False)
    self.file_tree.column("files", width=55, stretch=False)
    self.file_tree.pack(side="left", fill="both", expand=True)
    fy = ttk.Scrollbar(fframe, orient="vertical", command=self.file_tree.yview)
    self.file_tree.configure(yscrollcommand=fy.set)
    fy.pack(side="right", fill="y")

    ttk.Label(left, text="Available engines", style="Section.TLabel").pack(anchor="w")
    self.engine_tree = ttk.Treeview(left, columns=("category", "status", "types"), show="tree headings", selectmode="browse", height=8)
    self.engine_tree.heading("#0", text="Engine")
    for c, t, w in [("category", "Category", 120), ("status", "Status", 90), ("types", "Data types", 170)]:
        self.engine_tree.heading(c, text=t)
        self.engine_tree.column(c, width=w, stretch=True)
    self.engine_tree.pack(fill="both", expand=True, pady=(4, 4))

    ttk.Label(right, text="Results, assumptions, warnings, and selected Plot/view source", style="Section.TLabel").pack(anchor="w")
    self.results_text = ScrolledText(right, wrap="word")
    self.results_text.pack(fill="both", expand=True, pady=(4, 8))
    try:
        self.results_text.configure(background="#020617", foreground="#e5eefb", insertbackground="#f8fafc", font=("Consolas", 9))
    except Exception:
        pass
    bottom = ttk.Frame(right, style="Card.TFrame")
    bottom.pack(fill="x")
    ttk.Button(bottom, text="↗ Results popout", command=lambda: _v70_open_text_snapshot(self, "Analysis engine results", self.results_text.get("1.0", "end").splitlines())).pack(side="left")
    self.status_var = tk.StringVar(value="Ready")
    ttk.Label(outer, textvariable=self.status_var, style="Status.TLabel").pack(anchor="w", pady=(8, 0))


def _v754_engine_detect_session_data(self):
    try:
        self.file_tree.delete(*self.file_tree.get_children())
    except Exception:
        pass
    self._file_by_iid = {}
    self._view_by_iid = {}
    views = _v754_browser_plot_views(getattr(self, "owner", None))
    if views:
        for view in views:
            label = view.get("name") or f"Plot/view {view.get('index', 0)+1}"
            iid = self.file_tree.insert("", "end", text=label, values=(view.get("kind", ""), view.get("mode", ""), str(len(view.get("paths", [])))))
            self._view_by_iid[iid] = view
            self._file_by_iid[iid] = [Path(p) for p in view.get("paths", [])]
        try:
            first = self.file_tree.get_children()[0]
            self.file_tree.selection_set(first)
        except Exception:
            pass
        msg = f"Loaded {len(views)} browser Plot/view item(s). Select one or more Plot/view rows and run analysis. Raw/session files are intentionally hidden."
    else:
        iid = self.file_tree.insert("", "end", text="No Plot/view items yet", values=("", "", "0"))
        self._file_by_iid[iid] = []
        msg = "No Plot/view items found. In the Data Browser, select data in the smart tree, click Plot / overlay selected, then refresh this window."
    try:
        if hasattr(self, "_v754_source_note_var"):
            self._v754_source_note_var.set(msg)
    except Exception:
        pass

    try:
        self.engine_tree.delete(*self.engine_tree.get_children())
    except Exception:
        pass
    self._engine_by_iid = {}
    for e in self.engines:
        try:
            ok, _ = _v71_module_available(e.import_check)
            status = "available" if (ok or not e.import_check) else "missing"
            iid = self.engine_tree.insert("", "end", text=e.name, values=(e.category, status, ", ".join(e.supported_data_types)))
            self._engine_by_iid[iid] = e
        except Exception:
            pass
    try:
        self.results_text.delete("1.0", "end")
        self.log(msg)
        if views:
            self.log("\nPlot/view source rows:")
            for i, v in enumerate(views, 1):
                self.log(f"  {i:02d}. {v.get('name')} | {v.get('kind')} | {len(v.get('paths', []))} source file(s)")
    except Exception:
        try:
            self.status_var.set(msg)
        except Exception:
            pass


def _v754_engine_selected_files(self):
    selected_paths = []
    try:
        sel = self.file_tree.selection()
    except Exception:
        sel = []
    if not sel:
        return []
    for iid in sel:
        for p in getattr(self, "_file_by_iid", {}).get(iid, []) or []:
            try:
                pp = Path(p)
                if pp.suffix.lower() in _V754_TABLE_EXTS:
                    selected_paths.append(pp)
            except Exception:
                pass
    out, seen = [], set()
    for p in selected_paths:
        key = str(p)
        if key not in seen:
            out.append(p); seen.add(key)
    return out


def _v754_engine_run_analysis(self):
    try:
        _v753_track_event("analysis_engine_run_started", {"source": "plot_view_only_v754", "base_name": getattr(self, "base_name", "")})
    except Exception:
        pass
    files = self.selected_files()
    self.results = []
    try:
        self.results_text.delete("1.0", "end")
    except Exception:
        pass
    if not files:
        self.log("No Plot/view table files selected. Create/select a Plot/view in the Data Browser, refresh this window, then select the Plot/view row.")
        return
    self.log(f"Running compatible analysis on {len(files)} table file(s) from selected Data Browser Plot/view item(s).")
    for p in files:
        kind = _v71_guess_table_type(p)
        try:
            if kind == "EIS":
                self.results.append(_v71_eis_quantities(p))
            elif kind == "CV / LSV":
                self.results.append(_v71_cv_quantities(p))
            elif kind == "DRT":
                self.results.append(_v75_drt_quantities(p))
            elif kind == "OCP":
                self.results.append(_v75_ocp_quantities(p))
            elif kind == "IV / Tafel":
                self.results.append(_v75_tafel_quantities(p))
            else:
                self.results.append(_v75_generic_table_summary(p, kind))
        except Exception as exc:
            self.results.append({"file": str(p), "type": kind, "error": str(exc)})
    out = self._outdir() / f"{_v35_safe_name(self.base_name)}_plot_view_analysis_engine_results_v754.json"
    _v71_write_session_json(out, self.results)
    self.log(json.dumps(_v75_json_safe(self.results), ensure_ascii=False, indent=2))
    self.log(f"Saved Plot/view-source analysis results: {out}")
    try:
        _v753_track_event("analysis_engine_run_finished", {"source": "plot_view_only_v754", "base_name": getattr(self, "base_name", ""), "out": str(out)})
    except Exception:
        pass


