def _v755_session_reader_gui_init(self, *args, **kwargs):
    if _V755_PREV_ROOT_INIT is not None:
        _V755_PREV_ROOT_INIT(self, *args, **kwargs)
    try:
        ctx = _v753_launch_context()
        _v753_apply_title(self, "FaradaIQ Studio v273")
        # Ensure output root is not silently set to the tracking folder.
        if hasattr(self, "output_dir_var"):
            cur = str(self.output_dir_var.get() or "").strip()
            session_dir = str(ctx.get("session_dir", ""))
            if session_dir and session_dir.lower() in cur.lower():
                self.output_dir_var.set(str(Path.cwd()))
        _v753_track_event("main_window_open_v755", {"tracking_only_session_dir": ctx.get("session_dir")})
    except Exception:
        pass


