# ---- v75.6 generalized smart data tree for any experiment/parser ----
# User-requested improvement:
# * Apply smart tree logic broadly, not only to HEKA/POTMASTER exports.
# * Build tree from AI-bundle/manifests when available, but also infer structure from
#   folder organization, vendor signatures, file headers, filenames, scan rates,
#   potentials, cycles, replicates, locations, and common electrochemical/spectroscopy formats.
# * The launch-session folder remains tracking-only; smart-tree metadata is written with
#   the selected data analysis root, not inside FaradaIQ_launch_sessions.

APP_TITLE = "FaradaIQ Studio v273"

_V756_DATA_EXTS = set(_V754_DATA_EXTS) | {
    ".dat", ".dta", ".mpr", ".mpt", ".ids", ".idf", ".isw", ".pssession",
    ".spc", ".dx", ".jdx", ".spa", ".0", ".1", ".2",
    ".tif", ".tiff", ".bmp", ".gif", ".webp", ".mp4", ".avi", ".mov", ".wmv",
}
_V756_MEDIA_EXTS = {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".gif", ".webp", ".mp4", ".avi", ".mov", ".wmv", ".svg", ".pdf"}
_V756_TABLE_LIKE_EXTS = {".csv", ".txt", ".tsv", ".asc", ".dat", ".dta", ".mpt", ".ids", ".idf", ".xlsx", ".xls"}
_V756_AI_JSON_HINTS = {"ai", "bundle", "manifest", "index", "parse", "parsed", "structure", "metadata", "schema", "tree", "map"}


def _v756_norm_text(s):
    return re.sub(r"\s+", " ", str(s or "").replace("\ufeff", " ")).strip()


def _v756_clean_token(s):
    s = _v756_norm_text(s)
    s = re.sub(r"[_\-]+", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s


def _v756_file_head_text(p, max_bytes=65536):
    """Return a small text signature for content-based technique/vendor detection."""
    try:
        p = Path(p)
        if p.suffix.lower() in _V756_MEDIA_EXTS:
            return ""
        data = p.read_bytes()[:max_bytes]
        # Avoid spending time decoding obvious binary blobs.
        if b"\x00" in data[:2048] and p.suffix.lower() not in {".dta", ".mpr", ".h5", ".hdf5"}:
            return ""
        return data.decode("utf-8", errors="ignore") or data.decode("latin-1", errors="ignore")
    except Exception:
        return ""


def _v756_vendor_from_text(path, head=""):
    s = f"{Path(path).name} {Path(path).parent.as_posix()} {head[:5000]}".lower()
    vendors = [
        ("HEKA / POTMASTER", ["heka", "potmaster", "patchmaster", "__m", "__c"]),
        ("Gamry", ["gamry", "explain gamry", "zcur", "zreal", "zimag", ".dta"]),
        ("BioLogic", ["biologic", "ec-lab", ".mpr", ".mpt", "ewe/", "i/<ma>"]),
        ("CHI", ["chi", "ch instruments", "potential/v", "current/a"]),
        ("VersaSTAT / Princeton", ["versastat", "princeton", "powersuite", "versa studio"]),
        ("PalmSens", ["palmsens", "pssession", "pstouch"]),
        ("Metrohm Autolab", ["autolab", "nova", "metrohm"]),
        ("ZView / ZPlot", ["zview", "zplot", "scribner"]),
        ("Ivium", ["ivium", "iviumsoft"]),
        ("Generic table", ["potential", "current", "frequency", "zreal", "zimag"]),
    ]
    for vendor, pats in vendors:
        if any(pat in s for pat in pats):
            return vendor
    return ""


def _v756_normalize_technique(value, path=None, head=""):
    raw = str(value or "")
    s = f"{raw} {Path(path).name if path else ''} {Path(path).parent.as_posix() if path else ''} {head[:10000]}".lower()
    # Electrochemical impedance first because EIS files often also contain voltage/current words.
    if any(k in s for k in ["eis", "impedance", "nyquist", "bode", "zreal", "z_real", "re(z)", "z'", "zimag", "z_imag", "-zim", "frequency/hz", "freq/hz", "|z|", "zmod"]):
        return "EIS"
    if any(k in s for k in ["drt", "distribution of relaxation", "relaxation time", "tau", "gamma"]):
        return "DRT"
    if any(k in s for k in ["cyclic volt", "cyclic_volt", "cv", "lsv", "linear sweep", "voltam", "current_vs_potential", "ewe/v", "potential/v,current", "current/a"]):
        # Avoid classifying all generic current files as CV if time dominates.
        if not any(k in s for k in ["ocp", "open circuit", "open_circuit", "potential_vs_time"]):
            return "CV / LSV"
    if any(k in s for k in ["tafel", "polarization", "potentiodynamic", "iv curve", "i-v", "i_vs_v", "current voltage"]):
        return "IV / Tafel"
    if any(k in s for k in ["ocp", "open circuit", "open_circuit", "potential_vs_time", "open-circuit"]):
        return "OCP"
    if any(k in s for k in ["chronoamper", "chrono amp", "ca", "current_vs_time"]):
        return "Chronoamperometry"
    if any(k in s for k in ["chronopot", "chronopotenti", "cp", "potential_vs_time"]):
        return "Chronopotentiometry"
    if any(k in s for k in ["raman", "sers", "wavenumber", "raman shift", "cm-1", "cm^-1"]):
        return "Raman / SERS"
    if any(k in s for k in ["ftir", "irras", "infrared", "transmittance", "absorbance"]):
        return "FTIR / IR"
    if any(k in s for k in ["uv-vis", "uvvis", "uv_vis", "absorbance", "wavelength", "nm"]):
        return "UV-Vis"
    if any(k in s for k in ["xrd", "2theta", "2 theta", "diffraction"]):
        return "XRD"
    if any(k in s for k in ["xps", "binding energy"]):
        return "XPS"
    if any(k in s for k in ["eqcm", "qcm", "frequency shift", "mass change"]):
        return "EQCM"
    if path and Path(path).suffix.lower() in _V756_MEDIA_EXTS:
        return "Media / image"
    return raw if raw and raw not in {"Other", "Tables / text"} else ("Tables / text" if path and Path(path).suffix.lower() in _V756_TABLE_LIKE_EXTS else "Other")


def _v756_kind_from_content_or_path(path, fallback=""):
    p = Path(path)
    head = _v756_file_head_text(p)
    kind = _v756_normalize_technique(fallback, p, head)
    # If broad table detection returned only table/other, try explicit column heuristics.
    if kind in {"Other", "Tables / text", ""}:
        h = head.lower()
        has_pot = any(k in h for k in ["potential", "ewe", "voltage", "e/v", "ewe/v", "v vs"])
        has_cur = any(k in h for k in ["current", "i/a", "i<", "<i>", "ma", "ua"])
        has_time = any(k in h for k in ["time", "t/s", "elapsed"])
        has_freq = any(k in h for k in ["freq", "frequency", "hz"])
        has_z = any(k in h for k in ["zreal", "z_real", "zimag", "z_imag", "zmod", "zph", "phase", "ohm", "impedance"])
        if has_freq and has_z:
            kind = "EIS"
        elif has_pot and has_cur:
            kind = "CV / LSV"
        elif has_time and has_pot and not has_cur:
            kind = "OCP"
    return kind or "Other"


def _v756_parse_generic_id(text, names, label, width=None):
    t = str(text or "")
    joined = "|".join(names)
    pats = [
        rf"(?:^|[_\-\s])(?:{joined})[_\-\s:=#]*([A-Za-z]?\d{{1,6}})(?=$|[_\-\s])",
        rf"(?:^|[_\-\s])([A-Za-z]?\d{{1,6}})[_\-\s]*(?:{joined})(?=$|[_\-\s])",
    ]
    for pat in pats:
        m = re.search(pat, t, flags=re.I)
        if m:
            val = m.group(1)
            if width and re.fullmatch(r"\d+", val):
                val = f"{int(val):0{width}d}"
            return f"{label} {val}"
    return ""


def _v756_parse_point_label(text):
    return (_v754_parse_point_label(text)
            or _v756_parse_generic_id(text, ["position", "pos", "spot", "site", "pixel", "px", "loc", "location", "well", "cell", "sample"], "position"))


def _v756_parse_replicate_label(text):
    return _v756_parse_generic_id(text, ["rep", "replicate", "repeat", "trial", "duplicate"], "replicate")


def _v756_parse_step_label(text):
    return _v756_parse_generic_id(text, ["step", "stage", "sequence", "seq", "loop", "segment", "seg"], "step")


def _v756_parse_cycle_label(text):
    mc = _v754_parse_measurement_cycle(text)
    cyc = mc.get("cycle") or ""
    if cyc:
        return cyc
    return _v756_parse_generic_id(text, ["cycle", "cyc", "scan"], "cycle")


def _v756_parse_measurement_label(text):
    mc = _v754_parse_measurement_cycle(text)
    meas = mc.get("measurement") or ""
    if meas:
        return meas
    return _v756_parse_generic_id(text, ["measurement", "meas", "sweep", "series", "spectrum", "frame", "map"], "measurement", width=3)


def _v756_parse_temperature_label(text):
    t = str(text or "")
    m = re.search(r"(?:temp|temperature|T)[_\-\s:=]*([+\-]?\d+(?:[p\.]\d+)?)\s*(C|K|degC|°C)?", t, flags=re.I)
    if m:
        return f"{m.group(1).replace('p', '.')} {m.group(2) or 'C'}"
    return ""


def _v756_parse_frequency_label(text):
    t = str(text or "")
    m = re.search(r"(?:freq|frequency|f)[_\-\s:=]*([0-9]+(?:[p\.]\d+)?)\s*(Hz|kHz|MHz|mHz)?", t, flags=re.I)
    if m:
        return f"{m.group(1).replace('p', '.')} {m.group(2) or 'Hz'}"
    return ""


def _v756_experiment_prefix_from_name(path):
    p = Path(path)
    s = p.stem
    # Remove vendor/parser suffixes and common parameter tokens. This keeps arbitrary samples tidy.
    s = re.split(r"__(current|voltage|impedance|zreal|zimag|ocp|eis|cv|drt|table|metadata)", s, flags=re.I)[0]
    s = re.split(r"__m\d+", s, flags=re.I)[0]
    s = re.split(r"__c\d+", s, flags=re.I)[0]
    s = re.sub(r"(_current_vs_potential|_potential_vs_time|_current_vs_time|_impedance.*|_eis.*|_cv.*|_lsv.*|_ocp.*|_tafel.*|_drt.*)$", "", s, flags=re.I)
    s = re.sub(r"(?:^|[_\-\s])(point|pt|position|pos|spot|site|loc|run|rep|replicate|cycle|cyc|scan|sweep|series|step)[_\-\s]*[A-Za-z]?\d{1,6}(?=$|[_\-\s])", " ", s, flags=re.I)
    s = re.sub(r"(?:^|[_\-\s])m\d{1,5}(?=$|[_\-\s])", " ", s, flags=re.I)
    s = re.sub(r"(?:^|[_\-\s])c\d{1,5}(?=$|[_\-\s])", " ", s, flags=re.I)
    s = re.sub(r"[+\-]?\d+(?:p\d+|\.\d+)?\s*(m?V|mV/s|mVs|V/s|Hz|kHz|MHz)(?=$|[_\-\s])", " ", s, flags=re.I)
    s = re.sub(r"(?:with|without|no|wo|w/o)?[_\-\s]*(magnet|mag|bfield|b_field|control|blank)", " ", s, flags=re.I)
    s = _v756_clean_token(s)
    if not s or len(s) < 2:
        # Use the nearest meaningful folder when the filename is mostly numeric/parameter text.
        try:
            for part in reversed(p.parent.parts):
                pl = str(part).lower()
                if pl and not any(x in pl for x in ["ai", "bundle", "parsed", "csv", "data", "raw", "results"]):
                    s = _v756_clean_token(part)
                    break
        except Exception:
            pass
    return s[:90] if s else "experiment"


def _v756_parent_context(path, root):
    """Infer experiment/sample/context from folder organization."""
    p = Path(path)
    try:
        parts = list(p.relative_to(root).parts[:-1])
    except Exception:
        parts = list(p.parts[:-1])
    useful = []
    for part in parts:
        pl = part.lower()
        if not part or pl in {".", ".."}:
            continue
        if any(x in pl for x in ["ai_bundle", "aibundle", "parsed", "analysis_ready", "csv", "raw", "data", "export", "exports"]):
            continue
        if any(x in pl for x in ["faradaiq_analyzed_data", "faradaiq_launch_sessions"]):
            continue
        useful.append(_v756_clean_token(part))
    return useful[-4:]


def _v756_condition_group_for_record(rec):
    meta = rec.get("meta", {}) or {}
    kind = rec.get("kind") or meta.get("technique") or "Other"
    parts = []
    for k in ["condition", "potential", "scan_rate", "frequency", "temperature", "measurement", "cycle", "replicate", "step"]:
        val = meta.get(k) or ""
        if not val:
            continue
        if k == "condition":
            parts.append(_v756_clean_token(val))
        elif k == "potential":
            parts.append(f"potential {val}")
        elif k == "scan_rate":
            parts.append(f"scan rate {val}")
        elif k == "frequency":
            if kind not in {"EIS"}:
                parts.append(f"frequency {val}")
        elif k == "temperature":
            parts.append(f"T {val}")
        else:
            parts.append(str(val))
    # Technique-specific fallbacks to avoid a giant ungrouped bucket.
    if not parts:
        if kind == "EIS":
            parts.append("impedance dataset")
        elif kind == "CV / LSV":
            parts.append("voltammetry dataset")
        elif kind.startswith("Raman") or kind in {"FTIR / IR", "UV-Vis", "XRD", "XPS"}:
            parts.append("spectrum / map")
        elif kind == "Media / image":
            parts.append("media file")
        else:
            parts.append("ungrouped measurements")
    run = meta.get("run") or ""
    if run and run not in " ".join(parts):
        parts.insert(0, run)
    return " | ".join([p for p in parts if p])


def _v756_leaf_label(rec, root):
    p = Path(rec["path"])
    meta = rec.get("meta", {}) or {}
    bits = []
    for key in ["measurement", "cycle", "replicate", "scan_rate", "potential", "condition", "vendor"]:
        val = meta.get(key)
        if val:
            bits.append(str(val))
    suffix = " · ".join(bits)
    try:
        rel = p.relative_to(root).as_posix()
    except Exception:
        rel = p.name
    name = p.name
    if suffix:
        name = f"{suffix} · {p.name}"
    return _v754_safe_short(name, 130), _v754_safe_short(rel, 180)


def _v756_json_meta_value(obj, keys):
    if not isinstance(obj, dict):
        return ""
    wanted = {str(k).lower().replace(" ", "_").replace("-", "_") for k in keys}
    for kk, vv in obj.items():
        norm = str(kk).lower().replace(" ", "_").replace("-", "_")
        if norm in wanted:
            if isinstance(vv, (str, int, float)):
                return str(vv)
            if isinstance(vv, dict):
                # Common wrapped metadata, e.g. {value: 50, unit: mV/s}
                val = vv.get("value", vv.get("val", ""))
                unit = vv.get("unit", vv.get("units", ""))
                if val not in (None, ""):
                    return f"{val} {unit}".strip()
    return ""


def _v756_find_ai_json_files(root, max_files=600):
    out = []
    root = Path(root)
    if not root.exists():
        return out
    for p in sorted(root.rglob("*.json"), key=lambda x: str(x).lower()):
        try:
            if _v754_is_excluded_path(root, p):
                continue
            rel = p.relative_to(root).as_posix().lower()
            name = p.name.lower()
            if any(k in rel or k in name for k in _V756_AI_JSON_HINTS) or p.stat().st_size < 5 * 1024 * 1024:
                if p.stat().st_size <= 50 * 1024 * 1024:
                    out.append(p)
                    if len(out) >= max_files:
                        break
        except Exception:
            pass
    return out


def _v756_ai_bundle_metadata_map(root):
    """Broad AI/parser/manifest metadata map for HEKA plus arbitrary vendor/generic exports."""
    root = Path(root)
    mapping = {}
    json_files = _v756_find_ai_json_files(root)
    fields = {
        "experiment": ["experiment", "experiment_id", "dataset", "dataset_name", "project", "project_id", "session", "box", "sample", "sample_id", "specimen", "cell_id", "batch"],
        "sample": ["sample", "sample_id", "sample_name", "specimen", "material", "electrolyte_sample"],
        "point": ["point", "point_id", "point_index", "pixel", "position", "position_id", "location", "spot", "site", "well", "cell"],
        "run": ["run", "run_id", "run_index", "batch_run"],
        "technique": ["technique", "method", "data_type", "type", "detected_type", "measurement_type", "signal_type", "experiment_type"],
        "condition": ["condition", "magnet", "field_condition", "b_field", "bfield", "field", "label", "group", "class", "state"],
        "scan_rate": ["scan_rate", "scanrate", "scan_rate_mv_s", "scan_rate_mvs", "sweep_rate", "rate"],
        "potential": ["potential", "bias", "voltage", "ewe", "dc_potential", "applied_potential", "potential_v", "potential_mv", "ocp"],
        "frequency": ["frequency", "freq", "frequency_hz", "f_hz"],
        "temperature": ["temperature", "temp", "temperature_c", "temperature_k"],
        "measurement": ["measurement", "measurement_id", "m_index", "sweep", "sweep_id", "series", "series_id", "spectrum", "map", "frame"],
        "cycle": ["cycle", "cycle_id", "c_index", "segment", "segment_id", "scan_number"],
        "replicate": ["replicate", "rep", "repeat", "trial"],
        "instrument": ["instrument", "vendor", "software", "source", "parser", "device"],
    }

    def merge_meta(base, obj):
        meta = dict(base or {})
        if isinstance(obj, dict):
            for outkey, keys in fields.items():
                val = _v756_json_meta_value(obj, keys)
                if val and str(val).lower() not in {"none", "null", "nan", "unknown"}:
                    meta[outkey] = str(val)
        return meta

    def register_path(s, meta, source_json):
        try:
            ss = str(s or "").strip()
            if not ss or not _v754_is_pathish_string(ss):
                return
            pp = Path(ss)
            candidates = {ss, ss.replace("\\", "/"), pp.name, pp.stem}
            try:
                if not pp.is_absolute():
                    candidates.add(str((root / ss).resolve()))
                    candidates.add((root / ss).as_posix())
                    candidates.add(Path(root / ss).name)
                    candidates.add(Path(root / ss).stem)
                else:
                    candidates.add(str(pp.resolve()))
            except Exception:
                pass
            m2 = dict(meta or {})
            m2["source"] = f"AI/parser JSON: {Path(source_json).name}"
            for k in candidates:
                if k:
                    old = mapping.get(k, {})
                    merged = dict(old)
                    merged.update({kk: vv for kk, vv in m2.items() if vv not in (None, "")})
                    mapping[k] = merged
        except Exception:
            pass

    def walk(obj, ctx, source_json, depth=0):
        if depth > 20:
            return
        if isinstance(obj, dict):
            meta = merge_meta(ctx, obj)
            for kk, vv in obj.items():
                kl = str(kk).lower()
                if isinstance(vv, str) and any(x in kl for x in ["file", "path", "csv", "npy", "source", "uri", "href", "output"]):
                    register_path(vv, meta, source_json)
                elif isinstance(vv, list) and any(x in kl for x in ["files", "paths", "sources", "outputs", "records"]):
                    for item in vv[:10000]:
                        if isinstance(item, str):
                            register_path(item, meta, source_json)
                        else:
                            walk(item, meta, source_json, depth+1)
            for vv in obj.values():
                walk(vv, meta, source_json, depth+1)
        elif isinstance(obj, list):
            for vv in obj[:10000]:
                walk(vv, ctx, source_json, depth+1)
        elif isinstance(obj, str):
            register_path(obj, ctx, source_json)

    for jp in json_files:
        try:
            data = json.loads(jp.read_text(encoding="utf-8", errors="ignore"))
            walk(data, {}, jp)
        except Exception:
            try:
                # JSONL fallback.
                with jp.open("r", encoding="utf-8", errors="ignore") as fh:
                    for i, line in enumerate(fh):
                        if i > 10000:
                            break
                        try:
                            walk(json.loads(line), {}, jp)
                        except Exception:
                            pass
            except Exception:
                continue
    return mapping, json_files


def _v756_parse_metadata_from_filename(root, p, kind=None, head=""):
    p = Path(p)
    text = f"{p.stem} {p.parent.as_posix()} {head[:3000]}"
    parent_ctx = _v756_parent_context(p, root)
    kind2 = _v756_kind_from_content_or_path(p, kind or _v754_file_kind(p))
    vendor = _v756_vendor_from_text(p, head)
    meta = {
        "experiment": _v756_experiment_prefix_from_name(p),
        "sample": "",
        "point": _v756_parse_point_label(text),
        "run": _v754_parse_run_label(text) or _v756_parse_generic_id(text, ["run", "batch"], "run"),
        "technique": kind2,
        "condition": _v754_parse_condition_label(text),
        "scan_rate": _v754_parse_scan_rate_label(text),
        "potential": _v754_parse_potential_label(text),
        "frequency": _v756_parse_frequency_label(text),
        "temperature": _v756_parse_temperature_label(text),
        "measurement": _v756_parse_measurement_label(text),
        "cycle": _v756_parse_cycle_label(text),
        "replicate": _v756_parse_replicate_label(text),
        "step": _v756_parse_step_label(text),
        "vendor": vendor,
        "folder_context": parent_ctx,
        "source": "general smart inference: content + filename + folder structure",
    }
    # Use folder context for missing experiment/sample/point when filenames are generic.
    if parent_ctx:
        if not meta.get("sample") and len(parent_ctx) >= 1:
            meta["sample"] = parent_ctx[-1]
        if (not meta.get("experiment") or meta["experiment"] == "experiment") and parent_ctx:
            meta["experiment"] = parent_ctx[0]
        if not meta.get("point"):
            for part in reversed(parent_ctx):
                pt = _v756_parse_point_label(part)
                if pt:
                    meta["point"] = pt
                    break
    return meta


def _v756_apply_ai_meta_to_file(root, p, filename_meta, ai_map, head=""):
    p = Path(p)
    keys = []
    try:
        keys.append(str(p.resolve()))
    except Exception:
        pass
    try:
        keys.append(p.relative_to(root).as_posix())
    except Exception:
        pass
    keys.extend([p.as_posix(), str(p), p.name, p.stem])
    out = dict(filename_meta or {})
    hit = None
    for k in keys:
        if k in ai_map:
            hit = ai_map[k]
            break
    if hit:
        for kk, vv in hit.items():
            if vv not in (None, ""):
                out[kk] = str(vv)
        out["source"] = hit.get("source", "AI/parser JSON")
    out["technique"] = _v756_normalize_technique(out.get("technique"), p, head)
    if out.get("point") and not str(out["point"]).lower().startswith(("point", "position")):
        # Do not relabel location names like A1, but normalize bare integer points.
        if re.fullmatch(r"\d+", str(out["point"]).strip()):
            out["point"] = f"point {out['point']}"
    if out.get("measurement"):
        m = re.search(r"\d+", str(out["measurement"]))
        if m and re.search(r"^(m|measurement|meas|sweep|series)$", str(out["measurement"]).split()[0], flags=re.I):
            out["measurement"] = f"m{int(m.group(0)):03d}"
    if out.get("cycle"):
        c = re.search(r"\d+", str(out["cycle"]))
        if c and re.search(r"^(c|cycle|cyc)$", str(out["cycle"]).split()[0], flags=re.I):
            out["cycle"] = f"cycle {int(c.group(0))}"
    if not out.get("vendor"):
        out["vendor"] = _v756_vendor_from_text(p, head)
    return out


def _v756_record_sort_key(rec):
    meta = rec.get("meta", {}) or {}
    def num(s):
        m = re.search(r"[-+]?\d+(?:\.\d+)?", str(s or ""))
        return float(m.group(0)) if m else 1e12
    return (
        str(meta.get("experiment") or "").lower(),
        str(meta.get("sample") or "").lower(),
        str(meta.get("condition") or "").lower(),
        num(meta.get("point")),
        str(rec.get("kind") or ""),
        num(meta.get("potential")),
        num(meta.get("scan_rate")),
        num(meta.get("measurement")),
        num(meta.get("cycle")),
        str(rec.get("path") or "").lower(),
    )


def _v756_collect_smart_records(browser):
    root = Path(getattr(browser, "analysis_root", ".")).resolve()
    base_name = getattr(browser, "base_name", root.name)
    ai_only = False
    try:
        ai_only = bool(browser.ai_npy_only_var.get())
    except Exception:
        pass
    ai_map, ai_json_files = _v756_ai_bundle_metadata_map(root)
    try:
        ai_json_resolved = {str(Path(x).resolve()) for x in ai_json_files}
    except Exception:
        ai_json_resolved = set()
    records = []
    if not root.exists():
        return records, ai_json_files, ai_map
    for p in sorted(root.rglob("*"), key=lambda x: str(x).lower()):
        try:
            if not p.is_file():
                continue
            if p.suffix.lower() not in _V756_DATA_EXTS:
                continue
            if p.suffix.lower() == ".json":
                try:
                    if str(p.resolve()) in ai_json_resolved:
                        continue
                except Exception:
                    pass
            if _v754_is_excluded_path(root, p, base_name):
                continue
            rel_low = p.relative_to(root).as_posix().lower()
            if ai_only:
                if p.suffix.lower() not in {".npy", ".npz"}:
                    continue
                if not any(k in rel_low for k in ["ai", "bundle", "npy", "parsed", "analysis", "features"]):
                    continue
            head = _v756_file_head_text(p)
            kind = _v756_kind_from_content_or_path(p, _v754_file_kind(p))
            meta = _v756_parse_metadata_from_filename(root, p, kind=kind, head=head)
            meta = _v756_apply_ai_meta_to_file(root, p, meta, ai_map, head=head)
            kind = _v756_normalize_technique(meta.get("technique") or kind, p, head)
            meta["technique"] = kind
            records.append({
                "path": p,
                "kind": kind,
                "size": p.stat().st_size,
                "meta": meta,
            })
        except Exception:
            pass
    records.sort(key=_v756_record_sort_key)
    return records, ai_json_files, ai_map


def _v756_refresh_tree(browser):
    try:
        if hasattr(browser, "source_folder_var"):
            src = str(browser.source_folder_var.get()).strip()
            if src:
                browser.analysis_root = Path(src).resolve()
                browser.base_name = browser.analysis_root.name.replace("_analysis_ready_csv", "")
                try:
                    browser.analyzed_root = browser.analysis_root / f"{_v35_safe_name(browser.base_name)}_FaradaIQ_analyzed_data"
                    browser._ensure_analyzed_dirs()
                except Exception:
                    pass
    except Exception:
        pass
    try:
        browser.tree.delete(*browser.tree.get_children())
    except Exception:
        pass
    browser._path_by_iid = {}
    browser._group_file_paths = {}
    browser._group_iids = {}
    root = Path(getattr(browser, "analysis_root", ".")).resolve()
    if not root.exists():
        try:
            browser.log(f"Analysis root does not exist: {root}")
        except Exception:
            pass
        return
    records, ai_json_files, ai_map = _v756_collect_smart_records(browser)
    if not records:
        iid = browser.tree.insert("", "end", text="No data files found", values=("Empty", "0 files"), open=True)
        browser._group_file_paths[iid] = []
        try:
            browser.log(f"General smart tree found no data files under {root}")
        except Exception:
            pass
        return

    nested = {}
    for rec in records:
        meta = rec.get("meta", {}) or {}
        exp = _v756_clean_token(meta.get("experiment") or meta.get("sample") or root.name or "experiment")
        sample = _v756_clean_token(meta.get("sample") or "all samples")
        condition = _v756_clean_token(meta.get("condition") or "all conditions")
        point = _v756_clean_token(meta.get("point") or "all / unassigned positions")
        kind = rec.get("kind") or meta.get("technique") or "Other"
        param_group = _v756_condition_group_for_record(rec)
        vendor = _v756_clean_token(meta.get("vendor") or meta.get("instrument") or "")
        labels = [(f"Experiment: {exp}", "Experiment")]
        if sample and sample.lower() not in {"all samples", exp.lower()}:
            labels.append((f"Sample: {sample}", "Sample"))
        if condition and condition.lower() not in {"all conditions", ""}:
            labels.append((f"Condition: {condition}", "Condition"))
        labels.append((f"Point/position: {point}", "Point"))
        labels.append((kind, kind))
        if vendor and vendor.lower() not in {"generic table"}:
            labels.append((f"Source: {vendor}", "Instrument / parser"))
        labels.append((param_group, "Measurement group"))
        node = nested
        for label, node_kind in labels:
            key = (str(label), str(node_kind))
            if key not in node:
                node[key] = {"_files": [], "_children": {}, "_record_count": 0}
            node[key]["_files"].append(Path(rec["path"]))
            node[key]["_record_count"] = node[key].get("_record_count", 0) + 1
            node = node[key]["_children"]
        leaf_label, rel = _v756_leaf_label(rec, root)
        key = (leaf_label, rec.get("kind", "File"), str(rec["path"]))
        node[key] = {"_files": [Path(rec["path"])], "_children": {}, "_record": rec, "_rel": rel}

    project_iid = browser.tree.insert("", "end", text=f"Smart data structure: {root.name}", values=("Project", f"{len(records)} files"), open=True)
    browser._group_file_paths[project_iid] = [Path(r["path"]) for r in records]

    node_order = {
        "Experiment": 0, "Sample": 1, "Condition": 2, "Point": 3,
        "CV / LSV": 4, "EIS": 4, "DRT": 4, "OCP": 4, "IV / Tafel": 4,
        "Chronoamperometry": 4, "Chronopotentiometry": 4, "Raman / SERS": 4,
        "FTIR / IR": 4, "UV-Vis": 4, "XRD": 4, "XPS": 4, "EQCM": 4,
        "Media / image": 5, "Instrument / parser": 6, "Measurement group": 7,
    }

    def sort_nodes(item):
        key, _child = item
        if isinstance(key, tuple) and len(key) == 3:
            return (99, str(key[0]).lower())
        label, kind = key
        return (node_order.get(str(kind), 50), str(label).lower())

    def insert_rec(parent_iid, node_dict, level=0):
        for key, child_node in sorted(node_dict.items(), key=sort_nodes):
            if isinstance(key, tuple) and len(key) == 3:
                label, kind, _path_s = key
                rec = child_node.get("_record", {})
                p = Path(rec.get("path", _path_s))
                size = ""
                try:
                    size = browser._format_size(p.stat().st_size)
                except Exception:
                    try:
                        size = browser._size(p.stat().st_size)
                    except Exception:
                        size = ""
                iid = browser.tree.insert(parent_iid, "end", text=label, values=(kind, size), open=False)
                browser._path_by_iid[iid] = p
                browser._group_file_paths[iid] = [p]
            else:
                label, node_kind = key
                files = child_node.get("_files", [])
                open_default = level < 2 or node_kind in {"CV / LSV", "EIS", "DRT", "OCP", "IV / Tafel", "Raman / SERS", "Media / image"}
                iid = browser.tree.insert(parent_iid, "end", text=label, values=(node_kind, f"{len(files)} files"), open=open_default)
                browser._group_file_paths[iid] = list(files)
                if node_kind in {"CV / LSV", "EIS", "DRT", "OCP", "IV / Tafel", "Chronoamperometry", "Chronopotentiometry", "Raman / SERS", "FTIR / IR", "UV-Vis", "XRD", "XPS", "EQCM", "Media / image"} and node_kind not in browser._group_iids:
                    browser._group_iids[node_kind] = iid
                insert_rec(iid, child_node.get("_children", {}), level+1)
    insert_rec(project_iid, nested, level=0)

    # Cache index next to the selected data analysis root, not under launch-session tracking.
    try:
        index_dir = browser.analyzed_root / "metadata"
    except Exception:
        index_dir = root / f"{_v35_safe_name(getattr(browser, 'base_name', root.name))}_FaradaIQ_analyzed_data" / "metadata"
    try:
        index_dir.mkdir(parents=True, exist_ok=True)
        serial = []
        for rec in records:
            try:
                serial.append({
                    "path": str(Path(rec["path"])),
                    "relative_path": Path(rec["path"]).relative_to(root).as_posix(),
                    "kind": rec.get("kind"),
                    "size_bytes": rec.get("size"),
                    "metadata": rec.get("meta", {}),
                })
            except Exception:
                pass
        (index_dir / "smart_data_tree_index_v756.json").write_text(json.dumps({
            "created": datetime.now().isoformat(timespec="seconds"),
            "analysis_root": str(root),
            "tree_version": "v198 generalized smart tree",
            "n_files": len(records),
            "n_ai_json_files_read": len(ai_json_files),
            "ai_json_files": [str(x) for x in ai_json_files[:600]],
            "records": serial,
        }, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass

    by_kind = {}
    ai_hits = 0
    vendors = {}
    for r in records:
        by_kind[r.get("kind", "Other")] = by_kind.get(r.get("kind", "Other"), 0) + 1
        meta = r.get("meta", {}) or {}
        if str(meta.get("source", "")).lower().startswith("ai") or "json" in str(meta.get("source", "")).lower():
            ai_hits += 1
        if meta.get("vendor"):
            vendors[meta.get("vendor")] = vendors.get(meta.get("vendor"), 0) + 1
    try:
        summary = ", ".join(f"{k}={v}" for k, v in sorted(by_kind.items()))
        vendor_summary = ", ".join(f"{k}={v}" for k, v in sorted(vendors.items()))
        browser.log(f"v75.6 general smart tree built {len(records)} files under {root}. Types: {summary}. Parser/AI metadata hits: {ai_hits}. Vendors: {vendor_summary or 'generic/unknown'}")
        if hasattr(browser, "status_var"):
            browser.status_var.set("v75.6 general smart tree: AI/parser JSON + content headers + folder/filename structure. Select any group, then Plot / overlay selected.")
    except Exception:
        pass


