def _v757_register_browser(browser):
    try:
        if '_FARADAIQ_BROWSER_WINDOWS_V754' in globals():
            if browser not in _FARADAIQ_BROWSER_WINDOWS_V754:
                _FARADAIQ_BROWSER_WINDOWS_V754.append(browser)
    except Exception:
        pass
    try:
        globals()['_FARADAIQ_LAST_BROWSER_V757'] = browser
    except Exception:
        pass


def _v757_find_last_browser(owner=None):
    if owner is not None and hasattr(owner, 'plot_view_list'):
        return owner
    try:
        b = globals().get('_FARADAIQ_LAST_BROWSER_V757')
        if b is not None and hasattr(b, 'plot_view_list'):
            return b
    except Exception:
        pass
    try:
        wins = list(globals().get('_FARADAIQ_BROWSER_WINDOWS_V754', []) or [])
        for b in wins[::-1]:
            try:
                if b.winfo_exists() and hasattr(b, 'plot_view_list'):
                    return b
            except Exception:
                if hasattr(b, 'plot_view_list'):
                    return b
    except Exception:
        pass
    return None


def _v757_current_view_index(browser):
    try:
        sel = browser.plot_view_list.curselection()
        if sel:
            return int(sel[0])
    except Exception:
        pass
    try:
        idx = int(browser.plot_view_list.index('active'))
        if 0 <= idx < browser.plot_view_list.size():
            return idx
    except Exception:
        pass
    try:
        idx = int(browser.plot_view_list.nearest(0))
        if 0 <= idx < browser.plot_view_list.size():
            return idx
    except Exception:
        pass
    return None


def _v757_prompt_rename(parent, old):
    # simpledialog can occasionally be hidden behind transient windows on Windows; fallback to a small top-level editor.
    try:
        if _v757_simpledialog is not None:
            ans = _v757_simpledialog.askstring('Rename plot/view', 'New plot/view name:', initialvalue=old, parent=parent)
            if ans is not None:
                return ans
    except Exception:
        pass
    try:
        win = tk.Toplevel(parent)
        win.title('Rename plot/view')
        win.transient(parent)
        win.grab_set()
        ttk.Label(win, text='New plot/view name:').pack(anchor='w', padx=12, pady=(12, 4))
        var = tk.StringVar(value=old or '')
        ent = ttk.Entry(win, textvariable=var, width=60)
        ent.pack(fill='x', padx=12, pady=(0, 8))
        result = {'value': None}
        def ok():
            result['value'] = var.get()
            win.destroy()
        def cancel():
            win.destroy()
        row = ttk.Frame(win)
        row.pack(fill='x', padx=12, pady=(0, 12))
        ttk.Button(row, text='Rename', command=ok).pack(side='right')
        ttk.Button(row, text='Cancel', command=cancel).pack(side='right', padx=(0, 6))
        ent.focus_set()
        ent.selection_range(0, 'end')
        win.bind('<Return>', lambda e: ok())
        win.bind('<Escape>', lambda e: cancel())
        parent.wait_window(win)
        return result.get('value')
    except Exception:
        return None


def _v757_rename_current_view(browser):
    try:
        _v757_register_browser(browser)
        if not hasattr(browser, 'plot_view_list'):
            messagebox.showinfo('No plot/view list', 'The plot/view list is not available in this window.', parent=browser)
            return
        idx = _v757_current_view_index(browser)
        if idx is None:
            messagebox.showinfo('No plot/view selected', 'Select a plot/view first, then click Rename view.', parent=browser)
            return
        if not hasattr(browser, '_v69_plot_views'):
            browser._v69_plot_views = []
        while len(browser._v69_plot_views) <= idx:
            try:
                nm = browser.plot_view_list.get(len(browser._v69_plot_views))
            except Exception:
                nm = f'Plot/view {len(browser._v69_plot_views)+1}'
            browser._v69_plot_views.append({'name': nm, 'paths': [], 'kind': 'View'})
        old = str(browser._v69_plot_views[idx].get('name') or browser.plot_view_list.get(idx) or '')
        new = _v757_prompt_rename(browser, old)
        if new is None:
            return
        new = str(new).strip()
        if not new:
            messagebox.showinfo('Empty name', 'Please enter a non-empty plot/view name.', parent=browser)
            return
        browser._v69_plot_views[idx]['name'] = new
        try:
            browser.plot_view_list.delete(idx, idx)
        except TypeError:
            browser.plot_view_list.delete(idx)
        browser.plot_view_list.insert(idx, new)
        browser.plot_view_list.selection_clear(0, 'end')
        browser.plot_view_list.selection_set(idx)
        browser.plot_view_list.activate(idx)
        browser.plot_view_list.see(idx)
        try:
            _v75_save_session(browser, silent=True)
        except Exception:
            pass
        try:
            _v753_track_event('plot_view_renamed_v757', {'index': idx, 'name': new})
        except Exception:
            pass
        browser.log(f'Renamed plot/view #{idx+1}: {old} → {new}')
        try:
            if hasattr(browser, 'status_var'):
                browser.status_var.set(f'Renamed plot/view: {new}')
        except Exception:
            pass
    except Exception as exc:
        try:
            browser.log(f'Rename failed: {exc}')
        except Exception:
            pass
        try:
            messagebox.showerror('Rename failed', str(exc), parent=browser)
        except Exception:
            pass


def _v757_hide_legacy_cv_buttons(root):
    # Hide old lightweight CV tools so users are routed through PySimpleEChem.
    legacy = {'Find peaks', 'Baseline/area from 2 clicks', 'Baseline / area from 2 clicks', 'Open CV peak dashboard'}
    def walk(w):
        try:
            children = w.winfo_children()
        except Exception:
            children = []
        for c in children:
            try:
                txt = str(c.cget('text'))
            except Exception:
                txt = ''
            if txt in legacy:
                try:
                    c.pack_forget()
                    c.grid_forget()
                    c.place_forget()
                    setattr(c, '_faradaiq_hidden_legacy_cv_button', True)
                except Exception:
                    pass
            walk(c)
    try:
        walk(root)
    except Exception:
        pass


def _v757_open_native_pysimpleechem(browser=None):
    try:
        app_dir = Path(__file__).resolve().parent
        pse = app_dir / 'integrated_tools' / 'PySimpleEChem' / 'PySimpleEChem.py'
        if not pse.exists():
            messagebox.showerror('PySimpleEChem missing', f'Could not find: {pse}', parent=browser)
            return
        if _v757_subprocess is None:
            messagebox.showerror('Subprocess unavailable', 'Python subprocess is not available in this runtime.', parent=browser)
            return
        _v757_subprocess.Popen([_v757_sys.executable, str(pse)], cwd=str(pse.parent))
        if browser is not None:
            browser.log(f'Launched native PySimpleEChem CV workflow: {pse}')
    except Exception as exc:
        try:
            messagebox.showerror('Could not launch PySimpleEChem', str(exc), parent=browser)
        except Exception:
            pass
        try:
            browser.log(f'Could not launch native PySimpleEChem: {exc}')
        except Exception:
            pass


def _v757_selected_cv_paths(browser):
    try:
        paths = _v75x_get_selected_view_paths(browser)
    except Exception:
        paths = []
    try:
        tables = _v70_table_paths(paths)
    except Exception:
        tables = [Path(p) for p in paths]
    out = []
    for p in tables:
        try:
            kind = _v75_kind_from_paths([p])
        except Exception:
            kind = ''
        s = str(p).lower()
        if kind == 'CV / LSV' or any(tok in s for tok in ['cv', 'lsv', 'voltamm', 'current_vs', 'potential']):
            out.append(Path(p))
    if not out:
        out = [Path(p) for p in tables]
    # de-duplicate
    ded, seen = [], set()
    for p in out:
        k = str(Path(p).resolve()) if Path(p).exists() else str(p)
        if k not in seen:
            ded.append(Path(p))
            seen.add(k)
    return ded


def _v757_cv_shared_params(browser):
    d = {}
    try:
        meta = _v75_collect_metadata(browser)
    except Exception:
        meta = {}
    # Electrode area is a common metadata field in v75 panels.
    for key in ['electrode_area_cm2', 'electrode_area', 'area_cm2']:
        try:
            if meta.get(key):
                d['elec_area'] = float(meta.get(key))
                break
        except Exception:
            pass
    # User notes can include n=, concentration= etc.; keep conservative.
    try:
        notes = str(meta.get('notes', ''))
        m = re.search(r'(?:^|\b)n\s*=\s*([0-9.]+)', notes, re.I)
        if m:
            d['electron_n'] = float(m.group(1))
        m = re.search(r'(?:conc|concentration|bulk)\s*=\s*([0-9.eE+\-]+)\s*(mM|M|mol/cm3|mol/cm\^3)?', notes, re.I)
        if m:
            val = float(m.group(1)); unit = (m.group(2) or '').lower()
            if unit == 'mm':
                d['bulk_conc_mol_cm3'] = val * 1e-6
            elif unit == 'm':
                d['bulk_conc_mol_cm3'] = val * 1e-3
            else:
                d['bulk_conc_mol_cm3'] = val
    except Exception:
        pass
    return d


def _v757_cv_analyze_bundle(browser, paths=None):
    if _fq_pse_cv is None:
        raise RuntimeError(f'PySimpleEChem adapter failed to import: {_v757_pse_import_error}')
    if paths is None:
        paths = _v757_selected_cv_paths(browser)
    if not paths:
        raise RuntimeError('No CV/LSV table files selected. Create/select a CV Plot/view first.')
    params = _v757_cv_shared_params(browser)
    return _fq_pse_cv.analyze_cv_files(paths, shared_params=params)


def _v757_save_cv_bundle(browser, bundle):
    try:
        outdir = browser.analyzed_root / 'pysimpleechem_cv_results'
    except Exception:
        root = Path(getattr(browser, 'analysis_root', Path.cwd()))
        outdir = root / f'{_v35_safe_name(getattr(browser, "base_name", root.name))}_FaradaIQ_analyzed_data' / 'pysimpleechem_cv_results'
    outdir.mkdir(parents=True, exist_ok=True)
    stem = f'{_v35_safe_name(getattr(browser, "base_name", "faradaiq"))}_pysimpleechem_cv_{datetime.now().strftime("%Y%m%d_%H%M%S")}'
    try:
        paths = _fq_pse_cv.write_results_bundle(bundle, outdir, stem=stem) if _fq_pse_cv else {}
    except Exception as exc:
        paths = {}
        try:
            browser.log(f'Could not save PySimpleEChem bundle through adapter: {exc}')
        except Exception:
            pass
    return paths


def _v757_cv_quantities(path):
    if _fq_pse_cv is None:
        return {'file': str(path), 'type': 'CV / LSV', 'warnings': [f'PySimpleEChem adapter unavailable: {_v757_pse_import_error}'], 'assumptions': []}
    try:
        r = _fq_pse_cv.analyze_cv_file(path)
        q = _fq_pse_cv.compact_result(r)
        # Compatibility keys used by older FaradaIQ result tables/prompts.
        q['oxidation_peak_potential_V_estimate'] = q.get('Ep1_V')
        q['oxidation_peak_current_A_estimate'] = q.get('peak_1', {}).get('peak_current_density_or_current') if isinstance(q.get('peak_1'), dict) else None
        q['reduction_peak_potential_V_estimate'] = q.get('Ep2_V')
        q['reduction_peak_current_A_estimate'] = q.get('peak_2', {}).get('peak_current_density_or_current') if isinstance(q.get('peak_2'), dict) else None
        q['delta_Ep_V_estimate'] = q.get('Delta_Ep_V')
        q['ipa_ipc_ratio_estimate'] = q.get('Jp1_Jp2_ratio')
        return q
    except Exception as exc:
        return {'file': str(path), 'type': 'CV / LSV', 'warnings': [f'PySimpleEChem CV analysis failed: {exc}'], 'assumptions': []}


def _v757_run_pysimpleechem_cv_analysis(browser):
    try:
        bundle = _v757_cv_analyze_bundle(browser)
        saved = _v757_save_cv_bundle(browser, bundle)
        try:
            browser.results_tree.delete(*browser.results_tree.get_children())
        except Exception:
            pass
        try:
            for r in bundle.get('results', []):
                rr = _fq_pse_cv.compact_result(r) if _fq_pse_cv else r
                parent = browser.results_tree.insert('', 'end', text=rr.get('file_name', Path(rr.get('file','')).name), values=('PySimpleEChem CV', f"ΔEp={rr.get('Delta_Ep_V')}"), open=True)
                for key in ['scan_rate_V_s','Jp1','Jp2','Jp1_Jp2_ratio','Ep1_V','Ep2_V','E_half_V','Delta_Ep_V','alpha1','alpha2','backend']:
                    if key in rr:
                        browser.results_tree.insert(parent, 'end', text=key, values=('result', str(rr.get(key))))
        except Exception:
            pass
        lines = [
            'PySimpleEChem CV workflow results',
            f"Files analyzed: {bundle.get('n_results', 0)}",
            '',
        ]
        for r in bundle.get('results', [])[:12]:
            lines.append(str(r.get('file_name') or Path(r.get('file','')).name))
            for k in ['scan_rate_V_s','Jp1','Jp2','Jp1_Jp2_ratio','Ep1_V','Ep2_V','E_half_V','Delta_Ep_V','alpha1','alpha2']:
                val = r.get(k)
                try:
                    if val is not None and np.isfinite(float(val)):
                        val = f'{float(val):.6g}'
                except Exception:
                    pass
                lines.append(f'  {k}: {val}')
        if bundle.get('errors'):
            lines.append('')
            lines.append('Errors:')
            for e in bundle.get('errors', [])[:5]:
                lines.append(f"  {Path(e.get('file','')).name}: {e.get('error')}")
        if saved:
            lines.append('')
            lines.append('Saved:')
            for k, p in saved.items():
                lines.append(f'  {k}: {p}')
        try:
            browser.analysis_text.delete('1.0', 'end')
            browser.analysis_text.insert('end', '\n'.join(lines))
        except Exception:
            pass
        browser.log('PySimpleEChem CV analysis complete.' + (f" Saved: {saved}" if saved else ''))
        try:
            _v753_track_event('pysimpleechem_cv_analysis_v757', {'n_results': bundle.get('n_results', 0), 'saved': saved})
        except Exception:
            pass
        return bundle
    except Exception as exc:
        try:
            messagebox.showerror('PySimpleEChem CV analysis failed', str(exc), parent=browser)
            browser.log(f'PySimpleEChem CV analysis failed: {exc}')
        except Exception:
            pass
        return None


def _v757_cv_dashboard(browser):
    if _fq_pse_cv is None:
        messagebox.showerror('PySimpleEChem adapter unavailable', str(_v757_pse_import_error), parent=browser)
        return
    paths = _v757_selected_cv_paths(browser)
    if not paths:
        messagebox.showinfo('No CV/LSV tables', 'Select or load one or more CV/LSV table files first.', parent=browser)
        return
    try:
        bundle = _v757_cv_analyze_bundle(browser, paths=paths)
        browser.figure.clear()
        ax_cv = browser.figure.add_subplot(221)
        ax_jp = browser.figure.add_subplot(222)
        ax_de = browser.figure.add_subplot(223)
        ax_txt = browser.figure.add_subplot(224)
        ax_txt.axis('off')
        browser.curves = []
        browser.last_plot_paths = []
        txt = ['PySimpleEChem CV workflow', '', 'Two-baseline/two-peak analysis']
        scan_vals, jp1_vals, jp2_vals, de_vals = [], [], [], []
        for r in bundle.get('results', []):
            E = np.asarray(r.get('E_trim', r.get('E', [])), dtype=float)
            I = np.asarray(r.get('I_trim', r.get('I', [])), dtype=float)
            if len(E) < 3:
                continue
            label = str(r.get('file_name') or Path(r.get('file','')).stem)[:42]
            ax_cv.plot(E, I, linewidth=1.25, label=label)
            browser.curves.append({'path': Path(r.get('file')), 'x': E, 'y': I, 'xcol': 'Potential / V', 'ycol': 'Current density/current', 'label': label})
            # Peak markers and baselines.
            for pk_key, marker in [('peak_1', 'o'), ('peak_2', 's')]:
                pk = r.get(pk_key, {}) or {}
                try:
                    ax_cv.plot([pk['peak_E_V']], [pk['peak_current_density_or_current']], marker=marker, markersize=5)
                    coef = pk.get('baseline_poly_coef', [])
                    br = pk.get('baseline_range', [])
                    if len(coef) >= 2 and len(br) == 2:
                        Efull = np.asarray(r.get('E', []), dtype=float)
                        lo, hi = int(br[0]), int(br[1])
                        lo = max(0, min(lo, len(Efull)-1)); hi = max(0, min(hi, len(Efull)-1))
                        if hi < lo: lo, hi = hi, lo
                        xs = Efull[lo:hi+1]
                        ys = float(coef[0]) + float(coef[1])*xs
                        ax_cv.plot(xs, ys, linestyle='--', linewidth=1.0)
                except Exception:
                    pass
            sr = r.get('scan_rate_V_s') or 0.0
            if sr and np.isfinite(float(sr)) and float(sr) > 0:
                scan_vals.append(float(sr)**0.5)
                jp1_vals.append(float(r.get('Jp1', np.nan)))
                jp2_vals.append(float(r.get('Jp2', np.nan)))
            if r.get('Delta_Ep_V') is not None:
                try:
                    de_vals.append(float(r.get('Delta_Ep_V')))
                except Exception:
                    pass
            txt.append(label)
            for k in ['Jp1','Jp2','Ep1_V','Ep2_V','E_half_V','Delta_Ep_V']:
                v = r.get(k)
                try:
                    v = f'{float(v):.5g}' if v is not None and np.isfinite(float(v)) else v
                except Exception:
                    pass
                txt.append(f'  {k}: {v}')
            browser.last_plot_paths.append(Path(r.get('file')))
        ax_cv.set_title('CV overlay with PySimpleEChem peaks/baselines')
        ax_cv.set_xlabel('Potential / V')
        ax_cv.set_ylabel('Current density/current')
        ax_cv.grid(True, alpha=0.25)
        if len(paths) <= 10:
            ax_cv.legend(fontsize=6, loc='best')
        if scan_vals:
            ax_jp.scatter(scan_vals, jp1_vals, label='Jp1')
            ax_jp.scatter(scan_vals, jp2_vals, label='Jp2')
            ax_jp.set_xlabel('sqrt(scan rate) / (V s⁻¹)^0.5')
            ax_jp.set_ylabel('|Jp|')
            ax_jp.set_title('PySimpleEChem scan-rate view')
            ax_jp.grid(True, alpha=0.25)
            ax_jp.legend(fontsize=7)
        else:
            ax_jp.text(0.05, 0.95, 'No scan-rate series detected', va='top')
            ax_jp.set_axis_off()
        if de_vals:
            ax_de.plot(range(1, len(de_vals)+1), de_vals, marker='o')
            ax_de.set_title('ΔEₚ by file')
            ax_de.set_xlabel('CV file index')
            ax_de.set_ylabel('ΔEₚ / V')
            ax_de.grid(True, alpha=0.25)
        else:
            ax_de.text(0.05, 0.95, 'No ΔEₚ values', va='top')
            ax_de.set_axis_off()
        ax_txt.text(0.02, 0.98, '\n'.join(txt[:42]), va='top', ha='left', fontsize=8)
        browser.figure.tight_layout()
        browser.canvas.draw_idle()
        browser.ax = ax_cv
        browser.current_technique_var.set(f'Detected: CV / LSV | PySimpleEChem dashboard files: {len(paths)}')
        _v75x_store_current_view(browser, paths, 'CV / LSV', name=f"{len(getattr(browser,'_v69_plot_views',[]))+1:02d} PySimpleEChem CV dashboard ({len(paths)} files)")
        saved = _v757_save_cv_bundle(browser, bundle)
        browser.log(f'PySimpleEChem CV dashboard complete. Saved result bundle: {saved}')
    except Exception as exc:
        browser.log(f'PySimpleEChem CV dashboard failed: {exc}')
        try:
            messagebox.showerror('PySimpleEChem CV dashboard failed', str(exc), parent=browser)
        except Exception:
            pass


def _v757_update_analysis_schema(browser, kind=None):
    # Use the original v75 implementation for non-CV. For CV, replace the old lightweight peak tools.
    kind = kind or _v75_kind_from_paths(_v75x_get_selected_view_paths(browser))
    if kind != 'CV / LSV':
        try:
            _V75_ORIG_UPDATE_ANALYSIS_SCHEMA(browser, kind)
        except Exception:
            try:
                _v75_update_analysis_schema_enhanced(browser, kind)
            except Exception:
                pass
        return
    try:
        for child in browser.schema_body.winfo_children():
            child.destroy()
    except Exception:
        pass
    try:
        ttk.Label(browser.schema_body, text='PySimpleEChem CV / LSV workflow', style='Section.TLabel').pack(anchor='w')
        ttk.Label(
            browser.schema_body,
            text='FaradaIQ v273 routes CV analysis through the bundled PySimpleEChem workflow: trim, IR compensation, reference conversion, current density, baseline 1/2, peak mode/range, Jp1/Jp2, Ep1/Ep2, E½, ΔEp, alpha, and scan-rate plots.',
            style='Muted.TLabel', wraplength=310,
        ).pack(anchor='w', pady=(2, 6))
        ttk.Button(browser.schema_body, text='Open native PySimpleEChem CV workflow', command=lambda: _v757_open_native_pysimpleechem(browser)).pack(fill='x', pady=2)
        ttk.Button(browser.schema_body, text='Run PySimpleEChem CV analysis', command=lambda: _v757_run_pysimpleechem_cv_analysis(browser)).pack(fill='x', pady=2)
        ttk.Button(browser.schema_body, text='Open PySimpleEChem CV dashboard', command=lambda: _v757_cv_dashboard(browser)).pack(fill='x', pady=2)
        ttk.Button(browser.schema_body, text='Save session + audit state', command=lambda: _v75_save_session(browser)).pack(fill='x', pady=2)
        if _fq_pse_cv is None:
            ttk.Label(browser.schema_body, text=f'Adapter import warning: {_v757_pse_import_error}', style='Muted.TLabel', wraplength=310).pack(anchor='w', pady=(5, 0))
        else:
            ttk.Label(browser.schema_body, text='Older FaradaIQ candidate-peak and two-click baseline buttons are hidden for CV. Use PySimpleEChem controls/workflow instead.', style='Muted.TLabel', wraplength=310).pack(anchor='w', pady=(5, 0))
    except Exception as exc:
        try:
            browser.log(f'Could not build PySimpleEChem CV panel: {exc}')
        except Exception:
            pass


