def _v757_browser_build_ui(browser):
    if _V757_PREV_BROWSER_BUILD_UI is not None:
        _V757_PREV_BROWSER_BUILD_UI(browser)
    try:
        _v757_register_browser(browser)
    except Exception:
        pass
    try:
        _v753_apply_title(browser, 'FaradaIQ Studio v273 browser')
    except Exception:
        try:
            browser.title('FaradaIQ Studio v273 — PySimpleEChem CV workflow')
        except Exception:
            pass
    try:
        _v757_hide_legacy_cv_buttons(browser)
    except Exception:
        pass
    # Improve plot/view list rename discoverability.
    try:
        if hasattr(browser, 'plot_view_list'):
            browser.plot_view_list.bind('<F2>', lambda e, b=browser: (_v757_rename_current_view(b), 'break'))
            browser.plot_view_list.bind('<Double-Button-1>', lambda e, b=browser: (_v757_rename_current_view(b), 'break'))
            menu = tk.Menu(browser.plot_view_list, tearoff=0)
            menu.add_command(label='Rename plot/view', command=lambda b=browser: _v757_rename_current_view(b))
            menu.add_command(label='Analyze with PySimpleEChem CV workflow', command=lambda b=browser: _v757_run_pysimpleechem_cv_analysis(b))
            def popup(ev, m=menu):
                try:
                    browser.plot_view_list.selection_clear(0, 'end')
                    idx = browser.plot_view_list.nearest(ev.y)
                    browser.plot_view_list.selection_set(idx)
                    browser.plot_view_list.activate(idx)
                except Exception:
                    pass
                m.tk_popup(ev.x_root, ev.y_root)
            browser.plot_view_list.bind('<Button-3>', popup)
    except Exception:
        pass
    try:
        if hasattr(browser, 'status_var'):
            browser.status_var.set('v78: smart tree + PySimpleEChem CV workflow + fixed Plot/view rename.')
    except Exception:
        pass


