def _v757_browser_plot_views(owner):
    b = _v757_find_last_browser(owner)
    try:
        if _V754_BROWSER_PLOT_VIEWS_PREV_V757 is not None:
            return _V754_BROWSER_PLOT_VIEWS_PREV_V757(b)
    except Exception:
        pass
    # Fallback: build directly from the browser's visible Plot/view list and internal view store.
    views = []
    src = b or owner
    if src is None:
        return views
    try:
        raw = list(getattr(src, '_v69_plot_views', []) or [])
        names = []
        if hasattr(src, 'plot_view_list'):
            try:
                names = [src.plot_view_list.get(i) for i in range(src.plot_view_list.size())]
            except Exception:
                names = []
        for i, v in enumerate(raw):
            if not isinstance(v, dict):
                continue
            paths = []
            for pp in v.get('paths', []) or []:
                if pp:
                    paths.append(Path(pp))
            for c in v.get('curves', []) or []:
                if isinstance(c, dict) and c.get('path'):
                    paths.append(Path(c.get('path')))
            dedup, seen = [], set()
            for pp in paths:
                key = str(pp)
                if key not in seen:
                    dedup.append(pp); seen.add(key)
            nm = v.get('name') or (names[i] if i < len(names) else f'Plot/view {i+1}')
            views.append({'index': i, 'name': str(nm), 'kind': v.get('kind') or _v75_kind_from_paths(dedup), 'mode': v.get('mode', 'Auto'), 'paths': dedup, 'source_browser': src})
    except Exception:
        pass
    return views


