# ---- v80 simplification: concise experiment map, no raw-file clutter ----
def _v80_nat_key(value):
    return [int(t) if str(t).isdigit() else str(t).lower() for t in re.split(r"(\d+)", str(value or ""))]


def _v80_num(value, default=10**9):
    m = re.search(r"[-+]?\d+(?:\.\d+)?", str(value or ""))
    try:
        return float(m.group(0)) if m else default
    except Exception:
        return default


def _v80_clean(value, fallback=""):
    try:
        out = _v756_clean_token(str(value or ""))
    except Exception:
        out = str(value or "").strip()
    return out or fallback


def _v80_meta(rec, key, default=""):
    try:
        meta = rec.get('meta') or {}
        val = meta.get(key, default)
        if val is None:
            return default
        return str(val).strip()
    except Exception:
        return default


def _v80_measurement_num(rec):
    m = _v80_meta(rec, 'measurement') or Path(rec.get('path', '')).stem
    return _v80_num(m)


def _v80_path_text(rec):
    try:
        p = Path(rec.get('path'))
        return f"{p.name} {p.parent.as_posix()}"
    except Exception:
        return str(rec or "")


def _v80_infer_total_points(records, root_name=""):
    points = set()
    texts = [root_name]
    for r in records or []:
        meta = r.get('meta') or {}
        pt = meta.get('point') or meta.get('position') or meta.get('spot') or meta.get('site') or meta.get('well')
        if pt and not re.search(r"\b\d+\s*points?\b", str(pt), re.I):
            points.add(str(pt))
        texts.append(_v80_path_text(r))
    # Prefer explicit "11points" / "11 points" as total point count when present.
    for t in texts:
        m = re.search(r"(?:^|[_\-\s])([1-9]\d{0,3})\s*points?(?:$|[_\-\s])", str(t), flags=re.I)
        if m:
            try:
                n = int(m.group(1))
                if n > len(points):
                    return n
            except Exception:
                pass
    return len(points)


def _v80_kind(rec):
    try:
        kind = rec.get('kind') or (rec.get('meta') or {}).get('technique') or 'Other'
        return _v756_normalize_technique(kind, rec.get('path'), '')
    except Exception:
        return rec.get('kind') or 'Other'


def _v80_scan_label(rec):
    scan = _v80_meta(rec, 'scan_rate')
    if scan:
        return scan
    txt = _v80_path_text(rec)
    try:
        s2 = _v754_parse_scan_rate_label(txt)
        if s2:
            return s2
    except Exception:
        pass
    return ""


def _v80_cycle_label(rec):
    cyc = _v80_meta(rec, 'cycle')
    if cyc:
        return cyc
    txt = _v80_path_text(rec)
    try:
        return _v756_parse_cycle_label(txt) or ""
    except Exception:
        return ""


def _v80_potential_label(rec):
    pot = _v80_meta(rec, 'potential')
    if pot:
        return pot
    txt = _v80_path_text(rec)
    try:
        return _v754_parse_potential_label(txt) or ""
    except Exception:
        return ""


def _v80_point_label(rec):
    # Parse the filename/path first and choose the last explicit point-like token.
    # This prevents sample-wide names such as point_11points from becoming "point 11"
    # when a later token such as EIS_point1 or pos02 is the real position.
    txt = _v80_path_text(rec)
    matches = []
    pat = r"(?:^|[_\-\s])(?:point|pt|pos|position|spot|site|well)[_\-\s]*0*([0-9]+)(?!\s*points?)(?=$|[_\-\s])"
    for m in re.finditer(pat, txt, flags=re.I):
        try:
            matches.append(int(m.group(1)))
        except Exception:
            pass
    if matches:
        return f"point {matches[-1]:02d}"
    meta = rec.get('meta') or {}
    pt = meta.get('point') or meta.get('position') or meta.get('spot') or meta.get('site') or meta.get('well') or ""
    # Ignore metadata that likely came from point_11points rather than a real point.
    if pt:
        pt_s = str(pt)
        n = _v80_num(pt_s, default=None)
        if n is not None and re.search(rf"(?:^|[_\-\s]){int(n)}\s*points?(?:$|[_\-\s])", txt, flags=re.I):
            return ""
        if not re.search(r"\b\d+\s*points?\b", pt_s, re.I):
            return pt_s
    return ""


def _v80_group_insert(browser, parent, label, kind, records, open_node=False, count_label=None):
    records = list(records or [])
    count_label = count_label or f"{len(records)} file(s)"
    iid = browser.tree.insert(parent, 'end', text=label, values=(kind, count_label), open=open_node)
    paths = []
    for r in records:
        try:
            paths.append(Path(r.get('path')))
        except Exception:
            pass
    if not hasattr(browser, '_paths_by_iid'):
        browser._paths_by_iid = {}
    if not hasattr(browser, '_group_file_paths'):
        browser._group_file_paths = {}
    browser._paths_by_iid[iid] = paths
    browser._group_file_paths[iid] = paths
    return iid


def _v80_cycle_count_text(records):
    cycles = []
    meas = []
    for r in records or []:
        c = _v80_cycle_label(r)
        if c:
            cycles.append(c)
        m = _v80_meta(r, 'measurement')
        if m:
            meas.append(m)
    unique_cycles = sorted(set(cycles), key=_v80_nat_key)
    if len(unique_cycles) > 1:
        return f"{len(unique_cycles)} cycles"
    # HEKA/POTMASTER exports sometimes use m001/m002/m003 as cycle repeats while c001 is constant.
    unique_meas = sorted(set(meas), key=_v80_nat_key)
    if len(unique_meas) in {2, 3, 4, 5}:
        return f"{len(unique_meas)} cycles"
    return unique_cycles[0] if unique_cycles else ""


def _v80_cv_groups(cv_records):
    """Return compact CV groups. Prefer real scan rates; infer scan-rate sets from HEKA measurement triplets only when scan rate is unavailable."""
    cv_records = sorted(cv_records or [], key=lambda r: (_v80_num(_v80_scan_label(r)), _v80_measurement_num(r), str(r.get('path'))))
    with_scan = [r for r in cv_records if _v80_scan_label(r)]
    groups = []
    if with_scan:
        by = {}
        for r in cv_records:
            scan = _v80_scan_label(r) or 'unknown scan rate'
            by.setdefault(scan, []).append(r)
        for scan, recs in sorted(by.items(), key=lambda kv: (_v80_num(kv[0]), _v80_nat_key(kv[0]))):
            groups.append({'label_type': 'scan', 'scan': scan, 'records': recs})
        return groups
    # No scan-rate metadata. Use m001..m012 style ordering and group into triplets when it strongly looks like repeated cycles.
    m_nums = sorted({int(_v80_measurement_num(r)) for r in cv_records if _v80_measurement_num(r) < 10**8})
    if len(m_nums) >= 6 and len(m_nums) % 3 == 0:
        by_m = {}
        for r in cv_records:
            mn = int(_v80_measurement_num(r)) if _v80_measurement_num(r) < 10**8 else 0
            set_idx = ((mn - 1) // 3) + 1 if mn else 9999
            by_m.setdefault(set_idx, []).append(r)
        for idx, recs in sorted(by_m.items()):
            nums = sorted({int(_v80_measurement_num(r)) for r in recs if _v80_measurement_num(r) < 10**8})
            if nums:
                label = f"inferred scan-rate set {idx:02d} (m{nums[0]:03d}–m{nums[-1]:03d})"
            else:
                label = f"inferred scan-rate set {idx:02d}"
            groups.append({'label_type': 'inferred', 'scan': label, 'records': recs})
        return groups
    # Fallback: by measurement when no scan-rate or triplet structure is available.
    by_meas = {}
    for r in cv_records:
        m = _v80_meta(r, 'measurement') or 'CV / LSV files'
        by_meas.setdefault(m, []).append(r)
    for m, recs in sorted(by_meas.items(), key=lambda kv: _v80_nat_key(kv[0])):
        groups.append({'label_type': 'measurement', 'scan': m, 'records': recs})
    return groups


def _v80_exp_summary(records, root_name=''):
    records = list(records or [])
    cv = [r for r in records if _v80_kind(r) == 'CV / LSV']
    eis = [r for r in records if _v80_kind(r) == 'EIS']
    other_kinds = {}
    for r in records:
        k = _v80_kind(r)
        other_kinds[k] = other_kinds.get(k, 0) + 1
    parts = []
    npoints = _v80_infer_total_points(records, root_name=root_name)
    if npoints:
        parts.append(f"{npoints} points")
    if cv:
        scans = sorted({s for s in (_v80_scan_label(r) for r in cv) if s}, key=lambda x: (_v80_num(x), _v80_nat_key(x)))
        if scans:
            parts.append("CV scan rates: " + ", ".join(scans[:8]))
        else:
            cgroups = _v80_cv_groups(cv)
            if cgroups:
                parts.append(f"CV scan-rate sets: {len(cgroups)} inferred")
        # report cycles/set, not raw c001 when the grouping makes it obvious.
        cgroups = _v80_cv_groups(cv)
        cycle_counts = sorted({ _v80_cycle_count_text(g['records']) for g in cgroups if _v80_cycle_count_text(g['records']) }, key=_v80_nat_key)
        if cycle_counts:
            parts.append("cycles: " + ", ".join(cycle_counts[:4]))
    if eis:
        ekeys = set()
        for r in eis:
            ekeys.add((_v80_point_label(r) or 'EIS point', _v80_potential_label(r) or ''))
        parts.append(f"EIS: {len(ekeys) if ekeys else len(eis)} point/set(s)")
    # Only list other meaningful techniques, not every miscellaneous helper file.
    extra = []
    for k, v in sorted(other_kinds.items(), key=lambda kv: str(kv[0])):
        if k not in {'CV / LSV', 'EIS', 'Other', 'Tables / text'} and v:
            extra.append(f"{k}={v}")
    if extra:
        parts.append("other: " + ", ".join(extra[:6]))
    if not parts:
        parts.append(f"{len(records)} indexed data files")
    return " | ".join(parts)


def _v80_refresh_tree(browser):
    """Clean experiment map: group by experiment meaning; never dump all raw files by default."""
    try:
        if hasattr(browser, 'source_folder_var'):
            src = str(browser.source_folder_var.get()).strip()
            if src:
                browser.analysis_root = Path(src).resolve()
                browser.base_name = browser.analysis_root.name.replace('_analysis_ready_csv', '')
                try:
                    browser.analyzed_root = browser.analysis_root / f"{_v35_safe_name(browser.base_name)}_FaradaIQ_analyzed_data"
                    browser._ensure_analyzed_dirs()
                except Exception:
                    pass
    except Exception:
        pass
    try:
        browser.tree.delete(*browser.tree.get_children())
    except Exception:
        pass
    browser._path_by_iid = {}
    browser._paths_by_iid = {}
    browser._group_file_paths = {}
    browser._group_iids = {}
    root = Path(getattr(browser, 'analysis_root', '.')).resolve()
    records, ai_json_files, ai_map = [], [], {}
    try:
        records, ai_json_files, ai_map = _v756_collect_smart_records(browser)
    except Exception as exc:
        try:
            browser.log(f"v80 experiment-map indexing failed; falling back to generic collector: {exc}")
        except Exception:
            pass
        try:
            records = [_v77_record_for_file(p) for p in root.rglob('*') if p.is_file()]
        except Exception:
            records = []
    browser._v80_records = records
    browser._v78_records = records
    browser._v80_ai_json_files = ai_json_files
    browser._v80_ai_map = ai_map
    if not records:
        iid = browser.tree.insert('', 'end', text='No plottable experiment data found', values=('Empty', '0'), open=True)
        browser._paths_by_iid[iid] = []
        try:
            browser.summary_var.set('No plottable experiment data found')
            browser.status_var.set('Choose a folder or run parser/AI-bundle generation first.')
        except Exception:
            pass
        return
    base = getattr(browser, 'base_name', root.name)
    summary = _v80_exp_summary(records, root_name=f"{base} {root.as_posix()}")
    try:
        browser.summary_var.set(summary)
        browser.status_var.set('v80 clean experiment map: select a CV scan-rate set, EIS point/set, or technique group → Plot / overlay selected → Analyze view.')
    except Exception:
        pass
    top = browser.tree.insert('', 'end', text=f"Experiment summary: {base}", values=('Project', summary), open=True)
    _v80_group_insert(browser, top, 'All plottable data in this experiment', 'All', records, open_node=False)

    # CV/LSV section: compact scan-rate sets with optional point children, no raw file leaves.
    cv = [r for r in records if _v80_kind(r) == 'CV / LSV']
    if cv:
        cv_parent = _v80_group_insert(browser, top, 'CV / LSV scan-rate sets', 'CV / LSV', cv, open_node=True)
        for g in _v80_cv_groups(cv):
            recs = list(g['records'])
            npts = _v80_infer_total_points(recs, root_name=f"{base} {' '.join(_v80_path_text(r) for r in recs[:4])}")
            cyc = _v80_cycle_count_text(recs)
            prefix = g['scan']
            if g.get('label_type') == 'inferred':
                label = prefix
            elif g.get('label_type') == 'measurement':
                label = f"CV / LSV measurement {prefix}"
            else:
                label = str(prefix)
            if cyc:
                label += f", {cyc}"
            if npts:
                label += f" — {npts} point(s)"
            label += f" ({len(recs)} file(s))"
            gid = _v80_group_insert(browser, cv_parent, label, 'CV / LSV', recs, open_node=False)
            by_point = {}
            for r in recs:
                pt = _v80_point_label(r) or ('all points' if npts else 'unassigned point')
                by_point.setdefault(pt, []).append(r)
            # Show point children only when they clarify; keep collapsed and do not show individual files.
            if 1 < len(by_point) <= 30:
                for pt, prs in sorted(by_point.items(), key=lambda kv: _v80_nat_key(kv[0])):
                    _v80_group_insert(browser, gid, f"{pt} ({len(prs)} file(s))", 'Point', prs, open_node=False)

    # EIS section: point/potential grouped.
    eis = [r for r in records if _v80_kind(r) == 'EIS']
    if eis:
        eis_parent = _v80_group_insert(browser, top, 'EIS sets', 'EIS', eis, open_node=True)
        by = {}
        for r in eis:
            pt = _v80_point_label(r) or 'EIS point'
            pot = _v80_potential_label(r)
            key = (pt, pot)
            by.setdefault(key, []).append(r)
        for (pt, pot), recs in sorted(by.items(), key=lambda kv: (_v80_nat_key(kv[0][0]), _v80_num(kv[0][1]), _v80_nat_key(kv[0][1]))):
            label = pt
            if pot:
                label += f" | {pot}"
            label += f" ({len(recs)} file(s))"
            _v80_group_insert(browser, eis_parent, label, 'EIS', recs, open_node=False)

    # Other technique sections: grouped by technique and condition/point, not raw files.
    known = {'CV / LSV', 'EIS'}
    by_kind = {}
    for r in records:
        k = _v80_kind(r)
        if k in known:
            continue
        by_kind.setdefault(k or 'Other', []).append(r)
    for k, kres in sorted(by_kind.items(), key=lambda kv: str(kv[0])):
        # Hide helper metadata tables under one collapsed node to avoid clutter.
        open_node = k not in {'Other', 'Tables / text'}
        par = _v80_group_insert(browser, top, k, k, kres, open_node=open_node)
        buckets = {}
        for r in kres:
            cond = _v80_meta(r, 'condition') or ''
            pt = _v80_point_label(r) or ''
            label = ' / '.join([x for x in [cond, pt] if x]) or 'all files'
            buckets.setdefault(label, []).append(r)
        for label, recs in sorted(buckets.items(), key=lambda kv: _v80_nat_key(kv[0]))[:50]:
            _v80_group_insert(browser, par, f"{label} ({len(recs)} file(s))", k, recs, open_node=False)
        if len(buckets) > 50:
            browser.tree.insert(par, 'end', text=f"... {len(buckets)-50} additional grouped buckets hidden", values=(k, ''), open=False)

    # Persist smart index beside the data, not in the launch tracking folder.
    try:
        out = browser.analyzed_root / 'metadata' / 'clean_experiment_map_v80.json'
        out.parent.mkdir(parents=True, exist_ok=True)
        payload = []
        for r in records:
            payload.append({'path': str(r.get('path')), 'kind': _v80_kind(r), 'meta': r.get('meta') or {}, 'size': r.get('size')})
        out.write_text(json.dumps({'version': "v273", 'summary': summary, 'records': payload}, indent=2), encoding='utf-8')
    except Exception:
        pass
    try:
        browser.log(f"v80 clean experiment map indexed {len(records)} files into grouped CV/EIS/technique nodes. Raw file leaves are hidden by default.")
    except Exception:
        pass


def _v80_selected_paths(browser, plottable_only=True):
    paths = []
    try:
        selection = browser.tree.selection()
    except Exception:
        selection = []
    for iid in selection:
        for attr in ('_paths_by_iid', '_group_file_paths'):
            try:
                if iid in getattr(browser, attr, {}):
                    paths.extend(getattr(browser, attr)[iid])
            except Exception:
                pass
        try:
            if iid in getattr(browser, '_path_by_iid', {}):
                paths.append(browser._path_by_iid[iid])
        except Exception:
            pass
    out, seen = [], set()
    plottable_exts = set(_V70_TABLE_EXTS) | set(_V70_IMAGE_EXTS) | set(_V70_VIDEO_EXTS) | {'.npy', '.npz'}
    for p in paths:
        try:
            p = Path(p)
            if plottable_only and p.suffix.lower() not in plottable_exts:
                continue
            key = str(p.resolve()) if p.exists() else str(p)
            if key not in seen:
                seen.add(key)
                out.append(p)
        except Exception:
            pass
    return out


def _v80_builtin_suggestions(browser):
    records = getattr(browser, '_v80_records', None) or getattr(browser, '_v78_records', []) or []
    cv = [r for r in records if _v80_kind(r) == 'CV / LSV']
    eis = [r for r in records if _v80_kind(r) == 'EIS']
    suggestions = []
    if cv:
        cgroups = _v80_cv_groups(cv)
        scans = [g['scan'] for g in cgroups]
        suggestions.append('Overlay CV scan-rate sets: ' + ', '.join(str(x) for x in scans[:10]))
        suggestions.append('Use PySimpleEChem CV workflow on the saved Plot/view for peak, baseline, E½, and ΔEp metrics.')
        npts = _v80_infer_total_points(cv, root_name=getattr(browser, 'base_name', ''))
        if npts:
            suggestions.append(f'Compare CV trends across the {npts}-point map without expanding raw files.')
    if eis:
        suggestions.append('Plot EIS sets with Nyquist plus Bode real, Bode imag, Bode magnitude, and Bode phase.')
        suggestions.append('Compare low-frequency Zreal/|Z| across EIS point or potential groups before fitting.')
    if not suggestions:
        suggestions.append('Select a grouped technique node, click Plot / overlay selected, then Analyze view.')
    return suggestions


def _v80_ai_suggest_comparisons(browser):
    suggestions = _v80_builtin_suggestions(browser)
    try:
        browser.comp_list.delete(0, 'end')
        for s in suggestions:
            browser.comp_list.insert('end', s)
        browser.suggestions = suggestions
    except Exception:
        pass
    try:
        out = browser.analyzed_root / 'comparison_tables' / 'smart_comparison_suggestions_v80.txt'
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text('\n'.join(suggestions), encoding='utf-8')
    except Exception:
        pass
    try:
        browser.log(f"Filled {len(suggestions)} v80 clean-workflow suggestions.")
    except Exception:
        pass


def _v80_browser_build_ui(self):
    try:
        _v78_browser_build_ui(self)
    except Exception:
        return
    try:
        self.title('FaradaIQ Studio v273 — clean experiment map')
    except Exception:
        pass
    try:
        if hasattr(self, 'status_var'):
            self.status_var.set('v80: select one grouped experiment item → Plot / overlay selected → Analyze view. Raw file clutter is hidden by default.')
        if hasattr(self, 'analysis_progress_var'):
            self.analysis_progress_var.set('Select grouped CV/EIS item → Plot / overlay selected → Analyze view')
        if hasattr(self, 'tree'):
            self.tree.heading('#0', text='Experiment / scan-rate set / EIS point / technique group')
    except Exception:
        pass


try:
    FaradaIQDataBrowser._build_ui = _v80_browser_build_ui
    FaradaIQDataBrowser.refresh_tree = _v80_refresh_tree
    FaradaIQDataBrowser.selected_paths = _v80_selected_paths
    FaradaIQDataBrowser.ai_suggest_comparisons = _v80_ai_suggest_comparisons
except Exception:
    pass


def _v80_main():
    try:
        result = _v58_cli(sys.argv[1:])
        if result is not None:
            raise SystemExit(result)
    except SystemExit:
        raise
    except Exception as exc:
        print(f"FaradaIQ CLI failed: {exc}", file=sys.stderr)
        raise SystemExit(1)
    _v52_main()

