# ---- v80 persistent font/theme fix ----
# Problem fixed: the v36 light/dark theme function configured ttk fonts back to
# small hard-coded sizes (9/8 pt).  v75.8/v79 enlarged fonts during startup, but
# the Theme button called _v36_apply_theme again and the styles shrank.  v80 wraps
# the theme applier so the enlarged FaradaIQ font scale is re-applied after every
# theme switch.  This is not an incremental bump; it reasserts stable target sizes.

_V80_FONT_BASE_SIZE = 10
_V80_FONT_SMALL_SIZE = 9
_V80_FONT_SECTION_SIZE = 11
_V80_FONT_HERO_SIZE = 18
_V80_FONT_ROWHEIGHT = 26


def _v80_force_style_fonts(root=None):
    """Reassert FaradaIQ readable fonts after any ttk theme/style reset."""
    try:
        import tkinter.font as _tkfont
        # Keep named fonts readable.  Set absolute target sizes so toggling theme
        # repeatedly does not keep growing the UI.
        named_targets = {
            "TkDefaultFont": _V80_FONT_BASE_SIZE,
            "TkTextFont": _V80_FONT_BASE_SIZE,
            "TkMenuFont": _V80_FONT_BASE_SIZE,
            "TkHeadingFont": _V80_FONT_SECTION_SIZE,
            "TkCaptionFont": _V80_FONT_BASE_SIZE,
            "TkSmallCaptionFont": _V80_FONT_SMALL_SIZE,
            "TkIconFont": _V80_FONT_BASE_SIZE,
            "TkTooltipFont": _V80_FONT_SMALL_SIZE,
            "TkFixedFont": 10,
        }
        for name, size in named_targets.items():
            try:
                _tkfont.nametofont(name).configure(size=int(size))
            except Exception:
                pass
    except Exception:
        pass
    try:
        style = ttk.Style(root) if root is not None else ttk.Style()
        base = _V80_FONT_BASE_SIZE
        small = _V80_FONT_SMALL_SIZE
        section = _V80_FONT_SECTION_SIZE
        try: style.configure("TLabel", font=("Segoe UI", base))
        except Exception: pass
        try: style.configure("Card.TLabel", font=("Segoe UI", base))
        except Exception: pass
        try: style.configure("Muted.TLabel", font=("Segoe UI", small))
        except Exception: pass
        try: style.configure("Status.TLabel", font=("Segoe UI", small))
        except Exception: pass
        try: style.configure("Section.TLabel", font=("Segoe UI Semibold", section))
        except Exception: pass
        try: style.configure("HeroTitle.TLabel", font=("Segoe UI Semibold", _V80_FONT_HERO_SIZE))
        except Exception: pass
        try: style.configure("HeroSub.TLabel", font=("Segoe UI", small))
        except Exception: pass
        try: style.configure("HeroCredit.TLabel", font=("Segoe UI", small))
        except Exception: pass
        try: style.configure("TLabelframe.Label", font=("Segoe UI Semibold", section))
        except Exception: pass
        for sty, font in [
            ("TButton", ("Segoe UI", base)),
            ("Accent.TButton", ("Segoe UI Semibold", base)),
            ("TCheckbutton", ("Segoe UI", base)),
            ("TRadiobutton", ("Segoe UI", base)),
            ("TEntry", ("Segoe UI", base)),
            ("TCombobox", ("Segoe UI", base)),
        ]:
            try: style.configure(sty, font=font)
            except Exception: pass
        try:
            style.configure("Treeview", font=("Segoe UI", base), rowheight=_V80_FONT_ROWHEIGHT)
            style.configure("Treeview.Heading", font=("Segoe UI Semibold", section))
        except Exception:
            pass
    except Exception:
        pass


def _v80_force_widget_fonts(root):
    """Apply readable fonts to classic Tk widgets that are not covered by ttk.Style."""
    if root is None:
        return
    try:
        stack = [root]
        while stack:
            w = stack.pop()
            try:
                cls = str(w.winfo_class())
            except Exception:
                cls = ""
            try:
                if cls in ("Listbox",):
                    w.configure(font=("Segoe UI", _V80_FONT_BASE_SIZE))
                elif cls in ("Text",):
                    w.configure(font=("Consolas", 10))
                elif cls in ("Button", "Checkbutton", "Radiobutton", "Entry", "Label"):
                    w.configure(font=("Segoe UI", _V80_FONT_BASE_SIZE))
            except Exception:
                pass
            try:
                stack.extend(list(w.winfo_children()))
            except Exception:
                pass
    except Exception:
        pass


def _v80_reapply_fonts(root=None):
    try:
        _v80_force_style_fonts(root)
    except Exception:
        pass
    try:
        _v80_force_widget_fonts(root)
    except Exception:
        pass
    try:
        if root is not None and hasattr(root, "after"):
            root.after(80, lambda r=root: (_v80_force_style_fonts(r), _v80_force_widget_fonts(r)))
            root.after(300, lambda r=root: (_v80_force_style_fonts(r), _v80_force_widget_fonts(r)))
    except Exception:
        pass


try:
    _V80_PREV_APPLY_THEME = _v36_apply_theme
except Exception:
    _V80_PREV_APPLY_THEME = None


def _v36_apply_theme(root, mode="dark"):
    # Preserve the original palette/color behavior, then restore the v80 font scale.
    if _V80_PREV_APPLY_THEME is not None:
        _V80_PREV_APPLY_THEME(root, mode)
    try:
        _v80_reapply_fonts(root)
    except Exception:
        pass
    try:
        _v753_track_event("theme_applied", {"version": "v273", "mode": str(mode), "font_scale": "persistent"})
    except Exception:
        pass


def _v36_toggle_theme(self):
    mode = "light" if getattr(self, "_faradaiq_theme_mode", "dark") == "dark" else "dark"
    _v36_apply_theme(self, mode)
    try:
        _v80_reapply_fonts(self)
    except Exception:
        pass


# Also ensure browser/main windows that are built after this patch get the same
# persistent font scale on first draw and after any delayed theme/layout refresh.
try:
    _V80_PREV_BROWSER_BUILD_UI = FaradaIQDataBrowser._build_ui
    def _v80_browser_build_ui(self):
        _V80_PREV_BROWSER_BUILD_UI(self)
        try:
            _v80_reapply_fonts(self)
            self.after(250, lambda w=self: _v80_reapply_fonts(w))
        except Exception:
            pass
    FaradaIQDataBrowser._build_ui = _v80_browser_build_ui
except Exception:
    pass

try:
    _V80_PREV_ROOT_INIT = SessionReaderGUI.__init__
    def _v80_session_reader_gui_init(self, *args, **kwargs):
        _V80_PREV_ROOT_INIT(self, *args, **kwargs)
        try:
            _v80_reapply_fonts(self)
            self.after(250, lambda w=self: _v80_reapply_fonts(w))
        except Exception:
            pass
    SessionReaderGUI.__init__ = _v80_session_reader_gui_init
except Exception:
    pass

try:
    APP_TITLE = "FaradaIQ Studio v273"
    _v753_track_event('python_module_ready', {'version': "v273", 'feature': 'persistent readable font scale after dark/light theme toggle'})
except Exception:
    pass
