# ---- v83 GUI placement + credits cleanup ----
# User-requested layout change:
# 1) The launch-session tracking row is tracking-only and should appear just
#    above the pySECCM / DRT runners block in the main launcher window, not as
#    a loose bottom footer that visually separates from the controls.
# 2) Inline pySECCM/pyDRT credit footers are removed from the working GUI and
#    consolidated inside the About / credits window.
APP_TITLE = "FaradaIQ Studio v273"


def _v83_walk_widgets(root):
    stack = [root]
    while stack:
        w = stack.pop()
        yield w
        try:
            stack.extend(list(w.winfo_children()))
        except Exception:
            pass


def _v83_widget_text(widget):
    try:
        return str(widget.cget("text") or "")
    except Exception:
        return ""


def _v83_find_widget_by_exact_text(root, wanted):
    for w in _v83_walk_widgets(root):
        if _v83_widget_text(w) == wanted:
            return w
    return None


def _v83_remove_inline_credit_labels(root):
    """Move visible credit text out of the working layout and into About/credits."""
    if root is None:
        return
    credit_markers = (
        "pySECCM parser/plot tools credit",
        "pyDRTtools module credit",
        "Ciucci Lab, https://github.com/ciuccislab/pyDRTtools",
    )
    for w in list(_v83_walk_widgets(root)):
        txt = _v83_widget_text(w)
        if not txt:
            continue
        if not any(m in txt for m in credit_markers):
            continue
        # Keep the About button itself; only remove/shorten credit labels.
        if "About" in txt and "credit" in txt.lower():
            continue
        try:
            # If this is a longer descriptive sentence, keep the useful workflow
            # sentence but strip third-party credit from the inline GUI.
            if "Includes electrochemical data parsing" in txt:
                w.configure(text="Includes electrochemical data parsing, pySECCM plotting, DRT automation, and AI-analysis handoff.")
                continue
        except Exception:
            pass
        try:
            w.grid_remove()
        except Exception:
            pass
        try:
            w.pack_forget()
        except Exception:
            pass
        try:
            w.place_forget()
        except Exception:
            pass


def _v83_build_session_banner_frame(parent, title, ctx):
    try:
        frame = ttk.Frame(parent, style="Card.TFrame", padding=(8, 4))
    except Exception:
        frame = ttk.Frame(parent, padding=(8, 4))
    try:
        frame.columnconfigure(1, weight=1)
    except Exception:
        pass
    msg = f"{title}: {ctx.get('session_id')}"
    folder_text = f"Tracking folder only: {ctx.get('session_dir')}"
    try:
        ttk.Label(frame, text=msg, style="Section.TLabel").grid(row=0, column=0, sticky="w", padx=(0, 12))
        ttk.Label(frame, text=folder_text, style="Muted.TLabel").grid(row=0, column=1, sticky="ew", padx=(0, 8))
        ttk.Button(frame, text="Open tracking folder", command=lambda c=ctx: _v753_open_session_folder(c)).grid(row=0, column=2, sticky="e", padx=(4, 0))
        ttk.Button(frame, text="Copy ID", command=lambda w=parent.winfo_toplevel(), c=ctx: _v753_copy_session_id(w, c)).grid(row=0, column=3, sticky="e", padx=(4, 0))
    except Exception:
        ttk.Label(frame, text=msg).pack(side="left", padx=(0, 10))
        ttk.Label(frame, text=folder_text).pack(side="left", fill="x", expand=True)
        ttk.Button(frame, text="Open tracking folder", command=lambda c=ctx: _v753_open_session_folder(c)).pack(side="right", padx=(5, 0))
        ttk.Button(frame, text="Copy ID", command=lambda w=parent.winfo_toplevel(), c=ctx: _v753_copy_session_id(w, c)).pack(side="right", padx=(5, 0))
    return frame


def _v753_add_session_banner(window, title="Launch session"):
    """v83: place main launch-session tracker above pySECCM/DRT runners when present."""
    try:
        root = window.winfo_toplevel()
    except Exception:
        root = window
    try:
        if getattr(root, "_v753_session_banner_added", False):
            return
        ctx = _v753_launch_context()
        runner = _v83_find_widget_by_exact_text(root, "pySECCM / DRT runners")
        if runner is not None:
            parent = runner.master
            frame = _v83_build_session_banner_frame(parent, title, ctx)
            # The pySECCM runner block is grid-managed inside the main top panel.
            # Insert the tracking banner immediately above it by shifting rows down.
            try:
                info = runner.grid_info()
                target_row = int(info.get("row", 0))
                target_col = int(info.get("column", 0))
                target_span = int(info.get("columnspan", 1))
                for slave in list(parent.grid_slaves()):
                    try:
                        sinfo = slave.grid_info()
                        srow = int(sinfo.get("row", 0))
                        if srow >= target_row:
                            slave.grid_configure(row=srow + 1)
                    except Exception:
                        pass
                frame.grid(row=target_row, column=target_col, columnspan=max(1, target_span), sticky="ew", pady=(6, 4))
            except Exception:
                frame.pack(fill="x", padx=6, pady=(4, 4), before=runner)
        else:
            # Browser windows do not have the pySECCM runner panel; keep their
            # tracker as a compact bottom strip so it does not crowd the plot area.
            frame = _v83_build_session_banner_frame(root, title, ctx)
            try:
                frame.pack(side="bottom", fill="x", padx=6, pady=(2, 4))
            except Exception:
                frame.pack(fill="x", padx=6, pady=(2, 4))
        root._v753_session_banner_added = True
        root._v753_session_banner_frame = frame
        try:
            _v80_reapply_fonts(frame)
        except Exception:
            try:
                _v758_apply_font_bump_recursive(frame, delta=1)
            except Exception:
                pass
    except Exception:
        pass


