# ---- v83 experiment-map + PySimpleEChem selected-view workflow patch ----
# User-requested behavior:
# * CV map should use parser/AI manifest sequence information (11 points, 4 scan rates, 3 cycles)
#   instead of blindly grouping every m001/m002/m003 triplet as a new scan-rate set.
# * EIS map should keep real point groups visible and move aggregate/helper EIS files out of the way.
# * Plot/view list needs a Clear button.
# * PySimpleEChem CV workflow must appear for CV plot/views and be able to open the selected
#   Plot/view CV files directly.

APP_TITLE = "FaradaIQ Studio v273"


def _v83_as_list(x):
    if isinstance(x, list):
        return x
    if isinstance(x, tuple):
        return list(x)
    if x is None:
        return []
    return [x]


def _v83_walk_dicts(obj, max_items=20000):
    seen = 0
    stack = [obj]
    while stack and seen < max_items:
        cur = stack.pop()
        seen += 1
        if isinstance(cur, dict):
            yield cur
            for v in cur.values():
                if isinstance(v, (dict, list, tuple)):
                    stack.append(v)
        elif isinstance(cur, (list, tuple)):
            for v in cur[:10000]:
                if isinstance(v, (dict, list, tuple)):
                    stack.append(v)


def _v83_rate_label_from_method(m):
    if not isinstance(m, dict):
        return ''
    val = m.get('scan_rate_V_s') or m.get('scan_rate') or m.get('rate_V_s')
    if val not in (None, '', 'null'):
        try:
            v = float(val)
            if v > 0:
                return f'{v*1000:g} mV/s'
        except Exception:
            pass
    raw = str(m.get('rate') or m.get('raw_text') or '')
    mt0 = re.search(r'([0-9.+\-Ee]+)\s*(mV|V)', raw, flags=re.I)
    if mt0:
        try:
            v = float(mt0.group(1))
            unit = mt0.group(2).lower()
            return f'{v:g} mV/s' if unit == 'mv' else f'{v*1000:g} mV/s'
        except Exception:
            pass
    mt = re.search(r'Rate\s*=\s*([0-9.+\-Ee]+)\s*(mV|V)', raw, flags=re.I)
    if mt:
        try:
            v = float(mt.group(1))
            unit = mt.group(2).lower()
            return f'{v:g} mV/s' if unit == 'mv' else f'{v*1000:g} mV/s'
        except Exception:
            pass
    return ''


def _v83_cycles_from_method(m):
    if not isinstance(m, dict):
        return 1
    for k in ('cycles', 'n_cycles', 'cycle_count'):
        try:
            if m.get(k) not in (None, ''):
                return max(1, int(float(m.get(k))))
        except Exception:
            pass
    raw = str(m.get('raw_text') or '')
    mt = re.search(r'Cycles\s*=\s*([0-9.]+)', raw, flags=re.I)
    if mt:
        try:
            return max(1, int(float(mt.group(1))))
        except Exception:
            pass
    return 1


def _v83_load_experiment_context(root):
    """Read summary/manifest JSON files and extract the experimental sequence model."""
    root = Path(root).resolve()
    ctx = {
        'json_files': [],
        'point_count': 0,
        'cv_methods': [],
        'eis_methods': [],
        'software_exports': [],
        'drt_input_files': [],
        'notes': [],
    }
    candidates = []
    search_roots = [root]
    # If the user selected an analysis_ready folder, useful summary files may be in the parent/out folder too.
    try:
        search_roots.append(root.parent)
    except Exception:
        pass
    seen = set()
    for sr in search_roots:
        try:
            for jp in sr.rglob('*.json'):
                name = jp.name.lower()
                if any(tok in name for tok in ('summary', 'manifest', 'sequence', 'analysis_ready', 'parsed', 'metadata')):
                    key = str(jp.resolve())
                    if key not in seen:
                        seen.add(key); candidates.append(jp)
        except Exception:
            pass
    # Prefer nearby/small structured files first.
    candidates = sorted(candidates, key=lambda p: (0 if p.parent == root else 1, len(p.name), str(p).lower()))[:200]
    method_seen = set()
    for jp in candidates:
        try:
            data = json.loads(jp.read_text(encoding='utf-8', errors='ignore'))
        except Exception:
            continue
        ctx['json_files'].append(str(jp))
        for d in _v83_walk_dicts(data):
            # point count from any HEKA/SECCM summary level
            for k in ('n_inferred_measurement_points', 'sequence_point_count', 'n_heka_blocks_or_positions', 'n_total_measurements'):
                try:
                    v = d.get(k)
                    if v not in (None, ''):
                        n = int(float(v))
                        if n > ctx['point_count']:
                            ctx['point_count'] = n
                except Exception:
                    pass
            try:
                cs = d.get('collection_summary') or {}
                n = int(float(cs.get('n_total_measurements') or 0))
                if n > ctx['point_count']:
                    ctx['point_count'] = n
            except Exception:
                pass
            # method entries
            for key in ('method_entries', 'heka_method_entries'):
                vals = d.get(key)
                if isinstance(vals, list):
                    for m in vals:
                        if not isinstance(m, dict):
                            continue
                        raw = ' '.join(str(m.get(k) or '') for k in ('technique_text', 'technique', 'raw_text'))
                        ident = (m.get('method_entry'), raw[:120])
                        if ident in method_seen:
                            continue
                        method_seen.add(ident)
                        if re.search(r'\bCV\b|cyclic', raw, flags=re.I):
                            rate = _v83_rate_label_from_method(m)
                            cycles = _v83_cycles_from_method(m)
                            label = rate or f"CV method {len(ctx['cv_methods'])+1}"
                            ctx['cv_methods'].append({'label': label, 'scan_rate': rate, 'cycles': cycles, 'raw': raw, 'method_entry': m.get('method_entry')})
                        elif re.search(r'\bEIS\b|StartFreq|EndFreq|impedance', raw, flags=re.I):
                            ctx['eis_methods'].append(dict(m))
            # software export paths from parser summary
            exp = d.get('seccm_software_exports') or d.get('heka_seccm_software_exports')
            if isinstance(exp, dict):
                for f in exp.get('files') or []:
                    if isinstance(f, dict):
                        ctx['software_exports'].append(dict(f))
            gdi = d.get('generic_drt_input')
            if isinstance(gdi, dict):
                for f in gdi.get('files') or []:
                    if f:
                        ctx['drt_input_files'].append(str(f))
    # Clean / de-duplicate methods while preserving order.
    cv2, seen2 = [], set()
    for m in ctx['cv_methods']:
        key = (m.get('scan_rate') or m.get('label'), m.get('cycles'))
        if key not in seen2:
            seen2.add(key); cv2.append(m)
    ctx['cv_methods'] = cv2
    # If method entries were not found but software exports have scan-rate names, use those.
    if not ctx['cv_methods']:
        for f in ctx['software_exports']:
            if str(f.get('kind','')).upper() == 'CV' or re.search(r'CV', str(f.get('filename','')), re.I):
                rate = _v754_parse_scan_rate_label(str(f.get('filename') or f.get('path') or '')) if '_v754_parse_scan_rate_label' in globals() else ''
                cyc = _v756_parse_cycle_label(str(f.get('filename') or f.get('path') or '')) if '_v756_parse_cycle_label' in globals() else ''
                cn = int(float(re.search(r'\d+', str(cyc)).group(0))) if re.search(r'\d+', str(cyc)) else 3
                label = rate or f"CV export {len(ctx['cv_methods'])+1}"
                ctx['cv_methods'].append({'label': label, 'scan_rate': rate, 'cycles': cn, 'raw': str(f.get('filename') or '')})
    return ctx


def _v83_record_m_number(rec):
    # Use metadata first, then m### in filename/path.
    try:
        meta = rec.get('meta') or {}
        for k in ('measurement', 'measurement_index'):
            val = meta.get(k)
            if val not in (None, ''):
                m = re.search(r'\d+', str(val))
                if m:
                    return int(m.group(0))
    except Exception:
        pass
    txt = _v80_path_text(rec) if '_v80_path_text' in globals() else str(rec.get('path',''))
    m = re.search(r'(?:^|[_\-\s])m0*([0-9]+)(?=$|[_\-\s])', txt, flags=re.I)
    if m:
        return int(m.group(1))
    m = re.search(r'(?:measurement|pair|sweep)[_\-\s]*0*([0-9]+)', txt, flags=re.I)
    if m:
        return int(m.group(1))
    return 0


def _v83_cv_sequence_info(rec, ctx):
    methods = list(ctx.get('cv_methods') or [])
    if not methods:
        return None
    mnum = _v83_record_m_number(rec)
    if not mnum:
        return None
    per_point = sum(max(1, int(m.get('cycles') or 1)) for m in methods)
    if per_point <= 0:
        return None
    point_idx = ((mnum - 1) // per_point) + 1
    within = (mnum - 1) % per_point
    acc = 0
    for method_idx, m in enumerate(methods, start=1):
        cyc = max(1, int(m.get('cycles') or 1))
        if acc <= within < acc + cyc:
            cycle_idx = within - acc + 1
            return {
                'mnum': mnum,
                'point_idx': point_idx,
                'method_idx': method_idx,
                'cycle_idx': cycle_idx,
                'cycles': cyc,
                'scan': m.get('scan_rate') or m.get('label') or f'CV method {method_idx}',
                'label': m.get('label') or m.get('scan_rate') or f'CV method {method_idx}',
            }
        acc += cyc
    return None


def _v83_cv_groups(cv_records, ctx):
    cv_records = list(cv_records or [])
    methods = list(ctx.get('cv_methods') or [])
    point_count = int(ctx.get('point_count') or 0)
    # Preferred path: parser sequence model. This fixes HEKA/POTMASTER exports such as
    # 11 points × 4 CV methods × 3 cycles = 132 files.
    if methods:
        grouped = {i: [] for i in range(1, len(methods)+1)}
        for r in cv_records:
            info = _v83_cv_sequence_info(r, ctx)
            if info and info['method_idx'] in grouped:
                rr = dict(r); rr['_v83_cv_info'] = info
                grouped[info['method_idx']].append(rr)
        if any(grouped.values()):
            out = []
            for i, recs in grouped.items():
                if not recs:
                    continue
                m = methods[i-1]
                cyc = max(1, int(m.get('cycles') or 1))
                scan = m.get('scan_rate') or m.get('label') or f'CV method {i}'
                pts = sorted({(_v83_cv_sequence_info(r, ctx) or {}).get('point_idx') for r in recs if (_v83_cv_sequence_info(r, ctx) or {}).get('point_idx')})
                out.append({
                    'label_type': 'sequence',
                    'scan': scan,
                    'method_idx': i,
                    'cycles': cyc,
                    'points': pts,
                    'point_count': point_count or len(pts),
                    'records': recs,
                })
            return out
    # Fallback to previous v80 behavior for non-HEKA or missing summaries.
    try:
        return _v80_cv_groups(cv_records)
    except Exception:
        return [{'label_type':'all', 'scan':'CV / LSV files', 'records':cv_records}]


def _v83_eis_point_label(rec):
    txt = _v80_path_text(rec) if '_v80_path_text' in globals() else str(rec.get('path',''))
    # Prefer explicit position### in DRT/EIS input filenames.
    m = re.search(r'(?:position|pos|point|pt)[_\-\s]*0*([0-9]+)', txt, flags=re.I)
    if m and not re.search(rf'{m.group(1)}\s*points?', txt, flags=re.I):
        return f'point {int(m.group(1)):02d}'
    try:
        return _v80_point_label(rec)
    except Exception:
        return ''


def _v83_refresh_tree(browser):
    """Clean experiment map v83: parser-summary-aware CV/EIS grouping."""
    try:
        if hasattr(browser, 'source_folder_var'):
            src = str(browser.source_folder_var.get()).strip()
            if src:
                browser.analysis_root = Path(src).resolve()
                browser.base_name = browser.analysis_root.name.replace('_analysis_ready_csv', '').replace('_analysis_ready', '')
                try:
                    browser.analyzed_root = browser.analysis_root / f"{_v35_safe_name(browser.base_name)}_FaradaIQ_analyzed_data"
                    browser._ensure_analyzed_dirs()
                except Exception:
                    pass
    except Exception:
        pass
    try:
        browser.tree.delete(*browser.tree.get_children())
    except Exception:
        pass
    browser._path_by_iid = {}
    browser._paths_by_iid = {}
    browser._group_file_paths = {}
    browser._group_iids = {}
    root = Path(getattr(browser, 'analysis_root', '.')).resolve()
    if not root.exists():
        try: browser.log(f'Analysis root does not exist: {root}')
        except Exception: pass
        return
    try:
        records, ai_json_files, ai_map = _v756_collect_smart_records(browser)
    except Exception as exc:
        records, ai_json_files, ai_map = [], [], {}
        try: browser.log(f'v83 collector failed: {exc}')
        except Exception: pass
    ctx = _v83_load_experiment_context(root)
    browser._v83_experiment_context = ctx
    browser._v80_records = records
    browser._v80_ai_json_files = ai_json_files
    browser._v80_ai_map = ai_map
    if not records:
        iid = browser.tree.insert('', 'end', text='No data files found', values=('Empty', '0 files'), open=True)
        browser._group_file_paths[iid] = []
        return
    base = getattr(browser, 'base_name', root.name)
    point_count = int(ctx.get('point_count') or 0) or _v80_infer_total_points(records, root_name=f'{base} {root.as_posix()}')
    cv = [r for r in records if _v80_kind(r) == 'CV / LSV']
    eis = [r for r in records if _v80_kind(r) == 'EIS']
    other = [r for r in records if _v80_kind(r) not in {'CV / LSV', 'EIS'}]
    cv_groups = _v83_cv_groups(cv, ctx)
    # Build summary from context, not noisy raw-file count.
    summary_parts = []
    if point_count:
        summary_parts.append(f'{point_count} points')
    if cv_groups:
        scans = [str(g.get('scan')) for g in cv_groups]
        summary_parts.append('CV scan rates: ' + ', '.join(scans[:8]))
        cyc = sorted({str(g.get('cycles')) for g in cv_groups if g.get('cycles')}, key=_v80_nat_key)
        if cyc:
            summary_parts.append('cycles: ' + ', '.join(f'{c} cycles' for c in cyc[:4]))
    # Count meaningful EIS point groups.
    eis_points = sorted({p for p in (_v83_eis_point_label(r) for r in eis) if p}, key=_v80_nat_key)
    if eis_points:
        summary_parts.append(f'EIS: {len(eis_points)} point(s)')
    elif eis:
        summary_parts.append('EIS: 1 set')
    summary = ' | '.join(summary_parts) or f'{len(records)} indexed data files'
    top = browser.tree.insert('', 'end', text=f'Experiment summary: {base}', values=('Project', summary), open=True)
    browser._group_file_paths[top] = [Path(r.get('path')) for r in records]
    # Keep all data as one collapsed utility node, not expanded by default.
    all_iid = _v80_group_insert(browser, top, 'All plottable data in this experiment', 'All', records, open_node=False)
    try:
        browser.tree.item(all_iid, open=False)
    except Exception:
        pass
    # CV section: four scan-rate sets for a HEKA example, or similar parser-derived groups generally.
    if cv:
        cv_parent = _v80_group_insert(browser, top, 'CV / LSV scan-rate sets', 'CV / LSV', cv, open_node=True)
        for g in cv_groups:
            recs = list(g.get('records') or [])
            pts = g.get('points') or []
            npts = int(g.get('point_count') or point_count or len(pts) or _v80_infer_total_points(recs, root_name=base))
            cyc = int(g.get('cycles') or 0)
            label = str(g.get('scan') or 'CV / LSV set')
            if cyc:
                label += f', {cyc} cycles'
            if npts:
                label += f' — {npts} point(s)'
            label += f' ({len(recs)} file(s))'
            gid = _v80_group_insert(browser, cv_parent, label, 'CV / LSV', recs, open_node=False)
            by_point = {}
            for r in recs:
                info = r.get('_v83_cv_info') or _v83_cv_sequence_info(r, ctx) or {}
                pidx = info.get('point_idx')
                pt = f'point {int(pidx):02d}' if pidx else (_v80_point_label(r) or 'all / unassigned points')
                by_point.setdefault(pt, []).append(r)
            if 1 < len(by_point) <= 60:
                for pt, prs in sorted(by_point.items(), key=lambda kv: _v80_nat_key(kv[0])):
                    # Count cycles from sequence info if possible.
                    cycs = sorted({(r.get('_v83_cv_info') or _v83_cv_sequence_info(r, ctx) or {}).get('cycle_idx') for r in prs if (r.get('_v83_cv_info') or _v83_cv_sequence_info(r, ctx) or {}).get('cycle_idx')})
                    suffix = f'{len(cycs)} cycle(s)' if cycs else f'{len(prs)} file(s)'
                    _v80_group_insert(browser, gid, f'{pt} ({suffix})', 'Point', prs, open_node=False)
    # EIS section: show real point groups first; push helper/aggregate files to a collapsed extra node.
    if eis:
        eis_parent = _v80_group_insert(browser, top, 'EIS sets', 'EIS', eis, open_node=True)
        by_point = {}
        extras = []
        for r in eis:
            pt = _v83_eis_point_label(r)
            if pt:
                by_point.setdefault(pt, []).append(r)
            else:
                extras.append(r)
        if by_point:
            for pt, recs in sorted(by_point.items(), key=lambda kv: _v80_nat_key(kv[0])):
                _v80_group_insert(browser, eis_parent, f'{pt} ({len(recs)} file(s))', 'EIS', recs, open_node=False)
            if extras:
                _v80_group_insert(browser, eis_parent, f'Other EIS helper/aggregate files ({len(extras)} file(s))', 'EIS helper', extras, open_node=False)
        else:
            # no point labels: fall back to potential grouping, but hide mega-groups last.
            by = {}
            for r in eis:
                pot = _v80_potential_label(r) or 'EIS set'
                by.setdefault(pot, []).append(r)
            for pot, recs in sorted(by.items(), key=lambda kv: (_v80_num(kv[0]), _v80_nat_key(kv[0]))):
                _v80_group_insert(browser, eis_parent, f'{pot} ({len(recs)} file(s))', 'EIS', recs, open_node=False)
    # Other techniques: same compact grouping as v80, but keep helper tables collapsed.
    by_kind = {}
    for r in other:
        k = _v80_kind(r) or 'Other'
        by_kind.setdefault(k, []).append(r)
    for k, kres in sorted(by_kind.items(), key=lambda kv: str(kv[0])):
        open_node = k not in {'Other', 'Tables / text', 'HEKA'}
        par = _v80_group_insert(browser, top, k, k, kres, open_node=open_node)
        buckets = {}
        for r in kres:
            cond = _v80_meta(r, 'condition') or ''
            pt = _v83_eis_point_label(r) or _v80_point_label(r) or ''
            label = ' / '.join([x for x in [cond, pt] if x]) or 'all files'
            buckets.setdefault(label, []).append(r)
        for label, recs in sorted(buckets.items(), key=lambda kv: _v80_nat_key(kv[0]))[:30]:
            _v80_group_insert(browser, par, f'{label} ({len(recs)} file(s))', k, recs, open_node=False)
        if len(buckets) > 30:
            browser.tree.insert(par, 'end', text=f'... {len(buckets)-30} additional grouped buckets hidden', values=(k, ''), open=False)
    try:
        out = browser.analyzed_root / 'metadata' / 'clean_experiment_map_v83.json'
        out.parent.mkdir(parents=True, exist_ok=True)
        payload = [{'path': str(r.get('path')), 'kind': _v80_kind(r), 'meta': r.get('meta') or {}, 'size': r.get('size')} for r in records]
        out.write_text(json.dumps({'version': "v273", 'summary': summary, 'context': ctx, 'records': payload}, indent=2, default=str), encoding='utf-8')
    except Exception:
        pass
    try:
        browser.status_var.set('v83 experiment map: select scan-rate set / EIS point → Plot / overlay selected → Analyze view or PySimpleEChem CV workflow.')
        browser.log(f'v83 experiment map indexed {len(records)} records using parser context: {summary}')
    except Exception:
        pass


def _v83_clear_plot_views(browser):
    try:
        n = int(browser.plot_view_list.size()) if hasattr(browser, 'plot_view_list') else 0
    except Exception:
        n = 0
    if n:
        try:
            ok = messagebox.askyesno('Clear Plot/view list', f'Clear all {n} saved plot/view items from this browser session?', parent=browser)
            if not ok:
                return
        except Exception:
            pass
    try:
        browser.plot_view_list.delete(0, 'end')
    except Exception:
        pass
    try:
        browser._v69_plot_views = []
    except Exception:
        pass
    try:
        browser.last_plot_paths = []
    except Exception:
        pass
    try:
        _v75_save_session(browser, silent=True)
    except Exception:
        pass
    try:
        browser.log('Cleared Plot/view list for this browser session.')
        if hasattr(browser, 'status_var'):
            browser.status_var.set('Plot/view list cleared.')
    except Exception:
        pass


def _v83_current_plot_view_kind(browser):
    # More reliable than old path-only detection; uses stored kind, mode, visible name, and paths.
    paths = []
    label = ''
    kind = ''
    try:
        sel = browser.plot_view_list.curselection()
        if sel and getattr(browser, '_v69_plot_views', None):
            idx = sel[0]
            view = browser._v69_plot_views[idx]
            kind = str(view.get('kind') or '')
            label = str(view.get('name') or browser.plot_view_list.get(idx) or '')
            paths = [Path(p) for p in view.get('paths', []) or []]
            if not paths:
                for c in view.get('curves', []) or []:
                    if isinstance(c, dict) and c.get('path'):
                        paths.append(Path(c.get('path')))
    except Exception:
        pass
    text = ' '.join([kind, label, ' '.join(str(p) for p in paths), str(getattr(browser, 'plot_mode_var', tk.StringVar(value='')).get() if hasattr(browser, 'plot_mode_var') else '')]).lower()
    if 'cv' in text or 'lsv' in text or ('current' in text and 'potential' in text):
        return 'CV / LSV'
    if 'eis' in text or 'zreal' in text or 'zimag' in text or 'nyquist' in text or 'bode' in text:
        return 'EIS'
    if kind:
        return kind
    try:
        return _v75_kind_from_paths(paths)
    except Exception:
        return 'General'


def _v83_selected_cv_paths(browser):
    paths = []
    try:
        paths = _v75x_get_selected_view_paths(browser)
    except Exception:
        pass
    if not paths:
        try:
            paths = browser.selected_paths(plottable_only=True)
        except Exception:
            paths = []
    tables = []
    try:
        tables = _v70_table_paths(paths)
    except Exception:
        tables = [Path(p) for p in paths]
    out = []
    for p in tables:
        s = str(p).lower()
        if any(tok in s for tok in ['cv', 'lsv', 'current_vs_potential', 'voltamm']) or (('current' in s or 'imon' in s) and ('potential' in s or 'emon' in s)):
            out.append(Path(p))
    if not out and _v83_current_plot_view_kind(browser) == 'CV / LSV':
        out = [Path(p) for p in tables]
    ded, seen = [], set()
    for p in out:
        k = str(p.resolve()) if Path(p).exists() else str(p)
        if k not in seen:
            ded.append(Path(p)); seen.add(k)
    return ded


def _v83_write_pysimpleechem_selected_manifest(browser, paths):
    try:
        outdir = browser.analyzed_root / 'pysimpleechem_cv_results'
    except Exception:
        root = Path(getattr(browser, 'analysis_root', Path.cwd()))
        outdir = root / f'{_v35_safe_name(getattr(browser, "base_name", root.name))}_FaradaIQ_analyzed_data' / 'pysimpleechem_cv_results'
    outdir.mkdir(parents=True, exist_ok=True)
    mf = outdir / f'faradaiq_selected_cv_files_{datetime.now().strftime("%Y%m%d_%H%M%S")}.json'
    try:
        sel_name = ''
        sel = browser.plot_view_list.curselection()
        if sel:
            sel_name = browser.plot_view_list.get(sel[0])
    except Exception:
        sel_name = ''
    payload = {
        'created': datetime.now().isoformat(timespec='seconds'),
        'source': 'FaradaIQ Studio v273 Plot/view list selection',
        'plot_view_name': sel_name,
        'files': [str(Path(p)) for p in paths],
    }
    mf.write_text(json.dumps(payload, indent=2), encoding='utf-8')
    return mf


def _v83_open_native_pysimpleechem_with_selected(browser=None):
    try:
        app_dir = Path(__file__).resolve().parent
        pse = app_dir / 'integrated_tools' / 'PySimpleEChem' / 'PySimpleEChem.py'
        if not pse.exists():
            messagebox.showerror('PySimpleEChem missing', f'Could not find: {pse}', parent=browser)
            return
        paths = _v83_selected_cv_paths(browser) if browser is not None else []
        if not paths:
            messagebox.showinfo('No CV plot/view selected', 'Select a CV plot/view from the Plot/view list first, then open PySimpleEChem.', parent=browser)
            return
        mf = _v83_write_pysimpleechem_selected_manifest(browser, paths)
        env = _v227_theme_environment(browser) if '_v227_theme_environment' in globals() else os.environ.copy()
        env['FARADAIQ_PYSIMPLEECHEM_CV_MANIFEST'] = str(mf)
        _v757_subprocess.Popen([_v757_sys.executable, str(pse), '--faradaiq-cv-manifest', str(mf)], cwd=str(pse.parent), env=env)
        if browser is not None:
            browser.log(f'Launched PySimpleEChem with {len(paths)} selected CV file(s): {mf}')
    except Exception as exc:
        try:
            messagebox.showerror('Could not launch PySimpleEChem with selected CV files', str(exc), parent=browser)
        except Exception:
            pass
        try:
            browser.log(f'Could not launch PySimpleEChem with selected CV files: {exc}')
        except Exception:
            pass


