def _v83_browser_build_ui(self):
    try:
        _v80_browser_build_ui(self)
    except Exception:
        try:
            _v78_browser_build_ui(self)
        except Exception:
            return
    try:
        self.title('FaradaIQ Studio v273 — experiment map + PySimpleEChem CV')
    except Exception:
        pass
    # Fix missing old-name callbacks used by v80 UI lambdas and add Clear list button.
    try:
        if hasattr(self, 'plot_view_list'):
            self.plot_view_list.bind('<<ListboxSelect>>', lambda e, b=self: _v83_load_plot_view(b))
            self.plot_view_list.bind('<F2>', lambda e, b=self: (_v757_rename_current_view(b), 'break'))
            self.plot_view_list.bind('<Double-Button-1>', lambda e, b=self: (_v757_rename_current_view(b), 'break'))
            # Add a small row before the analysis-tools frame, only once.
            if not getattr(self, '_v83_clear_plot_views_button_added', False):
                parent = self.plot_view_list.master.master
                row = ttk.Frame(parent, style='Card.TFrame')
                before = getattr(self, 'schema_frame', None)
                try:
                    row.pack(fill='x', pady=(0, 5), before=before)
                except Exception:
                    row.pack(fill='x', pady=(0, 5))
                ttk.Button(row, text='Clear Plot/view list', command=lambda b=self: _v83_clear_plot_views(b)).pack(side='left', fill='x', expand=True)
                ttk.Button(row, text='Open PySimpleEChem for selected CV view', command=lambda b=self: _v83_open_native_pysimpleechem_with_selected(b)).pack(side='left', fill='x', expand=True, padx=(6,0))
                self._v83_clear_plot_views_button_added = True
            # Right-click menu includes clear and selected PySimpleEChem open.
            menu = tk.Menu(self.plot_view_list, tearoff=0)
            menu.add_command(label='Rename plot/view', command=lambda b=self: _v757_rename_current_view(b))
            menu.add_command(label='Open PySimpleEChem with selected CV files', command=lambda b=self: _v83_open_native_pysimpleechem_with_selected(b))
            menu.add_command(label='Clear Plot/view list', command=lambda b=self: _v83_clear_plot_views(b))
            def popup(ev, m=menu, b=self):
                try:
                    idx = b.plot_view_list.nearest(ev.y)
                    b.plot_view_list.selection_clear(0, 'end')
                    b.plot_view_list.selection_set(idx)
                    b.plot_view_list.activate(idx)
                except Exception:
                    pass
                m.tk_popup(ev.x_root, ev.y_root)
            self.plot_view_list.bind('<Button-3>', popup)
    except Exception as exc:
        try: self.log(f'Could not add v83 Plot/view controls: {exc}')
        except Exception: pass
    try:
        if hasattr(self, 'status_var'):
            self.status_var.set('v83: clean parser-aware CV/EIS map; select group → Plot / overlay selected → PySimpleEChem CV from Plot/view list.')
    except Exception:
        pass


