def _v83_set_window_icon(window):
    try:
        ico, png = _v83_icon_paths()
        if ico.exists():
            try:
                window.iconbitmap(str(ico))
            except Exception:
                pass
        if png.exists():
            try:
                photo = tk.PhotoImage(file=str(png))
                window.iconphoto(True, photo)
                # Keep a reference; otherwise Tk may discard it.
                window._faradaiq_v83_iconphoto = photo
            except Exception:
                pass
    except Exception:
        pass


def _v83_explicit_spectroscopy_evidence(rec):
    """Return True only for explicit spectroscopy evidence, not accidental cm-1/text matches."""
    try:
        p = Path(rec.get('path') or '')
    except Exception:
        p = Path(str(rec.get('path') or ''))
    meta = rec.get('meta', {}) or {}
    # Do not treat the already-assigned technique/kind as evidence; that may be
    # the false-positive label we are trying to suppress.  Use file/folder names
    # and descriptive metadata instead.
    pieces = [str(p.name), str(p.parent)]
    for k in ('method_id', 'curve_title', 'measurement_title', 'source', 'vendor', 'instrument', 'parser'):
        try:
            pieces.append(str(rec.get(k) or meta.get(k) or ''))
        except Exception:
            pass
    txt = ' '.join(pieces).lower()
    explicit = [
        'raman', 'sers', 'surface enhanced raman', 'raman_shift', 'ramanshift',
        'raman shift', 'rs_', '_rs_', 'spectrum_raman', 'spectra_raman'
    ]
    return any(x in txt for x in explicit)


def _v83_keep_map_record(rec, root=None):
    """Keep electrochemical/map records, but suppress false-positive spectroscopy buckets."""
    try:
        kind = _v80_kind(rec) if '_v80_kind' in globals() else (rec.get('kind') or rec.get('technique') or '')
    except Exception:
        kind = rec.get('kind') or rec.get('technique') or ''
    kind = str(kind or '')
    # In electrochemical parser output, helper CSV/JSON/text sometimes gets misread as Raman/SERS
    # because of generic spectral-column tokens.  Only show Raman/SERS when explicit Raman/SERS
    # labels exist in path/metadata.  Keep true Raman/SERS files for future multimodal datasets.
    if kind == 'Raman / SERS' and not _v83_explicit_spectroscopy_evidence(rec):
        return False
    # Also hide obvious FaradaIQ/support generated internals from experiment map when they are not data.
    try:
        ptxt = str(Path(rec.get('path') or '')).lower().replace('\\', '/')
        name = Path(rec.get('path') or '').name.lower()
        helper_names = (
            '_faradaiq_', 'smart_data_tree_index', 'session_context_from_bat',
            'launcher_events', 'dependency_check', 'seed_python_check'
        )
        if any(x in name for x in helper_names):
            return False
        if 'faradaiq_launch_sessions' in ptxt:
            return False
    except Exception:
        pass
    return True


try:
    _V83_ORIG_COLLECT_SMART_RECORDS = _v756_collect_smart_records
except Exception:
    _V83_ORIG_COLLECT_SMART_RECORDS = None


def _v83_collect_smart_records(browser):
    if _V83_ORIG_COLLECT_SMART_RECORDS is None:
        return [], [], {}
    records, ai_json_files, ai_map = _V83_ORIG_COLLECT_SMART_RECORDS(browser)
    try:
        root = Path(getattr(browser, 'analysis_root', '.')).resolve()
    except Exception:
        root = None
    filtered = []
    dropped = 0
    for rec in list(records or []):
        if _v83_keep_map_record(rec, root):
            filtered.append(rec)
        else:
            dropped += 1
    if dropped:
        try:
            browser.log(f'v83 experiment map suppressed {dropped} helper/false-positive spectroscopy record(s).')
        except Exception:
            pass
    return filtered, ai_json_files, ai_map


