# ---- v84 final patch: status-in-session row, simplified AI workflow, light icon branding ----
APP_TITLE = "FaradaIQ Studio v273"


def _v84_widget_text(widget):
    try:
        return str(widget.cget("text"))
    except Exception:
        return ""


def _v84_walk_widgets(root):
    yield root
    try:
        for child in root.winfo_children():
            yield from _v84_walk_widgets(child)
    except Exception:
        pass


def _v84_hide_legacy_status_labels(root):
    """Move the main status label out of the middle/bottom strip and into the launch row."""
    try:
        status_var = getattr(root, "status_var", None)
        if status_var is None:
            return
        var_name = str(status_var)
        for w in list(_v84_walk_widgets(root)):
            if getattr(w, "_v84_keep_status_label", False):
                continue
            try:
                if str(w.cget("textvariable")) == var_name:
                    try:
                        w.pack_forget()
                    except Exception:
                        pass
                    try:
                        w.grid_remove()
                    except Exception:
                        pass
                    try:
                        w.place_forget()
                    except Exception:
                        pass
            except Exception:
                pass
    except Exception:
        pass


def _v84_build_session_banner_frame(parent, title, ctx):
    try:
        frame = ttk.Frame(parent, style="Card.TFrame", padding=(8, 4))
    except Exception:
        frame = ttk.Frame(parent, padding=(8, 4))
    try:
        frame.columnconfigure(1, weight=1)
        frame.columnconfigure(3, weight=1)
    except Exception:
        pass
    root = parent.winfo_toplevel()
    msg = f"{title}: {ctx.get('session_id')}"
    folder_text = f"Tracking folder only: {ctx.get('session_dir')}"
    try:
        ttk.Label(frame, text=msg, style="Section.TLabel").grid(row=0, column=0, sticky="w", padx=(0, 12))
        ttk.Label(frame, text=folder_text, style="Muted.TLabel").grid(row=0, column=1, sticky="ew", padx=(0, 10))
        if hasattr(root, "status_var"):
            ttk.Label(frame, text="Status:", style="Muted.TLabel").grid(row=0, column=2, sticky="e", padx=(4, 4))
            st = ttk.Label(frame, textvariable=root.status_var, style="Status.TLabel", width=42)
            st._v84_keep_status_label = True
            st.grid(row=0, column=3, sticky="ew", padx=(0, 8))
        else:
            frame.columnconfigure(3, weight=0)
        ttk.Button(frame, text="Open tracking folder", command=lambda c=ctx: _v753_open_session_folder(c)).grid(row=0, column=4, sticky="e", padx=(4, 0))
        ttk.Button(frame, text="Copy ID", command=lambda w=root, c=ctx: _v753_copy_session_id(w, c)).grid(row=0, column=5, sticky="e", padx=(4, 0))
    except Exception:
        ttk.Label(frame, text=msg).pack(side="left", padx=(0, 10))
        ttk.Label(frame, text=folder_text).pack(side="left", fill="x", expand=True)
        if hasattr(root, "status_var"):
            ttk.Label(frame, text="Status:").pack(side="left", padx=(8, 4))
            st = ttk.Label(frame, textvariable=root.status_var)
            st._v84_keep_status_label = True
            st.pack(side="left", fill="x", expand=True)
        ttk.Button(frame, text="Open tracking folder", command=lambda c=ctx: _v753_open_session_folder(c)).pack(side="right", padx=(5, 0))
        ttk.Button(frame, text="Copy ID", command=lambda w=root, c=ctx: _v753_copy_session_id(w, c)).pack(side="right", padx=(5, 0))
    try:
        _v84_hide_legacy_status_labels(root)
    except Exception:
        pass
    return frame


def _v753_add_session_banner(window, title="Launch session"):
    """v84: keep session tracking row above pySECCM runners and include live status on that same row."""
    try:
        root = window.winfo_toplevel()
    except Exception:
        root = window
    try:
        if getattr(root, "_v753_session_banner_added", False):
            try:
                _v84_hide_legacy_status_labels(root)
            except Exception:
                pass
            return
        ctx = _v753_launch_context()
        try:
            runner = _v83_find_widget_by_exact_text(root, "pySECCM / DRT runners")
        except Exception:
            runner = None
        if runner is not None:
            parent = runner.master
            frame = _v84_build_session_banner_frame(parent, title, ctx)
            try:
                frame.pack(fill="x", padx=0, pady=(4, 5), before=runner)
            except Exception:
                frame.pack(fill="x", padx=6, pady=(4, 5))
        else:
            frame = _v84_build_session_banner_frame(root, title, ctx)
            try:
                frame.pack(side="bottom", fill="x", padx=6, pady=(2, 4))
            except Exception:
                frame.pack(fill="x", padx=6, pady=(2, 4))
        root._v753_session_banner_added = True
        root._v753_session_banner_frame = frame
        try:
            _v80_reapply_fonts(frame)
        except Exception:
            pass
        try:
            root.after(200, lambda r=root: _v84_hide_legacy_status_labels(r))
            root.after(1200, lambda r=root: _v84_hide_legacy_status_labels(r))
        except Exception:
            pass
    except Exception:
        pass


def _v753_apply_title(window, base="FaradaIQ Studio v273"):
    try:
        base = str(base)
        for old in ("v75.5", "v76", "v77", "v78", "v79", "v80", "v81", "v82", "v83"):
            base = base.replace(old, "v84")
        ctx = _v753_launch_context()
        window.title(f"{base} — session {ctx.get('session_id')}")
    except Exception:
        pass


