def _v84_send_ai_bundle_to_edison(gui):
    try:
        mode = getattr(gui, "_v84_edison_send_mode_var", tk.StringVar(value="default bundle")).get()
    except Exception:
        mode = "default bundle"
    try:
        if "guided" in str(mode).lower():
            # Build/update the LLM-guided bundle first, then use the current built-bundle sender.
            try:
                _v66_llm_guided_bundle(gui)
            except Exception:
                pass
            try:
                gui.after(800, lambda g=gui: _v56_send_built_ai_bundle_to_edison_gui(g))
                return
            except Exception:
                pass
        if "_v56_send_built_ai_bundle_to_edison_gui" in globals():
            return _v56_send_built_ai_bundle_to_edison_gui(gui)
        return _v37_send_to_edison(gui)
    except Exception as exc:
        try:
            messagebox.showerror("Send AI bundle to Edison failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)
        except Exception:
            pass


def _v84_find_ai_workflow_row(gui):
    try:
        for w in list(_v84_walk_widgets(gui)):
            if _v84_widget_text(w) == "AI workflow":
                return w.master
    except Exception:
        pass
    return None


def _v84_configure_ai_workflow_toolbar(gui):
    """Replace the cluttered/duplicated AI row with grouped default-vs-LLM-guided actions."""
    try:
        row = _v84_find_ai_workflow_row(gui)
        if row is None:
            return
        if getattr(row, "_v84_ai_toolbar_ready", False):
            # Make sure late old buttons have not been re-added by older scheduled callbacks.
            texts = [_v84_widget_text(c) for c in row.winfo_children()]
            bad = {"Generate prompt", "Build AI bundle", "LLM-guided bundle", "AI prompt with context", "Run parsers + Edison", "Auto-send after parser run", "Send AI bundle to Edison"}
            if not any(t in bad for t in texts if t not in {"Send AI bundle to Edison"}):
                return
        for c in list(row.winfo_children()):
            try:
                c.destroy()
            except Exception:
                pass
        if not hasattr(gui, "append_parsed_structure_after_parser_var"):
            gui.append_parsed_structure_after_parser_var = tk.BooleanVar(value=True)
        if not hasattr(gui, "_v84_edison_send_mode_var"):
            gui._v84_edison_send_mode_var = tk.StringVar(value="default bundle")
        line1 = ttk.Frame(row, style="Card.TFrame")
        line1.pack(fill="x", pady=(0, 3))
        ttk.Label(line1, text="AI workflow", style="Muted.TLabel").pack(side="left", padx=(0, 8))
        ttk.Button(line1, text="LLM settings", command=lambda g=gui: _v37_show_llm_settings(g)).pack(side="left", padx=(0, 5))
        ttk.Button(line1, text="Append default AI prompt", command=gui.append_ai_prompt).pack(side="left", padx=(0, 5))
        ttk.Button(line1, text="Generate LLM-guided prompt", command=lambda g=gui: _v45_generate_ai_prompt_with_llm(g)).pack(side="left", padx=(0, 5))
        ttk.Button(line1, text="Build default AI bundle", command=lambda g=gui: _v84_default_bundle(g), style="Accent.TButton").pack(side="left", padx=(0, 5))
        ttk.Button(line1, text="Build LLM-guided AI bundle", command=lambda g=gui: _v84_guided_bundle(g)).pack(side="left", padx=(0, 5))
        line2 = ttk.Frame(row, style="Card.TFrame")
        line2.pack(fill="x")
        ttk.Checkbutton(line2, text="Append parsed structure", variable=gui.append_parsed_structure_after_parser_var).pack(side="left", padx=(0, 8))
        ttk.Button(line2, text="Refresh structure", command=lambda g=gui: _v50_update_structure_preview_with_parsed_outputs(g, force=True)).pack(side="left", padx=(0, 5))
        ttk.Button(line2, text="Edison settings", command=lambda g=gui: _v58_show_edison_settings(g)).pack(side="left", padx=(0, 12))
        ttk.Label(line2, text="Send", style="Muted.TLabel").pack(side="left", padx=(0, 5))
        try:
            send_box = ttk.Combobox(line2, textvariable=gui._v84_edison_send_mode_var, values=["default bundle", "LLM-guided bundle"], state="readonly", width=18)
            send_box.pack(side="left", padx=(0, 5))
        except Exception:
            ttk.OptionMenu(line2, gui._v84_edison_send_mode_var, gui._v84_edison_send_mode_var.get(), "default bundle", "LLM-guided bundle").pack(side="left", padx=(0, 5))
        ttk.Button(line2, text="Send AI bundle to Edison", command=lambda g=gui: _v84_send_ai_bundle_to_edison(g)).pack(side="left", padx=(0, 5))
        row._v84_ai_toolbar_ready = True
        try:
            _v80_reapply_fonts(row)
            _v66_apply_tooltips(row)
        except Exception:
            pass
    except Exception:
        pass


