def _v89_send_ai_bundle_to_edison(gui):
    try:
        mode_var = getattr(gui, '_v89_edison_send_mode_var', None) or getattr(gui, '_v84_edison_send_mode_var', None)
        mode = str(mode_var.get() if mode_var is not None else 'default bundle').lower()
        try:
            if 'guided' in mode:
                _v89_build_guided_bundle(gui)
            else:
                _v89_build_default_bundle(gui)
        except Exception:
            # Continue to sender if an existing built bundle is present.
            pass
        if '_v56_send_built_ai_bundle_to_edison_gui' in globals():
            try:
                gui.after(500, lambda g=gui: _v56_send_built_ai_bundle_to_edison_gui(g))
                return
            except Exception:
                return _v56_send_built_ai_bundle_to_edison_gui(gui)
        if '_v37_send_to_edison' in globals():
            return _v37_send_to_edison(gui)
    except Exception as exc:
        try:
            messagebox.showerror("Send AI bundle to Edison failed", f"{exc}\n\n{traceback.format_exc()}", parent=gui)
        except Exception:
            pass


def _v89_configure_ai_workflow_toolbar(gui):
    """Build exactly one clean AI/Edison toolbar and prevent legacy callbacks from stacking rows."""
    try:
        row = _v89_find_ai_toolbar_root(gui)
        if row is None:
            return
        # Destroy the whole content of the actual AI workflow row, including any repeated Edison rows.
        for c in list(row.winfo_children()):
            try:
                c.destroy()
            except Exception:
                pass
        if not hasattr(gui, 'append_parsed_structure_after_parser_var'):
            gui.append_parsed_structure_after_parser_var = tk.BooleanVar(value=True)
        if not hasattr(gui, '_v89_edison_send_mode_var'):
            # Preserve v84 value when available.
            try:
                val = getattr(gui, '_v84_edison_send_mode_var').get()
            except Exception:
                val = 'default bundle'
            gui._v89_edison_send_mode_var = tk.StringVar(value=val)
        try:
            gui._v84_edison_send_mode_var = gui._v89_edison_send_mode_var
        except Exception:
            pass

        outer = ttk.Frame(row, style='Card.TFrame')
        outer._v89_ai_toolbar_container = True
        outer.pack(fill='x', pady=(0, 2))

        line1 = ttk.Frame(outer, style='Card.TFrame')
        line1.pack(fill='x', pady=(0, 3))
        ttk.Label(line1, text='AI workflow', style='Muted.TLabel').pack(side='left', padx=(0, 8))
        ttk.Button(line1, text='LLM settings', command=lambda g=gui: _v37_show_llm_settings(g)).pack(side='left', padx=(0, 5))
        ttk.Button(line1, text='Append default AI prompt', command=lambda g=gui: _v89_append_default_prompt(g)).pack(side='left', padx=(0, 5))
        ttk.Button(line1, text='Generate LLM-guided prompt', command=lambda g=gui: _v89_generate_llm_prompt(g)).pack(side='left', padx=(0, 5))
        ttk.Button(line1, text='Build default AI bundle', command=lambda g=gui: _v89_build_default_bundle(g), style='Accent.TButton').pack(side='left', padx=(0, 5))
        ttk.Button(line1, text='Build LLM-guided AI bundle', command=lambda g=gui: _v89_build_guided_bundle(g)).pack(side='left', padx=(0, 5))

        line2 = ttk.Frame(outer, style='Card.TFrame')
        line2.pack(fill='x')
        ttk.Checkbutton(line2, text='Append parsed structure', variable=gui.append_parsed_structure_after_parser_var).pack(side='left', padx=(0, 8))
        ttk.Button(line2, text='Refresh structure', command=lambda g=gui: _v89_refresh_structure(g)).pack(side='left', padx=(0, 5))
        ttk.Button(line2, text='Edison settings', command=lambda g=gui: _v58_show_edison_settings(g)).pack(side='left', padx=(0, 12))
        ttk.Label(line2, text='Send', style='Muted.TLabel').pack(side='left', padx=(0, 5))
        try:
            send_box = ttk.Combobox(line2, textvariable=gui._v89_edison_send_mode_var, values=['default bundle', 'LLM-guided bundle'], state='readonly', width=18)
            send_box.pack(side='left', padx=(0, 5))
        except Exception:
            ttk.OptionMenu(line2, gui._v89_edison_send_mode_var, gui._v89_edison_send_mode_var.get(), 'default bundle', 'LLM-guided bundle').pack(side='left', padx=(0, 5))
        ttk.Button(line2, text='Send AI bundle to Edison', command=lambda g=gui: _v89_send_ai_bundle_to_edison(g)).pack(side='left', padx=(0, 5))

        row._v84_ai_toolbar_ready = True
        row._v89_ai_toolbar_ready = True
        try:
            _v89_purge_orphan_ai_rows(gui, row)
        except Exception:
            pass
        try:
            _v80_reapply_fonts(row)
            if '_v66_apply_tooltips' in globals():
                _v66_apply_tooltips(row)
        except Exception:
            pass
        try:
            if hasattr(gui, 'set_status'):
                gui.set_status('v89: clean AI workflow toolbar ready; Edison send has default/LLM-guided bundle selector.')
        except Exception:
            pass
    except Exception:
        pass


