APP_TITLE = "FaradaIQ Studio v273"


def _v89_abbreviate_path(path_text, max_chars=92):
    """Show first and last path segments so long launch folders do not truncate in the GUI."""
    try:
        s = str(path_text or "")
        if len(s) <= max_chars:
            return s
        normalized = s.replace("/", "\\")
        parts = [p for p in normalized.split("\\") if p]
        prefix = ""
        if parts and parts[0].endswith(":"):
            prefix = parts[0] + "\\"
            parts = parts[1:]
        if len(parts) <= 5:
            return s[: max_chars//2 - 2] + " ... " + s[-max_chars//2:]
        # Keep useful user/root context plus the actual session folder at the end.
        head = parts[:2]
        tail = parts[-3:]
        out = prefix + "\\".join(head + ["..."] + tail)
        if len(out) > max_chars:
            out = prefix + "\\".join(head[:1] + ["..."] + tail[-2:])
        return out
    except Exception:
        try:
            s = str(path_text or "")
            return s if len(s) <= max_chars else s[:40] + " ... " + s[-45:]
        except Exception:
            return ""


