# ---- v89 final patch: duplicate-curve removal, richer CV labels, PySimpleEChem manifest metadata ----
APP_TITLE = "FaradaIQ Studio v273"

import hashlib as _v89_hashlib


def _v89_norm_path(p):
    try:
        pp = Path(p)
        return str(pp.resolve()).lower() if pp.exists() else str(pp).lower()
    except Exception:
        return str(p).lower()


def _v89_record_for_path(browser, path):
    key = _v89_norm_path(path)
    try:
        for r in list(getattr(browser, '_v80_records', []) or []):
            try:
                if _v89_norm_path(r.get('path')) == key:
                    return r
            except Exception:
                pass
    except Exception:
        pass
    try:
        for recs in list(getattr(browser, '_records_by_iid', {}) .values()):
            for r in list(recs or []):
                try:
                    if _v89_norm_path(r.get('path')) == key:
                        return r
                except Exception:
                    pass
    except Exception:
        pass
    return {'path': str(path), 'meta': {}}


def _v89_cv_info_for_path(browser, path):
    rec = _v89_record_for_path(browser, path)
    ctx = getattr(browser, '_v83_experiment_context', {}) or {}
    info = None
    try:
        info = rec.get('_v83_cv_info') or _v83_cv_sequence_info(rec, ctx)
    except Exception:
        info = None
    if not isinstance(info, dict):
        info = {}
    txt = str(path)
    # Fill missing scan / cycle from filename or parser metadata.
    try:
        if not info.get('scan'):
            scan = _v80_scan_label(rec) if '_v80_scan_label' in globals() else ''
            if not scan and '_v754_parse_scan_rate_label' in globals():
                scan = _v754_parse_scan_rate_label(txt)
            if scan:
                info['scan'] = scan
    except Exception:
        pass
    try:
        if not info.get('cycle_idx'):
            c = _v89_record_cycle_idx(rec) if '_v89_record_cycle_idx' in globals() else None
            if c:
                info['cycle_idx'] = c
            else:
                m = re.search(r'(?:^|[_\-\s])c0*([0-9]+)(?=$|[_\-\s])', txt, flags=re.I)
                if m:
                    info['cycle_idx'] = int(m.group(1))
    except Exception:
        pass
    try:
        if not info.get('point_idx'):
            ptxt = _v80_point_label(rec) if '_v80_point_label' in globals() else ''
            m = re.search(r'(?:point|position|pos)[_\-\s]*0*([0-9]+)', str(ptxt) + ' ' + txt, flags=re.I)
            if m and not re.search(r'\b\d+\s*points?\b', str(ptxt), flags=re.I):
                info['point_idx'] = int(m.group(1))
    except Exception:
        pass
    try:
        mnum = _v83_record_m_number(rec) if '_v83_record_m_number' in globals() else 0
        if mnum:
            info['mnum'] = mnum
    except Exception:
        pass
    return info


def _v89_display_label_for_path(browser, path, xcol=None, ycol=None, for_manifest=False):
    p = Path(path)
    stem = p.stem
    info = _v89_cv_info_for_path(browser, path)
    parts = []
    try:
        if info.get('point_idx'):
            parts.append(f"P{int(info.get('point_idx')):02d}")
    except Exception:
        pass
    scan = info.get('scan') or info.get('label') or ''
    if scan:
        parts.append(str(scan).replace('mVperS', 'mV/s'))
    try:
        if info.get('cycle_idx'):
            parts.append(f"C{int(info.get('cycle_idx'))}")
    except Exception:
        pass
    try:
        if info.get('mnum'):
            parts.append(f"m{int(info.get('mnum')):03d}")
    except Exception:
        pass
    if for_manifest:
        # Keep the actual file name visible in PySimpleEChem and exported result tables.
        return (" | ".join(parts) + " — " if parts else "") + p.name
    label = " | ".join(parts) if parts else _v64_curve_label(path, xcol=xcol, ycol=ycol)
    # Avoid extremely long legends but still keep the identifying suffix.
    if len(label) > 85:
        label = label[:40] + '…' + label[-40:]
    return label


def _v89_curve_signature_from_xy(x, y, xcol=None, ycol=None):
    try:
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        mask = np.isfinite(x) & np.isfinite(y)
        x = x[mask]; y = y[mask]
        if len(x) < 2 or len(y) < 2:
            return None
        # Rounded numeric signature: exact duplicates remain identical, tiny CSV formatting noise is tolerated.
        arr = np.column_stack([np.round(x, 12), np.round(y, 18)]).astype(np.float64, copy=False)
        h = _v89_hashlib.sha256(arr.tobytes()).hexdigest()
        return (len(x), str(xcol), str(ycol), h)
    except Exception:
        return None


def _v89_curve_signature_for_path(browser, path):
    try:
        df = _v64_read_table_file(path)
        mode = _v89_var_get(browser, 'plot_mode_var', 'Auto')
        x_choice = _v89_var_get(browser, 'x_axis_var', '')
        y_choice = _v89_var_get(browser, 'y_axis_var', '')
        x, y, xcol, ycol, detected = _v70_extract_xy(df, mode, x_choice=x_choice, y_choice=y_choice)
        return _v89_curve_signature_from_xy(x, y, xcol, ycol)
    except Exception:
        return None


def _v89_remove_duplicates_enabled(browser):
    try:
        return bool(browser.remove_duplicate_curves_var.get())
    except Exception:
        return True


def _v89_var_get(obj, attr, default=''):
    try:
        var = getattr(obj, attr, None)
        if var is None:
            return default
        return var.get()
    except Exception:
        return default


def _v89_deduplicate_paths_for_plot(browser, paths, force=None):
    paths = [Path(p) for p in list(paths or [])]
    enabled = _v89_remove_duplicates_enabled(browser) if force is None else bool(force)
    if not enabled or len(paths) < 2:
        try:
            browser._v89_last_duplicate_report = {'enabled': enabled, 'kept': [str(p) for p in paths], 'removed': []}
        except Exception:
            pass
        return paths
    kept, removed, seen = [], [], {}
    for p in paths:
        sig = _v89_curve_signature_for_path(browser, p)
        if sig is not None and sig in seen:
            removed.append({'path': str(p), 'duplicate_of': str(seen[sig]), 'label': _v89_display_label_for_path(browser, p, for_manifest=True)})
            continue
        if sig is not None:
            seen[sig] = p
        kept.append(p)
    try:
        browser._v89_last_duplicate_report = {'enabled': enabled, 'kept': [str(p) for p in kept], 'removed': removed}
        if removed:
            browser.log(f"Removed {len(removed)} exact duplicate curve(s) before plotting / PySimpleEChem handoff.")
            for r in removed[:20]:
                browser.log(f"  duplicate skipped: {Path(r['path']).name}  (same as {Path(r['duplicate_of']).name})")
            if len(removed) > 20:
                browser.log(f"  ... {len(removed)-20} more duplicate(s) skipped")
    except Exception:
        pass
    return kept


def _v89_add_duplicate_control(browser):
    try:
        if not hasattr(browser, 'remove_duplicate_curves_var'):
            browser.remove_duplicate_curves_var = tk.BooleanVar(value=True)
        if getattr(browser, '_v89_duplicate_control_added', False):
            return
        target = None
        for w in list(_v89_walk_widgets(browser) if '_v89_walk_widgets' in globals() else _v84_walk_widgets(browser)):
            try:
                txt = str(w.cget('text'))
                if txt.startswith('Plot / overlay'):
                    target = w
                    break
            except Exception:
                pass
        if target is not None:
            parent = target.master
            cb = ttk.Checkbutton(parent, text='Remove exact duplicates', variable=browser.remove_duplicate_curves_var)
            try:
                cb.pack(side='left', padx=(4, 4), after=target)
            except Exception:
                cb.pack(side='left', padx=(4, 4))
            try:
                _v66_add_tooltip(cb, 'When checked, FaradaIQ compares extracted X/Y arrays and keeps only one exact duplicate curve before plotting or sending to PySimpleEChem.')
            except Exception:
                pass
            browser._v89_duplicate_control_added = True
    except Exception as exc:
        try: browser.log(f'Could not add duplicate-removal checkbox: {exc}')
        except Exception: pass


def _v89_plot_or_overlay_selected(browser):
    try:
        all_paths = browser.selected_paths(plottable_only=True)
    except Exception:
        all_paths = []
    if not all_paths:
        try:
            messagebox.showinfo('No data selected', 'Select a sample/condition/point/technique group in the experiment map, then click Plot / overlay selected.', parent=browser)
        except Exception:
            pass
        return
    dedup_paths = _v89_deduplicate_paths_for_plot(browser, all_paths)
    try:
        paths = _v78_limit_plot_paths(browser, dedup_paths)
    except Exception:
        paths = dedup_paths
    try:
        browser.clear_plot()
    except Exception:
        pass
    try:
        browser.last_plot_paths = []
        browser._v89_seen_plot_signatures = set()
    except Exception:
        pass
    media = _v70_media_paths(paths)
    tables = _v70_table_paths(paths)
    if tables:
        for p in tables:
            try:
                browser._plot_file(p, clear=False)
            except Exception as exc:
                try: browser.log(f'Plot failed for {Path(p).name}: {exc}')
                except Exception: pass
        try: browser._finish_plot_axes()
        except Exception: pass
        try: _v74_hide_show_media_buttons(browser, False)
        except Exception: pass
    if media:
        try:
            _v70_display_media_paths(browser, media, 0)
            _v74_hide_show_media_buttons(browser, len(media) > 1)
        except Exception:
            pass
    try: _v752_reset_plot_geometry(browser)
    except Exception: pass
    try:
        kind = _v78_kind_from_paths(paths)
    except Exception:
        kind = _v75_kind_from_paths(paths)
    removed = len((getattr(browser, '_v89_last_duplicate_report', {}) or {}).get('removed', []))
    try:
        msg = f'{kind} | plotted: {len(paths)} of {len(all_paths)} selected file(s)'
        if removed:
            msg += f' | exact duplicates removed: {removed}'
        browser.current_technique_var.set(msg)
        if hasattr(browser, 'status_var'):
            browser.status_var.set(msg)
    except Exception:
        pass
    try:
        _v757_update_analysis_schema(browser, kind)
    except Exception:
        try: _v74_update_analysis_schema(browser, kind)
        except Exception: pass
    try:
        _v757_store_current_view(browser, paths, kind)
    except Exception:
        try: _v74_store_current_view(browser, paths, kind)
        except Exception: pass


def _v89_plot_file(self, path, clear=False):
    if self.ax is None:
        return
    df = _v64_read_table_file(path)
    mode = _v89_var_get(self, 'plot_mode_var', 'Auto')
    x_choice = _v89_var_get(self, 'x_axis_var', '')
    y_choice = _v89_var_get(self, 'y_axis_var', '')
    x, y, xcol, ycol, detected = _v70_extract_xy(df, mode, x_choice=x_choice, y_choice=y_choice)
    mask = np.isfinite(x) & np.isfinite(y)
    x = np.asarray(x, dtype=float)[mask]
    y = np.asarray(y, dtype=float)[mask]
    if len(x) < 2:
        self.log(f'Could not plot {Path(path).name}: {detected}')
        return
    if clear:
        self.clear_plot()
        self._v89_seen_plot_signatures = set()
    try:
        raw_sig = _v89_curve_signature_from_xy(x, y, xcol, ycol)
        if _v89_remove_duplicates_enabled(self):
            seen = getattr(self, '_v89_seen_plot_signatures', set())
            if raw_sig is not None and raw_sig in seen:
                self.log(f'Skipped duplicate curve during plotting: {Path(path).name}')
                return
            if raw_sig is not None:
                seen.add(raw_sig)
                self._v89_seen_plot_signatures = seen
    except Exception:
        pass
    y = self._apply_normalization(y, x)
    full_label = _v89_display_label_for_path(self, path, xcol=xcol, ycol=ycol)
    display_label = _v89_label_for_legend(full_label, _v89_get_legend_mode(self)) if '_v89_label_for_legend' in globals() else full_label
    self.ax.plot(x, y, marker='o' if len(x) <= 200 else None, linewidth=1.6, markersize=3, label=display_label)
    self.ax.set_xlabel(str(xcol)); self.ax.set_ylabel(str(ycol)); self.ax.set_title(str(mode) + ' overlay')
    try:
        if 'bode' in str(mode).lower() and np.nanmin(x) > 0:
            self.ax.set_xscale('log')
            if ('magnitude' in str(mode).lower() or '|z|' in str(mode).lower()) and np.nanmin(y) > 0:
                self.ax.set_yscale('log')
    except Exception:
        pass
    self.last_plot_paths.append(Path(path))
    self.curves.append({'path': Path(path), 'x': x, 'y': y, 'xcol': xcol, 'ycol': ycol, 'label': full_label, 'display_label': display_label})
    self._finish_plot_axes()
    self.log(f'Plotted {Path(path).name}: {detected} | label: {full_label}')


def _v89_store_manifest_entries(browser, paths):
    entries = []
    for p in paths:
        p = Path(p)
        info = _v89_cv_info_for_path(browser, p)
        entry = {
            'path': str(p),
            'file': str(p),
            'display_name': _v89_display_label_for_path(browser, p, for_manifest=True),
            'source_file_name': p.name,
        }
        for k in ('point_idx', 'scan', 'label', 'cycle_idx', 'method_idx', 'mnum', 'cycles'):
            if info.get(k) not in (None, ''):
                entry[k] = info.get(k)
        # Numeric scan rate for PySimpleEChem if possible.
        try:
            scan_txt = str(entry.get('scan') or entry.get('label') or '')
            m = re.search(r'([0-9.]+)\s*mV\s*/?\s*s', scan_txt, flags=re.I)
            if m:
                entry['scan_rate_V_s'] = float(m.group(1)) / 1000.0
            else:
                m = re.search(r'([0-9.]+)\s*V\s*/?\s*s', scan_txt, flags=re.I)
                if m:
                    entry['scan_rate_V_s'] = float(m.group(1))
        except Exception:
            pass
        entries.append(entry)
    return entries


