def _v89_write_pysimpleechem_selected_manifest(browser, paths):
    try:
        outdir = browser.analyzed_root / 'pysimpleechem_cv_results'
    except Exception:
        root = Path(getattr(browser, 'analysis_root', Path.cwd()))
        outdir = root / f'{_v35_safe_name(getattr(browser, "base_name", root.name))}_FaradaIQ_analyzed_data' / 'pysimpleechem_cv_results'
    outdir.mkdir(parents=True, exist_ok=True)
    mf = outdir / f'faradaiq_selected_cv_files_{datetime.now().strftime("%Y%m%d_%H%M%S")}.json'
    try:
        sel_name = ''
        sel = browser.plot_view_list.curselection()
        if sel:
            sel_name = browser.plot_view_list.get(sel[0])
    except Exception:
        sel_name = ''
    report = getattr(browser, '_v89_last_duplicate_report', {}) or {}
    entries = _v89_store_manifest_entries(browser, paths)
    payload = {
        'created': datetime.now().isoformat(timespec='seconds'),
        'source': 'FaradaIQ Studio v273 Plot/view list selection',
        'plot_view_name': sel_name,
        'duplicate_removal_enabled': _v89_remove_duplicates_enabled(browser),
        'removed_duplicates': report.get('removed', []),
        'files': entries,
        'paths': [str(Path(p)) for p in paths],
    }
    mf.write_text(json.dumps(payload, indent=2, default=str), encoding='utf-8')
    return mf


def _v89_open_native_pysimpleechem_with_selected(browser=None):
    try:
        app_dir = Path(__file__).resolve().parent
        pse = app_dir / 'integrated_tools' / 'PySimpleEChem' / 'PySimpleEChem.py'
        if not pse.exists():
            messagebox.showerror('PySimpleEChem missing', f'Could not find: {pse}', parent=browser)
            return
        paths = _v89_selected_cv_paths(browser) if browser is not None else []
        if not paths:
            messagebox.showinfo('No CV plot/view selected', 'Select a CV plot/view from the Plot/view list first, then open PySimpleEChem.', parent=browser)
            return
        mf = _v89_write_pysimpleechem_selected_manifest(browser, paths)
        env = _v227_theme_environment(browser) if '_v227_theme_environment' in globals() else os.environ.copy()
        env['FARADAIQ_PYSIMPLEECHEM_CV_MANIFEST'] = str(mf)
        _v757_subprocess.Popen([_v757_sys.executable, str(pse), '--faradaiq-cv-manifest', str(mf)], cwd=str(pse.parent), env=env)
        if browser is not None:
            removed = len((getattr(browser, '_v89_last_duplicate_report', {}) or {}).get('removed', []))
            msg = f'Launched PySimpleEChem with {len(paths)} deduplicated selected CV file(s): {mf}'
            if removed:
                msg += f' | duplicates removed: {removed}'
            browser.log(msg)
            try: browser.status_var.set(msg)
            except Exception: pass
    except Exception as exc:
        try: messagebox.showerror('Could not launch PySimpleEChem with selected CV files', str(exc), parent=browser)
        except Exception: pass
        try: browser.log(f'Could not launch PySimpleEChem with selected CV files: {exc}')
        except Exception: pass


