# ---- v89 final stability patch: non-recursive data-browser build/reset and QA guard ----
APP_TITLE = "FaradaIQ Studio v273"

# The v88 patch accidentally chained multiple browser _build_ui wrappers through the same
# global sentinel name. That made an older wrapper call itself recursively. v89 deliberately
# bypasses those wrappers and starts from the last known safe pre-v86/pre-v89 build target.
def _v89_safe_pre_browser_build_ui():
    for name in ("_V86_PREV_BROWSER_BUILD_UI", "_V84_PREV_BROWSER_BUILD_UI", "_V83_PREV_BROWSER_BUILD_UI"):
        fn = globals().get(name)
        if callable(fn):
            return fn
    # Fall back to the original class method definition if available by name; these functions
    # use distinct sentinel names and do not recurse through the v89/v88 sentinel.
    for name in ("_v84_browser_build_ui", "_v83_browser_build_ui_final", "_v83_browser_build_ui", "_v80_browser_build_ui", "_v78_browser_build_ui", "_v75_browser_build_ui"):
        fn = globals().get(name)
        if callable(fn):
            return fn
    return None


def _v89_browser_reset_stable(browser):
    """Full non-recursive reset used by the Data Browser Reset button and aliases."""
    try:
        browser.clear_plot()
    except Exception:
        pass
    for attr, val in [
        ('plot_mode_var','Auto'), ('normalize_var','None'), ('x_axis_var',''), ('y_axis_var',''),
        ('max_curves_var','12'), ('legend_mode_var','Short'), ('cv_cycle_filter_var','All cycles')
    ]:
        try:
            getattr(browser, attr).set(val)
        except Exception:
            pass
    for attr in ('invert_y_var','logx_var','logy_var','ai_npy_only_var'):
        try:
            getattr(browser, attr).set(False)
        except Exception:
            pass
    try:
        if hasattr(browser, 'remove_duplicate_curves_var'):
            browser.remove_duplicate_curves_var.set(True)
    except Exception:
        pass
    try:
        browser.comp_list.delete(0, 'end')
        browser.suggestions = []
    except Exception:
        pass
    try:
        browser.plot_view_list.delete(0, 'end')
        browser._v69_plot_views = []
    except Exception:
        pass
    try:
        browser.results_tree.delete(*browser.results_tree.get_children())
    except Exception:
        pass
    try:
        browser.tree.selection_remove(browser.tree.selection())
    except Exception:
        pass
    try:
        _v75_hide_show_media_buttons(browser, False)
    except Exception:
        pass
    try:
        browser._v89_seen_plot_signatures = set()
        browser._v89_last_duplicate_report = {'enabled': True, 'kept': [], 'removed': []}
    except Exception:
        try:
            browser._v88_seen_plot_signatures = set()
            browser._v88_last_duplicate_report = {'enabled': True, 'kept': [], 'removed': []}
        except Exception:
            pass
    try:
        browser.current_technique_var.set('No data selected')
    except Exception:
        pass
    try:
        browser.analysis_progress.configure(value=0)
    except Exception:
        pass
    try:
        browser.analysis_progress_var.set('Analysis idle')
    except Exception:
        pass
    try:
        browser.status_var.set('Browser reset: plot, Plot/view list, results, selections, cycle filter, legend controls, axes, duplicate state, and analysis state cleared.')
    except Exception:
        pass
    try:
        _v83_update_analysis_schema(browser, 'General')
    except Exception:
        pass
    try:
        _v75_save_session(browser, silent=True)
    except Exception:
        pass
    try:
        browser.log('Full browser reset completed without recursive reset wrapper.')
    except Exception:
        pass


def _v89_browser_build_ui_stable(self):
    base = _v89_safe_pre_browser_build_ui()
    if callable(base):
        base(self)
    else:
        # Last-resort minimal error-safe UI should not happen in packaged builds.
        try:
            ttk.Label(self, text='FaradaIQ Data Browser').pack(anchor='w', padx=8, pady=8)
        except Exception:
            pass
    try:
        _v83_set_window_icon(self)
    except Exception:
        pass
    try:
        self.title('FaradaIQ Studio v273 — experiment map + deduplicated CV/PySimpleEChem')
        if '_v753_apply_title' in globals():
            _v753_apply_title(self, 'FaradaIQ Studio v273 — experiment map + PySimpleEChem CV')
    except Exception:
        pass
    try:
        # Add v89/v88 duplicate-control UI after the safe base UI has created the toolbar.
        add_dup = globals().get('_v89_add_duplicate_control') or globals().get('_v88_add_duplicate_control')
        if callable(add_dup):
            add_dup(self)
        if not hasattr(self, 'remove_duplicate_curves_var'):
            self.remove_duplicate_curves_var = tk.BooleanVar(value=True)
    except Exception:
        pass
    try:
        if hasattr(self, 'status_var'):
            self.status_var.set('v89: Data Browser recursion fixed; exact duplicate curves can be removed before plotting and before PySimpleEChem handoff.')
    except Exception:
        pass
    try:
        for delay in (250, 700, 1600, 3200):
            self.after(delay, lambda b=self: (
                (globals().get('_v89_add_duplicate_control') or globals().get('_v88_add_duplicate_control'))(b) if callable(globals().get('_v89_add_duplicate_control') or globals().get('_v88_add_duplicate_control')) else None,
                _v80_reapply_fonts(b) if '_v80_reapply_fonts' in globals() else None,
                _v83_set_window_icon(b) if '_v83_set_window_icon' in globals() else None
            ))
    except Exception:
        pass


