# ---- v90 patch: sample-scoped output folder, nonblocking loaders, generalized experiment map, parser ETA, PySimpleEChem nonblocking handoff ----
APP_TITLE = "FaradaIQ Studio v273"


def _v90_safe_base_name(gui=None, base_name=None):
    try:
        return _v35_safe_name(base_name or _v27_current_base_name(gui))
    except Exception:
        return _v35_safe_name(base_name or 'sample')


def _v90_user_output_root(gui):
    try:
        return Path(str(gui.output_dir_var.get() or '.').strip()).resolve()
    except Exception:
        return Path.cwd().resolve()


def _v90_sample_output_dir(gui, base_name=None, create=True):
    """Return the per-sample output directory inside the user-selected output folder."""
    out = _v90_user_output_root(gui)
    safe = _v90_safe_base_name(gui, base_name)
    # If the user already chose the sample folder, do not nest again.
    if out.name.lower() == safe.lower():
        sample_out = out
    elif out.name.lower() in {f'{safe.lower()}_output', f'{safe.lower()}_faradaiq_output'}:
        sample_out = out
    else:
        sample_out = out / safe
    if create:
        try:
            sample_out.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
    return sample_out.resolve()


# Make all analysis-root finding routines aware of the per-sample output folder.
