def _v35_analysis_root_for_export(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    out = _v90_user_output_root(gui)
    safe = _v35_safe_name(base_name)
    sample_out = _v90_sample_output_dir(gui, base_name=base_name, create=False)
    candidates = [
        sample_out / f"{base_name}_analysis_ready_csv",
        sample_out / f"{safe}_analysis_ready_csv",
        out / safe / f"{base_name}_analysis_ready_csv",
        out / safe / f"{safe}_analysis_ready_csv",
        out / f"{base_name}_analysis_ready_csv",       # legacy, before v90
        out / f"{safe}_analysis_ready_csv",            # legacy, before v90
    ]
    for p in candidates:
        try:
            if p.exists() and p.is_dir():
                return p.resolve()
        except Exception:
            pass
    # During export, if nothing exists yet, return the sample-scoped output folder.
    return sample_out if sample_out.exists() else out


