def _v27_candidate_plotting_data_dirs(gui, base_name=None):
    base_name = base_name or _v27_current_base_name(gui)
    out = _v90_user_output_root(gui)
    safe = _v35_safe_name(base_name)
    sample_out = _v90_sample_output_dir(gui, base_name=base_name, create=False)
    roots = [
        sample_out / f"{base_name}_analysis_ready_csv",
        sample_out / f"{safe}_analysis_ready_csv",
        sample_out,
        out / safe / f"{base_name}_analysis_ready_csv",
        out / safe / f"{safe}_analysis_ready_csv",
        out / safe,
        out / f"{base_name}_analysis_ready_csv",
        out / f"{safe}_analysis_ready_csv",
        out,
    ]
    dirs, seen = [], set()
    for root in roots:
        try:
            if not root.exists() or not root.is_dir():
                continue
            candidates = []
            candidates.extend([p for p in root.rglob('data') if p.is_dir() and p.parent.name.endswith('_for_plotting_analysis')])
            candidates.extend([p for p in root.rglob('data_generated_from_HEKA') if p.is_dir()])
            candidates.extend([p for p in root.rglob('DRT_input_csv') if p.is_dir()])
            for c in candidates:
                key = str(c.resolve())
                if key not in seen:
                    seen.add(key); dirs.append(c)
        except Exception:
            pass
    good = []
    for d in dirs:
        try:
            detected = _v19_detect_pyseccm_files(d)
            if any(detected.get(k) for k in ['cv','eis','iv','corr','ocp','avg_ocp','pos','drt_dir']):
                good.append(d)
        except Exception:
            good.append(d)
    return good or dirs


# Wrap export so a single selected OUT folder can safely hold many sample folders.
