def _v90_browser_loading_refresh_noop(self):
    try:
        if hasattr(self, 'tree'):
            self.tree.delete(*self.tree.get_children())
            self.tree.insert('', 'end', text='Loading experiment map...', values=('Loading', ''), open=True)
        if hasattr(self, 'status_var'):
            self.status_var.set('Loading files and building experiment map...')
        self.update_idletasks()
    except Exception:
        pass


def _v90_finish_browser_initial_load(browser):
    try:
        browser.status_var.set('Loading experiment map: reading manifests and indexing plottable files...')
        browser.update_idletasks()
    except Exception: pass
    try:
        _v90_refresh_tree(browser)
    except Exception as exc:
        try:
            browser.log(f'Data Browser load failed: {exc}')
            messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=browser)
        except Exception: pass


def _v90_browser_init(self, gui, analysis_root=None, base_name=None):
    old_refresh = getattr(FaradaIQDataBrowser, 'refresh_tree', None)
    try:
        FaradaIQDataBrowser.refresh_tree = _v90_browser_loading_refresh_noop
        _V90_PREV_BROWSER_INIT(self, gui, analysis_root=analysis_root, base_name=base_name)
    finally:
        try:
            FaradaIQDataBrowser.refresh_tree = _v90_refresh_tree
        except Exception:
            if old_refresh: FaradaIQDataBrowser.refresh_tree = old_refresh
    try:
        self.title('FaradaIQ Studio v273 — loading experiment map')
        _v753_apply_title(self, 'FaradaIQ Studio v273 — experiment map + PySimpleEChem CV')
    except Exception: pass
    try:
        self.after(60, lambda b=self: _v90_finish_browser_initial_load(b))
    except Exception:
        try: _v90_finish_browser_initial_load(self)
        except Exception: pass

if _V90_PREV_BROWSER_INIT is not None:
    FaradaIQDataBrowser.__init__ = _v90_browser_init
FaradaIQDataBrowser.refresh_tree = _v90_refresh_tree
FaradaIQDataBrowser.selected_paths = _v89_selected_paths


# Parser progress ETA: observed command speed + heuristic weights for DRT-heavy steps.
def _v90_eta_text(elapsed, cur, tot, detail=''):
    try:
        cur = int(cur); tot = max(1, int(tot)); elapsed = max(0.1, float(elapsed))
        remaining_cmds = max(0, tot - cur)
        avg = elapsed / max(cur, 0.35)
        d = str(detail).lower()
        weight = 1.0
        if 'drt' in d or 'pydrt' in d:
            weight = 3.0
        elif 'eis' in d:
            weight = 1.4
        elif 'cv' in d:
            weight = 1.0
        elif 'ocp' in d or 'iv' in d or 'tafel' in d:
            weight = 0.8
        rem = avg * remaining_cmds * weight
        if rem < 60:
            return f'ETA ~{int(rem)} s'
        if rem < 3600:
            return f'ETA ~{int(rem//60)} min {int(rem%60)} s'
        return f'ETA ~{rem/3600:.1f} h'
    except Exception:
        return 'ETA estimating...'


def _v67_start_pyseccm_monitor(gui, progress_file, total):
    try:
        progress_file = Path(progress_file)
        _v67_add_pyseccm_status_bar(gui)
        start = time.time()
        if hasattr(gui, '_faradaiq_pyseccm_progress'):
            gui._faradaiq_pyseccm_progress.configure(maximum=max(1, int(total)), value=0)
        if hasattr(gui, '_faradaiq_pyseccm_status_var'):
            gui._faradaiq_pyseccm_status_var.set(f'pySECCM parser: launched 0/{total}; reading progress file...')
        state = {'last': '', 'stable_finished': 0}
        def poll():
            try:
                txt = progress_file.read_text(encoding='utf-8', errors='replace').strip()
            except Exception:
                txt = state['last']
            if txt:
                state['last'] = txt
                m = re.match(r'(\d+)\s+of\s+(\d+)\s+(\S+)\s*(.*)', txt)
                if m:
                    cur = int(m.group(1)); tot = max(1, int(m.group(2))); phase = m.group(3); detail = m.group(4).strip()
                    elapsed = time.time() - start
                    eta = _v90_eta_text(elapsed, cur if phase.upper() in {'DONE','FINISHED'} else max(cur-1, 0), tot, detail)
                    pct = 100.0 * min(max(cur,0), tot) / max(1, tot)
                    status = f'pySECCM/DRT parser: {phase} {cur}/{tot} ({pct:.0f}%) | {eta} | {detail}'
                    if hasattr(gui, '_faradaiq_pyseccm_progress'):
                        gui._faradaiq_pyseccm_progress.configure(maximum=tot, value=min(cur, tot))
                    if hasattr(gui, '_faradaiq_pyseccm_status_var'):
                        gui._faradaiq_pyseccm_status_var.set(status)
                    try: gui.set_status(status)
                    except Exception: pass
                    if phase.upper() == 'FINISHED':
                        state['stable_finished'] += 1
                        if state['stable_finished'] >= 3:
                            return
            gui.after(1200, poll)
        gui.after(300, poll)
    except Exception:
        pass


