# ---- v91 patch: smart comparisons as actions, useful quick summaries, reliable popouts ----
APP_TITLE = "FaradaIQ Studio v273"

# v91 makes the right-side analysis area useful: smart comparisons are actions that
# generate Plot/view items, and quick summaries replace the old generic analysis table.

def _v91_walk_widgets(root):
    try:
        yield root
        for c in root.winfo_children():
            yield from _v91_walk_widgets(c)
    except Exception:
        return


def _v91_parent_contains(parent, child):
    try:
        w = child
        while w is not None:
            if w == parent:
                return True
            w = w.master
    except Exception:
        pass
    return False


def _v91_visible_text(widget):
    try:
        return str(widget.cget('text'))
    except Exception:
        return ''


def _v91_popup_tree(owner, title, source_tree):
    try:
        win = tk.Toplevel(owner)
        win.title(str(title))
        win.geometry('980x680')
        try: _v83_set_window_icon(win)
        except Exception: pass
        outer = ttk.Frame(win, style='Card.TFrame', padding=(8, 8)); outer.pack(fill='both', expand=True)
        ttk.Label(outer, text=str(title), style='Section.TLabel').pack(anchor='w', pady=(0, 6))
        holder = ttk.Frame(outer, style='Card.TFrame'); holder.pack(fill='both', expand=True)
        cols = tuple(source_tree['columns']) if source_tree is not None else ()
        show = source_tree['show'] if source_tree is not None else 'tree headings'
        tree = ttk.Treeview(holder, columns=cols, show=show, selectmode='extended')
        y = ttk.Scrollbar(holder, orient='vertical', command=tree.yview)
        x = ttk.Scrollbar(holder, orient='horizontal', command=tree.xview)
        tree.configure(yscrollcommand=y.set, xscrollcommand=x.set)
        tree.grid(row=0, column=0, sticky='nsew'); y.grid(row=0, column=1, sticky='ns'); x.grid(row=1, column=0, sticky='ew')
        holder.rowconfigure(0, weight=1); holder.columnconfigure(0, weight=1)
        try:
            tree.heading('#0', text=source_tree.heading('#0').get('text', 'Item'))
            tree.column('#0', width=max(320, int(source_tree.column('#0').get('width', 300))), stretch=True)
            for c in cols:
                tree.heading(c, text=source_tree.heading(c).get('text', str(c)))
                tree.column(c, width=max(110, int(source_tree.column(c).get('width', 100))), stretch=True)
        except Exception:
            pass
        def clone(src_parent='', dst_parent=''):
            for iid in source_tree.get_children(src_parent):
                text = source_tree.item(iid, 'text')
                vals = source_tree.item(iid, 'values')
                opened = bool(source_tree.item(iid, 'open'))
                niid = tree.insert(dst_parent, 'end', text=text, values=vals, open=opened)
                clone(iid, niid)
        try: clone()
        except Exception as exc: tree.insert('', 'end', text=f'Could not copy tree: {exc}', values=())
        row = ttk.Frame(outer, style='Card.TFrame'); row.pack(fill='x', pady=(6,0))
        ttk.Button(row, text='Close', command=win.destroy).pack(side='right')
        try: _v80_reapply_fonts(win)
        except Exception: pass
        win.lift(); win.focus_force()
        return win
    except Exception as exc:
        try: messagebox.showerror('Popout failed', str(exc), parent=owner)
        except Exception: pass


def _v91_popup_listbox(owner, title, source_listbox):
    try:
        win = tk.Toplevel(owner)
        win.title(str(title)); win.geometry('900x560')
        try: _v83_set_window_icon(win)
        except Exception: pass
        outer = ttk.Frame(win, style='Card.TFrame', padding=(8, 8)); outer.pack(fill='both', expand=True)
        ttk.Label(outer, text=str(title), style='Section.TLabel').pack(anchor='w', pady=(0, 6))
        holder = ttk.Frame(outer, style='Card.TFrame'); holder.pack(fill='both', expand=True)
        lb = tk.Listbox(holder, exportselection=False)
        y = ttk.Scrollbar(holder, orient='vertical', command=lb.yview)
        x = ttk.Scrollbar(holder, orient='horizontal', command=lb.xview)
        lb.configure(yscrollcommand=y.set, xscrollcommand=x.set)
        lb.grid(row=0, column=0, sticky='nsew'); y.grid(row=0, column=1, sticky='ns'); x.grid(row=1, column=0, sticky='ew')
        holder.rowconfigure(0, weight=1); holder.columnconfigure(0, weight=1)
        try:
            for i in range(source_listbox.size()): lb.insert('end', source_listbox.get(i))
        except Exception as exc: lb.insert('end', f'Could not copy list: {exc}')
        row = ttk.Frame(outer, style='Card.TFrame'); row.pack(fill='x', pady=(6,0))
        ttk.Button(row, text='Close', command=win.destroy).pack(side='right')
        try: _v80_reapply_fonts(win)
        except Exception: pass
        win.lift(); win.focus_force()
        return win
    except Exception as exc:
        try: messagebox.showerror('Popout failed', str(exc), parent=owner)
        except Exception: pass

