def _v91_records(browser, kind=None):
    recs = list(getattr(browser, '_v80_records', []) or getattr(browser, '_v78_records', []) or [])
    if kind:
        out = []
        for r in recs:
            try:
                if _v80_kind(r) == kind:
                    out.append(r)
            except Exception:
                pass
        return out
    return recs


def _v91_plottable_path_from_record(r):
    try:
        p = Path(r.get('path'))
        if p.exists() and p.suffix.lower() in (set(_V70_TABLE_EXTS) | set(_V70_IMAGE_EXTS) | set(_V70_VIDEO_EXTS) | {'.npy', '.npz'}):
            return p
    except Exception:
        pass
    return None


def _v91_paths_for_kind(browser, kind=None):
    paths, seen = [], set()
    for r in _v91_records(browser, kind):
        p = _v91_plottable_path_from_record(r)
        if not p: continue
        key = str(p.resolve()) if p.exists() else str(p)
        if key not in seen:
            seen.add(key); paths.append(p)
    return paths


def _v91_selected_paths_if_useful(browser, kind=None):
    try: paths = list(browser.selected_paths(plottable_only=True) or [])
    except Exception: paths = []
    if not paths: return []
    if not kind: return paths
    try:
        k = _v78_kind_from_paths(paths)
        if k == kind or kind in k or k in kind:
            return paths
    except Exception:
        pass
    # If any selected file is likely matching kind, keep the selection.
    joined = ' '.join(Path(p).name.lower() for p in paths)
    if kind == 'CV / LSV' and ('cv' in joined or 'current_vs_potential' in joined): return paths
    if kind == 'EIS' and ('eis' in joined or 'zreal' in joined or 'zimag' in joined or 'freq' in joined): return paths
    return []


def _v91_curve_stats(browser, paths, mode='Auto', max_files=36):
    lines = []
    scan_set, point_set, cycle_set = set(), set(), set()
    xmin=xmax=ymin=ymax=None
    n_ok = 0
    for p in list(paths or [])[:max_files]:
        try:
            p = Path(p)
            df = _v64_read_table_file(p)
            x,y,xcol,ycol,det = _v70_extract_xy(df, mode, x_choice='', y_choice='')
            x = np.asarray(x, dtype=float); y = np.asarray(y, dtype=float)
            mask = np.isfinite(x) & np.isfinite(y); x=x[mask]; y=y[mask]
            if len(x) < 2: continue
            n_ok += 1
            xmin = float(np.nanmin(x)) if xmin is None else min(xmin, float(np.nanmin(x)))
            xmax = float(np.nanmax(x)) if xmax is None else max(xmax, float(np.nanmax(x)))
            ymin = float(np.nanmin(y)) if ymin is None else min(ymin, float(np.nanmin(y)))
            ymax = float(np.nanmax(y)) if ymax is None else max(ymax, float(np.nanmax(y)))
            try:
                info = _v89_cv_info_for_path(browser, p) if '_v89_cv_info_for_path' in globals() else {}
                if info.get('scan') or info.get('label'): scan_set.add(str(info.get('scan') or info.get('label')))
                if info.get('point_idx'): point_set.add(f"point {int(info.get('point_idx')):02d}")
                if info.get('cycle_idx'): cycle_set.add(f"cycle {int(info.get('cycle_idx'))}")
            except Exception:
                pass
        except Exception:
            continue
    if n_ok:
        lines.append(f'Curves read: {n_ok} of {len(paths)} selected/plotted file(s).')
        lines.append(f'X range: {xmin:.6g} to {xmax:.6g}')
        lines.append(f'Y range: {ymin:.6g} to {ymax:.6g}')
    else:
        lines.append('No readable numeric X/Y curves found for quick summary.')
    if point_set: lines.append('Points: ' + ', '.join(sorted(point_set, key=_v80_nat_key)[:18]))
    if scan_set: lines.append('Scan rates: ' + ', '.join(sorted(scan_set, key=lambda s: (_v80_num(s), _v80_nat_key(s)))[:18]))
    if cycle_set: lines.append('Cycles: ' + ', '.join(sorted(cycle_set, key=lambda s: (_v80_num(s), _v80_nat_key(s)))[:12]))
    try:
        report = getattr(browser, '_v89_last_duplicate_report', {}) or {}
        if report.get('enabled'):
            lines.append(f"Duplicate removal: removed {len(report.get('removed', []) or [])} exact duplicate curve(s).")
    except Exception:
        pass
    return '\n'.join(lines)


def _v91_update_quick_summary(browser, paths=None, kind=None, prefix=''):
    try:
        paths = [Path(p) for p in (paths or getattr(browser, 'last_plot_paths', []) or [])]
        kind = kind or (_v78_kind_from_paths(paths) if paths else 'General')
        mode = _v89_var_get(browser, 'plot_mode_var', 'Auto') if '_v89_var_get' in globals() else 'Auto'
        lines = []
        if prefix: lines.append(prefix.rstrip())
        lines.append(f'Current data type: {kind}')
        lines.append(f'Plot mode: {mode}')
        lines.append(_v91_curve_stats(browser, paths, mode=mode))
        if kind == 'CV / LSV':
            lines.append('Suggested next step: open the saved Plot/view in PySimpleEChem for baseline, Ep, Jp, E½, and ΔEp after selecting the desired cycle/scan group.')
        elif kind == 'EIS':
            lines.append('Suggested next step: inspect Nyquist plus Bode real/img/mag/phase before any equivalent-circuit fitting.')
        txt = '\n'.join(lines)
        if hasattr(browser, 'quick_summary_text'):
            browser.quick_summary_text.configure(state='normal')
            browser.quick_summary_text.delete('1.0','end')
            browser.quick_summary_text.insert('1.0', txt)
            browser.quick_summary_text.configure(state='disabled')
        if hasattr(browser, 'status_var'):
            browser.status_var.set((prefix or f'{kind} quick summary ready').strip())
        return txt
    except Exception as exc:
        try: browser.log(f'Quick summary failed: {exc}')
        except Exception: pass
        return ''


def _v91_builtin_suggestions(browser):
    recs = _v91_records(browser)
    cv = [r for r in recs if _v80_kind(r) == 'CV / LSV']
    eis = [r for r in recs if _v80_kind(r) == 'EIS']
    suggestions = []
    if cv:
        scans = sorted({(r.get('_v90_tags') or _v90_record_tags(r, getattr(browser, '_v83_experiment_context', {}))).get('scan','') for r in cv}, key=lambda s: (_v80_num(s), _v80_nat_key(s)))
        pts = sorted({(r.get('_v90_tags') or _v90_record_tags(r, getattr(browser, '_v83_experiment_context', {}))).get('point','') for r in cv}, key=_v80_nat_key)
        cycles = sorted({(r.get('_v90_tags') or _v90_record_tags(r, getattr(browser, '_v83_experiment_context', {}))).get('cycle','') for r in cv}, key=lambda s: (_v80_num(s), _v80_nat_key(s)))
        suggestions.append(f'Plot CV scan-rate overview ({len([s for s in scans if s and s!="unassigned"])} scan-rate group(s), {len([p for p in pts if p and p!="unassigned"])} point group(s)).')
        suggestions.append('Compare CV cycles for the selected point/scan-rate group and add the overlay to Plot/view list.')
        suggestions.append('Compare CV by point: overlay selected point groups across scan rates/cycles.')
        suggestions.append('Open PySimpleEChem for the current selected CV Plot/view for peak, baseline, E½, and ΔEp metrics.')
    if eis:
        pts = sorted({(r.get('_v90_tags') or _v90_record_tags(r, getattr(browser, '_v83_experiment_context', {}))).get('point','') for r in eis}, key=_v80_nat_key)
        suggestions.append(f'Plot EIS Nyquist overview across {len([p for p in pts if p and p!="unassigned"])} point/potential group(s).')
        suggestions.append('Plot EIS Bode magnitude overview for selected EIS point/potential groups.')
        suggestions.append('Plot EIS Bode real and Bode imag comparisons before fitting.')
    if not suggestions:
        suggestions.append('Plot selected grouped data and create a Plot/view item.')
    suggestions.append('Export current comparison view with figure, overlay data, and quick-summary text.')
    return suggestions


def _v91_fill_suggestions(browser):
    suggestions = _v91_builtin_suggestions(browser)
    browser.suggestions = suggestions
    for lb in [getattr(browser, 'comp_list', None), getattr(browser, 'right_comp_list', None)]:
        try:
            lb.delete(0, 'end')
            for s in suggestions: lb.insert('end', s)
        except Exception: pass
    try:
        out = browser.analyzed_root / 'comparison_tables' / 'smart_comparison_actions_v91.txt'
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text('\n'.join(suggestions), encoding='utf-8')
    except Exception: pass
    try: browser.log(f'Filled {len(suggestions)} actionable smart comparisons.')
    except Exception: pass
    return suggestions


def _v91_ai_suggest_comparisons(browser):
    # Deterministic suggestions are more reliable for GUI actions; no blocking LLM call here.
    return _v91_fill_suggestions(browser)


def _v91_get_selected_suggestion(browser):
    for lb in [getattr(browser, 'right_comp_list', None), getattr(browser, 'comp_list', None)]:
        try:
            sel = lb.curselection()
            if sel: return lb.get(sel[0])
        except Exception: pass
    return ''


def _v91_create_comparison_view(browser, paths, kind, mode='Auto', name=None):
    paths = [Path(p) for p in (paths or []) if Path(p).exists()]
    if not paths:
        try: browser.log('No plottable files found for this smart comparison.')
        except Exception: pass
        return False
    try: browser.plot_mode_var.set(mode)
    except Exception: pass
    try: paths = _v89_deduplicate_paths_for_plot(browser, paths)
    except Exception: pass
    all_paths = list(paths)
    try: paths = _v78_limit_plot_paths(browser, paths)
    except Exception: pass
    try: browser.clear_plot()
    except Exception: pass
    try:
        browser.last_plot_paths = []
        browser._v89_seen_plot_signatures = set()
    except Exception: pass
    media = _v70_media_paths(paths); tables = _v70_table_paths(paths)
    if tables:
        for p in tables:
            try: browser._plot_file(p, clear=False)
            except Exception as exc:
                try: browser.log(f'Plot failed for {Path(p).name}: {exc}')
                except Exception: pass
        try: browser._finish_plot_axes()
        except Exception: pass
        try: _v75_hide_show_media_buttons(browser, False)
        except Exception: pass
    elif media:
        try:
            _v70_display_media_paths(browser, media, 0)
            _v75_hide_show_media_buttons(browser, len(media) > 1)
        except Exception: pass
    try: _v752_reset_plot_geometry(browser)
    except Exception: pass
    try:
        _v757_store_current_view(browser, paths, kind, name=name or f'{len(getattr(browser,"_v69_plot_views",[]))+1:02d} {kind} smart comparison ({len(paths)} files)')
    except Exception:
        try: _v75_store_current_view(browser, paths, kind, name=name)
        except Exception: pass
    removed = len((getattr(browser, '_v89_last_duplicate_report', {}) or {}).get('removed', []) or [])
    prefix = f'Created smart comparison view: {name or kind}. Plotted {len(paths)} of {len(all_paths)} file(s).'
    if removed: prefix += f' Removed {removed} exact duplicate curve(s).'
    _v91_update_quick_summary(browser, paths, kind, prefix=prefix)
    try: browser.log(prefix)
    except Exception: pass
    return True


def _v91_apply_selected_suggestion(browser):
    try:
        suggestion = _v91_get_selected_suggestion(browser)
        if not suggestion:
            _v91_fill_suggestions(browser)
            suggestion = _v91_get_selected_suggestion(browser) or (browser.suggestions[0] if getattr(browser,'suggestions',[]) else '')
        low = suggestion.lower()
        kind = None; mode = 'Auto'
        if 'pysimpleechem' in low:
            # Use selected CV plot/view if available; otherwise create a CV view first.
            try:
                if not browser.plot_view_list.curselection():
                    cv_paths = _v91_selected_paths_if_useful(browser, 'CV / LSV') or _v91_paths_for_kind(browser, 'CV / LSV')
                    _v91_create_comparison_view(browser, cv_paths, 'CV / LSV', mode='CV / LSV', name='PySimpleEChem-ready CV comparison')
                _v89_open_native_pysimpleechem_with_selected(browser)
            except Exception as exc:
                try: browser.log(f'PySimpleEChem smart action failed: {exc}')
                except Exception: pass
            return
        if 'eis' in low or 'nyquist' in low or 'bode' in low or 'impedance' in low:
            kind = 'EIS'
            if 'bode real' in low: mode = 'Bode real (Zreal)'
            elif 'bode imag' in low: mode = 'Bode imag (Zimag)'
            elif 'phase' in low: mode = 'Bode phase'
            elif 'bode' in low or 'magnitude' in low or '|z|' in low: mode = 'Bode mag |Z|'
            else: mode = 'EIS Nyquist (-Zimag)'
        elif 'cv' in low or 'cycle' in low or 'scan-rate' in low or 'scan rate' in low or 'voltam' in low:
            kind = 'CV / LSV'; mode = 'CV / LSV'
        elif 'drt' in low:
            kind = 'DRT'; mode = 'DRT'
        else:
            kind = None; mode = 'Auto'
        paths = _v91_selected_paths_if_useful(browser, kind) or _v91_paths_for_kind(browser, kind)
        if not paths and kind is None:
            paths = _v91_selected_paths_if_useful(browser, None) or _v91_paths_for_kind(browser, None)
        if not paths:
            try: browser.log(f'No plottable files found for smart action: {suggestion}')
            except Exception: pass
            return
        name = re.sub(r'[^A-Za-z0-9_ .\-/()]+', '', suggestion).strip()[:90] or f'{kind or "General"} smart comparison'
        _v91_create_comparison_view(browser, paths, kind or _v78_kind_from_paths(paths), mode=mode, name=name)
    except Exception as exc:
        try: browser.log(f'Could not apply smart comparison: {exc}')
        except Exception: pass


def _v91_hide_old_analysis_area_and_add_smart_panel(browser):
    if getattr(browser, '_v91_smart_panel_added', False):
        return
    try:
        right = browser.schema_frame.master if hasattr(browser, 'schema_frame') else None
        if right is None: return
        start_hiding = False
        for child in list(right.winfo_children()):
            if child is getattr(browser, 'schema_frame', None): start_hiding = True
            if start_hiding:
                try: child.pack_forget()
                except Exception: pass
        panel = ttk.LabelFrame(right, text='Smart comparisons / quick analysis', padding=(6, 6))
        panel.pack(fill='both', expand=True, pady=(0, 5))
        ttk.Label(panel, text='Choose an action below. Apply creates the comparison, plots it, and adds it to the Plot/view list.', style='Muted.TLabel', wraplength=360).pack(anchor='w', pady=(0, 4))
        lb_frame = ttk.Frame(panel, style='Card.TFrame'); lb_frame.pack(fill='both', expand=True)
        browser.right_comp_list = tk.Listbox(lb_frame, height=7, exportselection=False)
        y = ttk.Scrollbar(lb_frame, orient='vertical', command=browser.right_comp_list.yview)
        browser.right_comp_list.configure(yscrollcommand=y.set)
        browser.right_comp_list.pack(side='left', fill='both', expand=True); y.pack(side='right', fill='y')
        browser.right_comp_list.bind('<Double-Button-1>', lambda e, b=browser: _v91_apply_selected_suggestion(b))
        row = ttk.Frame(panel, style='Card.TFrame'); row.pack(fill='x', pady=(4, 4))
        ttk.Button(row, text='Suggest', command=lambda b=browser: _v91_ai_suggest_comparisons(b)).pack(side='left', fill='x', expand=True, padx=(0,3))
        ttk.Button(row, text='Apply / add to Plot-view', command=lambda b=browser: _v91_apply_selected_suggestion(b)).pack(side='left', fill='x', expand=True, padx=(3,0))
        ttk.Label(panel, text='Quick summary for current Plot/view', style='Section.TLabel').pack(anchor='w', pady=(4,2))
        browser.quick_summary_text = ScrolledText(panel, height=8, wrap='word')
        browser.quick_summary_text.pack(fill='both', expand=True)
        try:
            browser.quick_summary_text.configure(background='#f8fafc', foreground='#0f172a', font=('Segoe UI', 10))
        except Exception: pass
        _v91_fill_suggestions(browser)
        browser._v91_smart_panel_added = True
    except Exception as exc:
        try: browser.log(f'Could not build v91 smart panel: {exc}')
        except Exception: pass

try:
    _V91_PREV_LOAD_PLOT_VIEW = _v89_load_plot_view if callable(globals().get('_v89_load_plot_view')) else _v75_load_plot_view
except Exception:
    _V91_PREV_LOAD_PLOT_VIEW = None


def _v91_load_plot_view(browser):
    try:
        if callable(_V91_PREV_LOAD_PLOT_VIEW): _V91_PREV_LOAD_PLOT_VIEW(browser)
    finally:
        try:
            paths = list(getattr(browser, 'last_plot_paths', []) or [])
            kind = _v78_kind_from_paths(paths) if paths else 'General'
            _v91_update_quick_summary(browser, paths, kind, prefix='Loaded Plot/view.')
        except Exception: pass

try:
    _V91_PREV_STORE_CURRENT_VIEW = _v757_store_current_view
except Exception:
    _V91_PREV_STORE_CURRENT_VIEW = None


def _v91_store_current_view(browser, paths, kind, name=None):
    res = None
    if callable(_V91_PREV_STORE_CURRENT_VIEW):
        res = _V91_PREV_STORE_CURRENT_VIEW(browser, paths, kind, name=name)
    else:
        res = _v75_store_current_view(browser, paths, kind, name=name)
