# Browser smart suggestions can use the structured metadata saved beside the analysis-ready output.
def _v92_load_browser_metadata(browser):
    try:
        roots = []
        for attr in ['analyzed_root', 'analysis_root', 'folder']:
            try:
                p = Path(getattr(browser, attr))
                roots += [p, p.parent]
            except Exception:
                pass
        for r in roots:
            for pat in ['FaradaIQ_structured_experiment_metadata_v92.json', '*structured_experiment_metadata*.json']:
                for p in r.glob(pat):
                    try:
                        return json.loads(p.read_text(encoding='utf-8', errors='replace'))
                    except Exception:
                        pass
    except Exception:
        pass
    return {}

