# ---- v93 patch: contextual AI chat window for currently loaded/processed data ----
APP_TITLE = "FaradaIQ Studio v273"

_FARADAIQ_V93_OPEN_BROWSERS = []


def _v93_now_label():
    try:
        return datetime.now().strftime('%Y%m%d_%H%M%S')
    except Exception:
        return 'timestamp'


def _v93_safe_get_text(widget, limit=12000):
    try:
        txt = widget.get('1.0', 'end').strip()
        return txt[:limit] + ('\n... [truncated]' if len(txt) > limit else '')
    except Exception:
        return ''


def _v93_json_preview(path, limit=12000):
    try:
        p = Path(path)
        raw = p.read_text(encoding='utf-8', errors='replace')
        try:
            data = json.loads(raw)
            raw = json.dumps(data, ensure_ascii=False, indent=2)
        except Exception:
            pass
        return raw[:limit] + ('\n... [truncated]' if len(raw) > limit else '')
    except Exception:
        return ''


def _v93_csv_preview(path, max_rows=8, limit=6000):
    try:
        p = Path(path)
        lines = []
        with p.open('r', encoding='utf-8', errors='replace') as f:
            for i, line in enumerate(f):
                if i >= max_rows:
                    break
                lines.append(line.rstrip('\n'))
        raw = '\n'.join(lines)
        return raw[:limit] + ('\n... [truncated]' if len(raw) > limit else '')
    except Exception:
        return ''


def _v93_find_open_browsers(gui=None):
    out = []
    def add(obj):
        try:
            if obj and obj.winfo_exists() and obj not in out:
                out.append(obj)
        except Exception:
            pass
    for b in list(globals().get('_FARADAIQ_V93_OPEN_BROWSERS', []) or []):
        add(b)
    # Also walk widget tree in case a browser was created before this patch registered it.
    def walk(w):
        try:
            if isinstance(w, FaradaIQDataBrowser):
                add(w)
        except Exception:
            pass
        try:
            for c in w.winfo_children():
                walk(c)
        except Exception:
            pass
    try:
        root = gui.winfo_toplevel() if gui is not None else None
        if root:
            walk(root)
    except Exception:
        pass
    try:
        # Tk toplevels are children of the root interpreter; this catches detached Toplevels.
        root = gui._root() if gui is not None and hasattr(gui, '_root') else None
        if root:
            walk(root)
    except Exception:
        pass
    return out


def _v93_browser_context(browser, max_views=12):
    lines = []
    try:
        lines.append(f'Browser title: {browser.title()}')
    except Exception: pass
    for attr in ['analysis_root', 'analyzed_root', 'base_name']:
        try:
            val = getattr(browser, attr)
            if val:
                lines.append(f'{attr}: {val}')
        except Exception: pass
    try:
        lines.append(f'Current plot mode: {browser.plot_mode_var.get()}')
    except Exception: pass
    try:
        lines.append(f'CV cycle filter: {browser.cv_cycle_filter_var.get()}')
    except Exception: pass
    try:
        lines.append(f'Legend mode: {browser.legend_mode_var.get()}')
    except Exception: pass
    try:
        lines.append(f'Remove exact duplicates: {bool(browser.remove_duplicate_curves_var.get())}')
    except Exception: pass
    try:
        views = list(getattr(browser, '_v69_plot_views', []) or [])
        lines.append(f'Plot/view count: {len(views)}')
        sel_idx = None
        try:
            sel = browser.plot_view_list.curselection()
            if sel:
                sel_idx = int(sel[0])
        except Exception:
            pass
        for i, v in enumerate(views[:max_views], start=1):
            mark = ' [selected]' if (sel_idx is not None and i-1 == sel_idx) else ''
            paths = v.get('paths') or v.get('source_paths') or []
            names = []
            for p in paths[:5]:
                try: names.append(Path(p).name)
                except Exception: names.append(str(p))
            lines.append(f'  {i:02d}. {v.get("name", "view")}{mark} | kind={v.get("kind", "")} | files={len(paths)} | first files={names}')
        if len(views) > max_views:
            lines.append(f'  ... {len(views)-max_views} more plot/views not listed')
    except Exception as exc:
        lines.append(f'Plot/view context unavailable: {exc}')
    try:
        if hasattr(browser, 'quick_summary_text'):
            lines.append('\nBrowser quick summary:')
            lines.append(_v93_safe_get_text(browser.quick_summary_text, 8000))
    except Exception: pass
    try:
        if hasattr(browser, 'log_text'):
            log_txt = _v93_safe_get_text(browser.log_text, 4000)
            if log_txt:
                lines.append('\nRecent browser log:')
                lines.append(log_txt[-4000:])
    except Exception: pass
    return '\n'.join(lines)


def _v93_latest_files_text(root, limit_files=14):
    root = Path(root) if root else None
    if not root or not root.exists():
        return ''
    candidates = []
    for pat in ['FaradaIQ_structured_experiment_metadata_v92.json', 'FaradaIQ_structured_data_map_v92.txt', 'AI_prompt_current.txt', '*AI_analysis_summary.json', '*manifest*.json', '*summary*.json', '*.csv', '*.txt']:
        try:
            candidates.extend([p for p in root.rglob(pat) if p.is_file()])
        except Exception:
            pass
    # Keep useful latest/metadata files, avoid very large raw dumps.
    unique = []
    seen = set()
    for p in sorted(candidates, key=lambda x: (0 if 'structured' in x.name.lower() or 'summary' in x.name.lower() or 'manifest' in x.name.lower() else 1, -x.stat().st_mtime)):
        try:
            if p in seen or p.stat().st_size > 2_000_000:
                continue
            seen.add(p); unique.append(p)
            if len(unique) >= limit_files:
                break
        except Exception:
            pass
    lines = []
    for p in unique:
        try:
            rel = p.relative_to(root)
        except Exception:
            rel = p.name
        lines.append(f'--- FILE PREVIEW: {rel} ({p.stat().st_size} bytes) ---')
        if p.suffix.lower() == '.json':
            lines.append(_v93_json_preview(p, 9000))
        elif p.suffix.lower() == '.csv':
            lines.append(_v93_csv_preview(p, max_rows=8, limit=5000))
        else:
            lines.append(p.read_text(encoding='utf-8', errors='replace')[:7000])
    return '\n'.join(lines)


def _v93_analysis_roots_for_gui(gui):
    roots = []
    try:
        r = _v37_analysis_root_for_gui(gui)
        if r and Path(r).exists():
            roots.append(Path(r))
    except Exception:
        pass
    try:
        out = Path(gui.output_dir_var.get().strip() or '').resolve()
        if out.exists():
            roots.append(out)
            # Prefer newest sample subfolders too.
            dirs = [p for p in out.iterdir() if p.is_dir()]
            dirs = sorted(dirs, key=lambda p: p.stat().st_mtime, reverse=True)[:4]
            roots.extend(dirs)
    except Exception:
        pass
    clean = []
    seen = set()
    for r in roots:
        try:
            key = str(r.resolve())
            if key not in seen:
                seen.add(key); clean.append(r)
        except Exception:
            pass
    return clean


def _v93_build_ai_chat_context(gui, max_chars=70000):
    lines = []
    lines.append('FARADAIQ LIVE DATA CONTEXT FOR AI CHAT')
    lines.append('This context is generated from the currently loaded/processed FaradaIQ data. Use only this context and ask for clarification if needed.')
    try:
        ctx = _v753_launch_context() if '_v753_launch_context' in globals() else {}
        lines.append(f"Launch session ID: {ctx.get('session_id','')}")
    except Exception: pass
    try: lines.append(f'Input file/folder: {gui.input_path_var.get()}')
    except Exception: pass
    try: lines.append(f'Output folder: {gui.output_dir_var.get()}')
    except Exception: pass
    try:
        provider, model, _cand = _v66_selected_llm_label_text() if '_v66_selected_llm_label_text' in globals() else ('selected LLM','',{})
        lines.append(f'Selected LLM: {provider} | model: {model}')
    except Exception: pass
    try:
        if getattr(gui, 'collection', None) is not None and getattr(gui.collection, 'source_path', None):
            lines.append(f'Collection source: {gui.collection.source_path}')
    except Exception: pass
    lines.append('\n--- EXPERIMENTAL DESCRIPTION / AI PROMPT TEXT ---')
    try: lines.append(_v93_safe_get_text(gui.desc_text, 14000))
    except Exception: pass
    lines.append('\n--- SESSION SUMMARY ---')
    try: lines.append(_v93_safe_get_text(gui.summary_text, 14000))
    except Exception: pass
    lines.append('\n--- STRUCTURED DATA MAP / DATA STRUCTURE PREVIEW ---')
    try: lines.append(_v93_safe_get_text(gui.structure_text, 18000))
    except Exception: pass
    for r in _v93_analysis_roots_for_gui(gui):
        lines.append(f'\n--- ANALYSIS/OUTPUT ROOT: {r} ---')
        try:
            lines.append(_v37_compact_file_tree(r, max_files=160, max_depth=5))
        except Exception:
            pass
        prev = _v93_latest_files_text(r, limit_files=10)
        if prev:
            lines.append('\n--- KEY FILE PREVIEWS FROM THIS ROOT ---')
            lines.append(prev)
    browsers = _v93_find_open_browsers(gui)
    if browsers:
        lines.append('\n--- OPEN DATA BROWSER / PLOT-VIEW CONTEXT ---')
        for i, b in enumerate(browsers, start=1):
            lines.append(f'\n[BROWSER {i}]')
            lines.append(_v93_browser_context(b))
    text = '\n'.join(str(x) for x in lines if x is not None)
    if len(text) > max_chars:
        text = text[:max_chars] + '\n... [FaradaIQ live context truncated for chat request]'
    return text


def _v93_chat_save_dir(gui):
    try:
        roots = _v93_analysis_roots_for_gui(gui)
        root = roots[0] if roots else Path(gui.output_dir_var.get().strip() or '.').resolve()
    except Exception:
        root = Path('.').resolve()
    p = root / 'FaradaIQ_AI_chat_transcripts'
    try: p.mkdir(parents=True, exist_ok=True)
    except Exception: pass
    return p


class FaradaIQAIChatWindow(tk.Toplevel):
    def __init__(self, gui):
        super().__init__(gui)
        self.gui = gui
        self.history = []
        self.context_text = ''
        self.title('FaradaIQ AI Chat — live data context')
        try: self.geometry('980x760')
        except Exception: pass
        try: _v29_set_icon(self)
        except Exception: pass
        try: _v80_reapply_fonts(self)
        except Exception: pass
        self._build_ui()
        self.refresh_context(auto=True)

    def _build_ui(self):
        outer = ttk.Frame(self, padding=(10,10))
        outer.pack(fill='both', expand=True)
        head = ttk.Frame(outer)
        head.pack(fill='x', pady=(0,6))
        try:
            provider, model, _cand = _v66_selected_llm_label_text()
            label = f'AI chat using: {provider} | {model}'
        except Exception:
            label = 'AI chat using selected FaradaIQ LLM'
        self.llm_var = tk.StringVar(value=label)
        ttk.Label(head, textvariable=self.llm_var, style='Section.TLabel').pack(side='left', fill='x', expand=True)
        ttk.Button(head, text='LLM settings', command=lambda: _v37_show_llm_settings(self.gui)).pack(side='right', padx=(6,0))
        ttk.Button(head, text='Refresh context', command=self.refresh_context).pack(side='right', padx=(6,0))
        ttk.Button(head, text='View context', command=self.view_context).pack(side='right', padx=(6,0))
        ttk.Button(head, text='Save transcript', command=self.save_transcript).pack(side='right', padx=(6,0))

        self.status_var = tk.StringVar(value='Ready')
        ttk.Label(outer, textvariable=self.status_var, style='Status.TLabel').pack(fill='x', pady=(0,4))

        self.chat = ScrolledText(outer, wrap='word', height=26)
        self.chat.pack(fill='both', expand=True, pady=(0,8))
        try: _v33_text_style(self.chat, small=False)
        except Exception: pass
        self.chat.insert('end', 'FaradaIQ AI Chat\n')
        self.chat.insert('end', 'This chat can use the current loaded data, structured metadata, parsed output tree, AI bundle files, and open Data Browser plot/view context.\n\n')
        self.chat.configure(state='disabled')

        opts = ttk.Frame(outer)
        opts.pack(fill='x', pady=(0,5))
        self.include_context_var = tk.BooleanVar(value=True)
        ttk.Checkbutton(opts, text='Attach current FaradaIQ data context to next message', variable=self.include_context_var).pack(side='left')
        self.max_context_var = tk.StringVar(value='70k')
        ttk.Label(opts, text='Context limit', style='Muted.TLabel').pack(side='left', padx=(12,4))
        try:
            ttk.Combobox(opts, textvariable=self.max_context_var, values=['35k','70k','120k'], state='readonly', width=8).pack(side='left')
        except Exception:
            pass

        row = ttk.Frame(outer)
        row.pack(fill='x')
        self.input = tk.Text(row, height=4, wrap='word')
        self.input.pack(side='left', fill='x', expand=True)
        try: _v33_text_style(self.input, small=False)
        except Exception: pass
        btncol = ttk.Frame(row)
        btncol.pack(side='right', fill='y', padx=(8,0))
        ttk.Button(btncol, text='Send', command=self.send_message, style='Accent.TButton').pack(fill='x', pady=(0,6))
        ttk.Button(btncol, text='Clear chat', command=self.clear_chat).pack(fill='x')
        try:
            self.input.bind('<Control-Return>', lambda e: (self.send_message(), 'break'))
        except Exception: pass

    def _append(self, who, text):
        self.chat.configure(state='normal')
        self.chat.insert('end', f'\n{who}:\n{text}\n')
        self.chat.see('end')
        self.chat.configure(state='disabled')

    def refresh_context(self, auto=False):
        try:
            lim = {'35k':35000, '70k':70000, '120k':120000}.get(self.max_context_var.get(), 70000)
        except Exception:
            lim = 70000
        self.status_var.set('Refreshing live FaradaIQ data context...')
        def work():
            try:
                ctx = _v93_build_ai_chat_context(self.gui, max_chars=lim)
                self.context_text = ctx
                def finish():
                    self.status_var.set(f'Context ready: {len(ctx):,} characters from current data/session/browser state.')
                    if not auto:
                        self._append('FaradaIQ', f'Live context refreshed ({len(ctx):,} characters).')
                self.after(0, finish)
            except Exception as exc:
                self.after(0, lambda: self.status_var.set(f'Context refresh failed: {exc}'))
        threading.Thread(target=work, daemon=True).start()

    def view_context(self):
        win = tk.Toplevel(self)
        win.title('FaradaIQ live context exposed to AI chat')
        try: win.geometry('920x680')
        except Exception: pass
        box = ScrolledText(win, wrap='word')
        box.pack(fill='both', expand=True, padx=10, pady=10)
        try: _v33_text_style(box, small=False)
        except Exception: pass
        box.insert('1.0', self.context_text or '(No context yet. Click Refresh context.)')
        box.configure(state='disabled')

    def clear_chat(self):
        self.history = []
        self.chat.configure(state='normal')
        self.chat.delete('1.0','end')
        self.chat.insert('end', 'FaradaIQ AI Chat\nChat cleared. Current data context is still available.\n')
        self.chat.configure(state='disabled')

    def save_transcript(self):
        try:
            folder = _v93_chat_save_dir(self.gui)
            path = folder / f'FaradaIQ_AI_chat_{_v93_now_label()}.txt'
            txt = self.chat.get('1.0','end')
            meta = '\n\n===== FARADAIQ CONTEXT SNAPSHOT USED BY CHAT =====\n' + (self.context_text or '')
            path.write_text(txt + meta, encoding='utf-8')
            self.status_var.set(f'Saved transcript: {path}')
            self._append('FaradaIQ', f'Saved transcript:\n{path}')
        except Exception as exc:
            messagebox.showerror('Save transcript failed', f'{exc}\n\n{traceback.format_exc()}', parent=self)

    def send_message(self):
        user_text = self.input.get('1.0','end').strip()
        if not user_text:
            return
        self.input.delete('1.0','end')
        self._append('You', user_text)
        self.status_var.set('Sending to selected LLM...')
        self.history.append({'role':'user', 'content':user_text})
        include_context = bool(self.include_context_var.get())
        context = self.context_text if include_context else ''
        # Refresh stale/empty context automatically when requested.
        if include_context and not context:
            try: context = _v93_build_ai_chat_context(self.gui, max_chars=70000); self.context_text = context
            except Exception: context = ''
        system = (
            'You are FaradaIQ Studio AI chat. Answer as an electrochemical data-analysis assistant. '
            'Use the provided FaradaIQ live context for the current loaded/processed data, parsed outputs, structured metadata, AI bundle, and Data Browser plot/view state. '
            'Do not invent measurements. If data or metadata are missing, state that and suggest the next FaradaIQ action. '
            'When useful, give concrete actions the user can take in FaradaIQ, and keep numeric claims tied to the provided context.'
        )
        context_msg = 'FARADAIQ LIVE CONTEXT FOR THIS CHAT TURN:\n' + (context or '(Context not attached.)')
        history = self.history[-10:]
        messages = [{'role':'system','content':system}, {'role':'user','content':context_msg}] + history
        def work():
            try:
                answer, conn = _v37_call_best_llm(messages, max_tokens=3200, temperature=0.18)
                answer = str(answer or '').strip()
                self.history.append({'role':'assistant', 'content':answer})
                def finish():
                    try:
                        provider = conn.get('name','LLM'); model = conn.get('model','')
                        self.llm_var.set(f'AI chat using: {provider} | {model}')
                    except Exception: pass
                    self._append('AI', answer)
                    self.status_var.set('Ready')
                    try:
                        folder = _v93_chat_save_dir(self.gui)
                        autosave = folder / 'FaradaIQ_AI_chat_latest.txt'
                        autosave.write_text(self.chat.get('1.0','end') + '\n\n===== CONTEXT SNAPSHOT =====\n' + (self.context_text or ''), encoding='utf-8')
                    except Exception: pass
                self.after(0, finish)
            except Exception as exc:
                def fail():
                    self._append('FaradaIQ', f'LLM call failed: {exc}\nOpen LLM settings, ping/select a provider, or start the LiteLLM proxy if using AWS Bedrock.')
                    self.status_var.set('LLM call failed')
                self.after(0, fail)
        threading.Thread(target=work, daemon=True).start()


