# ---- v95 patch: learned parser ETA stats + no version number in header tagline ----
# User request: keep parser/DRT timing history in the BAT root so ETA estimates improve like traffic-time estimates,
# and remove the version number from the visible header tagline.
import statistics as _v95_statistics

FARADAIQ_APP_VERSION = 'v199'


def _v95_runtime_stats_dir():
    """Persistent launcher-root folder for learned runtime/ETA data.

    The BAT sets FARADAIQ_RUNTIME_STATS_DIR to <BAT folder>\\FaradaIQ_runtime_estimates.
    This is intentionally not the per-launch tracking folder and not the selected data output folder.
    """
    try:
        p = os.environ.get('FARADAIQ_RUNTIME_STATS_DIR') or ''
        if p:
            d = Path(p)
        else:
            d = Path(__file__).resolve().parent / 'FaradaIQ_runtime_estimates'
        d.mkdir(parents=True, exist_ok=True)
        return d
    except Exception:
        return Path(__file__).resolve().parent


def _v95_runtime_history_path():
    return _v95_runtime_stats_dir() / 'parser_runtime_history_v95.jsonl'


def _v95_runtime_summary_path():
    return _v95_runtime_stats_dir() / 'parser_runtime_summary_v95.json'


def _v95_parser_kind(detail=''):
    d = str(detail or '').lower()
    if 'headless_pydrt' in d or 'pydrt' in d or 'drt' in d:
        return 'DRT'
    if 'parse_eis' in d or ' eis' in (' ' + d) or 'fulleis' in d:
        return 'EIS'
    if 'parse_cv' in d or ' cv' in (' ' + d) or 'current_vs_potential' in d:
        return 'CV'
    if 'parse_iv' in d or 'tafel' in d or ' iv' in (' ' + d):
        return 'IV_Tafel'
    if 'parse_ocp' in d or ' ocp' in (' ' + d):
        return 'OCP'
    return 'parser_other'


def _v95_read_runtime_summary():
    try:
        p = _v95_runtime_summary_path()
        if p.exists():
            data = json.loads(p.read_text(encoding='utf-8', errors='replace'))
            return data if isinstance(data, dict) else {}
    except Exception:
        pass
    return {}


def _v95_write_runtime_summary(summary):
    try:
        p = _v95_runtime_summary_path()
        tmp = p.with_suffix('.tmp')
        tmp.write_text(json.dumps(summary, indent=2, sort_keys=True, default=str), encoding='utf-8')
        tmp.replace(p)
    except Exception:
        pass


def _v95_record_parser_runtime(kind, seconds, detail='', returncode=None, total_commands=None):
    try:
        seconds = float(seconds)
        if seconds <= 0 or seconds > 86400:
            return
        kind = _v95_parser_kind(kind or detail)
        ctx = _v753_launch_context() if '_v753_launch_context' in globals() else {}
        row = {
            'timestamp': datetime.now().isoformat(timespec='seconds'),
            'session_id': ctx.get('session_id') or os.environ.get('FARADAIQ_SESSION_ID',''),
            'app_version': 'v95',
            'kind': kind,
            'duration_seconds': round(seconds, 3),
            'detail': str(detail or '')[:500],
            'returncode': returncode,
            'total_commands': total_commands,
        }
        hp = _v95_runtime_history_path()
        with hp.open('a', encoding='utf-8') as f:
            f.write(json.dumps(row, default=str) + '\n')
        summary = _v95_read_runtime_summary()
        summary.setdefault('version', 'v95')
        summary.setdefault('updated', '')
        summary['updated'] = row['timestamp']
        summary.setdefault('by_kind', {})
        k = summary['by_kind'].setdefault(kind, {'count':0, 'mean_seconds':0.0, 'median_seconds':0.0, 'recent_seconds':[]})
        recent = list(k.get('recent_seconds') or [])
        recent.append(seconds)
        recent = recent[-40:]
        k['recent_seconds'] = [round(float(x),3) for x in recent]
        k['count'] = int(k.get('count',0)) + 1
        k['mean_seconds'] = round(float(sum(recent) / max(1, len(recent))), 3)
        try: k['median_seconds'] = round(float(_v95_statistics.median(recent)), 3)
        except Exception: k['median_seconds'] = k['mean_seconds']
        _v95_write_runtime_summary(summary)
    except Exception:
        pass


def _v95_learned_seconds_for_kind(kind, fallback):
    try:
        summary = _v95_read_runtime_summary()
        k = (summary.get('by_kind') or {}).get(kind) or {}
        recent = [float(x) for x in (k.get('recent_seconds') or []) if float(x) > 0]
        if recent:
            # Blend median and mean to avoid one very slow DRT run dominating every ETA.
            return 0.65 * float(_v95_statistics.median(recent[-20:])) + 0.35 * float(sum(recent[-20:]) / len(recent[-20:]))
        m = float(k.get('mean_seconds') or 0)
        if m > 0: return m
    except Exception:
        pass
    return fallback


def _v95_eta_text(elapsed, cur, tot, detail=''):
    """ETA with persistent learned runtime stats plus current-run speed.

    It starts from literature/heuristic weights (DRT and EIS are heavier) and then gradually
    replaces them with locally observed timings saved in FaradaIQ_runtime_estimates.
    """
    try:
        cur = int(cur); tot = max(1, int(tot)); elapsed = max(0.1, float(elapsed))
        remaining_cmds = max(0, tot - cur)
        if remaining_cmds <= 0:
            return 'ETA done'
        kind = _v95_parser_kind(detail)
        heuristic = {'CV': 18.0, 'EIS': 42.0, 'DRT': 240.0, 'IV_Tafel': 18.0, 'OCP': 15.0, 'parser_other': 30.0}.get(kind, 30.0)
        learned = _v95_learned_seconds_for_kind(kind, heuristic)
        observed = elapsed / max(cur, 0.35)
        # At the beginning, rely more on learned history. As the current run progresses, blend in observed speed.
        progress = min(1.0, max(0.0, cur / max(1, tot)))
        per_cmd = (1.0 - 0.45 * progress) * learned + (0.45 * progress) * observed
        rem = max(0.0, per_cmd * remaining_cmds)
        basis = 'learned' if abs(learned - heuristic) > 1e-6 else 'estimated'
        if rem < 60:
            return f'ETA ~{int(rem)} s ({basis})'
        if rem < 3600:
            return f'ETA ~{int(rem//60)} min {int(rem%60)} s ({basis})'
        return f'ETA ~{rem/3600:.1f} h ({basis})'
    except Exception:
        return 'ETA estimating...'


