def _v67_start_pyseccm_monitor(gui, progress_file, total):
    """v95 monitor: progress + learned runtime persistence."""
    try:
        progress_file = Path(progress_file)
        _v67_add_pyseccm_status_bar(gui)
        start = time.time()
        step_starts = {}
        step_details = {}
        if hasattr(gui, '_faradaiq_pyseccm_progress'):
            gui._faradaiq_pyseccm_progress.configure(maximum=max(1, int(total)), value=0)
        if hasattr(gui, '_faradaiq_pyseccm_status_var'):
            stats_dir = _v95_runtime_stats_dir()
            gui._faradaiq_pyseccm_status_var.set(f'pySECCM/DRT parser: launched 0/{total}; learned ETA stats: {stats_dir.name}')
        state = {'last':'', 'stable_finished':0, 'last_tuple':None}
        def poll():
            try:
                txt = progress_file.read_text(encoding='utf-8', errors='replace').strip()
            except Exception:
                txt = state['last']
            if txt:
                state['last'] = txt
                m = re.match(r'(\d+)\s+of\s+(\d+)\s+(\S+)\s*(.*)', txt)
                if m:
                    cur = int(m.group(1)); tot = max(1, int(m.group(2))); phase = m.group(3); detail = m.group(4).strip()
                    tup = (cur, tot, phase, detail)
                    now = time.time()
                    if tup != state.get('last_tuple'):
                        state['last_tuple'] = tup
                        ph = phase.upper()
                        if ph == 'RUNNING':
                            step_starts[cur] = now
                            step_details[cur] = detail
                        elif ph == 'DONE':
                            st = step_starts.get(cur)
                            if st is not None:
                                rc = None
                                mm = re.search(r'rc\s*=\s*(-?\d+)', detail, flags=re.I)
                                if mm:
                                    try: rc = int(mm.group(1))
                                    except Exception: rc = None
                                dur = max(0.01, now - st)
                                _v95_record_parser_runtime(_v95_parser_kind(detail or step_details.get(cur,'')), dur, detail=(detail or step_details.get(cur,'')), returncode=rc, total_commands=tot)
                    elapsed = now - start
                    done_for_eta = cur if phase.upper() in {'DONE','FINISHED'} else max(cur-1, 0)
                    eta = _v95_eta_text(elapsed, done_for_eta, tot, detail)
                    pct = 100.0 * min(max(cur,0), tot) / max(1, tot)
                    status = f'pySECCM/DRT parser: {phase} {cur}/{tot} ({pct:.0f}%) | {eta} | {detail}'
                    if hasattr(gui, '_faradaiq_pyseccm_progress'):
                        gui._faradaiq_pyseccm_progress.configure(maximum=tot, value=min(cur, tot))
                    if hasattr(gui, '_faradaiq_pyseccm_status_var'):
                        gui._faradaiq_pyseccm_status_var.set(status)
                    try: gui.set_status(status)
                    except Exception: pass
                    if phase.upper() == 'FINISHED':
                        state['stable_finished'] += 1
                        if state['stable_finished'] >= 3:
                            try:
                                summary = _v95_runtime_summary_path()
                                if hasattr(gui, '_faradaiq_pyseccm_status_var'):
                                    gui._faradaiq_pyseccm_status_var.set(f'pySECCM/DRT parser: finished {tot}/{tot}. ETA stats updated: {summary.name}')
                            except Exception: pass
                            return
            gui.after(1200, poll)
        gui.after(300, poll)
    except Exception:
        pass


def _v95_strip_header_version_text(root):
    """Remove only the visible version token from the header tagline."""
    try:
        def walk(w):
            try:
                txt = str(w.cget('text'))
            except Exception:
                txt = None
            if txt and 'Designed by Venky Prabhakaran and powered by LLM' in txt:
                new = re.sub(r'\s*•\s*v\d+(?:\.\d+)?\s*', ' ', txt)
                new = re.sub(r'\s{2,}', ' ', new).strip()
                # Keep the year if it was present, but without the version token.
                new = new.replace('LLM 2026', 'LLM • 2026')
                try: w.configure(text=new)
                except Exception: pass
            try:
                for c in w.winfo_children():
                    walk(c)
            except Exception:
                pass
        walk(root)
    except Exception:
        pass


