def _v95_iter_widgets(root):
    try:
        yield root
        for child in root.winfo_children():
            yield from _v95_iter_widgets(child)
    except Exception:
        return


def _v95_widget_text(widget):
    try:
        return str(widget.cget('text')).strip()
    except Exception:
        return ''


def _v95_find_text_widgets(root, contains=None, exact=None):
    found = []
    low_contains = str(contains).lower() if contains is not None else None
    for w in _v95_iter_widgets(root):
        txt = _v95_widget_text(w)
        if exact is not None and txt == exact:
            found.append(w)
        elif low_contains is not None and low_contains in txt.lower():
            found.append(w)
    return found


def _v95_tooltip_text(widget):
    txt = _v95_widget_text(widget)
    cls = ''
    try: cls = widget.winfo_class()
    except Exception: pass
    t = txt.lower()
    specific = {
        'Plot / overlay selected': 'Plot the selected experiment-map group. The plotted data are also saved as a Plot/view item for reuse, PySimpleEChem handoff, smart comparison, and export.',
        'Clear': 'Clear only the current plot canvas. This does not delete source data or saved Plot/view items.',
        'Export': 'Export the current figure or comparison view to the active sample analysis output folder.',
        'Remove exact duplicates': 'When enabled, FaradaIQ compares numeric X/Y arrays and keeps one copy of exact duplicate curves before plotting or sending to PySimpleEChem.',
        'Rename view': 'Rename the selected Plot/view item. This only changes the display/session name, not source filenames.',
        'Analyze view': 'Analyze the selected Plot/view context. Prefer smart comparisons and PySimpleEChem for CV peak/baseline metrics.',
        'Clear Plot/view list': 'Remove all saved Plot/view items from this browser session. Source files are not changed.',
        'Open PySimpleEChem for selected CV view': 'Open the bundled PySimpleEChem workflow using the selected Plot/view CV files. If no Plot/view is selected, the current plotted CV files are used.',
        'Open PySimpleEChem for selected Plot/view CV files': 'Send the selected Plot/view CV files and metadata to PySimpleEChem for baseline, peak, Ep, Jp, E½, ΔEp, diffusion, and kinetics analysis.',
        'Suggest': 'Generate deterministic smart comparison actions from the detected data structure and structured metadata.',
        'Apply / add to Plot-view': 'Run the selected smart comparison action, plot the result, and add the created comparison to the Plot/view list.',
        'Apply': 'Run the selected smart comparison action and create a Plot/view item.',
        'Mode': 'Choose the plotting interpretation: CV/LSV, EIS Nyquist, Bode real/imag/magnitude/phase, OCP, IV/Tafel, DRT, or generic numeric.',
        'Normalize': 'Apply display normalization to the plotted Y values. This changes the view, not the source data.',
        'Max curves': 'Limit the number of curves plotted at once for readability and speed.',
    }
    if txt in specific:
        return specific[txt]
    if isinstance(widget, ttk.Button):
        return f'Button: {txt}. Click to run this FaradaIQ action.' if txt else 'Button: click to run this FaradaIQ action.'
    if 'Combobox' in cls:
        return 'Choose an option for plotting, filtering, routing, or analysis. The selected value affects the next plot or workflow action.'
    if 'Entry' in cls:
        return 'Input field. Enter or review a path, numeric value, label, metadata item, or workflow setting.'
    if 'Treeview' in cls:
        return 'Structured experiment map/table. Select groups such as point, scan rate, cycle, potential, technique, or saved result.'
    if 'Listbox' in cls:
        return 'Selection list. Choose an item, then use the nearby action buttons or double-click where supported.'
    try:
        if widget.winfo_class() in ('Text', 'ScrolledText'):
            return 'Text/status panel. This shows log messages, summaries, metadata, prompts, or generated context.'
    except Exception:
        pass
    if txt:
        return txt
    return ''


