def _v95_paths_from_plot_view(browser):
    """Return selected Plot/view paths, falling back to the current plotted files or selected tree group."""
    candidates = []
    try:
        sel = browser.plot_view_list.curselection()
        views = list(getattr(browser, '_v69_plot_views', []) or [])
        if sel and int(sel[0]) < len(views):
            v = views[int(sel[0])] or {}
            for key in ('paths', 'files', 'source_paths'):
                vals = v.get(key) if isinstance(v, dict) else None
                if vals:
                    candidates.extend(vals)
            if not candidates and isinstance(v.get('context'), dict):
                for key in ('paths', 'files', 'source_paths'):
                    vals = v.get('context', {}).get(key)
                    if vals: candidates.extend(vals)
    except Exception:
        pass
    if not candidates:
        try: candidates.extend(list(getattr(browser, 'last_plot_paths', []) or []))
        except Exception: pass
    if not candidates:
        try: candidates.extend(list(browser.selected_paths(plottable_only=True) or []))
        except Exception: pass
    out, seen = [], set()
    for p in candidates:
        try:
            pp = Path(p)
            if pp.exists():
                k = str(pp.resolve())
                if k not in seen:
                    seen.add(k); out.append(pp)
        except Exception:
            continue
    return out


def _v95_is_cv_like_path(p):
    try:
        s = str(Path(p).name).lower() + ' ' + str(Path(p).parent).lower()
        if any(tok in s for tok in ('current_vs_potential', 'voltamm', '_cv', 'cv_', 'lsv', 'emon', 'imon')):
            return True
        # Fallback: read small header and check columns.
        try:
            header = Path(p).read_text(encoding='utf-8', errors='ignore')[:4096].lower()
            return (('potential' in header or 'emon' in header or 'voltage' in header) and ('current' in header or 'imon' in header))
        except Exception:
            return False
    except Exception:
        return False


def _v95_selected_cv_paths(browser):
    paths = _v95_paths_from_plot_view(browser)
    try:
        tables = _v70_table_paths(paths)
    except Exception:
        tables = paths
    cv = [Path(p) for p in tables if _v95_is_cv_like_path(p)]
    if not cv:
        # If the current Plot/view kind is CV, pass numeric table files even if the names are generic.
        try:
            kind = _v83_current_plot_view_kind(browser) if '_v83_current_plot_view_kind' in globals() else ''
            if 'CV' in str(kind).upper() or 'LSV' in str(kind).upper():
                cv = [Path(p) for p in tables]
        except Exception:
            pass
    try:
        cv = _v89_deduplicate_paths_for_plot(browser, cv, force=_v89_remove_duplicates_enabled(browser))
    except Exception:
        pass
    # Keep stable order and unique paths.
    out, seen = [], set()
    for p in cv:
        try:
            k = str(Path(p).resolve())
            if k not in seen:
                seen.add(k); out.append(Path(p))
        except Exception:
            pass
    return out


