# ---- v96 patch: LLM-driven smart-comparison suggestions using structured metadata ----
APP_TITLE = "FaradaIQ Studio v273"

# In v96, clicking Suggest in the Data Browser asks the selected LLM to propose
# actionable comparison views using the structured metadata, parser data map,
# current tree selection, current Plot/view context, and any human comparison goals.
# If the selected LLM is unavailable, FaradaIQ falls back to the deterministic
# rule-based suggestions so offline analysis remains usable.


def _v96_text_from_widget(widget, max_chars=20000):
    try:
        if widget is None:
            return ''
        if hasattr(widget, 'get'):
            try:
                return str(widget.get('1.0', 'end')).strip()[:max_chars]
            except Exception:
                return str(widget.get()).strip()[:max_chars]
    except Exception:
        pass
    return ''


def _v96_short_path(path, max_len=180):
    try:
        s = str(path)
        if len(s) <= max_len:
            return s
        pp = Path(s)
        parts = pp.parts
        if len(parts) >= 5:
            left = str(Path(*parts[:3]))
            right = str(Path(*parts[-3:]))
            out = left + os.sep + '...' + os.sep + right
            if len(out) <= max_len:
                return out
        return s[:70] + ' ... ' + s[-90:]
    except Exception:
        s = str(path)
        return s[:70] + ' ... ' + s[-90:] if len(s) > max_len else s


def _v96_unique_keep_order(items, limit=12):
    out, seen = [], set()
    for x in items or []:
        s = re.sub(r'\s+', ' ', str(x or '')).strip(' -•\t\r\n')
        if not s:
            continue
        key = s.lower()
        if key not in seen:
            seen.add(key); out.append(s)
        if len(out) >= limit:
            break
    return out


def _v96_selected_tree_snapshot(browser):
    snap = []
    try:
        tree = getattr(browser, 'tree', None)
        if tree is None:
            return snap
        sels = list(tree.selection() or [])
        for iid in sels[:12]:
            try:
                item = tree.item(iid)
                parent_chain = []
                cur = iid
                while cur:
                    txt = str(tree.item(cur, 'text') or '')
                    if txt:
                        parent_chain.append(txt)
                    cur = tree.parent(cur)
                snap.append({
                    'text': item.get('text', ''),
                    'values': list(item.get('values', []) or []),
                    'path_in_tree': list(reversed(parent_chain)),
                    'child_count': len(tree.get_children(iid)),
                })
            except Exception:
                pass
    except Exception:
        pass
    return snap


def _v96_inventory_from_records(browser, max_records=5000):
    inv = {
        'n_records_seen': 0,
        'technique_counts': {},
        'scan_rates': [],
        'points': [],
        'cycles': [],
        'potentials_or_biases': [],
        'representative_files': [],
    }
    scan, points, cycles, potentials, reps = set(), set(), set(), set(), []
    try:
        records = _v91_records(browser) if '_v91_records' in globals() else list(getattr(browser, '_v80_records', []) or [])
        inv['n_records_seen'] = len(records)
        for r in records[:max_records]:
            try:
                kind = _v80_kind(r) if '_v80_kind' in globals() else str(r.get('technique') or r.get('kind') or 'Unknown')
                inv['technique_counts'][kind] = inv['technique_counts'].get(kind, 0) + 1
                for k in ['scan_rate', 'scan_rate_mV_s', 'scan rate', 'rate']:
                    if r.get(k) not in (None, ''):
                        scan.add(str(r.get(k))); break
                for k in ['point', 'point_idx', 'position', 'position_idx', 'measurement_index']:
                    if r.get(k) not in (None, ''):
                        val = str(r.get(k))
                        if k == 'measurement_index':
                            # Only use measurement_index as a point hint for non-CV point reports; it is often the curve number for individual CV rows.
                            title = str(r.get('measurement_title') or '')
                            if 'point' not in title.lower():
                                continue
                        points.add(val); break
                for k in ['cycle', 'cycle_idx', 'cycles', 'n_cycles']:
                    if r.get(k) not in (None, ''):
                        cycles.add(str(r.get(k))); break
                name = str(r.get('relative_csv_path') or r.get('path') or r.get('filename') or '')
                m = re.search(r'(?:^|[_\-\s])(?:E|V|bias|potential)([-+]?\d+(?:\.\d+)?)\s*(mV|V)?', name, flags=re.I)
                if m:
                    potentials.add((m.group(1) + ' ' + (m.group(2) or '')).strip())
                if len(reps) < 24:
                    p = r.get('path') or r.get('relative_csv_path') or r.get('filename') or ''
                    if p:
                        reps.append(_v96_short_path(p, max_len=140))
            except Exception:
                pass
    except Exception:
        pass
    try:
        # Prefer rich CV metadata when available.
        for p in list(getattr(browser, 'last_plot_paths', []) or [])[:300]:
            try:
                info = _v89_cv_info_for_path(browser, Path(p)) if '_v89_cv_info_for_path' in globals() else {}
                if info.get('label'): scan.add(str(info.get('label')))
                if info.get('point_idx'): points.add(f"point {int(info.get('point_idx')):02d}")
                if info.get('cycle_idx'): cycles.add(f"cycle {int(info.get('cycle_idx'))}")
            except Exception:
                pass
    except Exception:
        pass
    keynum = (lambda s: (_v80_num(s), _v80_nat_key(s))) if '_v80_num' in globals() and '_v80_nat_key' in globals() else (lambda s: str(s))
    inv['scan_rates'] = sorted(scan, key=keynum)[:50]
    inv['points'] = sorted(points, key=keynum)[:80]
    inv['cycles'] = sorted(cycles, key=keynum)[:20]
    inv['potentials_or_biases'] = sorted(potentials, key=keynum)[:40]
    inv['representative_files'] = _v96_unique_keep_order(reps, limit=24)
    return inv


def _v96_plot_view_snapshot(browser):
    views = []
    try:
        raw = list(getattr(browser, '_v69_plot_views', []) or getattr(browser, 'plot_views', []) or [])
        for i, v in enumerate(raw[:30], 1):
            if isinstance(v, dict):
                paths = v.get('paths') or v.get('files') or []
                views.append({
                    'index': i,
                    'name': v.get('name') or v.get('title') or f'view {i}',
                    'kind': v.get('kind') or v.get('type') or '',
                    'n_files': len(paths) if isinstance(paths, (list, tuple)) else '',
                })
            else:
                views.append({'index': i, 'repr': str(v)[:200]})
    except Exception:
        pass
    try:
        lb = getattr(browser, 'plot_view_list', None)
        if lb is not None and not views:
            for i in range(min(lb.size(), 30)):
                views.append({'index': i+1, 'name': lb.get(i)})
    except Exception:
        pass
    return views


def _v96_current_browser_context(browser):
    md = {}
    try:
        md = _v92_load_browser_metadata(browser) if '_v92_load_browser_metadata' in globals() else {}
    except Exception:
        md = {}
    try:
        fallback = _v91_builtin_suggestions(browser) if '_v91_builtin_suggestions' in globals() else []
    except Exception:
        fallback = []
    ctx = {
        'schema_version': 'FaradaIQ smart-comparison LLM context v96',
        'created': datetime.now().isoformat(timespec='seconds'),
        'analysis_root': _v96_short_path(getattr(browser, 'analyzed_root', '') or getattr(browser, 'analysis_root', '') or ''),
        'data_folder': _v96_short_path(getattr(browser, 'folder', '') or ''),
        'structured_metadata': md,
        'detected_inventory': _v96_inventory_from_records(browser),
        'selected_experiment_map_nodes': _v96_selected_tree_snapshot(browser),
        'plot_views': _v96_plot_view_snapshot(browser),
        'current_plot_context': {
            'last_plot_files': [_v96_short_path(p) for p in list(getattr(browser, 'last_plot_paths', []) or [])[:40]],
            'plot_mode': _v89_var_get(browser, 'plot_mode_var', 'Auto') if '_v89_var_get' in globals() else 'Auto',
            'cycle_filter': _v89_var_get(browser, 'cycle_filter_var', 'All cycles') if '_v89_var_get' in globals() else '',
            'legend_mode': _v89_var_get(browser, 'legend_mode_var', '') if '_v89_var_get' in globals() else '',
            'remove_exact_duplicates': bool(_v89_var_get(browser, 'remove_duplicates_var', False)) if '_v89_var_get' in globals() else False,
        },
        'quick_summary': _v96_text_from_widget(getattr(browser, 'quick_summary_text', None), max_chars=12000),
        'browser_log_tail': _v96_text_from_widget(getattr(browser, 'log_text', None), max_chars=8000)[-8000:],
        'rule_based_fallback_suggestions': fallback[:12],
    }
    return ctx


def _v96_build_llm_suggest_messages(browser, ctx):
    system = (
        'You are FaradaIQ Studio smart-comparison planner for electrochemical and multi-technique datasets. '
        'Use ONLY the supplied FaradaIQ data structure, metadata, browser selection, and plot context. '
        'Return actionable comparison suggestions that FaradaIQ can execute. Do not invent measurements or conditions. '
        'Prefer comparisons that create plot/view items: CV scan-rate overlays, CV cycle overlays, point-to-point CV comparisons, '
        'EIS Nyquist/Bode comparisons by point or potential, DRT comparisons only when DRT/EIS data exist, and PySimpleEChem handoff for CV metrics. '
        'If metadata are missing, include one suggestion to collect/refresh metadata rather than making unsupported claims. '
        'Every suggestion should be concise and begin with an action verb such as Plot, Compare, Overlay, Open PySimpleEChem, Export, or Refresh metadata. '
        'Make suggestions compatible with FaradaIQ apply logic by including keywords like CV, EIS, Nyquist, Bode real, Bode imag, Bode mag, phase, DRT, cycle, scan rate, point, or PySimpleEChem. '
        'Return JSON only, in this exact shape: {"suggestions":["...", "..."]}. Return 5 to 10 suggestions.'
    )
    user = (
        'Create FaradaIQ Smart Comparison suggestions from this current dataset context.\n\n'
        + json.dumps(ctx, ensure_ascii=False, indent=2, default=str)[:120000]
    )
    return [{'role':'system','content':system}, {'role':'user','content':user}]


def _v96_parse_llm_suggestions(text):
    raw = str(text or '').strip()
    if not raw:
        return []
    # Remove markdown fences if a model adds them despite JSON-only instructions.
    raw2 = re.sub(r'^```(?:json)?\s*|\s*```$', '', raw.strip(), flags=re.I|re.S).strip()
    candidates = []
    try:
        obj = json.loads(raw2)
        if isinstance(obj, dict):
            obj = obj.get('suggestions') or obj.get('actions') or obj.get('comparisons') or []
        if isinstance(obj, list):
            for x in obj:
                if isinstance(x, dict):
                    val = x.get('label') or x.get('suggestion') or x.get('action') or x.get('title') or json.dumps(x, ensure_ascii=False)
                else:
                    val = x
                candidates.append(str(val))
    except Exception:
        # Try to extract an embedded JSON object/list.
        m = re.search(r'\{.*\}', raw2, flags=re.S)
        if m:
            try:
                obj = json.loads(m.group(0))
                vals = obj.get('suggestions') if isinstance(obj, dict) else obj
                if isinstance(vals, list):
                    candidates.extend(str(v.get('suggestion') if isinstance(v, dict) else v) for v in vals)
            except Exception:
                pass
    if not candidates:
        for line in raw.splitlines():
            line = re.sub(r'^\s*(?:[-*•]|\d+[.)])\s*', '', line).strip()
            if line and len(line) > 8 and not line.lower().startswith(('json', '{', '}', '[')):
                candidates.append(line)
    # Keep only useful action-style strings.
    good = []
    for s in candidates:
        s = re.sub(r'\s+', ' ', str(s or '')).strip(' -•\t\r\n"')
        if not s or len(s) < 8:
            continue
        if len(s) > 220:
            s = s[:217].rstrip() + '...'
        good.append(s)
    return _v96_unique_keep_order(good, limit=10)


def _v96_fill_suggestion_widgets(browser, suggestions, source='LLM'):
    suggestions = _v96_unique_keep_order(suggestions, limit=12)
    if not suggestions:
        suggestions = ['Plot selected grouped data and create a Plot/view item.']
    try:
        browser.suggestions = list(suggestions)
    except Exception:
        pass
    for attr in ['right_comp_list']:
        try:
            lb = getattr(browser, attr, None)
            if lb is not None:
                lb.delete(0, 'end')
                for s in suggestions:
                    lb.insert('end', s)
        except Exception:
            pass
    try:
        if getattr(browser, 'quick_summary_text', None) is not None:
            existing = browser.quick_summary_text.get('1.0', 'end').strip()
            note = f'Smart suggestions source: {source}. {len(suggestions)} action(s) ready. Select one and click Apply / add to Plot-view.'
            text = (existing + '\n\n' + note).strip() if existing else note
            browser.quick_summary_text.delete('1.0', 'end')
            browser.quick_summary_text.insert('1.0', text)
    except Exception:
        pass
    try:
        browser.log(f'Smart comparison suggestions updated from {source}: {len(suggestions)} action(s).')
    except Exception:
        pass
    return suggestions


def _v96_save_llm_suggestion_artifacts(browser, ctx, prompt_messages, response, suggestions, provider=None, error=None):
    try:
        root = Path(getattr(browser, 'analyzed_root', '') or getattr(browser, 'analysis_root', '') or getattr(browser, 'folder', '.') or '.')
        outdir = root / 'comparison_tables'
        outdir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        payload = {
            'created': datetime.now().isoformat(timespec='seconds'),
            'provider': provider if isinstance(provider, dict) else (str(provider) if provider else ''),
            'error': str(error) if error else '',
            'context': ctx,
            'prompt_messages': prompt_messages,
            'raw_response': str(response or ''),
            'suggestions': suggestions,
        }
        p = outdir / f'smart_comparison_llm_suggestions_v96_{stamp}.json'
        p.write_text(json.dumps(payload, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
        (outdir / 'smart_comparison_suggestions_latest_v96.txt').write_text('\n'.join(suggestions or []), encoding='utf-8')
        return p
    except Exception:
        return None


def _v96_rule_fallback_suggestions(browser):
    try:
        return list(_v91_builtin_suggestions(browser) or [])
    except Exception:
        try:
            return list(_v80_builtin_suggestions(browser) or [])
        except Exception:
            return ['Plot selected grouped data and create a Plot/view item.']


def _v96_ai_suggest_comparisons(browser):
    fallback = _v96_rule_fallback_suggestions(browser)
    try:
        _v96_fill_suggestion_widgets(browser, ['Asking selected LLM for smart comparisons using data structure + structured metadata...'] + fallback[:4], source='LLM pending')
    except Exception:
        pass
    try:
        browser.log('Sending data structure, structured metadata, current selection, Plot/view context, and comparison goals to selected LLM for Smart comparisons...')
    except Exception:
        pass

    def worker():
        ctx = {}
        messages = []
        try:
            ctx = _v96_current_browser_context(browser)
            messages = _v96_build_llm_suggest_messages(browser, ctx)
            response, provider = _v37_call_best_llm(messages, max_tokens=2200, temperature=0.15)
            suggestions = _v96_parse_llm_suggestions(response)
            if not suggestions:
                suggestions = fallback
                source = 'rule-based fallback after empty LLM response'
            else:
                # Keep fallback safety actions if the LLM missed obvious pathways.
                for s in fallback:
                    if len(suggestions) >= 10:
                        break
                    if s not in suggestions:
                        suggestions.append(s)
                pname = provider.get('name', 'selected LLM') if isinstance(provider, dict) else 'selected LLM'
                source = pname
            _v96_save_llm_suggestion_artifacts(browser, ctx, messages, response, suggestions, provider=provider)
            browser.after(0, lambda: _v96_fill_suggestion_widgets(browser, suggestions, source=source))
        except Exception as exc:
            try:
                _v96_save_llm_suggestion_artifacts(browser, ctx, messages, '', fallback, error=exc)
            except Exception:
                pass
            def fail():
                _v96_fill_suggestion_widgets(browser, fallback, source='rule-based fallback; LLM unavailable')
                try:
                    browser.log(f'LLM smart-comparison suggestion failed; using rule-based fallback. Open LLM settings and ping selected provider if needed. Error: {exc}')
                except Exception:
                    pass
            try:
                browser.after(0, fail)
            except Exception:
                pass
    threading.Thread(target=worker, daemon=True).start()
    return fallback


