# ---- v100 patch: AI Chat live LLM processing status ----

def _v100_now_seconds():
    try:
        return time.time()
    except Exception:
        return 0.0


def _v100_format_elapsed(t0):
    try:
        sec = max(0.0, time.time() - float(t0))
        if sec < 60:
            return f'{sec:0.1f} s'
        m, s = divmod(int(sec), 60)
        return f'{m:d} min {s:02d} s'
    except Exception:
        return ''


class FaradaIQAIChatWindowV100(FaradaIQAIChatWindowV98):
    """AI chat window with explicit live LLM processing/status stages.

    FaradaIQ does not receive hidden chain-of-thought from LLM providers. The
    live "thinking" status shown here means the request has been sent and the
    provider/model is generating a response. Only the final answer is returned.
    """

    def _build_ui(self):
        super()._build_ui()
        try:
            # Insert a live-processing panel immediately after the existing status label
            # by packing it before the visible context summary frame if possible.
            self.live_stage_var = tk.StringVar(value='LLM live status: idle')
            self.live_elapsed_var = tk.StringVar(value='')
            self.live_detail_var = tk.StringVar(value='Ready. No request is currently running.')
            self._llm_busy = False
            self._llm_t0 = None

            # Find the top-level content frame created by super()._build_ui().
            outer = None
            for child in self.winfo_children():
                try:
                    if str(child.winfo_class()).lower() in ('tframe', 'frame'):
                        outer = child
                        break
                except Exception:
                    pass
            if outer is None:
                outer = ttk.Frame(self, padding=(10, 0))
                outer.pack(fill='x')

            self.live_frame = ttk.LabelFrame(outer, text='LLM live processing status')
            # Repack order is hard to control in cumulative script; putting it after
            # status/context is still visible and avoids layout breakage.
            self.live_frame.pack(fill='x', pady=(0, 8), after=None)
            row = ttk.Frame(self.live_frame)
            row.pack(fill='x', padx=6, pady=(4, 2))
            ttk.Label(row, textvariable=self.live_stage_var, style='Section.TLabel').pack(side='left', fill='x', expand=True)
            ttk.Label(row, textvariable=self.live_elapsed_var, style='Muted.TLabel').pack(side='right')
            self.live_progress = ttk.Progressbar(self.live_frame, mode='indeterminate')
            self.live_progress.pack(fill='x', padx=6, pady=(0, 3))
            ttk.Label(self.live_frame, textvariable=self.live_detail_var, style='Muted.TLabel', wraplength=940, justify='left').pack(fill='x', padx=6, pady=(0, 5))
            try:
                _v100_apply_chat_theme(self)
                if '_v80_reapply_fonts' in globals(): _v80_reapply_fonts(self)
            except Exception:
                pass
        except Exception:
            # Do not block chat if the status panel cannot be inserted.
            pass

    def _set_live_status(self, stage, detail='', busy=None):
        try:
            if not hasattr(self, 'live_stage_var'):
                return
            if busy is not None:
                self._llm_busy = bool(busy)
                if busy:
                    self._llm_t0 = _v100_now_seconds()
                    try: self.live_progress.start(12)
                    except Exception: pass
                    self._tick_live_elapsed()
                else:
                    try: self.live_progress.stop()
                    except Exception: pass
            self.live_stage_var.set(f'LLM live status: {stage}')
            if detail:
                self.live_detail_var.set(detail)
            if not self._llm_busy:
                self.live_elapsed_var.set('')
        except Exception:
            pass

    def _tick_live_elapsed(self):
        try:
            if getattr(self, '_llm_busy', False):
                self.live_elapsed_var.set('Elapsed: ' + _v100_format_elapsed(getattr(self, '_llm_t0', _v100_now_seconds())))
                self.after(350, self._tick_live_elapsed)
        except Exception:
            pass

    def _explain_thinking_once(self):
        try:
            if getattr(self, '_v100_thinking_note_shown', False):
                return
            self._v100_thinking_note_shown = True
            self._append(
                'FaradaIQ',
                'LLM status note: “Thinking” means FaradaIQ has sent the request and is waiting for the selected provider/model to generate its final response. Hidden chain-of-thought is not exposed by the model or stored by FaradaIQ; only the final answer is returned.'
            )
        except Exception:
            pass

    def refresh_context(self, auto=False):
        try:
            lim = {'35k':35000, '70k':70000, '120k':120000}.get(self.max_context_var.get(), 70000)
        except Exception:
            lim = 70000
        self.status_var.set('Refreshing live FaradaIQ data context...')
        self._set_live_status('preparing context', 'Reading current source path, structured metadata, parser output tree, AI bundle hints, and open Data Browser plot/view state.', busy=True)
        def work():
            try:
                self.after(0, lambda: self._set_live_status('summarizing data context', 'Building the compact “what is shared with the LLM” map and detailed context snapshot.'))
                manifest = _v100_context_manifest(self.gui)
                ctx = _v93_build_ai_chat_context(self.gui, max_chars=lim)
                self.context_manifest_text = manifest
                self.context_text = manifest + '\n\n===== DETAILED FARADAIQ CONTEXT =====\n' + ctx
                def finish():
                    self._set_context_summary(manifest)
                    self.status_var.set(f'Context ready: {len(self.context_text):,} characters from current data/session/browser state.')
                    self._set_live_status('idle', f'Context ready. {len(self.context_text):,} characters are available for the next chat turn.', busy=False)
                    if not auto:
                        self._append('FaradaIQ', f'Live context refreshed ({len(self.context_text):,} characters).')
                self.after(0, finish)
            except Exception as exc:
                self.after(0, lambda: (self.status_var.set(f'Context refresh failed: {exc}'), self._set_live_status('context refresh failed', str(exc), busy=False)))
        threading.Thread(target=work, daemon=True).start()

    def send_message(self):
        user_text = self.input.get('1.0','end').strip()
        if not user_text:
            return
        self.input.delete('1.0','end')
        self._append('You', user_text)
        self.history.append({'role':'user', 'content':user_text})
        include_context = bool(self.include_context_var.get())
        self.status_var.set('Preparing LLM request...')
        self._set_live_status('preparing request', 'Collecting chat history and deciding whether to attach the current FaradaIQ data context.', busy=True)
        context = self.context_text if include_context else ''
        # Refresh stale/empty context automatically when requested.
        if include_context and not context:
            try:
                self._set_live_status('building context', 'No cached context was available, so FaradaIQ is building one before sending.')
                lim = {'35k':35000, '70k':70000, '120k':120000}.get(self.max_context_var.get(), 70000)
                manifest = _v100_context_manifest(self.gui)
                ctx = _v93_build_ai_chat_context(self.gui, max_chars=lim)
                context = manifest + '\n\n===== DETAILED FARADAIQ CONTEXT =====\n' + ctx
                self.context_text = context
                self.context_manifest_text = manifest
                self._set_context_summary(manifest)
            except Exception as exc:
                context = ''
                self._set_live_status('context unavailable', f'Continuing without attached context because context creation failed: {exc}')
        system = (
            'You are FaradaIQ Studio AI chat. Answer as an electrochemical data-analysis assistant. '
            'Use the provided FaradaIQ live context for the current loaded/processed data, parsed outputs, structured metadata, AI bundle, and Data Browser plot/view state. '
            'Do not invent measurements. If data or metadata are missing, state that and suggest the next FaradaIQ action. '
            'When useful, give concrete actions the user can take in FaradaIQ, and keep numeric claims tied to the provided context.'
        )
        context_msg = 'FARADAIQ LIVE CONTEXT FOR THIS CHAT TURN:\n' + (context or '(Context not attached.)')
        history = self.history[-10:]
        messages = [{'role':'system','content':system}, {'role':'user','content':context_msg}] + history
        def work():
            try:
                self.after(0, lambda: self._set_live_status('sending request', 'Calling the selected FaradaIQ LLM provider/model with the current message and attached context.'))
                # The underlying FaradaIQ LLM call is non-streaming, so while this runs
                # FaradaIQ can show elapsed/waiting status but cannot display hidden chain-of-thought.
                self.after(500, lambda: (self._set_live_status('thinking / waiting for model', 'The selected LLM is generating a response. FaradaIQ does not receive or show hidden chain-of-thought; it only receives the final answer.'), self._explain_thinking_once()))
                answer, conn = _v37_call_best_llm(messages, max_tokens=3200, temperature=0.18)
                self.after(0, lambda: self._set_live_status('response received', 'Final response returned by the provider. Formatting and saving transcript now.'))
                answer = str(answer or '').strip()
                self.history.append({'role':'assistant', 'content':answer})
                def finish():
                    try:
                        provider = conn.get('name','LLM'); model = conn.get('model','')
                        self.llm_var.set(f'AI chat using: {provider} | {model}')
                    except Exception: pass
                    self._append('AI', answer)
                    self.status_var.set('Ready')
                    try:
                        folder = _v93_chat_save_dir(self.gui)
                        autosave = folder / 'FaradaIQ_AI_chat_latest.txt'
                        autosave.write_text(self.chat.get('1.0','end') + '\n\n===== CONTEXT SNAPSHOT =====\n' + (self.context_text or ''), encoding='utf-8')
                        self._set_live_status('ready', f'Response displayed and latest transcript autosaved to {autosave}', busy=False)
                    except Exception:
                        self._set_live_status('ready', 'Response displayed. Transcript autosave was skipped or failed.', busy=False)
                self.after(0, finish)
            except Exception as exc:
                def fail():
                    self._append('FaradaIQ', f'LLM call failed: {exc}\nOpen LLM settings, ping/select a provider, or start the LiteLLM proxy if using AWS Bedrock.')
                    self.status_var.set('LLM call failed')
                    self._set_live_status('LLM call failed', str(exc), busy=False)
                self.after(0, fail)
        threading.Thread(target=work, daemon=True).start()


