# ---- v100 patch: tooltip target filtering ----
APP_TITLE = "FaradaIQ Studio v273"

# Tooltip policy: only attach to actual controls or the visible text label/name of a
# field/box. Do not attach tooltips to broad frames/labelframes/panes/canvases,
# because those fire when hovering over empty space inside large sections such as
# the pySECCM / DRT runners box.

def _v100_widget_class(widget):
    try:
        return str(widget.winfo_class())
    except Exception:
        return ''


def _v100_widget_text(widget):
    try:
        return str(widget.cget('text')).strip()
    except Exception:
        return ''


def _v100_is_tooltip_target(widget):
    try:
        cls = _v100_widget_class(widget)
        txt = _v100_widget_text(widget)
        # Explicitly reject broad containers and plot canvases. These are the
        # source of tooltip popups over blank/empty GUI space.
        blocked = {
            'Frame','TFrame','Labelframe','TLabelframe','LabelFrame',
            'Panedwindow','TPanedwindow','Toplevel','Tk','Canvas',
            'Scrollbar','TScrollbar','Separator','TSeparator','Sizegrip','TSizegrip'
        }
        if cls in blocked:
            return False
        # Real interactive controls.
        if cls in {
            'Button','TButton','Checkbutton','TCheckbutton','Radiobutton','TRadiobutton',
            'Menubutton','TMenubutton','Entry','TEntry','Combobox','TCombobox',
            'Spinbox','TSpinbox','Scale','TScale'
        }:
            return True
        # Label/name text only. A plain label is small and represents the box name;
        # the surrounding frame remains tooltip-free.
        if cls in {'Label','TLabel'} and txt:
            return True
        # Some ttk widgets report variant names; keep the check narrow but robust.
        low = cls.lower()
        if any(k in low for k in ('button','checkbutton','radiobutton','combobox','spinbox')):
            return True
        if low.endswith('label') and txt and 'frame' not in low:
            return True
    except Exception:
        pass
    return False


# Keep the original tooltip helper available for debugging, then replace it with a
# filtered version used by all v66/v95/v96 tooltip passes.
try:
    _v100_unfiltered_add_tooltip = _v66_add_tooltip
except Exception:
    _v100_unfiltered_add_tooltip = None


def _v100_add_tooltip(widget, text):
    try:
        if widget is None or not text:
            return
        if not _v100_is_tooltip_target(widget):
            # Also remove an accidental old tooltip binding marker if a future
            # patch tries to bind a container before this filter runs.
            try:
                if getattr(widget, '_faradaiq_tooltip_added', False) and _v100_widget_class(widget) in {'Frame','TFrame','Labelframe','TLabelframe'}:
                    widget._faradaiq_tooltip_added = False
            except Exception:
                pass
            return
        if not getattr(widget, '_faradaiq_tooltip_added', False):
            widget._faradaiq_tooltip_added = True
            widget._faradaiq_tooltip = _FaradaIQTooltip(widget, text)
    except Exception:
        pass


def _v100_apply_tooltips(root):
    try:
        def walk(w):
            yield w
            try:
                for c in w.winfo_children():
                    yield from walk(c)
            except Exception:
                pass
        for w in walk(root):
            if not _v100_is_tooltip_target(w):
                continue
            tip = ''
            try:
                if '_v95_tooltip_text' in globals():
                    tip = _v95_tooltip_text(w) or ''
            except Exception:
                tip = ''
            if not tip:
                try:
                    txt = _v100_widget_text(w)
                    tip = _V66_TOOLTIP_TEXT.get(txt, '') if '_V66_TOOLTIP_TEXT' in globals() else ''
                except Exception:
                    tip = ''
            if tip:
                _v100_add_tooltip(w, tip)
    except Exception:
        pass


try:
    _v66_add_tooltip = _v100_add_tooltip
    _v66_apply_tooltips = _v100_apply_tooltips
    _v95_apply_tooltips = _v100_apply_tooltips
except Exception:
    pass

# Make already-created tooltip instances conservative too: if a container somehow
# inherited a tooltip binding, it will not show over empty space.
try:
    _v100_old_tooltip_schedule = _FaradaIQTooltip._schedule
    def _v100_tooltip_schedule(self, event=None):
        try:
            if not _v100_is_tooltip_target(getattr(self, 'widget', None)):
                return
        except Exception:
            return
        return _v100_old_tooltip_schedule(self, event)
    _FaradaIQTooltip._schedule = _v100_tooltip_schedule
except Exception:
    pass


def _v100_main():
    try: _v83_set_windows_app_id()
    except Exception: pass
    try: _v753_track_event('python_module_ready', {'version':"v273", 'feature':'tooltip target filtering for controls and box-name labels only'})
    except Exception: pass
    try:
        global APP_TITLE
        APP_TITLE = "FaradaIQ Studio v273"
    except Exception:
        pass
    _v80_main()

