def _v101_now_label():
    try:
        return datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
    except Exception:
        try: return _v93_now_label()
        except Exception: return 'now'


def _v101_json_safe(obj, depth=0):
    if depth > 6:
        return str(obj)[:300]
    try:
        if obj is None or isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, Path):
            return str(obj)
        if isinstance(obj, dict):
            return {str(k): _v101_json_safe(v, depth+1) for k, v in list(obj.items())[:200]}
        if isinstance(obj, (list, tuple, set)):
            return [_v101_json_safe(v, depth+1) for v in list(obj)[:500]]
    except Exception:
        pass
    return str(obj)[:1000]


def _v101_short_path(p, max_len=118):
    try:
        s = str(p)
        if len(s) <= max_len:
            return s
        parts = Path(s).parts
        if len(parts) >= 5:
            head = str(Path(*parts[:3]))
            tail = str(Path(*parts[-3:]))
            return f'{head}\\...\\{tail}'
        return s[:55] + ' ... ' + s[-55:]
    except Exception:
        s = str(p)
        return s[:max_len]


def _v101_analysis_roots(gui):
    roots = []
    try:
        if '_v93_analysis_roots_for_gui' in globals():
            roots += [Path(r).resolve() for r in _v93_analysis_roots_for_gui(gui) if r]
    except Exception:
        pass
    for attr in ('output_dir_var','input_path_var','file_path_var','folder_var'):
        try:
            val = getattr(gui, attr).get().strip()
            if val:
                p=Path(val)
                roots.append((p if p.is_dir() else p.parent).resolve())
        except Exception:
            pass
    out=[]; seen=set()
    for r in roots:
        try:
            if r.exists():
                key=str(r).lower()
                if key not in seen:
                    out.append(r); seen.add(key)
        except Exception:
            pass
    return out[:8]


def _v101_file_kind(path):
    path = Path(path)
    name = path.name.lower()
    suf = path.suffix.lower()
    if suf in ('.png','.jpg','.jpeg','.tif','.tiff','.bmp','.gif','.webp','.svg'):
        return 'figure/image'
    if suf in ('.csv','.txt','.asc','.dat','.par','.cor','.xls','.xlsx','.ods'):
        if any(k in name for k in ('freq_zreal_zimag','fulleis','eis','nyquist','bode','impedance')): return 'EIS numeric/table'
        if any(k in name for k in ('cv','current_vs_potential','cyclic','voltam')): return 'CV numeric/table'
        if any(k in name for k in ('drt','gamma','tau')): return 'DRT numeric/table'
        if any(k in name for k in ('ocp','open_circuit')): return 'OCP numeric/table'
        if any(k in name for k in ('tafel','iv','polarization')): return 'IV/Tafel numeric/table'
        return 'numeric/text table'
    if suf in ('.json','.jsonl'):
        return 'metadata/json'
    if suf in ('.npy','.npz','.h5','.hdf5'):
        return 'binary parsed data'
    if suf in ('.md','.log'):
        return 'text/log'
    return 'other'


def _v101_folder_inventory(root, max_files=800):
    root=Path(root)
    files=[]; counts={}; total=0; sizes=0
    try:
        candidates=[]
        for p in root.rglob('*'):
            if not p.is_file():
                continue
            low=str(p).lower()
            if any(skip in low for skip in ('__pycache__', '.git', 'faradaiq_launch_sessions')):
                continue
            candidates.append(p)
        def score(p):
            k=_v101_file_kind(p)
            pri={'metadata/json':0,'CV numeric/table':1,'EIS numeric/table':2,'DRT numeric/table':3,'numeric/text table':4,'figure/image':7,'binary parsed data':8}.get(k,6)
            return (pri, len(str(p)), str(p).lower())
        candidates=sorted(candidates, key=score)
        for p in candidates:
            total += 1
            try: sizes += p.stat().st_size
            except Exception: pass
            kind=_v101_file_kind(p)
            counts[kind]=counts.get(kind,0)+1
            if len(files) < max_files:
                try: rel=str(p.relative_to(root))
                except Exception: rel=str(p)
                try: size=p.stat().st_size
                except Exception: size=None
                files.append({'relative_path':rel, 'kind':kind, 'size_bytes':size})
    except Exception as exc:
        return {'root':str(root), 'error':str(exc), 'files':[], 'counts':{}}
    return {'root':str(root), 'total_files':total, 'total_size_bytes':sizes, 'counts':counts, 'files':files}


def _v101_table_summary(path, max_rows=1200):
    path=Path(path)
    out={'path':str(path), 'kind':_v101_file_kind(path)}
    try:
        txt=path.read_text(encoding='utf-8', errors='ignore')[:250000]
        lines=[ln for ln in txt.splitlines() if ln.strip()]
        out['n_text_lines_sampled']=len(lines)
        if not lines:
            return out
        header_idx=0
        for i,ln in enumerate(lines[:80]):
            low=ln.lower()
            if any(k in low for k in ('potential','current','emon','imon','freq','zreal','zimag','realz','imagz','impz','phase')):
                header_idx=i; break
        header=lines[header_idx]
        sep='\t' if '\t' in header else (',' if ',' in header else None)
        cols=[c.strip() for c in (header.split(sep) if sep else re.split(r'\s+', header.strip())) if c.strip()]
        out['columns']=cols[:30]
        numeric={}; rows=0
        for ln in lines[header_idx+1:header_idx+1+max_rows]:
            parts=[c.strip() for c in (ln.split(sep) if sep else re.split(r'\s+', ln.strip()))]
            if len(parts)<2: continue
            rows += 1
            for ci,val in enumerate(parts[:min(len(cols),len(parts),12)]):
                try:
                    x=float(str(val).replace(',',''))
                    key=cols[ci] if ci < len(cols) else f'col{ci+1}'
                    numeric.setdefault(key, []).append(x)
                except Exception:
                    pass
        out['n_numeric_rows_sampled']=rows
        stats={}
        for k,vals in numeric.items():
            if len(vals)>=3:
                stats[k]={'n':len(vals),'min':min(vals),'max':max(vals),'mean':sum(vals)/len(vals)}
        out['numeric_stats']=stats
    except Exception as exc:
        out['error']=str(exc)
    return out


def _v101_collect_metric_tables(root, max_tables=24):
    root=Path(root)
    results=[]
    try:
        candidates=[]
        for p in root.rglob('*'):
            if not p.is_file(): continue
            if p.suffix.lower() not in ('.csv','.txt','.asc'):
                continue
            kind=_v101_file_kind(p)
            if kind in ('CV numeric/table','EIS numeric/table','DRT numeric/table','OCP numeric/table','IV/Tafel numeric/table'):
                candidates.append(p)
        def score(p):
            n=p.name.lower(); k=_v101_file_kind(p)
            return ({'CV numeric/table':1,'EIS numeric/table':2,'DRT numeric/table':3}.get(k,5), 0 if any(s in n for s in ('summary','combined','peak','freq_zreal_zimag')) else 1, len(str(p)))
        for p in sorted(candidates, key=score)[:max_tables]:
            s=_v101_table_summary(p)
            try: s['relative_path']=str(p.relative_to(root))
            except Exception: pass
            results.append(s)
    except Exception as exc:
        results.append({'error':str(exc)})
    return results


def _v101_find_current_browser(gui):
    try:
        browsers = _v93_find_open_browsers(gui) if '_v93_find_open_browsers' in globals() else []
        for b in browsers:
            try:
                if b.winfo_exists(): return b
            except Exception: pass
    except Exception:
        pass
    return None


def _v101_current_plotview_pack(gui):
    b=_v101_find_current_browser(gui)
    if b is None:
        return {'available': False, 'reason':'No Data Browser is currently open.'}
    pack={'available': True}
    try:
        views=getattr(b,'_v69_plot_views',[]) or []
        sel=[]
        try: sel=list(b.plot_view_list.curselection())
        except Exception: sel=[]
        idx=sel[0] if sel else (len(views)-1 if views else None)
        pack['n_plot_views']=len(views)
        if idx is not None and 0 <= idx < len(views):
            v=views[idx]
            pack['selected_index']=idx
            pack['selected_view']=_v101_json_safe(v)
            paths=v.get('paths') or v.get('files') or []
            pack['selected_paths']=[str(p) for p in paths[:60]]
            summaries=[]
            for p in paths[:10]:
                try:
                    pp=Path(p)
                    if pp.exists() and pp.suffix.lower() in ('.csv','.txt','.asc'):
                        summaries.append(_v101_table_summary(pp, max_rows=500))
                except Exception: pass
            pack['selected_file_summaries']=summaries
        else:
            pack['selected_view']=None
        pack['browser_settings']={
            'plot_mode': getattr(getattr(b,'plot_mode_var',None),'get',lambda:'')(),
            'cycle_filter': getattr(getattr(b,'cycle_filter_var',None),'get',lambda:'')(),
            'legend_mode': getattr(getattr(b,'legend_mode_var',None),'get',lambda:'')(),
            'remove_exact_duplicates': getattr(getattr(b,'remove_duplicates_var',None),'get',lambda:None)(),
        }
    except Exception as exc:
        pack['error']=str(exc)
    return pack


def _v101_build_data_context_pack(gui, save=True):
    roots=_v101_analysis_roots(gui)
    source=''
    for attr in ('input_path_var','file_path_var','folder_var'):
        try:
            v=getattr(gui, attr).get().strip()
            if v: source=v; break
        except Exception: pass
    pack={
        'schema_version':'FaradaIQ_data_context_pack_v101',
        'created': datetime.datetime.now().isoformat(timespec='seconds') if 'datetime' in globals() else _v101_now_label(),
        'purpose':'Compact, provenance-tracked AI context for learning/questions about the current data and results. The LLM sees indexes and summaries; large raw files are summarized locally.',
        'source': source,
        'roots':[str(r) for r in roots],
        'data_used_policy': 'Folder inventory and compact summaries are shared. Raw large files/NPY/HDF5/images are not fully sent unless explicitly sampled by a FaradaIQ tool.',
        'folder_inventories': [],
        'metric_tables': [],
        'current_plotview': _v101_current_plotview_pack(gui),
        'structured_metadata_preview':'',
        'session_summary_preview':'',
    }
    try: pack['structured_metadata_preview']=_v93_safe_get_text(gui.structure_text, 20000) if '_v93_safe_get_text' in globals() else ''
    except Exception: pass
    try: pack['session_summary_preview']=_v93_safe_get_text(gui.summary_text, 14000) if '_v93_safe_get_text' in globals() else ''
    except Exception: pass
    for r in roots[:3]:
        pack['folder_inventories'].append(_v101_folder_inventory(r, max_files=500))
        pack['metric_tables'] += _v101_collect_metric_tables(r, max_tables=16)
    pack['available_local_summaries']=[
        'current_plotview numeric summaries','folder inventory by file type','CV/EIS/DRT table column/range summaries','structured metadata and comparison goals','plot/view provenance and selected file list','SciLink handoff exporter for higher-level agent workflows']
    if save and roots:
        try:
            out=Path(roots[0])/'FaradaIQ_AI_data_context_pack'
            out.mkdir(parents=True, exist_ok=True)
            (out/'FaradaIQ_data_context_pack_latest.json').write_text(json.dumps(_v101_json_safe(pack), indent=2), encoding='utf-8')
            (out/f'FaradaIQ_data_context_pack_{_v101_now_label()}.json').write_text(json.dumps(_v101_json_safe(pack), indent=2), encoding='utf-8')
            (out/'FaradaIQ_data_context_pack_latest.txt').write_text(_v101_pack_to_text(pack), encoding='utf-8')
            pack['saved_context_pack_dir']=str(out)
        except Exception as exc:
            pack['save_error']=str(exc)
    return pack


def _v101_pack_to_text(pack, max_chars=60000):
    lines=[]
    lines.append('===== FARADAIQ DATA CONTEXT PACK v216 =====')
    lines.append('Purpose: grounded AI chat for learning/questions about current data and results.')
    lines.append('Data access policy: ' + str(pack.get('data_used_policy','')))
    lines.append('Source: ' + str(pack.get('source','')))
    lines.append('Roots:')
    for r in pack.get('roots',[]): lines.append('  - '+_v101_short_path(r))
    lines.append('\n--- Current Plot/View ---')
    lines.append(json.dumps(_v101_json_safe(pack.get('current_plotview') or {}), indent=2)[:16000])
    lines.append('\n--- Folder Inventory Summary ---')
    for inv in pack.get('folder_inventories',[]):
        lines.append(f"Root: {_v101_short_path(inv.get('root',''))}")
        lines.append(f"Total files: {inv.get('total_files')} | total bytes: {inv.get('total_size_bytes')}")
        lines.append('Counts: '+json.dumps(inv.get('counts',{}), ensure_ascii=False))
        for f in inv.get('files',[])[:80]:
            lines.append(f"  - [{f.get('kind')}] {f.get('relative_path')} ({f.get('size_bytes')} bytes)")
    lines.append('\n--- Metric/Table Summaries ---')
    for t in pack.get('metric_tables',[])[:24]:
        lines.append(json.dumps(_v101_json_safe(t), indent=2)[:5000])
    lines.append('\n--- Structured Metadata Preview ---')
    lines.append(str(pack.get('structured_metadata_preview',''))[:18000])
    lines.append('\n--- Session Summary Preview ---')
    lines.append(str(pack.get('session_summary_preview',''))[:10000])
    text='\n'.join(lines)
    if len(text)>max_chars:
        text=text[:max_chars]+'\n... [Data context pack truncated]'
    return text

try:
    _v101_previous_ai_context_builder = _v93_build_ai_chat_context
except Exception:
    _v101_previous_ai_context_builder = None


def _v101_build_ai_chat_context(gui, max_chars=120000):
    parts=[]
    try:
        pack=_v101_build_data_context_pack(gui, save=True)
        parts.append(_v101_pack_to_text(pack, max_chars=int(max_chars*0.70)))
    except Exception as exc:
        parts.append(f'FaradaIQ v273 Data Context Pack failed: {exc}')
    try:
        if callable(_v101_previous_ai_context_builder):
            old=_v101_previous_ai_context_builder(gui, max_chars=int(max_chars*0.55))
            parts.append('\n===== LEGACY FARADAIQ CONTEXT SNAPSHOT =====\n'+old)
    except Exception as exc:
        parts.append(f'Legacy context unavailable: {exc}')
    text='\n\n'.join(parts)
    if len(text)>max_chars:
        text=text[:max_chars]+'\n... [FaradaIQ v273 AI context truncated]'
    return text

try:
    _v93_build_ai_chat_context = _v101_build_ai_chat_context
except Exception:
    pass


def _v101_data_used_block(gui):
    try:
        pack=_v101_build_data_context_pack(gui, save=False)
        pv=pack.get('current_plotview',{}) or {}
        lines=['\nData used for this answer:']
        if pv.get('available'):
            sv=pv.get('selected_view') or {}
            lines.append(f"- Current Plot/view: {sv.get('name','(selected/latest view)')}")
            lines.append(f"- Plot mode: {(pv.get('browser_settings') or {}).get('plot_mode','')}")
            lines.append(f"- Selected files summarized: {len(pv.get('selected_paths') or [])}")
        else:
            lines.append('- Current Plot/view: none open/selected')
        roots=pack.get('roots') or []
        if roots:
            lines.append(f"- Session/output root indexed: {_v101_short_path(roots[0])}")
        counts={}
        for inv in pack.get('folder_inventories',[])[:1]: counts=inv.get('counts',{}) or {}
        if counts: lines.append('- Folder file-type counts: '+', '.join(f'{k}: {v}' for k,v in counts.items()))
        lines.append('- Method: FaradaIQ v273 compact data context pack; large raw/binary files were indexed/summarized, not fully pasted into the prompt.')
        return '\n'.join(lines)
    except Exception as exc:
        return f'\nData used for this answer: context summary unavailable ({exc}).'


def _v101_make_prefill_prompt(kind='explain'):
    prompts={
        'plot':'Explain the current selected Plot/view using the FaradaIQ data context. Identify the technique, what is being compared, the visible/data-backed trends, useful metrics to extract, missing metadata, and which conclusions are safe versus not yet supported.',
        'trends':'Find data-backed trends in the current FaradaIQ session. Use the plot/view context and metric/table summaries. Prioritize CV scan-rate/cycle/point trends, EIS point or potential trends, and any CV–EIS relationships. State what data was used.',
        'next':'Suggest the next most useful analyses for this dataset. Use the actual detected structure, points, scan rates, cycles, potentials, plot/views, and available metric summaries. Return actionable FaradaIQ steps.',
        'learn':'Teach me the electrochemistry behind the current selected data using my actual FaradaIQ plot/view and metrics. Explain CV/EIS/DRT terms only where relevant to the selected data and identify what I should check next.'}
    return prompts.get(kind, 'Summarize the current FaradaIQ dataset and results using the attached data context pack.')


def _v101_export_scilink_handoff(gui, parent=None):
    roots=_v101_analysis_roots(gui)
    root=roots[0] if roots else Path('.').resolve()
    out=root / f'SciLink_handoff_{_v101_now_label()}'
    out.mkdir(parents=True, exist_ok=True)
    pack=_v101_build_data_context_pack(gui, save=True)
    (out/'faradaiq_data_context_pack.json').write_text(json.dumps(_v101_json_safe(pack), indent=2), encoding='utf-8')
    (out/'faradaiq_data_context_pack.txt').write_text(_v101_pack_to_text(pack, max_chars=120000), encoding='utf-8')
    prompt = """# SciLink task prompt generated by FaradaIQ Studio v273

You are analyzing a FaradaIQ electrochemical session. Use the attached FaradaIQ data context pack, metric summaries, structured metadata, and file inventory. Do not invent measurements. If deeper calculations are needed, request/compute them using FaradaIQ-compatible local tools.

Goals:
1. Summarize the experiment structure and available data.
2. Identify useful CV/EIS/DRT/other-technique comparisons.
3. Extract or request grounded trends from the metric tables.
4. Suggest next experiments or analyses.
5. Distinguish supported observations from hypotheses.

Recommended SciLink use: run literature/novelty/planning or custom FaradaIQ tool workflows on this handoff folder.
"""
    (out/'scilink_task_prompt.md').write_text(prompt, encoding='utf-8')
    bat = r'''@echo off
setlocal
cd /d "%~dp0"
echo FaradaIQ SciLink handoff folder: %CD%
echo.
echo 1) If SciLink is installed, you can run its CLI/tools from this folder.
echo 2) Recommended first checks:
echo      python -m pip show scilink
echo      scilink --help
echo.
echo Suggested task prompt is in scilink_task_prompt.md
echo Data context is in faradaiq_data_context_pack.json and .txt
echo.
cmd /k
'''
    (out/'run_scilink_handoff_here.bat').write_text(bat, encoding='utf-8')
    tool_stub = '''"""FaradaIQ -> SciLink custom-tool bridge stub.

This file is generated with a SciLink handoff. It exposes the FaradaIQ data context
pack and can be extended to call FaradaIQ CV/EIS/DRT summary routines as SciLink tools.
"""
from __future__ import annotations
import json
from pathlib import Path

HANDOFF_DIR = Path(__file__).resolve().parent
CONTEXT_PATH = HANDOFF_DIR / "faradaiq_data_context_pack.json"

def load_faradaiq_context():
    return json.loads(CONTEXT_PATH.read_text(encoding="utf-8"))

def summarize_faradaiq_session():
    ctx = load_faradaiq_context()
    return {
        "schema_version": ctx.get("schema_version"),
        "source": ctx.get("source"),
        "roots": ctx.get("roots", []),
        "current_plotview": ctx.get("current_plotview", {}),
        "folder_counts": [inv.get("counts", {}) for inv in ctx.get("folder_inventories", [])],
        "n_metric_tables": len(ctx.get("metric_tables", [])),
    }

tool_schemas = [{
    "type": "function",
    "function": {
        "name": "summarize_faradaiq_session",
        "description": "Return a compact summary of the FaradaIQ electrochemical session handoff.",
        "parameters": {"type": "object", "properties": {}}
    }
}]
'''
    (out/'faradaiq_scilink_tools.py').write_text(tool_stub, encoding='utf-8')
    try:
        if '_v33_open_folder' in globals(): _v33_open_folder(out)
    except Exception: pass
    try:
        if parent is not None:
            messagebox.showinfo('SciLink handoff exported', f'SciLink handoff folder created:\n{out}\n\nUse run_scilink_handoff_here.bat or import faradaiq_scilink_tools.py in a SciLink workflow.', parent=parent)
    except Exception: pass
    return out


def _v101_check_scilink_status():
    import subprocess, sys
    try:
        proc=subprocess.run([sys.executable,'-m','pip','show','scilink'], capture_output=True, text=True, timeout=12)
        if proc.returncode==0:
            return 'SciLink appears installed in this Python environment:\n\n'+(proc.stdout.strip()[:4000])
        return 'SciLink is not installed in this Python environment, or pip could not find it. You can still export a SciLink handoff folder and run it in your SciLink environment.'
    except Exception as exc:
        return f'Could not check SciLink installation: {exc}'


def _v101_show_scilink_bridge(gui, parent=None):
    par=parent or gui
    try:
        win=tk.Toplevel(par); win.title('FaradaIQ SciLink bridge')
        try: win.geometry('820x560')
        except Exception: pass
        try: _v29_set_icon(win)
        except Exception: pass
        outer=ttk.Frame(win, padding=10); outer.pack(fill='both', expand=True)
        ttk.Label(outer, text='SciLink bridge', style='Section.TLabel').pack(anchor='w')
        info=('Export the current FaradaIQ session as a SciLink handoff folder. SciLink can then use the structured metadata, folder index, metric summaries, plot/view provenance, and generated task prompt for higher-level agent workflows.')
        ttk.Label(outer, text=info, wraplength=760, justify='left').pack(fill='x', pady=(4,8))
        box=ScrolledText(outer, wrap='word', height=20); box.pack(fill='both', expand=True, pady=(0,8))
        try: _v33_text_style(box, small=False)
        except Exception: pass
        def write(msg):
            box.configure(state='normal'); box.insert('end', msg+'\n'); box.see('end'); box.configure(state='disabled')
        write('Ready. Click “Check SciLink install” or “Export SciLink handoff”.')
        row=ttk.Frame(outer); row.pack(fill='x')
        ttk.Button(row, text='Check SciLink install', command=lambda: write(_v101_check_scilink_status())).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Export SciLink handoff', style='Accent.TButton', command=lambda: write('Exported: '+str(_v101_export_scilink_handoff(gui, parent=win)))).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Build data context pack', command=lambda: write('Built data context pack in: '+str((_v101_build_data_context_pack(gui, save=True) or {}).get('saved_context_pack_dir','')))).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Close', command=win.destroy).pack(side='right')
        try:
            if '_v80_reapply_fonts' in globals(): _v80_reapply_fonts(win)
        except Exception: pass
        return win
    except Exception as exc:
        messagebox.showerror('SciLink bridge failed', f'{exc}\n\n{traceback.format_exc()}', parent=par)


class FaradaIQAIChatWindowV101(FaradaIQAIChatWindowV100):
    def _build_ui(self):
        super()._build_ui()
        try:
            quick=ttk.LabelFrame(self, text='Data-grounded quick questions and tools')
            quick.pack(fill='x', padx=10, pady=(0,8))
            row1=ttk.Frame(quick); row1.pack(fill='x', padx=6, pady=(5,3))
            def add(label, kind):
                b=ttk.Button(row1, text=label, command=lambda k=kind: self._v101_prefill_and_send(k))
                b.pack(side='left', padx=(0,5), pady=2)
            add('Ask about current plot', 'plot'); add('Find trends', 'trends'); add('Suggest next analysis', 'next'); add('Learning mode', 'learn')
            row2=ttk.Frame(quick); row2.pack(fill='x', padx=6, pady=(0,5))
            ttk.Button(row2, text='Build/View data pack', command=self._v101_build_and_show_pack).pack(side='left', padx=(0,5))
            ttk.Button(row2, text='SciLink bridge', command=lambda: _v101_show_scilink_bridge(self.gui, parent=self)).pack(side='left', padx=(0,5))
            ttk.Button(row2, text='Export SciLink handoff', command=lambda: self._v101_export_scilink()).pack(side='left', padx=(0,5))
            try:
                if '_v80_reapply_fonts' in globals(): _v80_reapply_fonts(self)
                if '_v100_apply_chat_theme' in globals(): _v100_apply_chat_theme(self)
            except Exception: pass
        except Exception: pass

    def _v101_prefill_and_send(self, kind):
        try:
            self.input.delete('1.0','end'); self.input.insert('1.0', _v101_make_prefill_prompt(kind)); self.send_message()
        except Exception as exc: messagebox.showerror('AI quick question failed', str(exc), parent=self)

    def _v101_build_and_show_pack(self):
        try:
            pack=_v101_build_data_context_pack(self.gui, save=True)
            txt=_v101_pack_to_text(pack, max_chars=160000)
            win=tk.Toplevel(self); win.title('FaradaIQ v273 data context pack')
            try: win.geometry('980x720')
            except Exception: pass
            box=ScrolledText(win, wrap='word'); box.pack(fill='both', expand=True, padx=10, pady=10)
            try: _v33_text_style(box, small=False)
            except Exception: pass
            box.insert('1.0', txt); box.configure(state='disabled')
            self._append('FaradaIQ', 'Built the FaradaIQ v273 data context pack. Saved folder: '+str(pack.get('saved_context_pack_dir','(not saved)')))
        except Exception as exc: messagebox.showerror('Build data context pack failed', f'{exc}\n\n{traceback.format_exc()}', parent=self)

    def _v101_export_scilink(self):
        try:
            out=_v101_export_scilink_handoff(self.gui, parent=self); self._append('FaradaIQ', f'SciLink handoff exported:\n{out}')
        except Exception as exc: messagebox.showerror('SciLink export failed', f'{exc}\n\n{traceback.format_exc()}', parent=self)

    def send_message(self):
        user_text = self.input.get('1.0','end').strip()
        if not user_text: return
        self.input.delete('1.0','end'); self._append('You', user_text); self.history.append({'role':'user', 'content':user_text})
        include_context = bool(self.include_context_var.get())
        self.status_var.set('Preparing grounded LLM request...')
        try: self._set_live_status('preparing grounded data context', 'Building FaradaIQ v273 data context pack: folder index, plot/view provenance, metric summaries, and structured metadata.', busy=True)
        except Exception: pass
        context = self.context_text if include_context else ''
        if include_context and not context:
            try:
                lim = {'35k':35000, '70k':70000, '120k':120000}.get(self.max_context_var.get(), 70000)
                manifest = _v100_context_manifest(self.gui) if '_v100_context_manifest' in globals() else ''
                ctx = _v101_build_ai_chat_context(self.gui, max_chars=lim)
                context = manifest + '\n\n===== FARADAIQ v101 DATA CONTEXT PACK =====\n' + ctx
                self.context_text = context; self.context_manifest_text = manifest
                try: self._set_context_summary(manifest + '\n\n[FaradaIQ v273] Data context pack attached: folder index + metric summaries + selected plot/view provenance.')
                except Exception: pass
            except Exception as exc:
                context = ''
                try: self._set_live_status('context unavailable', f'Continuing without attached context because context creation failed: {exc}')
                except Exception: pass
        system = ('You are FaradaIQ Studio AI Chat v101. Answer as a data-grounded electrochemical learning and analysis assistant. Use the FaradaIQ Data Context Pack, folder inventory, metric summaries, selected Plot/view provenance, structured metadata, and parser outputs. Do not invent numeric results. Distinguish data-backed observations from hypotheses. When answering, include a short “Data used” section or acknowledge if no selected plot/view was available. When deeper analysis is needed, tell the user which FaradaIQ local summary/action to run instead of guessing from filenames.')
        context_msg = 'FARADAIQ v101 DATA CONTEXT FOR THIS CHAT TURN:\n' + (context or '(Context not attached.)')
        messages = [{'role':'system','content':system}, {'role':'user','content':context_msg}] + self.history[-10:]
        def work():
            try:
                self.after(0, lambda: self._set_live_status('sending request', 'Sending grounded context and user question to selected FaradaIQ LLM.'))
                self.after(500, lambda: (self._set_live_status('thinking / waiting for model', 'The selected LLM is generating a final answer from the attached data context pack.'), self._explain_thinking_once()))
                answer, conn = _v37_call_best_llm(messages, max_tokens=3600, temperature=0.16)
                answer = str(answer or '').strip() + '\n' + _v101_data_used_block(self.gui)
                self.history.append({'role':'assistant', 'content':answer})
                def finish():
                    try: self.llm_var.set(f"AI chat using: {conn.get('name','LLM')} | {conn.get('model','')}")
                    except Exception: pass
                    self._append('AI', answer); self.status_var.set('Ready')
                    try:
                        folder = _v93_chat_save_dir(self.gui); autosave = folder / 'FaradaIQ_AI_chat_latest.txt'
                        autosave.write_text(self.chat.get('1.0','end') + '\n\n===== CONTEXT SNAPSHOT =====\n' + (self.context_text or ''), encoding='utf-8')
                        self._set_live_status('ready', f'Response displayed and transcript autosaved to {autosave}', busy=False)
                    except Exception: self._set_live_status('ready', 'Response displayed. Transcript autosave skipped or failed.', busy=False)
                self.after(0, finish)
            except Exception as exc:
                def fail():
                    self._append('FaradaIQ', f'LLM call failed: {exc}\nOpen LLM settings, ping/select a provider, or start the LiteLLM proxy if using AWS Bedrock.')
                    self.status_var.set('LLM call failed')
                    try: self._set_live_status('LLM call failed', str(exc), busy=False)
                    except Exception: pass
                self.after(0, fail)
        threading.Thread(target=work, daemon=True).start()


