try:
    import datetime as _v103_datetime_mod
except Exception:
    _v103_datetime_mod = None


def _v103_now_dt():
    try:
        return _v103_datetime_mod.datetime.now()
    except Exception:
        try:
            from datetime import datetime as _dt_cls
            return _dt_cls.now()
        except Exception:
            return None


def _v103_now_label():
    d = _v103_now_dt()
    try:
        return d.strftime('%Y%m%d_%H%M%S') if d is not None else str(int(time.time()))
    except Exception:
        return str(int(time.time()))


def _v103_iso_now():
    d = _v103_now_dt()
    try:
        return d.isoformat(timespec='seconds') if d is not None else str(time.time())
    except Exception:
        return str(time.time())


def _v103_safe_get_var(obj, names):
    for name in names:
        try:
            v = getattr(obj, name, None)
            if v is None:
                continue
            if hasattr(v, 'get'):
                s = str(v.get() or '').strip()
            else:
                s = str(v or '').strip()
            if s:
                return s
        except Exception:
            pass
    return ''


def _v103_text_from_widget(w, max_chars=240000):
    try:
        txt = w.get('1.0', 'end')
    except Exception:
        try:
            txt = w.get()
        except Exception:
            txt = ''
    txt = str(txt or '').strip()
    if len(txt) > max_chars:
        txt = txt[:max_chars] + '\n... [truncated]'
    return txt


def _v103_main_text_panels(gui):
    fields = [
        ('experimental_description', ['desc_text','experimental_description_text','description_text']),
        ('session_summary', ['summary_text','session_summary_text']),
        ('data_structure_preview', ['structure_text','data_structure_text','structured_metadata_text']),
        ('current_ai_prompt', ['prompt_text','ai_prompt_text'])
    ]
    out = {}
    for key, names in fields:
        val = ''
        for n in names:
            try:
                w = getattr(gui, n, None)
                if w is not None:
                    val = _v103_text_from_widget(w)
                    if val:
                        break
            except Exception:
                pass
        out[key] = val
    return out


def _v103_walk_widgets(root, limit=6000):
    seen = set(); out = []
    def rec(w):
        if w is None or id(w) in seen or len(out) >= limit:
            return
        seen.add(id(w)); out.append(w)
        try:
            for c in w.winfo_children():
                rec(c)
        except Exception:
            pass
    try:
        rec(root)
    except Exception:
        pass
    try:
        default_root = getattr(tk, '_default_root', None)
        if default_root is not None:
            rec(default_root)
    except Exception:
        pass
    return out


def _v103_find_open_browsers(gui=None):
    roots = []
    if gui is not None:
        roots.append(gui)
    try:
        if getattr(tk, '_default_root', None) is not None:
            roots.append(tk._default_root)
    except Exception:
        pass
    browsers = []
    seen = set()
    for root in roots:
        for w in _v103_walk_widgets(root):
            try:
                alive = bool(w.winfo_exists())
            except Exception:
                alive = True
            if not alive or id(w) in seen:
                continue
            seen.add(id(w))
            cls = w.__class__.__name__.lower()
            title = ''
            try:
                title = str(w.title()).lower()
            except Exception:
                pass
            has_browser_signature = hasattr(w, 'plot_view_list') or hasattr(w, '_v69_plot_views') or hasattr(w, 'analysis_root') or hasattr(w, 'source_folder_var')
            if ('browser' in cls or 'databrowser' in cls or 'experiment map' in title or has_browser_signature) and has_browser_signature:
                browsers.append(w)
    # Prefer most recently-opened windows with plot views.
    try:
        browsers.sort(key=lambda b: (1 if hasattr(b, 'plot_view_list') else 0, int(getattr(b, '_v103_seen_order', 0))), reverse=True)
    except Exception:
        pass
    return browsers


def _v103_current_browser(gui=None):
    bs = _v103_find_open_browsers(gui)
    return bs[-1] if bs else None


def _v103_guess_source(gui=None, roots=None):
    roots = roots or []
    if gui is not None:
        s = _v103_safe_get_var(gui, ['file_var','input_path_var','source_file_var','input_file_var','file_path_var','folder_var'])
        if s:
            return s
        try:
            coll = getattr(gui, 'collection', None)
            for attr in ('source_file','source_path','root_path','input_path'):
                v = getattr(coll, attr, '') if coll is not None else ''
                if v:
                    return str(v)
        except Exception:
            pass
    # Summary JSON may know the original source file.
    for r in roots or []:
        try:
            for p in Path(r).rglob('*summary*.json'):
                try:
                    data = json.loads(Path(p).read_text(encoding='utf-8', errors='ignore'))
                    sf = data.get('source_file') or ((data.get('entries') or [{}])[0].get('summary') or {}).get('source_file')
                    if sf:
                        return str(sf)
                except Exception:
                    pass
        except Exception:
            pass
    return ''


def _v103_analysis_roots(gui=None):
    roots = []
    def add(p):
        try:
            if not p:
                return
            pp = Path(str(p)).expanduser()
            if pp.is_file():
                pp = pp.parent
            if pp.exists():
                roots.append(pp.resolve())
        except Exception:
            pass
    if gui is not None:
        for n in ['output_dir_var','file_var','input_path_var','source_file_var','input_file_var','folder_var']:
            add(_v103_safe_get_var(gui, [n]))
    for b in _v103_find_open_browsers(gui):
        try: add(getattr(b, 'analysis_root', None))
        except Exception: pass
        try: add(b.source_folder_var.get())
        except Exception: pass
        try:
            views = list(getattr(b, '_v69_plot_views', []) or [])
            for v in views[-3:]:
                if isinstance(v, dict):
                    for p in (v.get('paths') or v.get('files') or [])[:6]:
                        add(Path(p).parent)
        except Exception:
            pass
    # Expand sample and analysis-ready subfolders under selected output roots.
    expanded = []
    seen = set()
    for r in roots:
        candidates = [r]
        try:
            candidates += [p for p in r.glob('*_analysis_ready_csv') if p.is_dir()]
            candidates += [p for p in r.glob('*/*_analysis_ready_csv') if p.is_dir()]
            candidates += [p for p in r.glob('*_AI_analysis*') if p.is_dir()]
            candidates += [p for p in r.glob('*/FaradaIQ_AI_data_context_pack') if p.is_dir()]
        except Exception:
            pass
        for c in candidates:
            try:
                key = str(c.resolve()).lower()
                if key not in seen:
                    expanded.append(c.resolve()); seen.add(key)
            except Exception:
                pass
    # Prefer analysis_ready directories first, then sample root, then broad OUT root.
    def score(p):
        s = str(p).lower()
        return (0 if 'analysis_ready_csv' in s else 1 if 'ai_analysis' in s else 2, len(s))
    try:
        expanded.sort(key=score)
    except Exception:
        pass
    return expanded[:10]


def _v103_read_json(path):
    try:
        return json.loads(Path(path).read_text(encoding='utf-8', errors='ignore'))
    except Exception:
        return None


def _v103_find_json_files(roots, max_each=6):
    items = []
    seen = set()
    prefs = ('structured_experiment_metadata','structured_data_map','analysis_ready_manifest','summary','sequence_manifest','manifest')
    for r in roots:
        try:
            files = [p for p in Path(r).rglob('*.json') if p.is_file()]
            def sc(p):
                n = p.name.lower()
                return (min([i for i,k in enumerate(prefs) if k in n] or [50]), len(str(p)))
            for p in sorted(files, key=sc)[:max_each]:
                k = str(p.resolve()).lower()
                if k not in seen:
                    items.append(p.resolve()); seen.add(k)
        except Exception:
            pass
    return items[:24]


def _v103_extract_overview_from_jsons(json_paths):
    overview = {
        'vendor': '', 'n_measurement_points': None, 'technique_counts': {},
        'cv_scan_rates_mV_s': [], 'cv_cycles': [], 'eis_frequency_range_Hz': None,
        'eis_ac_amplitude_mV': None, 'eis_groups_or_blocks': None,
        'source_file': '', 'notes': []
    }
    rates = set(); cycles = set(); tech_counts = {}
    for p in json_paths:
        data = _v103_read_json(p)
        if not isinstance(data, dict):
            continue
        if not overview.get('source_file') and data.get('source_file'):
            overview['source_file'] = str(data.get('source_file'))
        try:
            cs = data.get('collection_summary') or {}
            if cs.get('n_total_measurements') and not overview['n_measurement_points']:
                overview['n_measurement_points'] = cs.get('n_total_measurements')
            for k,v in (cs.get('aggregate_technique_counts') or {}).items():
                tech_counts[k] = max(tech_counts.get(k, 0), v if isinstance(v, int) else 0)
        except Exception:
            pass
        # pySECCM summary structure.
        entries = data.get('entries') or []
        for ent in entries if isinstance(entries, list) else []:
            summ = ent.get('summary') if isinstance(ent, dict) else None
            if not isinstance(summ, dict):
                continue
            if summ.get('vendor') and not overview['vendor']:
                overview['vendor'] = summ.get('vendor')
            if summ.get('n_measurements') and not overview['n_measurement_points']:
                overview['n_measurement_points'] = summ.get('n_measurements')
            for k,v in (summ.get('technique_counts') or {}).items():
                try: tech_counts[k] = max(tech_counts.get(k,0), int(v))
                except Exception: pass
            ds = summ.get('heka_metadata', {}).get('detail_summary') or summ.get('detail_summary') or {}
            if ds:
                if ds.get('frequency_min_Hz') is not None and ds.get('frequency_max_Hz') is not None:
                    overview['eis_frequency_range_Hz'] = [ds.get('frequency_min_Hz'), ds.get('frequency_max_Hz')]
                if ds.get('ac_amplitude_mV') is not None:
                    overview['eis_ac_amplitude_mV'] = ds.get('ac_amplitude_mV')
                if ds.get('cycles') is not None:
                    try: cycles.add(int(float(ds.get('cycles'))))
                    except Exception: pass
            for m in (summ.get('method_entries') or summ.get('heka_metadata', {}).get('detail_summary', {}).get('method_entries_preview') or []):
                if not isinstance(m, dict):
                    continue
                raw = str(m.get('raw_text','') or m.get('technique_text',''))
                rate = m.get('rate') or ''
                if rate:
                    try:
                        # HEKA stores rates like 100.0mV / 75.00mV; treat as mV/s from method text.
                        val = float(re.sub(r'[^0-9.+-eE]', '', str(rate)))
                        if val > 0: rates.add(round(val, 6))
                    except Exception:
                        pass
                if m.get('cycles') is not None:
                    try: cycles.add(int(float(m.get('cycles'))))
                    except Exception: pass
                if m.get('start_freq_Hz') is not None and m.get('end_freq_Hz') is not None:
                    overview['eis_frequency_range_Hz'] = [m.get('end_freq_Hz'), m.get('start_freq_Hz')]
                if m.get('ac_amplitude_mV') is not None:
                    overview['eis_ac_amplitude_mV'] = m.get('ac_amplitude_mV')
        # Analysis-ready manifest entries.
        csv_entries = data.get('csv_entries') or []
        for e in csv_entries if isinstance(csv_entries, list) else []:
            if not isinstance(e, dict):
                continue
            t = e.get('technique') or e.get('method_id') or ''
            if t:
                tech_counts[str(t)] = tech_counts.get(str(t), 0) + 1
            sr = e.get('scan_rate')
            if sr:
                try:
                    val = float(re.sub(r'[^0-9.+-eE]', '', str(sr)))
                    if val > 0:
                        rates.add(round(val if val > 1 else val*1000, 6))
                except Exception:
                    pass
    overview['technique_counts'] = dict(sorted(tech_counts.items(), key=lambda kv: str(kv[0])))
    overview['cv_scan_rates_mV_s'] = sorted(rates)
    overview['cv_cycles'] = sorted(cycles)
    return overview


def _v103_current_plotview_pack(gui=None):
    b = _v103_current_browser(gui)
    if b is None:
        return {'available': False, 'reason': 'No open Data Browser detected by FaradaIQ.'}
    pack = {'available': True, 'browser_title': ''}
    try:
        pack['browser_title'] = str(b.title())
    except Exception:
        pass
    try:
        views = list(getattr(b, '_v69_plot_views', []) or [])
        pack['n_plot_views'] = len(views)
        sel = []
        try: sel = list(b.plot_view_list.curselection())
        except Exception: pass
        idx = sel[0] if sel else (len(views)-1 if views else None)
        pack['selected_index'] = idx
        if idx is not None and 0 <= idx < len(views):
            v = views[idx]
            pack['selected_view_name'] = str(v.get('name','')) if isinstance(v, dict) else str(v)
            pack['selected_view_kind'] = str(v.get('kind','')) if isinstance(v, dict) else ''
            paths = list((v.get('paths') or v.get('files') or []) if isinstance(v, dict) else [])
            pack['selected_file_count'] = len(paths)
            pack['selected_paths'] = [str(p) for p in paths[:80]]
            pack['selected_file_summaries'] = []
            for p in paths[:12]:
                pp = Path(str(p))
                summ = {'path': str(pp), 'kind': _v101_file_kind(pp) if '_v101_file_kind' in globals() else _v103_file_kind(pp)}
                if pp.exists() and pp.suffix.lower() in ('.csv','.txt','.asc'):
                    try:
                        summ.update(_v101_table_summary(pp, max_rows=500) if '_v101_table_summary' in globals() else {})
                    except Exception as exc:
                        summ['summary_error'] = str(exc)
                pack['selected_file_summaries'].append(_v101_json_safe(summ) if '_v101_json_safe' in globals() else summ)
        else:
            pack['selected_view_name'] = ''
            pack['selected_file_count'] = 0
    except Exception as exc:
        pack['plotview_error'] = str(exc)
    try:
        pack['browser_settings'] = {
            'plot_mode': b.plot_mode_var.get() if hasattr(b, 'plot_mode_var') else '',
            'cycle_filter': b.cv_cycle_filter_var.get() if hasattr(b, 'cv_cycle_filter_var') else '',
            'legend_mode': b.legend_mode_var.get() if hasattr(b, 'legend_mode_var') else '',
            'remove_exact_duplicates': bool(b.remove_duplicates_var.get()) if hasattr(b, 'remove_duplicates_var') else None,
        }
    except Exception:
        pass
    try:
        sel = b.tree.selection() if hasattr(b, 'tree') else []
        labels = []
        for iid in list(sel)[:10]:
            try: labels.append(str(b.tree.item(iid, 'text')))
            except Exception: pass
        pack['experiment_map_selection'] = labels
    except Exception:
        pass
    try:
        log = getattr(b, 'log_text', None) or getattr(b, 'log_box', None)
        if log is not None:
            txt = _v103_text_from_widget(log, max_chars=6000)
            pack['browser_log_tail'] = txt[-3000:]
    except Exception:
        pass
    return pack


def _v103_file_kind(path):
    try:
        return _v101_file_kind(path)
    except Exception:
        p = Path(path); s = p.name.lower(); suf = p.suffix.lower()
        if suf in ('.png','.jpg','.jpeg','.tif','.tiff','.bmp','.gif','.webp','.svg'): return 'figure/image'
        if suf in ('.json','.jsonl'): return 'metadata/json'
        if suf in ('.csv','.txt','.asc','.dat','.par','.cor','.xls','.xlsx'): return 'numeric/text table'
        if suf in ('.npy','.npz','.h5','.hdf5'): return 'binary parsed data'
        return 'other'


def _v103_build_data_context_pack(gui, save=True):
    roots = _v103_analysis_roots(gui)
    json_paths = _v103_find_json_files(roots)
    text_panels = _v103_main_text_panels(gui)
    source = _v103_guess_source(gui, roots=roots)
    overview = _v103_extract_overview_from_jsons(json_paths)
    if not source and overview.get('source_file'):
        source = overview.get('source_file')
    pack = {
        'schema_version': 'FaradaIQ-data-context-pack-v103',
        'created': _v103_iso_now(),
        'source': source,
        'roots': [str(r) for r in roots],
        'data_used_policy': 'Only summaries, metadata, paths, selected plot/view provenance, numeric table summaries, and small text previews are attached; large raw binary arrays/images are not pasted into chat.',
        'structured_experiment_overview': overview,
        'text_panels': text_panels,
        'current_plotview': _v103_current_plotview_pack(gui),
        'json_context_files': [str(p) for p in json_paths[:18]],
        'folder_inventories': [],
        'metric_tables': [],
        'small_json_previews': []
    }
    for r in roots[:5]:
        try:
            pack['folder_inventories'].append(_v101_folder_inventory(r, max_files=180) if '_v101_folder_inventory' in globals() else {'root': str(r)})
        except Exception as exc:
            pack['folder_inventories'].append({'root': str(r), 'error': str(exc)})
        try:
            pack['metric_tables'].extend(_v101_collect_metric_tables(r, max_tables=8) if '_v101_collect_metric_tables' in globals() else [])
        except Exception as exc:
            pack['metric_tables'].append({'root': str(r), 'error': str(exc)})
    # include compact JSON previews from most relevant files
    for p in json_paths[:10]:
        try:
            data = _v103_read_json(p)
            if data is None:
                continue
            preview = _v101_json_safe(data, depth=0) if '_v101_json_safe' in globals() else data
            pack['small_json_previews'].append({'path': str(p), 'preview': preview})
        except Exception as exc:
            pack['small_json_previews'].append({'path': str(p), 'error': str(exc)})
    if save:
        try:
            root = roots[0] if roots else Path(_v103_safe_get_var(gui, ['output_dir_var']) or '.').resolve()
            out = Path(root) / 'FaradaIQ_AI_data_context_pack'
            out.mkdir(parents=True, exist_ok=True)
            safe_pack = _v101_json_safe(pack) if '_v101_json_safe' in globals() else pack
            (out / 'FaradaIQ_data_context_pack_latest.json').write_text(json.dumps(safe_pack, indent=2), encoding='utf-8')
            (out / f'FaradaIQ_data_context_pack_{_v103_now_label()}.json').write_text(json.dumps(safe_pack, indent=2), encoding='utf-8')
            (out / 'FaradaIQ_data_context_pack_latest.txt').write_text(_v103_pack_to_text(pack), encoding='utf-8')
            pack['saved_context_pack_dir'] = str(out)
        except Exception as exc:
            pack['save_error'] = str(exc)
    return pack


def _v103_pack_to_text(pack, max_chars=90000):
    lines = []
    lines.append('===== FARADAIQ DATA CONTEXT PACK v216 =====')
    lines.append('Purpose: grounded AI chat for learning/questions about current electrochemical data and results.')
    lines.append('Data access policy: ' + str(pack.get('data_used_policy','')))
    lines.append('Created: ' + str(pack.get('created','')))
    lines.append('Loaded source: ' + str(pack.get('source') or '(not detected)'))
    lines.append('')
    lines.append('--- Detected experiment overview ---')
    ov = pack.get('structured_experiment_overview') or {}
    lines.append(json.dumps(_v101_json_safe(ov) if '_v101_json_safe' in globals() else ov, indent=2, ensure_ascii=False)[:12000])
    lines.append('')
    lines.append('--- Main GUI text panels ---')
    tp = pack.get('text_panels') or {}
    for k,v in tp.items():
        lines.append(f'[{k}] {"available" if str(v).strip() else "empty/not available"} ({len(str(v or ""))} chars)')
        if str(v).strip():
            lines.append(str(v)[:8000])
    lines.append('')
    lines.append('--- Current Data Browser / Plot-view context ---')
    pv = pack.get('current_plotview') or {}
    lines.append(json.dumps(_v101_json_safe(pv) if '_v101_json_safe' in globals() else pv, indent=2, ensure_ascii=False)[:22000])
    lines.append('')
    lines.append('--- Analysis/output roots indexed ---')
    for r in pack.get('roots') or []:
        lines.append('  - ' + _v101_short_path(r) if '_v101_short_path' in globals() else '  - ' + str(r))
    lines.append('')
    lines.append('--- Folder inventory summaries ---')
    for inv in (pack.get('folder_inventories') or [])[:4]:
        lines.append(f"Root: {inv.get('root','')}")
        lines.append(f"Total files: {inv.get('total_files','?')} | Counts: {json.dumps(inv.get('counts',{}), ensure_ascii=False)}")
        for f in (inv.get('files') or [])[:45]:
            lines.append(f"  - [{f.get('kind')}] {f.get('relative_path')} ({f.get('size_bytes')} bytes)")
    lines.append('')
    lines.append('--- Numeric metric/table summaries ---')
    mt = pack.get('metric_tables') or []
    lines.append(f'Metric/table summaries included: {len(mt)}')
    for t in mt[:18]:
        lines.append(json.dumps(_v101_json_safe(t) if '_v101_json_safe' in globals() else t, indent=2, ensure_ascii=False)[:4500])
    lines.append('')
    lines.append('--- Relevant JSON/manifest previews ---')
    for j in (pack.get('small_json_previews') or [])[:6]:
        lines.append('JSON: ' + str(j.get('path','')))
        lines.append(json.dumps(_v101_json_safe(j.get('preview')) if '_v101_json_safe' in globals() else j.get('preview'), indent=2, ensure_ascii=False)[:7000])
    text = '\n'.join(lines)
    if len(text) > max_chars:
        text = text[:max_chars] + '\n... [FaradaIQ v273 data context pack truncated]'
    return text


def _v103_context_manifest(gui, browser=None):
    try:
        pack = _v103_build_data_context_pack(gui, save=False)
        lines = []
        lines.append('FARADAIQ DATA CONTEXT SHARED WITH AI CHAT')
        lines.append('Only summaries, metadata, paths, parsed previews, plot/view state, and small text/table previews are attached; large raw binary arrays/images are not pasted into chat.')
        lines.append('')
        lines.append('[Loaded source] ' + (str(pack.get('source')) if pack.get('source') else '(not detected yet)'))
        roots = pack.get('roots') or []
        lines.append('[Selected output / analysis root] ' + (str(roots[0]) if roots else '(not detected yet)'))
        ov = pack.get('structured_experiment_overview') or {}
        if ov:
            lines.append('[Detected experiment overview]')
            if ov.get('vendor'): lines.append('  Vendor/source: ' + str(ov.get('vendor')))
            if ov.get('n_measurement_points'): lines.append('  Measurement points: ' + str(ov.get('n_measurement_points')))
            if ov.get('technique_counts'): lines.append('  Techniques/counts: ' + json.dumps(ov.get('technique_counts'), ensure_ascii=False))
            if ov.get('cv_scan_rates_mV_s'): lines.append('  CV scan rates: ' + ', '.join(str(x) for x in ov.get('cv_scan_rates_mV_s')) + ' mV/s')
            if ov.get('cv_cycles'): lines.append('  CV cycles detected: ' + ', '.join(str(x) for x in ov.get('cv_cycles')))
            if ov.get('eis_frequency_range_Hz'): lines.append('  EIS frequency range: ' + str(ov.get('eis_frequency_range_Hz')) + ' Hz')
        tp = pack.get('text_panels') or {}
        for key, label in [('experimental_description','Experimental description'),('session_summary','Session summary'),('data_structure_preview','Data structure / structured metadata preview'),('current_ai_prompt','Current/generated AI prompt')]:
            val = tp.get(key) or ''
            lines.append(f'{label}: {"available" if str(val).strip() else "empty/not available"} ({len(str(val or ""))} chars)')
        try:
            provider, model, _ = _v66_selected_llm_label_text()
            lines.append(f'[Selected LLM] {provider} | {model}')
        except Exception:
            pass
        lines.append('[Analysis/output roots scanned for context]')
        if roots:
            for r in roots[:6]: lines.append('  - ' + (_v101_short_path(r) if '_v101_short_path' in globals() else str(r)))
        else:
            lines.append('  none detected')
        pv = pack.get('current_plotview') or {}
        lines.append('[Open Data Browser context] ' + ('attached' if pv.get('available') else 'none open'))
        if pv.get('available'):
            lines.append('  Plot/views: ' + str(pv.get('n_plot_views',0)))
            lines.append('  Selected Plot/view: ' + str(pv.get('selected_view_name') or '(latest/none)'))
            lines.append('  Selected files: ' + str(pv.get('selected_file_count',0)))
            bs = pv.get('browser_settings') or {}
            if bs: lines.append('  Browser settings: ' + json.dumps(bs, ensure_ascii=False))
        lines.append('[Metric/table summaries] ' + str(len(pack.get('metric_tables') or [])) + ' compact summaries available')
        lines.append('[Small file previews] latest JSON/CSV/TXT/manifest previews from analysis roots may be included within the context limit.')
        return '\n'.join(lines)
    except Exception as exc:
        return 'FARADAIQ DATA CONTEXT SHARED WITH AI CHAT\nContext manifest failed: ' + str(exc)


def _v103_build_ai_chat_context(gui, max_chars=120000):
    try:
        pack = _v103_build_data_context_pack(gui, save=True)
        text = _v103_pack_to_text(pack, max_chars=max_chars)
    except Exception as exc:
        text = 'FaradaIQ v273 Data Context Pack failed: ' + str(exc)
    if len(text) > max_chars:
        text = text[:max_chars] + '\n... [FaradaIQ v273 AI context truncated]'
    return text


