            bs = pv.get('browser_settings') or {}
            if bs.get('plot_mode'): lines.append('- Plot mode: ' + str(bs.get('plot_mode')))
            if bs.get('cycle_filter'): lines.append('- Cycle filter: ' + str(bs.get('cycle_filter')))
