# ---- v103 patch: responsive browser, strict plottable data tree, actionable comparison batches, quick-tip toggle ----
APP_TITLE = "FaradaIQ Studio v273"

# v103 goals:
# 1) Data tree contains only real numeric/plottable data files from actually detected techniques.
#    Media/images/figures/helper text are hidden from the tree and from smart comparisons.
# 2) Smart comparisons can create families of Plot/view items for every CV point and every scan rate.
# 3) Right-side Plot/view controls use clear actions; the unclear/hanging Analyze view button is replaced.
# 4) Quick tips are globally toggleable and OFF by default.
# 5) Plotting and comparison apply show live status before heavy work; browser log popout works; duplicate empty plot-log area is hidden.

_V103_MEDIA_EXTS = {'.png', '.jpg', '.jpeg', '.tif', '.tiff', '.bmp', '.gif', '.webp', '.mp4', '.avi', '.mov', '.mkv', '.wmv', '.svg', '.pdf'}
_V103_NUMERIC_EXTS = {'.csv', '.txt', '.tsv', '.asc', '.dat', '.dta', '.mpt', '.mpr', '.pssession', '.psbd', '.par', '.cor', '.z', '.xlsx', '.xls', '.npy', '.npz'}
_V103_ALLOWED_TECHNIQUES = {
    'CV / LSV', 'EIS', 'DRT', 'OCP', 'IV / Tafel', 'Chronoamperometry',
    'Chronopotentiometry', 'EQCM', 'Raman / SERS', 'FTIR / IR', 'UV-Vis', 'XRD', 'XPS'
}
_V103_EXCLUDE_PATH_TOKENS = (
    '/figures/', '/figure/', '/images/', '/image/', '/photos/', '/photo/', '/screenshots/', '/screenshot/',
    '/faradaiq_ai_chat_transcripts/', '/scilink_handoff/', '/ai_analysis_with_parsed_outputs/',
    '/report_bundles/', '/exports/', '/browser_cache/', '/pysimpleechem_cv_results/',
)
_V103_EXCLUDE_FILE_TOKENS = (
    'photo_manifest', 'trace_index', 'bundle_sections', 'method_entries', 'position_report',
    'runtime_history', 'runtime_summary', 'smart_comparison', 'comparison_actions',
    'session_context_from_bat', 'launcher_events', 'ai_prompt_current', 'readme', 'qa_',
)

def _v103_path_text(path):
    try: return str(Path(path).resolve()).replace('\\', '/').lower()
    except Exception: return str(path or '').replace('\\', '/').lower()


def _v103_is_media_or_figure_path(path):
    try:
        p = Path(path)
        low = _v103_path_text(p)
        if p.suffix.lower() in _V103_MEDIA_EXTS:
            return True
        if any(tok in low for tok in _V103_EXCLUDE_PATH_TOKENS):
            return True
        # Anything in a figures/ or image-ish output folder should not be treated as experiment data.
        return False
    except Exception:
        return True


def _v103_has_numeric_columns(path, max_bytes=90000):
    """Fast, permissive check: true when a text/table file seems to contain at least two numeric columns."""
    try:
        p = Path(path)
        if p.suffix.lower() in {'.npy', '.npz', '.mpr', '.dta', '.pssession', '.psbd', '.par', '.cor', '.z'}:
            return True
        if p.suffix.lower() in {'.xlsx', '.xls'}:
            return True
        data = p.read_bytes()[:max_bytes]
        if b'\x00' in data[:4096] and p.suffix.lower() not in {'.dat'}:
            return False
        txt = data.decode('utf-8', errors='ignore') or data.decode('latin-1', errors='ignore')
        numeric_rows = 0
        for line in txt.splitlines()[:500]:
            if not line.strip():
                continue
            vals = re.findall(r'(?<![A-Za-z])[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)
            if len(vals) >= 2:
                numeric_rows += 1
                if numeric_rows >= 3:
                    return True
        # Some HEKA/PalmSens headers may show only one numeric row in first chunk but are still valid by extension/name.
        low = (p.name + ' ' + str(p.parent)).lower()
        if any(tok in low for tok in ['current_vs_potential', 'freq_zreal_zimag', 'fulleis', 'full_eis', 'drt_input', 'zreal', 'zimag']):
            return True
    except Exception:
        return False
    return False


def _v103_record_is_real_plottable(rec):
    try:
        p = Path(rec.get('path'))
        if not p.exists() or not p.is_file():
            return False
        if _v103_is_media_or_figure_path(p):
            return False
        if p.suffix.lower() not in _V103_NUMERIC_EXTS:
            return False
        low = _v103_path_text(p)
        if any(tok in low for tok in _V103_EXCLUDE_FILE_TOKENS):
            # Explicit plottable patterns override helper-like names.
            if not any(keep in low for keep in ['current_vs_potential', 'freq_zreal_zimag', 'drt_input', 'fulleis', 'full_eis']):
                return False
        kind = _v100_norm_kind(_v80_kind(rec) if '_v80_kind' in globals() else rec.get('kind')) if '_v100_norm_kind' in globals() else str(rec.get('kind') or '')
        if not kind or kind in {'Other', 'Tables / text', 'Metadata JSON', 'HEKA', 'Media / image'}:
            return False
        if kind not in _V103_ALLOWED_TECHNIQUES:
            return False
        # Prevent invented Raman/SERS from ordinary text/log/prompt files.
        if kind == 'Raman / SERS':
            name_parent = (p.name + ' ' + str(p.parent)).lower()
            if not any(tok in name_parent for tok in ['raman', 'sers']):
                return False
        return _v103_has_numeric_columns(p)
    except Exception:
        return False

try:
    _V103_PREV_COLLECT_SMART_RECORDS = _v756_collect_smart_records
except Exception:
    _V103_PREV_COLLECT_SMART_RECORDS = None


def _v103_collect_smart_records(browser):
    records, ai_json_files, ai_map = ([], [], {})
    if callable(_V103_PREV_COLLECT_SMART_RECORDS):
        try:
            records, ai_json_files, ai_map = _V103_PREV_COLLECT_SMART_RECORDS(browser)
        except Exception as exc:
            try: browser.log(f'v103 collector fallback after previous collector failed: {exc}')
            except Exception: pass
    # Strictly keep only real numeric/plottable data. No images, saved figures, chat transcripts, helper JSON, or invented techniques.
    filtered, seen = [], set()
    for r in records or []:
        try:
            if not _v103_record_is_real_plottable(r):
                continue
            p = Path(r.get('path')).resolve()
            key = str(p)
            if key in seen:
                continue
            seen.add(key)
            rr = dict(r)
            # Normalize kind one more time after filtering.
            rr['kind'] = _v100_norm_kind(_v80_kind(rr) if '_v80_kind' in globals() else rr.get('kind')) if '_v100_norm_kind' in globals() else rr.get('kind')
            filtered.append(rr)
        except Exception:
            pass
    return filtered, ai_json_files, ai_map

try:
    _v756_collect_smart_records = _v103_collect_smart_records
except Exception:
    pass


def _v103_records(browser, kind=None):
    kind = _v100_norm_kind(kind) if '_v100_norm_kind' in globals() else kind
    recs = list(getattr(browser, '_v80_records', []) or getattr(browser, '_v78_records', []) or [])
    out = []
    for r in recs:
        try:
            if not _v103_record_is_real_plottable(r):
                continue
            if kind and (_v100_norm_kind(_v80_kind(r)) if '_v100_norm_kind' in globals() else _v80_kind(r)) != kind:
                continue
            out.append(r)
        except Exception:
            pass
    return out


def _v103_group_records_by_tag(browser, records, tag):
    ctx = getattr(browser, '_v83_experiment_context', {}) or {}
    buckets = {}
    for r in records or []:
        try:
            tags = r.get('_v90_tags') or _v90_record_tags(r, ctx)
            r['_v90_tags'] = tags
            label = str(tags.get(tag) or 'unassigned')
            if label.strip().lower() in {'', 'unassigned'}:
                label = f'unassigned {tag}'
            buckets.setdefault(label, []).append(r)
        except Exception:
            buckets.setdefault(f'unassigned {tag}', []).append(r)
    def key(item):
        return (_v80_num(item[0]) if '_v80_num' in globals() else 1e12, _v80_nat_key(item[0]) if '_v80_nat_key' in globals() else str(item[0]).lower())
    return dict(sorted(buckets.items(), key=key))


def _v103_paths_from_records(records):
    out, seen = [], set()
    for r in records or []:
        try:
            p = Path(r.get('path')).resolve()
            if not p.exists() or not _v103_record_is_real_plottable(r):
                continue
            s = str(p)
            if s not in seen:
                seen.add(s); out.append(p)
        except Exception:
            pass
    return out

# Replace safe path matching so all smart actions use numeric/plottable data only.
def _v103_path_matches_kind(path, kind=None, rec=None):
    try:
        if rec is None:
            rec = {'path': Path(path), 'kind': _v756_kind_from_content_or_path(Path(path), '') if '_v756_kind_from_content_or_path' in globals() else ''}
        if not _v103_record_is_real_plottable(rec):
            return False
        if not kind:
            return True
        return _v100_norm_kind(_v80_kind(rec)) == _v100_norm_kind(kind)
    except Exception:
        return False

try:
    _v100_path_matches_kind = _v103_path_matches_kind
except Exception:
    pass


def _v103_paths_for_kind(browser, kind=None, limit=None):
    paths = _v103_paths_from_records(_v103_records(browser, kind))
    return paths[:int(limit)] if limit else paths

