def _v103_selected_paths_if_useful(browser, kind=None):
    try: selected = list(browser.selected_paths(plottable_only=True) or [])
    except Exception: selected = []
    # Map selected paths to records when possible so kind/filters are reliable.
    rec_by_path = {}
    for r in _v103_records(browser, None):
        try: rec_by_path[str(Path(r.get('path')).resolve())] = r
        except Exception: pass
    out, seen = [], set()
    for p in selected:
        try:
            p = Path(p).resolve()
            rec = rec_by_path.get(str(p), {'path': p, 'kind': _v756_kind_from_content_or_path(p, '') if '_v756_kind_from_content_or_path' in globals() else ''})
            if not _v103_path_matches_kind(p, kind=kind, rec=rec):
                continue
            if str(p) not in seen:
                seen.add(str(p)); out.append(p)
        except Exception:
            pass
    return out

