def _v103_add_tooltip(widget, text):
    # Tooltips are attached only to actual widgets, never broad frames/empty areas; show is gated by global toggle.
    try:
        if widget is None: return
        cls = widget.winfo_class()
        allowed = {'TButton','Button','TCheckbutton','Checkbutton','TRadiobutton','Radiobutton','TEntry','Entry','TCombobox','Combobox','TSpinbox','Spinbox','TLabel','Label','Treeview','Listbox'}
        if cls not in allowed:
            return
        if not getattr(widget, '_faradaiq_tooltip_added', False):
            widget._faradaiq_tooltip_added = True
            widget._faradaiq_tooltip = _FaradaIQTooltip(widget, text)
    except Exception:
        pass

