def _v103_hide_center_plot_log(browser):
    # Remove the duplicated empty plot log under the central plot. The left Browser log is the single log location.
    try:
        left = getattr(browser, 'left_log_text', None)
        left_top = left.winfo_toplevel() if left is not None else browser
        for w in list(_v95_iter_widgets(browser) if '_v95_iter_widgets' in globals() else []):
            try:
                txt = _v95_widget_text(w)
                if txt == 'Log' and left is not None and not _v91_parent_contains(w, left):
                    w.pack_forget()
                if txt == '↗' and left is not None and not _v91_parent_contains(w.master, left):
                    # keep plot/view/smart popouts if they are in right panel/tree; only hide stray center-log popout by geometry below axes
                    pass
            except Exception: pass
        # Hide any old empty ScrolledText not equal to left log and under the plot area.
        for w in list(_v95_iter_widgets(browser) if '_v95_iter_widgets' in globals() else []):
            try:
                if isinstance(w, ScrolledText) and w is not left:
                    content = w.get('1.0','end').strip()
                    if not content or 'Plot failed' in content or 'Displayed image' in content:
                        # If it is the center log clone, hide it; leave descriptions/summary boxes in main GUI alone.
                        if w.winfo_toplevel() is browser:
                            w.pack_forget()
            except Exception: pass
    except Exception:
        pass


