def _v103_plot_or_overlay_selected(browser):
    # Schedule heavy plotting after status update so Windows does not look frozen before work begins.
    try:
        browser.status_var.set('Preparing plot in background-style UI pass: collecting selected numeric data...')
        browser.update_idletasks()
    except Exception: pass
    def work():
        try:
            try: browser.configure(cursor='watch')
            except Exception: pass
            all_paths = _v103_selected_paths_if_useful(browser, None)
            if not all_paths:
                try: messagebox.showinfo('No plottable data selected', 'Select a numeric CV/EIS/DRT/OCP/IV group in the experiment map. Images and generated figures are hidden intentionally.', parent=browser)
                except Exception: pass
                return
            try: browser.status_var.set(f'Plotting {len(all_paths)} selected numeric file(s)...')
            except Exception: pass
            # Never plot media images from the browser tree.
            dedup_paths = _v89_deduplicate_paths_for_plot(browser, all_paths) if '_v89_deduplicate_paths_for_plot' in globals() else all_paths
            try: paths = _v78_limit_plot_paths(browser, dedup_paths)
            except Exception: paths = dedup_paths
            paths = [p for p in paths if Path(p).suffix.lower() not in _V103_MEDIA_EXTS]
            try: browser.clear_plot()
            except Exception: pass
            try:
                browser.last_plot_paths = []; browser._v89_seen_plot_signatures = set()
            except Exception: pass
            for i, p in enumerate(paths, 1):
                try:
                    browser.status_var.set(f'Plotting {i}/{len(paths)}: {Path(p).name}')
                    if i == 1 or i % 4 == 0: browser.update_idletasks()
                    browser._plot_file(p, clear=False)
                except Exception as exc:
                    try: browser.log(f'Plot failed for {Path(p).name}: {exc}')
                    except Exception: pass
            try: browser._finish_plot_axes()
            except Exception: pass
            try: _v75_hide_show_media_buttons(browser, False)
            except Exception: pass
            try: _v752_reset_plot_geometry(browser)
            except Exception: pass
            try: kind = _v78_kind_from_paths(paths)
            except Exception: kind = 'General'
            removed = len((getattr(browser, '_v89_last_duplicate_report', {}) or {}).get('removed', []))
            msg = f'{kind} | plotted {len(paths)} of {len(all_paths)} selected numeric file(s)'
            if removed: msg += f' | exact duplicates removed: {removed}'
            try:
                browser.current_technique_var.set(msg); browser.status_var.set(msg)
            except Exception: pass
            try: _v757_store_current_view(browser, paths, kind)
            except Exception:
                try: _v75_store_current_view(browser, paths, kind)
                except Exception: pass
            try: _v91_update_quick_summary(browser, paths, kind, prefix='Added Plot/view.')
            except Exception: pass
        finally:
            try: browser.configure(cursor='')
            except Exception: pass
    try: browser.after(20, work)
    except Exception: work()

