_V105_SCILINK_LABRIC_BAT_DEFAULT = r"C:\SciLink\Start_SciLink_Labric.bat"


def _v105_safestr(x):
    try:
        return str(x)
    except Exception:
        return repr(x)


def _v105_short_win_path(path, max_len=96):
    try:
        s = str(path)
        if len(s) <= max_len:
            return s
        # Keep drive/root and the last 3 useful path segments.
        parts = re.split(r'[\\/]+', s)
        if len(parts) <= 5:
            return s[:max_len-3] + '...'
        head = '\\'.join(parts[:2]) if parts[0].endswith(':') else parts[0]
        tail = '\\'.join(parts[-3:])
        return f'{head}\\...\\{tail}'
    except Exception:
        return str(path)


def _v105_run_subprocess(cmd, timeout=8):
    import subprocess
    try:
        cp = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return cp.returncode, (cp.stdout or '').strip(), (cp.stderr or '').strip()
    except Exception as exc:
        return 999, '', str(exc)


def _v105_where_command(name):
    import subprocess, shutil
    out=[]
    try:
        if os.name == 'nt':
            cp=subprocess.run(['where', name], capture_output=True, text=True, timeout=5)
            if cp.returncode == 0:
                out += [x.strip() for x in (cp.stdout or '').splitlines() if x.strip()]
        else:
            p=shutil.which(name)
            if p: out.append(p)
    except Exception:
        pass
    return out


def _v105_candidate_python_exes(limit=28):
    """Find likely Python environments on the PC without doing a slow full-disk scan."""
    import glob, sys
    seen=set(); out=[]
    def add(p):
        try:
            if not p: return
            pp=Path(str(p).strip('"'))
            if not pp.exists(): return
            key=str(pp.resolve()).lower()
            if key not in seen:
                seen.add(key); out.append(str(pp))
        except Exception:
            pass
    add(sys.executable)
    for p in _v105_where_command('python') + _v105_where_command('python3'):
        add(p)
    user = os.environ.get('USERPROFILE') or str(Path.home())
    local = os.environ.get('LOCALAPPDATA') or ''
    patterns = [
        r'C:\SciLink\.venv\Scripts\python.exe',
        r'C:\SciLink\venv\Scripts\python.exe',
        r'C:\SciLink\env\Scripts\python.exe',
        r'C:\SciLink\scilink_env\Scripts\python.exe',
        r'C:\SciLink\*\Scripts\python.exe',
        os.path.join(user, 'miniconda3', 'envs', '*', 'python.exe'),
        os.path.join(user, 'anaconda3', 'envs', '*', 'python.exe'),
        os.path.join(user, 'AppData', 'Local', 'miniconda3', 'envs', '*', 'python.exe'),
        os.path.join(user, 'AppData', 'Local', 'anaconda3', 'envs', '*', 'python.exe'),
        os.path.join(local, 'Programs', 'Python', 'Python*', 'python.exe') if local else '',
    ]
    for pat in patterns:
        try:
            for p in glob.glob(pat)[:12]:
                add(p)
                if len(out) >= limit: return out
        except Exception:
            pass
    return out[:limit]


def _v105_check_python_has_scilink(py):
    code = "import importlib.util, sys; spec=importlib.util.find_spec('scilink'); print('FOUND' if spec else 'MISSING'); print(sys.executable)"
    rc, stdout, stderr = _v105_run_subprocess([py, '-c', code], timeout=5)
    found = ('FOUND' in stdout.splitlines()[:1])
    return found, rc, stdout, stderr


def _v105_check_scilink_status():
    lines=[]
    lines.append('SciLink / LabRIC integration check')
    lines.append('='*48)
    bat = Path(_V105_SCILINK_LABRIC_BAT_DEFAULT)
    if bat.exists():
        lines.append(f'[OK] LabRIC/SciLink starter BAT found: {bat}')
    else:
        lines.append(f'[MISSING] LabRIC/SciLink starter BAT not found at: {bat}')
        lines.append('          The Start button will still let you try this path if you create it later.')
    # scilink executable in PATH
    cmd_hits = _v105_where_command('scilink')
    if cmd_hits:
        lines.append('[OK] scilink command found in PATH:')
        for p in cmd_hits[:6]: lines.append('     - '+p)
    else:
        lines.append('[INFO] scilink command was not found in PATH.')
    # Check current Python via pip show also.
    try:
        import sys
        rc, out, err = _v105_run_subprocess([sys.executable, '-m', 'pip', 'show', 'scilink'], timeout=8)
        if rc == 0:
            name_line = '\n'.join((out or '').splitlines()[:8])
            lines.append('[OK] SciLink appears installed in the current FaradaIQ Python environment:')
            lines.append(name_line)
        else:
            lines.append('[INFO] SciLink is not installed in the current FaradaIQ Python environment.')
    except Exception as exc:
        lines.append(f'[WARN] Could not run pip show in current environment: {exc}')
    # Check likely Python/Conda/venv environments.
    lines.append('\nChecking likely Python environments on this PC...')
    found_any=False
    candidates=_v105_candidate_python_exes()
    checked=0
    for py in candidates:
        checked += 1
        found, rc, stdout, stderr = _v105_check_python_has_scilink(py)
        prefix='[OK]' if found else '[--]'
        if found: found_any=True
        lines.append(f'{prefix} {_v105_short_win_path(py)} : ' + ('scilink importable' if found else 'no scilink import'))
        if found and stdout:
            # keep a small trace of executable confirmation.
            pass
        if checked >= 24:
            lines.append('Stopped after checking 24 candidate Python environments to keep GUI responsive.')
            break
    if not candidates:
        lines.append('[INFO] No candidate Python environments were discovered beyond the current runtime.')
    if not found_any and not cmd_hits and not bat.exists():
        lines.append('\nResult: SciLink was not found locally, but FaradaIQ can still export a SciLink handoff folder for use elsewhere.')
    elif bat.exists():
        lines.append('\nResult: You can use the “Start LabRIC/SciLink BAT” button to launch your configured SciLink workflow.')
    else:
        lines.append('\nResult: At least one SciLink route may be available. Use the handoff export or configure PATH/start script as needed.')
    return '\n'.join(lines)

