def _v105_start_labric_scilink_bat(parent=None, bat_path=None):
    import subprocess
    p = Path(bat_path or _V105_SCILINK_LABRIC_BAT_DEFAULT)
    if not p.exists():
        msg = f'SciLink/LabRIC starter BAT was not found:\n{p}\n\nCreate this file or update the path, then try again.'
        try: messagebox.showwarning('SciLink starter BAT missing', msg, parent=parent)
        except Exception: pass
        return msg
    try:
        if os.name == 'nt':
            # Use cmd start so the BAT opens in its own console and does not block FaradaIQ.
            subprocess.Popen(['cmd', '/c', 'start', 'SciLink LabRIC', str(p)], cwd=str(p.parent), shell=False)
        else:
            subprocess.Popen([str(p)], cwd=str(p.parent))
        msg = f'Started SciLink/LabRIC BAT:\n{p}'
        try:
            if parent is not None:
                messagebox.showinfo('SciLink/LabRIC started', msg, parent=parent)
        except Exception:
            pass
        return msg
    except Exception as exc:
        msg = f'Could not start SciLink/LabRIC BAT:\n{p}\n\n{exc}'
        try: messagebox.showerror('SciLink start failed', msg, parent=parent)
        except Exception: pass
        return msg


def _v105_show_scilink_bridge(gui, parent=None):
    par=parent or gui
    try:
        win=tk.Toplevel(par); win.title('FaradaIQ SciLink / LabRIC bridge')
        try: win.geometry('920x640')
        except Exception: pass
        try: _v29_set_icon(win)
        except Exception: pass
        outer=ttk.Frame(win, padding=10); outer.pack(fill='both', expand=True)
        ttk.Label(outer, text='SciLink / LabRIC bridge', style='Section.TLabel').pack(anchor='w')
        info=('Export the current FaradaIQ session as a SciLink handoff folder, check whether SciLink is available in the current or other local Python environments, or start your configured LabRIC/SciLink launcher BAT.')
        ttk.Label(outer, text=info, wraplength=860, justify='left').pack(fill='x', pady=(4,8))
        bat_row=ttk.Frame(outer); bat_row.pack(fill='x', pady=(0,8))
        ttk.Label(bat_row, text='SciLink/LabRIC BAT:', style='Muted.TLabel').pack(side='left', padx=(0,5))
        bat_var=tk.StringVar(value=_V105_SCILINK_LABRIC_BAT_DEFAULT)
        bat_entry=ttk.Entry(bat_row, textvariable=bat_var)
        bat_entry.pack(side='left', fill='x', expand=True, padx=(0,6))
        def choose_bat():
            try:
                p=filedialog.askopenfilename(parent=win, title='Choose SciLink/LabRIC BAT', filetypes=[('Batch files','*.bat'),('All files','*.*')])
                if p: bat_var.set(p)
            except Exception: pass
        ttk.Button(bat_row, text='Browse', command=choose_bat).pack(side='left')
        box=ScrolledText(outer, wrap='word', height=22); box.pack(fill='both', expand=True, pady=(0,8))
        try: _v33_text_style(box, small=False)
        except Exception: pass
        def write(msg):
            box.configure(state='normal'); box.insert('end', str(msg)+'\n\n'); box.see('end'); box.configure(state='disabled')
        default_exists = Path(_V105_SCILINK_LABRIC_BAT_DEFAULT).exists()
        write('Ready. Click “Check SciLink install/PC envs”, “Start LabRIC/SciLink BAT”, or “Export SciLink handoff”.\nDefault BAT exists: '+('YES' if default_exists else 'NO')+f'\nDefault BAT: {_V105_SCILINK_LABRIC_BAT_DEFAULT}')
        row=ttk.Frame(outer); row.pack(fill='x')
        ttk.Button(row, text='Check SciLink install / PC envs', command=lambda: write(_v105_check_scilink_status())).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Start LabRIC/SciLink BAT', style='Accent.TButton', command=lambda: write(_v105_start_labric_scilink_bat(win, bat_var.get()))).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Export SciLink handoff', command=lambda: write('Exported: '+str(_v101_export_scilink_handoff(gui, parent=win)))).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Build data context pack', command=lambda: write('Built data context pack in: '+str((_v101_build_data_context_pack(gui, save=True) or {}).get('saved_context_pack_dir','')))).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Close', command=win.destroy).pack(side='right')
        try:
            if '_v80_reapply_fonts' in globals(): _v80_reapply_fonts(win)
            if '_v100_apply_chat_theme' in globals(): _v100_apply_chat_theme(win)
        except Exception: pass
        return win
    except Exception as exc:
        messagebox.showerror('SciLink bridge failed', f'{exc}\n\n{traceback.format_exc()}', parent=par)

