# ---- v106 persistent session + reusable Plot/view collection patch ----
# Adds two independent persistence layers:
#   1) Browser Plot/view collection JSON files: save/load/append multiple view sets.
#   2) Full FaradaIQ GUI session JSON files: main GUI state + open browser state + plot/views.
# This patch intentionally stores paths, metadata, settings, and lightweight view records. It does
# not duplicate large raw arrays; curves are reconstructed from saved paths when a view is opened.

def _v106_now_iso():
    import datetime as _dt
    return _dt.datetime.now().isoformat(timespec='seconds')

def _v106_stamp():
    import datetime as _dt
    return _dt.datetime.now().strftime('%Y%m%d_%H%M%S')

def _v106_json_safe(obj):
    try:
        import numpy as _np
    except Exception:
        _np = None
    from pathlib import Path as _Path
    if obj is None or isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, _Path):
        return str(obj)
    if _np is not None:
        if isinstance(obj, (_np.integer,)):
            return int(obj)
        if isinstance(obj, (_np.floating,)):
            return float(obj)
        if isinstance(obj, (_np.ndarray,)):
            # Do not serialize large arrays into sessions. Store only compact preview info.
            try:
                return {'array_shape': list(obj.shape), 'array_dtype': str(obj.dtype)}
            except Exception:
                return str(type(obj))
    if isinstance(obj, dict):
        return {str(k): _v106_json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_v106_json_safe(v) for v in obj]
    try:
        return str(obj)
    except Exception:
        return repr(obj)

def _v106_safe_text(widget, limit=200000):
    try:
        txt = widget.get('1.0', 'end').rstrip('\n')
        return txt[:limit]
    except Exception:
        return ''

def _v106_set_text(widget, text):
    try:
        widget.delete('1.0', 'end')
        widget.insert('1.0', str(text or ''))
    except Exception:
        pass

def _v106_safe_var_get(obj, name):
    try:
        var = getattr(obj, name, None)
        return var.get() if hasattr(var, 'get') else None
    except Exception:
        return None

def _v106_safe_var_set(obj, name, value):
    try:
        var = getattr(obj, name, None)
        if hasattr(var, 'set'):
            var.set('' if value is None else str(value))
    except Exception:
        pass

def _v106_default_session_dir(gui=None):
    from pathlib import Path as _Path
    try:
        out = _v106_safe_var_get(gui, 'output_dir_var') if gui is not None else ''
        root = _Path(out or '.').expanduser().resolve()
    except Exception:
        root = _Path('.').resolve()
    d = root / 'FaradaIQ_saved_sessions'
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return d

def _v106_browser_collection_dir(browser):
    from pathlib import Path as _Path
    try:
        root = _Path(getattr(browser, 'analyzed_root', '') or getattr(browser, 'analysis_root', '') or '.').resolve()
    except Exception:
        root = _Path('.').resolve()
    d = root / 'plotview_collections'
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return d

def _v106_browser_session_dir(browser):
    from pathlib import Path as _Path
    try:
        root = _Path(getattr(browser, 'analyzed_root', '') or getattr(browser, 'analysis_root', '') or '.').resolve()
    except Exception:
        root = _Path('.').resolve()
    d = root / 'browser_sessions'
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return d

def _v106_view_lightweight(view):
    # Prefer the existing v75 lightweight converter when available.
    try:
        if '_v75_view_lightweight' in globals():
            return _v75_view_lightweight(view)
    except Exception:
        pass
    v = dict(view or {})
    paths = []
    for p in v.get('paths', []) or []:
        paths.append(str(p))
    if not paths:
        for c in v.get('curves', []) or []:
            p = c.get('path') if isinstance(c, dict) else None
            if p:
                paths.append(str(p))
    curves = []
    for c in v.get('curves', []) or []:
        if not isinstance(c, dict):
            continue
        curves.append({
            'path': str(c.get('path','')),
            'label': str(c.get('label','')),
            'x_column': str(c.get('xcol', c.get('x_column',''))),
            'y_column': str(c.get('ycol', c.get('y_column',''))),
            'n_points': int(len(c.get('x', []))) if hasattr(c.get('x', []), '__len__') else 0,
        })
    v['paths'] = paths
    v['curves'] = curves
    return _v106_json_safe(v)

def _v106_collect_plotview_collection(browser):
    views = [_v106_view_lightweight(v) for v in getattr(browser, '_v69_plot_views', []) or []]
    settings = {}
    for key, attr in [('plot_mode','plot_mode_var'), ('x_axis','x_axis_var'), ('y_axis','y_axis_var'), ('normalize','normalize_var'),
                      ('cycle_filter','cycle_filter_var'), ('legend_mode','legend_mode_var'), ('remove_exact_duplicates','remove_dup_var')]:
        val = _v106_safe_var_get(browser, attr)
        if val is not None:
            settings[key] = val
    return {
        'schema': 'faradaiq_plotview_collection_v106',
        'app': 'FaradaIQ Studio',
        'version': "v273",
        'created': _v106_now_iso(),
        'analysis_root': str(getattr(browser, 'analysis_root', '')),
        'analyzed_root': str(getattr(browser, 'analyzed_root', '')),
        'base_name': str(getattr(browser, 'base_name', '')),
        'plot_views': views,
        'settings': settings,
        'notes': 'Reusable Plot/view collection. Contains path-based lightweight plot/view records; large arrays are reconstructed from source files when opened.',
    }

def _v106_apply_plotview_collection(browser, payload, append=False, silent=False):
    views = payload.get('plot_views', []) if isinstance(payload, dict) else []
    if not append:
        try:
            browser._v69_plot_views = []
            browser.plot_view_list.delete(0, 'end')
        except Exception:
            pass
    for raw in views:
        view = dict(raw or {})
        view['paths'] = [str(p) for p in view.get('paths', []) or []]
        # Rebuild curve arrays from source paths during view loading; do not trust stale serialized arrays.
        view['curves'] = []
        try:
            browser._v69_plot_views.append(view)
        except Exception:
            browser._v69_plot_views = [view]
        try:
            name = view.get('name') or f"{view.get('kind','View')} ({len(view.get('paths', []))} files)"
            browser.plot_view_list.insert('end', name)
        except Exception:
            pass
    # Apply plot-related display settings from collection if present.
    settings = payload.get('settings', {}) if isinstance(payload, dict) else {}
    reverse = {'plot_mode':'plot_mode_var','x_axis':'x_axis_var','y_axis':'y_axis_var','normalize':'normalize_var',
               'cycle_filter':'cycle_filter_var','legend_mode':'legend_mode_var','remove_exact_duplicates':'remove_dup_var'}
    for key, attr in reverse.items():
        if key in settings:
            try:
                getattr(browser, attr).set(settings[key])
            except Exception:
                pass
    try:
        n = int(browser.plot_view_list.size())
        if n:
            browser.plot_view_list.selection_clear(0, 'end')
            browser.plot_view_list.selection_set(n-1 if append else 0)
            browser.plot_view_list.see(n-1 if append else 0)
    except Exception:
        pass
    if not silent:
        try: browser.log(f"Loaded {len(views)} Plot/view item(s)" + (" and appended to existing list." if append else "."))
        except Exception: pass
    try:
        if '_v75_save_session' in globals():
            _v75_save_session(browser, silent=True)
    except Exception:
        pass

def _v106_save_plotviews_dialog(browser):
    try:
        from tkinter import filedialog, messagebox
        default = f"{str(getattr(browser,'base_name','faradaiq')).strip() or 'faradaiq'}_plotviews_{_v106_stamp()}.faradaiq_plotviews.json"
        path = filedialog.asksaveasfilename(
            title='Save Plot/view list collection',
            initialdir=str(_v106_browser_collection_dir(browser)),
            initialfile=default,
            defaultextension='.json',
            filetypes=[('FaradaIQ Plot/view collection', '*.faradaiq_plotviews.json'), ('JSON', '*.json'), ('All files', '*.*')],
            parent=browser,
        )
        if not path:
            return None
        payload = _v106_collect_plotview_collection(browser)
        Path(path).write_text(json.dumps(_v106_json_safe(payload), ensure_ascii=False, indent=2), encoding='utf-8')
        try: browser.status_var.set(f"Saved Plot/view list: {Path(path).name}")
        except Exception: pass
        try: browser.log(f"Saved reusable Plot/view list collection: {path}")
        except Exception: pass
        return Path(path)
    except Exception as exc:
        try:
            messagebox.showerror('Save Plot/view list failed', str(exc), parent=browser)
        except Exception:
            pass
        return None

def _v106_load_plotviews_dialog(browser):
    try:
        from tkinter import filedialog, messagebox
        path = filedialog.askopenfilename(
            title='Load Plot/view list collection',
            initialdir=str(_v106_browser_collection_dir(browser)),
            filetypes=[('FaradaIQ Plot/view collection', '*.faradaiq_plotviews.json'), ('JSON', '*.json'), ('All files', '*.*')],
            parent=browser,
        )
        if not path:
            return None
        payload = json.loads(Path(path).read_text(encoding='utf-8'))
        # Yes = replace, No = append, Cancel = stop.
        ans = messagebox.askyesnocancel(
            'Load Plot/view list',
            'Replace the current Plot/view list?\n\nYes = replace current list\nNo = append to current list\nCancel = do not load',
            parent=browser,
        )
        if ans is None:
            return None
        _v106_apply_plotview_collection(browser, payload, append=(ans is False), silent=False)
        try: browser.status_var.set(f"Loaded Plot/view list: {Path(path).name}")
        except Exception: pass
        return Path(path)
    except Exception as exc:
        try:
            messagebox.showerror('Load Plot/view list failed', str(exc), parent=browser)
        except Exception:
            pass
        return None

def _v106_collect_browser_session(browser):
    try:
        base = _v75_collect_session(browser) if '_v75_collect_session' in globals() else {}
    except Exception:
        base = {}
    extra_settings = {}
    for key, attr in [('source_folder','source_folder_var'), ('cycle_filter','cycle_filter_var'), ('legend_mode','legend_mode_var'), ('remove_dup','remove_dup_var'),
                      ('max_curves','max_curves_var'), ('quick_tips','quick_tips_var')]:
        val = _v106_safe_var_get(browser, attr)
        if val is not None:
            extra_settings[key] = val
    try:
        suggestions = [browser.comp_list.get(i) for i in range(browser.comp_list.size())] if hasattr(browser, 'comp_list') else []
    except Exception:
        suggestions = []
    try:
        selected = [browser.tree.item(i, 'text') for i in browser.tree.selection()] if hasattr(browser, 'tree') else []
    except Exception:
        selected = []
    base.update({
        'schema': 'faradaiq_browser_session_v106',
        'version': "v273",
        'created': _v106_now_iso(),
        'extra_settings_v106': extra_settings,
        'smart_comparisons': suggestions[:200],
        'selected_tree_items_text': selected[:100],
        'browser_log_tail': _v106_safe_text(getattr(browser, 'log_text', None), 20000),
        'plotview_collection': _v106_collect_plotview_collection(browser),
    })
    return _v106_json_safe(base)

def _v106_apply_browser_session(browser, payload, silent=False):
    if not isinstance(payload, dict):
        return
    # Source/path vars and settings.
    ex = payload.get('extra_settings_v106', {}) or {}
    for attr_key, attr in [('source_folder','source_folder_var'), ('cycle_filter','cycle_filter_var'), ('legend_mode','legend_mode_var'), ('remove_dup','remove_dup_var'),
                           ('max_curves','max_curves_var'), ('quick_tips','quick_tips_var')]:
        if attr_key in ex:
            try: getattr(browser, attr).set(ex[attr_key])
            except Exception: pass
    # Apply v75-compatible session payload for metadata/settings/plot_views.
    try:
        if '_v75_apply_session_payload' in globals():
            _v75_apply_session_payload(browser, payload, silent=True)
        else:
            _v106_apply_plotview_collection(browser, payload.get('plotview_collection', payload), append=False, silent=True)
    except Exception:
        _v106_apply_plotview_collection(browser, payload.get('plotview_collection', payload), append=False, silent=True)
    # Restore smart comparison text where possible.
    try:
        if hasattr(browser, 'comp_list'):
            browser.comp_list.delete(0, 'end')
            for s in payload.get('smart_comparisons', []) or []:
                browser.comp_list.insert('end', str(s))
    except Exception:
        pass
    try:
        browser.status_var.set('Loaded FaradaIQ browser session.')
        if not silent: browser.log('Loaded FaradaIQ browser session with Plot/view list and browser settings.')
    except Exception:
        pass

def _v106_save_browser_session_dialog(browser):
    try:
        from tkinter import filedialog, messagebox
        default = f"{str(getattr(browser,'base_name','faradaiq')).strip() or 'faradaiq'}_browser_session_{_v106_stamp()}.faradaiq_browser_session.json"
        path = filedialog.asksaveasfilename(title='Save Data Browser session', initialdir=str(_v106_browser_session_dir(browser)), initialfile=default,
                                            defaultextension='.json', filetypes=[('FaradaIQ browser session', '*.faradaiq_browser_session.json'), ('JSON', '*.json'), ('All files', '*.*')], parent=browser)
        if not path: return None
        Path(path).write_text(json.dumps(_v106_collect_browser_session(browser), ensure_ascii=False, indent=2), encoding='utf-8')
        try: browser.status_var.set(f"Saved browser session: {Path(path).name}")
        except Exception: pass
        try: browser.log(f"Saved Data Browser session: {path}")
        except Exception: pass
        return Path(path)
    except Exception as exc:
        try: messagebox.showerror('Save browser session failed', str(exc), parent=browser)
        except Exception: pass
        return None

def _v106_load_browser_session_dialog(browser):
    try:
        from tkinter import filedialog, messagebox
        path = filedialog.askopenfilename(title='Load Data Browser session', initialdir=str(_v106_browser_session_dir(browser)),
                                          filetypes=[('FaradaIQ browser session', '*.faradaiq_browser_session.json'), ('FaradaIQ session/Plotviews JSON', '*.json'), ('All files', '*.*')], parent=browser)
        if not path: return None
        payload = json.loads(Path(path).read_text(encoding='utf-8'))
        _v106_apply_browser_session(browser, payload, silent=False)
        return Path(path)
    except Exception as exc:
        try: messagebox.showerror('Load browser session failed', str(exc), parent=browser)
        except Exception: pass
        return None

def _v106_find_data_browsers(root):
    out=[]
    seen=set()
    def walk(w):
        if id(w) in seen: return
        seen.add(id(w))
        try:
            if hasattr(w, 'plot_view_list') and hasattr(w, '_v69_plot_views'):
                out.append(w)
        except Exception:
            pass
        try:
            for c in w.winfo_children(): walk(c)
        except Exception:
            pass
    try:
        walk(root)
    except Exception:
        pass
    return out

def _v106_collect_main_session(gui):
    main_vars = {}
    for name in ('file_var','output_dir_var'):
        val = _v106_safe_var_get(gui, name)
        if val is not None: main_vars[name]=val
    texts = {
        'experimental_description': _v106_safe_text(getattr(gui, 'desc_text', None), 200000),
        'session_summary': _v106_safe_text(getattr(gui, 'summary_text', None), 200000),
        'data_structure_preview': _v106_safe_text(getattr(gui, 'structure_text', None), 300000),
        'current_ai_prompt': _v106_safe_text(getattr(gui, 'prompt_text', None), 200000),
    }
    llm = {}
    for name in ('llm_provider_var','llm_model_var','llm_base_url_var','llm_status_var'):
        val = _v106_safe_var_get(gui, name)
        if val is not None: llm[name]=val
    browsers=[]
    for b in _v106_find_data_browsers(gui):
        try: browsers.append(_v106_collect_browser_session(b))
        except Exception as exc: browsers.append({'error': str(exc)})
    return _v106_json_safe({
        'schema': 'faradaiq_main_session_v106',
        'app': 'FaradaIQ Studio',
        'version': "v273",
        'created': _v106_now_iso(),
        'main_vars': main_vars,
        'main_texts': texts,
        'llm_settings_preview': llm,
        'current_summary': getattr(gui, 'current_summary', None),
        'current_analysis_root': str(getattr(gui, 'current_analysis_root', '')) if hasattr(gui,'current_analysis_root') else '',
        'open_browser_sessions': browsers,
        'notes': 'Full FaradaIQ session: main GUI state plus lightweight Data Browser sessions and Plot/view lists. Large raw arrays/images are not embedded.',
    })

def _v106_apply_main_session(gui, payload, open_browser=True):
    if not isinstance(payload, dict): return
    for name, val in (payload.get('main_vars', {}) or {}).items():
        _v106_safe_var_set(gui, name, val)
    texts = payload.get('main_texts', {}) or {}
    _v106_set_text(getattr(gui, 'desc_text', None), texts.get('experimental_description',''))
    _v106_set_text(getattr(gui, 'summary_text', None), texts.get('session_summary',''))
    _v106_set_text(getattr(gui, 'structure_text', None), texts.get('data_structure_preview',''))
    _v106_set_text(getattr(gui, 'prompt_text', None), texts.get('current_ai_prompt',''))
    try:
        gui.current_summary = payload.get('current_summary') or getattr(gui, 'current_summary', None)
    except Exception:
        pass
    browser_sessions = payload.get('open_browser_sessions', []) or []
    if open_browser and browser_sessions:
        existing = _v106_find_data_browsers(gui)
        # Load first session into first open browser, create additional browsers as needed.
        for i, bp in enumerate(browser_sessions):
            try:
                if i < len(existing):
                    b = existing[i]
                else:
                    ar = bp.get('analysis_root') or bp.get('plotview_collection',{}).get('analysis_root') or None
                    bn = bp.get('base_name') or bp.get('plotview_collection',{}).get('base_name') or None
                    b = FaradaIQDataBrowser(gui, analysis_root=ar, base_name=bn)
                b.after(300, lambda bb=b, pp=bp: _v106_apply_browser_session(bb, pp, silent=False))
            except Exception as exc:
                try: gui.set_status(f'Could not restore one browser session: {exc}')
                except Exception: pass
    try:
        if hasattr(gui, 'set_status'): gui.set_status('Loaded FaradaIQ main session. Browser and Plot/view state restored when available.')
    except Exception:
        pass

def _v106_save_main_session_dialog(gui):
    try:
        from tkinter import filedialog, messagebox
        stem='FaradaIQ_main_session'
        try:
            src = Path(_v106_safe_var_get(gui,'file_var') or '').stem
            if src: stem = _v35_safe_name(src) if '_v35_safe_name' in globals() else src
        except Exception:
            pass
        default = f'{stem}_{_v106_stamp()}.faradaiq_main_session.json'
        path = filedialog.asksaveasfilename(title='Save full FaradaIQ session', initialdir=str(_v106_default_session_dir(gui)), initialfile=default,
                                            defaultextension='.json', filetypes=[('FaradaIQ main session', '*.faradaiq_main_session.json'), ('JSON', '*.json'), ('All files', '*.*')], parent=gui)
        if not path: return None
        Path(path).write_text(json.dumps(_v106_collect_main_session(gui), ensure_ascii=False, indent=2), encoding='utf-8')
        try:
            if hasattr(gui, 'set_status'): gui.set_status(f'Saved full FaradaIQ session: {Path(path).name}')
        except Exception: pass
        return Path(path)
    except Exception as exc:
        try: messagebox.showerror('Save FaradaIQ session failed', str(exc), parent=gui)
        except Exception: pass
        return None

def _v106_load_main_session_dialog(gui):
    try:
        from tkinter import filedialog, messagebox
        path = filedialog.askopenfilename(title='Load full FaradaIQ session', initialdir=str(_v106_default_session_dir(gui)),
                                          filetypes=[('FaradaIQ main session', '*.faradaiq_main_session.json'), ('JSON', '*.json'), ('All files', '*.*')], parent=gui)
        if not path: return None
        payload = json.loads(Path(path).read_text(encoding='utf-8'))
        _v106_apply_main_session(gui, payload, open_browser=True)
        return Path(path)
    except Exception as exc:
        try: messagebox.showerror('Load FaradaIQ session failed', str(exc), parent=gui)
        except Exception: pass
        return None

def _v106_add_browser_persistence_buttons(browser):
    if getattr(browser, '_v106_persistence_buttons_added', False):
        return
    if not hasattr(browser, 'plot_view_list'):
        return
    try:
        # Create compact rows below the Plot/view list controls.
        outer = browser.plot_view_list.master.master
        row1 = ttk.Frame(outer, style='Card.TFrame')
        row1.pack(fill='x', pady=(4, 0))
        ttk.Button(row1, text='Save Plot/views', command=lambda b=browser: _v106_save_plotviews_dialog(b)).pack(side='left', fill='x', expand=True, padx=(0,2))
        ttk.Button(row1, text='Load Plot/views', command=lambda b=browser: _v106_load_plotviews_dialog(b)).pack(side='left', fill='x', expand=True, padx=(2,0))
        row2 = ttk.Frame(outer, style='Card.TFrame')
        row2.pack(fill='x', pady=(3, 0))
        ttk.Button(row2, text='Save browser session', command=lambda b=browser: _v106_save_browser_session_dialog(b)).pack(side='left', fill='x', expand=True, padx=(0,2))
        ttk.Button(row2, text='Load browser session', command=lambda b=browser: _v106_load_browser_session_dialog(b)).pack(side='left', fill='x', expand=True, padx=(2,0))
        browser._v106_persistence_buttons_added = True
        try:
            _v103_add_tooltip(row1.winfo_children()[0], 'Save only the current Plot/view list to a reusable local JSON file. Use this to keep multiple different plot-view collections for the same dataset.')
            _v103_add_tooltip(row1.winfo_children()[1], 'Load a saved Plot/view collection. You can replace the current list or append the saved views to the current list.')
            _v103_add_tooltip(row2.winfo_children()[0], 'Save the full Data Browser state, including the data root, browser settings, smart comparisons, and Plot/view list.')
            _v103_add_tooltip(row2.winfo_children()[1], 'Load a full Data Browser session and restore its Plot/view list, settings, and smart-comparison state.')
        except Exception:
            pass
    except Exception as exc:
        try: browser.log(f'Could not add v106 Plot/view/session buttons: {exc}')
        except Exception: pass

def _v106_add_main_session_buttons(gui):
    if getattr(gui, '_v106_main_session_buttons_added', False):
        return
    try:
        # Prefer appending to the clean AI workflow row if present.
        target = None
        def walk(w):
            nonlocal target
            if target is not None: return
            try:
                if hasattr(w, 'cget') and str(w.cget('text')).strip() == 'AI workflow':
                    target = w.master
                    return
            except Exception:
                pass
            try:
                for c in w.winfo_children(): walk(c)
            except Exception:
                pass
        walk(gui)
        if target is None:
            # Fall back to a top-level row.
            target = ttk.Frame(gui, style='Card.TFrame')
            try: target.pack(fill='x', padx=6, pady=(2,2), before=gui.summary_text.master.master)
            except Exception: target.pack(fill='x', padx=6, pady=(2,2))
            ttk.Label(target, text='Session', style='Muted.TLabel').pack(side='left', padx=(0,8))
        if not any((hasattr(c, 'cget') and str(c.cget('text')) == 'Save app session') for c in target.winfo_children()):
            ttk.Button(target, text='Save app session', command=lambda g=gui: _v106_save_main_session_dialog(g)).pack(side='left', padx=(6,2))
            ttk.Button(target, text='Load app session', command=lambda g=gui: _v106_load_main_session_dialog(g)).pack(side='left', padx=(2,6))
        gui._v106_main_session_buttons_added = True
    except Exception as exc:
        try:
            if hasattr(gui, 'set_status'): gui.set_status(f'Could not add v106 session buttons: {exc}')
        except Exception:
            pass

