def _v109_style_configure(root, mode='dark'):
    p = _v36_theme_palette(mode)
    try:
        style = ttk.Style(root)
        try:
            if 'clam' in set(style.theme_names()):
                style.theme_use('clam')
        except Exception:
            pass
        # Frames and labels
        style.configure('TFrame', background=p['bg'])
        style.configure('App.TFrame', background=p['bg'])
        style.configure('Card.TFrame', background=p['surface'])
        style.configure('Toolbar.TFrame', background=p['surface'])
        style.configure('Hero.TFrame', background=p['hero'])
        style.configure('TLabel', background=p['bg'], foreground=p['ink'], font=('Segoe UI', 10))
        style.configure('Card.TLabel', background=p['surface'], foreground=p['ink'], font=('Segoe UI', 10))
        style.configure('Muted.TLabel', background=p['surface'], foreground=p['muted'], font=('Segoe UI', 9))
        style.configure('Status.TLabel', background=p['bg'], foreground=p['muted'], font=('Segoe UI', 9))
        style.configure('Section.TLabel', background=p['surface'], foreground=p['hero_title'], font=('Segoe UI Semibold', 11))
        style.configure('HeroTitle.TLabel', background=p['hero'], foreground=p['hero_title'], font=('Segoe UI Semibold', 18))
        style.configure('HeroSub.TLabel', background=p['hero'], foreground=p['hero_sub'], font=('Segoe UI', 9))
        style.configure('HeroCredit.TLabel', background=p['hero'], foreground=p['hero_credit'], font=('Segoe UI', 9))
        # Labelframes
        style.configure('TLabelframe', background=p['surface'], foreground=p['ink'], borderwidth=1, relief='solid')
        style.configure('TLabelframe.Label', background=p['surface'], foreground=p['hero_sub'], font=('Segoe UI Semibold', 10))
        # Buttons: neutral professional default + blue/slate accent, no teal/green.
        style.configure('TButton', font=('Segoe UI', 10), padding=(12, 6), background=p['button_bg'], foreground=p['button_fg'], borderwidth=1, relief='raised')
        style.map('TButton',
                  background=[('disabled', p['surface2']), ('pressed', p['button_pressed']), ('active', p['button_active'])],
                  foreground=[('disabled', p['muted']), ('pressed', p['button_fg']), ('active', p['button_fg'])])
        style.configure('Accent.TButton', font=('Segoe UI Semibold', 10), padding=(12, 6), background=p['accent'], foreground=p['accent_fg'], borderwidth=1, relief='raised')
        style.map('Accent.TButton',
                  background=[('disabled', p['surface2']), ('pressed', p['accent_pressed']), ('active', p['accent_hover'])],
                  foreground=[('disabled', p['muted']), ('pressed', p['accent_fg']), ('active', p['accent_fg'])])
        # Keep older aliases commercial-ready if a previous patch uses them.
        for alias in ('Primary.TButton', 'Good.TButton', 'Success.TButton'):
            style.configure(alias, font=('Segoe UI Semibold', 10), padding=(12, 6), background=p['accent'], foreground=p['accent_fg'], borderwidth=1, relief='raised')
            style.map(alias, background=[('pressed', p['accent_pressed']), ('active', p['accent_hover'])], foreground=[('pressed', p['accent_fg']), ('active', p['accent_fg'])])
        # Entries and combos
        field_bg = '#ffffff' if p['mode'] == 'light' else '#0d1626'
        style.configure('TEntry', padding=(5, 5), fieldbackground=field_bg, foreground=p['text_fg'], insertcolor=p['text_fg'])
        style.configure('TCombobox', padding=(5, 4), fieldbackground=field_bg, background=p['button_bg'], foreground=p['text_fg'], arrowcolor=p['button_fg'])
        style.map('TCombobox', fieldbackground=[('readonly', field_bg)], background=[('active', p['button_active'])], foreground=[('readonly', p['text_fg'])])
        style.configure('TSpinbox', padding=(5, 4), fieldbackground=field_bg, foreground=p['text_fg'])
        # Checks/radios
        style.configure('TCheckbutton', background=p['bg'], foreground=p['ink'], font=('Segoe UI', 10))
        style.configure('TRadiobutton', background=p['bg'], foreground=p['ink'], font=('Segoe UI', 10))
        style.map('TCheckbutton', background=[('active', p['surface2'])], foreground=[('active', p['ink'])])
        style.map('TRadiobutton', background=[('active', p['surface2'])], foreground=[('active', p['ink'])])
        # Tree/list/table/progress
        style.configure('Treeview', background=p['text_bg'], fieldbackground=p['text_bg'], foreground=p['text_fg'], rowheight=26, borderwidth=1)
        style.configure('Treeview.Heading', background=p['surface3'], foreground=p['ink'], font=('Segoe UI Semibold', 10), relief='raised')
        style.map('Treeview', background=[('selected', p['select_bg'])], foreground=[('selected', p['select_fg'])])
        style.configure('TProgressbar', background=p['accent'], troughcolor=p['surface3'], bordercolor=p['surface3'], lightcolor=p['accent_hover'], darkcolor=p['accent_pressed'])
        style.configure('Horizontal.TScrollbar', background=p['surface3'], troughcolor=p['surface2'], arrowcolor=p['ink'])
        style.configure('Vertical.TScrollbar', background=p['surface3'], troughcolor=p['surface2'], arrowcolor=p['ink'])
        try:
            root.configure(bg=p['bg'])
        except Exception:
            pass
    except Exception:
        pass
    return p


def _v109_apply_widget_colors(root, p=None):
    if p is None:
        p = _v36_theme_palette(getattr(root, '_faradaiq_theme_mode', 'dark'))
    seen = set()
    def walk(w):
        if id(w) in seen:
            return
        seen.add(id(w))
        try:
            cls = w.winfo_class()
        except Exception:
            cls = ''
        try:
            if cls in ('Text',):
                w.configure(background=p['text_bg'], foreground=p['text_fg'], insertbackground=p['text_fg'],
                            selectbackground=p['select_bg'], selectforeground=p['select_fg'],
                            highlightbackground=p['text_border'], highlightcolor=p['accent'])
            elif cls in ('Listbox',):
                w.configure(background=p['text_bg'], foreground=p['text_fg'], selectbackground=p['select_bg'],
                            selectforeground=p['select_fg'], highlightbackground=p['text_border'], highlightcolor=p['accent'])
            elif cls in ('Entry',):
                w.configure(background=('#ffffff' if p['mode']=='light' else '#0d1626'), foreground=p['text_fg'],
                            insertbackground=p['text_fg'], selectbackground=p['select_bg'], selectforeground=p['select_fg'])
            elif cls in ('Frame', 'TFrame', 'Labelframe', 'TLabelframe'):
                # Do not aggressively recolor all frames; ttk style handles them. Plain Tk frames are safe.
                if cls == 'Frame':
                    try: w.configure(background=p['bg'])
                    except Exception: pass
        except Exception:
            pass
        try:
            for c in w.winfo_children():
                walk(c)
        except Exception:
            pass
    try:
        walk(root)
    except Exception:
        pass


def _v36_apply_theme(root, mode='dark'):
    p = _v109_style_configure(root, mode)
    try:
        root._faradaiq_theme_mode = p['mode']
    except Exception:
        pass
    try:
        if hasattr(root, 'theme_mode_var'):
            root.theme_mode_var.set('Light' if p['mode'] == 'light' else 'Dark')
    except Exception:
        pass
    try:
        _v109_apply_widget_colors(root, p)
    except Exception:
        pass
    try:
        if '_v80_reapply_fonts' in globals():
            _v80_reapply_fonts(root)
    except Exception:
        pass
    try:
        if hasattr(root, 'set_status'):
            root.set_status(f'Theme: {p["mode"]}.')
    except Exception:
        pass
    try:
        if hasattr(root, 'after'):
            root.after(200, lambda r=root, pp=p: (_v109_apply_widget_colors(r, pp), _v80_reapply_fonts(r) if '_v80_reapply_fonts' in globals() else None))
            root.after(800, lambda r=root, pp=p: (_v109_apply_widget_colors(r, pp), _v80_reapply_fonts(r) if '_v80_reapply_fonts' in globals() else None))
    except Exception:
        pass


def _v36_toggle_theme(self):
    mode = 'light' if getattr(self, '_faradaiq_theme_mode', 'dark') == 'dark' else 'dark'
    _v36_apply_theme(self, mode)


def _v109_apply_responsive_window(win, role='main'):
    """Open windows at a sensible size without using the full width of curved/ultra-wide monitors."""
    try:
        win.resizable(True, True)
    except Exception:
        pass
    try:
        win.update_idletasks()
    except Exception:
        pass
    try:
        sw = int(win.winfo_screenwidth() or 1600)
        sh = int(win.winfo_screenheight() or 900)
    except Exception:
        sw, sh = 1600, 900
    # laptop-safe min/max sizing; ultra-wide screens get a centered working window, not a giant ribbon.
    if role == 'browser':
        w = min(1900, max(1220, int(sw * 0.94)))
        h = min(1050, max(720, int(sh * 0.88)))
    elif role == 'chat':
        w = min(1500, max(1000, int(sw * 0.82)))
        h = min(1000, max(720, int(sh * 0.86)))
    elif role == 'scilink':
        w = min(1400, max(980, int(sw * 0.78)))
        h = min(900, max(620, int(sh * 0.78)))
    else:
        w = min(1720, max(1180, int(sw * 0.90)))
        h = min(980, max(720, int(sh * 0.86)))
    if sw <= 1400:
        w = max(980, sw - 30)
        h = max(650, sh - 86)
    if sh <= 820:
        h = max(620, sh - 72)
    w = min(w, max(900, sw - 20))
    h = min(h, max(600, sh - 60))
    x = max(0, int((sw - w) / 2))
    y = max(0, int((sh - h) / 2) - 12)
    try:
        win.minsize(min(1050, max(800, w - 300)), min(650, max(520, h - 260)))
    except Exception:
        pass
    try:
        win.geometry(f'{w}x{h}+{x}+{y}')
    except Exception:
        pass
    return (w, h)


