def _v109_apply_title(window, base='FaradaIQ Studio v273'):
    try:
        base2 = re.sub(r'v\d+(?:\.\d+)?', 'v109', str(base))
    except Exception:
        base2 = 'FaradaIQ Studio v273'
    try:
        if callable(_V109_PREV_APPLY_TITLE):
            _V109_PREV_APPLY_TITLE(window, base2)
        else:
            window.title(base2)
        try:
            window.title(re.sub(r'v\d+(?:\.\d+)?', 'v109', str(window.title())))
        except Exception:
            pass
    except Exception:
        pass

