# ---- v109 patch: custom LLM Smart-comparison request + interactive popout ----
APP_TITLE = "FaradaIQ Studio v273"

# v109 goals:
# 1) Smart comparisons accepts a user prompt, e.g. "Compare cycle 2 at 50 mV/s across all points".
# 2) The selected LLM receives that prompt plus the real detected data structure/metadata and may return multiple actions.
# 3) Apply converts each suggestion to real numeric-data filters and adds/plots matching Plot/view items.
# 4) The Smart-comparison popout is live and clickable, not a black text snapshot.

try:
    import datetime as _v109_datetime_module
except Exception:
    _v109_datetime_module = None


def _v109_safe_now_label():
    try:
        return _v109_datetime_module.datetime.now().strftime('%Y%m%d_%H%M%S')
    except Exception:
        try:
            return datetime.now().strftime('%Y%m%d_%H%M%S')
        except Exception:
            return 'now'


def _v109_get_ai_request(browser):
    for attr in ('ai_compare_request_text', '_v109_ai_request_text'):
        try:
            w = getattr(browser, attr, None)
            if w is None:
                continue
            try:
                return str(w.get('1.0', 'end')).strip()
            except Exception:
                return str(w.get()).strip()
        except Exception:
            pass
    return ''


def _v109_set_ai_request(browser, text):
    for attr in ('ai_compare_request_text', '_v109_ai_request_text'):
        try:
            w = getattr(browser, attr, None)
            if w is None:
                continue
            try:
                w.delete('1.0', 'end'); w.insert('1.0', text or '')
            except Exception:
                w.delete(0, 'end'); w.insert(0, text or '')
            return
        except Exception:
            pass


def _v109_unique(items, limit=80):
    out, seen = [], set()
    for x in items or []:
        s = re.sub(r'\s+', ' ', str(x or '')).strip(' \t\r\n-•')
        if not s:
            continue
        key = s.lower()
        if key in seen:
            continue
        seen.add(key); out.append(s)
        if len(out) >= limit:
            break
    return out


def _v109_suggestion_list(browser):
    try:
        return _v109_unique(list(getattr(browser, 'suggestions', []) or []), limit=200)
    except Exception:
        return []


def _v109_fill_suggestions(browser, suggestions, source='v109'):
    suggestions = _v109_unique(suggestions or [], limit=120)
    if not suggestions:
        suggestions = ['Plot selected grouped numeric data and create a Plot/view item.']
    try:
        browser.suggestions = list(suggestions)
    except Exception:
        pass
    # Update only live Smart-comparison listboxes, not the Browser-log list/text that older versions reused.
    for lb in [getattr(browser, 'right_comp_list', None), getattr(browser, '_v109_popout_listbox', None)]:
        try:
            lb.delete(0, 'end')
            for s in suggestions:
                lb.insert('end', s)
        except Exception:
            pass
    try:
        if getattr(browser, 'quick_summary_text', None) is not None:
            note = f'Smart suggestions source: {source}. {len(suggestions)} action(s) ready. Select one and click Apply / add to Plot-view.'
            oldtxt = browser.quick_summary_text.get('1.0','end').strip()
            if 'Smart suggestions source:' not in oldtxt[-500:]:
                browser.quick_summary_text.insert('end', ('\n\n' if oldtxt else '') + note)
            else:
                # Replace last source note lightly.
                browser.quick_summary_text.delete('1.0','end')
                browser.quick_summary_text.insert('1.0', re.sub(r'Smart suggestions source:.*$', note, oldtxt, flags=re.S))
    except Exception:
        pass
    try: browser.log(f'Smart suggestions ready from {source}: {len(suggestions)} action(s).')
    except Exception: pass
    return suggestions

# Override older fillers so left Browser-log is not overwritten.
try:
    _v96_fill_suggestion_widgets = _v109_fill_suggestions
    _v103_fill_suggestion_widgets = _v109_fill_suggestions
except Exception:
    pass


def _v109_tags(browser, rec):
    try:
        ctx = getattr(browser, '_v83_experiment_context', {}) or {}
        tags = rec.get('_v90_tags') or (_v90_record_tags(rec, ctx) if '_v90_record_tags' in globals() else {}) or {}
        rec['_v90_tags'] = tags
        return tags
    except Exception:
        return rec.get('_v90_tags') or {}


def _v109_normnum(x):
    try:
        m = re.search(r'[-+]?\d+(?:\.\d+)?', str(x or ''))
        return float(m.group(0)) if m else None
    except Exception:
        return None


def _v109_intnum(x):
    try:
        m = re.search(r'\d+', str(x or ''))
        return int(m.group(0)) if m else None
    except Exception:
        return None


def _v109_available_values(browser, kind='CV / LSV'):
    vals = {'points': [], 'scan_rates': [], 'cycles': [], 'potentials': []}
    sets = {k: set() for k in vals}
    try:
        records = _v103_records(browser, kind) if '_v103_records' in globals() else list(getattr(browser, '_v80_records', []) or [])
        for r in records:
            tags = _v109_tags(browser, r)
            for out_key, tag_key in [('points','point'), ('scan_rates','scan'), ('cycles','cycle'), ('potentials','potential')]:
                v = tags.get(tag_key)
                if v not in (None, '', 'unassigned'):
                    sets[out_key].add(str(v))
    except Exception:
        pass
    def sk(s):
        try:
            return (_v80_num(s), _v80_nat_key(s)) if '_v80_num' in globals() and '_v80_nat_key' in globals() else (999999, str(s).lower())
        except Exception: return (999999, str(s).lower())
    for k in vals:
        vals[k] = sorted(sets[k], key=sk)
    return vals


def _v109_extract_filters(text):
    low = str(text or '').lower()
    f = {'kind': None, 'scan_numbers': [], 'cycle_numbers': [], 'point_numbers': [], 'potential_numbers': [], 'all_points': False, 'every_points': False, 'every_scans': False, 'every_cycles': False}
    if any(x in low for x in ['eis','nyquist','bode','impedance','zreal','zimag','phase']): f['kind'] = 'EIS'
    elif any(x in low for x in ['cv','lsv','voltam','scan rate','scan-rate','cycle','pysimpleechem','peak current','peak potential']): f['kind'] = 'CV / LSV'
    elif 'drt' in low: f['kind'] = 'DRT'
    # Explicit scan rate numbers, e.g. 50 mV/s, 100mVps.
    for m in re.finditer(r'(\d+(?:\.\d+)?)\s*(?:m\s*v\s*/?\s*s|mvps|mvs|mv\s*per\s*s|mv/s)', low, flags=re.I):
        try: f['scan_numbers'].append(float(m.group(1)))
        except Exception: pass
    # Cycles: cycle 2, 2nd cycle, cycle #3.
    for m in re.finditer(r'(?:cycle|cyc)\s*(?:#|number|no\.?|=|:)?\s*(\d+)', low, flags=re.I):
        try: f['cycle_numbers'].append(int(m.group(1)))
        except Exception: pass
    for m in re.finditer(r'(\d+)\s*(?:st|nd|rd|th)\s*(?:cycle|cyc)', low, flags=re.I):
        try: f['cycle_numbers'].append(int(m.group(1)))
        except Exception: pass
    # Points: point 4, P04. Avoid treating 11 points inventory as a single requested point if preceded by all/across.
    for m in re.finditer(r'(?<!all\s)(?<!across\s)(?:point|position|pos|p)\s*0*(\d+)\b', low, flags=re.I):
        try: f['point_numbers'].append(int(m.group(1)))
        except Exception: pass
    if 'all point' in low or 'across point' in low or 'across all point' in low: f['all_points'] = True
    if any(x in low for x in ['every point', 'each point', 'one plot per point', 'for each point']): f['every_points'] = True
    if any(x in low for x in ['every scan', 'each scan', 'for each scan', 'one plot per scan']): f['every_scans'] = True
    if any(x in low for x in ['every cycle', 'each cycle', 'for each cycle', 'one plot per cycle']): f['every_cycles'] = True
    # EIS potentials/biases: only collect when EIS-ish to avoid scan-rate confusion.
    if f['kind'] == 'EIS':
        for m in re.finditer(r'([-+]?\d+(?:\.\d+)?)\s*(m\s*v|mv|v)\b', low, flags=re.I):
            val = float(m.group(1)); unit = m.group(2).replace(' ','').lower()
            if unit == 'mv': val = val / 1000.0
            f['potential_numbers'].append(val)
    f['scan_numbers'] = sorted(set(f['scan_numbers']))
    f['cycle_numbers'] = sorted(set(f['cycle_numbers']))
    f['point_numbers'] = sorted(set(f['point_numbers']))
    f['potential_numbers'] = sorted(set(round(x, 9) for x in f['potential_numbers']))
    return f


def _v109_match_num(tag_value, wanted, tol=1e-6):
    if not wanted:
        return True
    n = _v109_normnum(tag_value)
    if n is None:
        return False
    for w in wanted:
        try:
            if abs(float(n) - float(w)) <= max(tol, abs(float(w))*0.02):
                return True
        except Exception:
            pass
    return False


def _v109_match_int(tag_value, wanted):
    if not wanted:
        return True
    n = _v109_intnum(tag_value)
    return n in set(int(x) for x in wanted) if n is not None else False


def _v109_filter_records(browser, text, override=None):
    f = _v109_extract_filters(text)
    if override:
        f.update({k:v for k,v in override.items() if v not in (None, [], '')})
    kind = f.get('kind') or ('EIS' if 'eis' in str(text).lower() else 'CV / LSV')
    try:
        records = _v103_records(browser, kind) if '_v103_records' in globals() else list(getattr(browser, '_v80_records', []) or [])
    except Exception:
        records = []
    out = []
    for r in records:
        try:
            tags = _v109_tags(browser, r)
            if f.get('scan_numbers') and not _v109_match_num(tags.get('scan'), f['scan_numbers'], tol=0.05):
                continue
            if f.get('cycle_numbers') and not _v109_match_int(tags.get('cycle'), f['cycle_numbers']):
                continue
            if f.get('point_numbers') and not _v109_match_int(tags.get('point'), f['point_numbers']):
                continue
            if f.get('potential_numbers'):
                pot = tags.get('potential') or tags.get('bias') or ''
                n = _v109_normnum(pot)
                # if tag is in mV text, normalize approximate; tolerant enough for labels like 10 mV vs 0.010 V.
                low = str(pot).lower()
                if n is not None and 'mv' in low: n = n / 1000.0
                if n is None or not any(abs(n-w) <= max(1e-5, abs(w)*0.03) for w in f['potential_numbers']):
                    continue
            out.append(r)
        except Exception:
            pass
    return out, f, kind


def _v109_paths_from_filtered(browser, text, override=None):
    records, f, kind = _v109_filter_records(browser, text, override=override)
    try:
        paths = _v103_paths_from_records(records) if '_v103_paths_from_records' in globals() else [Path(r.get('path')) for r in records]
    except Exception:
        paths = []
    try:
        if paths and '_v89_deduplicate_paths_for_plot' in globals():
            paths = _v89_deduplicate_paths_for_plot(browser, paths)
    except Exception:
        pass
    return paths, f, kind


def _v109_make_view_name(text, max_len=110):
    s = re.sub(r'[^A-Za-z0-9_ .,/()\-]+', '', str(text or '')).strip()
    s = re.sub(r'\s+', ' ', s)
    return (s[:max_len].rstrip() or 'AI smart comparison')


def _v109_add_or_plot_suggestion(browser, suggestion, plot_now=True):
    low = str(suggestion or '').lower()
    if 'pysimpleechem' in low:
        try:
            _v89_open_native_pysimpleechem_with_selected(browser)
        except Exception as exc:
            try: browser.log(f'PySimpleEChem smart action failed: {exc}')
            except Exception: pass
        return True
    if 'export current' in low:
        try:
            if hasattr(browser, 'export_all'): browser.export_all(); return True
        except Exception: pass
    paths, filt, kind = _v109_paths_from_filtered(browser, suggestion)
    if not paths:
        # Fall back to current selection if text did not parse to filters.
        try:
            paths = _v103_selected_paths_if_useful(browser, kind) if '_v103_selected_paths_if_useful' in globals() else []
        except Exception:
            paths = []
    if not paths:
        try:
            browser.log(f'No numeric plottable files matched AI smart suggestion: {suggestion}')
            if hasattr(browser, 'status_var'): browser.status_var.set('No files matched that AI smart-comparison request. Try a valid point/scan rate/cycle from the detected experiment map.')
        except Exception: pass
        return False
    mode = _v100_mode_from_text(suggestion, kind) if '_v100_mode_from_text' in globals() else ('CV / LSV' if kind == 'CV / LSV' else 'Auto')
    name = _v109_make_view_name(suggestion)
    if plot_now:
        try:
            return _v100_create_comparison_view(browser, paths, kind, mode=mode, name=name) if '_v100_create_comparison_view' in globals() else _v91_create_comparison_view(browser, paths, kind, mode=mode, name=name)
        except Exception:
            try: return _v91_create_comparison_view(browser, paths, kind, mode=mode, name=name)
            except Exception as exc:
                try: browser.log(f'Could not plot AI smart comparison: {exc}')
                except Exception: pass
                return False
    else:
        try:
            if '_v103_add_plot_view_without_plotting' in globals():
                ok = _v103_add_plot_view_without_plotting(browser, paths, kind, name, mode=mode)
                if ok:
                    try: browser.log(f'Added Plot/view from AI suggestion: {name} ({len(paths)} file(s)).')
                    except Exception: pass
                return ok
        except Exception:
            pass
        # Last fallback plots if lazy add is unavailable.
        return _v109_add_or_plot_suggestion(browser, suggestion, plot_now=True)


def _v109_apply_selected_suggestion(browser):
    try:
        suggestion = _v103_selected_suggestion(browser) if '_v103_selected_suggestion' in globals() else _v91_get_selected_suggestion(browser)
    except Exception:
        suggestion = ''
    if not suggestion:
        try: _v109_custom_smart_suggest(browser)
        except Exception: pass
        return
    # Family actions from v103 still work.
    low = str(suggestion).lower()
    if any(x in low for x in ['every point', 'every scan', 'every cycle', 'for every point', 'for every scan', 'for every cycle']) and '_v103_apply_selected_suggestion' in globals():
        try: return _v103_apply_selected_suggestion(browser)
        except Exception: pass
    return _v109_add_or_plot_suggestion(browser, suggestion, plot_now=True)

try:
    FaradaIQDataBrowser.apply_selected_suggestion = _v109_apply_selected_suggestion
    _v91_apply_selected_suggestion = _v109_apply_selected_suggestion
    _v100_apply_selected_suggestion = _v109_apply_selected_suggestion
except Exception:
    pass


def _v109_rule_suggestions_from_query(browser, query):
    query = str(query or '').strip()
    if not query:
        try: return list(_v103_builtin_suggestions(browser))
        except Exception: return ['Plot selected grouped numeric data and create a Plot/view item.']
    f = _v109_extract_filters(query)
    kind = f.get('kind') or 'CV / LSV'
    vals = _v109_available_values(browser, kind)
    out = []
    def scan_label(num):
        for s in vals.get('scan_rates', []):
            if _v109_match_num(s, [num], tol=0.05): return s
        return f'{num:g} mV/s'
    def cyc_label(num): return f'cycle {int(num)}'
    # Generate multiple action lines when user asks every/each.
    if kind == 'CV / LSV':
        cycles = f.get('cycle_numbers') or []
        scans = f.get('scan_numbers') or []
        points = f.get('point_numbers') or []
        if f.get('every_scans') or ('for each scan' in query.lower()):
            for s in vals.get('scan_rates', []) or [scan_label(x) for x in scans]:
                tail = f'{s}'
                if cycles: tail += f', {cyc_label(cycles[0])}'
                if points: tail += f', point {points[0]:02d}'
                else: tail += ', across all points'
                out.append(f'Plot CV overlay: {tail}.')
        elif f.get('every_points'):
            for pnt in vals.get('points', []):
                tail = f'{pnt}'
                if scans: tail += f', {scan_label(scans[0])}'
                if cycles: tail += f', {cyc_label(cycles[0])}'
                out.append(f'Plot CV overlay: {tail}.')
        elif f.get('every_cycles'):
            for c in vals.get('cycles', []):
                tail = c
                if scans: tail += f', {scan_label(scans[0])}'
                if points: tail += f', point {points[0]:02d}'
                else: tail += ', across all points'
                out.append(f'Plot CV overlay: {tail}.')
        elif scans or cycles or points or f.get('all_points'):
            tail = []
            if scans: tail.append(scan_label(scans[0]))
            if cycles: tail.append(cyc_label(cycles[0]))
            if points: tail.append(f'point {points[0]:02d}')
            elif f.get('all_points') or 'all point' in query.lower(): tail.append('across all points')
            out.append('Plot CV overlay: ' + ', '.join(tail) + '.')
            if scans and cycles and not points:
                out.append('Compare CV peak-current trend by point: ' + scan_label(scans[0]) + f', {cyc_label(cycles[0])}.')
                out.append('Compare CV peak-potential trend by point: ' + scan_label(scans[0]) + f', {cyc_label(cycles[0])}.')
    elif kind == 'EIS':
        if f.get('every_points') or 'all point' in query.lower() or 'across point' in query.lower():
            out.append('Plot EIS Nyquist overlay across all points from numeric impedance tables.')
            out.append('Plot EIS Bode magnitude overlay across all points from numeric impedance tables.')
        else:
            out.append('Plot EIS Nyquist comparison from numeric impedance tables for the requested point/potential.')
            out.append('Plot EIS Bode magnitude comparison from numeric impedance tables for the requested point/potential.')
    if not out:
        out = [query]
    return _v109_unique(out, limit=40)


def _v109_build_llm_messages_for_custom(browser, query, ctx):
    avail_cv = _v109_available_values(browser, 'CV / LSV')
    avail_eis = _v109_available_values(browser, 'EIS')
    system = (
        'You are the FaradaIQ Smart-comparison action planner. The user will give a custom comparison request. '
        'Use ONLY the supplied dataset structure and available values. Return one or more GUI-executable action lines. '
        'Do not invent scan rates, cycles, points, potentials, or techniques. If the request implies multiple plots, return multiple action lines. '
        'Each action line must be concise and include enough filters for FaradaIQ to execute, such as technique, scan rate, cycle, point, potential, and group-by. '
        'Prefer forms like: "Plot CV overlay: 50 mV/s, cycle 2, across all points" or "Plot CV overlay: point 04, 100 mV/s, cycle 3" or "Plot EIS Nyquist overlay across all points". '
        'Return JSON only as {"suggestions": ["...", "..."]}.'
    )
    payload = {
        'user_custom_request': query,
        'available_cv_values': avail_cv,
        'available_eis_values': avail_eis,
        'faradaiq_context': ctx,
    }
    user = 'Create FaradaIQ Smart-comparison suggestions for this custom user request.\n\n' + json.dumps(payload, ensure_ascii=False, indent=2, default=str)[:120000]
    return [{'role':'system','content':system}, {'role':'user','content':user}]


def _v109_save_custom_suggestions(browser, query, ctx, response, suggestions, source, error=None):
    try:
        root = Path(getattr(browser, 'analyzed_root', '') or getattr(browser, 'analysis_root', '') or getattr(browser, 'folder', '.') or '.')
        outdir = root / 'comparison_tables'
        outdir.mkdir(parents=True, exist_ok=True)
        p = outdir / f'smart_comparison_custom_request_v109_{_v109_safe_now_label()}.json'
        p.write_text(json.dumps({
            'created': _v109_safe_now_label(),
            'query': query,
            'source': source,
            'error': str(error) if error else '',
            'context': ctx,
            'raw_response': str(response or ''),
            'suggestions': suggestions,
        }, ensure_ascii=False, indent=2, default=str), encoding='utf-8')
        return p
    except Exception:
        return None


def _v109_custom_smart_suggest(browser, query=None, append=None):
    query = query if query is not None else _v109_get_ai_request(browser)
    query = str(query or '').strip()
    if append is None:
        try: append = bool(browser._v109_append_suggestions_var.get())
        except Exception: append = False
    base_existing = _v109_suggestion_list(browser) if append else []
    fallback = _v109_rule_suggestions_from_query(browser, query)
    pending = base_existing + ([f'Asking selected LLM for custom smart comparisons: {query or "general suggestions"}'] if query else ['Asking selected LLM for smart comparisons...']) + fallback[:5]
    _v109_fill_suggestions(browser, pending, source='LLM pending')
    try:
        browser.status_var.set('Asking selected LLM for custom Smart-comparison suggestions...')
        browser.log(f'Custom Smart-comparison request sent to selected LLM: {query or "(general suggestions)"}')
    except Exception: pass

    def worker():
        ctx = {}
        suggestions = list(fallback)
        response = ''
        source = 'rule-based fallback'
        err = None
        try:
            ctx = _v96_current_browser_context(browser) if '_v96_current_browser_context' in globals() else {'available_cv_values': _v109_available_values(browser, 'CV / LSV')}
            if query:
                ctx['custom_user_comparison_request'] = query
            messages = _v109_build_llm_messages_for_custom(browser, query, ctx)
            response, provider = _v37_call_best_llm(messages, max_tokens=2400, temperature=0.10)
            parsed = _v96_parse_llm_suggestions(response) if '_v96_parse_llm_suggestions' in globals() else []
            if parsed:
                suggestions = parsed
                pname = provider.get('name', 'selected LLM') if isinstance(provider, dict) else 'selected LLM'
                source = pname
            else:
                source = 'rule-based fallback after empty LLM response'
        except Exception as exc:
            err = exc
            source = 'rule-based fallback; LLM unavailable'
        suggestions = _v109_unique((base_existing if append else []) + suggestions + ([] if query else fallback), limit=80)
        try: _v109_save_custom_suggestions(browser, query, ctx, response, suggestions, source, error=err)
        except Exception: pass
        def finish():
            _v109_fill_suggestions(browser, suggestions, source=source)
            try: browser.status_var.set(f'Smart-comparison suggestions ready from {source}.')
            except Exception: pass
            if err:
                try: browser.log(f'LLM custom Smart-comparison request failed; used rule-based fallback. Error: {err}')
                except Exception: pass
        try: browser.after(0, finish)
        except Exception: finish()
    threading.Thread(target=worker, daemon=True).start()
    return fallback


def _v109_add_all_suggestions_to_plotviews(browser):
    suggestions = _v109_suggestion_list(browser)
    if not suggestions:
        try: browser.status_var.set('No Smart-comparison suggestions to add.')
        except Exception: pass
        return 0
    made = 0
    for s in suggestions:
        if str(s).lower().startswith('asking selected llm'):
            continue
        try:
            if _v109_add_or_plot_suggestion(browser, s, plot_now=False):
                made += 1
        except Exception as exc:
            try: browser.log(f'Could not add suggestion to Plot/view: {s} ({exc})')
            except Exception: pass
    try:
        browser.status_var.set(f'Added {made} Smart-comparison suggestion(s) to Plot/view list.')
        browser.log(f'Added {made} Smart-comparison suggestion(s) to Plot/view list without plotting them immediately.')
        if '_v75_save_session' in globals(): _v75_save_session(browser, silent=True)
    except Exception: pass
    return made


def _v109_install_custom_smart_ui(browser):
    try:
        if getattr(browser, '_v109_custom_smart_ui_added', False):
            return
        lb = getattr(browser, 'right_comp_list', None)
        if lb is None:
            return
        lb_frame = lb.master
        panel = lb_frame.master
        req_frame = ttk.LabelFrame(panel, text='Ask AI for custom comparison suggestions', padding=(6, 4))
        try:
            req_frame.pack(fill='x', pady=(0, 5), before=lb_frame)
        except Exception:
            req_frame.pack(fill='x', pady=(0, 5))
        browser._v109_ai_request_text = tk.Text(req_frame, height=2, wrap='word')
        browser._v109_ai_request_text.pack(fill='x', expand=True, side='top')
        try:
            browser._v109_ai_request_text.insert('1.0', '')
        except Exception: pass
        row = ttk.Frame(req_frame)
        row.pack(fill='x', pady=(4,0))
        browser._v109_append_suggestions_var = tk.BooleanVar(value=False)
        ask_btn = ttk.Button(row, text='Ask AI', command=lambda b=browser: _v109_custom_smart_suggest(b))
        ask_btn.pack(side='left', padx=(0,4))
        add_all_btn = ttk.Button(row, text='Add all to Plot/view', command=lambda b=browser: _v109_add_all_suggestions_to_plotviews(b))
        add_all_btn.pack(side='left', padx=(0,4))
        cb = ttk.Checkbutton(row, text='Append suggestions', variable=browser._v109_append_suggestions_var)
        cb.pack(side='left', padx=(4,0))
        try:
            _v103_add_tooltip(browser._v109_ai_request_text, 'Type a natural-language comparison request. Example: Compare only cycle 2 at 50 mV/s across all points. The selected LLM receives this request with the detected data structure and returns one or more actionable Smart-comparison lines.')
            _v103_add_tooltip(ask_btn, 'Ask the selected LLM to turn your custom request into one or more validated Smart-comparison actions.')
            _v103_add_tooltip(add_all_btn, 'Add every current Smart-comparison suggestion to the Plot/view list without plotting each one immediately.')
            _v103_add_tooltip(cb, 'When checked, new AI suggestions are appended to the current list instead of replacing it.')
        except Exception: pass
        # Rewire buttons in the smart panel.
        for w in list(_v95_iter_widgets(panel) if '_v95_iter_widgets' in globals() else panel.winfo_children()):
            try:
                txt = _v95_widget_text(w) if '_v95_widget_text' in globals() else str(w.cget('text'))
                if txt == 'Suggest':
                    w.configure(command=lambda b=browser: _v109_custom_smart_suggest(b))
                elif txt.startswith('Apply'):
                    w.configure(command=lambda b=browser: _v109_apply_selected_suggestion(b))
            except Exception: pass
        browser._v109_custom_smart_ui_added = True
    except Exception as exc:
        try: browser.log(f'Could not install v109 custom Smart-comparison UI: {exc}')
        except Exception: pass


def _v109_popout_smart_comparisons(browser):
    try:
        win = tk.Toplevel(browser)
        win.title('Smart comparisons / quick analysis — interactive')
        try: win.geometry('980x680')
        except Exception: pass
        try: _v36_apply_theme(win, getattr(getattr(browser, 'gui', None), '_faradaiq_theme_mode', getattr(browser, '_faradaiq_theme_mode', 'light')))
        except Exception: pass
        top = ttk.LabelFrame(win, text='Ask AI for custom comparison suggestions', padding=(8, 6))
        top.pack(fill='x', padx=8, pady=(8,4))
        txt = tk.Text(top, height=3, wrap='word')
        txt.pack(fill='x', expand=True)
        try: txt.insert('1.0', _v109_get_ai_request(browser) or '')
        except Exception: pass
        row = ttk.Frame(top); row.pack(fill='x', pady=(6,0))
        append_var = tk.BooleanVar(value=False)
        status = tk.StringVar(value='Ready. Ask AI, then select suggestions and apply/add them to Plot/view.')
        list_frame = ttk.LabelFrame(win, text='Clickable Smart-comparison suggestions', padding=(8, 6))
        list_frame.pack(fill='both', expand=True, padx=8, pady=4)
        lb = tk.Listbox(list_frame, exportselection=False, selectmode='extended')
        y = ttk.Scrollbar(list_frame, orient='vertical', command=lb.yview)
        lb.configure(yscrollcommand=y.set)
        lb.pack(side='left', fill='both', expand=True); y.pack(side='right', fill='y')
        browser._v109_popout_listbox = lb
        def refresh_lb():
            lb.delete(0,'end')
            for s in _v109_suggestion_list(browser): lb.insert('end', s)
            try: status.set(f'{lb.size()} suggestion(s) shown.')
            except Exception: pass
        def ask_ai():
            _v109_set_ai_request(browser, txt.get('1.0','end').strip())
            try: browser._v109_append_suggestions_var.set(bool(append_var.get()))
            except Exception: pass
            _v109_custom_smart_suggest(browser, append=bool(append_var.get()))
            status.set('Asking selected LLM; suggestions will update here and in the browser list.')
            try: win.after(900, refresh_lb); win.after(2500, refresh_lb); win.after(6000, refresh_lb)
            except Exception: pass
        def apply_selected():
            inds = list(lb.curselection() or [])
            if not inds:
                status.set('Select one or more suggestions first.'); return
            ok = 0
            for i in inds:
                if _v109_add_or_plot_suggestion(browser, lb.get(i), plot_now=True): ok += 1
            status.set(f'Applied {ok} selected suggestion(s).')
        def add_selected():
            inds = list(lb.curselection() or [])
            if not inds:
                status.set('Select one or more suggestions first.'); return
            ok = 0
            for i in inds:
                if _v109_add_or_plot_suggestion(browser, lb.get(i), plot_now=False): ok += 1
            status.set(f'Added {ok} selected suggestion(s) to Plot/view list.')
        def add_all():
            ok = _v109_add_all_suggestions_to_plotviews(browser)
            status.set(f'Added {ok} suggestion(s) to Plot/view list.')
        ttk.Button(row, text='Ask AI', command=ask_ai).pack(side='left', padx=(0,4))
        ttk.Checkbutton(row, text='Append suggestions', variable=append_var).pack(side='left', padx=(4,10))
        ttk.Button(row, text='Refresh list', command=refresh_lb).pack(side='left', padx=4)
        actions = ttk.Frame(win); actions.pack(fill='x', padx=8, pady=(4,2))
        ttk.Button(actions, text='Apply selected / plot now', command=apply_selected).pack(side='left', fill='x', expand=True, padx=(0,4))
        ttk.Button(actions, text='Add selected to Plot/view', command=add_selected).pack(side='left', fill='x', expand=True, padx=4)
        ttk.Button(actions, text='Add all to Plot/view', command=add_all).pack(side='left', fill='x', expand=True, padx=(4,0))
        ttk.Label(win, textvariable=status, style='Muted.TLabel').pack(fill='x', padx=10, pady=(2,8))
        lb.bind('<Double-Button-1>', lambda e: apply_selected())
        refresh_lb()
        try: _v36_apply_theme(win, getattr(getattr(browser, 'gui', None), '_faradaiq_theme_mode', getattr(browser, '_faradaiq_theme_mode', 'light')))
        except Exception: pass
        return win
    except Exception as exc:
        try: messagebox.showerror('Smart-comparison popout failed', str(exc), parent=browser)
        except Exception: pass


def _v109_patch_smart_widgets(browser):
    try:
        _v109_install_custom_smart_ui(browser)
    except Exception: pass
    try:
        # Rewire smart popout buttons. The button is usually near the right_comp_list or labeled ↗.
        lb = getattr(browser, 'right_comp_list', None)
        panel = lb.master.master if lb is not None else browser
        for w in list(_v95_iter_widgets(panel) if '_v95_iter_widgets' in globals() else panel.winfo_children()):
            try:
                txt = _v95_widget_text(w) if '_v95_widget_text' in globals() else str(w.cget('text'))
                if txt == '↗':
                    w.configure(command=lambda b=browser: _v109_popout_smart_comparisons(b))
                elif txt == 'Suggest':
                    w.configure(command=lambda b=browser: _v109_custom_smart_suggest(b))
                elif txt.startswith('Apply'):
                    w.configure(command=lambda b=browser: _v109_apply_selected_suggestion(b))
            except Exception:
                pass
    except Exception: pass

