# ============================
# v109 startup recursion guard
# ============================
def _v109_session_init_is_recursive_guarded():
    """Detect and prevent accidental re-wrapping of SessionReaderGUI.__init__ with a global PREV pointer."""
    try:
        init = getattr(SessionReaderGUI, '__init__', None)
        name = getattr(init, '__name__', '')
        # If future patches accidentally point the global previous-init at the active init,
        # force a safe wrapper chain by using the default-bound wrapper applied above.
        if name == '_v109_session_reader_gui_init_b' and globals().get('_V109_PREV_ROOT_INIT_B') is init:
            if '_V109_PREV_ROOT_INIT_A' in globals():
                SessionReaderGUI.__init__ = globals().get('_v109_session_reader_gui_init_a', init)
        return True
    except Exception:
        return False
_v109_session_init_is_recursive_guarded()

