# ============================
# v110 patch: professional plot export manager + live plot popout
# ============================
APP_TITLE = "FaradaIQ Studio v273"

# v110 goals:
# 1) Export the currently displayed plot as figure + CSV + HDF5, not PNG only.
# 2) Let user edit plot title, X-axis label, and Y-axis label before exporting.
# 3) Add a working live plot popout and rewire/hide the old lower plot-log popout button.


def _v110_safe_now_label():
    try:
        return datetime.now().strftime('%Y%m%d_%H%M%S')
    except Exception:
        try:
            import datetime as _dt
            return _dt.datetime.now().strftime('%Y%m%d_%H%M%S')
        except Exception:
            return 'now'


def _v110_safe_name(value, max_len=90):
    try:
        if '_v35_safe_name' in globals():
            return _v35_safe_name(str(value or 'plot'))[:max_len]
    except Exception:
        pass
    s = re.sub(r'[^A-Za-z0-9_.\-]+', '_', str(value or 'plot')).strip('_.-')
    return (s or 'plot')[:max_len]


def _v110_get_plot_labels(browser):
    ax = getattr(browser, 'ax', None)
    try: title = ax.get_title() if ax is not None else ''
    except Exception: title = ''
    try: xlabel = ax.get_xlabel() if ax is not None else ''
    except Exception: xlabel = ''
    try: ylabel = ax.get_ylabel() if ax is not None else ''
    except Exception: ylabel = ''
    return str(title or ''), str(xlabel or ''), str(ylabel or '')


def _v110_apply_plot_labels(browser, title=None, xlabel=None, ylabel=None, draw=True):
    ax = getattr(browser, 'ax', None)
    if ax is None:
        return False
    try:
        if title is not None: ax.set_title(str(title))
        if xlabel is not None: ax.set_xlabel(str(xlabel))
        if ylabel is not None: ax.set_ylabel(str(ylabel))
        try: getattr(browser, 'figure', None).tight_layout()
        except Exception: pass
        if draw:
            try: browser.canvas.draw_idle()
            except Exception: pass
        return True
    except Exception as exc:
        try: browser.log(f'Could not apply plot labels: {exc}')
        except Exception: pass
        return False


def _v110_curve_rows_from_browser(browser):
    rows = []
    curves = list(getattr(browser, 'curves', []) or [])
    # Prefer FaradaIQ curve records because they retain source file + columns.
    for idx, c in enumerate(curves, 1):
        try:
            x = np.asarray(c.get('x', []), dtype=float)
            y = np.asarray(c.get('y', []), dtype=float)
            n = min(len(x), len(y))
            label = str(c.get('label') or f'curve {idx}')
            src = str(c.get('path') or '')
            xcol = str(c.get('xcol') or '')
            ycol = str(c.get('ycol') or '')
            for j in range(n):
                rows.append({'curve_index': idx, 'curve_label': label, 'point_index': j, 'x': float(x[j]), 'y': float(y[j]), 'source_file': src, 'x_column': xcol, 'y_column': ycol})
        except Exception:
            pass
    # Fallback: extract exactly displayed Matplotlib line data.
    if not rows:
        try:
            ax = getattr(browser, 'ax', None)
            for idx, line in enumerate(ax.get_lines() if ax is not None else [], 1):
                try:
                    label = str(line.get_label() or f'curve {idx}')
                    if label.startswith('_'):
                        label = f'curve {idx}'
                    x = np.asarray(line.get_xdata(), dtype=float)
                    y = np.asarray(line.get_ydata(), dtype=float)
                    n = min(len(x), len(y))
                    for j in range(n):
                        rows.append({'curve_index': idx, 'curve_label': label, 'point_index': j, 'x': float(x[j]), 'y': float(y[j]), 'source_file': '', 'x_column': '', 'y_column': ''})
                except Exception:
                    pass
        except Exception:
            pass
    return rows


def _v110_curves_to_long_df(browser):
    rows = _v110_curve_rows_from_browser(browser)
    try:
        import pandas as pd
        return pd.DataFrame(rows)
    except Exception:
        return rows


def _v110_curves_to_wide_df(browser):
    rows = _v110_curve_rows_from_browser(browser)
    try:
        import pandas as pd
        if not rows:
            return pd.DataFrame()
        by = {}
        for r in rows:
            by.setdefault((r['curve_index'], r['curve_label']), []).append(r)
        maxlen = max((len(v) for v in by.values()), default=0)
        cols = {}
        for (idx, label), vals in sorted(by.items(), key=lambda kv: kv[0][0]):
            key = _v110_safe_name(f'{idx:03d}_{label}', max_len=70)
            xs = [v.get('x') for v in vals]
            ys = [v.get('y') for v in vals]
            xs = xs + [float('nan')] * (maxlen - len(xs))
            ys = ys + [float('nan')] * (maxlen - len(ys))
            cols[f'{key}_x'] = xs
            cols[f'{key}_y'] = ys
        return pd.DataFrame(cols)
    except Exception:
        return []


def _v110_export_displayed_plot(browser, folder, base_name, title, xlabel, ylabel, do_png=True, do_svg=False, do_pdf=False, do_csv=True, do_hdf5=True):
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    base = _v110_safe_name(base_name or 'faradaiq_displayed_plot')
    _v110_apply_plot_labels(browser, title, xlabel, ylabel, draw=True)
    exported = []
    fig = getattr(browser, 'figure', None)
    if fig is not None:
        try: fig.tight_layout()
        except Exception: pass
    if fig is not None and do_png:
        p = folder / f'{base}.png'
        fig.savefig(p, dpi=300, bbox_inches='tight')
        exported.append(p)
    if fig is not None and do_svg:
        p = folder / f'{base}.svg'
        fig.savefig(p, bbox_inches='tight')
        exported.append(p)
    if fig is not None and do_pdf:
        p = folder / f'{base}.pdf'
        fig.savefig(p, bbox_inches='tight')
        exported.append(p)
    rows = _v110_curve_rows_from_browser(browser)
    if do_csv:
        try:
            import pandas as pd
            long_df = pd.DataFrame(rows)
            p1 = folder / f'{base}_displayed_curves_long.csv'
            long_df.to_csv(p1, index=False)
            exported.append(p1)
            wide_df = _v110_curves_to_wide_df(browser)
            if hasattr(wide_df, 'to_csv') and not wide_df.empty:
                p2 = folder / f'{base}_displayed_curves_wide.csv'
                wide_df.to_csv(p2, index=False)
                exported.append(p2)
        except Exception as exc:
            # Dependency-light CSV fallback.
            import csv
            p1 = folder / f'{base}_displayed_curves_long.csv'
            with open(p1, 'w', newline='', encoding='utf-8') as f:
                fields = ['curve_index','curve_label','point_index','x','y','source_file','x_column','y_column']
                w = csv.DictWriter(f, fieldnames=fields)
                w.writeheader()
                for r in rows: w.writerow({k: r.get(k, '') for k in fields})
            exported.append(p1)
            try: browser.log(f'CSV fallback used because pandas export failed: {exc}')
            except Exception: pass
    if do_hdf5:
        try:
            import h5py
            p = folder / f'{base}_displayed_curves.h5'
            with h5py.File(p, 'w') as h5:
                h5.attrs['app'] = 'FaradaIQ Studio'
                h5.attrs['version'] = 'v110'
                h5.attrs['created'] = _v110_safe_now_label()
                h5.attrs['plot_title'] = str(title or '')
                h5.attrs['x_axis_label'] = str(xlabel or '')
                h5.attrs['y_axis_label'] = str(ylabel or '')
                try: h5.attrs['plot_mode'] = str(getattr(browser, 'plot_mode_var', tk.StringVar(value='')).get())
                except Exception: pass
                grp = h5.create_group('displayed_curves')
                by = {}
                for r in rows:
                    by.setdefault((r['curve_index'], r['curve_label']), []).append(r)
                for (idx, label), vals in sorted(by.items(), key=lambda kv: kv[0][0]):
                    g = grp.create_group(f'curve_{idx:03d}')
                    g.attrs['label'] = str(label)
                    g.attrs['source_file'] = str(vals[0].get('source_file','') if vals else '')
                    g.attrs['x_column'] = str(vals[0].get('x_column','') if vals else '')
                    g.attrs['y_column'] = str(vals[0].get('y_column','') if vals else '')
                    g.create_dataset('x', data=np.asarray([v.get('x', np.nan) for v in vals], dtype=float))
                    g.create_dataset('y', data=np.asarray([v.get('y', np.nan) for v in vals], dtype=float))
            exported.append(p)
        except Exception as exc:
            try: messagebox.showwarning('HDF5 export skipped', f'HDF5 export failed or h5py is unavailable:\n{exc}', parent=browser)
            except Exception: pass
    # Save a tiny manifest for reproducibility.
    try:
        manifest = folder / f'{base}_export_manifest.json'
        manifest.write_text(json.dumps({
            'created': _v110_safe_now_label(),
            'app': 'FaradaIQ Studio v273',
            'plot_title': title,
            'x_axis_label': xlabel,
            'y_axis_label': ylabel,
            'base_name': str(getattr(browser, 'base_name', '')),
            'analysis_root': str(getattr(browser, 'analysis_root', '')),
            'n_displayed_curves': len(set((r.get('curve_index'), r.get('curve_label')) for r in rows)),
            'n_points_total': len(rows),
            'exported_files': [str(p) for p in exported],
        }, indent=2, ensure_ascii=False), encoding='utf-8')
        exported.append(manifest)
    except Exception:
        pass
    try:
        browser.log('Exported displayed plot bundle:\n' + '\n'.join(str(p) for p in exported))
        browser.status_var.set(f'Exported displayed plot bundle with {len(exported)} file(s).')
    except Exception:
        pass
    return exported


def _v110_default_export_folder(browser):
    try:
        root = Path(getattr(browser, 'analyzed_root', '') or getattr(browser, 'analysis_root', '') or '.')
        out = root / 'displayed_plot_exports'
        out.mkdir(parents=True, exist_ok=True)
        return out
    except Exception:
        out = Path.cwd() / 'displayed_plot_exports'
        out.mkdir(parents=True, exist_ok=True)
        return out


def _v110_open_plot_export_dialog(browser):
    if getattr(browser, 'figure', None) is None or getattr(browser, 'ax', None) is None:
        try: messagebox.showinfo('No plot', 'Plot data first, then export the displayed plot.', parent=browser)
        except Exception: pass
        return
    try:
        if not _v110_curve_rows_from_browser(browser):
            if not messagebox.askyesno('No numeric line data detected', 'No numeric line data were detected in the displayed plot. Export the figure only?', parent=browser):
                return
    except Exception:
        pass
    title0, xlabel0, ylabel0 = _v110_get_plot_labels(browser)
    win = tk.Toplevel(browser)
    win.title('Export displayed plot — figure + CSV + HDF5')
    try: win.geometry('780x520')
    except Exception: pass
    try: _v36_apply_theme(win, getattr(browser, '_faradaiq_theme_mode', getattr(getattr(browser, 'gui', None), '_faradaiq_theme_mode', 'light')))
    except Exception: pass
    main = ttk.Frame(win, padding=(12, 10))
    main.pack(fill='both', expand=True)
    ttk.Label(main, text='Displayed plot export manager', style='Section.TLabel').pack(anchor='w')
    ttk.Label(main, text='Edit title/axis labels, then export exactly the currently displayed curves as figure, CSV, and HDF5.', style='Muted.TLabel', wraplength=720).pack(anchor='w', pady=(2, 8))
    form = ttk.LabelFrame(main, text='Plot labels to apply before export', padding=(8, 6))
    form.pack(fill='x', pady=(0,8))
    title_var = tk.StringVar(value=title0)
    x_var = tk.StringVar(value=xlabel0)
    y_var = tk.StringVar(value=ylabel0)
    def add_row(r, label, var):
        ttk.Label(form, text=label, style='Muted.TLabel').grid(row=r, column=0, sticky='w', padx=(0,8), pady=3)
        ent = ttk.Entry(form, textvariable=var)
        ent.grid(row=r, column=1, sticky='ew', pady=3)
        return ent
    form.columnconfigure(1, weight=1)
    add_row(0, 'Plot title', title_var)
    add_row(1, 'X-axis label', x_var)
    add_row(2, 'Y-axis label', y_var)
    dest = ttk.LabelFrame(main, text='Output location and file base name', padding=(8, 6))
    dest.pack(fill='x', pady=(0,8))
    folder_var = tk.StringVar(value=str(_v110_default_export_folder(browser)))
    base0 = _v110_safe_name((title0 or getattr(browser, 'base_name', 'faradaiq_plot')) + '_' + _v110_safe_now_label(), max_len=85)
    base_var = tk.StringVar(value=base0)
    dest.columnconfigure(1, weight=1)
    ttk.Label(dest, text='Folder', style='Muted.TLabel').grid(row=0, column=0, sticky='w', padx=(0,8), pady=3)
    ttk.Entry(dest, textvariable=folder_var).grid(row=0, column=1, sticky='ew', pady=3)
    ttk.Button(dest, text='Choose', command=lambda: (lambda d: folder_var.set(d) if d else None)(filedialog.askdirectory(title='Choose plot export folder', initialdir=folder_var.get()))).grid(row=0, column=2, padx=(6,0))
    ttk.Label(dest, text='Base file name', style='Muted.TLabel').grid(row=1, column=0, sticky='w', padx=(0,8), pady=3)
    ttk.Entry(dest, textvariable=base_var).grid(row=1, column=1, sticky='ew', pady=3)
    formats = ttk.LabelFrame(main, text='Export formats', padding=(8, 6))
    formats.pack(fill='x', pady=(0,8))
    png_var = tk.BooleanVar(value=True)
    svg_var = tk.BooleanVar(value=False)
    pdf_var = tk.BooleanVar(value=False)
    csv_var = tk.BooleanVar(value=True)
    h5_var = tk.BooleanVar(value=True)
    ttk.Checkbutton(formats, text='PNG figure', variable=png_var).pack(side='left', padx=(0,12))
    ttk.Checkbutton(formats, text='SVG figure', variable=svg_var).pack(side='left', padx=(0,12))
    ttk.Checkbutton(formats, text='PDF figure', variable=pdf_var).pack(side='left', padx=(0,12))
    ttk.Checkbutton(formats, text='CSV data', variable=csv_var).pack(side='left', padx=(0,12))
    ttk.Checkbutton(formats, text='HDF5 data', variable=h5_var).pack(side='left', padx=(0,12))
    preview = ScrolledText(main, height=6, wrap='word')
    preview.pack(fill='both', expand=True, pady=(0,8))
    def update_preview():
        rows = _v110_curve_rows_from_browser(browser)
        ncurves = len(set((r.get('curve_index'), r.get('curve_label')) for r in rows))
        txt = [f'Current displayed numeric curves: {ncurves}', f'Total displayed points: {len(rows)}', '', 'Files to be written:']
        b = _v110_safe_name(base_var.get() or 'faradaiq_displayed_plot')
        if png_var.get(): txt.append(f'  {b}.png')
        if svg_var.get(): txt.append(f'  {b}.svg')
        if pdf_var.get(): txt.append(f'  {b}.pdf')
        if csv_var.get(): txt.extend([f'  {b}_displayed_curves_long.csv', f'  {b}_displayed_curves_wide.csv'])
        if h5_var.get(): txt.append(f'  {b}_displayed_curves.h5')
        txt.append(f'  {b}_export_manifest.json')
        preview.configure(state='normal')
        preview.delete('1.0', 'end')
        preview.insert('1.0', '\n'.join(txt))
        preview.configure(state='disabled')
    def apply_labels():
        _v110_apply_plot_labels(browser, title_var.get(), x_var.get(), y_var.get(), draw=True)
        update_preview()
    def export_now():
        try:
            exported = _v110_export_displayed_plot(browser, folder_var.get(), base_var.get(), title_var.get(), x_var.get(), y_var.get(), png_var.get(), svg_var.get(), pdf_var.get(), csv_var.get(), h5_var.get())
            messagebox.showinfo('Export complete', 'Exported displayed plot bundle:\n\n' + '\n'.join(str(p) for p in exported[:12]), parent=win)
            try: os.startfile(str(Path(folder_var.get())))
            except Exception: pass
        except Exception as exc:
            messagebox.showerror('Export failed', f'{exc}\n\n{traceback.format_exc()}', parent=win)
    btns = ttk.Frame(main)
    btns.pack(fill='x')
    ttk.Button(btns, text='Apply labels to current plot', command=apply_labels).pack(side='left', padx=(0,6))
    ttk.Button(btns, text='Export selected formats', command=export_now).pack(side='left', padx=(0,6))
    ttk.Button(btns, text='Open output folder', command=lambda: os.startfile(folder_var.get()) if hasattr(os, 'startfile') else None).pack(side='left', padx=(0,6))
    ttk.Button(btns, text='Close', command=win.destroy).pack(side='right')
    for v in (base_var,):
        try: v.trace_add('write', lambda *_: update_preview())
        except Exception: pass
    for v in (png_var, svg_var, pdf_var, csv_var, h5_var):
        try: v.trace_add('write', lambda *_: update_preview())
        except Exception: pass
    update_preview()
    try: _v36_apply_theme(win, getattr(browser, '_faradaiq_theme_mode', getattr(getattr(browser, 'gui', None), '_faradaiq_theme_mode', 'light')))
    except Exception: pass
    return win


def _v110_open_plot_label_dialog(browser):
    title0, xlabel0, ylabel0 = _v110_get_plot_labels(browser)
    win = tk.Toplevel(browser)
