def _v110_open_plot_popout(browser):
    if getattr(browser, 'ax', None) is None:
        try: messagebox.showinfo('No plot', 'Plot data first, then open the plot popout.', parent=browser)
        except Exception: pass
        return
    try:
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg, NavigationToolbar2Tk
        win = tk.Toplevel(browser)
        win.title('Current displayed plot — popout')
        try: win.geometry('980x720')
        except Exception: pass
        try: _v36_apply_theme(win, getattr(browser, '_faradaiq_theme_mode', getattr(getattr(browser, 'gui', None), '_faradaiq_theme_mode', 'light')))
        except Exception: pass
        top = ttk.Frame(win, padding=(8, 6)); top.pack(fill='x')
        ttk.Label(top, text='Current displayed plot', style='Section.TLabel').pack(side='left')
        fig = Figure(figsize=(9.2, 6.4), dpi=100)
        ax2 = fig.add_subplot(111)
        ax = browser.ax
        try:
            for line in ax.get_lines():
                label = line.get_label()
                if label and str(label).startswith('_'):
                    label = ''
                ax2.plot(line.get_xdata(), line.get_ydata(), linewidth=line.get_linewidth(), linestyle=line.get_linestyle(), marker=line.get_marker() if line.get_marker() not in {None, 'None'} else None, markersize=line.get_markersize(), label=label)
        except Exception:
            for r in _v110_curve_rows_from_browser(browser):
                pass
        try: ax2.set_title(ax.get_title())
        except Exception: pass
        try: ax2.set_xlabel(ax.get_xlabel())
        except Exception: pass
        try: ax2.set_ylabel(ax.get_ylabel())
        except Exception: pass
        try: ax2.set_xscale(ax.get_xscale()); ax2.set_yscale(ax.get_yscale())
        except Exception: pass
        try: ax2.grid(True, alpha=0.25)
        except Exception: pass
        try:
            handles, labels = ax2.get_legend_handles_labels()
            labels = [l for l in labels if l]
            if labels and len(labels) <= 30: ax2.legend(fontsize=8, loc='best')
        except Exception: pass
        try: fig.tight_layout()
        except Exception: pass
        canvas = FigureCanvasTkAgg(fig, master=win)
        canvas.get_tk_widget().pack(fill='both', expand=True, padx=8, pady=(0,4))
        toolbar = NavigationToolbar2Tk(canvas, win, pack_toolbar=False)
        toolbar.update(); toolbar.pack(fill='x', padx=8, pady=(0,6))
        canvas.draw_idle()
        row = ttk.Frame(win, padding=(8, 0)); row.pack(fill='x', pady=(0,8))
        ttk.Button(row, text='Edit labels in main plot', command=lambda: _v110_open_plot_label_dialog(browser)).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Export main displayed plot', command=lambda: _v110_open_plot_export_dialog(browser)).pack(side='left', padx=(0,6))
        ttk.Button(row, text='Close', command=win.destroy).pack(side='right')
        return win
    except Exception as exc:
        try: messagebox.showerror('Plot popout failed', f'{exc}\n\n{traceback.format_exc()}', parent=browser)
        except Exception: pass


def _v110_rewire_plot_buttons(browser):
    try:
        if getattr(browser, '_v110_plot_buttons_done', False):
            return
        widgets = list(_v95_iter_widgets(browser) if '_v95_iter_widgets' in globals() else [])
        export_buttons = []
        plot_buttons = []
        for w in widgets:
            try:
                txt = _v95_widget_text(w) if '_v95_widget_text' in globals() else str(w.cget('text'))
                if txt == 'Export':
                    export_buttons.append(w)
                elif txt == 'Plot / overlay selected':
                    plot_buttons.append(w)
            except Exception:
                pass
        for b in export_buttons:
            try:
                b.configure(text='Export plot/data', command=lambda br=browser: _v110_open_plot_export_dialog(br))
                if '_v103_add_tooltip' in globals(): _v103_add_tooltip(b, 'Export the currently displayed plot as PNG/SVG/PDF and the displayed curves as CSV/HDF5. Also edit title and axis labels before export.')
            except Exception: pass
        # Add explicit Labels and Popout plot buttons next to the central plotting toolbar.
        anchor = export_buttons[0] if export_buttons else (plot_buttons[0] if plot_buttons else None)
        if anchor is not None:
            parent = anchor.master
            lbl_exists = False; pop_exists = False
            for w in parent.winfo_children():
                try:
                    t = _v95_widget_text(w) if '_v95_widget_text' in globals() else str(w.cget('text'))
                    if t in {'Labels', 'Plot labels'}: lbl_exists = True
                    if t in {'Popout plot', 'Plot popout'}: pop_exists = True
                except Exception: pass
            if not lbl_exists:
                btn = ttk.Button(parent, text='Plot labels', command=lambda br=browser: _v110_open_plot_label_dialog(br))
                try: btn.pack(side='left', padx=(0,4), after=anchor)
                except Exception: btn.pack(side='left', padx=(0,4))
                if '_v103_add_tooltip' in globals(): _v103_add_tooltip(btn, 'Rename the plot title, X-axis label, and Y-axis label on the displayed plot.')
                anchor = btn
            if not pop_exists:
                btn = ttk.Button(parent, text='Popout plot', command=lambda br=browser: _v110_open_plot_popout(br))
                try: btn.pack(side='left', padx=(0,4), after=anchor)
                except Exception: btn.pack(side='left', padx=(0,4))
                if '_v103_add_tooltip' in globals(): _v103_add_tooltip(btn, 'Open the current displayed plot in a separate functional Matplotlib popout window.')
        browser._v110_plot_buttons_done = True
    except Exception as exc:
        try: browser.log(f'v110 plot button patch failed: {exc}')
        except Exception: pass


def _v110_rewire_bottom_plot_popout(browser):
    # The old tiny ↗ button below the plot came from the hidden central log and often opened nothing useful.
    # Rewire any unlabeled center-panel ↗ that is not attached to the experiment tree, smart panel, plot/view list, or browser log.
    try:
        tree = getattr(browser, 'tree', None)
        comp = getattr(browser, 'right_comp_list', None) or getattr(browser, 'comp_list', None)
        pv = getattr(browser, 'plot_view_list', None)
        left_log = getattr(browser, 'left_log_text', None)
        for w in list(_v95_iter_widgets(browser) if '_v95_iter_widgets' in globals() else []):
            try:
                txt = _v95_widget_text(w) if '_v95_widget_text' in globals() else str(w.cget('text'))
                if txt != '↗':
                    continue
                parent = w.master
                if tree is not None and ('_v91_parent_contains' in globals()) and _v91_parent_contains(parent, tree):
                    continue
                if comp is not None and ('_v91_parent_contains' in globals()) and _v91_parent_contains(parent, comp):
                    continue
                if pv is not None and ('_v91_parent_contains' in globals()) and _v91_parent_contains(parent, pv):
                    continue
                if left_log is not None and ('_v91_parent_contains' in globals()) and _v91_parent_contains(parent, left_log):
                    continue
                # If its parent is the center plot/log area, make it useful.
                w.configure(command=lambda br=browser: _v110_open_plot_popout(br))
                if '_v103_add_tooltip' in globals(): _v103_add_tooltip(w, 'Open the current displayed plot in a separate popout window.')
            except Exception:
                pass
    except Exception:
        pass


