APP_TITLE = "FaradaIQ Studio v273"


def _v111_widget_text(w):
    try:
        return str(w.cget('text'))
    except Exception:
        return ''


def _v111_is_descendant(widget, ancestor):
    try:
        cur = widget
        while cur is not None:
            if cur == ancestor:
                return True
            cur = cur.master
    except Exception:
        pass
    return False


def _v111_apply_axis_label_overrides(browser, draw=False):
    """Apply user-specified plot title/x/y labels after any plot/replot operation."""
    try:
        ax = getattr(browser, 'ax', None)
        if ax is None:
            return
        if getattr(browser, '_v111_custom_title_enabled', False):
            ax.set_title(str(getattr(browser, '_v111_plot_title', '')))
        if getattr(browser, '_v111_custom_xlabel_enabled', False):
            ax.set_xlabel(str(getattr(browser, '_v111_x_label', '')))
        if getattr(browser, '_v111_custom_ylabel_enabled', False):
            ax.set_ylabel(str(getattr(browser, '_v111_y_label', '')))
        if draw and getattr(browser, 'canvas', None) is not None:
            try:
                browser.figure.tight_layout()
            except Exception:
                pass
            browser.canvas.draw_idle()
    except Exception as exc:
        try: browser.log(f'Could not apply custom plot labels: {exc}')
        except Exception: pass


def _v111_apply_legend_mode(browser, draw=False):
    """Make Hidden / Short / Full legend mode affect already-displayed curves immediately."""
    try:
        ax = getattr(browser, 'ax', None)
        if ax is None:
            return
        mode = 'Short'
        try:
            mode = str(browser.legend_mode_var.get() or 'Short')
        except Exception:
            try:
                mode = _v89_get_legend_mode(browser)
            except Exception:
                mode = 'Short'
        mode_l = mode.strip().lower()
        # Remove old legend first so switching Hidden works immediately.
        try:
            old = ax.get_legend()
            if old is not None:
                old.remove()
        except Exception:
            pass
        lines = list(ax.get_lines() or [])
        curves = list(getattr(browser, 'curves', []) or [])
        for i, line in enumerate(lines):
            try:
                # Only relabel actual data curves. Leave peak markers/baselines alone.
                if i >= len(curves):
                    continue
                full = ''
                try:
                    full = str(curves[i].get('label') or curves[i].get('display_label') or '')
                except Exception:
                    full = ''
                if not full:
                    full = str(line.get_label() or f'curve {i+1}')
                if mode_l.startswith('hide'):
                    line.set_label('_nolegend_')
                else:
                    try:
                        lab = _v89_label_for_legend(full, mode)
                    except Exception:
                        lab = full if mode_l.startswith('full') else (full[:44] + '…' if len(full) > 45 else full)
                    line.set_label(lab)
            except Exception:
                pass
        if not mode_l.startswith('hide'):
            try:
                handles, labels = ax.get_legend_handles_labels()
                keep = [(h, l) for h, l in zip(handles, labels) if l and not str(l).startswith('_')]
                if keep:
                    hs, ls = zip(*keep)
                    ax.legend(hs, ls, fontsize=7, loc='best')
            except Exception:
                pass
        if draw and getattr(browser, 'canvas', None) is not None:
            try: browser.canvas.draw_idle()
            except Exception: pass
    except Exception as exc:
        try: browser.log(f'Could not apply legend mode: {exc}')
        except Exception: pass


