def _v111_finish_plot_axes(self):
    if callable(_V111_PREV_FINISH_PLOT_AXES):
        try:
            _V111_PREV_FINISH_PLOT_AXES(self)
        except Exception:
            pass
    # Re-apply the user's display choices after older plot routines reset labels/legends.
    try: _v111_apply_axis_label_overrides(self, draw=False)
    except Exception: pass
    try: _v111_apply_legend_mode(self, draw=False)
    except Exception: pass
    try:
        if getattr(self, 'figure', None) is not None:
            self.figure.tight_layout()
        if getattr(self, 'canvas', None) is not None:
            self.canvas.draw_idle()
    except Exception:
        pass


