# ---- v112 hotfix: robust Windows auto-run command-window launch cwd ----
# User report in v111: after AI bundle export completed, auto-run parser launch failed at
# subprocess.Popen(..., cwd=data_dir) with [WinError 267] The directory name is invalid.
# The batch itself already cd's into each parser working folder, so the command window
# should be launched from a stable app-local folder rather than a deep/generated data path.

APP_TITLE = "FaradaIQ Studio v273"

import os as _v112_os
import sys as _v112_sys
import json as _v112_json
import time as _v112_time
import tempfile as _v112_tempfile
import traceback as _v112_traceback
from pathlib import Path as _V112Path


def _v112_existing_dir(path):
    try:
        if path is None:
            return None
        p = _V112Path(path).expanduser()
        if p.exists() and p.is_dir():
            return p.resolve()
    except Exception:
        return None
    return None


def _v112_app_dir():
    try:
        return _V112Path(__file__).resolve().parent
    except Exception:
        try:
            return _V112Path.cwd().resolve()
        except Exception:
            return _V112Path('.')


def _v112_safe_launch_cwd(requested=None):
    """Return a stable directory for launching cmd.exe, never a generated/deep data folder.

    Parser BAT files cd into their own per-command folders.  The Popen cwd only needs to be
    a valid startup directory for cmd.exe.  Using generated analysis folders caused WinError
    267 on some Windows systems when the path was stale/deep/invalid.
    """
    app = _v112_existing_dir(_v112_app_dir())
    req = _v112_existing_dir(requested)
    # Prefer the app folder for Windows command-window launch.  It is short, stable, and exists.
    candidates = [app]
    # Keep requested as a fallback only when it is short and definitely valid.
    if req and len(str(req)) < 220:
        candidates.append(req)
    try:
        candidates.append(_V112Path.cwd().resolve())
    except Exception:
        pass
    try:
        candidates.append(_V112Path.home().resolve())
    except Exception:
        pass
    for c in candidates:
        if c and _v112_existing_dir(c):
            return _v112_existing_dir(c)
    return _V112Path('.')


def _v112_batch_dir():
    root = _v112_app_dir() / 'FaradaIQ_launch_sessions' / '_bat_scripts'
    try:
        root.mkdir(parents=True, exist_ok=True)
        return root
    except Exception:
        try:
            return _V112Path(_v112_tempfile.gettempdir())
        except Exception:
            return _v112_app_dir()


def _v22_write_bat_and_launch(batch_text, cwd=None, prefix="electrochem_bridge"):
    """v112 override: write BAT to an app-local folder and launch from a safe cwd.

    The older implementation launched cmd.exe with cwd set to the first generated data
    directory.  That can fail with WinError 267 even though the data exist, especially when
    Windows rejects a stale/deep generated path.  This function now launches cmd.exe from the
    FaradaIQ app folder; the BAT still cd's into each parser folder before each command.
    """
    safe_cwd = _v112_safe_launch_cwd(cwd)
    bat_root = _v112_batch_dir()
    try:
        stamp = _v112_time.strftime('%Y%m%d_%H%M%S')
        safe_prefix = ''.join(ch if ch.isalnum() or ch in ('_', '-') else '_' for ch in str(prefix or 'faradaiq'))[:40]
        bat_path = bat_root / f"{safe_prefix}_{stamp}_{_v112_os.getpid()}.bat"
        bat_path.write_text(str(batch_text or ''), encoding='utf-8', newline='\r\n')
    except Exception:
        fd, raw = _v112_tempfile.mkstemp(prefix=str(prefix or 'faradaiq') + '_', suffix='.bat', text=True)
        bat_path = _V112Path(raw)
        with _v112_os.fdopen(fd, 'w', encoding='utf-8', newline='\r\n') as f:
            f.write(str(batch_text or ''))

    if _v112_sys.platform.startswith('win'):
        flags = getattr(_v19_subprocess, 'CREATE_NEW_CONSOLE', 0) if '_v19_subprocess' in globals() else 0
        cmd = ['cmd.exe', '/k', str(bat_path)]
        try:
            _v19_subprocess.Popen(cmd, cwd=str(safe_cwd), creationflags=flags)
        except Exception as exc:
            # Retry from app dir/home before surfacing a readable error.
            retry_cwd = _v112_existing_dir(_v112_app_dir()) or _v112_existing_dir(_V112Path.home()) or safe_cwd
            try:
                _v19_subprocess.Popen(cmd, cwd=str(retry_cwd), creationflags=flags)
            except Exception as exc2:
                raise RuntimeError(
                    "Could not launch the parser command window.\n\n"
                    f"Original requested cwd: {cwd}\n"
                    f"Safe launch cwd tried: {safe_cwd}\n"
                    f"Retry cwd tried: {retry_cwd}\n"
                    f"Batch file written here: {bat_path}\n\n"
                    "You can open that BAT manually, or run FaradaIQ from a shorter folder path.\n"
                    f"Windows error: {exc2}"
                ) from exc2
    else:
        _v19_subprocess.Popen(['sh', str(bat_path)], cwd=str(safe_cwd))
    return bat_path


def _v112_filter_valid_dirs(dirs):
    out, seen = [], set()
    for d in dirs or []:
        p = _v112_existing_dir(d)
        if not p:
            continue
        key = str(p).lower() if _v112_sys.platform.startswith('win') else str(p)
        if key not in seen:
            seen.add(key)
            out.append(p)
    return out


def _v112_command_cwd(cwd):
    p = _v112_existing_dir(cwd)
    if p:
        return p
    try:
        pp = _V112Path(cwd).expanduser().parent
        p = _v112_existing_dir(pp)
        if p:
            return p
    except Exception:
        pass
    return _v112_safe_launch_cwd(None)


def _v112_sanitize_commands(commands, notes=None):
    cleaned = []
    notes = notes if isinstance(notes, list) else []
    for args, cwd in commands or []:
        safe = _v112_command_cwd(cwd)
        if str(safe) != str(cwd):
            notes.append(f"FaradaIQ v273 adjusted invalid parser cwd from {cwd} to {safe}")
        cleaned.append((args, safe))
    return cleaned, notes


def _v112_parser_analysis_root(data_dirs):
    for d in data_dirs or []:
        p = _v112_existing_dir(d)
        if not p:
            continue
        # Prefer the analysis_ready_csv folder above *_for_plotting_analysis/data.
        try:
            if p.name.lower() == 'data' and p.parent.name.endswith('_for_plotting_analysis'):
                return p.parent.parent
            if p.name.lower() in {'drt_input_csv', 'data_generated_from_heka'}:
                return p.parent
            return p.parent if p.name.lower() == 'data' else p
        except Exception:
            return p
    return _v112_app_dir()


def _v27_launch_auto_pyseccm_after_export(gui, base_name=None):
    """v112 override: launch parser auto-run from stable cwd and validate data dirs."""
    base_name = base_name or _v27_current_base_name(gui)
    data_dirs = _v112_filter_valid_dirs(_v27_candidate_plotting_data_dirs(gui, base_name=base_name))
    if not data_dirs:
        raise FileNotFoundError(
            "No valid generated parser data folder was found after export.\n"
            "The AI bundle may have completed, but no existing *_for_plotting_analysis/data, "
            "data_generated_from_HEKA, or DRT_input_csv folder was found for auto-run."
        )

    script_root = _v19_default_script_dir_for_gui(gui) or _v19_find_pyseccm_script_root([_v112_app_dir()]) or str(_v112_app_dir() / 'pyseccm_tools')
    python_exe = _v19_sys.executable
    missing = _v22_missing_modules_for_python(python_exe, kind='all')
    if missing:
        msg = "The auto-run pipeline needs pySECCM/DRT dependencies in the current Python environment.\n\nRepair/install them now?"
        if messagebox.askyesno("Auto-run dependencies", msg, parent=gui):
            _v22_install_dependencies_for_python(python_exe, kind='all', parent=gui)
        raise RuntimeError("Dependencies are missing or being repaired. Run Export again after the dependency window finishes.")

    all_commands, all_notes, folder_reports = [], [], []
    for d in data_dirs:
        try:
            cmds, notes, detected = _v27_build_auto_pyseccm_commands_for_data_dir(d, script_root=script_root, python_exe=python_exe, include_drt=True)
            cmds, all_notes = _v112_sanitize_commands(cmds, all_notes)
            all_commands.extend(cmds)
            all_notes.extend(notes or [])
            folder_reports.append({
                'data_dir': str(d),
                'n_commands': len(cmds),
                'n_cv': len(detected.get('cv', [])),
                'n_eis': len(detected.get('eis', [])),
                'n_iv': len(detected.get('iv', [])),
                'n_ocp': len(detected.get('ocp', [])),
                'n_drt_dir': len(detected.get('drt_dir', [])),
            })
            try:
                _heka_v14_make_minimal_mplstyle(_V112Path(d))
            except Exception:
                pass
        except Exception as exc:
            all_notes.append(f"Failed to prepare {d}: {exc}")

    if not all_commands:
        detail = "\n".join(all_notes) if all_notes else "No CV/EIS/IV/OCP/DRT files were detected."
        raise RuntimeError("No auto-run commands could be built.\n" + detail)

    analysis_root = _v112_parser_analysis_root(data_dirs)
    try:
        analysis_root.mkdir(parents=True, exist_ok=True)
    except Exception:
        analysis_root = _v112_app_dir()
    progress_file = analysis_root / '_faradaiq_pyseccm_parser_progress.txt'
    try:
        progress_file.write_text(f"0 of {len(all_commands)} QUEUED Parser commands queued\n", encoding='utf-8')
    except Exception:
        progress_file = _v112_batch_dir() / '_faradaiq_pyseccm_parser_progress.txt'
        progress_file.write_text(f"0 of {len(all_commands)} QUEUED Parser commands queued\n", encoding='utf-8')

    # Save a small manifest next to the progress file for troubleshooting.
    try:
        manifest = {
            'schema': 'faradaiq-auto-parser-launch-v112',
            'base_name': base_name,
            'launch_cwd_policy': 'cmd.exe starts from FaradaIQ app folder; batch cd commands enter data folders',
            'script_root': str(script_root),
            'python_exe': str(python_exe),
            'progress_file': str(progress_file),
            'data_dirs': [str(d) for d in data_dirs],
            'folder_reports': folder_reports,
            'n_commands': len(all_commands),
            'notes': all_notes,
        }
        (progress_file.parent / '_faradaiq_pyseccm_parser_launch_manifest.json').write_text(_v112_json.dumps(manifest, indent=2), encoding='utf-8')
    except Exception:
        pass

    batch = _v67_command_batch_with_progress(all_commands, progress_file, notes=all_notes, title='Auto parsers + AI bundle + optional Edison handoff')
    launch_cwd = _v112_safe_launch_cwd(None)
    bat = _v22_write_bat_and_launch(batch, cwd=launch_cwd, prefix='auto_pyseccm_after_export')
    _v67_start_pyseccm_monitor(gui, progress_file, len(all_commands))
    try:
        gui.set_status(f"Parser BAT launched from safe folder: {launch_cwd}; commands queued: {len(all_commands)}")
    except Exception:
        pass
    return {
        'batch': str(bat),
        'n_commands': len(all_commands),
        'folders': folder_reports,
        'script_root': str(script_root),
        'python_exe': str(python_exe),
        'progress_file': str(progress_file),
        'launch_cwd': str(launch_cwd),
    }


