# ---- FaradaIQ Studio v273 patch: official/legacy DRT engine policy ----
# v118 removes the experimental FaradaIQ ridge/NNLS stable engine from automatic DRT mode.
# Auto mode now tries the official/installed ciuccislab pyDRTtools bridge first and then the
# v110-style bundled legacy pyDRTtools engine. The experimental stable engine is available
# only when explicitly selected in the DRT command-line runner.
import re as _v118_re

try:
    _V118_PREV_PYSECCM_BUILD_COMMANDS = PySECCMRunWindow.build_commands
    def _v118_pyseccm_build_commands(self, *args, _prev=_V118_PREV_PYSECCM_BUILD_COMMANDS, **kwargs):
        commands = _prev(self, *args, **kwargs)
        try:
            if getattr(self, 'tool', None) == 'drt':
                engine = 'auto'
                try:
                    engine = str(getattr(self, 'drt_engine_var', None).get() or 'auto')
                except Exception:
                    engine = 'auto'
                norm = engine.strip().lower()
                if norm.startswith('auto'):
                    norm = 'auto'
                elif 'official' in norm or 'github' in norm:
                    norm = 'official'
                elif 'legacy' in norm or 'v110' in norm:
                    norm = 'legacy'
                elif 'stable' in norm or 'experimental' in norm:
                    norm = 'stable'
                new_commands = []
                for item in commands:
                    if len(item) >= 2:
                        a = list(item[0])
                        cwd = item[1]
                        if not any(str(x).startswith('--engine') for x in a):
                            a += ['--engine', norm]
                        new_commands.append((a, cwd))
                    else:
                        new_commands.append(item)
                commands = new_commands
        except Exception:
            pass
        return commands
    PySECCMRunWindow.build_commands = _v118_pyseccm_build_commands
except Exception:
    pass

