    _V118_PREV_PYSECCM_INIT = PySECCMRunWindow.__init__
    def _v118_pyseccm_init(self, *args, _prev=_V118_PREV_PYSECCM_INIT, **kwargs):
        _prev(self, *args, **kwargs)
