# ---- FaradaIQ Studio v273 packaging/UI/AWS SSO patch ----
# Clean v198 title, put Quick tips + Theme beside About/credits, and retry AWS Bedrock
# direct pings after automatically running aws sso login when the cached SSO token expired.
import shutil as _v120_shutil
import subprocess as _v120_subprocess


def _v120_iter_widgets(widget):
    try:
        yield widget
        for child in widget.winfo_children():
            yield from _v120_iter_widgets(child)
    except Exception:
        return


def _v120_widget_text(widget):
    try:
        return str(widget.cget('text') or '')
    except Exception:
        return ''


def _v120_widget_textvariable(widget):
    try:
        return str(widget.cget('textvariable') or '')
    except Exception:
        return ''


def _v120_find_about_button(root):
    for w in _v120_iter_widgets(root):
        try:
            if _v120_widget_text(w).strip().lower() == 'about / credits':
                return w
        except Exception:
            pass
    return None


def _v120_clean_version_labels(root):
    for w in list(_v120_iter_widgets(root)):
        try:
            txt = _v120_widget_text(w)
            if txt and 'v118' in txt:
                w.configure(text=txt.replace('v118', 'v199'))
        except Exception:
            pass


def _v120_remove_old_quick_theme_controls(root, keep_parent=None):
    """Remove duplicate Quick tips/Theme controls from pySECCM rows after header controls are added."""
    theme_var_name = ''
    try:
        theme_var_name = str(root.theme_mode_var)
    except Exception:
        pass
    for w in list(_v120_iter_widgets(root)):
        try:
            if keep_parent is not None and (w is keep_parent or w.master is keep_parent):
                continue
            txt = _v120_widget_text(w).strip()
            tv = _v120_widget_textvariable(w)
            if txt == 'Quick tips':
                w.destroy()
                continue
            if txt == 'Theme':
                w.destroy()
                continue
            if theme_var_name and tv == theme_var_name:
                w.destroy()
                continue
        except Exception:
            pass


def _v120_place_header_controls(root):
    try:
        _v120_clean_version_labels(root)
        about = _v120_find_about_button(root)
        if about is None:
            return
        hero = about.master
        if getattr(root, '_v120_header_controls_added', False):
            _v120_remove_old_quick_theme_controls(root, keep_parent=getattr(root, '_v120_header_controls_frame', None))
            return
        if not hasattr(root, '_faradaiq_quick_tips_var'):
            root._faradaiq_quick_tips_var = tk.BooleanVar(value=False)
        if not hasattr(root, 'theme_mode_var'):
            root.theme_mode_var = tk.StringVar(value='Dark')

        # Put the controls in the same hero/header area as About / credits.
        frame = ttk.Frame(hero, style='Hero.TFrame')
        try:
            frame.grid(row=2, column=2, sticky='ne', padx=(8, 0), pady=(4, 0))
        except Exception:
            frame.pack(side='right', padx=(8, 0))

        cb = ttk.Checkbutton(
            frame,
            text='Quick tips',
            variable=root._faradaiq_quick_tips_var,
            command=lambda r=root: _v103_set_quick_tips(r._faradaiq_quick_tips_var.get(), r),
        )
        cb.pack(side='left', padx=(0, 8))
        ttk.Label(frame, text='Theme', style='HeroSub.TLabel').pack(side='left', padx=(0, 5))
        ttk.Button(frame, textvariable=root.theme_mode_var, command=lambda r=root: _v36_toggle_theme(r)).pack(side='left')
        try:
            _v103_add_tooltip(cb, 'Turn detailed hover tips on or off for this FaradaIQ session. Default is off.')
        except Exception:
            pass

        root._v120_header_controls_frame = frame
        root._v120_header_controls_added = True
        root._v103_quick_tip_toggle_added = True
        _v120_remove_old_quick_theme_controls(root, keep_parent=frame)
    except Exception:
        pass


