def _v120_aws_error_needs_sso_refresh(exc_or_text):
    s = str(exc_or_text or '').lower()
    needles = [
        'token has expired',
        'refresh failed',
        'unauthorizedssotoken',
        'sso session',
        'sso token',
        'the sso session associated with this profile has expired',
        'invalid grant',
    ]
    return any(n in s for n in needles)


def _v120_run_aws_sso_login(profile):
    profile = str(profile or '').strip()
    if not profile:
        raise RuntimeError('AWS_PROFILE is empty; cannot run aws sso login automatically.')
    aws = _v120_shutil.which('aws') or 'aws'
    cmd = [aws, 'sso', 'login', '--profile', profile]
    # This opens the normal AWS SSO browser/device flow and waits for completion.
    proc = _v120_subprocess.run(cmd, text=True, capture_output=True, timeout=600)
    if proc.returncode != 0:
        detail = ((proc.stdout or '') + '\n' + (proc.stderr or '')).strip()
        raise RuntimeError('aws sso login failed for profile ' + profile + ((':\n' + detail) if detail else ''))
    return ((proc.stdout or '') + '\n' + (proc.stderr or '')).strip()


