def _v37_aws_bedrock_chat(model_id, messages, max_tokens=2200, temperature=0.2, timeout=180):
    """v198: direct Bedrock call with automatic AWS SSO refresh/retry for expired SSO tokens."""
    if _V120_PREV_AWS_BEDROCK_CHAT is None:
        raise RuntimeError('AWS Bedrock direct chat implementation is unavailable.')
    profile = _v40_env_first(['AWS_PROFILE'], _FARADAIQ_DEFAULT_AWS_PROFILE if '_FARADAIQ_DEFAULT_AWS_PROFILE' in globals() else '')
    try:
        return _V120_PREV_AWS_BEDROCK_CHAT(model_id, messages, max_tokens=max_tokens, temperature=temperature, timeout=timeout)
    except Exception as exc:
        if not _v120_aws_error_needs_sso_refresh(exc):
            raise
        _v120_run_aws_sso_login(profile)
        return _V120_PREV_AWS_BEDROCK_CHAT(model_id, messages, max_tokens=max_tokens, temperature=temperature, timeout=timeout)


