# ---- FaradaIQ Studio v273 compact HEKA/AI bundle consolidation patch ----
# Goal: keep one canonical parser CSV/ASC set, one compact HDF5 + one JSON index for
# AI/Data Browser handoff, no mirrored files_snapshot, no NPY payload, no DRT_input_csv_all.

FARADAIQ_V120_COMPACT_SCHEMA = "faradaiq-compact-data-bundle-v1"


def _v120_now_iso():
    try:
        return datetime.now().isoformat(timespec="seconds")
    except Exception:
        return ""


def _v120_safe_json_value(x, depth=0):
    """JSON-safe conversion for compact manifests without exploding large arrays."""
    if depth > 6:
        return str(type(x).__name__)
    try:
        if isinstance(x, (str, int, float, bool)) or x is None:
            return x
        if isinstance(x, (np.integer,)):
            return int(x)
        if isinstance(x, (np.floating,)):
            v = float(x)
            return v if np.isfinite(v) else None
        if isinstance(x, (np.ndarray,)):
            return {"ndarray_shape": list(x.shape), "dtype": str(x.dtype)}
        if isinstance(x, (Path,)):
            return str(x)
        if isinstance(x, dict):
            return {str(k): _v120_safe_json_value(v, depth + 1) for k, v in list(x.items())[:1000]}
        if isinstance(x, (list, tuple, set)):
            return [_v120_safe_json_value(v, depth + 1) for v in list(x)[:1000]]
    except Exception:
        pass
    return str(x)


def _v120_relpath(path, root):
    try:
        return Path(path).resolve().relative_to(Path(root).resolve()).as_posix()
    except Exception:
        return Path(path).name


def _v120_parts_lower(path):
    try:
        return [str(x).lower() for x in Path(path).parts]
    except Exception:
        return str(path or "").lower().replace("\\", "/").split("/")


def _v120_is_redundant_or_cache_path(path, analysis_root=None):
    parts = _v120_parts_lower(path)
    joined = "/".join(parts)
    banned_exact = {
        "files_snapshot", "raw_export_siblings", "data_generated_from_heka",
        "drt_input_csv_all", "__pycache__", ".faradaiq_venv", ".deareis_venv", "site-packages",
        "faradaiq_ai_data_context_pack", "scilink_results", "edison_results",
        "edisonscientific_handoff", "scilink_handoff",
    }
    if any(p in banned_exact for p in parts):
        return True
    if any("ai_analysis_with_parsed_outputs" in p for p in parts):
        return True
    if any(p.endswith("_ai_analysis_with_parsed_outputs") for p in parts):
        return True
    if any(p.endswith("_ai_bundle") for p in parts):
        return True
    if any(p.startswith("scilink_handoff_") for p in parts):
        return True
    if any(p.startswith("edison") and "handoff" in p for p in parts):
        return True
    if "/drt/drt_" in joined or re.search(r"/drt_\d{8}_\d{6}", joined):
        # DRT results are kept in the filesystem, but they are not parser input roots.
        return False
    return False


try:
    _V120_PREV_UNDER_SNAPSHOT_OR_GENERATED = _v118_under_snapshot_or_generated_result
except Exception:
    _V120_PREV_UNDER_SNAPSHOT_OR_GENERATED = None


def _v118_under_snapshot_or_generated_result(p):
    """v198: ignore redundant generated/cache folders when looking for parser input roots."""
    if _v120_is_redundant_or_cache_path(p):
        return True
    if callable(_V120_PREV_UNDER_SNAPSHOT_OR_GENERATED):
        return bool(_V120_PREV_UNDER_SNAPSHOT_OR_GENERATED(p))
    return False


def _v120_file_kind(path):
    p = Path(path)
    s = p.name.lower()
    suf = p.suffix.lower()
    parts = _v120_parts_lower(p)
    if suf in {".gif", ".mp4", ".avi", ".mov"}:
        return "movie_or_gif"
    if suf in {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".svg", ".pdf"}:
        return "figure"
    if suf in {".json", ".jsonl"}:
        return "json_metadata"
    if "drt_input_csv" in parts and suf in {".csv", ".txt"}:
        return "drt_input_table"
    if "drt" in parts and suf in {".csv", ".txt", ".json", ".png"}:
        return "drt_result"
    if suf in {".csv", ".txt", ".asc", ".tsv", ".dat"}:
        if "data_by_point_sequence" in parts:
            return "canonical_point_sequence_csv"
        if p.parent.name.lower() == "data" and p.parent.parent.name.lower().endswith("_for_plotting_analysis"):
            return "canonical_parser_input"
        return "numeric_or_text_table"
    if suf in {".h5", ".hdf5"}:
        return "hdf5_bundle_or_export"
    if suf in {".npy", ".npz"}:
        return "numpy_binary"
    return "other"


def _v120_collect_canonical_files(analysis_root, include_large_binary=False):
    """Collect one canonical set for AI/Data Browser indexing without mirrored snapshots."""
    root = Path(analysis_root).resolve()
    include_exts = {".csv", ".txt", ".asc", ".tsv", ".dat", ".json", ".png", ".jpg", ".jpeg", ".gif", ".svg", ".pdf", ".h5", ".hdf5"}
    if include_large_binary:
        include_exts |= {".npy", ".npz"}
    files = []
    if not root.exists():
        return files
    for p in root.rglob("*"):
        try:
            if not p.is_file():
                continue
            if p.suffix.lower() not in include_exts:
                continue
            if _v120_is_redundant_or_cache_path(p, root):
                continue
            # Do not recursively include the compact bundle being written.
            if "faradaiq_compact_bundle" in [x.lower() for x in p.parts]:
                continue
            files.append(p)
        except Exception:
            continue
    # Include a few root-level siblings created beside the analysis_ready folder, but not NPY payloads.
    try:
        parent = root.parent
        safe = root.name[:-len("_analysis_ready_csv")] if root.name.endswith("_analysis_ready_csv") else root.name
        for suffix in ["_summary.json", "_raw_session.json", "_analysis_ready_manifest.json"]:
            p = parent / f"{safe}{suffix}"
            if p.exists() and p.is_file():
                files.append(p)
    except Exception:
        pass
    # De-duplicate by resolved path.
    seen, out = set(), []
    for p in sorted(files, key=lambda x: str(x).lower()):
        try:
            key = str(p.resolve()).lower() if os.name == "nt" else str(p.resolve())
        except Exception:
            key = str(p).lower()
        if key not in seen:
            seen.add(key)
            out.append(p)
    return out


def _v120_text_preview(path, max_chars=6000):
    try:
        txt = Path(path).read_text(encoding="utf-8-sig", errors="replace")
        return txt[:max_chars], len(txt) > max_chars
    except Exception as exc:
        return f"[preview failed: {exc}]", False


def _v120_table_summary(path, max_sample_rows=5000):
    p = Path(path)
    out = {"loader": "none"}
    try:
        import pandas as _pd
        df = _pd.read_csv(p, sep=None, engine="python", nrows=max_sample_rows)
        out["loader"] = "pandas_sample"
        out["sample_rows"] = int(df.shape[0])
        out["columns"] = [str(c) for c in df.columns]
        numeric = df.apply(_pd.to_numeric, errors="coerce")
        cols = []
        for c in numeric.columns:
            ser = numeric[c]
            if ser.notna().any():
                cols.append({
                    "column": str(c),
                    "count_non_nan": int(ser.notna().sum()),
                    "min": float(ser.min(skipna=True)),
                    "max": float(ser.max(skipna=True)),
                    "mean": float(ser.mean(skipna=True)),
                })
        out["numeric_columns"] = cols[:100]
    except Exception as exc:
        out["error"] = str(exc)
    return out


def _v120_h5_dataset_name(index, rel):
    safe = re.sub(r"[^A-Za-z0-9_]+", "_", str(rel))[:80].strip("_") or "file"
    return f"file_{int(index):05d}_{safe}"


def _v120_write_compact_h5(h5_path, files, analysis_root, manifest_records, max_embed_bytes=300_000_000):
    """Write exact canonical table/json/gif bytes into a compressed HDF5 container."""
    try:
        import h5py
    except Exception as exc:
        return {"h5_written": False, "h5_error": f"h5py unavailable: {exc}"}
    h5_path = Path(h5_path)
    h5_path.parent.mkdir(parents=True, exist_ok=True)
    embedded = 0
    skipped = 0
    total_bytes = 0
    string_dtype = h5py.string_dtype(encoding="utf-8")
    with h5py.File(h5_path, "w") as h5:
        h5.attrs["schema"] = FARADAIQ_V120_COMPACT_SCHEMA
        h5.attrs["app"] = "FaradaIQ Studio"
        h5.attrs["version"] = "v199"
        h5.attrs["created"] = _v120_now_iso()
        h5.attrs["analysis_root"] = str(Path(analysis_root))
        h5.create_dataset("manifest_json", data=json.dumps(_v120_safe_json_value(manifest_records), ensure_ascii=False), dtype=string_dtype)
        grp = h5.create_group("canonical_files")
        for idx, p in enumerate(files, start=1):
            try:
                st = p.stat()
                rel = _v120_relpath(p, analysis_root)
                kind = _v120_file_kind(p)
                item = grp.create_group(_v120_h5_dataset_name(idx, rel))
                item.attrs["relative_path"] = rel
                item.attrs["name"] = p.name
                item.attrs["suffix"] = p.suffix.lower()
                item.attrs["kind"] = kind
                item.attrs["size_bytes"] = int(st.st_size)
                embeddable = p.suffix.lower() in {".csv", ".txt", ".asc", ".tsv", ".dat", ".json", ".gif"}
                if embeddable and st.st_size <= max_embed_bytes:
                    raw = p.read_bytes()
                    arr = np.frombuffer(raw, dtype=np.uint8)
                    item.create_dataset("file_bytes", data=arr, compression="gzip", compression_opts=4, shuffle=True)
                    item.attrs["embedded"] = True
                    embedded += 1
                    total_bytes += int(st.st_size)
                else:
                    item.attrs["embedded"] = False
                    skipped += 1
            except Exception as exc:
                try:
                    item = grp.create_group(f"file_{idx:05d}_error")
                    item.attrs["error"] = str(exc)
                except Exception:
                    pass
    return {"h5_written": True, "embedded_files": embedded, "skipped_files": skipped, "embedded_source_bytes": total_bytes}


def _v120_cleanup_redundant_export_files(analysis_root, aggressive=False):
    """Remove only known mirrors/caches. Canonical CSV/ASC, DRT_input_csv, plots, photos, GIFs stay."""
    root = Path(analysis_root)
    removed = []
    errors = []
    if not root.exists():
        return {"removed": removed, "errors": errors}
    dirs_to_remove = []
    for name in ["DRT_input_csv_all", "data_generated_from_HEKA"]:
        try:
            dirs_to_remove.extend([p for p in root.rglob(name) if p.is_dir()])
        except Exception:
            pass
    if aggressive:
        try:
            dirs_to_remove.extend([p for p in root.rglob("files_snapshot") if p.is_dir()])
        except Exception:
            pass
    for d in sorted(set(dirs_to_remove), key=lambda p: len(str(p)), reverse=True):
        try:
            # Keep generated HEKA folder if canonical data folder is absent.
            if d.name.lower() == "data_generated_from_heka":
                canonical = d.parent / "data"
                if not (canonical.exists() and any(canonical.iterdir())):
                    continue
            shutil.rmtree(d)
            removed.append(str(d))
        except Exception as exc:
            errors.append({"path": str(d), "error": str(exc)})
    # Remove old heavy AI payloads and extra timestamp context-pack copies.
    patterns = ["*_AI_analysis_payload.npy"]
    if aggressive:
        patterns += ["FaradaIQ_data_context_pack_*.json", "FaradaIQ_data_context_pack_latest.txt"]
    for pat in patterns:
        try:
            for p in root.rglob(pat):
                try:
                    p.unlink()
                    removed.append(str(p))
                except Exception as exc:
                    errors.append({"path": str(p), "error": str(exc)})
        except Exception:
            pass
    # v198 compact bundle replaces the root-level parsed NPY payload. Remove only exact
    # sample-level *_parsed.npy siblings beside *_analysis_ready_csv; never scan broadly.
    try:
        if root.name.endswith("_analysis_ready_csv"):
            stem = root.name[:-len("_analysis_ready_csv")]
            p = root.parent / f"{stem}_parsed.npy"
            if p.exists() and p.is_file():
                p.unlink()
                removed.append(str(p))
    except Exception as exc:
        errors.append({"path": str(root.parent if 'root' in locals() else ''), "error": str(exc)})
    return {"removed": removed, "errors": errors}


