def _heka_v14_export_seccm_plotting_analysis_outputs(self, output_dir: Path, base_name: str) -> dict:
    """v198: HEKA export keeps one canonical parser data folder and one DRT_input_csv set."""
    if _V120_PREV_HEKA_SECCM_EXPORT is None:
        raise RuntimeError("HEKA SECCM plotting export implementation is unavailable.")
    info = _V120_PREV_HEKA_SECCM_EXPORT(self, output_dir, base_name)
    try:
        safe = PSSessionParser._sanitize_filename(base_name)
    except Exception:
        safe = str(base_name or "heka_session")
    root = Path(info.get("root") or Path(output_dir) / f"{safe}_for_plotting_analysis")
    main_data = Path(info.get("main_data") or root / "data")
    generated = root / "data_generated_from_HEKA"
    man_path = Path(info.get("manifest") or root / "plotting_analysis_manifest.json")
    cleanup = _v120_cleanup_redundant_export_files(root, aggressive=False)
    info["v130_consolidation"] = {
        "policy": "canonical *_for_plotting_analysis/data plus DRT_input_csv plus data_by_point_sequence; no data_generated_from_HEKA mirror",
        "cleanup": cleanup,
    }
    # Repair manifest paths that used to point at removed data_generated_from_HEKA files.
    try:
        if man_path.exists():
            man = json.loads(man_path.read_text(encoding="utf-8", errors="replace"))
            for row in man.get("generated_from_heka", []) or []:
                old_name = Path(str(row.get("path", ""))).name
                if old_name:
                    new_path = main_data / old_name
                    if new_path.exists():
                        row["path"] = str(new_path)
                        row["canonical_relative_path"] = str(new_path.relative_to(root)).replace("\\", "/")
            man["format"] = "heka-seccm-plotting-analysis-folder-v198-consolidated"
            man["main_data_source"] = str(main_data)
            man["redundant_mirrors_removed"] = cleanup.get("removed", [])
            man.setdefault("notes", []).append("FaradaIQ v273: data_generated_from_HEKA mirror removed after copying generated HEKA files into canonical data/. Parsers should use data/ and DRT_input_csv/ only.")
            man_path.write_text(json.dumps(_v120_safe_json_value(man), indent=2, ensure_ascii=False), encoding="utf-8")
    except Exception as exc:
        info.setdefault("notes", []).append(f"FaradaIQ v273 manifest consolidation failed: {exc}")
    return info


