def _v29_export_generic_drt_for_collection(collection, analysis_root: Path, base_name: str):
    """v198: create per-entry DRT_input_csv only; do not create duplicated DRT_input_csv_all."""
    analysis_root = Path(analysis_root)
    safe_base = _v29_safe_label(base_name, "electrochem_session") if "_v29_safe_label" in globals() else str(base_name or "electrochem_session")
    manifest = {
        "created": _v120_now_iso(),
        "format": "generic-eis-drt-input-v198-canonical-only",
        "note": "DRT-compatible CSV files are generated beside each entry under *_for_plotting_analysis/DRT_input_csv. DRT_input_csv_all is intentionally not created to avoid duplicate DRT runs.",
        "analysis_ready_root": str(analysis_root),
        "all_drt_input_dir": None,
        "entries": [],
        "n_files": 0,
    }
    files = []
    try:
        entries = getattr(collection, "entries", []) or []
    except Exception:
        entries = []
    for entry_idx, entry in enumerate(entries, start=1):
        parser = entry.get("parser") if isinstance(entry, dict) else None
        meta = (entry.get("path_metadata", {}) or {}) if isinstance(entry, dict) else {}
        stem = Path(meta.get("basename", f"entry_{entry_idx}")).stem
        rel_dir = Path(*meta.get("subfolder_names", [])) if meta.get("subfolder_names") else Path()
        target_root = analysis_root / rel_dir / f"{_v29_safe_label(stem) if '_v29_safe_label' in globals() else stem}_for_plotting_analysis"
        data_dir = target_root / "data"
        drt_dir = target_root / "DRT_input_csv"
        for d in (data_dir, drt_dir):
            d.mkdir(parents=True, exist_ok=True)
        try:
            records = _v29_extract_generic_eis_records(parser)
        except Exception:
            records = []
        entry_manifest = {
            "entry_id": f"e{entry_idx:04d}",
            "source_file": meta.get("relative_path") or getattr(parser, "source_path", ""),
            "stem": stem,
            "vendor_parser": parser.__class__.__name__ if parser else "unknown",
            "plotting_root": str(target_root),
            "data_folder": str(data_dir),
            "drt_input_csv_dir": str(drt_dir),
            "n_eis_spectra": len(records),
            "files": [],
        }
        try:
            (data_dir / "README_DRT_input_csv.txt").write_text(
                "DRT-compatible EIS CSV files are in ../DRT_input_csv.\n"
                "Each CSV has columns: frequency_Hz, Zreal_ohm, Zimag_ohm.\n",
                encoding="utf-8",
            )
        except Exception:
            pass
        for ri, rec in enumerate(records, start=1):
            try:
                label = _v29_safe_label(rec.get("label"), f"EIS_{ri:03d}") if "_v29_safe_label" in globals() else f"EIS_{ri:03d}"
                fname = f"{_v29_safe_label(stem) if '_v29_safe_label' in globals() else stem}__{label}__freq_zreal_zimag.csv"
                arr = np.asarray(rec.get("array"), dtype=float)
                p1 = drt_dir / fname
                _v29_write_drt_csv(p1, arr)
                row = {
                    "label": rec.get("label"),
                    "source": rec.get("source"),
                    "n_rows": int(len(arr)),
                    "freq_min_Hz": float(np.nanmin(arr[:, 0])) if len(arr) else None,
                    "freq_max_Hz": float(np.nanmax(arr[:, 0])) if len(arr) else None,
                    "relative_drt_path": str(p1.relative_to(analysis_root)).replace("\\", "/"),
                }
                entry_manifest["files"].append(row)
                files.append(str(p1))
            except Exception as exc:
                entry_manifest.setdefault("errors", []).append(str(exc))
        if records:
            try:
                with open(target_root / "generic_DRT_input_manifest.json", "w", encoding="utf-8") as f:
                    json.dump(_v120_safe_json_value(entry_manifest), f, indent=2, ensure_ascii=False)
            except Exception:
                pass
        manifest["entries"].append(entry_manifest)
    manifest["n_files"] = len(files)
    manifest_path = analysis_root / "generic_DRT_input_manifest.json"
    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(_v120_safe_json_value(manifest), f, indent=2, ensure_ascii=False)
    try:
        _v120_cleanup_redundant_export_files(analysis_root, aggressive=False)
    except Exception:
        pass
    return {"manifest_path": str(manifest_path), "all_drt_input_dir": None, "n_files": len(files), "files": files}


