def _pss_collection_v120_export_analysis_ready_csv(self, output_dir: Path, base_name: str) -> dict:
    if _V120_PREV_COLLECTION_EXPORT is None:
        raise RuntimeError("PSSessionCollection export implementation is unavailable.")
    info = _V120_PREV_COLLECTION_EXPORT(self, output_dir, base_name)
    try:
        drt_info = _v29_export_generic_drt_for_collection(self, Path(info["analysis_ready_root"]), base_name)
        info["generic_drt_input"] = drt_info
        mp = Path(info.get("manifest_path", ""))
        if mp.exists():
            data = json.loads(mp.read_text(encoding="utf-8", errors="replace"))
            data["generic_drt_input"] = drt_info
            data.setdefault("notes", []).append("FaradaIQ v273: canonical-only DRT export; no DRT_input_csv_all duplicate mirror.")
            mp.write_text(json.dumps(_v120_safe_json_value(data), indent=2, ensure_ascii=False), encoding="utf-8")
        _v120_cleanup_redundant_export_files(Path(info["analysis_ready_root"]), aggressive=False)
    except Exception as exc:
        info["generic_drt_input_error"] = str(exc)
    return info

