def make_ai_analysis_bundle(analysis_root, base_name=None, label="compact", copy_files=False, progress_callback=None):
    """v198 compact bundle: write one HDF5 plus one JSON index; do not mirror files."""
    analysis_root = Path(analysis_root).resolve()
    if base_name is None:
        name = analysis_root.name
        base_name = name[:-len("_analysis_ready_csv")] if name.endswith("_analysis_ready_csv") else name
    safe = _v35_safe_name(base_name) if "_v35_safe_name" in globals() else re.sub(r"[^A-Za-z0-9_.-]+", "_", str(base_name))
    bundle_dir = analysis_root / f"{safe}_FaradaIQ_compact_bundle"
    bundle_dir.mkdir(parents=True, exist_ok=True)

    def progress(msg):
        try:
            if progress_callback:
                progress_callback(msg)
        except Exception:
            pass
        try:
            print(msg)
        except Exception:
            pass

    progress(f"[FaradaIQ v273 AI bundle] Building compact HDF5/JSON bundle under: {analysis_root}")
    try:
        _v120_cleanup_redundant_export_files(analysis_root, aggressive=False)
    except Exception:
        pass
    files = _v120_collect_canonical_files(analysis_root, include_large_binary=False)
    records = []
    categories = {}
    total_bytes = 0
    for idx, p in enumerate(files, start=1):
        try:
            st = p.stat()
            rel = _v120_relpath(p, analysis_root)
            kind = _v120_file_kind(p)
            rec = {
                "id": idx,
                "relative_path": rel,
                "name": p.name,
                "suffix": p.suffix.lower(),
                "kind": kind,
                "size_bytes": int(st.st_size),
                "modified_time": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
            }
            if p.suffix.lower() in {".csv", ".txt", ".asc", ".tsv", ".dat"}:
                preview, truncated = _v120_text_preview(p, max_chars=6000)
                rec["text_preview"] = preview
                rec["preview_truncated"] = truncated
                rec["table_summary"] = _v120_table_summary(p, max_sample_rows=3000)
            elif p.suffix.lower() == ".json" and st.st_size <= 2_000_000:
                try:
                    rec["json_preview"] = _v120_safe_json_value(json.loads(p.read_text(encoding="utf-8", errors="replace")))
                except Exception:
                    preview, truncated = _v120_text_preview(p, max_chars=6000)
                    rec["text_preview"] = preview
                    rec["preview_truncated"] = truncated
            records.append(rec)
            categories.setdefault(kind, 0)
            categories[kind] += 1
            total_bytes += int(st.st_size)
        except Exception as exc:
            records.append({"id": idx, "path": str(p), "error": str(exc)})
    h5_path = bundle_dir / f"{safe}_data_bundle.h5"
    index_path = bundle_dir / f"{safe}_data_bundle_index.json"
    h5_info = _v120_write_compact_h5(h5_path, files, analysis_root, records)
    summary = {
        "schema": FARADAIQ_V120_COMPACT_SCHEMA,
        "app": "FaradaIQ Studio",
        "version": "v273",
        "created": _v120_now_iso(),
        "base_name": base_name,
        "label": label,
        "analysis_root": str(analysis_root),
        "bundle_dir": str(bundle_dir),
        "hdf5_bundle": str(h5_path) if h5_info.get("h5_written") else None,
        "json_index": str(index_path),
        "n_files_indexed": len(records),
        "n_files_copied": 0,
        "n_files_copy_skipped": len(records),
        "total_indexed_bytes": total_bytes,
        "categories": categories,
        "hdf5_policy": {
            "embedded_extensions": [".csv", ".txt", ".asc", ".tsv", ".dat", ".json", ".gif"],
            "max_embed_bytes_per_file": 300_000_000,
            "figures_and_pngs": "indexed by path; not duplicated in files_snapshot",
        },
        "consolidation_policy": [
            "No files_snapshot mirror is created.",
            "No *_AI_analysis_payload.npy is created.",
            "No DRT_input_csv_all mirror is created.",
            "HEKA parser inputs remain in *_for_plotting_analysis/data.",
            "DRT parser inputs remain in *_for_plotting_analysis/DRT_input_csv.",
            "Point-sequence CSVs remain in data_by_point_sequence as the one canonical CSV set for browser/AI use.",
        ],
    }
    bundle_index = {"summary": summary, "files": records, "h5_info": h5_info}
    index_path.write_text(json.dumps(_v120_safe_json_value(bundle_index), indent=2, ensure_ascii=False), encoding="utf-8")
    readme = bundle_dir / "README_COMPACT_BUNDLE.txt"
    readme.write_text(
        "FaradaIQ Studio v273 compact AI/Data Browser bundle\n"
        "====================================================\n\n"
        "This folder intentionally contains one HDF5 data bundle and one JSON index.\n"
        "It replaces the older files_snapshot mirror and huge NPY payload.\n\n"
        f"JSON index: {index_path.name}\n"
        f"HDF5 bundle: {h5_path.name if h5_info.get('h5_written') else 'not written; see JSON h5_info'}\n",
        encoding="utf-8",
    )
    progress(f"[FaradaIQ v273 AI bundle] Complete: {bundle_dir}")
    return {
        "bundle_dir": str(bundle_dir),
        "manifest_path": str(index_path),
        "summary_path": str(index_path),
        "index_path": str(index_path),
        "h5_path": str(h5_path) if h5_info.get("h5_written") else "",
        "npy_path": "",
        "n_files_indexed": len(records),
        "n_files_copied": 0,
    }


