def _v120_build_data_context_pack(gui, save=True):
    """v198: context pack saves only latest JSON; no timestamp duplicates or TXT mirrors."""
    if callable(_V120_PREV_BUILD_CONTEXT_PACK):
        pack = _V120_PREV_BUILD_CONTEXT_PACK(gui, save=False)
    else:
        pack = {"schema_version": "FaradaIQ-data-context-pack-v198", "created": _v120_now_iso(), "roots": []}
    pack["schema_version"] = "FaradaIQ-data-context-pack-v198"
    pack["save_policy"] = "single latest JSON only; no timestamp duplicates and no TXT mirror"
    if save:
        try:
            roots = pack.get("roots") or []
            root = Path(roots[0]) if roots else Path(getattr(getattr(gui, "output_dir_var", None), "get", lambda: ".")()).resolve()
            out = root / "FaradaIQ_AI_data_context_pack"
            out.mkdir(parents=True, exist_ok=True)
            latest = out / "FaradaIQ_data_context_pack_latest.json"
            latest.write_text(json.dumps(_v120_safe_json_value(pack), indent=2, ensure_ascii=False), encoding="utf-8")
            # remove older duplicate copies created by previous versions
            for p in list(out.glob("FaradaIQ_data_context_pack_*.json")) + list(out.glob("FaradaIQ_data_context_pack_latest.txt")):
                try:
                    if p.name != latest.name:
                        p.unlink()
                except Exception:
                    pass
            pack["saved_context_pack_dir"] = str(out)
            pack["saved_context_pack_json"] = str(latest)
        except Exception as exc:
            pack["save_error"] = str(exc)
    return pack

