def _v130p_get_selected_view_paths(browser):
    paths = []
    try:
        paths = _v75x_get_selected_view_paths(browser)
    except Exception:
        pass
    if not paths:
        try:
            paths = browser.selected_paths(plottable_only=True)
        except Exception:
            paths = []
    try:
        paths = _v70_table_paths(paths)
    except Exception:
        paths = [Path(p) for p in paths]
    out, seen = [], set()
    for p in paths:
        try:
            pp = Path(p)
            key = str(pp.resolve()) if pp.exists() else str(pp)
            if key not in seen:
                out.append(pp); seen.add(key)
        except Exception:
            pass
    return out


def _v130p_selected_eis_paths(browser):
    tables = _v130p_get_selected_view_paths(browser)
    out = []
    for p in tables:
        s = str(p).lower()
        if any(tok in s for tok in ['eis', 'impedance', 'nyquist', 'bode', 'zreal', 'zimag', 'fullEIS'.lower(), 'drt_input']):
            out.append(Path(p))
    if not out:
        try:
            if _v83_current_plot_view_kind(browser) == 'EIS':
                out = [Path(p) for p in tables]
        except Exception:
            pass
    ded, seen = [], set()
    for p in out:
        k = str(p.resolve()) if Path(p).exists() else str(p)
        if k not in seen:
            ded.append(Path(p)); seen.add(k)
    return ded


def _v130p_deareis_output_root(browser):
    try:
        root = browser.analyzed_root / 'deareis_eis_handoff'
    except Exception:
        r = Path(getattr(browser, 'analysis_root', Path.cwd()))
        root = r / f'{_v35_safe_name(getattr(browser, "base_name", r.name))}_FaradaIQ_analyzed_data' / 'deareis_eis_handoff'
    root.mkdir(parents=True, exist_ok=True)
    return root


def _v130p_deareis_install(parent=None):
    try:
        app_dir = Path(__file__).resolve().parent
        bat = app_dir / 'install_deareis_optional.bat'
        if bat.exists() and os.name == 'nt':
            os.startfile(str(bat))
            return
        if _v130p_subprocess is None:
            raise RuntimeError('subprocess unavailable')
        _v130p_subprocess.Popen([sys.executable, 'faradaiq_deareis_adapter.py', '--install'])
    except Exception as exc:
        try:
            messagebox.showerror('DearEIS install failed to start', str(exc), parent=parent)
        except Exception:
            pass


def _v130p_launch_deareis_gui(parent=None):
    try:
        app_dir = Path(__file__).resolve().parent
        bat = app_dir / 'run_deareis_gui.bat'
        if bat.exists() and os.name == 'nt':
            os.startfile(str(bat))
            return
        if _v130p_subprocess is None:
            raise RuntimeError('subprocess unavailable')
        # Non-Windows developer fallback only. The Windows package uses .deareis_venv.
        _v130p_subprocess.Popen([sys.executable, '-m', 'deareis'])
    except Exception as exc:
        try:
            messagebox.showerror('Could not launch DearEIS', 'DearEIS may not be installed yet. Use the install button first.\n\n' + str(exc), parent=parent)
        except Exception:
            pass


def _v130p_open_deareis_with_selected(browser=None, launch=True):
    try:
        paths = _v130p_selected_eis_paths(browser) if browser is not None else []
        if not paths:
            messagebox.showinfo('No EIS plot/view selected', 'Select an EIS/Nyquist/Bode Plot/view first, then send it to DearEIS.', parent=browser)
            return
        import faradaiq_deareis_adapter as _fq_deareis
        root = _v130p_deareis_output_root(browser)
        label = f'{getattr(browser, "base_name", "FaradaIQ")}_selected_EIS'
        result = _fq_deareis.create_deareis_handoff(paths, root, label=label, make_project=True)
        try:
            browser.log(f'DearEIS handoff created with {len(result.normalized_files)} normalized EIS file(s): {result.output_dir}')
            if result.project_json:
                browser.log(f'DearEIS project JSON: {result.project_json}')
        except Exception:
            pass
        try:
            if os.name == 'nt':
                os.startfile(result.output_dir)
        except Exception:
            pass
        msg = (
            f'DearEIS handoff created for {len(result.normalized_files)} EIS file(s).\n\n'
            f'Folder:\n{result.output_dir}\n\n'
            f'DearEIS project JSON:\n{result.project_json or "not created; install DearEIS first"}'
        )
        if result.warnings:
            msg += '\n\nWarnings:\n' + '\n'.join(result.warnings[:6])
            if len(result.warnings) > 6:
                msg += f'\n... plus {len(result.warnings)-6} more warning(s).'
        if launch:
            try:
                _v130p_launch_deareis_gui(browser)
                msg += '\n\nDearEIS GUI launch requested. Import/open the normalized CSVs from the handoff folder if the project is not loaded automatically.'
            except Exception as exc:
                msg += f'\n\nDearEIS GUI launch failed: {exc}'
        elif not result.deareis_available:
            msg += '\n\nDearEIS is optional and is installed in a separate .deareis_venv. Use the Install/upgrade DearEIS button or install_deareis_optional.bat.'
        messagebox.showinfo('DearEIS EIS handoff', msg, parent=browser)
    except Exception as exc:
        try:
            messagebox.showerror('DearEIS EIS handoff failed', str(exc), parent=browser)
        except Exception:
            pass
        try:
            browser.log(f'DearEIS EIS handoff failed: {exc}')
        except Exception:
            pass


