# ---- FaradaIQ Studio v273 patch: support sites moved into LLM settings + elapsed/ETA progress ----
# User request: do not prompt to open support sites during startup; expose support links inside LLM settings.
# User request: show elapsed time as well as ETA, and estimate ETA more accurately from learned/runtime data.
APP_TITLE = "FaradaIQ Studio v273"


def _v130_format_duration(seconds):
    try:
        seconds = max(0.0, float(seconds))
    except Exception:
        seconds = 0.0
    if seconds < 60:
        return f"{int(round(seconds))} s"
    if seconds < 3600:
        m = int(seconds // 60); s = int(seconds % 60)
        return f"{m} min {s:02d} s"
    h = int(seconds // 3600); m = int((seconds % 3600) // 60)
    return f"{h} h {m:02d} min"


def _v130_kind_from_detail(detail):
    try:
        return _v95_parser_kind(detail)
    except Exception:
        d = str(detail or '').lower()
        if 'drt' in d:
            return 'DRT'
        if 'eis' in d or 'impedance' in d:
            return 'EIS'
        if 'cv' in d:
            return 'CV'
        if 'ocp' in d:
            return 'OCP'
        if 'iv' in d or 'tafel' in d:
            return 'IV_Tafel'
        return 'parser_other'


def _v130_learned_seconds(kind):
    heuristic = {'CV': 18.0, 'EIS': 42.0, 'DRT': 240.0, 'IV_Tafel': 18.0, 'OCP': 15.0, 'parser_other': 30.0}.get(kind, 30.0)
    try:
        val = _v95_learned_seconds_for_kind(kind, heuristic)
        if val and float(val) > 0:
            return float(val), ('learned' if abs(float(val) - heuristic) > 1e-6 else 'estimated')
    except Exception:
        pass
    return heuristic, 'estimated'


def _v130_progress_time_text(elapsed, cur, tot, phase='RUNNING', detail='', step_elapsed=None, completed_durations=None):
    """Return compact elapsed + ETA text for parser/DRT progress.

    The v95 estimator used only average command counts. v198 improves this by:
      - always showing elapsed wall time,
      - using learned per-kind history when available,
      - blending current completed-step durations with learned history,
      - accounting for the current running command separately instead of treating it as finished.
    """
    try:
        cur = max(0, int(cur)); tot = max(1, int(tot)); elapsed = max(0.0, float(elapsed))
        phase_u = str(phase or '').upper()
        elapsed_txt = 'Elapsed ' + _v130_format_duration(elapsed)
        if phase_u == 'FINISHED' or cur >= tot and phase_u in {'DONE', 'FINISHED'}:
            return elapsed_txt + ' | ETA done'
        kind = _v130_kind_from_detail(detail)
        learned, basis = _v130_learned_seconds(kind)
        completed = [float(x) for x in (completed_durations or []) if float(x) > 0]
        if completed:
            # Robust current-run estimate: median resists one slow command; mean still responds to real slowdown.
            try:
                import statistics as _v130_statistics
                med = float(_v130_statistics.median(completed[-8:]))
            except Exception:
                med = float(sum(completed[-8:]) / max(1, len(completed[-8:])))
            mean = float(sum(completed[-8:]) / max(1, len(completed[-8:])))
            current_run = 0.70 * med + 0.30 * mean
            # As more commands finish, trust local run more than old history.
            w = min(0.75, 0.22 * len(completed))
            per_cmd = (1.0 - w) * learned + w * current_run
            basis = 'learned+current' if basis == 'learned' else 'current+estimated'
        else:
            per_cmd = learned
        if phase_u == 'RUNNING':
            # cur is the 1-based currently running command in the progress BAT protocol.
            future_after_current = max(0, tot - cur)
            se = None
            try:
                se = max(0.0, float(step_elapsed)) if step_elapsed is not None else None
            except Exception:
                se = None
            if se is not None:
                # Do not assume a long-running current DRT step has the full learned duration still ahead.
                current_rem = max(0.0, per_cmd - se)
                if se > per_cmd and completed:
                    # When current command has exceeded estimate, use the recent command spread as a conservative tail.
                    current_rem = min(max(per_cmd * 0.15, 10.0), per_cmd * 0.50)
            else:
                current_rem = max(0.0, per_cmd * 0.50)
            remaining = current_rem + per_cmd * future_after_current
        else:
            # DONE means current command is complete; remaining commands start after cur.
            remaining = per_cmd * max(0, tot - cur)
        remaining = max(0.0, float(remaining))
        eta_txt = 'ETA ~' + _v130_format_duration(remaining)
        return f'{elapsed_txt} | {eta_txt} ({basis})'
    except Exception:
        try:
            return 'Elapsed ' + _v130_format_duration(elapsed) + ' | ETA estimating...'
        except Exception:
            return 'Elapsed -- | ETA estimating...'


def _v95_eta_text(elapsed, cur, tot, detail=''):
    """v198 compatibility override for code paths that still call the v95 ETA helper directly."""
    return _v130_progress_time_text(elapsed, cur, tot, phase='DONE', detail=detail)

try:
    _v90_eta_text = _v95_eta_text
except Exception:
    pass


def _v67_start_pyseccm_monitor(gui, progress_file, total):
    """v198 monitor: status includes elapsed + improved ETA and records learned runtimes."""
    try:
        progress_file = Path(progress_file)
        _v67_add_pyseccm_status_bar(gui)
        start = time.time()
        step_starts = {}
        step_details = {}
        completed_durations = []
        if hasattr(gui, '_faradaiq_pyseccm_progress'):
            gui._faradaiq_pyseccm_progress.configure(maximum=max(1, int(total)), value=0)
        if hasattr(gui, '_faradaiq_pyseccm_status_var'):
            stats_dir = _v95_runtime_stats_dir() if '_v95_runtime_stats_dir' in globals() else Path.cwd()
            gui._faradaiq_pyseccm_status_var.set(f'pySECCM/DRT parser: launched 0/{total}; elapsed 0 s; ETA learning from {getattr(stats_dir, "name", "runtime stats")}')
        state = {'last':'', 'stable_finished':0, 'last_tuple':None}
        def poll():
            try:
                txt = progress_file.read_text(encoding='utf-8', errors='replace').strip()
            except Exception:
                txt = state['last']
            now = time.time()
            if txt:
                state['last'] = txt
                m = re.match(r'(\d+)\s+of\s+(\d+)\s+(\S+)\s*(.*)', txt)
                if m:
                    cur = int(m.group(1)); tot = max(1, int(m.group(2))); phase = m.group(3); detail = m.group(4).strip()
                    tup = (cur, tot, phase, detail)
                    phase_u = phase.upper()
                    if tup != state.get('last_tuple'):
                        state['last_tuple'] = tup
                        if phase_u == 'RUNNING':
                            step_starts.setdefault(cur, now)
                            step_details[cur] = detail
                        elif phase_u == 'DONE':
                            st = step_starts.get(cur)
                            if st is not None:
                                rc = None
                                mm = re.search(r'rc\s*=\s*(-?\d+)', detail, flags=re.I)
                                if mm:
                                    try: rc = int(mm.group(1))
                                    except Exception: rc = None
                                dur = max(0.01, now - st)
                                completed_durations.append(dur)
                                try:
                                    _v95_record_parser_runtime(_v130_kind_from_detail(detail or step_details.get(cur,'')), dur, detail=(detail or step_details.get(cur,'')), returncode=rc, total_commands=tot)
                                except Exception:
                                    pass
                    elapsed = now - start
                    step_elapsed = None
                    if phase_u == 'RUNNING':
                        st = step_starts.get(cur)
                        if st is not None:
                            step_elapsed = max(0.0, now - st)
                    timing = _v130_progress_time_text(elapsed, cur, tot, phase=phase, detail=(detail or step_details.get(cur,'')), step_elapsed=step_elapsed, completed_durations=completed_durations)
                    pct = 100.0 * min(max(cur,0), tot) / max(1, tot)
                    status = f'pySECCM/DRT parser: {phase} {cur}/{tot} ({pct:.0f}%) | {timing} | {detail}'
                    if hasattr(gui, '_faradaiq_pyseccm_progress'):
                        gui._faradaiq_pyseccm_progress.configure(maximum=tot, value=min(cur, tot))
                    if hasattr(gui, '_faradaiq_pyseccm_status_var'):
                        gui._faradaiq_pyseccm_status_var.set(status)
                    try: gui.set_status(status)
                    except Exception: pass
                    if phase_u == 'FINISHED':
                        state['stable_finished'] += 1
                        if state['stable_finished'] >= 3:
                            try:
                                summary = _v95_runtime_summary_path() if '_v95_runtime_summary_path' in globals() else Path('runtime_summary.json')
                                final_status = f'pySECCM/DRT parser: finished {tot}/{tot}. Elapsed {_v130_format_duration(elapsed)}. ETA stats updated: {Path(summary).name}'
                                if hasattr(gui, '_faradaiq_pyseccm_status_var'):
                                    gui._faradaiq_pyseccm_status_var.set(final_status)
                                try: gui.set_status(final_status)
                                except Exception: pass
                            except Exception:
                                pass
                            return
            gui.after(1200, poll)
        gui.after(300, poll)
    except Exception:
        pass


