# ---- FaradaIQ Studio v273 patch: native Tafel Analysis window ----
# User request: add FaradaIQ Tafel Analysis with classical/manual slope,
# auto-linear PyPI-tafel-style R² window search, Taffit-style nonlinear
# Butler-Volmer fitting, eta-window scan, and a combined results table.
APP_TITLE = "FaradaIQ Studio v273"


def _v130_tafel_output_root(browser=None):
    try:
        root = browser.analyzed_root / 'tafel_analysis'
    except Exception:
        try:
            r = Path(getattr(browser, 'analysis_root', Path.cwd()))
            root = r / f'{_v35_safe_name(getattr(browser, "base_name", r.name))}_FaradaIQ_analyzed_data' / 'tafel_analysis'
        except Exception:
            root = Path.cwd() / 'FaradaIQ_tafel_analysis'
    root.mkdir(parents=True, exist_ok=True)
    return root


def _v130_selected_iv_lsv_paths(browser=None, generous=False):
    paths = []
    try:
        paths = _v130p_get_selected_view_paths(browser)
    except Exception:
        try:
            paths = browser.selected_paths(plottable_only=True)
        except Exception:
            paths = []
    out, seen = [], set()
    skip_tokens = ['eis', 'impedance', 'nyquist', 'bode', 'zreal', 'zimag', 'drt', 'ocp']
    keep_tokens = ['iv', 'tafel', 'taffit', 'lsv', 'linear_sweep', 'polarization', 'polarisation', 'current', 'potential', 'voltam']
    try:
        k = str(_v83_current_plot_view_kind(browser)).lower()
    except Exception:
        k = ''
    kind_says_iv = any(t in k for t in ['iv', 'tafel', 'lsv', 'cv', 'polar'])
    for p in paths:
        try:
            pp = Path(p)
            s = str(pp).lower()
            if any(t in s for t in skip_tokens):
                continue
            keep = generous or kind_says_iv or any(t in s for t in keep_tokens)
            if not keep:
                continue
            key = str(pp.resolve()) if pp.exists() else str(pp)
            if key not in seen:
                out.append(pp); seen.add(key)
        except Exception:
            pass
    return out


def _v130_parse_range_pair(text, default_pair):
    try:
        s = str(text or '').replace(';', ',').replace('to', ',')
        vals = [float(x.strip()) for x in s.split(',') if x.strip()]
        if len(vals) >= 2:
            return (float(vals[0]), float(vals[1]))
    except Exception:
        pass
    return default_pair


def _v130_open_path(path):
    try:
        path = Path(path)
        if os.name == 'nt':
            os.startfile(str(path))
        else:
            import subprocess as _v130_subprocess
            _v130_subprocess.Popen(['open' if sys.platform=='darwin' else 'xdg-open', str(path)])
    except Exception as exc:
        try:
            messagebox.showerror('Open folder failed', str(exc))
        except Exception:
            pass


class FaradaIQTafelAnalysisWindow(tk.Toplevel):
    def __init__(self, browser=None, paths=None):
        super().__init__(browser)
        self.browser = browser
        self.paths = [Path(p) for p in (paths or [])]
        self.output_root = _v130_tafel_output_root(browser)
        self.last_output_dir = None
        self.title('FaradaIQ Tafel Analysis v228')
        self.geometry('1080x760')
        try:
            _v83_set_window_icon(self)
        except Exception:
            pass
        self._build()
        self._refresh_file_list()

    def _build(self):
        outer = ttk.Frame(self, padding=(12, 12))
        outer.pack(fill='both', expand=True)
        top = ttk.Frame(outer)
        top.pack(fill='x')
        ttk.Label(top, text='FaradaIQ Tafel Analysis', style='Hero.TLabel').pack(anchor='w')
        ttk.Label(
            top,
            text='Classical/manual Tafel slope + auto-linear R² search + Taffit-style nonlinear Butler-Volmer fit + ηwin scan. Use selected CV/LSV/IV/Polarization Plot/view files or choose files manually. CV scans can be analyzed as forward and reverse branches separately.',
            style='Muted.TLabel', wraplength=980,
        ).pack(anchor='w', pady=(3, 8))

        main = ttk.PanedWindow(outer, orient='horizontal')
        main.pack(fill='both', expand=True)
        left = ttk.Frame(main, padding=(0, 0, 8, 0))
        right = ttk.Frame(main)
        try:
            main.add(left, weight=0)
            main.add(right, weight=1)
        except TypeError:
            main.add(left); main.add(right)

        files_box = ttk.LabelFrame(left, text='Selected CV / LSV / IV data', padding=(8, 8))
        files_box.pack(fill='both', expand=False)
        self.files_text = tk.Text(files_box, width=48, height=9, wrap='word')
        self.files_text.pack(fill='both', expand=True)
        row = ttk.Frame(files_box); row.pack(fill='x', pady=(6, 0))
        ttk.Button(row, text='Choose CV/LSV/IV files', command=self._choose_files).pack(side='left', padx=(0, 5))
        ttk.Button(row, text='Use selected Plot/view', command=self._use_selected).pack(side='left')

        settings_box = ttk.LabelFrame(left, text='Tafel / Taffit-style settings', padding=(8, 8))
        settings_box.pack(fill='x', pady=(8, 0))
        self.area_var = tk.StringVar(value='1.0')
        self.n_var = tk.StringVar(value='1')
        self.temp_var = tk.StringVar(value='298.15')
        self.eeq_var = tk.StringVar(value='')
        self.adjust_var = tk.BooleanVar(value=True)
        self.win_var = tk.StringVar(value='120')
        self.cath_var = tk.StringVar(value='-0.180, -0.060')
        self.anod_var = tk.StringVar(value='0.060, 0.180')
        self.scan_branch_var = tk.StringVar(value='Whole trace / LSV')
        rows = [
            ('Surface area (cm²)', self.area_var),
            ('n electrons', self.n_var),
            ('Temperature (K)', self.temp_var),
            ('Eeq/OCP (V, blank=auto)', self.eeq_var),
            ('Taffit window ηwin total (mV)', self.win_var),
            ('Manual cathodic η range (V)', self.cath_var),
            ('Manual anodic η range (V)', self.anod_var),
        ]
        for i, (lab, var) in enumerate(rows):
            ttk.Label(settings_box, text=lab).grid(row=i, column=0, sticky='w', pady=2)
            ttk.Entry(settings_box, textvariable=var, width=22).grid(row=i, column=1, sticky='ew', pady=2, padx=(8, 0))
        ttk.Label(settings_box, text='CV scan branch').grid(row=len(rows), column=0, sticky='w', pady=(6, 2))
        ttk.Combobox(settings_box, textvariable=self.scan_branch_var, state='readonly', width=28,
                     values=('Whole trace / LSV', 'Forward scan only', 'Reverse scan only', 'Forward + reverse separately')).grid(row=len(rows), column=1, sticky='ew', pady=(6, 2), padx=(8, 0))
        ttk.Checkbutton(settings_box, text='Subtract current at provided Eeq', variable=self.adjust_var).grid(row=len(rows)+1, column=0, columnspan=2, sticky='w', pady=(6, 0))
        settings_box.columnconfigure(1, weight=1)

        btn_box = ttk.Frame(left)
        btn_box.pack(fill='x', pady=(8, 0))
        ttk.Button(btn_box, text='Run Tafel analysis on selected files', command=self._run_selected).pack(fill='x', pady=2)
        ttk.Button(btn_box, text='Generate dummy IV/LSV and test drive', command=self._dummy_test).pack(fill='x', pady=2)
        ttk.Button(btn_box, text='Open last output folder', command=self._open_last).pack(fill='x', pady=2)
        ttk.Button(btn_box, text='Close', command=self.destroy).pack(fill='x', pady=(12, 2))

        credit = (
            'Credit: Taffit-style nonlinear fit is based on the published Taffit concept by Joshua Coduto and Johna Leddy. '
            'FaradaIQ implements a Python-native analysis and does not require Excel Solver/macros.'
        )
        ttk.Label(left, text=credit, style='Muted.TLabel', wraplength=390).pack(anchor='w', pady=(8, 0))

        self.results = ttk.Treeview(right, columns=('method','branch','slope','logj0','alpha','sigma','r2','n','window'), show='headings', height=14)
        headers = [
            ('method','Method',220), ('branch','Branch',80), ('slope','Slope mV/dec',105), ('logj0','log10 j0',90),
            ('alpha','α',70), ('sigma','σ',70), ('r2','R²',70), ('n','N',50), ('window','ηwin mV',80),
        ]
        for key, text, width in headers:
            self.results.heading(key, text=text)
            self.results.column(key, width=width, stretch=(key=='method'))
        self.results.pack(fill='both', expand=True)
        self.log = ScrolledText(right, height=14, wrap='word')
        self.log.pack(fill='both', expand=True, pady=(8, 0))
        self._log('Ready. Output root: ' + str(self.output_root))

    def _settings(self):
        import faradaiq_tafel_adapter as _fq_tafel
        eeq_text = self.eeq_var.get().strip()
        eeq = None if not eeq_text else float(eeq_text)
        return _fq_tafel.TafelSettings(
            surface_area_cm2=float(self.area_var.get()),
            n_electrons=int(float(self.n_var.get())),
            temperature_K=float(self.temp_var.get()),
            eeq_V=eeq,
            current_adjust=bool(self.adjust_var.get()),
            fitting_window_mV=float(self.win_var.get()),
            manual_cathodic_range_V=_v130_parse_range_pair(self.cath_var.get(), (-0.18, -0.06)),
            manual_anodic_range_V=_v130_parse_range_pair(self.anod_var.get(), (0.06, 0.18)),
            scan_branch_mode=self.scan_branch_var.get(),
        )

    def _log(self, text):
        try:
            self.log.insert('end', str(text) + '\n')
            self.log.see('end')
        except Exception:
            pass
        try:
            if self.browser is not None:
                self.browser.log(str(text))
        except Exception:
            pass

    def _refresh_file_list(self):
        try:
            self.files_text.configure(state='normal')
            self.files_text.delete('1.0', 'end')
            if not self.paths:
                self.files_text.insert('end', 'No CV/LSV/IV files selected yet. Select a CV/LSV/IV Plot/view in the browser or choose files manually.\n')
            else:
                for p in self.paths:
                    self.files_text.insert('end', str(p) + '\n')
            self.files_text.configure(state='disabled')
        except Exception:
            pass

    def _choose_files(self):
        try:
            files = filedialog.askopenfilenames(
                parent=self,
                title='Choose CV/LSV/IV/Tafel data files',
                filetypes=[('Text/CSV data', '*.csv *.txt *.tsv *.dat *.asc *.mpt'), ('All files', '*.*')],
            )
            if files:
                self.paths = [Path(f) for f in files]
                self._refresh_file_list()
        except Exception as exc:
            messagebox.showerror('Choose files failed', str(exc), parent=self)

    def _use_selected(self):
        self.paths = _v130_selected_iv_lsv_paths(self.browser, generous=True)
        self._refresh_file_list()
        self._log(f'Loaded {len(self.paths)} selected Plot/view file(s).')

    def _clear_results(self):
        try:
            for iid in self.results.get_children():
                self.results.delete(iid)
        except Exception:
            pass

    def _insert_result_rows(self, source, rows):
        def fmt(x, nd=4):
            try:
                if x is None or x == '': return ''
                return f'{float(x):.{nd}g}'
            except Exception:
                return str(x)
        for row in rows:
            try:
                self.results.insert('', 'end', values=(
                    f"{Path(source).name}: {row.get('method','')}",
                    row.get('branch',''),
                    fmt(row.get('tafel_slope_mV_dec')),
                    fmt(row.get('log10_j0_A_cm2')),
                    fmt(row.get('alpha')),
                    fmt(row.get('sigma')),
                    fmt(row.get('r2')),
                    row.get('n_points',''),
                    fmt(row.get('eta_window_mV')),
                ))
            except Exception:
                pass

    def _run_selected(self):
        try:
            if not self.paths:
                messagebox.showinfo('No CV/LSV/IV files', 'Select CV/LSV/IV/Polarization files first.', parent=self)
                return
            import faradaiq_tafel_adapter as _fq_tafel
            self._clear_results()
            settings = self._settings()
            self._log('Running FaradaIQ Tafel analysis...')
            results = _fq_tafel.analyze_files(self.paths, self.output_root, settings)
            for res in results:
                self.last_output_dir = res.output_dir
                self._insert_result_rows(res.source_file, res.comparison_rows)
                self._log(f'Completed: {Path(res.source_file).name}')
                self._log(f'  Folder: {res.output_dir}')
                self._log(f'  Comparison: {res.comparison_csv}')
                if res.figure_png:
                    self._log(f'  Figure: {res.figure_png}')
                if res.warnings:
                    self._log('  Warnings: ' + '; '.join([w for w in res.warnings if w][:5]))
            messagebox.showinfo('FaradaIQ Tafel Analysis', f'Completed Tafel analysis for {len(results)} file(s).\n\nLast output:\n{self.last_output_dir}', parent=self)
        except Exception as exc:
            self._log('Tafel analysis failed: ' + str(exc))
            messagebox.showerror('Tafel analysis failed', str(exc), parent=self)

    def _dummy_test(self):
        try:
            import faradaiq_tafel_adapter as _fq_tafel
            self._clear_results()
            self._log('Generating dummy Butler-Volmer IV/LSV data and running test drive...')
            res = _fq_tafel.run_dummy_test(self.output_root)
            self.paths = [Path(res.source_file)]
            self.last_output_dir = res.output_dir
            self._refresh_file_list()
            self._insert_result_rows(res.source_file, res.comparison_rows)
            self._log(f'Dummy test complete. Data: {res.source_file}')
            self._log(f'Output: {res.output_dir}')
            self._log('Expected dummy parameters approximately: log10(j0)=-6, alpha=0.45. See Taffit-style rows in the table.')
            messagebox.showinfo('Dummy Tafel test complete', f'Dummy IV/LSV data and analysis were written to:\n{res.output_dir}', parent=self)
        except Exception as exc:
            self._log('Dummy test failed: ' + str(exc))
            messagebox.showerror('Dummy test failed', str(exc), parent=self)

    def _open_last(self):
        if self.last_output_dir:
            _v130_open_path(self.last_output_dir)
        else:
            _v130_open_path(self.output_root)


def _v130_open_tafel_window(browser=None):
    try:
        paths = _v130_selected_iv_lsv_paths(browser, generous=False)
        win = FaradaIQTafelAnalysisWindow(browser, paths=paths)
        try:
            win.transient(browser)
        except Exception:
            pass
        return win
    except Exception as exc:
        try:
            messagebox.showerror('FaradaIQ Tafel Analysis failed to open', str(exc), parent=browser)
        except Exception:
            pass


def _v130_run_tafel_selected_quick(browser=None):
    try:
        paths = _v130_selected_iv_lsv_paths(browser, generous=True)
        if not paths:
            messagebox.showinfo('No IV/LSV files selected', 'Select an IV/LSV/Polarization Plot/view first, then run Tafel analysis.', parent=browser)
            return
        import faradaiq_tafel_adapter as _fq_tafel
        root = _v130_tafel_output_root(browser)
        settings = _fq_tafel.TafelSettings()
        results = _fq_tafel.analyze_files(paths, root, settings)
        for r in results:
            try:
                browser.log(f'FaradaIQ Tafel analysis completed: {r.output_dir}')
            except Exception:
                pass
        msg = f'Completed FaradaIQ Tafel analysis for {len(results)} file(s).\n\nLast output:\n{results[-1].output_dir if results else root}'
        messagebox.showinfo('FaradaIQ Tafel Analysis', msg, parent=browser)
    except Exception as exc:
        try:
            messagebox.showerror('FaradaIQ Tafel Analysis failed', str(exc), parent=browser)
        except Exception:
            pass


