        ttk.Separator(body, orient='horizontal').pack(fill='x', pady=(8, 6))
        ttk.Label(body, text='FaradaIQ Tafel Analysis', style='Section.TLabel').pack(anchor='w')
        ttk.Label(
            body,
            text='For IV/LSV/polarization data: classical/manual Tafel slope, auto-linear R² window search, Taffit-style nonlinear BV fit (j0, -log(j0), α, cathodic/anodic slopes, σ), ηwin scan, and one comparison table.',
            style='Muted.TLabel', wraplength=330,
        ).pack(anchor='w', pady=(2, 6))
