        ttk.Button(body, text='Run Tafel analysis on selected view', command=lambda b=browser: _v130_run_tafel_selected_quick(b)).pack(fill='x', pady=2)
        ttk.Button(body, text='Dummy IV/LSV Tafel test drive', command=lambda b=browser: FaradaIQTafelAnalysisWindow(b, paths=[])._dummy_test()).pack(fill='x', pady=2)
