# ---- FaradaIQ Studio v273 patch: live ETA overrun handling for long parser steps ----
# User report: status could stay at "ETA ~42 s" while parse_EIS.py kept running.
# Cause: parser BAT progress reports only step start/end, so the previous estimator let the
# current step remainder fall to zero after it exceeded the learned/heuristic duration. v198
# keeps the current running command in the remaining-time model and switches to a conservative
# "ETA >" estimate when a step is running longer than expected.
APP_TITLE = "FaradaIQ Studio v273"


def _v130_safe_float(value, default=0.0):
    try:
        value = float(value)
        if value == value and value != float('inf') and value != float('-inf'):
            return value
    except Exception:
        pass
    return default


def _v130_recent_runtime_seconds(completed_durations, learned):
    vals = []
    try:
        for x in (completed_durations or [])[-10:]:
            fx = _v130_safe_float(x, 0.0)
            if fx > 0:
                vals.append(fx)
    except Exception:
        vals = []
    if not vals:
        return max(1.0, _v130_safe_float(learned, 30.0)), False
    try:
        import statistics as _v130_statistics
        med = float(_v130_statistics.median(vals))
    except Exception:
        med = float(sum(vals) / max(1, len(vals)))
    mean = float(sum(vals) / max(1, len(vals)))
    recent = 0.65 * med + 0.35 * mean
    # If this run already has several completed commands, current-run timing is usually better
    # than old history. Keep a small learned component to avoid overreacting to tiny CV/OCP steps.
    w = min(0.82, 0.18 + 0.12 * len(vals))
    per_cmd = (1.0 - w) * max(1.0, _v130_safe_float(learned, 30.0)) + w * max(1.0, recent)
    return max(1.0, per_cmd), True


def _v124_progress_time_text(elapsed, cur, tot, phase='RUNNING', detail='', step_elapsed=None, completed_durations=None):
    """v198 live elapsed/ETA text.

    This intentionally overrides the v124 helper used by the parser monitor. It cannot see
    internal progress inside parse_EIS.py/DRT, but it no longer freezes the ETA after the
    expected duration is exceeded. Once a command overruns, the ETA is shown as a lower-bound
    style estimate (ETA >...) and grows with the observed running time until the step finishes.
    """
    try:
        cur = max(0, int(cur)); tot = max(1, int(tot))
        elapsed = max(0.0, _v130_safe_float(elapsed, 0.0))
        phase_u = str(phase or '').upper()
        elapsed_txt = 'Elapsed ' + _v124_format_duration(elapsed)
        if phase_u == 'FINISHED' or (cur >= tot and phase_u in {'DONE', 'FINISHED'}):
            return elapsed_txt + ' | ETA done'

        kind = _v124_kind_from_detail(detail)
        learned, basis = _v124_learned_seconds(kind)
        per_cmd, used_recent = _v130_recent_runtime_seconds(completed_durations, learned)
        if used_recent:
            basis = 'learned+current' if str(basis).startswith('learned') else 'current+estimated'

        eta_prefix = 'ETA ~'
        step_txt = ''
        if phase_u == 'RUNNING':
            future_after_current = max(0, tot - cur)
            se = None
            if step_elapsed is not None:
                se = max(0.0, _v130_safe_float(step_elapsed, 0.0))
            if se is None:
                current_rem = max(8.0, 0.50 * per_cmd)
            elif se <= per_cmd:
                # Before the expected duration is reached, count down normally but leave a
                # small tail because BAT progress only updates when the process exits.
                current_rem = max(5.0, per_cmd - se)
                step_txt = ' | Step ' + _v124_format_duration(se)
            else:
                # The current command has already exceeded history/heuristic. We cannot know
                # exact progress, so use an adaptive tail rather than pretending zero remains.
                # The tail grows slowly with runtime, making the displayed ETA change every poll.
                over = se - per_cmd
                adaptive_tail = max(20.0, 0.35 * se, 0.75 * per_cmd)
                # DRT and very large EIS files can run much longer; avoid tiny tails for them.
                if kind in {'DRT', 'EIS'}:
                    adaptive_tail = max(adaptive_tail, min(900.0, 0.55 * se))
                current_rem = min(max(adaptive_tail, 20.0), 3600.0)
                eta_prefix = 'ETA >'
                basis = (basis + '; current step running long').strip('; ')
                step_txt = ' | Step ' + _v124_format_duration(se) + ' running long'
            remaining = current_rem + per_cmd * future_after_current
        else:
            # DONE means current command is complete; remaining commands start after cur.
            remaining = per_cmd * max(0, tot - cur)

        remaining = max(0.0, _v130_safe_float(remaining, 0.0))
        eta_txt = eta_prefix + _v124_format_duration(remaining)
        return f'{elapsed_txt}{step_txt} | {eta_txt} ({basis})'
    except Exception:
        try:
            return 'Elapsed ' + _v124_format_duration(elapsed) + ' | ETA estimating...'
        except Exception:
            return 'Elapsed -- | ETA estimating...'


def _v95_eta_text(elapsed, cur, tot, detail=''):
    """v198 compatibility override for older code paths."""
    return _v124_progress_time_text(elapsed, cur, tot, phase='DONE', detail=detail)

