# ---- FaradaIQ Studio v273 patch: always-visible Plot/view handoff buttons + robust EIS/Tafel kind detection ----
# User report: DearEIS and Tafel buttons were not visible even when an EIS Plot/view was selected.
# Fix: keep EIS/Tafel/CV handoff controls in a persistent Plot/view action box, and make kind detection
# prioritize explicit EIS/Nyquist/Bode modes before generic/CV-like names.

try:
    _V126_PREV_CURRENT_PLOT_VIEW_KIND = _v83_current_plot_view_kind
except Exception:
    _V126_PREV_CURRENT_PLOT_VIEW_KIND = None


def _v130_current_plot_view_kind(browser):
    paths = []
    label = ''
    kind = ''
    mode = ''
    try:
        mode = str(browser.plot_mode_var.get()) if hasattr(browser, 'plot_mode_var') else ''
    except Exception:
        mode = ''
    try:
        sel = browser.plot_view_list.curselection()
        if sel and getattr(browser, '_v69_plot_views', None):
            idx = sel[0]
            view = browser._v69_plot_views[idx]
            kind = str(view.get('kind') or '')
            label = str(view.get('name') or browser.plot_view_list.get(idx) or '')
            paths = [Path(p) for p in view.get('paths', []) or []]
            if not paths:
                for c in view.get('curves', []) or []:
                    if isinstance(c, dict) and c.get('path'):
                        paths.append(Path(c.get('path')))
    except Exception:
        pass
    text = ' '.join([mode, kind, label, ' '.join(str(p) for p in paths)]).lower()

    # Explicit plot mode wins. This prevents generic Plot/view labels from hiding EIS/Tafel panels.
    if any(tok in str(mode).lower() for tok in ('eis', 'nyquist', 'bode', 'zreal', 'zimag', 'impedance')):
        return 'EIS'
    if any(tok in str(mode).lower() for tok in ('iv', 'tafel', 'polarization', 'polarisation')):
        return 'IV / Tafel'
    if any(tok in str(mode).lower() for tok in ('cv', 'lsv')):
        return 'CV / LSV'

    # Impedance tokens are checked before CV tokens because paths/views can contain generic words.
    if any(tok in text for tok in ('eis', 'impedance', 'nyquist', 'bode', 'zreal', 'zimag', 'z_real', 'z_imag', 'full_eis', 'fulleis')):
        return 'EIS'
    if any(tok in text for tok in ('iv', 'tafel', 'polarization', 'polarisation', 'current-voltage', 'current_vs_potential')):
        return 'IV / Tafel'
    if 'lsv' in text or 'cv' in text or ('current' in text and ('potential' in text or 'voltage' in text)):
        return 'CV / LSV'
    if kind:
        return kind
    if callable(_V126_PREV_CURRENT_PLOT_VIEW_KIND):
        try:
            return _V126_PREV_CURRENT_PLOT_VIEW_KIND(browser)
        except Exception:
            pass
    return 'General'


