# ---- FaradaIQ Studio v273 canonical bundle workflow patch ----
# User policy: one canonical H5 + one JSON manifest, auto-created after initial export/parser run,
# rebuild manually after additional DRT, Browser reads the H5-derived structure, no DRT image plots,
# no separate/default/LLM-guided AI bundle buttons, and no Raman/SERS browser technique.

try:
    import faradaiq_canonical_bundle as _fq127_bundle
except Exception:
    _fq127_bundle = None


def _v130_gui_metadata(gui):
    meta = {}
    try:
        meta['experimental_description_or_prompt'] = gui.desc_text.get('1.0', 'end').strip()
    except Exception:
        meta['experimental_description_or_prompt'] = ''
    try:
        meta['data_structure_preview'] = gui.structure_text.get('1.0', 'end').strip()[:60000]
    except Exception:
        pass
    try:
        meta['summary_text'] = gui.summary_text.get('1.0', 'end').strip()[:60000]
    except Exception:
        pass
    try:
        meta['source_path'] = str(getattr(getattr(gui, 'collection', None), 'source_path', '') or '')
    except Exception:
        pass
    try:
        if getattr(gui, 'collection', None):
            meta['session_summary_json'] = gui.collection.build_summary_json(meta.get('experimental_description_or_prompt', ''))
    except Exception as exc:
        meta['session_summary_error'] = str(exc)
    try:
        if hasattr(gui, '_v92_metadata_map'):
            meta['structured_metadata_map'] = getattr(gui, '_v92_metadata_map')
    except Exception:
        pass
    return meta


def _v130_build_bundle_for_gui(gui, analysis_root=None, base_name=None, label='manual_rebuild', progress_callback=None):
    if _fq127_bundle is None:
        raise RuntimeError('faradaiq_canonical_bundle.py could not be imported.')
    base_name = base_name or _v27_current_base_name(gui)
    if analysis_root is None:
        analysis_root = _v55_find_existing_analysis_root(gui, base_name=base_name) if '_v55_find_existing_analysis_root' in globals() else _v35_analysis_root_for_export(gui, base_name=base_name)
    if analysis_root is None:
        raise FileNotFoundError('No analysis-ready folder was found. Export first, then rebuild the H5 bundle.')
    info = _fq127_bundle.build_canonical_bundle(
        analysis_root,
        base_name=base_name,
        gui_metadata=_v130_gui_metadata(gui),
        progress_callback=progress_callback,
        label=label,
    )
    try:
        techniques = ', '.join(info.get('techniques_detected') or []) or 'none detected'
        counts = info.get('technique_counts') or {}
        msg = f"Canonical H5 bundle rebuilt. Techniques: {techniques}. Counts: {counts}"
        gui.set_status(msg)
    except Exception:
        pass
    return info


