def make_ai_analysis_bundle(analysis_root, base_name=None, label='canonical', copy_files=False, progress_callback=None):
    """v198: build exactly one canonical H5 plus one JSON manifest for handoff/browser use."""
    if _fq127_bundle is None:
        if callable(_V130_PREV_MAKE_AI_ANALYSIS_BUNDLE):
            return _V130_PREV_MAKE_AI_ANALYSIS_BUNDLE(analysis_root, base_name=base_name, label=label, copy_files=False, progress_callback=progress_callback)
        raise RuntimeError('faradaiq_canonical_bundle.py could not be imported.')
    return _fq127_bundle.build_canonical_bundle(
        analysis_root,
        base_name=base_name,
        gui_metadata={'note': 'Built from CLI/export path. GUI prompt/metadata are included when rebuilt from the main GUI.'},
        progress_callback=progress_callback,
        label=label,
    )


def _v130_rebuild_bundle_gui(gui):
    try:
        win, log = _v63_analysis_progress_window(gui, 'Rebuild FaradaIQ H5 bundle') if '_v63_analysis_progress_window' in globals() else (None, lambda m: None)
        log('[Bundle] Rebuilding one canonical H5 + one JSON manifest.')
        info = _v130_build_bundle_for_gui(gui, label='manual_rebuild_after_optional_drt', progress_callback=log)
        tech = ', '.join(info.get('techniques_detected') or []) or 'none detected'
        validation = info.get('validation') or {}
        msg = (
            'Rebuilt canonical FaradaIQ bundle.\n\n'
            f"H5:\n{info.get('h5_path')}\n\n"
            f"JSON:\n{info.get('json_path')}\n\n"
            f"Techniques detected:\n{tech}\n\n"
            f"Technique counts:\n{info.get('technique_counts')}\n\n"
            f"CV one file per cycle key: {validation.get('cv_one_file_per_cycle_key', 'n/a')}\n"
            f"CV files included: {validation.get('cv_files_included', 'n/a')}"
        )
        try:
            if validation.get('warnings'):
                msg += '\n\nValidation warnings:\n' + '\n'.join(str(x) for x in validation.get('warnings')[:8])
        except Exception:
            pass
        try:
            messagebox.showinfo('FaradaIQ H5 bundle rebuilt', msg, parent=gui)
        except Exception:
            pass
        try:
            if os.name == 'nt': os.startfile(str(Path(info.get('bundle_dir'))))
        except Exception:
            pass
        return info
    except Exception as exc:
        try:
            gui.set_status('H5 bundle rebuild failed.')
        except Exception:
            pass
        try:
            messagebox.showerror('H5 bundle rebuild failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception:
            pass
        return None


