def _v130_browser_init(self, gui, analysis_root=None, base_name=None):
    original_root = Path(analysis_root).resolve() if analysis_root else None
    if original_root is None:
        try:
            original_root, inferred_base = _v64_analysis_root_for_browser(gui)
            original_root = Path(original_root).resolve()
            base_name = base_name or inferred_base
        except Exception:
            pass
    extract_info = _v130_extract_browser_root(original_root, base_name=base_name) if original_root is not None else None
    if extract_info and extract_info.get('cache_root'):
        if callable(_V130_PREV_BROWSER_INIT):
            _V130_PREV_BROWSER_INIT(self, gui, analysis_root=Path(extract_info['cache_root']), base_name=base_name)
        self._v130_original_analysis_root = str(original_root)
        self._v130_bundle_h5 = extract_info.get('h5_path')
        self._v130_bundle_json = extract_info.get('json_path')
        self._v130_bundle_manifest = extract_info.get('manifest') or {}
        try:
            self.log(f"FaradaIQ v273: Data Browser is reading canonical H5 bundle: {self._v130_bundle_h5}")
            self.log(f"FaradaIQ v273: Extracted {extract_info.get('n_tables')} H5 table(s) into hidden browser cache for plotting.")
            val = ((self._v130_bundle_manifest or {}).get('data_structure') or {}).get('validation') or {}
            if val:
                self.log('v198 bundle validation: ' + json.dumps(val, ensure_ascii=False)[:4000])
                if hasattr(self, 'summary_var'):
                    techs = ', '.join((self._v130_bundle_manifest or {}).get('techniques_detected') or [])
                    self.summary_var.set(f"H5 bundle source | techniques: {techs or 'none'} | CV one-file/cycle: {val.get('cv_one_file_per_cycle_key', 'n/a')}")
        except Exception:
            pass
        return
    if callable(_V130_PREV_BROWSER_INIT):
        _V130_PREV_BROWSER_INIT(self, gui, analysis_root=analysis_root, base_name=base_name)

