# ---- FaradaIQ Studio v273 root-level canonical bundle + browser-open fix ----
# User policy refinement:
# * Place the one canonical H5 and one canonical JSON beside *_analysis_ready_csv, not in a bundle subfolder.
# * Merge parent-level summary/manifest JSON content into the canonical JSON and remove those extra visible JSON files.
# * Build after the initial auto parser run finishes.
# * Prebuild/reuse the hidden H5 browser cache so the browser window does not open as a blank, non-responsive window.

try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v130_bundle_h5_for_root(root, base_name=None):
    try:
        if _fq127_bundle is None:
            return None
        return _fq127_bundle.find_latest_bundle(Path(root), base_name=base_name)
    except Exception:
        return None


def _v130_ensure_bundle_and_cache(gui, root=None, base_name=None, label='before_browser_open', force_build=False):
    """Ensure the v198 root-level H5/JSON exists and its hidden browser cache is ready."""
    try:
        if _fq127_bundle is None:
            return None
        if root is None or base_name is None:
            try:
                root2, base2 = _v64_analysis_root_for_browser(gui)
                root = root or root2
                base_name = base_name or base2
            except Exception:
                pass
        if root is None:
            return None
        root = Path(root).resolve()
        h5 = _v130_bundle_h5_for_root(root, base_name=base_name)
        if force_build or h5 is None or not Path(h5).exists():
            try: gui.set_status('Building canonical root-level H5/JSON bundle before opening browser...')
            except Exception: pass
            info = _v130_build_bundle_for_gui(gui, analysis_root=root, base_name=base_name, label=label)
            h5 = info.get('h5_path') if isinstance(info, dict) else None
        if h5 and Path(h5).exists():
            try:
                # Reuse the cache produced during bundle build. If missing/stale, build it here
                # before constructing the browser Toplevel, avoiding a blank not-responding window.
                extract = _fq127_bundle.extract_h5_tables_for_browser(Path(h5), prefer_reuse=True)
                try:
                    gui.set_status(f"Canonical H5 ready for browser: {Path(h5).name}; cache tables: {extract.get('n_tables')}")
                except Exception:
                    pass
                return extract
            except Exception as exc:
                try: gui.set_status(f'Canonical H5 exists but browser cache preparation failed: {exc}')
                except Exception: pass
                return {'h5_path': str(h5), 'cache_error': str(exc)}
    except Exception as exc:
        try: gui.set_status(f'Bundle/cache preparation failed: {exc}')
        except Exception: pass
    return None


