def _v67_start_pyseccm_monitor(gui, progress_file, total):
    """v198: keep the v125 ETA monitor and add initial auto-parser bundle creation."""
    try:
        if callable(_V130_PREV_START_PYSECCM_MONITOR):
            _V130_PREV_START_PYSECCM_MONITOR(gui, progress_file, total)
    except Exception:
        pass
    try:
        progress_file = Path(progress_file)
        state = {'stable_finished': 0, 'built': False}
        def poll_bundle_finish():
            try:
                txt = progress_file.read_text(encoding='utf-8', errors='replace').strip()
            except Exception:
                txt = ''
            if re.search(r'\bFINISHED\b', txt, flags=re.I):
                state['stable_finished'] += 1
            else:
                state['stable_finished'] = 0
            if state['stable_finished'] >= 3 and not state['built']:
                state['built'] = True
                try:
                    if bool(getattr(gui, '_v130_initial_export_parser_active', False)):
                        gui._v130_initial_export_parser_active = False
                        try: gui.set_status('Initial export/parsing finished. Building canonical root-level H5/JSON bundle...')
                        except Exception: pass
                        root, base_name = _v64_analysis_root_for_browser(gui)
                        info = _v130_build_bundle_for_gui(gui, analysis_root=root, base_name=base_name, label='after_initial_export_and_auto_parsing')
                        try:
                            tech = ', '.join(info.get('techniques_detected') or []) or 'none detected'
                            gui.set_status(f"Initial export/parsing bundle ready: {Path(info.get('h5_path')).name}; techniques: {tech}")
                        except Exception:
                            pass
                except Exception as exc:
                    try: gui.set_status(f'Initial H5/JSON bundle build failed after parser run: {exc}')
                    except Exception: pass
                return
            if not state['built']:
                try:
                    gui.after(1500, poll_bundle_finish)
                except Exception:
                    pass
        try:
            gui.after(1800, poll_bundle_finish)
        except Exception:
            pass
    except Exception:
        pass


