def _v64_open_data_browser(gui):
    try:
        root, base_name = _v64_analysis_root_for_browser(gui)
        if root and Path(root).exists():
            _v130_ensure_bundle_and_cache(gui, root=root, base_name=base_name, label='before_browser_open', force_build=False)
    except Exception:
        pass
    if callable(_V130_PREV_OPEN_DATA_BROWSER):
        return _V130_PREV_OPEN_DATA_BROWSER(gui)
    try:
        root, base_name = _v64_analysis_root_for_browser(gui)
        win = FaradaIQDataBrowser(gui, analysis_root=root, base_name=base_name)
        win.lift()
        return win
    except Exception as exc:
        messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        return None


# Handoff compatibility: when the latest bundle is a root-level H5, create local ZIP handoffs
# from only that H5 and its matching JSON rather than zipping the full run folder.
try:
    _V130_PREV_SEND_BUILT_AI_BUNDLE_CLI = _v56_send_built_ai_bundle_to_edison_cli
except Exception:
    _V130_PREV_SEND_BUILT_AI_BUNDLE_CLI = None


def _v130_h5_json_pair_for_path(path, base_name=None):
    try:
        h5 = _v130_bundle_h5_for_root(path, base_name=base_name)
        if h5 is None:
            p = Path(path).resolve()
            if p.is_file() and p.suffix.lower() in {'.h5', '.hdf5'}:
                h5 = p
        if h5 is None or not Path(h5).exists():
            return None, None
        h5 = Path(h5).resolve()
        json_path = h5.with_suffix('.json')
        if not json_path.exists():
            cands = sorted(h5.parent.glob('*_faradaiq_bundle.json'), key=lambda q: q.stat().st_mtime, reverse=True)
            json_path = cands[0] if cands else None
        return h5, json_path if json_path and Path(json_path).exists() else None
    except Exception:
        return None, None


def _v56_send_built_ai_bundle_to_edison_cli(path, base_name=None):
    h5, json_path = _v130_h5_json_pair_for_path(path, base_name=base_name)
    if h5 is not None:
        # Create a clean local handoff ZIP with exactly the canonical H5 + JSON + send metadata.
        root = Path(path).resolve()
        analysis_root = h5.parent
        safe = _v35_safe_name(base_name or h5.stem.replace('_faradaiq_bundle',''))
        run_id = datetime.now().strftime('%Y%m%d_%H%M%S')
        forced_response_dir = _v40_env_first(['FARADAIQ_EDISON_RESPONSE_DIR'], '') if '_v40_env_first' in globals() else ''
        handoff_dir = Path(forced_response_dir).resolve() if forced_response_dir else (analysis_root / f'{safe}_EdisonScientific_handoff' / f'edison_send_built_{run_id}')
        handoff_dir.mkdir(parents=True, exist_ok=True)
        metadata = {
            'created': datetime.now().isoformat(timespec='seconds'),
            'app': 'FaradaIQ Studio',
            'version': "v273",
            'operation': 'send_canonical_h5_json_bundle_to_edison',
            'base_name': base_name or safe,
            'analysis_root': str(analysis_root),
            'h5_path': str(h5),
            'json_path': str(json_path or ''),
            'bundle_policy': 'one canonical H5 plus one canonical JSON only',
        }
        metadata_path = handoff_dir / 'edison_send_metadata.json'
        metadata_path.write_text(json.dumps(metadata, ensure_ascii=False, indent=2), encoding='utf-8')
        zip_path = handoff_dir / f'{safe}_FaradaIQ_H5_JSON_for_Edison_{run_id}.zip'
        with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED) as z:
            z.write(h5, Path('FaradaIQ_bundle') / h5.name)
            if json_path is not None:
                z.write(json_path, Path('FaradaIQ_bundle') / Path(json_path).name)
            z.write(metadata_path, 'edison_send_metadata.json')
        result = {
            'uploaded': False,
            'status': 'local_handoff_zip_created_from_canonical_h5_json',
            'zip_path': str(zip_path),
            'handoff_dir': str(handoff_dir),
            'h5_path': str(h5),
            'json_path': str(json_path or ''),
            'message': 'Created local Edison handoff ZIP containing only the canonical H5 and JSON. Upload/send can be handled by the existing Edison client workflow when credentials are configured.',
        }
        (handoff_dir / 'edison_send_response.json').write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
        try:
            print('FaradaIQ v273 Edison handoff ZIP created:', zip_path, flush=True)
        except Exception:
            pass
        return result
    if callable(_V130_PREV_SEND_BUILT_AI_BUNDLE_CLI):
        return _V130_PREV_SEND_BUILT_AI_BUNDLE_CLI(path, base_name=base_name)
    raise FileNotFoundError('No canonical H5/JSON bundle found.')


