# ---- FaradaIQ Studio v273 nonblocking browser/bundle/LLM settings patch ----
# Fixes reported Windows issue: blank/white Toplevels marked Not Responding when the
# browser or LLM settings are opened while H5/cache building or LLM pings run on the Tk thread.

try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass

try:
    import threading as _v130_threading
except Exception:
    _v130_threading = None


def _v130_tk_after(widget, delay_ms, func):
    try:
        widget.after(delay_ms, func)
    except Exception:
        try:
            widget.after(0, func)
        except Exception:
            pass


def _v130_set_status_async(gui, msg):
    try:
        _v130_tk_after(gui, 0, lambda: gui.set_status(str(msg)))
    except Exception:
        pass


def _v130_gui_metadata_snapshot(gui):
    """Read Tk widgets on the Tk thread, then pass this plain dict to worker threads."""
    meta = {}
    try:
        meta['experimental_description_or_prompt'] = gui.desc_text.get('1.0', 'end').strip()
    except Exception:
        meta['experimental_description_or_prompt'] = ''
    try:
        meta['data_structure_preview'] = gui.structure_text.get('1.0', 'end').strip()[:60000]
    except Exception:
        pass
    try:
        meta['summary_text'] = gui.summary_text.get('1.0', 'end').strip()[:60000]
    except Exception:
        pass
    try:
        meta['source_path'] = str(getattr(getattr(gui, 'collection', None), 'source_path', '') or '')
    except Exception:
        pass
    try:
        if getattr(gui, 'collection', None):
            meta['session_summary_json'] = gui.collection.build_summary_json(meta.get('experimental_description_or_prompt', ''))
    except Exception as exc:
        meta['session_summary_error'] = str(exc)
    try:
        if hasattr(gui, '_v92_metadata_map'):
            meta['structured_metadata_map'] = getattr(gui, '_v92_metadata_map')
    except Exception:
        pass
    return meta


def _v130_build_bundle_worker(root, base_name, gui_metadata, label, progress_queue=None):
    if _fq127_bundle is None:
        raise RuntimeError('faradaiq_canonical_bundle.py could not be imported.')
    def progress(msg):
        try:
            if progress_queue is not None:
                progress_queue.append(str(msg))
            else:
                print(str(msg), flush=True)
        except Exception:
            pass
    info = _fq127_bundle.build_canonical_bundle(
        root,
        base_name=base_name,
        gui_metadata=gui_metadata or {},
        progress_callback=progress,
        label=label,
    )
    return info


def _v130_extract_cache_worker(h5_path, progress_queue=None):
    if _fq127_bundle is None:
        raise RuntimeError('faradaiq_canonical_bundle.py could not be imported.')
    if progress_queue is not None:
        try: progress_queue.append(f'[Browser cache] Extracting plotting tables from {Path(h5_path).name} ...')
        except Exception: pass
    return _fq127_bundle.extract_h5_tables_for_browser(Path(h5_path), prefer_reuse=True)


def _v130_open_browser_from_cache(gui, cache_info, base_name):
    try:
        cache_root = cache_info.get('cache_root') if isinstance(cache_info, dict) else None
        if not cache_root or not Path(cache_root).exists():
            raise FileNotFoundError('H5 browser cache was not created.')
        win = FaradaIQDataBrowser(gui, analysis_root=Path(cache_root), base_name=base_name)
        try:
            win._faradaiq_source_h5_path = cache_info.get('h5_path')
            win._faradaiq_source_bundle_json = cache_info.get('json_path')
            win._faradaiq_h5_manifest = cache_info.get('manifest')
        except Exception:
            pass
        try:
            win.title(f'FaradaIQ Studio v273 — experiment map + H5 browser — {Path(cache_info.get("h5_path", "")).name}')
        except Exception:
            pass
        try:
            win.log(f"Loaded from canonical H5 cache. Source H5: {cache_info.get('h5_path')} | tables: {cache_info.get('n_tables')}")
        except Exception:
            pass
        win.lift()
        return win
    except Exception as exc:
        try:
            messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception:
            pass
        return None


def _v130_prepare_and_open_browser_async(gui, root=None, base_name=None, force_build=False):
    """Prepare H5/cache on a worker thread, then open the browser from the cache root."""
    try:
        if _fq127_bundle is None:
            raise RuntimeError('faradaiq_canonical_bundle.py could not be imported.')
        if root is None or base_name is None:
            root2, base2 = _v64_analysis_root_for_browser(gui)
            root = root or root2
            base_name = base_name or base2
        root = Path(root).resolve()
        if not root.exists():
            messagebox.showwarning('No analysis folder found', 'Export archive + CSV first, then open Data browser + analysis.', parent=gui)
            return None
        # Show a small progress dialog immediately so Windows does not show a blank browser Toplevel.
        prep = tk.Toplevel(gui)
        prep.title('Preparing FaradaIQ H5 browser')
        prep.geometry('760x280')
        try:
            p = _v36_theme_palette(getattr(gui, '_faradaiq_theme_mode', 'dark'))
            prep.configure(bg=p.get('bg'))
        except Exception:
            pass
        frame = ttk.Frame(prep, style='Card.TFrame', padding=(14, 14))
        frame.pack(fill='both', expand=True, padx=10, pady=10)
        ttk.Label(frame, text='Preparing Data Browser from canonical H5', style='Section.TLabel').pack(anchor='w')
        msg_var = tk.StringVar(value='Checking for root-level H5/JSON bundle...')
        ttk.Label(frame, textvariable=msg_var, style='Card.TLabel', wraplength=700).pack(anchor='w', fill='x', pady=(8, 8))
        logbox = ScrolledText(frame, wrap='word', height=8)
        logbox.pack(fill='both', expand=True)
        try:
            logbox.configure(background='#020617', foreground='#e5eefb', insertbackground='#f8fafc')
        except Exception:
            pass
        progress = []
        gui_metadata = _v130_gui_metadata_snapshot(gui)

        def plog(m):
            try:
                logbox.configure(state='normal')
                logbox.insert('end', str(m) + '\n')
                logbox.see('end')
                logbox.configure(state='disabled')
                msg_var.set(str(m))
            except Exception:
                pass

        def pump():
            try:
                while progress:
                    plog(progress.pop(0))
            except Exception:
                pass
            try:
                if prep.winfo_exists() and not getattr(prep, '_v130_done', False):
                    prep.after(300, pump)
            except Exception:
                pass

        def worker():
            err = None; cache_info = None; info = None
            try:
                h5 = _v130_bundle_h5_for_root(root, base_name=base_name)
                if force_build or h5 is None or not Path(h5).exists():
                    progress.append('[Bundle] Building one root-level H5 + one JSON from analysis-ready export...')
                    info = _v130_build_bundle_worker(root, base_name, gui_metadata, 'before_browser_open_async', progress)
                    h5 = info.get('h5_path') if isinstance(info, dict) else None
                if not h5 or not Path(h5).exists():
                    raise FileNotFoundError('Canonical H5 bundle was not found or created.')
                progress.append(f'[Browser cache] Source H5 ready: {Path(h5).name}')
                cache_info = _v130_extract_cache_worker(h5, progress)
            except Exception as exc:
                err = f'{exc}\n\n{traceback.format_exc()}'
            def done():
                try: prep._v130_done = True
                except Exception: pass
                try: prep.destroy()
                except Exception: pass
                if err:
                    try: messagebox.showerror('Data browser preparation failed', err, parent=gui)
                    except Exception: pass
                    return
                try:
                    n = cache_info.get('n_tables') if isinstance(cache_info, dict) else 'n/a'
                    gui.set_status(f'Canonical H5 cache ready. Opening Data Browser from {n} plotting tables.')
                except Exception:
                    pass
                _v130_open_browser_from_cache(gui, cache_info, base_name)
            _v130_tk_after(gui, 0, done)
        pump()
        if _v130_threading is None:
            worker()
        else:
            th = _v130_threading.Thread(target=worker, daemon=True)
            th.start()
        return prep
    except Exception as exc:
        try:
            messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception:
            pass
        return None


# Override browser button target: no synchronous H5/cache work and no direct open of loose CSV tree.
def _v64_open_data_browser(gui):
    return _v130_prepare_and_open_browser_async(gui, force_build=False)


# Override initial post-parser bundle build so it runs in the background and does not freeze LLM settings or main UI.
try:
    _V1302_MONITOR_BASE = globals().get('_V130_PREV_START_PYSECCM_MONITOR') or _V130_PREV_START_PYSECCM_MONITOR
except Exception:
    _V1302_MONITOR_BASE = None


def _v67_start_pyseccm_monitor(gui, progress_file, total):
    try:
        if callable(_V1302_MONITOR_BASE):
            _V1302_MONITOR_BASE(gui, progress_file, total)
    except Exception:
        pass
    try:
        progress_file = Path(progress_file)
        state = {'stable_finished': 0, 'built': False}
        def poll_bundle_finish():
            try:
                txt = progress_file.read_text(encoding='utf-8', errors='replace').strip()
            except Exception:
                txt = ''
            if re.search(r'\bFINISHED\b', txt, flags=re.I):
                state['stable_finished'] += 1
            else:
                state['stable_finished'] = 0
            if state['stable_finished'] >= 3 and not state['built']:
                state['built'] = True
                if bool(getattr(gui, '_v130_initial_export_parser_active', False)):
                    gui._v130_initial_export_parser_active = False
                    try:
                        root, base_name = _v64_analysis_root_for_browser(gui)
                        meta = _v130_gui_metadata_snapshot(gui)
                        gui.set_status('Initial export/parsing finished. Building canonical H5/JSON in background...')
                    except Exception as exc:
                        _v130_set_status_async(gui, f'Could not start background bundle build: {exc}')
                        return
                    def worker():
                        try:
                            info = _v130_build_bundle_worker(root, base_name, meta, 'after_initial_export_and_auto_parsing_async')
                            tech = ', '.join(info.get('techniques_detected') or []) or 'none detected'
                            _v130_set_status_async(gui, f"Initial H5/JSON bundle ready: {Path(info.get('h5_path')).name}; techniques: {tech}. Click Data Browser to prepare plotting cache.")
                        except Exception as exc:
                            _v130_set_status_async(gui, f'Initial H5/JSON background bundle build failed: {exc}')
                    if _v130_threading is None:
                        worker()
                    else:
                        _v130_threading.Thread(target=worker, daemon=True).start()
                return
            if not state['built']:
                try: gui.after(1500, poll_bundle_finish)
                except Exception: pass
        try: gui.after(1800, poll_bundle_finish)
        except Exception: pass
    except Exception:
        pass


# Make Rebuild H5 bundle nonblocking too.
def _v130_rebuild_bundle_gui(gui):
    try:
        prep = tk.Toplevel(gui)
        prep.title('Rebuild FaradaIQ H5 bundle')
        prep.geometry('760x260')
        frame = ttk.Frame(prep, style='Card.TFrame', padding=(14,14)); frame.pack(fill='both', expand=True, padx=10, pady=10)
        ttk.Label(frame, text='Rebuilding canonical H5 + JSON', style='Section.TLabel').pack(anchor='w')
        msg_var = tk.StringVar(value='Starting rebuild...')
        ttk.Label(frame, textvariable=msg_var, style='Card.TLabel', wraplength=700).pack(anchor='w', fill='x', pady=(8,8))
        logbox = ScrolledText(frame, wrap='word', height=7); logbox.pack(fill='both', expand=True)
        progress=[]
        root, base_name = _v64_analysis_root_for_browser(gui)
        meta = _v130_gui_metadata_snapshot(gui)
        def pump():
            try:
                while progress:
                    m=progress.pop(0); msg_var.set(m); logbox.insert('end', m+'\n'); logbox.see('end')
            except Exception: pass
            try:
                if prep.winfo_exists() and not getattr(prep,'_done',False): prep.after(300,pump)
            except Exception: pass
        def worker():
            err=None; info=None
            try:
                info = _v130_build_bundle_worker(root, base_name, meta, 'manual_rebuild_after_optional_drt_async', progress)
            except Exception as exc:
                err=f'{exc}\n\n{traceback.format_exc()}'
            def done():
                try: prep._done=True; prep.destroy()
                except Exception: pass
                if err:
                    try: messagebox.showerror('H5 bundle rebuild failed', err, parent=gui)
                    except Exception: pass
                    return
                tech=', '.join(info.get('techniques_detected') or []) or 'none detected'
                try: gui.set_status(f'Rebuilt canonical H5/JSON. Techniques: {tech}')
                except Exception: pass
                try:
                    messagebox.showinfo('FaradaIQ H5 bundle rebuilt', f"H5:\n{info.get('h5_path')}\n\nJSON:\n{info.get('json_path')}\n\nTechniques detected:\n{tech}\n\nCounts:\n{info.get('technique_counts')}", parent=gui)
                except Exception: pass
            _v130_tk_after(gui, 0, done)
        pump()
        if _v130_threading is None: worker()
        else: _v130_threading.Thread(target=worker, daemon=True).start()
        return prep
    except Exception as exc:
        try: messagebox.showerror('H5 bundle rebuild failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception: pass
        return None

