# ---- FaradaIQ Studio v273 QA bundle/browser patch ----
# Fixes v198 browser hang by opening the H5-derived cache with the pre-v198
# Data Browser initializer directly, avoiding the H5-opening wrapper recursion.
# Also relies on faradaiq_canonical_bundle.py v138, which builds one clean root
# H5 + one clean root JSON using DAT/sequence metadata for HEKA exports.

try:
    _V138_PREV_OPEN_BROWSER_FROM_CACHE = globals().get('_v130_open_browser_from_cache')
except Exception:
    _V138_PREV_OPEN_BROWSER_FROM_CACHE = None


def _v130_open_browser_from_cache(gui, cache_info, base_name):
    try:
        cache_root = None
        if isinstance(cache_info, dict):
            cache_root = cache_info.get('cache_root')
        if not cache_root:
            raise FileNotFoundError('H5 browser cache was not prepared; cache_root is empty.')
        cache_root = Path(cache_root).resolve()
        if not cache_root.exists():
            raise FileNotFoundError(f'H5 browser cache folder does not exist: {cache_root}')

        # Use the initializer captured before v198 installed its H5 wrapper. Calling
        # FaradaIQDataBrowser(...) here can re-enter the v198/v138 H5 extraction path
        # and leave a blank white Tk window. __new__ + previous init opens directly.
        init = globals().get('_V130_PREV_BROWSER_INIT')
        if callable(init):
            win = FaradaIQDataBrowser.__new__(FaradaIQDataBrowser)
            init(win, gui, analysis_root=cache_root, base_name=base_name)
        else:
            # Fallback only if the captured initializer is unavailable.
            win = FaradaIQDataBrowser(gui, analysis_root=cache_root, base_name=base_name)

        try:
            win._v138_source_policy = 'canonical_h5_browser_cache'
            win._faradaiq_source_h5_path = (cache_info or {}).get('h5_path')
            win._faradaiq_source_bundle_json = (cache_info or {}).get('json_path')
            win._faradaiq_h5_manifest = (cache_info or {}).get('manifest') or {}
            win._v130_original_analysis_root = (cache_info or {}).get('source_root') or (cache_info or {}).get('analysis_root')
            win._v130_bundle_h5 = win._faradaiq_source_h5_path
            win._v130_bundle_json = win._faradaiq_source_bundle_json
            win._v130_bundle_manifest = win._faradaiq_h5_manifest
        except Exception:
            pass
        try:
            win.title(f'FaradaIQ Studio v273 — experiment map + H5 browser — {base_name or "bundle"}')
        except Exception:
            pass
        try:
            win.log(f'FaradaIQ v273: Data Browser opened from canonical H5 cache: {cache_root}')
            if getattr(win, '_faradaiq_source_h5_path', None):
                win.log(f'v138: Source H5: {win._faradaiq_source_h5_path}')
            manifest = getattr(win, '_faradaiq_h5_manifest', {}) or {}
            val = ((manifest.get('data_structure') or {}).get('validation') or {})
            if val:
                win.log('v138 bundle validation: ' + json.dumps(val, ensure_ascii=False)[:5000])
            techs = ', '.join(manifest.get('techniques_detected') or [])
            if hasattr(win, 'summary_var'):
                win.summary_var.set(
                    f'H5 bundle source | techniques: {techs or "none"} | '
                    f'CV files: {val.get("cv_files_included", "n/a")} | '
                    f'one file/cycle: {val.get("cv_one_file_per_cycle_key", "n/a")}'
                )
        except Exception:
            pass
        return win
    except Exception as exc:
        try:
            messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception:
            pass
        return None


# Avoid accidental direct construction through the v198 H5 wrapper. The toolbar
# button uses _v64_open_data_browser, which prepares H5/cache first and then calls
# _v130_open_browser_from_cache above. Restoring __init__ removes one recursion path.
try:
    if callable(globals().get('_V130_PREV_BROWSER_INIT')):
        FaradaIQDataBrowser.__init__ = globals().get('_V130_PREV_BROWSER_INIT')
except Exception:
    pass


# Ensure the browser preparation path does not open the old blank window on errors
# and labels the progress clearly for v138.
try:
    _V138_PREV_PREPARE_BROWSER_ASYNC = globals().get('_v130_prepare_and_open_browser_async')
except Exception:
    _V138_PREV_PREPARE_BROWSER_ASYNC = None


def _v130_prepare_and_open_browser_async(gui, force_build=False):
    if callable(_V138_PREV_PREPARE_BROWSER_ASYNC):
        try:
            return _V138_PREV_PREPARE_BROWSER_ASYNC(gui, force_build=force_build)
        except TypeError:
            return _V138_PREV_PREPARE_BROWSER_ASYNC(gui)
        except Exception as exc:
            try:
                messagebox.showerror('Data browser preparation failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
            except Exception:
                pass
            return None
    return None


def _v64_open_data_browser(gui):
    return _v130_prepare_and_open_browser_async(gui, force_build=False)


