def _v138_fmt_size(n):
    try:
        n = float(n)
        for unit in ('B', 'KB', 'MB', 'GB'):
            if n < 1024:
                return f'{n:.0f} {unit}' if unit == 'B' else f'{n:.1f} {unit}'
            n /= 1024.0
    except Exception:
        pass
    return ''


def _v138_csv_read(path, max_rows=None):
    try:
        import pandas as _pd
        kw = {'sep': None, 'engine': 'python'}
        if max_rows:
            kw['nrows'] = int(max_rows)
        return _pd.read_csv(path, **kw)
    except Exception:
        if '_v64_read_table_file' in globals():
            try:
                return _v64_read_table_file(path, max_rows=max_rows or 100000)
            except Exception:
                pass
        raise


def _v138_pick_col(columns, needles):
    cols = list(columns)
    lows = [(str(c).lower(), c) for c in cols]
    for needle in needles:
        nl = str(needle).lower()
        for low, col in lows:
            if nl in low:
                return col
    return None


def _v138_choose_xy(df, mode='Auto', path=None):
    mode_l = str(mode or 'Auto').lower()
    cols = list(df.columns)
    # Impedance forms first.
    freq = _v138_pick_col(cols, ['frequency_hz', 'freq', 'frequency', 'f/hz', 'hz'])
    zr = _v138_pick_col(cols, ['zreal_ohm', 'zreal', 're(z)', "z'", 'zre', 'real'])
    zi = _v138_pick_col(cols, ['zimag_ohm', 'zimag', 'im(z)', "z''", 'zim', 'imag'])
    negzi = _v138_pick_col(cols, ['neg_zimag_ohm', '-zimag', '-zimag_ohm', '-im'])
    zmod = _v138_pick_col(cols, ['zmod_ohm', '|z|', 'modulus', 'magnitude'])
    phase = _v138_pick_col(cols, ['phase_deg', 'phase', 'theta'])
    if 'nyquist' in mode_l or (mode_l == 'auto' and zr is not None and (zi is not None or negzi is not None)):
        return zr, negzi or zi, 'EIS Nyquist'
    if 'bode magnitude' in mode_l or ('bode' in mode_l and 'phase' not in mode_l):
        if freq is not None and zmod is not None:
            return freq, zmod, 'Bode magnitude'
        if freq is not None and zr is not None:
            return freq, zr, 'Bode magnitude fallback'
    if 'bode phase' in mode_l:
        if freq is not None and phase is not None:
            return freq, phase, 'Bode phase'
    # DRT.
    tau = _v138_pick_col(cols, ['tau'])
    gamma = _v138_pick_col(cols, ['gamma'])
    if 'drt' in mode_l or (mode_l == 'auto' and tau is not None and gamma is not None):
        return tau, gamma, 'DRT'
    # CV/LSV/IV.
    pot = _v138_pick_col(cols, ['potential_v', 'potential', 'e_v', 'ewe', 'emon', 'voltage'])
    cur = _v138_pick_col(cols, ['current_a', 'current', 'i_a', 'i/', 'amps'])
    if pot is not None and cur is not None:
        return pot, cur, 'CV / LSV / IV'
    # Generic numeric fallback.
    try:
        import pandas as _pd
        numeric = []
        for c in cols:
            vals = _pd.to_numeric(df[c], errors='coerce')
            if vals.notna().sum() >= 2:
                numeric.append(c)
        if len(numeric) >= 2:
            return numeric[0], numeric[1], 'Numeric'
    except Exception:
        pass
    return None, None, 'No numeric pair'


class FaradaIQH5Browser(tk.Toplevel):
    """Lightweight canonical-H5 browser used by v138 to avoid legacy GUI hangs."""

    def __init__(self, gui, cache_info=None, base_name=None):
        super().__init__(gui)
        self.gui = gui
        self.cache_info = cache_info or {}
        self.cache_root = Path(self.cache_info.get('cache_root') or self.cache_info.get('analysis_root') or Path.cwd()).resolve()
        self.h5_path = Path(self.cache_info.get('h5_path')).resolve() if self.cache_info.get('h5_path') else None
        self.json_path = Path(self.cache_info.get('json_path')).resolve() if self.cache_info.get('json_path') else None
        self.manifest = self.cache_info.get('manifest') or {}
        self.base_name = base_name or (self.manifest.get('base_name') if isinstance(self.manifest, dict) else None) or (self.h5_path.stem.replace('_faradaiq_bundle','') if self.h5_path else self.cache_root.name)
        try:
            self.analyzed_root = (self.h5_path.parent if self.h5_path else self.cache_root) / f'{_v35_safe_name(self.base_name)}_FaradaIQ_analyzed_data'
        except Exception:
            self.analyzed_root = self.cache_root / 'FaradaIQ_analyzed_data'
        self.analyzed_root.mkdir(parents=True, exist_ok=True)
        self._path_by_iid = {}
        self._curves = []
        self._figure = None; self._ax = None; self._canvas = None; self._toolbar = None
        self.last_plot_paths = []
        self.selected_path = None
        self.selected_df = None
        self.title(f'FaradaIQ Studio v273 — canonical H5 browser — {self.base_name}')
        self.geometry('1540x900')
        self.minsize(1120, 720)
        try: _v83_set_window_icon(self)
        except Exception: pass
        self._build_visible_ui_first()
        # Populate after the window is drawn; prevents Windows from painting a white frozen Toplevel.
        try: self.after(80, self.refresh_tree)
        except Exception: self.refresh_tree()

    def _style_text(self, widget):
        try:
            widget.configure(background='#020617', foreground='#e5eefb', insertbackground='#f8fafc', font=('Consolas', 8))
        except Exception:
            pass

    def _build_visible_ui_first(self):
        try: _v36_apply_theme(self, getattr(self.gui, '_faradaiq_theme_mode', 'dark'))
        except Exception: pass
        outer = ttk.Frame(self, style='Card.TFrame', padding=(8, 6)); outer.pack(fill='both', expand=True)
        top = ttk.Frame(outer, style='Card.TFrame'); top.pack(fill='x', pady=(0, 6))
        ttk.Label(top, text='FaradaIQ canonical H5 browser', style='Section.TLabel').pack(side='left', padx=(0, 12))
        src = self.h5_path.name if self.h5_path else str(self.cache_root)
        self.summary_var = tk.StringVar(value=f'Source: {src}')
        ttk.Label(top, textvariable=self.summary_var, style='Muted.TLabel').pack(side='left', fill='x', expand=True)
        ttk.Button(top, text='Refresh', command=self.refresh_tree).pack(side='left', padx=3)
        ttk.Button(top, text='Open bundle folder', command=self.open_bundle_folder).pack(side='left', padx=3)
        ttk.Button(top, text='Close', command=self.destroy).pack(side='right', padx=3)

        pan = ttk.Panedwindow(outer, orient='horizontal'); pan.pack(fill='both', expand=True)
        left = ttk.Frame(pan, style='Card.TFrame', padding=(6,6)); pan.add(left, weight=2)
        center = ttk.Frame(pan, style='Card.TFrame', padding=(6,6)); pan.add(center, weight=4)
        right = ttk.Frame(pan, style='Card.TFrame', padding=(6,6)); pan.add(right, weight=2)

        ttk.Label(left, text='Experiment map from H5/JSON', style='Section.TLabel').pack(anchor='w')
        tree_frame = ttk.Frame(left, style='Card.TFrame'); tree_frame.pack(fill='both', expand=True, pady=(4,6))
        self.tree = ttk.Treeview(tree_frame, columns=('kind','size'), show='tree headings', selectmode='extended', height=26)
        self.tree.heading('#0', text='Technique / group / file')
        self.tree.heading('kind', text='Type')
        self.tree.heading('size', text='Size')
        self.tree.column('#0', width=430, stretch=True)
        self.tree.column('kind', width=110, stretch=False)
        self.tree.column('size', width=80, stretch=False)
        y = ttk.Scrollbar(tree_frame, orient='vertical', command=self.tree.yview)
        self.tree.configure(yscrollcommand=y.set)
        self.tree.pack(side='left', fill='both', expand=True); y.pack(side='right', fill='y')
        self.tree.bind('<<TreeviewSelect>>', lambda e=None: self.preview_selected())

        plot_top = ttk.Frame(center, style='Card.TFrame'); plot_top.pack(fill='x', pady=(0,4))
        ttk.Button(plot_top, text='Plot/overlay selected', command=lambda: self.plot_selected(clear=True)).pack(side='left', padx=(0,4))
        ttk.Button(plot_top, text='Overlay add', command=lambda: self.plot_selected(clear=False)).pack(side='left', padx=(0,4))
        ttk.Button(plot_top, text='Clear plot', command=self.clear_plot).pack(side='left', padx=(0,4))
        ttk.Label(plot_top, text='Mode', style='Muted.TLabel').pack(side='left', padx=(12,3))
        self.plot_mode_var = tk.StringVar(value='Auto')
        ttk.Combobox(plot_top, textvariable=self.plot_mode_var, state='readonly', width=18, values=['Auto','CV / LSV','EIS Nyquist','Bode magnitude','Bode phase','DRT','IV / Tafel','Numeric']).pack(side='left')
        ttk.Label(plot_top, text='Max curves', style='Muted.TLabel').pack(side='left', padx=(12,3))
        self.max_curves_var = tk.StringVar(value='24')
        ttk.Entry(plot_top, textvariable=self.max_curves_var, width=5).pack(side='left')
        self.plot_holder = ttk.Frame(center, style='Card.TFrame')
        self.plot_holder.pack(fill='both', expand=True)
        self.placeholder = ScrolledText(self.plot_holder, wrap='word')
        self.placeholder.pack(fill='both', expand=True)
        self._style_text(self.placeholder)
        self.placeholder.insert('1.0', 'Browser opened from canonical H5 cache. Select files or groups, then click Plot/overlay selected.\n\nMatplotlib is loaded only when plotting so this window opens immediately.\n')
        self.placeholder.configure(state='disabled')

        ttk.Label(right, text='Handoff / analysis tools', style='Section.TLabel').pack(anchor='w')
        ttk.Button(right, text='DearEIS EIS handoff for selected data', command=lambda: _v130p_open_deareis_with_selected(self, launch=False) if '_v130p_open_deareis_with_selected' in globals() else None).pack(fill='x', pady=2)
        ttk.Button(right, text='Open selected EIS in pyDRTtools', command=lambda: _v225_open_pydrttools_with_selected(self)).pack(fill='x', pady=2)
        ttk.Button(right, text='FaradaIQ Tafel Analysis for selected IV/LSV', command=lambda: _v130_open_tafel_window(self) if '_v130_open_tafel_window' in globals() else None).pack(fill='x', pady=2)
        ttk.Button(right, text='PySimpleEChem CV handoff for selected CV', command=self._open_pysimple).pack(fill='x', pady=2)
        ttk.Separator(right).pack(fill='x', pady=8)
        ttk.Label(right, text='Quick bundle QA', style='Section.TLabel').pack(anchor='w')
        self.qa_text = ScrolledText(right, height=13, wrap='word'); self.qa_text.pack(fill='x', pady=(3,8)); self._style_text(self.qa_text)
        ttk.Label(right, text='Browser log', style='Section.TLabel').pack(anchor='w')
        self.log_text = ScrolledText(right, height=18, wrap='word'); self.log_text.pack(fill='both', expand=True); self._style_text(self.log_text)
        self._write_qa_summary()

    def _open_pysimple(self):
        try:
            if '_v95_open_pysimpleechem_for_current_view' in globals():
                return _v95_open_pysimpleechem_for_current_view(self)
            if '_v83_open_native_pysimpleechem_with_selected' in globals():
                return _v83_open_native_pysimpleechem_with_selected(self)
            messagebox.showinfo('PySimpleEChem', 'PySimpleEChem handoff function is not available in this build.', parent=self)
        except Exception as exc:
            messagebox.showerror('PySimpleEChem handoff failed', str(exc), parent=self)

    def _write_qa_summary(self):
        try:
            self.qa_text.configure(state='normal'); self.qa_text.delete('1.0','end')
            man = self.manifest if isinstance(self.manifest, dict) else {}
            counts = man.get('technique_counts') or {}
            val = ((man.get('data_structure') or {}).get('validation') or {})
            lines = []
            lines.append('Techniques detected: ' + (', '.join(man.get('techniques_detected') or counts.keys()) or 'none'))
            if counts: lines.append('Technique counts: ' + json.dumps(counts, ensure_ascii=False))
            for k in ['expected_points_from_dat','expected_scan_rates_mV_s_from_dat','expected_cycles_per_cv_from_dat','expected_cv_cycle_files_from_dat','cv_files_included','cv_unique_point_scanrate_cycle_keys','cv_one_file_per_cycle_key','eis_tables_included','drt_tables_included']:
                if k in val: lines.append(f'{k}: {val.get(k)}')
            if val.get('warnings'): lines.append('Warnings: ' + '; '.join(map(str, val.get('warnings')[:10])))
            self.qa_text.insert('1.0', '\n'.join(lines) if lines else 'No manifest QA metadata available yet.')
            self.qa_text.configure(state='disabled')
            try:
                self.summary_var.set(f'H5 source | CV {counts.get("CV / LSV",0)} | EIS {counts.get("EIS",0)} | DRT {counts.get("DRT",0)} | one-file/cycle {val.get("cv_one_file_per_cycle_key", "n/a")}')
            except Exception: pass
        except Exception: pass

    def log(self, msg):
        try:
            self.log_text.insert('end', f'[{datetime.now().strftime("%H:%M:%S")}] {msg}\n')
            self.log_text.see('end')
        except Exception: pass

    def open_bundle_folder(self):
        try:
            p = self.h5_path.parent if self.h5_path else self.cache_root
            if os.name == 'nt': os.startfile(str(p))
            else:
                import subprocess; subprocess.Popen(['open' if sys.platform=='darwin' else 'xdg-open', str(p)])
        except Exception as exc:
            messagebox.showerror('Open folder failed', str(exc), parent=self)

    def refresh_tree(self):
        try:
            self.tree.delete(*self.tree.get_children())
            self._path_by_iid.clear()
            root_ids = {}
            def root(label, open=True):
                iid = self.tree.insert('', 'end', text=label, values=('', ''), open=open)
                root_ids[label] = iid
                return iid
            cv_rate_root = root('CV / LSV grouped by scan rate', True)
            cv_point_root = root('CV / LSV grouped by point', False)
            eis_root = root('EIS sets / Nyquist + Bode tables', True)
            drt_root = root('DRT analyzed data tables', False)
            other_root = root('Other tables', False)
            files = sorted([p for p in self.cache_root.rglob('*.csv') if p.is_file()], key=lambda p: str(p).lower())
            inserted = 0
            node_cache = {}
            def child(parent, label, kind='', open=False):
                key=(parent,label,kind)
                if key in node_cache: return node_cache[key]
                iid=self.tree.insert(parent,'end',text=label,values=(kind,''),open=open)
                node_cache[key]=iid; return iid
            def add_file(parent, p, kind):
                nonlocal inserted
                label = p.name
                iid = self.tree.insert(parent, 'end', text=label, values=(kind, _v138_fmt_size(p.stat().st_size)))
                self._path_by_iid[iid] = p
                inserted += 1
            for p in files:
                s = p.as_posix().lower()
                if '/cv_lsv/' in s or '\\cv_lsv\\' in s:
                    m_rate = re.search(r'scanrate_([^/\\]+)', p.as_posix(), flags=re.I)
                    m_point = re.search(r'point_(\d+)', p.as_posix(), flags=re.I)
                    m_cycle = re.search(r'cycle_(\d+)', p.as_posix(), flags=re.I)
                    rate = m_rate.group(1) if m_rate else 'unknown'
                    point = int(m_point.group(1)) if m_point else 0
                    cyc = int(m_cycle.group(1)) if m_cycle else 0
                    rnode = child(cv_rate_root, f'{rate}', 'scan rate', True)
                    pnode = child(rnode, f'point {point:02d}', 'point', False)
                    cnode = child(pnode, f'cycle {cyc:02d}', 'cycle', False)
                    add_file(cnode, p, 'CV / LSV')
                    ptop = child(cv_point_root, f'point {point:02d}', 'point', False)
                    rtop = child(ptop, f'{rate}', 'scan rate', False)
                    ctop = child(rtop, f'cycle {cyc:02d}', 'cycle', False)
                    add_file(ctop, p, 'CV / LSV')
                elif '/eis/' in s or '\\eis\\' in s:
                    m_point = re.search(r'point_(\d+)', p.as_posix(), flags=re.I)
                    point = int(m_point.group(1)) if m_point else 0
                    pnode = child(eis_root, f'point {point:02d}', 'EIS point', True)
                    add_file(pnode, p, 'EIS')
                elif '/drt/' in s or '\\drt\\' in s:
                    rel = p.relative_to(self.cache_root).parts
                    run = rel[1] if len(rel) > 2 else 'DRT'
                    rnode = child(drt_root, run, 'DRT run', False)
                    m_point = re.search(r'point_(\d+)', p.as_posix(), flags=re.I)
                    point = int(m_point.group(1)) if m_point else 0
                    pnode = child(rnode, f'point {point:02d}', 'DRT point', False)
                    add_file(pnode, p, 'DRT')
                else:
                    add_file(other_root, p, 'Numeric')
            self.log(f'Indexed {len(files)} unique H5-extracted CSV table(s); tree entries include CV grouped both by scan rate and by point.')
        except Exception as exc:
            self.log(f'Refresh tree failed: {exc}\n{traceback.format_exc()}')

    def _collect_children_paths(self, iid, out):
        p = self._path_by_iid.get(iid)
        if p is not None: out.append(p)
        for ch in self.tree.get_children(iid):
            self._collect_children_paths(ch, out)

    def selected_paths(self, plottable_only=True):
        out=[]
        for iid in self.tree.selection():
            self._collect_children_paths(iid, out)
        ded=[]; seen=set()
        for p in out:
            try:
                if plottable_only and Path(p).suffix.lower() not in {'.csv','.txt','.asc','.tsv','.xlsx','.xls'}:
                    continue
                k=str(Path(p).resolve())
                if k not in seen:
                    ded.append(Path(p)); seen.add(k)
            except Exception: pass
        return ded

    def preview_selected(self):
        paths = self.selected_paths(plottable_only=True)
        if len(paths) == 1:
            self.selected_path = paths[0]
            try:
                self.selected_df = _v138_csv_read(paths[0], max_rows=2000)
                self.log(f'Selected table: {paths[0].name} | rows={len(self.selected_df)} cols={len(self.selected_df.columns)}')
            except Exception as exc:
                self.log(f'Preview failed for {paths[0].name}: {exc}')
        elif len(paths) > 1:
            self.log(f'Selected group with {len(paths)} table(s).')

    def _ensure_plot_canvas(self):
        if self._canvas is not None:
            return True
        try:
            try:
                self.placeholder.destroy()
            except Exception: pass
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg, NavigationToolbar2Tk
            from matplotlib.figure import Figure
            self._figure = Figure(figsize=(7.6, 5.4), dpi=100)
            self._ax = self._figure.add_subplot(111)
            self._ax.grid(True, alpha=0.25)
            self._canvas = FigureCanvasTkAgg(self._figure, master=self.plot_holder)
            self._canvas.get_tk_widget().pack(fill='both', expand=True)
            self._toolbar = NavigationToolbar2Tk(self._canvas, self.plot_holder, pack_toolbar=False)
            self._toolbar.update(); self._toolbar.pack(fill='x')
            return True
        except Exception as exc:
            self.log(f'Matplotlib canvas failed: {exc}')
            messagebox.showerror('Plot canvas failed', str(exc), parent=self)
            return False

    def _plot_one(self, p, clear=False):
        if not self._ensure_plot_canvas(): return
        try:
            import pandas as _pd
            df = _v138_csv_read(p)
            xcol, ycol, detected = _v138_choose_xy(df, self.plot_mode_var.get(), p)
            if xcol is None or ycol is None:
                self.log(f'No numeric x/y pair: {p.name}')
                return
            x = _pd.to_numeric(df[xcol], errors='coerce').to_numpy(dtype=float)
            y = _pd.to_numeric(df[ycol], errors='coerce').to_numpy(dtype=float)
            mask = np.isfinite(x) & np.isfinite(y)
            x = x[mask]; y = y[mask]
            if len(x) < 2:
                self.log(f'Not enough numeric data: {p.name}')
                return
            ylabel = str(ycol)
            if detected == 'EIS Nyquist':
                # If using Zimag rather than an already positive -Zimag column, apply Nyquist convention.
                if 'neg' not in str(ycol).lower() and np.nanmedian(y) < 0:
                    y = -y; ylabel = '-' + str(ycol)
            self._ax.plot(x, y, marker='o' if len(x) <= 250 else None, markersize=3, linewidth=1.4, label=p.stem[:80])
            self._ax.set_xlabel(str(xcol)); self._ax.set_ylabel(ylabel); self._ax.set_title(self.plot_mode_var.get() + ' overlay')
            self._curves.append({'path': p, 'xcol': xcol, 'ycol': ycol, 'detected': detected})
            self.last_plot_paths.append(p)
            self.log(f'Plotted {p.name}: {detected}')
        except Exception as exc:
            self.log(f'Plot failed for {p.name}: {exc}')

    def plot_selected(self, clear=True):
        paths = self.selected_paths(plottable_only=True)
        if not paths:
            messagebox.showinfo('No table selected', 'Select one or more table files or a group in the experiment map.', parent=self)
            return
        try:
            maxn = max(1, int(float(self.max_curves_var.get())))
        except Exception:
            maxn = 24
        if clear: self.clear_plot()
        for p in paths[:maxn]:
            self._plot_one(p, clear=False)
        try:
            if self._ax is not None:
                self._ax.grid(True, alpha=0.25)
                if len(self._curves) <= 16: self._ax.legend(fontsize=7, loc='best')
                self._figure.tight_layout(); self._canvas.draw_idle()
            if len(paths) > maxn:
                self.log(f'Plotted first {maxn} of {len(paths)} selected files. Increase Max curves to show more.')
        except Exception: pass

    def clear_plot(self):
        try:
            if self._ax is not None:
                self._ax.clear(); self._ax.grid(True, alpha=0.25); self._ax.set_title('Select files/groups and click Plot/overlay selected'); self._canvas.draw_idle()
            self._curves = []; self.last_plot_paths = []
        except Exception: pass


def _v138_open_browser_from_cache(gui, cache_info, base_name=None):
    try:
        if not cache_info or not cache_info.get('cache_root'):
            raise FileNotFoundError('H5 browser cache was not prepared.')
        win = FaradaIQH5Browser(gui, cache_info=cache_info, base_name=base_name)
        try: win.lift()
        except Exception: pass
        try:
            gui.set_status(f'Data Browser opened from canonical H5 cache: {cache_info.get("n_tables", "n/a")} table(s).')
        except Exception: pass
        return win
    except Exception as exc:
        try: messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception: pass
        return None


def _v138_prepare_and_open_browser_async(gui, root=None, base_name=None, force_build=False, on_open=None):
    try:
        from queue import Empty, SimpleQueue

        if _fq127_bundle is None:
            raise RuntimeError('faradaiq_canonical_bundle.py could not be imported.')
        if root is None or base_name is None:
            root2, base2 = _v64_analysis_root_for_browser(gui)
            root = root or root2; base_name = base_name or base2
        root = Path(root).resolve()
        if not root.exists():
            messagebox.showwarning('No analysis folder found', 'Export archive + CSV first, then open Data browser + analysis.', parent=gui)
            return None
        prep = tk.Toplevel(gui)
        prep.title('Preparing FaradaIQ H5 browser')
        prep.geometry('720x220')
        frame = ttk.Frame(prep, style='Card.TFrame', padding=(12,12)); frame.pack(fill='both', expand=True, padx=8, pady=8)
        ttk.Label(frame, text='Preparing canonical H5 browser', style='Section.TLabel').pack(anchor='w')
        msg_var = tk.StringVar(value='Checking root-level H5/JSON bundle...')
        ttk.Label(frame, textvariable=msg_var, style='Card.TLabel', wraplength=680).pack(anchor='w', fill='x', pady=(8,5))
        logbox = ScrolledText(frame, height=6, wrap='word'); logbox.pack(fill='both', expand=True)
        try: logbox.configure(background='#020617', foreground='#e5eefb', insertbackground='#f8fafc', font=('Consolas', 8))
        except Exception: pass
        progress=[]; meta={}
        completed=SimpleQueue()
        try: meta = _v130_gui_metadata_snapshot(gui)
        except Exception: meta = {}
        def show(m):
            try:
                msg_var.set(str(m)); logbox.insert('end', str(m)+'\n'); logbox.see('end')
            except Exception: pass
        def pump():
            while progress:
                show(progress.pop(0))
            try:
                cache_info, err = completed.get_nowait()
            except Empty:
                prep.after(150, pump)
                return
            prep.destroy()
            if err:
                messagebox.showerror('Data browser preparation failed', err, parent=gui)
                return
            browser = _v138_open_browser_from_cache(gui, cache_info, base_name)
            if browser is not None and on_open is not None:
                on_open(browser)

        def worker():
            err=None; cache_info=None
            try:
                h5 = _fq127_bundle.find_latest_bundle(root, base_name=base_name)
                if force_build or h5 is None or not Path(h5).exists():
                    progress.append('[Bundle] Building one root-level H5 + one JSON...')
                    info = _fq127_bundle.build_canonical_bundle(root, base_name=base_name, gui_metadata=meta, progress_callback=lambda m: progress.append(m), label='v138_before_browser_open')
                    h5 = info.get('h5_path')
                progress.append(f'[Browser] Extracting/reusing H5 plotting cache: {Path(h5).name}')
                cache_info = _fq127_bundle.extract_h5_tables_for_browser(h5, prefer_reuse=True)
            except Exception as exc:
                err = f'{exc}\n\n{traceback.format_exc()}'
            completed.put((cache_info, err))
        if '_v130_threading' in globals() and _v130_threading is not None:
            _v130_threading.Thread(target=worker, daemon=True).start()
        else:
            worker()
        prep.after(0, pump)
        return prep
    except Exception as exc:
        try: messagebox.showerror('Data browser failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception: pass
        return None


