def _v138_path_is_pure_h5_cv_cache(p):
    try:
        pp = Path(p)
        s = pp.as_posix().lower()
        n = pp.name.lower()
        # The canonical H5 browser cache stores true CV cycles under CV_LSV/ with filenames CV_point_...
        # These are for PySimpleEChem, not Tafel. LSV/IV/Tafel files will keep their own names.
        return ('/cv_lsv/' in s or '\\cv_lsv\\' in s) and n.startswith('cv_point_')
    except Exception:
        return False


def _v138_selected_iv_lsv_paths(browser=None, generous=False):
    paths = []
    try:
        paths = _v130p_get_selected_view_paths(browser)
    except Exception:
        try:
            paths = browser.selected_paths(plottable_only=True)
        except Exception:
            paths = []
    out, seen = [], set()
    skip_tokens = ['eis', 'impedance', 'nyquist', 'bode', 'zreal', 'zimag', 'drt', 'ocp', 'cv_point_']
    keep_tokens = ['iv', 'tafel', 'taffit', 'linear_sweep', 'polarization', 'polarisation', 'current-voltage', 'current_voltage']
    try:
        k = str(_v83_current_plot_view_kind(browser)).lower()
    except Exception:
        k = ''
    # Do not treat a CV plot/view as Tafel-ready. LSV remains allowed.
    kind_says_iv = any(t in k for t in ['iv', 'tafel', 'lsv', 'polar']) and 'eis' not in k and 'drt' not in k
    for p in paths:
        try:
            pp = Path(p)
            s = pp.as_posix().lower()
            n = pp.name.lower()
            if _v138_path_is_pure_h5_cv_cache(pp):
                continue
            if any(t in s for t in skip_tokens):
                continue
            keep = bool(generous or kind_says_iv or any(t in s for t in keep_tokens) or any(t in n for t in ['iv', 'tafel', 'lsv', 'polar']))
            if not keep:
                # Content fallback: two numeric columns with potential/current names and filename not marked CV.
                try:
                    head = pp.read_text(encoding='utf-8', errors='ignore')[:2048].lower()
                    keep = (('potential' in head or 'voltage' in head or 'eta' in head) and ('current' in head or 'j_' in head or 'j/' in head) and 'cv_point_' not in n)
                except Exception:
                    keep = False
            if not keep:
                continue
            key = str(pp.resolve()) if pp.exists() else str(pp)
            if key not in seen:
                out.append(pp); seen.add(key)
        except Exception:
            pass
    return out

