def _v138_safe_label(text, maxlen=96):
    try:
        s = str(text or '').strip()
        s = re.sub(r'\s+', ' ', s)
        return (s[:maxlen-3] + '...') if len(s) > maxlen else s
    except Exception:
        return str(text)[:maxlen]


def _v138_browser_init_state(self):
    if not hasattr(self, 'plot_views') or self.plot_views is None:
        self.plot_views = []
    if not hasattr(self, 'current_view_index'):
        self.current_view_index = None
    if not hasattr(self, 'plot_title_var'):
        self.plot_title_var = tk.StringVar(value='FaradaIQ overlay')
    if not hasattr(self, 'x_label_var'):
        self.x_label_var = tk.StringVar(value='')
    if not hasattr(self, 'y_label_var'):
        self.y_label_var = tk.StringVar(value='')
    if not hasattr(self, 'legend_var'):
        self.legend_var = tk.StringVar(value='Auto')
    if not hasattr(self, '_v138_last_export_dir'):
        try:
            self._v138_last_export_dir = self.analyzed_root / 'displayed_plot_exports'
            self._v138_last_export_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            self._v138_last_export_dir = Path.cwd()


