def _v138_launch_deareis_gui(parent=None, cwd=None):
    try:
        app_dir = Path(__file__).resolve().parent
        py = app_dir / '.deareis_venv' / ('Scripts/python.exe' if os.name == 'nt' else 'bin/python')
        cwd = Path(cwd).resolve() if cwd else app_dir
        if py.exists():
            return _v130p_subprocess.Popen([str(py), '-m', 'deareis'], cwd=str(cwd)) if '_v130p_subprocess' in globals() and _v130p_subprocess is not None else None
        bat = app_dir / 'run_deareis_gui.bat'
        if bat.exists() and os.name == 'nt':
            return _v130p_subprocess.Popen(['cmd.exe', '/c', str(bat)], cwd=str(cwd)) if '_v130p_subprocess' in globals() and _v130p_subprocess is not None else os.startfile(str(bat))
        return _v130p_subprocess.Popen([sys.executable, '-m', 'deareis'], cwd=str(cwd)) if '_v130p_subprocess' in globals() and _v130p_subprocess is not None else None
    except Exception as exc:
        try:
            messagebox.showerror('Could not launch DearEIS', 'DearEIS may not be installed yet. Use install_deareis_optional.bat.\n\n' + str(exc), parent=parent)
        except Exception:
            pass
        return None


def _v138_write_deareis_open_bat(outdir):
    try:
        app_dir = Path(__file__).resolve().parent
        outdir = Path(outdir)
        bat = outdir / 'OPEN_IN_DEAREIS.bat'
        py = app_dir / '.deareis_venv' / 'Scripts' / 'python.exe'
        if py.exists():
            txt = f'@echo off\r\ncd /d "{outdir}"\r\n"{py}" -m deareis\r\npause\r\n'
        else:
            txt = f'@echo off\r\ncd /d "{outdir}"\r\n"{app_dir / "run_deareis_gui.bat"}"\r\npause\r\n'
        bat.write_text(txt, encoding='utf-8')
        return bat
    except Exception:
        return None


def _v138_open_deareis_with_selected(browser=None, launch=True):
    try:
        paths = _v130p_selected_eis_paths(browser) if browser is not None else []
        if not paths:
            messagebox.showinfo('No EIS data selected', 'Select an EIS/Nyquist/Bode table, EIS group, or EIS Plot/view first.', parent=browser)
            return
        import faradaiq_deareis_adapter as _fq_deareis
        root = _v130p_deareis_output_root(browser)
        label = f'{getattr(browser, "base_name", "FaradaIQ")}_selected_EIS'
        result = _fq_deareis.create_deareis_handoff(paths, root, label=label, make_project=True)
        open_bat = _v138_write_deareis_open_bat(result.output_dir)
        try:
            browser.log(f'DearEIS handoff created with {len(result.normalized_files)} normalized EIS file(s): {result.output_dir}')
            if result.project_json:
                browser.log(f'DearEIS project JSON: {result.project_json}')
            if open_bat:
                browser.log(f'DearEIS launcher BAT: {open_bat}')
        except Exception:
            pass
        try:
            if os.name == 'nt':
                os.startfile(result.output_dir)
        except Exception:
            pass
        if launch:
            _v138_launch_deareis_gui(browser, cwd=result.output_dir)
        msg = f'DearEIS handoff created for {len(result.normalized_files)} EIS file(s).\n\nFolder:\n{result.output_dir}\n\n'
        if result.project_json:
            msg += f'DearEIS project JSON:\n{result.project_json}\n\n'
        else:
            msg += 'Project JSON was not created in the FaradaIQ Python environment; normalized CSVs are ready and the DearEIS GUI opens in the handoff folder.\n\n'
        if open_bat:
            msg += f'Launcher BAT:\n{open_bat}\n\n'
        if result.warnings:
            msg += 'Warnings:\n' + '\n'.join(result.warnings[:6])
        if launch:
            msg += '\n\nDearEIS GUI launch requested from the handoff folder; use DearEIS Project/Data-set import if it does not auto-load.'
        messagebox.showinfo('DearEIS EIS handoff', msg, parent=browser)
        return result
    except Exception as exc:
        try:
            messagebox.showerror('DearEIS EIS handoff failed', str(exc), parent=browser)
        except Exception:
            pass
        try:
            browser.log(f'DearEIS EIS handoff failed: {exc}')
        except Exception:
            pass
        return None


