def _v138_browser_context_for_llm(self, user_prompt, max_files=220):
    man = self.manifest if isinstance(getattr(self, 'manifest', None), dict) else {}
    val = ((man.get('data_structure') or {}).get('validation') or {})
    files=[]
    try:
        for p in sorted(self.cache_root.rglob('*.csv'), key=lambda x: x.as_posix().lower())[:max_files]:
            files.append(str(p.relative_to(self.cache_root)).replace('\\','/'))
    except Exception:
        pass
    return {
        'request': user_prompt,
        'base_name': getattr(self, 'base_name', ''),
        'h5_path': str(getattr(self, 'h5_path', '') or ''),
        'json_path': str(getattr(self, 'json_path', '') or ''),
        'techniques_detected': man.get('techniques_detected'),
        'technique_counts': man.get('technique_counts'),
        'validation': val,
        'files_from_h5_browser_cache': files,
        'instruction': 'Return concise, actionable comparison suggestions. Prefer one suggestion per line. Include group identifiers such as point, scan rate, cycle, EIS point, DRT run when possible. Do not invent files not present in the file list.'
    }


def _v138_llm_suggestion_lines(text):
    out=[]
    for raw in str(text or '').splitlines():
        s = raw.strip().lstrip('-•0123456789. )\t').strip()
        if not s: continue
        if len(s) < 8: continue
        if s.lower().startswith(('here are','suggestions','comparison suggestions')): continue
        out.append(s[:240])
    return out[:24]


def _v138_insert_suggestions(self, suggestions, append=True, prefix='AI'):
    try:
        if not append:
            self.suggestion_list.delete(0, 'end')
        existing = set(self.suggestion_list.get(0, 'end')) if append else set()
        for s in suggestions:
            label = s if str(s).startswith(('AI/', 'Smart/', 'Local/')) else f'{prefix}: {s}'
            if label not in existing:
                self.suggestion_list.insert('end', label); existing.add(label)
    except Exception as exc:
        try: self.log(f'Could not insert suggestions: {exc}')
        except Exception: pass


def _v138_local_suggestions(self):
    man = self.manifest if isinstance(getattr(self, 'manifest', None), dict) else {}
    counts = man.get('technique_counts') or {}
    out=[]
    if counts.get('CV / LSV'):
        out += [
            'Compare the same CV cycle across points 1-8 at each scan rate.',
            'Compare 2nd CV cycle from each point for 25, 50, 75, and 100 mV/s separately.',
            'Overlay scan-rate series for each point and check current scaling with scan rate.',
        ]
    if counts.get('EIS'):
        out += [
            'Compare EIS Nyquist curves across points with same x/y scale and flag outlier points.',
            'Compare Bode magnitude and phase across all EIS points.',
        ]
    if counts.get('DRT'):
        out += ['Compare DRT gamma(tau) peak position and intensity across points using log tau axis.']
    out += ['Export the current comparison view with figure, overlay data, H5, and quick summary.']
    return out


def _v138_request_llm_suggestions(self, prompt, append=True):
    prompt = str(prompt or '').strip() or 'Suggest the most useful comparisons for this FaradaIQ electrochemistry H5/JSON dataset.'
    ctx = _v138_browser_context_for_llm(self, prompt)
    messages = [
        {'role': 'system', 'content': 'You are FaradaIQ Smart Compare. Generate file-grounded electrochemical comparison suggestions only from the provided H5/JSON dataset context.'},
        {'role': 'user', 'content': json.dumps(ctx, ensure_ascii=False, indent=2)[:24000]},
    ]
    def worker():
        try:
            if '_v37_call_best_llm' not in globals() or not callable(_v37_call_best_llm):
                raise RuntimeError('Configured LLM call helper is unavailable.')
            ok, text, meta = _v37_call_best_llm(messages, max_tokens=900, temperature=0.15)
            if not ok:
                raise RuntimeError(str(text or meta or 'LLM call failed'))
            suggestions = _v138_llm_suggestion_lines(text)
            if not suggestions:
                suggestions = _v138_local_suggestions(self)
            def done():
                _v138_insert_suggestions(self, suggestions, append=append, prefix='AI')
                try: self.log(f'Smart Compare LLM returned {len(suggestions)} suggestion(s).')
                except Exception: pass
            try: self.after(0, done)
            except Exception: done()
        except Exception as exc:
            suggestions = _v138_local_suggestions(self)
            def done_fail():
                _v138_insert_suggestions(self, suggestions, append=append, prefix='AI/local')
                try: self.log(f'LLM unavailable for Smart Compare; inserted local suggestions. Reason: {exc}')
                except Exception: pass
            try: self.after(0, done_fail)
            except Exception: done_fail()
    try:
        self.log('Sending Smart Compare request to configured LLM with H5/JSON technique map and browser file list...')
    except Exception: pass
    try:
        if '_v130_threading' in globals() and _v130_threading is not None:
            _v130_threading.Thread(target=worker, daemon=True).start()
        else:
            worker()
    except Exception:
        worker()


def _v138_suggest_comparisons(self):
    default_prompt = 'Suggest useful CV, EIS, DRT, and IV/LSV comparisons for this FaradaIQ H5 dataset. Emphasize point-to-point, scan-rate, cycle, Nyquist/Bode, and DRT peak comparisons.'
    _v138_request_llm_suggestions(self, default_prompt, append=False)


def _v138_ask_ai_comparisons(self):
    prompt = ''
    try: prompt = (self.ai_compare_entry.get() or '').strip()
    except Exception: pass
    if not prompt:
        prompt = 'Suggest useful comparisons for the selected FaradaIQ data.'
    _v138_request_llm_suggestions(self, prompt, append=True)


