def _v138_browser_build_visible_ui(self):
    try: _v36_apply_theme(self, getattr(self.gui, '_faradaiq_theme_mode', 'dark'))
    except Exception: pass
    _v138_browser_init_state(self)
    outer = ttk.Frame(self, style='Card.TFrame', padding=(8, 6)); outer.pack(fill='both', expand=True)
