    self.summary_var = tk.StringVar(value=f'H5 source: {self.h5_path.name if self.h5_path else self.cache_root}')
    ttk.Label(top, textvariable=self.summary_var, style='Muted.TLabel').pack(side='left', fill='x', expand=True)
