    ttk.Button(top, text='Close', command=self.destroy).pack(side='right', padx=3)

    pan = ttk.Panedwindow(outer, orient='horizontal'); pan.pack(fill='both', expand=True)
    left = ttk.Frame(pan, style='Card.TFrame', padding=(6,6)); pan.add(left, weight=3)
    center = ttk.Frame(pan, style='Card.TFrame', padding=(6,6)); pan.add(center, weight=5)
    right = ttk.Frame(pan, style='Card.TFrame', padding=(6,6)); pan.add(right, weight=3)

