# ---- FaradaIQ Studio v273: Windows long-path pySECCM CV parser skip + native H5 fallback ----
# Some generated HEKA CV-only paths exceed the classic Windows/cmd.exe path limit.
# In those cases cmd.exe reports "The current directory is invalid" before parse_CV.py
# even starts.  The canonical H5 bundle now splits combined CV ASC files itself, so
# replace only the risky pySECCM parse_CV command with a harmless status command.
try:
    _V138_PREV_V118_DEDUPE_COMMANDS = _v118_dedupe_commands
except Exception:
    _V138_PREV_V118_DEDUPE_COMMANDS = None


def _v138_is_risky_windows_cv_command(cmd):
    try:
        args, cwd = cmd[:2]
        script = _v118_script_name(args) if '_v118_script_name' in globals() else ''
        if script != 'parse_cv.py':
            return False, ''
        cwd_s = str(cwd or '')
        input_s = ''
        try:
            if len(args) >= 3:
                input_s = str(_v118_resolve_command_arg(args[2], cwd)) if '_v118_resolve_command_arg' in globals() else str(args[2])
        except Exception:
            input_s = str(args[2]) if len(args) >= 3 else ''
        # cmd.exe cannot cd into these very long generated folders; output Groups paths
        # are even longer. Native H5 split is safer and avoids a false parser failure.
        max_len = max(len(cwd_s), len(input_s))
        if max_len >= 235 or len(cwd_s) >= 220:
            return True, f'cwd length={len(cwd_s)}, input length={len(input_s)}'
    except Exception as exc:
        return False, str(exc)
    return False, ''


def _v118_dedupe_commands(commands, notes=None):
    notes = notes if isinstance(notes, list) else []
    if callable(_V138_PREV_V118_DEDUPE_COMMANDS):
        out, skipped, notes = _V138_PREV_V118_DEDUPE_COMMANDS(commands, notes)
    else:
        out, skipped, notes = commands or [], [], notes
    patched=[]; n_long=0
    for cmd in out:
        risky, why = _v138_is_risky_windows_cv_command(cmd)
        if risky:
            n_long += 1
            try:
                args, cwd = cmd[:2]
                py = str(args[0]) if args else _v112_sys.executable
                input_name = str(args[2]) if len(args) >= 3 else 'CV file'
            except Exception:
                py = _v112_sys.executable; input_name = 'CV file'
            msg = (
                'FaradaIQ v273 skipped pySECCM parse_CV for a very long Windows path. '
                'The canonical H5 builder will split this combined CV ASC file natively. '
                f'File: {input_name}. Reason: {why}'
            )
            code = "print(" + repr(msg) + ")"
            patched.append(([py, '-c', code], _v112_app_dir()))
        else:
            patched.append(cmd)
    if n_long:
        notes.append(f'v138 replaced {n_long} long-path parse_CV commands with native-H5-split status commands to avoid cmd.exe "current directory is invalid" failures.')
    return patched, skipped, notes


