# ---- FaradaIQ Studio v273 final: short-name pySECCM staging instead of long-path skip ----
# If a pySECCM parse_CV command would fail on Windows because the generated path is too
# long, do not skip it.  Run parse_CV.py from a short temporary staging folder using a
# suggested short filename alias, then copy the parser Groups/Figures back to the original
# unchanged export folder.
try:
    _V138_SHORTPATH_BASE_DEDUPE_COMMANDS = _V138_PREV_V118_DEDUPE_COMMANDS
except Exception:
    _V138_SHORTPATH_BASE_DEDUPE_COMMANDS = None


def _v138_short_alias_for_cv_arg(arg):
    try:
        name = _V118Path(str(arg)).name if '_V118Path' in globals() else Path(str(arg)).name
        import re as _re, hashlib as _hashlib
        rate = None; cycles = None
        m = _re.search(r'CV\s*([0-9]+(?:\.[0-9]+)?)\s*mVperS', name, flags=_re.I)
        if not m:
            m = _re.search(r'([0-9]+(?:\.[0-9]+)?)\s*mV\s*per\s*s', name, flags=_re.I)
        if m:
            rate = m.group(1).replace('.', 'p')
        m = _re.search(r'([0-9]+)\s*cycles?', name, flags=_re.I)
        if m:
            cycles = m.group(1)
        h = _hashlib.sha1(name.encode('utf-8', errors='ignore')).hexdigest()[:6]
        ext = _V118Path(str(arg)).suffix if '_V118Path' in globals() else Path(str(arg)).suffix
        parts = ['CV']
        if rate: parts.append(f'{rate}mVs')
        if cycles: parts.append(f'{cycles}cy')
        parts.append(h)
        return '_'.join(parts) + (ext or '.asc')
    except Exception:
        return 'CV_short.asc'


def _v138_shortpath_patch_command(cmd):
    risky, why = _v138_is_risky_windows_cv_command(cmd) if '_v138_is_risky_windows_cv_command' in globals() else (False, '')
    if not risky:
        return cmd, None
    try:
        args, cwd = cmd[:2]
        py = str(args[0]) if args else _v112_sys.executable
        script = str(args[1]) if len(args) >= 2 else str(_v112_app_dir() / 'pyseccm_tools' / 'parse_CV.py')
        src = str(_v118_resolve_command_arg(args[2], cwd)) if '_v118_resolve_command_arg' in globals() and len(args) >= 3 else str(args[2])
        short_name = _v138_short_alias_for_cv_arg(args[2] if len(args) >= 3 else src)
        runner = str(_v112_app_dir() / 'faradaiq_pyseccm_shortpath_runner.py') if '_v112_app_dir' in globals() else 'faradaiq_pyseccm_shortpath_runner.py'
        new_args = [
            py, runner,
            '--script', script,
            '--input', src,
            '--original-cwd', str(cwd),
            '--short-name', short_name,
            '--reason', why or 'long Windows parser path',
        ]
        if any(str(a).lower() == '--plot' for a in list(args)[3:]):
            new_args.append('--plot')
        note = f'FaradaIQ v273 short-name staging will run parse_CV.py for long path using alias {short_name} (reason: {why}).'
        return (new_args, _v112_app_dir()), note
    except Exception as exc:
        return cmd, f'FaradaIQ v273 short-name staging could not patch one command: {exc}'


def _v118_dedupe_commands(commands, notes=None):
    notes = notes if isinstance(notes, list) else []
    if callable(_V138_SHORTPATH_BASE_DEDUPE_COMMANDS):
        out, skipped, notes = _V138_SHORTPATH_BASE_DEDUPE_COMMANDS(commands, notes)
    else:
        out, skipped = list(commands or []), []
    patched=[]; n_patched=0
    for cmd in out:
        new_cmd, note = _v138_shortpath_patch_command(cmd)
        if note:
            notes.append(note); n_patched += 1
        patched.append(new_cmd)
    if n_patched:
        notes.append(f'FaradaIQ v273 used short-name staging for {n_patched} long-path parse_CV commands; original folders were not renamed.')
    return patched, skipped, notes

