def _v138_edison_prompt_from_canonical_json(h5, json_path, max_chars=120000):
    import json as _json
    from pathlib import Path as _Path
    manifest = {}
    if json_path and _Path(json_path).exists():
        try:
            manifest = _json.loads(_Path(json_path).read_text(encoding='utf-8', errors='replace'))
        except Exception:
            manifest = {}
    slim = {
        'instruction': 'Analyze this FaradaIQ canonical electrochemistry bundle. Use the H5 numeric tables and JSON manifest only. Separate observations from interpretations. Do not invent values or citations.',
        'bundle_policy': 'one canonical H5 plus one canonical JSON',
        'h5_file': _Path(h5).name if h5 else '',
        'json_file': _Path(json_path).name if json_path else '',
        'base_name': manifest.get('base_name'),
        'sample_name': manifest.get('sample_name'),
        'techniques_detected': manifest.get('techniques_detected'),
        'technique_counts': manifest.get('technique_counts'),
        'h5_counts': manifest.get('h5_counts'),
        'source_policy': manifest.get('source_policy'),
        'data_structure': manifest.get('data_structure'),
        'experiment_structure_from_dat': manifest.get('experiment_structure_from_dat'),
        'gui_metadata': manifest.get('gui_metadata'),
    }
    txt = 'FaradaIQ Edison Scientific analysis request\n\n' + _json.dumps(slim, ensure_ascii=False, indent=2)
    if len(txt) > max_chars:
        txt = txt[:max_chars] + '\n...[truncated by FaradaIQ before Edison submission]...'
    return txt


def _v56_send_built_ai_bundle_to_edison_cli(path, base_name=None):
    import json as _json, zipfile as _zipfile, os as _os
    from pathlib import Path as _Path
    from datetime import datetime as _datetime
    h5, json_path = _v138_h5_json_pair_for_root(path, base_name=base_name)
    if h5 is None:
        if callable(_V138_PREV_EDISON_CLI):
            return _V138_PREV_EDISON_CLI(path, base_name=base_name)
        raise FileNotFoundError('No canonical H5/JSON bundle found for Edison handoff.')
    analysis_root = _Path(h5).parent
    safe = _v35_safe_name(base_name or _Path(h5).stem.replace('_faradaiq_bundle',''))
    run_id = _datetime.now().strftime('%Y%m%d_%H%M%S')
    forced_response_dir = _v138_env_first(['FARADAIQ_EDISON_RESPONSE_DIR'], '')
    handoff_dir = _Path(forced_response_dir).resolve() if forced_response_dir else (analysis_root / f'{safe}_EdisonScientific_handoff' / f'edison_send_built_{run_id}')
    handoff_dir.mkdir(parents=True, exist_ok=True)
    metadata = {
        'created': _datetime.now().isoformat(timespec='seconds'),
        'app': 'FaradaIQ Studio',
        'version': "v273",
        'operation': 'send_canonical_h5_json_bundle_to_edison',
        'base_name': base_name or safe,
        'analysis_root': str(analysis_root),
        'h5_path': str(h5),
        'json_path': str(json_path or ''),
        'bundle_policy': 'one canonical H5 plus one canonical JSON only',
        'send_modes': ['official_edison_client', 'custom_upload_url', 'local_handoff_zip'],
    }
    metadata_path = handoff_dir / 'edison_send_metadata.json'
    metadata_path.write_text(_json.dumps(metadata, ensure_ascii=False, indent=2), encoding='utf-8')
    prompt_path = handoff_dir / 'AI_analysis_prompt_for_current_bundle.txt'
    prompt_path.write_text(_v138_edison_prompt_from_canonical_json(h5, json_path), encoding='utf-8')
    summary_path = handoff_dir / f'{safe}_AI_analysis_summary.json'
    summary = {
        'base_name': metadata.get('base_name'),
        'h5_path': str(h5),
        'json_path': str(json_path or ''),
        'bundle_policy': metadata.get('bundle_policy'),
    }
    try:
        if json_path and _Path(json_path).exists():
            manifest = _json.loads(_Path(json_path).read_text(encoding='utf-8', errors='replace'))
            summary.update({
                'techniques_detected': manifest.get('techniques_detected'),
                'technique_counts': manifest.get('technique_counts'),
                'h5_counts': manifest.get('h5_counts'),
                'source_policy': manifest.get('source_policy'),
            })
    except Exception:
        pass
    summary_path.write_text(_json.dumps(summary, ensure_ascii=False, indent=2), encoding='utf-8')
    zip_path = handoff_dir / f'{safe}_FaradaIQ_H5_JSON_for_Edison_{run_id}.zip'
    with _zipfile.ZipFile(zip_path, 'w', compression=_zipfile.ZIP_DEFLATED) as z:
        z.write(h5, _Path('FaradaIQ_bundle') / _Path(h5).name)
        if json_path is not None:
            z.write(json_path, _Path('FaradaIQ_bundle') / _Path(json_path).name)
        z.write(metadata_path, 'edison_send_metadata.json')
        z.write(prompt_path, 'AI_analysis_prompt_for_current_bundle.txt')
        z.write(summary_path, f'{safe}_AI_analysis_summary.json')
    api_key = _v138_env_first(['EDISON_PLATFORM_API_KEY', 'EDISON_API_KEY', 'EDISON_SCIENTIFIC_API_KEY'], '')
    upload_url = _v138_env_first(['EDISON_UPLOAD_URL', 'EDISON_SCIENTIFIC_UPLOAD_URL'], '')
    mode = str(_v138_env_first(['EDISON_SEND_MODE'], 'official_client') or 'official_client').lower()
    result = {
        'uploaded': False,
        'status': 'local_handoff_zip_created_from_canonical_h5_json',
        'mode_requested': mode,
        'zip_path': str(zip_path),
        'handoff_dir': str(handoff_dir),
        'h5_path': str(h5),
        'json_path': str(json_path or ''),
        'edison_api_key_present': bool(api_key),
        'edison_upload_url_present': bool(upload_url),
        'message': 'Created Edison handoff ZIP containing the canonical FaradaIQ H5 and JSON plus prompt/metadata.',
    }
    try:
        print('='*72, flush=True)
        print('FaradaIQ v273 → Edison Scientific canonical H5/JSON handoff', flush=True)
        print(f'H5:       {h5}', flush=True)
        print(f'JSON:     {json_path}', flush=True)
        print(f'ZIP:      {zip_path}', flush=True)
        print(f'Mode:     {mode}', flush=True)
        print(f'API key:  {"present" if api_key else "missing"}', flush=True)
        print(f'Upload URL fallback: {"present" if upload_url else "missing"}', flush=True)
    except Exception:
        pass
    response_path = handoff_dir / 'edison_send_response.json'
    try:
        if mode != 'custom_upload_url' and api_key:
            official = _v58_run_official_edison_analysis(zip_path, handoff_dir, metadata, api_key)
            result.update(official)
            result['uploaded'] = True
            result['status'] = 'completed_official_edison_client'
        elif upload_url and api_key:
            legacy = _v37_multipart_upload(
                upload_url,
                api_key,
                fields={'app': 'FaradaIQ Studio', 'version': "v273", 'metadata': _json.dumps(metadata)},
                files={'file': zip_path},
                timeout=1200,
            )
            result.update({'uploaded': True, 'status': 'uploaded_custom_url', 'edison_response': legacy})
        else:
            result['missing'] = [name for name, val in [('EDISON_PLATFORM_API_KEY/EDISON_API_KEY', api_key), ('EDISON_UPLOAD_URL', upload_url)] if not val]
            result['status'] = 'local_handoff_only_missing_edison_credentials'
            result['message'] = 'Direct Edison send was not attempted because credentials/endpoint are missing. Local Edison ZIP is ready for manual upload.'
    except Exception as exc:
        result['uploaded'] = False
        result['status'] = 'edison_send_failed_local_zip_preserved'
        result['error'] = str(exc)
        try:
            import traceback as _traceback
            result['traceback'] = _traceback.format_exc()
        except Exception:
            pass
    response_path.write_text(_json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
    try:
        answer = result.get('answer') or result.get('message') or result.get('error') or ''
        (handoff_dir / 'edison_answer.txt').write_text(str(answer), encoding='utf-8')
    except Exception:
        pass
    try:
        print('FaradaIQ Edison handoff result:', result.get('status'), flush=True)
        print('Response saved:', response_path, flush=True)
    except Exception:
        pass
    return result

