# ---- FaradaIQ Studio v273: ZIP vendor loading and technique compatibility patch ----
# Adds VersaStudio .par/.par.psbd support directly from ZIP archives and avoids
# showing empty technique sections downstream by preserving only successfully
# loaded entries.
APP_TITLE = "FaradaIQ Studio v273"
try:
    import tempfile as _v177_tempfile
    import hashlib as _v177_hashlib
except Exception:
    _v177_tempfile = None
    _v177_hashlib = None

_v177_PREV_COLLECTION_LOAD_ZIP = getattr(PSSessionCollection, "_load_zip", None)

def _pss_collection_v177_load_zip(self, zip_path: str):
    with zipfile.ZipFile(zip_path, "r") as zf:
        names = sorted([n for n in zf.namelist() if n.lower().endswith((".pssession", ".dat", ".cor", ".z", ".mpr", ".mps", ".mgr", ".par"))])
        if not names:
            raise RuntimeError("ZIP loading supports PalmSens .pssession, VersaStudio .par/.par.psbd, bundled HEKA DAT2 .dat, Solartron .cor/.z, and BioLogic .mpr/.mps/.mgr entries.")
        selected = []
        seen_bio = set()
        seen_versa = set()
        for n in names:
            low = n.lower()
            if low.endswith(('.mpr', '.mps', '.mgr')):
                key = (str(PurePosixPath(n).parent), BioLogicParser._norm_key(PurePosixPath(n).name))
                if key in seen_bio:
                    continue
                seen_bio.add(key)
                group = BioLogicParser._pair_from_zip(zf, n)
                chosen = group.get('mpr') or group.get('mps') or group.get('mgr')
                if chosen:
                    selected.append(chosen)
            elif low.endswith('.par'):
                pp = PurePosixPath(n)
                psbd = str(pp) + '.psbd'
                if psbd not in zf.namelist():
                    # Some ZIP tools use case changes; do a slower case-insensitive match.
                    psbd = next((x for x in zf.namelist() if x.lower() == (str(pp) + '.psbd').lower()), None)
                if not psbd:
                    continue
                key = str(pp).lower()
                if key in seen_versa:
                    continue
                seen_versa.add(key)
                selected.append(n)
            else:
                selected.append(n)
        display_names = self._drop_common_root(selected)
        for raw_name, disp_name in zip(selected, display_names):
            low = raw_name.lower()
            try:
                if low.endswith('.dat'):
                    data = zf.read(raw_name)
                    if data[:4] == b'DAT2':
                        parser = HEKAPotmasterParser(); parser.load_from_bytes(data, f"{zip_path}::{raw_name}")
                    else:
                        continue
                elif low.endswith('.pssession'):
                    parser = PSSessionParser(); parser.load_from_bytes(zf.read(raw_name), f"{zip_path}::{raw_name}")
                elif low.endswith('.par'):
                    if _v177_tempfile is None:
                        raise RuntimeError('tempfile module unavailable for ZIP-contained VersaStudio file extraction')
                    tmp_root = Path(_v177_tempfile.mkdtemp(prefix='faradaiq_versa_zip_'))
                    if not hasattr(self, '_v177_temp_dirs'):
                        self._v177_temp_dirs = []
                    self._v177_temp_dirs.append(str(tmp_root))
                    pp = PurePosixPath(raw_name)
                    psbd_name = str(pp) + '.psbd'
                    if psbd_name not in zf.namelist():
                        psbd_name = next((x for x in zf.namelist() if x.lower() == (str(pp) + '.psbd').lower()), None)
                    if not psbd_name:
                        continue
                    digest = (_v177_hashlib.md5(raw_name.encode('utf-8')).hexdigest()[:8] if _v177_hashlib else str(len(self.entries)+1))
                    safe_stem = PSSessionParser._sanitize_filename(pp.stem)[:80] + '_' + digest
                    par_path = tmp_root / (safe_stem + '.par')
                    psbd_path = tmp_root / (safe_stem + '.par.psbd')
                    par_path.write_bytes(zf.read(raw_name)); psbd_path.write_bytes(zf.read(psbd_name))
                    parser = VersaStudioParser(); parser.load(str(par_path))
                    parser.source_path = f"{zip_path}::{raw_name}"
                    parser.psbd_path = f"{zip_path}::{psbd_name}"
                elif low.endswith(('.cor', '.z')):
                    parser = SolartronParser(); parser.load_from_bytes(zf.read(raw_name), f"{zip_path}::{raw_name}")
                else:
                    parser = BioLogicParser(); parser.load_from_zip(zf, raw_name, zip_path)
            except Exception as exc:
                # Keep loading the rest of a large mixed ZIP; skipped entries are recorded.
                if not hasattr(self, '_v177_zip_skipped'):
                    self._v177_zip_skipped = []
                self._v177_zip_skipped.append({'entry': raw_name, 'error': str(exc)})
                continue
            self.entries.append({"entry_name": disp_name, "virtual_source": f"{zip_path}::{raw_name}", "parser": parser})

PSSessionCollection._load_zip = _pss_collection_v177_load_zip
# ---- End v198 ZIP vendor loading patch ----


