# ---- FaradaIQ Studio v273 Smart Compare legend patch ----
# User-reported issue: Smart Compare correctly resolved and plotted 40 curves,
# but no legend appeared because the H5 browser kept the older Auto rule
# "only show legend when <=16 curves". For Smart Compare comparisons, the
# legend is scientifically important, so v198 forces a compact, readable
# legend and relabels curves using point/scan-rate/cycle metadata rather than
# long filenames.
try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v177_int_from_match(pattern, text, default=None):
    try:
        m = re.search(pattern, str(text or ''), flags=re.I)
        if m:
            return int(m.group(1))
    except Exception:
        pass
    return default


def _v177_rate_from_text(text):
    try:
        s = str(text or '')
        m = re.search(r'scanrate[_\-\s]*([0-9]+(?:\.[0-9]+)?\s*mV\s*/?\s*s|[0-9]+(?:\.[0-9]+)?\s*mVs|unknown)', s, flags=re.I)
        if m:
            val = m.group(1).replace(' ', '').replace('/s', 's')
            return val
        m = re.search(r'([0-9]+(?:\.[0-9]+)?)\s*mV\s*/?\s*s', s, flags=re.I)
        if m:
            return f'{m.group(1)}mVs'
    except Exception:
        pass
    return None


def _v177_curve_label_from_path(path, all_paths=None):
    """Return short, informative labels for legends from canonical H5 cache filenames."""
    try:
        p = Path(path)
        s = p.as_posix()
        name = p.stem
        point = _v177_int_from_match(r'point[_\-]?(\d+)', s, None)
        cycle = _v177_int_from_match(r'cycle[_\-]?(\d+)', s, None)
        rate = _v177_rate_from_text(s)
        # Decide whether some fields are constant over the current comparison.
        same_rate = same_cycle = same_point = False
        try:
            paths = [Path(q).as_posix() for q in (all_paths or [])]
            rates = {_v177_rate_from_text(q) for q in paths if _v177_rate_from_text(q)}
            cycles = {_v177_int_from_match(r'cycle[_\-]?(\d+)', q, None) for q in paths}
            points = {_v177_int_from_match(r'point[_\-]?(\d+)', q, None) for q in paths}
            cycles.discard(None); points.discard(None)
            same_rate = len(rates) == 1
            same_cycle = len(cycles) == 1
            same_point = len(points) == 1
        except Exception:
            pass
        parts = []
        if point is not None and not same_point:
            parts.append(f'P{point:02d}')
        elif point is not None and same_point:
            parts.append(f'P{point:02d}')
        if rate and not same_rate:
            parts.append(str(rate))
        if cycle is not None and not same_cycle:
            parts.append(f'C{cycle:02d}')
        elif cycle is not None and same_cycle and len(parts) == 0:
            parts.append(f'C{cycle:02d}')
        if parts:
            return ' '.join(parts)
        # EIS/DRT fallback.
        if point is not None:
            return f'P{point:02d}'
        return _v138_safe_label(name, 40) if '_v138_safe_label' in globals() else name[:40]
    except Exception:
        try: return Path(path).stem[:40]
        except Exception: return 'curve'


def _v177_relabel_axes_curves(browser, paths=None):
    try:
        ax = getattr(browser, '_ax', None)
        if ax is None:
            return []
        paths = list(paths or getattr(browser, 'last_plot_paths', []) or [])
        lines = list(ax.get_lines())
        if not lines or not paths:
            return []
        # Relabel the last N lines, which correspond to the just-plotted paths.
        n = min(len(lines), len(paths))
        labels = []
        for line, p in zip(lines[-n:], paths[-n:]):
            lab = _v177_curve_label_from_path(p, paths)
            line.set_label(lab)
            labels.append(lab)
        return labels
    except Exception:
        return []


def _v177_apply_compact_legend(browser, paths=None, force=False):
    try:
        ax = getattr(browser, '_ax', None)
        fig = getattr(browser, '_figure', None)
        canvas = getattr(browser, '_canvas', None)
        if ax is None or fig is None:
            return
        labels = _v177_relabel_axes_curves(browser, paths=paths)
        lines = list(ax.get_lines())
        n = len(lines)
        if n <= 0:
            return
        legend_mode = 'Auto'
        try:
            legend_mode = browser.legend_var.get()
        except Exception:
            pass
        if legend_mode == 'Off' and not force:
            return
        try:
            old = ax.get_legend()
            if old is not None:
                old.remove()
        except Exception:
            pass
        # Smart Compare needs legends even for 40 curves. Use compact labels and
        # place the legend outside the axes so it does not cover the curves.
        if n <= 12:
            ax.legend(fontsize=7, loc='best', frameon=True)
            fig.tight_layout()
        elif n <= 60:
            ncol = 1 if n <= 30 else 2
            ax.legend(fontsize=6, loc='center left', bbox_to_anchor=(1.01, 0.5), ncol=ncol,
                      frameon=True, title='Curves')
            try:
                fig.tight_layout(rect=[0.0, 0.0, 0.78 if ncol == 1 else 0.70, 1.0])
            except Exception:
                fig.tight_layout()
        else:
            ncol = 3
            ax.legend(fontsize=5.5, loc='center left', bbox_to_anchor=(1.01, 0.5), ncol=ncol,
                      frameon=True, title=f'{n} curves')
            try:
                fig.tight_layout(rect=[0.0, 0.0, 0.64, 1.0])
            except Exception:
                fig.tight_layout()
        if canvas is not None:
            canvas.draw_idle()
        try:
            if labels:
                browser.log(f'Applied compact legend with {n} curve label(s).')
        except Exception:
            pass
    except Exception as exc:
        try: browser.log(f'Could not apply compact legend: {exc}')
        except Exception: pass


