def _v177_apply_selected_suggestion_with_legend(self):
    """Use the v145 JSON-resolved plot recipe, then force a compact legend."""
    paths = []
    try:
        sel = list(self.suggestion_list.curselection()) if hasattr(self, 'suggestion_list') else []
        if sel:
            idx = sel[0]
            if hasattr(self, '_smart_compare_recipes') and 0 <= idx < len(self._smart_compare_recipes):
                recipe = self._smart_compare_recipes[idx]
                paths = [Path(p) for p in recipe.get('resolved_paths') or [] if Path(p).is_file()]
    except Exception:
        paths = []
    if callable(_v177_PREV_APPLY_SELECTED_SUGGESTION):
        result = _v177_PREV_APPLY_SELECTED_SUGGESTION(self)
    else:
        result = None
    try:
        if not paths:
            paths = list(getattr(self, 'last_plot_paths', []) or [])
        # Force legend for Smart Compare, even when Auto mode would normally hide it.
        _v177_apply_compact_legend(self, paths=paths, force=True)
        try:
            if '_v145_set_smart_status' in globals():
                _v145_set_smart_status(self, f'Applied Smart Compare and displayed compact legend for {len(paths)} curve(s).', True)
        except Exception:
            pass
    except Exception:
        pass
    return result


