# ---- FaradaIQ Studio v273 responsive export patch ----
# Long HEKA exports, canonical H5 builds, and parser-staging can take enough time that
# running the complete export chain on Tk's event loop makes Windows show "Not Responding".
# v198 runs the existing export chain on a worker thread while all user-visible progress is
# sent to a Tk queue that is drained from the main thread. The main GUI remains movable and
# mostly interactive while export continues.

try:
    import threading as _v177_threading
    import queue as _v177_queue
except Exception:
    _v177_threading = None
    _v177_queue = None

class _v177StaticVar:
    def __init__(self, value=None):
        self._value = value
    def get(self):
        return self._value
    def set(self, value):
        self._value = value

class _v177StaticText:
    def __init__(self, value=''):
        self._value = value
    def get(self, *args, **kwargs):
        return self._value
    def delete(self, *args, **kwargs):
        self._value = ''
    def insert(self, *args, **kwargs):
        try:
            self._value += str(args[-1])
        except Exception:
            pass
    def see(self, *args, **kwargs):
        pass


def _v177_make_export_progress_window(gui, title='FaradaIQ export running in background'):
    """Create a non-modal progress window that does not block the main GUI."""
    try:
        win = tk.Toplevel(gui)
        win.title(title)
        win.geometry('900x520')
        try:
            p = _v36_theme_palette(getattr(gui, '_faradaiq_theme_mode', 'dark'))
            win.configure(bg=p.get('bg', '#0f172a'))
        except Exception:
            pass
        frame = ttk.Frame(win, style='Card.TFrame', padding=(10, 10))
        frame.pack(fill='both', expand=True, padx=10, pady=10)
        ttk.Label(frame, text=title, style='Section.TLabel').pack(anchor='w')
        ttk.Label(
            frame,
            text='Export/bundle work is running on a background worker. You can move/use the main FaradaIQ window while progress streams here.',
            style='Muted.TLabel'
        ).pack(anchor='w', pady=(2, 6))
        txt = ScrolledText(frame, wrap='word', height=22)
        txt.pack(fill='both', expand=True)
        try:
            txt.configure(background='#020617', foreground='#e5eefb', insertbackground='#f8fafc')
        except Exception:
            pass
        bar = ttk.Progressbar(frame, mode='indeterminate')
        bar.pack(fill='x', pady=(8, 6))
        try: bar.start(12)
        except Exception: pass
        row = ttk.Frame(frame, style='Card.TFrame')
        row.pack(fill='x')
        status_var = tk.StringVar(value='Starting export worker...')
        ttk.Label(row, textvariable=status_var, style='Muted.TLabel').pack(side='left', fill='x', expand=True)
        def open_tracking():
            try:
                folder = getattr(gui, '_faradaiq_launch_session_dir', None) or getattr(gui, '_faradaiq_tracking_dir', None)
                if folder and Path(folder).exists():
                    os.startfile(str(folder))
            except Exception:
                pass
        ttk.Button(row, text='Open tracking folder', command=open_tracking).pack(side='right', padx=(4, 0))
        close_btn = ttk.Button(row, text='Close', command=win.destroy)
        close_btn.pack(side='right', padx=(4, 0))
        def append_line(msg):
            try:
                timestamp = datetime.now().strftime('%H:%M:%S')
                txt.configure(state='normal')
                txt.insert('end', f'[{timestamp}] {msg}\n')
                txt.see('end')
                txt.configure(state='disabled')
                status_var.set(str(msg)[:220])
            except Exception:
                pass
        append_line('[FaradaIQ v273] Background export progress window is ready.')
        return win, append_line, status_var, bar
    except Exception:
        return None, (lambda msg: None), None, None


def _v177_snapshot_export_state(gui):
    """Capture Tk values on the main thread before the worker starts."""
    state = {}
    def g(name, default=''):
        try:
            obj = getattr(gui, name, None)
            return obj.get() if obj is not None and hasattr(obj, 'get') else default
        except Exception:
            return default
    for name in [
        'file_var', 'output_dir_var', 'auto_run_pyseccm_after_export_var',
        'send_ai_bundle_to_edison_after_parse_var', 'save_raw_json_var',
        'append_parsed_structure_var'
    ]:
        state[name] = g(name, '')
    try:
        state['desc_text'] = gui.desc_text.get('1.0', 'end') if hasattr(gui, 'desc_text') else ''
    except Exception:
        state['desc_text'] = ''
    return state

try:
    _v177_PREV_EXPORT_OUTPUTS_RESPONSIVE = SessionReaderGUI.export_outputs
except Exception:
    _v177_PREV_EXPORT_OUTPUTS_RESPONSIVE = None


def _session_reader_gui_v177_export_outputs_responsive(self):
    """Run the existing export chain on a worker so the Tk UI no longer freezes."""
    if _v177_threading is None or _v177_queue is None or not callable(_v177_PREV_EXPORT_OUTPUTS_RESPONSIVE):
        return _v177_PREV_EXPORT_OUTPUTS_RESPONSIVE(self) if callable(_v177_PREV_EXPORT_OUTPUTS_RESPONSIVE) else None
    try:
        th = getattr(self, '_v177_export_thread', None)
        if th is not None and th.is_alive():
            try: messagebox.showinfo('Export already running', 'FaradaIQ export is already running in the background. Watch the progress window.', parent=self)
            except Exception: pass
            return None
    except Exception:
        pass

    state = _v177_snapshot_export_state(self)
    q = _v177_queue.Queue()
    win, append_line, status_var, bar = _v177_make_export_progress_window(self, 'FaradaIQ v273 background export / bundle progress')
    done = {'value': False, 'ok': False, 'error': None}

    def qlog(msg):
        try: q.put(('log', str(msg)))
        except Exception: pass
    def qstatus(msg):
        try: q.put(('status', str(msg)))
        except Exception: pass

    def drain_queue():
        try:
            while True:
                kind, payload = q.get_nowait()
                if kind == 'log':
                    append_line(payload)
                elif kind == 'status':
                    append_line('[status] ' + payload)
                    try: self.status_var.set(payload[:220])
                    except Exception: pass
                elif kind == 'done':
                    done['value'] = True; done['ok'] = bool(payload)
                elif kind == 'error':
                    done['value'] = True; done['ok'] = False; done['error'] = payload
                    append_line('[ERROR] ' + str(payload)[:4000])
        except Exception:
            pass
        if done['value']:
            try:
                if bar: bar.stop()
            except Exception: pass
            try:
                if done['ok']:
                    self.status_var.set('Export finished in background. Canonical H5/JSON bundle should be ready.')
                    if status_var: status_var.set('Export finished successfully.')
                    append_line('[complete] Export worker finished successfully.')
                else:
                    self.status_var.set('Export failed in background. See progress window.')
                    if status_var: status_var.set('Export failed. See log above.')
            except Exception:
                pass
            return
        try:
            self.after(150, drain_queue)
        except Exception:
            pass

    def worker():
        global _FARADAIQ_AI_PROGRESS_CALLBACK
        # Save objects/functions touched by legacy export so they can be restored.
        saved = {}
        for name in ['file_var','output_dir_var','auto_run_pyseccm_after_export_var','send_ai_bundle_to_edison_after_parse_var','save_raw_json_var','append_parsed_structure_var','desc_text','set_status','update','update_idletasks']:
            try: saved[name] = getattr(self, name)
            except Exception: pass
        saved_globals = {}
        for name in ['_v63_analysis_progress_window','_v41_analysis_progress_window','_FARADAIQ_AI_PROGRESS_CALLBACK']:
            try: saved_globals[name] = globals().get(name)
            except Exception: pass
        saved_msg = (messagebox.showinfo, messagebox.showwarning, messagebox.showerror)
        try:
            # Replace Tk variables/widgets with plain proxies for the worker. This prevents
            # most cross-thread Tk calls while preserving the legacy export code path.
            for name, val in state.items():
                if name == 'desc_text':
                    continue
                if hasattr(self, name):
                    setattr(self, name, _v177StaticVar(val))
            if hasattr(self, 'desc_text'):
                self.desc_text = _v177StaticText(state.get('desc_text', ''))
            def worker_status(msg):
                qstatus(msg)
            self.set_status = worker_status
            self.update = lambda *a, **k: None
            self.update_idletasks = lambda *a, **k: None
            def progress_window_proxy(gui, title='FaradaIQ progress'):
                qlog(f'[{title}] progress redirected to the FaradaIQ v273 background progress window.')
                return None, qlog
            globals()['_v63_analysis_progress_window'] = progress_window_proxy
            globals()['_v41_analysis_progress_window'] = progress_window_proxy
            _FARADAIQ_AI_PROGRESS_CALLBACK = qlog
            messagebox.showinfo = lambda title, msg, *a, **k: (qlog(f'[info] {title}: {msg}'), 'ok')[1]
            messagebox.showwarning = lambda title, msg, *a, **k: (qlog(f'[warning] {title}: {msg}'), 'ok')[1]
            messagebox.showerror = lambda title, msg, *a, **k: (qlog(f'[error] {title}: {msg}'), 'ok')[1]
            qlog('[FaradaIQ v273] Export worker started. Main Tk thread remains responsive.')
            qlog('[FaradaIQ v273] Existing export/bundle/parser chain is running with Tk-safe progress redirection.')
            _v177_PREV_EXPORT_OUTPUTS_RESPONSIVE(self)
            q.put(('done', True))
        except Exception as exc:
            try:
                q.put(('error', f'{exc}\n\n{traceback.format_exc()}'))
            except Exception:
                pass
        finally:
            try:
                _FARADAIQ_AI_PROGRESS_CALLBACK = saved_globals.get('_FARADAIQ_AI_PROGRESS_CALLBACK')
            except Exception:
                pass
            for name, val in saved_globals.items():
                try:
                    if name != '_FARADAIQ_AI_PROGRESS_CALLBACK' and val is not None:
                        globals()[name] = val
                except Exception:
                    pass
            try:
                messagebox.showinfo, messagebox.showwarning, messagebox.showerror = saved_msg
            except Exception:
                pass
            for name, val in saved.items():
                try: setattr(self, name, val)
                except Exception: pass

    t = _v177_threading.Thread(target=worker, name='FaradaIQ-v210-export-worker', daemon=True)
    self._v177_export_thread = t
    t.start()
    try:
        self.after(150, drain_queue)
    except Exception:
        pass
    return None

try:
    if callable(_v177_PREV_EXPORT_OUTPUTS_RESPONSIVE):
        SessionReaderGUI.export_outputs = _session_reader_gui_v177_export_outputs_responsive
except Exception:
    pass

