# ---- FaradaIQ Studio v273 export-button guard patch ----
# Disable every visible "Export archive + CSV" / "Export archive + analysis-ready CSV"
# button while the background export worker is active.  This prevents accidental
# double-clicks or a second export launch before the first worker has completed.

try:
    _v177_PREV_EXPORT_OUTPUTS_DISABLE_GUARD = SessionReaderGUI.export_outputs
except Exception:
    _v177_PREV_EXPORT_OUTPUTS_DISABLE_GUARD = None


def _v177_is_export_worker_active(gui):
    for name in ('_v177_export_thread', '_v147_export_thread'):
        try:
            th = getattr(gui, name, None)
            if th is not None and th.is_alive():
                return True
        except Exception:
            pass
    return False


def _v177_walk_widgets(widget):
    try:
        yield widget
        for child in widget.winfo_children():
            yield from _v177_walk_widgets(child)
    except Exception:
        return


def _v177_find_export_buttons(gui):
    hits = []
    try:
        for w in _v177_walk_widgets(gui):
            try:
                txt = str(w.cget('text') or '')
            except Exception:
                continue
            low = txt.lower()
            # Main export button variants used across FaradaIQ versions.
            if ('export archive' in low and ('csv' in low or 'analysis-ready' in low)):
                hits.append(w)
    except Exception:
        pass
    # Stable order and no duplicates.
    out, seen = [], set()
    for w in hits:
        k = str(w)
        if k not in seen:
            seen.add(k); out.append(w)
    return out


def _v177_set_export_buttons(gui, active=False):
    """Disable/restore export buttons and keep a user-visible active-export state."""
    try:
        buttons = _v177_find_export_buttons(gui)
        gui._v177_export_buttons = buttons
    except Exception:
        buttons = []
    for b in buttons:
        try:
            if not hasattr(b, '_faradaiq_v177_original_text'):
                try: b._faradaiq_v177_original_text = str(b.cget('text') or '')
                except Exception: b._faradaiq_v177_original_text = 'Export archive + CSV'
            if active:
                try: b.configure(text='Export running...', state='disabled')
                except Exception:
                    try: b.state(['disabled'])
                    except Exception: pass
            else:
                try: b.configure(text=b._faradaiq_v177_original_text, state='normal')
                except Exception:
                    try: b.state(['!disabled'])
                    except Exception: pass
        except Exception:
            pass
    try:
        gui._v177_export_buttons_disabled = bool(active)
    except Exception:
        pass


def _v177_poll_export_button_state(gui):
    """Re-enable Export archive + CSV when the background worker finishes."""
    try:
        if _v177_is_export_worker_active(gui):
            _v177_set_export_buttons(gui, active=True)
            gui.after(350, lambda: _v177_poll_export_button_state(gui))
            return
        _v177_set_export_buttons(gui, active=False)
        try:
            # Do not overwrite a more important error/status message if the export failed;
            # this short suffix is only a visual cue that the button has been restored.
            cur = gui.status_var.get() if hasattr(gui, 'status_var') else ''
            if cur and 'failed' not in cur.lower() and 'error' not in cur.lower():
                gui.status_var.set(str(cur)[:180] + ' | Export button re-enabled')
        except Exception:
            pass
    except Exception:
        try: _v177_set_export_buttons(gui, active=False)
        except Exception: pass


def _session_reader_gui_v177_export_outputs_disable_guard(self):
    """Guard wrapper around the v198 responsive export worker."""
    if _v177_is_export_worker_active(self):
        _v177_set_export_buttons(self, active=True)
        try:
            messagebox.showinfo(
                'Export already running',
                'FaradaIQ export is already running. The Export archive + CSV button is disabled until the current export finishes.',
                parent=self,
            )
        except Exception:
            pass
        try: self.after(350, lambda: _v177_poll_export_button_state(self))
        except Exception: pass
        return None
    _v177_set_export_buttons(self, active=True)
    try:
        result = _v177_PREV_EXPORT_OUTPUTS_DISABLE_GUARD(self) if callable(_v177_PREV_EXPORT_OUTPUTS_DISABLE_GUARD) else None
    except Exception:
        _v177_set_export_buttons(self, active=False)
        raise
    # v198/v147 responsive export returns immediately after launching a worker.
    # If no worker was launched, restore the button shortly.
    try:
        self.after(350, lambda: _v177_poll_export_button_state(self))
    except Exception:
        if not _v177_is_export_worker_active(self):
            _v177_set_export_buttons(self, active=False)
    return result

try:
    if callable(_v177_PREV_EXPORT_OUTPUTS_DISABLE_GUARD):
        SessionReaderGUI.export_outputs = _session_reader_gui_v177_export_outputs_disable_guard
except Exception:
    pass

