# ---- FaradaIQ Studio v273 Smart Compare local/AI split ----
# User request: do not require an LLM for deterministic plot filtering. Smart Compare
# now exposes two explicit request paths:
#   Ask AI    -> use configured LLM only when the GUI checkbox allows it; still validate
#                and override with local hard constraints from the typed request.
#   Ask Local -> deterministic local parser/resolver only; never calls the LLM.
# Both paths save transaction JSON and *.plot_recipe.json files with the same audit trail.
try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v177_truthy_env(name, default=True):
    try:
        val = os.environ.get(name)
        if val is None or str(val).strip() == '':
            return bool(default)
        return str(val).strip().lower() not in {'0', 'false', 'no', 'off', 'disable', 'disabled'}
    except Exception:
        return bool(default)


def _v177_direct_prompt_item(prompt):
    """Create one structured local item from a direct typed request."""
    text = str(prompt or '').strip() or 'Create local Smart Compare plot recipe for selected or visible data.'
    mode = _v177j_mode_from_item({'plot_mode': 'Auto'}, text) if '_v177j_mode_from_item' in globals() else 'Auto'
    if not mode or mode == 'Auto':
        # Default direct scan-rate/cycle/point requests to CV/LSV, because these
        # are the common VersaStudio / CV comparison words users type.
        if re.search(r'\b(scan\s*rate|m\s*v\s*/\s*s|mvs|cycle|cv|lsv)\b', text, flags=re.I):
            mode = 'CV / LSV'
    return {
        'title': text,
        'technique': mode if mode and mode != 'Auto' else '',
        'plot_mode': mode or 'Auto',
        'selection': {},
        'x': 'auto',
        'y': 'auto',
        'overlay_by': 'auto',
        'reason': 'Locally parsed from the typed request; no LLM call was made.',
        'raw': text,
    }


def _v177_prompt_is_direct_plot_request(prompt):
    text = str(prompt or '')
    try:
        hard = _v177_parse_hard_constraints(text)
    except Exception:
        hard = {}
    if hard.get('has_rate') or hard.get('has_cycle') or hard.get('has_points'):
        return True
    return bool(re.search(r'\b(compare|plot|overlay|show|view|nyquist|bode|drt|cv|lsv|dpv|swv|tafel|eis|scan\s*rate|cycle)\b', text, flags=re.I))


def _v177_local_items_for_prompt(browser, prompt, mode='ask_local'):
    prompt = str(prompt or '').strip()
    if prompt and _v177_prompt_is_direct_plot_request(prompt):
        return [_v177_direct_prompt_item(prompt)]
    try:
        return _v177j_local_items(browser) if '_v177j_local_items' in globals() else [{'title': prompt or 'Compare selected data locally', 'selection': {}, 'raw': prompt}]
    except Exception:
        return [{'title': prompt or 'Compare selected data locally', 'selection': {}, 'raw': prompt}]


def _v177_request_local_suggestions(browser, user_prompt='', append=True, mode='ask_local'):
    prompt = str(user_prompt or '').strip() or 'Create local Smart Compare plot recipes for selected or visible FaradaIQ data.'
    txn = f'SCLOCAL-{_v177j_now_id()}' if '_v177j_now_id' in globals() else ('SCLOCAL-' + datetime.now().strftime('%Y%m%d_%H%M%S'))
    try:
        hard = _v177_parse_hard_constraints(prompt)
    except Exception:
        hard = {}
    try:
        _v177_set_smart_status(browser, f'{txn} → Local Smart Compare parser running. No LLM call will be made.', True)
    except Exception:
        pass
    try:
        items = _v177_local_items_for_prompt(browser, prompt, mode=mode)
        recipes = [_v177_recipe_from_item(browser, it, source='Local/rules', txn=txn, user_prompt=prompt, mode='ask') for it in items]
        txn_record = {
            'transaction_id': txn,
            'schema_version': 'faradaiq_smart_compare_transaction_v177',
            'provider': 'Local FaradaIQ rule parser',
            'model': None,
            'llm_used': False,
            'mode': mode,
            'user_prompt': prompt,
            'hard_constraints_extracted_by_faradaiq': hard,
            'parse_mode': 'local-hard-constraint-parser',
            'raw_llm_response': None,
            'parsed_json': {'suggestions': items},
            'parsed_items': items,
            'resolved_recipes': recipes,
            'created': datetime.now().isoformat(timespec='seconds'),
        }
        added = _v177j_insert_recipes(browser, recipes, append=append) if '_v177j_insert_recipes' in globals() else 0
        try:
            _v177j_init_recipe_store(browser)
            browser._smart_compare_transactions.append(txn_record)
        except Exception:
            pass
        out = _v177j_save_transaction(browser, txn_record) if '_v177j_save_transaction' in globals() else None
        resolved = sum(1 for r in recipes if r.get('resolved_count'))
        total_curves = sum(int(r.get('resolved_count') or 0) for r in recipes)
        try:
            _v177_set_smart_status(browser, f'{txn} ✓ Ask Local added {added} local plot recipe(s); resolved {resolved}/{len(recipes)} recipe(s), {total_curves} curve(s). Stored: {Path(out).name if out else "not saved"}', True)
        except Exception:
            pass
    except Exception as exc:
        try:
            _v177_set_smart_status(browser, f'{txn} ✗ Ask Local failed: {exc}', True)
        except Exception:
            pass
        try:
            messagebox.showerror('Ask Local failed', str(exc), parent=browser)
        except Exception:
            pass


def _v177_ask_local_comparisons(self):
    try:
        q = self.ai_compare_entry.get().strip()
    except Exception:
        q = ''
    _v177_request_local_suggestions(self, q, append=True, mode='ask_local')


def _v177_ask_ai_comparisons(self):
    try:
        q = self.ai_compare_entry.get().strip()
    except Exception:
        q = ''
    if not q:
        q = 'Create JSON plot-recipes for selected or visible FaradaIQ data.'
    use_llm = True
    try:
        if hasattr(self, 'smart_compare_use_llm_var'):
            use_llm = bool(self.smart_compare_use_llm_var.get())
        else:
            use_llm = _v177_truthy_env('FARADAIQ_SMART_COMPARE_USE_LLM', True)
    except Exception:
        use_llm = True
    if not use_llm:
        try:
            _v177_set_smart_status(self, 'Ask AI is set to Local mode because LLM is disabled. Running the local parser instead.', True)
        except Exception:
            pass
        return _v177_request_local_suggestions(self, q, append=True, mode='ask_ai_llm_disabled')
    return _v177_request_llm_suggestions(self, q, append=True, mode='ask')


def _v177_suggest_comparisons(self):
    # Keep Suggest safe and useful: when LLM is disabled, use local dataset-grounded suggestions.
    use_llm = True
    try:
        if hasattr(self, 'smart_compare_use_llm_var'):
            use_llm = bool(self.smart_compare_use_llm_var.get())
        else:
            use_llm = _v177_truthy_env('FARADAIQ_SMART_COMPARE_USE_LLM', True)
    except Exception:
        use_llm = True
    if not use_llm:
        default_prompt = 'Generate local Smart Compare suggestions from the available H5/cache data. Prefer CV scan-rate/cycle comparisons, EIS Nyquist point trends, DRT point trends, and only techniques present in the bundle.'
        return _v177_request_local_suggestions(self, default_prompt, append=False, mode='suggest_local')
    try:
        return _v177_suggest_comparisons(self)
    except Exception:
        default_prompt = 'Generate local Smart Compare suggestions from the available H5/cache data.'
        return _v177_request_local_suggestions(self, default_prompt, append=False, mode='suggest_local_fallback')


def _v177_set_use_llm_from_var(browser):
    try:
        val = '1' if bool(browser.smart_compare_use_llm_var.get()) else '0'
        os.environ['FARADAIQ_SMART_COMPARE_USE_LLM'] = val
        label = 'enabled' if val == '1' else 'disabled'
        _v177_set_smart_status(browser, f'LLM for Ask AI is {label}. Ask Local always uses only the local parser.', True)
    except Exception:
        pass


def _v177_enhance_smart_compare_ui(self):
    try:
        if not hasattr(self, 'suggestion_list'):
            return
        tab_ai = self.suggestion_list.master
        if getattr(self, '_v177_smart_ui_enhanced', False):
            return
        self._v177_smart_ui_enhanced = True
        default_llm = _v177_truthy_env('FARADAIQ_SMART_COMPARE_USE_LLM', True)
        self.smart_compare_use_llm_var = tk.BooleanVar(value=default_llm)
        localrow = ttk.Frame(tab_ai, style='Card.TFrame')
        localrow.pack(fill='x', pady=(3, 3))
        ttk.Checkbutton(localrow, text='Use LLM for Ask AI', variable=self.smart_compare_use_llm_var, command=lambda: _v177_set_use_llm_from_var(self)).pack(side='left', padx=(0, 6))
        ttk.Button(localrow, text='Ask Local', command=self.ask_local_comparisons).pack(side='left', fill='x', expand=True, padx=(2, 0))
        ttk.Label(tab_ai, text='Ask AI = LLM JSON recipe + local hard-constraint override. Ask Local = deterministic rule parser only; no LLM, no network.', style='Muted.TLabel', wraplength=360).pack(anchor='w', fill='x', pady=(0, 3))
        try:
            if hasattr(self, 'smart_compare_status_var'):
                provider, model = _v177_selected_llm_label() if '_v177_selected_llm_label' in globals() else ('configured LLM', '')
                self.smart_compare_status_var.set('Ready. Ask AI uses LLM when enabled: ' + provider + (f' | model: {model}' if model else '') + '. Ask Local never uses LLM.')
        except Exception:
            pass
    except Exception as exc:
        try:
            self.log(f'Could not add v198 Smart Compare local/AI controls: {exc}')
        except Exception:
            pass

