def _v177_default_plotting_options_prompt():
    return (
        'Suggest concrete plotting options for this FaradaIQ H5/JSON dataset. '
        'Use only the available techniques and files from the browser context. '
        'Return JSON suggestions for plots the user can apply directly: CV/LSV overlays by point, scan rate, and cycle; '
        'fixed-cycle/fixed-scan-rate comparisons; EIS Nyquist and Bode overlays; DRT gamma(tau) trends; '
        'DPV/SWV peak-shift comparisons; CP/CA transient overlays; and useful export/report views. '
        'Mention exact available point numbers, scan rates, cycles, technique groups, and recommended plot mode when possible. '
        'Do not invent missing techniques or files.'
    )


def _v177_suggest_comparisons_llm_default(self):
    # Suppress only the automatic call scheduled while the browser opens.
    if getattr(self, '_v177_disable_auto_suggest', False):
        self._v177_disable_auto_suggest = False
        try:
            provider, model = _v177_selected_llm_label() if '_v177_selected_llm_label' in globals() else ('configured LLM', '')
            _v177_set_smart_status(self, 'Ready. Click Suggest to ask the configured LLM for plotting options: ' + provider + (f' | {model}' if model else ''), False)
        except Exception:
            pass
        return
    prompt = _v177_default_plotting_options_prompt()
    try:
        _v177_set_smart_status(self, 'Suggest → asking configured LLM for dataset-grounded plotting options. Local suggestions will be used only if the LLM is unavailable.', True)
    except Exception:
        pass
    return _v177_request_llm_suggestions(self, prompt, append=False, mode='suggest')


# --- Export button restore watchdog ------------------------------------------
try:
    _v177_PREV_FIND_EXPORT_BUTTONS = _v177_find_export_buttons
except Exception:
    _v177_PREV_FIND_EXPORT_BUTTONS = None


def _v177_find_export_buttons(gui):
    hits = []
    try:
        if callable(_v177_PREV_FIND_EXPORT_BUTTONS):
            hits.extend(_v177_PREV_FIND_EXPORT_BUTTONS(gui) or [])
    except Exception:
        pass
    try:
        hits.extend(getattr(gui, '_v177_export_buttons', []) or [])
    except Exception:
        pass
    try:
        walker = _v177_walk_widgets if '_v177_walk_widgets' in globals() else (lambda w: [])
        for w in walker(gui):
            try:
                txt = str(w.cget('text') or '').lower()
            except Exception:
                continue
            if (
                ('export archive' in txt and ('csv' in txt or 'analysis-ready' in txt))
                or txt.strip().startswith('export running')
            ):
                hits.append(w)
    except Exception:
        pass
    out, seen = [], set()
    for w in hits:
        try:
            if hasattr(w, 'winfo_exists') and not w.winfo_exists():
                continue
        except Exception:
            pass
        k = str(w)
        if k not in seen:
            seen.add(k)
            out.append(w)
    return out


def _v177_set_export_buttons(gui, active=False):
    buttons = _v177_find_export_buttons(gui)
    try:
        gui._v177_export_buttons = buttons
    except Exception:
        pass
    for b in buttons:
        try:
            try:
                current = str(b.cget('text') or '')
            except Exception:
                current = ''
            if not hasattr(b, '_faradaiq_v177_original_text'):
                b._faradaiq_v177_original_text = 'Export archive + CSV' if current.lower().startswith('export running') else (current or 'Export archive + CSV')
            if active:
                try:
                    b.configure(text='Export running...', state='disabled')
                except Exception:
                    try:
                        b.state(['disabled'])
                    except Exception:
                        pass
            else:
                original = getattr(b, '_faradaiq_v177_original_text', 'Export archive + CSV') or 'Export archive + CSV'
                if str(original).lower().startswith('export running'):
                    original = 'Export archive + CSV'
                try:
                    b.configure(text=original, state='normal')
                except Exception:
                    try:
                        b.state(['!disabled'])
                    except Exception:
                        pass
        except Exception:
            pass
    try:
        gui._v177_export_buttons_disabled = bool(active)
    except Exception:
        pass


def _v177_restore_export_buttons_if_idle(gui, note=True):
    try:
        active = _v177_is_export_worker_active(gui) if '_v177_is_export_worker_active' in globals() else False
    except Exception:
        active = False
    if active:
        try:
            _v177_set_export_buttons(gui, active=True)
            gui.after(500, lambda g=gui: _v177_restore_export_buttons_if_idle(g, note=note))
        except Exception:
            pass
        return False
    try:
        _v177_set_export_buttons(gui, active=False)
        if note and hasattr(gui, 'status_var'):
            cur = str(gui.status_var.get() or '')
            if 'Export running' in cur:
                gui.status_var.set('Export finished. Export archive + CSV is ready again.')
    except Exception:
        pass
    return True


