# ---- FaradaIQ Studio v273 point-index precedence fix ----
# Fix: experiments whose source folder contains text like "point_11points" caused
# the H5 browser and Smart Compare path resolver to group every CV cache file under
# point 11. The extracted cache file names already contain the actual per-file
# point, e.g. CV_point_001_scanrate_100mVs_cycle_01.csv. v198 now gives the file
# name point index priority over parent folders and source experiment names.

def _v177_point_from_filename_first(path):
    p = Path(path)
    name = p.name
    # Prefer the generated cache filename: CV_point_001_scanrate_..._cycle_...
    patterns_name = [
        r'(?:^|[_\-\s])cv[_\-\s]*point[_\-\s]*0*(\d+)(?:[_\-\s]|$)',
        r'(?:^|[_\-\s])eis[_\-\s]*point[_\-\s]*0*(\d+)(?:[_\-\s]|$)',
        r'(?:^|[_\-\s])drt[_\-\s]*point[_\-\s]*0*(\d+)(?:[_\-\s]|$)',
        r'(?:^|[_\-\s])point[_\-\s]*0*(\d+)(?:[_\-\s]|$)',
    ]
    for pat in patterns_name:
        m = re.search(pat, name, flags=re.I)
        if m:
            try:
                return int(m.group(1))
            except Exception:
                pass

    # Next prefer the nearest path components, but ignore components like
    # point_11points because that means "11 points in this experiment", not point 11.
    for part in reversed(p.parts):
        pl = str(part).lower()
        if re.search(r'point[_\-\s]*\d+\s*points?\b', pl):
            continue
        for pat in [r'^point[_\-\s]*0*(\d+)$', r'^position[_\-\s]*0*(\d+)$', r'^pos[_\-\s]*0*(\d+)$']:
            m = re.search(pat, pl, flags=re.I)
            if m:
                try:
                    return int(m.group(1))
                except Exception:
                    pass

    # Last resort: full path, still skipping the "...11points" style.
    s = p.as_posix().lower()
    s = re.sub(r'point[_\-\s]*\d+\s*points?\b', '', s)
    for pat in [r'point[_\-\s]*0*(\d+)', r'position[_\-\s]*0*(\d+)', r'pos[_\-\s]*0*(\d+)']:
        m = re.search(pat, s, flags=re.I)
        if m:
            try:
                return int(m.group(1))
            except Exception:
                pass
    return None


def _v177_rate_from_filename_or_path(path):
    p = Path(path)
    for source in (p.name, p.as_posix()):
        for pat in [r'scanrate[_\-\s]*([0-9]+(?:[p\.][0-9]+)?)', r'([0-9]+(?:[p\.][0-9]+)?)\s*m\s*v\s*/?\s*s', r'([0-9]+(?:[p\.][0-9]+)?)\s*mvs']:
            m = re.search(pat, source, flags=re.I)
            if m:
                try:
                    return _v177_float_from_token(m.group(1)) if '_v177_float_from_token' in globals() else float(str(m.group(1)).replace('p', '.'))
                except Exception:
                    pass
    return None


def _v177_cycle_from_filename_or_path(path):
    p = Path(path)
    for source in (p.name, p.as_posix()):
        for pat in [r'cycle[_\-\s]*0*(\d+)', r'cyc[_\-\s]*0*(\d+)', r'__c0*(\d+)__']:
            m = re.search(pat, source, flags=re.I)
            if m:
                try:
                    return int(m.group(1))
                except Exception:
                    pass
    return None


# Override the Smart Compare path metadata helpers so typed/LLM requests such as
# "point 1-11" resolve real files from CV_point_001...CV_point_011 instead of
# the parent experiment label point_11points.
def _v177_path_point_value(path):
    return _v177_point_from_filename_first(path)


def _v177_path_rate_value(path):
    return _v177_rate_from_filename_or_path(path)


def _v177_path_cycle_value(path):
    return _v177_cycle_from_filename_or_path(path)


def _v177_sort_cv_key(path):
    return (
        _v177_path_rate_value(path) or 0.0,
        _v177_path_cycle_value(path) or 0,
        _v177_path_point_value(path) or 0,
        Path(path).name.lower(),
    )


def _v177_refresh_tree_pointfix(self):
    try:
        self.tree.delete(*self.tree.get_children())
        self._path_by_iid.clear()
        root_ids = {}

        def root_node(label, open=True):
            iid = self.tree.insert('', 'end', text=label, values=('', ''), open=open)
            root_ids[label] = iid
            return iid

        cv_rate_root = root_node('CV / LSV grouped by scan rate', True)
        cv_point_root = root_node('CV / LSV grouped by point', False)
        eis_root = root_node('EIS sets / Nyquist + Bode tables', True)
        drt_root = root_node('DRT analyzed data tables', False)
        other_root = root_node('Other tables', False)

        files = sorted([p for p in self.cache_root.rglob('*.csv') if p.is_file()], key=lambda p: str(p).lower())
        inserted = 0
        node_cache = {}

        def child(parent, label, kind='', open=False):
            key = (parent, label, kind)
            if key in node_cache:
                return node_cache[key]
            iid = self.tree.insert(parent, 'end', text=label, values=(kind, ''), open=open)
            node_cache[key] = iid
            return iid

        def add_file(parent, p, kind):
            nonlocal inserted
            label = p.name
            size = _v138_fmt_size(p.stat().st_size) if '_v138_fmt_size' in globals() else ''
            iid = self.tree.insert(parent, 'end', text=label, values=(kind, size))
            self._path_by_iid[iid] = p
            inserted += 1

        cv_points_seen = set()
        for p in files:
            s = p.as_posix().lower()
            if '/cv_lsv/' in s or '\\cv_lsv\\' in s or 'cv_point_' in p.name.lower():
                rate_val = _v177_rate_from_filename_or_path(p)
                rate = (f'{rate_val:g}mVs' if rate_val is not None else 'unknown')
                point = _v177_point_from_filename_first(p) or 0
                cyc = _v177_cycle_from_filename_or_path(p) or 0
                cv_points_seen.add(point)
                rnode = child(cv_rate_root, f'{rate}', 'scan rate', True)
                pnode = child(rnode, f'point {point:02d}', 'point', False)
                cnode = child(pnode, f'cycle {cyc:02d}', 'cycle', False)
                add_file(cnode, p, 'CV / LSV')

                ptop = child(cv_point_root, f'point {point:02d}', 'point', False)
                rtop = child(ptop, f'{rate}', 'scan rate', False)
                ctop = child(rtop, f'cycle {cyc:02d}', 'cycle', False)
                add_file(ctop, p, 'CV / LSV')
            elif '/eis/' in s or '\\eis\\' in s or 'eis_point_' in p.name.lower():
                point = _v177_point_from_filename_first(p) or 0
                pnode = child(eis_root, f'point {point:02d}', 'EIS point', True)
                add_file(pnode, p, 'EIS')
            elif '/drt/' in s or '\\drt\\' in s or 'drt_point_' in p.name.lower():
                rel = p.relative_to(self.cache_root).parts
                run = rel[1] if len(rel) > 2 else 'DRT'
                rnode = child(drt_root, run, 'DRT run', False)
                point = _v177_point_from_filename_first(p) or 0
                pnode = child(rnode, f'point {point:02d}', 'DRT point', False)
                add_file(pnode, p, 'DRT')
            else:
                add_file(other_root, p, 'Numeric')

        try:
            point_summary = f' | CV points from file names: {min(cv_points_seen)}-{max(cv_points_seen)} ({len(cv_points_seen)} points)' if cv_points_seen else ''
            self.log(f'Indexed {len(files)} unique H5-extracted CSV table(s); file-name point index has priority over parent folder labels{point_summary}.')
        except Exception:
            pass
    except Exception as exc:
        try:
            self.log(f'Refresh tree failed: {exc}\n{traceback.format_exc()}')
        except Exception:
            pass


