# ---- FaradaIQ Studio v273 Smart Compare transaction-list refresh patch ----
# Narrow fix: keep the working browser/plotting behavior from the previous working build, but ensure
# the visible "LLM / Local transactions" list refreshes after Suggest, Ask AI,
# Ask Local, LLM fallback, and JSON-first Smart Compare requests. The previous build stored
# transaction JSON on disk but did not repaint the listbox after the worker
# thread appended the transaction record.
try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v177_transaction_kind(record):
    try:
        rec = dict(record or {})
        if rec.get('llm_used') is False:
            return 'Local'
        if rec.get('error') and str(rec.get('parse_mode') or '').lower().startswith('local'):
            return 'AI/local fallback'
        provider = str(rec.get('provider') or '')
        if 'local' in provider.lower() and 'llm' not in provider.lower():
            return 'Local'
        return 'LLM'
    except Exception:
        return 'Transaction'


def _v177_transaction_summary(record):
    try:
        rec = dict(record or {})
        txn = str(rec.get('transaction_id') or '').strip() or 'SC'
        kind = _v177_transaction_kind(rec)
        prompt = str(rec.get('user_prompt') or '').strip().replace('\n', ' ')
        prompt = re.sub(r'\s+', ' ', prompt)
        if len(prompt) > 70:
            prompt = prompt[:67].rstrip() + '...'
        parse_mode = str(rec.get('parse_mode') or '').strip()
        recipes = list(rec.get('resolved_recipes') or [])
        total = len(recipes)
        resolved = sum(1 for r in recipes if isinstance(r, dict) and r.get('resolved_count'))
        total_curves = sum(int(r.get('resolved_count') or 0) for r in recipes if isinstance(r, dict))
        tail = []
        if parse_mode:
            tail.append(parse_mode)
        if total:
            tail.append(f'{resolved}/{total} recipes')
        if total_curves:
            tail.append(f'{total_curves} curves')
        if rec.get('error'):
            tail.append('fallback/error')
        return f'{txn} | {kind} | {prompt}' + ((' | ' + ' | '.join(tail)) if tail else '')
    except Exception:
        return str(record)


def _v177_refresh_transaction_ui(browser):
    """Repaint the Smart Compare transaction listbox from stored records."""
    try:
        txns = list(getattr(browser, '_smart_compare_transactions', []) or [])
        if not hasattr(browser, 'smart_txn_list'):
            return False
        widget = browser.smart_txn_list
        try:
            widget.delete(0, 'end')
        except Exception:
            pass
        for rec in txns:
            try:
                widget.insert('end', _v177_transaction_summary(rec))
            except Exception:
                widget.insert('end', str(rec))
        try:
            if widget.size():
                widget.see('end')
        except Exception:
            pass
        return True
    except Exception:
        return False


def _v177_schedule_transaction_refresh(browser, delays=(0, 250, 800, 1500, 3000, 6000, 12000, 25000)):
    """Schedule refreshes because LLM transactions are appended by a worker."""
    def _do():
        try:
            # Ensure the transaction UI exists if the Smart Compare tab was built.
            if not hasattr(browser, 'smart_txn_list') and '_v177_enhance_smart_compare_layout' in globals():
                try:
                    _v177_enhance_smart_compare_layout(browser)
                except Exception:
                    pass
            _v177_refresh_transaction_ui(browser)
        except Exception:
            pass
    try:
        for d in delays:
            try:
                browser.after(int(d), _do)
            except Exception:
                pass
    except Exception:
        _do()


