# ---- FaradaIQ Studio v273 CP/CA browser classification patch ----
# User request: classify CP (chronopotentiometry/chronoamperometry) in the H5
# browser like CV, EIS, and DRT instead of placing CP_point_*.csv under Other tables.
# This patch keeps the working stable plotting path and only adds a CP/CA group,
# CP-aware x/y selection, and optional CP/CA mode in the existing dropdown.
try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v177_is_cp_cache_path(path):
    try:
        p = Path(path)
        s = p.as_posix().lower()
        n = p.name.lower()
        return (
            '/cp/' in s or '\\cp\\' in s or
            '/chronopotentiometry/' in s or '\\chronopotentiometry\\' in s or
            '/chronoamperometry/' in s or '\\chronoamperometry\\' in s or
            n.startswith('cp_point_') or n.startswith('ca_point_') or
            'chronopot' in n or 'chronoamp' in n
        )
    except Exception:
        return False


def _v177_cp_kind_label(path):
    try:
        n = Path(path).name.lower()
        s = Path(path).as_posix().lower()
        if n.startswith('ca_') or 'chronoamp' in n or 'chronoamperometry' in s:
            return 'CA / chronoamperometry'
        return 'CP / chronopotentiometry'
    except Exception:
        return 'CP / CA'


try:
    _v177_PREV_CHOOSE_XY_CP = _v138_choose_xy
except Exception:
    _v177_PREV_CHOOSE_XY_CP = None


def _v177_pick_col_any(columns, needles):
    lows = [(str(c).lower().strip(), c) for c in columns]
    for needle in needles:
        n = str(needle).lower().strip()
        for low, c in lows:
            if low == n:
                return c
    for needle in needles:
        n = str(needle).lower().strip()
        for low, c in lows:
            if n in low:
                return c
    return None


def _v177_choose_xy_cpaware(df, mode='Auto', path=None):
    mode_l = str(mode or 'Auto').lower()
    is_cp = _v177_is_cp_cache_path(path) or ('cp' in mode_l) or ('chrono' in mode_l) or ('transient' in mode_l)
    if is_cp:
        try:
            cols = list(df.columns)
            tcol = _v177_pick_col_any(cols, ['time_s', 'time/s', 'time', 't_s', 'elapsed_s', 'seconds', 's'])
            pot = _v177_pick_col_any(cols, ['potential_v', 'potential', 'e_v', 'ewe_v', 'ewe', 'voltage_v', 'voltage'])
            cur = _v177_pick_col_any(cols, ['current_a', 'current', 'i_a', 'i/a', '<i>/a', 'amps', 'ampere'])
            # CP usually wants potential vs time; CA usually wants current vs time.
            if tcol is not None:
                if pot is not None and ('ca' not in mode_l and 'chronoamp' not in mode_l):
                    return tcol, pot, 'CP / CA transient'
                if cur is not None:
                    return tcol, cur, 'CP / CA transient'
                if pot is not None:
                    return tcol, pot, 'CP / CA transient'
            # No time column: avoid CV-style potential-vs-current if possible and use first numeric pair.
            import pandas as _pd
            numeric = []
            for c in cols:
                vals = _pd.to_numeric(df[c], errors='coerce')
                if vals.notna().sum() >= 2:
                    numeric.append(c)
            if len(numeric) >= 2:
                return numeric[0], numeric[1], 'CP / CA numeric fallback'
        except Exception:
            pass
    if callable(_v177_PREV_CHOOSE_XY_CP):
        return _v177_PREV_CHOOSE_XY_CP(df, mode, path)
    return None, None, 'No numeric pair'


def _v177_refresh_tree_cp_classification(self):
    try:
        self.tree.delete(*self.tree.get_children())
        self._path_by_iid.clear()
        root_ids = {}

        def root_node(label, open=True):
            iid = self.tree.insert('', 'end', text=label, values=('', ''), open=open)
            root_ids[label] = iid
            return iid

        cv_rate_root = root_node('CV / LSV grouped by scan rate', True)
        cv_point_root = root_node('CV / LSV grouped by point', False)
        eis_root = root_node('EIS sets / Nyquist + Bode tables', True)
        drt_root = root_node('DRT analyzed data tables', False)
        cp_root = root_node('CP / CA transients grouped by point', True)
        other_root = root_node('Other tables', False)

        files = sorted([p for p in Path(self.cache_root).rglob('*.csv') if p.is_file()], key=lambda p: str(p).lower())
        inserted = 0
        node_cache = {}

        def child(parent, label, kind='', open=False):
            key = (parent, label, kind)
            if key in node_cache:
                return node_cache[key]
            iid = self.tree.insert(parent, 'end', text=label, values=(kind, ''), open=open)
            node_cache[key] = iid
            return iid

        def add_file(parent, p, kind):
            nonlocal inserted
            label = Path(p).name
            size = _v138_fmt_size(Path(p).stat().st_size) if '_v138_fmt_size' in globals() else ''
            iid = self.tree.insert(parent, 'end', text=label, values=(kind, size))
            self._path_by_iid[iid] = Path(p)
            inserted += 1

        cv_points_seen = set()
        cp_points_seen = set()
        for p in files:
            p = Path(p)
            s = p.as_posix().lower()
            n = p.name.lower()
            if '/cv_lsv/' in s or '\\cv_lsv\\' in s or 'cv_point_' in n:
                rate_val = _v177_rate_from_filename_or_path(p) if '_v177_rate_from_filename_or_path' in globals() else None
                rate = (f'{rate_val:g}mVs' if rate_val is not None else 'unknown')
                point = (_v177_point_from_filename_first(p) if '_v177_point_from_filename_first' in globals() else None) or 0
                cyc = (_v177_cycle_from_filename_or_path(p) if '_v177_cycle_from_filename_or_path' in globals() else None) or 0
                cv_points_seen.add(point)
                rnode = child(cv_rate_root, f'{rate}', 'scan rate', True)
                pnode = child(rnode, f'point {point:02d}', 'point', False)
                cnode = child(pnode, f'cycle {cyc:02d}', 'cycle', False)
                add_file(cnode, p, 'CV / LSV')
                ptop = child(cv_point_root, f'point {point:02d}', 'point', False)
                rtop = child(ptop, f'{rate}', 'scan rate', False)
                ctop = child(rtop, f'cycle {cyc:02d}', 'cycle', False)
                add_file(ctop, p, 'CV / LSV')
            elif '/eis/' in s or '\\eis\\' in s or 'eis_point_' in n:
                point = (_v177_point_from_filename_first(p) if '_v177_point_from_filename_first' in globals() else None) or 0
                pnode = child(eis_root, f'point {point:02d}', 'EIS point', True)
                add_file(pnode, p, 'EIS')
            elif '/drt/' in s or '\\drt\\' in s or 'drt_point_' in n:
                rel = p.relative_to(self.cache_root).parts
                run = rel[1] if len(rel) > 2 else 'DRT'
                rnode = child(drt_root, run, 'DRT run', False)
                point = (_v177_point_from_filename_first(p) if '_v177_point_from_filename_first' in globals() else None) or 0
                pnode = child(rnode, f'point {point:02d}', 'DRT point', False)
                add_file(pnode, p, 'DRT')
            elif _v177_is_cp_cache_path(p):
                point = (_v177_point_from_filename_first(p) if '_v177_point_from_filename_first' in globals() else None) or 0
                cp_points_seen.add(point)
                label = _v177_cp_kind_label(p)
                pnode = child(cp_root, f'point {point:03d}', 'CP / CA point', True)
                add_file(pnode, p, label)
            else:
                add_file(other_root, p, 'Numeric')

        try:
            parts = []
            if cv_points_seen:
                parts.append(f'CV points from file names: {min(cv_points_seen)}-{max(cv_points_seen)} ({len(cv_points_seen)} points)')
            if cp_points_seen:
                parts.append(f'CP/CA points from file names: {min(cp_points_seen)}-{max(cp_points_seen)} ({len(cp_points_seen)} points)')
            suffix = ' | ' + ' | '.join(parts) if parts else ''
            self.log(f'Indexed {len(files)} H5-extracted CSV table(s); CP/CA files are classified separately from Other tables{suffix}.')
        except Exception:
            pass
    except Exception as exc:
        try:
            self.log(f'Refresh tree failed: {exc}\n{traceback.format_exc()}')
        except Exception:
            pass


# Add CP/CA to the plot-mode combobox when the browser is constructed without
# altering the stable plotting canvas.
def _v177_add_cp_mode_to_comboboxes(browser):
    try:
        def walk(w):
            yield w
            for ch in w.winfo_children():
                yield from walk(ch)
        for w in walk(browser):
            try:
                if w.winfo_class() == 'TCombobox':
                    vals = list(w.cget('values') or [])
                    if 'Auto' in vals and 'CV / LSV' in vals and 'CP / CA' not in vals:
                        # Put CP/CA near other time-domain/numeric modes.
                        vals.append('CP / CA')
                        w.configure(values=vals)
            except Exception:
                pass
    except Exception:
        pass


