def _v177_paths_for_suggestion(self, text):
    raw = _v177_clean_suggestion_text(text) if '_v177_clean_suggestion_text' in globals() else str(text or '')
    tl = raw.lower()
    if any(k in tl for k in [' cp', 'cp ', 'chronopot', 'chronoamp', 'transient', 'ca ']):
        try:
            files = _v177_all_browser_csv_files(self) if '_v177_all_browser_csv_files' in globals() else sorted([p for p in Path(self.cache_root).rglob('*.csv') if p.is_file()], key=lambda p: str(p).lower())
            points, all_points = _v177_parse_point_values(raw) if '_v177_parse_point_values' in globals() else ([], False)
            def point_ok(p):
                if not points:
                    return True
                pv = _v177_path_point_value(p) if '_v177_path_point_value' in globals() else None
                return pv in points
            cand = [Path(p) for p in files if _v177_is_cp_cache_path(p) and point_ok(p)]
            cand = sorted(cand, key=lambda p: (_v177_path_point_value(p) if '_v177_path_point_value' in globals() else 0, Path(p).name.lower()))
            try:
                self.log(f'Smart Compare matched {len(cand)} CP/CA file(s) for: {raw}')
            except Exception:
                pass
            if all_points:
                return cand
            try:
                maxn = max(1, int(float(self.max_curves_var.get() or 24)))
            except Exception:
                maxn = 24
            return cand[:maxn]
        except Exception:
            pass
    if callable(_v177_PREV_PATHS_FOR_SUGGESTION_CP):
        return _v177_PREV_PATHS_FOR_SUGGESTION_CP(self, text)
    return []


