# ---- FaradaIQ Studio v273 point parser extension for CP filenames ----
# Accept file extensions after the point number, e.g. CP_point_002.csv, so the
# file name wins over parent folders such as CP/point_001/CP_point_002.csv.
def _v177_point_from_filename_first(path):
    p = Path(path)
    name = p.name
    patterns_name = [
        r'(?:^|[_\-\s])(?:cv|eis|drt|cp|ca)[_\-\s]*point[_\-\s]*0*(\d+)(?=[_\-\s\.]|$)',
        r'(?:^|[_\-\s])point[_\-\s]*0*(\d+)(?=[_\-\s\.]|$)',
    ]
    for pat in patterns_name:
        m = re.search(pat, name, flags=re.I)
        if m:
            try:
                return int(m.group(1))
            except Exception:
                pass
    for part in reversed(p.parts):
        pl = str(part).lower()
        if re.search(r'point[_\-\s]*\d+\s*points?\b', pl):
            continue
        for pat in [r'^point[_\-\s]*0*(\d+)$', r'^position[_\-\s]*0*(\d+)$', r'^pos[_\-\s]*0*(\d+)$']:
            m = re.search(pat, pl, flags=re.I)
            if m:
                try:
                    return int(m.group(1))
                except Exception:
                    pass
    s = re.sub(r'point[_\-\s]*\d+\s*points?\b', '', p.as_posix().lower())
    for pat in [r'point[_\-\s]*0*(\d+)(?=[_\-\s\./]|$)', r'position[_\-\s]*0*(\d+)', r'pos[_\-\s]*0*(\d+)']:
        m = re.search(pat, s, flags=re.I)
        if m:
            try:
                return int(m.group(1))
            except Exception:
                pass
    return None


def _v177_path_point_value(path):
    return _v177_point_from_filename_first(path)

# ---- End FaradaIQ Studio v273 point parser extension for CP filenames ----


