def _v177_replace_header_attribution_labels(root):
    """Replace visible main-header attribution labels with the new tagline.

    This is applied only to the main/root GUI, not to the About/Credits dialog.
    """
    try:
        seen = set()
        def walk(w):
            if id(w) in seen:
                return
            seen.add(id(w))
            try:
                txt = str(w.cget('text') or '')
            except Exception:
                txt = ''
            if 'Designed by Venky Prabhakaran' in txt:
                try:
                    w.configure(text=_FARADAIQ_v177_TAGLINE)
                except Exception:
                    pass
            try:
                for c in w.winfo_children():
                    walk(c)
            except Exception:
                pass
        walk(root)
    except Exception:
        pass


