def _v177_add_session_buttons_to_banner(gui):
    """Add Save/Load session buttons to the left of the FaradaIQ session row."""
    if getattr(gui, '_v177_session_row_buttons_added', False):
        return
    try:
        target_frame = None
        first_session_label = None

        def walk(w):
            nonlocal target_frame, first_session_label
            if target_frame is not None:
                return
            try:
                txt = str(w.cget('text') or '')
            except Exception:
                txt = ''
            if txt.startswith('FaradaIQ launch session'):
                first_session_label = w
                target_frame = w.master
                return
            try:
                for c in w.winfo_children():
                    walk(c)
            except Exception:
                pass

        walk(gui)
        if target_frame is None:
            return

        # Avoid duplicates even if later wrappers re-run.
        for child in target_frame.winfo_children():
            try:
                if str(child.cget('text') or '') in {'Save session', 'Load session'}:
                    gui._v177_session_row_buttons_added = True
                    return
            except Exception:
                pass

        btn_save = ttk.Button(target_frame, text='Save session', command=lambda g=gui: _v106_save_main_session_dialog(g) if '_v106_save_main_session_dialog' in globals() else None)
        btn_load = ttk.Button(target_frame, text='Load session', command=lambda g=gui: _v106_load_main_session_dialog(g) if '_v106_load_main_session_dialog' in globals() else None)

        try:
            btn_save.pack(side='left', padx=(0, 4), before=first_session_label)
            btn_load.pack(side='left', padx=(0, 10), before=first_session_label)
        except Exception:
            btn_save.pack(side='left', padx=(0, 4))
            btn_load.pack(side='left', padx=(0, 10))

        try:
            if '_v103_add_tooltip' in globals():
                _v103_add_tooltip(btn_save, 'Save the full FaradaIQ app session: loaded file/folder, output folder, text panels, LLM settings preview, and open browser/Plot-view sessions.')
                _v103_add_tooltip(btn_load, 'Load a saved full FaradaIQ app session and restore browser/Plot-view state when available.')
        except Exception:
            pass

        gui._v177_session_row_buttons_added = True
    except Exception as exc:
        try:
            if hasattr(gui, 'set_status'):
                gui.set_status(f'Could not add v198 session-row buttons: {exc}')
        except Exception:
            pass


