    try:
        for delay in (300, 900, 1800, 3200):
            self.after(delay, lambda g=self: (_v177_replace_header_attribution_labels(g), _v177_add_session_buttons_to_banner(g)))
    except Exception:
        try:
            _v177_replace_header_attribution_labels(self)
            _v177_add_session_buttons_to_banner(self)
        except Exception:
            pass


