# ---- FaradaIQ Studio v273 rollback-base session persistence + split/join removal patch ----
# Built from the clean rollback base. This patch removes the main-GUI
# split/join repair button and adds durable Save session / Load session buttons
# on the FaradaIQ launch-session row. The saved JSON is path-based and restores
# the main GUI fields/text, current analysis root/summary, LLM/settings preview,
# and open Data Browser / canonical H5 browser sessions when their source files
# still exist.

try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v177_is_tk_var(obj):
    try:
        return hasattr(obj, 'get') and hasattr(obj, 'set') and obj.__class__.__module__.startswith('tkinter')
    except Exception:
        return False


def _v177_safe_get(obj, default=''):
    try:
        val = obj.get()
        if val is None:
            return default
        return val
    except Exception:
        return default


def _v177_safe_set(obj, value):
    try:
        obj.set(value)
        return True
    except Exception:
        return False


def _v177_get_text(widget):
    try:
        return widget.get('1.0', 'end-1c')
    except Exception:
        try:
            return widget.get()
        except Exception:
            return ''


def _v177_set_text(widget, value):
    try:
        widget.configure(state='normal')
    except Exception:
        pass
    try:
        widget.delete('1.0', 'end')
        widget.insert('1.0', value or '')
        return True
    except Exception:
        try:
            widget.delete(0, 'end')
            widget.insert(0, value or '')
            return True
        except Exception:
            return False


def _v177_json_safe(obj):
    try:
        json.dumps(obj)
        return obj
    except Exception:
        pass
    if isinstance(obj, dict):
        return {str(k): _v177_json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_v177_json_safe(v) for v in obj]
    if isinstance(obj, Path):
        return str(obj)
    try:
        import numpy as _np
        if isinstance(obj, _np.generic):
            return obj.item()
        if isinstance(obj, _np.ndarray):
            return obj.tolist()
    except Exception:
        pass
    return str(obj)


def _v177_stamp():
    try:
        return datetime.now().strftime('%Y%m%d_%H%M%S')
    except Exception:
        import time as _time
        return _time.strftime('%Y%m%d_%H%M%S')


def _v177_session_dir(gui=None):
    try:
        out = _v177_safe_get(getattr(gui, 'output_dir_var', None), '') if gui is not None else ''
        root = Path(out or '.').expanduser().resolve()
    except Exception:
        root = Path('.').resolve()
    d = root / 'FaradaIQ_saved_sessions'
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return d


def _v177_collect_var_attrs(obj):
    out = {}
    try:
        for name, val in sorted(vars(obj).items()):
            if name.startswith('_'):
                continue
            if name.endswith('_var') or _v177_is_tk_var(val):
                try:
                    out[name] = _v177_json_safe(val.get())
                except Exception:
                    pass
    except Exception:
        pass
    return out


def _v177_apply_var_attrs(obj, values):
    for name, val in (values or {}).items():
        try:
            target = getattr(obj, name, None)
            if target is not None and hasattr(target, 'set'):
                target.set(val)
        except Exception:
            pass


def _v177_collect_main_texts(gui):
    text_map = {}
    for key, attr in [
        ('experimental_description', 'desc_text'),
        ('session_summary', 'summary_text'),
        ('data_structure_preview', 'structure_text'),
        ('current_ai_prompt', 'prompt_text'),
        ('browser_log', 'log_text'),
    ]:
        try:
            widget = getattr(gui, attr, None)
            if widget is not None:
                text_map[key] = _v177_get_text(widget)
        except Exception:
            pass
    return text_map


def _v177_apply_main_texts(gui, text_map):
    mapping = {
        'experimental_description': 'desc_text',
        'session_summary': 'summary_text',
        'data_structure_preview': 'structure_text',
        'current_ai_prompt': 'prompt_text',
        'browser_log': 'log_text',
    }
    for key, attr in mapping.items():
        try:
            if key in (text_map or {}) and hasattr(gui, attr):
                _v177_set_text(getattr(gui, attr), text_map.get(key, ''))
        except Exception:
            pass


def _v177_collect_collection_state(gui):
    out = {}
    try:
        col = getattr(gui, 'collection', None)
        if col is None:
            return out
        for name in ('source_path', 'vendor', 'parser_name', 'base_name'):
            try:
                val = getattr(col, name, None)
                if val is not None:
                    out[name] = str(val)
            except Exception:
                pass
        try:
            entries = getattr(col, 'entries', []) or []
            out['entries_count'] = len(entries)
            out['techniques'] = sorted({str(getattr(e, 'technique', '') or '') for e in entries if getattr(e, 'technique', '')})
        except Exception:
            pass
    except Exception:
        pass
    return out


def _v177_find_open_browsers(root):
    out, seen = [], set()
    def walk(w):
        if id(w) in seen:
            return
        seen.add(id(w))
        try:
            is_browser = (
                hasattr(w, 'plot_view_list')
                or hasattr(w, '_v69_plot_views')
                or hasattr(w, 'cache_root')
                or hasattr(w, 'h5_path')
                or w.__class__.__name__ in {'FaradaIQH5Browser', 'FaradaIQDataBrowser'}
            )
            if is_browser and w is not root:
                out.append(w)
        except Exception:
            pass
        try:
            for c in w.winfo_children():
                walk(c)
        except Exception:
            pass
    try:
        walk(root)
    except Exception:
        pass
    # De-duplicate while preserving order.
    final, ids = [], set()
    for b in out:
        if id(b) not in ids:
            ids.add(id(b))
            final.append(b)
    return final


def _v177_collect_plot_views(browser):
    views = []
    for attr in ('_v69_plot_views', 'plot_views', '_plot_views'):
        try:
            vals = getattr(browser, attr, None)
            if vals:
                for v in vals:
                    vv = dict(v) if isinstance(v, dict) else {'value': str(v)}
                    # Large raw arrays are not embedded; paths/labels/settings are retained.
                    if 'curves' in vv:
                        curves = []
                        for c in vv.get('curves', []) or []:
                            if isinstance(c, dict):
                                curves.append({
                                    'path': str(c.get('path', '')),
                                    'label': str(c.get('label', '')),
                                    'xcol': str(c.get('xcol', c.get('x_column', ''))),
                                    'ycol': str(c.get('ycol', c.get('y_column', ''))),
                                    'n_points': int(len(c.get('x', []))) if hasattr(c.get('x', []), '__len__') else 0,
                                })
                        vv['curves'] = curves
                    if 'paths' in vv:
                        vv['paths'] = [str(p) for p in vv.get('paths', []) or []]
                    views.append(_v177_json_safe(vv))
                break
        except Exception:
            pass
    return views


def _v177_collect_browser_session(browser):
    cls = browser.__class__.__name__
    payload = {
        'schema': 'faradaiq_open_browser_session_v177',
        'class_name': cls,
        'base_name': str(getattr(browser, 'base_name', '')),
        'analysis_root': str(getattr(browser, 'analysis_root', '')),
        'analyzed_root': str(getattr(browser, 'analyzed_root', '')),
        'cache_root': str(getattr(browser, 'cache_root', '')),
        'h5_path': str(getattr(browser, 'h5_path', '') or ''),
        'json_path': str(getattr(browser, 'json_path', '') or ''),
        'cache_info': _v177_json_safe(getattr(browser, 'cache_info', {}) or {}),
        'vars': _v177_collect_var_attrs(browser),
        'plot_views': _v177_collect_plot_views(browser),
        'last_plot_paths': [str(p) for p in getattr(browser, 'last_plot_paths', []) or []],
    }
    try:
        if hasattr(browser, 'suggestion_list'):
            payload['smart_compare_suggestions'] = [str(browser.suggestion_list.get(i)) for i in range(browser.suggestion_list.size())]
    except Exception:
        pass
    try:
        if hasattr(browser, 'smart_txn_list'):
            payload['smart_compare_transactions_visible'] = [str(browser.smart_txn_list.get(i)) for i in range(browser.smart_txn_list.size())]
    except Exception:
        pass
    return _v177_json_safe(payload)


def _v177_collect_full_session(gui):
    payload = {
        'schema': 'faradaiq_main_session_v199',
        'app': 'FaradaIQ Studio',
        'version': "v273",
        'created': _v177_stamp(),
        'launch_session': _v753_launch_context() if '_v753_launch_context' in globals() else {},
        'main_vars': _v177_collect_var_attrs(gui),
        'main_texts': _v177_collect_main_texts(gui),
        'current_summary': _v177_json_safe(getattr(gui, 'current_summary', None)),
        'current_analysis_root': str(getattr(gui, 'current_analysis_root', '') or ''),
        'collection_state': _v177_collect_collection_state(gui),
        'open_browser_sessions': [],
        'notes': 'Path-based full FaradaIQ session. Restores GUI fields, text panels, output/input paths, current summary/root, and browser/Plot-view state when files still exist. Large arrays/images are not embedded.',
    }
    try:
        for b in _v177_find_open_browsers(gui):
            try:
                payload['open_browser_sessions'].append(_v177_collect_browser_session(b))
            except Exception as exc:
                payload['open_browser_sessions'].append({'error': str(exc), 'class_name': b.__class__.__name__})
    except Exception:
        pass
    return _v177_json_safe(payload)


def _v177_restore_browser(gui, bp):
    if not isinstance(bp, dict):
        return None
    cls = str(bp.get('class_name', ''))
    try:
        # Prefer canonical H5 browser when H5/cache data are present.
        cache_info = bp.get('cache_info') or {}
        if not cache_info:
            cache_info = {}
            for key in ('cache_root', 'h5_path', 'json_path'):
                val = bp.get(key)
                if val:
                    cache_info[key] = val
        has_h5 = bool(cache_info.get('h5_path') or bp.get('h5_path') or cache_info.get('cache_root') or bp.get('cache_root'))
        if ('H5' in cls or has_h5) and 'FaradaIQH5Browser' in globals():
            # Make missing cache_info as robust as possible.
            if bp.get('h5_path') and not cache_info.get('h5_path'):
                cache_info['h5_path'] = bp.get('h5_path')
            if bp.get('json_path') and not cache_info.get('json_path'):
                cache_info['json_path'] = bp.get('json_path')
            if bp.get('cache_root') and not cache_info.get('cache_root'):
                cache_info['cache_root'] = bp.get('cache_root')
            b = FaradaIQH5Browser(gui, cache_info=cache_info, base_name=bp.get('base_name') or None)
        elif 'FaradaIQDataBrowser' in globals():
            ar = bp.get('analysis_root') or bp.get('analyzed_root') or None
            b = FaradaIQDataBrowser(gui, analysis_root=ar, base_name=bp.get('base_name') or None)
        else:
            return None
        try:
            _v177_apply_var_attrs(b, bp.get('vars') or {})
        except Exception:
            pass
        try:
            views = bp.get('plot_views') or []
            if views and hasattr(b, '_v69_plot_views'):
                b._v69_plot_views = views
                if hasattr(b, 'plot_view_list'):
                    b.plot_view_list.delete(0, 'end')
                    for i, v in enumerate(views, 1):
                        name = v.get('name') if isinstance(v, dict) else None
                        b.plot_view_list.insert('end', name or f'{i:02d} restored plot/view')
        except Exception:
            pass
        try:
            b.after(500, b.refresh_tree)
        except Exception:
            pass
        return b
    except Exception as exc:
        try:
            if hasattr(gui, 'set_status'):
                gui.set_status(f'Could not restore browser from session: {exc}')
        except Exception:
            pass
        return None


def _v177_apply_full_session(gui, payload, open_browsers=True):
    if not isinstance(payload, dict):
        return False
    try:
        _v177_apply_var_attrs(gui, payload.get('main_vars') or {})
        _v177_apply_main_texts(gui, payload.get('main_texts') or {})
        try:
            gui.current_summary = payload.get('current_summary')
        except Exception:
            pass
        try:
            gui.current_analysis_root = payload.get('current_analysis_root') or getattr(gui, 'current_analysis_root', '')
        except Exception:
            pass
        # Backward-compatible application of previous v106 sessions too.
        if payload.get('schema') == 'faradaiq_main_session_v106' and '_v106_apply_main_session' in globals():
            try:
                _v106_apply_main_session(gui, payload, open_browser=False)
            except Exception:
                pass
        if open_browsers:
            for bp in payload.get('open_browser_sessions', []) or []:
                _v177_restore_browser(gui, bp)
        try:
            if hasattr(gui, 'set_status'):
                gui.set_status('Loaded FaradaIQ session JSON. Main state and browser state restored where source paths exist.')
        except Exception:
            pass
        return True
    except Exception:
        return False


def _v177_save_full_session_dialog(gui):
    try:
        from tkinter import filedialog, messagebox
        stem = 'FaradaIQ_session'
        try:
            src = Path(_v177_safe_get(getattr(gui, 'file_var', None), '')).stem
            if src:
                stem = _v35_safe_name(src) if '_v35_safe_name' in globals() else src
        except Exception:
            pass
        default = f'{stem}_{_v177_stamp()}.faradaiq_session.json'
        path = filedialog.asksaveasfilename(
            title='Save full FaradaIQ session',
            initialdir=str(_v177_session_dir(gui)),
            initialfile=default,
            defaultextension='.json',
            filetypes=[('FaradaIQ session JSON', '*.faradaiq_session.json'), ('FaradaIQ main session JSON', '*.faradaiq_main_session.json'), ('JSON', '*.json'), ('All files', '*.*')],
            parent=gui,
        )
        if not path:
            return None
        payload = _v177_collect_full_session(gui)
        Path(path).write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
        try:
            if hasattr(gui, 'set_status'):
                gui.set_status(f'Saved full FaradaIQ session: {Path(path).name}')
            if '_v753_track_event' in globals():
                _v753_track_event('full_session_saved', {'path': str(path), 'schema': payload.get('schema')})
        except Exception:
            pass
        return Path(path)
    except Exception as exc:
        try:
            messagebox.showerror('Save FaradaIQ session failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception:
            pass
        return None


def _v177_load_full_session_dialog(gui):
    try:
        from tkinter import filedialog, messagebox
        path = filedialog.askopenfilename(
            title='Load FaradaIQ session JSON',
            initialdir=str(_v177_session_dir(gui)),
            filetypes=[('FaradaIQ session JSON', '*.faradaiq_session.json *.faradaiq_main_session.json'), ('JSON', '*.json'), ('All files', '*.*')],
            parent=gui,
        )
        if not path:
            return None
        payload = json.loads(Path(path).read_text(encoding='utf-8'))
        ok = _v177_apply_full_session(gui, payload, open_browsers=True)
        if ok:
            try:
                messagebox.showinfo('FaradaIQ session loaded', f'Loaded session:\n{path}\n\nInput/output paths, text panels, summaries, and browser Plot/view state were restored when available.', parent=gui)
            except Exception:
                pass
            return Path(path)
    except Exception as exc:
        try:
            messagebox.showerror('Load FaradaIQ session failed', f'{exc}\n\n{traceback.format_exc()}', parent=gui)
        except Exception:
            pass
        return None


def _v177_remove_split_join_buttons(gui):
    """Remove main-GUI split/join/HEKA-repair button requested for rollback build."""
    removed = 0
    def walk(w):
        nonlocal removed
        try:
            kids = list(w.winfo_children())
        except Exception:
            kids = []
        for c in kids:
            txt = ''
            try:
                txt = str(c.cget('text') or '')
            except Exception:
                pass
            low = txt.lower()
            if ('split heka' in low) or ('heka file repair' in low) or ('split-file joiner' in low) or ('split/join' in low):
                try:
                    c.destroy()
                    removed += 1
                    continue
                except Exception:
                    try:
                        c.pack_forget()
                        c.grid_forget()
                        removed += 1
                        continue
                    except Exception:
                        pass
            walk(c)
    try:
        walk(gui)
    except Exception:
        pass
    try:
        gui._v177_split_join_buttons_removed = True
    except Exception:
        pass
    return removed


def _v177_find_session_banner_frame(gui):
    try:
        frame = getattr(gui, '_v753_session_banner_frame', None)
        if frame is not None and frame.winfo_exists():
            return frame
    except Exception:
        pass
    found = None
    def walk(w):
        nonlocal found
        if found is not None:
            return
        try:
            texts = []
            for c in w.winfo_children():
                try:
                    texts.append(str(c.cget('text') or ''))
                except Exception:
                    pass
            if any(t.startswith('FaradaIQ launch session') for t in texts) and any(t == 'Open tracking folder' for t in texts):
                found = w
                return
            for c in w.winfo_children():
                walk(c)
        except Exception:
            pass
    try:
        walk(gui)
    except Exception:
        pass
    return found


def _v177_add_session_buttons_to_launch_row(gui):
    """v216: keep exactly one canonical Save Session / Load Session pair."""
    frame = _v177_find_session_banner_frame(gui)
    if frame is None:
        return False
    inserter = globals().get('_v177_insert_main_session_buttons')
    if callable(inserter):
        return bool(inserter(gui, frame))
    return False


def _v177_apply_main_window_cleanup(gui):
    try:
        _v177_remove_split_join_buttons(gui)
    except Exception:
        pass
    try:
        _v177_add_session_buttons_to_launch_row(gui)
    except Exception:
        pass


