# ---- FaradaIQ Studio v273 Auto Save session checkbox + background autosave patch ----
# Adds an Auto Save session checkbox on the FaradaIQ launch-session row.
# It is enabled by default and begins saving after Load + inspect. The autosave
# uses the same full-session JSON schema as the manual Save session button.

_FARADAIQ_v177_AUTOSAVE_INTERVAL_MS = 30000


def _v177_autosave_dir(gui):
    try:
        base = Path(_v177_session_dir(gui))
    except Exception:
        base = Path.cwd() / 'FaradaIQ_sessions'
    d = base / 'autosave'
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return d


def _v177_autosave_path(gui):
    try:
        existing = getattr(gui, '_v177_auto_save_path', None)
        if existing:
            p = Path(existing)
            try:
                p.parent.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            return p
    except Exception:
        pass
    stem = 'FaradaIQ_autosave'
    try:
        src = _v177_safe_get(getattr(gui, 'file_var', None), '')
        if src:
            stem = (_v35_safe_name(Path(src).stem) if '_v35_safe_name' in globals() else Path(src).stem) + '_autosave'
    except Exception:
        pass
    p = _v177_autosave_dir(gui) / f'{stem}.faradaiq_session.json'
    try:
        gui._v177_auto_save_path = str(p)
    except Exception:
        pass
    return p


def _v177_auto_save_enabled(gui):
    try:
        if not hasattr(gui, 'auto_save_session_var'):
            gui.auto_save_session_var = tk.BooleanVar(value=True)
        return bool(gui.auto_save_session_var.get())
    except Exception:
        return True


def _v177_write_autosave_session(gui, reason='timer'):
    try:
        if not _v177_auto_save_enabled(gui):
            return None
        payload = _v177_collect_full_session(gui)
        try:
            payload.setdefault('auto_save_session', {
                'enabled': _v177_auto_save_enabled(gui),
                'interval_ms': int(_FARADAIQ_v177_AUTOSAVE_INTERVAL_MS),
                'auto_save_path': str(_v177_autosave_path(gui)),
            })
        except Exception:
            pass
        payload['autosave'] = True
        payload['autosave_reason'] = str(reason)
        payload['autosave_interval_ms'] = int(_FARADAIQ_v177_AUTOSAVE_INTERVAL_MS)
        payload['autosave_saved_at'] = _v177_stamp()
        p = _v177_autosave_path(gui)
        tmp = p.with_suffix(p.suffix + '.tmp')
        tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
        try:
            tmp.replace(p)
        except Exception:
            p.write_text(tmp.read_text(encoding='utf-8', errors='replace'), encoding='utf-8')
            try:
                tmp.unlink()
            except Exception:
                pass
        try:
            gui._v177_last_auto_save_path = str(p)
            gui._v177_last_auto_save_time = payload['autosave_saved_at']
        except Exception:
            pass
        try:
            if hasattr(gui, 'status_var'):
                cur = str(gui.status_var.get() or '')
                if 'running' not in cur.lower() and 'export' not in cur.lower():
                    gui.status_var.set(f'Auto-saved session: {p.name}')
        except Exception:
            pass
        return p
    except Exception as exc:
        try:
            gui._v177_last_auto_save_error = str(exc)
            if hasattr(gui, 'status_var'):
                gui.status_var.set(f'Auto-save session failed: {exc}')
        except Exception:
            pass
        return None


def _v177_autosave_tick(gui):
    try:
        gui._v177_autosave_after_id = None
    except Exception:
        pass
    try:
        if _v177_auto_save_enabled(gui):
            _v177_write_autosave_session(gui, reason='timer')
            try:
                gui._v177_autosave_after_id = gui.after(_FARADAIQ_v177_AUTOSAVE_INTERVAL_MS, lambda g=gui: _v177_autosave_tick(g))
            except Exception:
                pass
    except Exception:
        pass


def _v177_start_autosave_session(gui, immediate=True, reason='start'):
    try:
        if not _v177_auto_save_enabled(gui):
            return False
        try:
            old = getattr(gui, '_v177_autosave_after_id', None)
            if old:
                gui.after_cancel(old)
        except Exception:
            pass
        if immediate:
            _v177_write_autosave_session(gui, reason=reason)
        try:
            gui._v177_autosave_after_id = gui.after(_FARADAIQ_v177_AUTOSAVE_INTERVAL_MS, lambda g=gui: _v177_autosave_tick(g))
        except Exception:
            pass
        return True
    except Exception:
        return False


def _v177_stop_autosave_session(gui):
    try:
        old = getattr(gui, '_v177_autosave_after_id', None)
        if old:
            gui.after_cancel(old)
        gui._v177_autosave_after_id = None
    except Exception:
        pass


def _v177_toggle_autosave_session(gui):
    try:
        if _v177_auto_save_enabled(gui):
            _v177_start_autosave_session(gui, immediate=True, reason='checkbox_on')
        else:
            _v177_stop_autosave_session(gui)
            try:
                if hasattr(gui, 'status_var'):
                    gui.status_var.set('Auto Save session disabled.')
            except Exception:
                pass
    except Exception:
        pass


def _v177_add_autosave_checkbox_to_launch_row(gui):
    try:
        if not hasattr(gui, 'auto_save_session_var'):
            gui.auto_save_session_var = tk.BooleanVar(value=True)
    except Exception:
        pass
    frame = _v177_find_session_banner_frame(gui) if '_v177_find_session_banner_frame' in globals() else None
    if frame is None:
        return False
    try:
        for c in frame.winfo_children():
            try:
                if str(c.cget('text') or '') == 'Auto Save session':
                    return True
            except Exception:
                pass
        use_grid = False
        try:
            use_grid = any(bool(c.grid_info()) for c in frame.winfo_children())
        except Exception:
            use_grid = False
        if use_grid:
            # Put checkbox after Save/Load when possible, shifting later buttons right.
            for c in frame.winfo_children():
                try:
                    info = c.grid_info()
                    col = int(info.get('column', 0))
                    if col >= 4:
                        c.grid_configure(column=col + 1)
                except Exception:
                    pass
            ttk.Checkbutton(
                frame,
                text='Auto Save session',
                variable=gui.auto_save_session_var,
                command=lambda g=gui: _v177_toggle_autosave_session(g),
            ).grid(row=0, column=4, sticky='e', padx=(8, 0))
        else:
            # Pack mode row: add near Save/Load on same row.
            ttk.Checkbutton(
                frame,
                text='Auto Save session',
                variable=gui.auto_save_session_var,
                command=lambda g=gui: _v177_toggle_autosave_session(g),
            ).pack(side='right', padx=(10, 0))
        try:
            if '_v103_add_tooltip' in globals():
                for c in frame.winfo_children():
                    try:
                        if str(c.cget('text') or '') == 'Auto Save session':
                            _v103_add_tooltip(c, 'Enabled by default. After Load + inspect, FaradaIQ saves the full session JSON every 30 seconds in FaradaIQ_sessions/autosave so you can recover and continue processing.')
                    except Exception:
                        pass
        except Exception:
            pass
        gui._v177_autosave_checkbox_added = True
        return True
    except Exception as exc:
        try:
            if hasattr(gui, 'set_status'):
                gui.set_status(f'Could not add Auto Save session checkbox: {exc}')
        except Exception:
            pass
        return False


# Upgrade existing cleanup hook so it also adds Auto Save session checkbox.
