def _v177_load_and_inspect_with_autosave(self, *args, **kwargs):
    result = None
    exc = None
    try:
        if callable(_v177_PREV_LOAD_AND_INSPECT_AUTOSAVE):
            result = _v177_PREV_LOAD_AND_INSPECT_AUTOSAVE(self, *args, **kwargs)
        else:
            result = None
    except Exception as e:
        exc = e
    try:
        if not hasattr(self, 'auto_save_session_var'):
            self.auto_save_session_var = tk.BooleanVar(value=True)
        # User requested default-on when Load + inspect is used.
        try:
            if self.auto_save_session_var.get() in (None, ''):
                self.auto_save_session_var.set(True)
        except Exception:
            pass
        if bool(self.auto_save_session_var.get()):
            _v177_start_autosave_session(self, immediate=True, reason='load_and_inspect')
    except Exception:
        pass
    if exc is not None:
        raise exc
    return result


