def _v177_apply_full_session(gui, payload, open_browsers=True):
    ok = _v177_PREV_APPLY_FULL_SESSION_AUTOSAVE(gui, payload, open_browsers=open_browsers) if callable(_v177_PREV_APPLY_FULL_SESSION_AUTOSAVE) else False
    try:
        meta = payload.get('auto_save_session') or {}
        if not hasattr(gui, 'auto_save_session_var'):
            gui.auto_save_session_var = tk.BooleanVar(value=True)
        gui.auto_save_session_var.set(bool(meta.get('enabled', True)))
        if meta.get('auto_save_path'):
            gui._v177_auto_save_path = str(meta.get('auto_save_path'))
        _v177_add_autosave_checkbox_to_launch_row(gui)
        if gui.auto_save_session_var.get():
            _v177_start_autosave_session(gui, immediate=True, reason='load_session')
    except Exception:
        pass
    return ok


