# ---- FaradaIQ Studio v273 premium About/Credits dialog + standard icon patch ----
# Restores the usual static FaradaIQ icon in the About / Credits dialog.
# No animated About-specific asset is loaded or packaged in v198.


def _v177_about_icon_path():
    try:
        base = Path(__file__).resolve().parent
        for name in ('faradaiq_icon.png', 'faradaiq_clean_icon.png', 'electrochem_bridge_icon.png'):
            p = base / name
            if p.exists():
                return p
    except Exception:
        pass
    return None


def _v177_attach_about_static_icon(label, owner, size=112):
    """Attach the usual static FaradaIQ icon to the About/Credits dialog."""
    icon_path = _v177_about_icon_path()
    if icon_path is None:
        return False
    try:
        try:
            from PIL import Image, ImageTk
            im = Image.open(icon_path)
            im.thumbnail((int(size), int(size)))
            photo = ImageTk.PhotoImage(im)
        except Exception:
            photo = tk.PhotoImage(file=str(icon_path))
            try:
                sub = max(1, int(max(photo.width(), photo.height()) // int(size)))
                if sub > 1:
                    photo = photo.subsample(sub, sub)
            except Exception:
                pass
        label.configure(image=photo)
        owner._v177_about_logo = photo
        return True
    except Exception:
        return False


