# ---- FaradaIQ Studio v273 main-GUI Save/Load Session restoration patch ----
# User request: put the Save Session and Load Session controls back on the main GUI.
# This patch attaches the buttons directly to the launch-session banner builder, so
# the controls survive banner rebuilds instead of depending only on delayed scans.

try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v177_text_of(widget):
    try:
        return str(widget.cget('text') or '')
    except Exception:
        return ''


def _v177_find_live_session_banner_frame(gui):
    """Find the live FaradaIQ launch-session banner frame in the main GUI."""
    try:
        frame = getattr(gui, '_v753_session_banner_frame', None)
        if frame is not None and frame.winfo_exists():
            return frame
    except Exception:
        pass
    found = None
    def walk(w):
        nonlocal found
        if found is not None:
            return
        try:
            kids = list(w.winfo_children())
        except Exception:
            kids = []
        texts = [_v177_text_of(c) for c in kids]
        try:
            if (
                any(t.startswith('FaradaIQ launch session') for t in texts)
                or any(t.startswith('Tracking only:') for t in texts)
            ) and (
                any(t == 'Open tracking folder' for t in texts)
                or any(t == 'Copy ID' for t in texts)
            ):
                found = w
                return
        except Exception:
            pass
        for c in kids:
            walk(c)
    try:
        walk(gui)
    except Exception:
        pass
    return found


def _v177_save_session_from_button(gui):
    try:
        import time as _time
        if _time.monotonic() < float(getattr(gui, '_v228_session_actions_ready_at', 0.0) or 0.0):
            return None
    except Exception:
        pass
    try:
        if '_v177_save_full_session_dialog' in globals():
            return _v177_save_full_session_dialog(gui)
        if '_v106_save_main_session_dialog' in globals():
            return _v106_save_main_session_dialog(gui)
    except Exception as exc:
        try:
            messagebox.showerror('Save FaradaIQ session failed', str(exc), parent=gui)
        except Exception:
            pass
    return None


def _v177_load_session_from_button(gui):
    try:
        import time as _time
        if _time.monotonic() < float(getattr(gui, '_v228_session_actions_ready_at', 0.0) or 0.0):
            return None
    except Exception:
        pass
    try:
        if '_v177_load_full_session_dialog' in globals():
            return _v177_load_full_session_dialog(gui)
        if '_v106_load_main_session_dialog' in globals():
            return _v106_load_main_session_dialog(gui)
    except Exception as exc:
        try:
            messagebox.showerror('Load FaradaIQ session failed', str(exc), parent=gui)
        except Exception:
            pass
    return None


def _v177_remove_old_session_buttons(frame):
    """Remove lower-case or misplaced session buttons before inserting the v198 pair."""
    removed = 0
    try:
        for c in list(frame.winfo_children()):
            txt = _v177_text_of(c).strip().lower()
            if txt in {'save session', 'load session'}:
                try:
                    c.destroy()
                    removed += 1
                except Exception:
                    try:
                        c.grid_forget(); c.pack_forget(); removed += 1
                    except Exception:
                        pass
    except Exception:
        pass
    return removed


def _v177_banner_uses_grid(frame):
    try:
        return any(bool(c.grid_info()) for c in frame.winfo_children())
    except Exception:
        return False


def _v177_insert_main_session_buttons(gui, frame=None):
    """Always place Save Session / Load Session on the main launch-session row."""
    try:
        root = gui.winfo_toplevel() if hasattr(gui, 'winfo_toplevel') else gui
    except Exception:
        root = gui
    if frame is None:
        frame = _v177_find_live_session_banner_frame(root)
    if frame is None:
        return False

    try:
        # If exact v198 controls are already present on this frame, refresh commands and stop.
        exact = {}
        for c in frame.winfo_children():
            txt = _v177_text_of(c)
            if txt in {'Save Session', 'Load Session'}:
                exact[txt] = c
        if 'Save Session' in exact and 'Load Session' in exact:
            # Remove every duplicate lower-case or repeated session button while
            # preserving one canonical pair on the launch-session row.
            keep = {exact['Save Session'], exact['Load Session']}
            for child in list(frame.winfo_children()):
                try:
                    if child not in keep and _v177_text_of(child).strip().lower() in {'save session', 'load session'}:
                        child.destroy()
                except Exception:
                    pass
            try:
                exact['Save Session'].configure(command=lambda g=root: _v177_save_session_from_button(g))
                exact['Load Session'].configure(command=lambda g=root: _v177_load_session_from_button(g))
            except Exception:
                pass
            try:
                root._v177_main_session_buttons_present = True
            except Exception:
                pass
            return True
    except Exception:
        pass

    _v177_remove_old_session_buttons(frame)

    try:
        btn_save = ttk.Button(frame, text='Save Session', command=lambda g=root: _v177_save_session_from_button(g))
        btn_load = ttk.Button(frame, text='Load Session', command=lambda g=root: _v177_load_session_from_button(g))
    except Exception:
        return False

    try:
        if _v177_banner_uses_grid(frame):
            # Existing row normally uses: 0 title, 1 tracking path, 2 Open folder, 3 Copy ID.
            # Shift action buttons right and insert session controls at columns 2 and 3.
            for c in frame.winfo_children():
                if c in (btn_save, btn_load):
                    continue
                try:
                    info = c.grid_info()
                    if not info:
                        continue
                    row = int(info.get('row', 0))
                    col = int(info.get('column', 0))
                    if row == 0 and col >= 2:
                        c.grid_configure(column=col + 2)
                    elif row == 1:
                        # Status row spans all controls. Keep it spanning the wider row.
                        try:
                            span = int(info.get('columnspan', 1))
                            if span >= 4:
                                c.grid_configure(columnspan=span + 2)
                        except Exception:
                            pass
                except Exception:
                    pass
            try:
                frame.columnconfigure(2, weight=0)
                frame.columnconfigure(3, weight=0)
                frame.columnconfigure(4, weight=0)
                frame.columnconfigure(5, weight=0)
            except Exception:
                pass
            btn_save.grid(row=0, column=2, sticky='e', padx=(4, 0), pady=(0, 2))
            btn_load.grid(row=0, column=3, sticky='e', padx=(4, 0), pady=(0, 2))
        else:
            # Fallback for pack-managed banners: place the buttons on the same row,
            # immediately before the tracking-folder controls when Tk allows it.
            open_btn = None
            copy_btn = None
            for c in frame.winfo_children():
                txt = _v177_text_of(c)
                if txt == 'Open tracking folder':
                    open_btn = c
                elif txt == 'Copy ID':
                    copy_btn = c
            if open_btn is not None:
                try:
                    btn_load.pack(side='right', padx=(5, 0), before=open_btn)
                    btn_save.pack(side='right', padx=(5, 0), before=btn_load)
                except Exception:
                    btn_load.pack(side='right', padx=(5, 0))
                    btn_save.pack(side='right', padx=(5, 0))
            elif copy_btn is not None:
                try:
                    btn_load.pack(side='right', padx=(5, 0), before=copy_btn)
                    btn_save.pack(side='right', padx=(5, 0), before=btn_load)
                except Exception:
                    btn_load.pack(side='right', padx=(5, 0))
                    btn_save.pack(side='right', padx=(5, 0))
            else:
                btn_save.pack(side='left', padx=(8, 0))
                btn_load.pack(side='left', padx=(5, 0))

        try:
            if '_v103_add_tooltip' in globals():
                _v103_add_tooltip(btn_save, 'Save the full FaradaIQ session JSON: input/output paths, text panels, current summary, analysis root, open browser states, and Plot/view lists.')
                _v103_add_tooltip(btn_load, 'Load a saved FaradaIQ session JSON and restore paths, text panels, summaries, browser state, and Plot/view lists.')
        except Exception:
            pass
        try:
            root._v177_main_session_buttons_present = True
        except Exception:
            pass
        return True
    except Exception as exc:
        try:
            if hasattr(root, 'set_status'):
                root.set_status(f'Could not add Save Session / Load Session buttons: {exc}')
        except Exception:
            pass
        return False


