# ---- FaradaIQ Studio v273 rollback-stable parser-output patch ----
# User request: roll back to stable v178 behavior and keep the original pySECCM parser
# outputs as the primary analysis result.  v198 intentionally avoids the experimental
# v179-v185 lightweight/custom EIS figure path.  Exports should generate the same
# *_for_plotting_analysis/data layout used by v178, then run pySECCM parse_CV.py,
# parse_EIS.py, parse_IV.py, parse_OCP.py and DRT where matching files exist.
# For EIS datasets with two EIS spectra per point, every *_fullEIS*.txt file is
# queued separately so pySECCM creates parser-native Figures/<fullEIS-stem>/... folders
# for method 1 and method 2 rather than only preparing simplified CSV/overlay files.
APP_TITLE = "FaradaIQ Studio v273"


def _v198_env_auto_parser_default():
    try:
        val = str(os.environ.get('FARADAIQ_AUTO_RUN_PARSER_AFTER_EXPORT', '')).strip().lower()
        if val in {'0', 'false', 'no', 'off', 'disable', 'disabled'}:
            return False
    except Exception:
        pass
    return True


def _v198_all_eis_files_for_data_dir(data_dir):
    """Return every parser-native fullEIS text file in the v178 data folder."""
    try:
        d = Path(data_dir)
        detected = _v19_detect_pyseccm_files(d) if '_v19_detect_pyseccm_files' in globals() else {}
        eis = list(detected.get('eis', []) or [])
        if not eis:
            eis = sorted(d.glob('*fullEIS*.txt'), key=lambda p: [int(t) if t.isdigit() else t.lower() for t in re.split(r'(\d+)', p.name)])
        return [Path(p) for p in eis if Path(p).is_file()]
    except Exception:
        try:
            return sorted(Path(data_dir).glob('*fullEIS*.txt'), key=lambda p: p.name.lower())
        except Exception:
            return []


# Make the export checkbox default to ON so parser outputs are produced like the
# known-good v178 exported folders.  The checkbox is still visible and can be unchecked.
try:
    _SESSION_READER_GUI_V187_PREV_BUILD_UI = SessionReaderGUI._build_ui
    def _session_reader_gui_v198_build_ui(self):
        try:
            if not hasattr(self, 'auto_run_pyseccm_after_export_var'):
                self.auto_run_pyseccm_after_export_var = tk.BooleanVar(value=_v198_env_auto_parser_default())
        except Exception:
            pass
        _SESSION_READER_GUI_V187_PREV_BUILD_UI(self)
        try:
            # New sessions default to parser-on; keep it user-toggleable after the GUI is built.
            if not hasattr(self, '_v198_auto_parser_default_applied'):
                self._v198_auto_parser_default_applied = True
                self.auto_run_pyseccm_after_export_var.set(_v198_env_auto_parser_default())
        except Exception:
            pass
    SessionReaderGUI._build_ui = _session_reader_gui_v198_build_ui
except Exception:
    pass


# Patch the dedicated parser-tools window so EIS runs every fullEIS file, not just the
# first detected file.  This keeps two-EIS-per-point line scans parser-native.
try:
    def _v198_seccm_runner_run_eis(self):
        self.detect_files()
        self._ensure_style()
        script = self._script('parse_EIS.py')
        pos = self.files.get('pos')
        data_dir = self._data_dir()
        eis_files = _v198_all_eis_files_for_data_dir(data_dir)
        if not pos or not eis_files:
            self.log('Need both position/takedata file and one or more fullEIS files.')
            return
        for eis in eis_files:
            self.log(f'Running pySECCM parse_EIS for {eis.name}')
            self._run([sys.executable, script, pos.name, eis.name, '--plot', '--n_grid', '100'], cwd=data_dir)
    SECCMPlotRunnerGUI.run_eis = _v198_seccm_runner_run_eis
except Exception:
    pass


# Patch the nonblocking "Run all available" collector to queue every EIS method file.
try:
    _V187_PREV_V69_COLLECT_TOOLS_COMMANDS = _v69_collect_tools_commands
    def _v69_collect_tools_commands(win):
        win.detect_files()
        win._ensure_style()
        commands = []
        notes = []
        data_dir = win._data_dir()
        script_root = win._script_dir()
        py = sys.executable

        try:
            cv_script = win._script('parse_CV.py')
            for p in win.files.get('cv', []):
                commands.append(([py, cv_script, p.name, '--plot'], data_dir, f'CV: {p.name}'))
        except Exception as exc:
            notes.append(f'CV skipped: {exc}')

        try:
            eis_script = win._script('parse_EIS.py')
            pos = win.files.get('pos')
            eis_files = _v198_all_eis_files_for_data_dir(data_dir)
            if pos and eis_files:
                for eis in eis_files:
                    commands.append(([py, eis_script, pos.name, eis.name, '--plot', '--n_grid', '100'], data_dir, f'EIS: {eis.name}'))
            elif eis_files:
                notes.append('EIS skipped: position/takedata file not detected.')
            else:
                notes.append('EIS skipped: no fullEIS files detected.')
        except Exception as exc:
            notes.append(f'EIS skipped: {exc}')

        try:
            iv_script = win._script('parse_IV.py')
            if win.files.get('pos') and win.files.get('corr') and win.files.get('iv'):
                commands.append(([py, iv_script, win.files['pos'].name, win.files['corr'].name, win.files['iv'].name, '--plot', '--n_grid', '100'], data_dir, 'IV/Tafel: parse_IV.py'))
            else:
                notes.append('IV/Tafel skipped: position/corr/IV file not detected.')
        except Exception as exc:
            notes.append(f'IV/Tafel skipped: {exc}')

        try:
            ocp_script = win._script('parse_OCP.py')
            if win.files.get('pos') and win.files.get('avg_ocp') and win.files.get('ocp'):
                commands.append(([py, ocp_script, win.files['pos'].name, win.files['avg_ocp'].name, win.files['ocp'].name, '--plot', '--n_grid', '100'], data_dir, 'OCP: parse_OCP.py'))
            else:
                notes.append('OCP skipped: position/average/full OCP file not detected.')
        except Exception as exc:
            notes.append(f'OCP skipped: {exc}')

        try:
            candidates = [
                script_root / 'headless_pyDRTtools' / 'pyDRTtools' / 'headless_pyDRTtools.py',
                script_root / 'pyDRTtools' / 'headless_pyDRTtools.py',
                script_root / 'headless_pyDRTtools.py',
            ]
            drt_script = next((p for p in candidates if p.exists()), None)
            if drt_script is None:
                notes.append('DRT skipped: headless_pyDRTtools.py was not found.')
            else:
                drt_dir = win.files.get('drt_dir')
                if drt_dir is None:
                    for candidate in [data_dir.parent / 'DRT_input_csv', data_dir / 'Figures' / 'Nyquist']:
                        if candidate.exists():
                            drt_dir = candidate
                            break
                if drt_dir is None:
                    notes.append('DRT skipped: no DRT input folder found. Run EIS first or use exporter DRT_input_csv.')
                else:
                    commands.append(([py, drt_script, str(drt_dir), '--run_types', 'simple', '--plot_types', 'eis', 'drt', '--export_types', 'drt', '--rbf_type', 'gaussian'], drt_script.parent, 'DRT: headless_pyDRTtools.py'))
        except Exception as exc:
            notes.append(f'DRT skipped: {exc}')
        return commands, notes
except Exception:
    pass


# Helper used by QA and advanced users to verify that a data folder will be parsed in
