# ---- FaradaIQ Studio v273 generalized N-method EIS + CA/CP parser-native patch ----
# Keep the v178-stable parser workflow. Generalize method handling so any number of
# generated EIS files (*_fullEIS*.txt) are parsed, and duplicate/multi CA or CP
# transients are exported as separate method files (*_fullCA*.asc / *_fullCP*.asc)
# rather than collapsed into one ambiguous table. CA/CP use FaradaIQ parser scripts
# parse_CA.py / parse_CP.py when present; these scripts generate v178-style Figures
# subfolders without touching the official CV/EIS parser behavior.
APP_TITLE = "FaradaIQ Studio v273"


def _v198_method_text(entry):
    try:
        if isinstance(entry, dict):
            return " ".join(str(entry.get(k, "")) for k in ("technique", "name", "method_name", "raw_text", "title", "type"))
    except Exception:
        pass
    return str(entry or "")


def _v198_classify_chrono_method_entry(entry, default=None):
    txt = _v198_method_text(entry).lower()
    # HEKA/POTMASTER often labels potentiostatic chronoamperometry steps as ChronoPotStat.
    if any(k in txt for k in ["chronopotstat", "chrono pot stat", "chronoamper", "chrono amper", "potentiostatic", "constv", "const v", "constant voltage", "hold potential"]):
        return "CA"
    if any(k in txt for k in ["chronogalv", "chrono galv", "chronopotenti", "chrono potenti", "galvanostatic", "consti", "const i", "constant current", "hold current"]):
        return "CP"
    return default


def _v198_default_chrono_kind(self):
    raw = "\n".join(_v198_method_text(e) for e in (getattr(self, "method_entries", []) or []))
    kind = _v198_classify_chrono_method_entry({"raw_text": raw})
    return kind


def _v198_non_cv_remaining_pairs_by_block(self):
    try:
        by = _heka_v15_current_potential_pairs_by_block(self)
    except Exception:
        by = {}
    try:
        used = _heka_v15_allocated_cv_pair_ids(self)
    except Exception:
        used = set()
    out = {}
    for bi in sorted(by):
        rows=[]
        for p in by.get(bi, []) or []:
            try:
                pair_idx = int(p.get("pair_index", -1))
            except Exception:
                pair_idx = -1
            if pair_idx in used:
                continue
            rows.append(dict(p))
        if rows:
            out[int(bi)] = rows
    return out


def _v198_chrono_method_kinds(self, n_slots=0):
    entries = []
    for e in getattr(self, "method_entries", []) or []:
        k = _v198_classify_chrono_method_entry(e)
        if k in {"CA", "CP"}:
            entries.append(k)
    default = _v198_default_chrono_kind(self)
    n_slots = int(max(0, n_slots or 0))
    if not entries and default in {"CA", "CP"} and n_slots:
        entries = [default] * n_slots
    elif entries and n_slots and len(entries) < n_slots:
        # If one ChronoPotStat method is repeated within every point, treat every
        # remaining local pair as its own method replicate while preserving CA/CP kind.
        entries = entries + [entries[-1]] * (n_slots - len(entries))
    return entries[:n_slots] if n_slots else entries


def _v198_collect_chrono_method_allocations(self):
    """Return {('CA'|'CP', method_number): [pair records across points]} for all remaining chrono pairs."""
    by = _v198_non_cv_remaining_pairs_by_block(self)
    if not by:
        return {}
    max_slots = max((len(v) for v in by.values()), default=0)
    kinds = _v198_chrono_method_kinds(self, max_slots)
    if not kinds:
        return {}
    alloc = {}
    for local_i in range(max_slots):
        kind = kinds[local_i] if local_i < len(kinds) else kinds[-1]
        if kind not in {"CA", "CP"}:
            continue
        method_num = local_i + 1
        key = (kind, method_num)
        for bi in sorted(by):
            pairs = by[bi]
            if local_i >= len(pairs):
                continue
            p = dict(pairs[local_i])
            p["block_index0"] = int(bi)
            p["point_index"] = int(bi) + 1
            p["method_type"] = kind
            p["method_entry"] = method_num
            p["local_chrono_index"] = method_num
            alloc.setdefault(key, []).append(p)
    return alloc


def _v198_trace_dt_s(self, trace_index):
    try:
        dt = _heka_v15_trace_sample_interval_s(self, int(trace_index))
    except Exception:
        dt = float("nan")
    try:
        if np.isfinite(dt) and dt > 0 and dt < 1e6:
            return float(dt), "trace_sample_interval"
    except Exception:
        pass
    return 1.0, "fallback_1s"


def _v198_cumulative_charge(time_s, current_A):
    try:
        t = np.asarray(time_s, dtype=float)
        i = np.asarray(current_A, dtype=float)
        n = min(len(t), len(i))
        if n <= 0:
            return np.asarray([], dtype=float)
        q = np.zeros(n, dtype=float)
        if n > 1:
            dt = np.diff(t[:n])
            q[1:] = np.cumsum(0.5 * (i[:n-1] + i[1:n]) * dt)
        return q
    except Exception:
        return np.zeros(len(current_A), dtype=float)


def _v198_write_chrono_method_file(self, out_path, method_type, method_number, pair_records):
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    total = 0
    groups = 0
    with open(out_path, "w", encoding="windows-1252", newline="") as f:
        for rec in sorted(pair_records or [], key=lambda r: int(r.get("point_index") or r.get("block_index0", 0) + 1)):
            try:
                ci = int(rec.get("current_trace_index"))
                ei = int(rec.get("potential_trace_index"))
                n = min(int(rec.get("n_points") or 0), HEKA_V16_MAX_TRACE_POINTS_FOR_CANONICAL_CSV)
            except Exception:
                continue
            if n <= 0:
                continue
            try:
                cur = np.asarray(self.read_trace_array(ci, max_points=n), dtype=float).ravel()
                pot = np.asarray(self.read_trace_array(ei, max_points=n), dtype=float).ravel()
            except Exception:
                continue
            m = min(len(cur), len(pot), n)
            if m <= 0:
                continue
            dt, dt_source = _v198_trace_dt_s(self, ei)
            t = np.arange(m, dtype=float) * float(dt)
            q = _v198_cumulative_charge(t, cur)
            point = int(rec.get("point_index") or rec.get("block_index0", 0) + 1)
            label = "Chronoamperometry" if method_type == "CA" else "Chronopotentiometry"
            f.write(f"Series_{label}_method{int(method_number)}_point{point:03d}\n")
            f.write(f"Sweep_{label}_point{point:03d}_method{int(method_number)},  0.000000000E+00, 00:00:00.000, 1970/01/01 00:00:00.000, \"Generated from HEKA DAT/PUL; dt_source={dt_source}\"\n")
            f.write('"Index", "Time[s]"       , "Imon-2[A]"     , "Time[s]"       , "Emon-2[V]"     , "Charge[C]"     , "Point" , "Method"\n')
            for k in range(m):
                f.write(f"{k:7d}, {float(t[k]):16.9E}, {float(cur[k]):16.9E}, {float(t[k]):16.9E}, {float(pot[k]):16.9E}, {float(q[k]):16.9E}, {point:7d}, {int(method_number):7d}\n")
            f.write("\n")
            total += m
            groups += 1
    return {"path": str(out_path), "filename": out_path.name, "kind": method_type, "method_entry": int(method_number), "n_groups": groups, "total_rows": total, "source": "HEKA_DAT_PUL_remaining_chrono_current_potential_pairs"}


def _v198_generate_chrono_files(self, data_dir, safe):
    infos = []
    alloc = _v198_collect_chrono_method_allocations(self)
    for (kind, method_num), records in sorted(alloc.items(), key=lambda kv: (kv[0][0], kv[0][1])):
        if not records:
            continue
        if kind == "CA":
            name = f"{safe}_fullCA_9.asc" if method_num == 1 else f"{safe}_fullCA_method{method_num}.asc"
        else:
            name = f"{safe}_fullCP_9.asc" if method_num == 1 else f"{safe}_fullCP_method{method_num}.asc"
        info = _v198_write_chrono_method_file(self, Path(data_dir) / name, kind, method_num, records)
        infos.append(info)
    return infos


# Add CA/CP files after the stable v178/v186 export has produced the normal parser folder.
try:
    _V187_PREV_SECCM_EXPORT = _heka_v14_export_seccm_plotting_analysis_outputs
except Exception:
    _V187_PREV_SECCM_EXPORT = None


def _heka_v14_export_seccm_plotting_analysis_outputs(self, output_dir: Path, base_name: str) -> dict:
    info = _V187_PREV_SECCM_EXPORT(self, output_dir, base_name) if callable(_V187_PREV_SECCM_EXPORT) else {}
    safe = PSSessionParser._sanitize_filename(base_name)
    root = Path(info.get("root") or Path(output_dir) / f"{safe}_for_plotting_analysis")
    generated_data = root / "data_generated_from_HEKA"
    main_data = Path(info.get("main_data") or root / "data")
    generated_data.mkdir(parents=True, exist_ok=True)
    main_data.mkdir(parents=True, exist_ok=True)
    added = []
    try:
        added = _v198_generate_chrono_files(self, generated_data, safe)
        for row in added:
            src = Path(row.get("path", ""))
            if src.exists():
                _v14_shutil.copy2(src, main_data / src.name)
        _heka_v14_make_minimal_mplstyle(main_data)
    except Exception as exc:
        info.setdefault("notes", []).append(f"FaradaIQ v273 CA/CP multi-method export failed: {exc}")
    if added:
        info.setdefault("files", []).extend([str(Path(r["path"])) for r in added])
        info["n_chrono_method_files"] = len(added)
        info["chrono_method_files"] = [r.get("filename") for r in added]
    man_path = Path(info.get("manifest", root / "plotting_analysis_manifest.json"))
    try:
        man = {}
        if man_path.exists():
            with open(man_path, "r", encoding="utf-8") as f:
                man = json.load(f)
        man.setdefault("generated_from_heka", []).extend(added)
        man.setdefault("notes", []).append("v198: all generated *_fullEIS*.txt files are parsed separately; multi CA/CP remaining chrono pairs are exported as separate *_fullCA*.asc / *_fullCP*.asc method files.")
        man["n_chrono_method_files"] = len(added)
        man["chrono_method_files"] = [r.get("filename") for r in added]
        with open(man_path, "w", encoding="utf-8") as f:
            json.dump(man, f, indent=2, ensure_ascii=False)
        info["manifest"] = str(man_path)
    except Exception:
        pass
    return info


# Classify parser data folder CA/CP files and keep all instances, just like all fullEIS files.
try:
    _V187_PREV_CLASSIFY_FILE = _v19_classify_file
except Exception:
    _V187_PREV_CLASSIFY_FILE = None


def _v19_classify_file(path: Path):
    low = Path(path).name.lower()
    if "fullca" in low or "chronoamper" in low or re.search(r"(^|[_\-])ca([_\-]|$)", low):
        return "CA"
    if "fullcp" in low or "chronopot" in low or re.search(r"(^|[_\-])cp([_\-]|$)", low):
        return "CP"
    if callable(_V187_PREV_CLASSIFY_FILE):
        return _V187_PREV_CLASSIFY_FILE(path)
    return _heka_v14_classify_companion_file(path)


try:
    _V187_PREV_DETECT_FILES = _v19_detect_pyseccm_files
except Exception:
    _V187_PREV_DETECT_FILES = None


def _v19_detect_pyseccm_files(data_dir: Path):
    out = _V187_PREV_DETECT_FILES(data_dir) if callable(_V187_PREV_DETECT_FILES) else {"cv": [], "eis": [], "pos": [], "iv": [], "corr": [], "ocp": [], "avg_ocp": [], "drt_dir": []}
    out.setdefault("ca", [])
    out.setdefault("cp", [])
    d = Path(data_dir)
    if not d.exists() or not d.is_dir():
        return out
    try:
        files = sorted([p for p in d.iterdir() if p.is_file()], key=_heka_v14_nat_key_path)
    except Exception:
        files = sorted([p for p in d.iterdir() if p.is_file()], key=lambda p: p.name.lower())
    seen_ca = {str(Path(p).resolve()) for p in out.get("ca", []) if Path(p).exists()}
    seen_cp = {str(Path(p).resolve()) for p in out.get("cp", []) if Path(p).exists()}
    for p in files:
        kind = _v19_classify_file(p)
        try:
            key = str(p.resolve())
        except Exception:
            key = str(p)
        if kind == "CA" and key not in seen_ca:
            out["ca"].append(p); seen_ca.add(key)
        elif kind == "CP" and key not in seen_cp:
            out["cp"].append(p); seen_cp.add(key)
    return out


