def _v27_build_auto_pyseccm_commands_for_data_dir(data_dir, script_root=None, python_exe=None, include_drt=True):
    commands, notes, detected = _V187_PREV_BUILD_AUTO_COMMANDS(data_dir, script_root=script_root, python_exe=python_exe, include_drt=include_drt) if callable(_V187_PREV_BUILD_AUTO_COMMANDS) else ([], [], _v19_detect_pyseccm_files(Path(data_dir)))
    data_dir = Path(data_dir)
    script_root = Path(script_root or _v19_find_pyseccm_script_root([data_dir, data_dir.parent, Path(__file__).resolve().parent]) or (Path(__file__).resolve().parent / "pyseccm_tools"))
    python_exe = str(python_exe or _v19_sys.executable)
    for key, script_name in [("ca", "parse_CA.py"), ("cp", "parse_CP.py")]:
        script_path = script_root / script_name
        files = list((detected or {}).get(key, []) or [])
        if files and script_path.exists():
            for p in files:
                commands.append(([python_exe, str(script_path), Path(p).name, "--plot"], Path(p).parent))
        elif files:
            notes.append(f"Skipped {key.upper()} parser in {data_dir}: {script_name} was not found in {script_root}; exported files are still available.")
    return commands, notes, detected


