# ---- FaradaIQ Studio v273 parser-native short-path + error-visible auto-run patch ----
# Keep the stable v178 parser-native workflow, but make it reliable for long Windows
# paths and long sample names. the previous build correctly queued two fullEIS files, but direct
# parse_EIS.py calls could finish with errors before creating *_Groups/Figures on
# deep Windows folders. v198 stages every parser input through short aliases, copies
# the v178-style parser outputs back using the original filenames, and writes command
# logs plus FAILED progress when a parser returns nonzero.
APP_TITLE = "FaradaIQ Studio v273"

import hashlib as _v198_hashlib
import tempfile as _v198_tempfile
from pathlib import Path as _V188Path


def _v198_script_name(args):
    try:
        return _V188Path(str(args[1])).name.lower() if len(args) > 1 else ""
    except Exception:
        return ""


def _v198_abs_arg(token, cwd):
    try:
        p = _V188Path(str(token))
        if p.is_absolute():
            return p
        return (_V188Path(cwd) / p).resolve()
    except Exception:
        return _V188Path(str(token))


def _v198_short_alias(src, prefix="F", ext=None, max_base=32):
    try:
        p = _V188Path(src)
        h = _v198_hashlib.sha1(str(p).encode("utf-8", errors="ignore")).hexdigest()[:8]
        suffix = ext if ext is not None else (p.suffix or ".txt")
        stem = re.sub(r"[^A-Za-z0-9_.-]+", "_", p.stem).strip("_.")
        # Preserve EIS method identity while keeping the staging path short.
        low = p.name.lower()
        tag = prefix
        if "methode" in low or "method" in low:
            m = re.search(r"method\s*([0-9]+)", low)
            tag = f"{prefix}m{m.group(1)}" if m else f"{prefix}m"
        elif "fulleis" in low:
            tag = prefix
        stem = (stem[:max_base].strip("_.") or tag)
        return f"{tag}_{stem}_{h}{suffix}"
    except Exception:
        return f"{prefix}_{_v198_hashlib.sha1(os.urandom(8)).hexdigest()[:8]}{ext or '.txt'}"


def _v198_stage_parser_command(cmd):
    """Return a short-path runner command for CV/EIS/CA/CP parser commands."""
    try:
        args, cwd = cmd[:2]
        args = [str(a) for a in args]
        script_name = _v198_script_name(args)
        if script_name not in {"parse_cv.py", "parse_eis.py", "parse_ca.py", "parse_cp.py"}:
            return cmd, None
        py = args[0]
        script = args[1]
        cwd = _V188Path(cwd)
        runner = _V188Path(__file__).resolve().parent / "faradaiq_pyseccm_shortpath_runner.py"
        if not runner.exists():
            return cmd, "FaradaIQ v273 short-path runner missing; using direct parser command."
        # parse_EIS.py pos_file eis_file --plot --n_grid N
        if script_name == "parse_eis.py" and len(args) >= 4:
            pos = _v198_abs_arg(args[2], cwd)
            eis = _v198_abs_arg(args[3], cwd)
            if not pos.exists() or not eis.exists():
                return cmd, f"v198 could not stage EIS because input missing: pos={pos.exists()} eis={eis.exists()}"
            new_args = [
                py, str(runner),
                "--script", str(script),
                "--pos-input", str(pos),
                "--input", str(eis),
                "--original-cwd", str(cwd),
                "--pos-short-name", _v198_short_alias(pos, prefix="POS", max_base=14),
                "--short-name", _v198_short_alias(eis, prefix="EIS", max_base=18),
                "--reason", "FaradaIQ v273 stages EIS parser inputs to avoid Windows long-path/long-name parser failures",
            ]
            # Preserve parser options after required positional args.
            new_args.extend(args[4:])
            return (new_args, _V188Path(__file__).resolve().parent), f"v198 staged parse_EIS.py for {eis.name} through short aliases; outputs are copied back as v178-style parser folders."
        # parse_CV.py/parse_CA.py/parse_CP.py one_input --plot
        if len(args) >= 3:
            src = _v198_abs_arg(args[2], cwd)
            if not src.exists():
                return cmd, f"v198 could not stage {script_name} because input is missing: {src}"
            prefix = "CV" if script_name == "parse_cv.py" else ("CA" if script_name == "parse_ca.py" else "CP")
            new_args = [
                py, str(runner),
                "--script", str(script),
                "--input", str(src),
                "--original-cwd", str(cwd),
                "--short-name", _v198_short_alias(src, prefix=prefix, max_base=20),
                "--reason", f"v198 stages {script_name} inputs to avoid Windows long-path/long-name parser failures",
            ]
            new_args.extend(args[3:])
            return (new_args, _V188Path(__file__).resolve().parent), f"v198 staged {script_name} for {src.name}; outputs are copied back as v178-style parser folders."
    except Exception as exc:
        return cmd, f"v198 staging skipped one parser command: {exc}"
    return cmd, None


try:
    _V188_PREV_DEDUPE_COMMANDS = _v118_dedupe_commands
except Exception:
    _V188_PREV_DEDUPE_COMMANDS = None


def _v118_dedupe_commands(commands, notes=None):
    notes = notes if isinstance(notes, list) else []
    if callable(_V188_PREV_DEDUPE_COMMANDS):
        out, skipped, notes = _V188_PREV_DEDUPE_COMMANDS(commands, notes)
    else:
        out, skipped = list(commands or []), []
    patched = []
    n_staged = 0
    for cmd in out:
        new_cmd, note = _v198_stage_parser_command(cmd)
        if note:
            notes.append(note)
        if new_cmd is not cmd:
            n_staged += 1
        patched.append(new_cmd)
    if n_staged:
        notes.append(f"FaradaIQ v273 short-path staged {n_staged} parser commands; parser outputs are copied back to the original data folder with the original long basenames.")
    return patched, skipped, notes


def _v198_quote_for_echo(text):
    return str(text).replace("%", "%%").replace("&", "and").replace("|", "-").replace(">", "-").replace("<", "-")


def _v67_command_batch_with_progress(commands, progress_file, notes=None, title="Auto pySECCM/DRT after export"):
    """v198 override: log each parser command and report parser failures honestly."""
    total = len(commands)
    pf_path = _V188Path(progress_file)
    pf = str(pf_path)
    log_dir = pf_path.parent / "_faradaiq_parser_logs"
    # Windows batch file; logs are written beside the progress file.
    lines = [
        "@echo off",
        "chcp 65001 >nul",
        "setlocal EnableExtensions EnableDelayedExpansion",
        f"title {title}",
        f"if not exist { _v19_subprocess.list2cmdline([str(log_dir)]) } mkdir { _v19_subprocess.list2cmdline([str(log_dir)]) }",
        "set ANY_FAIL=0",
        "set PYTHONUTF8=1",
        "set PYTHONIOENCODING=utf-8",
        "set PYTHONLEGACYWINDOWSSTDIO=0",
        "echo ============================================================",
        f"echo {title}",
        "echo ============================================================",
        "echo.",
        f'> "{pf}" echo 0 of {total} STARTING Preparing parser commands',
    ]
    if notes:
        lines += ["echo.", "echo Auto-run notes:"]
        for n in notes:
            lines.append(f"echo   {_v198_quote_for_echo(n)}")
        lines.append("echo.")
    for i, (args, cwd) in enumerate(commands, start=1):
        cwd = _V188Path(cwd)
        cmdline = _v19_subprocess.list2cmdline([str(a) for a in args])
        script_label = _V188Path(str(args[1])).name if len(args) > 1 else _V188Path(str(args[0])).name
        safe_label = _v198_quote_for_echo(script_label)
        log_file = log_dir / f"parser_{i:03d}_{re.sub(r'[^A-Za-z0-9_.-]+','_', script_label)}.log"
        lines += [
            f'> "{pf}" echo {i} of {total} RUNNING {safe_label}',
            "echo ------------------------------------------------------------",
            f"echo [{i}/{total}] {safe_label}",
            f"echo Working folder: {cwd}",
            f"echo Log file: {log_file}",
            f"cd /d {_v19_subprocess.list2cmdline([str(cwd)])}",
            f"> {_v19_subprocess.list2cmdline([str(log_file)])} echo FaradaIQ parser command {i} of {total}: {safe_label}",
            f">> {_v19_subprocess.list2cmdline([str(log_file)])} echo Working folder: {cwd}",
            f">> {_v19_subprocess.list2cmdline([str(log_file)])} echo Command: {cmdline}",
            f">> {_v19_subprocess.list2cmdline([str(log_file)])} echo ------------------------------------------------------------",
            f"{cmdline} >> {_v19_subprocess.list2cmdline([str(log_file)])} 2>&1",
            "set LAST_EXIT=!ERRORLEVEL!",
            f">> {_v19_subprocess.list2cmdline([str(log_file)])} echo ------------------------------------------------------------",
            f">> {_v19_subprocess.list2cmdline([str(log_file)])} echo Exit code: !LAST_EXIT!",
            f"type {_v19_subprocess.list2cmdline([str(log_file)])}",
            "if not \"!LAST_EXIT!\"==\"0\" set ANY_FAIL=1",
            f"if \"!LAST_EXIT!\"==\"0\" (> \"{pf}\" echo {i} of {total} DONE rc=!LAST_EXIT! {safe_label}) else (> \"{pf}\" echo {i} of {total} FAILED rc=!LAST_EXIT! {safe_label} -- see {log_file})",
            "echo.",
        ]
    lines += [
        "if \"!ANY_FAIL!\"==\"0\" goto FARADAIQ_PARSERS_OK",
        f"> \"{pf}\" echo {total} of {total} FINISHED_WITH_ERRORS One or more parser commands failed; inspect _faradaiq_parser_logs",
        "echo.",
        "echo One or more parser commands failed. Inspect the log files above.",
        "goto FARADAIQ_PARSERS_DONE",
        ":FARADAIQ_PARSERS_OK",
        f"> \"{pf}\" echo {total} of {total} FINISHED All parser commands finished",
        "echo.",
        "echo All requested commands finished successfully.",
        ":FARADAIQ_PARSERS_DONE",
        "echo This window is intentionally left open so you can inspect parser output/errors.",
        "echo.",
        "pause",
    ]
    return "\n".join(lines) + "\n"


