def _v198_h5_numeric_column_helpers(df):
    import pandas as _pd
    cols = list(getattr(df, 'columns', []) or [])
    low = {c: str(c).lower().replace(' ', '').replace('_', '').replace('-', '') for c in cols}
    def find_any(patterns):
        pats = [str(p).lower().replace(' ', '').replace('_', '').replace('-', '') for p in patterns]
        # Prefer exact-ish semantic matches before broad fallback.
        for c in cols:
            lc = low.get(c, '')
            if any(lc == p for p in pats):
                return c
        for c in cols:
            lc = low.get(c, '')
            if any(p in lc for p in pats):
                return c
        return None
    def num(c):
        try:
            return _pd.to_numeric(df[c], errors='coerce').to_numpy(dtype=float)
        except Exception:
            return np.asarray([], dtype=float)
    freq = find_any(['frequencyhz','freqhz','f2hz','fhz','freq','frequency','hz'])
    zr = find_any(['zrealohm','realzohm','zreohm','zreal','realz','rez','zprime','real'])
    zi = find_any(['zimagohm','imagzohm','zimohm','zimag','imagz','imz','zdoubleprime','imag'])
    mag = find_any(['zabsohm','impzohm','zmodohm','modzohm','zabs','impz','zmod','magnitude','mag','modulus'])
    phase = find_any(['phasedeg','phase'])
    return {'freq': freq, 'zr': zr, 'zi': zi, 'mag': mag, 'phase': phase, 'num': num}


def _v198_eis_label_for_path(path, all_paths=None):
    try:
        s = Path(path).stem
        low = s.lower()
        mpoint = re.search(r'point[_\- ]*0*(\d+)', low)
        mmeth = re.search(r'method[_\- ]*0*(\d+)', low)
        parts = []
        if mpoint:
            parts.append(f'P{int(mpoint.group(1)):02d}')
        if mmeth:
            parts.append(f'M{int(mmeth.group(1)):02d}')
        if parts:
            return ' '.join(parts)
        if '_v177_label_for_path' in globals():
            try:
                return _v177_label_for_path(path, all_paths)
            except Exception:
                pass
        return _v138_safe_label(s, 42) if '_v138_safe_label' in globals() else s[:42]
    except Exception:
        try:
            return Path(path).stem[:42]
        except Exception:
            return 'curve'


