def _v198_find_comboboxes(widget, out=None):
    out = [] if out is None else out
    try:
        if widget.winfo_class() in {'TCombobox', 'Combobox'}:
            out.append(widget)
    except Exception:
        pass
    try:
        for ch in widget.winfo_children():
            _v198_find_comboboxes(ch, out)
    except Exception:
        pass
    return out


