def _v198_style_flags(browser):
    try:
        style = str(browser.eis_plot_style_var.get() or 'Line + Points').strip().lower()
    except Exception:
        style = 'line + points'
    want_line = ('line' in style)
    want_points = ('point' in style)
    if not want_line and not want_points:
        want_line = True
    return want_line, want_points


def _v198_eis_cmap():
    try:
        import matplotlib.pyplot as _plt
        return _plt.get_cmap('Blues_r')
    except Exception:
        return None


def _v198_freq_to_color_values(freq):
    f = np.asarray(freq, dtype=float)
    m = np.isfinite(f) & (f > 0)
    vals = np.full(f.shape, 0.50, dtype=float)
    if np.count_nonzero(m) >= 2:
        lf = np.log10(f[m])
        lo = float(np.nanmin(lf)); hi = float(np.nanmax(lf))
        if hi > lo:
            # With Blues_r: low frequency -> dark, high frequency -> light.
            vals[m] = (lf - lo) / (hi - lo)
        else:
            vals[m] = 0.50
    return vals


def _v198_add_freq_colorbar(browser, freq):
    try:
        if not getattr(browser, 'eis_freq_gradient_var', tk.BooleanVar(value=True)).get():
            return
        if getattr(browser, '_v198_eis_colorbar', None) is not None:
            return
        import matplotlib as _mpl
        cmap = _v198_eis_cmap()
        if cmap is None:
            return
        f = np.asarray(freq, dtype=float)
        f = f[np.isfinite(f) & (f > 0)]
        if f.size < 2:
            return
        lo = float(np.nanmin(f)); hi = float(np.nanmax(f))
        if hi <= lo:
            return
        norm = _mpl.colors.LogNorm(vmin=lo, vmax=hi)
        sm = _mpl.cm.ScalarMappable(norm=norm, cmap=cmap)
        sm.set_array([])
        cb = browser._figure.colorbar(sm, ax=browser._ax, pad=0.025, fraction=0.046)
        cb.set_label('Frequency / Hz')
        browser._v198_eis_colorbar = cb
    except Exception as exc:
        try:
            browser.log(f'Could not add EIS frequency colorbar: {exc}')
        except Exception:
            pass


def _v198_plot_frequency_gradient_xy(browser, x, y, freq, label, mode='nyquist'):
    import matplotlib as _mpl
    from matplotlib.collections import LineCollection
    x = np.asarray(x, dtype=float); y = np.asarray(y, dtype=float); freq = np.asarray(freq, dtype=float)
    mask = np.isfinite(x) & np.isfinite(y) & np.isfinite(freq) & (freq > 0)
    x = x[mask]; y = y[mask]; freq = freq[mask]
    if x.size < 2:
        return False
    order = np.argsort(freq)[::-1]  # high to low frequency, matching instrument sweep order visually.
    x = x[order]; y = y[order]; freq = freq[order]
    want_line, want_points = _v198_style_flags(browser)
    cmap = _v198_eis_cmap()
    vals = _v198_freq_to_color_values(freq)
    norm = None
    try:
        ff = freq[np.isfinite(freq) & (freq > 0)]
        if ff.size >= 2 and float(np.nanmax(ff)) > float(np.nanmin(ff)):
            norm = _mpl.colors.LogNorm(vmin=float(np.nanmin(ff)), vmax=float(np.nanmax(ff)))
    except Exception:
        norm = None
    if want_line and x.size >= 2:
        pts = np.column_stack([x, y]).reshape(-1, 1, 2)
        segs = np.concatenate([pts[:-1], pts[1:]], axis=1)
        seg_freq = (freq[:-1] + freq[1:]) / 2.0
        lc = LineCollection(segs, cmap=cmap, norm=norm, linewidths=1.65, alpha=0.95)
        try:
            lc.set_array(seg_freq if norm is not None else (vals[:-1] + vals[1:]) / 2.0)
        except Exception:
            pass
        browser._ax.add_collection(lc)
    if want_points:
        if cmap is not None and norm is not None:
            browser._ax.scatter(x, y, c=freq, cmap=cmap, norm=norm, s=28 if x.size <= 250 else 14, edgecolors='none', alpha=0.98, label='_nolegend_')
        elif cmap is not None:
            browser._ax.scatter(x, y, c=cmap(vals), s=28 if x.size <= 250 else 14, edgecolors='none', alpha=0.98, label='_nolegend_')
        else:
            browser._ax.scatter(x, y, s=22, alpha=0.95, label='_nolegend_')
    # Proxy legend handle: one curve label per selected file, not every point.
    try:
        import matplotlib.lines as _mlines
        proxy = _mlines.Line2D([], [], color=(0.05, 0.18, 0.36, 1.0), marker='o' if want_points else None,
                               linestyle='-' if want_line else 'None', markersize=4, linewidth=1.6, label=label)
        handles = getattr(browser, '_v198_legend_handles', [])
        handles.append(proxy)
        browser._v198_legend_handles = handles
    except Exception:
        pass
    try:
        browser._ax.update_datalim(np.column_stack([x, y])); browser._ax.autoscale_view()
    except Exception:
        pass
    _v198_add_freq_colorbar(browser, freq)
    return True


try:
    _V198_PREV_H5_PLOT_ONE = FaradaIQH5Browser._plot_one
except Exception:
    _V198_PREV_H5_PLOT_ONE = None


def _v198_h5_plot_one(self, p, clear=False):
    if not self._ensure_plot_canvas():
        return
    _v198_init_h5_plot_controls(self)
    try:
        import pandas as _pd
        df = _v138_csv_read(p)
        cols = _v198_h5_numeric_column_helpers(df)
        num = cols.get('num')
        mode = str(getattr(self, 'plot_mode_var', tk.StringVar(value='Auto')).get() or 'Auto')
        mode_l = mode.lower()
        is_eis_table = bool(cols.get('zr') and cols.get('zi')) or ('eis' in str(p).lower() or 'nyquist' in str(p).lower() or 'bode' in str(p).lower())
        label = _v198_eis_label_for_path(p, getattr(self, 'last_plot_paths', []))
        # Frequency-colored Nyquist is the requested default for EIS Nyquist-style views.
        if is_eis_table and ('nyquist' in mode_l or mode_l == 'auto' or mode_l == 'eis nyquist') and cols.get('zr') and cols.get('zi'):
            x = num(cols['zr']); raw_y = num(cols['zi']); y = raw_y.copy()
            if 'raw' not in mode_l:
                # Nyquist convention: plot -Zimag. If the stored imaginary column is already positive, keep it.
                if np.nanmedian(y) < 0:
                    y = -y
            freq = num(cols['freq']) if cols.get('freq') else np.arange(len(x), 0, -1, dtype=float)
            mask = np.isfinite(x) & np.isfinite(y)
            x=x[mask]; y=y[mask]; freq=freq[mask] if len(freq)==len(mask) else np.arange(len(x), 0, -1, dtype=float)
            if x.size < 2:
                self.log(f'Not enough numeric EIS data: {Path(p).name}'); return
            use_gradient = bool(getattr(self, 'eis_freq_gradient_var', tk.BooleanVar(value=True)).get())
            style = str(getattr(self, 'eis_plot_style_var', tk.StringVar(value='Line + Points')).get() or '')
            if use_gradient and cols.get('freq'):
                _v198_plot_frequency_gradient_xy(self, x, y, freq, label, mode='nyquist')
            else:
                want_line, want_points = _v198_style_flags(self)
                self._ax.plot(x, y, linestyle='-' if want_line else 'None', marker='o' if want_points else None,
                              markersize=3.5, linewidth=1.5, color='#0f355e', label=label)
            self._ax.set_xlabel('RealZ / Ohm')
            self._ax.set_ylabel('-ImagZ / Ohm' if 'raw' not in mode_l else 'ImagZ / Ohm')
            self._ax.set_title('EIS Nyquist frequency-gradient overlay' if use_gradient else 'EIS Nyquist overlay')
            try:
                # Preserve a true Nyquist aspect when the data range makes it readable, but do not force huge blank space.
                xr = float(np.nanmax(x) - np.nanmin(x)); yr = float(np.nanmax(y) - np.nanmin(y))
                if xr > 0 and yr > 0 and 0.25 <= xr/yr <= 4.0:
                    self._ax.set_aspect('equal', adjustable='box')
                else:
                    self._ax.set_aspect('auto')
            except Exception:
                pass
            self._curves.append({'path': Path(p), 'xcol': cols.get('zr'), 'ycol': cols.get('zi'), 'detected': 'EIS Nyquist freq-gradient', 'label': label})
            self.last_plot_paths.append(Path(p))
            self.log(f'Plotted {Path(p).name}: EIS Nyquist frequency-gradient, style={style}')
            return
        # Bode modes get the same line/points style toggle.
        if is_eis_table and 'bode' in mode_l and cols.get('freq'):
            f = num(cols['freq'])
            if 'phase' in mode_l:
                if cols.get('phase'):
                    y = num(cols['phase']); ylabel = 'Phase / deg'; detected = 'Bode phase'
                elif cols.get('zr') and cols.get('zi'):
                    y = np.degrees(np.arctan2(num(cols['zi']), num(cols['zr']))); ylabel = 'Phase / deg'; detected = 'Bode phase calculated'
                else:
                    self.log(f'No phase/Zreal/Zimag columns for {Path(p).name}'); return
            elif 'real' in mode_l and cols.get('zr'):
                y = num(cols['zr']); ylabel = 'Zreal / Ohm'; detected = 'Bode real'
            elif ('imag' in mode_l or 'img' in mode_l) and cols.get('zi'):
                y = num(cols['zi']); ylabel = 'Zimag / Ohm'; detected = 'Bode imag'
            else:
                if cols.get('mag'):
                    y = np.abs(num(cols['mag']))
                elif cols.get('zr') and cols.get('zi'):
                    y = np.sqrt(num(cols['zr'])**2 + num(cols['zi'])**2)
                else:
                    self.log(f'No magnitude/Zreal/Zimag columns for {Path(p).name}'); return
                ylabel = '|Z| / Ohm'; detected = 'Bode magnitude'
            mask = np.isfinite(f) & np.isfinite(y) & (f > 0)
            f = f[mask]; y = y[mask]
            if f.size < 2:
                self.log(f'Not enough Bode data: {Path(p).name}'); return
            order = np.argsort(f)
            f=f[order]; y=y[order]
            want_line, want_points = _v198_style_flags(self)
            self._ax.plot(f, y, linestyle='-' if want_line else 'None', marker='o' if want_points else None,
                          markersize=3.2, linewidth=1.45, label=label)
            self._ax.set_xscale('log')
            if 'magnitude' in detected.lower():
                try:
                    if np.nanmin(y) > 0: self._ax.set_yscale('log')
                except Exception:
                    pass
            self._ax.set_xlabel('Frequency / Hz'); self._ax.set_ylabel(ylabel); self._ax.set_title(f'EIS {detected} overlay')
            self._curves.append({'path': Path(p), 'xcol': cols.get('freq'), 'ycol': ylabel, 'detected': detected, 'label': label})
            self.last_plot_paths.append(Path(p))
            self.log(f'Plotted {Path(p).name}: {detected}')
            return
    except Exception as exc:
        try:
            self.log(f'FaradaIQ v273 EIS plot failed for {Path(p).name}: {exc}')
        except Exception:
            pass
    if callable(_V198_PREV_H5_PLOT_ONE):
        return _V198_PREV_H5_PLOT_ONE(self, p, clear=clear)


def _v198_apply_visible_legend(browser, force=False):
    try:
        ax = getattr(browser, '_ax', None); fig = getattr(browser, '_figure', None); canvas = getattr(browser, '_canvas', None)
        if ax is None:
            return
        mode = 'On'
        try:
            mode = str(browser.legend_var.get() or 'On')
        except Exception:
            pass
        if mode == 'Off' and not force:
            old = ax.get_legend()
            if old is not None:
                try: old.remove()
                except Exception: pass
            return
        handles = list(getattr(browser, '_v198_legend_handles', []) or [])
        labels = [h.get_label() for h in handles if getattr(h, 'get_label', lambda:'')() and not str(h.get_label()).startswith('_')]
        if handles and labels:
            hs = handles; ls = labels
        else:
            hs, ls = ax.get_legend_handles_labels()
            pairs = [(h,l) for h,l in zip(hs,ls) if l and not str(l).startswith('_')]
            hs = [p[0] for p in pairs]; ls = [p[1] for p in pairs]
        if not hs:
            return
        # Deduplicate labels while preserving order.
        seen=set(); hs2=[]; ls2=[]
        for h,l in zip(hs,ls):
            if l in seen: continue
            seen.add(l); hs2.append(h); ls2.append(l)
        n=len(ls2)
        fontsize = 7 if n <= 12 else (6 if n <= 30 else 5)
        ncol = 1 if n <= 12 else (2 if n <= 30 else 3)
        old = ax.get_legend()
        if old is not None:
            try: old.remove()
            except Exception: pass
        leg = ax.legend(hs2, ls2, fontsize=fontsize, loc='upper right', ncol=ncol, frameon=True,
                        framealpha=0.86, title='Curves')
        try: leg.get_title().set_fontsize(fontsize)
        except Exception: pass
        if fig is not None:
            try: fig.tight_layout()
            except Exception: pass
        if canvas is not None:
            try: canvas.draw_idle()
            except Exception: pass
        try:
            browser.log(f'v198 legend displayed with {n} label(s).')
        except Exception:
            pass
    except Exception as exc:
        try: browser.log(f'Could not apply v198 visible legend: {exc}')
        except Exception: pass


