def _v198_h5_plot_selected(self, clear=True, add_view=True):
    _v198_init_h5_plot_controls(self)
    try:
        paths = self.selected_paths(plottable_only=True)
        if not paths:
            messagebox.showinfo('No table selected', 'Select one or more table files, an EIS point/group, or a Plot/view entry.', parent=self)
            return
        try:
            maxn = max(1, int(float(self.max_curves_var.get())))
        except Exception:
            maxn = 24
        if clear:
            self.clear_plot()
        if not hasattr(self, '_v198_legend_handles'):
            self._v198_legend_handles = []
        self.last_plot_paths = [] if clear else list(getattr(self, 'last_plot_paths', []) or [])
        selected = list(paths[:maxn])
        for p in selected:
            self._plot_one(p, clear=False)
        if self._ax is not None:
            try: self._ax.grid(True, alpha=0.25)
            except Exception: pass
            try: self._apply_axis_title_labels()
            except Exception: pass
            _v198_apply_visible_legend(self, force=True)
            try: self._figure.tight_layout()
            except Exception: pass
            try: self._canvas.draw_idle()
            except Exception: pass
        if len(paths) > maxn:
            try: self.log(f'Plotted first {maxn} of {len(paths)} selected files. Increase Max curves to show more.')
            except Exception: pass
        if add_view:
            try:
                label_parts=[]; sel=list(self.tree.selection())
                if sel: label_parts.append(self.tree.item(sel[0], 'text'))
                label = f'{self.plot_mode_var.get()} — ' + (_v138_safe_label(label_parts[0], 60) if label_parts else f'{len(selected)} selected file(s)')
                view = _v138_add_plot_view(self, label, selected, mode=self.plot_mode_var.get(), source='v198_plot_selected') if '_v138_add_plot_view' in globals() else None
                if view is not None:
                    view['eis_plot_style'] = getattr(self, 'eis_plot_style_var', tk.StringVar(value='Line + Points')).get()
                    view['eis_freq_gradient'] = bool(getattr(self, 'eis_freq_gradient_var', tk.BooleanVar(value=True)).get())
                    view['legend'] = getattr(self, 'legend_var', tk.StringVar(value='On')).get()
            except Exception:
                pass
    except Exception as exc:
        try: self.log(f'v198 plot selected failed: {exc}\n{traceback.format_exc()}')
        except Exception: pass
        if callable(_V198_PREV_H5_PLOT_SELECTED):
            return _V198_PREV_H5_PLOT_SELECTED(self, clear=clear, add_view=add_view)


