def _v198b_available_cmaps():
    names = [
        'Blues','Greys','Purples','Greens','Oranges','Reds',
        'PuBu','PuBuGn','BuGn','BuPu','GnBu','YlGn','YlGnBu','YlOrBr','YlOrRd',
        'viridis','plasma','inferno','magma','cividis','coolwarm','cubehelix','twilight',
        'Accent','Dark2','Paired','Pastel1','Pastel2','Set1','Set2','Set3','tab10','tab20','tab20b','tab20c',
        'binary','bone','copper','gray','hot','pink','spring','summer','autumn','winter','cool','Wistia',
        'CMRmap','BrBG','PRGn','PiYG','PuOr','RdBu','RdGy','RdPu','RdYlBu','RdYlGn','Spectral','seismic',
        'gist_earth','gist_gray','gist_heat','gist_ncar','gist_rainbow','gist_stern','gist_yarg',
        'gnuplot','gnuplot2','ocean','terrain','rainbow','jet','turbo','hsv','flag','prism','nipy_spectral',
    ]
    try:
        import matplotlib.pyplot as _plt
        names += [str(x) for x in list(_plt.colormaps())]
    except Exception:
        pass
    out=[]; seen=set()
    for n in names:
        if not n or n in seen or str(n).endswith('_r'):
            continue
        seen.add(n); out.append(n)
    return out


def _v198b_init_controls(browser):
    try:
        if not hasattr(browser, 'eis_plot_style_var'):
            browser.eis_plot_style_var = tk.StringVar(value='Line + Points')
        if not hasattr(browser, 'eis_freq_gradient_var'):
            browser.eis_freq_gradient_var = tk.BooleanVar(value=True)
        if not hasattr(browser, 'legend_var'):
            browser.legend_var = tk.StringVar(value='On')
        if not hasattr(browser, 'eis_cmap_var'):
            browser.eis_cmap_var = tk.StringVar(value='Blues')
    except Exception:
        pass


def _v198b_get_cmap(browser=None):
    try:
        import matplotlib.pyplot as _plt
        name = 'Blues'
        if browser is not None and hasattr(browser, 'eis_cmap_var'):
            name = str(browser.eis_cmap_var.get() or 'Blues')
        cmap = _plt.get_cmap(name)
        # Requested convention: high frequency is lighter and low frequency is darker.
        # Most sequential maps are light at low scalar / dark at high scalar, so reverse them.
        if not str(name).endswith('_r'):
            try:
                cmap = cmap.reversed()
            except Exception:
                pass
        return cmap
    except Exception:
        try:
            import matplotlib.pyplot as _plt
            return _plt.get_cmap('Blues').reversed()
        except Exception:
            return None


def _v198b_palette_colors(browser, n=40):
    try:
        import matplotlib.colors as _mcolors
        cmap = _v198b_get_cmap(browser)
        vals = np.linspace(0.0, 1.0, int(max(8, n)))
        return [_mcolors.to_hex(cmap(float(v)), keep_alpha=False) for v in vals]
    except Exception:
        return ['#f7fbff','#deebf7','#c6dbef','#9ecae1','#6baed6','#4292c6','#2171b5','#084594']


def _v198b_render_palette_preview(browser):
    try:
        canv = getattr(browser, '_v198b_palette_canvas', None)
        if canv is None:
            return
        w = int(canv.cget('width') or 140); h = int(canv.cget('height') or 15)
        canv.delete('all')
        cols = _v198b_palette_colors(browser, n=max(16, min(80, w//3)))
        dx = float(w) / float(max(1, len(cols)))
        x = 0.0
        for col in cols:
            canv.create_rectangle(x, 0, x + dx + 1, h, fill=col, outline=col)
            x += dx
        canv.create_rectangle(0, 0, w, h, outline='#666666')
        canv.create_text(3, h/2, text='HF', anchor='w', fill='#111111', font=('Arial', 6, 'bold'))
        canv.create_text(w-3, h/2, text='LF', anchor='e', fill='#111111', font=('Arial', 6, 'bold'))
    except Exception:
        pass


def _v198b_find_plot_mode_parent(browser):
    try:
        plot_var_name = str(getattr(browser, 'plot_mode_var', ''))
        finder = globals().get('_v198_find_comboboxes')
        boxes = finder(browser) if callable(finder) else []
        for cb in boxes:
            try:
                if str(cb.cget('textvariable')) == plot_var_name:
                    return cb.master
            except Exception:
                pass
    except Exception:
        pass
    return None


def _v198b_build_visible_ui(self):
    _v198b_init_controls(self)
    if callable(_V198B_PREV_BUILD_UI):
        _V198B_PREV_BUILD_UI(self)
    _v198b_init_controls(self)
    try:
        parent = _v198b_find_plot_mode_parent(self)
        if parent is not None and not getattr(self, '_v198b_palette_method_ui_added', False):
            self._v198b_palette_method_ui_added = True
            ttk.Checkbutton(parent, text='Legend', variable=self.legend_var,
                            onvalue='On', offvalue='Off').pack(side='left', padx=(8, 0))
            ttk.Label(parent, text='Palette', style='Muted.TLabel').pack(side='left', padx=(10, 3))
            pal = ttk.Combobox(parent, textvariable=self.eis_cmap_var, state='readonly', width=12,
                               values=_v198b_available_cmaps())
            pal.pack(side='left')
            canv = tk.Canvas(parent, width=136, height=15, bd=0, highlightthickness=0, relief='flat')
            canv.pack(side='left', padx=(5, 0))
            self._v198b_palette_canvas = canv
            try:
                self.eis_cmap_var.trace_add('write', lambda *_a, b=self: _v198b_render_palette_preview(b))
            except Exception:
                pass
            _v198b_render_palette_preview(self)
            # Add small note in log, not the crowded toolbar.
            try:
                self.log('v198 browser controls: Legend On/Off, EIS palette dropdown/preview, and method-group tree roots enabled.')
            except Exception:
                pass
    except Exception as exc:
        try:
            self.log(f'v198 palette/legend UI setup skipped: {exc}')
        except Exception:
            pass


def _v198b_method_number(path, default=1):
    s = Path(path).as_posix()
    pats = [r'method[_\- ]*(\d+)', r'method(\d+)', r'_m(\d+)(?:_|\.|$)', r'fullEIS_(\d+)', r'fullCA_(\d+)', r'fullCP_(\d+)']
    for pat in pats:
        m = re.search(pat, s, flags=re.I)
        if m:
            try:
                v = int(m.group(1))
                if 'fulleis_' in pat.lower() or 'fullca_' in pat.lower() or 'fullcp_' in pat.lower():
                    # v178 names such as fullEIS_6 are historically method 01.
                    return 1
                return max(1, v)
            except Exception:
                pass
    return int(default)


def _v198b_point_number(path, default=0):
    s = Path(path).as_posix()
    for pat in [r'point[_\- ]*(\d+)', r'P(\d{1,4})[_\- ]*M\d+']:
        m = re.search(pat, s, flags=re.I)
        if m:
            try: return int(m.group(1))
            except Exception: pass
    return int(default)


def _v198b_is_eis(path):
    s = Path(path).as_posix().lower(); n = Path(path).name.lower()
    return ('/eis/' in s or '\\eis\\' in s or 'nyquist_bode' in n or 'fulleis' in n or '_eis' in n)


def _v198b_chrono_kind(path):
    s = Path(path).as_posix().lower(); n = Path(path).name.lower()
    if ('/ca/' in s or '\\ca\\' in s or 'fullca' in n or 'ca_point' in n or '_ca_' in n):
        return 'CA'
    if ('/cp/' in s or '\\cp\\' in s or 'fullcp' in n or 'cp_point' in n or '_cp_' in n):
        return 'CP'
    if ('chronoamperometry' in s): return 'CA'
    if ('chronopotentiometry' in s): return 'CP'
    return None


def _v198b_add_method_group_roots(browser):
    try:
        exts = {'.csv','.txt','.asc','.tsv','.xlsx','.xls'}
        files = sorted([p for p in browser.cache_root.rglob('*') if p.is_file() and p.suffix.lower() in exts], key=lambda p: str(p).lower())
        eis = [p for p in files if _v198b_is_eis(p)]
        chrono = [(p, _v198b_chrono_kind(p)) for p in files]
        chrono = [(p,k) for p,k in chrono if k in {'CA','CP'}]
        if not eis and not chrono:
            return
        def root(label, open=False):
            return browser.tree.insert('', 'end', text=label, values=('', ''), open=open)
        def child(parent, label, kind='', open=False, cache={}):
            key = (parent, label, kind)
            if key in cache:
                return cache[key]
            iid = browser.tree.insert(parent, 'end', text=label, values=(kind, ''), open=open)
            cache[key] = iid
            return iid
        def add_file(parent, p, kind):
            try:
                iid = browser.tree.insert(parent, 'end', text=p.name, values=(kind, _v138_fmt_size(p.stat().st_size) if '_v138_fmt_size' in globals() else ''))
            except Exception:
                iid = browser.tree.insert(parent, 'end', text=p.name, values=(kind, ''))
            browser._path_by_iid[iid] = p
        if eis:
            r = root('EIS sets grouped by method', False)
            for p in eis:
                m = _v198b_method_number(p)
                pt = _v198b_point_number(p)
                mn = child(r, f'method {m:02d}', 'EIS method', True)
                pn = child(mn, f'point {pt:03d}' if pt else 'point unknown', 'EIS point', False)
                add_file(pn, p, 'EIS')
        if chrono:
            r = root('CP / CA transients grouped by method', False)
            for p,k in chrono:
                m = _v198b_method_number(p)
                pt = _v198b_point_number(p)
                kr = child(r, k, f'{k} technique', True)
                mn = child(kr, f'method {m:02d}', f'{k} method', True)
                pn = child(mn, f'point {pt:03d}' if pt else 'point unknown', f'{k} point', False)
                add_file(pn, p, k)
        try:
            browser.log(f'v198 method grouping added: EIS files={len(eis)}, CA/CP files={len(chrono)}.')
        except Exception:
            pass
    except Exception as exc:
        try:
            browser.log(f'v198 method grouping skipped: {exc}')
        except Exception:
            pass


def _v198b_refresh_tree(self):
    if callable(_V198B_PREV_REFRESH_TREE):
        _V198B_PREV_REFRESH_TREE(self)
    _v198b_add_method_group_roots(self)


def _v198_add_freq_colorbar(browser, freq):
    """Override final colorbar so the selected user palette is shown."""
    try:
        from matplotlib.colors import LogNorm, Normalize
        import matplotlib as _mpl
        ax = getattr(browser, '_ax', None); fig = getattr(browser, '_figure', None)
        if ax is None or fig is None:
            return None
        for attr in ['_v198_eis_colorbar','_v198b_eis_colorbar']:
            cb0 = getattr(browser, attr, None)
            if cb0 is not None:
                try: cb0.remove()
                except Exception: pass
                try: setattr(browser, attr, None)
                except Exception: pass
        f = np.asarray(freq, dtype=float)
        f = f[np.isfinite(f) & (f > 0)]
        if f.size == 0:
            return None
        if np.nanmax(f) > np.nanmin(f) > 0:
            norm = LogNorm(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f)))
        else:
            norm = Normalize(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f)))
        sm = _mpl.cm.ScalarMappable(norm=norm, cmap=_v198b_get_cmap(browser))
        sm.set_array([])
        cb = fig.colorbar(sm, ax=ax, pad=0.02)
        cb.set_label('Frequency / Hz')
        browser._v198b_eis_colorbar = cb
        browser._v198_eis_colorbar = cb
        return cb
    except Exception as exc:
        try: browser.log(f'v198 colorbar skipped: {exc}')
        except Exception: pass
        return None


def _v198_plot_frequency_gradient_xy(browser, x, y, freq, label, mode='nyquist'):
    """Override final gradient plot to honor palette dropdown and style toggle."""
    try:
        from matplotlib.collections import LineCollection
        from matplotlib.lines import Line2D
        from matplotlib.colors import LogNorm, Normalize
        _v198b_init_controls(browser)
        f = np.asarray(freq, dtype=float)
        x = np.asarray(x, dtype=float); y = np.asarray(y, dtype=float)
        mask = np.isfinite(x) & np.isfinite(y)
        if f.shape == x.shape:
            mask = mask & np.isfinite(f) & (f > 0)
        x=x[mask]; y=y[mask]
        f=f[mask] if f.shape == mask.shape else np.arange(len(x), 0, -1, dtype=float)
        if x.size < 2:
            return
        want_line, want_points = _v198_style_flags(browser) if '_v198_style_flags' in globals() else (True, True)
        cmap = _v198b_get_cmap(browser)
        if f.size == x.size and np.nanmax(f) > np.nanmin(f) > 0:
            norm = LogNorm(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f)))
            cvals = f
        else:
            norm = Normalize(vmin=0.0, vmax=1.0); cvals = np.linspace(1.0, 0.0, len(x))
        if want_line and x.size >= 2:
            pts = np.column_stack([x, y]).reshape(-1, 1, 2)
            seg = np.concatenate([pts[:-1], pts[1:]], axis=1)
            seg_c = (cvals[:-1] + cvals[1:]) / 2.0 if len(cvals) == len(x) else np.linspace(1.0, 0.0, len(seg))
            lc = LineCollection(seg, cmap=cmap, norm=norm, linewidths=1.8)
            lc.set_array(seg_c)
            browser._ax.add_collection(lc)
            try: browser._ax.autoscale_view()
            except Exception: pass
        if want_points:
            browser._ax.scatter(x, y, c=cvals, cmap=cmap, norm=norm, s=30 if x.size <= 250 else 14,
                                edgecolors='none', alpha=0.98, label='_nolegend_')
        try:
            proxy = Line2D([0], [0], color=cmap(0.55), marker='o' if want_points else None,
                           linestyle='-' if want_line else 'None', linewidth=1.8, markersize=4.5,
                           label=str(label)[:44])
            handles = list(getattr(browser, '_v198_legend_handles', []) or [])
            handles.append(proxy)
            browser._v198_legend_handles = handles
        except Exception:
            pass
        _v198_add_freq_colorbar(browser, f)
    except Exception as exc:
        try: browser.log(f'v198 frequency-gradient plot failed: {exc}')
        except Exception: pass


def _v198_apply_visible_legend(browser, force=False):
    """Legend On/Off that works for large overlays and gradient proxy handles."""
    try:
        ax = getattr(browser, '_ax', None); fig = getattr(browser, '_figure', None); canvas = getattr(browser, '_canvas', None)
        if ax is None:
            return
        mode = 'On'
        try: mode = str(browser.legend_var.get() or 'On')
        except Exception: pass
        if mode.lower() in {'off','false','0','no'}:
            old = ax.get_legend()
            if old is not None:
                try: old.remove()
                except Exception: pass
            if canvas is not None:
                try: canvas.draw_idle()
                except Exception: pass
            try: browser.log('Legend disabled for current browser plot.')
            except Exception: pass
            return
        handles = list(getattr(browser, '_v198_legend_handles', []) or [])
        labels = [h.get_label() for h in handles if getattr(h, 'get_label', lambda:'')() and not str(h.get_label()).startswith('_')]
        if handles and labels:
            hs, ls = handles, labels
        else:
            hs, ls = ax.get_legend_handles_labels()
            pairs = [(h,l) for h,l in zip(hs,ls) if l and not str(l).startswith('_')]
            hs=[p[0] for p in pairs]; ls=[p[1] for p in pairs]
        if not hs:
            return
        seen=set(); hs2=[]; ls2=[]
        for h,l in zip(hs,ls):
            l = str(l)
            if l in seen: continue
            seen.add(l); hs2.append(h); ls2.append(l)
        n = len(ls2)
        fontsize = 7 if n <= 12 else (6 if n <= 30 else 5)
        ncol = 1 if n <= 12 else (2 if n <= 30 else 3)
        old = ax.get_legend()
        if old is not None:
            try: old.remove()
            except Exception: pass
        leg = ax.legend(hs2, ls2, fontsize=fontsize, loc='upper right', ncol=ncol,
                        frameon=True, framealpha=0.84, title='Curves')
        try: leg.get_title().set_fontsize(fontsize)
        except Exception: pass
        if fig is not None:
            try: fig.tight_layout()
            except Exception: pass
        if canvas is not None:
            try: canvas.draw_idle()
            except Exception: pass
        try: browser.log(f'v198 legend displayed with {n} label(s); mode={mode}.')
        except Exception: pass
    except Exception as exc:
        try: browser.log(f'Could not apply v198 legend: {exc}')
        except Exception: pass


