# ---- FaradaIQ Studio v273 visible EIS frequency-gradient enforcement patch ----
# Fixes the prior issue where selecting "EIS Nyquist freq-color (-Zimag)"
# could still draw a normal single-color line when the cached H5 table used
# frequency column aliases such as f2, f2_Hz, or when the v191 renderer required
# a freq column before dispatching to the gradient renderer. This final override
# always uses the frequency-gradient renderer for EIS Nyquist freq-color modes,
# and falls back to row-order only when no numeric frequency column is present.
try:
    APP_TITLE = "FaradaIQ Studio v273"
except Exception:
    pass


def _v198_clean_col_name(c):
    try:
        return re.sub(r'[^a-z0-9]+', '', str(c).lower())
    except Exception:
        return ''


def _v198_h5_numeric_column_helpers(df):
    import pandas as _pd
    cols = list(getattr(df, 'columns', []))
    low = {c: _v198_clean_col_name(c) for c in cols}
    def find_any(patterns, prefer=None):
        pats = [_v198_clean_col_name(p) for p in patterns]
        prefer = [_v198_clean_col_name(p) for p in (prefer or [])]
        for c in cols:
            lc = low.get(c, '')
            if any(lc == p for p in prefer):
                return c
        for c in cols:
            lc = low.get(c, '')
            if any(lc == p for p in pats):
                return c
        for c in cols:
            lc = low.get(c, '')
            if any(p and p in lc for p in pats):
                return c
        return None
    def num(c):
        try:
            return _pd.to_numeric(df[c], errors='coerce').to_numpy(dtype=float)
        except Exception:
            return np.asarray([], dtype=float)
    # Include pySECCM/parser aliases: f2, f2_Hz, f2 (Hz), Freq, Frequency_Hz.
    freq = find_any([
        'frequencyhz','frequency_hz','frequency(hz)','freqhz','freq_hz','freq(hz)',
        'f2hz','f2_hz','f2(hz)','f2','fhz','f_hz','f','hz','frequency','freq'
    ], prefer=['frequencyhz','freqhz','f2hz','f2'])
    zr = find_any([
        'zrealohm','zreal_ohm','realzohm','realz_ohm','zreohm','zre_ohm',
        'realz','zreal','rez','zprime','zprimeohm','real'
    ], prefer=['zrealohm','realzohm','zreal','realz'])
    # Prefer the raw imaginary column for raw mode, but also expose explicit -Zimag if present.
    zi = find_any([
        'zimagohm','zimag_ohm','imagzohm','imagz_ohm','zimohm','zim_ohm',
        'imagz','zimag','imz','zdoubleprime','zdoubleprimeohm','imag'
    ], prefer=['zimagohm','imagzohm','zimag','imagz'])
    negzi = find_any([
        'negzimagohm','neg_zimag_ohm','minuszimagohm','negativezimagohm','negimagzohm',
        'negzimag','neg_zimag','minuszimag','negativezimag','negimagz','minusimagz'
    ], prefer=['negzimagohm','negzimag','neg_zimag_ohm'])
    mag = find_any([
        'zabsohm','zabs_ohm','impzohm','impz_ohm','zmodohm','zmod_ohm','modzohm',
        'zabs','impz','zmod','magnitude','mag','modulus'
    ])
    phase = find_any(['phasedeg','phase_deg','phase'])
    return {'freq': freq, 'zr': zr, 'zi': zi, 'negzi': negzi, 'mag': mag, 'phase': phase, 'num': num}


def _v198_get_cmap(browser=None):
    try:
        # Reuse the v191/v198 palette control if present.
        if '_v198b_get_cmap' in globals():
            return _v198b_get_cmap(browser)
        if '_v191b_get_cmap' in globals():
            return _v191b_get_cmap(browser)
    except Exception:
        pass
    try:
        import matplotlib.pyplot as _plt
        return _plt.get_cmap('Blues').reversed()
    except Exception:
        return None


def _v198_add_freq_colorbar(browser, freq, actual_frequency=True):
    try:
        from matplotlib.colors import LogNorm, Normalize
        import matplotlib as _mpl
        ax = getattr(browser, '_ax', None); fig = getattr(browser, '_figure', None)
        if ax is None or fig is None:
            return None
        # Remove any prior colorbars before adding the current one.
        for attr in ['_v191_eis_colorbar','_v191b_eis_colorbar','_v198_eis_colorbar','_v198b_eis_colorbar']:
            cb0 = getattr(browser, attr, None)
            if cb0 is not None:
                try: cb0.remove()
                except Exception: pass
                try: setattr(browser, attr, None)
                except Exception: pass
        f = np.asarray(freq, dtype=float)
        f = f[np.isfinite(f) & (f > 0)]
        if f.size == 0:
            return None
        if actual_frequency and f.size >= 2 and float(np.nanmax(f)) > float(np.nanmin(f)) > 0:
            norm = LogNorm(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f)))
            label = 'Frequency / Hz'
        else:
            norm = Normalize(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f)))
            label = 'Frequency order' if not actual_frequency else 'Frequency / Hz'
        sm = _mpl.cm.ScalarMappable(norm=norm, cmap=_v198_get_cmap(browser))
        sm.set_array([])
        cb = fig.colorbar(sm, ax=ax, pad=0.02, fraction=0.046)
        cb.set_label(label)
        browser._v198_eis_colorbar = cb
        browser._v198b_eis_colorbar = cb
        browser._v191_eis_colorbar = cb
        browser._v191b_eis_colorbar = cb
        return cb
    except Exception as exc:
        try: browser.log(f'v198 colorbar skipped: {exc}')
        except Exception: pass
        return None


def _v198_plot_frequency_gradient_xy(browser, x, y, freq, label, actual_frequency=True):
    try:
        from matplotlib.collections import LineCollection
        from matplotlib.lines import Line2D
        from matplotlib.colors import LogNorm, Normalize
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        f = np.asarray(freq, dtype=float)
        mask = np.isfinite(x) & np.isfinite(y)
        if f.shape == x.shape and actual_frequency:
            mask = mask & np.isfinite(f) & (f > 0)
        x = x[mask]; y = y[mask]
        if f.shape == mask.shape:
            f = f[mask]
        else:
            f = np.arange(len(x), 0, -1, dtype=float)
            actual_frequency = False
        if x.size < 2:
            return False
        # Plot in descending frequency when actual frequency is known, matching the instrument sweep.
        try:
            if actual_frequency and f.size == x.size:
                order = np.argsort(f)[::-1]
                x=x[order]; y=y[order]; f=f[order]
        except Exception:
            pass
        want_line, want_points = _v198_style_flags(browser) if '_v198_style_flags' in globals() else (_v191_style_flags(browser) if '_v191_style_flags' in globals() else (True, True))
        cmap = _v198_get_cmap(browser)
        if actual_frequency and f.size == x.size and np.nanmax(f) > np.nanmin(f) > 0:
            norm = LogNorm(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f)))
            cvals = f
        else:
            # High-frequency/order side is light, low-frequency/order side is dark using the reversed palette.
            norm = Normalize(vmin=0.0, vmax=1.0)
            cvals = np.linspace(1.0, 0.0, len(x))
        if want_line and x.size >= 2:
            pts = np.column_stack([x, y]).reshape(-1, 1, 2)
            seg = np.concatenate([pts[:-1], pts[1:]], axis=1)
            seg_c = (cvals[:-1] + cvals[1:]) / 2.0 if len(cvals) == len(x) else np.linspace(1.0, 0.0, len(seg))
            lc = LineCollection(seg, cmap=cmap, norm=norm, linewidths=2.0, alpha=0.96, label='_nolegend_')
            lc.set_array(seg_c)
            browser._ax.add_collection(lc)
            try:
                browser._ax.update_datalim(np.column_stack([x, y]))
                browser._ax.autoscale_view()
            except Exception:
                pass
        if want_points:
            browser._ax.scatter(x, y, c=cvals, cmap=cmap, norm=norm, s=34 if x.size <= 250 else 16,
                                edgecolors='none', alpha=0.98, label='_nolegend_')
        try:
            proxy_color = cmap(0.35) if cmap is not None else '#0f355e'
            proxy = Line2D([0], [0], color=proxy_color, marker='o' if want_points else None,
                           linestyle='-' if want_line else 'None', linewidth=2.0, markersize=4.8,
                           label=str(label)[:48])
            handles = list(getattr(browser, '_v191_legend_handles', []) or [])
            handles.append(proxy)
            browser._v191_legend_handles = handles
            browser._v198_legend_handles = handles
        except Exception:
            pass
        _v198_add_freq_colorbar(browser, f, actual_frequency=actual_frequency)
        return True
    except Exception as exc:
        try: browser.log(f'v198 frequency-gradient plot failed: {exc}')
        except Exception: pass
        return False


