def _v198_h5_plot_one(self, p, clear=False):
    if not self._ensure_plot_canvas():
        return
    try:
        if '_v198b_init_controls' in globals(): _v198b_init_controls(self)
        elif '_v191b_init_controls' in globals(): _v191b_init_controls(self)
        elif '_v191_init_h5_plot_controls' in globals(): _v191_init_h5_plot_controls(self)
    except Exception:
        pass
    try:
        df = _v138_csv_read(p) if '_v138_csv_read' in globals() else __import__('pandas').read_csv(p)
        cols = _v198_h5_numeric_column_helpers(df)
        num = cols.get('num')
        mode = str(getattr(self, 'plot_mode_var', tk.StringVar(value='Auto')).get() or 'Auto')
        mode_l = mode.lower()
        is_eis_table = bool(cols.get('zr') and (cols.get('zi') or cols.get('negzi'))) or ('eis' in str(p).lower() or 'nyquist' in str(p).lower() or 'bode' in str(p).lower())
        label = _v191_eis_label_for_path(p, getattr(self, 'last_plot_paths', [])) if '_v191_eis_label_for_path' in globals() else Path(p).stem[:48]
        nyq_requested = ('nyquist' in mode_l or mode_l == 'auto' or mode_l == 'eis nyquist')
        if is_eis_table and nyq_requested and cols.get('zr') and (cols.get('zi') or cols.get('negzi')):
            x = num(cols['zr'])
            raw_y = num(cols['zi']) if cols.get('zi') else np.asarray([], dtype=float)
            if 'raw' in mode_l:
                y = raw_y
                ylabel = 'ImagZ / Ohm'
            else:
                if cols.get('negzi'):
                    y = num(cols['negzi'])
                else:
                    y = raw_y.copy()
                    # Nyquist convention is -Zimag. If raw Zimag is negative, flip to positive.
                    try:
                        if np.nanmedian(y) < 0:
                            y = -y
                    except Exception:
                        pass
                ylabel = '-Zimag / Ohm'
            freq_col = cols.get('freq')
            actual_frequency = bool(freq_col)
            freq = num(freq_col) if freq_col else np.arange(len(x), 0, -1, dtype=float)
            mask = np.isfinite(x) & np.isfinite(y)
            if actual_frequency and len(freq) == len(mask):
                mask = mask & np.isfinite(freq) & (freq > 0)
            x = x[mask]; y = y[mask]
            freq = freq[mask] if len(freq) == len(mask) else np.arange(len(x), 0, -1, dtype=float)
            if x.size < 2:
                self.log(f'Not enough numeric EIS data: {Path(p).name}')
                return
            use_gradient = bool(getattr(self, 'eis_freq_gradient_var', tk.BooleanVar(value=True)).get())
            # Force gradient for the explicit freq-color mode, even if no frequency alias was recognized.
            if 'freq-color' in mode_l or 'gradient' in mode_l:
                use_gradient = True
            style = str(getattr(self, 'eis_plot_style_var', tk.StringVar(value='Line + Points')).get() or '')
            if use_gradient:
                ok = _v198_plot_frequency_gradient_xy(self, x, y, freq, label, actual_frequency=actual_frequency)
                if not ok:
                    # Visible fallback: still use a single reversed palette along row order.
                    _v198_plot_frequency_gradient_xy(self, x, y, np.arange(len(x), 0, -1, dtype=float), label, actual_frequency=False)
            else:
                want_line, want_points = _v198_style_flags(self) if '_v198_style_flags' in globals() else (_v191_style_flags(self) if '_v191_style_flags' in globals() else (True, True))
                self._ax.plot(x, y, linestyle='-' if want_line else 'None', marker='o' if want_points else None,
                              markersize=3.5, linewidth=1.5, color='#0f355e', label=label)
            self._ax.set_xlabel('Zreal / Ω')
            self._ax.set_ylabel(ylabel.replace('Ohm', 'Ω'))
            self._ax.set_title('EIS Nyquist frequency-gradient overlay' if use_gradient else 'EIS Nyquist overlay')
            try:
                xr = float(np.nanmax(x) - np.nanmin(x)); yr = float(np.nanmax(y) - np.nanmin(y))
                if xr > 0 and yr > 0 and 0.25 <= xr/yr <= 4.0:
                    self._ax.set_aspect('equal', adjustable='box')
                else:
                    self._ax.set_aspect('auto')
            except Exception:
                pass
            try:
                self._curves.append({'path': Path(p), 'xcol': cols.get('zr'), 'ycol': cols.get('negzi') or cols.get('zi'), 'detected': 'EIS Nyquist frequency-gradient', 'label': label})
                self.last_plot_paths.append(Path(p))
            except Exception:
                pass
            try:
                self.log(f'v198 plotted {Path(p).name}: EIS Nyquist frequency-gradient, freq_col={freq_col or "row-order fallback"}, style={style}')
            except Exception:
                pass
            return
    except Exception as exc:
        try: self.log(f'FaradaIQ v273 EIS gradient plot failed for {Path(p).name}: {exc}')
        except Exception: pass
    if callable(_V198_PREV_FINAL_H5_PLOT_ONE):
        return _V198_PREV_FINAL_H5_PLOT_ONE(self, p, clear=clear)


def _v198_h5_clear_plot(self):
    try:
        for attr in ['_v191_eis_colorbar','_v191b_eis_colorbar','_v198_eis_colorbar','_v198b_eis_colorbar']:
            cb = getattr(self, attr, None)
            if cb is not None:
                try: cb.remove()
                except Exception: pass
                try: setattr(self, attr, None)
                except Exception: pass
        self._v191_legend_handles = []
        self._v198_legend_handles = []
        if getattr(self, '_ax', None) is not None:
            self._ax.clear(); self._ax.grid(True, alpha=0.25); self._ax.set_aspect('auto')
            self._ax.set_title('Select files/groups and click Plot/overlay selected')
            if getattr(self, '_canvas', None) is not None:
                try: self._canvas.draw_idle()
                except Exception: pass
        self._curves=[]; self.last_plot_paths=[]
    except Exception:
        if callable(_V198_PREV_FINAL_CLEAR_PLOT):
            try: return _V198_PREV_FINAL_CLEAR_PLOT(self)
            except Exception: pass


