# ---- FaradaIQ Studio v273 no-default-root browser plotting fix ----
# Avoid constructing tk.StringVar/BooleanVar as getattr defaults during headless
# QA and normal non-root object initialization; some older overrides did that and
# could fall back to single-color plotting after an exception.

def _v198_var_value(obj, name, default=None):
    try:
        var = getattr(obj, name, None)
        if var is None:
            return default
        if hasattr(var, 'get'):
            return var.get()
        return var
    except Exception:
        return default


def _v198_style_flags(browser):
    style = str(_v198_var_value(browser, 'eis_plot_style_var', 'Line + Points') or 'Line + Points').strip().lower()
    want_line = 'line' in style
    want_points = 'point' in style
    if not want_line and not want_points:
        want_line = True
    return want_line, want_points


