def _v198c_text(w):
    try: return str(w.cget('text') or '')
    except Exception: return ''


def _v198c_textvar(w):
    try: return str(w.cget('textvariable') or '')
    except Exception: return ''


def _v198c_is_old_eis_control(browser, w):
    txt=_v198c_text(w).strip().lower().replace(' ', '')
    if txt in {'legend','freqgradient','palette'}:
        return True
    # Old mini-palette canvases are short horizontal canvases in the plot toolbar.
    try:
        if str(w.winfo_class()) == 'Canvas' and int(w.cget('height') or 0) <= 22:
            return True
    except Exception:
        pass
    try:
        tv=_v198c_textvar(w)
        for nm in ('eis_cmap_var',):
            var=getattr(browser,nm,None)
            if var is not None and str(var)==tv:
                return True
    except Exception:
        pass
    return False


def _v198c_forget_old_inline_controls(browser):
    def walk(w):
        try:
            for ch in list(w.winfo_children()):
                if getattr(ch, '_v198c_keep', False):
                    walk(ch); continue
                if _v198c_is_old_eis_control(browser, ch):
                    try: ch.pack_forget()
                    except Exception: pass
                    try: ch.grid_remove()
                    except Exception: pass
                    try: ch.place_forget()
                    except Exception: pass
                walk(ch)
        except Exception:
            pass
    try: walk(browser)
    except Exception: pass


def _v198c_find_mode_row(browser):
    try:
        plot_var=str(getattr(browser,'plot_mode_var',''))
        boxes=[]
        finder=globals().get('_v198_find_comboboxes') or globals().get('_v192_find_comboboxes')
        if callable(finder):
            boxes=finder(browser)
        for cb in boxes:
            try:
                if str(cb.cget('textvariable'))==plot_var:
                    return cb.master
            except Exception: pass
        found=None
        def walk(w):
            nonlocal found
            if found is not None: return
            try:
                kids=list(w.winfo_children())
                if any('max curves' in _v198c_text(k).lower() for k in kids):
                    found=w; return
                for k in kids: walk(k)
            except Exception: pass
        walk(browser)
        return found
    except Exception:
        return None


def _v198c_ensure_vars(browser):
    try:
        if '_v198b_init_controls' in globals(): _v198b_init_controls(browser)
        elif '_v192b_init_controls' in globals(): _v192b_init_controls(browser)
    except Exception: pass
    try:
        if not hasattr(browser,'eis_plot_style_var'): browser.eis_plot_style_var=tk.StringVar(value='Line + Points')
        if not hasattr(browser,'eis_freq_gradient_var'): browser.eis_freq_gradient_var=tk.BooleanVar(value=True)
        if not hasattr(browser,'legend_var'): browser.legend_var=tk.StringVar(value='On')
        if not hasattr(browser,'eis_cmap_var'): browser.eis_cmap_var=tk.StringVar(value='Blues')
    except Exception: pass


def _v198c_build_toolbar(browser, mode_row):
    try:
        _v198c_ensure_vars(browser)
        host=getattr(mode_row,'master',None) or mode_row
        strip=getattr(browser,'_v198c_eis_toolbar',None)
        if strip is None or not strip.winfo_exists():
            strip=ttk.Frame(host); strip._v198c_keep=True
            try: strip.pack(after=mode_row, fill='x', padx=(4,4), pady=(3,2))
            except Exception: strip.pack(fill='x', padx=(4,4), pady=(3,2))
            browser._v198c_eis_toolbar=strip
        for ch in list(strip.winfo_children()):
            try: ch.destroy()
            except Exception: pass
        row1=ttk.Frame(strip); row1._v198c_keep=True; row1.pack(fill='x', pady=(0,2))
        row2=ttk.Frame(strip); row2._v198c_keep=True; row2.pack(fill='x')
        ttk.Label(row1,text='EIS style',style='Muted.TLabel').pack(side='left',padx=(0,4))
        cb=ttk.Combobox(row1,textvariable=browser.eis_plot_style_var,state='readonly',width=15,values=['Line','Line + Points','Points']); cb._v198c_keep=True; cb.pack(side='left',padx=(0,12))
        fg=ttk.Checkbutton(row1,text='Freq gradient',variable=browser.eis_freq_gradient_var); fg._v198c_keep=True; fg.pack(side='left',padx=(0,12))
        lg=ttk.Checkbutton(row1,text='Legend',variable=browser.legend_var,onvalue='On',offvalue='Off'); lg._v198c_keep=True; lg.pack(side='left',padx=(0,12))
        ttk.Label(row2,text='Palette',style='Muted.TLabel').pack(side='left',padx=(0,4))
        vals=[]
        try:
            vals=_v198b_available_cmaps() if '_v198b_available_cmaps' in globals() else (_v192b_available_cmaps() if '_v192b_available_cmaps' in globals() else [])
        except Exception: vals=[]
        if not vals: vals=['Blues','Greys','viridis','plasma','inferno','magma','cividis','jet','rainbow','turbo','coolwarm','Spectral','tab10','tab20']
        pal=ttk.Combobox(row2,textvariable=browser.eis_cmap_var,state='readonly',width=24,values=vals); pal._v198c_keep=True; pal.pack(side='left',padx=(0,8))
        canv=tk.Canvas(row2,width=280,height=18,bd=0,highlightthickness=0,relief='flat'); canv._v198c_keep=True; canv.pack(side='left',padx=(0,8))
        browser._v198b_palette_canvas=canv
        browser._v192b_palette_canvas=canv
        try:
            renderer=globals().get('_v198b_render_palette_preview') or globals().get('_v192b_render_palette_preview')
            if callable(renderer): renderer(browser)
        except Exception: pass
        try:
            def _preview(*_a, b=browser):
                renderer=globals().get('_v198b_render_palette_preview') or globals().get('_v192b_render_palette_preview')
                if callable(renderer): renderer(b)
            browser.eis_cmap_var.trace_add('write', _preview)
        except Exception: pass
        try: browser.log('FaradaIQ v273 EIS controls are in a dedicated visible toolbar; old crowded inline controls hidden.')
        except Exception: pass
    except Exception as exc:
        try: browser.log(f'v198 toolbar build failed: {exc}')
        except Exception: pass


def _v198c_build_visible_ui(self):
    if getattr(self,'_v198c_in_build_ui',False):
        return
    self._v198c_in_build_ui=True
    try:
        if callable(_V198C_PREV_BUILD_UI) and _V198C_PREV_BUILD_UI is not _v198c_build_visible_ui:
            _V198C_PREV_BUILD_UI(self)
    finally:
        self._v198c_in_build_ui=False
    try:
        _v198c_forget_old_inline_controls(self)
        row=_v198c_find_mode_row(self)
        if row is not None:
            _v198c_build_toolbar(self,row)
        _v198c_forget_old_inline_controls(self)
    except Exception as exc:
        try: self.log(f'v198 visible-toolbar setup skipped: {exc}')
        except Exception: pass


def _v198c_get_cmap(browser):
    try:
        if '_v198_get_cmap' in globals(): return _v198_get_cmap(browser)
        if '_v192_get_cmap' in globals(): return _v192_get_cmap(browser)
        if '_v198b_get_cmap' in globals(): return _v198b_get_cmap(browser)
        if '_v192b_get_cmap' in globals(): return _v192b_get_cmap(browser)
    except Exception: pass
    try:
        import matplotlib.pyplot as _plt
        return _plt.get_cmap('Blues').reversed()
    except Exception:
        return None


def _v198c_reserve_space(browser):
    try:
        fig=getattr(browser,'_figure',None)
        if fig is None: return
        handles=list(getattr(browser,'_v198c_legend_handles',[]) or getattr(browser,'_v198_legend_handles',[]) or getattr(browser,'_v192_legend_handles',[]) or [])
        n=len(handles)
        has_cb=any(getattr(browser,a,None) is not None for a in ['_v198c_eis_colorbar','_v198_eis_colorbar','_v192_eis_colorbar','_v192b_eis_colorbar'])
        mode='On'
        try: mode=str(browser.legend_var.get() or 'On')
        except Exception: pass
        if mode.lower() in {'off','false','0','no'}:
            right=0.88 if has_cb else 0.96
        else:
            right=0.72 if n>8 else (0.82 if has_cb else 0.94)
        fig.subplots_adjust(left=0.10,bottom=0.12,right=right,top=0.90)
    except Exception: pass


def _v198c_add_freq_colorbar(browser,freq,actual_frequency=True):
    try:
        from matplotlib.colors import LogNorm, Normalize
        import matplotlib as _mpl
        fig=getattr(browser,'_figure',None); ax=getattr(browser,'_ax',None)
        if fig is None or ax is None: return None
        for attr in ['_v198c_eis_colorbar','_v198_eis_colorbar','_v198b_eis_colorbar','_v192_eis_colorbar','_v192b_eis_colorbar']:
            cb=getattr(browser,attr,None)
            if cb is not None:
                try: cb.remove()
                except Exception: pass
                try: setattr(browser,attr,None)
                except Exception: pass
        f=np.asarray(freq,dtype=float); f=f[np.isfinite(f)&(f>0)]
        if f.size<2: return None
        if actual_frequency and float(np.nanmax(f))>float(np.nanmin(f))>0:
            norm=LogNorm(vmin=float(np.nanmin(f)),vmax=float(np.nanmax(f))); label='Frequency / Hz'
        else:
            norm=Normalize(vmin=float(np.nanmin(f)),vmax=float(np.nanmax(f))); label='Frequency order'
        sm=_mpl.cm.ScalarMappable(norm=norm,cmap=_v198c_get_cmap(browser)); sm.set_array([])
        cb=fig.colorbar(sm,ax=ax,pad=0.015,fraction=0.035,shrink=0.90)
        cb.set_label(label)
        for attr in ['_v198c_eis_colorbar','_v198_eis_colorbar','_v192_eis_colorbar','_v192b_eis_colorbar']:
            try: setattr(browser,attr,cb)
            except Exception: pass
        _v198c_reserve_space(browser)
        return cb
    except Exception as exc:
        try: browser.log(f'v198 colorbar skipped: {exc}')
        except Exception: pass
        return None


def _v198c_style_flags(browser):
    try:
        if '_v198_style_flags' in globals(): return _v198_style_flags(browser)
        if '_v192_style_flags' in globals(): return _v192_style_flags(browser)
    except Exception: pass
    try: style=str(browser.eis_plot_style_var.get() or 'Line + Points').lower()
    except Exception: style='line + points'
    line='line' in style; pts='point' in style
    if not line and not pts: line=True
    return line,pts


def _v198c_add_proxy(browser,label,want_line=True,want_points=True):
    try:
        from matplotlib.lines import Line2D
        cmap=_v198c_get_cmap(browser); color=cmap(0.42) if cmap is not None else '#1f77b4'
        proxy=Line2D([0],[0],color=color,marker='o' if want_points else None,linestyle='-' if want_line else 'None',linewidth=2.0,markersize=4.5,label=str(label)[:48])
        handles=list(getattr(browser,'_v198c_legend_handles',[]) or [])
        handles.append(proxy)
        browser._v198c_legend_handles=handles
        browser._v198_legend_handles=handles
        browser._v192_legend_handles=handles
    except Exception: pass


def _v198c_plot_frequency_gradient_xy(browser,x,y,freq,label,actual_frequency=True):
    try:
        from matplotlib.collections import LineCollection
        from matplotlib.colors import LogNorm, Normalize
        x=np.asarray(x,dtype=float); y=np.asarray(y,dtype=float); f=np.asarray(freq,dtype=float)
        mask=np.isfinite(x)&np.isfinite(y)
        if f.shape==x.shape and actual_frequency: mask=mask&np.isfinite(f)&(f>0)
        x=x[mask]; y=y[mask]
        if f.shape==mask.shape: f=f[mask]
        else:
            f=np.arange(len(x),0,-1,dtype=float); actual_frequency=False
        if x.size<2: return False
        try:
            if actual_frequency and f.size==x.size:
                order=np.argsort(f)[::-1]; x=x[order]; y=y[order]; f=f[order]
        except Exception: pass
        want_line,want_points=_v198c_style_flags(browser)
        cmap=_v198c_get_cmap(browser)
        if actual_frequency and f.size==x.size and float(np.nanmax(f))>float(np.nanmin(f))>0:
            norm=LogNorm(vmin=float(np.nanmin(f)),vmax=float(np.nanmax(f))); cvals=f
        else:
            norm=Normalize(vmin=0.0,vmax=1.0); cvals=np.linspace(1.0,0.0,len(x))
        if want_line and x.size>=2:
            pts=np.column_stack([x,y]).reshape(-1,1,2)
            seg=np.concatenate([pts[:-1],pts[1:]],axis=1)
            seg_c=(cvals[:-1]+cvals[1:])/2.0 if len(cvals)==len(x) else np.linspace(1.0,0.0,len(seg))
            lc=LineCollection(seg,cmap=cmap,norm=norm,linewidths=2.0,alpha=0.98,label='_nolegend_')
            lc.set_array(seg_c); browser._ax.add_collection(lc)
            try:
                browser._ax.update_datalim(np.column_stack([x,y])); browser._ax.autoscale_view()
            except Exception: pass
        if want_points:
            browser._ax.scatter(x,y,c=cvals,cmap=cmap,norm=norm,s=34 if x.size<=250 else 16,edgecolors='none',alpha=0.98,label='_nolegend_')
        try: browser._ax.set_aspect('auto')
        except Exception: pass
        _v198c_add_proxy(browser,label,want_line,want_points)
        _v198c_add_freq_colorbar(browser,f,actual_frequency=actual_frequency)
        return True
    except Exception as exc:
        try: browser.log(f'v198 frequency-gradient plot failed: {exc}')
        except Exception: pass
        return False


def _v198c_apply_legend(browser,force=False):
    try:
        ax=getattr(browser,'_ax',None); canvas=getattr(browser,'_canvas',None)
        if ax is None: return
        old=ax.get_legend()
        if old is not None:
            try: old.remove()
            except Exception: pass
        mode='On'
        try: mode=str(browser.legend_var.get() or 'On')
        except Exception: pass
        if mode.lower() in {'off','false','0','no'}:
            _v198c_reserve_space(browser)
            if canvas is not None:
                try: canvas.draw_idle()
                except Exception: pass
            return
        handles=list(getattr(browser,'_v198c_legend_handles',[]) or getattr(browser,'_v198_legend_handles',[]) or getattr(browser,'_v192_legend_handles',[]) or [])
        labels=[str(h.get_label()) for h in handles if getattr(h,'get_label',lambda:'')() and not str(h.get_label()).startswith('_')]
        if not handles or not labels:
            hs,ls=ax.get_legend_handles_labels(); pairs=[(h,str(l)) for h,l in zip(hs,ls) if l and not str(l).startswith('_')]
            handles=[p[0] for p in pairs]; labels=[p[1] for p in pairs]
        if not handles:
            _v198c_reserve_space(browser)
            if canvas is not None:
                try: canvas.draw_idle()
                except Exception: pass
            return
        seen=set(); hs2=[]; ls2=[]
        for h,l in zip(handles,labels):
            if l in seen: continue
            seen.add(l); hs2.append(h); ls2.append(l)
        n=len(ls2); fontsize=7 if n<=10 else (6 if n<=24 else 5)
        if n>8:
            ncol=1 if n<=18 else 2
            leg=ax.legend(hs2,ls2,fontsize=fontsize,loc='upper left',bbox_to_anchor=(1.02,1.0),borderaxespad=0.0,frameon=True,framealpha=0.88,title='Curves',ncol=ncol,handlelength=2.0,columnspacing=0.9,labelspacing=0.3)
        else:
            leg=ax.legend(hs2,ls2,fontsize=fontsize,loc='best',frameon=True,framealpha=0.88,title='Curves')
        try: leg.get_title().set_fontsize(fontsize)
        except Exception: pass
        _v198c_reserve_space(browser)
        if canvas is not None:
            try: canvas.draw_idle()
            except Exception: pass
    except Exception as exc:
        try: browser.log(f'Could not apply v198 legend: {exc}')
        except Exception: pass


def _v198c_plot_one(self,p,clear=False):
    out=_V198C_PREV_PLOT_ONE(self,p,clear=clear) if callable(_V198C_PREV_PLOT_ONE) else None
    try:
        if getattr(self,'_ax',None) is not None: self._ax.set_aspect('auto')
        _v198c_reserve_space(self)
    except Exception: pass
    return out


def _v198c_plot_selected(self,clear=True):
    try:
        if clear:
            self._v198c_legend_handles=[]; self._v198_legend_handles=[]; self._v192_legend_handles=[]
    except Exception: pass
    out=_V198C_PREV_PLOT_SELECTED(self,clear=clear) if callable(_V198C_PREV_PLOT_SELECTED) else None
    try:
        _v198c_apply_legend(self)
        if getattr(self,'_ax',None) is not None: self._ax.set_aspect('auto')
        _v198c_reserve_space(self)
        if getattr(self,'_canvas',None) is not None: self._canvas.draw_idle()
    except Exception: pass
    return out


def _v198c_clear_plot(self):
    try:
        self._v198c_legend_handles=[]; self._v198_legend_handles=[]; self._v192_legend_handles=[]
    except Exception: pass
    out=_V198C_PREV_CLEAR_PLOT(self) if callable(_V198C_PREV_CLEAR_PLOT) else None
    try:
        for attr in ['_v198c_eis_colorbar','_v198_eis_colorbar','_v192_eis_colorbar','_v192b_eis_colorbar']:
            cb=getattr(self,attr,None)
            if cb is not None:
                try: cb.remove()
                except Exception: pass
                try: setattr(self,attr,None)
                except Exception: pass
    except Exception: pass
    return out

