def _v198_widget_text(w):
    try: return str(w.cget('text') or '')
    except Exception: return ''

def _v198_widget_textvar(w):
    try: return str(w.cget('textvariable') or '')
    except Exception: return ''

def _v198_is_descendant(w, anc):
    try:
        while w is not None:
            if w is anc: return True
            w = getattr(w, 'master', None)
    except Exception: pass
    return False

def _v198_remove_duplicate_eis_controls(browser):
    """Hide old crowded-row EIS controls, including duplicate EIS style, outside the dedicated toolbar."""
    try:
        keep_roots = [getattr(browser, '_v198_eis_toolbar', None), getattr(browser, '_v195c_eis_toolbar', None), getattr(browser, '_v195b_eis_toolbar', None)]
        keep_roots = [k for k in keep_roots if k is not None]
        eis_style_var = str(getattr(browser, 'eis_plot_style_var', ''))
        cmap_var = str(getattr(browser, 'eis_cmap_var', ''))
        def in_keep(w):
            return any(_v198_is_descendant(w, k) for k in keep_roots)
        def walk(w):
            try:
                for ch in list(w.winfo_children()):
                    if not in_keep(ch):
                        txt=_v198_widget_text(ch).strip().lower().replace(' ','')
                        tv=_v198_widget_textvar(ch)
                        cls=''
                        try: cls=str(ch.winfo_class())
                        except Exception: pass
                        hide=False
                        if txt in {'eisstyle','freqgradient','legend','palette'}:
                            hide=True
                        if tv and tv in {eis_style_var, cmap_var}:
                            hide=True
                        try:
                            if cls == 'Canvas' and int(ch.cget('height') or 0) <= 24:
                                hide=True
                        except Exception: pass
                        if hide:
                            for fn in ('pack_forget','grid_remove','place_forget'):
                                try: getattr(ch, fn)()
                                except Exception: pass
                    walk(ch)
            except Exception: pass
        walk(browser)
    except Exception: pass

def _v198_build_visible_ui(self):
    # Call the stable v198/v195 UI builder once, then only hide duplicate inline controls.
    if getattr(self, '_v198_in_build_ui', False):
        return
    self._v198_in_build_ui = True
    try:
        if callable(_V198_PREV_BUILD_UI) and _V198_PREV_BUILD_UI is not _v198_build_visible_ui:
            _V198_PREV_BUILD_UI(self)
    finally:
        self._v198_in_build_ui = False
    try:
        _v198_remove_duplicate_eis_controls(self)
        # Mark the existing dedicated toolbar so future cleanup preserves it.
        tb = getattr(self, '_v195c_eis_toolbar', None) or getattr(self, '_v195b_eis_toolbar', None)
        if tb is not None:
            self._v198_eis_toolbar = tb
    except Exception as exc:
        try: self.log(f'v198 duplicate-control cleanup skipped: {exc}')
        except Exception: pass


def _v198_remove_colorbars(browser):
    """Remove all non-main axes created by previous colorbars, even if older attrs missed them."""
    try:
        fig=getattr(browser,'_figure',None); ax=getattr(browser,'_ax',None)
        if fig is not None:
            for a in list(getattr(fig,'axes',[]) or []):
                if ax is not None and a is ax: continue
                try: a.remove()
                except Exception: pass
        for attr in ['_v198_eis_colorbar','_v195c_eis_colorbar','_v195_eis_colorbar','_v195b_eis_colorbar','_v192_eis_colorbar','_v192b_eis_colorbar']:
            try: setattr(browser, attr, None)
            except Exception: pass
    except Exception: pass

def _v198_fixed_axes(browser):
    """A deterministic axes rectangle; repeated plotting cannot keep shrinking it."""
    try:
        fig=getattr(browser,'_figure',None); ax=getattr(browser,'_ax',None)
        if fig is None or ax is None: return
        try: fig.set_constrained_layout(False)
        except Exception: pass
        try: ax.set_aspect('auto', adjustable='box')
        except Exception: pass
        try: ax.set_box_aspect(None)
        except Exception: pass
        # Use a stable absolute axes position. Legend and colorbar stay inside this box.
        try: ax.set_position([0.10, 0.12, 0.82, 0.78])
        except Exception:
            try: fig.subplots_adjust(left=0.10, right=0.92, bottom=0.12, top=0.90)
            except Exception: pass
    except Exception: pass

def _v198_add_freq_colorbar(browser, freq, actual_frequency=True):
    """Inset colorbar inside the axes. It never changes figure margins or axes width."""
    try:
        from matplotlib.colors import LogNorm, Normalize
        import matplotlib as _mpl
        from mpl_toolkits.axes_grid1.inset_locator import inset_axes
        ax=getattr(browser,'_ax',None)
        if ax is None: return None
        _v198_remove_colorbars(browser)
        f=np.asarray(freq,dtype=float); f=f[np.isfinite(f)&(f>0)]
        if f.size<2: return None
        if actual_frequency and float(np.nanmax(f))>float(np.nanmin(f))>0:
            norm=LogNorm(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f))); label='Frequency / Hz'
        else:
            norm=Normalize(vmin=float(np.nanmin(f)), vmax=float(np.nanmax(f))); label='Frequency order'
        cmap=None
        for nm in ('_v195c_get_cmap','_v195_get_cmap','_v192_get_cmap','_v192b_get_cmap'):
            fn=globals().get(nm)
            if callable(fn):
                try:
                    cmap=fn(browser)
                    if cmap is not None: break
                except Exception: pass
        if cmap is None:
            import matplotlib.pyplot as _plt
            cmap=_plt.get_cmap('Blues').reversed()
        sm=_mpl.cm.ScalarMappable(norm=norm,cmap=cmap); sm.set_array([])
        # Inset in upper-right of plot area, so no axes stealing / no left squeeze.
        cax=inset_axes(ax, width='3.2%', height='48%', loc='upper right', borderpad=1.15)
        cb=ax.figure.colorbar(sm, cax=cax)
        cb.set_label(label, fontsize=8)
        try: cb.ax.tick_params(labelsize=7)
        except Exception: pass
        for attr in ['_v198_eis_colorbar','_v195c_eis_colorbar','_v195_eis_colorbar','_v192_eis_colorbar','_v192b_eis_colorbar']:
            try: setattr(browser, attr, cb)
            except Exception: pass
        _v198_fixed_axes(browser)
        return cb
    except Exception as exc:
        try: browser.log(f'v198 inset colorbar skipped: {exc}')
        except Exception: pass
        return None

def _v198_apply_legend(browser, force=False):
    """Compact inside-axes legend. It never reserves new right margin."""
    try:
        ax=getattr(browser,'_ax',None); canvas=getattr(browser,'_canvas',None)
        if ax is None: return
        old=ax.get_legend()
        if old is not None:
            try: old.remove()
            except Exception: pass
        mode='On'
        try: mode=str(browser.legend_var.get() or 'On')
        except Exception: pass
        if mode.lower() in {'off','false','0','no'}:
            _v198_fixed_axes(browser)
            if canvas is not None:
                try: canvas.draw_idle()
                except Exception: pass
            return
        handles=list(getattr(browser,'_v195c_legend_handles',[]) or getattr(browser,'_v195_legend_handles',[]) or getattr(browser,'_v192_legend_handles',[]) or [])
        labels=[str(h.get_label()) for h in handles if getattr(h,'get_label',lambda:'')() and not str(h.get_label()).startswith('_')]
        if not handles or not labels:
            hs,ls=ax.get_legend_handles_labels(); pairs=[(h,str(l)) for h,l in zip(hs,ls) if l and not str(l).startswith('_')]
            handles=[p[0] for p in pairs]; labels=[p[1] for p in pairs]
        if handles and labels:
            seen=set(); hs2=[]; ls2=[]
            for h,l in zip(handles,labels):
                if l in seen: continue
                seen.add(l); hs2.append(h); ls2.append(l)
            n=len(ls2); fontsize=7 if n<=8 else (6 if n<=20 else 5)
            ncol=1 if n<=10 else (2 if n<=30 else 3)
            leg=ax.legend(hs2, ls2, fontsize=fontsize, loc='upper left', frameon=True, framealpha=0.78,
                          title='Curves', ncol=ncol, handlelength=1.6, columnspacing=0.7, labelspacing=0.25)
            try: leg.get_title().set_fontsize(fontsize)
            except Exception: pass
        _v198_fixed_axes(browser)
        if canvas is not None:
            try: canvas.draw_idle()
            except Exception: pass
    except Exception as exc:
        try: browser.log(f'Could not apply v198 legend: {exc}')
        except Exception: pass

def _v198_clear_plot(self):
    # Clear plot without fig.clear and remove any old colorbar axes first/after.
    try:
        _v198_remove_colorbars(self)
    except Exception: pass
    out=None
    try:
        if callable(_V198_PREV_CLEAR_PLOT): out=_V198_PREV_CLEAR_PLOT(self)
        elif getattr(self,'_ax',None) is not None:
            self._ax.clear(); self._ax.grid(True, alpha=0.25); self._curves=[]; self.last_plot_paths=[]
    except Exception: pass
    try:
        _v198_remove_colorbars(self)
        self._v195c_legend_handles=[]; self._v195_legend_handles=[]; self._v192_legend_handles=[]
        if getattr(self,'_ax',None) is not None:
            self._ax.grid(True, alpha=0.25)
            self._ax.set_aspect('auto', adjustable='box')
        _v198_fixed_axes(self)
        if getattr(self,'_canvas',None) is not None: self._canvas.draw_idle()
    except Exception: pass
    return out

def _v198_plot_selected(self, clear=True):
    try:
        if clear:
            _v198_clear_plot(self)
        _v198_remove_duplicate_eis_controls(self)
    except Exception: pass
    out=None
    try:
        if callable(_V198_PREV_PLOT_SELECTED): out=_V198_PREV_PLOT_SELECTED(self, clear=False if clear else clear)
    finally:
        try:
            _v198_remove_colorbars(self)  # remove any margin-stealing colorbar made by older path
            # Re-add inset colorbar from last detected frequency if older plotter stored one? If no, next gradient call will add it.
            # Existing gradient line/points remain; only the old cbar axes are removed. The gradient helper below is patched too.
            _v198_apply_legend(self)
            if getattr(self,'_ax',None) is not None:
                self._ax.set_aspect('auto', adjustable='box')
            _v198_fixed_axes(self)
            if getattr(self,'_canvas',None) is not None: self._canvas.draw_idle()
        except Exception: pass
    return out

def _v198_plot_one(self, p, clear=False):
    if clear:
        _v198_clear_plot(self)
        clear=False
    out=_V198_PREV_PLOT_ONE(self,p,clear=clear) if callable(_V198_PREV_PLOT_ONE) else None
    try:
        if getattr(self,'_ax',None) is not None: self._ax.set_aspect('auto', adjustable='box')
        _v198_fixed_axes(self)
    except Exception: pass
    return out

