        if not hasattr(browser, 'eis_freq_gradient_var'): browser.eis_freq_gradient_var = tk.BooleanVar(value=True)
        if not hasattr(browser, 'legend_var'): browser.legend_var = tk.StringVar(value='On')
        if not hasattr(browser, 'eis_cmap_var'): browser.eis_cmap_var = tk.StringVar(value='Blues')
