def _v199_label_for_path(path):
    try:
        s=Path(path).stem; mp=re.search(r'point[_\- ]*0*(\d+)',s,re.I); mm=re.search(r'method[_\- ]*0*(\d+)',s,re.I); parts=[]
        if mp: parts.append(f'P{int(mp.group(1)):02d}')
        if mm: parts.append(f'M{int(mm.group(1)):02d}')
        return ' '.join(parts) if parts else s[:48]
    except Exception: return 'curve'

def _v199_plot_eis(browser,p,df,cols,mode_l):
    from matplotlib.collections import LineCollection
    from matplotlib.colors import LogNorm, Normalize
    num=cols['num']; x=num(cols['zr']); raw_y=num(cols['zi']) if cols.get('zi') else np.asarray([],dtype=float)
    if 'raw' in mode_l: y=raw_y; ylabel='ImagZ / Ω'
    else:
        if cols.get('negzi'): y=num(cols['negzi'])
        else:
            y=raw_y.copy()
            try:
                if np.nanmedian(y)<0: y=-y
            except Exception: pass
        ylabel='-Zimag / Ω'
    freq_col=cols.get('freq'); freq=num(freq_col) if freq_col else np.arange(len(x),0,-1,dtype=float)
    mask=np.isfinite(x)&np.isfinite(y); actual=bool(freq_col)
    if actual and len(freq)==len(mask): mask=mask&np.isfinite(freq)&(freq>0)
    x=x[mask]; y=y[mask]; freq=freq[mask] if len(freq)==len(mask) else np.arange(len(x),0,-1,dtype=float)
    if len(x)<2:
        browser.log(f'Not enough EIS data: {Path(p).name}'); return False
    try:
        if actual:
            order=np.argsort(freq)[::-1]; x=x[order]; y=y[order]; freq=freq[order]
    except Exception: pass
    label=_v199_label_for_path(p); want_line,want_points=_v199_style_flags(browser)
    use_gradient=bool(_v199_var(browser,'eis_freq_gradient_var',True)) or 'freq' in mode_l or 'gradient' in mode_l
    if use_gradient:
        cmap=_v199_get_cmap(browser)
        if actual and np.nanmax(freq)>np.nanmin(freq)>0:
            norm=LogNorm(vmin=float(np.nanmin(freq)),vmax=float(np.nanmax(freq))); cvals=freq; cb_label='Frequency / Hz'
        else:
            norm=Normalize(vmin=0.0,vmax=1.0); cvals=np.linspace(1.0,0.0,len(x)); cb_label='Frequency order'
        if want_line:
            pts=np.column_stack([x,y]).reshape(-1,1,2); seg=np.concatenate([pts[:-1],pts[1:]],axis=1); seg_c=(cvals[:-1]+cvals[1:])/2.0 if len(cvals)==len(x) else np.linspace(1.0,0.0,len(seg))
            lc=LineCollection(seg,cmap=cmap,norm=norm,linewidths=2.0,alpha=0.98,label='_nolegend_'); lc.set_array(seg_c); browser._ax.add_collection(lc); browser._ax.update_datalim(np.column_stack([x,y])); browser._ax.autoscale_view()
        if want_points:
            browser._ax.scatter(x,y,c=cvals,cmap=cmap,norm=norm,s=34 if len(x)<=250 else 16,edgecolors='none',alpha=0.98,label='_nolegend_')
        _v199_inset_colorbar(browser,norm,cmap,cb_label); _v199_add_proxy(browser,label,want_line,want_points)
    else:
        browser._ax.plot(x,y,linestyle='-' if want_line else 'None',marker='o' if want_points else None,markersize=3.5,linewidth=1.5,label=label)
    browser._ax.set_xlabel('Zreal / Ω'); browser._ax.set_ylabel(ylabel); browser._ax.set_title('EIS Nyquist frequency-gradient overlay' if use_gradient else 'EIS Nyquist overlay'); browser._ax.set_aspect('auto',adjustable='box')
    try: browser._curves.append({'path':Path(p),'xcol':cols.get('zr'),'ycol':cols.get('negzi') or cols.get('zi'),'detected':'EIS Nyquist','label':label}); browser.last_plot_paths.append(Path(p))
    except Exception: pass
    return True

def _v199_plot_one(self,p,clear=False):
    if clear: _v199_reset_axes(self)
    if not self._ensure_plot_canvas(): return
    try:
        import pandas as _pd
        df=_v138_csv_read(p) if '_v138_csv_read' in globals() else _pd.read_csv(p); cols=_v199_cols(df); mode=str(_v199_var(self,'plot_mode_var','Auto') or 'Auto').lower()
        is_eis=bool(cols.get('zr') and (cols.get('zi') or cols.get('negzi'))) or ('eis' in str(p).lower() or 'nyquist' in str(p).lower())
        if is_eis and (mode=='auto' or 'nyquist' in mode or 'eis' in mode): return _v199_plot_eis(self,p,df,cols,mode)
    except Exception as exc:
        try: self.log(f'v199 direct plot failed for {Path(p).name}: {exc}')
        except Exception: pass
    return _V199_PREV_PLOT_ONE(self,p,clear=False) if callable(_V199_PREV_PLOT_ONE) else None

def _v199_plot_selected(self,clear=True):
    paths=self.selected_paths(plottable_only=True)
    if not paths:
        try: messagebox.showinfo('No table selected','Select one or more table files or a group in the experiment map.',parent=self)
        except Exception: pass
        return
    try: maxn=max(1,int(float(self.max_curves_var.get())))
    except Exception: maxn=24
    if clear:
        if not _v199_reset_axes(self): return
    else:
        if not self._ensure_plot_canvas(): return
    _v199_remove_extra_axes(self); _v199_hide_old_controls(self)
    for p in paths[:maxn]: self._plot_one(p,clear=False)
    try:
        self._ax.grid(True,alpha=0.25); self._ax.set_aspect('auto',adjustable='box'); _v199_apply_legend(self); self._figure.subplots_adjust(left=0.10,right=0.94,bottom=0.12,top=0.90); self._canvas.draw_idle()
        if len(paths)>maxn: self.log(f'Plotted first {maxn} of {len(paths)} selected files. Increase Max curves to show more.')
    except Exception as exc:
        try: self.log(f'v199 final plot layout failed: {exc}')
        except Exception: pass

def _v199_clear_plot(self):
    try:
        if self._ensure_plot_canvas():
            _v199_reset_axes(self); self._ax.set_title('Select files/groups and click Plot/overlay selected'); self._canvas.draw_idle()
    except Exception: pass

