def faradaiq_v199_parser_command_summary(data_dir, script_root=None, include_drt=True):
    s = faradaiq_v198_parser_command_summary(data_dir, script_root=script_root, include_drt=include_drt)
    try:
        cmds = s.get('commands') or []
        def count_script(name):
            return sum(1 for c in cmds if any(str(a).endswith(name) for a in (c.get('args') or [])))
        s.setdefault('n_parse_CV_commands', count_script('parse_CV.py'))
        s.setdefault('n_parse_EIS_commands', count_script('parse_EIS.py'))
        s.setdefault('n_parse_CA_commands', count_script('parse_CA.py'))
        s.setdefault('n_parse_CP_commands', count_script('parse_CP.py'))
        s.setdefault('n_parse_IV_commands', count_script('parse_IV.py'))
        s.setdefault('n_parse_OCP_commands', count_script('parse_OCP.py'))
    except Exception:
        pass
    return s
