def _v206_norm_col(s):
    return re.sub(r'[^a-z0-9]+', '', str(s).strip().lower())


def _v206_pick(cols, names, prefer=()):
    norm = {_v206_norm_col(c): c for c in cols}
    for n in list(prefer) + list(names):
        nn = _v206_norm_col(n)
        if nn in norm:
            return norm[nn]
    for c in cols:
        cn = _v206_norm_col(c)
        for n in names:
            if _v206_norm_col(n) and _v206_norm_col(n) in cn:
                return c
    return None


def _v206_columns(df):
    cols = list(getattr(df, 'columns', []))
    return {
        'freq': _v206_pick(cols, ['frequency_hz','frequency hz','frequency/Hz','frequency','freq_hz','freq hz','freq','f2_hz','f2','f','Hz'], prefer=['frequency_hz','freq_hz','f2_hz','f2']),
        'zr': _v206_pick(cols, ['zreal_ohm','zreal ohm','zreal','realz_ohm','realz ohm','realz','zre','zprime','real']),
        'zi': _v206_pick(cols, ['zimag_ohm','zimag ohm','zimag','imagz_ohm','imagz ohm','imagz','zim','imz','zdoubleprime','imag']),
        'negzi': _v206_pick(cols, ['-zimag','neg_zimag_ohm','neg zimag ohm','neg_zimag','negzimag','minus_zimag','minuszimag','negative_zimag','negativezimag']),
        'zmod': _v206_pick(cols, ['zmod_ohm','zmod ohm','zmod','zabs_ohm','zabs ohm','zabs','impz','magnitude','modulus']),
        'phase': _v206_pick(cols, ['phase_deg','phase deg','phase']),
        'pot': _v206_pick(cols, ['potential_v','potential v','potential','e_v','e v','Ewe','voltage_v','voltage','E']),
        'cur': _v206_pick(cols, ['current_a','current a','current','i_a','i a','imon','Imon','amps','I']),
        'time': _v206_pick(cols, ['time_s','time s','time','t_s','t s','t']),
        'charge': _v206_pick(cols, ['charge_c','charge c','charge','q_c','q c','q']),
        'tau': _v206_pick(cols, ['tau','tau_s','tau s','timescale']),
        'gamma': _v206_pick(cols, ['gamma','gamma_ohm','gamma ohm','drt']),
    }


def _v206_numeric(df, col):
    import pandas as _pd
    if col is None:
        return np.asarray([], dtype=float)
    return _pd.to_numeric(df[col], errors='coerce').to_numpy(dtype=float)


def _v206_safe_label(path):
    p = Path(path)
    stem = p.stem
    m_point = re.search(r'(?:point|pt)[_\-\s]*(\d+)', stem, re.I)
    m_method = re.search(r'(?:method|m)[_\-\s]*(\d+)', stem, re.I)
    m_cycle = re.search(r'(?:cycle|c)[_\-\s]*(\d+)', stem, re.I)
    parts = []
    if m_point: parts.append(f"P{int(m_point.group(1)):02d}")
    if m_method: parts.append(f"M{int(m_method.group(1)):02d}")
    if m_cycle: parts.append(f"C{int(m_cycle.group(1)):02d}")
    return ' '.join(parts) if parts else stem[:55]


def _v206_tech_for_file(path, df, mode='Auto'):
    cols = _v206_columns(df)
    name = Path(path).name.lower()
    mode_l = str(mode or '').lower()
    if cols.get('zr') and (cols.get('zi') or cols.get('negzi')):
        return 'EIS', cols
    if cols.get('tau') and cols.get('gamma'):
        return 'DRT', cols
    if any(tok in name for tok in ['ca','cp','chrono','chronopot','chronoamp']) and cols.get('time') and cols.get('cur'):
        return 'CA/CP', cols
    if cols.get('pot') and cols.get('cur'):
        return 'CV/LSV/IV', cols
    if cols.get('time') and cols.get('cur'):
        return 'CA/CP', cols
    return 'Numeric', cols


def _v206_available_palettes():
    return ['Blues','Greys','viridis','plasma','inferno','magma','cividis','turbo','jet','rainbow','coolwarm','Spectral','YlGnBu','YlOrRd','PuBu','GnBu']


def _v206_get_cmap(browser):
    import matplotlib.pyplot as _plt
    name = 'Blues'
    try: name = browser.eis_cmap_var.get() or 'Blues'
    except Exception: pass
    try:
        # Reversed sequential maps: high frequency is lighter, low frequency darker for Blues/Greys.
        if name in {'Blues','Greys','YlGnBu','YlOrRd','PuBu','GnBu'}:
            return _plt.get_cmap(name + '_r')
        return _plt.get_cmap(name)
    except Exception:
        return _plt.get_cmap('Blues_r')


def _v206_render_palette_preview(browser):
    try:
        c = getattr(browser, '_v206_palette_canvas', None)
        if c is None or not c.winfo_exists(): return
        c.delete('all')
        w = int(c.winfo_width() or c.cget('width') or 260); h = int(c.winfo_height() or c.cget('height') or 18)
        cmap = _v206_get_cmap(browser)
        for i in range(max(1, w)):
            rgba = cmap(i/max(1,w-1))
            color = '#%02x%02x%02x' % tuple(int(max(0,min(1,x))*255) for x in rgba[:3])
            c.create_line(i, 0, i, h, fill=color)
        c.create_text(4, h//2, text='HF', anchor='w', fill='black', font=('Arial', 7, 'bold'))
        c.create_text(w-4, h//2, text='LF', anchor='e', fill='black', font=('Arial', 7, 'bold'))
    except Exception:
        pass


def _v206_setvar(obj, name, value, kind='string'):
    if hasattr(obj, name): return getattr(obj, name)
    if kind == 'bool': var = tk.BooleanVar(value=value)
    else: var = tk.StringVar(value=value)
    setattr(obj, name, var)
    return var


def _v206_ensure_vars(browser):
    _v206_setvar(browser, 'plot_mode_var', 'Auto')
    _v206_setvar(browser, 'max_curves_var', '24')
    _v206_setvar(browser, 'eis_plot_style_var', 'Line + Points')
