def _v206_ensure_publication_panel(self):
    try:
        panel=getattr(self, '_v206_pub_panel', None)
        if panel is None or panel.outer is None or not panel.outer.winfo_exists():
            self._v206_pub_panel = FaradaIQPublicationPlotPanelV206(self)
            self._v200_pub_panel = self._v206_pub_panel
        try: _v206_hide_legacy_controls(self)
        except Exception: pass
        return True
    except Exception as exc:
        try: self.log(f'v216 publication plot panel failed: {exc}')
        except Exception: pass
        try: messagebox.showerror('Publication plot panel failed', str(exc), parent=self)
        except Exception: pass
        return False


def _v206_plot_selected(self, clear=True, add_view=True):
    if not _v206_ensure_publication_panel(self): return
    paths=self.selected_paths(plottable_only=True)
    if not paths:
        try: messagebox.showinfo('No table selected','Select one or more table files or a group in the experiment map.',parent=self)
        except Exception: pass
        return
    try: maxn=max(1,int(float(self.max_curves_var.get())))
    except Exception: maxn=24
    selected=paths[:maxn]
    panel=self._v206_pub_panel
    new_curves=[]
    for p in selected:
        try: new_curves.append(panel._load_curve(p))
        except Exception as exc:
            try: self.log(f'v210 could not load {Path(p).name}: {exc}')
            except Exception: pass
    if not new_curves:
        try: self.log('v210 plot: no plottable curves loaded.')
        except Exception: pass
        return
    curves = (list(panel.last_curves) + new_curves) if clear is False else new_curves
    panel.render(curves, clear=True)
    self._curves=[{'path':c.get('path'), 'detected':c.get('tech'), 'label':c.get('label')} for c in curves]
    self.last_plot_paths=[Path(c.get('path')) for c in curves if c.get('path') is not None]
    try:
        if '_v138_add_plot_view' in globals() and add_view:
            label=f"{self.plot_mode_var.get()} | {len(curves)} curve(s) | v216 publication"
            _v138_add_plot_view(self, label, self.last_plot_paths, mode=self.plot_mode_var.get(), source='v206_publication_plot')
    except Exception: pass
    try:
        self.log(f'v216 publication plot rendered {len(curves)} curve(s). CV/LSV default I-V; I-t/E-t/Q-t available; global axis/grid/scale options active.')
        if len(paths)>maxn: self.log(f'Plotted first {maxn} of {len(paths)} selected files. Increase Max curves to show more.')
    except Exception: pass


def _v206_clear_plot(self):
    if not _v206_ensure_publication_panel(self): return
    try:
        self._v206_pub_panel.render([], clear=True)
        self._curves=[]; self.last_plot_paths=[]
    except Exception: pass

