# ---- FaradaIQ Studio v273 CV/LSV default I-V hard fix ----
# User report: CV cycle/group selection still rendered Current vs Time and title "Chrono".
# This final v208 patch is self-contained: it does not call previous version helpers for
# column detection, so it cannot recursively wrap itself. It force-classifies CV/LSV/IV
# tables by path/mode and defaults them to Current vs Potential.
APP_TITLE = "FaradaIQ Studio v273"
FARADAIQ_PUBLIC_VERSION = "v216"


def _v206b_norm_col(s):
    return re.sub(r'[^a-z0-9]+', '', str(s).strip().lower())


def _v206b_pick(cols, names, prefer=()):
    norm = {_v206b_norm_col(c): c for c in cols}
    for n in list(prefer) + list(names):
        nn = _v206b_norm_col(n)
        if nn in norm:
            return norm[nn]
    for c in cols:
        cn = _v206b_norm_col(c)
        for n in names:
            nn = _v206b_norm_col(n)
            if nn and nn in cn:
                return c
    return None


def _v206b_columns(df):
    cols = list(getattr(df, 'columns', []))
    return {
        'freq': _v206b_pick(cols, ['frequency_hz','frequency hz','frequency/hz','frequency','freq_hz','freq hz','freq','f2_hz','f2','f','hz'], prefer=['frequency_hz','freq_hz','f2_hz','f2','Frequency/Hz']),
        'zr': _v206b_pick(cols, ['zreal_ohm','zreal ohm','zreal/ohm','zreal','realz_ohm','realz ohm','realz','zre','zprime','real','re_z','re(z)']),
        'zi': _v206b_pick(cols, ['zimag_ohm','zimag ohm','zimag/ohm','zimag','imagz_ohm','imagz ohm','imagz','zim','imz','zdoubleprime','imag','im_z','im(z)']),
        'negzi': _v206b_pick(cols, ['-zimag','-z imag','minus_zimag','minuszimag','neg_zimag_ohm','neg zimag ohm','neg_zimag','negzimag','negative_zimag','negativezimag']),
        'zmod': _v206b_pick(cols, ['zmod_ohm','zmod ohm','zmod/ohm','zmod','zabs_ohm','zabs ohm','zabs','impz','magnitude','modulus']),
        'phase': _v206b_pick(cols, ['phase_deg','phase deg','phase/deg','phase']),
        'pot': _v206b_pick(cols, ['potential_v','potential v','potential/v','potential (v)','potential','e_v','e v','e/v','e (v)','ewe_v','ewe v','ewe/v','ewe (v)','ewe','ewe vs ref','ewe_vs_ref','working electrode potential','voltage_v','voltage v','voltage/v','voltage (v)','voltage','applied potential','applied_potential','ecell','ewe-ece','we potential','E','Ewe','Ewe/V','Ewe_V','Potential applied (V)'], prefer=['potential_V','potential_v','potential/V','Ewe/V','Ewe_V','ewe_v','voltage_v']),
        'cur': _v206b_pick(cols, ['current_a','current a','current/a','current (a)','current','i_a','i a','i/a','i (a)','current_na','current_ua','current_ma','current_nA','current_uA','current_mA','i','I','Imon','I/mA','I/uA','I/nA','<I>/A'], prefer=['current_A','current_a','current/A','i_a','I/A']),
        'time': _v206b_pick(cols, ['time_s','time s','time/s','time (s)','time','t_s','t s','t/s','t (s)','t','Time/s','Time_S'], prefer=['time_s','Time/s','time/S']),
        'charge': _v206b_pick(cols, ['charge_c','charge c','charge/c','charge (c)','charge','q_c','q c','q/c','q','Q','Q/C']),
        'tau': _v206b_pick(cols, ['tau','tau_s','tau s','tau/s','timescale']),
        'gamma': _v206b_pick(cols, ['gamma','gamma_ohm','gamma ohm','gamma/ohm','drt']),
    }


def _v206b_path_or_mode_says_cv(path, mode=''):
    s = (str(path) + ' ' + str(mode)).lower().replace('\\','/')
    return any(tok in s for tok in ['/cv_lsv/', 'cv_lsv', 'cv/lsv', 'cv / lsv', 'cv_', '/cv/', 'cyclic', 'lsv', 'linear sweep', 'iv / tafel', 'iv_tafel', '/iv/', 'tafel', 'scanrate', 'scan rate', 'cycle_'])


def _v206b_tech_for_file(path, df, mode='Auto'):
    cols = _v206b_columns(df)
    name = str(path).lower().replace('\\','/')
    if cols.get('zr') and (cols.get('zi') or cols.get('negzi')):
        return 'EIS', cols
    if cols.get('tau') and cols.get('gamma'):
        return 'DRT', cols
    # CV path/mode has priority over generic time/current chrono detection.
    if _v206b_path_or_mode_says_cv(path, mode) and cols.get('cur'):
        return 'CV/LSV/IV', cols
    if cols.get('pot') and cols.get('cur'):
        return 'CV/LSV/IV', cols
    if any(tok in name for tok in ['ca','cp','chrono','chronopot','chronoamp']) and cols.get('time') and cols.get('cur'):
        return 'CA/CP', cols
    if cols.get('time') and cols.get('cur'):
        return 'CA/CP', cols
    return 'Numeric', cols


def _v206b_numeric(df, col):
    import pandas as _pd
    if col is None:
        return np.asarray([], dtype=float)
    return _pd.to_numeric(df[col], errors='coerce').to_numpy(dtype=float)


def _v206b_find_numeric_column(df, exclude=()):
    try:
        import pandas as _pd
        ex = {str(x) for x in exclude if x}
        candidates=[]
        for c in df.columns:
            if str(c) in ex:
                continue
            arr=_pd.to_numeric(df[c], errors='coerce')
            n=int(arr.notna().sum())
            if n >= 2:
                span=float(arr.max()-arr.min()) if n else 0.0
                candidates.append((span, str(c), c))
        candidates.sort(reverse=True)
        return candidates[0][2] if candidates else None
    except Exception:
        return None


def _v206b_load_curve(self, path):
    import pandas as _pd
    p = Path(path)
    try:
        df = _v138_csv_read(p) if '_v138_csv_read' in globals() else _pd.read_csv(p)
    except Exception:
        df = _pd.read_csv(p, sep=None, engine='python')
    tech, cols = _v206b_tech_for_file(p, df, self._get('plot_mode_var','Auto'))
    labfun = globals().get('_v206_safe_label') or globals().get('_v202_safe_label')
    label = labfun(p) if callable(labfun) else p.stem[:55]
    return {'path': p, 'df': df, 'tech': tech, 'cols': cols, 'label': label}


def _v206b_plot_xy(self, curve, mode_l):
    df=curve['df']; cols=_v206b_columns(df); tech=curve.get('tech'); label=curve.get('label') or Path(curve.get('path','')).stem
    mode_l=str(mode_l or '').lower()
    view=str(self._get('cv_view_var','I-V') or 'I-V').lower().replace(' ','')
    path=curve.get('path','')
    # Do not let a stale parent folder named CV_LSV override explicit CA/CP
    # evidence in the filename/directory. Legacy pre-v208 H5 caches are rebuilt, but
    # this guard also protects direct-folder plotting.
    _chrono_tokens = _v206_path_tokens(path) if '_v206_path_tokens' in globals() else set()
    _explicit_chrono = bool({'ca','cp','chronoamperometry','chronopotentiometry','chronoamp','chronopot'} & _chrono_tokens)
    if tech == 'CA/CP' and not _explicit_chrono and _v206b_path_or_mode_says_cv(path, self._get('plot_mode_var','Auto')):
        tech = 'CV/LSV/IV'
    xcol=ycol=None; xlabel=''; ylabel=''
    if tech == 'DRT':
        xcol=cols.get('tau'); ycol=cols.get('gamma'); xlabel='τ / s'; ylabel='γ'
    elif tech == 'CA/CP':
        if 'q' in mode_l or 'charge' in mode_l or view == 'q-t':
            xcol=cols.get('time'); ycol=cols.get('charge') or cols.get('cur'); xlabel='Time / s'; ylabel='Charge / C'
        elif 'e-t' in mode_l or 'potential' in mode_l or 'voltage' in mode_l or view == 'e-t':
            xcol=cols.get('time'); ycol=cols.get('pot') or cols.get('cur'); xlabel='Time / s'; ylabel='Potential / V'
        else:
            xcol=cols.get('time'); ycol=cols.get('cur'); xlabel='Time / s'; ylabel='Current / A'
    elif tech == 'CV/LSV/IV':
        explicit_it = any(tok in mode_l for tok in ['i-t','it chrono','chrono']) or view == 'i-t'
        explicit_et = any(tok in mode_l for tok in ['e-t','potential-time','voltage-time']) or view == 'e-t'
        explicit_qt = any(tok in mode_l for tok in ['q-t','charge-time']) or view == 'q-t'
        if explicit_it:
            xcol=cols.get('time') or _v206b_find_numeric_column(df, exclude=[cols.get('cur')]); ycol=cols.get('cur'); xlabel='Time / s'; ylabel='Current / A'
        elif explicit_et:
            xcol=cols.get('time') or _v206b_find_numeric_column(df, exclude=[cols.get('pot')]); ycol=cols.get('pot') or cols.get('cur'); xlabel='Time / s'; ylabel='Potential / V'
        elif explicit_qt:
            xcol=cols.get('time') or _v206b_find_numeric_column(df, exclude=[cols.get('charge')]); ycol=cols.get('charge') or cols.get('cur'); xlabel='Time / s'; ylabel='Charge / C'
        else:
            # True default: Current vs Potential, never Current vs Time for CV/LSV unless explicitly selected.
            xcol=cols.get('pot') or _v206b_find_numeric_column(df, exclude=[cols.get('time'), cols.get('cur'), cols.get('charge')])
            ycol=cols.get('cur')
            xlabel='Potential / V'; ylabel='Current / A'
    else:
        nums=[]
        try:
            import pandas as _pd
            for c in df.columns:
                arr=_pd.to_numeric(df[c], errors='coerce')
                if arr.notna().sum()>=2: nums.append(c)
        except Exception: pass
        if len(nums)>=2:
            xcol,ycol=nums[0],nums[1]; xlabel=str(xcol); ylabel=str(ycol)
    if xcol is None or ycol is None:
        return None
    x=_v206b_numeric(df,xcol); y=_v206b_numeric(df,ycol)
    mask=np.isfinite(x)&np.isfinite(y); x=x[mask]; y=y[mask]
    if len(x)<2: return None
    line,=self.ax.plot(x,y,linewidth=1.6,marker=None if len(x)>350 else '.',markersize=2.8,label=label)
    self.ax.set_xlabel(xlabel); self.ax.set_ylabel(ylabel)
    return line


def _v206b_render(self, curves, clear=True):
    mode=str(self._get('plot_mode_var','Auto') or 'Auto')
    mode_l=mode.lower()
    self._new_figure()
    handles=[]; has_cbar=False; fixed_curves=[]
    for c in list(curves or []):
        try:
            tech, cols = _v206b_tech_for_file(c.get('path',''), c.get('df'), mode)
            c=dict(c); c['tech']=tech; c['cols']=cols; fixed_curves.append(c)
            if tech == 'EIS':
                h, cb = self._plot_eis(c, mode_l); has_cbar = has_cbar or cb
            else:
                h = _v206b_plot_xy(self, c, mode_l)
            if h is not None: handles.append(h)
        except Exception as exc:
            try: self.browser.log(f'v210 plot skipped {Path(c.get("path", "")).name}: {exc}')
            except Exception: pass
    title = 'FaradaIQ publication overlay' if mode == 'Auto' else f'{mode} publication overlay'
    if 'tafel' in mode_l and 'log' in mode_l:
        title='Tafel trace: log10(|I| / A) vs measured potential'
    elif fixed_curves:
        techs={c.get('tech') for c in fixed_curves}
        if techs == {'EIS'}: title='EIS Nyquist publication overlay'
        elif techs <= {'CV/LSV/IV'}: title='CV/LSV publication overlay'
        elif techs <= {'CA/CP'}: title='Chrono publication overlay'
    self.ax.set_title(title)
    if handles and str(self._get('legend_var','On')).lower() not in {'off','false','0','no'}:
        fs=7 if len(handles)<=14 else (6 if len(handles)<=30 else 5)
        try: self.ax.legend(handles=handles, fontsize=fs, loc='best', frameon=True, framealpha=0.86, title='Curves')
        except Exception: pass
    self._apply_options(has_cbar)
    try: self.canvas.draw_idle()
    except Exception: pass
    self.last_curves=list(fixed_curves or [])
    self.last_recipe={'version':"v273",'mode':mode,'palette':str(self._get('eis_cmap_var','Blues')),'eis_style':str(self._get('eis_plot_style_var','Line + Points')),'legend':str(self._get('legend_var','On')),'cv_trace_view':str(self._get('cv_view_var','I-V')),'xscale':str(self._get('plot_xscale_var','Linear')),'yscale':str(self._get('plot_yscale_var','Linear')),'grid':bool(self._get('plot_grid_var',True)),'xlim':[self._get('plot_xmin_var',''),self._get('plot_xmax_var','')],'ylim':[self._get('plot_ymin_var',''),self._get('plot_ymax_var','')],'files':[str(c.get('path')) for c in fixed_curves or []]}
    return True

