# ---- FaradaIQ Studio v273 alias correction: prevent potential column from matching time_s ----
# The prior broad alias list included one-letter potential aliases.  Exact one-letter matches
# are allowed, but substring matches are blocked so "E" cannot match "time_s".
def _v206c_pick(cols, names, prefer=()):
    norm = {_v206b_norm_col(c): c for c in cols}
    for n in list(prefer) + list(names):
        nn = _v206b_norm_col(n)
        if nn in norm:
            return norm[nn]
    for c in cols:
        cn = _v206b_norm_col(c)
        for n in names:
            nn = _v206b_norm_col(n)
            if len(nn) >= 3 and nn in cn:
                return c
    return None


def _v206c_columns(df):
    cols = list(getattr(df, 'columns', []))
    return {
        'freq': _v206c_pick(cols, ['frequency_hz','frequency hz','frequency/hz','frequency','freq_hz','freq hz','freq','f2_hz','f2','hz'], prefer=['frequency_hz','freq_hz','f2_hz','f2','Frequency/Hz']),
        'zr': _v206c_pick(cols, ['zreal_ohm','zreal ohm','zreal/ohm','zreal','realz_ohm','realz ohm','realz','zre','zprime','real','re_z','re(z)']),
        'zi': _v206c_pick(cols, ['zimag_ohm','zimag ohm','zimag/ohm','zimag','imagz_ohm','imagz ohm','imagz','zim','imz','zdoubleprime','imag','im_z','im(z)']),
        'negzi': _v206c_pick(cols, ['-zimag','-z imag','minus_zimag','minuszimag','neg_zimag_ohm','neg zimag ohm','neg_zimag','negzimag','negative_zimag','negativezimag']),
        'zmod': _v206c_pick(cols, ['zmod_ohm','zmod ohm','zmod/ohm','zmod','zabs_ohm','zabs ohm','zabs','impz','magnitude','modulus']),
        'phase': _v206c_pick(cols, ['phase_deg','phase deg','phase/deg','phase']),
        'pot': _v206c_pick(cols, ['potential_v','potential v','potential/v','potential (v)','potential','e_v','e v','e/v','e (v)','ewe_v','ewe v','ewe/v','ewe (v)','ewe','ewe vs ref','ewe_vs_ref','working electrode potential','voltage_v','voltage v','voltage/v','voltage (v)','voltage','applied potential','applied_potential','ecell','ewe-ece','we potential','E','Ewe','Ewe/V','Ewe_V','Potential applied (V)'], prefer=['potential_V','potential_v','potential/V','Ewe/V','Ewe_V','ewe_v','voltage_v','E']),
        'cur': _v206c_pick(cols, ['current_a','current a','current/a','current (a)','current','i_a','i a','i/a','i (a)','current_na','current_ua','current_ma','current_nA','current_uA','current_mA','i','I','Imon','I/mA','I/uA','I/nA','<I>/A'], prefer=['current_A','current_a','current/A','i_a','I/A','I']),
        'time': _v206c_pick(cols, ['time_s','time s','time/s','time (s)','time','t_s','t s','t/s','t (s)','t','Time/s','Time_S'], prefer=['time_s','Time/s','time/S','t']),
        'charge': _v206c_pick(cols, ['charge_c','charge c','charge/c','charge (c)','charge','q_c','q c','q/c','q','Q','Q/C'], prefer=['charge_C','Q/C','Q']),
        'tau': _v206c_pick(cols, ['tau','tau_s','tau s','tau/s','timescale']),
        'gamma': _v206c_pick(cols, ['gamma','gamma_ohm','gamma ohm','gamma/ohm','drt']),
    }


def _v206c_tech_for_file(path, df, mode='Auto'):
    cols = _v206c_columns(df)
    name = str(path).lower().replace('\\','/')
    if cols.get('zr') and (cols.get('zi') or cols.get('negzi')):
        return 'EIS', cols
    if cols.get('tau') and cols.get('gamma'):
        return 'DRT', cols
    if _v206b_path_or_mode_says_cv(path, mode) and cols.get('cur'):
        return 'CV/LSV/IV', cols
    if cols.get('pot') and cols.get('cur'):
        return 'CV/LSV/IV', cols
    if any(tok in name for tok in ['ca','cp','chrono','chronopot','chronoamp']) and cols.get('time') and cols.get('cur'):
        return 'CA/CP', cols
    if cols.get('time') and cols.get('cur'):
        return 'CA/CP', cols
    return 'Numeric', cols

