# ---- FaradaIQ Studio v273 canonical technique-tree rebuild ----
# Replaces all earlier additive tree wrappers with one deterministic browser index.
# Goals:
#   * one top-level root per detected technique; no empty roots;
#   * repair flattened HEKA CV numbering using expected points/cycles metadata;
#   * discover latest analyzed DRT result tables even when DRT was run after H5 build;
#   * classify CA, CP, OCP/OCV, IV/Tafel, pulse, GCD/GCPL, ZRA and other tables;
#   * avoid DRT input/EIS-fit duplicates and duplicate method-group top-level roots.
try:
    APP_TITLE = 'FaradaIQ Studio v273'
except Exception:
    pass

_V206_TABLE_EXTS = {'.csv','.tsv','.txt','.asc','.xlsx','.xls'}
_V206_SKIP_PARTS = {
    'pyseccm_tools_scripts','headless_pydrttools','_faradaiq_parser_logs',
    '__pycache__','.pytest_cache','figures','videos','media','photos'
}


def _v206_norm(s):
    return re.sub(r'[^a-z0-9]+','',str(s or '').lower())


def _v206_has_token(text, token):
    return re.search(r'(?<![a-z0-9])'+re.escape(str(token).lower())+r'(?![a-z0-9])', str(text or '').lower()) is not None


def _v206_header_columns(path):
    """Read only a small header prefix; supports pyDRTtools files with metadata rows."""
    p=Path(path)
    if p.suffix.lower() in {'.xlsx','.xls'}:
        try:
            import pandas as _pd
            return [str(x) for x in _pd.read_excel(p,nrows=2).columns]
        except Exception:
            return []
    try:
        raw=p.read_bytes()[:32768]
        try: txt=raw.decode('utf-8-sig')
        except Exception: txt=raw.decode('latin-1','replace')
    except Exception:
        return []
    known=('time','potential','voltage','current','charge','frequency','freq','zreal','realz','zimag','imagz','tau','gamma','phase','capacity')
    best=[]; best_score=-1
    for line in txt.splitlines()[:24]:
        if not line.strip(): continue
        delim=max([',','\t',';'], key=lambda d: line.count(d))
        if line.count(delim)<1: continue
        cols=[c.strip().strip('"\'') for c in line.split(delim)]
        score=sum(1 for c in cols if any(k in _v206_norm(c) for k in known)) + min(len(cols),10)*0.02
        if score>best_score:
            best=cols; best_score=score
    return best


def _v206_col_flags(cols):
    ns={_v206_norm(c) for c in (cols or [])}
    def anyeq(vals):
        v={_v206_norm(x) for x in vals}
        return any(n in v or any(len(x)>=4 and x in n for x in v) for n in ns)
    return {
        'time': anyeq(['time','time_s','times','t_s']),
        'potential': anyeq(['potential','potential_v','ewe','ewe_v','voltage','voltage_v','ecell']),
        'current': anyeq(['current','current_a','i_a','imon']),
        'charge': anyeq(['charge','charge_c','q_c']),
        'capacity': anyeq(['capacity','capacity_ah','capacity_mah']),
        'frequency': anyeq(['frequency','frequency_hz','freq','freq_hz','f2']),
        'zreal': anyeq(['zreal','zreal_ohm','realz','realz_ohm','zre','re_z']),
        'zimag': anyeq(['zimag','zimag_ohm','imagz','imagz_ohm','neg_zimag','im_z']),
        'tau': anyeq(['tau','tau_s','out_tau_vec','timescale']),
        'gamma': anyeq(['gamma','gamma_ohm','drt']),
        'phase': anyeq(['phase','phase_deg']),
    }


def _v206_signal_spans(path, cols):
    """Small numeric sample used only to disambiguate old CA/CP caches mislabeled CV."""
    try:
        import pandas as _pd
        p=Path(path)
        if p.suffix.lower() not in {'.csv','.tsv','.txt','.asc'}: return {}
        # Find likely header row using the selected columns.
        raw=p.read_text(encoding='utf-8-sig',errors='replace').splitlines()[:24]
        target={_v206_norm(c) for c in cols}
        best_i=0; best=-1
        for i,line in enumerate(raw):
            sc=sum(1 for c in re.split(r'[,;\t]',line) if _v206_norm(c) in target)
            if sc>best: best=sc; best_i=i
        df=_pd.read_csv(p,sep=None,engine='python',skiprows=best_i,nrows=400)
        out={}
        for c in df.columns:
            n=_v206_norm(c)
            a=_pd.to_numeric(df[c],errors='coerce').dropna()
            if len(a)>=2:
                out[n]=float(a.max()-a.min())
        return out
    except Exception:
        return {}


def _v206_path_meta(path):
    p=Path(path)
    # Prefer the filename, then nearest parent components. This prevents a sample
    # name such as "...point_11points..." from overriding "position002".
    search_parts=[p.name]+list(reversed(p.parts[:-1]))
    def pick(patterns, default=0):
        for text in search_parts:
            for pat in patterns:
                matches=list(re.finditer(pat,str(text),re.I))
                if matches:
                    try: return int(matches[-1].group(1))
                    except Exception: pass
        return default
    point=pick([r'(?:position|pos)[_\- ]*(\d+)',r'(?:point|pt)[_\- ]*(\d+)',r'^P(\d{1,4})[_\- ]*M\d+'])
    method=pick([r'method[_\- ]*(\d+)',r'^P\d{1,4}[_\- ]*M(\d+)',r'(?:^|[_\-])m(\d+)(?:_|\.|$)'],1)
    cycle=pick([r'cycle[_\- ]*(\d+)',r'(?:^|[_\-])c(\d+)(?:_|\.|$)'])
    s=p.as_posix()
    rate='unknown'
    m=re.search(r'scanrate[_\- ]*([^/\\]+)',s,re.I)
    if m: rate=m.group(1)
    else:
        m=re.search(r'(\d+(?:\.\d+)?)\s*mV(?:perS|s)',s,re.I)
        if m: rate=m.group(1)+'mVs'
    run='DRT results'
    for part in p.parts:
        if re.match(r'DRT[_\-]\d',part,re.I): run=part
    low=p.name.lower()
    engine='DRT'
    for key,label in [('bayes','Bayesian'),('bht','BHT'),('simple','Simple'),('deareis','DearEIS'),('ridge','Ridge'),('nnls','NNLS')]:
        if key in low: engine=label; break
    return {'point':point,'method':method,'cycle':cycle,'rate':rate,'run':run,'engine':engine}

def _v206_classify(path, cols=None, base_name=''):
    p=Path(path); s=p.as_posix().lower(); n=p.name.lower(); flags=_v206_col_flags(cols or _v206_header_columns(p))
    parts=[x.lower() for x in p.parts]
    # Numeric signatures are strongest.
    if flags['tau'] and flags['gamma']:
        return 'DRT'
    if flags['zreal'] and flags['zimag']:
        return 'EIS'
    # Strong path/name techniques. Put specialized techniques before generic CA/CP/IV fallbacks.
    if any(tok in s for tok in ['conductivity','constant_voltage_conduct','constant-voltage-conduct']):
        return 'Conductivity'
    if any(tok in s for tok in ['eqcm','electrochemical_quartz','quartz_crystal_microbalance']) or ('mass' in n and 'qcm' in s):
        return 'EQCM'
    if any(_v206_has_token(x,'gitt') for x in parts) or re.search(r'(^|[_\-])gitt([_\-.]|$)',n): return 'GITT'
    if any(_v206_has_token(x,'pitt') for x in parts) or re.search(r'(^|[_\-])pitt([_\-.]|$)',n): return 'PITT'
    if 'mott_schottky' in s or 'mott-schottky' in s or 'mottschottky' in s: return 'Mott-Schottky'
    if any(_v206_has_token(x,'rrde') for x in parts) or re.search(r'(^|[_\-])rrde([_\-.]|$)',n): return 'RDE/RRDE'
    if any(_v206_has_token(x,'rde') for x in parts) or re.search(r'(^|[_\-])rde([_\-.]|$)',n): return 'RDE/RRDE'
    if 'electrochemical_noise' in s or 'electrochemical-noise' in s or any(_v206_has_token(x,'ecnoise') for x in parts): return 'Electrochemical noise'
    if any(tok in s for tok in ['raman','sers']): return 'Raman/SERS'
    if any(tok in s for tok in ['ftir','irras','infrared']): return 'FTIR/IR'
    if any(tok in s for tok in ['uv_vis','uv-vis','uvvis']): return 'UV-Vis'
    if any(_v206_has_token(x,'xrd') for x in parts): return 'XRD'
    if any(_v206_has_token(x,'xps') for x in parts): return 'XPS'
    if any(_v206_has_token(x,'chronoamperometry') for x in parts) or re.search(r'(^|[_\-])ca([_\-.]|$)',n) or 'fullca' in n or 'chronoamp' in s:
        return 'CA'
    if any(_v206_has_token(x,'chronopotentiometry') for x in parts) or re.search(r'(^|[_\-])cp([_\-.]|$)',n) or 'fullcp' in n or 'chronopot' in s:
        return 'CP'
    if any(_v206_has_token(x,'ocp') or _v206_has_token(x,'ocv') for x in parts) or re.search(r'(^|[_\-])(ocp|ocv)([_\-.]|$)',n):
        return 'OCP/OCV'
    if any(tok in n for tok in ['nyquist','bode','fulleis']) or any(_v206_has_token(x,'eis') for x in parts):
        return 'EIS'
    if any(_v206_has_token(x,'drt') for x in parts) and 'eis_data' not in n and ('drt' in n or flags['gamma']):
        return 'DRT'
    if any(_v206_has_token(x,'dpv') for x in parts) or re.search(r'(^|[_\-])dpv([_\-.]|$)',n): return 'DPV'
    if any(_v206_has_token(x,'swv') for x in parts) or re.search(r'(^|[_\-])swv([_\-.]|$)',n): return 'SWV'
    if any(_v206_has_token(x,'npv') for x in parts) or re.search(r'(^|[_\-])npv([_\-.]|$)',n): return 'NPV'
    if any(_v206_has_token(x,'gcpl') or _v206_has_token(x,'gcd') for x in parts) or 'charge_discharge' in s: return 'GCD/GCPL'
    if 'chronocoul' in s or any(_v206_has_token(x,'cc') for x in parts): return 'Chronocoulometry'
    if any(_v206_has_token(x,'zra') for x in parts): return 'ZRA'
    if any(_v206_has_token(x,'tafel') for x in parts): return 'IV/Tafel'
    if any(_v206_has_token(x,'lsv') for x in parts) and not any(_v206_has_token(x,'cv_lsv') for x in parts): return 'LSV'
    if any(_v206_has_token(x,'iv') for x in parts) or re.search(r'(^|[_\-])iv([_\-.]|$)',n): return 'IV/Tafel'
    strong_cv=('cv_lsv' in s or re.search(r'(^|[_\-])cv([_\-.]|$)',n) or 'scanrate_' in s or 'cycle_' in s)
    if strong_cv:
        # Old CA/CP bundles were sometimes exported under CV_LSV. Use dataset hint + constant-control shape.
        bn=str(base_name or '').lower()
        if (_v206_has_token(bn,'ca') or bn.endswith('_ca')) and flags['time'] and flags['current'] and flags['potential']:
            spans=_v206_signal_spans(p,cols or _v206_header_columns(p))
            pspan=max([v for k,v in spans.items() if 'potential' in k or k in {'ewe','voltagev'}] or [999.0])
            if pspan < 0.01: return 'CA'
        if (_v206_has_token(bn,'cp') or bn.endswith('_cp')) and flags['time'] and flags['potential']:
            return 'CP'
        return 'CV/LSV'
    # Column fallback.
    if flags['time'] and flags['current'] and flags['charge']: return 'CA'
    if flags['time'] and flags['potential'] and not flags['current']: return 'OCP/OCV'
    if flags['potential'] and flags['current']: return 'IV/Tafel'
    if flags['time'] and flags['current']: return 'CA/CP'
    return 'Other'


def _v206_is_drt_output(path):
    p=Path(path); s=p.as_posix().lower(); n=p.name.lower()
    if p.suffix.lower() not in _V206_TABLE_EXTS: return False
    if '/drt/' not in s.replace('\\','/'): return False
    if any(x in n for x in ['readme','manifest','eis_data']): return False
    if 'drt' not in n and 'gamma' not in n: return False
    cols=_v206_header_columns(p); f=_v206_col_flags(cols)
    return (f['tau'] and f['gamma']) or 'drt_data' in n or re.search(r'[_\-]drt\.(csv|txt|tsv)$',n,re.I) is not None


def _v206_external_strong(path):
    s=Path(path).as_posix().lower(); n=Path(path).name.lower()
    if any(part.lower() in _V206_SKIP_PARTS for part in Path(path).parts): return False
    if 'drt_input_csv' in s and '/drt/' not in s.replace('\\','/'): return False
    pats=['ca_point','cp_point','ocp','ocv','tafel','dpv','swv','npv','gcpl','gcd','chronocoul','zra','fullca','fullcp','fulliv','fullocp',
          'conductivity','eqcm','gitt','pitt','mott_schottky','mott-schottky','rrde','rde','electrochemical_noise',
          'raman','sers','ftir','irras','uv_vis','uv-vis','xrd','xps']
    return any(x in n or x in s for x in pats)


def _v206_drt_score(rec):
    n=rec['path'].name.lower(); score=0
    if 'drt_data' in n: score+=100
    if 'method' in n: score+=25
    if 'position' in n or 'point' in n: score+=10
    if 'simple_drt.csv' in n and 'drt_data' not in n: score-=15
    score+=min(rec['path'].stat().st_size if rec['path'].exists() else 0,1000000)/1000000
    return score


def _v206_validation(manifest):
    m=manifest if isinstance(manifest,dict) else {}
    return ((m.get('data_structure') or {}).get('validation') or m.get('validation') or {})


def _v206_collect_browser_records(cache_root, bundle_root=None, manifest=None, base_name=''):
    cache_root=Path(cache_root).resolve(); bundle_root=Path(bundle_root).resolve() if bundle_root else cache_root.parent
    records=[]; seen=set()
    def add(p,source):
        try:
            p=Path(p).resolve()
            if p in seen or not p.is_file() or p.suffix.lower() not in _V206_TABLE_EXTS: return
            if p.name.lower().startswith('readme'): return
            cols=_v206_header_columns(p)
            tech=_v206_classify(p,cols,base_name=base_name)
            meta=_v206_path_meta(p)
            records.append({'path':p,'source':source,'tech':tech,'cols':cols,**meta})
            seen.add(p)
        except Exception:
            return
    if cache_root.exists():
        for p in sorted(cache_root.rglob('*'),key=lambda x:str(x).lower()):
            if p.is_file() and p.suffix.lower() in _V206_TABLE_EXTS: add(p,'cache')
    cache_techs={r['tech'] for r in records}
    # External DRT outputs always matter because DRT may run after the H5 was built.
    # Other strong technique outputs are used only when absent from the H5 cache.
    if bundle_root.exists():
        for p in sorted(bundle_root.rglob('*'),key=lambda x:str(x).lower()):
            try:
                if not p.is_file() or p.suffix.lower() not in _V206_TABLE_EXTS: continue
                if cache_root==p or cache_root in p.parents: continue
                if any(part.lower() in _V206_SKIP_PARTS for part in p.parts): continue
                if _v206_is_drt_output(p):
                    add(p,'external_drt')
                elif _v206_external_strong(p):
                    cols=_v206_header_columns(p); tech=_v206_classify(p,cols,base_name=base_name)
                    if tech not in cache_techs and tech not in {'Other','EIS','DRT'}: add(p,'external')
            except Exception:
                pass
    # DRT de-duplication: one preferred plot table per run/engine/method/point.
    out=[]; drt_best={}
    for r in records:
        if r['tech']!='DRT': out.append(r); continue
        key=(r.get('run'),r.get('engine'),r.get('method'),r.get('point'))
        if key not in drt_best or _v206_drt_score(r)>_v206_drt_score(drt_best[key]): drt_best[key]=r
    out.extend(drt_best.values())
    records=out
    # Prefer point-resolved tables over aggregate combined/all tables for techniques
    # that already have per-point exports. This prevents a duplicate point 00 entry.
    for _tech in ('CA','CP','CA/CP','EIS','OCP/OCV','IV/Tafel','LSV','DPV','SWV','NPV','GCD/GCPL','Chronocoulometry','ZRA',
                  'Conductivity','EQCM','GITT','PITT','Mott-Schottky','RDE/RRDE','Electrochemical noise',
                  'Raman/SERS','FTIR/IR','UV-Vis','XRD','XPS'):
        if any(r['tech']==_tech and int(r.get('point') or 0)>0 for r in records):
            records=[r for r in records if not (
                r['tech']==_tech and int(r.get('point') or 0)==0 and
                any(tok in r['path'].name.lower() for tok in ('combined','all_points','allpositions','summary'))
            )]
    # Repair flattened HEKA CV numbering (e.g. point_001 + cycle_01..33 for 11 points x 3 cycles).
    val=_v206_validation(manifest)
    try: expected_points=int(val.get('expected_points_from_dat') or 0)
    except Exception: expected_points=0
    try: cycles_per=int(val.get('expected_cycles_per_cv_from_dat') or 0)
    except Exception: cycles_per=0
    by_rate={}
    for r in records:
        if r['tech']=='CV/LSV': by_rate.setdefault(r.get('rate','unknown'),[]).append(r)
    if expected_points>1 and cycles_per>0:
        for rate,grp in by_rate.items():
            pts={r.get('point',0) for r in grp}; mx=max([r.get('cycle',0) for r in grp] or [0])
            if len(pts)<=1 and mx>=expected_points*cycles_per:
                for r in grp:
                    serial=max(1,int(r.get('cycle') or 1))
                    r['point']=((serial-1)//cycles_per)+1
                    r['cycle']=((serial-1)%cycles_per)+1
                    r['cv_repaired']=True
    return sorted(records,key=lambda r:(r['tech'],str(r.get('rate','')),int(r.get('method') or 0),int(r.get('point') or 0),int(r.get('cycle') or 0),str(r['path']).lower()))


def _v206_rate_label(rate):
    s=str(rate or 'unknown').replace('mVperS','mVs').replace('mvperS','mVs')
    m=re.match(r'([0-9.]+)mVs$',s,re.I)
    return f'{m.group(1)} mV/s' if m else s


def _v206_bundle_root(browser):
    candidates=[]
    try:
        if getattr(browser,'h5_path',None): candidates.append(Path(browser.h5_path).parent)
    except Exception: pass
    try: candidates.append(Path(browser.cache_root).parent)
    except Exception: pass
    try:
        for k in ('container_root','bundle_dir','analysis_root'):
            v=(getattr(browser,'manifest',{}) or {}).get(k)
            if v and Path(v).exists(): candidates.append(Path(v))
    except Exception: pass
    for c in candidates:
        try:
            c=c.resolve()
            if c.exists(): return c
        except Exception: pass
    return Path(browser.cache_root).parent


def _v206_refresh_tree(self):
    try:
        self.tree.delete(*self.tree.get_children()); self._path_by_iid.clear()
        records=_v206_collect_browser_records(self.cache_root,_v206_bundle_root(self),getattr(self,'manifest',{}),getattr(self,'base_name',''))
        groups={}
        for r in records: groups.setdefault(r['tech'],[]).append(r)
        node_cache={}
        def node(parent,label,kind='',open=False):
            key=(parent,label,kind)
            if key in node_cache: return node_cache[key]
            iid=self.tree.insert(parent,'end',text=label,values=(kind,''),open=open); node_cache[key]=iid; return iid
        def root(label,open=False): return node('',label,'',open)
        def leaf(parent,label,r,kind=None):
            try: size=_v138_fmt_size(r['path'].stat().st_size)
            except Exception: size=''
            iid=self.tree.insert(parent,'end',text=label,values=(kind or r['tech'],size),open=False)
            self._path_by_iid[iid]=r['path']; return iid
        # CV / LSV: one technique root with two explicit grouping views.
        cv=groups.get('CV/LSV',[])
        if cv:
            rr=root('CV / LSV',True); br=node(rr,'Grouped by scan rate','view',True); bp=node(rr,'Grouped by point','view',False)
            for r in cv:
                rate=_v206_rate_label(r.get('rate')); pt=int(r.get('point') or 0); cy=int(r.get('cycle') or 0)
                rn=node(br,rate,'scan rate',False); pn=node(rn,f'point {pt:02d}','point',False)
                leaf(pn,f'cycle {cy:02d}',r,'CV / LSV')
                pn2=node(bp,f'point {pt:02d}','point',False); rn2=node(pn2,rate,'scan rate',False)
                leaf(rn2,f'cycle {cy:02d}',r,'CV / LSV')
        # EIS: by point and by method under one root.
        eis=groups.get('EIS',[])
        if eis:
            rr=root('EIS — Nyquist / Bode',True); bp=node(rr,'Grouped by point','view',True); bm=node(rr,'Grouped by method','view',False)
            for r in eis:
                pt=int(r.get('point') or 0); me=int(r.get('method') or 1)
                pn=node(bp,f'point {pt:02d}','EIS point',False); leaf(pn,f'method {me:02d} — {r["path"].name}',r,'EIS')
                mn=node(bm,f'method {me:02d}','EIS method',False); leaf(mn,f'point {pt:02d} — {r["path"].name}',r,'EIS')
        # DRT analyzed results, discovered outside stale H5 cache and deduplicated.
        drt=groups.get('DRT',[])
        if drt:
            rr=root('DRT analyzed results',True)
            for r in drt:
                run=node(rr,str(r.get('run') or 'DRT results'),'DRT run',False)
                eng=node(run,str(r.get('engine') or 'DRT'),'DRT engine',True)
                pt=int(r.get('point') or 0); me=int(r.get('method') or 1)
                leaf(eng,f'point {pt:02d} — method {me:02d}',r,'DRT')
        def standard_root(tech,label):
            arr=groups.get(tech,[])
            if not arr: return
            rr=root(label,False); methods={int(r.get('method') or 1) for r in arr}
            for r in arr:
                pt=int(r.get('point') or 0); me=int(r.get('method') or 1); cy=int(r.get('cycle') or 0)
                parent=rr
                if len(methods)>1: parent=node(rr,f'method {me:02d}',f'{tech} method',False)
                txt=f'point {pt:02d}' if pt else r['path'].stem
                if cy: txt+=f' — cycle {cy:02d}'
                if pt: txt+=f' — {r["path"].name}'
                leaf(parent,txt,r,tech)
        for tech,label in [
            ('CA','Chronoamperometry (CA)'),('CP','Chronopotentiometry (CP)'),('CA/CP','Chrono transients (CA / CP)'),
            ('OCP/OCV','Open-circuit potential (OCP / OCV)'),('LSV','Linear sweep voltammetry (LSV)'),
            ('IV/Tafel','I–V / Tafel'),('DPV','Differential pulse voltammetry (DPV)'),
            ('SWV','Square-wave voltammetry (SWV)'),('NPV','Normal pulse voltammetry (NPV)'),
            ('GCD/GCPL','Galvanostatic charge–discharge (GCD / GCPL)'),
            ('Chronocoulometry','Chronocoulometry'),('ZRA','Zero-resistance ammetry (ZRA)'),
            ('Conductivity','Conductivity / constant-voltage measurements'),('EQCM','Electrochemical quartz crystal microbalance (EQCM)'),
            ('GITT','Galvanostatic intermittent titration (GITT)'),('PITT','Potentiostatic intermittent titration (PITT)'),
            ('Mott-Schottky','Mott–Schottky'),('RDE/RRDE','Rotating disk / ring-disk electrode (RDE / RRDE)'),
            ('Electrochemical noise','Electrochemical noise'),('Raman/SERS','Raman / SERS'),('FTIR/IR','FTIR / IR'),
            ('UV-Vis','UV–Vis'),('XRD','X-ray diffraction (XRD)'),('XPS','X-ray photoelectron spectroscopy (XPS)')]:
            standard_root(tech,label)
        other=groups.get('Other',[])
        if other:
            rr=root('Other numeric tables',False)
            for r in other: leaf(rr,r['path'].name,r,'Numeric')
        counts={k:len(v) for k,v in groups.items() if v}
        self._v206_technique_counts=counts
        try:
            order=['CV/LSV','EIS','DRT','CA','CP','CA/CP','OCP/OCV','LSV','IV/Tafel','DPV','SWV','NPV','GCD/GCPL','Chronocoulometry','ZRA',
                   'Conductivity','EQCM','GITT','PITT','Mott-Schottky','RDE/RRDE','Electrochemical noise',
                   'Raman/SERS','FTIR/IR','UV-Vis','XRD','XPS','Other']
            text=' | '.join(f'{k} {counts[k]}' for k in order if counts.get(k)) or 'no plottable tables'
            self.summary_var.set(f'H5/source index | {text}')
        except Exception: pass
        try:
            repaired=sum(1 for r in records if r.get('cv_repaired'))
            self.log(f'v210 technique tree: unique records={len(records)}, counts={counts}, repaired CV point/cycle mappings={repaired}.')
        except Exception: pass
        try: _v206_write_qa_summary(self)
        except Exception: pass
    except Exception as exc:
        try: self.log(f'v210 refresh tree failed: {exc}\n{traceback.format_exc()}')
        except Exception: pass


def _v206_write_qa_summary(self):
    try:
        # Keep manifest validation but report live discovered counts, including post-H5 DRT results.
        self.qa_text.configure(state='normal'); self.qa_text.delete('1.0','end')
        man=self.manifest if isinstance(self.manifest,dict) else {}; val=_v206_validation(man)
        counts=getattr(self,'_v206_technique_counts',{}) or man.get('technique_counts') or {}
        lines=['Live browser technique counts: '+json.dumps(counts,ensure_ascii=False)]
        for k in ['expected_points_from_dat','expected_scan_rates_mV_s_from_dat','expected_cycles_per_cv_from_dat','expected_cv_cycle_files_from_dat','cv_files_included','eis_tables_included','drt_tables_included']:
            if k in val: lines.append(f'{k}: {val.get(k)}')
        lines.append('DRT note: browser refresh discovers analyzed DRT result tables created after the canonical H5 build.')
        self.qa_text.insert('1.0','\n'.join(lines)); self.qa_text.configure(state='disabled')
    except Exception: pass

try:
    FaradaIQH5Browser.refresh_tree = _v206_refresh_tree
    FaradaIQH5Browser._write_qa_summary = _v206_write_qa_summary
except Exception:
    pass

try:
    _v753_track_event('python_module_ready', {'version':"v273",'feature':'single-root technique tree; repaired CV points/cycles; post-H5 DRT discovery; CA/CP/OCP/pulse/GCD classification'})
except Exception:
    pass
# ---- End FaradaIQ Studio v273 canonical technique-tree rebuild ----


# ---- FaradaIQ Studio v273 browser classification + startup performance fix ----
# Fixes:
# 1. Windows paths contain "Users"; substring testing for "sers" incorrectly
#    classified every CV file as Raman/SERS. Spectroscopy detection is now token-aware.
# 2. Canonical cache files are classified from their relative directory first, without
#    opening every CSV header. This substantially reduces browser startup time.
# 3. The bundle fallback scan reads headers only for plausible DRT/technique candidates.
# 4. Repeated refreshes reuse an in-memory index when the source signature is unchanged.
APP_TITLE = 'FaradaIQ Studio v273'
FARADAIQ_PUBLIC_VERSION = 'v216'

_V206_FAST_RECORD_CACHE = {}
_V206_CACHE_DIR_MAP = {
    'cv_lsv':'CV/LSV', 'cv':'CV/LSV', 'cyclic_voltammetry':'CV/LSV',
    'eis':'EIS', 'impedance':'EIS', 'drt':'DRT',
    'chronoamperometry_ca':'CA', 'chronoamperometry':'CA', 'ca':'CA',
    'chronopotentiometry_cp':'CP', 'chronopotentiometry':'CP', 'cp':'CP',
    'ca_cp':'CA/CP', 'chrono':'CA/CP', 'chrono_transients':'CA/CP',
    'ocp':'OCP/OCV', 'ocv':'OCP/OCV', 'open_circuit':'OCP/OCV',
    'lsv':'LSV', 'linear_sweep_voltammetry':'LSV',
    'iv_tafel':'IV/Tafel', 'tafel':'IV/Tafel', 'iv':'IV/Tafel',
    'dpv':'DPV', 'swv':'SWV', 'npv':'NPV',
    'gcd':'GCD/GCPL', 'gcpl':'GCD/GCPL',
    'chronocoulometry':'Chronocoulometry', 'zra':'ZRA',
    'conductivity':'Conductivity', 'eqcm':'EQCM', 'gitt':'GITT', 'pitt':'PITT',
    'mott_schottky':'Mott-Schottky', 'mottschottky':'Mott-Schottky',
    'rde':'RDE/RRDE', 'rrde':'RDE/RRDE',
    'electrochemical_noise':'Electrochemical noise',
    'raman':'Raman/SERS', 'sers':'Raman/SERS',
    'ftir':'FTIR/IR', 'irras':'FTIR/IR', 'infrared':'FTIR/IR',
    'uv_vis':'UV-Vis', 'uvvis':'UV-Vis', 'xrd':'XRD', 'xps':'XPS',
}


def _v206_tokenize_path(path):
    toks=[]
    try:
        for part in Path(path).parts:
            low=str(part).lower()
            toks.extend([x for x in re.split(r'[^a-z0-9]+',low) if x])
            # Preserve common compound directory names as one normalized token.
            norm=re.sub(r'[^a-z0-9]+','_',low).strip('_')
            if norm: toks.append(norm)
    except Exception:
        pass
    return set(toks)


def _v206_has_exact_path_token(path, *tokens):
    have=_v206_tokenize_path(path)
    return any(str(t).lower().replace('-','_').replace(' ','_') in have for t in tokens)


def _v206_fast_cache_tech(path, cache_root=None, base_name=''):
    p=Path(path)
    try:
        rel=p.resolve().relative_to(Path(cache_root).resolve()) if cache_root else p
    except Exception:
        rel=p
    parts=[re.sub(r'[^a-z0-9]+','_',str(x).lower()).strip('_') for x in rel.parts]
    name=p.name.lower()
    # The nearest cache directory is authoritative. This avoids the Windows
    # C:/Users/... -> "sers" false positive and avoids reading 100s of headers.
    for part in parts[:-1]:
        if part in _V206_CACHE_DIR_MAP:
            tech=_V206_CACHE_DIR_MAP[part]
            # Preserve legacy CA/CP correction for old bundles stored under CV_LSV.
            if tech=='CV/LSV':
                bn=str(base_name or '').lower()
                if re.search(r'(^|[^a-z0-9])ca([^a-z0-9]|$)',bn) or bn.endswith('_ca'):
                    return None
                if re.search(r'(^|[^a-z0-9])cp([^a-z0-9]|$)',bn) or bn.endswith('_cp'):
                    return None
            return tech
    # Strong filename fallbacks.
    if name.startswith('cv_') or 'current_vs_potential' in name or 'scanrate_' in name:
        return 'CV/LSV'
    if any(x in name for x in ('nyquist','bode','fulleis')):
        return 'EIS'
    if 'drt_data' in name or re.search(r'(^|[_\-])drt([_\-.]|$)',name):
        return 'DRT'
    return None


def _v206_classify(path, cols=None, base_name=''):
    p=Path(path); n=p.name.lower(); flags=_v206_col_flags(cols or _v206_header_columns(p))
    toks=_v206_tokenize_path(p)
    # Numeric signatures are strongest.
    if flags['tau'] and flags['gamma']: return 'DRT'
    if flags['zreal'] and flags['zimag']: return 'EIS'
    # Legacy cache repair: old CA/CP exports may have been stored under CV_LSV.
    # Use the dataset name plus the signal behavior before accepting the cache directory.
    bn=str(base_name or '').lower()
    in_cv_cache=('cv_lsv' in toks or 'cyclic_voltammetry' in toks)
    if in_cv_cache and flags['time'] and flags['potential']:
        if re.search(r'(^|[^a-z0-9])ca([^a-z0-9]|$)',bn) or bn.endswith('_ca'):
            if flags['current']:
                spans=_v206_signal_spans(p,cols or _v206_header_columns(p))
                pspan=max([v for k,v in spans.items() if 'potential' in k or k in {'ewe','voltagev'}] or [999.0])
                if pspan < 0.01: return 'CA'
        if re.search(r'(^|[^a-z0-9])cp([^a-z0-9]|$)',bn) or bn.endswith('_cp'):
            return 'CP'
    # Canonical cache/path classification before generic spectroscopy checks.
    fast=_v206_fast_cache_tech(p, None, base_name=base_name)
    if fast:
        if fast=='CV/LSV':
            bn=str(base_name or '').lower()
            if (re.search(r'(^|[^a-z0-9])ca([^a-z0-9]|$)',bn) or bn.endswith('_ca')) and flags['time'] and flags['current'] and flags['potential']:
                spans=_v206_signal_spans(p,cols or _v206_header_columns(p))
                pspan=max([v for k,v in spans.items() if 'potential' in k or k in {'ewe','voltagev'}] or [999.0])
                if pspan < 0.01: return 'CA'
            if (re.search(r'(^|[^a-z0-9])cp([^a-z0-9]|$)',bn) or bn.endswith('_cp')) and flags['time'] and flags['potential']:
                return 'CP'
        return fast
    # Exact technique tokens; never substring-match "sers" inside "Users".
    if 'conductivity' in toks: return 'Conductivity'
    if 'eqcm' in toks or ('mass' in n and 'qcm' in toks): return 'EQCM'
    if 'gitt' in toks: return 'GITT'
    if 'pitt' in toks: return 'PITT'
    if 'mott_schottky' in toks or 'mottschottky' in toks: return 'Mott-Schottky'
    if 'rrde' in toks or 'rde' in toks: return 'RDE/RRDE'
    if 'electrochemical_noise' in toks or 'ecnoise' in toks: return 'Electrochemical noise'
    if 'raman' in toks or 'sers' in toks: return 'Raman/SERS'
    if 'ftir' in toks or 'irras' in toks or 'infrared' in toks: return 'FTIR/IR'
    if 'uv_vis' in toks or 'uvvis' in toks: return 'UV-Vis'
    if 'xrd' in toks: return 'XRD'
    if 'xps' in toks: return 'XPS'
    if 'chronoamperometry' in toks or re.search(r'(^|[_\-])ca([_\-.]|$)',n) or 'fullca' in n or 'chronoamp' in n: return 'CA'
    if 'chronopotentiometry' in toks or re.search(r'(^|[_\-])cp([_\-.]|$)',n) or 'fullcp' in n or 'chronopot' in n: return 'CP'
    if 'ocp' in toks or 'ocv' in toks or re.search(r'(^|[_\-])(ocp|ocv)([_\-.]|$)',n): return 'OCP/OCV'
    if any(x in n for x in ('nyquist','bode','fulleis')) or 'eis' in toks: return 'EIS'
    if 'drt' in toks and 'eis_data' not in n and ('drt' in n or flags['gamma']): return 'DRT'
    if 'dpv' in toks: return 'DPV'
    if 'swv' in toks: return 'SWV'
    if 'npv' in toks: return 'NPV'
    if 'gcpl' in toks or 'gcd' in toks or 'charge_discharge' in toks: return 'GCD/GCPL'
    if 'chronocoulometry' in toks or 'chronocoul' in toks: return 'Chronocoulometry'
    if 'zra' in toks: return 'ZRA'
    if 'tafel' in toks: return 'IV/Tafel'
    if 'lsv' in toks and 'cv_lsv' not in toks: return 'LSV'
    if 'iv' in toks: return 'IV/Tafel'
    if 'cv_lsv' in toks or 'cv' in toks or 'scanrate' in toks or 'cycle' in toks:
        return 'CV/LSV'
    # Column fallback.
    if flags['time'] and flags['current'] and flags['charge']: return 'CA'
    if flags['time'] and flags['potential'] and not flags['current']: return 'OCP/OCV'
    if flags['potential'] and flags['current']: return 'IV/Tafel'
    if flags['time'] and flags['current']: return 'CA/CP'
    return 'Other'


def _v206_external_candidate(path):
    p=Path(path); n=p.name.lower(); toks=_v206_tokenize_path(p)
    if any(part.lower() in _V206_SKIP_PARTS for part in p.parts): return False
    if any(x in n for x in ('drt_data','simple_drt','bayes_drt','bht_drt','deareis_drt')): return True
    exact={'ca','cp','ocp','ocv','tafel','dpv','swv','npv','gcpl','gcd','chronocoulometry','zra',
           'conductivity','eqcm','gitt','pitt','mott_schottky','rrde','rde','electrochemical_noise',
           'raman','sers','ftir','irras','uv_vis','xrd','xps'}
    if toks & exact: return True
    return any(x in n for x in ('ca_point','cp_point','fullca','fullcp','fulliv','fullocp'))


def _v206_source_signature(cache_root,bundle_root):
    vals=[]
    for root in (Path(cache_root),Path(bundle_root)):
        try:
            st=root.stat(); vals.extend([str(root),st.st_mtime_ns,st.st_size])
            for ch in sorted(root.iterdir(),key=lambda x:x.name.lower()):
                try:
                    st=ch.stat(); vals.extend([ch.name,st.st_mtime_ns,st.st_size])
                except Exception: pass
        except Exception: pass
    return tuple(vals)


def _v206_collect_browser_records(cache_root, bundle_root=None, manifest=None, base_name=''):
    t0=time.perf_counter()
    cache_root=Path(cache_root).resolve(); bundle_root=Path(bundle_root).resolve() if bundle_root else cache_root.parent
    sig=_v206_source_signature(cache_root,bundle_root)
    key=(str(cache_root),str(bundle_root),str(base_name),sig)
    cached=_V206_FAST_RECORD_CACHE.get(key)
    if cached is not None:
        return [dict(r) for r in cached]
    records=[]; seen=set()
    def add(p,source,tech_hint=None):
        try:
            p=Path(p).resolve()
            if p in seen or not p.is_file() or p.suffix.lower() not in _V206_TABLE_EXTS: return
            if p.name.lower().startswith('readme'): return
            tech=tech_hint or _v206_fast_cache_tech(p,cache_root,base_name=base_name)
            cols=[]
            if tech is None:
                cols=_v206_header_columns(p); tech=_v206_classify(p,cols,base_name=base_name)
            elif tech in {'DRT','EIS'}:
                # Keep columns available for DRT/EIS de-dup signatures without an expensive full read.
                cols=[]
            meta=_v206_path_meta(p)
            records.append({'path':p,'source':source,'tech':tech,'cols':cols,**meta})
            seen.add(p)
        except Exception:
            return
    # Fast canonical-cache walk: classify from relative directory, no CSV header reads.
    if cache_root.exists():
        for dirpath,dirs,files in os.walk(cache_root):
            dirs[:]=[d for d in dirs if d.lower() not in _V206_SKIP_PARTS and d!='__pycache__']
            for fn in files:
                p=Path(dirpath)/fn
                if p.suffix.lower() in _V206_TABLE_EXTS:
                    add(p,'cache')
    cache_techs={r['tech'] for r in records}
    # One metadata-only bundle walk. Open headers only for plausible external candidates.
    if bundle_root.exists():
        cache_s=str(cache_root).lower()
        for dirpath,dirs,files in os.walk(bundle_root):
            dp=Path(dirpath)
            try:
                if cache_root==dp.resolve() or cache_root in dp.resolve().parents:
                    dirs[:]=[]; continue
            except Exception: pass
            dirs[:]=[d for d in dirs if d.lower() not in _V206_SKIP_PARTS and d not in {'.git','.venv','venv','node_modules','__pycache__'}]
            for fn in files:
                p=dp/fn
                if p.suffix.lower() not in _V206_TABLE_EXTS or not _v206_external_candidate(p): continue
                try:
                    if _v206_is_drt_output(p):
                        add(p,'external_drt','DRT')
                    else:
                        cols=_v206_header_columns(p); tech=_v206_classify(p,cols,base_name=base_name)
                        if tech not in cache_techs and tech not in {'Other','EIS','DRT','CV/LSV'}:
                            add(p,'external',tech)
                except Exception:
                    pass
    # DRT de-duplication.
    out=[]; drt_best={}
    for r in records:
        if r['tech']!='DRT': out.append(r); continue
        k=(r.get('run'),r.get('engine'),r.get('method'),r.get('point'))
        if k not in drt_best or _v206_drt_score(r)>_v206_drt_score(drt_best[k]): drt_best[k]=r
    out.extend(drt_best.values()); records=out
    # Suppress aggregate duplicates when point-resolved records exist.
    for tech in ('CA','CP','CA/CP','EIS','OCP/OCV','IV/Tafel','LSV','DPV','SWV','NPV','GCD/GCPL','Chronocoulometry','ZRA',
                 'Conductivity','EQCM','GITT','PITT','Mott-Schottky','RDE/RRDE','Electrochemical noise',
                 'Raman/SERS','FTIR/IR','UV-Vis','XRD','XPS'):
        if any(r['tech']==tech and int(r.get('point') or 0)>0 for r in records):
            records=[r for r in records if not (r['tech']==tech and int(r.get('point') or 0)==0 and any(tok in r['path'].name.lower() for tok in ('combined','all_points','allpositions','summary')))]
    # Repair flattened HEKA CV numbering.
    val=_v206_validation(manifest)
    try: expected_points=int(val.get('expected_points_from_dat') or 0)
    except Exception: expected_points=0
    try: cycles_per=int(val.get('expected_cycles_per_cv_from_dat') or 0)
    except Exception: cycles_per=0
    by_rate={}
    for r in records:
        if r['tech']=='CV/LSV': by_rate.setdefault(r.get('rate','unknown'),[]).append(r)
    if expected_points>1 and cycles_per>0:
        for rate,grp in by_rate.items():
            pts={r.get('point',0) for r in grp}; mx=max([r.get('cycle',0) for r in grp] or [0])
            if len(pts)<=1 and mx>=expected_points*cycles_per:
                for r in grp:
                    serial=max(1,int(r.get('cycle') or 1))
                    r['point']=((serial-1)//cycles_per)+1; r['cycle']=((serial-1)%cycles_per)+1; r['cv_repaired']=True
    records=sorted(records,key=lambda r:(r['tech'],str(r.get('rate','')),int(r.get('method') or 0),int(r.get('point') or 0),int(r.get('cycle') or 0),str(r['path']).lower()))
    # Keep only the latest signature per root in memory.
    for old in list(_V206_FAST_RECORD_CACHE):
        if old[:3]==key[:3] and old!=key: _V206_FAST_RECORD_CACHE.pop(old,None)
    _V206_FAST_RECORD_CACHE[key]=[dict(r) for r in records]
    try:
        globals()['_V206_LAST_COLLECT_SECONDS']=time.perf_counter()-t0
    except Exception: pass
    return records


