#    legacy cache folder contains the token CV_LSV.
APP_TITLE = "FaradaIQ Studio v273"
FARADAIQ_PUBLIC_VERSION = "v216"


def _v206_exact_component_token(text, token):
    return re.search(r"(?<![a-z0-9])" + re.escape(str(token).lower()) + r"(?![a-z0-9])", str(text or "").lower()) is not None


def _v206_dataset_chrono_kind(base_name='', manifest=None, bundle_root=None):
    vals=[str(base_name or '')]
    if isinstance(manifest,dict):
        vals.extend(str(manifest.get(k) or '') for k in ('base_name','label','sample_name'))
        try:
            vals.extend(str(x) for x in manifest.get('techniques_detected',[]) or [])
        except Exception: pass
    if bundle_root is not None:
        try: vals.append(Path(bundle_root).name)
        except Exception: pass
    joined=' '.join(vals)
    if any(_v206_exact_component_token(v,'ca') for v in vals) or 'chronoamper' in joined.lower() or 'chronopotstat' in joined.lower():
        return 'CA'
    if any(_v206_exact_component_token(v,'cp') for v in vals) or 'chronopotentiometry' in joined.lower() or 'chronogalv' in joined.lower():
        return 'CP'
    return None


def _v206_is_helper_table(path):
    n=Path(path).name.lower()
    helpers=(
        'bundle_sections','trace_index','method_entries','photo_manifest','position_report',
        'pair_summary','parser_short_name_aliases','generic_drt_input_manifest','runtime_history',
        'runtime_summary','plotting_analysis_manifest','sequence_manifest','point_manifest',
        'readme','ai_prompt','progress','launch_manifest','metadata','summary'
    )
    return any(x in n for x in helpers)


# Future raw HEKA exports: a collapsed single block containing N chrono pairs for N
# spatial points is one method across N points, not N methods at point 1.
try:
    _V206_PREV_COLLECT_CHRONO_ALLOC = _v198_collect_chrono_method_allocations
except Exception:
    _V206_PREV_COLLECT_CHRONO_ALLOC = None


def _v198_collect_chrono_method_allocations(self):
    try:
        by=_v198_non_cv_remaining_pairs_by_block(self)
    except Exception:
        by={}
    if not by:
        return {}
    # Determine expected line-scan point count from stage/takedata rows. Synthetic
    # ordered positions are acceptable because they preserve the acquisition order.
    point_count=0
    try:
        rows,_src=_heka_v15_position_rows_from_dat(self)
        point_count=len(rows or [])
    except Exception:
        point_count=0
    if len(by)==1:
        bi=next(iter(by))
        pairs=list(by.get(bi) or [])
        if point_count>1 and len(pairs)>=point_count and len(pairs)%point_count==0:
            n_methods=max(1,len(pairs)//point_count)
            kinds=_v198_chrono_method_kinds(self,n_methods)
            if kinds:
                alloc={}
                for serial,p0 in enumerate(pairs):
                    point=(serial//n_methods)+1
                    method=(serial%n_methods)+1
                    kind=kinds[method-1] if method-1<len(kinds) else kinds[-1]
                    if kind not in {'CA','CP'}: continue
                    p=dict(p0)
                    p['block_index0']=int(bi)
                    p['point_index']=int(point)
                    p['method_type']=kind
                    p['method_entry']=int(method)
                    p['local_chrono_index']=int(method)
                    p['source_repair_v206']='collapsed_single_block_points_methods_reconstruction'
                    alloc.setdefault((kind,method),[]).append(p)
                if alloc:
                    return alloc
    if callable(_V206_PREV_COLLECT_CHRONO_ALLOC):
        return _V206_PREV_COLLECT_CHRONO_ALLOC(self)
    return {}


# Browser classification/index repair. The previous deterministic collector remains
# the source of files; this layer changes only proven chrono misclassification and
# removes helper/support tables from scientific technique roots.
try:
    _V206_PREV_COLLECT_BROWSER_RECORDS = _v206_collect_browser_records
except Exception:
    _V206_PREV_COLLECT_BROWSER_RECORDS = None


def _v206_collect_browser_records(cache_root, bundle_root=None, manifest=None, base_name=''):
    if callable(_V206_PREV_COLLECT_BROWSER_RECORDS):
        records=_V206_PREV_COLLECT_BROWSER_RECORDS(cache_root,bundle_root,manifest,base_name)
    else:
        records=[]
    kind=_v206_dataset_chrono_kind(base_name,manifest,bundle_root)
    # The canonical H5 cache is authoritative for declared CA/CP datasets. Older
    # analysis-ready helper exports can look like I-V tables and otherwise create a
    # second, incorrect technique root. Keep post-H5 DRT outputs, but suppress those
    # alternate electrochemical views when point-resolved chrono cache tables exist.
    has_authoritative_chrono = bool(kind in {'CA','CP'} and any(
        str(r.get('source') or '') == 'cache' and str(r.get('tech') or '') == kind
        for r in records
    ))
    if has_authoritative_chrono:
        records=[r for r in records if not (
            str(r.get('source') or '') == 'external' and
            str(r.get('tech') or '') in {'CV/LSV','IV/Tafel','CA/CP','CA','CP'}
        )]
    repaired=[]
    for src in records:
        r=dict(src)
        p=Path(r.get('path',''))
        if _v206_is_helper_table(p):
            continue
        # Old H5/browser caches may still be physically under CV_LSV. Dataset and
        # method evidence override that folder only for generic line-scan records.
        if kind in {'CA','CP'} and r.get('tech')=='CV/LSV':
            r['tech']=kind
            r['rate']=''
            r['method']=int(r.get('method') or 1)
            r['chrono_repaired_v206']=True
        repaired.append(r)
    records=repaired
    # Legacy direct-folder CA export: point 1 + methods 1..N was actually N ordered
    # line-scan points when the expected point count equals the number of files.
    target=kind if kind in {'CA','CP'} else None
    if target:
        arr=[r for r in records if r.get('tech')==target]
        try:
            val=_v206_validation(manifest)
            expected=int(val.get('expected_points_from_dat') or 0)
        except Exception:
            expected=0
        methods=sorted({int(r.get('method') or 1) for r in arr})
        points={int(r.get('point') or 0) for r in arr}
        if expected>1 and len(arr)>=expected and len(points)<=1 and len(methods)>=expected:
            for r in arr:
                me=int(r.get('method') or 1)
                if 1<=me<=expected:
                    r['point']=me
                    r['method']=1
                    r['chrono_repaired_v206']=True
    return sorted(records,key=lambda r:(str(r.get('tech','')),str(r.get('run','')),str(r.get('engine','')),int(r.get('method') or 0),int(r.get('point') or 0),int(r.get('cycle') or 0),str(r.get('path','')).lower()))


# Plot technique classification: exact CA/CP path components are evaluated before
# generic current-potential/CV tests. This guarantees I-t for CA and E-t for CP.
def _v206_path_tokens(path):
    toks=set()
    try:
        for part in Path(path).parts:
            low=str(part).lower()
            toks.update(x for x in re.split(r'[^a-z0-9]+',low) if x)
            norm=re.sub(r'[^a-z0-9]+','_',low).strip('_')
            if norm: toks.add(norm)
    except Exception: pass
    return toks


def _v206c_tech_for_file(path, df, mode='Auto'):
    cols=_v206c_columns(df)
    toks=_v206_path_tokens(path)
    low=str(path).lower().replace('\\','/')
    is_ca=('ca' in toks or 'chronoamperometry' in toks or 'chronoamp' in toks or 'fullca' in low)
    is_cp=('cp' in toks or 'chronopotentiometry' in toks or 'chronopot' in toks or 'fullcp' in low)
    if cols.get('zr') and (cols.get('zi') or cols.get('negzi')):
        return 'EIS',cols
    if cols.get('tau') and cols.get('gamma'):
        return 'DRT',cols
    if is_ca and cols.get('time') and cols.get('cur'):
        return 'CA/CP',cols
    if is_cp and cols.get('time') and (cols.get('pot') or cols.get('cur')):
        return 'CA/CP',cols
    if _v206b_path_or_mode_says_cv(path,mode) and cols.get('cur'):
        return 'CV/LSV/IV',cols
    if cols.get('pot') and cols.get('cur'):
        return 'CV/LSV/IV',cols
    if cols.get('time') and cols.get('cur'):
        return 'CA/CP',cols
    return 'Numeric',cols

