def _v206_refresh_tree(self):
    try:
        self.tree.delete(*self.tree.get_children()); self._path_by_iid.clear()
        records=_v206_collect_browser_records(self.cache_root,_v206_bundle_root(self),getattr(self,'manifest',{}),getattr(self,'base_name',''))
        groups={}
        for r in records: groups.setdefault(r.get('tech','Other'),[]).append(r)
        node_cache={}
        def node(parent,label,kind='',open=False):
            key=(parent,label,kind)
            if key in node_cache: return node_cache[key]
            iid=self.tree.insert(parent,'end',text=label,values=(kind,''),open=open); node_cache[key]=iid; return iid
        def root(label,open=False): return node('',label,'',open)
        def leaf(parent,label,r,kind=None):
            try: size=_v138_fmt_size(Path(r['path']).stat().st_size)
            except Exception: size=''
            iid=self.tree.insert(parent,'end',text=label,values=(kind or r.get('tech',''),size),open=False)
            self._path_by_iid[iid]=Path(r['path']); return iid
        cv=groups.get('CV/LSV',[])
        if cv:
            rr=root('CV / LSV',True); br=node(rr,'Grouped by scan rate','view',True); bp=node(rr,'Grouped by point','view',False)
            for r in cv:
                rate=_v206_rate_label(r.get('rate')); pt=int(r.get('point') or 0); cy=int(r.get('cycle') or 0)
                rn=node(br,rate,'scan rate',False); pn=node(rn,f'point {pt:02d}','point',False)
                leaf(pn,f'cycle {cy:02d}',r,'CV / LSV')
                pn2=node(bp,f'point {pt:02d}','point',False); rn2=node(pn2,rate,'scan rate',False)
                leaf(rn2,f'cycle {cy:02d}',r,'CV / LSV')
        eis=groups.get('EIS',[])
        if eis:
            rr=root('EIS — Nyquist / Bode',True); bp=node(rr,'Grouped by point','view',True); bm=node(rr,'Grouped by method','view',False)
            for r in eis:
                pt=int(r.get('point') or 0); me=int(r.get('method') or 1)
                pn=node(bp,f'point {pt:02d}','EIS point',False); leaf(pn,f'method {me:02d}',r,'EIS')
                mn=node(bm,f'method {me:02d}','EIS method',False); leaf(mn,f'point {pt:02d}',r,'EIS')
        drt=groups.get('DRT',[])
        if drt:
            rr=root('DRT analyzed results',True)
            for run_name in sorted({str(r.get('run') or 'DRT results') for r in drt},key=str.lower):
                run=node(rr,run_name,'DRT run',True)
                run_rows=[r for r in drt if str(r.get('run') or 'DRT results')==run_name]
                for eng_name in sorted({str(r.get('engine') or 'DRT') for r in run_rows},key=str.lower):
                    eng=node(run,eng_name,'DRT engine',True)
                    eng_rows=[r for r in run_rows if str(r.get('engine') or 'DRT')==eng_name]
                    bp=node(eng,'Grouped by point','view',True)
                    bm=node(eng,'Grouped by method','view',False)
                    for r in eng_rows:
                        pt=int(r.get('point') or 0); me=int(r.get('method') or 1)
                        pn=node(bp,f'point {pt:02d}','DRT point',False)
                        leaf(pn,f'method {me:02d}',r,'DRT')
                        mn=node(bm,f'method {me:02d}','DRT method',False)
                        leaf(mn,f'point {pt:02d}',r,'DRT')
        def chrono_root(tech,label):
            arr=groups.get(tech,[])
            if not arr: return
            rr=root(label,tech=='CA')
            bp=node(rr,'Grouped by point','view',True)
            bm=node(rr,'Grouped by method','view',False)
            for r in arr:
                pt=int(r.get('point') or 0); me=int(r.get('method') or 1); cy=int(r.get('cycle') or 0)
                pn=node(bp,f'point {pt:02d}','point',False)
                l1=f'method {me:02d}' + (f' — cycle {cy:02d}' if cy else '')
                leaf(pn,l1,r,tech)
                mn=node(bm,f'method {me:02d}',f'{tech} method',False)
                l2=f'point {pt:02d}' + (f' — cycle {cy:02d}' if cy else '')
                leaf(mn,l2,r,tech)
        chrono_root('CA','Chronoamperometry (CA)')
        chrono_root('CP','Chronopotentiometry (CP)')
        chrono_root('CA/CP','Chrono transients (CA / CP)')
        def standard_root(tech,label):
            arr=groups.get(tech,[])
            if not arr:return
            rr=root(label,False)
            methods={int(r.get('method') or 1) for r in arr}
            for r in arr:
                pt=int(r.get('point') or 0); me=int(r.get('method') or 1); cy=int(r.get('cycle') or 0)
                parent=rr
                if len(methods)>1: parent=node(rr,f'method {me:02d}',f'{tech} method',False)
                txt=f'point {pt:02d}' if pt else Path(r['path']).stem
                if cy: txt+=f' — cycle {cy:02d}'
                leaf(parent,txt,r,tech)
        for tech,label in [
            ('OCP/OCV','Open-circuit potential (OCP / OCV)'),('LSV','Linear sweep voltammetry (LSV)'),
            ('IV/Tafel','I–V / Tafel'),('DPV','Differential pulse voltammetry (DPV)'),
            ('SWV','Square-wave voltammetry (SWV)'),('NPV','Normal pulse voltammetry (NPV)'),
            ('GCD/GCPL','Galvanostatic charge–discharge (GCD / GCPL)'),('Chronocoulometry','Chronocoulometry'),
            ('ZRA','Zero-resistance ammetry (ZRA)'),('Conductivity','Conductivity / constant-voltage measurements'),
            ('EQCM','Electrochemical quartz crystal microbalance (EQCM)'),('GITT','Galvanostatic intermittent titration (GITT)'),
            ('PITT','Potentiostatic intermittent titration (PITT)'),('Mott-Schottky','Mott–Schottky'),
            ('RDE/RRDE','Rotating disk / ring-disk electrode (RDE / RRDE)'),('Electrochemical noise','Electrochemical noise'),
            ('Raman/SERS','Raman / SERS'),('FTIR/IR','FTIR / IR'),('UV-Vis','UV–Vis'),('XRD','X-ray diffraction (XRD)'),
            ('XPS','X-ray photoelectron spectroscopy (XPS)')]:
            standard_root(tech,label)
        other=groups.get('Other',[])
        if other:
            rr=root('Other numeric tables',False)
            for r in other: leaf(rr,Path(r['path']).name,r,'Numeric')
        counts={k:len(v) for k,v in groups.items() if v}
        self._v206_technique_counts=counts
        try:
            order=['CV/LSV','EIS','DRT','CA','CP','CA/CP','OCP/OCV','LSV','IV/Tafel','DPV','SWV','NPV','GCD/GCPL','Chronocoulometry','ZRA','Conductivity','EQCM','GITT','PITT','Mott-Schottky','RDE/RRDE','Electrochemical noise','Raman/SERS','FTIR/IR','UV-Vis','XRD','XPS','Other']
            text=' | '.join(f'{k} {counts[k]}' for k in order if counts.get(k)) or 'no plottable tables'
            self.summary_var.set(f'H5/source index | {text}')
        except Exception: pass
        try:
            self.log(f'v210 technique tree: unique records={len(records)}, counts={counts}; DRT and chrono point/method grouping enabled.')
        except Exception: pass
        try: _v206_write_qa_summary(self)
        except Exception: pass
    except Exception as exc:
        try: self.log(f'v210 refresh tree failed: {exc}\n{traceback.format_exc()}')
        except Exception: pass

