# ---- FaradaIQ Studio v273 official HEKA/POTMASTER trace decoding repair ----
# The legacy generic trace scanner assumed every DAT trace was little-endian float32
# and did not apply TrDataFormat, TrDataScaler, or TrZeroData. HEKA's published
# v1000 TraceRecord stores those fields in the PUL tree and permits int16, int32,
# real32, and real64 data. Misreading int16 data as float32 produces the enormous
# 1e28-1e38 values seen in malformed CA exports. This patch parses the actual PUL
# tree first and falls back to the legacy scanner only for unsupported layouts.

try:
    _V206_LEGACY_FIND_HEKA_TRACES = HEKAPotmasterParser._find_trace_records_generic
    _V206_LEGACY_READ_HEKA_TRACE = HEKAPotmasterParser.read_trace_array
    _V206_LEGACY_TRACE_INTERVAL = _heka_v15_trace_sample_interval_s
except Exception:
    _V206_LEGACY_FIND_HEKA_TRACES = None
    _V206_LEGACY_READ_HEKA_TRACE = None
    _V206_LEGACY_TRACE_INTERVAL = None

_V206_HEKA_DTYPE_INFO = {
    0: ('i2', 2),   # int16
    1: ('i4', 4),   # int32
    2: ('f4', 4),   # IEEE real32
    3: ('f8', 8),   # IEEE real64
}


def _v206_heka_cstring(raw):
    try:
        return bytes(raw).split(b'\x00', 1)[0].decode('latin-1', errors='replace').strip()
    except Exception:
        return ''


def _v206_heka_tree_trace_records(self):
    pul = bytes(getattr(self, 'pul', b'') or b'')
    if len(pul) < 16:
        return []
    magic = pul[:4]
    if magic == b'eerT':
        endian = '<'
    elif magic == b'Tree':
        endian = '>'
    else:
        return []
    try:
        levels = _heka_struct.unpack_from(endian + 'i', pul, 4)[0]
        if not (1 <= levels <= 16):
            return []
        level_sizes = list(_heka_struct.unpack_from(endian + ('i' * levels), pul, 8))
        if any(size <= 0 or size > 100000 for size in level_sizes):
            return []
        pos = 8 + 4 * levels
    except Exception:
        return []

    records = []
    trace_level = levels - 1

    def walk(level):
        nonlocal pos
        if level < 0 or level >= levels:
            raise ValueError('invalid PUL tree level')
        rec_size = int(level_sizes[level])
        rec_off = pos
        rec_end = rec_off + rec_size
        if rec_end + 4 > len(pul):
            raise EOFError('truncated PUL tree record')
        rec = pul[rec_off:rec_end]
        pos = rec_end
        child_count = _heka_struct.unpack_from(endian + 'i', pul, pos)[0]
        pos += 4
        if child_count < 0 or child_count > 10000000:
            raise ValueError('invalid PUL child count')

        if level == trace_level and rec_size >= 121:
            try:
                label = _v206_heka_cstring(rec[4:36])
                old_offset = int(_heka_struct.unpack_from(endian + 'i', rec, 40)[0])
                if old_offset < 0:
                    old_offset += 1 << 32
                n_points = int(_heka_struct.unpack_from(endian + 'i', rec, 44)[0])
                data_kind = int(_heka_struct.unpack_from(endian + 'H', rec, 64)[0])
                data_format = int(rec[70])
                scaler = float(_heka_struct.unpack_from(endian + 'd', rec, 72)[0])
                time_offset = float(_heka_struct.unpack_from(endian + 'd', rec, 80)[0])
                zero_data = float(_heka_struct.unpack_from(endian + 'd', rec, 88)[0])
                y_unit = _v206_heka_cstring(rec[96:104])
                x_interval = float(_heka_struct.unpack_from(endian + 'd', rec, 104)[0])
                x_start = float(_heka_struct.unpack_from(endian + 'd', rec, 112)[0])
                x_unit = _v206_heka_cstring(rec[120:128]) if rec_size >= 128 else ''
                dtype_code, itemsize = _V206_HEKA_DTYPE_INFO.get(data_format, (None, 0))
                if (
                    label and _heka_is_printable_label(label)
                    and 0 < n_points < 200000000
                    and dtype_code is not None
                    and np.isfinite(scaler) and np.isfinite(zero_data)
                ):
                    nbytes = int(n_points) * int(itemsize)
                    mode = self._classify_trace_offset(old_offset, nbytes)
                    if mode != 'unknown' or not getattr(self, 'dat_payload_length', 0):
                        tr = HekaTraceRec(-1, rec_off, label, data_kind, old_offset, n_points, nbytes, mode)
                        # Dynamic attributes preserve compatibility with the historical dataclass.
                        tr.data_format = data_format
                        tr.data_scaler = scaler
                        tr.zero_data = zero_data
                        tr.time_offset = time_offset
                        tr.x_interval = x_interval
                        tr.x_start = x_start
                        tr.x_unit = x_unit
                        tr.y_unit = y_unit
                        tr.data_endian = '<' if (data_kind & 0x1) else '>'
                        tr.itemsize = itemsize
                        tr.record_layout = 'HEKA_PUL_v1000_tree'
                        if rec_size >= 300:
                            tr.interleave_size = int(_heka_struct.unpack_from(endian + 'i', rec, 292)[0])
                            tr.interleave_skip = int(_heka_struct.unpack_from(endian + 'i', rec, 296)[0])
                        else:
                            tr.interleave_size = 0
                            tr.interleave_skip = 0
                        records.append(tr)
            except Exception:
                pass

        if level + 1 < levels:
            for _ in range(child_count):
                walk(level + 1)

    try:
        walk(0)
    except Exception:
        return []
    if not records:
        return []
    for index, trace in enumerate(records):
        trace.tree_index = index
    try:
        self.heka_trace_layout = 'HEKA_PUL_v1000_tree'
        self.heka_trace_endian = endian
    except Exception:
        pass
    return records


def _v206_find_heka_trace_records(self):
    records = _v206_heka_tree_trace_records(self)
    if records:
        try:
            self.notes.append(
                f'v216: decoded {len(records)} HEKA traces from the PUL tree with per-trace data format, byte order, scaler, and zero offset.'
            )
        except Exception:
            pass
        return records
    if callable(_V206_LEGACY_FIND_HEKA_TRACES):
        records = _V206_LEGACY_FIND_HEKA_TRACES(self)
        try:
            self.notes.append('v210: official PUL tree layout was not recognized; used legacy trace scanner fallback.')
        except Exception:
            pass
        return records
    return []


def _v206_read_heka_trace_array(self, trace_index, max_points=None):
    trace = self.traces[int(trace_index)]
    if not hasattr(trace, 'data_format'):
        if callable(_V206_LEGACY_READ_HEKA_TRACE):
            return _V206_LEGACY_READ_HEKA_TRACE(self, trace_index, max_points=max_points)
        raise ValueError('HEKA trace format metadata is unavailable.')
    n = int(trace.n_points if max_points is None else min(trace.n_points, int(max_points)))
    dtype_code, itemsize = _V206_HEKA_DTYPE_INFO.get(int(trace.data_format), (None, 0))
    if dtype_code is None or n <= 0:
        return np.asarray([], dtype=float)
    dtype = np.dtype(str(getattr(trace, 'data_endian', '<')) + dtype_code)
    total_bytes = n * itemsize

    def read_contiguous(start, count_bytes):
        if self.mode == 'bytes_bundle':
            if '.dat' not in self.section_bytes:
                raise ValueError('No .dat section bytes are available.')
            payload = self.section_bytes['.dat']
            if trace.data_offset_mode in {'bundle_absolute', 'raw_absolute'}:
                local_start = int(start) - int(self.dat_payload_offset)
            else:
                local_start = int(start)
            return bytes(payload[local_start:local_start + count_bytes])
        if self.dat_payload_path is None:
            raise ValueError('No data payload path available.')
        absolute = self._trace_abs_file_offset(trace)
        with self.dat_payload_path.open('rb') as handle:
            handle.seek(absolute)
            return handle.read(count_bytes)

    interleave_size = int(getattr(trace, 'interleave_size', 0) or 0)
    interleave_skip = int(getattr(trace, 'interleave_skip', 0) or 0)
    if interleave_size > 0 and interleave_skip > 0 and total_bytes > interleave_size:
        chunks = []
        remaining = total_bytes
        block_start = int(trace.old_offset)
        while remaining > 0:
            take = min(interleave_size, remaining)
            # For interleaved traces, each stored block begins interleave_skip bytes after the previous block.
            if self.mode == 'bytes_bundle':
                payload = self.section_bytes.get('.dat', b'')
                local = block_start - int(self.dat_payload_offset) if trace.data_offset_mode in {'bundle_absolute', 'raw_absolute'} else block_start
                chunks.append(bytes(payload[local:local + take]))
            else:
                if self.dat_payload_path is None:
                    raise ValueError('No data payload path available.')
                absolute = block_start if self.mode == 'bundle' and trace.data_offset_mode in {'bundle_absolute', 'raw_absolute'} else int(self.dat_payload_offset) + block_start
                with self.dat_payload_path.open('rb') as handle:
                    handle.seek(absolute)
                    chunks.append(handle.read(take))
            remaining -= take
            block_start += interleave_skip
        raw = b''.join(chunks)
    else:
        raw = read_contiguous(int(trace.old_offset), total_bytes)
    count = min(n, len(raw) // itemsize)
    if count <= 0:
        return np.asarray([], dtype=float)
    values = np.frombuffer(raw, dtype=dtype, count=count).astype(float)
    values = values * float(getattr(trace, 'data_scaler', 1.0)) + float(getattr(trace, 'zero_data', 0.0))
    return values


def _v206_heka_trace_sample_interval_s(self, trace_index):
    try:
        trace = self.traces[int(trace_index)]
        interval = float(getattr(trace, 'x_interval'))
        if np.isfinite(interval) and 0 < interval < 1e6:
            return interval
    except Exception:
        pass
    if callable(_V206_LEGACY_TRACE_INTERVAL):
        return _V206_LEGACY_TRACE_INTERVAL(self, trace_index)
    return float('nan')


try:
    HEKAPotmasterParser._find_trace_records_generic = _v206_find_heka_trace_records
    HEKAPotmasterParser.read_trace_array = _v206_read_heka_trace_array
    _heka_v15_trace_sample_interval_s = _v206_heka_trace_sample_interval_s
except Exception:
    pass

