def _v208_apply_title(window, base="FaradaIQ Studio v273"):
    """Apply the public release version while retaining an optional window suffix."""
    try:
        source = str(base or "FaradaIQ Studio v273")
        suffix = ""
        if "—" in source:
            suffix = source.split("—", 1)[1].strip()
        elif " - " in source:
            suffix = source.split(" - ", 1)[1].strip()
        title = "FaradaIQ Studio v273"
        if suffix:
            title += " — " + suffix
        window.title(title)
    except Exception:
        try:
            window.title("FaradaIQ Studio v273")
        except Exception:
            pass


