def _v208_reset_parser_status(gui, reason="ready"):
    """Reset parser progress before a new load or export transaction."""
    try:
        gui._v208_parser_generation = int(getattr(gui, "_v208_parser_generation", 0)) + 1
    except Exception:
        pass
    try:
        _v67_add_pyseccm_status_bar(gui)
    except Exception:
        pass
    try:
        if hasattr(gui, "_faradaiq_pyseccm_progress"):
            gui._faradaiq_pyseccm_progress.stop()
            gui._faradaiq_pyseccm_progress.configure(maximum=1, value=0)
    except Exception:
        pass
    try:
        if hasattr(gui, "_faradaiq_pyseccm_status_var"):
            if reason == "load":
                text = "pySECCM/DRT parser: ready — new dataset inspection started; no parser run active yet."
            elif reason == "export":
                text = "pySECCM/DRT parser: ready — new export started; waiting for parser scheduling."
            else:
                text = "pySECCM/DRT parser: ready."
            gui._faradaiq_pyseccm_status_var.set(text)
    except Exception:
        pass


