try:
    _V207_PREV_START_PARSER_MONITOR = _v67_start_pyseccm_monitor
except Exception:
    _V207_PREV_START_PARSER_MONITOR = None


class _v208ParserMonitorProxy:
    """Forward GUI access while cancelling callbacks from superseded parser runs."""
    def __init__(self, gui, generation):
        object.__setattr__(self, "_gui", gui)
        object.__setattr__(self, "_generation", int(generation))

    def __getattr__(self, name):
        return getattr(object.__getattribute__(self, "_gui"), name)

    def __setattr__(self, name, value):
        if name in {"_gui", "_generation"}:
            object.__setattr__(self, name, value)
        else:
            setattr(object.__getattribute__(self, "_gui"), name, value)

    def after(self, delay_ms, callback=None, *args):
        gui = object.__getattribute__(self, "_gui")
        generation = object.__getattribute__(self, "_generation")
        if callback is None:
            return gui.after(delay_ms)

        def guarded_callback(*cb_args):
            try:
                if int(getattr(gui, "_v208_parser_generation", 0)) != generation:
                    return None
            except Exception:
                return None
            return callback(*cb_args)

        return gui.after(delay_ms, guarded_callback, *args)


def _v208_start_pyseccm_monitor(gui, progress_file, total):
    """Start one parser monitor and invalidate callbacks from any older transaction."""
    try:
        generation = int(getattr(gui, "_v208_parser_generation", 0)) + 1
    except Exception:
        generation = 1
    try:
        gui._v208_parser_generation = generation
        gui._v208_active_parser_progress_file = str(progress_file)
    except Exception:
        pass
    if callable(_V207_PREV_START_PARSER_MONITOR):
        return _V207_PREV_START_PARSER_MONITOR(
            _v208ParserMonitorProxy(gui, generation), progress_file, total
        )
    return None


