def _v208_heka_analyze(self):
    """Run historical trace extraction, then reconstruct and classify the full PUL tree."""
    if callable(_V208_PREV_HEKA_ANALYZE):
        _V208_PREV_HEKA_ANALYZE(self)
    if _heka_v208_module is None:
        try:
            self.notes.append("v210 structured HEKA module could not be imported; legacy analysis remains available.")
        except Exception:
            pass
        return None
    try:
        result = _heka_v208_module.analyze(self)
        # Legacy EIS grouping is label-window based and can mistake SF-phase for
        # impedance. Suppress it when the structured classifier found no EIS.
        if not result.get("technique_counts", {}).get("EIS"):
            self.eis_groups = []
        try:
            self.notes.append(
                "v216: reconstructed Root/Group/Series/Sweep/Trace hierarchy; "
                "classified Series using labels, units, waveform, processed channels, and scan context."
            )
        except Exception:
            pass
        return result
    except Exception as exc:
        try:
            self.notes.append(f"v210 structured HEKA analysis warning: {exc}. Legacy trace access remains available.")
            self.metadata.setdefault("warnings", []).append({
                "code": "structured_heka_analysis_failed",
                "message": str(exc),
                "file": str(getattr(self, "source_path", "")),
            })
        except Exception:
            pass
        return None


def _v208_heka_summarize(self):
    if _heka_v208_module is not None and getattr(self, "heka_v208", None):
        try:
            return _heka_v208_module.compact_summary(self)
        except Exception:
            pass
    if callable(_V208_PREV_HEKA_SUMMARIZE):
        return _V208_PREV_HEKA_SUMMARIZE(self)
    return {}


def _v208_heka_native_numeric_payload(self):
    if getattr(self, "heka_v208", None):
        result = self.heka_v208
        return {
            "format": "faradaiq-heka-structured-index-v208",
            "source_file": self.source_path,
            "mode": self.mode,
            "metadata": self.metadata,
            "hierarchy_counts": result.get("hierarchy", {}).get("level_counts", {}),
            "series_classifications": result.get("series_classifications", []),
            "eis_spectra_index": [
                {k: v for k, v in sp.items() if k != "rows"}
                for sp in result.get("eis_spectra", [])
            ],
            "warnings": result.get("warnings", []),
        }
    if callable(_V208_PREV_HEKA_NATIVE):
        return _V208_PREV_HEKA_NATIVE(self)
    return {}


def _v208_heka_export(self, output_dir, base_name):
    if _heka_v208_module is None or not getattr(self, "heka_v208", None):
        if callable(_V208_PREV_HEKA_EXPORT):
            return _V208_PREV_HEKA_EXPORT(self, output_dir, base_name)
        return {"files": [], "csv_entries": [], "skipped_entries": [], "n_csv_files": 0}
    info = _heka_v208_module.export_structured(self, Path(output_dir), str(base_name))
    root = Path(info.get("root", output_dir))
    csv_entries = []
    for rec in info.get("records", []):
        rel = rec.get("relative_csv_path")
        if not rel:
            continue
        csv_entries.append({
            "relative_csv_path": str((root / rel).relative_to(Path(output_dir))).replace("\\", "/"),
            "technique": rec.get("technique", "HEKA"),
            "curve_title": rec.get("role", "HEKA processed table"),
            "n_points": "",
            "x_label": rec.get("x_label", ""),
            "x_unit": rec.get("x_unit", ""),
            "y_label": rec.get("y_label", ""),
            "y_unit": rec.get("y_unit", ""),
            "method_id": rec.get("series_title", "HEKA"),
            "point": rec.get("point", ""),
            "cycle": rec.get("cycle", ""),
            "group_index": rec.get("group_index", ""),
            "series_index": rec.get("series_index", ""),
            "sweep_index": rec.get("sweep_index", ""),
            "confidence": rec.get("confidence", ""),
        })
    files = list(info.get("files", []))
    return {
        "files": files,
        "csv_entries": csv_entries,
        "skipped_entries": [{"reason": w.get("message", str(w))} for w in info.get("warnings", []) if isinstance(w, dict)],
        "n_csv_files": sum(1 for f in files if str(f).lower().endswith(".csv")),
        "heka_v208_manifest": info.get("manifest", ""),
        "raw_h5": info.get("raw_h5", ""),
    }


def _v208_heka_iter_primary_curve_exports(self):
    # Structured v208 CSVs already preserve Group/Series/Sweep/Cycle. Returning
    # the old flat iterator here would create duplicate CV/LSV entries.
    if getattr(self, "heka_v208", None):
        return iter(())
    if callable(_V208_PREV_HEKA_ITER_CURVES):
        return _V208_PREV_HEKA_ITER_CURVES(self)
    return iter(())


