# ---- FaradaIQ Studio v273 HEKA EIS Bode plotting QA fix ----
# Keep the existing Nyquist renderer, but make the explicit Bode modes use the
# reconstructed frequency, magnitude, and phase columns exported by heka_v208.
_V208_PREV_PLOT_EIS = FaradaIQPublicationPlotPanelV206._plot_eis
_V208_PREV_RENDER_PUBLICATION = FaradaIQPublicationPlotPanelV206.render


def _v208_plot_eis_with_bode(self, curve, mode_l):
    mode_l = str(mode_l or '').lower()
    if 'bode' not in mode_l:
        return _V208_PREV_PLOT_EIS(self, curve, mode_l)
    df = curve['df']; cols = curve['cols']; label = curve['label']
    freq = _v206_numeric(df, cols.get('freq'))
    zr = _v206_numeric(df, cols.get('zr'))
    zi = _v206_numeric(df, cols.get('zi'))
    if not len(zi) and cols.get('negzi'):
        zi = -_v206_numeric(df, cols.get('negzi'))
    if 'phase' in mode_l:
        if cols.get('phase'):
            y = _v206_numeric(df, cols.get('phase'))
        elif len(zr) and len(zi) == len(zr):
            y = np.degrees(np.arctan2(zi, zr))
        else:
            return None, False
        ylabel = 'Phase / °'
    else:
        if cols.get('zmod'):
            y = np.abs(_v206_numeric(df, cols.get('zmod')))
        elif len(zr) and len(zi) == len(zr):
            y = np.sqrt(zr * zr + zi * zi)
        else:
            return None, False
        ylabel = '|Z| / Ω'
    if not len(freq) or len(freq) != len(y):
        return None, False
    mask = np.isfinite(freq) & (freq > 0) & np.isfinite(y)
    if 'phase' not in mode_l:
        mask &= (y > 0)
    x = freq[mask]; y = y[mask]
    if len(x) < 2:
        return None, False
    order = np.argsort(x)
    x = x[order]; y = y[order]
    want_line, want_points = self._style_flags()
    line, = self.ax.plot(
        x, y,
        linestyle='-' if want_line else 'None',
        marker='o' if want_points else None,
        linewidth=1.7,
        markersize=3.5,
        label=label,
    )
    self.ax.set_xlabel('Frequency / Hz')
    self.ax.set_ylabel(ylabel)
    return line, False


def _v208_render_publication_with_eis_titles(self, curves, clear=True):
    mode = str(self._get('plot_mode_var', 'Auto') or 'Auto')
    mode_l = mode.lower()
    previous_mode = str((self.last_recipe or {}).get('mode', ''))
    # Apply a technique-appropriate Bode default only when entering a Bode view.
    # A later user change to Linear remains respected while the mode is unchanged.
    if 'bode' in mode_l and previous_mode != mode:
        try: self.browser.plot_xscale_var.set('Log')
        except Exception: pass
    result = _V208_PREV_RENDER_PUBLICATION(self, curves, clear=clear)
    if curves and {c.get('tech') for c in curves} == {'EIS'}:
        if 'bode' in mode_l and 'phase' in mode_l:
            self.ax.set_title('EIS Bode phase publication overlay')
        elif 'bode' in mode_l:
            self.ax.set_title('EIS Bode magnitude publication overlay')
        elif 'raw' in mode_l:
            self.ax.set_title('EIS Nyquist raw-sign publication overlay')
        else:
            self.ax.set_title('EIS Nyquist publication overlay')
        try: self.canvas.draw_idle()
        except Exception: pass
    return result


