def _v209_heka_load(self, path):
    p = Path(path)
    ext = p.suffix.lower()
    semantic_support = {".pgf", ".onl", ".amp", ".sol", ".mrk", ".mth"}
    # A standalone support file is useful even when no PUL/DAT siblings exist.
    if ext in semantic_support and p.exists() and not p.with_suffix(".pul").exists():
        self.__init__()
        self.source_path = str(p)
        self.mode = "support_only"
        self.support_paths = {ext: p}
        self.section_bytes = {ext: p.read_bytes()}
        self.metadata = {"source_file": str(p), "mode": self.mode, "support_files": {ext: str(p)}}
        self._analyze()
        return self
    return _V209_PREV_HEKA_LOAD(self, path)


def _v209_heka_analyze(self):
    # Run the validated trace decoder only when a PUL acquisition tree exists.
    if bytes(getattr(self, "pul", b"") or b"") and callable(_V209_PREV_HEKA_ANALYZE):
        _V209_PREV_HEKA_ANALYZE(self)
    if _heka_v209_module is None:
        self.notes.append("v210 HEKA semantic module could not be imported; existing trace access remains available.")
        return None
    try:
        result = _heka_v209_module.analyze(self)
        if not result.get("technique_counts", {}).get("EIS"):
            self.eis_groups = []
        self.notes.append(
            "v216: decoded HEKA hierarchy and complete attached PGF v1000/ONL v11 semantics, "
            "including protocols, segments, online functions, graph definitions, and Series linkage."
        )
        return result
    except Exception as exc:
        self.notes.append(f"v210 HEKA semantic analysis warning: {exc}. Raw source bytes remain preserved.")
        self.metadata.setdefault("warnings", []).append({"code": "heka_v209_semantic_analysis_failed", "message": str(exc), "file": str(getattr(self, "source_path", ""))})
        return None


def _v209_heka_summarize(self):
    if _heka_v209_module is not None and getattr(self, "heka_v209", None):
        return _heka_v209_module.compact_summary(self)
    return _V209_PREV_HEKA_SUMMARIZE(self) if callable(_V209_PREV_HEKA_SUMMARIZE) else {}


def _v209_heka_native(self):
    result = getattr(self, "heka_v209", None)
    if result:
        return {
            "format": "faradaiq-heka-structured-index-v210",
            "source_file": self.source_path,
            "mode": self.mode,
            "metadata": self.metadata,
            "hierarchy_counts": result.get("hierarchy", {}).get("level_counts", {}),
            "series_classifications": result.get("series_classifications", []),
            "semantic_section_inventory": result.get("semantic_sections", {}).get("inventory", []),
            "semantic_sections": result.get("semantic_sections", {}).get("sections", {}),
            "eis_spectra_index": [{k: v for k, v in sp.items() if k != "rows"} for sp in result.get("eis_spectra", [])],
            "warnings": result.get("warnings", []),
        }
    return _V209_PREV_HEKA_NATIVE(self) if callable(_V209_PREV_HEKA_NATIVE) else {}


def _v209_heka_export(self, output_dir, base_name):
    if _heka_v209_module is None or not getattr(self, "heka_v209", None):
        return _V209_PREV_HEKA_EXPORT(self, output_dir, base_name) if callable(_V209_PREV_HEKA_EXPORT) else {"files": [], "csv_entries": [], "skipped_entries": [], "n_csv_files": 0}
    info = _heka_v209_module.export_structured(self, Path(output_dir), str(base_name))
    root = Path(info.get("root", output_dir)); csv_entries = []
    for rec in info.get("records", []):
        rel = rec.get("relative_csv_path")
        if not rel: continue
        csv_entries.append({
            "relative_csv_path": str((root / rel).relative_to(Path(output_dir))).replace("\\", "/"),
            "technique": rec.get("technique", "HEKA"), "curve_title": rec.get("role", "HEKA processed table"),
            "n_points": "", "x_label": rec.get("x_label", ""), "x_unit": rec.get("x_unit", ""),
            "y_label": rec.get("y_label", ""), "y_unit": rec.get("y_unit", ""),
            "method_id": rec.get("series_title", "HEKA"), "point": rec.get("point", ""), "cycle": rec.get("cycle", ""),
            "group_index": rec.get("group_index", ""), "series_index": rec.get("series_index", ""), "sweep_index": rec.get("sweep_index", ""),
            "confidence": rec.get("confidence", ""),
        })
    files = list(info.get("files", []))
    return {"files": files, "csv_entries": csv_entries,
            "skipped_entries": [{"reason": w.get("message", str(w))} for w in info.get("warnings", []) if isinstance(w, dict)],
            "n_csv_files": sum(1 for f in files if str(f).lower().endswith(".csv")),
            "heka_v209_manifest": info.get("manifest", ""), "raw_h5": info.get("raw_h5", "")}


def _v209_heka_iter(self):
    if getattr(self, "heka_v209", None): return iter(())
    return _V209_PREV_HEKA_ITER(self) if callable(_V209_PREV_HEKA_ITER) else iter(())


