def _v210_heka_export_with_traditional_pyseccm(self, output_dir, base_name):
    info = _V210_PREV_HEKA_EXPORT(self, output_dir, base_name) if callable(_V210_PREV_HEKA_EXPORT) else {
        "files": [], "csv_entries": [], "skipped_entries": [], "n_csv_files": 0
    }
    if info.get("heka_v209_manifest") and not info.get("heka_v210_manifest"):
        # Public alias for the current release; the older key remains only for
        # compatibility with saved v209 bundles and private browser helpers.
        info["heka_v210_manifest"] = info.get("heka_v209_manifest")
    if not getattr(self, "heka_v209", None) or not callable(_v210_export_legacy_pyseccm):
        if _v210_export_legacy_pyseccm is None:
            info.setdefault("skipped_entries", []).append({"reason": f"v216 traditional pySECCM export module unavailable: {_v210_legacy_import_error}"})
        return info
    try:
        current_manifest = info.get("heka_v210_manifest") or info.get("heka_v209_manifest") or ""
        structured = {
            "root": str(Path(current_manifest).parent) if current_manifest else "",
            "manifest": current_manifest,
            "records": [],
        }
        man = Path(str(current_manifest))
        if man.exists():
            payload = json.loads(man.read_text(encoding="utf-8"))
            structured["root"] = str(man.parent)
            structured["records"] = list(payload.get("records", []) or [])
            structured["warnings"] = list(payload.get("warnings", []) or [])
        elif _heka_v209_module is not None:
            # Defensive fallback: rebuild structured export only if the first stage
            # did not return a readable manifest.
            structured = _heka_v209_module.export_structured(self, Path(output_dir), str(base_name))
        legacy = _v210_export_legacy_pyseccm(
            self,
            structured,
            Path(output_dir),
            str(base_name),
            package_root=Path(__file__).resolve().parent,
        )
        info["traditional_pyseccm"] = legacy
        info.setdefault("files", []).extend(legacy.get("files", []))
        info.setdefault("csv_entries", []).append({
            "relative_csv_path": "",
            "technique": "HEKA pySECCM compatibility",
            "curve_title": "Traditional pySECCM parser input folder",
            "method_id": "traditional_pySECCM_v216",
            "output_folder": legacy.get("root", ""),
            "data_folder": legacy.get("main_data", ""),
            "n_points": legacy.get("n_generated_files", 0),
            "x_label": "", "x_unit": "", "y_label": "", "y_unit": "",
        })
        try:
            self.metadata.setdefault("heka_v210", {})["traditional_pyseccm"] = legacy
        except Exception:
            pass
    except Exception as exc:
        info.setdefault("skipped_entries", []).append({"reason": f"v216 traditional pySECCM export failed: {exc}"})
    return info


HEKAPotmasterParser.export_analysis_ready_outputs = _v210_heka_export_with_traditional_pyseccm

