def _v27_build_auto_pyseccm_commands_for_data_dir(data_dir, script_root=None, python_exe=None, include_drt=True):
    data_dir = Path(data_dir)
    script_root = Path(script_root or _v19_find_pyseccm_script_root([data_dir, data_dir.parent, Path(__file__).resolve().parent]) or (Path(__file__).resolve().parent / "pyseccm_tools"))
    python_exe = str(python_exe or sys.executable)
    if callable(_v210_commands_from_manifest):
        try:
            result = _v210_commands_from_manifest(data_dir, script_root, python_exe, include_drt=include_drt)
            if result is not None:
                return result
        except Exception as exc:
            # Fall back to the general detector for non-v210 or damaged folders.
            commands, notes, detected = _V210_PREV_BUILD_AUTO_COMMANDS(data_dir, script_root=script_root, python_exe=python_exe, include_drt=include_drt)
            notes = list(notes or [])
            notes.append(f"v210 manifest command routing fell back to filename detection: {exc}")
            return commands, notes, detected
    return _V210_PREV_BUILD_AUTO_COMMANDS(data_dir, script_root=script_root, python_exe=python_exe, include_drt=include_drt)


