_V211_MEDIA_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".gif", ".webp"}
_V211_MEDIA_VIDEO_EXTS = {".mp4", ".avi", ".mov", ".mkv", ".wmv", ".mpeg", ".mpg", ".m4v", ".webm"}


def _v211_discover_heka_media(self):
    """Discover sidecar photographs, GIFs, and videos without scanning unrelated folders."""
    self.media_files = []
    self.image_files = []
    self.video_files = []
    self.media_manifest = []
    try:
        source = Path(str(getattr(self, "source_path", "")))
        base = source.parent if source.is_file() else source
        if not base.exists():
            return
        candidates = [p for p in base.iterdir() if p.is_file() and p.suffix.lower() in (_V211_MEDIA_IMAGE_EXTS | _V211_MEDIA_VIDEO_EXTS)]
        for folder_name in ("photos", "photo", "images", "media", "videos", "movies", "Figures", "figures"):
            folder = base / folder_name
            if folder.is_dir():
                candidates.extend(p for p in folder.rglob("*") if p.is_file() and p.suffix.lower() in (_V211_MEDIA_IMAGE_EXTS | _V211_MEDIA_VIDEO_EXTS))
        seen = set()
        ordered = []
        for p in sorted(candidates, key=lambda q: (re.sub(r"\d+", "", q.name.lower()), [int(x) for x in re.findall(r"\d+", q.name)] or [0], q.name.lower())):
            key = str(p.resolve()).lower()
            if key not in seen:
                seen.add(key); ordered.append(p.resolve())
        self.media_files = ordered
        self.image_files = [p for p in ordered if p.suffix.lower() in _V211_MEDIA_IMAGE_EXTS]
        self.video_files = [p for p in ordered if p.suffix.lower() in _V211_MEDIA_VIDEO_EXTS]
        for index, p in enumerate(ordered, 1):
            st = p.stat()
            kind = "video" if p.suffix.lower() in _V211_MEDIA_VIDEO_EXTS else ("gif" if p.suffix.lower() == ".gif" else "image")
            self.media_manifest.append({
                "media_index": index, "filename": p.name, "path": str(p), "relative_path": p.relative_to(base).as_posix(),
                "media_type": kind, "size_bytes": int(st.st_size),
                "modified_time": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
            })
        self.photo_summary = {
            "n_images": len(self.image_files), "n_videos": len(self.video_files), "n_media": len(ordered),
            "base_dir": str(base), "image_order_method": "natural filename order",
        }
    except Exception as exc:
        self.notes.append(f"v216 media discovery warning: {exc}")


