def _v216_normalize_main_session_row(gui):
    """Guarantee one Save Session, one Load Session, and one Auto Save checkbox."""
    try:
        frame = _v177_find_live_session_banner_frame(gui) if '_v177_find_live_session_banner_frame' in globals() else _v177_find_session_banner_frame(gui)
        if frame is None:
            return False
        # Remove duplicate session buttons, keeping the first canonical pair.
        seen = set()
        for child in list(frame.winfo_children()):
            try:
                low = str(child.cget('text') or '').strip().lower()
            except Exception:
                continue
            if low in {'save session', 'load session', 'auto save session'}:
                if low in seen:
                    try: child.destroy()
                    except Exception:
                        try: child.grid_forget(); child.pack_forget()
                        except Exception: pass
                else:
                    seen.add(low)
                    if low == 'save session':
                        child.configure(text='Save Session', command=lambda g=gui: _v177_save_session_from_button(g))
                    elif low == 'load session':
                        child.configure(text='Load Session', command=lambda g=gui: _v177_load_session_from_button(g))
        _v177_insert_main_session_buttons(gui, frame)
        if '_v177_add_autosave_checkbox_to_launch_row' in globals():
            _v177_add_autosave_checkbox_to_launch_row(gui)
        return True
    except Exception:
        return False


# Disable the older lower-case session-button injector. It remains as a
# compatibility name, but now delegates to the canonical v216 pair instead of
# creating a second transient pair during startup.
def _v216_legacy_session_button_shim(gui):
    try:
        frame = _v177_find_live_session_banner_frame(gui) if '_v177_find_live_session_banner_frame' in globals() else _v177_find_session_banner_frame(gui)
        return _v177_insert_main_session_buttons(gui, frame) if frame is not None else False
    except Exception:
        return False

