# ---- FaradaIQ Studio v273 named working sessions ----
# Adds a New Session control before Save Session / Load Session. Every valid
# Load + inspect action starts a clean named working session based on the
# selected file or folder, while preserving the selected source path and any
# user-entered experimental description.

def _v219_safe_session_name(source_path=None):
    import re as _re
    from pathlib import Path as _Path
    raw = ""
    try:
        if source_path:
            p = _Path(str(source_path))
            raw = p.name or p.stem
            if p.is_file() and p.suffix:
                raw = p.stem
    except Exception:
        raw = ""
    raw = str(raw or "untitled").strip()
    safe = _re.sub(r"[^A-Za-z0-9._-]+", "_", raw).strip("._-") or "untitled"
    from faradaiq.readable_names import safe_component
    return raw, safe_component(raw,max_chars=120)


def _v219_reset_working_state(gui, preserve_description=True):
    """Clear parsed/session-specific state without erasing the selected input."""
    try:
        if '_v177_stop_autosave_session' in globals():
            _v177_stop_autosave_session(gui)
    except Exception:
        pass
    try:
        for browser in list(_v177_find_open_browsers(gui)) if '_v177_find_open_browsers' in globals() else []:
            try:
                browser.destroy()
            except Exception:
                pass
    except Exception:
        pass
    try:
        current = getattr(gui, 'collection', None)
        cls = current.__class__ if current is not None else globals().get('PSSessionCollection')
        gui.collection = cls() if cls is not None else PSSessionCollection()
    except Exception:
        try:
            gui.collection = PSSessionCollection()
        except Exception:
            pass
    try:
        gui.current_summary = None
    except Exception:
        pass
    try:
        gui.current_analysis_root = ''
    except Exception:
        pass
    for attr in ('summary_text', 'structure_text'):
        try:
            widget = getattr(gui, attr, None)
            if widget is not None:
                widget.delete('1.0', 'end')
        except Exception:
            pass
    try:
        if hasattr(gui, 'desc_text'):
            current_text = gui.desc_text.get('1.0', 'end').strip()
            if hasattr(gui, '_strip_loaded_context_block'):
                current_text = gui._strip_loaded_context_block(current_text)
            gui.desc_text.delete('1.0', 'end')
            if preserve_description and current_text:
                gui.desc_text.insert('1.0', current_text)
    except Exception:
        pass
    for attr in ('_v177_auto_save_path', '_v177_last_auto_save_path', '_v177_last_auto_save_time', '_v177_last_auto_save_error'):
        try:
            setattr(gui, attr, None)
        except Exception:
            pass




def _v219_refresh_session_banner_text(gui):
    try:
        frame = getattr(gui, '_v753_session_banner_frame', None)
        ctx = getattr(gui, '_v219_working_session_context', None) or _v753_launch_context()
        sid = str(ctx.get('session_id') or '')
        name = str(ctx.get('session_name') or '').strip()
        if frame is None or not frame.winfo_exists():
            return False
        label_text = f'FaradaIQ working session: {sid}'
        if name:
            label_text += f'  |  {name}'
        for child in frame.winfo_children():
            try:
                text = str(child.cget('text') or '')
                if text.startswith('FaradaIQ launch session:') or text.startswith('FaradaIQ working session:'):
                    child.configure(text=label_text)
            except Exception:
                pass
        return True
    except Exception:
        return False


def _v219_rebuild_session_banner(gui):
    try:
        frame = getattr(gui, '_v753_session_banner_frame', None)
        if frame is not None and frame.winfo_exists():
            frame.destroy()
    except Exception:
        pass
    try:
        gui._v753_session_banner_added = False
        gui._v753_session_banner_frame = None
    except Exception:
        pass
    try:
        _v753_add_session_banner(gui, 'FaradaIQ working session')
        _v219_refresh_session_banner_text(gui)
    except Exception:
        pass
    try:
        _v177_insert_main_session_buttons(gui)
    except Exception:
        pass
    try:
        if '_v177_add_autosave_checkbox_to_launch_row' in globals():
            _v177_add_autosave_checkbox_to_launch_row(gui)
    except Exception:
        pass


def _v219_start_new_session(gui, source_path=None, reason='manual', preserve_description=True):
    import os as _os
    import uuid as _uuid
    from datetime import datetime as _datetime
    from pathlib import Path as _Path

    selected = str(source_path or '').strip()
    display_name, safe_name = _v219_safe_session_name(selected)
    stamp = _datetime.now().strftime('%Y%m%d_%H%M%S_%f')[:-3]
    sid = f"FQ_{stamp}_{_uuid.uuid4().hex[:6].upper()}"
    launch_root = (_os.environ.get('FARADAIQ_LAUNCH_ROOT') or '').strip()
    if not launch_root:
        launch_root = str(_Path(__file__).resolve().parent / 'FaradaIQ_launch_sessions')
    root = _Path(launch_root).resolve()
    from faradaiq.readable_names import new_folder
    session_dir = new_folder(root, safe_name, reserve=48)
    (session_dir / 'logs').mkdir(parents=True, exist_ok=True)
    (session_dir / 'activity').mkdir(parents=True, exist_ok=True)

    _v219_reset_working_state(gui, preserve_description=preserve_description)

    _os.environ['FARADAIQ_SESSION_ID'] = sid
    _os.environ['FARADAIQ_LAUNCH_ROOT'] = str(root)
    _os.environ['FARADAIQ_SESSION_DIR'] = str(session_dir)
    _os.environ['FARADAIQ_APP_VERSION'] = 'v336'
    _os.environ['FARADAIQ_SESSION_NAME'] = display_name
    if selected:
        _os.environ['FARADAIQ_SESSION_SOURCE'] = selected
    else:
        _os.environ.pop('FARADAIQ_SESSION_SOURCE', None)

    ctx = {
        'session_id': sid,
        'session_name': display_name,
        'source_path': selected,
        'launch_root': str(root),
        'session_dir': str(session_dir),
        'logs_dir': str(session_dir / 'logs'),
        'tracking_dir': str(session_dir),
        'created_or_seen': _datetime.now().isoformat(timespec='seconds'),
        'pid': _os.getpid(),
        'script': str(_Path(__file__).resolve()),
        'reason': str(reason),
        'app_version': 'v336',
    }
    try:
        (session_dir / 'session_context.json').write_text(json.dumps(_v177_json_safe(ctx), ensure_ascii=False, indent=2), encoding='utf-8')
        (session_dir / 'session_info.txt').write_text(
            '\n'.join([
                'FaradaIQ eStudio working session',
                f'Session name: {display_name}',
                f'Session ID: {sid}',
                f'Source: {selected or "not selected"}',
                f'Created: {ctx["created_or_seen"]}',
                f'Reason: {reason}',
                'App version: v336',
            ]) + '\n',
            encoding='utf-8',
        )
    except Exception:
        pass
    try:
        gui._faradaiq_launch_context = ctx
        gui._v219_working_session_context = ctx
    except Exception:
        pass

    _v219_rebuild_session_banner(gui)
    try:
        for delay in (80, 350, 1000, 2200):
            gui.after(delay, lambda g=gui: _v219_refresh_session_banner_text(g))
    except Exception:
        pass
    try:
        _v753_apply_title(gui, 'FaradaIQ Studio v273')
    except Exception:
        try:
            gui.title(f'FaradaIQ Studio v273 — session {sid}')
        except Exception:
            pass
    message = f'New session started: {display_name} ({sid})'
    try:
        gui.set_status(message)
    except Exception:
        try:
            gui.status_var.set(message)
        except Exception:
            pass
    try:
        _v753_track_event('new_working_session', {'session_name': display_name, 'source_path': selected, 'reason': reason})
    except Exception:
        pass
    return ctx


def _v219_new_session_from_button(gui):
    try:
        source = str(gui.file_var.get() or '').strip() if hasattr(gui, 'file_var') else ''
    except Exception:
        source = ''
    return _v219_start_new_session(gui, source_path=source, reason='new_session_button', preserve_description=True)


