def _v222_session_init(self, *args, **kwargs):
    if callable(_V222_PREV_SESSION_INIT):
        _V222_PREV_SESSION_INIT(self, *args, **kwargs)
    try:
        self._faradaiq_theme_mode = 'high contrast'
        if not hasattr(self, 'theme_mode_var'):
            self.theme_mode_var = tk.StringVar(master=self, value=_V222_DEFAULT_THEME)
        else:
            self.theme_mode_var.set(_V222_DEFAULT_THEME)
        _v36_apply_theme(self, _V222_DEFAULT_THEME)
        _v177_insert_main_session_buttons(self)
        _v219_refresh_session_banner_text(self)
        self.title('FaradaIQ Studio v273')
        self.update_idletasks()
    except Exception:
        pass

    def _v222_reveal_stable_first_frame():
        if getattr(self, '_v222_startup_revealed', False):
            return
        try:
            self._faradaiq_theme_mode = 'high contrast'
            self.theme_mode_var.set(_V222_DEFAULT_THEME)
            _v36_apply_theme(self, _V222_DEFAULT_THEME)
            _v177_insert_main_session_buttons(self)
            _v219_refresh_session_banner_text(self)
            self.title('FaradaIQ Studio v273')
            self.update_idletasks()
            self.deiconify()
            self._v222_startup_revealed = True
            self._faradaiq_startup_hidden = False
        except Exception:
            try:
                self.deiconify()
                self._v222_startup_revealed = True
                self._faradaiq_startup_hidden = False
            except Exception:
                pass

    # Permit the queued header/footer construction passes to finish while hidden,
    # then reveal exactly one fully themed first frame.
    try:
        self.after(220, _v222_reveal_stable_first_frame)
    except Exception:
        _v222_reveal_stable_first_frame()


