# ---- FaradaIQ Studio v273 selected-EIS pyDRTtools GUI handoff ----
# Replaces the separate "Open native DearEIS GUI" browser button with a
# selected-spectrum handoff into the official ciuccislab pyDRTtools GUI.

import subprocess as _v225_subprocess


def _v225_pydrttools_output_root(browser):
    try:
        root = Path(browser.analyzed_root) / 'pydrttools_eis_handoff'
    except Exception:
        base = Path(getattr(browser, 'analysis_root', Path.cwd()))
        root = base / f'{_v35_safe_name(getattr(browser, "base_name", base.name))}_FaradaIQ_analyzed_data' / 'pydrttools_eis_handoff'
    root.mkdir(parents=True, exist_ok=True)
    return root


def _v225_pydrttools_import_ready():
    """Check the optional Qt integration out-of-process.

    The official GUI selects the Qt5Agg Matplotlib backend during import.  A
    subprocess probe avoids changing the active Tk/Matplotlib backend in the
    running FaradaIQ browser merely to test whether pyDRTtools is installed.
    """
    code = (
        "from pyDRTtools.GUI import GUI; "
        "from pyDRTtools.runs import EIS_object; "
        "import cvxopt, sklearn, requests; "
        "print('pyDRTtools selected-EIS bridge ready')"
    )
    kwargs = {
        'cwd': str(Path(__file__).resolve().parent),
        'capture_output': True,
        'text': True,
        'timeout': 30,
    }
    if os.name == 'nt':
        kwargs['creationflags'] = getattr(_v225_subprocess, 'CREATE_NO_WINDOW', 0)
    try:
        completed = _v225_subprocess.run([sys.executable, '-c', code], **kwargs)
        if completed.returncode == 0:
            return True, ''
        reason = (completed.stderr or completed.stdout or f'exit code {completed.returncode}').strip()
        return False, reason
    except Exception as exc:
        return False, str(exc)


def _v225_write_pydrttools_open_bat(result):
    """Create a reproducible Windows install-if-needed + preload launcher."""
    try:
        app_dir = Path(__file__).resolve().parent
        outdir = Path(result.output_dir)
        bat = outdir / 'OPEN_SELECTED_IN_PYDRTTOOLS.bat'
        py = Path(sys.executable).resolve()
        installer = app_dir / 'install_official_pydrttools_optional.bat'
        loader = app_dir / 'faradaiq_pydrttools_gui_loader.py'
        manifest = Path(result.manifest).resolve()
        text = (
            '@echo off\r\n'
            'setlocal EnableExtensions\r\n'
            f'title FaradaIQ selected EIS to pyDRTtools v228\r\n'
            f'cd /d "{app_dir}"\r\n'
            f'set "FQ_PY={py}"\r\n'
            f'set "FQ_INSTALLER={installer}"\r\n'
            f'set "FQ_LOADER={loader}"\r\n'
            f'set "FQ_MANIFEST={manifest}"\r\n'
            'if not exist "%FQ_PY%" (\r\n'
            '  echo ERROR: FaradaIQ private Python was not found: %FQ_PY%\r\n'
            '  pause\r\n'
            '  exit /b 1\r\n'
            ')\r\n'
            '"%FQ_PY%" -c "from pyDRTtools.GUI import GUI; from pyDRTtools.runs import EIS_object; import cvxopt, sklearn, requests" >nul 2>&1\r\n'
            'if errorlevel 1 (\r\n'
            '  echo Official pyDRTtools is missing or broken. Installing/repairing it now...\r\n'
            '  call "%FQ_INSTALLER%" --auto\r\n'
            '  if errorlevel 1 (\r\n'
            '    echo ERROR: pyDRTtools installation/repair failed.\r\n'
            '    pause\r\n'
            '    exit /b 1\r\n'
            '  )\r\n'
            ')\r\n'
            'echo Opening every selected EIS spectrum already loaded in pyDRTtools...\r\n'
            '"%FQ_PY%" "%FQ_LOADER%" --manifest "%FQ_MANIFEST%"\r\n'
            'if errorlevel 1 (\r\n'
            '  echo ERROR: pyDRTtools could not load the selected spectrum set.\r\n'
            '  pause\r\n'
            '  exit /b 1\r\n'
            ')\r\n'
            'exit /b 0\r\n'
        )
        bat.write_text(text, encoding='utf-8')
        return bat
    except Exception:
        return None


def _v225_open_pydrttools_with_selected(browser=None):
    try:
        paths = _v130p_selected_eis_paths(browser) if browser is not None else []
        if not paths:
            messagebox.showinfo(
                'No EIS data selected',
                'Select an EIS/Nyquist/Bode table, EIS group, or EIS Plot/view first, then press Open selected EIS in pyDRTtools.',
                parent=browser,
            )
            return None

        import faradaiq_pydrttools_adapter as _fq_pydrt_adapter
        root = _v225_pydrttools_output_root(browser)
        label = f'{getattr(browser, "base_name", "FaradaIQ")}_selected_EIS'
        result = _fq_pydrt_adapter.create_pydrttools_handoff(paths, root, label=label)
        open_bat = _v225_write_pydrttools_open_bat(result)
        ready, reason = _v225_pydrttools_import_ready()
        helper = Path(__file__).resolve().parent / 'faradaiq_pydrttools_gui_loader.py'

        try:
            browser.log(
                f'pyDRTtools handoff created for {len(result.strict_files)} selected EIS spectrum/spectra: {result.output_dir}'
            )
            browser.log('Each selected spectrum will open preloaded in its own pyDRTtools GUI window.')
            if not ready and reason:
                browser.log(f'Official pyDRTtools requires installation/repair before launch: {reason}')
            if open_bat:
                browser.log(f'pyDRTtools reproducible launcher: {open_bat}')
        except Exception:
            pass

        proc = None
        if ready:
            cmd = [sys.executable, str(helper), '--manifest', str(result.manifest)]
            env = _v227_theme_environment(browser) if '_v227_theme_environment' in globals() else os.environ.copy()
            proc = _v130p_subprocess.Popen(cmd, cwd=str(result.output_dir), env=env) if '_v130p_subprocess' in globals() and _v130p_subprocess is not None else _v225_subprocess.Popen(cmd, cwd=str(result.output_dir), env=env)
        elif os.name == 'nt' and open_bat and Path(open_bat).exists():
            # First use may install official pyDRTtools; the same BAT continues and
            # launches the preloaded windows when installation finishes.
            env = _v227_theme_environment(browser) if '_v227_theme_environment' in globals() else os.environ.copy()
            proc = _v130p_subprocess.Popen(['cmd.exe', '/c', str(open_bat)], cwd=str(result.output_dir), env=env) if '_v130p_subprocess' in globals() and _v130p_subprocess is not None else _v225_subprocess.Popen(['cmd.exe', '/c', str(open_bat)], cwd=str(result.output_dir), env=env)
        else:
            raise RuntimeError(
                'Official pyDRTtools is not available in the FaradaIQ environment. '
                'Run install_official_pydrttools_optional.bat, then press the button again.\n\n' + reason
            )

        try:
            status = (
                f'Opening {len(result.strict_files)} selected EIS spectrum/spectra in pyDRTtools.'
                if ready
                else f'Installing/repairing pyDRTtools, then opening {len(result.strict_files)} selected EIS spectrum/spectra.'
            )
            if hasattr(browser, 'set_status'):
                browser.set_status(status)
        except Exception:
            pass

        message = (
            f'Prepared {len(result.strict_files)} selected EIS spectrum/spectra for pyDRTtools.\n\n'
            f'Handoff folder:\n{result.output_dir}\n\n'
            'Each spectrum is opened already loaded in a separate pyDRTtools GUI window.'
        )
        if not ready:
            message += '\n\nOfficial pyDRTtools was not ready, so installation/repair was started first. The same launcher will open the selected spectra after installation completes.'
        if result.warnings:
            message += '\n\nWarnings:\n' + '\n'.join(result.warnings[:6])
        messagebox.showinfo('pyDRTtools selected-EIS handoff', message, parent=browser)
        return result
    except Exception as exc:
        try:
            messagebox.showerror('pyDRTtools EIS handoff failed', f'{exc}\n\n{traceback.format_exc()}', parent=browser)
        except Exception:
            pass
        try:
            browser.log(f'pyDRTtools EIS handoff failed: {exc}')
        except Exception:
            pass
        return None


_V225_PYDRT_HELP = ('v228 selected EIS to pyDRTtools', r"""
PYDRTTOOLS SELECTED-EIS HANDOFF

In Data browser + analysis, select an EIS table, EIS group, Nyquist/Bode Plot/view, or several EIS spectra. Press Open selected EIS in pyDRTtools. FaradaIQ extracts the exact selected frequency, Z-real, and Z-imag data, writes strict headerless three-column files required by the official pyDRTtools importer, and opens every selected spectrum already loaded in pyDRTtools.

The official pyDRTtools GUI stores one spectrum per window. Therefore, selecting several spectra opens one preloaded pyDRTtools window per spectrum. Measured impedance values are not smoothed or altered. The handoff preserves the actual complex Z-imaginary sign; pyDRTtools applies its own Nyquist display convention.

If official pyDRTtools is missing, FaradaIQ starts the optional installer/repair workflow and then continues to the same preloaded launch. The reproducible OPEN_SELECTED_IN_PYDRTTOOLS.bat launcher and a JSON manifest remain in the handoff folder.

The separate Open native DearEIS GUI button was removed. DearEIS selected-EIS handoff remains available as a separate analysis route.

Credit: pyDRTtools, Ciucci Lab, https://github.com/ciuccislab/pyDRTtools
""")
try:
    if isinstance(_V207_HELP_TABS, list) and not any(str(item[0]) == _V225_PYDRT_HELP[0] for item in _V207_HELP_TABS):
        _V207_HELP_TABS.append(_V225_PYDRT_HELP)
except Exception:
    pass

